  { MinKey = 6101703, MaxKey = 6200220, Loader = function()
      return {
        [6101703] = {
            ["Content"] = "“嗨，亲爱的旅人！请问你掉的是这个黄金提灯，还是这个木头提灯，又或者是这个普通提灯呢？”",
            ["ContentKR"] = "\"안녕? 친애하는 여행자! 실례지만 네가 떨어뜨린 것은 이 황금 랜턴일까? 아니면 이 나무 랜턴일까? 아니면 이 일반 랜턴일까?\"",
            ["DialogueId"] = 6101703,
