            ["FinalCamera"] = "116.4375,-210.523438,168.495239,0.000323,-19.201778,29.174892,35.0,100000.0,false,Manual,22.0",
            ["GUID"] = "1910D540",
            ["LookAt"] = {
                [1] = "100001:n(100014)",
                },
            ["NextDialogue"] = 10012704,
            ["SpeakNpcId"] = 100001,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/100127/1910D540",
            },
        [10012704] = {
            ["Camera"] = "699.554688,-957.21875,341.90564,0.000407,-14.001368,121.374519,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "不。我能看见，你的未来、我们的未来……绝非止步于此。",
            ["ContentKR"] = "아니, 내게는 다 보여. 너의 미래, 그리고 우리의 미래… 절대 여기서 끝나지 않아.",
            ["DialogueId"] = 10012704,
            ["Duration"] = 5,
            ["ExStoryInfo"] = "EXPlayer",
            ["FinalCamera"] = "249.050781,-1061.171875,341.90564,0.00044,-16.201441,91.573235,35.0,100000.0,false,Manual,22.0",
            ["GUID"] = "1910D56A",
            ["NextDialogue"] = 10012705,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100012,
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/story/1002/100127/1910D56A",
            },
        [10012705] = {
            ["Content"] = "会有人将你从苦涩的海水中打捞出来，带向一片苦寒的荒原，命运将在那里降下真正的淬炼。",
            ["ContentKR"] = "누군가 널 짜디짠 바닷물에서 건져 척박한 황무지로 데려갈 거야. 그리고 넌 진정한 운명의 시련을 마주하게 되겠지.",
            ["DialogueId"] = 10012705,
            ["Duration"] = 5,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1910D56B",
            ["NextDialogue"] = 10012706,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1002/100127/1910D56B",
            },
        [10012706] = {
            ["Camera"] = "116.4375,-210.523438,168.495239,0.000323,-19.201778,29.174892,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "你是说——我还活着？",
            ["ContentKR"] = "그 말은... 내가 아직 살아 있다는 거야?",
            ["DefaultLookAt"] = "KeepState",
            ["DialogueId"] = 10012706,
            ["Duration"] = 5,
            ["ExStoryInfo"] = "Player",
            ["FinalCamera"] = "136.882812,-238.855469,168.495239,0.000319,-18.601807,42.176678,35.0,100000.0,false,Manual,22.0",
            ["GUID"] = "1910D594",
            ["LookAt"] = {
                [1] = "100001:n(100014)",
                },
            ["NextDialogue"] = 10012712,
            ["SpeakNpcId"] = 100001,
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1002/100127/1910D594",
            },
        [10012707] = {
            ["Camera"] = "524.417969,-273.097656,72.024963,0.000254,10.998483,156.973907,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "……时间到了。让我给你最后一份助力吧。",
            ["ContentKR"] = "...시간이 됐어. 이건 내가 너에게 주는 마지막 도움이야.",
            ["DialogueId"] = 10012707,
            ["Duration"] = 5,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1910D595",
            ["NextDialogue"] = 10012708,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1002/100127/1910D595",
            },
        [10012708] = {
            ["Camera"] = "524.417969,-273.097656,72.024963,0.000254,10.998483,156.973907,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "把手给我，{nickname}。",
            ["ContentKR"] = "잠깐 손 좀 내밀어 볼래, {nickname}.",
            ["DialogueId"] = 10012708,
            ["Duration"] = 5,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1910D599",
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1002/100127/1910D599",
            },
        [10012709] = {
            ["Camera"] = "524.417969,-273.097656,72.024963,0.000254,10.998483,156.973907,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "这些砂砾是你我二人的，连接着过去、现在、与未来的“记忆”。",
            ["ContentKR"] = "이 모래알들은 너와 나의 것이야. 과거와 현재, 그리고 미래의 '기억'을 잇지.",
            ["DialogueId"] = 10012709,
            ["Duration"] = 4,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1910D59A",
            ["NextDialogue"] = 10012710,
            ["RelatedWikiId"] = {
                [1] = 304001,
                [2] = 204001,
                [3] = 201001,
                [4] = 304002,
                },
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100012,
            },
        [10012710] = {
            ["Camera"] = "524.417969,-273.097656,72.024963,0.000254,10.998483,156.973907,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "从中寻觅吧……寻觅那些我们或许已经熟悉，或许将在未来相遇的身影。",
            ["ContentKR"] = "이 기억의 모래 속에 이번 여정에 도움이 되는 게 있을 거야.",
            ["DialogueId"] = 10012710,
            ["Duration"] = 4,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1910D59B",
            ["NextDialogue"] = 10012711,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1002/100127/1910D59B",
            },
        [10012711] = {
            ["Content"] = "愿他们成为你此行的助力。",
            ["ContentKR"] = "부디, 그들이 너의 여정에 도움이 되길.",
            ["DialogueId"] = 10012711,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1910D59C",
            ["NextDialogue"] = 10012712,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1002/100127/1910D59C",
            },
        [10012712] = {
            ["Camera"] = "524.417969,-273.097656,72.024963,0.000254,10.998483,156.973907,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "该出发了。",
            ["ContentKR"] = "자, 이제 떠날 때야.",
            ["DialogueId"] = 10012712,
            ["Duration"] = 5,
            ["ExStoryInfo"] = "EXPlayer",
            ["FinalCamera"] = "511.515625,-301.914062,72.024963,0.000255,10.998483,151.374451,35.0,100000.0,false,Manual,22.0",
            ["GUID"] = "1910D596",
            ["NextDialogue"] = 10012713,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100012,
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1002/100127/1910D596",
            },
        [10012713] = {
            ["Camera"] = "317.9375,-203.148438,165.504761,0.000249,2.998658,152.974579,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "……{nickname}。生命是航行在无尽长夜里的孤船。河流泪水满溢，夹岸荆棘丛生。",
            ["ContentKR"] = "...{nickname}. 생명은 무한한 밤 속에서 항해하는 외딴 배와 같아. 강물은 눈물로 가득하고, 강가는 가시로 덮여 있지.",
            ["DialogueId"] = 10012713,
            ["Duration"] = 5,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1910D597",
            ["NextDialogue"] = 10012714,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1002/100127/1910D597",
            },
        [10012714] = {
            ["Camera"] = "317.9375,-203.148438,165.504761,0.000249,2.998658,152.974579,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "我会一直注视着……彼岸的你，将驶向何方。",
            ["ContentKR"] = "난 계속해서... 저편의 네가 어디로 향하는지 지켜볼 거야.",
            ["DialogueId"] = 10012714,
            ["Duration"] = 5,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1910D598",
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1002/100127/1910D598",
            },
        [10012801] = {
            ["Content"] = "这是我第一次来科赛托斯省。看来这里的待客之道，颇为独特啊。",
            ["ContentKR"] = "코퀴투스에 온 것은 처음이지만, 여긴 손님 대접하는 방식이 참 독특한 것 같군.",
            ["DialogueId"] = 10012801,
            ["Duration"] = 8.1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1910E52A",
            ["RelatedWikiId"] = {
                [1] = 408002,
                },
            ["SnapShot"] = "MYSTERIOUS",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1002/100128/1910E52A",
            },
        [10012802] = {
            ["Content"] = "我没有任何恶意，只是想同你做一笔……小小的交易。",
            ["ContentKR"] = "악의는 없어... 그저 작은 거래를 하고 싶을 뿐.",
            ["DialogueId"] = 10012802,
            ["Duration"] = 6.1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1910E57E",
            ["SnapShot"] = "MYSTERIOUS",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1002/100128/1910E57E",
            },
        [10012803] = {
            ["Content"] = "我会付给你无法拒绝的报酬，而你要做的，非常简单。",
            ["ContentKR"] = "거절할 수 없는 대가를 주지. 네가 해야 할 일은 아주 간단해.",
            ["DialogueId"] = 10012803,
            ["Duration"] = 6.5,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1910E5A8",
            ["SnapShot"] = "MYSTERIOUS",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1002/100128/1910E5A8",
            },
        [10017801] = {
            ["Content"] = "......",
            ["DialogueId"] = 10017801,
            ["Duration"] = 1,
            ["GUID"] = "1914197A",
            ["RelatedWikiId"] = {
                [1] = 408001,
                [2] = 201001,
                [3] = 303001,
                [4] = 401001,
                [5] = 403001,
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/100178/1914197A",
            },
        [10017901] = {
            ["Content"] = "飞艇在山顶。稍微修整一下，就继续往上走吧。",
            ["ContentKR"] = "비행선은 정상에 있어. 잠시만 정비하고 마저 올라가자.",
            ["DialogueId"] = 10017901,
            ["DisableMouth"] = 1,
            ["Duration"] = 5,
            ["GUID"] = "191429E2",
            ["SpeakNpcId"] = 100003,
            ["VoiceName"] = "voice/$Locale$/story/1001/100179/191429E2",
            },
        [10017902] = {
            ["Content"] = "……这么快，就要和净界岛告别了。",
            ["ContentKR"] = "...이렇게 갑자기 연옥도를 떠나게 될 줄이야.",
            ["DialogueId"] = 10017902,
            ["DisableMouth"] = 1,
            ["Duration"] = 3.5,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19142A0C",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100179/19142A0C",
            },
        [10017903] = {
            ["Content"] = "……真是片刻也不让人清净。",
            ["ContentKR"] = "...정말 쉴 틈도 안 주는군.",
            ["DialogueId"] = 10017903,
            ["DisableMouth"] = 1,
            ["Duration"] = 5.5,
            ["GUID"] = "19142A0D",
            ["SpeakNpcId"] = 100003,
            ["VoiceName"] = "voice/$Locale$/story/1001/100179/19142A0D",
            },
        [10018001] = {
            ["Content"] = "走。",
            ["DialogueId"] = 10018001,
            ["Duration"] = 2,
            ["GUID"] = "19143A4A",
            ["SpeakNpcId"] = 100003,
            ["VoiceName"] = "voice/$Locale$/story/1001/100180/19143A4A",
            },
        [10018101] = {
            ["DialogueId"] = 10018101,
            ["Duration"] = 1,
            ["GUID"] = "19144AB2",
            ["SpeakNpcId"] = 100003,
            ["VoiceName"] = "voice/$Locale$/story/1001/100181/19144AB2",
            },
        [10018201] = {
            ["Content"] = "那天，在毁灭之前，我睁开双眼。瞳孔所见之景，是“无限”。",
            ["DialogueId"] = 10018201,
            ["DialoguePanelType"] = "None",
            ["Duration"] = 13,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19145B1A",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100182/19145B1A",
            },
        [10018202] = {
            ["Content"] = "第一次，我感受到了，我是如此真实地活着。",
            ["DialogueId"] = 10018202,
            ["DialoguePanelType"] = "None",
            ["Duration"] = 7,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19145B44",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100182/19145B44",
            },
        [10018301] = {
            ["Content"] = "下坠。我本应朝着漆黑的深渊下坠。",
            ["DialogueId"] = 10018301,
            ["Duration"] = 2.5,
            ["GUID"] = "19146B82",
            ["NextDialogue"] = 10018302,
            ["VoiceName"] = "voice/$Locale$/story/1001/100183/19146B82",
            },
        [10018302] = {
            ["Content"] = "但，我却感觉自己在晨雾的怀抱里飘浮。",
            ["DialogueId"] = 10018302,
            ["Duration"] = 2.5,
            ["GUID"] = "19146BAC",
            ["NextDialogue"] = 10018303,
            ["VoiceName"] = "voice/$Locale$/story/1001/100183/19146BAC",
            },
        [10018303] = {
            ["Content"] = "周身被冰冷的触感包围，但意外的是，那种冰冷并不令人恐惧。",
            ["DialogueId"] = 10018303,
            ["Duration"] = 4,
            ["GUID"] = "19146BD6",
            ["NextDialogue"] = 10018304,
            ["VoiceName"] = "voice/$Locale$/story/1001/100183/19146BD6",
            },
        [10018304] = {
            ["Content"] = "而是一种，奇特的触感……亲切，甚至令人怀念。",
            ["DialogueId"] = 10018304,
            ["Duration"] = 3,
            ["GUID"] = "19146C00",
            ["VoiceName"] = "voice/$Locale$/story/1001/100183/19146C00",
            },
        [10018401] = {
            ["Content"] = "回答我的，只有不尽流泻的无垠白沙；以及……",
            ["ContentKR"] = "내게 응답한 것은 끝없이 흘러내리는 하얀 모래뿐, 그리고...",
            ["DialogueId"] = 10018401,
            ["Duration"] = 0.5,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19147BEA",
            ["NextDialogue"] = 10018402,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100184/19147BEA",
            },
        [10018402] = {
            ["Content"] = "{性别：她|他}。",
            ["ContentKR"] = "{性别:그녀|그}.",
            ["DialogueId"] = 10018402,
            ["Duration"] = 1.5,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19147C14",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100184/19147C14",
            },
        [10018501] = {
            ["Content"] = "占位文本",
            ["DialogueId"] = 10018501,
            ["GUID"] = "19148C52",
            ["VoiceName"] = "voice/$Locale$/story/1001/100185/19148C52",
            },
        [10018601] = {
            ["Content"] = "不要……",
            ["ContentKR"] = "안돼...",
            ["DialogueId"] = 10018601,
            ["Duration"] = 2,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19149CBA",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100186/19149CBA",
            },
        [10018602] = {
            ["Content"] = "不要……把……她……",
            ["ContentKR"] = "베레... 를...",
            ["DialogueId"] = 10018602,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19149CE4",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100186/19149CE4",
            },
        [10018603] = {
            ["Content"] = "滚开。",
            ["DialogueId"] = 10018603,
            ["Duration"] = 2,
            ["GUID"] = "19144AB3",
            ["SpeakNpcId"] = 100003,
            ["VoiceName"] = "voice/$Locale$/story/1001/100181/19144AB3",
            },
        [10018701] = {
            ["Content"] = "——“我是谁？”",
            ["ContentKR"] = "\"난 누구지?\"",
            ["DialogueId"] = 10018701,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "1914AD22",
            ["SpeakNpcId"] = 100001,
            },
        [10018801] = {
            ["DialogueId"] = 10018801,
            ["Duration"] = 1,
            ["GUID"] = "1914BD8A",
            ["VoiceName"] = "voice/$Locale$/story/1001/100188/1914BD8A",
            },
        [10018901] = {
            ["Camera"] = "445.776367,-604.509766,186.644531,0.000533,7.394103,84.717964,24.0,500.0,false,Disable,22.0",
            ["Content"] = "出海指望不上了。看来只能试试那个……",
            ["ContentKR"] = "바다는 포기해야겠네. 아무래도 그걸 사용해 보는 수밖에...",
            ["DefaultLookAt"] = "KeepState",
            ["DialogueId"] = 10018901,
            ["FacialId"] = {
