            ["GUID"] = "190FAD9E",
            ["SpeakNpcId"] = 100003,
            ["TalkActionId"] = {
                [1] = "100003:Agree",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1001/100109/190FAD9E",
            },
        [10019001] = {
            ["Content"] = "村子里什么人声都没有，恐怕他们已经……",
            ["ContentKR"] = "마을에서 아무런 소리도 안 나는 걸 보니, 아무래도 이미...",
            ["DialogueId"] = 10019001,
            ["Duration"] = 1.8,
            ["GUID"] = "1914DE5A",
            ["NextDialogue"] = 10019002,
            ["SpeakNpcId"] = 100003,
            ["VoiceName"] = "voice/$Locale$/story/1001/100190/1914DE5A",
            },
        [10019002] = {
            ["Content"] = "……！！",
            ["ContentKR"] = "......!!",
            ["DialogueId"] = 10019002,
            ["Duration"] = 2,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "1914DE84",
            ["NextDialogue"] = 10019003,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100190/1914DE84",
            },
        [10019003] = {
            ["Content"] = "……我的意思是，他们大多应该乘船逃走了。",
            ["ContentKR"] = "...아니, 대다수는 이미 배를 타고 도망친 것 같다는 거야.",
            ["DialogueId"] = 10019003,
            ["Duration"] = 2.5,
            ["GUID"] = "1914DEAE",
            ["NextDialogue"] = 10019004,
            ["SpeakNpcId"] = 100003,
            ["VoiceName"] = "voice/$Locale$/story/1001/100190/1914DEAE",
            },
        [10019004] = {
            ["Content"] = "抓紧回家拿到武器，然后去码头吧。这里现在还很危险。",
            ["ContentKR"] = "어서 집으로 가서 무기를 가지고 부두로 가자. 여기는 아직 위험해.",
            ["DialogueId"] = 10019004,
            ["Duration"] = 2.5,
            ["GUID"] = "1914DEAF",
            ["NextDialogue"] = 10019005,
            ["SpeakNpcId"] = 100003,
            ["VoiceName"] = "voice/$Locale$/story/1001/100190/1914DEAF",
            },
        [10019005] = {
            ["Content"] = "（……我们现在赤手空拳，得尽量避开秽兽。）",
            ["ContentKR"] = "(...지금은 무기가 없으니 최대한 필토이드를 피해야 해)",
            ["DialogueId"] = 10019005,
            ["Duration"] = 2.5,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "1914DEB1",
            ["NextDialogue"] = 10019006,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100190/1914DEB1",
            },
        [10019006] = {
            ["Content"] = "还差一点……家就在前面了。",
            ["ContentKR"] = "조금만 더 가면 돼... 집이 바로 앞이야.",
            ["DialogueId"] = 10019006,
            ["Duration"] = 2.5,
            ["GUID"] = "1914DEB2",
            ["SpeakNpcId"] = 100003,
            ["VoiceName"] = "voice/$Locale$/story/1001/100190/1914DEB2",
            },
        [10019007] = {
