            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1001/100191/1914EF16",
            },
        [10019104] = {
            ["Content"] = "你在说什么……",
            ["ContentKR"] = "무슨 말을 하는 거야...",
            ["DialogueId"] = 10019104,
            ["DisableMouth"] = 1,
            ["Duration"] = 5,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "1914EF17",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100191/1914EF17",
            },
        [10019201] = {
            ["Content"] = "关于那柄剑……除了它从小就在身边之外，我一无所知。",
            ["DialogueId"] = 10019201,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "1914FF2A",
            ["NextDialogue"] = 10019202,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100192/1914FF2A",
            },
        [10019202] = {
            ["Content"] = "正如我不知道自己从何而来——我没有与贝蕾相遇之前的任何记忆。",
            ["DialogueId"] = 10019202,
            ["Duration"] = 3.5,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "1914FF54",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100192/1914FF54",
            },
        [10019301] = {
            ["Content"] = "秽兽没完没了的……",
            ["ContentKR"] = "필토이드가 끝도 없이 몰려와...",
            ["DialogueId"] = 10019301,
            ["Duration"] = 3.5,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19150F92",
            ["NextDialogue"] = 10019302,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100193/19150F92",
            },
        [10019302] = {
            ["Content"] = "向上跑。甩掉它们。",
            ["ContentKR"] = "빨리 올라가자. 필토이드를 떨쳐내는 거야.",
            ["DialogueId"] = 10019302,
            ["Duration"] = 4,
            ["GUID"] = "19150FBC",
            ["SpeakNpcId"] = 100003,
            ["VoiceName"] = "voice/$Locale$/story/1001/100193/19150FBC",
            },
        [10019401] = {
            ["Content"] = "这是我第一次来科赛托斯省。看来，这里的待客之道颇为独特啊。",
            ["ContentKR"] = "코퀴투스에 온 것은 처음이지만, 여긴 손님 대접하는 방식이 참 독특한 것 같군.",
            ["DialogueId"] = 10019401,
            ["Duration"] = 8,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "19151FFA",
            ["RelatedWikiId"] = {
                [1] = 408002,
                },
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1001/100194/19151FFA",
            },
        [10019402] = {
            ["Content"] = "我没有任何恶意，只是想同你做一笔……小小的交易。",
            ["ContentKR"] = "악의는 없어... 그저 작은 거래를 하고 싶을 뿐.",
            ["DialogueId"] = 10019402,
            ["Duration"] = 5.3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "19152024",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1001/100194/19152024",
            },
        [10019403] = {
            ["Content"] = "我会付给你无法拒绝的报酬，而你要做的，非常简单。",
            ["ContentKR"] = "거절할 수 없는 대가를 주지. 네가 해야 할 일은 아주 간단해.",
            ["DialogueId"] = 10019403,
            ["Duration"] = 6.9,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1915204E",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1001/100194/1915204E",
            },
        [10019501] = {
            ["Content"] = "？？？：不杀了{性别：他|她}吗？",
            ["DialogueId"] = 10019501,
            ["Duration"] = 2.5,
            ["GUID"] = "19153057.0",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1001/100195/19153057",
            },
        [10019502] = {
            ["Content"] = "？？？：{性别：他|她}和您一样，拥有决定历史轨迹的力量。不要忘记，您的使命。",
            ["DialogueId"] = 10019502,
            ["Duration"] = 9,
            ["GUID"] = "19153058.0",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1001/100195/19153058",
            },
        [10019503] = {
            ["Content"] = "？？？：我会处理。但，现在还不是时候。",
            ["DialogueId"] = 10019503,
            ["Duration"] = 4,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "19153059.0",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1001/100195/19153059",
            },
        [10019504] = {
            ["Content"] = "？？？：收到。将如实提交您的答复。",
            ["DialogueId"] = 10019504,
            ["Duration"] = 5,
            ["GUID"] = "19153060.0",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1001/100195/19153060",
            },
        [10019505] = {
            ["Content"] = "？？？：……听着，{NickName}。",
            ["DialogueId"] = 10019505,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "19153061.0",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1001/100195/19153061",
            },
        [10019506] = {
            ["Content"] = "？？？：“生命是航行在无尽长夜里的孤船。”",
            ["DialogueId"] = 10019506,
            ["Duration"] = 4,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "19153062.0",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1001/100195/19153062",
            },
        [10019507] = {
            ["Content"] = "？？？：“河流泪水满溢，夹岸荆棘丛生。”",
            ["DialogueId"] = 10019507,
            ["Duration"] = 4,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1915308C",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1001/100195/1915308C",
            },
        [10019508] = {
            ["Content"] = "？？？：“我会一直注视着……”",
            ["DialogueId"] = 10019508,
            ["Duration"] = 4,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "191530B6",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1001/100195/191530B6",
            },
        [10019509] = {
            ["Content"] = "？？？：“来自彼岸之人，你将驶向何方。”",
            ["DialogueId"] = 10019509,
            ["Duration"] = 5,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "191530E0",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1001/100195/191530E0",
            },
        [10019510] = {
            ["Content"] = "（是谁……）",
            ["DialogueId"] = 10019510,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1915310A",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1001/100195/1915310A",
            },
        [10025701] = {
            ["Content"] = "这场逃亡，是从那场奇异的梦开始的；从小到大，我一直重复着相似的梦。",
            ["ContentKR"] = "이 도망은 그 기이한 꿈에서 시작한 것이다. 어릴 적부터 나는 같은 꿈을 꿔왔지만...",
            ["DialogueId"] = 10025701,
            ["Duration"] = 3,
            ["GUID"] = "19192992",
            ["NextDialogue"] = 10025702,
            ["VoiceName"] = "voice/$Locale$/story/1002/100257/19192992",
            },
        [10025702] = {
            ["Content"] = "但不容回想，我知道此刻有更急迫的事——",
            ["ContentKR"] = "지금은 과거를 추억할 때가 아니다.",
            ["DialogueId"] = 10025702,
            ["Duration"] = 3,
            ["GUID"] = "191929BC",
            ["NextDialogue"] = 10025703,
            ["VoiceName"] = "voice/$Locale$/story/1002/100257/191929BC",
            },
        [10025703] = {
            ["Content"] = "必须和贝蕾妮卡一起逃离这座叫做“净界岛”的小岛，即使这是我们一起长大的地方。",
            ["ContentKR"] = "반드시 베레니카와 함께 이 '연옥도'라는 섬에서 탈출해야 한다. 비록 이곳은 우리가 함께 자란 곳이지만.",
            ["DialogueId"] = 10025703,
            ["Duration"] = 4,
            ["GUID"] = "191929E6",
            ["VoiceName"] = "voice/$Locale$/story/1002/100257/191929E6",
            },
        [10025704] = {
            ["Content"] = "因为我们平静的生活，早已被秽兽的利爪撕碎……",
            ["ContentKR"] = "우리의 평온한 삶은 이미 필토이드의 날카로운 발톱에 갈기갈기 찢겼기 때문이다...",
            ["DialogueId"] = 10025704,
            ["Duration"] = 3,
            ["GUID"] = "19192A10",
            ["VoiceName"] = "voice/$Locale$/story/1002/100257/19192A10",
            },
        [10025801] = {
            ["Content"] = "这些秽兽……死了？",
            ["ContentKR"] = "이 필토이드들... 죽은 거야?",
            ["DialogueId"] = 10025801,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "191939FA",
            ["NextDialogue"] = 10025802,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100258/191939FA",
            },
        [10025802] = {
            ["Content"] = "看来在我们之前，这里就有人和秽兽战斗过。而且，还没过去太久。",
            ["ContentKR"] = "우리가 오기 전에 누군가 필토이드와 싸웠던 것 같네. 게다가 얼마 되지도 않은 것 같아.",
            ["DialogueId"] = 10025802,
            ["GUID"] = "19193A24",
            ["NextDialogue"] = 10025803,
            ["SpeakNpcId"] = 100003,
            ["VoiceName"] = "voice/$Locale$/story/1001/100258/19193A24",
            },
        [10025803] = {
            ["Content"] = "难道有村民逃到了这里……不，那扇门是我们打开的才对。",
            ["ContentKR"] = "설마 여기로 도망친 사람들이 있는 건가... 그럴 리가, 그 문은 우리가 열었는데.",
            ["DialogueId"] = 10025803,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19193A4E",
            ["NextDialogue"] = 10025804,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100258/19193A4E",
            },
        [10025804] = {
            ["Content"] = "不过好在有他帮忙清理，否则秽兽就更难对付了。",
            ["ContentKR"] = "어쨌든 필토이드를 처리해 줘서 다행이야. 덕분에 훨씬 편해졌어.",
            ["DialogueId"] = 10025804,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19193A78",
            ["NextDialogue"] = 10025805,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100258/19193A78",
            },
        [10025805] = {
            ["Content"] = "无论是谁，他的实力都不容小觑。我们也要留心。",
            ["ContentKR"] = "누군지 모르겠지만 만만치 않은 실력을 갖췄을 거야. 우리도 조심하자.",
            ["DialogueId"] = 10025805,
            ["GUID"] = "19193AA2",
            ["SpeakNpcId"] = 100003,
            ["VoiceName"] = "voice/$Locale$/story/1001/100258/19193AA2",
            },
        [10025806] = {
            ["Content"] = "这些秽兽……断气了？",
            ["ContentKR"] = "이 필토이드들…… 죽은 거야?",
            ["DialogueId"] = 10025806,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19193AA3",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100258/19193AA3",
            },
        [10027501] = {
            ["Content"] = "在不远处……",
            ["ContentKR"] = "멀지 않은 곳",
            ["DialogueId"] = 10027501,
            ["Duration"] = 2,
            ["GUID"] = "191A50E2",
            ["VoiceName"] = "voice/$Locale$/story/1001/100275/191A50E2",
            },
        [10029301] = {
            ["Content"] = "无数次，螺旋般往复的梦中，我一遍又一遍地问着。",
            ["ContentKR"] = "무수히 반복되는 꿈 속에서 몇 번이고 나 자신에게 물었다.",
            ["DialogueId"] = 10029301,
            ["Duration"] = 0.5,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "1914AD4C",
            ["NextDialogue"] = 10018401,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/100293/1914AD4C",
            },
        [10029309] = {
            ["Content"] = "恭喜你起名完成啦！！！！！",
            ["DialogueId"] = 10029309,
            ["Duration"] = 3,
            ["GUID"] = "1914AD4D",
            ["VoiceName"] = "voice/$Locale$/story/1002/100293/",
            },
        [10029401] = {
            ["Content"] = "要再休息一会儿吗？",
            ["ContentKR"] = "좀 더 쉴래?",
            ["DialogueId"] = 10029401,
            ["GUID"] = "1914AD4E",
            ["SpeakNpcId"] = 100003,
            },
        [10030101] = {
            ["Content"] = "呼…呼…",
            ["ContentKR"] = "헉... 헉...",
            ["DialogueId"] = 10030101,
            ["Duration"] = 3,
            ["GUID"] = "191BFB72",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100301/191BFB72",
            },
        [10030201] = {
            ["DialogueId"] = 10030201,
