        [10030607] = {
            ["Camera"] = "-405.321106,133.943359,83.382812,0.000094,-6.002507,-9.651911,35.0,681.079041,false,Manual,3.0",
            ["Content"] = "（嗯……看起来这两个人都还挺精神的。）",
            ["ContentKR"] = "(음... 다들 기운 넘쳐보이네.)",
            ["DialogueId"] = 10030607,
            ["DisableMouth"] = 1,
