        [10030608] = {
            ["Camera"] = "135.663208,-35.232422,147.521484,0.000062,-15.799928,131.261826,35.000023,295.694153,false,Manual,6.0",
            ["Content"] = "小仆从你感觉怎么样？嗯……胳膊腿都在，角的颜色很棒，脸色有点差。",
            ["ContentKR"] = "그래 시종, 몸은 좀 어때? 음... 팔다리는 멀쩡하고, 뿔 색깔도 아주 예쁘고, 안색은 좀 별로지만.",
            ["DialogueId"] = 10030608,
            ["GUID"] = "191C4EA0",
            ["LookAt"] = {
                [1] = "200002:n(100001)",
                [2] = "200021:n(100001)",
                [3] = "100001:n(200002)",
                },
            ["NextDialogue"] = 10030609,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Bai_Think2Confident",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C4EA0",
            },
        [10030609] = {
            ["Content"] = "很好，我就知道“不死的白色骑士，重生的夜航之星，被赐福的恶魔伯爵”不会随便抛下魔王大人不管的！",
            ["ContentKR"] = "아주 좋아. '불사의 백기사, 다시 태어난 녹토 보이저의 별, 축복받은 악마 백작'이 이 마왕님을 버리고 가지 않을 줄 알았어!",
            ["DialogueId"] = 10030609,
            ["FacialId"] = {
                [1] = "200002:Happy02",
                },
            ["GUID"] = "191C4ECA",
            ["NextDialogue"] = 10030610,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C4ECA",
            },
        [10030610] = {
            ["Content"] = "你坐在这里不要动，我去给你拿点水果补补身子！",
            ["ContentKR"] = "여기서 기다려, 내가 몸에 좋은 과일 좀 가져올 테니까!",
            ["DialogueId"] = 10030610,
            ["FacialId"] = {
                [1] = "200002:None",
                },
            ["GUID"] = "191C4EF4",
            ["NextDialogue"] = 10030631,
