            ["ToFinalCameraBlendTime"] = 4,
            ["TurnTo"] = {
                [1] = "100001:n(100304)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C4FF0",
            },
        [10030617] = {
            ["Camera"] = "230.647583,-1.03125,119.628906,0.000082,4.597776,170.360352,35.0,130.051529,false,DoNotOverride,3.0",
            ["Content"] = "……黎瑟·费西尔？",
            ["ContentKR"] = "...리듬 페실?",
            ["DialogueId"] = 10030617,
            ["GUID"] = "191C501A",
            ["NextDialogue"] = 10030618,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain01_End",
                [2] = "200002:Shock_End",
                [3] = "200021:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C501A",
            },
        [10030618] = {
            ["Content"] = "对，又来了。她基本每天这个点都要来问一次。",
            ["ContentKR"] = "맞아, 또 왔네. 매일 이 시간에 꼭 한 번씩 와서 물어보더라고.",
            ["DialogueId"] = 10030618,
            ["GUID"] = "191C5044",
            ["NextDialogue"] = 10030619,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C5044",
            },
        [10030619] = {
            ["Content"] = "……既然你说了“又”，那就说明这几天已经应付过她很多次了。交给你了，奥特赛德，加油，你可以的。",
            ["ContentKR"] = "...'또'라고 하는 걸 보니 며칠 사이 그녀를 여러 번 상대했다는 뜻이네. 이번에도 부탁할 게 아웃사이더, 힘내, 넌 할 수 있어.",
            ["DialogueId"] = 10030619,
            ["GUID"] = "191C506E",
            ["LookAt"] = {
                [1] = "200021:n(100001)",
                [2] = "100001:n(200021)",
                },
            ["NextDialogue"] = 10030620,
            ["SpeakNpcId"] = 100001,
            ["TurnTo"] = {
                [1] = "100001:n(200021)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C506E",
            },
        [10030620] = {
            ["Content"] = "等等，先别走。唉，我说过，这麻烦你逃不掉的。",
            ["ContentKR"] = "잠깐만, 일단 있어봐. 휴, 내가 말했잖아, 이건 네가 피할 수 없는 골칫거리라고.",
            ["DialogueId"] = 10030620,
            ["GUID"] = "191C5098",
            ["LookAt"] = {
                [1] = "200002:n(100001)",
                },
            ["NextDialogue"] = 10030621,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C5098",
            },
        [10030621] = {
            ["Content"] = "<W>卡戎狩猎</>是近期发生在外城的<W>连环凶案</>，你作为唯一幸存者不可能不被军团问话，时间早晚而已。",
            ["ContentKR"] = "<W>카론 사냥</>은 최근 외성에서 일어난 <W>연쇄살인 사건</>이야. 유일한 생존자인 네가 군단의 심문을 피할 수 있을 리가 없잖아. 시간문제일 뿐이지.",
            ["DialogueId"] = 10030621,
            ["GUID"] = "191C50C2",
            ["NextDialogue"] = 10030622,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C50C2",
            },
        [10030622] = {
            ["Content"] = "我看这位黎瑟女士还挺好说话的，这在军团可不多见。要是换个凶神恶煞的来，还不如她呢。",
            ["ContentKR"] = "내가 봤을 때 리듬 씨는 그래도 꽤나 나긋나긋한 것 같은데, 군단에서 그런 사람은 흔치 않아. 성격이 더러운 사람한테 심문받기보단 낫잖아.",
            ["DialogueId"] = 10030622,
            ["GUID"] = "191C50EC",
            ["NextOptions"] = {
                [1] = 10030623,
                [2] = 10030624,
                },
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C50EC",
            },
        [10030623] = {
            ["Content"] = "…………",
            ["ContentKR"] = "......",
            ["DialogueId"] = 10030623,
            ["GUID"] = "191C5116",
            ["NextDialogue"] = 10030625,
            },
        [10030624] = {
            ["Content"] = "……我不太想见她。",
            ["ContentKR"] = "...별로 만나고 싶지 않아.",
            ["DialogueId"] = 10030624,
            ["GUID"] = "191C5140",
            ["NextDialogue"] = 10030625,
            },
        [10030625] = {
            ["Content"] = "好吧，你的意思我懂了。既然你还没做好准备，那就还是先由我——",
            ["ContentKR"] = "그래, 무슨 뜻인지 알겠어. 준비가 안 됐다면 어쩔 수 없...",
            ["DialogueId"] = 10030625,
            ["GUID"] = "191C516A",
            ["NextDialogue"] = 10030626,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Talk01_End",
                },
