            },
        [10030627] = {
            ["Camera"] = "3.56424,135.133789,143.957031,0.000086,-7.202332,-42.028748,35.000008,998.946716,false,Manual,3.0",
            ["Content"] = "……她看到了！",
            ["ContentKR"] = "...봤구나!",
            ["DialogueId"] = 10030627,
