            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C51BE",
            },
        [10030628] = {
            ["Camera"] = "230.647583,-1.03125,119.628906,0.000082,4.597776,170.360352,35.0,130.051529,false,DoNotOverride,3.0",
            ["Content"] = "那就没办法了，去吧{性别：兄弟|朋友}，该来的总会来的。",
            ["ContentKR"] = "그럼 어쩔 수 없지, 어서 가 친구야. 피할 수 없으면 즐겨야지.",
            ["DialogueId"] = 10030628,
            ["GUID"] = "191C51E8",
            ["LookAt"] = {
                [1] = "200021:n(100304)",
