            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C51E8",
            },
        [10030629] = {
            ["Content"] = "唉，真是甩不掉的麻烦啊。",
            ["ContentKR"] = "휴, 진짜 피할 수 없는 골칫거리네.",
            ["DialogueId"] = 10030629,
            ["FacialId"] = {
                [1] = "100001:None",
