            ["NextDialogue"] = 10030630,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Sigh_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C5212",
            },
        [10030630] = {
            ["Camera"] = "-285.275513,162.134766,109.957031,0.000065,2.195619,-25.839436,35.000008,1787541766275072.0,false,Manual,3.0",
            ["Content"] = "……先看看这家伙到底有什么事吧。",
