            },
        [10030702] = {
            ["Camera"] = "-89.270386,-159.456055,192.513672,0.000299,-23.794125,44.6567,35.000015,330.701721,false,Manual,3.0",
            ["Content"] = "长官要喝点什么吗？今天“冰湖往事”打五折哦。",
            ["ContentKR"] = "장교님, 마실 것 좀 드릴까요? 지금 '아이스레이크의 이야기'가 반값 세일중입니다.",
            ["DialogueId"] = 10030702,
            ["FacialId"] = {
                [1] = "200002:Happy02",
                },
            ["GUID"] = "191C5E0C",
            ["LookAt"] = {
                [1] = "100304:n(200002)",
                },
            ["NextDialogue"] = 10030703,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100307/191C5E0C",
            },
        [10030703] = {
            ["Camera"] = "29.417786,145.418945,56.080078,0.000265,19.004721,-80.540367,35.000011,219.87709,false,Manual,3.0",
            ["Content"] = "不用。帝国军律第142条规定军人执勤期间不能饮酒，而且我也没有这个习惯。",
            ["ContentKR"] = "괜찮습니다. 제국 군법 제142조는 군인의 근무 중 음주를 금지하고 있고, 저 또한 술 마시는 습관이 없습니다.",
            ["DialogueId"] = 10030703,
            ["FacialId"] = {
                [1] = "200002:None",
                [2] = "100304:Shock01",
                },
            ["GUID"] = "191C5E36",
            ["NextDialogue"] = 10030704,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100307/191C5E36",
            },
        [10030704] = {
            ["Camera"] = "-373.256409,-7.81543,220.638672,0.000206,-19.196136,3.056015,25.0,219.87709,false,Manual,3.0",
            ["Content"] = "我直接说正题吧。我是为了调查冰湖城外城近几日的恶性事件“卡戎狩猎”而来。",
            ["ContentKR"] = "바로 본론으로 들어가겠습니다. 최근 아이스레이크 시티 외성에서 발생한 '카론 사냥' 사건에 대해 조사하기 위해 찾아왔습니다.",
            ["DialogueId"] = 10030704,
            ["FacialId"] = {
                [1] = "100304:Unhappy01",
                },
            ["FinalCamera"] = "-330.987732,-5.65625,205.90625,0.000206,-19.196136,2.856016,25.0,219.87709,false,Manual,3.0",
            ["GUID"] = "191C5E60",
            ["LookAt"] = {
                [1] = "100304:n(100001)",
                },
            ["NextDialogue"] = 10030705,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "200002:Explain02_End",
                },
            ["ToFinalCameraBlendTime"] = 3,
            ["VoiceName"] = "voice/$Locale$/story/1003/100307/191C5E60",
            },
        [10030705] = {
            ["Camera"] = "-196.299988,-7.27832,128.933594,0.000239,-0.99649,-6.538433,35.000019,254.835373,false,Manual,6.0",
            ["Content"] = "这是第一次询问，我需要按照惯例确认一下你的身份。可以给我看一下<H>通行证</>吗？",
            ["ContentKR"] = "이번이 첫 번째 심문이기 때문에 관례에 따라 당신의 신원을 확인해야 합니다. <H>통행증</>을 보여주시겠습니까?",
            ["DialogueId"] = 10030705,
            ["GUID"] = "191C602F",
            ["NextDialogue"] = 10030706,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100307/191C602F",
            },
        [10030706] = {
            ["Camera"] = "-16.850769,-112.700195,139.550781,0.000263,-2.797638,120.662224,35.000019,146.760483,false,Manual,6.0",
            ["Content"] = "…………！",
            ["ContentKR"] = "......!",
            ["DialogueId"] = 10030706,
            ["FacialId"] = {
                [1] = "100001:Unhappy01",
                },
            ["GUID"] = "191C6030",
            ["NextDialogue"] = 10030707,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Shock_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100307/191C6030",
            },
        [10030707] = {
            ["Content"] = "我急着出门，通行证还在家里，我先回去拿。",
            ["ContentKR"] = "급하게 나오느라 통행증을 집에 두고 왔어요. 지금 가서 가져올게요.",
            ["DialogueId"] = 10030707,
            ["GUID"] = "191C6031",
            ["NextDialogue"] = 10030708,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Shock_End",
                [2] = "100304:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100307/191C6031",
            },
        [10030708] = {
            ["Camera"] = "20.996643,167.708008,186.025391,0.000272,-16.19771,-130.733917,35.000015,206.537537,false,Manual,3.0",
            ["Content"] = "记错了吧？你通行证我前几天落在我家了，我正准备还给你——喏，长官，在这儿。",
            ["ContentKR"] = "잘못 기억한거 아냐? 너 며칠 전에 우리 집에 통행증을 두고 갔잖아. 마침 돌려주려 했는데, 자, 리듬 장교님, 여기있습니다.",
            ["DialogueId"] = 10030708,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["GUID"] = "191C6032",
            ["LookAt"] = {
                [1] = "200021:n(100001)",
                [2] = "100001:n(200021)",
                },
            ["NextDialogue"] = 10030709,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Give",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100307/191C6032",
            },
        [10030709] = {
            ["Camera"] = "20.996643,167.708008,186.025391,0.000272,-16.19771,-130.733917,35.000015,206.537537,false,Manual,3.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "……名字，{nickname}。居住城市，科赛托斯省，冰湖城。职业，驯兽师……",
            ["ContentKR"] = "...이름, {nickname}. 거주 도시, 코퀴투스 주, 아이스레이크 시티. 직업, 조련사...",
            ["DialogueId"] = 10030709,
            ["DialoguePanelType"] = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter_Passport.T_Guide_Chapter_Passport'}",
            ["FacialId"] = {
                [1] = "100304:None",
                },
            ["FinalCamera"] = "20.996643,167.708008,186.025391,0.000264,-15.397602,-85.33358,35.000015,310.0784,false,Manual,3.0",
            ["GUID"] = "191C6033",
            ["LookAt"] = {
                [1] = "200021:n(100304)",
                [2] = "100001:n(100304)",
                },
            ["NextDialogue"] = 10030710,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 3,
            ["VoiceName"] = "voice/$Locale$/story/1003/100307/191C6033",
            },
        [10030710] = {
            ["Camera"] = "-80.779236,-40.317383,131.921875,0.000273,3.401782,-7.736254,35.000023,126.193214,false,Manual,6.0",
            ["Content"] = "呃，你不是狩月人吗？",
            ["ContentKR"] = "음, 당신은 월석 사냥꾼이 아니었던가요?",
            ["DialogueId"] = 10030710,
            ["FacialId"] = {
                [1] = "100304:Unacceptable01",
                },
            ["GUID"] = "191C6034",
            ["NextDialogue"] = 10030711,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100307/191C6034",
            },
        [10030711] = {
            ["Camera"] = "136.852234,-320.489258,75.955078,0.000275,7.598257,113.8312,35.000019,482.916321,false,Manual,6.0",
            ["Content"] = "那是过去的事了。{性别：他|她}以前是专门给有钱人养狗的，前任主人破产了吃不上饭才来干这行。",
            ["ContentKR"] = "다 지나간 일이죠. 얘가 전엔 부잣집 강아지 돌봐주는 일을 했었거든요. 전 주인이 파산하고 먹고살기 어려워지니까 이쪽으로 넘어온 거죠.",
            ["DialogueId"] = 10030711,
            ["GUID"] = "191C6035",
            ["LookAt"] = {
                [1] = "100304:n(200021)",
                },
            ["NextDialogue"] = 10030712,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100307/191C6035",
            },
        [10030712] = {
            ["Content"] = "不信你去卡米拉女士那儿问问，{性别：他|她}就是前几天才登记成狩月人的。来，{nickname}，给长官展示一下你高超的训犬技巧。",
            ["ContentKR"] = "못 믿으시겠으면 카밀라 씨한테 물어보세요. 얘 진짜 바로 며칠 전에 월석 사냥꾼으로 등록했거든요. 자, {nickname}, 리듬 장교님한테 너의 뛰어난 조련 스킬을 좀 보여드려.",
            ["DialogueId"] = 10030712,
            ["GUID"] = "191C6036",
            ["NextDialogue"] = 10030713,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100307/191C6036",
            },
        [10030713] = {
            ["Camera"] = "35.158813,-132.652344,109.820312,0.000287,8.387151,125.228546,35.000023,303.465393,false,Manual,6.0",
            ["Content"] = "嘬嘬嘬。",
            ["ContentKR"] = "우쭈쭈쭈.",
            ["DialogueId"] = 10030713,
            ["GUID"] = "191C6037",
            ["LookAt"] = {
                [1] = "100001:n(200021)",
                [2] = "200021:n(100001)",
                [3] = "100304:n(100001)",
                },
            ["NextDialogue"] = 10030714,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "200021:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100307/191C6037",
            },
        [10030714] = {
            ["Content"] = "不是，你对着我嘬什么啊！",
            ["ContentKR"] = "아니, 나한테 말고!",
            ["DialogueId"] = 10030714,
            ["FacialId"] = {
                [1] = "200021:Shock01",
                },
            ["GUID"] = "191C6038",
            ["LookAt"] = {
                [1] = "100304:n(200021)",
                },
            ["NextDialogue"] = 10030715,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Shock_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100307/191C6038",
            },
        [10030715] = {
            ["Camera"] = "-203.567261,147.061523,100.875,0.000257,3.596395,-42.564396,35.000015,382.628754,false,Manual,3.0",
            ["Content"] = "……好，通行证我看过没问题了，谢谢配合。接下来，我们来说袭击的事吧。",
            ["ContentKR"] = "...그래요, 통행증은 문제없습니다. 협조에 감사드립니다. 이제 습격에 관해 말씀 부탁드리겠습니다.",
            ["DialogueId"] = 10030715,
            ["FacialId"] = {
                [1] = "200021:None",
                },
            ["FinalCamera"] = "-204.68335,145.84668,116.058594,0.000257,3.596395,-42.564442,35.000019,321.983032,false,Manual,6.0",
            ["GUID"] = "191C6039",
            ["LookAt"] = {
                [1] = "200021:n(100304)",
                [2] = "100001:n(100304)",
                [3] = "100304:n(100001)",
                },
            ["NextDialogue"] = 10030716,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "200021:Shock_End",
                [2] = "100304:AgreeHead",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1003/100307/191C6039",
            },
        [10030716] = {
            ["Camera"] = "-70.692688,-985.964844,130.398438,0.000275,-3.004272,85.63118,35.000011,8667.292969,false,Manual,3.0",
            ["Content"] = "我想尽快抓住那个袭击你的凶手，还你们大家一个安全。{nickname}，你是这次连续袭击中唯一的幸存者，对我们掌握案情至关重要。只是酒馆人多眼杂——",
            ["ContentKR"] = "저는 범인을 최대한 빨리 잡아서 모두에게 안전을 되찾아주고 싶습니다. 이번 연쇄 습격에서 살아남은 유일한 생존자로서, {nickname} 씨는 저희가 작업을 진행하는 데 매우 중요합니다. 하지만 여기는 사람이 너무 많아서...",
            ["DialogueId"] = 10030716,
            ["FinalCamera"] = "-68.961426,-964.299805,129.412109,0.000276,-2.604269,85.431206,35.000011,8667.292969,false,Manual,3.0",
            ["GUID"] = "191C5E8A",
            ["NextDialogue"] = 10030717,
            ["Scripts"] = "LookAt{LookAtDescription{\"100304:p(lise_03_looking)\"}}",
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Explain01_Start",
                },
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/story/1003/100307/191C5E8A",
            },
        [10030717] = {
            ["Camera"] = "136.852234,-320.489258,75.955078,0.000275,7.598257,113.8312,35.000019,482.916321,false,Manual,6.0",
            ["Content"] = "哦，懂了。那我们就找个安静点的地方聊吧。",
            ["ContentKR"] = "아아, 알겠습니다. 그럼, 저희 좀 조용한 장소로 옮겨서 얘기하죠.",
            ["DialogueId"] = 10030717,
            ["GUID"] = "191C5EB4",
            ["LookAt"] = {
                [1] = "100304:n(200021)",
                },
            ["NextDialogue"] = 10030718,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:AgreeHead",
                [2] = "100304:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100307/191C5EB4",
            },
        [10030718] = {
            ["Camera"] = "136.852234,-320.489258,75.955078,0.000275,7.598257,113.8312,35.000019,482.916321,false,Manual,6.0",
            ["Content"] = "万分感谢，请随我来。",
            ["ContentKR"] = "감사드립니다. 저를 따라오세요.",
            ["DialogueId"] = 10030718,
            ["FacialId"] = {
                [1] = "100304:None",
                },
            ["GUID"] = "191C5EDE",
            ["NextDialogue"] = 10030719,
