        [10031005] = {
            ["Camera"] = "-64.777344,-47.655518,128.217285,0.000165,-0.000854,-48.591522,40.0,941.904541,false,DoNotOverride,1.2",
            ["Content"] = "不记得。那时我……心情不太好。觉得回家也多半睡不着，就想着在城里散散心。",
            ["ContentKR"] = "기억 안 나요. 그땐... 기분이 좀 별로여서 집에 돌아가도 잠들기 힘들겠다 싶어서 바람 좀 쐬려고 했죠. ",
            ["DetectiveQuestionId"] = 1001,
            ["DialogueId"] = 10031005,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["FinalCamera"] = "-66.598633,-49.306152,128.217285,0.000165,-0.000854,-46.391235,40.0,941.904541,false,DoNotOverride,1.2",
