            },
        [10031006] = {
            ["Camera"] = "-401.587891,135.657227,245.506836,0.000158,-15.000843,-35.580502,35.0,941.904541,false,DoNotOverride,22",
            ["Content"] = "具体的时间……我……当时在想其他事，不记得了。",
            ["ContentKR"] = "구체적인 시간은... 제가... 그때 다른 생각을 하고 있어서 기억이 안 나요.",
            ["DetectiveQuestionId"] = 1001,
            ["DialogueId"] = 10031006,
            ["FacialId"] = {
