            },
        [10031008] = {
            ["Camera"] = "114.541016,142.993408,51.0,0.000056,8.797734,-105.975533,35.0,941.904541,false,DoNotOverride,1.903106",
            ["Content"] = "没事，是我想一个人走走。",
            ["ContentKR"] = "괜찮아, 내가 혼자 걷고 싶어서 그런 건데 뭐.",
            ["DetectiveQuestionId"] = 1001,
            ["DialogueId"] = 10031008,
            ["FinalCamera"] = "122.243164,140.819336,51.0,0.000055,8.797734,-107.575684,35.0,941.904541,false,DoNotOverride,1.903106",
