        [10031009] = {
            ["Camera"] = "16.606445,-174.10498,173.058594,10.800163,-21.601551,-45.770706,35.0,941.904541,false,DoNotOverride,1.903106",
            ["Content"] = "（等一下……我还记得刚走到这条街的时候，风刚停，月亮出来了。看月亮的位置，应该是……<H>凌晨四点到五点之间</>？）",
            ["ContentKR"] = "(잠깐만... 내가 이 거리까지 걸었을 때 마침 바람이 그치고 달이 떴던 것 같은데. 달의 위치를 보면 아마도... <H>새벽 네 시부터 다섯 시 사이인 건가</>?)",
            ["DetectiveQuestionId"] = 1001,
            ["DialogueId"] = 10031009,
            ["DisableMouth"] = 1,
            ["FacialId"] = {
                [1] = "100001:Doubt01",
