                [2] = 405005,
                },
            ["Scripts"] = "PlayAnimation{_delay{4},ActorId{100304},AnimationId{\"Think_End\"},Duration{2}}",
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1003/100311/191C9F82",
            },
        [10031102] = {
            ["Camera"] = "164.110352,-295.21875,130.549805,0.000187,-2.201418,135.795242,35.0,324.824371,false,Manual,3.0",
            ["Content"] = "那么，关于凶手的特征，你还记得多少？我想知道线索，任何线索都可以。",
            ["ContentKR"] = "그럼, 범인의 특징에 대해 기억나는 것이 있습니까? 단서가 필요합니다, 그 어떤 단서도 상관없습니다.",
            ["DialogueId"] = 10031102,
            ["FacialId"] = {
                [1] = "100304:None",
                },
            ["GUID"] = "191C9FAC",
            ["NextDialogue"] = 10031103,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100311/191C9FAC",
            },
        [10031103] = {
            ["Camera"] = "1.719727,-99.894531,130.34082,0.000209,1.398256,-61.207794,35.000011,324.828125,false,Manual,22.0",
            ["Content"] = "当时的袭击太突然，我没看太清楚凶手的长相。但有一点我可以确认，它……不是人。",
            ["ContentKR"] = "너무 갑작스럽게 당해서 어떻게 생겼는지 제대로 보진 못했어요. 하지만 한가지는 분명해요. 그건... 사람이 아니었어요.",
            ["DialogueId"] = 10031103,
            ["FacialId"] = {
                [1] = "200002:Shock01",
                [2] = "200021:Shock01",
                },
            ["GUID"] = "191C9FD6",
            ["LookAt"] = {
                [1] = "100001:n(100304)",
                },
            ["NextDialogue"] = 10031104,
            ["Scripts"] = "CameraMoveTo{_delay{7},TargetPosition{\"56.811523,-148.78833,135.421875,0.000207,4.598254,-77.806282,35.000011,324.828125,false,Manual,22.0\"},duration{0}},",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100311/191C9FD6",
            },
        [10031104] = {
            ["Camera"] = "56.811523,-148.78833,135.421875,0.000208,4.59824,-76.605972,35.000015,324.828125,false,Manual,22.0",
            ["Content"] = "我昏倒前最后一刻看到的，是一张怪物的面孔。至于到底是秽兽还是其他什么，就不清楚了。",
            ["ContentKR"] = "정신을 잃기 전 마지막 순간에 본 건, 괴물의 얼굴이었어요. 그게 필토이드인지 다른 뭔가인지는, 저도 잘 모르겠어요.",
            ["DialogueId"] = 10031104,
            ["FacialId"] = {
                [1] = "100001:Think01",
                },
            ["GUID"] = "191CA000",
            ["LookAt"] = {
                [1] = "200021:n(100001)",
                },
            ["NextDialogue"] = 10031105,
            ["Scripts"] = "PlayAnimation{_delay{6},ActorId{100001},AnimationId{\"Think_End\"},Duration{2}}",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100311/191CA000",
            },
        [10031105] = {
            ["Camera"] = "149.513672,-169.366943,198.691895,0.000219,-21.601606,154.789032,35.0,324.824371,false,DoNotOverride,22",
            ["Content"] = "嗯……怪物，这个我已经知道了。没有其他信息了吗……",
            ["ContentKR"] = "네... 괴물 말이죠. 그건 저도 이미 압니다. 다른 정보는 없을까요...",
            ["DialogueId"] = 10031105,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["GUID"] = "191CA02A",
            ["LookAt"] = {
                [1] = "200021:n(100304)",
                },
            ["NextDialogue"] = 10031106,
            ["Scripts"] = "PlayAnimation{_delay{3},ActorId{100304},AnimationId{\"Think_End\"},Duration{2}}",
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100311/191CA02A",
            },
        [10031106] = {
            ["Camera"] = "5.640625,-44.589111,120.307129,0.000218,2.797017,-73.17907,35.000015,324.824371,false,DoNotOverride,22",
            ["Content"] = "等等，还有一件事！",
            ["ContentKR"] = "잠시만요, 또 한가지 있어요!",
            ["DialogueId"] = 10031106,
            ["FacialId"] = {
                [1] = "100001:Shock01",
                },
            ["GUID"] = "191CA054",
            ["NextDialogue"] = 10031107,
