            ["TalkActionId"] = {
                [1] = "100001:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100311/191CA054",
            },
        [10031107] = {
            ["Content"] = "请说！",
            ["ContentKR"] = "말씀하세요!",
            ["DialogueId"] = 10031107,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["GUID"] = "191CA07E",
