            },
        [10031204] = {
            ["Camera"] = "-69.961914,-225.399414,156.75,0.000232,-6.595599,79.803307,35.000023,358.523438,false,Manual,3.0",
            ["Content"] = "原来你也和我一样不擅长音乐。",
            ["ContentKR"] = "당신도 저처럼 음악에 재능이 없는 모양이군요.",
            ["DetectiveQuestionId"] = 1003,
            ["DialogueId"] = 10031204,
            ["FacialId"] = {
                [1] = "100304:Ahaha01",
                },
            ["GUID"] = "191CB068",
            ["NextOptions"] = {
                [1] = 10031205,
                [2] = 10031207,
                },
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Explain02_Start",
                },
            ["TurnTo"] = {
                [1] = "200021:n(100304)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100312/191CB068",
            },
        [10031205] = {
            ["Content"] = "没错，唱歌好难。",
            ["ContentKR"] = "맞아요, 노래는 너무 어려워요.",
            ["DetectiveQuestionId"] = 1003,
            ["DialogueId"] = 10031205,
            ["GUID"] = "191CB092",
            ["ImprPlusId"] = 1009,
            ["NextDialogue"] = 10031206,
            },
        [10031206] = {
            ["Camera"] = "-54.453125,66.138184,140.532715,0.000112,-0.197263,-73.591354,35.000011,100000.0,false,Manual,22.0",
            ["Content"] = "况且我就听了一遍，记不住旋律。不过，如果能再次听到那支曲子的话，我大概可以认出来。",
            ["ContentKR"] = "게다가 한 번만 들어서 멜로디를 기억할 수가 없었어요. 하지만 다시 한번 들을 수 있다면, 기억해 낼 수 있을 것 같아요.",
            ["DetectiveQuestionId"] = 1003,
            ["DialogueId"] = 10031206,
            ["GUID"] = "191CB0BC",
            ["NextDialogue"] = 10031209,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100304:Explain02_End",
                [2] = "100001:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100312/191CB0BC",
            },
        [10031207] = {
            ["Content"] = "我才没五音不全，少来套近乎。",
            ["ContentKR"] = "저 음치 아니에요. 친한 척 하지 마세요.",
            ["DetectiveQuestionId"] = 1003,
            ["DialogueId"] = 10031207,
            ["GUID"] = "191CB0E6",
            ["ImprPlusId"] = 1010,
            ["NextDialogue"] = 10031208,
            },
        [10031208] = {
            ["Camera"] = "-54.453125,66.138184,140.532715,0.000112,-0.197263,-73.591354,35.000011,100000.0,false,Manual,22.0",
            ["Content"] = "只是睡太久忘了而已。如果再次听到那支曲子的话，我一定能认出来的。",
            ["ContentKR"] = "너무 오래 자서 까먹은 것뿐입니다. 한 번만 다시 더 들을 수 있다면 꼭 기억해 낼 수 있어요.",
            ["DetectiveQuestionId"] = 1003,
            ["DialogueId"] = 10031208,
            ["GUID"] = "191CB110",
            ["NextDialogue"] = 10031209,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100304:Explain02_End",
                [2] = "100001:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100312/191CB110",
            },
        [10031209] = {
            ["Camera"] = "-53.863281,-63.319824,136.021973,0.000113,2.80494,77.005501,35.000015,100000.0,false,Manual,22.0",
            ["Content"] = "那就有劳你多留意了。",
            ["ContentKR"] = "그럼, 신경 좀 써주시길 부탁드리겠습니다.",
            ["DetectiveQuestionId"] = 1003,
            ["DialogueId"] = 10031209,
            ["FacialId"] = {
                [1] = "100304:None",
                },
            ["GUID"] = "191CB13A",
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100312/191CB13A",
            },
        [10031210] = {
            ["Content"] = "这是……一块布？手感还挺好的。",
            ["ContentKR"] = "이건... 천 조각? 촉감이 괜찮네.",
            ["DetectiveQuestionId"] = 1003,
            ["DialogueId"] = 10031210,
            ["DialoguePanelType"] = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter_MainCurtain.T_Guide_Chapter_MainCurtain'}",
            ["GUID"] = "191CB164",
            ["NextDialogue"] = 10031211,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100312/191CB164",
            },
        [10031211] = {
            ["Content"] = "（贝蕾就很喜欢这种毛茸茸的触感……）",
            ["ContentKR"] = "(베레가 이런 보송보송한 촉감을 좋아하는데...)",
            ["DetectiveQuestionId"] = 1003,
            ["DialogueId"] = 10031211,
            ["DisableMouth"] = 1,
            ["GUID"] = "191CB18E",
            ["NextDialogue"] = 10031212,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100312/191CB18E",
            },
        [10031212] = {
            ["Content"] = "我看一下……嗯，丝绒的，看花纹和折痕，这块布像是一块<H>舞台帷幕</>。",
            ["ContentKR"] = "어디 보자... 음, 벨벳이네요, 무늬와 주름을 보면 이건 <H>무대 커튼</> 같습니다.",
            ["DetectiveQuestionId"] = 1003,
            ["DialogueId"] = 10031212,
            ["GUID"] = "191CB1B8",
            ["NextDialogue"] = 10031213,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100312/191CB1B8",
            },
        [10031213] = {
            ["Content"] = "这附近有舞台的地方，只有<H>盖雷亚剧院</>。最近那里正在为<H>银烛狂欢</>庆典做准备，人多手杂，有人不小心把废弃幕布丢掉了也不奇怪。",
            ["ContentKR"] = "근처에 무대가 있는 곳은 오직 <H>갈레아 극장</>뿐입니다. 요즘 그곳은 <H>은촛불 축제</> 준비로 바쁘기 때문에 누군가 실수로 낡은 무대 커튼을 잃어버린 것도 이상한 일은 아니죠.",
            ["DetectiveQuestionId"] = 1003,
            ["DialogueId"] = 10031213,
            ["GUID"] = "191CB1E2",
            ["NextDialogue"] = 10031214,
            ["RelatedWikiId"] = {
                [1] = 406002,
                [2] = 405006,
                },
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100312/191CB1E2",
            },
        [10031214] = {
            ["Content"] = "（银烛……庆典，城里那些装饰就是因为这个庆典吗？）",
            ["ContentKR"] = "(은촛불... 축제, 도심 속에 그 장식도 축제 때문인가?)",
            ["DetectiveQuestionId"] = 1003,
            ["DialogueId"] = 10031214,
            ["DisableMouth"] = 1,
            ["GUID"] = "191CB20C",
            ["NextDialogue"] = 10031215,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100312/191CB20C",
            },
        [10031215] = {
            ["Content"] = "如果只有这块布也看不出什么，但是如果把这条线索和你刚才提到的另一条线索结合起来……",
            ["ContentKR"] = "이 천 쪼가리로는 아무것도 알아낼 수 없지만, 이 단서를 방금 당신께서 말씀하신 또 하나의 단서와 결합한다면...",
            ["DetectiveQuestionId"] = 1003,
            ["DialogueId"] = 10031215,
            ["GUID"] = "191CB236",
            ["NextDialogue"] = 10031216,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100312/191CB236",
            },
        [10031216] = {
            ["Content"] = "（嗯……舞台帷幕，的确和<H>那个线索</>有一定关联。）",
            ["ContentKR"] = "(음... 무대 커튼, 분명히 <H>그 단서</>와 어느 정도 연관이 있어.)",
            ["DetectiveQuestionId"] = 1003,
            ["DialogueId"] = 10031216,
            ["DisableMouth"] = 1,
            ["GUID"] = "191CB260",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100312/191CB260",
            },
        [10031301] = {
            ["Content"] = "垃圾桶里有个<H>断掉的风向标</>哎。唔，看起来好新好新，就这样扔了吗……好浪费哦，不如咱们带走吧！",
            ["ContentKR"] = "쓰레기통에 <H>부러진 풍향계</>가 있네. 음, 완전 새 것 같은데 그냥 버리다니... 너무 아깝다, 그냥 우리가 가져가자!",
            ["DetectiveQuestionId"] = 1002,
            ["DialogueId"] = 10031301,
            ["DialoguePanelType"] = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter_Vane.T_Guide_Chapter_Vane'}",
            ["GUID"] = "191CC052",
            ["NextDialogue"] = 10031302,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1003/100313/191CC052",
            },
        [10031302] = {
            ["Content"] = "你喜欢收集风向标吗？真是奇怪的爱好。我可以托我下属买个新的送你，但是这个是证物，不能交给你处置。",
            ["ContentKR"] = "풍향계 수집을 좋아하시나요? 정말 이상한 취미군요. 제 부하에게 부탁하여 새로 사서 드릴 순 있지만 이건 증거물이기 때문에 드릴 수 없습니다.",
            ["DetectiveQuestionId"] = 1002,
            ["DialogueId"] = 10031302,
            ["GUID"] = "191CC07C",
            ["NextDialogue"] = 10031303,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100313/191CC07C",
            },
        [10031303] = {
            ["Content"] = "那、那个……白就是随口一说！我、我并不是喜欢风向标……",
            ["ContentKR"] = "그, 그냥... 해 본 말이야! 나, 나 풍향계 별로 안 좋아해...",
            ["DetectiveQuestionId"] = 1002,
            ["DialogueId"] = 10031303,
            ["GUID"] = "191CC0A6",
            ["NextDialogue"] = 10031304,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1003/100313/191CC0A6",
            },
        [10031304] = {
            ["Content"] = "呜呜，头一次真的有人把白说的话当回事，好感动，呜呜呜……",
            ["ContentKR"] = "엉엉, 처음으로 누군가 스노우 말에 귀를 기울여줬어, 감동이야, 흑흑...",
            ["DetectiveQuestionId"] = 1002,
            ["DialogueId"] = 10031304,
            ["GUID"] = "191CC0D0",
            ["NextDialogue"] = 10031305,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1003/100313/191CC0D0",
            },
        [10031305] = {
            ["Content"] = "黎瑟长官，这条街是什么时候开始封锁的？",
            ["ContentKR"] = "리듬 장교님, 이 거리는 언제부터 봉쇄된 거죠?",
            ["DetectiveQuestionId"] = 1002,
            ["DialogueId"] = 10031305,
            ["GUID"] = "191CC0FA",
            ["NextDialogue"] = 10031306,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100313/191CC0FA",
            },
        [10031306] = {
            ["Content"] = "“卡戎狩猎”第一起案发的次日清晨。",
            ["ContentKR"] = "첫 번째 '카론 사냥' 사건이 발생한 다음 날 아침입니다.",
            ["DetectiveQuestionId"] = 1002,
            ["DialogueId"] = 10031306,
            ["GUID"] = "191CC124",
            ["NextDialogue"] = 10031307,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100313/191CC124",
            },
        [10031307] = {
            ["Content"] = "封锁得还算及时……既然是新的，这枚风向标应该也不是被谁故意丢弃在这里……",
            ["ContentKR"] = "봉쇄가 꽤 제때 이뤄졌네요... 새로운 풍향계이니 누군가 일부러 여기에 버려뒀을 리는 없을 것 같고...",
            ["DetectiveQuestionId"] = 1002,
            ["DialogueId"] = 10031307,
            ["GUID"] = "191CC14E",
            ["NextDialogue"] = 10031308,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100313/191CC14E",
            },
        [10031308] = {
            ["Content"] = "难道是那晚的大风？",
            ["ContentKR"] = "설마 그날 밤 바람 때문에?",
            ["DetectiveQuestionId"] = 1002,
            ["DialogueId"] = 10031308,
            ["GUID"] = "191CC178",
            ["NextDialogue"] = 10031309,
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1003/100313/191CC178",
            },
        [10031309] = {
            ["Content"] = "不，五天前的那场风暴后，治安署的确收到过很多财产损失报告，但这枚风向标并不是被吹下来的，更大的可能是被凶手<H>撞下来的</>。",
            ["ContentKR"] = "아닙니다. 5일 전 그 폭풍우 이후 치안서에서 재산 피해 보고를 많이 받은 건 사실이지만 이 풍향계는 바람에 쓰러진 건 아닐 겁니다. 범인에게 <H>부딪혀 쓰러졌을</> 가능성이 더 큽니다.",
            ["DetectiveQuestionId"] = 1002,
            ["DialogueId"] = 10031309,
            ["GUID"] = "191CC1A2",
            ["NextDialogue"] = 10031310,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100313/191CC1A2",
            },
        [10031310] = {
            ["Content"] = "卡米拉女士的证词说，凶手和她交手之后，跳上了<H>楼顶</>。这枚风向标，就是从那里掉下来的。",
            ["ContentKR"] = "카밀라 씨의 증언에 따르면, 범인은 그녀와 싸운 뒤 <H>옥상</>으로 뛰어올라 갔다고 합니다. 그 풍향계는 거기에서 떨어진 것입니다.",
            ["DetectiveQuestionId"] = 1002,
            ["DialogueId"] = 10031310,
            ["GUID"] = "191CC1CC",
            ["NextDialogue"] = 10031311,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100313/191CC1CC",
            },
        [10031311] = {
            ["Content"] = "（楼顶吗……也顺带去看一下吧。）",
            ["ContentKR"] = "(옥상이라... 한번 가보는 것도 나쁘지 않겠지.)",
            ["DetectiveQuestionId"] = 1002,
            ["DialogueId"] = 10031311,
            ["DisableMouth"] = 1,
            ["GUID"] = "191CC1F6",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100313/191CC1F6",
            },
        [10031401] = {
            ["Content"] = "就是这个了，缺口完全一致。底座的弯折痕迹，比起被风吹断，更像是人为撞击所致。",
            ["ContentKR"] = "바로 이겁니다. 부러진 부위가 완전히 일치해요. 받침대의 구부러진 흔적은 바람에 부러졌다기보단 인위적인 충돌로 인한 것으로 보이는군요. ",
            ["DetectiveQuestionId"] = 1002,
            ["DialogueId"] = 10031401,
            ["DialoguePanelType"] = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter_VaneBottom.T_Guide_Chapter_VaneBottom'}",
            ["GUID"] = "191CD0BA",
            ["NextDialogue"] = 10031402,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100314/191CD0BA",
            },
        [10031402] = {
            ["Content"] = "从这个弯折角度，不难推测它逃窜的方向。",
            ["ContentKR"] = "구부러진 각도로 도망친 방향도 쉽게 추측해 낼 수 있습니다.",
            ["DetectiveQuestionId"] = 1002,
            ["DialogueId"] = 10031402,
            ["GUID"] = "191CD0E4",
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100314/191CD0E4",
            },
        [10031501] = {
            ["Camera"] = "-300.109375,-328.852295,9.648438,0.000113,8.397396,46.788681,30.0,100000.0,false,Manual,3.0-300.109375,-328.852295,9.648438,0.000113,8.397396,46.788681,30.0,100000.0,false,Manual,22.0",
            ["Content"] = "没错，你也看出来了。它是往西南方向逃的。",
            ["ContentKR"] = "그래요, 당신도 알아채셨군요. 놈은 남서 방향으로 도망쳤습니다.",
            ["DetectiveQuestionId"] = 1004,
            ["DialogueId"] = 10031501,
            ["FinalCamera"] = "-300.109375,-328.852295,9.648438,0.000112,13.797432,46.589191,30.0,100000.0,false,Manual,22.0",
            ["GUID"] = "191CE122",
            ["LookAt"] = {
