                [2] = "100001:n(100304)",
                [3] = "200002:n(100304)",
                [4] = "100304:n(100001)",
                },
            ["NextDialogue"] = 10031502,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Explain01_Start",
                },
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/story/1003/100315/191CE122",
            },
        [10031502] = {
            ["Camera"] = "-196.082031,-87.382202,123.586182,0.000121,4.399837,29.404526,35.000011,100000.0,false,Manual,22.0",
            ["Content"] = "这不是都查到了吗，那卫戍部队怎么不直接去那边搜？",
            ["ContentKR"] = "다 알아냈잖아요? 그럼 방위대는 왜 직접 그쪽으로 수색하지 않는 거죠?",
            ["DetectiveQuestionId"] = 1004,
            ["DialogueId"] = 10031502,
            ["FacialId"] = {
                [1] = "200021:Think01",
                },
            ["GUID"] = "191CE14C",
            ["LookAt"] = {
                [1] = "100304:n(200021)",
                },
            ["NextDialogue"] = 10031503,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Think_Start",
                [2] = "100304:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100315/191CE14C",
            },
        [10031503] = {
            ["Camera"] = "210.840332,-20.857056,160.915527,0.000128,-7.400673,172.395859,35.000011,328.483368,false,Manual,3.0",
            ["Content"] = "人手不够，情报也不够。",
            ["ContentKR"] = "사람이 부족합니다, 단서도 부족하구요.",
            ["DetectiveQuestionId"] = 1004,
            ["DialogueId"] = 10031503,
            ["FacialId"] = {
                [1] = "200021:None",
                [2] = "100304:Sad01",
                },
            ["GUID"] = "191CE176",
            ["NextDialogue"] = 10031504,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100315/191CE176",
            },
        [10031504] = {
            ["Content"] = "西南方向那些工厂、住宅和学校我们也在逐步盘查，但范围太大了，现在还没有多少进展。",
            ["ContentKR"] = "남서쪽에 있는 공장, 주택과 학교에 대한 수색을 점진적으로 진행하고 있지만, 범위가 너무 넓기 때문에 아직 결정적인 진전은 없습니다.",
            ["DetectiveQuestionId"] = 1004,
            ["DialogueId"] = 10031504,
            ["GUID"] = "191CE1A0",
            ["NextDialogue"] = 10031505,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "200021:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100315/191CE1A0",
            },
        [10031505] = {
            ["Camera"] = "53.891113,3.93689,137.345459,0.00013,-1.601071,-174.00856,35.000011,103.373474,DoNotOverride,22",
            ["Content"] = "说来惭愧，这案子只有我和我的几个下属在调查……其中一个下属折在了它手上，就在11月25日的那一批遇害者里。",
            ["ContentKR"] = "부끄럽지만 이 사건을 조사하고 있는 사람은 저와 저의 부하 몇 명뿐입니다... 저의 부하 중 한 명은 이미 놈에게 당했습니다, 11월 25일의 피해자 중 한 명이죠.",
            ["DetectiveQuestionId"] = 1004,
            ["DialogueId"] = 10031505,
            ["FinalCamera"] = "16.574219,0.020508,136.559082,0.00013,-1.201041,-174.00856,35.000011,103.373474,DoNotOverride,22",
            ["GUID"] = "191CE1CA",
            ["LookAt"] = {
                [1] = "100304:n(100304)",
                },
            ["NextDialogue"] = 10031506,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Sigh_Start",
                },
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/story/1003/100315/191CE1CA",
            },
        [10031506] = {
            ["Content"] = "我们发现他的时候，他浑身上下的内脏都被踩碎了，就像被擀面杖碾过去的面团。",
            ["ContentKR"] = "우리가 그를 발견했을 때, 그는 이미 밀대에 밀린 반죽처럼 온몸의 내장이 짓밟혀 뭉개져 있었습니다.",
            ["DetectiveQuestionId"] = 1004,
            ["DialogueId"] = 10031506,
            ["GUID"] = "191CE1F4",
            ["NextDialogue"] = 10031507,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Sigh_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100315/191CE1F4",
            },
        [10031507] = {
            ["Camera"] = "-192.28125,-79.032227,113.535645,0.000153,6.002226,26.208307,35.000008,100000.0,false,Manual,22.0",
            ["Content"] = "……你节哀。",
            ["ContentKR"] = "...너무 슬퍼하지 마세요.",
            ["DetectiveQuestionId"] = 1004,
            ["DialogueId"] = 10031507,
            ["FacialId"] = {
                [1] = "200021:Sad01",
                },
            ["GUID"] = "191CE21E",
            ["NextDialogue"] = 10031508,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100315/191CE21E",
            },
        [10031508] = {
            ["Camera"] = "25.955078,-88.894897,153.555908,0.000082,-7.000821,146.786774,35.000011,100000.0,false,Manual,22.0",
            ["Content"] = "抓到凶手，才是对所有人最好的交代。但……我们还没能找到那怪物。",
            ["ContentKR"] = "범인을 잡는 것만이 모두에게 돌려줄 수 있는 답입니다. 하지만... 우린 아직 그 괴물을 찾지 못했습니다.",
            ["DetectiveQuestionId"] = 1004,
            ["DialogueId"] = 10031508,
            ["FacialId"] = {
                [1] = "100304:Unhappy01",
                },
            ["GUID"] = "191CE248",
            ["NextDialogue"] = 10031509,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100315/191CE248",
            },
        [10031509] = {
            ["Content"] = "我几次向上级请求支援，但申请都被驳回了——呃，确切来说不是驳回，而是我必须调查出凶手的确切藏身地，才能得到支援。",
            ["ContentKR"] = "상부에 여러 차례 지원을 요청해 봤지만 전부 거부당했습니다. 정확히 말씀드리면 거부당한 건 아니지만, 지원을 받으려면 범인의 정확한 은신처를 찾아야 했습니다.",
            ["DetectiveQuestionId"] = 1004,
            ["DialogueId"] = 10031509,
            ["GUID"] = "191CE272",
            ["NextDialogue"] = 10031510,
            ["Scripts"] = "PlayAnimation{_delay{3},ActorId{100304},AnimationId{\"Explain02_End\"},Duration{2}}",
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100315/191CE272",
            },
        [10031510] = {
            ["Camera"] = "-75.790039,-151.490479,103.759521,0.000096,7.797897,37.589153,35.000015,320.964508,false,Manual,3.0",
            ["Content"] = "我看怕不是案发地点刚好是卡戎聚居区，反正怪物也跑不到内城去，所以你上级根本懒得管？",
            ["ContentKR"] = "어차피 사건은 카론 거주 구역에서 일어나니까, 괴물이 내성에 올 일은 없다는 거죠. 그쪽 윗선도 그래서 손 놓고 있는 거 아닌가요?",
            ["DetectiveQuestionId"] = 1004,
            ["DialogueId"] = 10031510,
            ["FacialId"] = {
                [1] = "200021:Angry01",
                },
            ["GUID"] = "191CE29C",
            ["LookAt"] = {
                [1] = "100001:n(200021)",
                },
            ["NextDialogue"] = 10031511,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100315/191CE29C",
            },
        [10031511] = {
            ["Camera"] = "234.138672,-54.546997,140.426514,0.000134,-4.200279,171.592026,35.0,328.483368,false,Manual,22.0",
            ["Content"] = "我不敢妄自揣测。",
            ["ContentKR"] = "감히 함부로 추측할 순 없습니다.",
            ["DetectiveQuestionId"] = 1004,
            ["DialogueId"] = 10031511,
            ["FacialId"] = {
                [1] = "100304:Sad02",
                },
            ["GUID"] = "191CE2C6",
            ["LookAt"] = {
                [1] = "100001:n(100304)",
                },
            ["NextDialogue"] = 10031512,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100315/191CE2C6",
            },
        [10031512] = {
            ["Camera"] = "-75.790039,-151.490479,103.759521,0.000096,7.797897,37.589153,35.000015,320.964508,false,Manual,3.0",
            ["Content"] = "呵。",
            ["ContentKR"] = "허.",
            ["DetectiveQuestionId"] = 1004,
            ["DialogueId"] = 10031512,
            ["GUID"] = "191CE2F0",
            ["NextDialogue"] = 10031513,
            ["Scripts"] = "PlayAnimation{_delay{2},ActorId{200021},AnimationId{\"DisagreeHead\"},Duration{2}}",
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100315/191CE2F0",
            },
        [10031513] = {
            ["Camera"] = "-173.730469,-12.869507,127.995117,0.000144,-0.600647,-13.806776,35.000015,234.613907,false,Manual,3.0",
            ["Content"] = "那我们动作再快些吧，帮长官尽快破案。",
            ["ContentKR"] = "그럼 좀 더 서두르자. 사건이 하루빨리 해결될 수 있도록 도와야지.",
            ["DetectiveQuestionId"] = 1004,
            ["DialogueId"] = 10031513,
            ["GUID"] = "191CE31A",
            ["LookAt"] = {
                [1] = "100304:n(100001)",
                },
            ["NextDialogue"] = 10031514,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100315/191CE31A",
            },
        [10031514] = {
            ["Camera"] = "129.509766,-215.724609,129.291016,0.000136,-1.800014,129.604965,35.000011,100000.0,false,Manual,22.0",
            ["Content"] = "万分感谢！",
            ["ContentKR"] = "정말 감사드립니다!",
            ["DetectiveQuestionId"] = 1004,
            ["DialogueId"] = 10031514,
            ["FacialId"] = {
                [1] = "100304:None",
                },
            ["GUID"] = "191CE344",
            ["LookAt"] = {
                [1] = "100304:n(100001)",
                },
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100315/191CE344",
            },
        [10031601] = {
            ["Content"] = "这是……蓝色的雪？",
            ["ContentKR"] = "이건... 눈이 파란색이네요?",
            ["DetectiveQuestionId"] = 1004,
            ["DialogueId"] = 10031601,
            ["DialoguePanelType"] = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter_MoonWaterOnSnow.T_Guide_Chapter_MoonWaterOnSnow'}",
            ["GUID"] = "191CF18A",
            ["NextDialogue"] = 10031602,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100316/191CF18A",
            },
        [10031602] = {
            ["Content"] = "我看过了，这是几滴<H>月髓液</>，它滴在雪里会像花一样晕开。",
            ["ContentKR"] = "네, 저도 봤습니다, <H>액체 폭시코르</>입니다. 눈에 떨어지면 꽃처럼 피어나가죠.",
            ["DetectiveQuestionId"] = 1004,
            ["DialogueId"] = 10031602,
            ["GUID"] = "191CF1B4",
            ["NextDialogue"] = 10031603,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100316/191CF1B4",
            },
        [10031603] = {
            ["Content"] = "很漂亮，不是吗？每次看到这种蓝色的“小花”，就感觉一天的疲惫都消失了。",
            ["ContentKR"] = "정말 예쁘지 않습니까? 매번 이렇게 파란 '꽃'을 보게 되면 하루의 피로가 전부 씻겨나가는 것 같습니다.",
            ["DetectiveQuestionId"] = 1004,
            ["DialogueId"] = 10031603,
            ["GUID"] = "191CF1DE",
            ["NextDialogue"] = 10031604,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100316/191CF1DE",
            },
        [10031604] = {
            ["Content"] = "看这颜色，纯度还蛮高的啊。有月髓液泄漏了？",
            ["ContentKR"] = "색깔을 보니 순도가 꽤 높은 것 같네요. 액체 폭시코르 누출인 걸까요?",
            ["DetectiveQuestionId"] = 1004,
            ["DialogueId"] = 10031604,
            ["GUID"] = "191CF208",
            ["NextDialogue"] = 10031605,
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1003/100316/191CF208",
            },
        [10031605] = {
            ["Content"] = "嗯……的确有可能。不过保险起见，关于月髓液这件事，我需要跟{nickname}确认一下。",
            ["ContentKR"] = "음... 그럴 수도 있겠네요. 하지만 액체 폭시코르에 관한 일은 {nickname} 씨와 확인해 볼 것이 있어요.",
            ["DetectiveQuestionId"] = 1004,
            ["DialogueId"] = 10031605,
            ["GUID"] = "191CF232",
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100316/191CF232",
            },
        [10031701] = {
            ["Camera"] = "-606.177734,-381.434937,-17.229248,-0.001038,12.606322,29.999029,35.000015,1068.077393,false,Manual,1.2",
            ["Content"] = "月髓液啊……保险起见，我有个问题。",
            ["ContentKR"] = "액체 폭시코르군요... 한가지 확인해 볼 게 있습니다.",
            ["DetectiveQuestionId"] = 1004,
            ["DialogueId"] = 10031701,
            ["FacialId"] = {
                [1] = "100304:Think01",
                },
            ["FinalCamera"] = "-606.177734,-381.434937,-17.229248,-0.001038,10.206399,27.999102,35.000015,1068.077393,false,Manual,1.2",
            ["GUID"] = "191D01F2",
            ["LookAt"] = {
                [1] = "200021:n(100304)",
                [2] = "100001:n(100304)",
                [3] = "200002:n(100304)",
                [4] = "100304:n(100001)",
                },
            ["NextDialogue"] = 10031702,
            ["SpeakNpcId"] = 100304,
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1003/100317/191D01F2",
            },
        [10031702] = {
            ["Camera"] = "89.222656,-173.515381,134.491943,0.000058,-2.800077,128.408691,35.000008,1068.077393,false,DoNotOverride,1.2",
            ["Content"] = "你在遭遇凶手时，有没有闻到一股刺鼻的气味，大概像是……80%的油漆混上20%面包发霉的味道？抱歉，我可能不太擅长比喻……",
            ["ContentKR"] = "범인을 만났을 때 코를 찌르는 냄새가 났습니까? 마치... 페인트 냄새 80%에 곰팡이 낀 빵 냄새 20%가 섞인 냄새 말입니다. 죄송합니다, 제가 비유를 잘 못해서...",
            ["DetectiveQuestionId"] = 1004,
            ["DialogueId"] = 10031702,
            ["FacialId"] = {
                [1] = "100304:Doubt01",
                },
            ["FinalCamera"] = "85.961914,-176.022827,134.491943,0.000058,-2.800077,125.808693,35.000008,1068.077393,false,DoNotOverride,1.2",
            ["GUID"] = "191D021C",
