                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100318/191D12D8",
            },
        [10031805] = {
            ["Camera"] = "-73.910156,65.542358,74.60791,0.000098,0.799842,23.224178,35.000011,100000.0,false,DoNotOverride,22",
            ["Content"] = "难怪之前没见过！黎瑟长官给人的感觉和其他士兵不太一样呢。",
            ["ContentKR"] = "어쩐지 낯선 얼굴이더라고! 리듬 장교는 다른 병사들이랑 좀 다른 것 같아.",
            ["DialogueId"] = 10031805,
            ["FacialId"] = {
