            ["Scripts"] = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"-127.73233,235.162033,163.292969,0.00052,-10.603151,-102.705711,35.0,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-121.892624,233.538239,158.339844,0.000529,-9.402985,-103.307755,35.000008,100000.0,false,DoNotOverride,22.0\"},duration{5}}}",
            ["SpeakNpcId"] = 100313,
            ["TalkActionId"] = {
                [1] = "100313:Agree",
