        [10032309] = {
            ["Camera"] = "169.253906,74.701294,123.164062,0.000129,2.59791,-117.5755,40.0,357.36673,false,Manual,3.974401",
            ["Content"] = "真不用吗，你看起来像是刚从棺材里爬出来一样。",
            ["ContentKR"] = "정말 괜찮아요? 방금 관 속에서 기어 나온 것처럼 안색이 안 좋아요.",
            ["DialogueId"] = 10032309,
