            ["NextDialogue"] = 10032310,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Talk02_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100323/191D65B2",
            },
        [10032310] = {
            ["Camera"] = "12.228516,34.297607,98.183594,0.0001,13.597519,-19.587948,35.000011,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "我，我好得很！大家这一个多月都这么过来的。我要抓紧时间，抓紧时间……",
            ["ContentKR"] = "전, 정말 괜찮습니다! 다들 한 달 동안이나 이렇게 버틴걸요. 시간이 아까워요, 시간이...",
