        [10032314] = {
            ["Camera"] = "-320.859375,1100.031616,28.5,-0.000032,9.262918,-73.549782,35.000011,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "其实就是大家戴上面具，换上奇奇怪怪的装扮，抛下身份与种族……大家一起围聚在大剧院里，一边看庆典的表演，一边彻夜跳舞。",
            ["ContentKR"] = "사실 그냥 사람들이 가면 쓰고 이상한 분장 하고 신분과 종족을 전부 내려놓고... 극장에 모여서 축제 공연을 즐기면서 밤새 춤추는 거야.",
            ["DialogueId"] = 10032314,
            ["FacialId"] = {
                [1] = "200021:Smile01",
                },
            ["FinalCamera"] = "-320.859375,1100.031616,28.5,-0.000031,5.462908,-73.948982,35.000011,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "191D6684",
