            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:DisagreeHead",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100325/191D88F8",
            },
        [10032526] = {
            ["Content"] = "渔夫。",
            ["ContentKR"] = "어부일 거예요.",
            ["DialogueId"] = 10032526,
            ["GUID"] = "191D8922",
            ["ImprPlusId"] = 1008,
            ["NextDialogue"] = 10032527,
            },
        [10032527] = {
            ["Camera"] = "-52.859375,-596.512695,69.789795,0.000565,3.798207,76.587906,45.000011,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "嗯，我也赞同。",
            ["ContentKR"] = "네, 저도 동의합니다.",
            ["DialogueId"] = 10032527,
            ["FacialId"] = {
                [1] = "100304:Confident01",
