            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100325/191D894C",
            },
        [10032528] = {
            ["Content"] = "大军团长。",
            ["ContentKR"] = "군단장일 거예요.",
            ["DialogueId"] = 10032528,
            ["GUID"] = "191D8976",
            ["ImprPlusId"] = 1010,
            ["NextDialogue"] = 10032529,
            },
        [10032529] = {
            ["Camera"] = "144.700195,198.821289,123.930664,0.000542,0.797261,-121.204803,45.000011,100000.0,false,DoNotOverride,22.0",
            ["CameraBlendCurve"] = "easeInQuad",
            ["Content"] = "……见鬼，卡米拉不是说这家伙已经退烧了吗？",
            ["ContentKR"] = "...돌겠네, 카밀라가 이 녀석 열은 다 내렸다고 하지 않았냐?",
            ["DialogueId"] = 10032529,
            ["FacialId"] = {
                [1] = "200021:Think01",
                },
            ["FinalCamera"] = "148.501099,196.557617,123.930664,0.000542,0.797261,-122.204849,45.000011,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "191D89A0",
            ["LookAt"] = {
                [1] = "200021:n(100304)",
                [2] = "100304:n(200021)",
                },
            ["NextDialogue"] = 10032530,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Sigh_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100325/191D89A0",
            },
        [10032530] = {
            ["Camera"] = "33.316406,-37.37793,155.04126,0.000549,-10.602694,72.394211,45.000011,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "军团的名誉不容侮辱，请您不要开这种玩笑！结合鱼叉和鱼油这两条线索，我觉得嫌疑人最有可能是“渔夫”。",
            ["ContentKR"] = "군단의 명예를 함부로 모욕해서는 안 됩니다. 그런 농담은 하지 말아주십시오! 작살과 생선 기름, 이 두 단서를 결합해 봤을 때, 용의자는 '어부'일 확률이 가장 높습니다.",
            ["DialogueId"] = 10032530,
            ["FacialId"] = {
                [1] = "100304:Confident01",
                },
            ["FinalCamera"] = "50.216919,18.608398,144.636963,0.000552,-9.602693,71.39389,45.000011,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "191D89CA",
            ["NextDialogue"] = 10032531,
            ["Scripts"] = "PARA{SEQ{CameraMoveTo{_delay{1.5},TargetPosition{\"-24.407104,-565.220215,68.926025,0.000549,4.198333,79.992966,45.000011,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-13.015869,-567.29248,68.926025,0.00055,4.198333,80.392738,45.000011,100000.0,false,DoNotOverride,22.0\"},duration{5}}},PlayAnimation{_delay{4},ActorId{100304},AnimationId{\"Angry01_End\"},Duration{2}}}",
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
