            ["VoiceName"] = "voice/$Locale$/story/1003/100327/191DA62C",
            },
        [10032703] = {
            ["Content"] = "……看来和他无关。",
            ["ContentKR"] = "...이 사람과는 상관없는 것 같아.",
            ["DialogueId"] = 10032703,
            ["GUID"] = "191DA656",
            ["ImprPlusId"] = 1008,
            ["NextDialogue"] = 10032704,
            },
        [10032704] = {
            ["Camera"] = "46.723465,1252.376953,414.33252,0.000076,-5.598597,-104.804741,35.000008,100000.0,false,Manual,22.0",
            ["Content"] = "唉……你先冷静点，回答我们的问题。",
            ["ContentKR"] = "휴... 진정하고 우리가 묻는 물음에 대답해.",
            ["DialogueId"] = 10032704,
            ["FinalCamera"] = "46.723465,1252.376953,410.037598,0.000077,-5.198607,-104.804794,35.000008,100000.0,false,Manual,22.0",
            ["GUID"] = "191DA680",
            ["NextDialogue"] = 10032707,
            ["Scripts"] = "PlayAnimation{_delay{3},ActorId{200021},AnimationId{\"Talk01_End\"},Duration{2}}",
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Talk01_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1003/100327/191DA680",
            },
        [10032705] = {
            ["Content"] = "这就要看你的表现了，长官的子弹可没多少耐心。",
            ["ContentKR"] = "하는 거 봐서. 장교님의 총은 인내심이 별로 없으시거든.",
            ["DialogueId"] = 10032705,
            ["GUID"] = "191DA6AA",
            ["ImprPlusId"] = 1006,
            ["NextDialogue"] = 10032706,
            },
        [10032706] = {
            ["Camera"] = "17.473167,996.777344,407.513184,0.000079,-1.398672,95.794754,36.000004,100000.0,false,Manual,22.0",
            ["Content"] = "我好好表现！长官别开枪，别开枪！",
            ["ContentKR"] = "진짜 잘할게요! 제발 쏘지 말아 주십쇼, 제발요!",
            ["DialogueId"] = 10032706,
            ["FacialId"] = {
