        [10032727] = {
            ["Camera"] = "2.182457,1055.015625,378.21875,0.000225,6.601323,-88.042694,15.0,44.406654,false,Manual,2.0",
            ["Content"] = "快说！把你知道的全告诉我，一句也不要遗漏！",
            ["ContentKR"] = "빨리 말하세요! 알고 있는 걸 전부 다 말하세요, 한 마디도 빠짐없이!",
            ["DialogueId"] = 10032727,
            ["FacialId"] = {
                [1] = "100304:Unhappy01",
                },
            ["FinalCamera"] = "2.247303,1052.630859,378.50293,0.000228,6.801318,-88.44265,15.0,44.406654,false,Manual,2.0",
            ["GUID"] = "191DAA46",
            ["NextDialogue"] = 10032728,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Angry01_Start",
                [2] = "\
100314:Talk01_End",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1003/100327/191DAA46",
            },
        [10032728] = {
            ["Camera"] = "35.5327,1047.580078,426.085449,0.000162,-13.398644,112.155922,25.0,100000.0,false,Manual,22.0",
            ["Content"] = "你们、你们得先答应……你们要保证我的安全！我怕万一说出来，那该死的怪物就会把我、把我……",
            ["ContentKR"] = "먼, 먼저 약속해요... 제 안전을 책임져 주겠다고요! 혹시라도 말하면 그 빌어먹을 괴물이 저를, 저를...",
            ["DialogueId"] = 10032728,
            ["FinalCamera"] = "30.844559,1060.518555,427.949219,0.000161,-14.798738,110.955978,25.000002,100000.0,false,Manual,22.0",
            ["GUID"] = "191DAA70",
            ["NextDialogue"] = 10032729,
            ["Scripts"] = "PlayAnimation{_delay{4},ActorId{100314},AnimationId{\"Explain02_Start\"},Duration{2}}",
            ["SpeakNpcId"] = 100314,
            ["TalkActionId"] = {
                [1] = "100304:Angry01_End",
                [2] = "\
100314:Disagree",
                },
            ["ToFinalCameraBlendTime"] = 12,
            ["VoiceName"] = "voice/$Locale$/story/1003/100327/191DAA70",
            },
        [10032729] = {
            ["Camera"] = "7.246655,1098.832031,376.648438,0.000195,5.001645,-96.442291,25.0,100000.0,false,Manual,22.0",
            ["Content"] = "我保证，不会让那只怪物伤害到你。",
            ["ContentKR"] = "약속드리겠습니다, 그 괴물로부터 당신을 지켜드리겠다고.",
            ["DialogueId"] = 10032729,
            ["FinalCamera"] = "6.774265,1094.647461,377.016602,0.000194,5.201646,-96.242355,25.0,100000.0,false,Manual,22.0",
            ["GUID"] = "191DAA9A",
            ["NextDialogue"] = 10032730,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
