            ["ToFinalCameraBlendTime"] = 3,
            ["VoiceName"] = "voice/$Locale$/story/1003/100327/191DAB18",
            },
        [10032733] = {
            ["Camera"] = "2.76627,1049.458008,392.086426,0.000262,-9.596436,-92.63929,19.0,50.097149,false,Manual,3.0",
            ["Content"] = "不，秽兽没有理智，只会在街上横冲直撞。而这只怪物既然白天会藏起来，那就说明它具备反侦察意识。",
            ["ContentKR"] = "아닙니다. 필토이드는 이성이 없어요. 거리에서 날뛸 줄밖에 모르죠. 하지만, 이 괴물은 낮엔 숨어 있는 걸 보면, 정찰에 대한 경계 의식을 가지고 있다는 걸 설명합니다.",
            ["DialogueId"] = 10032733,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["FinalCamera"] = "2.76627,1049.458008,392.086426,0.000262,-9.596436,-92.63929,20.0,50.097149,false,Manual,3.0",
