            },
        [10032822] = {
            ["Camera"] = "120.826347,-1.616959,114.983398,0.007418,8.980496,-81.996254,35.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "啊……",
            ["ContentKR"] = "아... ",
            ["DialogueId"] = 10032822,
            ["FacialId"] = {
                [1] = "100304:Shock01",
                },
            ["FinalCamera"] = "118.27652,16.516449,112.0896,0.007418,8.980496,-81.996254,35.0,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "191DB9DC",
            ["NextDialogue"] = 10032823,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100328/191DB9DC",
            },
        [10032823] = {
            ["Camera"] = "312.308807,-216.968994,83.050049,0.007329,7.778444,126.202782,35.000008,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "因为夜航者小队会和你一起去，不会让你一个人逞英雄立功的。对吧，队长？",
            ["ContentKR"] = "왜냐하면 녹토 보이저도 당신과 함께 갈 거예요. 혼자 영웅이 되는 걸 허락하지 않을 거니까요. 그렇지 대장?",
            ["DialogueId"] = 10032823,
            ["FacialId"] = {
                [1] = "200021:Happy01",
                },
            ["FinalCamera"] = "312.308807,-216.968994,83.050049,0.007329,5.97843,125.203247,35.000008,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "191DBA06",
            ["LookAt"] = {
                [1] = "100001:n(200021)",
                [2] = "200021:n(100001)",
                },
            ["NextOptions"] = {
                [1] = 10032824,
                [2] = 10032825,
                },
            ["Scripts"] = "PARA{SEQ{CameraMoveTo{_delay{5},TargetPosition{\"18.183481,-25.84479,181.624756,0.007328,-16.821007,41.593891,35.000008,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"20.124172,-27.936852,181.624756,0.007327,-16.821007,43.193699,35.000008,100000.0,false,DoNotOverride,22.0\"},duration{5}}},PlayAnimation{_delay{4},ActorId{200021},AnimationId{\"Confident_Start\"},Duration{2}}}",
            ["SpeakNpcId"] = 200021,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100328/191DBA06",
            },
        [10032824] = {
            ["Content"] = "嗯，就是这样。",
            ["ContentKR"] = "응, 맞아.",
            ["DialogueId"] = 10032824,
            ["GUID"] = "191DBA30",
            ["NextDialogue"] = 10032826,
            },
        [10032825] = {
            ["Content"] = "那怪物打人疼死了，我得亲自报仇才行。",
            ["ContentKR"] = "그 괴물 녀석에게 맞은 게 너무 아파. 직접 복수해야겠어.",
            ["DialogueId"] = 10032825,
            ["GUID"] = "191DBA5A",
            ["NextDialogue"] = 10032826,
            },
        [10032826] = {
            ["Camera"] = "73.926605,-238.322037,143.751465,0.00736,-3.820944,66.994003,35.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "天快黑了，黎瑟长官，你也不想磨磨蹭蹭的，害得今天晚上又有无辜的人被袭击吧？",
            ["ContentKR"] = "날이 저물고 있어요, 리듬 장교님. 설마 꾸물거리다가 오늘 밤 또 죄 없는 사람들이 공격당하게 만들고 싶으신 건 아니겠죠?",
            ["DialogueId"] = 10032826,
            ["FinalCamera"] = "65.447815,-234.789932,143.750977,0.007359,-3.820944,63.794052,35.0,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "191DBA84",
            ["LookAt"] = {
                [1] = "100001:n(100304)",
                },
            ["NextDialogue"] = 10032827,
            ["Scripts"] = "LookAt{_delay{2},LookAtDescription{\"200002:n(100304)\"}}",
            ["SpeakNpcId"] = 100001,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100328/191DBA84",
            },
        [10032827] = {
            ["Camera"] = "92.946442,268.478546,205.385986,0.007381,-16.020536,-85.002853,35.000008,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "……我明白你们的意思了。那我们……出发吧。",
            ["ContentKR"] = "...여러분의 뜻은 잘 알겠습니다. 그럼... 출발합시다.",
            ["DialogueId"] = 10032827,
            ["FacialId"] = {
                [1] = "100304:Confident01",
                },
            ["FinalCamera"] = "100.467682,269.136414,205.385742,0.007382,-16.020521,-86.802406,35.000008,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "191DBAAE",
            ["LookAt"] = {
                [1] = "200021:n(100304)",
                [2] = "200002:n(100304)",
                },
            ["NextDialogue"] = 10032828,
            ["Scripts"] = "PARA{PlayAnimation{_delay{4},ActorId{100304},AnimationId{\"AgreeHead\"},Duration{2}},PlayAnimation{_delay{2},ActorId{200021},AnimationId{\"Confident_End\"},Duration{2}}}",
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Explain02_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100328/191DBAAE",
            },
        [10032828] = {
            ["Camera"] = "112.471596,-154.705948,142.71875,0.007393,-21.019278,64.592957,35.000008,210.83786,false,Manual,6.454089",
            ["Content"] = "那个，那个……你们两个就没人好奇黎瑟长官的第三件事到底是什么吗？",
            ["ContentKR"] = "저기, 저기... 너희 둘은 리듬 장교님의 세 번째 부탁이 뭔지 궁금하지 않아?",
            ["DialogueId"] = 10032828,
            ["FacialId"] = {
                [1] = "200002:Happy01",
                },
            ["FinalCamera"] = "112.471596,-154.705948,142.71875,0.007391,-17.819143,64.792992,35.000008,210.83786,false,Manual,6.454089",
            ["GUID"] = "191DBAD8",
            ["LookAt"] = {
                [1] = "200002:n(100304)",
                },
            ["NextDialogue"] = 10032829,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100328/191DBAD8",
            },
        [10032829] = {
            ["Camera"] = "181.988678,85.651779,83.525391,0.007393,10.776809,-102.371201,30.0,210.83786,false,Manual,6.454089",
            ["Content"] = "哦，我原本是打算把秘密基地的钥匙给你们。我所有积蓄都放在那儿，如果我回不来，你们就可以自己拿报酬。",
            ["ContentKR"] = "아, 원래는 비밀 아지트의 열쇠를 당신들에게 드리려 했습니다. 제 모든 재산이 거기 있거든요. 만약 제가 돌아오지 못한다면, 직접 가서 보수를 가져가시라고요.",
            ["DialogueId"] = 10032829,
            ["FacialId"] = {
                [1] = "100304:None",
                },
            ["FinalCamera"] = "181.988678,85.651779,88.937988,0.007396,10.776809,-102.371193,30.0,210.83786,false,Manual,6.454089",
            ["GUID"] = "191DBB02",
            ["LookAt"] = {
                [1] = "100304:n(200002)",
                },
            ["NextDialogue"] = 10032830,
            ["Scripts"] = "PARA{SEQ{CameraMoveTo{_delay{5},TargetPosition{\"218.8479,-220.312103,76.052246,0.007326,9.376709,110.837814,30.0,210.83786,false,Manual,6.454089\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"223.453308,-218.817688,76.05249,0.007326,9.376709,113.638161,30.0,210.83786,false,Manual,6.454089\"},duration{5}}},PlayAnimation{_delay{6},ActorId{100304},AnimationId{\"ExplainTwo_End\"},Duration{2}}}",
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:ExplainTwo_Start",
                [2] = "200002:Think_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100328/191DBB02",
            },
        [10032830] = {
            ["Camera"] = "148.493927,27.434708,144.814453,0.00731,-6.81881,-93.240387,30.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "不过既然{nickname}那样说了，我相信以我们第一次见面时你们的实力……我们一定能平安回来的。",
            ["ContentKR"] = "그런데 {nickname} 씨도 그렇게 얘기하시니까, 처음에 당신들을 만났을 때의 실력을 믿겠습니다... 우린 반드시 무사히 돌아올 수 있을 겁니다.",
            ["DialogueId"] = 10032830,
            ["FacialId"] = {
                [1] = "100304:Confident01",
                },
            ["FinalCamera"] = "149.026001,36.830658,145.938721,0.00731,-6.418793,-93.240837,30.0,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "191DBB2C",
            ["LookAt"] = {
                [1] = "100304:n(100001)",
                },
            ["Scripts"] = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"-764.08551,466.744812,142.1875,0.007305,-1.81905,-29.224564,35.0,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-775.528442,446.289978,142.189941,0.007305,-1.81905,-27.42462,35.0,100000.0,false,DoNotOverride,22.0\"},duration{10}}}",
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:DisagreeHead",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100328/191DBB2C",
            },
        [10032901] = {
            ["Content"] = "走这边。",
            ["ContentKR"] = "이쪽으로.",
            ["DialogueId"] = 10032901,
            ["GUID"] = "191DC6D2",
            ["NextDialogue"] = 10032902,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100329/191DC6D2",
            },
        [10032902] = {
            ["Content"] = "黎瑟长官对这里似乎很熟悉？",
            ["ContentKR"] = "리듬 장교님은 이곳에 익숙하신가 보네요?",
            ["DialogueId"] = 10032902,
            ["GUID"] = "191DC6FC",
            ["NextDialogue"] = 10032903,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100329/191DC6FC",
            },
        [10032903] = {
            ["Content"] = "这些年帝国很注重各城镇地下设施的建设，卫戍部队也要出力维护。",
            ["ContentKR"] = "제국은 최근 몇 년 동안 각 도시의 지하 시설 건설에 큰 주의를 기울이고 있습니다. 따라서 방위대도 유지보수를 책임져야죠.",
            ["DialogueId"] = 10032903,
            ["GUID"] = "191DC726",
            ["NextDialogue"] = 10032904,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100329/191DC726",
            },
        [10032904] = {
            ["Content"] = "刚加入卫戍部队时，我每天都被安排打扫这里。",
            ["ContentKR"] = "처음 방위대에 들어왔을 땐, 매일 이곳의 청소를 배정받았습니다.",
            ["DialogueId"] = 10032904,
            ["GUID"] = "191DC750",
            ["NextDialogue"] = 10032905,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100329/191DC750",
            },
        [10032905] = {
            ["Content"] = "天天清理下水道……卡戎就算加入军团也还是会被欺负吗？",
            ["ContentKR"] = "매일 하수도 청소라니... 카론은 군단에 들어가도 괴롭힘을 당하는 건가요?",
            ["DialogueId"] = 10032905,
            ["GUID"] = "191DC77A",
            ["NextDialogue"] = 10032906,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100329/191DC77A",
            },
        [10032906] = {
            ["Content"] = "偏见是根深蒂固的，但在军团至少我们还可以靠功绩来赢得尊重。",
            ["ContentKR"] = "편견의 뿌리는 깊습니다. 하지만 적어도 군단에선 공적을 쌓는 것을 통해 존경을 받을 수 있습니다.",
            ["DialogueId"] = 10032906,
            ["GUID"] = "191DC7A4",
            ["NextDialogue"] = 10032907,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100329/191DC7A4",
            },
        [10032907] = {
            ["Content"] = "这也是身为“恶魔的孩子”，偿还自己罪业的方式之一。",
            ["ContentKR"] = "이 또한 '악마의 아이'로서 속죄할 수 있는 방법 중 하나죠.",
            ["DialogueId"] = 10032907,
            ["GUID"] = "191DC7CE",
            ["NextDialogue"] = 10032908,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100329/191DC7CE",
            },
        [10032908] = {
            ["Content"] = "等等……你们有没有听到什么声音？",
            ["ContentKR"] = "잠깐... 무슨 소리 못 들었어?",
            ["DialogueId"] = 10032908,
            ["GUID"] = "191DC7F8",
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1003/100329/191DC7F8",
            },
        [10032909] = {
            ["Content"] = "救，救救我……我……不想死……",
            ["ContentKR"] = "살, 살려줘... 난... 죽고싶지 않아...",
            ["DialogueId"] = 10032909,
            ["GUID"] = "191DC822",
            ["NextDialogue"] = 10032910,
            ["SpeakNpcId"] = 100321,
            ["VoiceName"] = "voice/$Locale$/story/1003/100329/191DC822",
            },
        [10032910] = {
            ["Content"] = "……呼救声！我马上过来！",
            ["ContentKR"] = "...구조 요청 소리! 바로 갈게요!",
            ["DialogueId"] = 10032910,
            ["GUID"] = "191DC84C",
            ["NextDialogue"] = 10032911,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100329/191DC84C",
            },
        [10032911] = {
            ["Content"] = "喂，你都不确认一下是不是陷阱吗……啧，我们也快跟上去吧。",
            ["ContentKR"] = "저기요, 함정인지 아닌지 확인도 안 해보고... 쩝, 우리도 따라가자.",
            ["DialogueId"] = 10032911,
            ["GUID"] = "191DC876",
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1003/100329/191DC876",
            },
        [10033001] = {
            ["Camera"] = "624.507812,337.115234,453.645508,0.000164,-26.398672,-154.983353,25.0,100000.0,false,Manual,22.0",
            ["Content"] = "这是什么情况？",
            ["ContentKR"] = "이게 무슨 상황이야?",
            ["DialogueId"] = 10033001,
            ["FinalCamera"] = "623.152344,340.018555,453.645508,0.000164,-26.39868,-154.983414,25.0,100000.0,false,Manual,22.0",
