        [10033006] = {
            ["Camera"] = "-295.976562,77.636719,167.921021,0.000128,-13.597185,-9.189079,20.000011,100000.0,false,Manual,22.0",
            ["Content"] = "多谢各位长官，我，我的同伴就在前面那道锁住的门后不远。",
            ["ContentKR"] = "감사합니다, 장교님들. 제, 제 동료가 바로 앞에 있는 잠긴 문 뒤에 있습니다.",
            ["DialogueId"] = 10033006,
            ["FacialId"] = {
                [1] = "100321:CM_Smile01",
                },
            ["FinalCamera"] = "-295.976562,77.636719,163.988159,0.000128,-12.797076,-9.389367,20.000011,100000.0,false,Manual,22.0",
            ["GUID"] = "191DD80C",
            ["LookAt"] = {
