                [2] = "\
100001:Talk03_End",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1003/100332/191DF8B2",
            },
        [10033206] = {
            ["Content"] = "收到。",
            ["ContentKR"] = "알겠습니다.",
            ["DialogueId"] = 10033206,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["GUID"] = "191DF8DC",
