            },
        [10033907] = {
            ["Camera"] = "-81.523438,283.592834,150.683594,0.00011,-8.204743,-37.341213,35.000023,332.760406,false,Manual,4.091501",
            ["Content"] = "说是已经脱离了危险，但……现在看起来丝毫没有要醒来的迹象。",
            ["ContentKR"] = "고비는 넘겼대, 그런데... 깨어날 기미가 전혀 안 보여.",
            ["DialogueId"] = 10033907,
            ["FinalCamera"] = "-84.269043,279.994141,150.683594,0.000113,-8.204743,-35.341167,35.000023,332.760406,false,Manual,4.091501",
