        [10033916] = {
            ["Camera"] = "526.81543,176.885864,156.60498,0.000122,-6.853343,-167.440613,35.000008,563.148376,false,Manual,1.225325",
            ["Content"] = "真是的，姐姐又在白天睡大觉——明天就要考试了！你还记得刚才我讲到哪儿了吗？",
            ["ContentKR"] = "아잇 진짜, 누난 자꾸 낮에 자더라. 내일이면 시험이야! 방금 내가 어디까지 얘기했는지 기억나?",
            ["DialogueId"] = 10033916,
            ["FinalCamera"] = "530.197266,161.683472,156.60498,0.000122,-6.85333,-167.240479,35.000008,563.148376,false,Manual,1.225325",
            ["GUID"] = "191E6D58",
