        [10033940] = {
            ["Camera"] = "148.391602,-30.790039,184.855225,0.002318,-29.476192,140.533157,50.0,91.877663,false,Manual,3.753203",
            ["Content"] = "……哨塔？",
            ["ContentKR"] = "...초소?",
            ["DialogueId"] = 10033940,
            ["FacialId"] = {
                [1] = "100304:Think01",
                },
            ["FinalCamera"] = "144.614258,-35.229736,184.855225,0.002323,-29.476179,137.532928,50.0,91.877663,false,Manual,3.753203",
            ["GUID"] = "191E7148",
            ["NextDialogue"] = 10033941,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100358:Explain01_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100339/191E7148",
            },
        [10033941] = {
            ["Camera"] = "329.514648,-197.759277,252.08667,0.002183,-22.681835,142.327667,30.000008,7420.709473,false,DoNotOverride,2.157511",
            ["Content"] = "嗯嗯——确切来说，是哨塔上那盏灯。那是整座冰湖城最高的地方！",
            ["ContentKR"] = "그래, 정확하게는 초소 위의 저 등불이야. 저곳이 아이스레이크 시티에서 제일 높은 곳이야!",
            ["DialogueId"] = 10033941,
            ["FinalCamera"] = "297.395508,-234.10498,252.08667,0.002188,-22.481806,132.727509,30.000008,7420.709473,false,DoNotOverride,2.157511",
            ["GUID"] = "191E7172",
            ["NextDialogue"] = 10033942,
            ["Scripts"] = "PlayAnimation{_delay{2},ActorId{100358},AnimationId{\"Talk01_Start\"},Duration{2}}",
            ["SpeakNpcId"] = 100358,
            ["TalkActionId"] = {
                [1] = "100358:AgreeHead",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100339/191E7172",
            },
        [10033942] = {
            ["Camera"] = "272.657227,-228.072998,65.852295,0.002184,11.115211,134.331268,30.000008,7420.709473,false,DoNotOverride,2.157511",
            ["Content"] = "我每次站在这儿往内城看，都觉得它那么高，那么远，那么亮。就像书本上写的灯塔，只能远远看着，但永远都摸不到。",
            ["ContentKR"] = "매번 여기 서서 내성을 바라보면, 너무 높고, 너무 멀고, 너무 밝다고 느껴졌어. 멀리서 바라볼 수만 있고 영원히 가까이 다가가지 못하는, 책 속에 나오는 등대처럼 말이야.",
            ["DialogueId"] = 10033942,
            ["FacialId"] = {
                [1] = "100304:Confident01",
                },
            ["FinalCamera"] = "272.657227,-228.072998,65.852295,0.002188,11.915223,137.931427,30.000008,7420.709473,false,DoNotOverride,2.157511",
            ["GUID"] = "191E719C",
            ["NextDialogue"] = 10033943,
            ["Scripts"] = "PARA{\
MoveTo{_delay{1.5},ActorId{100358},TargetPoint{\"cp2fixsimple25-26Point04\"},MoveSpeed{80},Visibility{\"Show\"}},\
SEQ{\
CameraMoveTo{_delay{4},TargetPosition{\"-154.816406,-8.20752,30.02124,0.002207,26.910547,-7.464888,25.0,7420.709473,false,DoNotOverride,2.157511\"},duration{0}},\
CameraMoveTo{_delay{0},TargetPosition{\"-150.234375,-8.808838,0.62915,0.002212,35.71027,-6.26536,25.0,7420.709473,false,DoNotOverride,2.157511\"},duration{10}}\
}\
}",
            ["SpeakNpcId"] = 100358,
            ["TalkActionId"] = {
                [1] = "100358:Talk01_End",
                },
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/story/1003/100339/191E719C",
            },
        [10033943] = {
            ["Camera"] = "111.371094,-113.845703,177.456787,0.002008,-26.280388,156.343842,30.000013,7420.709473,false,DoNotOverride,2.157511",
            ["Content"] = "但是现在，我和之前不一样了，我成“桂冠卡戎”了！之前的好多好多愿望，表演啊弹琴啊，都不再是白日做梦了！",
            ["ContentKR"] = "하지만 지금의 난 달라, 난 '계관카론'이 됐어! 과거의 수많은 소망, 공연, 연주와 같은 것들은 더 이상 꿈이 아니야! ",
            ["DialogueId"] = 10033943,
            ["FinalCamera"] = "108.759766,-119.812256,177.456787,0.002008,-26.28038,151.74408,30.000013,7420.709473,false,DoNotOverride,2.157511",
            ["GUID"] = "191E71C6",
            ["NextDialogue"] = 10033944,
            ["Scripts"] = "SEQ{CameraMoveTo{_delay{6},TargetPosition{\"-485.847656,46.956299,137.444336,0.001994,1.519833,-11.67173,30.000013,559.792786,false,Manual,2.30239\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-483.134766,59.942139,137.444336,0.001994,1.519833,-11.871832,30.000013,559.792786,false,Manual,2.30239\"},duration{10}}}",
            ["SpeakNpcId"] = 100358,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100339/191E71C6",
            },
        [10033944] = {
            ["Camera"] = "77.242188,-175.824219,156.161133,0.002098,-10.087157,100.349434,30.000013,7420.709473,false,DoNotOverride,2.157511",
            ["Content"] = "我可以到内城，爬到哨塔上面，站在那盏灯下……我觉得自己就像是冰湖城的皇帝！",
            ["ContentKR"] = "난 이제 내성에 들어가서 저 초소 위에 있는 등불 밑에 설 수 있어... 아이스레이크 시티의 황제라도 된 느낌이야!",
            ["DialogueId"] = 10033944,
            ["FinalCamera"] = "77.242188,-175.824219,156.161133,0.002093,-6.687103,100.549789,30.000013,7420.709473,false,DoNotOverride,2.157511",
            ["GUID"] = "191E71F0",
            ["NextDialogue"] = 10033945,
            ["Scripts"] = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"451.72168,-618.515869,-61.140137,0.002101,7.911216,-50.449219,30.000013,7420.709473,false,DoNotOverride,2.157511\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"451.72168,-618.515869,-61.140137,0.002098,13.311171,-41.649197,30.000013,7420.709473,false,DoNotOverride,2.157511\"},duration{8}}}",
            ["SpeakNpcId"] = 100358,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100339/191E71F0",
            },
        [10033945] = {
            ["Camera"] = "154.736328,-179.322754,105.369629,0.002146,9.71145,139.943695,30.000013,7420.709473,false,DoNotOverride,2.157511",
            ["Content"] = "“士兵们听令——全军出击！为了海伯利亚的荣耀！”",
            ["ContentKR"] = "“병사들이여, 내 명을 받들라, 전군 진격이다! 휘페르보레아의 영광을 위하여!”",
            ["DialogueId"] = 10033945,
            ["FinalCamera"] = "154.736328,-179.322754,105.369629,0.002145,13.511438,137.943466,30.000013,7420.709473,false,DoNotOverride,2.157511",
