        [10033951] = {
            ["Camera"] = "159.118164,62.682617,116.599609,0.002062,5.112949,-136.657822,30.000013,174.769302,false,Manual,3.415042",
            ["Content"] = "姐、姐姐，你怎么哭了！不用担心，不用担心，等三年期满我们就能见面啦！而且，说不定……说不定你运气好，明年就成了桂冠卡戎呢！",
            ["ContentKR"] = "누, 누나, 왜 울어! 걱정 마, 걱정하지 말라니까. 3년만 지나면 다시 만날 수 있을 거야! 게다가 운 좋으면... 내년에 계관카론이 될 수 있을지도 모르잖아!",
            ["DialogueId"] = 10033951,
            ["FacialId"] = {
                [1] = "100358:None",
                },
            ["FinalCamera"] = "161.53418,60.29541,116.599609,0.002064,5.112949,-139.257599,30.000013,174.769302,false,Manual,3.415042",
            ["GUID"] = "191E7316",
