        [10034304] = {
            ["Content"] = "好惊人的语速。",
            ["ContentKR"] = "놀라운 말 속도네요.",
            ["DialogueId"] = 10034304,
            ["GUID"] = "191EAD00",
            ["NextDialogue"] = 10034305,
            },
        [10034305] = {
            ["Camera"] = "-4.078125,106.379272,144.205078,0.000115,-19.596823,48.052696,35.0,115.848167,false,Manual,5.0",
            ["Content"] = "呜呜，长官听起来像是要把{nickname}抓走了！",
            ["ContentKR"] = "우웅, 장교님 말투가... {nickname}을(를) 잡아갈 것처럼 말하네!",
            ["DialogueId"] = 10034305,
            ["FinalCamera"] = "-4.078125,106.379272,138.203125,0.000085,-31.796755,52.451656,35.000008,203.224945,false,Manual,5.0",
