        [10034320] = {
            ["Camera"] = "-96.10498,201.29425,7.722656,0.000082,19.400864,-41.310314,47.0,313.029602,false,Manual,3.0",
            ["Content"] = "我明白你的不平。但是我已经满足了，布鲁斯能实现他的梦想，更是我们小时候根本不敢相信的。",
            ["ContentKR"] = "저는 당신이 느끼는 억울함을 이해합니다. 하지만 저는 이미 만족해요. 블루스가 그의 꿈을 이룰 수 있었다는 것만으로도, 저희가 어렸을 때는 상상조차 할 수 없었던 일이니까요.",
            ["DialogueId"] = 10034320,
            ["FacialId"] = {
                [1] = "100001:None",
                [2] = "\
200021:None",
                },
            ["FinalCamera"] = "-87.334961,189.71106,12.724609,0.000082,19.400829,-41.110359,47.0,313.029602,false,Manual,3.0",
            ["GUID"] = "191EAFA0",
            ["NextDialogue"] = 10034321,
