                [1] = "200002:n(200021)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100345/191ED1C0",
            },
        [10034529] = {
            ["Camera"] = "76.509949,95.736488,35.371094,0.000062,15.598738,-23.400145,35.000011,544.895874,false,DoNotOverride,22",
            ["Content"] = "我们也有帮不少忙呀！",
            ["ContentKR"] = "우리도 꽤 많이 도왔잖아!",
