            ["VoiceName"] = "voice/$Locale$/story/1003/100345/191ED1EA",
            },
        [10034530] = {
            ["Camera"] = "313.703003,-7.806791,124.205078,0.000106,14.197558,-47.393547,35.000015,116.556152,false,Manual,4.0",
            ["Content"] = "你是指搬弹药箱误触引爆，还是指堵管道时时撞坏水闸让大伙白忙活半天？",
            ["ContentKR"] = "탄약 상자 옮기다가 실수로 폭발시킨 거 말하는 거야? 아니면 파이프 막으려다가 밸브를 망가뜨려서 다들 반나절 동안 헛수고하게 만든 거 말하는 거야?",
            ["DialogueId"] = 10034530,
