        [10034532] = {
            ["Camera"] = "379.26709,-408.699371,228.950928,0.000039,-18.000458,96.800278,35.000011,544.895874,false,Manual,22.0",
            ["Content"] = "话说黎瑟现在在哪儿呢？平时这个时间都会在停车场准时等我们的。",
            ["ContentKR"] = "그러고 보니, 리듬은 지금 어디 있는 거지? 평소라면 이 시간엔 항상 주차장에서 우리를 기다리고 있었잖아.",
            ["DialogueId"] = 10034532,
            ["FacialId"] = {
                [1] = "200021:None",
                [2] = "200002:None",
                },
            ["GUID"] = "191ED268",
            ["LookAt"] = {
                [1] = "200021:n(100001)",
                [2] = "200002:n(100001)",
                [3] = "100001:n(200021)",
