            ["VoiceName"] = "voice/$Locale$/story/1003/100345/191ED268",
            },
        [10034533] = {
            ["Content"] = "确实，那家伙连每天等我们的位置和姿势都不带变的。",
            ["ContentKR"] = "맞아, 그 녀석, 맨날 우리를 기다리는 위치랑 자세까지도 안 바꾸잖아.",
            ["DialogueId"] = 10034533,
            ["GUID"] = "191ED292",
            ["LookAt"] = {
