            },
        [10034534] = {
            ["Camera"] = "240.401016,109.887741,127.815674,0.00013,3.595767,-46.793732,35.000011,296.605652,false,Manual,4.0",
            ["Content"] = "能让这么死板的家伙挪腾地方，怕是又出什么事了？四处找找吧。",
            ["ContentKR"] = "그렇게 고지식한 녀석이 자리를 옮길 정도면, 뭔가 또 일이 생긴 거 아닐까? 여기저기 찾아보자.",
            ["DialogueId"] = 10034534,
            ["GUID"] = "191ED2BC",
            ["LookAt"] = {
                [1] = "200021:n(100001)",
                [2] = "200002:n(200021)",
                [3] = "100001:n(200021)",
                },
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1003/100345/191ED2BC",
            },
        [10034535] = {
            ["Camera"] = "313.962891,-339.905273,217.369629,0.000059,-19.399368,135.380035,35.000008,100000.0,false,Manual,22.0",
            ["Content"] = "哇，你怎么又拿了张清单，不会军团又给你派活了吧。",
            ["ContentKR"] = "와, 그 목록 또 어디서 났어요? 설마 군단에서 또 일 시킨 거예요?",
            ["DialogueId"] = 10034535,
            ["FacialId"] = {
                [1] = "200021:Smile01",
                },
            ["FinalCamera"] = "313.962891,-339.905273,217.369629,0.000063,-13.999196,135.380676,35.000008,100000.0,false,Manual,22.0",
