        [10034540] = {
            ["Camera"] = "275.59668,-135.068359,262.251953,0.000129,-23.202957,151.422806,35.000015,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "这才对嘛，这么久了还说谢，就太见外了。",
            ["ContentKR"] = "그렇죠, 이렇게 오래됐는데 아직도 감사하다는 말은 너무 서운하잖아요.",
