        [10034705] = {
            ["Camera"] = "183.185303,-145.604492,137.870605,0.000083,-4.397877,148.777023,36.000004,436.538635,false,Manual,15.0",
            ["Content"] = "不过你们短短几天居然和军团的长官打上交道了？怎么办到的呀，教教我教教我——",
            ["ContentKR"] = "아니 그런데, 며칠 만에 군단 장교랑도 연결이 닿은 거예요? 어떻게 한 건데요? 저도 좀 알려주세요!",
            ["DialogueId"] = 10034705,
