        [10034706] = {
            ["Camera"] = "69.720703,-114.928711,91.78125,0.000193,19.60211,89.360085,38.000008,131.344574,false,Manual,15.0",
            ["Content"] = "各队注意，各队注意，速来8号下水道入口集结，重复，速来8号下水道入口集结。",
            ["ContentKR"] = "각 팀 주의, 각 팀 주의. 즉시 8번 하수도 입구로 집결하라. 반복한다, 즉시 8번 하수도 입구로 집결하라.",
