        [10034708] = {
            ["Camera"] = "2.168945,-132.580078,128.23877,0.000005,5.403356,71.540291,37.0,168.412857,false,Manual,8.0",
            ["Content"] = "嗯，看来抓捕行动进入下一阶段了……！我们也快点过去吧。",
            ["ContentKR"] = "네, 보아하니 체포 작전이 다음 단계로 들어간 것 같군요...! 우리도 서둘러 가죠!",
