        [10034709] = {
            ["Camera"] = "45.459961,48.591797,128.559082,0.000089,-0.797179,-109.845421,25.0,118.729843,false,Manual,8.0",
            ["Content"] = "咦，这就要走了吗……那过去这阵子，你们一定要再来哦，我会准备好多好玩的小东西等你们！",
            ["ContentKR"] = "어, 벌써 가시는 거예요...? 그럼 바쁜 일이 지나가면, 꼭 다시 오셔야 해요! 제가 재미있는 물건들을 많이 준비해 놓고 기다릴게요!",
            ["DialogueId"] = 10034709,
            ["FinalCamera"] = "48.275146,56.394531,128.67334,0.000089,-0.797179,-109.845421,25.0,118.729843,false,Manual,8.0",
