        [10034715] = {
            ["Content"] = "各个区域都有士兵驻守，是已经完成了封锁吗？",
            ["ContentKR"] = "구역마다 병사가 배치되어 있네요, 이미 봉쇄가 완료된 건가요?",
            ["DialogueId"] = 10034715,
            ["GUID"] = "191EF06E",
            ["NextDialogue"] = 10034716,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100347/191EF06E",
            },
        [10034716] = {
            ["Content"] = "看来是。接下来随时可能遇敌。目标的身手我们是领教过的，务必当心。",
            ["ContentKR"] = "그런 것 같군요. 이제 언제든 적과 마주칠 수 있습니다. 목표의 실력은 우리가 이미 경험했으니, 꼭 조심하세요.",
            ["DialogueId"] = 10034716,
            ["GUID"] = "191EF098",
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100347/191EF098",
            },
        [10034717] = {
            ["Content"] = "先去找克莱夫留下的标记吧。",
            ["ContentKR"] = "먼저 클레이프가 남긴 표시를 찾아보자.",
