        [10034811] = {
            ["Camera"] = "-33.097656,174.466797,70.899658,-0.00174,12.431073,39.826427,35.000011,233.370453,false,Manual,4.128408",
            ["Content"] = "下水道公爵是……什么？",
            ["ContentKR"] = "하수도 공작이... 뭐죠?",
            ["DialogueId"] = 10034811,
            ["FacialId"] = {
                [1] = "100304:Doubt01",
                },
            ["FinalCamera"] = "-35.933594,177.720703,70.899658,-0.001739,12.43106,37.626053,35.000011,233.370453,false,Manual,4.128408",
            ["GUID"] = "191F002E",
            ["LookAt"] = {
                [1] = "100304:n(200002)",
                [2] = "200002:n(100304)",
                },
            ["NextDialogue"] = 10034812,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Think_Start",
