        [10034820] = {
            ["Camera"] = "-279.149902,-145.59668,154.250244,0.000173,-5.394012,36.42305,30.0,7947.058105,false,Manual,22.0",
            ["Content"] = "啊，我想起来了！上面那个假人的造型，我以前在布鲁斯临摹的歌剧海报上看到过。",
            ["ContentKR"] = "아, 생각났어요! 위에 있는 저 마네킹의 모습, 예전에 블루스가 따라 그렸던 오페라 포스터에서 본 적이 있어요.",
            ["DialogueId"] = 10034820,
            ["FacialId"] = {
                [1] = "100304:None",
                },
            ["FinalCamera"] = "-279.149902,-145.59668,164.95874,0.000173,-5.994051,36.422974,30.0,7947.058105,false,Manual,22.0",
