            },
        [10034821] = {
            ["Camera"] = "-30.813477,46.808594,125.878662,0.000131,5.604402,63.830662,36.000004,16827.542969,false,Manual,22.0",
            ["Content"] = "嗯……这么说来，这整个房间都布置得像个舞台一样。凶手难道是一名<H>歌剧爱好者</>？",
            ["ContentKR"] = "음... 그러고 보니까, 이 방 전체가 무대처럼 꾸며져 있네요. 설마 범인은 <H>오페라 애호가</>인 걸까요?",
            ["DialogueId"] = 10034821,
            ["FacialId"] = {
                [1] = "100001:Shock01",
                },
            ["FinalCamera"] = "-18.894043,45.036133,126.219971,0.000127,5.80439,68.630951,36.000004,16827.542969,false,Manual,22.0",
            ["GUID"] = "191F01D2",
            ["LookAt"] = {
                [1] = "100001:n(100001)",
                [2] = "\
200021:n(100001)",
                },
            ["NextDialogue"] = 10034822,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:ScratchHead_Start",
                },
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1003/100348/191F01D2",
            },
        [10034822] = {
            ["Camera"] = "-2.286133,328.46582,139.172852,0.000183,-0.195316,-81.557655,32.000004,16827.542969,false,Manual,22.0",
            ["Content"] = "……不过既然军团已经找到了凶手，这条线索已经意义不大了。",
            ["ContentKR"] = "...하지만 군단이 이미 범인을 찾아냈으니, 이 단서는 이제 큰 의미가 없겠네요.",
            ["DialogueId"] = 10034822,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["FinalCamera"] = "-5.772461,327.951172,139.172852,0.000183,-0.195316,-81.957558,32.000004,16827.542969,false,Manual,22.0",
            ["GUID"] = "191F01FC",
            ["NextDialogue"] = 10034823,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100304:Confident_End",
                [2] = "\
100001:ScratchHead_End",
                [3] = "\
200021:ConfidentLR_Start",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1003/100348/191F01FC",
            },
        [10034823] = {
            ["Camera"] = "-460.376465,319.509766,156.266602,0.000142,-6.195459,-23.380085,31.654133,100000.0,false,Manual,22.0",
            ["Content"] = "的确。总不能跟凶手来段对唱，人家一看我们志同道合，就乖乖认罪吧。",
            ["ContentKR"] = "맞아. 설마 범인이 우리하고 듀엣을 부르다가, 마음이 통한다면서 순순히 투항하길 기대할 순 없겠지.",
            ["DialogueId"] = 10034823,
            ["FinalCamera"] = "-460.07373,319.378906,144.872803,0.000142,-5.395446,-23.57946,31.654133,100000.0,false,Manual,22.0",
            ["GUID"] = "191F0226",
            ["LookAt"] = {
                [1] = "100304:n(200021)",
                [2] = "\
100001:n(200021)",
                },
            ["NextDialogue"] = 10034824,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:ConfidentLRToSighR_Start",
                },
            ["ToFinalCameraBlendTime"] = 9,
            ["VoiceName"] = "voice/$Locale$/story/1003/100348/191F0226",
            },
        [10034824] = {
            ["Camera"] = "-9.942383,21.341797,132.388428,0.000254,0.805327,76.790901,33.0,16827.542969,false,Manual,22.0",
            ["Content"] = "来听听克莱夫有什么新指示吧。",
            ["ContentKR"] = "클레이프가 무슨 새로운 지시를 내릴지 들어봅시다.",
            ["DialogueId"] = 10034824,
            ["FinalCamera"] = "-9.302246,24.06543,132.428711,0.000254,0.805327,76.790901,33.0,16827.542969,false,Manual,22.0",
            ["GUID"] = "191F0250",
            ["LookAt"] = {
                [1] = "100001:n(100001)",
                },
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "200021:ConfidentLRToSighR_End",
                [2] = "\
100001:Talk02_Start",
                [3] = "\
100304:AgreeHead",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1003/100348/191F0250",
            },
        [10034825] = {
            ["Content"] = "小仆从，这里有个奇奇怪怪的机关诶！",
            ["ContentKR"] = "시종, 여기 이상하게 생긴 장치가 있어!",
            ["DialogueId"] = 10034825,
            ["GUID"] = "191F0101",
            ["NextDialogue"] = 10034826,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1003/100348/191F0101",
            },
        [10034826] = {
            ["Content"] = "小矮子先别碰，当心有诈！……嗯，还好，只是普通的升降机。",
            ["ContentKR"] = "꼬맹이, 일단 만지지 마. 함정일 수도 있어! ...음, 다행이네. 그냥 평범한 승강기야.",
            ["DialogueId"] = 10034826,
            ["GUID"] = "191F0102",
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1003/100348/191F0102",
            },
        [10034827] = {
            ["Content"] = "出现了新的路诶！简直像变魔术一样！",
            ["ContentKR"] = "새로운 길이 나타났어! 마술 같아!",
            ["DialogueId"] = 10034827,
            ["GUID"] = "191F0103",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1003/100348/191F0103",
            },
        [10034828] = {
            ["Content"] = "嘁，什么都没有嘛，我还以为会突然蹦出来啥。",
            ["ContentKR"] = "쳇, 아무것도 없잖아. 난 또 뭐라도 튀어나오는 줄 알았네.",
            ["DialogueId"] = 10034828,
            ["GUID"] = "191F0104",
            ["NextDialogue"] = 10034829,
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1003/100348/191F0104",
            },
        [10034829] = {
            ["Content"] = "呸呸呸，不许乌鸦嘴！",
            ["ContentKR"] = "퉤퉤퉤, 재수 없는 소리 하지 마!",
            ["DialogueId"] = 10034829,
            ["GUID"] = "191F0105",
            ["NextDialogue"] = 10034830,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1003/100348/191F0105",
            },
        [10034830] = {
            ["Content"] = "继续向上吧。",
            ["ContentKR"] = "계속 올라가 보자.",
            ["DialogueId"] = 10034830,
            ["GUID"] = "191F0106",
            ["NextDialogue"] = 10034832,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100348/191F0106",
            },
        [10034831] = {
            ["Content"] = "嚯，一下就亮起来了。边边角角都看得一清二楚。",
            ["ContentKR"] = "이야, 순식간에 환해졌네. 이제 구석구석 잘 보여.",
            ["DialogueId"] = 10034831,
            ["GUID"] = "191F0107",
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1003/100348/191F0107",
            },
        [10034832] = {
            ["Content"] = "不得不说，这地方布置得还挺有艺术感的，简直像个缩小版的剧院舞台。",
            ["ContentKR"] = "그건 그렇고, 꽤 예술적으로 꾸몄네. 극장 무대의 축소판이잖아.",
            ["DialogueId"] = 10034832,
            ["GUID"] = "191F0108",
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1003/100348/191F0108",
            },
        [10034833] = {
            ["Content"] = "看样子这里没有什么陷阱。回去报告黎瑟长官吧。",
            ["ContentKR"] = "여긴 함정은 없는 것 같아. 돌아가서 리듬 장교님한테 알려 주자.",
            ["DialogueId"] = 10034833,
            ["GUID"] = "191F0109",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100348/191F0109",
            },
        [10034901] = {
            ["Camera"] = "-15.305176,154.117188,133.735596,0.000155,3.200162,-93.18692,35.0,100000.0,false,Manual,22.0",
