        [10035209] = {
            ["Content"] = "很麻烦啊，保护市民与遵守命令都是你的职责。",
            ["ContentKR"] = "골치 아프겠네요, 시민을 보호하는 것도, 명령을 따르는 것도 장교님의 책임이잖아요.",
            ["DialogueId"] = 10035209,
            ["GUID"] = "191F417A",
            ["ImprPlusId"] = 1007,
            ["NextDialogue"] = 10035210,
            },
        [10035210] = {
            ["Camera"] = "-75.948898,-23.243881,162.542236,0.000282,-10.804621,24.274958,40.0,119.498253,false,Manual,8.0",
            ["Content"] = "我明白你的意思，是我做出选择的时候了……",
            ["ContentKR"] = "말씀하신 뜻은 이해합니다. 이제 제가 선택을 해야 할 때인 것 같습니다...",
            ["DialogueId"] = 10035210,
            ["FacialId"] = {
                [1] = "100304:Close",
                },
            ["FinalCamera"] = "-77.361824,-20.11338,162.542236,0.000282,-10.404604,22.675148,40.0,119.498253,false,Manual,8.0",
            ["GUID"] = "191F41A4",
            ["NextDialogue"] = 10035215,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Sigh_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1003/100352/191F41A4",
            },
        [10035211] = {
            ["Content"] = "那就做回平时的你吧。",
            ["ContentKR"] = "그럼, 평소의 당신으로 돌아가세요.",
            ["DialogueId"] = 10035211,
            ["GUID"] = "191F41CE",
            ["ImprPlusId"] = 1009,
            ["NextDialogue"] = 10035212,
            },
        [10035212] = {
            ["Camera"] = "-151.905182,-13.076996,141.362305,0.000255,-2.60461,19.078295,35.0,193.682495,false,Manual,8.0",
            ["Content"] = "那个不会放弃，为了保护市民拼尽全力的你。",
            ["ContentKR"] = "그 누구보다도 시민을 지키기 위해 끝까지 최선을 다하던 당신 말이에요.",
            ["DialogueId"] = 10035212,
            ["FinalCamera"] = "-149.821655,-19.036041,141.362305,0.000255,-2.604604,19.478231,35.0,193.682495,false,Manual,8.0",
            ["GUID"] = "191F41F8",
            ["NextDialogue"] = 10035215,
            ["Scripts"] = "SEQ{\
