        [10035217] = {
            ["Camera"] = "70.786507,-101.814659,183.269775,0.000131,-18.616329,118.726715,30.0,199.427307,false,Manual,8.0",
            ["Content"] = "刚刚我一直在想，我一开始为什么要选择加入卫戍部队，为什么想成为“桂冠卡戎”……",
            ["ContentKR"] = "조금 전까지 계속 생각했어요. 처음에 왜 제가 방위대에 들어가려고 했는지, 왜 '계관카론'이 되고 싶었는지...",
            ["DialogueId"] = 10035217,
            ["FinalCamera"] = "68.902,-102.838882,183.269775,0.000131,-18.616322,118.326736,30.0,199.427307,false,Manual,8.0",
            ["GUID"] = "191F42CA",
            ["NextDialogue"] = 10035218,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Explain02_End",
                },
            ["ToFinalCameraBlendTime"] = 9,
            ["VoiceName"] = "voice/$Locale$/story/1003/100352/191F42CA",
            },
        [10035218] = {
            ["Camera"] = "165.494141,35.52478,112.30127,0.00033,10.385882,-175.467896,30.0,133.341751,false,Manual,5.0",
            ["Content"] = "为了军人的职责吗？为了保护民众吗？都不是。我……没有这么伟大。我想要的，不过是一份安稳的生活，能让自己过得安心一点。",
            ["ContentKR"] = "군인의 책임 때문일까요? 시민을 보호하기 위해서일까요? 다 아니에요. 저는... 그렇게 대단한 사람이 아니에요. 제가 원했던 건 그저 안정된 삶, 그리고 스스로 조금이나마 마음 편히 살 수 있는 그런 삶이었어요.",
            ["DialogueId"] = 10035218,
            ["FinalCamera"] = "131.374222,28.1595,121.635498,0.000325,11.985854,-177.667572,30.0,101.947998,false,Manual,5.0",
            ["GUID"] = "191F42F4",
            ["NextDialogue"] = 10035219,
            ["Scripts"] = "PARA{\
SetLocation{ActorId{100001},TargetPoint{\"TargetPoint_cp2fixsimple47_nvzhuHide\"},Visibility{\"Hide\"}},\
SEQ{\
PlayAnimation{_delay{3.5},ActorId{100304},AnimationId{\"Sigh_Start\"},Duration{3}},\
PlayAnimation{_delay{3.5},ActorId{100304},AnimationId{\"Sigh_End\"},Duration{3}},\
PlayAnimation{ActorId{100304},AnimationId{\"DisagreeHead\"},Duration{3}},\
}\
}\
",
            ["SpeakNpcId"] = 100304,
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/story/1003/100352/191F42F4",
            },
        [10035219] = {
            ["Camera"] = "-7.093658,62.875187,145.726074,0.000396,-17.213251,-45.26133,31.000006,51.557377,false,Manual,5.0",
            ["Content"] = "所以，我已经做好了决定。",
            ["ContentKR"] = "그러니, 전 이미 결정을 내렸습니다.",
            ["DialogueId"] = 10035219,
