                [2] = "\
200021:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100352/191F4540",
            },
        [10035233] = {
            ["Content"] = "一起去吧。我不会让你再留下遗憾。",
            ["ContentKR"] = "같이 가요. 다시는 후회할 일 없게.",
            ["DialogueId"] = 10035233,
            ["GUID"] = "191F456A",
            ["ImprPlusId"] = 1009,
            ["NextDialogue"] = 10035235,
            },
        [10035234] = {
            ["Content"] = "只有我们几个人行动吗？",
            ["ContentKR"] = "우리 몇 명만이 움직이는 건가요?",
            ["DialogueId"] = 10035234,
            ["GUID"] = "191F4594",
            ["ImprPlusId"] = 1006,
            ["NextDialogue"] = 10035235,
