        [10035243] = {
            ["Camera"] = "55.511089,-48.67382,134.474365,0.000208,1.577227,116.598,35.5,108.506393,false,Manual,8.0",
            ["Content"] = "好，黎瑟长官……不，黎瑟。",
            ["ContentKR"] = "네, 리듬 장교님... 아니, 리듬 씨.",
