                },
            ["NextDialogue"] = 10035250,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100352/191F480A",
            },
        [10035250] = {
            ["Camera"] = "-83.064827,-13.434433,122.876221,0.000078,11.996905,-30.740709,30.000013,100000.0,false,Manual,22.0",
            ["Content"] = "这么高雅的东西就别看我啦。",
            ["ContentKR"] = "그렇게 고상한 건 나한텐 기대하지 마라.",
            ["DialogueId"] = 10035250,
            ["FacialId"] = {
                [1] = "200021:Ahaha01",
                [2] = "100304:None",
                },
            ["GUID"] = "191F4834",
            ["LookAt"] = {
                [1] = "200021:n(200021)",
                [2] = "200002:n(200002)",
                [3] = "100304:n(200021)",
                [4] = "100001:n(200021)",
                },
            ["NextDialogue"] = 10035251,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:ScratchHead_Start",
                [2] = "100001:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100352/191F4834",
            },
        [10035251] = {
            ["Camera"] = "230.964554,123.720169,183.445557,0.000094,-14.6028,-143.350281,30.000008,100000.0,false,Manual,22.0",
            ["Content"] = "唔，我也不会……黎瑟长官呢？",
            ["ContentKR"] = "음, 나도 잘 몰라... 리듬 장교님은?",
            ["DialogueId"] = 10035251,
            ["FacialId"] = {
                [1] = "200021:None",
                },
            ["GUID"] = "191F485E",
            ["LookAt"] = {
