            },
        [10035402] = {
            ["Content"] = "好家伙，自己找上门来了……",
            ["ContentKR"] = "간도 크군, 제 발로 찾아오다니...",
            ["DialogueId"] = 10035402,
            ["GUID"] = "191F6124",
            ["NextDialogue"] = 10035403,
            ["SpeakNpcId"] = 200021,
