        [10035411] = {
            ["Camera"] = "-29.5625,-71.805176,165.97998,0.0,7.367677,18.358356,50.0,100000.0,false,Manual,22.0",
            ["Content"] = "布鲁斯·费西尔。你的，弟弟。那把口琴的，主人。",
            ["ContentKR"] = "블루스 페실. 당신의, 동생. 그 하모니카의, 주인.",
            ["DialogueId"] = 10035411,
            ["FinalCamera"] = "-29.5625,-71.805176,165.97998,0.0,11.16768,18.558241,50.0,100000.0,false,Manual,22.0",
