        [10035702] = {
            ["Camera"] = "455.675781,-610.116211,254.409729,0.000055,-14.003389,120.793579,20.000011,335.406189,false,DoNotOverride,1.2",
            ["Content"] = "我是36号，你是谁？",
            ["ContentKR"] = "난 36번이야, 넌 누구야?",
            ["DialogueId"] = 10035702,
            ["FinalCamera"] = "446.724609,-615.169922,254.409729,0.000057,-12.803305,115.393036,20.000011,335.406189,false,DoNotOverride,1.2",
