        [10035902] = {
            ["Camera"] = "-28.668945,-107.926758,217.894287,0.000002,-6.20203,-26.613487,20.000011,335.406189,false,DoNotOverride,1.2",
            ["Content"] = "抱歉，吵醒你了吗？",
            ["ContentKR"] = "미안해, 너무 시끄럽게 했나?",
            ["DialogueId"] = 10035902,
            ["FinalCamera"] = "-120.114258,-65.876953,220.58136,0.000004,-8.202053,-24.615345,20.000011,335.406189,false,DoNotOverride,1.2",
