            },
        [10035903] = {
            ["Camera"] = "432.814453,-578.855469,220.180359,0.000004,-7.399868,119.568428,20.000008,680.700806,false,Manual,3",
            ["Content"] = "难听得让人睡不着。头一次听到有人能把《雪国的孩子》里的唱段唱这么难听。",
            ["ContentKR"] = "너무 못 불러서 잠이 안 오네. 누가 〈설국의 아이〉를 이렇게 끔찍하게 부르는 건 처음이야.",
            ["DialogueId"] = 10035903,
            ["GUID"] = "191FB356",
            ["NextDialogue"] = 10035904,
            ["Scripts"] = "SetLocation{ActorId{100331},TargetPoint{\"tuosi01_53_idle\"},Visibility{\"Show\"}}",
            ["SpeakNpcId"] = 100328,
            ["SpeakNpcName"] = "Cp2CharacterName02",
            ["VoiceName"] = "voice/$Locale$/story/1003/100359/191FB356",
            },
        [10035904] = {
            ["Camera"] = "-120.114258,-65.876953,220.58136,0.000004,-8.202053,-24.615345,20.000011,335.406189,false,DoNotOverride,1.2",
            ["Content"] = "哈哈，如果有乐器，能演奏就不难听了。",
            ["ContentKR"] = "하하, 악기가 있어서 연주할 수 있으면 이렇게 형편없진 않았을 텐데.",
            ["DialogueId"] = 10035904,
            ["GUID"] = "191FB380",
            ["NextDialogue"] = 10035905,
            ["SpeakNpcId"] = 100331,
            ["SpeakNpcName"] = "Cp2CharacterName03",
            ["VoiceName"] = "voice/$Locale$/story/1003/100359/191FB380",
            },
        [10035905] = {
            ["Camera"] = "-120.114258,-65.876953,220.58136,0.000004,-8.202053,-24.615345,20.000011,335.406189,false,DoNotOverride,1.2",
            ["Content"] = "你不难受吗？",
            ["ContentKR"] = "넌 아프지 않아?",
            ["DialogueId"] = 10035905,
            ["GUID"] = "191FB3AA",
            ["LookAt"] = {
                [1] = "100328:n(100331)",
                },
            ["NextDialogue"] = 10035906,
            ["SpeakNpcId"] = 100328,
            ["SpeakNpcName"] = "Cp2CharacterName02",
            ["TalkActionId"] = {
                [1] = "100328:Sigh_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100359/191FB3AA",
            },
        [10035906] = {
            ["Camera"] = "434.479492,-573.817383,223.790649,0.000063,-8.001894,117.545296,22.000006,927.34375,false,Manual,2.799999",
            ["Content"] = "难受才要唱歌。",
            ["ContentKR"] = "아플수록 노래를 불러야지.",
            ["DialogueId"] = 10035906,
            ["GUID"] = "191FB3D4",
            ["LookAt"] = {
                [1] = "100328:n(100328)",
                },
            ["NextDialogue"] = 10035907,
            ["SpeakNpcId"] = 100331,
            ["SpeakNpcName"] = "Cp2CharacterName03",
            ["VoiceName"] = "voice/$Locale$/story/1003/100359/191FB3D4",
            },
        [10035907] = {
            ["Camera"] = "434.479492,-573.817383,223.790649,0.000063,-8.001894,117.545296,22.000006,927.34375,false,Manual,2.799999",
            ["Content"] = "省省吧。好不容易熬过了实验，别把自己唱死了。",
            ["ContentKR"] = "그만둬. 실험도 겨우 버텼는데, 노래 부르다 죽지나 마.",
            ["DialogueId"] = 10035907,
            ["GUID"] = "191FB3FE",
            ["NextDialogue"] = 10035908,
            ["SpeakNpcId"] = 100328,
            ["SpeakNpcName"] = "Cp2CharacterName02",
            ["TalkActionId"] = {
                [1] = "100328:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100359/191FB3FE",
            },
        [10035908] = {
            ["Camera"] = "180.489258,-377.827148,235.083801,0.000124,-5.80118,-21.050528,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "肉体的疼痛不算什么。把活生生的人给……！才让人难受……",
            ["ContentKR"] = "육체의 고통은 아무것도 아니야. 살아 있는 사람을...! 그게 진짜 고통스러운 거지...",
            ["DialogueId"] = 10035908,
            ["GUID"] = "191FB428",
            ["NextDialogue"] = 10035909,
            ["SpeakNpcId"] = 100331,
            ["SpeakNpcName"] = "Cp2CharacterName03",
            ["VoiceName"] = "voice/$Locale$/story/1003/100359/191FB428",
            },
        [10035909] = {
            ["Camera"] = "410.818359,-586.445312,210.064209,10.811686,-3.001451,107.757263,20.0,927.34375,false,Manual,3",
            ["Content"] = "这么久了，你还认为自己还是人啊。我们是怪物，无知无觉的、任人驱使的怪物。记住这点，你就不难受了。",
            ["ContentKR"] = "이렇게 오래 지나도 아직도 자기를 사람이라고 생각하나 보네. 우린 괴물이야. 무지하고, 무감각하고, 남이 부리는 대로 움직이는 괴물. 기억해, 그러면 덜 고통스러울 거야.",
            ["DialogueId"] = 10035909,
            ["GUID"] = "191FB452",
            ["LookAt"] = {
                [1] = "100328:n(100331)",
                },
            ["NextDialogue"] = 10035910,
            ["Scripts"] = "SEQ{\
MoveTo{ActorId{100328},TargetPoint{\"tuosi01_walk\"},MoveSpeed{150},Visibility{\"Show\"}},\
CameraMoveTo{_delay{0.6},TargetPosition{\"284.339844,-294.831055,217.898376,10.817102,0.598243,129.1483,20.000008,927.34375,false,Manual,22.0\"},duration{0}}\
}",
            ["SpeakNpcId"] = 100328,
            ["SpeakNpcName"] = "Cp2CharacterName02",
            ["VoiceName"] = "voice/$Locale$/story/1003/100359/191FB452",
            },
        [10035910] = {
            ["Camera"] = "317.161133,-375.083008,228.198242,0.000137,-7.201799,-39.445698,20.000008,100000.0,false,Manual,22.0",
            ["Content"] = "不能……不能变成怪物……如果连心都投降了，就真的变成怪物了。",
            ["ContentKR"] = "안 돼... 괴물이 될 순 없어... 마음마저 항복해버리면, 그땐 정말로 괴물이 돼버리는 거야.",
            ["DialogueId"] = 10035910,
            ["GUID"] = "191FB47C",
            ["NextDialogue"] = 10035911,
            ["SpeakNpcId"] = 100331,
            ["SpeakNpcName"] = "Cp2CharacterName03",
            ["TalkActionId"] = {
                [1] = "100331:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100359/191FB47C",
            },
        [10035911] = {
            ["Camera"] = "299.682617,-302.890625,219.492859,0.000183,-2.405818,132.131363,20.000008,100000.0,false,Manual,22.0",
            ["Content"] = "你忘了上次逃跑失败被按在电椅上了？省省吧，还是你想再挨一次？",
            ["ContentKR"] = "지난번에 탈출에 실패하고 전기의자에 앉은 거 잊었어? 그만둬. 아니면, 또 한 번 앉아보고 싶은 건가?",
            ["DialogueId"] = 10035911,
            ["GUID"] = "191FB4A6",
            ["LookAt"] = {
                [1] = "100328:n(100331)",
                },
            ["NextDialogue"] = 10035912,
            ["SpeakNpcId"] = 100328,
            ["SpeakNpcName"] = "Cp2CharacterName02",
            ["VoiceName"] = "voice/$Locale$/story/1003/100359/191FB4A6",
            },
        [10035912] = {
            ["Camera"] = "150.523438,-204.141602,220.726868,0.000177,-9.001649,-29.027712,20.000008,690.414062,false,Manual,2.799999",
            ["Content"] = "你看，你还在关心这些。这就证明了你还不是怪物。",
            ["ContentKR"] = "거봐, 넌 아직 이런 것들을 신경 쓰고 있잖아. 그게 네가 아직 괴물이 아니라는 증거야.",
            ["DialogueId"] = 10035912,
            ["GUID"] = "191FB4D0",
            ["NextDialogue"] = 10035913,
            ["SpeakNpcId"] = 100331,
            ["SpeakNpcName"] = "Cp2CharacterName03",
            ["TalkActionId"] = {
                [1] = "100331:Give",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100359/191FB4D0",
            },
        [10035913] = {
            ["Camera"] = "392.458984,-406.024414,222.654724,0.000121,-1.801845,133.350006,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "诡辩。",
            ["ContentKR"] = "궤변이야.",
            ["DialogueId"] = 10035913,
            ["FinalCamera"] = "304.217773,-313.102539,219.070496,0.000124,-0.801789,133.149994,25.0,100000.0,false,Manual,22.0",
            ["GUID"] = "191FB4FA",
            ["NextDialogue"] = 10035914,
            ["SpeakNpcId"] = 100328,
            ["SpeakNpcName"] = "Cp2CharacterName02",
            ["ToFinalCameraBlendTime"] = 1.5,
            ["VoiceName"] = "voice/$Locale$/story/1003/100359/191FB4FA",
            },
        [10035914] = {
            ["Camera"] = "183.125977,-413.553711,313.950928,0.000107,-24.746048,-11.405643,25.000002,100000.0,false,Manual,22.0",
            ["Content"] = "放心，我会带你一起逃出去的。",
            ["ContentKR"] = "걱정하지 마, 내가 널 데리고 이곳에서 탈출할게.",
            ["DialogueId"] = 10035914,
            ["FinalCamera"] = "153.149414,-407.208984,328.39209,0.000109,-24.946075,-11.006715,25.000002,100000.0,false,Manual,22.0",
            ["GUID"] = "191FB524",
            ["SpeakNpcId"] = 100331,
            ["SpeakNpcName"] = "Cp2CharacterName03",
            ["TalkActionId"] = {
                [1] = "100331:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1003/100359/191FB524",
            },
        [10035915] = {
            ["Content"] = "哇，这都没死成啊，再生能力看来也适应得不错。",
            ["ContentKR"] = "와, 이걸로도 안 죽다니. 재생 능력이 잘 적응된 모양이네.",
            ["DialogueId"] = 10035915,
            ["GUID"] = "191FB54E",
            ["NextDialogue"] = 10035916,
            ["SpeakNpcName"] = "Cp2CharacterName05",
            ["VoiceName"] = "voice/$Locale$/story/1003/100359/191FB54E",
            },
        [10035916] = {
            ["Content"] = "喂，别以为我不知道你在想什么哦。",
            ["ContentKR"] = "야, 네가 무슨 생각하는지 내가 모를 거로 생각하지 마.",
            ["DialogueId"] = 10035916,
            ["GUID"] = "191FB578",
            ["NextDialogue"] = 10035917,
            ["SpeakNpcName"] = "Cp2CharacterName05",
            ["VoiceName"] = "voice/$Locale$/story/1003/100359/191FB578",
            },
        [10035917] = {
            ["Content"] = "明明能很轻松获胜的吧，居然故意露出破绽伤成这个样子。",
            ["ContentKR"] = "분명 쉽게 이길 수 있었을 텐데, 일부러 빈틈을 보여서 이렇게 다친 거잖아.",
            ["DialogueId"] = 10035917,
            ["GUID"] = "191FB5A2",
            ["NextDialogue"] = 10035918,
            ["SpeakNpcName"] = "Cp2CharacterName05",
            ["VoiceName"] = "voice/$Locale$/story/1003/100359/191FB5A2",
            },
        [10035918] = {
            ["Content"] = "我们可不会让你们这么宝贵的改造体白白死掉呢！",
            ["ContentKR"] = "우리가 너희같이 소중한 개조체를 그냥 죽게 놔둘 리 없잖아!",
            ["DialogueId"] = 10035918,
            ["GUID"] = "191FB5CC",
            ["SpeakNpcName"] = "Cp2CharacterName05",
            ["VoiceName"] = "voice/$Locale$/story/1003/100359/191FB5CC",
            },
        [10035919] = {
            ["Content"] = "*的，又疯了一个。",
            ["ContentKR"] = "빌어먹을, 이 녀석도 정신이 나가 버렸잖아.",
            ["DialogueId"] = 10035919,
            ["GUID"] = "191FB525",
            ["VoiceName"] = "voice/$Locale$/story/1003/100359/191FB525",
            },
        [10035920] = {
            ["Content"] = "可惜了，本来有希望超过36号和47号的。",
            ["ContentKR"] = "36번이랑 47번을 뛰어넘으려나 했는데, 아깝게 됐어.",
            ["DialogueId"] = 10035920,
            ["GUID"] = "191FB526",
            ["VoiceName"] = "voice/$Locale$/story/1003/100359/191FB526",
            },
        [10035921] = {
            ["Content"] = "这就不行了？废物就是废物。",
            ["ContentKR"] = "이걸 못 버틴다고? 역시 실패작은 실패작이야.",
            ["DialogueId"] = 10035921,
            ["GUID"] = "191FB527",
            ["VoiceName"] = "voice/$Locale$/story/1003/100359/191FB527",
            },
        [10035922] = {
            ["Content"] = "呼……总算处理干净了。",
            ["ContentKR"] = "휴... 간신히 다 치웠네.",
            ["DialogueId"] = 10035922,
            ["GUID"] = "191FB528",
            ["VoiceName"] = "voice/$Locale$/story/1003/100359/191FB528",
            },
        [10036001] = {
