            },
        [10036005] = {
            ["Camera"] = "58.138672,-330.501953,109.144714,0.000134,8.597835,-22.997952,35.0,291.655762,false,Manual,2.8",
            ["Content"] = "嘿……这个，拿去……应该能缓解一下我们白天受的伤。",
            ["ContentKR"] = "저기, 이거... 가져가... 이걸로 낮에 입은 상처를 조금이나마 치료할 수 있을 거야.",
            ["DialogueId"] = 10036005,
            ["FinalCamera"] = "58.137695,-330.5,140.144714,0.000134,8.597835,-22.997952,35.0,291.655762,false,Manual,2.8",
            ["GUID"] = "191FC412",
            ["LookAt"] = {
                [1] = "100328:n(100331)",
                },
            ["NextDialogue"] = 10036006,
            ["SpeakNpcId"] = 100331,
            ["SpeakNpcName"] = "Cp2CharacterName03",
            ["TalkActionId"] = {
                [1] = "100331:Give",
                },
            ["ToFinalCameraBlendTime"] = 4,
            ["TurnTo"] = {
                [1] = "100328:n(100331)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100360/191FC412",
            },
        [10036006] = {
            ["Camera"] = "463.391602,-580.462891,220.541992,0.000188,-7.202789,119.394897,20.0,678.51178,false,Manual,3.0",
            ["Content"] = "……所以你白天任务完成那么慢，还挨了打，就是为了这几瓶药？",
            ["ContentKR"] = "...그래서 낮에 임무를 그렇게 늦게 끝내고, 심지어 맞기까지 한 게 이 몇 병의 약 때문이었어?",
            ["DialogueId"] = 10036006,
            ["GUID"] = "191FC43C",
            ["NextDialogue"] = 10036007,
            ["SpeakNpcId"] = 100328,
            ["SpeakNpcName"] = "Cp2CharacterName02",
            ["TalkActionId"] = {
                [1] = "100328:Sigh_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100360/191FC43C",
            },
        [10036007] = {
            ["Content"] = "被你发现了呀……",
            ["ContentKR"] = "들켰네...",
            ["DialogueId"] = 10036007,
            ["GUID"] = "191FC466",
            ["NextDialogue"] = 10036008,
            ["SpeakNpcId"] = 100331,
            ["SpeakNpcName"] = "Cp2CharacterName03",
            ["VoiceName"] = "voice/$Locale$/story/1003/100360/191FC466",
            },
        [10036008] = {
            ["Camera"] = "185.640625,-233.083984,160.088501,0.000144,8.996766,-43.391754,35.0,526.580566,false,Manual,2.8",
            ["Content"] = "可别放弃活下去的念头。我说过，要带你活着逃出去。",
            ["ContentKR"] = "절대 살아갈 희망을 버리지 마. 내가 말했잖아, 널 데리고 살아서 탈출할 거라고.",
            ["DialogueId"] = 10036008,
            ["GUID"] = "191FC490",
            ["LookAt"] = {
                [1] = "100328:n(100328)",
                },
            ["NextDialogue"] = 10036009,
            ["SpeakNpcId"] = 100331,
            ["SpeakNpcName"] = "Cp2CharacterName03",
            ["TalkActionId"] = {
                [1] = "100331:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100360/191FC490",
            },
        [10036009] = {
            ["Camera"] = "-267.09668,-233.355469,217.466675,-0.000031,-3.001649,50.570717,25.0,335.406189,false,DoNotOverride,1.2",
            ["Content"] = "为什么想活着？我们都这样了，出去了又能有什么好事？",
            ["ContentKR"] = "왜 살고 싶어 하는 거야? 이렇게까지 됐는데, 나가 봐야 좋은 일이 뭐가 있겠어?",
            ["DialogueId"] = 10036009,
            ["GUID"] = "191FC4BA",
            ["NextDialogue"] = 10036010,
            ["Scripts"] = "MoveTo{ActorId{100328},TargetPoint{\"tuosi01_walk3\"},MoveSpeed{200},Visibility{\"Show\"}}",
            ["SpeakNpcId"] = 100328,
            ["SpeakNpcName"] = "Cp2CharacterName02",
            ["VoiceName"] = "voice/$Locale$/story/1003/100360/191FC4BA",
            },
        [10036010] = {
            ["Camera"] = "160.84668,-584.186523,204.747314,-0.00003,-2.401276,24.76207,25.000002,335.406189,false,DoNotOverride,1.2",
            ["Content"] = "但死掉就永远不会发生好事，我不甘心。",
            ["ContentKR"] = "하지만, 이대로 죽으면 좋은 일은 영원히 일어나지 않을 거잖아. 난 그게 너무 억울해.",
            ["DialogueId"] = 10036010,
            ["GUID"] = "191FC4E4",
            ["NextDialogue"] = 10036011,
            ["SpeakNpcId"] = 100331,
            ["SpeakNpcName"] = "Cp2CharacterName03",
            ["TalkActionId"] = {
                [1] = "100331:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100360/191FC4E4",
            },
        [10036011] = {
            ["Camera"] = "307.469727,-340.191406,161.595886,0.000178,13.19656,-47.393784,35.000011,241.246582,false,Manual,2.799999",
            ["Content"] = "我们都还有梦想没实现吧。",
            ["ContentKR"] = "우리 아직 이루지 못한 꿈이 있잖아.",
            ["DialogueId"] = 10036011,
            ["GUID"] = "191FC50E",
            ["NextDialogue"] = 10036012,
            ["SpeakNpcId"] = 100331,
            ["SpeakNpcName"] = "Cp2CharacterName03",
            ["TalkActionId"] = {
                [1] = "100331:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100360/191FC50E",
            },
        [10036012] = {
            ["Camera"] = "498.730469,-495.881836,208.647461,0.00018,-0.003142,142.201035,50.0,241.246582,false,Manual,22.0",
            ["Content"] = "不重要了，反正都这样了。",
            ["ContentKR"] = "이젠 중요하지 않아, 어차피 이렇게 돼버렸으니까.",
            ["DialogueId"] = 10036012,
