            ["VoiceName"] = "voice/$Locale$/story/1003/100361/191FD672",
            },
        [10036118] = {
            ["Content"] = "那就，好……",
            ["ContentKR"] = "그럼, 다행이네...",
            ["DialogueId"] = 10036118,
            ["GUID"] = "191FD69C",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
