            ["SpeakNpcName"] = "Cp2CharacterName03",
            ["VoiceName"] = "voice/$Locale$/story/1003/100361/191FD69C",
            },
        [10036119] = {
            ["Content"] = "逃？这世上除了战场与实验室，哪里有你们怪物的容身之所！",
            ["ContentKR"] = "도망쳐? 이 세상에 전장과 실험실 말고 너희 같은 괴물이 머물 곳이 어디 있다고!",
            ["DialogueId"] = 10036119,
            ["GUID"] = "191FD6C6",
            ["NextDialogue"] = 10036120,
            ["SpeakNpcName"] = "Cp2CharacterName04",
            ["VoiceName"] = "voice/$Locale$/story/1003/100361/191FD6C6",
            },
        [10036120] = {
            ["Content"] = "…………",
            ["ContentKR"] = "......",
            ["DialogueId"] = 10036120,
            ["GUID"] = "191FD6F0",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10036121,
            ["SpeakNpcId"] = 100328,
            ["SpeakNpcName"] = "Cp2CharacterName02",
            ["VoiceName"] = "voice/$Locale$/story/1003/100361/191FD6F0",
            },
        [10036121] = {
            ["Content"] = "我们不是怪物。我们是，人……！",
            ["ContentKR"] = "우린 괴물이 아니야. 우린, 사람이야...!",
            ["DialogueId"] = 10036121,
            ["GUID"] = "191FD71A",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 100331,
            ["SpeakNpcName"] = "Cp2CharacterName03",
            ["VoiceName"] = "voice/$Locale$/story/1003/100361/191FD71A",
            },
        [10036122] = {
            ["Content"] = "这边！",
            ["ContentKR"] = "이쪽!",
            ["DialogueId"] = 10036122,
            ["GUID"] = "191FD744",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10036123,
            ["SpeakNpcId"] = 100328,
            ["SpeakNpcName"] = "Cp2CharacterName02",
            ["VoiceName"] = "voice/$Locale$/story/1003/100361/191FD744",
            },
        [10036123] = {
            ["Content"] = "这是……风吗？自由的……咳、咳……",
            ["ContentKR"] = "이건... 바람인가? 자유의... 쿨럭, 쿨럭...",
            ["DialogueId"] = 10036123,
            ["GUID"] = "191FD76E",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 100331,
            ["SpeakNpcName"] = "Cp2CharacterName03",
            ["VoiceName"] = "voice/$Locale$/story/1003/100361/191FD76E",
            },
        [10036124] = {
            ["Content"] = "这里有水声，一定能通向外面。",
            ["ContentKR"] = "여기 물소리가 들려. 분명 밖으로 통할 거야.",
            ["DialogueId"] = 10036124,
            ["GUID"] = "191FD798",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10036125,
            ["SpeakNpcId"] = 100328,
            ["SpeakNpcName"] = "Cp2CharacterName02",
            ["VoiceName"] = "voice/$Locale$/story/1003/100361/191FD798",
            },
        [10036125] = {
            ["Content"] = "真是，太好了，咳……",
            ["ContentKR"] = "정말, 다행이다, 쿨럭...",
            ["DialogueId"] = 10036125,
            ["GUID"] = "191FD7C2",
