            ["SpeakNpcId"] = 100328,
            ["SpeakNpcName"] = "Cp2CharacterName03",
            ["VoiceName"] = "voice/$Locale$/story/1003/100361/191FD816",
            },
        [10036128] = {
            ["Content"] = "太好了……我们……自由了……",
            ["ContentKR"] = "정말 다행이다... 우린... 자유야...",
            ["DialogueId"] = 10036128,
            ["GUID"] = "191FD840",
