            ["SpeakNpcName"] = "Cp2CharacterName02",
            ["VoiceName"] = "voice/$Locale$/story/1003/100361/191FD894",
            },
        [10036131] = {
            ["Content"] = "首先，要找个地方藏身……",
            ["ContentKR"] = "우선, 숨을 곳을 찾아야 해...",
            ["DialogueId"] = 10036131,
            ["GUID"] = "191FD8BE",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10036131.T_Story_Recall_10036131'",
