            ["VoiceName"] = "voice/$Locale$/story/1003/100362/191FE686",
            },
        [10036216] = {
            ["Content"] = "我还，以为，你会一直昏到，世界末日。",
            ["ContentKR"] = "세상이, 끝날 때까지, 기절해 있을 줄 알았어.",
            ["DialogueId"] = 10036216,
            ["GUID"] = "191FE6B0",
