            },
        [10036519] = {
            ["Content"] = "抱歉了，长官……！",
            ["ContentKR"] = "죄송합니다, 장교님...!",
            ["DialogueId"] = 10036519,
            ["GUID"] = "19201866",
            ["NextDialogue"] = 10036520,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100365/19201866",
            },
        [10036520] = {
            ["Content"] = "黎瑟撑住！我们也来帮你。",
            ["ContentKR"] = "리듬 씨, 버텨요! 우리도 도울게요.",
            ["DialogueId"] = 10036520,
            ["GUID"] = "19201890",
            ["NextDialogue"] = 10036521,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100365/19201890",
            },
        [10036521] = {
            ["Content"] = "好吧、好吧。既然都到了这份上，我也只能舍命相陪了！",
            ["ContentKR"] = "어쩔 수 없네. 이렇게 된 이상 나도 목숨 걸고 함께할 수밖에 없겠군!",
            ["DialogueId"] = 10036521,
            ["GUID"] = "192018BA",
            ["NextDialogue"] = 10036522,
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1003/100365/192018BA",
            },
        [10036522] = {
            ["Content"] = "你们、怎么……",
            ["ContentKR"] = "너희, 왜...",
            ["DialogueId"] = 10036522,
            ["GUID"] = "192018E4",
            ["SpeakNpcId"] = 100327,
