        [10037612] = {
            ["Camera"] = "-244.910645,-507.646484,467.576172,0.000006,-32.398735,52.788418,35.000015,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "我汇报的另一件事，关于冰湖城佩剑炼金院和第六军团勾结，在科赛托斯省以招募考核为名的非法实验……第十三军团真的完全不打算追究吗？",
            ["ContentKR"] = "제가 보고했던 또 다른 건 말입니다, 아이스레이크 시티의 소드 연금원이 제6군단과 결탁하여 코퀴투스 주에서 모병 시험이라는 명목으로 진행한 불법 실험에 대한 것이었는데... 제13군단은 정말 이 일을 전혀 추궁할 생각이 없는 겁니까?",
            ["DialogueId"] = 10037612,
            ["FacialId"] = {
                [1] = "200022:Doubt01",
                },
            ["FinalCamera"] = "-228.406738,-520.140625,467.576172,0.000007,-32.398735,55.388721,35.000015,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "1920CBB8",
