        [10037624] = {
            ["Camera"] = "-120.253906,83.223389,109.773438,0.000115,6.400085,-83.788696,35.000015,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "哈哈，可算等到你说“休息”了。生命在于休息，你终于听进去了上司的谆谆教诲，可喜可贺。",
            ["ContentKR"] = "하하, 드디어 '쉴래'라는 말을 꺼내네. 삶은 휴식에 달려 있는 법이야. 마침내 상사의 간곡한 충고를 귀담아들었으니, 축하할 일이네.",
            ["DialogueId"] = 10037624,
            ["FacialId"] = {
                [1] = "200022:Confident01",
                },
            ["FinalCamera"] = "-130.150879,82.145996,109.773438,0.000111,6.400085,-81.788612,35.000015,100000.0,false,DoNotOverride,22.0",
