        [10100210] = {
            ["Camera"] = "4915.476562,-702.842285,1756.620605,0.000003,25.494759,-14.000834,12.000003,3073.631592,false,Manual,1.2",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "是啊，怎么啦，突然大惊小怪的？",
            ["ContentKR"] = "응, 휘페르보레아 제국. 뭘 그렇게 놀라고 그래?",
