            ["NextDialogue"] = 10100302,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101003/1948F8A2",
            },
        [10100302] = {
            ["Content"] = "没什么，已经不痛了。",
            ["ContentKR"] = "괜찮아, 이제 아프지 않아.",
            ["DialogueId"] = 10100302,
            ["ExStoryInfo"] = "Player",
