            ["GUID"] = "1948F8F6",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10100304,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101003/1948F8F6",
            },
        [10100304] = {
            ["Content"] = "现在有我罩着你啦！毕竟白可是——",
            ["ContentKR"] = "이제 내가 지켜줄게! 이 스노우는...",
            ["DialogueId"] = 10100304,
            ["GUID"] = "1948F920",
