        [10101603] = {
            ["Camera"] = "9.080318,-196.48999,134.954025,0.001162,-2.098801,82.004311,35.000008,182.297424,false,Manual,1.993266",
            ["Content"] = "你不要生气，其实恩里克叔叔并没有那么贪财。只是我们最近实在拮据，不然他也不会打算卖掉老宅补贴家用。",
            ["ContentKR"] = "화 풀어. 헨릭 아저씨도 사실 돈 욕심이 있어서 그러는 건 아냐. 그냥 요즘 우리가 형편이 좀 어려워서 그래. 안 그러면 저택을 팔아 생활비에 보탤 생각도 안 했을 거야.",
            ["DialogueId"] = 10101603,
            ["FacialId"] = {
                [1] = "200002:Smile01",
                },
            ["FinalCamera"] = "9.080318,-196.48999,134.954025,0.001162,-0.498747,82.004166,35.000008,182.297424,false,Manual,1.993266",
