            ["VoiceName"] = "voice/$Locale$/story/1002/101016/1949CFE2",
            },
        [10101614] = {
            ["Camera"] = "390.112488,2686.977783,149.298599,0.001179,0.600053,-100.143715,50.0,100000.0,false,DoNotOverride,2.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "多亏了她，总算找到了住的地方，先休息一会儿吧，我也站累啦！",
            ["ContentKR"] = "덕분에 머물 곳도 찾았고... 일단 좀 쉬자. 서 있기도 피곤해!",
            ["DialogueId"] = 10101614,
            ["FacialId"] = {
                [1] = "200002:Smile02",
