            },
        [10101702] = {
            ["Camera"] = "32.615486,-85.951172,141.394852,0.001194,-10.600405,119.473099,50.000011,174.121933,false,Manual,22.0",
            ["CameraBlendCurve"] = "easeInQuad",
            ["Content"] = "（唯一确定的只有，我已经和贝蕾失散了……)",
            ["ContentKR"] = "(한 가지 확실한 건 베레와 떨어졌다는 거야...)",
            ["DialogueId"] = 10101702,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "100001:Sad01",
                },
            ["FinalCamera"] = "20.154007,-63.900879,136.737762,0.001195,-11.20041,119.473099,50.000011,174.121933,false,Manual,22.0",
            ["GUID"] = "1949DE7C",
            ["NextDialogue"] = 10101703,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["ToFinalCameraBlendTime"] = 7,
            ["VoiceName"] = "voice/$Locale$/story/1002/101017/1949DE7C",
            },
        [10101703] = {
            ["Camera"] = "521.906738,-420.427246,557.736206,0.001077,-34.294342,143.62709,35.000008,749.64917,false,Manual,4.0",
            ["CameraBlendCurve"] = "easeInQuad",
            ["Content"] = "（……如果她那时逃脱了，应该也会想尽办法找我......当然，不能排除最坏的可能性，也就是她被西比尔带去了军团。）",
            ["ContentKR"] = "(...만약 베레가 탈출에 성공했다면 어떻게든 날 찾으려 할텐데... 물론 시빌라에게 잡혀 군단으로 끌려갔다는 최악의 가능성도 배제할 순 없어.)",
            ["DialogueId"] = 10101703,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "Player",
            ["FinalCamera"] = "459.354492,-374.35791,505.258728,0.001073,-34.094299,144.027039,35.000008,749.64917,false,Manual,4.0",
            ["GUID"] = "1949DEA6",
            ["NextDialogue"] = 10101704,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["ToFinalCameraBlendTime"] = 16,
            ["VoiceName"] = "voice/$Locale$/story/1002/101017/1949DEA6",
            },
        [10101704] = {
            ["Camera"] = "-50.302734,-52.980469,119.29213,0.001284,-17.399469,87.817223,35.000011,114.672478,false,Manual,4.0",
            ["CameraBlendCurve"] = "easeInQuad",
            ["Content"] = "（不幸中的万幸是，西比尔似乎出于某种原因<H>需要</>贝蕾，应该不会加害于她。）",
            ["ContentKR"] = "(불행 중 다행인 건... 이유는 모르겠지만 시빌라가 베레를 <H>필요</>로 하는 것처럼 보였다는 거야. 그러니 해치지는 않겠지.)",
            ["DialogueId"] = 10101704,
