        [10102107] = {
            ["Camera"] = "-324.333984,818.858521,893.822021,-5.000005,-35.792892,-76.391212,40.168049,228.342102,false,DoNotOverride,6.685584",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "我怎么看怎么像条狗呢，哈哈，哈哈哈哈哈！",
            ["ContentKR"] = "아무리 봐도 개처럼 보인단 말이지, 하하, 으하하하하!",
            ["DialogueId"] = 10102107,
            ["FinalCamera"] = "-324.333984,818.858521,836.514404,-5.000005,-35.792892,-76.391212,40.168049,228.342102,false,DoNotOverride,6.685584",
            ["GUID"] = "194A20EE",
            ["NextDialogue"] = 10102108,
            ["SpeakNpcId"] = 200008,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/101021/194A20EE",
            },
        [10102108] = {
            ["Camera"] = "-119.224854,-52.406082,82.172852,0.000047,14.206512,-47.991478,45.857548,255.974915,false,Manual,2.325034",
            ["Content"] = "哎，要不你学几声狗叫，给咱们听听？",
            ["ContentKR"] = "큭, 한번 짖어보라고.",
            ["DialogueId"] = 10102108,
            ["GUID"] = "194A2118",
            ["SpeakNpcId"] = 200010,
            ["VoiceName"] = "voice/$Locale$/story/1002/101021/194A2118",
            },
        [10102201] = {
            ["Content"] = "不，不行……",
            ["ContentKR"] = "안 돼, 안 돼...",
            ["DialogueId"] = 10102201,
            ["Duration"] = 2,
            ["GUID"] = "194A305A",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101022/194A305A",
            },
        [10102202] = {
            ["Content"] = "嗯？看什么看，小崽子。",
            ["ContentKR"] = "응? 구경이라도 났나, 빨리 안 꺼져?",
            ["DialogueId"] = 10102202,
            ["Duration"] = 1.5,
            ["GUID"] = "194A3084",
            ["SpeakNpcName"] = "UI_Npc_Name_Man_5",
            ["VoiceName"] = "voice/$Locale$/story/1002/101022/194A3084",
            },
        [10102203] = {
            ["Content"] = "你不会给我惹什么麻烦的——对吧？",
            ["ContentKR"] = "날 귀찮게 할 생각은 아니겠지?",
            ["DialogueId"] = 10102203,
            ["Duration"] = 4,
            ["GUID"] = "194A30AE",
            ["SpeakNpcId"] = 200003,
            ["VoiceName"] = "voice/$Locale$/story/1002/101022/194A30AE",
            },
        [10102204] = {
            ["Content"] = "父、父亲……",
            ["ContentKR"] = "아, 아버지...",
            ["DialogueId"] = 10102204,
