            ["Duration"] = 1.5,
            ["GUID"] = "194A312C",
            ["SpeakNpcName"] = "UI_Npc_Name_Man_13",
            ["VoiceName"] = "voice/$Locale$/story/1002/101022/194A312C",
            },
        [10102206] = {
