        [10102403] = {
            ["Camera"] = "125.824219,-225.558105,135.956543,0.000172,-1.798553,120.789757,50.0,356.306458,false,Manual,6.0",
            ["Content"] = "如果你们是从海伯利亚以外的地方来的，请记住，千万不要触怒“<H>索拉之民</>”。",
            ["ContentKR"] = "만약 휘페르보레아 밖에서 온 사람이라면, 절대로 <H>솔라</>를 화나게 해선 안 돼",
