            ["Content"] = "……这样吗。",
            ["ContentKR"] = "...그렇게 된 건가.",
            ["DialogueId"] = 10102603,
            ["FacialId"] = {
                [1] = "100001:Smile01",
                [2] = "200006:Happy01",
