        [10102604] = {
            ["Camera"] = "53.717529,77.917969,151.150391,0.001249,-3.299029,-154.168152,60.000004,328.479401,false,Manual,5.0",
            ["Content"] = "……我是带这位朋友来的。{性别：他|她}想找一份狩月人的工作。",
            ["ContentKR"] = "...오늘 여기 온 건, 이 친구가 월석 사냥꾼 일을 해보고 싶다고 해서요.",
            ["DialogueId"] = 10102604,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
