            ["TalkActionId"] = {
                [1] = "200011:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101026/194A72F6",
            },
        [10102608] = {
            ["Camera"] = "-109.342285,-78.164062,166.683594,0.00123,-3.99997,36.028351,50.0,253.714981,false,Manual,3.5",
            ["Content"] = "这么快就交上了朋友……你还挺受欢迎。至于狩月人——",
            ["ContentKR"] = "이렇게 빨리 친구를 사귀다니... 인기가 꽤 많네. 그리고 월석 사냥꾼 일은...",
            ["DialogueId"] = 10102608,
            ["FacialId"] = {
                [1] = "100001:Confident01",
                },
            ["GUID"] = "194A7320",
            ["LookAt"] = {
