                },
            ["NextDialogue"] = 10102609,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{200003},AnimationId{\"Think_End\"},Duration{1.5}},\
PlayAnimation{ActorId{200003},AnimationId{\"Confident_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 200003,
            ["VoiceName"] = "voice/$Locale$/story/1002/101026/194A7320",
            },
        [10102609] = {
            ["Camera"] = "291.657104,98.844727,170.599609,0.001316,-5.498842,-164.352921,52.422081,496.264801,false,Manual,4.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "丑话说在前头，这不是小孩子玩闹，更不是什么轻松活计。这里是不问来历、不问出身，但你得到的每一枚回报，都伴随着相应的危险。",
            ["ContentKR"] = "솔직하게 말하지. 이건 애들 장난이 아니야. 쉬운 일도 아니고. 여긴 과거도, 출신도 묻지 않지만 네가 받는 모든 보상에 그만큼의 위험이 따를 거야.",
            ["DialogueId"] = 10102609,
            ["FacialId"] = {
                [1] = "200011:Unhappy01",
                },
            ["FinalCamera"] = "231.961548,82.132812,164.626953,0.001316,-5.498842,-164.352844,52.422081,430.432526,false,Manual,4.0",
            ["GUID"] = "194A734A",
            ["LookAt"] = {
                [1] = "200011:n(200003)",
                [2] = "200006:n(200003)",
                [3] = "200003:n(100001)",
                },
            ["NextOptions"] = {
                [1] = 101026091,
                [2] = 101026092,
                },
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{200003},AnimationId{\"Confident_End\"},Duration{2}},\
PlayAnimation{ActorId{200003},AnimationId{\"Talk02_Start\"},Duration{2.5}},\
PlayAnimation{ActorId{200003},AnimationId{\"Talk02_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 200003,
            ["ToFinalCameraBlendTime"] = 14,
            ["VoiceName"] = "voice/$Locale$/story/1002/101026/194A734A",
            },
        [10102610] = {
            ["Camera"] = "-294.801819,-157.509766,135.695312,0.001227,1.1999,33.90601,60.000004,460.630157,false,Manual,12.0",
            ["Content"] = "模样不算硬朗，想法倒是坚决。",
            ["ContentKR"] = "생긴 건 비리비리한데 꽤 강단이 있네.",
            ["DialogueId"] = 10102610,
            ["FacialId"] = {
                [1] = "200006:None",
                [2] = "200011:None",
                },
            ["GUID"] = "194A7374",
            ["LookAt"] = {
                [1] = "200011:n(200003)",
                },
            ["NextDialogue"] = 10102611,
            ["SpeakNpcId"] = 200003,
            ["TalkActionId"] = {
                [1] = "200003:Talk03_Start",
                [2] = "100001:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101026/194A7374",
            },
        [10102611] = {
            ["Camera"] = "-43.718262,-1261.714844,610.828125,0.001481,-22.297657,82.031219,25.0,166.832703,false,DoNotOverride,22.0",
            ["Content"] = "你身手确实比一般的卡戎强些，我见过。但想要成为狩月人的话，只有蛮力是不够的——你还得证明自己能够应付突发事件与各种各样的雇主。",
            ["ContentKR"] = "보아하니 확실히 일반 카론보다는 실력이 있어 보이지만, 월석 사냥꾼이 되려면 힘만 세서는 안돼. 돌발상황이나 여러 고용주에 대처할 능력이 있다는 걸 증명해야 하지.",
            ["DialogueId"] = 10102611,
            ["FinalCamera"] = "-98.231934,-1254.261719,610.828125,0.001477,-22.297657,82.031197,25.0,166.832703,false,DoNotOverride,22.0",
