        [10102612] = {
            ["Camera"] = "-328.773987,-167.959961,134.214844,0.001226,0.0,28.499939,50.0,499.398407,false,Manual,10.0",
            ["Content"] = "比如，这里就有一个证明的机会。",
            ["ContentKR"] = "여기 마침 그걸 증명할 기회가 생겼네.",
            ["DialogueId"] = 10102612,
