}",
            ["SpeakNpcId"] = 200053,
            ["VoiceName"] = "voice/$Locale$/story/1002/101032/194AD496",
            },
        [10103204] = {
            ["Camera"] = "-94.212891,40.829102,88.263504,0.000059,6.830749,-10.009793,37.719067,200.074844,false,Manual,5.0",
            ["Content"] = "你要吃饭，别人就不要吃吗！而且你刚才抢劫的时候可嚣张得很！",
            ["ContentKR"] = "네 배만 배다 이거지! 다른 사람들은 생각도 안 하고! 그리고 아까 지갑 뺏을 땐 엄청 거만하더니!",
            ["DialogueId"] = 10103204,
            ["FacialId"] = {
                [1] = "200011:Angry01",
