            ["VoiceName"] = "voice/$Locale$/story/1002/101033/194AE4D2",
            },
        [10103302] = {
            ["Camera"] = "66.533203,37.944336,174.613312,0.000149,-10.000031,-167.999481,35.0,212.973618,false,Manual,4.0",
            ["Content"] = "不许提我妈……！凶婆娘你他*的松手！！",
            ["ContentKR"] = "감히 우리 엄마를 들먹여...! 이 못된 녀석이...!!",
            ["DialogueId"] = 10103302,
            ["GUID"] = "194AE4FC",
            ["LookAt"] = {
                [1] = "200003:n(200053)",
                },
            ["SpeakNpcId"] = 200053,
            ["TalkActionId"] = {
                [1] = "200053:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101033/194AE4FC",
            },
        [10103303] = {
            ["Content"] = "卡米拉一把握住青年的手。她的力道很大，你甚至能听到小臂骨头咔嚓折断的响声。",
            ["ContentKR"] = "카밀라가 청년의 손을 세게 움켜쥐었다. 얼마나 세게 움켜쥐었는지 팔뚝에서 우지끈 소리가 들려올 정도였다.",
            ["DialogueId"] = 10103303,
            ["GUID"] = "194AE4FD",
            ["IsBlack"] = 1,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/talk_grip_1\"},PlayAs2D{true}}",
            ["TalkActionId"] = {
                [1] = "200003:Talk03_End",
                [2] = "200053:Angry01_End",
                },
            },
        [10103304] = {
            ["Content"] = "突然，卡米拉倒吸一口冷气，些微踉跄了一步。她睁大眼睛，直直盯着青年的手腕处。",
            ["ContentKR"] = "카밀라가 갑자기 숨을 들이켰고, 약간 비틀거렸다. 그리곤 눈을 크게 뜨고 청년의 손목을 뚫어지게 쳐다보았다.",
            ["DialogueId"] = 10103304,
            ["GUID"] = "194AE4FE",
            ["IsBlack"] = 1,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/talk_grip_2\"},PlayAs2D{true}}",
            },
        [10103305] = {
            ["Content"] = "青年袖口的绷带似乎在刚才的打斗中被扯开了。你看到他手腕处横亘着一道深入骨髓的黑色印记——它看起来如此不祥，让你不由得想起一个词：“恶魔”。",
            ["ContentKR"] = "방금 전 다툼으로 인해 청년 옷소매 쪽의 붕대가 찢어졌고, 손목에 드러난 뼛속 깊이 새겨진 검은 표식은 무의식적으로 '악마'라는 단어가 떠오를 만큼이나 불길하게 느껴졌다.",
            ["DialogueId"] = 10103305,
            ["GUID"] = "194AE4FF",
            ["IsBlack"] = 1,
            },
