        [10103403] = {
            ["Camera"] = "415.427734,94.491211,401.934753,8.000882,-38.599918,-167.192322,20.0,100000.0,false,Disable,2.8",
            ["CameraBlendCurve"] = "easeInQuad",
            ["Content"] = "老……我、我知道了，知错了，这次是真的知错了！你们怎么惩罚我都行，千万别送我去那儿！",
            ["ContentKR"] = "내가... 제, 제가 잘못했어요, 진심으로 반성하고 있다고요! 어떤 벌이든 달게 받을 테니, 제발 거기로만은 보내지 말아 주세요!",
            ["DialogueId"] = 10103403,
