        [10103404] = {
            ["Camera"] = "1827.431641,564.506836,52.700241,8.011471,1.600771,-160.179901,25.0,171.285019,false,DoNotOverride,1.6",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "我、我可以离开冰湖城，再也不回来！放了我吧，求求你们！",
            ["ContentKR"] = "아이스레이크 시티를 떠나서 다시는 안 돌아올게요! 제발 보내주세요, 부탁드립니다!",
