        [10103501] = {
            ["Camera"] = "-165.324219,313.250977,140.767822,0.000018,-4.657957,-60.556728,41.027447,1.5,false,Disable,1.2",
            ["Content"] = "奇怪，卡米拉大姐什么人没见过，这次怎么反应这么大……",
            ["ContentKR"] = "이상하네요, 누굴 본 것도 아닌데 카밀라 언니가 왜 그렇게까지 민감하게 반응한 걸까요...",
            ["DialogueId"] = 10103501,
            ["FacialId"] = {
