            },
        [10103804] = {
            ["Camera"] = "174.522949,141.578125,137.132812,0.001337,-15.600308,-143.896393,35.0,212.370575,false,Manual,2.8",
            ["Content"] = "之前也没说过假话！快来快来，我的小仆从，这是威尔斯大叔，这里最勤快的狩月人啦。",
            ["ContentKR"] = "전에도 거짓말한 적 없거든! 얼른 와, 시종. 여긴 웨일즈 아저씨야. 여기에서 제일 부지런한 월석 사냥꾼이지.",
            ["DialogueId"] = 10103804,
            ["FacialId"] = {
                [1] = "200002:None",
                },
            ["GUID"] = "194B3758",
            ["NextDialogue"] = 10103805,
