        [10103807] = {
            ["Camera"] = "284.5,160.327148,200.447266,0.001179,-15.600097,-147.194611,35.000011,345.690643,false,Manual,2.25",
            ["Content"] = "过奖了，小事而已。",
            ["ContentKR"] = "과찬이세요. 별거 아닌걸요.",
            ["DialogueId"] = 10103807,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "100001:Smile02",
                },
            ["GUID"] = "194B37D6",
