}",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101038/194B37D6",
            },
        [10103808] = {
            ["Camera"] = "-88.652222,34.671875,132.285156,0.00134,1.999114,2.708378,30.0,289.613831,false,Manual,1.6",
            ["CameraBlendCurve"] = "easeOutQuad",
            ["Content"] = "小事？我跟你说，就是你们这些干小事的人太多，冰湖城才是现在这副样子。要是干什么大事，那冰湖城还不得翻了天去。",
            ["ContentKR"] = "별거 아냐? 이봐, 너희 같이 별거 아닌 일을 하는 분이 어찌나 많으신지 아이스레이크 시티가 지금 이 모양이라고. 진짜 별거인 일이라도 하면 아이스레이크 시티가 아주 뒤집어지겠어.",
            ["DialogueId"] = 10103808,
            ["FinalCamera"] = "-37.667603,37.084961,137.621094,0.00134,1.999114,2.708446,30.0,210.36618,false,Manual,1.6",
            ["GUID"] = "194B3800",
            ["NextDialogue"] = 10103809,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{200065},AnimationId{\"Disagree\"},Duration{2.2}},\
PlayAnimation{ActorId{200065},AnimationId{\"Explain01_Start\"},Duration{5}},\
PlayAnimation{ActorId{200065},AnimationId{\"Explain01_End\"},Duration{2.1}},\
PlayAnimation{_delay{2.6},ActorId{200065},AnimationId{\"Talk01_Start\"},Duration{0.5}}\
}",
            ["SpeakNpcId"] = 200065,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/101038/194B3800",
            },
        [10103809] = {
