        [10103817] = {
            ["Camera"] = "-903.175842,661.294922,132.769531,0.00128,-1.799468,-25.584341,60.000004,184.96936,false,Manual,10.0",
            ["Content"] = "抱歉抱歉，想喝点什么？去跟卡米拉说一声，我请你，就当作赔礼。",
            ["ContentKR"] = "미안, 미안, 뭔가 마시고 싶은 거라도 있어? 카밀라한테는 내가 산다고 해. 사과의 의미로 내가 살게.",
            ["DialogueId"] = 10103817,
            ["FinalCamera"] = "-896.797668,674.62207,132.769531,0.001278,-1.799468,-25.585255,60.000004,184.96936,false,Manual,10.0",
            ["GUID"] = "194B39CE",
            ["SpeakNpcId"] = 200065,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/101038/194B39CE",
            },
        [10103901] = {
            ["Content"] = "太好了，你的第一个委托比我想象中还要顺利呢。",
            ["ContentKR"] = "다행이다, 첫 의뢰가 순조롭게 잘 마무리된 것 같네. 괜한 걱정을 했어.",
            ["DialogueId"] = 10103901,
            ["GUID"] = "194B4742",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101039/194B4742",
            },
        [10103902] = {
            ["Content"] = "和卡米拉说一声吧，我请客。",
            ["ContentKR"] = "카밀라한테는 내가 산다고 해.",
            ["DialogueId"] = 10103902,
            ["GUID"] = "194B476C",
            ["SpeakNpcId"] = 200015,
            ["VoiceName"] = "voice/$Locale$/story/1002/101039/194B476C",
            },
        [10104001] = {
            ["Camera"] = "-128.52594,-209.771484,157.75,0.001194,-1.599637,42.225967,62.024101,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "第一个任务还算利落，和威尔斯也聊的不错，你的狩月人生涯开场挺顺利的。",
            ["ContentKR"] = "첫 번째 임무는 그럭저럭 깔끔했고, 웨일즈와 얘기도 잘 된 것 같으니, 앞으로의 월석 사냥꾼 생활에 첫걸음은 잘 뗀 것 같네.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 10104001,
            ["FinalCamera"] = "-38.11908,-127.723633,154.339844,0.001194,-1.599637,42.226406,62.024101,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "194B57AA",
            ["LookAt"] = {
                [1] = "200003:n(100001)",
                },
            ["NextDialogue"] = 10104002,
            ["RelatedWikiId"] = {
                [1] = 408003,
                [2] = 405004,
                [3] = 201004,
                },
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{200003},AnimationId{\"Talk02_Start\"},Duration{2}},\
PlayAnimation{ActorId{200003},AnimationId{\"Talk02_End\"},Duration{1.9}},\
PlayAnimation{ActorId{200003},AnimationId{\"Think_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 200003,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/101040/194B57AA",
            },
        [10104002] = {
            ["Camera"] = "264.06897,120.25293,140.035156,0.001216,-0.898272,38.841923,25.000002,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "来吧，喝口热饮。本来还想请你一杯，但既然威尔斯开了口，那就记他账上吧。",
            ["ContentKR"] = "자, 따끈한 음료라도 마시고 몸 좀 녹여. 원래는 내가 한 잔 사려고 했는데 웨일즈가 먼저 말했으니 웨일즈한테 달아 둘게.",
            ["DialogueId"] = 10104002,
            ["GUID"] = "194B57D4",
            ["LookAt"] = {
                [1] = "200002:n(200065)",
                },
            ["NextDialogue"] = 10104003,
            ["Scripts"] = "PARA{\
SEQ{\
PlayAnimation{ActorId{200003},AnimationId{\"Think_End\"},Duration{1}},\
PlayAnimation{ActorId{200003},AnimationId{\"Give\"},Duration{3}}\
},\
PARA{\
LookAt{_delay{5},LookAtDescription{\"200003:n(200065)\"}},\
PlayAnimation{_delay{7},ActorId{200003},AnimationId{\"Talk03_Start\"},Duration{1}}\
}\
}",
            ["SpeakNpcId"] = 200003,
            ["VoiceName"] = "voice/$Locale$/story/1002/101040/194B57D4",
            },
        [10104003] = {
            ["Camera"] = "628.309448,196.21875,165.917969,0.001246,-2.898438,-159.398209,50.000008,418.194519,false,Manual,2.0",
            ["Content"] = "哎，刚刚确实是我误会了这位{性别：小兄弟|小姑娘}，应该的。",
            ["ContentKR"] = "아, 방금은 내가 이 친구를 오해한 게 맞으니 당연히 내가 사야지.",
            ["DialogueId"] = 10104003,
            ["ExStoryInfo"] = "Player",
            ["FinalCamera"] = "620.438354,217.157227,165.917969,0.001246,-2.898438,-159.398209,50.000008,418.194519,false,Manual,2.0",
            ["GUID"] = "194B57FE",
            ["LookAt"] = {
                [1] = "200003:n(200065)",
                },
            ["NextDialogue"] = 10104004,
            ["Scripts"] = "PARA{\
