                [1] = "200065:n(100001)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101040/194B59F6",
            },
        [10104016] = {
            ["Camera"] = "261.87085,-103.149414,166.572266,0.001257,-8.298399,112.052223,35.000008,221.426971,false,Manual,2.0",
            ["Content"] = "真要去？{性别：小老弟|小姑娘}，大叔我没跟你说笑——这可不是过家家！",
            ["ContentKR"] = "진짜 가려고? {性别:청년|아가씨}, 내가 농담하는 걸로 보여? 이건 소꿉놀이가 아니라고!",
            ["DialogueId"] = 10104016,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194B5A20",
            ["LookAt"] = {
