}\
}",
            ["SpeakNpcId"] = 200065,
            ["VoiceName"] = "voice/$Locale$/story/1002/101040/194B5A20",
            },
        [10104017] = {
            ["Content"] = "谢谢你，我明白的。但是，卡米拉女士……",
            ["ContentKR"] = "감사해요, 저도 알아요. 하지만 카밀라 씨...",
            ["DialogueId"] = 10104017,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "100001:Confident01",
                },
            ["GUID"] = "194B5A4A",
