            ["VoiceName"] = "voice/$Locale$/story/1002/101040/194B5A4A",
            },
        [10104018] = {
            ["Camera"] = "586.407837,263.538086,166.693359,0.001254,-5.098381,-163.341629,60.0,424.533936,false,Manual,3.8",
            ["Content"] = "你说过的。如果连这点事都做不到，那我靠什么去找我……弄丢的宝物。",
            ["ContentKR"] = "말씀하신 대로 이 정도 일도 못 해내면 제가 어떻게... 잃어버린 보물을 찾을 수 있겠어요.",
            ["DialogueId"] = 10104018,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194B5A74",
