PlayFacial{_delay{5},ActorId{200006},FacialId{\"Smile01\"}}\
}",
            ["SpeakNpcId"] = 100001,
            ["TurnTo"] = {
                [1] = "100001:n(200003)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101040/194B5A74",
            },
        [10104019] = {
            ["Camera"] = "-127.626587,-169.432617,135.080078,0.001295,0.699917,38.798576,70.000015,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "水仙平原对委托人和狩月人的委托内容不做干涉。你心意已决，我自然不会阻拦。",
            ["ContentKR"] = "아스포델은 의뢰인과 월석 사냥꾼의 의뢰 내용에 관여하지 않아. 네가 하겠다면 난 막을 생각 없어.",
            ["DialogueId"] = 10104019,
            ["FacialId"] = {
                [1] = "200003:Uninterested01",
                },
            ["GUID"] = "194B5A9E",
            ["LookAt"] = {
                [1] = "200065:n(200003)",
                },
