PlayAnimation{ActorId{100001},AnimationId{\"Think_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "200006:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101046/194BBC3C",
            },
        [10104701] = {
            ["Content"] = "锁住了？看我给它敲开！",
            ["ContentKR"] = "잠겼어? 내가 여는 거 잘 봐!",
            ["DialogueId"] = 10104701,
            ["Duration"] = 3,
            ["GUID"] = "194BCA82",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104702,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101047/194BCA82",
            },
        [10104702] = {
            ["Content"] = "（头槌砸门声）",
            ["ContentKR"] = "(문에 박치기하는 소리)",
            ["DialogueId"] = 10104702,
            ["DisableMouth"] = 1,
            ["Duration"] = 2,
            ["GUID"] = "194BCA83",
            ["NextDialogue"] = 10104703,
            ["VoiceName"] = "sfx/common/story/01/tietougong",
            },
        [10104703] = {
            ["Content"] = "……哇！",
            ["ContentKR"] = "...악!",
            ["DialogueId"] = 10104703,
            ["Duration"] = 2,
            ["GUID"] = "194BCAD6",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104704,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101047/194BCAD6",
            },
        [10104704] = {
            ["Content"] = "这种厚度的门应该是无法用蛮力打开的。",
            ["ContentKR"] = "이 정도 두께라면 아무리 힘을 써도 열리지 않겠어.",
            ["DialogueId"] = 10104704,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194BCB00",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104705,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101047/194BCB00",
            },
        [10104705] = {
            ["Content"] = "那我们在周围转转，看看有没有其它入口吧。",
            ["ContentKR"] = "그럼 다른 입구가 있는지 주변을 둘러보자.",
            ["DialogueId"] = 10104705,
            ["Duration"] = 3,
            ["GUID"] = "194BCB2A",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104706,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101047/194BCB2A",
            },
        [10104706] = {
            ["Content"] = "白，你的脑袋痛吗？我来帮你——",
            ["ContentKR"] = "스노우, 머리 많이 아프겠다. 내가 도와줄게.",
            ["DialogueId"] = 10104706,
            ["Duration"] = 3,
            ["GUID"] = "194BCB54",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104707,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101047/194BCB54",
            },
        [10104707] = {
            ["Content"] = "……吹一下就不疼啦。",
            ["ContentKR"] = "...이렇게 불면 아프지 않을 거야.",
            ["DialogueId"] = 10104707,
            ["Duration"] = 3,
            ["GUID"] = "194BCB7E",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104708,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101047/194BCB7E",
            },
        [10104708] = {
            ["Content"] = "呜呜……你真是个大好人。等本魔王大人彻底占领这里，就封你——",
            ["ContentKR"] = "흑흑... 넌 정말 좋은 사람이야. 이 마왕님께서 여길 점령하면 널...",
            ["DialogueId"] = 10104708,
            ["Duration"] = 3,
            ["GUID"] = "194BCBA8",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104709,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101047/194BCBA8",
            },
        [10104709] = {
            ["Content"] = "“温柔的绿衣法师，睿智的月石主宰，第一代格雷姆矿场大公”！",
            ["ContentKR"] = "'온화한 녹색 옷의 마법사, 현명한 월석의 주재자, 초대 글로스터 광갱 대공'으로 임명하겠어!",
            ["DialogueId"] = 10104709,
            ["Duration"] = 3,
            ["GUID"] = "194BCBD2",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104710,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101047/194BCBD2",
            },
        [10104710] = {
            ["Content"] = "（之前我是下水道公爵……大公是不是比公爵还要高级一点的爵位啊？）",
            ["ContentKR"] = "(저번에 나는 하수도 공작이었는데... 대공이면 나보다 높은 작위 아닌가?)",
            ["DialogueId"] = 10104710,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194BCBFC",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104711,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101047/194BCBFC",
            },
        [10104711] = {
            ["Content"] = "（为什么赛琪的爵位比我高？等等，怎么我又在一本正经思考了。）",
            ["ContentKR"] = "(왜 프시케의 작위가 나보다 높은 거지? 잠깐, 난 또 뭘 진지하게 생각하는 거야.)",
            ["DialogueId"] = 10104711,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194BCC26",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101047/194BCC26",
            },
        [10104801] = {
            ["Content"] = "“在魔王大人白的指引下，刚刚从远方抵达冰湖城的小仆从，只一天功夫就成为了出色的‘狩月人’。”",
            ["ContentKR"] = "\"본 마왕 스노우 님의 인도 하에, 막 아이스레이크 시티에 도착한 시종은 하루 만에 뛰어난 '월석 사냥꾼'이 되었다.\"",
            ["DialogueId"] = 10104801,
            ["GUID"] = "194BDAEA",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104802,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101048/194BDAEA",
            },
        [10104802] = {
            ["Content"] = "本魔王的传说又可以添上新的篇章啦。",
            ["ContentKR"] = "이 마왕님의 전설에 또 새로운 페이지가 더해지는군.",
            ["DialogueId"] = 10104802,
            ["GUID"] = "194BDB14",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104803,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101048/194BDB14",
            },
        [10104803] = {
            ["Content"] = "“狩月人”这个名字还挺特别的……狩猎月亮？",
            ["ContentKR"] = "'월석 사냥꾼'이라... 꽤나 독특한 이름이네... 월석을 사냥하는 사람이라는 뜻인 건가?",
            ["DialogueId"] = 10104803,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194BDB3E",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104804,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101048/194BDB3E",
            },
        [10104804] = {
            ["Content"] = "错了错了！狩月人这个名字和月亮没什么关系，它最早的意思其实是——“月石猎人”！",
            ["ContentKR"] = "땡! '월석 사냥꾼'은 의뢰를 받아서 수행하는 현상금 사냥꾼이라는 뜻이야. 월석을 채집하는 건 옛날 얘기라고!",
            ["DialogueId"] = 10104804,
            ["GUID"] = "194BDB68",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104805,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101048/194BDB68",
            },
        [10104805] = {
            ["Content"] = "嗯，我听说这个职业就是起源于冰湖城。",
            ["ContentKR"] = "응, 이 직업은 아이스레이크 시티에서 유래된 거라고 들었어.",
            ["DialogueId"] = 10104805,
            ["GUID"] = "194BDB92",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104806,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101048/194BDB92",
            },
        [10104806] = {
            ["Content"] = "似乎是因为，维德弗尼尔山一带有丰富的天之树矿脉，上面的月石可以卖出好价钱……",
            ["ContentKR"] = "베드르폴니르 산 일대에는 천국의 나무 광맥이 풍부하고, 그 위에 달린 월석이 아주 좋은 가격에 팔렸기 때문일 거야...",
            ["DialogueId"] = 10104806,
            ["GUID"] = "194BDBBC",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104807,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101048/194BDBBC",
            },
        [10104807] = {
            ["Content"] = "没错！所以很久很久以前，就有很多人冒险接受委托去采月石了。",
            ["ContentKR"] = "맞아! 그래서 아주 오래전 많은 사람이 위험을 무릅쓰고 의뢰를 받아 월석을 캐러 왔지.",
            ["DialogueId"] = 10104807,
            ["GUID"] = "194BDBE6",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104808,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101048/194BDBE6",
            },
        [10104808] = {
            ["Content"] = "不过大商人和帝国先后接管了这附近的矿区，普通人就没什么机会碰到月石了……",
            ["ContentKR"] = "하지만 거상과 제국이 이 부근의 광산을 차례로 접수하면서 일반인들은 월석을 마주할 기회를 잃게 됐어... 거기다 이 근처 광맥도 점점 고갈됐고 말이야.",
            ["DialogueId"] = 10104808,
            ["GUID"] = "194BDC10",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104815,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101048/194BDC10",
            },
        [10104809] = {
            ["Content"] = "不过呢，靠接取委托为生的狩月人，还是作为一种特色职业保留了下来，只是委托的种类呢就五花八门啦。",
            ["ContentKR"] = "하지만 그렇게 의뢰를 받아 생계를 유지하는 월석 사냥꾼은 여전히 특별한 직업으로 남아있어. 물론 의뢰 종류는 더 다양해졌지만.",
            ["DialogueId"] = 10104809,
            ["GUID"] = "194BDC3A",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104810,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101048/194BDC3A",
            },
        [10104810] = {
            ["Content"] = "大到从秽兽的魔爪下保护城市，小到从狗嘴里抢刚出炉的面包……",
            ["ContentKR"] = "크게는 필토이드의 마수에서 도시를 보호하고, 작게는 개가 물고 가려는 갓 구운 빵을 빼앗는 것까지 있거든...",
            ["DialogueId"] = 10104810,
            ["GUID"] = "194BDC64",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104811,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101048/194BDC64",
            },
        [10104811] = {
            ["Content"] = "和狗抢面包？",
            ["ContentKR"] = "개와 빵을 두고 다툰다고?",
            ["DialogueId"] = 10104811,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194BDC8E",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104812,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101048/194BDC8E",
            },
        [10104812] = {
            ["Content"] = "还有一些更可怕的，比如让自己讨厌的家伙再也不会出现……",
            ["ContentKR"] = "더 무서운 것도 있어. 예를 들면 자기가 싫어하는 사람을 다시는 눈앞에 나타나지 못하게 하는 거라던가",
            ["DialogueId"] = 10104812,
            ["GUID"] = "194BDCB8",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104813,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101048/194BDCB8",
            },
        [10104813] = {
            ["Content"] = "可是，跑一趟水仙平原的功夫，面包不是早就被狗吃掉了吗？",
            ["ContentKR"] = "하지만 아스포델에 다녀오는 사이에 개가 빵을 다 먹어 치우지 않을까?",
            ["DialogueId"] = 10104813,
            ["GUID"] = "194BDCE2",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104814,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101048/194BDCE2",
            },
        [10104814] = {
            ["Content"] = "你们两个能不能别再关心狗啦！",
            ["ContentKR"] = "이봐, 너희 둘! 지금 개가 중요한 게 아니잖아!",
            ["DialogueId"] = 10104814,
            ["GUID"] = "194BDD0C",
            ["GuideFacialId"] = "Angry",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101048/194BDD0C",
            },
        [10104815] = {
            ["Content"] = "再后来，这附近的矿脉也渐渐枯竭掉了，比如现在这座格雷姆废矿……",
            ["ContentKR"] = "그 후에 이 부근 광맥도 점점 고갈됐어. 지금 이 글로스터 폐광처럼...",
            ["DialogueId"] = 10104815,
            ["GUID"] = "194BDC11",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104816,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101048/194BDC11",
            },
        [10104816] = {
            ["Content"] = "对呀，好可惜哦！否则小仆从就能靠卖月石大赚一笔了。",
            ["ContentKR"] = "맞아, 정말 아쉽다니까! 안 그랬으면 시종도 월석을 팔아 큰돈을 벌 수 있었을 텐데.",
            ["DialogueId"] = 10104816,
            ["GUID"] = "194BDC12",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104809,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101048/194BDC12",
            },
        [10104901] = {
            ["Content"] = "没事吧？",
            ["ContentKR"] = "괜찮아?",
            ["DialogueId"] = 10104901,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194BEB52",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104902,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101049/194BEB52",
            },
        [10104902] = {
            ["Content"] = "……！！",
            ["ContentKR"] = "......!!",
            ["DialogueId"] = 10104902,
            ["GUID"] = "194BEB7C",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104903,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101049/194BEB7C",
            },
        [10104903] = {
            ["Content"] = "我刚刚突然看不清东西，没想到竟然惊动了它……抱歉！",
            ["ContentKR"] = "방금 갑자기 앞이 잘 안보여서 필토이드를 놀라게 해 버렸네... 정말 미안해!",
            ["DialogueId"] = 10104903,
            ["GUID"] = "194BEBA6",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104904,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101049/194BEBA6",
            },
        [10104904] = {
            ["Content"] = "现在好些了吗？",
            ["ContentKR"] = "이제 좀 괜찮아?",
            ["DialogueId"] = 10104904,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194BEBD0",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104905,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101049/194BEBD0",
            },
        [10104905] = {
            ["Content"] = "嗯，没问题了。",
            ["ContentKR"] = "응, 괜찮아.",
            ["DialogueId"] = 10104905,
            ["GUID"] = "194BEBFA",
            ["GuideFacialId"] = "Angry",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104906,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101049/194BEBFA",
            },
        [10104906] = {
            ["Content"] = "好。可以战斗的话，一起来对付这个大块头。",
            ["ContentKR"] = "좋아, 싸울 수 있으면 이 덩치 큰 놈을 같이 상대해 보자.",
            ["DialogueId"] = 10104906,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194BEC24",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104907,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101049/194BEC24",
            },
        [10104907] = {
            ["Content"] = "明白了！我会尽我所能支援你。",
            ["ContentKR"] = "알았어! 최선을 다해 널 도울게.",
            ["DialogueId"] = 10104907,
            ["GUID"] = "194BEC4E",
            ["GuideFacialId"] = "Angry",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101049/194BEC4E",
            },
        [10105001] = {
            ["Content"] = "我听说多凶猛的野兽，只要能找到<H>弱点</>，就能打败……",
            ["ContentKR"] = "아무리 흉폭한 녀석이라도 <H>약점</>만 찾는다면, 무찌를 수 있다고 했어...",
            ["DialogueId"] = 10105001,
            ["GUID"] = "194BFBB9",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10105002,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101050/194BFBB9",
            },
        [10105002] = {
            ["Content"] = "秽兽一定也是这样！我们冷静下来……想办法找找它的弱点吧。",
            ["ContentKR"] = "필토이드도 마찬가지야! 차분히 생각하자... 약점을 찾는 거야.",
            ["DialogueId"] = 10105002,
            ["GUID"] = "194BFBBA",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101050/194BFBBA",
            },
        [10105101] = {
            ["Content"] = "它变迟钝了。{nickname}，<H>看起来像肩膀的位置</>就是它的弱点！",
            ["ContentKR"] = "움직임이 느려졌어. {nickname}, 아무래도 <H>어깨 부위</>가 약점인 것 같아!",
            ["DialogueId"] = 10105101,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194C0C4C",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101051/194C0C4C",
            },
        [10105201] = {
            ["Content"] = "它停下来了——趁这个机会！",
            ["ContentKR"] = "멈췄다, 바로 지금이야!",
            ["DialogueId"] = 10105201,
            ["GUID"] = "194C1C8A",
            ["GuideFacialId"] = "Angry",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10105202,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101052/194C1C8A",
            },
        [10105202] = {
            ["Content"] = "太好了……！",
            ["ContentKR"] = "정말 다행이야...!",
            ["DialogueId"] = 10105202,
            ["GUID"] = "194C1CB4",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101052/194C1CB4",
            },
        [10105301] = {
            ["Content"] = "群星绮晶……真漂亮！难怪大家都喜欢。",
            ["ContentKR"] = "반짝이는 수정이라... 이렇게 아름다우니 다들 좋아하지.",
            ["DialogueId"] = 10105301,
            ["GUID"] = "194C2CF2",
            ["SpeakNpcId"] = 200021,
            ["SpeakNpcName"] = "UI_Npc_Name_Man_17",
            ["VoiceName"] = "voice/$Locale$/story/1002/101053/194C2CF2",
            },
        [10105302] = {
            ["Content"] = "刚刚这边好大的动静——该不会是你们搞定了那个大家伙？有两下子嘛。",
            ["ContentKR"] = "설마 방금 그 소리가... 너희가 저 덩치를 해치우면서 난 거였어? 꽤 하는걸?",
            ["DialogueId"] = 10105302,
            ["GUID"] = "194C2D1C",
            ["SpeakNpcId"] = 200021,
            ["SpeakNpcName"] = "UI_Npc_Name_Man_17",
            ["VoiceName"] = "voice/$Locale$/story/1002/101053/194C2D1C",
            },
        [10105401] = {
            ["Camera"] = "-29.328125,-255.251953,164.21875,0.001081,-14.107393,94.226692,50.000008,544.145996,false,Manual,5.0",
            ["Content"] = "奥特赛德？！你装什么傻，绮晶怎么会在你手里？是我家小仆从先——",
            ["ContentKR"] = "아웃사이더?! 장난치지 마. 반짝이는 수정이 어떻게 네 손에 있는데? 그건 우리 시종이 먼저...",
            ["DialogueId"] = 10105401,
            ["FacialId"] = {
                [1] = "200021:Smile02",
                [2] = "200002:Angry01",
                },
            ["FinalCamera"] = "-3.181641,-258.998047,197.030273,0.001091,-23.507626,104.626007,50.000008,311.108795,false,Manual,5.0",
            ["GUID"] = "194C3D5A",
