        [10105428] = {
            ["Camera"] = "-1728.742188,5596.728516,1904.164062,0.001424,-17.799246,-151.3983,45.0,354.288879,false,DoNotOverride,10.0",
            ["Content"] = "要不是碰上这怪物，它们的主人没准还好端端地坐在水仙平原，喝着酒，吹着牛。",
            ["ContentKR"] = "이 괴물을 안 만났으면 지금쯤 그 사람들도 아스포델에서 술이나 즐기고 있었겠지.",
            ["DialogueId"] = 10105428,
            ["FinalCamera"] = "-1728.742188,5596.728516,1904.164062,0.001424,-17.799246,-151.3983,48.0,354.288879,false,DoNotOverride,10.0",
