            },
        [10105442] = {
            ["Camera"] = "84.869141,80.519531,138.115234,0.000074,-0.799583,168.758072,50.0,167.178925,false,Manual,5.0",
            ["Content"] = "大部分卡戎之民就没那么幸运了，最多就是身体变得结实一些。据说还有少数人会变得很可怕，不过我没有亲眼见过！",
            ["ContentKR"] = "모든 카론이 그렇게 운이 좋은 건 아니야. 기껏해야 몸이 좀 더 튼튼해지는 정도지. 일부는 아주 무섭게 변한다고 하는데, 나도 직접 본 적은 없어!",
            ["DialogueId"] = 10105442,
            ["FacialId"] = {
                [1] = "200006:Sad01",
                },
            ["FinalCamera"] = "82.318359,69.537109,138.115234,0.000074,-0.799583,163.757156,50.0,167.178925,false,Manual,5.0",
