                [1] = "200005:n(200059)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101058/194C7F24",
            },
        [10105803] = {
            ["Content"] = "你应该留在修普诺斯之家，而不是跟在这个来路不明的小鬼后面。你不知道{性别：他|她}是什么底细，同样地，{性别：他|她}也没{性别：他|她}想象得那么了解你。",
            ["ContentKR"] = "히프노스의 집에 있었어야지, 왜 정체도 불분명한 녀석을 따라간 것이냐. 너도, 이 녀석도 서로가 어디서 뭘 한 누군지 모르지 않느냐.",
            ["DialogueId"] = 10105803,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194C7F4E",
            ["NextDialogue"] = 10105804,
            ["Scripts"] = "PARA{\
SEQ{\
SetLocation{ActorId{100001},TargetPoint{\"P10105801Nvzhu2\"},Visibility{\"Hide\"}},\
PlayAnimation{_delay{2},ActorId{200005},AnimationId{\"SpecialThink_End\"},Duration{4.5}},\
PlayAnimation{ActorId{200005},AnimationId{\"Disagree\"},Duration{4.5}},\
