        [10105806] = {
            ["Camera"] = "-146.253906,8.684082,132.574219,0.000076,6.199974,-15.00077,35.0,195.174042,false,Manual,4.235867",
            ["Content"] = "先别管绮晶。进修普诺斯之家的第一天，我跟你说过什么，还记得吗？",
            ["ContentKR"] = "수정은 신경 쓰지 말거라. 히프노스의 집에 들어온 첫날 내가 뭐라고 했는지 기억하니?",
            ["DialogueId"] = 10105806,
            ["GUID"] = "194C7FCC",
            ["NextDialogue"] = 10105807,
            ["Scripts"] = "SEQ{\
