            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/1002/101058/194C8020",
            },
        [10105809] = {
            ["Camera"] = "178.701172,37.807617,161.741211,0.000015,-4.800045,-164.274582,75.000015,266.881348,false,Manual,10.075966",
            ["Content"] = "如果耽误了正事，或者被旁人看出来什么……你知道后果。",
            ["ContentKR"] = "만약 일을 그르치거나, 다른 사람들이 뭔가 눈치채기라도 하면... 어떻게 될지 너도 잘 알잖니.",
            ["DialogueId"] = 10105809,
