                },
            ["SpeakNpcId"] = 200005,
            ["VoiceName"] = "voice/$Locale$/story/1002/101058/194C80C8",
            },
        [10105814] = {
            ["Camera"] = "-248.442383,-210.168945,153.489746,0.000127,-3.200374,44.998043,35.000008,345.865082,false,Manual,5.41403",
            ["CameraBlendCurve"] = "easeInQuad",
            ["Content"] = "她不是你的女儿。就算是，你也不该连这点自由都不给她。你知道出一趟门她有多开心吗？",
            ["ContentKR"] = "프시케는 당신 딸도 아니잖아요. 설령 그렇다 해도 이 정도 자유는 줘야죠. 프시케가 오늘 나가서 얼마나 즐거워했는지 아세요?",
            ["DialogueId"] = 10105814,
            ["ExStoryInfo"] = "Player",
            ["FinalCamera"] = "-248.442383,-210.168945,153.489746,0.000127,-3.000386,39.998112,35.000008,345.865082,false,Manual,5.41403",
            ["GUID"] = "194C80F2",
            ["NextDialogue"] = 10105816,
            ["Scripts"] = "SEQ{\
