        [10105901] = {
            ["Content"] = "恩里克这家伙，一开口还是这么让人火大……",
            ["ContentKR"] = "헨릭 저 녀석, 계속 화나게 만드는 말만 하네...",
            ["DialogueId"] = 10105901,
            ["Duration"] = 3,
            ["GUID"] = "194C8F62",
            ["GuideFacialId"] = "Angry",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10105902,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101059/194C8F62",
            },
        [10105902] = {
            ["Content"] = "但愿他不会责骂赛琪。",
            ["ContentKR"] = "프시케를 혼내지 않기만 바랄 뿐이야.",
            ["DialogueId"] = 10105902,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194C8F8C",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10105903,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101059/194C8F8C",
            },
        [10105903] = {
            ["Content"] = "至于是不是住在宅子里的最后一晚，得要去找奥特赛德了。",
            ["ContentKR"] = "정말 저택에서의 마지막 밤이 될지는 아웃사이더를 찾아가 보면 알겠지.",
            ["DialogueId"] = 10105903,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194C8FB6",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10105904,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101059/194C8FB6",
            },
        [10105904] = {
            ["Content"] = "要绕开我说悄悄话对吧？奥特赛德事儿真多。",
            ["ContentKR"] = "날 따돌리고 둘이서 말하려는 거지? 아웃사이더도 가만 보면 정말 소심하다니까.",
            ["DialogueId"] = 10105904,
            ["Duration"] = 3,
            ["GUID"] = "194C8FE0",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10105905,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101059/194C8FE0",
            },
        [10105905] = {
            ["Content"] = "哼，我还不稀罕听呢！你走吧，我要去水仙平原玩了。",
            ["ContentKR"] = "흥, 어차피 듣고 싶지도 않거든! 가, 난 아스포델에 놀러 갈 거야.",
            ["DialogueId"] = 10105905,
            ["Duration"] = 3,
            ["GUID"] = "194C900A",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101059/194C900A",
            },
