        [10106006] = {
            ["Camera"] = "370.792603,91.521484,112.964844,0.000431,7.607048,-73.383011,35.0,223.797852,false,Manual,14.35696",
            ["Content"] = "我哪里都没去。今天可是菲娜小姐的生日啊，我一直待在冰湖城。",
            ["ContentKR"] = "아무 데도 안 갔어. 오늘은 피나 생일이잖아. 아이스레이크 시티에 계속 있었지.",
            ["DialogueId"] = 10106006,
            ["GUID"] = "194CA09C",
