            ["TalkActionId"] = {
                [1] = "100001:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101061/194CB0DA",
            },
        [10106104] = {
            ["Content"] = "我叫{nickname}，你好。",
            ["ContentKR"] = "안녕, {nickname}(이)라고 해. 만나서 반가워.",
            ["DialogueId"] = 10106104,
            ["GUID"] = "10106104",
            ["NextDialogue"] = 10106105,
            },
        [10106105] = {
            ["Camera"] = "392.718933,-45.626953,133.417969,0.000022,-8.587979,133.589279,20.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你好！我是菲娜，奥特赛德的妹妹……咳、咳！",
            ["ContentKR"] = "안녕! 나는 피나야. 아웃사이더의 여동생이야... 콜록, 콜록!",
            ["DialogueId"] = 10106105,
            ["FacialId"] = {
                [1] = "200020:Happy01",
                },
            ["GUID"] = "194CB0DB",
            ["LookAt"] = {
