        [10106109] = {
            ["Camera"] = "501.11377,-161.582031,158.515625,0.000135,2.209382,-66.61792,40.0,552.96875,false,DoNotOverride,5.0",
            ["Content"] = "没事吧，我给你倒点热水。",
            ["ContentKR"] = "괜찮아? 바로 뜨거운 물 올릴테니까...",
            ["DialogueId"] = 10106109,
            ["FacialId"] = {
                [1] = "200021:Sad01",
                },
            ["GUID"] = "194CB12E",
            ["NextDialogue"] = 10106110,
