            },
        [10106110] = {
            ["Camera"] = "590.448242,-478.587891,143.261719,0.000085,-4.187855,118.580727,45.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "不用，我没事的！只是，难得有奥特赛德的朋友来，我很开心。你也一起来参加茶会吧？我会分给你甜甜的蛋糕。",
            ["ContentKR"] = "아냐, 난 괜찮아. 오랜만의 아웃사이더 친구라니 즐거워서 그래. 같이 다과회나 열까? 달콤한 케이크도 있으니까.",
            ["DialogueId"] = 10106110,
            ["FacialId"] = {
                [1] = "200020:Happy01",
                },
            ["GUID"] = "194CB158",
            ["LookAt"] = {
                [1] = "200020:n(200021)",
