        [10106202] = {
            ["Camera"] = "-6.599731,-145.632812,140.769531,0.000156,-3.591819,17.001183,30.0,555.360596,false,DoNotOverride,4.01182",
            ["Content"] = "{性别：大哥哥|大姐姐}，怎么了？",
            ["ContentKR"] = "{性别:오빠|언니}, 왜 그래?",
            ["DialogueId"] = 10106202,
            ["ExStoryInfo"] = "Player",
            ["FinalCamera"] = "-14.872528,-148.162109,141.300781,0.000156,-3.591819,17.001348,30.000002,555.360596,false,DoNotOverride,4.01182",
            ["GUID"] = "194CC0C4",
            ["LookAt"] = {
                [1] = "100001:n(200020)",
                },
            ["NextDialogue"] = 10106203,
            ["SpeakNpcId"] = 200020,
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1002/101062/194CC0C4",
            },
        [10106203] = {
            ["Camera"] = "275.194794,306.837891,122.601562,0.000144,-0.389526,-86.22683,50.0,393.914001,false,Manual,3.873447",
            ["Content"] = "没什么。只是味道很甜，让我想起了一个人……我的家人。她总是会在饭菜里放很多很多糖。",
            ["ContentKR"] = "아무것도 아니야. 그냥 달콤한 맛에 한 사람이 생각 나서... 내 가족인데 항상 음식에 설탕을 엄청 넣었거든.",
            ["DialogueId"] = 10106203,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "100001:Smile02",
                },
            ["FinalCamera"] = "273.907379,326.357422,122.730469,0.000156,-0.389526,-86.226807,50.000008,393.914001,false,Manual,3.873447",
            ["GUID"] = "194CC0EE",
            ["NextDialogue"] = 10106204,
            ["Scripts"] = "SEQ{\
LookAt{_delay{2.5},LookAtDescription{\"100001:n(200020)\"}},\
PlayFacial{ActorId{100001},FacialId{\"Sad01\"}},\
LookAt{_delay{3.5},LookAtDescription{\"100001:p(P101060Cake)\"}}\
}",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/1002/101062/194CC0EE",
            },
        [10106204] = {
            ["Content"] = "我们长大的那座小岛，最不缺鱼和盐，但是糖的价格却有些昂贵。所以小的时候，我们是从来都吃不到糖的。",
            ["ContentKR"] = "우리가 자란 작은 섬은 생선과 소금은 넘쳐났지만, 설탕은 비싸서 어릴 때부터 단 걸 맛보기 힘들었어서.",
            ["DialogueId"] = 10106204,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["GUID"] = "194CC118",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10106204.T_Story_Recall_10106204'",
            ["LookAt"] = {
                [1] = "100001:n(100001)",
                },
            ["NextDialogue"] = 10106205,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101062/194CC118",
            },
        [10106205] = {
            ["Camera"] = "225.539108,-21.537109,188.570312,0.000213,-25.98712,-68.410789,50.0,111.523781,false,Manual,7.19876",
            ["Content"] = "她只是个比我年长几岁的女孩子，很小的时候，她就去隔壁的渔夫那里做帮工了。",
            ["ContentKR"] = "나보다 고작 몇 살 많은 여자아이였는데, 아주 어릴 때 옆집 어부의 조수가 되어서 일을 시작했어.",
            ["DialogueId"] = 10106205,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "100001:Sad01",
                },
            ["GUID"] = "194CC142",
            ["NextDialogue"] = 10106206,
            ["Scripts"] = "PARA{\
LookAt{_delay{1.5},LookAtDescription{\"100001:p(P101062)\"}},\
