            },
        [10107018] = {
            ["Camera"] = "-239.527344,-76.267822,140.667969,0.000016,-1.799352,15.204823,35.000008,357.107239,false,Manual,4.7",
            ["Content"] = "昨晚恩里克先生的脸色很差。他没有凶你吧？",
            ["ContentKR"] = "어젯밤에 헨릭 씨 표정이 안 좋았잖아. 화를 내거나 그러진 않았지?",
            ["DialogueId"] = 10107018,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "100001:Angry01",
                [2] = "200006:None",
                },
            ["FinalCamera"] = "-258.751953,-81.134766,141.289062,0.000016,-1.799365,14.20413,35.000008,357.107239,false,Manual,4.773073",
            ["GUID"] = "194D467A",
            ["NextDialogue"] = 10107019,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1002/101070/194D467A",
            },
        [10107019] = {
            ["Camera"] = "98.041016,134.36499,152.681641,0.000016,-2.19958,-125.604164,55.000008,235.416611,false,Manual,10.570968",
            ["Content"] = "没有没有。恩里克叔叔只是有些……不善言辞。毕竟他大多数时间都一个人闷在办公室里搞他的研究，很少和别人说话……",
            ["ContentKR"] = "아냐, 아냐. 헨릭 아저씨는 그냥... 대화가 서툰 거야. 연구 때문에 대부분의 시간을 혼자 사무실에서 보내느라, 다른 사람과는 거의 말을 나누지 않거든...",
            ["DialogueId"] = 10107019,
            ["FinalCamera"] = "114.261719,157.031006,153.753906,0.000001,-2.199615,-125.60421,55.0,235.416611,false,Manual,4.291738",
