        [10107106] = {
            ["Camera"] = "70.351562,-398.249817,694.277344,0.0,-0.800252,89.591064,25.0,100000.0,false,DoNotOverride,2.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "……清理。打扫。每天一遍，每一层书架和每一扇门。全部擦干净。",
            ["ContentKR"] = "...정리하고 청소 중이야. 매일 모든 층의 책꽂이와 문을 깨끗하게 닦거든.",
            ["DialogueId"] = 10107106,
            ["FacialId"] = {
