            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101076/194DA64A",
            },
        [10107701] = {
            ["Content"] = "……你走吧。",
            ["ContentKR"] = "...그만 가봐.",
