}",
            ["SpeakNpcId"] = 200021,
            ["ToFinalCameraBlendTime"] = 12,
            ["VoiceName"] = "voice/$Locale$/story/1002/101078/194DC966",
            },
        [10107816] = {
            ["Camera"] = "40.309082,-165.490234,149.889648,0.000082,-6.199803,104.007965,35.000008,251.467529,false,Manual,8.0",
            ["Content"] = "过去体格并不算好，但是最近开始有所长进了。",
            ["ContentKR"] = "예전엔 체력이 좋지 않았지만, 최근에 좀 나아지기 시작했어.",
            ["DialogueId"] = 10107816,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "100001:Ahaha02",
                },
            ["GUID"] = "194DC990",
            ["NextDialogue"] = 10107817,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk03_Start",
                [2] = "200021:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101078/194DC990",
            },
        [10107817] = {
            ["Camera"] = "66.280518,143.457031,91.727539,0.000016,11.199843,-111.197601,35.000008,244.047409,false,Manual,5.0",
            ["Content"] = "好。那么接下来的几天，我也教你一些格斗的技巧吧——有备无患。",
            ["ContentKR"] = "좋아. 그럼 앞으로 며칠간 나도 너한테 싸우는 기술을 좀 가르쳐 줄게. 미리 준비하는 거지.",
            ["DialogueId"] = 10107817,
            ["FacialId"] = {
                [1] = "200021:Confident01",
                },
