        [10107819] = {
            ["Camera"] = "351.825439,503.387695,167.38916,0.000006,-7.200166,-124.993027,30.000002,446.696014,false,DoNotOverride,3.0",
            ["CameraBlendCurve"] = "easeInQuad",
            ["Content"] = "对了，下次见到卡米拉的时候也和她知会一声吧，就说我们暂时结成了小队。这样一起行动会方便些。",
            ["ContentKR"] = "그리고 다음에 카밀라를 만나면 우리가 임시로 팀을 꾸렸다고 알려줘. 그러면 함께 행동하기 편할 거야.",
            ["DialogueId"] = 10107819,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["FinalCamera"] = "351.825439,503.387695,111.700684,0.000005,-3.199944,-124.99308,30.000002,446.696014,false,DoNotOverride,3.0",
            ["GUID"] = "194DC9E5",
            ["NextDialogue"] = 10107820,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Think_End",
                },
            ["ToFinalCameraBlendTime"] = 9,
            ["VoiceName"] = "voice/$Locale$/story/1002/101078/194DC9E5",
            },
        [10107820] = {
            ["Camera"] = "-9.021729,-26.742188,128.609863,0.000102,5.600222,80.398033,35.0,95.583733,false,Manual,5.0",
            ["Content"] = "（……时候还早，或许我可以看看有没有什么能接的委托……）",
            ["ContentKR"] = "(...아직 시간이 좀 이른데, 또 받을 만한 의뢰가 있나 살펴볼까...)",
            ["DialogueId"] = 10107820,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194DD782",
            ["LookAt"] = {
