            ["NextDialogue"] = 10107821,
            ["Scripts"] = "SetLocation{ActorId{200021},TargetPoint{\"101078Point1\"},Visibility{\"Hide\"}}",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101079/194DD782",
            },
        [10107821] = {
            ["Content"] = "（……还有，赛琪看起来有些孤独。有机会的话，离开冰湖城之前，也去陪她说说话吧。）",
            ["ContentKR"] = "(그리고 프시케가 좀 외로워 보이던데. 기회가 되면 아이스레이크 시티를 떠나기 전에 가서 이야기나 나눠볼까.)",
            ["DialogueId"] = 10107821,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194DD783",
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{100001},AnimationId{\"Think_Start\"},Duration{1}},\
PlayAnimation{_delay{2},ActorId{100001},AnimationId{\"Think_End\"},Duration{1}}\
}",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101078/194DD783",
            },
