        [10108002] = {
            ["Content"] = "一个坏消息，和一个——呃，或许应该也算是坏消息。",
            ["ContentKR"] = "나쁜 소식 하나와 또 하나의... 으음, 어쩌면 이것도 나쁜 소식일 수 있겠군요.",
            ["DialogueId"] = 10108002,
            ["GUID"] = "194DE814",
            ["NextDialogue"] = 10108003,
            ["Scripts"] = "PARA{\
SEQ{\
CameraMoveTo{_delay{3.5},TargetPosition{\"-128.663086,624.128906,1.964844,0.000055,-11.999959,57.393639,30.000002,195.345673,false,Manual,3.030511\"},duration{0}},\
CameraMoveTo{TargetPosition{\"-128.663086,624.128906,-0.25,0.00007,-11.999959,57.393517,30.000008,195.345673,false,Manual,3.030511\"},duration{2}}\
