        [10108312] = {
            ["Camera"] = "-28.867188,60.662109,122.698242,0.000077,0.402216,-42.205906,35.000008,149.242798,false,Manual,4.0",
            ["Content"] = "这是什么？这个声音……怎么像是你在鬼叫？",
            ["ContentKR"] = "이게 뭐지? 이 소리는... 꼭 네가 우는 소리 같은데?",
