        [10108313] = {
            ["Camera"] = "196.914062,-106.330078,121.105469,0.000192,1.199682,145.998581,50.0,303.34079,false,Manual,8.0",
            ["Content"] = "拾荒小妹那里淘来的破铜烂铁。别说，还挺结实的，不花点儿时间还真打不穿。正适合在里面塞个扩音器，把它们引过来——",
            ["ContentKR"] = "넝마주이 동생한테서 구해온 고철 덩어리야. 이래 봬도 꽤 단단해서 금방 구멍이 뚫리진 않을 거야. 안에 확성기를 끼워 넣으면 저것들을 끌어들이기에 딱이지!",
            ["DialogueId"] = 10108313,
            ["FacialId"] = {
                [1] = "200021:Smile01",
                },
            ["FinalCamera"] = "202.421875,-97.979248,121.105469,0.000192,1.199654,147.997437,50.0,303.34079,false,Manual,8.0",
            ["GUID"] = "19516E96",
            ["NextDialogue"] = 10108314,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Give",
                [2] = "100001:Shock_End",
                },
            ["ToFinalCameraBlendTime"] = 11,
            ["VoiceName"] = "voice/$Locale$/story/1002/101135/19516E96",
            },
        [10108314] = {
            ["Camera"] = "-349.433594,-129.305176,85.915527,0.000037,0.200002,21.990885,25.0,400.144287,false,Manual,2.0",
            ["CameraBlendCurve"] = "easeOutQuad",
            ["Content"] = "嘿，看那边，小可爱、大可爱们来喽！",
            ["ContentKR"] = "저기 봐. 귀염둥이들이 왔잖아!",
            ["DialogueId"] = 10108314,
            ["FinalCamera"] = "-390.789062,-152.256104,373.813477,0.000045,-22.999779,21.590296,25.000002,5027.468262,false,Manual,2.0",
