        [10108502] = {
            ["Camera"] = "-115.567871,-338.226562,281.567627,0.000205,-25.200125,66.302895,40.000011,546.789001,false,Manual,2.0",
            ["Content"] = "奥特赛德真是个坏东西，非得让我在这里盯梢。本魔王的一身本事是为了带领你们打猎，才不是为了在这里盯着那个阴沉大叔！",
            ["ContentKR"] = "굳이 날 여기서 감시나 하게 하다니! 아웃사이더, 넌 정말 나쁜 놈이야. 이 마왕님의 능력은 너희를 데리고 사냥을 나가기 위한 거지, 여기 숨어서 저 음침한 아저씨나 지켜보는 게 아니라고!",
            ["DialogueId"] = 10108502,
            ["FacialId"] = {
                [1] = "200064:Doubt01",
                },
            ["FinalCamera"] = "-99.011719,-300.50293,244.98291,0.000237,-21.799927,66.303619,40.000011,483.54599,false,Manual,2.0",
            ["GUID"] = "194E3A1C",
            ["LookAt"] = {
                [1] = "200064:n(200021)",
                },
            ["NextDialogue"] = 10108503,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{200064},AnimationId{\"SpecialConfident_End\"},Duration{1}},\
