            ["ToFinalCameraBlendTime"] = 12,
            ["VoiceName"] = "voice/$Locale$/story/1002/101085/194E3A1C",
            },
        [10108503] = {
            ["Camera"] = "-98.271973,73.517578,107.652588,0.000086,12.605715,-48.246983,50.0,203.457687,false,Manual,8.0",
            ["Content"] = "这不是看魔王大人您天赋异禀，更方便隐匿行踪嘛。您看我们这么五大三粗的，要是恩里克出来，随便扫一眼不就暴露了。",
            ["ContentKR"] = "마왕님은 타고난 재능 덕에 잘 들키지도 않고 좋잖아~ 우리 같이 우락부락한 것들은 헨릭이 나와서 대충 훑어만 봐도 바로 눈에 띈다고~",
            ["DialogueId"] = 10108503,
            ["FacialId"] = {
                [1] = "200021:Smile02",
                [2] = "100001:Smile02",
                },
            ["FinalCamera"] = "-97.125,82.003906,106.376465,0.000081,12.805723,-50.447262,50.0,211.465363,false,Manual,8.0",
            ["GUID"] = "194E3A46",
            ["NextDialogue"] = 10108504,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{200021},AnimationId{\"Explain01_Start\"},Duration{3.3}},\
PlayAnimation{ActorId{200021},AnimationId{\"Explain01_End\"},Duration{1.6}},\
PlayAnimation{ActorId{200021},AnimationId{\"Explain02_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200064:Bai_Idle",
                },
            ["ToFinalCameraBlendTime"] = 11,
            ["VoiceName"] = "voice/$Locale$/story/1002/101085/194E3A46",
            },
        [10108504] = {
            ["Camera"] = "28.857422,-61.823242,137.124268,0.000146,-17.4002,77.194801,50.0,180.819702,false,Manual,8.0",
            ["Content"] = "哼，居然知道夸本大人，看来你还是挺聪明——不对！你是在变着法子说我个子矮吧！！",
            ["ContentKR"] = "흥, 이 마왕님 칭찬도 다 하고, 그래도 똑똑한 거 같네... 아니지! 내가 키가 작다고 놀린 거지!!",
            ["DialogueId"] = 10108504,
            ["FacialId"] = {
                [1] = "200064:Happy02",
                },
            ["FinalCamera"] = "32.961914,-44.213867,131.525879,0.000162,-17.200184,76.594582,50.0,160.226791,false,Manual,8.0",
            ["GUID"] = "194E3A70",
            ["NextDialogue"] = 10108505,
