        [10108704] = {
            ["Camera"] = "742.229492,179.731445,413.833496,0.000161,-34.997704,-137.795181,30.0,317.800873,false,DoNotOverride,5.0",
            ["Content"] = "啊！怎么会是空的！",
            ["ContentKR"] = "어라! 비어 있잖아!",
            ["DialogueId"] = 10108704,
            ["FacialId"] = {
                [1] = "100001:Shock02",
                [2] = "200002:Shock02",
                },
            ["GUID"] = "194E5B16",
