                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101087/194E5BE8",
            },
        [10108801] = {
            ["Content"] = "与此同时，修普诺斯之家——",
            ["ContentKR"] = "같은 시각 히프노스의 집...",
            ["DialogueId"] = 10108801,
            ["Duration"] = 5,
            ["GUID"] = "194E6B2A",
            ["VoiceName"] = "voice/$Locale$/story/1002/101088/194E6B2A",
            },
        [10108901] = {
            ["Camera"] = "-274.201172,432.903809,147.820312,0.000363,2.80673,-42.981243,64.455444,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "咳、咳！",
