        [10109009] = {
            ["Camera"] = "46.280029,5.457031,149.058594,0.000183,0.999714,-140.175919,45.0,163.680023,false,Manual,8.0",
            ["Content"] = "“一个人离我而去，而我什么都做不到”。是吗？",
            ["ContentKR"] = "'누군가를 잃었지만, 아무것도 할 수 없었다'는 건가?",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 10109009,
            ["FacialId"] = {
                [1] = "200021:None",
                },
            ["FinalCamera"] = "46.280029,5.457031,149.058594,0.000183,0.999714,-140.175919,48.0,163.680023,false,Manual,8.0",
