            },
        [10109018] = {
            ["Camera"] = "-64.027588,-77.358398,149.785156,0.000002,-4.20084,22.199293,50.0,119.109459,false,Manual,5.0",
            ["CameraBlendCurve"] = "easeInQuad",
            ["Content"] = "谢谢你，我冷静下来了。我先做一些准备……不过明天，我还是要去找一趟赛琪。",
            ["ContentKR"] = "고마워, 좀 진정됐어. 일단 준비할게... 하지만 그래도 내일 프시케와 한번 이야기해 봐야겠어.",
            ["DialogueId"] = 10109018,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
