        [10109019] = {
            ["Camera"] = "-213.689941,-320.035156,233.059082,0.000065,-17.40115,53.39225,35.000008,304.896423,false,DoNotOverride,1.969391",
            ["Content"] = "……放心，我和恩里克的关系之前缓和了一些，装作什么都不知道就行。",
            ["ContentKR"] = "...안심해, 헨릭 씨와의 사이가 전보다는 좋아졌거든. 아무것도 모르는 척하면 돼.",
            ["DialogueId"] = 10109019,
