            },
        [10109020] = {
            ["Camera"] = "532.194092,-1924.368164,111.047852,0.000126,-0.401069,102.201553,50.000008,1925.386108,false,Manual,2.8",
            ["Content"] = "嗯，还得想想人救出来之后怎么办……你对冰湖城不熟，这事就交给我来办吧。",
            ["ContentKR"] = "그래, 프시케를 구한 후에 어떻게 할지도 생각해야 해... 넌 아이스레이크 시티에 대해 잘 모르니 이 일은 나한테 맡겨 줘.",
            ["DialogueId"] = 10109020,
