            ["DialogueId"] = 10109403,
            ["GUID"] = "10109403.0",
            ["NextDialogue"] = 10109404,
            },
        [10109404] = {
            ["Camera"] = "19.714844,-41.03125,94.928711,0.00024,0.189367,126.75769,20.000008,100000.0,false,DoNotOverride,22.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "真好啊。你看，旅客们是不是点起了灯？那些车窗是不是很漂亮，很温暖，像炉子里的小火苗一样？",
            ["ContentKR"] = "잘 됐다. 저기 봐, 승객들이 등불을 켰네. 저기 유리창도, 정말 예쁘고 따뜻해 보이지 않아? 화롯불 옆에 있는 것처럼 말이야.",
            ["DialogueId"] = 10109404,
            ["FacialId"] = {
                [1] = "200006:Happy02",
                },
            ["FinalCamera"] = "31.46875,-56.716797,94.905273,0.000241,-2.210632,127.157379,20.000008,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "194ECDEE",
            ["LookAt"] = {
                [1] = "100001:n(200006)",
                [2] = "200006:n(100001)",
                },
            ["NextDialogue"] = 10109407,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{200006},AnimationId{\"Explain02_Start\"},Duration{2.5}},\
PlayAnimation{ActorId{200006},AnimationId{\"Explain02_End\"},Duration{1}},\
PlayAnimation{ActorId{200006},AnimationId{\"Explain01_Start\"},Duration{2}}\
}\
",
            ["SpeakNpcId"] = 200006,
            ["ToFinalCameraBlendTime"] = 9,
            ["VoiceName"] = "voice/$Locale$/story/1002/101094/194ECDEE",
            },
        [10109405] = {
            ["Content"] = "只是风的声音。",
            ["ContentKR"] = "그저 바람 소리일 뿐이야.",
            ["DialogueId"] = 10109405,
            ["GUID"] = "10109405",
            ["NextDialogue"] = 10109406,
            },
        [10109406] = {
            ["Camera"] = "28.210938,-52.099609,95.129883,0.000245,0.989387,124.358093,20.0,100000.0,false,DoNotOverride,22.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "……原来不是啊。",
            ["ContentKR"] = "...아, 기차 소리가 아니었구나.",
            ["DialogueId"] = 10109406,
            ["FacialId"] = {
                [1] = "200006:Happy02",
                },
            ["FinalCamera"] = "13.988281,-31.232422,98.763672,0.000245,0.989387,124.358093,20.0,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "194ECE18",
            ["NextDialogue"] = 10109407,
            ["Scripts"] = "PlayAnimation{_delay{4},ActorId{200006},AnimationId{\"Explain02_End\"},Duration{1}}",
            ["SpeakNpcId"] = 200006,
            ["TalkActionId"] = {
                [1] = "200006:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 9,
            ["VoiceName"] = "voice/$Locale$/story/1002/101094/194ECE18",
            },
        [10109407] = {
            ["Camera"] = "-281.054688,-237.414062,82.333008,0.0,-2.99999,39.999969,20.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "你的眼睛……是什么时候看不清的？",
            ["ContentKR"] = "눈이... 언제부터 잘 안 보인 거야?",
            ["DialogueId"] = 10109407,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "100001:Sad01",
                },
            ["FinalCamera"] = "-281.054688,-237.414062,47.505859,0.000001,4.000004,39.999969,20.0,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "194ECE42",
            ["NextDialogue"] = 10109408,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain01_Start",
                },
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1002/101094/194ECE42",
            },
        [10109408] = {
            ["Camera"] = "97.648438,-137.328125,117.448242,0.00021,-3.611073,122.97995,50.000008,336.90625,false,Manual,7.017789",
            ["Content"] = "什么时候……",
            ["ContentKR"] = "언제부터였더라...",
            ["DialogueId"] = 10109408,
            ["GUID"] = "194ECE6C",
            ["NextDialogue"] = 10109409,
            ["SpeakNpcId"] = 200006,
            ["TalkActionId"] = {
                [1] = "200006:Sigh_Start",
                [2] = "100001:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101094/194ECE6C",
            },
        [10109409] = {
            ["Camera"] = "-173.027344,119.447266,100.172852,0.000213,0.788593,-32.62458,50.000008,287.144684,false,Manual,4.056031",
            ["CameraBlendCurve"] = "easeInQuad",
            ["Content"] = "我也不知道。我以为和从前一样，模糊一阵子就会慢慢好起来。可现在……",
            ["ContentKR"] = "나도 잘 모르겠어. 예전처럼 잠시 흐릿하다가 천천히 나아질 줄 알았는데, 지금은…",
            ["DialogueId"] = 10109409,
            ["FacialId"] = {
                [1] = "200006:Unhappy01",
                },
            ["FinalCamera"] = "-153.613281,107.021484,100.492188,0.000213,0.788593,-32.62458,50.000008,287.144684,false,Manual,4.056031",
            ["GUID"] = "194ECE6D",
            ["NextDialogue"] = 10109410,
            ["SpeakNpcId"] = 200006,
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1002/101094/194ECE6D",
            },
        [10109410] = {
            ["Camera"] = "60.910156,-67.048828,109.011719,0.000257,-3.799709,132.574326,35.0,339.966736,false,DoNotOverride,2.608581",
            ["Content"] = "不说这个了。我有一个想去的地方，你可以陪我一起吗？",
            ["ContentKR"] = "그 얘기는 안 할래... 가고 싶은 곳이 한 군데 있는데 나랑 함께 가 줄 수 있어?",
            ["DialogueId"] = 10109410,
            ["FacialId"] = {
                [1] = "200006:None",
                },
            ["GUID"] = "194ECE96",
            ["NextOptions"] = {
                [1] = 10109411,
                },
            ["Scripts"] = "PARA{\
CameraMoveTo{_delay{3.4},TargetPosition{\"-2489.960938,234.535156,332.305664,0.000228,6.999994,117.97747,20.0,339.966736,false,DoNotOverride,22\"},duration{0}},\
CameraMoveTo{_delay{3.5},TargetPosition{\"-2489.960938,234.535156,576.185547,0.000228,4.999999,117.977455,20.0,339.966736,false,DoNotOverride,22\"},duration{8}},\
SEQ{\
PlayAnimation{ActorId{200006},AnimationId{\"Sigh_End\"},Duration{1}},\
PlayAnimation{ActorId{200006},AnimationId{\"DisagreeHead\"},Duration{1}},\
PlayAnimation{ActorId{200006},AnimationId{\"Explain01_Start\"},Duration{1}},\
}\
}",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101094/194ECE96",
            },
        [10109411] = {
            ["Content"] = "好。",
            ["ContentKR"] = "응.",
            ["DialogueId"] = 10109411,
            ["GUID"] = "10109411",
            },
        [10109501] = {
            ["Content"] = "是泪湖畔，那附近有一截老树根。小时候，爸爸曾带我去过那儿。",
            ["ContentKR"] = "눈물의 호수를 가고 싶어. 그 주변에 오래된 나무 뿌리도 있는데, 어릴 때 아빠가 날 거기 데려갔었거든.",
            ["DialogueId"] = 10109501,
            ["GUID"] = "194EDE02",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10109502,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101095/194EDE02",
            },
        [10109502] = {
            ["Content"] = "……已经过去那么多年了啊……",
            ["ContentKR"] = "...벌써 몇 년이나 지난 일이지만...",
            ["DialogueId"] = 10109502,
            ["GUID"] = "194EDE2C",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101095/194EDE2C",
            },
        [10109601] = {
            ["Content"] = "我们到了。",
            ["ContentKR"] = "도착했어.",
            ["DialogueId"] = 10109601,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194EEE6A",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10109602,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101096/194EEE6A",
            },
        [10109602] = {
            ["Content"] = "树根附近……埋着一个小盒子。{nickname}，你可以帮我找找那个盒子吗？",
            ["ContentKR"] = "나무 뿌리... 주위에 작은 상자가 묻혀 있을 거야. {nickname}, 그걸 찾아줄 수 있을까?",
            ["DialogueId"] = 10109602,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194EEEBE",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101096/194EEEBE",
            },
        [10109701] = {
            ["Camera"] = "-190.949219,140.849609,112.655273,0.000004,-12.601363,-7.686144,50.0,234.678116,false,Manual,8.0",
            ["DialogueId"] = 10109701,
            ["DialoguePanelType"] = "None",
            ["GUID"] = "194EEEBF",
            ["LookAt"] = {
                [1] = "100001:n(200006)",
                [2] = "200006:n(100001)",
                },
            ["NextOptions"] = {
                [1] = 10109702,
                },
            },
        [10109702] = {
            ["Content"] = "挖到了，给。",
            ["ContentKR"] = "다 팠어, 자.",
            ["DialogueId"] = 10109702,
            ["GUID"] = "10109702.0",
            ["NextDialogue"] = 10109703,
            },
        [10109703] = {
            ["Camera"] = "109.730469,-1.478516,30.498047,0.000287,12.399074,142.316772,50.0,278.758331,false,Manual,5.0",
            ["Content"] = "你来把它打开吧。",
            ["ContentKR"] = "그걸 열어봐.",
            ["DialogueId"] = 10109703,
            ["FacialId"] = {
                [1] = "200006:Smile01",
                },
            ["GUID"] = "194EFEFC",
            ["NextDialogue"] = 10109704,
            ["SpeakNpcId"] = 200006,
            ["TalkActionId"] = {
                [1] = "200006:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101097/194EFEFC",
            },
        [10109704] = {
            ["Camera"] = "-96.394531,130.861328,78.214844,0.000252,-8.00076,-17.689077,25.0,125.918678,false,Manual,3.0",
            ["Content"] = "这是……",
            ["ContentKR"] = "이건...",
            ["DialogueId"] = 10109704,
            ["DialoguePanelType"] = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter01_Camera.T_Guide_Chapter01_Camera'}",
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "100001:Shock01",
                },
            ["GUID"] = "194EFF26",
            ["NextDialogue"] = 10109705,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101097/194EFF26",
            },
        [10109705] = {
            ["Camera"] = "330.355469,-963.607422,7.018555,-5.000005,1.19807,109.312668,50.0,1184.560059,false,Manual,3.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "它叫“照相机”，是很了不起的宝物。",
            ["ContentKR"] = "'사진기'라고 하는 거야. 엄청나게 귀한 물건이지.",
            ["DialogueId"] = 10109705,
            ["FacialId"] = {
                [1] = "200006:Smile02",
                [2] = "100001:None",
                },
            ["FinalCamera"] = "320.921875,-966.865234,7.888672,-5.000004,1.19807,108.912674,50.0,1184.560059,false,Manual,3.0",
            ["GUID"] = "194EFF50",
            ["NextDialogue"] = 10109706,
            ["SpeakNpcId"] = 200006,
            ["TalkActionId"] = {
                [1] = "200006:Talk02_Start",
                },
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/story/1002/101097/194EFF50",
            },
        [10109706] = {
            ["Camera"] = "-513.90625,86.755859,248.274414,-3.000002,-22.199732,4.520242,50.0,589.274902,false,Manual,12.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "这是四岁那年爸爸送我的。那年他培育出了很漂亮的泪湖铃兰，内城的大富豪很高兴，就随手送了这个给他，他又当做礼物送给了我。",
            ["ContentKR"] = "내가 네 살 되던 해에 아빠가 내게 주신 거야. 아빠가 눈물의 호수에 아름다운 은방울꽃을 키웠거든. 내성의 한 부자가 기뻐하면서 이걸 아빠한테 줬어. 그리고 아빠는 그걸 내 생일 선물로 주셨고.",
            ["DialogueId"] = 10109706,
            ["FacialId"] = {
                [1] = "200006:Happy02",
                },
            ["FinalCamera"] = "-513.90625,86.755859,228.629883,-3.000002,-19.999599,4.520289,50.0,589.274902,false,Manual,12.0",
            ["GUID"] = "194EFF7A",
            ["NextDialogue"] = 10109707,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{200006},AnimationId{\"Talk02_End\"},Duration{2}},\
PlayAnimation{ActorId{200006},AnimationId{\"Explain01_Start\"},Duration{2}},\
\
}",
            ["SpeakNpcId"] = 200006,
            ["ToFinalCameraBlendTime"] = 13,
            ["VoiceName"] = "voice/$Locale$/story/1002/101097/194EFF7A",
            },
        [10109707] = {
            ["Camera"] = "97.855469,26.320312,46.532227,-1.0,10.398955,146.71611,50.0,242.458954,false,Manual,8.0",
            ["Content"] = "可我舍不得用。我想，既然是珍贵的宝物，如果埋在土里，等到收获的时节，就能长出好多个相机了。那时家里就会富有起来，爸爸妈妈也就不用那么辛苦。",
            ["ContentKR"] = "아까워서 쓸 수가 없었어. 그래서 흙에다가 이 귀한 보물을 묻어 놓으면, 사진기가 여러 개 자라나 있을 줄 알았어. 그러면 집안도 부유해지고 엄마, 아빠가 덜 힘들겠다고 생각했지.",
            ["DialogueId"] = 10109707,
            ["FacialId"] = {
                [1] = "200006:None",
                },
            ["FinalCamera"] = "95.832031,23.208984,46.592773,-1.0,10.398955,145.715927,50.0,242.458954,false,Manual,8.0",
            ["GUID"] = "194EFFA4",
            ["NextDialogue"] = 10109708,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{200006},AnimationId{\"Explain01_End\"},Duration{2}},\
PlayAnimation{ActorId{200006},AnimationId{\"DisagreeHead\"},Duration{2}},\
PlayAnimation{ActorId{200006},AnimationId{\"Explain02_Start\"},Duration{2}}\
}",
            ["SpeakNpcId"] = 200006,
            ["ToFinalCameraBlendTime"] = 13,
            ["VoiceName"] = "voice/$Locale$/story/1002/101097/194EFFA4",
            },
        [10109708] = {
            ["Camera"] = "17.835938,30.003906,75.855469,0.000003,5.999706,139.000046,50.0,172.869095,false,Manual,5.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "所以我悄悄把它“种”在了这里。……那个时候的我，真是傻乎乎的。",
            ["ContentKR"] = "그래서 그걸 몰래 여기다 '심어 놓은' 거야. ...그때의 나는 참 바보 같았어.",
            ["DialogueId"] = 10109708,
            ["FinalCamera"] = "17.835938,30.003906,75.855469,0.000003,6.399723,139.000046,53.0,172.869095,false,Manual,5.0",
            ["GUID"] = "194EFFCE",
            ["NextDialogue"] = 10109709,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{200006},AnimationId{\"Explain02_End\"},Duration{1.5}},\
LookAt{LookAtDescription{\"200006:p(Point101097)\"}}\
}",
            ["SpeakNpcId"] = 200006,
            ["ToFinalCameraBlendTime"] = 7,
            ["VoiceName"] = "voice/$Locale$/story/1002/101097/194EFFCE",
            },
        [10109709] = {
            ["Camera"] = "-167.960938,132.5625,94.099609,0.000283,-8.400545,-7.686968,50.0,217.697235,false,Manual,8.0",
            ["Content"] = "不过爸爸妈妈后来并没有责怪我，而是对我说，“那就等你成年那天再把它挖出来吧，就当是给未来自己的礼物。”",
            ["ContentKR"] = "하지만 아빠, 엄마는 혼내지 않고 나한테 이렇게 말했지. \"그럼 미래의 자신에게 줄 선물이라고 여기고 네가 성년이 되는 날 다시 꺼내렴.\"",
            ["DialogueId"] = 10109709,
            ["FacialId"] = {
                [1] = "200006:Smile01",
                },
            ["FinalCamera"] = "-167.53125,135.693359,94.099609,0.000283,-8.400545,-8.887018,50.0,217.697235,false,Manual,8.0",
            ["GUID"] = "194EFFF8",
            ["LookAt"] = {
                [1] = "200006:n(100001)",
                },
            ["NextOptions"] = {
                [1] = 10109710,
                [2] = 10109711,
                },
            ["SpeakNpcId"] = 200006,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1002/101097/194EFFF8",
            },
        [10109710] = {
            ["Content"] = "是很可爱的想法。",
            ["ContentKR"] = "귀여운 생각이네.",
            ["DialogueId"] = 10109710,
            ["GUID"] = "10109710.0",
            ["NextDialogue"] = 10109712,
            },
        [10109711] = {
            ["Content"] = "大家小时候都做过傻事。",
            ["ContentKR"] = "모두 어릴 때는 바보 같은 짓을 하잖아.",
            ["DialogueId"] = 10109711,
            ["GUID"] = "10109711.0",
            ["NextDialogue"] = 10109712,
            },
        [10109712] = {
            ["Camera"] = "95.253906,26.408203,53.023438,-1.0,8.100427,144.515015,40.000011,249.648575,false,Manual,8.0",
            ["Content"] = "{nickname}，谢谢你这些天陪我，但我没有什么值钱的东西。这个相机，就当做送给你的礼物吧。",
            ["ContentKR"] = "{nickname}, 요즘 나와 같이 있어 줘서 고마워. 그런데 나한테 값비싼 물건이 없어서, 이 사진기를 선물로 줄게.",
            ["DialogueId"] = 10109712,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "200006:Smile01",
                },
            ["FinalCamera"] = "93.351562,23.771484,53.079102,-0.999999,8.100427,144.115082,40.000011,249.648575,false,Manual,8.0",
            ["GUID"] = "194F0022",
            ["NextOptions"] = {
                [1] = 10109713,
                [2] = 10109714,
                },
            ["SpeakNpcId"] = 200006,
            ["TalkActionId"] = {
                [1] = "100001:Think_End",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1002/101097/194F0022",
            },
        [10109713] = {
            ["Content"] = "这不是你的宝物吗？太贵重了。",
            ["ContentKR"] = "이건 네 보물이잖아. 너무 귀한 거야.",
            ["DialogueId"] = 10109713,
            ["GUID"] = "10109713.0",
            ["NextDialogue"] = 10109715,
            },
        [10109714] = {
            ["Content"] = "你给过我礼物了——那朵花。它是无价之宝。",
            ["ContentKR"] = "나한테 선물은 이미 줬어. 그때 그 꽃, 그건 값을 매길 수 없는 보물이나 마찬가지야.",
            ["DialogueId"] = 10109714,
            ["GUID"] = "10109714.0",
            ["NextDialogue"] = 10109715,
            },
        [10109715] = {
            ["Camera"] = "15.8125,94.824219,78.226562,0.000262,7.799119,158.600952,50.0,140.419205,false,Manual,8.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "我的眼睛已经不再需要它，但你的旅途还很漫长。",
            ["ContentKR"] = "내 눈은 이제 사진기가 필요하지 않아. 하지만 네 여정은 아직 길잖아.",
            ["DialogueId"] = 10109715,
            ["FacialId"] = {
                [1] = "200006:Happy02",
                },
            ["FinalCamera"] = "15.8125,94.824219,78.226562,0.000262,7.799119,159.000992,52.0,140.419205,false,Manual,8.0",
            ["GUID"] = "194F004C",
            ["NextDialogue"] = 10109716,
            ["SpeakNpcId"] = 200006,
            ["TalkActionId"] = {
                [1] = "200006:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1002/101097/194F004C",
            },
        [10109716] = {
            ["Camera"] = "-73.710938,92.207031,66.693359,0.000262,3.399228,-0.487854,50.0,93.129883,false,Manual,5.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "用你的眼睛，替我继续看看这个世界吧。",
            ["ContentKR"] = "네 눈으로 나 대신 이 세계를 계속 봐줘.",
            ["DialogueId"] = 10109716,
            ["FinalCamera"] = "-73.710938,92.207031,66.693359,0.000262,3.399228,-0.487854,52.0,93.129883,false,Manual,5.0",
            ["GUID"] = "194F0076",
            ["NextDialogue"] = 10109717,
            ["SpeakNpcId"] = 200006,
            ["TalkActionId"] = {
                [1] = "200006:Explain02_End",
                },
            ["ToFinalCameraBlendTime"] = 4.5,
            ["VoiceName"] = "voice/$Locale$/story/1002/101097/194F0076",
            },
        [10109717] = {
            ["Camera"] = "-380.574219,-471.193359,463.862305,-5.000005,-33.000675,60.310459,50.0,928.722656,false,DoNotOverride,3.0",
            ["Content"] = "…………",
            ["ContentKR"] = "......",
            ["DialogueId"] = 10109717,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "200006:None",
                },
            ["GUID"] = "194F00A0",
            ["NextDialogue"] = 10109718,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101097/194F00A0",
            },
        [10109718] = {
            ["Camera"] = "198.785156,-175.792969,10.463867,-3.000001,7.397299,129.297333,35.0,447.397217,false,Manual,3.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "难得出来一趟，我们就在湖上随便走走吧？",
            ["ContentKR"] = "모처럼 나왔는데 우리 호숫가를 좀 걸을까?",
            ["DialogueId"] = 10109718,
            ["FinalCamera"] = "207.707031,-186.716797,8.631836,-3.000001,7.397299,129.297287,35.0,479.576324,false,Manual,3.0",
            ["GUID"] = "194F00CA",
            ["SpeakNpcId"] = 200006,
            ["TalkActionId"] = {
                [1] = "200006:Talk02_Start",
                },
            ["ToFinalCameraBlendTime"] = 4.5,
            ["VoiceName"] = "voice/$Locale$/story/1002/101097/194F00CA",
            },
        [10109801] = {
            ["Content"] = "在我很小的时候，爸爸偶尔会带我来湖边散步。",
            ["ContentKR"] = "어릴 때 종종 아빠와 함께 호숫가를 산책하고는 했어.",
            ["DialogueId"] = 10109801,
            ["GUID"] = "194F0F3A",
            ["NextDialogue"] = 10109802,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101098/194F0F3A",
            },
        [10109802] = {
            ["Content"] = "虽然时不时要和秽兽捉迷藏，但我总是很期待来这里。",
            ["ContentKR"] = "가끔은 필토이드와 숨바꼭질을 해야 했지만, 그래도 항상 여기 오길 바랐어.",
            ["DialogueId"] = 10109802,
            ["GUID"] = "194F0F64",
            ["NextDialogue"] = 10109803,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101098/194F0F64",
            },
        [10109803] = {
            ["Content"] = "因为我喜欢这里的浮冰和山峰，更因为，我喜欢看列车呼啸而过。",
            ["ContentKR"] = "이곳의 빙하와 산봉우리를 좋아하거든, 거기에 열차가 씽씽 달리며 지나가는 걸 보는 것도 좋았어.",
            ["DialogueId"] = 10109803,
            ["GUID"] = "194F0F8E",
            ["NextDialogue"] = 10109804,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101098/194F0F8E",
            },
        [10109804] = {
            ["Content"] = "你喜欢列车？",
            ["ContentKR"] = "열차를 좋아해?",
            ["DialogueId"] = 10109804,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194F0FB8",
            ["NextDialogue"] = 10109805,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101098/194F0FB8",
            },
        [10109805] = {
            ["Content"] = "嗯。我喜欢它开去的地方……“南方”。",
            ["ContentKR"] = "응, 열차가 떠나는 곳이 좋거든... '남쪽' 말이야.",
            ["DialogueId"] = 10109805,
            ["GUID"] = "194F0FE2",
            ["NextDialogue"] = 10109806,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101098/194F0FE2",
            },
        [10109806] = {
            ["Content"] = "书上写，南方和冰湖城不一样。",
            ["ContentKR"] = "책에는 남쪽이 아이스레이크 시티와 다르다고 적혀 있었어.",
            ["DialogueId"] = 10109806,
            ["GUID"] = "194F100C",
            ["NextDialogue"] = 10109807,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101098/194F100C",
            },
        [10109807] = {
            ["Content"] = "那里的太阳更加温暖，那里有四季变换。",
            ["ContentKR"] = "그곳의 태양은 훨씬 따뜻하고, 사계절의 변화도 있대.",
            ["DialogueId"] = 10109807,
            ["GUID"] = "194F1036",
            ["NextDialogue"] = 10109808,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101098/194F1036",
            },
        [10109808] = {
            ["Content"] = "当春天来临，冰雪就会融去，即使在旷野，也会有大片繁花盛开。",
            ["ContentKR"] = "봄이 오면 얼음과 눈이 녹고, 광야에는 꽃이 가득 핀다더라.",
            ["DialogueId"] = 10109808,
            ["GUID"] = "194F1060",
            ["NextDialogue"] = 10109809,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101098/194F1060",
            },
        [10109809] = {
            ["Content"] = "当时我就想，如果我也能乘上列车，就可以抵达那里了。",
            ["ContentKR"] = "그때의 난 열차만 탈 수 있다면 그곳에 갈 수 있을 거라 생각했어.",
            ["DialogueId"] = 10109809,
            ["GUID"] = "194F108A",
            ["NextDialogue"] = 10109810,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101098/194F108A",
            },
        [10109810] = {
            ["Content"] = "但是爸爸告诉我，这个心愿太奢侈了。",
            ["ContentKR"] = "하지만 아빠는 그 소원이 너무 허황되다고 했지.",
            ["DialogueId"] = 10109810,
            ["GUID"] = "194F10B4",
            ["NextDialogue"] = 10109811,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101098/194F10B4",
            },
        [10109811] = {
            ["Content"] = "因为……卡戎之民的缘故？",
            ["ContentKR"] = "...카론이라서?",
            ["DialogueId"] = 10109811,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194F10DE",
            ["NextDialogue"] = 10109812,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101098/194F10DE",
            },
        [10109812] = {
            ["Content"] = "是的。而且爸爸和妈妈只是最普通的花匠，我们很清贫，没有乘上那辆列车的资格。",
            ["ContentKR"] = "맞아. 게다가 아빠와 엄마는 그저 꽃을 기르는 일을 해서 가난했어. 그런 기차를 탈 자격이 없었지.",
            ["DialogueId"] = 10109812,
            ["GUID"] = "194F1108",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101098/194F1108",
            },
        [10109901] = {
            ["Camera"] = "43.035156,-369.824219,5.117188,0.00037,9.794949,103.195534,15.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "所以，你敲开“修普诺斯之家”大门的那一天，我是那么惊喜……因为我几乎从未和冰湖城之外的人打过交道。",
            ["ContentKR"] = "그래서 네가 '히프노스의 집' 문을 두드리던 날, 난 정말 기뻤어... 아이스레이크 시티 바깥 사람과 교류한 적이 없었거든.",
            ["DialogueId"] = 10109901,
            ["FacialId"] = {
                [1] = "200027:Smile02",
                },
            ["FinalCamera"] = "50.992188,-403.761719,-0.895508,0.00037,9.794949,103.195534,15.0,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "194F1FA2",
            ["LookAt"] = {
                [1] = "100001:n(200027)",
                [2] = "200027:n(100001)",
                },
            ["NextDialogue"] = 10109902,
            ["RelatedWikiId"] = {
                [1] = 408003,
                [2] = 301005,
                [3] = 405002,
                [4] = 201007,
                [5] = 201006,
                [6] = 201001,
                },
            ["Scripts"] = "SEQ{\
