            },
        [10110213] = {
            ["Camera"] = "65.837891,244.282227,142.673828,0.000048,-1.002317,-107.633041,35.000015,374.558105,false,Manual,4.0",
            ["Content"] = "身为卡戎，不知道“秽蚀”是什么？你到底是不是帝国人啊？",
            ["ContentKR"] = "카론이 '침식'을 모른다고? 너 제국인이 맞긴 해?",
            ["DialogueId"] = 10110213,
            ["GUID"] = "194F52D2",
            ["NextOptions"] = {
                [1] = 10110214,
                [2] = 10110216,
                },
