            ["NextDialogue"] = 10110522,
            ["SpeakNpcId"] = 200021,
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/story/1002/101105/194F84DC",
            },
        [10110522] = {
            ["Camera"] = "62.456299,-179.568848,96.763916,0.00015,6.0,94.153214,25.0,8628.139648,false,Manual,6.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "快去看看！",
            ["ContentKR"] = "얼른 가 보자!",
