        [10110602] = {
            ["Camera"] = "-58.66626,184.545898,58.416016,0.000013,9.599646,-71.385262,25.000002,245.13945,false,Manual,22.0",
            ["Content"] = "刚才不会是你在鬼叫吧？出什么事了？",
            ["ContentKR"] = "방금 네가 소리 지른 거지? 무슨 일이야?",
            ["DialogueId"] = 10110602,
            ["FacialId"] = {
                [1] = "200002:None",
                },
            ["GUID"] = "194F92A4",
            ["LookAt"] = {
                [1] = "200002:n(200021)",
                },
            ["NextDialogue"] = 10110603,
            ["Scripts"] = "PARA{\
SetLocation{ActorId{200021},TargetPoint{\"P10110603\"},Visibility{\"Show\"}},\
PlayAnimation{ActorId{200021},AnimationId{\"Explain01_Start\"},Duration{1}},\
PlayAnimation{_delay{3},ActorId{200002},AnimationId{\"Sigh_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1002/101106/194F92A4",
            },
        [10110603] = {
            ["Camera"] = "3.640381,-208.794922,183.625,0.000189,-20.999163,86.982307,50.000011,313.724945,false,DoNotOverride,3.0",
            ["Content"] = "我不是按你们说的一直在这里观察情况嘛……然后，真的像你们说的那样，赛琪出来了！我就上去拉住她，准备带她去找你们。",
            ["ContentKR"] = "너희 말대로 계속 여기 상황을 지켜보고 있었어... 그런데 너희 말대로 정말 프시케가 나왔거든! 내가 가서 너희한테 데려가려고 했지.",
            ["DialogueId"] = 10110603,
            ["FacialId"] = {
                [1] = "200002:Doubt01",
                },
            ["GUID"] = "194F92CE",
            ["NextDialogue"] = 10110604,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{200002},AnimationId{\"Angry01_Start\"},Duration{3.8}},PlayAnimation{ActorId{200002},AnimationId{\"Angry01_End\"},Duration{4.2}},PlayAnimation{ActorId{200002},AnimationId{\"Talk02_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101106/194F92CE",
            },
        [10110604] = {
            ["Camera"] = "5.263672,-60.99707,136.059082,0.000133,-20.999565,92.985939,35.000008,170.151947,false,Manual,22.0",
            ["Content"] = "可她突然扑了过来，狠狠地抓向我……还好本大人闪得快！但是……那真的是赛琪吗？那个人一点都不像平时的她，就像是……一头野兽！",
            ["ContentKR"] = "그런데 갑자기 사납게 달려들면서 날 잡으려고 하잖아... 다행히 내가 빨리 피하긴 했는데 그게 정말... 프시케였을까? 평소 프시케와 달랐어. 꼭... 짐승 같았어!",
            ["DialogueId"] = 10110604,
