CameraMoveTo{_delay{2.2},TargetPosition{\"-27.648438,1.795654,150.466797,0.000102,-4.600037,179.58815,35.000011,65.552429,false,DoNotOverride,22\"},duration{2}}\
}",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_End",
                },
            ["ToFinalCameraBlendTime"] = 3,
            ["VoiceName"] = "voice/$Locale$/story/1002/101109/194FC4D8",
            },
        [10111001] = {
            ["Content"] = "呼……呼……呼……",
            ["ContentKR"] = "후... 후... 후...",
            ["DialogueId"] = 10111001,
            ["Duration"] = 3,
            ["GUID"] = "194FD41A",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101110/194FD41A",
            },
        [10111002] = {
            ["Content"] = "啊……",
            ["ContentKR"] = "아아...",
            ["DialogueId"] = 10111002,
            ["Duration"] = 1,
            ["GUID"] = "194FD444",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101110/194FD444",
            },
        [10111003] = {
            ["Content"] = "对……不……",
            ["ContentKR"] = "미…… 안……",
            ["DialogueId"] = 10111003,
            ["Duration"] = 0.5,
            ["GUID"] = "194FD46E",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101110/194FD46E",
            },
        [10111004] = {
            ["Content"] = "回来，危险！",
            ["ContentKR"] = "으윽...!!",
            ["DialogueId"] = 10111004,
            ["Duration"] = 0.5,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194FD498",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101110/194FD498",
            },
        [10111005] = {
            ["Content"] = "风太大了，我没法靠近……！",
            ["ContentKR"] = "바람이 너무 세서 가까이 갈 수가 없어...!",
            ["DialogueId"] = 10111005,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194FD499",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101110/194FD499",
            },
        [10111006] = {
            ["Content"] = "该死，这样下去我们都会送命的……",
            ["ContentKR"] = "돌아와, 위험해! 젠장! 이러다가 우리 다 죽겠어...",
            ["DialogueId"] = 10111006,
            ["Duration"] = 4.5,
            ["GUID"] = "194FD500",
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1002/101110/194FD500",
            },
        [10111007] = {
            ["Content"] = "她失去理智了，应战！",
            ["ContentKR"] = "이미 제정신이 아냐, 조심해!",
            ["DialogueId"] = 10111007,
            ["Duration"] = 2.5,
            ["GUID"] = "194FD516",
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1002/101110/194FD516",
            },
        [10111101] = {
            ["Content"] = "赛琪，听得见我的声音吗？",
            ["ContentKR"] = "프시케, 내 목소리 들려?",
            ["DialogueId"] = 10111101,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194FE482",
            ["NextDialogue"] = 10111102,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101111/194FE482",
            },
        [10111102] = {
            ["Content"] = "回答我……",
            ["ContentKR"] = "대답해 줘...",
            ["DialogueId"] = 10111102,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194FE4AC",
            ["NextDialogue"] = 10111103,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101111/194FE4AC",
            },
        [10111103] = {
            ["Content"] = "你说过的，你明明还有那么多想做的事……",
            ["ContentKR"] = "네가 그랬잖아, 하고 싶은 게 그렇게 많다고...",
            ["DialogueId"] = 10111103,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194FE4D6",
            ["NextDialogue"] = 10111104,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101111/194FE4D6",
            },
        [10111104] = {
            ["Content"] = "你会离开这里，去那些你前所未见的地方——",
            ["ContentKR"] = "여길 떠나서 네가 가보지 못한 곳에 갈 거라며.",
            ["DialogueId"] = 10111104,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194FE500",
            ["NextDialogue"] = 10111105,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101111/194FE500",
            },
        [10111105] = {
            ["Content"] = "……你可以去一座小岛，在那里盖几间房子……",
            ["ContentKR"] = "작은 섬... 그곳에 가서 집을 몇 채 짓는 거야...",
            ["DialogueId"] = 10111105,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194FE52A",
            ["NextDialogue"] = 10111106,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101111/194FE52A",
            },
        [10111106] = {
            ["Content"] = "……在房子边上种满白色的花……",
            ["ContentKR"] = "...집 주변에 하얀 꽃을 가득 심고...",
            ["DialogueId"] = 10111106,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194FE554",
            ["NextDialogue"] = 10111107,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101111/194FE554",
            },
        [10111107] = {
            ["Content"] = "……一边用大大的帽檐遮住太阳，一边和友人说起冰湖城的雪……",
            ["ContentKR"] = "...눈부신 태양을 피해 챙이 넓은 모자를 쓰고, 친구들에게 아이스레이크 시티의 새하얀 눈 이야기를 해 주는 거야...",
            ["DialogueId"] = 10111107,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194FE57E",
            ["NextDialogue"] = 10111108,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101111/194FE57E",
            },
        [10111108] = {
            ["Content"] = "……回答我……",
            ["ContentKR"] = "...대답해줘...",
            ["DialogueId"] = 10111108,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194FE5A8",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101111/194FE5A8",
            },
        [10111201] = {
            ["Content"] = "赛琪，我来带你回家。",
            ["ContentKR"] = "프시케, 집에 가자.",
            ["DialogueId"] = 10111201,
            ["Duration"] = 4,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194FF4EA",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101127/1950EB02",
            },
        [10111301] = {
            ["Content"] = "这是……我家？",
            ["ContentKR"] = "여기는... 우리 집이잖아?",
            ["DialogueId"] = 10111301,
            ["GUID"] = "191B889A",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101113/191B889A",
            },
        [10111401] = {
            ["Content"] = "亲爱的，看，赛琪在对我们笑呢。",
            ["ContentKR"] = "여보, 봐요. 프시케가 우리를 보고 웃고 있어요.",
            ["DialogueId"] = 10111401,
            ["GUID"] = "191B88C4",
            ["NextDialogue"] = 10111402,
            ["SpeakNpcId"] = 200039,
            ["VoiceName"] = "voice/$Locale$/story/1002/101114/191B88C4",
            },
        [10111402] = {
            ["Content"] = "……不知道这孩子来到世上，究竟是幸运还是不幸。",
            ["ContentKR"] = "...이 아이가 이 세상에 온 게 행운인지 불행인지 모르겠어.",
            ["DialogueId"] = 10111402,
            ["GUID"] = "191B88EE",
            ["NextDialogue"] = 10111403,
            ["SpeakNpcId"] = 200038,
            ["VoiceName"] = "voice/$Locale$/story/1002/101114/191B88EE",
            },
        [10111403] = {
            ["Content"] = "……是的，我们并不是带着祝福降生的。",
            ["ContentKR"] = "...그러네요, 우린 축복을 안고 태어난 게 아니니까요.",
            ["DialogueId"] = 10111403,
            ["GUID"] = "191B8918",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101114/191B8918",
            },
        [10111501] = {
            ["Content"] = "妈妈！我答应过赛琪，今天带她来家里堆积木……",
            ["ContentKR"] = "엄마! 오늘 프시케랑 집에서 블록을 쌓기로 했어요...",
            ["DialogueId"] = 10111501,
            ["GUID"] = "191BB9D2",
            ["NextDialogue"] = 10111502,
            ["SpeakNpcId"] = 200040,
            ["VoiceName"] = "voice/$Locale$/story/1002/101115/191BB9D2",
            },
        [10111502] = {
            ["Content"] = "谁让你和她玩的？说过多少次，少碰那些不干不净的，你想被邪恶的魔法害死吗？",
            ["ContentKR"] = "걔랑 놀지 말라고 했지? 몇 번이나 말했잖니, 그런 존재는 가까이하면 안 돼. 사악한 마법 때문에 큰일이라도 나면 어쩌려고 그래!",
            ["DialogueId"] = 10111502,
            ["GUID"] = "191BB9FC",
            ["NextDialogue"] = 10111503,
            ["SpeakNpcId"] = 200041,
            ["VoiceName"] = "voice/$Locale$/story/1002/101115/191BB9FC",
            },
        [10111503] = {
            ["Content"] = "哎呀，好好的积木都弄脏了，快扔掉！",
            ["ContentKR"] = "휴, 멀쩡한 블록만 더러워졌네. 얼른 갖다 버려!",
            ["DialogueId"] = 10111503,
            ["GUID"] = "191BBA26",
            ["SpeakNpcId"] = 200041,
            ["VoiceName"] = "voice/$Locale$/story/1002/101115/191BBA26",
            },
        [10111601] = {
            ["Content"] = "那天，怀着委屈与不解，我花了一整晚时间洗澡，直到皮肤流出鲜血。",
            ["ContentKR"] = "그날 나는 억울함과 의아함을 안고 피가 날 때까지 밤새워 목욕했다.",
            ["DialogueId"] = 10111601,
            ["GUID"] = "191BBA50",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101116/191BBA50",
            },
        [10111701] = {
            ["Content"] = "不是的长官，我的女儿一向懂事，她绝不会偷窃顾客的项链，更没有藏在花盆里！",
            ["ContentKR"] = "아닙니다, 병사님. 제 딸은 착해서 절대 손님의 목걸이를 훔치지도, 화분에 숨기지도 않는다고요!",
            ["DialogueId"] = 10111701,
            ["GUID"] = "191BCA3A",
            ["NextDialogue"] = 10111702,
            ["SpeakNpcId"] = 200039,
            ["VoiceName"] = "voice/$Locale$/story/1002/101117/191BCA3A",
            },
        [10111702] = {
            ["Content"] = "狡辩什么，卡戎崽子有几个手脚干净的？",
            ["ContentKR"] = "변명은 집어치워, 카론 놈들 중에 깨끗한 놈이 얼마나 된다고!",
            ["DialogueId"] = 10111702,
            ["GUID"] = "191BCA64",
            ["NextDialogue"] = 10111703,
            ["SpeakNpcId"] = 200043,
            ["VoiceName"] = "voice/$Locale$/story/1002/101117/191BCA64",
            },
        [10111703] = {
            ["Content"] = "这样吧，不是说没偷没藏吗，那就让她自己把店里那些花一盆盆砸了，证明清白。",
            ["ContentKR"] = "그래, 훔치지 않았다면서? 그럼 직접 가게의 모든 화분을 깨부숴서 결백을 증명해봐.",
            ["DialogueId"] = 10111703,
            ["GUID"] = "191BCA8E",
            ["NextDialogue"] = 10111704,
            ["SpeakNpcId"] = 200044,
            ["VoiceName"] = "voice/$Locale$/story/1002/101117/191BCA8E",
            },
        [10111704] = {
            ["Content"] = "……因为，我们生而是“恶魔的孩子”。",
            ["ContentKR"] = "...왜냐하면 우리는 '악마의 아이'니까요.",
            ["DialogueId"] = 10111704,
            ["GUID"] = "191BDAA2",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101117/191BDAA2",
            },
        [10111801] = {
            ["Content"] = "啊啊……为什么……",
            ["ContentKR"] = "아아... 어째서...",
            ["DialogueId"] = 10111801,
            ["GUID"] = "191BDACC",
            ["NextDialogue"] = 10111802,
            ["SpeakNpcId"] = 200039,
            ["VoiceName"] = "voice/$Locale$/story/1002/101118/191BDACC",
            },
        [10111802] = {
            ["Content"] = "她那么善良，我们一家也本本分分，没做过任何坏事……为什么这种事会落在我们头上？",
            ["ContentKR"] = "이렇게 착한 아이에게... 우리 가족 모두 나쁜 짓 한 번 한 적이 없는데... 왜 이런 일이 우리한테 벌어지는 거죠?",
            ["DialogueId"] = 10111802,
            ["GUID"] = "191BDAF6",
            ["NextDialogue"] = 10111803,
            ["SpeakNpcId"] = 200039,
            ["VoiceName"] = "voice/$Locale$/story/1002/101118/191BDAF6",
            },
        [10111803] = {
            ["Content"] = "……事到如今，只能去请求恩里克·埃塞尔莱德医生了。这是我们最后能为她做的。",
            ["ContentKR"] = "...이렇게 된 이상 헨릭 애설레드 선생님께 부탁할 수밖에 없어. 이게 우리가 마지막으로 프시케를 위해 할 수 있는 거야.",
            ["DialogueId"] = 10111803,
            ["GUID"] = "191BDB20",
            ["NextDialogue"] = 10111804,
            ["SpeakNpcId"] = 200038,
            ["VoiceName"] = "voice/$Locale$/story/1002/101118/191BDB20",
            },
        [10111804] = {
            ["Content"] = "爸爸，妈妈，对不起……",
            ["ContentKR"] = "엄마, 아빠, 미안해요...",
            ["DialogueId"] = 10111804,
            ["GUID"] = "191BDB4A",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101118/191BDB4A",
            },
        [10111901] = {
            ["Content"] = "……没有任何意义。",
            ["ContentKR"] = "...다 부질없어.",
            ["DialogueId"] = 10111901,
            ["GUID"] = "191BEB0A",
            ["NextDialogue"] = 10111902,
            ["SpeakNpcId"] = 200045,
            ["VoiceName"] = "voice/$Locale$/story/1002/101119/191BEB0A",
            },
        [10111902] = {
            ["Content"] = "你每天送这种东西给我，又能改变什么呢。",
            ["ContentKR"] = "매일 이런 걸 준다고 뭐가 달라지겠어.",
            ["DialogueId"] = 10111902,
            ["GUID"] = "191BEB34",
            ["NextDialogue"] = 10111903,
            ["SpeakNpcId"] = 200045,
            ["VoiceName"] = "voice/$Locale$/story/1002/101119/191BEB34",
            },
        [10111903] = {
            ["Content"] = "赛琪。你应该知道，来到“修普诺斯之家”意味着什么。",
            ["ContentKR"] = "프시케, '히프노스의 집'에 온 게 어떤 의미인지 잘 알고 있지?",
            ["DialogueId"] = 10111903,
            ["GUID"] = "191BEB5E",
            ["NextDialogue"] = 10111904,
            ["SpeakNpcId"] = 200046,
            ["VoiceName"] = "voice/$Locale$/story/1002/101119/191BEB5E",
            },
        [10111904] = {
            ["Content"] = "嗯，我都明白。",
            ["ContentKR"] = "네, 알아요.",
            ["DialogueId"] = 10111904,
            ["GUID"] = "191BEB88",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10111905,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101119/191BEB88",
            },
        [10111905] = {
            ["Content"] = "……但我们是为了什么“意义”才活着吗？",
            ["ContentKR"] = "...그런데 우리는 무슨 '의미'를 위해 살아가는 거죠?",
            ["DialogueId"] = 10111905,
            ["GUID"] = "191BEBB2",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101119/191BEBB2",
            },
        [10112001] = {
            ["Content"] = "……赛琪……",
            ["ContentKR"] = "...프시케...",
            ["DialogueId"] = 10112001,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "191B9902",
            ["NextDialogue"] = 10112002,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101120/191B9902",
            },
        [10112002] = {
