            ["VoiceName"] = "voice/$Locale$/story/1002/101121/19508891",
            },
        [10112101] = {
            ["Camera"] = "-1315.217285,639.65625,36.358154,-0.0,-14.999996,-34.000755,14.0,100000.0,false,DoNotOverride,2.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "你已经看到了自己的一生。怀抱诅咒的来，毫无意义的去。",
            ["ContentKR"] = "넌 이미 너 자신의 일생을 보았다. 저주받은 삶에 무의미한 죽음이지.",
            ["DialogueId"] = 10112101,
            ["FacialId"] = {
                [1] = "200052:Smile01",
                [2] = "200006:Shock01",
                },
            ["FinalCamera"] = "-1353.548462,665.503906,107.660645,-0.0,-8.800411,-34.000824,12.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "19508892",
            ["LookAt"] = {
                [1] = "200052:n(200006)",
                [2] = "200006:n(200052)",
                },
            ["NextDialogue"] = 10112102,
            ["Scripts"] = "PARA{\
