            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101124/1950BA1E",
            },
        [10112404] = {
            ["Content"] = "不要向这个冷冰冰的世界投降！",
            ["ContentKR"] = "이 차가운 세상에 지지 마!",
            ["DialogueId"] = 10112404,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "1950BA48",
            ["NextDialogue"] = 10112405,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101124/1950BA48",
            },
        [10112405] = {
            ["Content"] = "我……",
            ["ContentKR"] = "난...",
            ["DialogueId"] = 10112405,
            ["GUID"] = "1950BA72",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101124/1950BA72",
            },
        [10112501] = {
            ["Content"] = "你疯了？你在做什么？！杀了我，你自己也会死的！",
            ["ContentKR"] = "미쳤어? 뭘 하는 거야?! 날 죽이면 너도 같이 죽을 거야!",
            ["DialogueId"] = 10112501,
            ["GUID"] = "1950CA5B",
            ["NextDialogue"] = 10112502,
            ["SnapShot"] = "MONSTER",
            ["SpeakNpcId"] = 200052,
            ["VoiceName"] = "voice/$Locale$/story/1002/101125/1950CA5B",
            },
        [10112502] = {
            ["Content"] = "侮辱和伤害你的是他们，是他们！你却要选择毁灭我吗？！",
            ["ContentKR"] = "너를 모욕하고 상처 준 건 그들이야, 그들! 그런데, 날 없애려고 하는 거야?!",
            ["DialogueId"] = 10112502,
            ["GUID"] = "1950CA5C",
            ["NextDialogue"] = 10112503,
            ["SnapShot"] = "MONSTER",
            ["SpeakNpcId"] = 200052,
            ["VoiceName"] = "voice/$Locale$/story/1002/101125/1950CA5C",
            },
        [10112503] = {
            ["Content"] = "为什么不顺从这具躯体，去破坏，去毁灭？",
            ["ContentKR"] = "왜 이 몸에 순종하지 않아? 왜 파괴와 멸망의 길을 택하지 않는 거야?",
            ["DialogueId"] = 10112503,
            ["GUID"] = "1950CA86",
            ["NextDialogue"] = 10112504,
            ["SnapShot"] = "MONSTER",
            ["SpeakNpcId"] = 200052,
            ["VoiceName"] = "voice/$Locale$/story/1002/101125/1950CA86",
            },
        [10112504] = {
            ["Content"] = "不是这样的。因为我记得……",
            ["ContentKR"] = "왜냐하면, 나는 기억하니까…",
            ["DialogueId"] = 10112504,
            ["GUID"] = "1950CA87",
            ["GuideFacialId"] = "Angry",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101125/1950CA87",
            },
        [10112601] = {
            ["Content"] = "赛琪，你还记得，一直以来的愿望是什么吗？",
            ["ContentKR"] = "프시케, 네가 줄곧 바라왔던 소원이 뭔지 기억나니?",
            ["DialogueId"] = 10112601,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "1950DA9A",
            ["NextDialogue"] = 10112602,
            ["Scripts"] = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt02/0063_story_saiqi_last_word\"}}",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101126/1950DA9A",
            },
        [10112602] = {
            ["Content"] = "嗯，我都想起来了。",
            ["ContentKR"] = "응, 다 기억났어.",
            ["DialogueId"] = 10112602,
            ["Duration"] = 3,
            ["GUID"] = "1950DAEE",
            ["NextDialogue"] = 10112603,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101126/1950DAEE",
            },
        [10112603] = {
            ["Content"] = "想离开这儿，想去更广阔的世界旅行。",
            ["ContentKR"] = "이곳을 떠나 더 넓은 세상을 여행하고 싶었어.",
            ["DialogueId"] = 10112603,
            ["Duration"] = 3,
            ["GUID"] = "1950DB18",
            ["NextDialogue"] = 10112604,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101126/1950DB18",
            },
        [10112604] = {
            ["Content"] = "想去一个繁花盛开的温暖之地。",
            ["ContentKR"] = "꽃이 만발한 따뜻한 곳에 가고 싶었지.",
            ["DialogueId"] = 10112604,
            ["Duration"] = 3,
            ["GUID"] = "1950DB42",
