        [10113301] = {
            ["Content"] = "再一次崩塌的梦里，那个声音从风中传来。",
            ["ContentKR"] = "다시 한 번 무너지는 꿈 속에서, 그 목소리가 바람을 타고 들려왔다.",
            ["DialogueId"] = 10113301,
            ["Duration"] = 3.5,
            ["GUID"] = "19514D72",
            ["NextDialogue"] = 10113302,
            ["VoiceName"] = "voice/$Locale$/story/1002/101133/19514D72",
            },
        [10113302] = {
            ["Content"] = "这一次，我终于可以听清。",
            ["ContentKR"] = "이번에는 그 목소리가 똑똑하게 들려왔다.",
            ["DialogueId"] = 10113302,
            ["Duration"] = 3.5,
            ["GUID"] = "19514D9C",
            ["NextDialogue"] = 10113303,
            ["VoiceName"] = "voice/$Locale$/story/1002/101133/19514D9C",
            },
        [10113303] = {
            ["Content"] = "像树木的根须汲取着每一滴水，我竭尽全力试图记住那个名字。",
            ["ContentKR"] = "나무의 뿌리가 물 한 방울도 놓치지 않듯이, 나는 온 힘을 다해 그 이름을 기억하려 했다.",
            ["DialogueId"] = 10113303,
            ["Duration"] = 4,
            ["GUID"] = "19514DC6",
            ["NextDialogue"] = 10113304,
            ["VoiceName"] = "voice/$Locale$/story/1002/101133/19514DC6",
            },
        [10113304] = {
            ["Content"] = "……那个名字……",
            ["ContentKR"] = "...그리고 그 이름은...",
            ["DialogueId"] = 10113304,
            ["Duration"] = 3,
            ["GUID"] = "19514DF0",
            ["VoiceName"] = "voice/$Locale$/story/1002/101133/19514DF0",
            },
        [10113401] = {
            ["Camera"] = "-1818.244629,451.75,65.15918,0.0,3.799989,1.999787,35.0,269.181396,false,Manual,1.2",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "我承受过痛苦，体会过憎恨。我曾为之疲惫，也曾为之悲叹——",
            ["ContentKR"] = "난 고통을 겪었고, 증오를 느꼈어. 그로 인해 지치기도 했고, 슬퍼하기도 했지만...",
            ["DialogueId"] = 10113401,
            ["FacialId"] = {
                [1] = "2000591:Happy02",
                },
            ["FinalCamera"] = "-1818.244629,451.75,77.947998,0.0,6.0,1.999786,35.0,921.225525,false,Manual,1.2",
            ["GUID"] = "19515DDA",
