            },
        [10113502] = {
            ["Camera"] = "238.0625,-87.837646,103.295898,0.000204,4.399468,158.005524,35.0,185.005707,false,Manual,4.0",
            ["CameraBlendCurve"] = "easeInQuad",
            ["Content"] = "你就把这个正在嗷嗷乱叫的破机器当做你想要保护的人，把这些秽兽当做要攻击她的家伙。",
            ["ContentKR"] = "지금 꽥꽥대는 이 고철 기계를 네가 지키고 싶은 사람으로 생각하고, 저 필토이드들은 그 사람을 공격하려는 놈으로 생각해.",
            ["DialogueId"] = 10113502,
            ["FinalCamera"] = "240.769531,-81.229736,103.295898,0.000213,4.399468,158.005692,35.0,292.735229,false,Manual,5.0",
            ["GUID"] = "19516F14",
