        [10113701] = {
            ["Content"] = "呃，碎掉了。",
            ["ContentKR"] = "앗, 망가졌네.",
            ["DialogueId"] = 10113701,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19518F12",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10113702,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101137/19518F12",
            },
        [10113702] = {
            ["Content"] = "废品改装的嘛，能用已经很不错了！。",
            ["ContentKR"] = "쓰레기를 개조한 거잖아. 쓸 수 있는 게 어디야!",
            ["DialogueId"] = 10113702,
            ["Duration"] = 2.5,
            ["GUID"] = "19518F3C",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
