            ["VoiceName"] = "voice/$Locale$/story/1002/101137/19518F3C",
            },
        [10113801] = {
            ["Content"] = "任务完成",
            ["ContentKR"] = "퀘스트 완료",
            ["DialogueId"] = 10113801,
            ["Duration"] = 3.5,
            ["GUID"] = "19519F7A",
            ["VoiceName"] = "voice/$Locale$/story/1002/101138/19519F7A",
            },
        [10113901] = {
            ["Content"] = "本次技术性测试剧情流程已结束。",
            ["DialogueId"] = 10113901,
            ["Duration"] = 5,
            ["GUID"] = "1951AFE2",
            ["VoiceName"] = "voice/$Locale$/story/1002/101139/1951AFE2",
            },
        [10114001] = {
            ["Content"] = "这么快就回来了？不是去跟踪恩里克了吗？",
            ["ContentKR"] = "왜 이렇게 빨리 돌아왔어? 헨릭이 어디 가는지 뒤쫓아 간 거 아니었어?",
            ["DialogueId"] = 10114001,
            ["GUID"] = "1951C04A",
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1002/101140/1951C04A",
            },
        [10114201] = {
            ["Content"] = "你们要早点休息哦。",
            ["ContentKR"] = "다들 일찍 쉬어.",
            ["DialogueId"] = 10114201,
            ["GUID"] = "1951E11A",
            ["SpeakNpcId"] = 200020,
            ["VoiceName"] = "voice/$Locale$/story/1002/101142/1951E11A",
            },
        [10114301] = {
            ["Content"] = "如果恩里克叔叔同意的话，你可以再来找我玩吗？",
            ["ContentKR"] = "헨릭 아저씨가 허락하면 또 나랑 놀 수 있어?",
            ["DialogueId"] = 10114301,
            ["GUID"] = "1951F182",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101143/1951F182",
            },
        [10114401] = {
            ["Content"] = "放老实点，别管与你无关的事。",
            ["ContentKR"] = "너와 상관 없는 일에 쓸데없이 끼어들지 마라.",
            ["DialogueId"] = 10114401,
            ["GUID"] = "195201EA",
            ["SpeakNpcId"] = 200005,
            ["VoiceName"] = "voice/$Locale$/story/1002/101144/195201EA",
            },
        [10114501] = {
