        [10114601] = {
            ["Content"] = "拜托了，请跟我来！",
            ["ContentKR"] = "부탁이야. 같이 좀 가줘!",
            ["DialogueId"] = 10114601,
            ["Duration"] = 4,
            ["GUID"] = "195222BA",
            ["SpeakNpcId"] = 200019,
            ["SpeakNpcName"] = "UI_Npc_Name_Boy_3",
            ["VoiceName"] = "voice/$Locale$/story/1002/101146/195222BA",
            },
        [10114701] = {
            ["Content"] = "这边，恩里克先生的办公室！",
            ["ContentKR"] = "여기, 헨릭 씨의 사무실이야!",
            ["DialogueId"] = 10114701,
            ["Duration"] = 5,
            ["GUID"] = "19523322",
            ["SpeakNpcId"] = 200019,
            ["SpeakNpcName"] = "UI_Npc_Name_Boy_3",
            ["VoiceName"] = "voice/$Locale$/story/1002/101147/19523322",
            },
        [10114801] = {
            ["Content"] = "先抓紧离开这儿吧。",
            ["ContentKR"] = "우선 여기부터 나가자.",
            ["DialogueId"] = 10114801,
            ["Duration"] = 4,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "1952438A",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101148/1952438A",
            },
        [10114901] = {
            ["Content"] = "请一定要找到她，拜托了……",
            ["ContentKR"] = "꼭 찾아줘. 부탁이야...",
            ["DialogueId"] = 10114901,
            ["GUID"] = "195253F2",
            ["SpeakNpcId"] = 200045,
            ["VoiceName"] = "voice/$Locale$/story/1002/101149/195253F2",
            },
        [10115001] = {
            ["Content"] = "……赛琪杀了恩里克……为什么……会这样……",
            ["ContentKR"] = "... 프시케가 헨릭 씨를... 대체 왜... 이렇게...",
            ["DialogueId"] = 10115001,
            ["GUID"] = "1952645A",
            ["NextDialogue"] = 10115002,
            ["SpeakNpcId"] = 700049,
            ["VoiceName"] = "voice/$Locale$/story/1002/101150/1952645A",
            },
        [10115002] = {
            ["Content"] = "赛琪永远都在笑着……恩里克先生虽然话不多，但总是像父亲一样照料我们……他们明明都是那么好的人啊……",
            ["ContentKR"] = "프시케는 언제나 웃고 있었어... 헨릭 씨는 말수는 적었지만, 우리를 자식처럼 챙겼다고... 모두 그렇게 좋은 사람인데...",
            ["DialogueId"] = 10115002,
            ["GUID"] = "19526484",
            ["SpeakNpcId"] = 700049,
            ["VoiceName"] = "voice/$Locale$/story/1002/101150/19526484",
            },
        [10115101] = {
            ["Content"] = "恩里克先生一直都太累了。或许对他来说，这样的结局……也不错。",
            ["ContentKR"] = "헨릭 씨는 많이 지쳐 있었어요. 그에겐 어쩌면... 이런 결말도 괜찮을지 몰라요.",
            ["DialogueId"] = 10115101,
            ["GUID"] = "195274C2",
            ["SpeakNpcId"] = 200019,
            ["VoiceName"] = "voice/$Locale$/story/1002/101151/195274C2",
            },
        [10115201] = {
            ["Content"] = "白，还记得赛琪是往哪个方向跑的吗？",
            ["ContentKR"] = "스노우, 프시케가 어디로 갔는지 기억해?",
            ["DialogueId"] = 10115201,
            ["Duration"] = 4,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "1952852A",
            ["NextDialogue"] = 10115202,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101152/1952852A",
            },
        [10115202] = {
            ["Content"] = "当然记得，我的记忆不会出错！她是往城门的方向跑的！",
            ["ContentKR"] = "내 기억력이 얼마나 좋은데, 물론 기억하지! 프시케는 성문을 향해 갔어!",
            ["DialogueId"] = 10115202,
            ["Duration"] = 4,
            ["GUID"] = "19528554",
            ["NextDialogue"] = 10115203,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101152/19528554",
            },
        [10115203] = {
            ["Content"] = "……她出城了？",
            ["ContentKR"] = "... 설마 성을 나간 건가?",
            ["DialogueId"] = 10115203,
            ["Duration"] = 4,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "1952857E",
            ["NextDialogue"] = 10115204,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101152/1952857E",
            },
        [10115204] = {
            ["Content"] = "好，我们也跟上，去城外。",
            ["ContentKR"] = "그래, 우리도 성 밖으로 따라가자.",
            ["DialogueId"] = 10115204,
            ["Duration"] = 4,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "195285A8",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101152/195285A8",
            },
        [10115301] = {
            ["Content"] = "好大的风！呜哇，感觉要被吹飞了——",
            ["ContentKR"] = "바람이 너무 많이 불어! 으악, 이러다 날아갈 것 같아...",
            ["DialogueId"] = 10115301,
            ["Duration"] = 4,
            ["GUID"] = "19529592",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10115302,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101153/19529592",
            },
        [10115302] = {
            ["Content"] = "你们两个也小心点！",
            ["ContentKR"] = "너희 둘도 조심해!",
            ["DialogueId"] = 10115302,
            ["Duration"] = 4,
            ["GUID"] = "195295BC",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101153/195295BC",
            },
        [10115401] = {
            ["Content"] = "这是最近的路，踩着浮冰过去吧。",
            ["ContentKR"] = "이게 가장 빠른 길이야. 이 얼음 조각을 밟고 가자.",
            ["DialogueId"] = 10115401,
            ["Duration"] = 4,
            ["GUID"] = "1952A5FA",
            ["GuideFacialId"] = "Angry",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10115402,
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1002/101154/1952A5FA",
            },
        [10115402] = {
            ["Content"] = "这里水深，仔细点，别掉下去。",
            ["ContentKR"] = "물이 깊으니 조심해. 빠지면 위험해.",
            ["DialogueId"] = 10115402,
            ["Duration"] = 4,
            ["GUID"] = "1952A624",
            ["GuideFacialId"] = "Angry",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10115403,
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1002/101154/1952A624",
            },
        [10115403] = {
            ["Content"] = "……赛琪，等我。",
            ["ContentKR"] = "...프시케, 기다려 줘.",
            ["DialogueId"] = 10115403,
            ["Duration"] = 4,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "1952A64E",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101154/1952A64E",
            },
        [10115501] = {
            ["Content"] = "与此同时，皇都·迪斯玛尼亚——",
            ["ContentKR"] = "한편, 황성 디즈마니아에서는...",
            ["DialogueId"] = 10115501,
            ["Duration"] = 4,
            ["GUID"] = "1952B662",
            ["Scripts"] = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"}}",
            ["VoiceName"] = "voice/$Locale$/story/1002/101155/1952B662",
            },
        [10115601] = {
            ["Content"] = "突然，恩里克出现了",
            ["DialogueId"] = 10115601,
            ["GUID"] = "1952C6CA",
            ["VoiceName"] = "voice/$Locale$/story/1002/101156/1952C6CA",
            },
        [10115701] = {
            ["Content"] = "一个熟悉的少女叫住了一行人",
            ["DialogueId"] = 10115701,
            ["GUID"] = "1952D732",
            ["VoiceName"] = "voice/$Locale$/story/1002/101157/1952D732",
            },
        [10115801] = {
            ["Content"] = "（已经和奥特赛德和白交代好了今天发生的所有事。）",
            ["ContentKR"] = "(이미 아웃사이더와 스노우에게 오늘 있었던 일을 다 얘기했는데.)",
            ["DialogueId"] = 10115801,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "1952E79A",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 10115802,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101158/1952E79A",
            },
        [10115802] = {
            ["Content"] = "（接下来能做的，就只有在说好的地方……耐心等待。）",
            ["ContentKR"] = "(이제 할 수 있는 건, 약속 장소에서... 기다리는 것뿐이야.)",
            ["DialogueId"] = 10115802,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "1952E7C4",
            ["IsBlack"] = 1,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101158/1952E7C4",
            },
        [10116701] = {
            ["Camera"] = "1254.770752,-2759.531738,887.252197,0.000057,-11.799739,115.599007,35.0,100000.0,false,Disable,2.8",
            ["DialogueId"] = 10116701,
            ["Duration"] = 4,
            ["GUID"] = "19537B42",
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/metaldooropen\"},PlayAs2D{true}}",
            ["VoiceName"] = "voice/$Locale$/story/1002/101167/19537B42",
            },
        [10116801] = {
            ["Content"] = "我们开始狩猎吧！",
            ["DialogueId"] = 10116801,
            ["GUID"] = "19538BAA",
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1002/101168/19538BAA",
            },
        [10116901] = {
            ["Content"] = "地上这些是……奥特赛德布置的陷阱。",
            ["ContentKR"] = "이건... 아웃사이더가 설치한 함정이구나.",
            ["DialogueId"] = 10116901,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19539C12",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10116902,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101169/19539C12",
            },
        [10116902] = {
            ["Content"] = "……还挺厉害的。奥特赛德竟然还会这种手艺。",
            ["ContentKR"] = "...대단하네. 아웃사이더한테 이런 능력도 있을 줄이야.",
            ["DialogueId"] = 10116902,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19539C3C",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101169/19539C3C",
            },
        [10117001] = {
            ["Content"] = "这是怎么回事？",
            ["ContentKR"] = "이게 어떻게 된 일이야?",
            ["DialogueId"] = 10117001,
            ["Duration"] = 4,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "1953AC7A",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10117002,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101170/1953AC7A",
            },
        [10117002] = {
            ["Content"] = "啊哈，真不巧，调试的时候弄了点动静，把这些小家伙引来了……",
            ["ContentKR"] = "아하하, 확인하다가 실수로 인기척을 냈더니, 이렇게 되어 버렸네...",
            ["DialogueId"] = 10117002,
            ["Duration"] = 6,
            ["GUID"] = "1953ACA4",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10117003,
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1002/101170/1953ACA4",
            },
        [10117003] = {
            ["Content"] = "朋友，快来搭把手！",
            ["ContentKR"] = "어서 와서 도와줘!",
            ["DialogueId"] = 10117003,
            ["Duration"] = 4,
            ["GUID"] = "1953ACCE",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10117004,
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1002/101170/1953ACCE",
            },
        [10117004] = {
            ["Content"] = "你这不是活该吗！……算了。",
            ["ContentKR"] = "이게 무슨 말도 안 되는...! 휴, 됐다.",
            ["DialogueId"] = 10117004,
            ["Duration"] = 4,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "1953ACF8",
            ["GuideFacialId"] = "Angry",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101170/1953ACF8",
            },
        [10117101] = {
            ["Content"] = "咱们就先往西边找吧！",
            ["ContentKR"] = "일단 서쪽으로 가보죠!",
            ["DialogueId"] = 10117101,
            ["Duration"] = 3,
            ["GUID"] = "1953BCE2",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10117102,
            ["SpeakNpcId"] = 200011,
            ["VoiceName"] = "voice/$Locale$/story/1002/101171/1953BCE2",
            },
        [10117102] = {
            ["Content"] = "那小贼一头黑发，当时穿的好像是……蓝色的上衣？",
            ["ContentKR"] = "그 도둑은 검은 머리에... 파란색 옷을 입고 있었던 것 같아요.",
            ["DialogueId"] = 10117102,
            ["Duration"] = 3,
            ["GUID"] = "1953BD0C",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200011,
            ["VoiceName"] = "voice/$Locale$/story/1002/101171/1953BD0C",
            },
        [10117201] = {
            ["Content"] = "那是……贫民窟的巴迪爷爷！我去找他打听打听！",
            ["ContentKR"] = "어... 빈민가의 바디 할아버지잖아! 할아버지께 물어봐야겠어요!",
            ["DialogueId"] = 10117201,
            ["Duration"] = 3,
            ["GUID"] = "1953CD4A",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200011,
            ["VoiceName"] = "voice/$Locale$/story/1002/101172/1953CD4A",
            },
        [10117301] = {
            ["Camera"] = "495.198669,-153.64209,121.41748,0.000037,-4.599893,-178.0,35.0,490.637817,false,DoNotOverride,1.5",
            ["Content"] = "巴迪爷爷！您这是出来散步？",
            ["ContentKR"] = "바디 할아버지! 산책 나오셨어요?",
            ["DialogueId"] = 10117301,
            ["FacialId"] = {
                [1] = "200011:Smile02",
                },
            ["GUID"] = "1953DDB1",
            ["LookAt"] = {
                [1] = "200011:n(200054)",
                [2] = "200002:n(200054)",
                [3] = "100001:n(200054)",
                },
            ["NextDialogue"] = 10117302,
            ["RelatedWikiId"] = {
                [1] = 408003,
                [2] = 405004,
                [3] = 201008,
                [4] = 201005,
                },
            ["Scripts"] = "PARA{\
