            ["DisableMouth"] = 1,
            ["GUID"] = "195471D8",
            ["VoiceName"] = "voice/$Locale$/story/1002/101182/195471D8",
            },
        [10118301] = {
            ["Content"] = "又、又不见了？他是幽灵吗？",
            ["ContentKR"] = "또, 또 사라졌어? 정말 유령이라도 되는 걸까?",
            ["DialogueId"] = 10118301,
            ["Duration"] = 3,
            ["GUID"] = "195481C2",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10118303,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101183/195481C2",
            },
        [10118302] = {
            ["Content"] = "不……你们看，这面井盖有被挪动过的痕迹。",
            ["ContentKR"] = "아니에요... 보세요, 여기 맨홀 뚜껑에 움직인 흔적이 있어요.",
            ["DialogueId"] = 10118302,
            ["Duration"] = 3,
            ["GUID"] = "195481EC",
            ["GuideFacialId"] = "Angry",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10118303,
            ["SpeakNpcId"] = 200011,
            ["VoiceName"] = "voice/$Locale$/story/1002/101183/195481EC",
            },
        [10118303] = {
            ["Content"] = "以我的推测，他一定钻进了下水道！",
            ["ContentKR"] = "제 추리에 의하면 틀림없이 하수도로 들어갔을 거예요!",
            ["DialogueId"] = 10118303,
