            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200011,
            ["VoiceName"] = "voice/$Locale$/story/1002/101183/19548216",
            },
        [10118401] = {
            ["Content"] = "这么深的水……根本就过不去吧！他怎么做到的？",
            ["ContentKR"] = "물이 이렇게 깊으면... 도저히 건널 수가 없잖아! 그 녀석은 어떻게 한 거지?",
            ["DialogueId"] = 10118401,
            ["Duration"] = 3,
            ["GUID"] = "1954922A",
