            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101187/1954C38C",
            },
        [10118801] = {
            ["Content"] = "咳、咳……呛死我了……好卑鄙……",
            ["ContentKR"] = "콜록, 콜록…… 숨 막혀 죽겠네…… 비겁하긴……",
            ["DialogueId"] = 10118801,
            ["Duration"] = 3,
            ["GUID"] = "1954D3CA",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200011,
            ["VoiceName"] = "voice/$Locale$/story/1002/101188/1954D3CA",
            },
        [10118901] = {
            ["Content"] = "听到脚步声了，这边这边！",
            ["ContentKR"] = "발소리가 들려요, 이쪽이에요 이쪽!",
            ["DialogueId"] = 10118901,
            ["Duration"] = 3,
            ["GUID"] = "1954E432",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200011,
            ["VoiceName"] = "voice/$Locale$/story/1002/101189/1954E432",
            },
        [10119001] = {
            ["Content"] = "刚才有什么飞过来了……",
            ["ContentKR"] = "방금 뭔가 날아왔는데...",
            ["DialogueId"] = 10119001,
            ["Duration"] = 3,
            ["GUID"] = "1954F49A",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10119002,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101190/1954F49A",
            },
        [10119002] = {
            ["Content"] = "呜啊……疼疼疼！是石头！",
            ["ContentKR"] = "으악... 뭐야, 돌멩이잖아!",
            ["DialogueId"] = 10119002,
            ["Duration"] = 3,
