        [10119201] = {
            ["Content"] = "这些脚印是刚踩上去的，沿着这些湿漉漉的脚印追上去准没错。",
            ["ContentKR"] = "여기 발자국들은 방금 찍힌 거예요. 이쪽 젖은 발자국을 따라가면 될 거예요.",
            ["DialogueId"] = 10119201,
            ["Duration"] = 3,
            ["GUID"] = "1955156A",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200011,
            ["VoiceName"] = "voice/$Locale$/story/1002/101192/1955156A",
            },
        [10119301] = {
            ["Content"] = "这是……新鲜的血迹？他受伤了？",
            ["ContentKR"] = "이건... 새로 묻은 핏자국 같은데? 도둑 녀석이 다친 걸까요?",
            ["DialogueId"] = 10119301,
            ["Duration"] = 3,
            ["GUID"] = "195525D2",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10122001,
            ["SpeakNpcId"] = 200011,
            ["VoiceName"] = "voice/$Locale$/story/1002/101193/195525D2",
            },
        [10119302] = {
            ["Content"] = "他或许被什么袭击了……我们也谨慎一些。",
            ["ContentKR"] = "뭔가에 공격당했을지도 몰라... 우리도 조심해야 해.",
            ["DialogueId"] = 10119302,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "195525FC",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101193/195525FC",
            },
        [10119401] = {
            ["Content"] = "果然……他惊扰了这里的秽兽群，以至遭到了围攻。",
            ["ContentKR"] = "역시... 여기 필토이드 무리한테 걸려서 포위당한 모양이야.",
            ["DialogueId"] = 10119401,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "1955363A",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101194/1955363A",
            },
        [10119501] = {
            ["Content"] = "我跑不动了……我投降……",
            ["ContentKR"] = "더는 못 뛰겠어... 항복할게...",
            ["DialogueId"] = 10119501,
            ["Duration"] = 3,
            ["GUID"] = "10119501.0",
            ["NextDialogue"] = 10119502,
            ["SpeakNpcId"] = 200053,
            ["VoiceName"] = "sfx/enemy/Mn/Haer/vo_$Locale$_Die",
            },
        [10119502] = {
            ["Content"] = "哼哼，跑不动了吧！",
            ["ContentKR"] = "흥흥, 이제 더는 못 도망가겠지!",
            ["DialogueId"] = 10119502,
            ["Duration"] = 3,
            ["GUID"] = "195546A2",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10119503,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101195/195546A2",
            },
        [10119503] = {
            ["Content"] = "{nickname}，搭把手，一起按住他！",
            ["ContentKR"] = "{nickname}, 저 사람 잡는 걸 도와주세요!",
            ["DialogueId"] = 10119503,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "195546CC",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200011,
            ["VoiceName"] = "voice/$Locale$/story/1002/101195/195546CC",
            },
        [10119601] = {
            ["Content"] = "这扇门看起来没坏，只是上了锁……",
            ["ContentKR"] = "이 문은 고장 난 게 아니라 그냥 잠긴 거네...",
            ["DialogueId"] = 10119601,
            ["Duration"] = 3,
            ["GUID"] = "1955570A",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10119602,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101196/1955570A",
            },
        [10119602] = {
            ["Content"] = "唉，都成废矿了，有必要搞这么多防盗措施吗！",
            ["ContentKR"] = "아, 폐광이 됐는데도 이렇게까지 도둑 걱정을 할 필요가 있나?",
            ["DialogueId"] = 10119602,
            ["Duration"] = 3,
            ["GUID"] = "19555734",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10119603,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101196/19555734",
            },
        [10119603] = {
            ["Content"] = "……也许是为了防止有人误入此地，被秽兽伤到？",
            ["ContentKR"] = "...어쩌면 사람들이 실수로 들어와 필토이드에게 공격당하는 걸 막으려는 건지도 몰라.",
            ["DialogueId"] = 10119603,
            ["Duration"] = 3,
            ["GUID"] = "1955575E",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10119604,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101196/1955575E",
            },
        [10119604] = {
            ["Content"] = "让我们碰碰运气吧！看看这附近能不能找到钥匙一类的东西。",
            ["ContentKR"] = "혹시 근처에 열쇠가 있는지 찾아보자. 운이 좋으면 찾을 수 있을지도 몰라.",
            ["DialogueId"] = 10119604,
            ["Duration"] = 3,
            ["GUID"] = "19555788",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101196/19555788",
            },
        [10119701] = {
            ["Content"] = "哇……原来矿坑里还有这种好东西？要是让玛尔洁知道了，她还不得乐开花！",
            ["ContentKR"] = "와... 광갱에 이런 좋은 물건이 있었다고? 마르제가 알면 좋아하겠는걸!",
            ["DialogueId"] = 10119701,
            ["Duration"] = 3,
            ["GUID"] = "19556772",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10119702,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101197/19556772",
            },
        [10119702] = {
            ["Content"] = "但是这矿石很硬吧，玛尔洁小姐的铲子说不定会被磕坏的。",
            ["ContentKR"] = "하지만 이 광석은 너무 단단해 보이는데, 마르제 씨의 삽이 망가질지도 몰라.",
            ["DialogueId"] = 10119702,
            ["Duration"] = 3,
            ["GUID"] = "1955679C",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101197/1955679C",
            },
        [10119801] = {
            ["Content"] = "{nickname}，我也来帮忙吧！",
            ["ContentKR"] = "나도 도와줄게!",
            ["DialogueId"] = 10119801,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "195577DA",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10119802,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101198/195577DA",
            },
        [10119802] = {
            ["Content"] = "不用。赛琪，趁“魔王大人”没看着……我们平分了怎么样？",
            ["ContentKR"] = "괜찮아. 프시케, '마왕님'이 보고 있지 않을 때... 우리끼리 나눠 가지는 건 어때?",
            ["DialogueId"] = 10119802,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19557804",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10119803,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101198/19557804",
            },
        [10119803] = {
            ["Content"] = "你拿着就好！可以给自己买点漂亮衣服什么的，我……没什么需要用钱的地方。",
            ["ContentKR"] = "그냥 네가 다 가져가. 예쁜 옷도 사고 그래. 난... 돈 쓸 데가 별로 없어서.",
            ["DialogueId"] = 10119803,
            ["Duration"] = 3,
            ["GUID"] = "1955782E",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101198/1955782E",
            },
        [10119901] = {
            ["Content"] = "这是什么？",
            ["ContentKR"] = "이게 뭐지?",
            ["DialogueId"] = 10119901,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19558842",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101199/19558842",
            },
        [10120001] = {
            ["Content"] = "唔……是开门的机关！藏得好严实。",
            ["ContentKR"] = "음... 문을 여는 장치였네! 정말 잘 숨겨놨는걸.",
            ["DialogueId"] = 10120001,
            ["Duration"] = 3,
            ["GUID"] = "195598AA",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101200/195598AA",
            },
        [10120101] = {
            ["Content"] = "怎么这么多……呃……呃呃……",
            ["ContentKR"] = "뭐가 이렇게 많아... 으... 으으...",
            ["DialogueId"] = 10120101,
            ["Duration"] = 3,
            ["GUID"] = "1955A912",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10120102,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101201/1955A912",
            },
        [10120102] = {
            ["Content"] = "从我大腿上下来，白。你这样我动不了了……你先回冰湖城吧，我不会笑话你的。",
            ["ContentKR"] = "일단 내 다리에서 내려와, 스노우. 네가 그러고 있으면 내가 못 움직이잖아... 먼저 아이스레이크 시티로 돌아가. 놀리지 않을 테니까.",
            ["DialogueId"] = 10120102,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "1955A93C",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10120103,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101201/1955A93C",
            },
        [10120103] = {
            ["Content"] = "不不不不回去，没没没没有经历过冒冒冒险的人生一定是不不不不不完整的！",
            ["ContentKR"] = "아, 안 안 돌아갈 거야, 모모모험을 경험해보지 못한 인생은 부부분명 완벽하지 않으니까!",
            ["DialogueId"] = 10120103,
            ["Duration"] = 3,
            ["GUID"] = "1955A966",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10120104,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101201/1955A966",
            },
        [10120104] = {
            ["Content"] = "好呀，那我就陪着{nickname}和魔王大人一起，把人生变“完整”一点吧。",
            ["ContentKR"] = "좋아, 그럼 나도 {nickname}(이)랑 마왕님과 함께 인생을 좀 더 '완전하게' 만들어볼게.",
            ["DialogueId"] = 10120104,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "1955A990",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10120105,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101201/1955A990",
            },
        [10120105] = {
            ["Content"] = "刚刚我应该没有拖后腿……所以接下来，我想也不会有问题的！",
            ["ContentKR"] = "지금까지 내가 발목 붙잡은 일은 없었던 것 같은데... 그러니까 앞으로도 걱정하지 않아도 괜찮아!",
            ["DialogueId"] = 10120105,
            ["Duration"] = 3,
            ["GUID"] = "1955A9BA",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10120106,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101201/1955A9BA",
            },
        [10120106] = {
            ["Content"] = "嗯，我们继续往前走吧。",
            ["ContentKR"] = "응, 그러면 계속 앞으로 가보자.",
            ["DialogueId"] = 10120106,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "1955A9E4",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10120107,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101201/1955A9E4",
            },
        [10120107] = {
            ["Content"] = "（只是一些寻常的秽兽，远不如净界岛那一次来得凶险……）",
            ["ContentKR"] = "(그저 평범한 필토이드일 뿐이야. 연옥도에서 마주쳤던 것만큼 위험하진 않아...)",
            ["DialogueId"] = 10120107,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "1955AA0E",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10120108,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101201/1955AA0E",
            },
        [10120108] = {
            ["Content"] = "（仔细回想贝蕾教过的防身技巧，谨慎地挥出每一次剑——可以做到的。）",
            ["ContentKR"] = "(베레가 가르쳐준 호신술을 잘 떠올리며, 조심스럽게 칼을 휘두르면... 할 수 있어.)",
            ["DialogueId"] = 10120108,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "1955AA38",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101201/1955AA38",
            },
