            },
        [10121107] = {
            ["Camera"] = "85.51416,-96.30043,125.066162,0.000233,-0.732729,147.629822,35.0,198.376389,false,Manual,1.2",
            ["Content"] = "原来是脑袋先着地吗……还好有这顶万能的锅子。",
            ["ContentKR"] = "머리가 먼저 닿았던 건가요... 다행히 이 만능 냄비가 있어서 살았네요.",
            ["DialogueId"] = 10121107,
            ["FacialId"] = {
                [1] = "200072:Ahaha02",
                },
            ["GUID"] = "19564E1E",
            ["SpeakNpcId"] = 200072,
            ["TalkActionId"] = {
                [1] = "200072:SpecialHoldHelmet_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101211/19564E1E",
            },
        [10121201] = {
            ["Content"] = "这些湿漉漉的脚印，看尺寸，应该就是那个贼留下的吧。",
            ["ContentKR"] = "(이 젖은 발자국들, 크기로 봐선 아마 그 도둑이 남긴 게 맞겠지.)",
            ["DialogueId"] = 10121201,
            ["GUID"] = "19565D8A",
            ["GuideFacialId"] = "Angry",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10121202,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101212/19565D8A",
            },
        [10121202] = {
            ["Content"] = "唔，这些秽兽是被刚刚的爆炸声引来的吗？",
            ["ContentKR"] = "(음, 조금 전 폭발 소리가 이 필토이드들을 자극한 건가?)",
            ["DialogueId"] = 10121202,
            ["GUID"] = "19565D8B",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101212/19565D8B",
            },
        [10121301] = {
            ["Content"] = "总觉得这块木板怪怪的，也许不要踩为好。",
            ["ContentKR"] = "(왠지 저 나무판자가 수상해, 밟지 않는 게 좋을 것 같아.)",
            ["DialogueId"] = 10121301,
            ["GUID"] = "19566DF2",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101213/19566DF2",
            },
        [10121302] = {
            ["Content"] = "是爆炸声！小仆从，你也中陷阱了吗？！",
            ["ContentKR"] = "폭발 소리야! 시종, 너도 함정에 걸린 거야?!",
            ["DialogueId"] = 10121302,
            ["GUID"] = "19566DF3",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10121303,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101213/19566DF3",
            },
        [10121303] = {
            ["Content"] = "没事！咳，我只是想试试这块木板牢不牢固。",
            ["ContentKR"] = "괜찮아! 크흠, 그냥 이 나무판자가 얼마나 튼튼한지 시험해 보고 싶었을 뿐이야.",
            ["DialogueId"] = 10121303,
            ["GUID"] = "19566DF4",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101213/19566DF4",
            },
        [10121401] = {
            ["Camera"] = "178.257812,-350.6875,109.97998,0.000151,-7.200406,133.796951,12.0,269.704346,false,DoNotOverride,10.0",
            ["Content"] = "又是你们？！逼老子动真格的？",
            ["ContentKR"] = "또 너희들이냐?! 진심으로 상대해 줘야겠어?!",
            ["DialogueId"] = 10121401,
            ["GUID"] = "19567E5A",
            ["SpeakNpcId"] = 200053,
            ["VoiceName"] = "voice/$Locale$/story/1002/101214/19567E5A",
            },
        [10121501] = {
            ["Content"] = "咳、咳……！呛死我了……",
            ["ContentKR"] = "콜록, 콜록...! 숨막혀 죽겠네...",
            ["DialogueId"] = 10121501,
            ["GUID"] = "19568EC2",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10121502,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101215/19568EC2",
            },
        [10121502] = {
            ["Content"] = "（这家伙是个移动杂货铺吗，身上什么都有。该不会把冰湖城偷了个遍吧？）",
            ["ContentKR"] = "(이 녀석, 움직이는 잡화점인가? 없는 게 없잖아. 설마 아이스레이크 시티를 통째로 털어버린 건가?)",
            ["DialogueId"] = 10121502,
            ["DisableMouth"] = 1,
            ["GUID"] = "19568EEC",
            ["GuideFacialId"] = "Angry",
