            },
        [10121601] = {
            ["Camera"] = "12.563477,563.442627,81.617554,-0.0,-2.99999,-90.591133,18.0,100000.0,false,Disable,2.8",
            ["CameraBlendCurve"] = "easeOutQuad",
            ["Content"] = "（门无法从这一侧打开……）",
            ["ContentKR"] = "(문이 이쪽에서는 열리지 않네...)",
            ["DialogueId"] = 10121601,
            ["FinalCamera"] = "12.563477,563.442627,100.538574,0.0,0.0,-90.591133,18.0,100000.0,false,Disable,2.8",
