            },
        [10121602] = {
            ["Camera"] = "-121.490234,-70.165771,128.248779,0.0,0.0,15.000545,35.0,155.751907,false,Manual,5.125435",
            ["Content"] = "怎么了怎么了，小贼把这扇门反锁了吗？",
            ["ContentKR"] = "어떻게 된 거죠? 도둑놈이 이 문을 안에서 잠가버린 거예요?",
            ["DialogueId"] = 10121602,
            ["GUID"] = "19569F54",
            ["LookAt"] = {
