                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101245/19587B70",
            },
        [10124601] = {
            ["Content"] = "这边的积雪有些厚，小心。",
            ["ContentKR"] = "{性别: 여기 눈이 좀 두꺼워, 조심해.|여기 눈이 많이 쌓였어, 조심해.} ",
            ["DialogueId"] = 10124601,
            ["GUID"] = "19588B5A",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10124602,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101246/19588B5A",
            },
        [10124602] = {
            ["Content"] = "嗯……那你走在前，我在后面。",
            ["ContentKR"] = "응... 그럼, 네가 앞에서 걷고, 내가 뒤에서 따라갈게.",
            ["DialogueId"] = 10124602,
            ["GUID"] = "19588B84",
