            ["NextDialogue"] = 10125003,
            ["Scripts"] = "PARA{\
MoveTo{ActorId{200006},MoveSpeed{120},TargetPoint{\"P101250Saiqi\"}}\
}",
            ["SpeakNpcId"] = 200006,
            ["ToFinalCameraBlendTime"] = 2.5,
            ["VoiceName"] = "voice/$Locale$/story/1002/101250/1958CD24",
            },
        [10125003] = {
            ["Camera"] = "153.019531,416.476562,54.358398,0.000051,4.999835,-100.502174,30.0,326.873077,false,Manual,22",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "要摘一朵留念吗？",
            ["ContentKR"] = "한 송이 따서 기념으로 가져갈까?",
            ["DialogueId"] = 10125003,
            ["FinalCamera"] = "160.480469,456.728516,50.777344,0.000051,4.999835,-100.502174,30.0,326.873077,false,Manual,22",
