        [10125102] = {
            ["Camera"] = "-157.761719,270.34375,84.228516,0.000002,-1.300195,-48.197968,50.0,243.327423,false,Manual,8.0",
            ["CameraBlendCurve"] = "easeInQuad",
            ["Content"] = "抱歉，就当这是我自私的小秘密吧。",
