            },
        [10125103] = {
            ["Camera"] = "-383.175781,979.316406,15.928711,0.000024,1.699392,-58.39698,30.0,937.541016,false,Manual,1.2",
            ["CameraBlendCurve"] = "easeInQuad",
            ["Content"] = "来，{nickname}，再给我拍一张照吧，要把冰湖城拍进去哦。",
            ["ContentKR"] = "자, {nickname}, 사진 한 장 더 찍어줘, 아이스레이크 시티도 보이게.",
            ["DialogueId"] = 10125103,
            ["FacialId"] = {
                [1] = "200027:Smile01",
                },
            ["FinalCamera"] = "-383.175781,979.316406,35.485352,0.000037,3.600001,-55.999863,30.000002,923.619934,false,Manual,1.2",
            ["GUID"] = "1958DDB6",
            ["LookAt"] = {
