        [10125201] = {
            ["Content"] = "（那边那个人好像有点眼熟……是谁来着？）",
            ["ContentKR"] = "(저 사람 좀 익숙한데... 누구였더라?)",
            ["DialogueId"] = 10125201,
            ["DisableMouth"] = 1,
            ["GUID"] = "1958EDCA",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101252/1958EDCA",
            },
        [10125301] = {
            ["Content"] = "我真要开枪了！我是说真的！！",
            ["ContentKR"] = "나 정말로 쏜다! 진짜라고!!",
            ["DialogueId"] = 10125301,
            ["GUID"] = "1958FE32",
            ["VoiceName"] = "voice/$Locale$/story/1002/101253/1958FE32",
            },
        [10125401] = {
            ["Content"] = "哇啊快跑，这块冰要碎了！",
            ["ContentKR"] = "와아! 빨리 도망쳐, 얼음이 금방 꺼질 것 같아!",
            ["DialogueId"] = 10125401,
            ["GUID"] = "19590E9A",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101254/19590E9A",
            },
        [10125501] = {
            ["Content"] = "冰面易碎，或许我们应该先躲到更稳固的台子上。",
            ["ContentKR"] = "얼음이 쉽게 깨지니까, 먼저 더 단단한 발판으로 피하는 게 좋을 것 같아.",
            ["DialogueId"] = 10125501,
            ["GUID"] = "19591F02",
            ["GuideFacialId"] = "Angry",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1002/101255/19591F02",
            },
        [10125601] = {
            ["Content"] = "（这应该是最后一段路了吧……）",
            ["ContentKR"] = "(이게 아마 마지막 구간이겠지...)",
            ["DialogueId"] = 10125601,
            ["DisableMouth"] = 1,
            ["GUID"] = "19592F6A",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10125602,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101256/19592F6A",
            },
        [10125602] = {
            ["Content"] = "（赛琪，等我……我来带你回家。）",
            ["ContentKR"] = "(프시케, 기다려... 집으로 데리러 왔어.)",
            ["DialogueId"] = 10125602,
            ["DisableMouth"] = 1,
            ["GUID"] = "19592F94",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101256/19592F94",
            },
        [10125701] = {
            ["Content"] = "{nickname}，你去了哪儿？",
            ["ContentKR"] = "{nickname}, 어디 갔어?",
            ["DialogueId"] = 10125701,
            ["GUID"] = "19593FD2",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101257/19593FD2",
            },
        [10125702] = {
            ["Content"] = "你已经走远了吗？我在这儿等你……",
            ["ContentKR"] = "이미 멀리 간 거야? 나 여기서 기다릴게...",
            ["DialogueId"] = 10125702,
            ["GUID"] = "19593FFC",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101257/19593FFC",
            },
        [10125801] = {
            ["Content"] = "回去睡会儿吧。知道你肯定睡不着，但歇一会儿也是好的。",
            ["ContentKR"] = "잠깐 쉬러 가자. 잠들 수 없을 거란 건 알지만, 잠시라도 쉬는 게 좋아.",
            ["DialogueId"] = 10125801,
            ["GUID"] = "1959503A",
            ["NextDialogue"] = 10125802,
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1002/101258/1959503A",
            },
        [10125802] = {
            ["Content"] = "不用了，我想一个人走走。",
            ["ContentKR"] = "괜찮아, 혼자 좀 걸을래.",
            ["DialogueId"] = 10125802,
            ["GUID"] = "19595064",
            ["NextDialogue"] = 10125803,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101258/19595064",
            },
        [10125803] = {
            ["Content"] = "……好，冰湖城的夜很长，你多小心。",
            ["ContentKR"] = "...알겠어, 아이스레이크 시티의 밤은 길어. 조심해.",
            ["DialogueId"] = 10125803,
            ["GUID"] = "1959508E",
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1002/101258/1959508E",
            },
        [10125901] = {
            ["Camera"] = "454.923828,1684.220703,-255.024414,8.000015,2.99999,-111.999702,35.0,320.217255,false,Manual,4.0",
            ["Content"] = "愿你的灵魂于雾海深处获得安宁……",
            ["ContentKR"] = "안개의 바다 깊은 곳에서 평안을 얻기를...",
            ["DialogueId"] = 10125901,
            ["GUID"] = "195960A2",
