                },
            ["NextDialogue"] = 10125915,
            ["SpeakNpcId"] = 200076,
            ["SpeakNpcName"] = "UI_Npc_Name_Nifu",
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1002/101259/195962C4",
            },
        [10125915] = {
            ["Camera"] = "1720.431641,1626.798828,101.317383,0.000085,-1.000022,-137.800919,50.000008,655.091675,false,Manual,22.0",
            ["Content"] = "或许，那便是她所为你留下的。",
            ["ContentKR"] = "아마 널 향한 축복이었을 거야.",
