            },
        [10130502] = {
            ["Content"] = "……准备正面迎敌！",
            ["ContentKR"] = "...정면 교전 준비!",
            ["DialogueId"] = 10130502,
            ["GUID"] = "195BD034",
            ["VoiceName"] = "voice/$Locale$/story/1002/101305/195BD034",
            },
        [10130601] = {
            ["Camera"] = "-90.074219,755.777344,469.635742,0.000111,-25.499575,-93.596069,25.0,467.444916,false,Manual,22.0",
            ["CameraBlendCurve"] = "easeInQuad",
            ["Content"] = "这是……长官，秽蚀者已经……！",
            ["ContentKR"] = "이건... 준위님, 침식자가 이미...!",
            ["DialogueId"] = 10130601,
            ["FacialId"] = {
