            ["NextDialogue"] = 10131006,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101310/195BD052",
            },
        [10131006] = {
            ["Content"] = "这么说来，刚刚的笔记还写到，废矿里可能有一种特别的秽兽出没……大家留意些，不要落单。",
            ["ContentKR"] = "그러고 보니, 방금 노트에서 광갱 안쪽에 특수한 필토이드가 출몰할 가능성이 있다고 했어... 모두 뒤처지지 않게 조심해.",
            ["DialogueId"] = 10131006,
            ["GUID"] = "195BD053",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101310/195BD053",
            },
        [10131101] = {
            ["Content"] = "快看，中间那块大晶石在发光诶！难道里面有我们要找的群星绮晶？",
            ["ContentKR"] = "봐봐! 저기 한가운데에 반짝반짝 빛나는 커다란 결정체! 저게 혹시 우리가 찾는 반짝이는 수정 아닐까?",
            ["DialogueId"] = 10131101,
            ["GUID"] = "195BD054",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101311/195BD054",
            },
        [10131201] = {
            ["Content"] = "吼——",
            ["ContentKR"] = "크르르르——",
