                [1] = "110022:Sigh_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/110101/1B9008B2",
            },
        [11010102] = {
            ["Camera"] = "102.601562,206.410156,117.232056,0.000039,-23.600208,-132.594559,28.0,179.473755,false,Manual,10.963819",
            ["Content"] = "<W>……那只巨兽正拦在你的去路，扼住你的咽喉。</>",
            ["ContentKR"] = "<W>... 지금 괴수가 널 가로막고, 네 숨통을 조이고 있다.</>",
            ["DialogueId"] = 11010102,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["FinalCamera"] = "89.054688,191.6875,108.48584,0.000039,-23.600208,-132.594559,28.0,179.473755,false,Manual,10.963819",
            ["GUID"] = "1B9008DC",
            ["NextDialogue"] = 11010103,
            ["Scripts"] = "PARA{\
PlayNormalSound{\
EventPath{\"event:/sfx/common/story/ex01/evilvo\"},PlayAs2D{true}},PostProcess{MaterailInstance{\"MaterialInstanceConstant'/Game/Asset/Scene/common/PP/MI_PP_Demon_01.MI_PP_Demon_01'\"}\
}}",
            ["SnapShot"] = "MONSTER",
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/110101/1B9008DC",
            },
        [11010103] = {
            ["Camera"] = "138.929688,18.707031,107.624329,0.000043,-26.202394,152.990067,28.0,179.473755,false,Manual,10.963819",
            ["Content"] = "<W>你的血肉之躯因窒息而悸动，疼痛叩击着你深处最隐秘的渴望。</>",
            ["ContentKR"] = "<W>너의 그 몸뚱이는 질식으로 부들부들 떨리고, 고통이 너의 가장 깊숙한 곳에 숨겨진 욕망을 두드리고 있지.</>",
            ["DialogueId"] = 11010103,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["FinalCamera"] = "138.929688,18.707031,131.753906,0.000043,-26.202394,152.990067,28.0,179.473755,false,Manual,10.963819",
            ["GUID"] = "1B900906",
            ["NextDialogue"] = 11010104,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/evilvo\"},PlayAs2D{true}}",
            ["SnapShot"] = "MONSTER",
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/1002/110101/1B900906",
            },
        [11010104] = {
            ["Camera"] = "80.007812,123.242188,115.345276,0.000047,-32.004726,-160.221619,28.0,121.418312,false,Manual,10.963819",
            ["Content"] = "（又是这个声音……）",
            ["ContentKR"] = "(또 이 목소리인가...)",
            ["DialogueId"] = 11010104,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["FinalCamera"] = "65.46875,118.03125,105.693848,0.000047,-32.004726,-160.221619,28.0,121.418312,false,Manual,10.963819",
            ["GUID"] = "1B900930",
            ["NextOptions"] = {
                [1] = 11010105,
                },
            ["RelatedWikiId"] = {
                [1] = 204001,
                },
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1002/110101/1B900930",
            },
        [11010105] = {
            ["Content"] = "（够了。从我的脑子里滚出去。）",
            ["ContentKR"] = "(그만해. 내 머릿속에서 꺼지라고.)",
            ["DialogueId"] = 11010105,
            ["GUID"] = "1B90095A",
            ["NextDialogue"] = 11010106,
            },
        [11010106] = {
            ["Camera"] = "-162.023438,188.144531,-14.760071,0.000057,25.19714,-32.413078,28.0,179.473755,false,Manual,10.963819",
            ["Content"] = "<W>杀了它。聆听它的哀嚎，沐浴它的血。拥抱这甜蜜的死亡。</>",
            ["ContentKR"] = "<W>녀석을 죽여. 녀석의 울부짖음을 듣고, 녀석의 피로 널 적시며, 그 달콤한 죽음을 받아들이는 거다.</>",
            ["DialogueId"] = 11010106,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["FinalCamera"] = "-313.984375,284.59375,-99.471802,0.000057,25.19714,-32.413078,28.0,179.473755,false,Manual,10.963819",
            ["GUID"] = "1B900984",
            ["NextOptions"] = {
                [1] = 11010107,
                [2] = 11010108,
                },
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/evilvo\"},PlayAs2D{true}}",
            ["SnapShot"] = "MONSTER",
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/1002/110101/1B900984",
            },
        [11010107] = {
            ["Content"] = "（捂住耳朵。拼尽全力隔绝这奇怪的声音。）",
            ["ContentKR"] = "(귀를 막는다. 최선을 다해 이상한 목소리를 무시한다.)",
            ["DialogueId"] = 11010107,
            ["GUID"] = "1B9009AE",
            },
        [11010108] = {
            ["Content"] = "（寻找离开这里的路。）",
            ["ContentKR"] = "(여기를 벗어날 방법을 찾는다.)",
            ["DialogueId"] = 11010108,
            ["GUID"] = "1B9009D8",
            },
        [11010116] = {
            ["Content"] = "（……总之，我必须逃离这里，逃离这如同附骨之疽的可怕念头。）",
            ["ContentKR"] = "(...어쨌든, 여기서 벗어나야 해. 이 끔찍한 생각들로부터 도망쳐야 해.)",
            ["DialogueId"] = 11010116,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B900B28",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110101/1B900B28",
            },
        [11010117] = {
            ["Content"] = ".....{nickname2}，醒醒！",
            ["ContentKR"] = "...{nickname2}, 일어나요!",
            ["DialogueId"] = 11010117,
            ["Duration"] = 3,
            ["GUID"] = "1B900B52",
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1002/110101/1B900B52",
            },
        [11010203] = {
            ["Content"] = "队长，你终于醒了！",
            ["ContentKR"] = "대장님, 드디어 깨어나셨군요!",
            ["DialogueId"] = 11010203,
            ["Duration"] = 3,
            ["GUID"] = "1B90196E",
            ["NextDialogue"] = 11010204,
            ["SpeakNpcId"] = 110019,
            ["VoiceName"] = "voice/$Locale$/story/1002/110102/1B90196E",
            },
        [11010204] = {
            ["Content"] = "那秽兽要不行了！干掉它，快！！",
            ["ContentKR"] = "필토이드가 약해진 지금이 기회입니다. 어서요!",
            ["DialogueId"] = 11010204,
            ["Duration"] = 3,
            ["GUID"] = "1B901998",
            ["NextDialogue"] = 11010205,
            ["SpeakNpcId"] = 110019,
            ["VoiceName"] = "voice/$Locale$/story/1002/110102/1B901998",
            },
        [11010205] = {
            ["Content"] = "尤里安，跟我撤到后方去！您的伤口要裂开了！",
            ["ContentKR"] = "율리안, 저랑 같이 뒤로 물러나요! 그러다 상처가 벌어질 거예요!",
            ["DialogueId"] = 11010205,
            ["Duration"] = 3,
            ["GUID"] = "1B9019C2",
            ["NextDialogue"] = 11010206,
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110102/1B9019C2",
            },
        [11010206] = {
            ["Content"] = "我们要……相信{nickname2}。",
            ["ContentKR"] = "{nickname2} 대장님을 믿어봐요.",
            ["DialogueId"] = 11010206,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B9019EC",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110102/1B9019EC",
            },
        [11010207] = {
            ["Camera"] = "-541.03125,57.806641,257.779175,0.000056,-14.399083,-25.188799,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "处理干净了……唔！",
            ["ContentKR"] = "다 해치웠나... 으윽!",
            ["DialogueId"] = 11010207,
            ["ExStoryInfo"] = "EXPlayer",
            ["FacialId"] = {
                [1] = "110022:Unhappy02",
                },
