            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110108/1B907C5C",
            },
        [11010901] = {
            ["Content"] = "是秽兽！",
            ["ContentKR"] = "필토이드다!",
            ["DialogueId"] = 11010901,
            ["Duration"] = 3,
            ["GUID"] = "1B908BF2",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110109/1B908BF2",
            },
        [11010902] = {
            ["Content"] = "达芙涅，保护伤员。",
            ["ContentKR"] = "다프네, 부상자들을 지켜요.",
            ["DialogueId"] = 11010902,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B908C1C",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110109/1B908C1C",
            },
        [11010903] = {
            ["Content"] = "……是！",
            ["ContentKR"] = "네!",
            ["DialogueId"] = 11010903,
            ["Duration"] = 3,
            ["GUID"] = "1B908C46",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110109/1B908C46",
            },
        [11011001] = {
            ["Content"] = "坚持住，我再试试联系“雪狼”分队！",
            ["ContentKR"] = "조금만 버텨주세요. 다시 '스노우 울프'와 연락을 취해볼게요!",
            ["DialogueId"] = 11011001,
            ["Duration"] = 3,
            ["GUID"] = "1B909C5A",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 11011002,
            ["Scripts"] = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"},RelatedRegionId{102101}}",
            ["SnapShot"] = "OUTDOOR",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909C5A",
            },
        [11011002] = {
            ["Content"] = "还是……没反应……",
            ["ContentKR"] = "여전히... 그대로예요...",
            ["DialogueId"] = 11011002,
            ["Duration"] = 3,
            ["GUID"] = "1B909C84",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 11011003,
            ["SnapShot"] = "OUTDOOR",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909C84",
            },
        [11011003] = {
            ["Content"] = "喂？喂？",
            ["ContentKR"] = "통신보안, 통신보안!",
            ["DialogueId"] = 11011003,
            ["Duration"] = 3,
            ["GUID"] = "1B909CAE",
            ["NextDialogue"] = 11011004,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/snapshot/story/ex01_vo_behind_door\"},PlayAs2D{true}}",
            ["SnapShot"] = "OUTDOOR",
            ["SpeakNpcId"] = 110010,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909CAE",
            },
        [11011004] = {
            ["Content"] = "接通了……！",
            ["ContentKR"] = "연결됐어요...!",
            ["DialogueId"] = 11011004,
            ["Duration"] = 3,
            ["GUID"] = "1B909CD8",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 11011005,
            ["SnapShot"] = "OUTDOOR",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909CD8",
            },
        [11011005] = {
            ["Content"] = "<H>海伯利亚今日天气怎么样？</>",
            ["ContentKR"] = "<Highlight>휘페르보레아의 오늘 날씨는 어떤가?</>",
            ["DialogueId"] = 11011005,
            ["Duration"] = 3,
            ["GUID"] = "1B909D02",
            ["NextDialogue"] = 11011006,
            ["SnapShot"] = "OUTDOOR",
            ["SpeakNpcId"] = 110010,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909D02",
            },
        [11011006] = {
            ["Content"] = "<H>迪斯玛尼亚今夜有雨。</>",
            ["ContentKR"] = "<Highlight>디즈마니아는 오늘 밤 비가 오겠습니다.</>",
            ["DialogueId"] = 11011006,
            ["Duration"] = 3,
            ["GUID"] = "1B909D2C",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 11011007,
            ["SnapShot"] = "OUTDOOR",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909D2C",
            },
        [11011007] = {
            ["Content"] = "我是阿瓦尔·赫德兰中校。对面的“狮鹫”小队队员，你们在哪里？",
            ["ContentKR"] = "아바르 헤데란 중령이다. 연결된 자는 '그리핀 소대'의 누구인가?",
            ["DialogueId"] = 11011007,
            ["Duration"] = 3,
            ["GUID"] = "1B909D56",
            ["NextDialogue"] = 11011008,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/signal_off\"},PlayAs2D{true}}",
            ["SnapShot"] = "OUTDOOR",
            ["SpeakNpcId"] = 110010,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909D56",
            },
        [11011008] = {
            ["Content"] = "医务员达芙涅·塞奥多尔请求支援。我们当前正位于……",
            ["ContentKR"] = "의무관 다프네 세오도어입니다. 지원을 요청합니다. 저희는 지금...",
            ["DialogueId"] = 11011008,
            ["Duration"] = 3,
            ["GUID"] = "1B909D80",
            ["NextDialogue"] = 11011009,
            ["SnapShot"] = "OUTDOOR",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909D80",
            },
        [11011009] = {
            ["Content"] = "没完没了……",
            ["ContentKR"] = "끝도 없군...",
            ["DialogueId"] = 11011009,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B909DAA",
            ["Scripts"] = "StopNormalSound{EventPath{\"event:/snapshot/story/ex01_vo_behind_door\"},PlayAs2D{true}}",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909DAA",
            },
        [11011010] = {
            ["Content"] = "小鬼，撑住！",
            ["ContentKR"] = "꼬맹이, 조금만 버텨!",
            ["DialogueId"] = 11011010,
            ["Duration"] = 3,
            ["GUID"] = "1B909DD4",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909DD4",
            },
        [11011011] = {
            ["Content"] = "阿瓦尔老师！",
            ["ContentKR"] = "아바르 교관님!",
            ["DialogueId"] = 11011011,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B909DFE",
            ["NextDialogue"] = 11011012,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909DFE",
            },
        [11011012] = {
            ["Content"] = "嗯，有我呢。你专心应付眼前，背后交给我就是。",
            ["ContentKR"] = "그래, 내가 왔으니 뒤는 나한테 맡기고 앞만 신경 써라.",
            ["DialogueId"] = 11011012,
            ["GUID"] = "1B909E28",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909E28",
            },
        [11011013] = {
            ["Content"] = "我们暂时击退了来袭的秽兽，清理出一个临时休整点，不过这边也坚持不了太久。",
            ["ContentKR"] = "우선 이곳의 필토이드를 처리하고 임시 정비 구역을 마련했지만, 여기도 오래 버티긴 힘들 것 같습니다.",
            ["DialogueId"] = 11011013,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B909E52",
            ["NextDialogue"] = 11011014,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909E52",
            },
        [11011014] = {
            ["Content"] = "达芙涅紧急救治了伤员，但据伤情判断，他们已经暂时丧失了作战能力。",
            ["ContentKR"] = "부상자들은 다프네가 임시 치료를 하긴 했지만, 부상 정도를 볼 때 지금 상태로 싸우기는 무리입니다.",
            ["DialogueId"] = 11011014,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B909E7C",
            ["NextDialogue"] = 11011015,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909E7C",
            },
        [11011015] = {
            ["Content"] = "……好。你们也辛苦了。",
            ["ContentKR"] = "...그래. 고생이 많았겠군.",
            ["DialogueId"] = 11011015,
            ["GUID"] = "1B909EA6",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909EA6",
            },
        [11011016] = {
            ["Content"] = "阿瓦尔长官！哈、哈……你来了！你一定会带着大家……攻下这座要塞……",
            ["ContentKR"] = "아바르 중령님! 휴, 후우... 오셨군요! 아바르 중령님이 오셨으니 이제... 이 요새를 공격하러...",
            ["DialogueId"] = 11011016,
            ["GUID"] = "1B909ED0",
            ["NextDialogue"] = 11011017,
            ["SpeakNpcId"] = 110019,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909ED0",
            },
        [11011017] = {
            ["Content"] = "你们都是好样的，你们的勇敢对得起胸口的徽章，帝国不会让你们在这里白白流血。",
            ["ContentKR"] = "가슴에 달린 제국 휘장에 걸맞은 용기를 가졌다니, 모두 훌륭하군. 제국은 자네들이 흘린 피를 절대 헛되이 만들지 않겠다.",
            ["DialogueId"] = 11011017,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["GUID"] = "1B909EFA",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909EFA",
            },
        [11011018] = {
            ["Content"] = "长官，“雪狼”那边怎么样了？",
            ["ContentKR"] = "중령님, '스노우 울프' 쪽은 어떻습니까?",
            ["DialogueId"] = 11011018,
            ["GUID"] = "1B909F24",
            ["NextDialogue"] = 11011019,
            ["SpeakNpcId"] = 110013,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909F24",
            },
        [11011019] = {
            ["Content"] = "雪狼分队一切正常。我已经联系上了总指挥官，你们尽管放心休息，接下来就交给我们。",
            ["ContentKR"] = "모두 임무를 잘 수행하고 있다. 내가 총지휘관님께 연락을 취했으니, 마음 놓고 쉬어도 된다. 나머지는 우리에게 맡겨라.",
            ["DialogueId"] = 11011019,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["GUID"] = "1B909F4E",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909F4E",
            },
        [11011020] = {
            ["Content"] = "阿瓦尔长官？我……在做梦吗……",
            ["ContentKR"] = "아바르 중령님? 제가... 꿈을 꾸는...",
            ["DialogueId"] = 11011020,
            ["GUID"] = "1B909F78",
            ["NextDialogue"] = 11011021,
            ["SpeakNpcId"] = 110027,
            ["SpeakNpcName"] = "UI_Npc_Hurtsoldier",
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909F78",
            },
        [11011021] = {
            ["Content"] = "这不是梦。坚持住，别睡着。",
            ["ContentKR"] = "꿈이 아니다. 조금만 더 버텨라. 잠들지 마라.",
            ["DialogueId"] = 11011021,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["GUID"] = "1B909FA2",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909FA2",
            },
        [11011022] = {
            ["Content"] = "向您致意……长官……荣耀……尽归吾皇……",
            ["ContentKR"] = "중령님, 부디... 황제 폐하께... 영광을...",
            ["DialogueId"] = 11011022,
            ["GUID"] = "1B909FCC",
            ["NextDialogue"] = 11011023,
            ["SpeakNpcId"] = 110028,
            ["SpeakNpcName"] = "UI_Npc_Hurtsoldier",
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909FCC",
            },
        [11011023] = {
            ["Content"] = "荣耀尽归吾皇。",
            ["ContentKR"] = "황제 폐하께 영광을.",
            ["DialogueId"] = 11011023,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["GUID"] = "1B909FF6",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909FF6",
            },
        [11011024] = {
            ["Content"] = "长官，以你们的判断，这次作战还有希望吗？",
            ["ContentKR"] = "대장님, 그리고 중령님... 이번 작전에 아직 희망이 있겠습니까?",
            ["DialogueId"] = 11011024,
            ["GUID"] = "1B90A020",
            ["NextDialogue"] = 11011025,
            ["SpeakNpcId"] = 110026,
            ["SpeakNpcName"] = "UI_Npc_Hurtsoldier",
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B90A020",
            },
        [11011025] = {
            ["Content"] = "以当前的战况来看——",
            ["ContentKR"] = "현재 상황으로 볼 때...",
            ["DialogueId"] = 11011025,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B90A04A",
            ["NextDialogue"] = 11011026,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B90A04A",
            },
        [11011026] = {
            ["Content"] = "以当前的战况来看，援军就在路上。我们很快会夺下要塞，把那群混蛋打得头破血流。",
            ["ContentKR"] = "현재 전황으로 볼 때, 지원군도 오는 중이니 금방 요새를 점령하고, 그 놈들을 박살 낼 수 있을 것이다.",
            ["DialogueId"] = 11011026,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["GUID"] = "1B90A074",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B90A074",
            },
        [11011101] = {
            ["Camera"] = "320.033203,-633.472656,260.888916,0.000053,-14.19958,121.341087,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "我看过大家的情况了。",
            ["ContentKR"] = "현재 상황이 어떤지는 모두 잘 확인했다.",
            ["DialogueId"] = 11011101,
            ["FinalCamera"] = "350.376953,-614.980469,260.888916,0.000053,-14.19958,121.341087,35.0,100000.0,false,Manual,22.0",
