            },
        [11011103] = {
            ["Camera"] = "257.042969,179.53125,146.075317,0.000055,-3.799197,-141.261063,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "怎么了？既然胳膊腿都好好的，就打起精神来！",
            ["ContentKR"] = "모두 팔다리는 멀쩡한 것에 위안을 삼아야겠군. 그래도 여기서 멍하니 있을 수는 없지 않나, 정신 차려!",
            ["DialogueId"] = 11011103,
            ["FinalCamera"] = "259.916016,175.957031,146.075317,0.000055,-3.799197,-141.261063,35.0,100000.0,false,Manual,22.0",
            ["GUID"] = "1B90AD16",
