            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E048",
            },
        [11011418] = {
            ["Content"] = "我们必须让那些机关瘫痪掉……维克不能白白牺牲。",
            ["ContentKR"] = "빅의 희생을 헛되게 만들지 않으려면... 저 장치들의 작동을 반드시 종료해야 한다.",
            ["DialogueId"] = 11011418,
            ["Duration"] = 3,
            ["GUID"] = "1B90E0C4",
            ["GuideFacialId"] = "Angry",
            ["HeadIconType"] = "Npc",
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E0C4",
            },
        [11011419] = {
            ["Content"] = "哦？已经处理好一个了吗，小心些，我好像听到秽兽靠过来的声音了。",
            ["DialogueId"] = 11011419,
            ["Duration"] = 3,
            ["GUID"] = "1B90E0EE",
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E0EE",
            },
        [11011420] = {
            ["Content"] = "好，{nickname2}，动力链接已经断开了，我们得趁现在去把整个动力装置都毁了。",
            ["DialogueId"] = 11011420,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B90E118",
            ["NextDialogue"] = 11011421,
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E118",
            },
        [11011421] = {
            ["Content"] = "核心的动力炉就在下面，小心些……",
            ["DialogueId"] = 11011421,
            ["Duration"] = 3,
            ["GUID"] = "1B90E142",
            ["NextDialogue"] = 11011422,
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E142",
            },
        [11011422] = {
            ["Content"] = "有些脏东西围过来了……事办妥了再上来集合！",
            ["DialogueId"] = 11011422,
            ["Duration"] = 3,
            ["GUID"] = "1B90E16C",
            ["NextDialogue"] = 11011423,
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E16C",
            },
        [11011423] = {
            ["Content"] = "好……",
            ["DialogueId"] = 11011423,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B90E196",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E196",
            },
        [11011424] = {
            ["Content"] = "我会逐个解锁防护屏障，等信号亮起，你就把月髓舱打碎！",
            ["ContentKR"] = "내가 방어막을 하나씩 해제할 테니, 신호가 들어오면 폭시코르를 부수면 된다!",
            ["DialogueId"] = 11011424,
            ["Duration"] = 3,
            ["GUID"] = "1B90E1C0",
            ["NextDialogue"] = 11011425,
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E1C0",
            },
        [11011425] = {
            ["Content"] = "有些月髓舱可能会配备自毁装置，如果听到倒计时响起，就终止行动，马上离开。",
            ["ContentKR"] = "어떤 폭시코르에는 자폭 장치가 있을 수 있어. 카운트다운 소리가 들리면 즉시 행동을 중지하고 빠져나와.",
            ["DialogueId"] = 11011425,
            ["Duration"] = 3,
            ["GUID"] = "1B90E1C1",
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E1C1",
            },
        [11011426] = {
            ["Content"] = "就是现在，打碎它！",
            ["ContentKR"] = "지금이다. 파괴해!",
            ["DialogueId"] = 11011426,
            ["Duration"] = 3,
            ["GUID"] = "1B90E1C2",
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E1C2",
            },
        [11011427] = {
            ["Content"] = "干得不错，我们还有两个要处理。",
            ["ContentKR"] = "좋아. 이제 두 개만 처리하면 된다.",
            ["DialogueId"] = 11011427,
            ["Duration"] = 3,
            ["GUID"] = "1B90E1C3",
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E1C3",
            },
        [11011428] = {
            ["Content"] = "2号月髓舱的屏障解锁了，上吧！",
            ["ContentKR"] = "2호 폭시코르 방어막이 해제됐다. 지금이다!",
            ["DialogueId"] = 11011428,
            ["Duration"] = 3,
            ["GUID"] = "1B90E1C4",
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E1C4",
            },
        [11011429] = {
            ["Content"] = "呼……还有最后一个，你那儿还行吗？",
            ["ContentKR"] = "휴…… 이제 하나 남았군. 괜찮나?",
            ["DialogueId"] = 11011429,
            ["Duration"] = 3,
            ["GUID"] = "1B90E1C5",
            ["NextDialogue"] = 11011430,
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E1C5",
            },
        [11011430] = {
            ["Content"] = "没问题。",
            ["ContentKR"] = "괜찮습니다.",
            ["DialogueId"] = 11011430,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B90E1C6",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E1C6",
            },
        [11011432] = {
            ["Content"] = "好了，3号，最后一个！",
            ["ContentKR"] = "좋아, 3호, 마지막이다!",
            ["DialogueId"] = 11011432,
            ["GUID"] = "1B90E2E7",
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E2E7",
            },
        [11011433] = {
            ["Content"] = "……自毁倒计时？",
            ["ContentKR"] = "…… 자폭 카운트다운인가?",
            ["DialogueId"] = 11011433,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B90E2E8",
            ["NextDialogue"] = 11011434,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E2E8",
            },
        [11011434] = {
            ["Content"] = "动力室要爆炸了，快走！",
            ["ContentKR"] = "동력실이 폭발한다. 빨리 나와!",
            ["DialogueId"] = 11011434,
            ["GUID"] = "1B90E2E9",
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E2E9",
            },
