            },
        [11011514] = {
            ["Camera"] = "-208.61084,-34.998047,124.695801,0.0,3.399972,25.594477,28.000006,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我倒是想光荣，只是如果您的保密工作和行动计划能稍微可靠那么一点点，士兵们此刻会在中央控制室开庆功会，而不是一个个躺在冷冰冰的钢板上。",
            ["ContentKR"] = "대령님이 비밀 유지와 작전에 조금만 더 신경을 쓰셨더라면 병사들은 지금 차가운 철판에 누워 있는 게 아니라 중앙 관제실에서 축하 파티를 열고 있었을 텐데 말입니다.",
            ["DialogueId"] = 11011514,
            ["Duration"] = 3,
