        [11011540] = {
            ["Camera"] = "-355.052734,1504.162109,650.109497,0.000091,-19.999565,-79.788002,28.000006,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "队长、队长！",
            ["ContentKR"] = "대장님, 대장님!",
            ["DialogueId"] = 11011540,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["FinalCamera"] = "-330.253906,1366.505859,599.202942,0.00009,-19.999557,-79.787865,28.000006,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1B90F4C8",
            ["NextDialogue"] = 11011541,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/signal_on\"},PlayAs2D{true}}",
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcName"] = "UI_Npc_HelpVoice",
            ["TalkActionId"] = {
                [1] = "110022:Call_Start",
                },
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/1002/110115/1B90F4C8",
            },
        [11011541] = {
            ["Content"] = "我是“狮鹫”分队的西蒙，队长，你在吗？",
            ["ContentKR"] = "'그리핀' 소대의 시몬입니다. 대장님, 들리십니까?",
            ["DialogueId"] = 11011541,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["GUID"] = "1B90F4F2",
            ["NextDialogue"] = 11011542,
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcName"] = "UI_Npc_HelpVoice",
            ["VoiceName"] = "voice/$Locale$/story/1002/110115/1B90F4F2",
            },
        [11011542] = {
            ["Camera"] = "-140.854004,198.513672,147.002014,1.0,-9.599516,-74.977852,28.000006,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我在听。西蒙，你在哪里？",
            ["ContentKR"] = "듣고 있다. 시몬, 지금 어디 있지?",
            ["DialogueId"] = 11011542,
            ["ExStoryInfo"] = "EXPlayer",
            ["FinalCamera"] = "-133.268555,200.566406,146.866943,0.999995,-9.599516,-74.977119,28.000006,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1B90F51C",
            ["NextDialogue"] = 11011543,
            ["SpeakNpcId"] = 110022,
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/story/1002/110115/1B90F51C",
            },
        [11011543] = {
            ["Content"] = "轨道线一带有大片秽兽，大家被困在里面，请求支援！",
            ["ContentKR"] = "선로에 엄청난 규모의 필토이드가 몰려있고, 저희 병사들이 안에 갇혀 있습니다. 지원이 필요한 상황입니다!",
            ["DialogueId"] = 11011543,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["GUID"] = "1B90F546",
            ["NextDialogue"] = 11011544,
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcName"] = "UI_Npc_HelpVoice",
            ["VoiceName"] = "voice/$Locale$/story/1002/110115/1B90F546",
            },
        [11011544] = {
            ["Content"] = "拜托……你了！",
            ["ContentKR"] = "제발... 부탁드립니다!",
            ["DialogueId"] = 11011544,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["GUID"] = "1B90F570",
            ["NextDialogue"] = 11011545,
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcName"] = "UI_Npc_HelpVoice",
            ["VoiceName"] = "voice/$Locale$/story/1002/110115/1B90F570",
            },
        [11011545] = {
            ["Camera"] = "-3.358398,-61.634766,129.081787,0.000143,-6.799275,-81.393707,28.000006,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "…………",
            ["ContentKR"] = "......",
            ["DialogueId"] = 11011545,
            ["ExStoryInfo"] = "EXPlayer",
            ["FacialId"] = {
                [1] = "110022:Angry01",
                },
            ["GUID"] = "1B90F59A",
            ["NextDialogue"] = 11011546,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/signal_off\"},PlayAs2D{true}}",
            ["SpeakNpcId"] = 110022,
            ["TalkActionId"] = {
                [1] = "110022:Call_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110115/1B90F59A",
            },
        [11011546] = {
            ["Camera"] = "170.827637,-188.957031,121.458923,0.000164,-2.399261,154.39566,28.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我也收到了另一队士兵汇报位置的信号，就在刚结束富尔维斯通讯的时候。{nickname2}，你怎么打算？",
            ["ContentKR"] = "나도 방금 풀비스와의 통신이 끝나자마자 다른 소대 병사들의 위치 신호를 받았다. {nickname2}, 넌 어떻게 할 생각이지?",
            ["DialogueId"] = 11011546,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B90F5C4",
            ["LookAt"] = {
                [1] = "110010:n(110022)",
                },
            ["NextOptions"] = {
                [1] = 11011547,
                [2] = 11011549,
                },
            ["SpeakNpcId"] = 110010,
            ["TalkActionId"] = {
                [1] = "110010:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110115/1B90F5C4",
            },
        [11011547] = {
            ["Content"] = "我想先去救援士兵们，现在的情况，只靠我们没什么胜算。",
            ["ContentKR"] = "우선 다른 병사들을 구하러 가는 게 좋을 것 같습니다. 지금 상황에 저희 둘로는 승산이 없습니다.",
            ["DialogueId"] = 11011547,
            ["GUID"] = "1B90F5EE",
            ["ImprPlusId"] = 1009,
            ["NextDialogue"] = 11011548,
            },
        [11011548] = {
            ["Camera"] = "170.827637,-188.957031,121.458923,0.000164,-2.399261,154.39566,28.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你啊……我果然没看错你。",
            ["ContentKR"] = "너... 역시 내가 사람을 제대로 봤군.",
            ["DialogueId"] = 11011548,
            ["Duration"] = 3,
            ["GUID"] = "1B90F618",
            ["LookAt"] = {
                [1] = "110010:n(110022)",
                },
            ["NextDialogue"] = 11011550,
            ["SpeakNpcId"] = 110010,
            ["TalkActionId"] = {
                [1] = "110010:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110115/1B90F618",
            },
        [11011549] = {
            ["Content"] = "我认为即使胜算不大，也应该执行总指挥官的命令。",
            ["ContentKR"] = "승산이 크지 않더라도 총지휘관의 명령을 수행해야 한다고 봅니다.",
            ["DialogueId"] = 11011549,
            ["GUID"] = "1B90F642",
            ["ImprPlusId"] = 1007,
            ["NextDialogue"] = 11011550,
            },
        [11011550] = {
            ["Camera"] = "276.480469,1274.542969,240.643982,0.000117,-3.999116,-107.394035,28.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "富尔维斯傲慢又好大喜功，他高高在上地指挥你，靠的不过是富尔维斯家族在元老院中的世袭席位。",
            ["ContentKR"] = "풀비스는 교만하고 공을 세우는 데만 혈안이 된 자야. 풀비스 가문이 원로원에서 작위를 세습한 덕에 지휘관 자리에 앉아서 명령을 내리는 것뿐이다.",
            ["DialogueId"] = 11011550,
            ["Duration"] = 3,
            ["FinalCamera"] = "236.748047,1279.9375,274.560486,0.000103,-3.999116,-107.394089,28.000006,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1B90F66C",
            ["LookAt"] = {
                [1] = "110010:n(110022)",
                },
            ["NextDialogue"] = 11011551,
            ["SpeakNpcId"] = 110010,
            ["TalkActionId"] = {
                [1] = "110010:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 25,
            ["VoiceName"] = "voice/$Locale$/story/1002/110115/1B90F66C",
            },
        [11011551] = {
            ["Content"] = "士兵们在他眼里是汇报书里的一串数字，勋章上的一块铁，唯独不是活生生的人。",
            ["ContentKR"] = "풀비스 눈에 병사들은 그저 보고서의 숫자에 불과하고, 훈장의 한 조각일 뿐이야. 살아 있는 사람으로 보지 않는다고.",
            ["DialogueId"] = 11011551,
            ["Duration"] = 3,
            ["GUID"] = "1B90F696",
            ["NextDialogue"] = 11011552,
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110115/1B90F696",
            },
        [11011552] = {
            ["Camera"] = "-23.271973,-38.910156,134.332947,0.000116,-1.398891,154.005493,28.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "更何况，战场瞬息万变，他空对着一张地图又能知道什么？",
            ["ContentKR"] = "게다가 전장은 순식간에 변하는 법인데 달랑 지도 한 장만 보는 걸로, 뭘 알 수 있겠는가?",
            ["DialogueId"] = 11011552,
            ["Duration"] = 3,
            ["GUID"] = "1B90F6C0",
            ["NextDialogue"] = 11011553,
            ["SpeakNpcId"] = 110010,
            ["TalkActionId"] = {
                [1] = "110010:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110115/1B90F6C0",
            },
        [11011553] = {
            ["Camera"] = "-116.939453,59.931641,129.807434,0.000084,-6.599089,-65.392105,28.000008,100000.0,false,Manual,8.0",
            ["Content"] = "去救你的战友，{nickname2}。富尔维斯事后问责起来，就说是我的命令。",
            ["ContentKR"] = "전우들을 구하러 가라, {nickname2}. 풀비스가 나중에 책임을 물으면 내 명령이었다고 해.",
            ["DialogueId"] = 11011553,
            ["Duration"] = 3,
            ["GUID"] = "1B90F6EA",
            ["NextDialogue"] = 11011554,
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110115/1B90F6EA",
            },
        [11011554] = {
            ["Content"] = "是。",
            ["ContentKR"] = "알겠습니다.",
            ["DialogueId"] = 11011554,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B90F714",
            ["NextDialogue"] = 11011555,
            ["SpeakNpcId"] = 110022,
            ["TalkActionId"] = {
                [1] = "110022:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110115/1B90F714",
            },
        [11011555] = {
            ["Camera"] = "57.235352,-148.5625,119.510437,0.000097,-0.398992,145.808975,28.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我和莫妮卡也出发去救援另一群士兵，他们被困在了4号炮台附近。",
            ["ContentKR"] = "4호 포대 근처에 다른 무리가 갇혀 있다고 하니까, 난 모니카와 그쪽 병사들을 구조하러 가겠다.",
            ["DialogueId"] = 11011555,
            ["Duration"] = 3,
            ["GUID"] = "1B90F73E",
            ["NextDialogue"] = 11011556,
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110115/1B90F73E",
            },
        [11011556] = {
            ["Content"] = "……我们刚刚解除了动力，炮台的自动防御应该停止了……或许可以考虑先攻下炮台……",
            ["ContentKR"] = "...방금 우리가 동력을 차단해서 포대의 자동 방어 시스템은 멈췄을 테니... 포대부터 점령하는 것도 괜찮겠군...",
            ["DialogueId"] = 11011556,
            ["Duration"] = 3,
            ["GUID"] = "1B90F768",
            ["NextDialogue"] = 11011557,
            ["SpeakNpcId"] = 110010,
            ["TalkActionId"] = {
                [1] = "110010:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110115/1B90F768",
            },
        [11011557] = {
            ["Content"] = "……这样一来，我们还能用月髓炮轰开中心区的防御设施。",
            ["ContentKR"] = "...그렇게 하면 폭시코르 캐논을 조작해서 중앙 구역의 방어 설비를 폭파할 수 있을 거다.",
            ["DialogueId"] = 11011557,
            ["Duration"] = 3,
            ["GUID"] = "1B90F769",
            ["NextDialogue"] = 11011558,
            ["SpeakNpcId"] = 110010,
            ["TalkActionId"] = {
                [1] = "110010:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110115/1B90F769",
            },
        [11011558] = {
            ["Camera"] = "-3.358398,-61.634766,129.081787,0.000143,-6.799255,-81.393669,28.000006,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "就这么办吧。如果你那边顺利，等下就到4号炮台来。",
            ["ContentKR"] = "이렇게 하지. 그쪽 상황에 별다른 문제가 없으면 이따 4호 포대로 와라.",
            ["DialogueId"] = 11011558,
            ["GUID"] = "1B90F76A",
            ["SpeakNpcId"] = 110010,
            ["TalkActionId"] = {
                [1] = "110022:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110115/1B90F76A",
            },
        [11011601] = {
