            },
        [11011704] = {
            ["Content"] = "通讯器的呼叫音",
            ["ContentKR"] = "*통신기 신호음*",
            ["DialogueId"] = 11011704,
            ["Duration"] = 3,
            ["GUID"] = "1B910FB0",
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/call_02\"},PlayAs2D{true}}",
            ["VoiceName"] = "voice/$Locale$/story/1002/110117/1B910FB0",
            },
        [11011705] = {
            ["Content"] = "……喂？",
            ["ContentKR"] = "...통신보안?",
            ["DialogueId"] = 11011705,
            ["Duration"] = 3,
            ["GUID"] = "1B910FDA",
            ["NextDialogue"] = 11011706,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/signal_on\"},PlayAs2D{true}}",
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110117/1B910FDA",
            },
        [11011706] = {
            ["Content"] = "喂？我是“狮鹫”分队医务员达芙涅·塞奥多尔。",
            ["ContentKR"] = "통신보안? 저는 '그리핀' 소대 의무관 다프네 세오도어입니다.",
            ["DialogueId"] = 11011706,
            ["Duration"] = 3,
            ["GUID"] = "1B911004",
            ["NextDialogue"] = 11011707,
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110117/1B911004",
            },
        [11011707] = {
            ["Content"] = "……{nickname2}？是你吗？为什么不说话？你受伤了？",
            ["ContentKR"] = "...{nickname2} 대장? 맞죠? 왜 아무 말도 안하세요? 설마 다치신 건가요?",
            ["DialogueId"] = 11011707,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B91102E",
            ["NextDialogue"] = 11011708,
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110117/1B91102E",
            },
        [11011708] = {
            ["Content"] = "你在哪儿？我马上申请赶过去……",
            ["ContentKR"] = "지금 어디에 계세요? 제가 지금 바로 갈테니...",
            ["DialogueId"] = 11011708,
            ["Duration"] = 3,
            ["GUID"] = "1B911058",
            ["NextDialogue"] = 11011709,
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110117/1B911058",
            },
        [11011709] = {
            ["Content"] = "我……只是想听听你们的声音。我没事，你们还好吗？",
            ["ContentKR"] = "그냥... 목소리라도 들으려고 연락했습니다. 저는 괜찮아요. 그쪽 상황은 어떻습니까?",
            ["DialogueId"] = 11011709,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B911082",
            ["NextDialogue"] = 11011710,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110117/1B911082",
            },
        [11011710] = {
            ["Content"] = "“雪狼”的残兵和我们会合了，我们这里暂时还算安稳。你那边呢？",
            ["ContentKR"] = "'스노우 울프'의 남은 병사들이 합류해서 지금은 안전해요. 그쪽은요?",
            ["DialogueId"] = 11011710,
            ["Duration"] = 3,
            ["GUID"] = "1B9110AC",
            ["NextDialogue"] = 11011711,
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110117/1B9110AC",
            },
        [11011711] = {
            ["Content"] = "……我……也很好。我继续执行任务了，再见。",
            ["ContentKR"] = "...여기도... 괜찮습니다. 임무를 마저 해야 해서, 그럼 이만.",
            ["DialogueId"] = 11011711,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B9110D6",
            ["NextDialogue"] = 11011712,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110117/1B9110D6",
            },
        [11011712] = {
            ["Content"] = "请多保重……我们会在迪斯玛尼亚平安重逢。",
            ["ContentKR"] = "몸조심하세요... 디즈마니아에서 꼭 다시 만나요.",
            ["DialogueId"] = 11011712,
            ["Duration"] = 3,
            ["GUID"] = "1B911100",
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/signal_off\"},PlayAs2D{true}}",
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110117/1B911100",
            },
        [11011801] = {
            ["Content"] = "队长！嗨——在这里！",
            ["ContentKR"] = "대장님! 이쪽입니다!",
            ["DialogueId"] = 11011801,
            ["Duration"] = 3,
            ["GUID"] = "1B911F9A",
            ["SpeakNpcId"] = 110015,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1002/110118/1B911F9A",
            },
        [11011802] = {
            ["Camera"] = "-485.80957,430.660156,148.512939,0.000044,-2.39937,-69.002335,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "啊，队长，我亲爱的队长！！终于找到你了！！我们的联络频段突然出现异常，这一路谁也联系不上，西蒙就跑出去求救了。",
            ["ContentKR"] = "아, 대장님, 사랑하는 대장님!! 드디어 오셨군요!! 저희 무전기 주파수에 문제가 생겨서 계속 연락을 못했는데, 시몬이 구조 요청을 하러 나갔는데요.",
            ["DialogueId"] = 11011802,
            ["FinalCamera"] = "-485.80957,430.660156,123.858765,0.000044,-2.39937,-69.002335,35.000008,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1B911FC4",
            ["LookAt"] = {
                [1] = "110043:n(110022)",
                [2] = "110022:n(110043)",
                },
            ["NextDialogue"] = 11011803,
            ["RelatedWikiId"] = {
                [1] = 204001,
                [2] = 201012,
                [3] = 201013,
                [4] = 408007,
                [5] = 101004,
                },
            ["Scripts"] = "SEQ{\
