  { MinKey = 11011842, MaxKey = 11012806, Loader = function()
      return {
        [11011842] = {
            ["Content"] = "可是，不动的话……就没法为您指路了……",
            ["ContentKR"] = "하지만 움직이지 않으면... 길을 안내할 수 없는걸요...",
            ["DialogueId"] = 11011842,
            ["Duration"] = 3,
            ["GUID"] = "1B912654",
            ["NextDialogue"] = 11011843,
            ["SpeakNpcId"] = 110034,
            },
        [11011843] = {
            ["Content"] = "对哦，也是。",
            ["ContentKR"] = "아, 그렇네.",
            ["DialogueId"] = 11011843,
            ["Duration"] = 3,
            ["GUID"] = "1B91267E",
            ["NextDialogue"] = 11011844,
            ["SpeakNpcId"] = 110015,
            },
        [11011844] = {
            ["Content"] = "您无需这样戒备，普通的卡戎之民也是人，大家和您一样，都有妈妈，都想回去和她团聚。",
            ["ContentKR"] = "그렇게 경계하지 않아도 돼요. 평범한 카론도 사람이에요. 여러분처럼 저희도 모두 엄마가 있고 또 어서 돌아가 엄마를 만나고 싶은 마음 뿐이에요.",
            ["DialogueId"] = 11011844,
            ["Duration"] = 3,
            ["GUID"] = "1B9126A8",
            ["NextDialogue"] = 11011845,
            ["SpeakNpcId"] = 110034,
            },
        [11011845] = {
            ["Content"] = "……唉，卡嘉……",
            ["ContentKR"] = "...아아, 카지아...",
            ["DialogueId"] = 11011845,
            ["GUID"] = "1B9126D2",
            ["NextDialogue"] = 11011846,
            ["SpeakNpcId"] = 110017,
            },
        [11011846] = {
            ["Content"] = "……队长，为什么要阻止我？！",
            ["ContentKR"] = "...대장님, 왜 저를 막으신 겁니까?!",
            ["DialogueId"] = 11011846,
            ["GUID"] = "1B9126FC",
            ["NextDialogue"] = 11011847,
            ["SpeakNpcId"] = 110016,
            },
        [11011847] = {
            ["Content"] = "不一定所有卡戎之民都是同盟那些反抗者——比如阿瓦尔长官也是卡戎之民。就算这几个人真的是同盟成员，活着的他们也比死了的他们更有价值。",
            ["ContentKR"] = "모든 카론이 포세이큰 같이 적인 건 아니야. 아바르 중령님도 카론이잖아. 이 중 몇 명이 정말로 포세이큰 동맹 소속이라 해도 죽이는 것보단 살려 두는 게 더 쓸모 있을 거야.",
            ["DialogueId"] = 11011847,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B912726",
            ["NextDialogue"] = 11011848,
            ["SpeakNpcId"] = 110022,
            },
        [11011848] = {
            ["Content"] = "……无论心里有什么声音在回响，都不要屈从它们。马尔科，不要让冲动凌驾在理智之上。",
            ["ContentKR"] = "...마음속에서 어떤 소리가 들리더라도 그것에 굴복하지 마라, 마르코. 충동에 사로잡히면 안돼.",
            ["DialogueId"] = 11011848,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B912750",
            ["SpeakNpcId"] = 110022,
            },
        [11011849] = {
