            ["SpeakNpcId"] = 110022,
            ["TalkActionId"] = {
                [1] = "110009:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110124/1B9182DC",
            },
        [11012407] = {
            ["Content"] = "找我干什么？向我展示海伯利亚军官老爷不计前嫌的大度？还是假惺惺地惋惜一下我这个“误入歧途”的可怜小姑娘，想要“拯救”我啊？",
            ["ContentKR"] = "날 왜 찾아오셨을까? 우리 휘페르보레아 제국 장교 나리는 아량이 넓다는 걸 보여 주려고? 아니면 '잘못된 길로 빠진' 불쌍한 소녀를 동정하는 척 날 '구원'하려고 그러시나?",
            ["DialogueId"] = 11012407,
            ["FacialId"] = {
                [1] = "110009:Happy01",
                },
            ["GUID"] = "1B918306",
            ["LookAt"] = {
                [1] = "110022:n(110009)",
                },
            ["NextDialogue"] = 11012408,
            ["Scripts"] = "PARA{\
SEQ{\
