        [11012447] = {
            ["Camera"] = "17.73999,15.974609,99.406067,-0.00278,-44.606674,-61.595421,15.610328,100000.0,false,Manual,22.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "<W>不要再犹豫了！快用你的剑！它在呼唤着你，它在等待着血肉赐予的甜蜜与欢愉！</>",
            ["ContentKR"] = "<W>뭘 망설이는 거야! 어서 칼을 휘둘러! 칼이 피와 살의 달콤함과 기쁨을 갈망하는 소리가 들리지 않아?</>",
            ["DialogueId"] = 11012447,
            ["DisableMouth"] = 1,
