            },
        [11012609] = {
            ["Camera"] = "36.704773,-12.279297,139.930115,0.000127,-6.395844,109.990677,15.610328,100000.0,false,Manual,22.0",
            ["Content"] = "（刚才那些……是幻觉吗……）",
            ["ContentKR"] = "(방금 그건... 환각이었나...)",
            ["DialogueId"] = 11012609,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
