            ["VoiceName"] = "voice/$Locale$/story/1002/110126/1B91A42B",
            },
        [11012701] = {
            ["Camera"] = "-17.772652,-716.293457,114.469177,0.5,-3.598355,87.691597,40.000011,850.827148,false,Manual,10.225481",
            ["Content"] = "看来富尔维斯的援军短时间内是等不来了。",
            ["ContentKR"] = "당장은 풀비스의 지원군이 금방 도착하길 기대하긴 힘들 것 같군.",
            ["DialogueId"] = 11012701,
