                [1] = "110016:n(110010)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110127/1B91B36C",
            },
        [11012703] = {
            ["Camera"] = "-12.380791,280.555664,122.310181,0.000131,-5.199953,-55.185879,35.0,351.159821,false,Manual,8.87682",
            ["Content"] = "而她这样的埋伏，前面不知道还有多少。",
            ["ContentKR"] = "다만 저 여자 같은 매복이 얼마나 더 있을지 모른다는 문제가 있습니다.",
            ["DialogueId"] = 11012703,
            ["Duration"] = 3,
