            ["ToFinalCameraBlendTime"] = 0.2,
            ["TurnTo"] = {
                [1] = "110015:n(110010)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110127/1B91B468",
            },
        [11012709] = {
            ["Camera"] = "36.496845,123.416016,88.121643,0.0,13.999503,86.565399,35.000008,817.298035,false,DoNotOverride,2.8",
            ["Content"] = "这次行动到现在，我们功劳与危险并存，而且危险总是更多一些。",
            ["ContentKR"] = "이번 작전은 지금까지 공도 세웠지만 위험이 함께했지. 물론 위험한 상황이 더 많았지만.",
            ["DialogueId"] = 11012709,
            ["Duration"] = 3,
            ["FinalCamera"] = "37.052647,132.677246,90.414429,0.0,13.999503,86.565399,35.000008,817.298035,false,DoNotOverride,2.8",
            ["GUID"] = "1B91B492",
            ["LookAt"] = {
                [1] = "110010:n(110010)",
                },
            ["NextDialogue"] = 11012710,
            ["SpeakNpcId"] = 110010,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1002/110127/1B91B492",
            },
        [11012710] = {
            ["Camera"] = "-12.165825,-818.205078,237.788666,0.000159,-10.198333,88.291573,35.0,579.363892,false,DoNotOverride,5.0",
            ["Content"] = "你们还年轻，未来的路很长，也会有很多很多沐浴荣光的机会。所以，这功劳可不能让你们抢走。还是让我一个人去，再添一枚勋章吧。",
            ["ContentKR"] = "너희는 젊고 앞날이 창창하니, 영광을 누릴 기회는 많을 것이다. 이번 공은 내가 가져가야겠어. 나 혼자 들어가서 훈장 하나 더 달 생각이다.",
            ["DialogueId"] = 11012710,
            ["Duration"] = 3,
            ["FinalCamera"] = "-27.306183,-817.759277,237.788666,0.000159,-10.198333,88.291573,35.0,579.363892,false,DoNotOverride,5.0",
            ["GUID"] = "1B91B4BC",
            ["LookAt"] = {
                [1] = "110010:n(110020)",
                },
            ["NextDialogue"] = 11012711,
            ["Scripts"] = "SEQ{\
CameraMoveTo{_delay{10},TargetPosition{\"-49.806252,74.208496,38.168884,-3.000001,19.199593,63.080681,30.000008,138.022522,false,Manual,8.0\"},duration{0}},\
CameraMoveTo{TargetPosition{\"-45.084969,94.379395,45.618835,-3.0,19.59967,60.480312,30.000008,138.022522,false,Manual,8.0\"},duration{8}}\
}",
            ["SpeakNpcId"] = 110010,
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1002/110127/1B91B4BC",
            },
        [11012711] = {
            ["Camera"] = "-791.496155,210.537109,527.647827,0.0002,-28.798002,-13.499554,30.000002,517.956055,false,DoNotOverride,2.8",
            ["Content"] = "你们据守炮台，如果我失联，就继续炮击中央控制室，切勿冒进，继续等待后续支援。",
            ["ContentKR"] = "너희는 여기서 포대를 지키다가 내가 연락이 끊기면 중앙 관제실을 계속 포격해. 절대 무리하게 나서지 말고 후속 지원을 기다려라.",
            ["DialogueId"] = 11012711,
            ["Duration"] = 3,
            ["FinalCamera"] = "-775.113831,278.776367,527.647827,0.0002,-28.798002,-13.499554,30.000002,517.956055,false,DoNotOverride,2.8",
            ["GUID"] = "1B91B4E6",
            ["NextDialogue"] = 11012712,
            ["SpeakNpcId"] = 110010,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/110127/1B91B4E6",
            },
        [11012712] = {
            ["Camera"] = "4.667221,273.677246,128.522583,0.000149,-7.797876,-58.891384,35.0,280.465454,false,DoNotOverride,5.0",
            ["Content"] = "长官，您一个人办不到的……这不是您的本意。",
            ["ContentKR"] = "중령님, 혼자서는 안 됩니다... 진심으로 말씀하시는 게 아니라는 것 다 알고 있습니다.",
            ["DialogueId"] = 11012712,
            ["Duration"] = 3,
            ["GUID"] = "1B91B510",
            ["LookAt"] = {
                [1] = "110016:n(110010)",
                },
            ["NextDialogue"] = 11012713,
            ["SpeakNpcId"] = 110016,
            ["TalkActionId"] = {
                [1] = "110016:Talk01_Start",
                },
            ["TurnTo"] = {
                [1] = "110016:n(110010)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110127/1B91B510",
            },
        [11012713] = {
            ["Camera"] = "131.189819,-166.486328,116.257446,0.000163,-1.198357,98.096161,60.000004,380.104767,false,DoNotOverride,2.8",
            ["Content"] = "什么本意不本意的，这是命令。",
            ["ContentKR"] = "진심이고 자시고, 이건 명령이다.",
            ["DialogueId"] = 11012713,
            ["Duration"] = 3,
            ["GUID"] = "1B91B53A",
            ["LookAt"] = {
                [1] = "110010:n(110016)",
