        [11013501] = {
            ["Camera"] = "-143.608765,-25.8125,20.521362,0.00005,5.207773,-128.420609,20.649015,100000.0,false,Manual,22.0",
            ["Content"] = "让我们好好谈一谈吧。",
            ["ContentKR"] = "우리 좋게 좋게 이야기 좀 하지.",
            ["DialogueId"] = 11013501,
            ["Duration"] = 3,
            ["FinalCamera"] = "-887.352478,-3455.875,1084.944336,0.000019,-37.191525,90.183495,20.649015,100000.0,false,Manual,22.0",
