        [11013609] = {
            ["Camera"] = "-427.870239,2258.052734,924.980835,0.000026,-20.399008,-74.736588,35.000011,271.648438,false,DoNotOverride,2.652164",
            ["Content"] = "先说说你为什么要用那些伪证栽赃我吧。你当上面都是傻子？",
            ["ContentKR"] = "거짓 증거로 나한테 누명을 씌우려는 이유부터 말해 보시지. 상부에 바보만 있는 줄 아는 건가?",
            ["DialogueId"] = 11013609,
            ["Duration"] = 3,
            ["FinalCamera"] = "-427.870239,2258.052734,892.516418,0.000027,-20.399042,-74.737274,35.000011,271.648438,false,DoNotOverride,20.0",
            ["GUID"] = "1B92483A",
            ["LookAt"] = {
                [1] = "110011:n(110011)",
                },
            ["NextDialogue"] = 11013610,
            ["SpeakNpcId"] = 110010,
            ["TalkActionId"] = {
                [1] = "110010:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/110136/1B92483A",
            },
        [11013610] = {
            ["Camera"] = "-89.605194,-418.919922,28.023407,-10.014737,8.201615,53.252785,35.0,271.651154,false,DoNotOverride,20.0",
            ["Content"] = "就是因为上面有很多聪明人，他们才一定会装傻。阿瓦尔，动动你的脑子。既然我敢把事做绝，自然有想要我做绝的人。",
            ["ContentKR"] = "오히려 똑똑한 사람이 많으니까 전부 바보인 척하겠지. 아바르, 머리 좀 굴려봐. 설마 내가 혼자서 이런 일을 꾸몄을 거라 생각하는 건 아니겠지?",
            ["DialogueId"] = 11013610,
            ["Duration"] = 3,
            ["GUID"] = "1B924864",
            ["NextDialogue"] = 11013611,
            ["Scripts"] = "PARA{\
SEQ{\
CameraMoveTo{_delay{5},TargetPosition{\"-427.870239,2258.052734,892.516418,0.000025,-20.399035,-74.737183,35.000011,271.648438,false,DoNotOverride,20.0\"},duration{0}},\
CameraMoveTo{TargetPosition{\"-412.960815,2203.416016,871.454102,0.000026,-20.399035,-74.737061,35.000011,271.648438,false,DoNotOverride,20.0\"},duration{6}}\
},\
MoveTo{_delay{5},ActorId{110011},TargetPoint{\"EX01_FixSimple_19point01\"},MoveSpeed{105},Visibility{\"Show\"}}\
}",
            ["SpeakNpcId"] = 110011,
            ["VoiceName"] = "voice/$Locale$/story/1002/110136/1B924864",
            },
        [11013611] = {
            ["Camera"] = "199.207306,49.052734,103.883209,-0.001587,-1.196615,95.62352,35.0,439.465851,false,DoNotOverride,22.0",
            ["Content"] = "反正你已经是个死人了，那么我就再宽仁一次，让你死得明白一点吧。",
            ["ContentKR"] = "어차피 넌 이제 죽은 목숨이니까 내가 특별히 좀 더 자세히 말해주지.",
            ["DialogueId"] = 11013611,
            ["Duration"] = 3,
            ["FinalCamera"] = "196.638626,75.138672,103.335693,-0.001587,-1.196615,95.62352,35.0,439.465851,false,DoNotOverride,22.0",
            ["GUID"] = "1B92488E",
            ["NextDialogue"] = 11013612,
            ["Scripts"] = "PlayAnimation{_delay{1},ActorId{110011},AnimationId{\"Talk03_Start\"},Duration{6}}",
            ["SpeakNpcId"] = 110011,
            ["ToFinalCameraBlendTime"] = 12,
            ["VoiceName"] = "voice/$Locale$/story/1002/110136/1B92488E",
            },
        [11013612] = {
            ["Camera"] = "34.140366,-340.748047,894.160034,-0.001587,-12.995759,88.221321,43.321198,100000.0,false,Manual,22.0",
            ["Content"] = "陛下即位之初——也就是塞维乌斯公爵担任摄政的那段时间里——他们偏离了海伯利亚长久以来的规则，为帝国这棵大树嫁接了太多无用的枝叶。",
            ["ContentKR"] = "폐하께서 막 즉위하셨을 때... 그러니까 세르비우스 공작이 섭정하는 동안 두 분은 휘페르보레아의 오랜 규칙에서 벗어나 제국이란 큰 나무에 쓸모없는 가지를 너무 많이 붙이셨지.",
            ["DialogueId"] = 11013612,
            ["Duration"] = 3,
            ["FinalCamera"] = "195.783936,-345.769531,815.577393,-0.001587,-12.995759,88.221321,43.321198,100000.0,false,Manual,22.0",
            ["GUID"] = "1B9248B8",
            ["LookAt"] = {
                [1] = "110011:n(110011)",
                },
            ["NextDialogue"] = 11013613,
            ["RelatedWikiId"] = {
                [1] = 201017,
                },
            ["Scripts"] = "SEQ{\
