EventPath{\"event:/sfx/common/story/ex01/evilvo\"},PlayAs2D{true}},PostProcess{MaterailInstance{\"MaterialInstanceConstant'/Game/Asset/Scene/common/PP/MI_PP_Demon_01.MI_PP_Demon_01'\"}\
}}",
            ["SnapShot"] = "MONSTER",
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1002/110138/1B9267BA",
            },
        [11013802] = {
            ["Content"] = "<W>……醒来吧……</>",
            ["ContentKR"] = "<W>...깨어나라...</>",
            ["DialogueId"] = 11013802,
            ["DisableMouth"] = 1,
            ["Duration"] = 2,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B9267E4",
            ["NextDialogue"] = 11013803,
            ["Scripts"] = "PARA{\
