}}",
            ["SnapShot"] = "MONSTER",
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1002/110138/1B9267E4",
            },
        [11013803] = {
            ["Content"] = "<W>……在鲜血化为奔流的河之前……一切远未结束……</>",
            ["ContentKR"] = "<W>...피가 흘러 강을 이루기 전에... 아직 끝나지 않았다...</>",
            ["DialogueId"] = 11013803,
            ["DisableMouth"] = 1,
            ["Duration"] = 2,
            ["ExStoryInfo"] = "EXPlayer",
