            ["SpeakNpcName"] = "UI_Npc_Broadcast",
            ["VoiceName"] = "voice/$Locale$/story/1002/110140/1B92895C",
            },
        [11014007] = {
            ["Camera"] = "-115.764587,-253.871094,-34.510376,-5.000038,12.998785,112.919754,35.000008,155.831024,false,Manual,22.0",
            ["Content"] = "……达芙涅？通缉？",
