                [1] = "110022:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110142/1B92A984",
            },
        [11014203] = {
            ["Content"] = "中央控制室。父……阿瓦尔长官，还在那里。",
            ["ContentKR"] = "중앙 관제실이요. 아버... 아바르 중령님이 아직 거기 계세요.",
            ["DialogueId"] = 11014203,
            ["FacialId"] = {
                [1] = "110005:Sad01",
                },
