}",
            ["SpeakNpcId"] = 110005,
            ["TalkActionId"] = {
                [1] = "110005:DisagreeHead",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/110144/1B92CA7E",
            },
        [11014404] = {
            ["Camera"] = "-88.27002,103.208984,34.547974,0.000074,-7.599576,87.918869,13.462664,136.822205,false,Manual,22.0",
            ["Content"] = "我请求您……请求您告诉我……我可以信任您……只要您这么说，我就会相信。",
            ["ContentKR"] = "부탁이에요... 당신을 믿어도 된다고... 말해줘요... 그렇게만 말해주면 당신을 믿을게요.",
            ["DialogueId"] = 11014404,
            ["GUID"] = "1B92CAA8",
            ["NextOptions"] = {
                [1] = 11014405,
                [2] = 11014406,
                },
            ["Scripts"] = "SEQ{PlayAnimation{_delay{1},ActorId{110005},AnimationId{\"Explain02_End\"},Duration{1}},CameraMoveTo{_delay{3},TargetPosition{\"5.080566,190.669922,1.12085,3.600006,16.199665,176.318161,35.000008,128.714386,false,Manual,22.0\"},duration{0}}}",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110144/1B92CAA8",
            },
        [11014405] = {
            ["Content"] = "（轻轻拥抱她。告诉她可以信任你。）",
            ["ContentKR"] = "(살며시 안으며 나를 믿어도 된다고 말해 준다.)",
            ["DialogueId"] = 11014405,
            ["GUID"] = "1B92CAD2",
            ["ImprPlusId"] = 1009,
            ["NextDialogue"] = 110144071,
            },
        [11014406] = {
            ["Content"] = "（她太依赖自己了——让她靠自己的力量坚强起来。）",
            ["ContentKR"] = "(나를 너무 의지하는 것 같다. 스스로 강해지도록 놔둔다.)",
            ["DialogueId"] = 11014406,
            ["GUID"] = "1B92CAFC",
