        [11015802] = {
            ["Content"] = "如审判长大人所见，我是龙莎战役先遣小队的指挥官阿瓦尔·赫德兰……",
            ["ContentKR"] = "재판장님도 아시다시피 저는 론샤 전투의 선발대 지휘관 아바르 헤데란입니다...",
            ["DialogueId"] = 11015802,
            ["Duration"] = 3,
            ["GUID"] = "1B93B004",
            ["LookAt"] = {
                [1] = "110010:n(0)",
                },
            ["NextDialogue"] = 11015803,
            ["SpeakNpcId"] = 110010,
            ["SpeakNpcName"] = "UI_Npc_DreamAware",
            ["TurnTo"] = {
                [1] = "110010:n(0)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110158/1B93B004",
            },
        [11015803] = {
            ["Content"] = "我背叛了海伯利亚帝国，背叛了十三军团……出卖了“狮鹫”、“雪狼”两支先遣队……",
            ["ContentKR"] = "저는 휘페르보레아 제국을 배신했고, 13군단을 배신했고... '그리핀'과 '스노우 울프' 두 선발대를 팔아넘겼습니다...",
            ["DialogueId"] = 11015803,
            ["Duration"] = 3,
            ["GUID"] = "1B93B02E",
            ["NextDialogue"] = 11015804,
            ["SpeakNpcId"] = 110010,
            ["SpeakNpcName"] = "UI_Npc_DreamAware",
            ["VoiceName"] = "voice/$Locale$/story/1002/110158/1B93B02E",
            },
        [11015804] = {
            ["Content"] = "我的协助者是……我和前妻克劳迪娅·塞奥多尔的女儿……达芙涅……以及……我在皇家军事学院的学生……{nickname2}……",
            ["ContentKR"] = "저와 협조한 자는... 전 부인 클로디아 세오도어 사이에서 낳은 딸... 다프네... 그리고... 황립 사관학교에서 가르쳤던 제자... {nickname2}입니다...",
            ["DialogueId"] = 11015804,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B93B058",
            ["NextDialogue"] = 11015805,
            ["SpeakNpcId"] = 110010,
            ["SpeakNpcName"] = "UI_Npc_DreamAware",
            ["VoiceName"] = "voice/$Locale$/story/1002/110158/1B93B058",
            },
        [11015805] = {
            ["Content"] = "…………",
            ["ContentKR"] = "......",
            ["DialogueId"] = 11015805,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B93B082",
            ["NextDialogue"] = 11015806,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110158/1B93B082",
            },
        [11015806] = {
            ["Content"] = "看来，这就是富尔维斯为我准备的“罪名”了。",
            ["ContentKR"] = "풀비스가 날 위해 준비한 '죄명'이 이거구나.",
            ["DialogueId"] = 11015806,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B93B0AC",
            ["NextDialogue"] = 11015807,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110158/1B93B0AC",
            },
        [11015807] = {
            ["Content"] = "闭嘴。别用他的样子说话。",
            ["ContentKR"] = "닥쳐. 그의 모습으로 말하지 마.",
            ["DialogueId"] = 11015807,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B93B0D6",
            ["NextDialogue"] = 11015808,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110158/1B93B0D6",
            },
        [11015808] = {
            ["Content"] = "…………",
            ["ContentKR"] = "......",
            ["DialogueId"] = 11015808,
            ["Duration"] = 3,
            ["GUID"] = "1B93B100",
            ["SpeakNpcName"] = "UI_Npc_DreamAware",
            ["VoiceName"] = "voice/$Locale$/story/1002/110158/1B93B100",
            },
        [11015901] = {
            ["Camera"] = "-68.808594,-818.875,282.347656,0.000035,-15.198877,68.960663,30.000002,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "如审判长大人所见，我是阿瓦尔·赫德兰的女儿，达芙涅·塞奥多尔……",
            ["ContentKR"] = "재판장님도 아시다시피 저는 아바르 헤데란의 딸, 다프네 세오도어입니다...",
            ["DialogueId"] = 11015901,
            ["Duration"] = 3,
            ["GUID"] = "1B93C042",
            ["LookAt"] = {
                [1] = "0:n(110005)",
                },
            ["NextDialogue"] = 11015902,
            ["SpeakNpcId"] = 110005,
            ["SpeakNpcName"] = "UI_Npc_DreamDafu",
            ["TurnTo"] = {
                [1] = "0:n(110005)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110159/1B93C042",
            },
        [11015902] = {
            ["Content"] = "我的父亲……与{nickname2}……原本计划平分向同盟出卖情报的报酬……",
            ["ContentKR"] = "제 아버지...와 {nickname2}... 이 둘은 처음에 포세이큰 동맹에 정보를 팔아넘긴 대가를 똑같이 나눌 계획이었습니다...",
            ["DialogueId"] = 11015902,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B93C06C",
            ["LookAt"] = {
                [1] = "110005:n(0)",
                },
            ["NextDialogue"] = 11015903,
            ["SpeakNpcId"] = 110005,
            ["SpeakNpcName"] = "UI_Npc_DreamDafu",
            ["TalkActionId"] = {
                [1] = "110005:Explain02_Start",
                },
            ["TurnTo"] = {
                [1] = "110005:n(0)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110159/1B93C06C",
            },
        [11015903] = {
            ["Content"] = "……在要塞核心区域……因分赃不均……",
            ["ContentKR"] = "...요새 핵심 구역에서... 이익 분배 문제로...",
            ["DialogueId"] = 11015903,
            ["Duration"] = 3,
            ["GUID"] = "1B93C096",
            ["NextDialogue"] = 11015904,
            ["SpeakNpcId"] = 110005,
            ["SpeakNpcName"] = "UI_Npc_DreamDafu",
            ["TalkActionId"] = {
                [1] = "110005:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110159/1B93C096",
            },
        [11015904] = {
            ["Content"] = "我的父亲……被……",
            ["ContentKR"] = "제 아버지는...",
            ["DialogueId"] = 11015904,
            ["Duration"] = 3,
            ["GUID"] = "1B93C0C0",
            ["NextDialogue"] = 11015905,
            ["SpeakNpcId"] = 110005,
            ["SpeakNpcName"] = "UI_Npc_DreamDafu",
            ["VoiceName"] = "voice/$Locale$/story/1002/110159/1B93C0C0",
            },
        [11015905] = {
            ["Content"] = "被{nickname2}设计害死……",
            ["ContentKR"] = "{nickname2}의 손에... 계획적으로 살해당했습니다...",
            ["DialogueId"] = 11015905,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B93C0EA",
            ["NextDialogue"] = 11015906,
            ["SpeakNpcId"] = 110005,
            ["SpeakNpcName"] = "UI_Npc_DreamDafu",
            ["TalkActionId"] = {
                [1] = "110005:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110159/1B93C0EA",
            },
        [11015906] = {
            ["Content"] = "在那之后，{性别2：他|她}还欺骗了我……父亲死亡的真相……",
            ["ContentKR"] = "그 후, 그 사람은 저에게 제 아버지 죽음의 진실을 숨겼습니다...",
            ["DialogueId"] = 11015906,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B93C114",
            ["NextDialogue"] = 11015907,
            ["SpeakNpcId"] = 110005,
            ["SpeakNpcName"] = "UI_Npc_DreamDafu",
            ["TalkActionId"] = {
                [1] = "110005:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110159/1B93C114",
            },
        [11015907] = {
            ["Content"] = "我将凶手带到审判长大人面前……恳求审判长大人给予公正的判决……",
            ["ContentKR"] = "범인을 재판장님 앞에 데려갈 테니... 공정한 판결을 내려 주세요...",
            ["DialogueId"] = 11015907,
            ["Duration"] = 3,
            ["GUID"] = "1B93C13E",
            ["NextDialogue"] = 11015908,
            ["SpeakNpcId"] = 110005,
            ["SpeakNpcName"] = "UI_Npc_DreamDafu",
            ["TalkActionId"] = {
                [1] = "110005:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110159/1B93C13E",
            },
        [11015908] = {
            ["Content"] = "……你不是达芙涅。",
            ["ContentKR"] = "...넌 다프네가 아니야.",
            ["DialogueId"] = 11015908,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B93C168",
            ["SpeakNpcId"] = 110022,
            ["TalkActionId"] = {
                [1] = "0:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110159/1B93C168",
            },
        [11016001] = {
            ["Camera"] = "657.027344,-647.62207,449.714844,0.000194,-31.196772,156.787415,25.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "如审判长大人所见，我是龙莎要塞中央控制室的控制台……",
            ["ContentKR"] = "재판장님도 아시다시피 저는 론샤 요새 중앙 관제실의 콘솔입니다...",
            ["DialogueId"] = 11016001,
            ["Duration"] = 3,
            ["GUID"] = "1B93D0AA",
            ["NextDialogue"] = 11019317,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/poweron\"},PlayAs2D{true}}",
            ["SnapShot"] = "ELECTRIC",
            ["SpeakNpcName"] = "UI_Npc_MechVoice",
            ["VoiceName"] = "voice/$Locale$/story/1002/110160/1B93D0AA",
            },
        [11016005] = {
            ["Content"] = "海伯利亚军团箴言第十八条：过于顺利的战况之后，很可能就是敌人的埋伏……",
            ["ContentKR"] = "휘페르보레아 군단 격언 제18조, 과하게 순조로운 전황 뒤에는 적이 매복하고 있을 가능성이 높다...",
            ["DialogueId"] = 11016005,
            ["Duration"] = 3,
            ["GUID"] = "1B93D152",
            ["NextDialogue"] = 11016006,
            ["SnapShot"] = "ELECTRIC",
            ["SpeakNpcName"] = "UI_Npc_MechVoice",
            ["VoiceName"] = "voice/$Locale$/story/1002/110160/1B93D152",
            },
        [11016006] = {
            ["Content"] = "……为什么你在梦里也要复读那些箴言啊！",
            ["ContentKR"] = "...왜 꿈속에서도 저딴 격언이나 읊고 있는 거야!",
            ["DialogueId"] = 11016006,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B93D17C",
            ["Scripts"] = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/poweron\"},PlayAs2D{true}}",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110160/1B93D17C",
            },
        [11016101] = {
            ["Camera"] = "-13.981445,564.373535,123.75,0.00011,3.399125,89.793884,17.134987,100000.0,false,Manual,22.0",
            ["Content"] = "所有审判，皆为正义。",
            ["ContentKR"] = "심판은 정의를 위한 것이다.",
            ["DialogueId"] = 11016101,
            ["Duration"] = 3,
            ["GUID"] = "1B93E112",
            ["NextDialogue"] = 11016102,
            ["SnapShot"] = "MONSTER",
            ["SpeakNpcId"] = 110032,
            ["TalkActionId"] = {
                [1] = "110032:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110161/1B93E112",
            },
        [11016102] = {
            ["Camera"] = "-11.319336,897.331055,144.578125,0.000127,5.398841,86.191856,17.134987,100000.0,false,Manual,22.0",
            ["Content"] = "你须如实回答所有问题，不得有半分虚假、矫饰或隐瞒。",
            ["ContentKR"] = "모든 질문에 한 치의 거짓이나 숨김없이 사실대로 답해야 한다.",
            ["DialogueId"] = 11016102,
            ["Duration"] = 3,
            ["GUID"] = "1B93E13C",
            ["NextDialogue"] = 11019017,
            ["SnapShot"] = "MONSTER",
            ["SpeakNpcId"] = 110032,
            ["VoiceName"] = "voice/$Locale$/story/1002/110161/1B93E13C",
            },
        [11016201] = {
            ["Camera"] = "-13.981445,564.373535,123.75,0.00011,3.399125,89.793884,17.134987,100000.0,false,Manual,22.0",
            ["Content"] = "龙莎要塞一役中，先遣队伍全军覆没，是否与你有关？",
            ["ContentKR"] = "론샤 요새 전투에서 선발대가 전멸한 것이 너와 관련이 있는가?",
            ["DialogueId"] = 11016201,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["GUID"] = "1B93F17A",
            ["NextDialogue"] = 11016202,
            ["SnapShot"] = "MONSTER",
            ["SpeakNpcId"] = 110032,
            ["SpeakNpcName"] = "UI_Npc_Wardenry",
            ["VoiceName"] = "voice/$Locale$/story/1002/110162/1B93F17A",
            },
        [11016202] = {
            ["Camera"] = "-11.319336,897.331055,144.578125,0.000127,5.398841,86.191856,17.134987,100000.0,false,Manual,22.0",
            ["Content"] = "好好感受吧！因为某些人的背叛，他们不得不这样死去！",
            ["ContentKR"] = "똑똑히 느껴라! 누군가의 배신 때문에 전사들이 이렇게 죽어 갔다!",
            ["DialogueId"] = 11016202,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["GUID"] = "1B93F1A4",
            ["NextDialogue"] = 11016203,
            ["SnapShot"] = "MONSTER",
            ["SpeakNpcId"] = 110032,
            ["SpeakNpcName"] = "UI_Npc_Wardenry",
            ["VoiceName"] = "voice/$Locale$/story/1002/110162/1B93F1A4",
            },
        [11016203] = {
            ["Camera"] = "-4.504883,1095.012207,226.371094,-0.000824,-13.200255,-89.031578,17.134987,100000.0,false,Manual,22.0",
            ["Content"] = "若你背弃了同胞的正义，就被秽兽的利爪撕碎！",
            ["ContentKR"] = "동료들의 정의를 저버렸다면, 필토이드의 발톱에 찢겨라!",
            ["DialogueId"] = 11016203,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["GUID"] = "1B93F1CE",
            ["NextDialogue"] = 11016204,
            ["SnapShot"] = "MONSTER",
            ["SpeakNpcId"] = 110032,
            ["SpeakNpcName"] = "UI_Npc_Wardenry",
            ["VoiceName"] = "voice/$Locale$/story/1002/110162/1B93F1CE",
            },
        [11016204] = {
            ["Camera"] = "13.287109,114.423828,114.03125,-0.000825,14.198904,-86.82589,17.134987,100000.0,false,Manual,22.0",
            ["Content"] = "（他们就是被这些怪物……富尔维斯……甚至用这样的怪物来对付自己的同胞……！）",
            ["ContentKR"] = "(모두 이런 몬스터에게…… 풀비스…… 이런 몬스터들이 동료들을 물어뜯도록 하다니!)",
            ["DialogueId"] = 11016204,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B93F1F8",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110162/1B93F1F8",
            },
        [11016301] = {
            ["Content"] = "最后一个问题，阿瓦尔·赫德兰的死亡，是否是你所为？",
            ["ContentKR"] = "마지막 질문이다. 아바르 헤데란을 네 손으로 죽였나?",
            ["DialogueId"] = 11016301,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["GUID"] = "1B9401E2",
            ["NextDialogue"] = 11016302,
            ["SnapShot"] = "MONSTER",
            ["SpeakNpcId"] = 110032,
            ["SpeakNpcName"] = "UI_Npc_Wardenry",
            ["VoiceName"] = "voice/$Locale$/story/1002/110163/1B9401E2",
            },
        [11016302] = {
            ["Content"] = "即使他背叛了帝国，他也一直信任你。他葬身火海中的时候，你在做什么？",
            ["ContentKR"] = "아바르가 제국을 배반했다 하더라도 그는 항상 널 믿었다. 아바르가 불바다에서 목숨을 잃어갈 때 넌 뭘 하고 있었지?",
            ["DialogueId"] = 11016302,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["GUID"] = "1B94020C",
            ["NextDialogue"] = 11016305,
            ["SnapShot"] = "MONSTER",
            ["SpeakNpcId"] = 110032,
            ["SpeakNpcName"] = "UI_Npc_Wardenry",
            ["VoiceName"] = "voice/$Locale$/story/1002/110163/1B94020C",
            },
        [11016303] = {
            ["Content"] = "（是的……他<H>的的确确</>那样信任我……）",
            ["ContentKR"] = "(맞아…… 교관님은 <Highlight>확실히</> 날 믿으셨어……)",
            ["DialogueId"] = 11016303,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B940236",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110163/1B940236",
            },
        [11016304] = {
            ["Content"] = "（在完成复仇之前，我必须活下去……不能让这个女人杀了我……）",
            ["ContentKR"] = "(복수를 끝내기 전까진 무조건 살아남아야 해…… 이 여자 손에 죽을 순 없어……)",
            ["DialogueId"] = 11016304,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B940260",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110163/1B940260",
            },
        [11016305] = {
            ["Content"] = "若你背弃了同伴的正义，就被这狱火灼烧殆尽！",
            ["ContentKR"] = "동료의 정의를 저버렸다면 이 지옥 불에 타 죽게 될 것이다!",
            ["DialogueId"] = 11016305,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["GUID"] = "1B94028A",
            ["NextDialogue"] = 11019052,
            ["SnapShot"] = "MONSTER",
            ["SpeakNpcId"] = 110032,
            ["SpeakNpcName"] = "UI_Npc_Wardenry",
            ["VoiceName"] = "voice/$Locale$/story/1002/110163/1B94028A",
            },
        [11016306] = {
            ["Content"] = "（正义……正义……她一直在追求的，正是“正义”……）",
            ["ContentKR"] = "(정의... 정의... 이 여자는 줄곧 '정의'를 좇고 있다...)",
            ["DialogueId"] = 11016306,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B9402B4",
            ["NextDialogue"] = 11016307,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110163/1B9402B4",
            },
        [11016307] = {
            ["Content"] = "（是时候……把<H>那件事</>告诉她了……）",
            ["ContentKR"] = "(이제... <Highlight>그 일</>을 그녀에게 말해줄 때가 된 것 같아...)",
            ["DialogueId"] = 11016307,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B9402DE",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110163/1B9402DE",
            },
        [11016401] = {
            ["Content"] = "典狱长大人，为了你心中的正义——",
            ["ContentKR"] = "교도소장님, 당신이 품고 있는 그 정의를 위해서...",
            ["DialogueId"] = 11016401,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B94124A",
            ["NextDialogue"] = 11016402,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110164/1B94124A",
            },
        [11016402] = {
            ["Content"] = "让我来告诉你真相吧。那天在中央控制室，全部的“真相”。",
            ["ContentKR"] = "그날 중앙 관제실에서 있었던 모든 '진실'을 말씀드리겠습니다.",
            ["DialogueId"] = 11016402,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B941274",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110164/1B941274",
            },
        [11016501] = {
