            },
        [11019402] = {
            ["Content"] = "们我了叛背人有见所人大长判审如阱陷了置设都上路条一每在盟同者弃神",
            ["ContentKR"] = "다니큽 이성능가 을했설누 을획계 에맹동 큰이세포 이님령중 인론카 는에각생 제",
            ["DialogueId"] = 11019402,
            ["GUID"] = "1B95FEA4",
            ["SpeakNpcId"] = 110016,
            ["SpeakNpcName"] = "UI_Npc_DreamMaerke",
            ["VoiceName"] = "voice/$Locale$/story/1002/110194/1B95FEA4",
            },
        [11019403] = {
            ["Content"] = "人的划计露泄盟同者弃神向能可最是他的民之戎卡为身",
            ["ContentKR"] = "다니습뒀 해치설 을정함 다마길 이맹동 큰이세포다니습했신배 를리우 가군누 피시다시아 도님장판재",
            ["DialogueId"] = 11019403,
            ["GUID"] = "1B95FECE",
            ["SpeakNpcId"] = 110017,
            ["SpeakNpcName"] = "UI_Npc_DreamLaiang",
            ["VoiceName"] = "voice/$Locale$/story/1002/110194/1B95FECE",
            },
        [11019404] = {
            ["Content"] = "队遣先支两狼雪鹫狮了卖出团军三十了叛背国帝亚利伯海了叛背我",
            ["ContentKR"] = "다니습겼넘아팔 를대발선 두 프울 우노스 과 핀리그 고했신배 을단군31 고했신배 을국제 아레보르페휘 는저",
            ["DialogueId"] = 11019404,
            ["GUID"] = "1B95FEF8",
            ["SpeakNpcId"] = 110010,
            ["SpeakNpcName"] = "UI_Npc_DreamAware",
            ["VoiceName"] = "voice/$Locale$/story/1002/110194/1B95FEF8",
            },
        [11019405] = {
            ["Content"] = "决判的正公予给人大长判审求恳前面人大长判审到带手凶将我",
            ["ContentKR"] = "요세주 려내 을결판 한정공 니테 갈려데 에앞 님장판재 을인범",
            ["DialogueId"] = 11019405,
            ["GUID"] = "1B95FF22",
            ["SpeakNpcId"] = 110005,
            ["SpeakNpcName"] = "UI_Npc_DreamDafu",
            ["VoiceName"] = "voice/$Locale$/story/1002/110194/1B95FF22",
            },
        [11019406] = {
            ["Content"] = "开门",
            ["ContentKR"] = "문 열기",
            ["DialogueId"] = 11019406,
            ["GUID"] = "1B95FF4C",
            ["NextDialogue"] = 11019407,
            },
        [11019407] = {
            ["Content"] = "（按下“开门”按钮，但大门纹丝不动——它被做了什么手脚吗？看来事情并非想象中那么简单。）",
            ["ContentKR"] = "('문 열기' 버튼을 눌렀지만, 대문은 전혀 움직이지 않는다. 뭔가 손을 쓴 건가? 아무래도 아직도 끝이 아니구나…)",
            ["DialogueId"] = 11019407,
            ["GUID"] = "1B95FF76",
            ["NextOptions"] = {
                [1] = 11019408,
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110194/1B95FF76",
            },
        [11019408] = {
            ["Content"] = "查阅文件",
            ["ContentKR"] = "문서 확인하기",
            ["DialogueId"] = 11019408,
            ["GUID"] = "1B95FFA0",
            ["NextDialogue"] = 11018807,
            },
        [11019409] = {
            ["Content"] = "……",
            ["ContentKR"] = "…………",
            ["DialogueId"] = 11019409,
            ["GUID"] = "1B95FFCA",
            ["NextOptions"] = {
                [1] = 11019406,
                },
            },
        [11019410] = {
            ["Content"] = "最后的审判",
            ["ContentKR"] = "마지막 심판",
            ["DialogueId"] = 11019410,
            ["GUID"] = "1B95FFF4",
            ["VoiceName"] = "voice/$Locale$/story/1002/110194/1B95FFF4",
            },
        [11019411] = {
            ["Content"] = "背叛者？",
            ["ContentKR"] = "반역자?",
            ["DialogueId"] = 11019411,
            ["GUID"] = "1B96001E",
            ["VoiceName"] = "voice/$Locale$/story/1002/110194/1B96001E",
            },
        [11019412] = {
            ["Content"] = "无罪者？",
            ["ContentKR"] = "무죄자?",
            ["DialogueId"] = 11019412,
            ["GUID"] = "1B960048",
            ["VoiceName"] = "voice/$Locale$/story/1002/110194/1B960048",
            },
        [11019413] = {
            ["Content"] = "活下去",
            ["ContentKR"] = "살아갈 거다",
            ["DialogueId"] = 11019413,
            ["GUID"] = "1B960072",
            ["VoiceName"] = "voice/$Locale$/story/1002/110194/1B960072",
            },
        [11019414] = {
            ["Content"] = "和达芙涅",
            ["ContentKR"] = "다프네와",
            ["DialogueId"] = 11019414,
            ["GUID"] = "1B96009C",
            ["VoiceName"] = "voice/$Locale$/story/1002/110194/1B96009C",
            },
        [11019415] = {
            ["Content"] = "一起",
            ["ContentKR"] = "함께",
            ["DialogueId"] = 11019415,
            ["GUID"] = "1B9600C6",
            ["VoiceName"] = "voice/$Locale$/story/1002/110194/1B9600C6",
            },
        [11019416] = {
            ["Content"] = "（士兵们已经没有了气息。）",
            ["ContentKR"] = "(병사들은 이미 숨이 멎었다.)",
            ["DialogueId"] = 11019416,
            ["GUID"] = "1B9600C7",
            },
        [11019417] = {
            ["Content"] = "（秽兽的尸骸——正是这些怪物夺走了士兵们年轻的生命；而士兵们也在最后一刻，在它们身上留下了致命的弹孔。）",
            ["ContentKR"] = "(필토이드의 잔해... 바로 이 괴물들이 병사들의 젊은 생명을 앗아갔다. 하지만 병사들은 마지막 순간에 괴물들에게 치명적인 총격을 남겼다.)",
            ["DialogueId"] = 11019417,
            ["GUID"] = "1B9600C8",
            },
        [11019418] = {
            ["DialogueId"] = 11019418,
            ["DialoguePanelType"] = "{type:showtext;topic:READ_NAME_JailInves02;content:READ_TEXT_JailInves02}",
            ["GUID"] = "1B9600C9",
            },
        [11019419] = {
            ["DialogueId"] = 11019419,
            ["DialoguePanelType"] = "{type:showtext;topic:READ_NAME_JailInves01;content:READ_TEXT_JailInves01}",
            ["GUID"] = "1B9600CA",
            },
        [11019420] = {
            ["Content"] = "你向典狱长承认了罪行，等待你的将是更为严酷的裁决。",
            ["ContentKR"] = "나는 교도소장에게 죄를 인정하고, 나에게 찾아올 더 엄격하고 냉혹한 판결을 기다린다.",
            ["DialogueId"] = 11019420,
            ["Duration"] = 4,
            ["GUID"] = "1B9600CB",
            ["NextDialogue"] = 11019421,
            },
        [11019421] = {
            ["Content"] = "你听见她的嗤笑——她曾认为你坚强无匹，但如今看来，你和她审判过的其他囚犯也并无分别。",
            ["ContentKR"] = "그녀의 비웃음이 들려온다. 그녀는 한때 날 굳세고 강하다고 생각했지만, 지금 보니 과거에 자신이 재판했던 다른 죄수들과 전혀 다를 바가 없다.",
            ["DialogueId"] = 11019421,
            ["Duration"] = 4,
            ["GUID"] = "1B9600CC",
            ["NextDialogue"] = 11019422,
            },
        [11019422] = {
            ["Content"] = "你意识到自己正在坠入漆黑的深渊——你开始思索，如果当时你的意志能够更坚定一些，结局会不会有所不同？",
            ["ContentKR"] = "내가 지금 칠흑 같은 심연에 떨어지고 있다는 걸 깨닫는다. 만약 그때 내 의지가 좀 더 굳건했다면, 지금과는 다른 결과가 나타났을까?",
            ["DialogueId"] = 11019422,
            ["Duration"] = 4,
            ["GUID"] = "1B9600CD",
            },
        [12000100] = {
            ["Content"] = "东国引入测试文本",
            ["DialogueId"] = 12000100,
            ["GUID"] = "1E0A7E68",
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1200/120001/1E0A7E68",
            },
        [12000401] = {
            ["Camera"] = "867.037842,-235.637695,67.861328,0.000032,17.998148,95.003975,25.0,137.990356,false,DoNotOverride,18.0",
            ["Content"] = "让我看看——帮人找走丢的猫，抓偷蜡烛的小贼，疏通堵塞的烟囱……怎么都是些让人提不起劲的小委托。",
            ["ContentKR"] = "어디 보자~ 길 잃은 고양이를 찾아주고, 초를 훔친 소매치기를 잡고, 막힌 굴뚝을 뚫어주고... 왜 다들 이런 재미없는 의뢰들만 주는 거야.",
            ["DialogueId"] = 12000401,
            ["FacialId"] = {
                [1] = "200002:Unhappy01",
                },
            ["FinalCamera"] = "851.23999,-237.014648,67.861328,0.000032,17.998148,95.003975,25.0,137.990356,false,DoNotOverride,18.0",
