        [12000403] = {
            ["Camera"] = "642.821411,-52.40918,142.441406,0.000153,-0.997529,138.025009,60.000004,133.680405,false,DoNotOverride,9.0",
            ["Content"] = "停、停——再叽叽喳喳个没完，酒客们都要被你烦跑了。今天的损失就从你的生活费里扣吧。",
            ["ContentKR"] = "그만, 그만! 계속 떠들어대다간 손님들이 다 도망가겠다. 오늘 빠진 매출은 네 생활비에서 빼야겠어.",
            ["DialogueId"] = 12000403,
            ["FacialId"] = {
                [1] = "200003:Uninterested01",
                [2] = "200002:None",
                },
            ["FinalCamera"] = "626.849487,-38.043945,142.076172,0.000153,-0.997529,138.024979,60.000004,133.680405,false,DoNotOverride,9.0",
