        [12000412] = {
            ["Camera"] = "210.601685,277.546875,150.097656,0.000214,2.402225,109.397453,35.0,312.341827,false,DoNotOverride,10.0",
            ["Content"] = "千万别。",
            ["ContentKR"] = "절대 안 돼.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12000412,
            ["GUID"] = "1E0AB198",
            ["NextDialogue"] = 12000413,
            ["SpeakNpcId"] = 200003,
            ["VoiceName"] = "voice/$Locale$/story/1200/120004/1E0AB198",
            },
        [12000413] = {
            ["Content"] = "今天我有位难得的大客户要接待。你要是待在这儿，人家还以为我放着好好的酒馆生意不做，转头开幼儿园了呢。",
            ["ContentKR"] = "오늘은 내가 중요한 손님을 접대해야 해. 네가 여기 있으면 사람들이 술집을 놔두고 애들 노는 유치원이라도 만든 줄 알겠다고!",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12000413,
            ["FacialId"] = {
                [1] = "200003:Uninterested01",
                },
            ["GUID"] = "1E0AB1C2",
            ["NextDialogue"] = 12000414,
            ["SpeakNpcId"] = 200003,
            ["TalkActionId"] = {
                [1] = "200003:Talk03_End",
                [2] = "100001:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/story/1200/120004/1E0AB1C2",
            },
        [12000414] = {
            ["Camera"] = "719.914917,-228.804688,96.634766,-2.0,-2.801607,32.384254,45.000023,171.47702,false,Manual,18.0",
            ["Content"] = "呜呜，不过是离开了几天，卡米拉就嫌弃起白了，呜呜。",
            ["ContentKR"] = "흑흑, 며칠 자리를 비운 것뿐인데 카밀라가 벌써 스노우를 싫어하게 됐어. 흑흑.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12000414,
            ["FacialId"] = {
                [1] = "200002:Sad01",
                },
            ["FinalCamera"] = "728.670654,-242.667969,96.0625,-2.0,-2.801607,32.385002,45.000023,165.913345,false,Manual,18.0",
            ["GUID"] = "1E0AB1EC",
            ["NextDialogue"] = 12000415,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Talk01_Start",
                [2] = "200002:Talk03_End",
                [3] = "200003:Talk03_End",
                },
            ["ToFinalCameraBlendTime"] = 2.5,
            ["VoiceName"] = "voice/$Locale$/story/1200/120004/1E0AB1EC",
            },
        [12000415] = {
            ["Camera"] = "215.504517,220.833984,112.722656,0.000129,10.599026,104.21505,35.000011,150.0,false,Manual,10.0",
            ["Content"] = "别以为你那些小伎俩对我有用，眼泪在这酒馆里是最不值钱的东西。",
            ["ContentKR"] = "네 꼼수 같은 건 나한테 안 통해. 이 술집에서 제일 싼 게 눈물이거든.",
            ["DefaultLookAt"] = "TalkNpc",
