  { MinKey = 12000506, MaxKey = 12001720, Loader = function()
      return {
        [12000506] = {
            ["Content"] = "开个车，提示去聊一下",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12000506,
            ["GUID"] = "1E0AC0B2",
            ["NextDialogue"] = 12000507,
            },
        [12000507] = {
            ["Content"] = "开个车，提示去聊一下+1",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12000507,
            ["GUID"] = "1E0AC0B3",
            },
        [12000601] = {
            ["Content"] = "以薇奥莱塔女士的美妙歌喉，那清澈饱满的高音，充满艺术性的花腔，一定能完美诠释妖精的角色，让这部经久不衰的歌剧达到新的高峰！",
            ["ContentKR"] = "비올레타 여사의 맑고 풍부한 고음, 그리고 섬세하고 예술적인 표현이라면 요정 역할을 완벽히 소화해 낼 거야. 이 오페라가 다시 큰 사랑을 받을 수 있겠지!",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12000601,
            ["GUID"] = "1E0AD09A",
            ["NextDialogue"] = 12000602,
            ["SpeakNpcId"] = 220003,
            ["VoiceName"] = "voice/$Locale$/story/1200/120006/1E0AD09A",
            },
        [12000602] = {
            ["Content"] = "是吗……依我看，这里的歌剧班底是一年不如一年了，也就是勉强能入耳的水平。",
            ["ContentKR"] = "그런가... 난 여기 오페라 단원들이 해가 지날수록 점점 실력이 떨어지는 것 같던데? 겨우 들을 만한 수준이랄까.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12000602,
            ["GUID"] = "1E0AD0C4",
            ["NextDialogue"] = 12000603,
            ["SpeakNpcId"] = 220004,
            ["VoiceName"] = "voice/$Locale$/story/1200/120006/1E0AD0C4",
            },
        [12000603] = {
            ["Content"] = "那你还场场不落地买票？",
            ["ContentKR"] = "그럼 왜 공연마다 빠짐없이 티켓을 사는 건데?",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12000603,
            ["GUID"] = "1E0AD0EE",
            ["NextDialogue"] = 12000604,
            ["SpeakNpcId"] = 220003,
            ["VoiceName"] = "voice/$Locale$/story/1200/120006/1E0AD0EE",
            },
        [12000604] = {
            ["Content"] = "能不能听，总要实际到场后才好评价。毕竟也只能指着这些乐趣活了。",
            ["ContentKR"] = "들을 만한지 아닌지는 직접 들어봐야 알지. 뭐, 어차피 이런 게 내 유일한 재미니까. ",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12000604,
            ["GUID"] = "1E0AD118",
            ["SpeakNpcId"] = 220004,
            ["VoiceName"] = "voice/$Locale$/story/1200/120006/1E0AD118",
            },
        [12000605] = {
            ["Content"] = "爸爸，莉莉马上就能听到大姐姐们施展声音的魔法了！",
            ["ContentKR"] = "아빠! 리리도 곧 언니들이 목소리로 마법 부리는 걸 들을 수 있대요!",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12000605,
            ["GUID"] = "1E0AD142",
            ["NextDialogue"] = 12000606,
            ["SpeakNpcId"] = 220005,
            ["VoiceName"] = "voice/$Locale$/story/1200/120006/1E0AD142",
            },
        [12000606] = {
            ["Content"] = "能和爸爸一起看歌剧，结束后还要去吃大餐，今天就是莉莉最幸福的一天！",
            ["ContentKR"] = "아빠랑 오페라도 보고, 끝나서 맛있는 것도 먹고, 오늘은 리리가 세상에서 제일 행복한 날이에요! ",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12000606,
            ["GUID"] = "1E0AD16C",
            ["SpeakNpcId"] = 220005,
            ["VoiceName"] = "voice/$Locale$/story/1200/120006/1E0AD16C",
            },
        [12000607] = {
            ["Content"] = "喂，你听说了吗？前几天的银烛狂欢，有人在剧院当场行凶，直接惊动了军团老爷耶！",
            ["ContentKR"] = "야, 너 그 얘기 들었어? 며칠 전에 은촛불 축제 때 극장에서 무슨 사건이 터졌대. 군단까지 출동했다더라!",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12000607,
            ["GUID"] = "1E0AD196",
            ["NextDialogue"] = 12000608,
            ["SpeakNpcId"] = 220006,
            ["VoiceName"] = "voice/$Locale$/story/1200/120006/1E0AD196",
            },
        [12000608] = {
            ["Content"] = "究竟是闹鬼、神弃者、还是“卡戎狩猎”的怪物复活了……想一探究竟的人，全被下封口令了！",
            ["ContentKR"] = "유령이 나왔다느니, 신에게 버림받은 자라느니, 아니면 '카론 사냥'의 괴물이 다시 나타났다느니... 궁금해하는 사람들 전부 입 막혔다더라!",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12000608,
            ["GUID"] = "1E0AD1C0",
            ["SpeakNpcId"] = 220006,
            ["VoiceName"] = "voice/$Locale$/story/1200/120006/1E0AD1C0",
            },
        [12000701] = {
            ["Camera"] = "-677.66748,25.194824,133.280273,0.000017,-4.400049,-14.604745,35.000008,576.302551,false,Manual,10.0",
            ["Content"] = "票，内部优惠，要不？",
            ["ContentKR"] = "티켓 있어요! 내부 할인이라 싸게 드릴게요, 하나 사세요?",
            ["DefaultLookAt"] = "TalkNpc",
