        [12000801] = {
            ["Camera"] = "-170.109375,317.277344,120.285156,0.000179,8.798184,-120.996368,35.0,1500.0,false,DoNotOverride,10.0",
            ["Content"] = "她在这边站了好久……是在等什么人吗？",
            ["ContentKR"] = "저 사람 여기 한참 서 있는데... 누구를 기다리는 걸까?",
            ["DialogueId"] = 12000801,
            ["FinalCamera"] = "-170.007812,317.214844,125.261719,0.000179,8.798184,-120.996368,35.0,1500.0,false,DoNotOverride,10.0",
            ["GUID"] = "1E0AF16A",
            ["SpeakNpcId"] = 200002,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1200/120008/1E0AF16A",
            },
        [12000901] = {
            ["Camera"] = "447.142578,-1718.275391,230.304688,0.000094,0.799959,98.196053,35.000008,500.702026,false,Manual,10.0",
            ["Content"] = "尊敬的先生，请拿好您的票。您的座位在进去后左手边的位置，愿您度过美妙的一天。",
            ["ContentKR"] = "존경하는 고객님, 여기 티켓 받으세요. 좌석은 들어가셔서 왼쪽에 있습니다. 즐거운 시간 되세요!",
            ["DialogueId"] = 12000901,
            ["FinalCamera"] = "467.927734,-1842.345215,228.707031,0.000094,-0.999905,95.795494,33.0,500.702026,false,Manual,10.0",
