        [12000902] = {
            ["Camera"] = "304.976562,-1287.830078,283.621094,0.000145,-15.79839,19.40465,28.000006,500.702026,false,Manual,10.0",
            ["Content"] = "给你！这是白和小仆从的票。",
            ["ContentKR"] = "여기 있어! 이건 스노우랑 시종의 티켓이야.",
            ["DialogueId"] = 12000902,
            ["FacialId"] = {
                [1] = "200002:Smile02",
                },
            ["FinalCamera"] = "304.976562,-1287.830078,283.621094,0.000138,-17.998436,17.204498,28.000006,500.702026,false,Manual,10.0",
