                [1] = "210004:Give",
                },
            ["VoiceName"] = "voice/$Locale$/story/1200/120012/1E0B330A",
            },
        [12001301] = {
            ["Camera"] = "376.210938,-1350.273438,190.855469,0.000201,25.199463,-55.5868,35.000011,262.433014,false,DoNotOverride,10.0",
            ["Content"] = "我出钱包下了这间包厢。带两个小朋友进去，想必是合规矩的吧？",
            ["ContentKR"] = "제가 바로 일등석을 예약한 사람입니다. 여기 두 어린 친구를 데려가도 규칙 위반은 아니겠죠?",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001301,
            ["FinalCamera"] = "370.894531,-1342.501953,186.433594,0.000201,25.199463,-55.5868,35.000011,262.433014,false,DoNotOverride,10.0",
            ["GUID"] = "1E0B4372",
            ["LookAt"] = {
                [1] = "210004:n(220010)",
                },
            ["NextDialogue"] = 12001302,
            ["Scripts"] = "LookAt{_delay{3},LookAtDescription{\"210004:n(220013)\"}},",
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210004:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1200/120013/1E0B4372",
            },
        [12001302] = {
            ["Camera"] = "460.166016,-1490.179199,238.054688,0.000203,2.199983,118.812393,35.000008,257.958527,false,Manual,10.0",
            ["Content"] = "……女士，您确定要让这种来历不明、不三不四的人玷污您的包厢吗？您可别被他们看似无辜的外表骗到了！",
            ["ContentKR"] = "...여사님, 정말 이런 정체불명의, 어딘가 수상한 사람들이 당신의 객실까지 더럽히게 두시는 겁니까? 그들의 순진해 보이는 외모에 속으신 건 아닙니까?",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001302,
            ["FacialId"] = {
                [1] = "220010:CM_Angry01",
                },
            ["FinalCamera"] = "464.386719,-1497.868164,237.734375,0.000203,2.199983,118.812393,35.000008,262.433014,false,Manual,10.0",
            ["GUID"] = "1E0B439C",
            ["LookAt"] = {
                [1] = "220010:n(210004)",
                },
            ["NextDialogue"] = 12001303,
            ["Scripts"] = "PlayAnimation{_delay{4},ActorId{220010},AnimationId{\"Think_End\"},Duration{1}}",
            ["SpeakNpcId"] = 220010,
            ["TalkActionId"] = {
                [1] = "220013:Sigh_End",
                [2] = "210004:Confident_End",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1200/120013/1E0B439C",
            },
        [12001303] = {
            ["Camera"] = "557.857422,-581.538086,373.707031,0.00023,-12.400208,-101.401718,35.0,391.082153,false,DoNotOverride,7.0",
            ["Content"] = "他们是什么样的人，我自有定数。还是说……你想质疑我的决定吗？",
            ["ContentKR"] = "그들이 어떤 사람들인지는 제가 잘 알고 있어요. 아니면... 제 결정을 의심하겠다는 건가요?",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001303,
            ["FacialId"] = {
                [1] = "210004:Angry01",
                },
            ["FinalCamera"] = "562.587891,-558.097656,378.964844,0.00023,-12.400208,-101.401718,35.0,391.082153,false,DoNotOverride,7.0",
            ["GUID"] = "1E0B43C6",
            ["NextDialogue"] = 12001304,
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210004:Confident_Start",
                [2] = "200002:Talk03_Start",
                [3] = "220010:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1200/120013/1E0B43C6",
            },
        [12001304] = {
            ["Camera"] = "434.730469,-1369.897949,290.742188,0.000221,-14.599761,139.198776,35.0,391.082153,false,DoNotOverride,7.0",
            ["Content"] = "不会的，女士。带什么人进去，当然是客人全权说了算。就算是您要把雾区的叫花子带进去，盖雷亚剧院也会竭诚为您服务。混小子，快给我闭嘴！",
            ["ContentKR"] = "그럴 리가 있겠습니까, 여사님. 자리에 누구를 데리고 가시든, 그건 전적으로 고객님의 자유입니다. 여사님이 안개 구역의 거지들을 데려가신다 해도, 갈레아 극장은 최선을 다해 모실 겁니다. 이 자식아, 입 다물고 있어!",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001304,
            ["GUID"] = "1E0B43F0",
            ["LookAt"] = {
                [1] = "220013:n(210004)",
