            },
        [12001342] = {
            ["Camera"] = "-87.818359,443.974121,52.113281,0.000121,1.803375,-87.158249,50.0,81.737244,false,DoNotOverride,5.0",
            ["Content"] = "……一场歌剧都演完了，人还没来。这就是帝国的待客礼仪吗？",
            ["ContentKR"] = "...오페라 한 편이 다 끝났는데도 사람은 안 보이는데, 이게 제국에서 손님을 대접하는 방식인가?",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001342,
            ["FacialId"] = {
                [1] = "220014:Unhappy01",
                [2] = "100001:Unhappy01",
