        [12001344] = {
            ["Camera"] = "-122.492188,200.228027,-8.191406,-1.999999,11.002273,75.213051,40.000023,302.271698,false,Manual,5.0",
            ["Content"] = "老子传达的不够清楚吗？散场结束前，一个都不能走！",
            ["ContentKR"] = "내가 한 말을 못 알아들은 겁니까? 공연 끝나기 전엔 누구도 못 나갑니다!",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001344,
