            ["VoiceName"] = "voice/$Locale$/story/1200/120015/1E0B6A7E",
            },
        [12001540] = {
            ["Camera"] = "-6.899292,367.232422,133.763672,0.000402,-4.796657,-112.247681,19.845516,159.369675,false,Manual,10.0",
            ["Content"] = "呵呵，{nickname}，真好，看来我们的缘分还未中断……接下来几日，就拜托你了。",
            ["ContentKR"] = "하하, {nickname}, 다행히 우리 인연이 아직 끝나지 않았나 보네... 앞으로 며칠간, 잘 부탁해.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001540,
