        [12001551] = {
            ["Camera"] = "-509.560974,609.379883,181.859375,0.000415,-15.375602,-144.277359,35.0,360.0,false,Manual,10.0",
            ["Content"] = "咦，这把剑瞅着怎么有点眼熟？好像在哪里见过的样子……",
            ["ContentKR"] = "어라? 이 검, 뭔가 익숙한데? 어디서 본 것 같은데...",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001551,
            ["GUID"] = "1E0B6C76",
