            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1200/120017/1E0B85E4",
            },
        [12001707] = {
            ["Camera"] = "-26.722656,319.375977,59.239258,0.000077,19.398317,164.820892,35.000011,187.953278,false,Manual,10.0",
            ["Content"] = "……我不是故意不带你。只是，这次可能会惹到海伯利亚的士兵，我不能为了自己的事把你卷进去。",
            ["ContentKR"] = "...너를 일부러 데려가지 않으려던 건 아니야. 다만 이번 일은 휘페르보레아 제국 병사들과 얽힐 가능성이 있어서, 너까지 끌어들이고 싶지 않아.",
            ["DialogueId"] = 12001707,
            ["FacialId"] = {
                [1] = "100001:Sad01",
                },
            ["GUID"] = "1E0B860E",
            ["NextDialogue"] = 12001708,
