            ["VoiceName"] = "voice/$Locale$/story/1200/120017/1E0B86B6",
            },
        [12001712] = {
            ["Content"] = "才才才才没有……那明明是在考验你的实力，你不要误会！",
            ["ContentKR"] = "전, 전혀 그런 적 없거든...! 그건 네 실력을 시험해 본 거야. 오해하지 마!",
