            ["TalkActionId"] = {
                [1] = "200002:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1200/120017/1E0B86E0",
            },
        [12001713] = {
            ["Content"] = "再说了，就算只是在幕后指挥，白聪明的脑瓜子，也一定能够派上大用场！",
            ["ContentKR"] = "게다가, 스노우처럼 똑똑한 머리라면 뒤에서 지휘만 해도 크게 도움이 될 거야!",
            ["DialogueId"] = 12001713,
