        [12001739] = {
            ["Camera"] = "-75.75293,79.15387,174.89502,0.000084,-6.400638,156.217987,35.000015,135.16452,false,Manual,10.0",
            ["Content"] = "了解。还有其他异常吗？",
            ["ContentKR"] = "알겠다. 다른 특이점은 없나?",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001739,
            ["GUID"] = "1E0B8B4E",
