                [1] = "200002:Alright_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1200/120017/1E0B8C4A",
            },
        [12001746] = {
            ["Camera"] = "-425.98642,47.386562,174.56543,0.000182,-22.600637,6.394048,40.0,241.074173,false,Manual,10.0",
            ["Content"] = "嗯嗯，就是这样！再多说点，白爱听！",
            ["ContentKR"] = "응응, 그래야지! 더 말해봐, 스노우는 칭찬 좋아하거든!",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001746,
            ["FacialId"] = {
                [1] = "200002:Happy02",
                },
            ["GUID"] = "1E0B8C74",
            ["NextDialogue"] = 12001748,
            ["Scripts"] = "PlayAnimation{_delay{3},ActorId{200002},AnimationId{\"Confident_End\"},Duration{1}}",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1200/120017/1E0B8C74",
            },
        [12001747] = {
            ["Camera"] = "-425.98642,47.386562,174.56543,0.000182,-22.600637,6.394048,40.0,241.074173,false,Manual,10.0",
            ["Content"] = "什么嘛！你上哪里才能找到像本大人一样效率高超、演技高超、关键是还很可爱的帮手！",
            ["ContentKR"] = "뭐야! 너 어디 가서 이 마왕님처럼 능력도 뛰어나고, 연기도 잘하며, 게다가 이렇게 귀엽기까지 한 파트너를 또 찾을 수 있겠어!",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001747,
            ["FacialId"] = {
                [1] = "200002:Doubt01",
                },
            ["GUID"] = "1E0B8C9E",
            ["NextDialogue"] = 12001748,
            ["Scripts"] = "PlayAnimation{_delay{3},ActorId{200002},AnimationId{\"Confident_End\"},Duration{1}}",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1200/120017/1E0B8C9E",
            },
        [12001748] = {
            ["Content"] = "话说回来，那些家伙也太过分了！竟然用贝蕾的消息当做诱饵——",
            ["ContentKR"] = "그러고 보니, 저놈들 너무하네! 베레의 정보를 미끼로 쓰다니...",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001748,
