        [12001754] = {
            ["Camera"] = "375.109375,67.12085,53.858154,0.000092,2.599358,-116.196808,48.590485,160.792343,false,Manual,10.0",
            ["Content"] = "呼、呼……那个，咱们，这是要第几次……钻下水道了……先、让我、歇歇……",
            ["ContentKR"] = "헉, 헉... 저, 저기... 우리가 이번이 몇 번째... 하수도로 들어가는 거더라... 잠, 잠깐만... 쉬게 해줘...",
