        [12001762] = {
            ["Camera"] = "55.601562,-74.976562,92.190918,0.000011,13.599883,168.789474,35.000019,257.48999,false,Manual,10.0",
            ["Content"] = "什么人？停车！",
            ["ContentKR"] = "누구야? 멈춰!",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001762,
            ["GUID"] = "1E0B8F14",
            ["NextDialogue"] = 12001763,
            ["SpeakNpcId"] = 220025,
            ["VoiceName"] = "voice/$Locale$/story/1200/120017/1E0B8F14",
            },
        [12001763] = {
            ["Content"] = "上头下了命令，今晚一个可疑人士都不能放行，麻烦你们配合一下。",
            ["ContentKR"] = "오늘 밤에는 수상한 사람 누구도 통과시키면 안 된다는 상부 명령이 있었습니다. 협조 바랍니다.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001763,
            ["GUID"] = "1E0B8F3E",
            ["LookAt"] = {
                [1] = "220025:n(220014)",
                },
            ["NextDialogue"] = 120017641,
            ["SpeakNpcId"] = 220025,
            ["TalkActionId"] = {
                [1] = "220025:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1200/120017/1E0B8F3E",
            },
        [12001764] = {
            ["Camera"] = "-462.479492,486.855469,394.952148,0.000034,-20.000547,-54.008591,35.000008,100000.0,false,DoNotOverride,10.0",
            ["Content"] = "哎呀……我过来的路上看见不少士兵在街上巡逻。请问出了什么事吗？",
            ["ContentKR"] = "아이고... 오다 보니 거리 곳곳에서 순찰 중인 병사들을 많이 봤네요. 도대체 무슨 일이 일어난 거죠?",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001764,
            ["FinalCamera"] = "-462.479492,486.855469,339.495117,0.000034,-20.000547,-54.008591,35.000008,100000.0,false,DoNotOverride,10.0",
