        [12002100] = {
            ["Content"] = "假装潜行玩法",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12002100,
            ["GUID"] = "1E0BC688",
            },
        [12003001] = {
            ["Content"] = "假装这里坐下来了，后面k一个Sequence",
            ["DialogueId"] = 12003001,
            ["GUID"] = "1E0C5A5A",
            },
        [12003101] = {
            ["Content"] = "假装把止流带走",
            ["DialogueId"] = 12003101,
            ["GUID"] = "1E0C6AC2",
            },
        [12003201] = {
            ["Content"] = "假装2D图",
            ["DialogueId"] = 12003201,
            ["GUID"] = "1E0C7B2A",
            },
        [12003301] = {
            ["Content"] = "这里就把玩家传到东国了",
            ["DialogueId"] = 12003301,
            ["GUID"] = "1E0C8B92",
            },
        [12003401] = {
            ["Content"] = "假装开车出城的Sequence",
            ["DialogueId"] = 12003401,
            ["GUID"] = "1E0C9BFA",
            },
        [12004001] = {
            ["Camera"] = "127.357666,-54.3125,106.762451,0.000013,7.799898,-163.400085,35.0,100000.0,False,Manual,10.0",
            ["Content"] = "选A还是B",
            ["DialogueId"] = 12004001,
            ["GUID"] = "1E0CFE6A",
            ["SpeakNpcId"] = 100001,
            },
        [12004002] = {
            ["Content"] = "A",
            ["DialogueId"] = 12004002,
            ["GUID"] = "1E0CFE94",
            ["SpeakNpcId"] = 100001,
            },
        [12004003] = {
            ["Content"] = "B",
            ["DialogueId"] = 12004003,
            ["GUID"] = "1E0CFEBE",
            ["SpeakNpcId"] = 200002,
            },
        [12004101] = {
            ["Content"] = "……哇，好多人哦。大家都是来看剧的吗？",
            ["ContentKR"] = "...와, 사람 진짜 많네. 다들 공연 보러 온 거야?",
            ["DialogueId"] = 12004101,
            ["GUID"] = "1E0AE102",
            ["NextDialogue"] = 12004102,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1200/120007/1E0AE102",
            },
        [12004102] = {
            ["Content"] = "他们好像在聊一些很有意思的事情，小仆从，我们去听听看吧。",
            ["ContentKR"] = "사람들이 재밌는 얘기 하는 것 같아, 시종, 우리 가서 들어보자.",
            ["DialogueId"] = 12004102,
            ["GUID"] = "1E0D0EFC",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1200/120041/1E0D0EFC",
            },
        [12004201] = {
            ["Content"] = "止流姐姐，你去水仙平原，莫非是要见什么人？",
            ["ContentKR"] = "지류 언니, 아스포델에 가서 누굴 만나려는 거야?",
            ["DialogueId"] = 12004201,
            ["GUID"] = "1E0D1F3A",
            ["NextDialogue"] = 12004202,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1200/120042/1E0D1F3A",
            },
        [12004202] = {
            ["Content"] = "让白猜猜……该不会是一位金色大波浪、说起话来凶巴巴的老板娘吧！",
            ["ContentKR"] = "내가 한번 맞춰볼게... 혹시 황금빛 곱슬곱슬 머리하고, 말할 때마다 까칠까칠한 여사장님 아니야?",
            ["DialogueId"] = 12004202,
            ["GUID"] = "1E0D1F64",
            ["NextDialogue"] = 12004203,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1200/120042/1E0D1F64",
            },
        [12004203] = {
            ["Content"] = "呵呵，这都被你猜中了。",
            ["ContentKR"] = "하하, 다 맞혔네.",
            ["DialogueId"] = 12004203,
            ["GUID"] = "1E0D1F8E",
            ["NextDialogue"] = 12004204,
            ["SpeakNpcId"] = 220014,
            ["VoiceName"] = "voice/$Locale$/story/1200/120042/1E0D1F8E",
            },
        [12004204] = {
            ["Content"] = "魔王大人当然是料事如神啦！",
            ["ContentKR"] = "이 마왕님은 당연히 모든 걸 다 알고 있지!",
            ["DialogueId"] = 12004204,
            ["GUID"] = "1E0D1FB8",
            ["NextDialogue"] = 12004205,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1200/120042/1E0D1FB8",
            },
        [12004205] = {
            ["Content"] = "啊，不过，刚刚的话，可千万别对卡米拉说哦……不然今天的零花钱又要被扣光了。",
            ["ContentKR"] = "아, 그런데 방금 말한 거, 카밀라한테는 절대 말하지 마! 안 그럼 오늘 용돈 또 다 깎일 거야...",
            ["DialogueId"] = 12004205,
            ["GUID"] = "1E0D1FE2",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1200/120042/1E0D1FE2",
            },
        [12004206] = {
            ["Content"] = "我们到啦——",
            ["ContentKR"] = "도착했어~",
            ["DialogueId"] = 12004206,
            ["GUID"] = "1E0D200C",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1200/120042/1E0D200C",
            },
        [12004301] = {
            ["Content"] = "皎皎气呼呼地跑走了。",
            ["ContentKR"] = "루나가 식식거리며 달려갔다.",
            ["DialogueId"] = 12004301,
            ["Duration"] = 2,
            ["GUID"] = "1E0D2FA2",
            ["VoiceName"] = "voice/$Locale$/story/1200/120043/1E0D2FA2",
            },
        [12004401] = {
            ["Content"] = "那边的机器奇奇怪怪的……唔，总觉得绕开它们比较好！",
            ["ContentKR"] = "저쪽 기계들 좀 이상해... 음, 그냥 피하는 게 좋을 것 같아!",
            ["DialogueId"] = 12004401,
            ["GUID"] = "1E0D400A",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1200/120044/1E0D400A",
            },
        [12004402] = {
            ["Content"] = "它转过去啦，就是现在——",
            ["ContentKR"] = "돌아갔어, 지금이야!",
            ["DialogueId"] = 12004402,
            ["GUID"] = "1E0D4034",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1200/120044/1E0D4034",
            },
        [12004501] = {
            ["Content"] = "<W>发现追捕目标，发现追捕目标。</>",
            ["ContentKR"] = "<W>목표 발견. 목표 발견.</>",
            ["DialogueId"] = 12004501,
            ["GUID"] = "1E0D5072",
            ["NextDialogue"] = 12004502,
            ["SnapShot"] = "BROADCAST",
            ["VoiceName"] = "voice/$Locale$/story/1200/120045/1E0D5072",
            },
        [12004502] = {
            ["Content"] = "哇啊……我们的行踪好像暴露了！",
            ["ContentKR"] = "와... 우리 행적이 들킨 것 같네!",
            ["DialogueId"] = 12004502,
            ["GUID"] = "1E0D509C",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1200/120045/1E0D509C",
            },
        [12004503] = {
            ["Content"] = "任务失败，请重新开始。",
            ["ContentKR"] = "퀘스트 실패, 다시 시작해 주세요.",
            ["DialogueId"] = 12004503,
            ["GUID"] = "1E0D509D",
            ["SpeakNpcId"] = 200002,
            },
        [12004504] = {
            ["Content"] = "被动失败",
            ["ContentKR"] = "퀘스트 수행 실패",
            ["DialogueId"] = 12004504,
            ["GUID"] = "1E0D509E",
            ["SpeakNpcId"] = 200002,
            },
        [12010000] = {
            ["Content"] = "收帆——归港咯——",
            ["ContentKR"] = "돛을 내려라! 입항이다!",
            ["DialogueId"] = 12010000,
            ["Duration"] = 5,
            ["GUID"] = "1E10D6A0",
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D6A0",
            },
        [12010001] = {
            ["Content"] = "一路上，从敞篷车换飞艇再坐船，白的屁股都坐痛了……",
            ["ContentKR"] = "오는 내내 오픈카에, 비행선에, 이젠 또 배까지. 스노우 엉덩이 아파 죽겠어...",
            ["DialogueId"] = 12010001,
            ["GUID"] = "1E10D6CA",
            ["NextDialogue"] = 12010002,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408011,
                [3] = 203001,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D6CA",
            },
        [12010002] = {
            ["Content"] = "呵呵……毕竟从华胥到海伯利亚，隔了千百里之遥。能将广阔的距离缩减为一日之内的行程，已经是月石技术的伟力了。",
            ["ContentKR"] = "후후... 화서에서 휘페르보레아 제국까지는 수천 리나 떨어져 있으니까. 그렇게나 먼 거리를 하루 만에 왕복할 수 있게 된 것도, 다 위대한 월석 기술 덕분이야.",
            ["DialogueId"] = 12010002,
            ["GUID"] = "1E10D6F4",
            ["NextDialogue"] = 12010003,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D6F4",
            },
        [12010003] = {
            ["Content"] = "说的也是。白还从没来过这么远的地方呢！",
            ["ContentKR"] = "하긴 그래. 스노우는 이렇게 멀리까진 처음 와 봤어!",
            ["DialogueId"] = 12010003,
            ["GUID"] = "1E10D71E",
            ["NextDialogue"] = 12010004,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D71E",
            },
        [12010004] = {
            ["Content"] = "能看到这么绿的山峰，这趟算是来对了！要是还待在冰湖城，就只能和雪地里的冰原狼大眼瞪小眼。",
            ["ContentKR"] = "이런 초록빛 산봉오리를 볼 수 있다니, 오길 진짜 잘한 거 같아! 계속 아이스레이크 시티에 있었으면, 눈밭에서 스노우 울프랑 서로 눈만 멀뚱멀뚱하고 있었을 거야.",
            ["DialogueId"] = 12010004,
            ["GUID"] = "1E10D748",
            ["NextDialogue"] = 12010005,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D748",
            },
        [12010005] = {
            ["Content"] = "小仆从，这就是你们经常说的南方吧。这里和你的家乡像吗？",
            ["ContentKR"] = "시종, 여기가 너네가 맨날 얘기하던 남쪽 맞지? 네 고향이랑 좀 닮았어?",
            ["DialogueId"] = 12010005,
            ["GUID"] = "1E10D772",
            ["NextDialogue"] = 12010006,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D772",
            },
        [12010006] = {
            ["Content"] = "有点相似，但又有很多不一样的地方。",
            ["ContentKR"] = "조금은. 그렇지만 다른 점도 많아.",
            ["DialogueId"] = 12010006,
            ["GUID"] = "1E10D79C",
            ["NextDialogue"] = 12010007,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D79C",
            },
        [12010007] = {
            ["Content"] = "净界岛是个袖珍的小岛，就算是最高点，对于小孩子来说铆足了劲就能一口气冲上去，然后就能看见碧蓝的大海……",
            ["ContentKR"] = "연옥도는 아주 작아서, 섬에서 제일 높은 곳까지 꼬마도 한달음에 뛰어 올라갈 수 있는데, 거기 도착하면 눈앞에 새파란 바다가 펼쳐져...",
            ["DialogueId"] = 12010007,
            ["GUID"] = "1E10D7C6",
            ["NextDialogue"] = 12010008,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D7C6",
            },
        [12010008] = {
            ["Content"] = "止流掌柜，华胥是个怎样的国家呢？",
            ["ContentKR"] = "지류 사장님, 화서는 어떤 곳인가요?",
            ["DialogueId"] = 12010008,
            ["GUID"] = "1E10D7F0",
            ["NextDialogue"] = 12010009,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D7F0",
            },
        [12010009] = {
            ["Content"] = "让我想想……你们所见的，只是华胥的一小部分区域。",
            ["ContentKR"] = "글쎄... 너희가 보고 있는 곳은 화서의 아주 작은 일부에 지나지 않아.",
            ["DialogueId"] = 12010009,
            ["GUID"] = "1E10D81A",
            ["NextDialogue"] = 12010010,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D81A",
            },
        [12010010] = {
            ["Content"] = "昔日，华胥先人依靠团结一致的伟力，解决了肆虐于这片土地的秽兽危机。然后扎根下来，逐渐地繁衍生息、开疆拓土。",
            ["ContentKR"] = "과거, 화서의 선조들께서는 모두 힘을 모아, 이 땅을 어지럽히던 필토이드의 위협을 종식하셨지. 그 후, 이곳에 삶의 터전을 일구고 번영하며, 영토를 넓혀 오셨어.",
            ["DialogueId"] = 12010010,
            ["GUID"] = "1E10D844",
            ["NextDialogue"] = 12010011,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D844",
            },
        [12010011] = {
            ["Content"] = "如今，这处入海口已经成为了旧都。在华胥广袤的版图中，它只占了一小块，却拥有不容忽视的影响力。",
            ["ContentKR"] = "그랬던 이 강어귀도 이제는 옛 수도가 되었지. 화서의 드넓은 영토 중 아주 작은 면적에 불과하지만, 그 영향력만은 결코 얕볼 수 없어.",
            ["DialogueId"] = 12010011,
            ["GUID"] = "1E10D86E",
            ["NextDialogue"] = 12010012,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D86E",
            },
        [12010012] = {
            ["Content"] = "就整个华胥而言，这里地产富足，风景秀美，四季常青，由织星客领衔的贸易发达……",
            ["ContentKR"] = "화서의 다른 지역과 비교해 보면, 이곳은 물산이 풍족하고 사계절 내내 푸르른 경관을 자랑해. 별을 잇는 자들이 이끄는 무역도 발달해서...",
            ["DialogueId"] = 12010012,
            ["GUID"] = "1E10D898",
            ["NextDialogue"] = 12010013,
            ["RelatedWikiId"] = {
                [1] = 405007,
                },
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D898",
            },
        [12010013] = {
            ["Content"] = "呵呵，怎么一脸凝重，莫非是我的介绍太官方了？",
            ["ContentKR"] = "후후, 표정들이 심각하네. 내 설명이 너무 딱딱했나?",
            ["DialogueId"] = 12010013,
            ["GUID"] = "1E10D8C2",
            ["NextOptions"] = {
                [1] = 120100131,
                [2] = 120100132,
                },
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D8C2",
            },
        [12010014] = {
            ["Content"] = "这样吧，说点你们可能感兴趣的。华胥是<H>不动干戈，世无纷争</>的和睦之乡。",
            ["ContentKR"] = "그렇다면 두 사람이 관심을 가질 법한 이야기를 해 줄게. 화서는 <H>창칼을 들지 않으매, 하늘 아래 다툼이 없는</> 평화로운 나라야.",
            ["DialogueId"] = 12010014,
            ["GUID"] = "1E10D8EC",
            ["NextDialogue"] = 12010015,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D8EC",
            },
        [12010015] = {
            ["Content"] = "什么干什么戈……白好像没太听懂！",
            ["ContentKR"] = "창칼을... 들지 않으매? 스노우는 무슨 말인지 잘 모르겠어!",
            ["DialogueId"] = 12010015,
            ["GUID"] = "1E10D916",
            ["NextDialogue"] = 12010016,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D916",
            },
        [12010016] = {
            ["Content"] = "唔，意思是，这里没有战争，人们也不会像冰湖城那样动不动打架？",
            ["ContentKR"] = "음, 그러니까 여긴 전쟁도 없고, 아이스레이크 시티처럼 사소한 일로 싸우지도 않는다는 건가요?",
            ["DialogueId"] = 12010016,
            ["GUID"] = "1E10D940",
            ["NextDialogue"] = 12010017,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D940",
            },
        [12010017] = {
            ["Content"] = "嗯。就连鸡鸣狗盗之恶，华胥也早已杜绝。",
            ["ContentKR"] = "맞아. 협잡 같은 하찮은 악행조차, 이 화서에서는 사라진 지 오래거든.",
            ["DialogueId"] = 12010017,
            ["GUID"] = "1E10D96A",
            ["NextDialogue"] = 12010018,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D96A",
            },
        [12010018] = {
            ["Content"] = "你该不会是说——华胥没人犯罪？我才不信咧，这种话就是哄小孩子的吧！",
            ["ContentKR"] = "설마... 화서엔 범죄자가 하나도 없다는 거야? 안 믿어. 누가 봐도 애들 달래려고 하는 소리잖아!",
            ["DialogueId"] = 12010018,
            ["GUID"] = "1E10D994",
            ["NextDialogue"] = 12010019,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D994",
            },
        [12010019] = {
            ["Content"] = "呵呵……是吗？",
            ["ContentKR"] = "후후... 그런가?",
            ["DialogueId"] = 12010019,
            ["GUID"] = "1E10D9BE",
            ["NextDialogue"] = 12010020,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D9BE",
            },
        [12010020] = {
            ["Content"] = "止流大当家——",
            ["ContentKR"] = "지류 대방님!",
            ["DialogueId"] = 12010020,
            ["GUID"] = "1E10D9E8",
            ["NextDialogue"] = 12010021,
            ["SpeakNpcName"] = "UI_Npc_Name_FarawayVoice",
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D9E8",
            },
        [12010021] = {
            ["Content"] = "好像码头上有人在叫您。",
            ["ContentKR"] = "누가 부두에서 지류 사장님을 찾고 있는 것 같아요.",
            ["DialogueId"] = 12010021,
            ["GUID"] = "1E10DA12",
            ["NextDialogue"] = 12010022,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10DA12",
            },
        [12010022] = {
            ["Content"] = "嗯，我听到了。我们先下船去看看吧。",
            ["ContentKR"] = "응, 나도 들었어. 우선 배에서 내려 같이 가 보도록 하자.",
            ["DialogueId"] = 12010022,
            ["GUID"] = "1E10DA3C",
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10DA3C",
            },
        [12010101] = {
            ["Content"] = "止流大当家。今次的卸货名单，该找哪位清点核对呢？",
            ["ContentKR"] = "지류 대방님. 이번 하역 목록은 어느 분께 확인을 받아야 할까요?",
            ["DialogueId"] = 12010101,
            ["GUID"] = "1E10E732",
            ["NextDialogue"] = 12010102,
            ["SpeakNpcId"] = 210030,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E732",
            },
        [12010102] = {
            ["Content"] = "杜立没来吗？我嘱咐过他提早前来接应的。",
            ["ContentKR"] = "두립은 안 왔나요? 미리 지원 나오라고 일러두었는데요.",
            ["DialogueId"] = 12010102,
            ["GUID"] = "1E10E75C",
            ["NextDialogue"] = 12010103,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E75C",
            },
        [12010103] = {
            ["Content"] = "这趟运回来了好些贵重货物，有些需要特殊的储运手法，有他盯着，我放心些。",
            ["ContentKR"] = "이번에는 귀한 물건을 많이 들여온 터라, 특수한 방법으로 운반하고 보관해야 하는 것들도 있어요. 두립이 지켜보고 있어야 마음이 놓여요.",
            ["DialogueId"] = 12010103,
            ["GUID"] = "1E10E786",
            ["NextDialogue"] = 12010104,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E786",
            },
        [12010104] = {
            ["Content"] = "兄弟们打听了一圈，今天码头上没人见过杜管事。",
            ["ContentKR"] = "동료들이 두루 수소문해 보았지만, 오늘 부두에서 두립 행수님을 본 사람은 없었습니다.",
            ["DialogueId"] = 12010104,
            ["GUID"] = "1E10E7B0",
            ["NextDialogue"] = 12010105,
            ["SpeakNpcId"] = 210030,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E7B0",
            },
        [12010105] = {
            ["Content"] = "嗯……我明白了。他或许是被什么事情拖住了，先在这里等候一下吧。",
            ["ContentKR"] = "...알겠어요. 아마 사정이 생겨 늦어지는 모양이니, 여기서 잠시 기다려 보죠.",
            ["DialogueId"] = 12010105,
            ["GUID"] = "1E10E7DA",
            ["NextDialogue"] = 12010106,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E7DA",
            },
        [12010106] = {
            ["Content"] = "新鲜出炉的烤鱼嘞——不好吃不要钱——",
            ["ContentKR"] = "갓 구운 생선구이 사세요! 맛없으면 공짜로 드려요!",
            ["DialogueId"] = 12010106,
            ["GUID"] = "1E10E804",
            ["NextDialogue"] = 12010107,
            ["SpeakNpcId"] = 210031,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E804",
            },
        [12010107] = {
            ["Content"] = "哇——好香啊！",
            ["ContentKR"] = "우와! 냄새 엄청 좋다!",
            ["DialogueId"] = 12010107,
            ["GUID"] = "1E10E82E",
            ["NextDialogue"] = 12010108,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E82E",
            },
        [12010108] = {
            ["Content"] = "刚刚才在船上吃了小点心，现在又馋了吗？",
            ["ContentKR"] = "조금 전에 배에서 간식 먹었잖아. 벌써 배고파졌어?",
            ["DialogueId"] = 12010108,
            ["GUID"] = "1E10E858",
            ["NextDialogue"] = 12010109,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E858",
            },
        [12010109] = {
            ["Content"] = "烤鱼是很香没错啦！但感觉空气里还有一股说不上来的香味。",
            ["ContentKR"] = "생선구이 냄새가 엄청 좋잖아! 근데 그거 말고, 뭔가 말로는 표현이 잘 안되는 향기가 섞여 있는 것 같아.",
            ["DialogueId"] = 12010109,
            ["GUID"] = "1E10E882",
            ["NextDialogue"] = 12010110,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E882",
            },
        [12010110] = {
            ["Content"] = "有点像花香，又有点像清晨的霜的味道……总之很好闻就是了！",
            ["ContentKR"] = "꽃 향기 같기도 하고, 새벽에 내린 서리 냄새 같기도 하고... 어쨌든 진짜 좋은 향기야!",
            ["DialogueId"] = 12010110,
            ["GUID"] = "1E10E8AC",
            ["NextDialogue"] = 12010111,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E8AC",
            },
        [12010111] = {
            ["Content"] = "也是巧合，本该前来接应的人迟到了。{nickname}，你们初来乍到，我就陪你们逛逛吧。",
            ["ContentKR"] = "공교롭게도 마중 나오기로 한 사람이 늦네. {nickname}, 스노우, 두 사람은 이곳에 초행일 테니, 내가 안내할게.",
            ["DialogueId"] = 12010111,
            ["GUID"] = "1E10E8D6",
            ["NextDialogue"] = 12010112,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E8D6",
            },
        [12010112] = {
            ["Content"] = "好耶！那白想看看那边的小吃摊子，那个拨浪鼓看起来也好有意思……还有那里！",
            ["ContentKR"] = "좋아! 그럼 난 저쪽에 있는 간식 노점들 구경할래. 저 땡땡이북도 재미있어 보여... 그리고 저기두!",
            ["DialogueId"] = 12010112,
            ["GUID"] = "1E10E900",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E900",
            },
        [12010113] = {
            ["Camera"] = "315.296692,492.476501,203.203613,0.000004,-9.399719,-124.991638,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "针头线脑、香脂香囊，我这儿样样齐全。客官，要来一份吗？",
            ["ContentKR"] = "바늘이며 실, 향유에 향주머니까지! 없는 것 빼고 다 있습니다! 손님, 뭐 필요하신 거라도 있으세요?",
            ["DialogueId"] = 12010113,
            ["FacialId"] = {
                [1] = "210031:Cin_Smile01",
                },
            ["FinalCamera"] = "311.297241,486.82547,183.789551,0.000005,-7.199613,-125.391396,35.000011,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1E10E92A",
            ["LookAt"] = {
                [1] = "210031:n(100001)",
                },
            ["NextDialogue"] = 12010114,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408011,
                [3] = 203001,
                },
            ["SpeakNpcId"] = 210031,
            ["TalkActionId"] = {
                [1] = "210031:Talk01_Start",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E92A",
            },
        [12010114] = {
            ["Content"] = "看中了什么？直接拿吧，我来付账。",
            ["ContentKR"] = "마음에 드는 거 있어? 값은 내가 치를 테니, 편하게 골라.",
            ["DialogueId"] = 12010114,
            ["FacialId"] = {
                [1] = "210004:Smile01",
                },
            ["GUID"] = "1E10E954",
            ["LookAt"] = {
                [1] = "210004:n(100001)",
                },
            ["NextDialogue"] = 12010115,
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210031:Talk01_End",
                [2] = "\
210004:ConfidentR_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E954",
            },
        [12010115] = {
            ["Camera"] = "-300.496887,-107.604889,166.557129,0.000039,-5.799308,31.399658,50.0,441.88739,false,DoNotOverride,8.0",
            ["Content"] = "你们在华胥的所有开销都由我包揽了，尽管花，让他们记在百年春的账上就行。",
            ["ContentKR"] = "화서에 있는 동안 비용은 모두 내가 부담할 테니, 마음껏 쓰고, 대금은 백년춘 앞으로 달아두라고 해.",
            ["DialogueId"] = 12010115,
            ["FinalCamera"] = "-302.217896,-104.770386,166.557129,0.000039,-5.799308,31.399658,50.0,441.88739,false,DoNotOverride,8.0",
            ["GUID"] = "1E10E97E",
            ["LookAt"] = {
                [1] = "100001:n(210004)",
                },
            ["NextOptions"] = {
                [1] = 120101151,
                [2] = 120101152,
                },
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210004:ConfidentRToTalk_Start",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E97E",
            },
        [12010116] = {
            ["Camera"] = "-166.510681,150.144012,125.549805,0.000042,2.600478,-8.198592,50.0,257.556915,false,DoNotOverride,8.0",
            ["Content"] = "呵呵……放心。这些小钱，我供得起。",
            ["ContentKR"] = "후후... 걱정하지 마. 그 정도 돈은 나한테 아무것도 아니니까.",
            ["DialogueId"] = 12010116,
            ["GUID"] = "1E10E9A8",
            ["NextDialogue"] = 12010117,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E9A8",
            },
        [12010117] = {
            ["Camera"] = "-258.889587,722.140747,375.999023,0.000044,-22.399721,-67.201347,35.0,257.556915,false,DoNotOverride,8.0",
            ["Content"] = "止流大当家！您办事归来了。原来这位<H>有龙氏</>是您邀请的客人。",
            ["ContentKR"] = "돌아오셨군요, 지류 대방님! 이 <H>용의 자손</>이 대방님의 손님이셨군요.",
            ["DialogueId"] = 12010117,
            ["GUID"] = "1E10E9D2",
            ["LookAt"] = {
                [1] = "210031:n(210004)",
                [2] = "\
210004:n(210031)",
                [3] = "\
100001:n(210031)",
                },
            ["NextDialogue"] = 12010118,
            ["RelatedWikiId"] = {
                [1] = 405008,
                },
            ["SpeakNpcId"] = 210031,
            ["TalkActionId"] = {
                [1] = "210004:ConfidentRToTalk_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E9D2",
            },
        [12010118] = {
            ["Camera"] = "-148.47049,-63.694336,115.687988,0.000015,3.201023,52.205986,50.000008,354.199371,false,DoNotOverride,8.0",
            ["Content"] = "瞧{性别：他|她}的角，小巧、坚硬又有光泽，一看便有成龙之相。真是优秀的后生，让人看着就心生欢喜。",
            ["ContentKR"] = "{性别:공자|소저}의 뿔을 보니, 작고 옹골차면서 빛깔도 고운 게, 척 봐도 용이 되실 상입니다. 제가 다 흐뭇해질 정도로 훌륭한 청년이시네요.",
            ["DialogueId"] = 12010118,
            ["FinalCamera"] = "-145.448669,-59.758316,115.963867,0.000015,3.201023,52.205986,50.000008,354.199371,false,DoNotOverride,8.0",
            ["GUID"] = "1E10E9FC",
            ["NextDialogue"] = 12010119,
            ["SpeakNpcId"] = 210031,
            ["TalkActionId"] = {
                [1] = "210004:ConfidentR_End",
                },
            ["ToFinalCameraBlendTime"] = 11,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E9FC",
            },
        [12010119] = {
            ["Camera"] = "-23.817619,-70.792191,153.86084,0.00002,-4.399809,81.994202,50.0,147.841843,false,DoNotOverride,8.0",
            ["Content"] = "有龙氏……止流掌柜，你们是在说我吗？",
            ["ContentKR"] = "용의 자손...? 지류 사장님, 지금 제 얘기하시는 거예요?",
            ["DialogueId"] = 12010119,
            ["FacialId"] = {
                [1] = "100001:Curious",
                },
            ["FinalCamera"] = "-23.817619,-70.792191,153.86084,0.00002,-4.399809,81.994202,53.0,147.841843,false,DoNotOverride,8.0",
            ["GUID"] = "1E10EA26",
            ["NextDialogue"] = 12010120,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:ScratchHead_Start",
                },
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10EA26",
            },
        [12010120] = {
            ["Camera"] = "-166.510681,150.144012,125.549805,0.000042,2.600478,-8.198592,50.0,257.556915,false,DoNotOverride,8.0",
            ["Content"] = "忘了告诉你，有龙氏是华胥文化中对于卡戎的称呼。不同于海伯利亚的歧视与打压，在这里，卡戎被视为护佑国家的祥瑞种族。",
            ["ContentKR"] = "아, 미처 말을 못 했네. 화서에서는 카론을 용의 자손이라고 불러. 카론을 차별하고 탄압하는 휘페르보레아 제국과는 달리, 이곳에서는 나라를 지키는 상서로운 종족으로 여기고 있지.",
            ["DialogueId"] = 12010120,
            ["GUID"] = "1E10EA50",
            ["LookAt"] = {
                [1] = "210004:n(100001)",
                [2] = "100001:n(210004)",
                },
            ["NextDialogue"] = 12010121,
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "100001:ScratchHead_End",
                [2] = "210004:Explain01L_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10EA50",
            },
        [12010121] = {
            ["Content"] = "当初我遇见你时，看见年幼的有龙氏被旁人刁难，忍不住照拂了一下。",
            ["ContentKR"] = "널 처음 만났을 때도, 곤경에 처한 어린 용의 자손을 차마 외면할 수 없어서 살짝 도와주었던 거야.",
            ["DialogueId"] = 12010121,
            ["FacialId"] = {
                [1] = "210004:Smile02",
                },
            ["GUID"] = "1E10EA7A",
            ["NextDialogue"] = 12010122,
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210004:Explain01L_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10EA7A",
            },
        [12010122] = {
            ["Camera"] = "-68.049751,89.252998,97.667969,0.000073,16.599312,8.000803,35.0,176.801208,false,DoNotOverride,8.0",
            ["Content"] = "这样说来……止流掌柜也是卡戎——啊，有龙氏。我那时就好奇过您的身份，您看起来地位并不普通。",
            ["ContentKR"] = "그렇게 따지면... 지류 사장님도 카론, 아니, 용의 자손이네요. 저도 그때 지류 사장님 정체가 궁금했어요. 예사롭지 않은 분 같았거든요.",
            ["DialogueId"] = 12010122,
            ["FinalCamera"] = "-68.049751,89.252998,97.667969,0.000073,16.599312,8.000803,38.0,176.801208,false,DoNotOverride,8.0",
            ["GUID"] = "1E10EAA4",
            ["NextDialogue"] = 12010123,
            ["SpeakNpcId"] = 100001,
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10EAA4",
            },
        [12010123] = {
            ["Camera"] = "-258.889587,722.140747,375.999023,0.000044,-22.399721,-67.201347,35.0,257.556915,false,DoNotOverride,8.0",
            ["Content"] = "呵呵……{性别：小弟弟|小妹妹}，你觉得止流大当家是什么身份？",
            ["ContentKR"] = "하하... {性别:공자|소저}는 지류 대방님을 어떤 분이라 생각하셨습니까?",
            ["DialogueId"] = 12010123,
            ["GUID"] = "1E10EACE",
            ["LookAt"] = {
                [1] = "210031:n(100001)",
                [2] = "\
210004:n(210031)",
                [3] = "\
100001:n(210031)",
                },
            ["NextOptions"] = {
                [1] = 120101231,
                [2] = 120101232,
                },
            ["SpeakNpcId"] = 210031,
            ["TalkActionId"] = {
                [1] = "210031:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10EACE",
            },
        [12010124] = {
            ["Camera"] = "-300.496887,-107.604889,166.557129,0.000039,-5.799308,31.399658,50.0,441.88739,false,DoNotOverride,8.0",
            ["Content"] = "她可是年纪尚轻时，就获得了天命青睐，当上了<H>龙渊上卿</>。如今她司掌天禄司，就是说呀，咱们华胥所有贸易、财政、收税都归她管。",
            ["ContentKR"] = "대방님께선 젊은 나이에 하늘의 총애를 받아 용연상경의 지위에 오르셨습니다. 이 화서의 교역, 재정, 세금 권한은 모두 대방님께서 갖고 계시지요.",
            ["DialogueId"] = 12010124,
            ["FacialId"] = {
                [1] = "210004:Smile01",
                },
            ["FinalCamera"] = "-302.217896,-104.770386,166.557129,0.000039,-5.799308,31.399658,50.0,441.88739,false,DoNotOverride,8.0",
            ["GUID"] = "1E10EAF8",
            ["NextDialogue"] = 12010125,
            ["RelatedWikiId"] = {
                [1] = 407005,
                },
            ["SpeakNpcId"] = 210031,
            ["TalkActionId"] = {
                [1] = "210004:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10EAF8",
            },
        [12010125] = {
            ["Content"] = "只是，止流大当家为人平易近人，平日里不准我们称呼她的官职，只愿我们以大当家的头衔相称。在这里做生意的人，多多少少都承过她的人情。",
            ["ContentKR"] = "그저 소탈하신 분이라, 평소엔 관직명보다는 대방님으로 불리길 원하시는 것뿐이랍니다. 이곳 상인들은 너나 할 것 없이 대방님께 크고 작은 도움을 받았지요.",
            ["DialogueId"] = 12010125,
            ["GUID"] = "1E10EB22",
            ["NextDialogue"] = 12010126,
            ["SpeakNpcId"] = 210031,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10EB22",
            },
        [12010126] = {
            ["Content"] = "……只是没有刻意提起的必要罢了。毕竟，以势压人，不如以理服人来得妥当。",
            ["ContentKR"] = "...굳이 언급해야 할 이유가 없었을 뿐이에요. 힘으로 누르는 것보단 이치에 맞게 설득하는 게 옳으니까요.",
            ["DialogueId"] = 12010126,
            ["GUID"] = "1E10EB4C",
            ["NextDialogue"] = 12010127,
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210004:DisagreeHead",
                [2] = "210031:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10EB4C",
            },
        [12010127] = {
            ["Camera"] = "-68.959076,68.54129,118.671875,0.000075,7.399253,11.199726,35.0,165.19751,false,DoNotOverride,8.0",
            ["Content"] = "商人这个身份，进可织星揽月，退可通权达变。比起一官半职来，倒是更符合我的喜好。",
            ["ContentKR"] = "상인이란 신분은, 상황이 유리할 때는 원대한 포부를 펼치고, 상황이 여의치 않을 때도 유연하게 대처할 수 있죠. 어설픈 벼슬자리보다 오히려 더 취향에 맞아요.",
            ["DialogueId"] = 12010127,
            ["FinalCamera"] = "-68.959076,68.54129,118.671875,0.000075,7.399253,11.199726,38.0,165.19751,false,DoNotOverride,8.0",
            ["GUID"] = "1E10EB76",
            ["NextDialogue"] = 12010128,
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210004:Talk03ToTalkL_Start",
                },
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10EB76",
            },
        [12010128] = {
            ["Camera"] = "315.296692,492.476501,203.203613,0.000004,-9.399719,-124.991638,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "来，{性别：小弟弟|小妹妹}。止流大当家难得带贵客来。这件香囊你就作为见面礼收下吧。",
            ["ContentKR"] = "자, {性别:공자|소저}. 지류 대방님께서 모처럼 귀한 손님을 모시고 오셨으니, 만남을 기념하는 선물로 이 향주머니를 드리겠습니다.",
            ["DialogueId"] = 12010128,
            ["FinalCamera"] = "311.297241,486.82547,183.789551,0.000005,-7.199613,-125.391396,35.000011,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1E10EBA0",
            ["NextOptions"] = {
                [1] = 120101281,
                [2] = 120101282,
                },
            ["SpeakNpcId"] = 210031,
            ["TalkActionId"] = {
                [1] = "210004:Talk03ToTalkL_End",
                [2] = "210031:Give",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10EBA0",
            },
        [12010129] = {
            ["Content"] = "<H>香</>在华胥可是有着大作用。定气凝神，防身护体，个中妙用，你很快就能体悟到了。",
            ["ContentKR"] = "<H>향</>은 화서에서 아주 중요한 역할을 한답니다. 기를 안정시키고, 정신을 맑게 해 주고, 몸을 보호해 주지요. 조만간 그 신묘한 효과를 직접 느끼실 수 있을 겁니다.",
            ["DialogueId"] = 12010129,
            ["FacialId"] = {
                [1] = "210031:Cin_Happy01",
                },
            ["GUID"] = "1E10EBCA",
            ["RelatedWikiId"] = {
                [1] = 403005,
                },
            ["SpeakNpcId"] = 210031,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10EBCA",
            },
        [12010130] = {
            ["Content"] = "烤鱿鱼还是香喷喷的小银鱼干，唔，好难选哦……",
            ["ContentKR"] = "오징어구이를 먹을까, 아니면 고소한 멸치를 먹을까... 으음, 뭘 골라야 할지 고민되네...",
            ["DialogueId"] = 12010130,
            ["Duration"] = 3,
            ["GUID"] = "1E10EBF4",
            ["NextDialogue"] = 12010131,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10EBF4",
            },
        [12010131] = {
            ["Content"] = "老板，一样来一份好了！多来点酱汁！",
            ["ContentKR"] = "사장님, 그냥 둘 다 하나씩 줘! 소스는 듬뿍!",
            ["DialogueId"] = 12010131,
            ["GUID"] = "1E10EC1E",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10EC1E",
            },
        [12010132] = {
            ["Content"] = "咦，白跑到哪里去了……",
            ["ContentKR"] = "어? 스노우가 어디 갔지...?",
            ["DialogueId"] = 12010132,
            ["GUID"] = "1E10EC48",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10EC48",
            },
        [12010201] = {
            ["Camera"] = "26.601562,-263.371094,126.632324,0.0,-8.000487,77.603035,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "所以说，梦想是很重要的——比如白的梦想，就是成为世界第一的大魔王！",
            ["ContentKR"] = "그러니까, 꿈은 엄청 중요해! 예를 들어, 스노우의 꿈은 바로 세계 최고의 대마왕이 되는 거야!",
            ["DialogueId"] = 12010201,
            ["GUID"] = "1E10F79A",
            ["NextDialogue"] = 12010202,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408011,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10F79A",
            },
        [12010202] = {
            ["Content"] = "哇，说的太好了！",
            ["ContentKR"] = "우와, 정말 멋진 말이야!",
            ["DialogueId"] = 12010202,
            ["GUID"] = "1E10F7C4",
            ["NextDialogue"] = 12010203,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10F7C4",
            },
        [12010203] = {
            ["Content"] = "你看，华胥的这片码头有这么大对吧。今后本魔王大人的宫殿要比它大十倍！",
            ["ContentKR"] = "봐, 화서에 있는 이 부두, 크기가 아주 크지? 나중에 이 마왕님의 궁전은 저것보다 10배는 더 커다랄 거야!",
            ["DialogueId"] = 12010203,
            ["GUID"] = "1E10F7EE",
            ["NextDialogue"] = 12010204,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10F7EE",
            },
        [12010204] = {
            ["Content"] = "等梦想实现后，白每天就能睡到下午三点，然后从长一百米的大床上醒来，享用搜罗了全世界所有小蛋糕的豪华下午茶！",
            ["ContentKR"] = "꿈이 이루어진 다음엔, 스노우는 맨날 오후 3시까지 늦잠 자고, 100미터짜리 침대에서 일어나서, 온 세상의 케이크를 다 모아 놓은 호화 티타임을 즐길 거야!",
            ["DialogueId"] = 12010204,
            ["GUID"] = "1E10F818",
            ["NextDialogue"] = 12010205,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10F818",
            },
        [12010205] = {
            ["Content"] = "那……我要成为青史留名的织星客，在人类的史书上，写下皎皎一族的名字！",
            ["ContentKR"] = "그럼... 난 역사에 길이 남을 별을 잇는 자가 돼서, 인류의 역사책에 루나 일족의 이름을 남길래!",
            ["DialogueId"] = 12010205,
            ["GUID"] = "1E10F842",
            ["NextDialogue"] = 12010206,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10F842",
            },
        [12010206] = {
            ["Content"] = "到时候，从现在这里到遥远的对岸，整个码头都要铺满我的货物。每个集装箱上都要画一个硕大的皎皎涂鸦！",
            ["ContentKR"] = "그때가 되면, 여기서부터 저 멀리 건너편까지, 부두 전체를 내 물건으로 가득 채울 거야. 화물 상자마다 거대한 루나 그림도 그려 넣고!",
            ["DialogueId"] = 12010206,
            ["GUID"] = "1E10F86C",
            ["NextDialogue"] = 12010207,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10F86C",
            },
        [12010207] = {
            ["Content"] = "很好，就要这个气势！大声喊出来，皎皎之民征服世界——",
            ["ContentKR"] = "좋아, 바로 그 기세야! 소리 질러, 루나가 세계를 정복한다!",
            ["DialogueId"] = 12010207,
            ["GUID"] = "1E10F896",
            ["NextDialogue"] = 12010208,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10F896",
            },
        [12010208] = {
            ["Content"] = "呜呜……早上起床时，我向白龙神君祈愿，希望今天可以撞见好运。",
            ["ContentKR"] = "흑흑... 나 아침에 일어날 때, 백룡신군께 오늘 행운을 만나게 해 달라고 빌었거든?",
            ["DialogueId"] = 12010208,
            ["GUID"] = "1E10F8C0",
            ["NextDialogue"] = 12010209,
            ["RelatedWikiId"] = {
                [1] = 303008,
                },
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10F8C0",
            },
        [12010209] = {
            ["Content"] = "本来只是指望来码头进货时，可以从那些抠门织星客手中再抢下几个单子。没想到，有生之年，竟然能让我看到活的有角皎皎……",
            ["ContentKR"] = "원래는 항구에 물건 떼러 온 김에, 그 짠돌이 같은 별을 잇는 자들한테서 주문이나 몇 건 더 따내 볼까 했던 건데... 세상에, 내 인생에 뿔 달린 루나를 직접 보게 될 줄이야...",
            ["DialogueId"] = 12010209,
            ["GUID"] = "1E10F8EA",
            ["NextDialogue"] = 12010210,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10F8EA",
            },
        [12010210] = {
            ["Camera"] = "345.640625,-174.457031,104.969238,0.000003,-0.600497,140.202652,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "看来白龙神君大人终于回应我的诚心了……那个，尊贵的魔王殿下，可以让我再摸一下你的角吗？",
            ["ContentKR"] = "아무래도 백룡신군께서 드디어 내 정성을 알아주셨나 봐... 저기, 존귀하신 마왕님, 뿔 한 번만 더 만져 봐도 될까?",
            ["DialogueId"] = 12010210,
            ["GUID"] = "1E10F914",
            ["LookAt"] = {
                [1] = "100001:n(200002)",
                },
            ["NextOptions"] = {
                [1] = 120102101,
                [2] = 120102102,
                },
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10F914",
            },
        [12010211] = {
            ["Content"] = "小仆从，你怎么来了……你、你都听见了？",
            ["ContentKR"] = "시종, 네가 왜 거기서 나와? ...서, 설마 다 들었어?",
            ["DialogueId"] = 12010211,
            ["GUID"] = "1E10F93E",
            ["NextOptions"] = {
                [1] = 120102111,
                [2] = 120102112,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10F93E",
            },
        [12010212] = {
            ["Content"] = "咳咳……这就是本魔王麾下的得力大将，{nickname}。",
            ["ContentKR"] = "크, 크흠... {nickname} 얜 이 마왕님의 가장 믿음직한 시종이야.",
            ["DialogueId"] = 12010212,
            ["GUID"] = "1E10F968",
            ["NextDialogue"] = 12010213,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10F968",
            },
        [12010213] = {
            ["Content"] = "哇——不愧是魔王大人，竟然能吸引一位有龙氏前来效忠。幸会，我是即将成为华胥第一织星客的锦鲤皎皎！",
            ["ContentKR"] = "우와! 용의 자손까지 충성을 맹세할 정도라니, 역시 마왕님이야! 만나서 반가워. 난 화서 최고의 별을 잇는 자가 될 행운아 루나야!",
            ["DialogueId"] = 12010213,
            ["GUID"] = "1E10F992",
            ["NextDialogue"] = 12010214,
            ["RelatedWikiId"] = {
                [1] = 203002,
                },
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10F992",
            },
        [12010214] = {
            ["Camera"] = "422.453125,1255.105469,437.982422,0.00003,-8.400634,-104.197899,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "白，止流掌柜还在等着我们呢。玩够了就赶紧回去吧。",
            ["ContentKR"] = "스노우, 지류 사장님이 우릴 기다리고 계셔. 다 놀았으면 얼른 돌아가자.",
            ["DialogueId"] = 12010214,
            ["GUID"] = "1E10F9BC",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10F9BC",
            },
        [12010215] = {
            ["Camera"] = "-387.542969,474.4375,151.621582,0.000187,-2.20303,-35.42408,35.0,100000.0,false,Manual,12.0",
            ["Content"] = "止流掌柜——我把白找回来了。",
            ["ContentKR"] = "지류 사장님! 스노우 데리고 왔어요.",
            ["DialogueId"] = 12010215,
            ["GUID"] = "1E10F9E6",
            ["NextDialogue"] = 12010216,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408011,
                [3] = 203001,
                },
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10F9E6",
            },
        [12010216] = {
            ["Content"] = "……一群**养的！没完没了！",
            ["ContentKR"] = "...이 *자식들! 아주 그냥 적당히를 모르는구나!",
            ["DialogueId"] = 12010216,
            ["GUID"] = "1E10FA10",
            ["NextDialogue"] = 12010217,
            ["SpeakNpcId"] = 210002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FA10",
            },
        [12010217] = {
            ["Camera"] = "192.5,215.453125,162.744141,0.000181,-5.402953,-76.421349,35.0,100000.0,false,Manual,12.0",
            ["Content"] = "……小心！！！",
            ["ContentKR"] = "...조심해요!",
            ["DialogueId"] = 12010217,
            ["GUID"] = "1E10FA3A",
            ["NextDialogue"] = 12010218,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FA3A",
            },
        [12010218] = {
            ["Camera"] = "999.449219,-469.097656,578.913574,0.000173,-25.402763,150.978256,35.0,100000.0,false,Manual,12.0",
            ["Content"] = "喂，你就是这里的舵手吧？赶紧驾船带老子离开这个鬼地方，越快越好！",
            ["ContentKR"] = "어이, 네 녀석이 조타수지? 지금 당장 이 배를 몰아서 날 이 거지 같은 곳에서 내보내, 늦장 부리지 마!",
            ["DialogueId"] = 12010218,
            ["GUID"] = "1E10FA64",
            ["NextDialogue"] = 12010219,
            ["SpeakNpcId"] = 210002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FA64",
            },
        [12010219] = {
            ["Content"] = "胆敢轻举妄动，或者做什么手脚，老子一刀嘎了你。",
            ["ContentKR"] = "장난질을 하거나 허튼수작을 부렸다간, 오늘이 네 제삿날이 될 줄 알아.",
            ["DialogueId"] = 12010219,
            ["GUID"] = "1E10FA8E",
            ["NextDialogue"] = 12010220,
            ["SpeakNpcId"] = 210002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FA8E",
            },
        [12010220] = {
            ["Content"] = "放开他！",
            ["ContentKR"] = "그 사람을 놔줘!",
            ["DialogueId"] = 12010220,
            ["GUID"] = "1E10FAB8",
            ["NextDialogue"] = 12010221,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FAB8",
            },
        [12010221] = {
            ["Camera"] = "-863.470703,299.425781,276.108887,0.000178,-7.60267,-14.021979,35.0,100000.0,false,Manual,12.0",
            ["Content"] = "冷静点，{nickname}，不用出手。",
            ["ContentKR"] = "진정해, {nickname}. 나설 필요 없어.",
            ["DialogueId"] = 12010221,
            ["GUID"] = "1E10FAE2",
            ["NextDialogue"] = 12010222,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FAE2",
            },
        [12010222] = {
            ["Content"] = "可是刀都架在船夫的脖子上了！明明是这么紧急的情况，你们怎么还能这么淡定！",
            ["ContentKR"] = "선원 목에 칼을 겨누고 있잖아! 긴급 상황인데, 다들 어떻게 이렇게 침착한 거야!",
            ["DialogueId"] = 12010222,
            ["GUID"] = "1E10FB0C",
            ["NextDialogue"] = 12010223,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FB0C",
            },
        [12010223] = {
            ["Content"] = "这位劫匪大约是外来者，尚未熟悉这里的规矩。",
            ["ContentKR"] = "이 강도는 화서 사람이 아니라서, 이곳 규율에 익숙하지 않은 모양이군.",
            ["DialogueId"] = 12010223,
            ["GUID"] = "1E10FB36",
            ["NextDialogue"] = 12010224,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FB36",
            },
        [12010224] = {
            ["Content"] = "记得我先前所说吗？华胥是<H>止戈之乡</>。也好，让你们有机会亲眼见证——",
            ["ContentKR"] = "화서는 <H>창칼을 들지 않는 나라</>라고 했던 거 기억해? 마침 잘됐군, 직접 보여줄 기회가 생겼네.",
            ["DialogueId"] = 12010224,
            ["GUID"] = "1E10FB60",
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FB60",
            },
        [12010225] = {
            ["Content"] = "嗷呜——",
            ["ContentKR"] = "크르르릉!",
            ["DialogueId"] = 12010225,
            ["GUID"] = "1E10FB8A",
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FB8A",
            },
        }
  end },
  { MinKey = 12010226, MaxKey = 12010909, Loader = function()
      return {
        [12010226] = {
            ["Content"] = "又是这些东西，怎么阴魂不散的！",
            ["ContentKR"] = "왜 이렇게 끈질기게 들러붙는 거야!",
            ["DialogueId"] = 12010226,
            ["GUID"] = "1E10FBB4",
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FBB4",
            },
        [12010227] = {
            ["Camera"] = "-78.574219,498.462891,113.020996,0.000014,-0.99994,-74.596542,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那、那是什么……？",
            ["ContentKR"] = "저, 저건 대체...?",
            ["DialogueId"] = 12010227,
            ["GUID"] = "1E10FBDE",
            ["NextDialogue"] = 12010228,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FBDE",
            },
        [12010228] = {
            ["Content"] = "小仆从，看到了吗！那个家伙只用了一招就让坏人消失了诶。",
            ["ContentKR"] = "시종, 봤어?! 저 녀석이 순식간에 악당을 사라지게 만들었어.",
            ["DialogueId"] = 12010228,
            ["GUID"] = "1E10FC08",
            ["NextDialogue"] = 12010229,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FC08",
            },
        [12010229] = {
            ["Content"] = "<H>大风有隧，有空大谷。有兽狴犴，乘风而行。香尘扰扰，缘有罪因。</>这是华胥子民从牙牙学语时便能念诵的歌谣。",
            ["ContentKR"] = "\"<H>큰바람 일어 넓은 골짜기에 이르고, 폐안이라는 짐승 있어 바람 타고 다니네. 향 태운 재 자욱하니 죄지은 자 있었구나.</>\" 화서의 아이들이 옹알이할 때부터 읊는 노래지.",
            ["DialogueId"] = 12010229,
            ["GUID"] = "1E10FC32",
            ["NextDialogue"] = 12010230,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FC32",
            },
        [12010230] = {
            ["Content"] = "歌谣中的“狴犴”，便是你们所见之物——华胥的守护者。",
            ["ContentKR"] = "이 노래 속의 '폐안'이 바로 너희들이 본, 화서의 수호자야.",
            ["DialogueId"] = 12010230,
            ["GUID"] = "1E10FC5C",
            ["NextDialogue"] = 12010231,
            ["RelatedWikiId"] = {
                [1] = 303009,
                },
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FC5C",
            },
        [12010231] = {
            ["Content"] = "华胥全境被一种无声无形、但又恒常流转之法则，<H>大风九章</>所统御。任何人只要踏入了华胥的界域，就会进入大风九章的保护范围内。",
            ["ContentKR"] = "화서 전역은 형체는 없어도 늘 순환하는 법칙, <H>대풍구장</>이 제어하고 있어. 누구든 화서에 발을 들이면, 그 법칙의 보호 범위 안에 들어가게 돼.",
            ["DialogueId"] = 12010231,
            ["GUID"] = "1E10FC86",
            ["NextDialogue"] = 12010232,
            ["RelatedWikiId"] = {
                [1] = 304003,
                },
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FC86",
            },
        [12010232] = {
            ["Content"] = "对于触犯诫律者，狴犴会从凛风中突现，施以惩戒。",
            ["ContentKR"] = "규율을 어긴 자는, 폐안이 바람과 함께 홀연히 나타나 벌을 내리게 되지.",
            ["DialogueId"] = 12010232,
            ["GUID"] = "1E10FCB0",
            ["NextDialogue"] = 12010233,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FCB0",
            },
        [12010233] = {
            ["Content"] = "原来，这就是这里完全杜绝犯罪的理由……",
            ["ContentKR"] = "아하, 그래서 여긴 범죄가 전혀 없는 거구나...",
            ["DialogueId"] = 12010233,
            ["GUID"] = "1E10FCDA",
            ["NextDialogue"] = 12010234,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FCDA",
            },
        [12010234] = {
            ["Content"] = "只是不知何故，出现了不懂规矩的外来者。看来，这一趟办事归来，倒是有些“惊喜”等着我呢。",
            ["ContentKR"] = "하지만 어찌 된 영문인지, 규율을 모르는 외지인이 나타났네. 아무래도 이번 귀향길에 뜻밖의 서프라이즈가 날 기다리고 있나 본데.",
            ["DialogueId"] = 12010234,
            ["GUID"] = "1E10FD04",
            ["NextDialogue"] = 12010235,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FD04",
            },
        [12010235] = {
            ["Content"] = "大当家——不好意思，属下来迟了——",
            ["ContentKR"] = "대방님, 죄송합니다. 제가 늦었습니다...",
            ["DialogueId"] = 12010235,
            ["GUID"] = "1E10FD2E",
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FD2E",
            },
        [12010301] = {
            ["Camera"] = "-156.389893,790.13324,235.143555,0.00015,-10.001431,-71.777824,50.0,856.361206,false,DoNotOverride,2.8",
            ["Content"] = "幸好歹人已经被截获了……他竟然跑到这里来，惊扰到了您。",
            ["ContentKR"] = "다행히 괴한은 이미 붙잡혔군요. 그자가 여기까지 와서 소란을 피울 줄이야...",
            ["DialogueId"] = 12010301,
            ["FacialId"] = {
                [1] = "210032:Cin_Sad01",
                },
            ["FinalCamera"] = "-137.076416,731.468506,224.247559,0.00015,-10.001431,-71.777466,50.0,856.361206,false,DoNotOverride,2.8",
            ["GUID"] = "1E110802",
            ["LookAt"] = {
                [1] = "100001:n(210032)",
                [2] = "210004:n(210032)",
                [3] = "210003:n(210032)",
                },
            ["NextDialogue"] = 12010302,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408011,
                [3] = 203001,
                [4] = 303009,
                [5] = 304003,
                },
            ["SpeakNpcId"] = 210032,
            ["TalkActionId"] = {
                [1] = "210032:Explain02_Start",
                [2] = "210004:ConfidentR_Start",
                },
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1201/120103/1E110802",
            },
        [12010302] = {
            ["Camera"] = "-53.126144,-142.106125,132.289062,0.000153,-0.802465,48.999199,50.0,257.290894,false,DoNotOverride,2.8",
            ["Content"] = "杜立，不用急。调顺了气息再说话。",
            ["ContentKR"] = "두립, 서두르지 말고 숨부터 고르고 말해요.",
            ["DialogueId"] = 12010302,
            ["FacialId"] = {
                [1] = "210004:Unhappy01",
                },
            ["FinalCamera"] = "-24.557076,-109.239418,131.683594,0.000153,-0.802465,48.999199,50.0,257.290894,false,DoNotOverride,2.8",
            ["GUID"] = "1E11082C",
            ["NextDialogue"] = 12010303,
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210032:Explain02_End",
                [2] = "210004:ConfidentRToExplain_Start",
                },
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1201/120103/1E11082C",
            },
        [12010303] = {
            ["Content"] = "你迟来的理由，和这个歹徒有关吗？",
            ["ContentKR"] = "늦은 이유가, 저 괴한과 관련이 있나요?",
            ["DialogueId"] = 12010303,
            ["GUID"] = "1E110856",
            ["NextDialogue"] = 12010304,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120103/1E110856",
            },
        [12010304] = {
            ["Camera"] = "80.523117,233.023392,157.48584,0.000134,-5.002382,-84.793343,35.0,422.948425,false,DoNotOverride,2.8",
            ["Content"] = "……确是如此。",
            ["ContentKR"] = "...그렇습니다.",
            ["DialogueId"] = 12010304,
            ["FinalCamera"] = "83.662094,198.468262,154.45166,0.000134,-5.002382,-84.793343,35.0,422.948425,false,DoNotOverride,2.8",
            ["GUID"] = "1E110880",
            ["LookAt"] = {
                [1] = "210032:n(210004)",
                },
            ["NextDialogue"] = 12010305,
            ["SpeakNpcId"] = 210032,
            ["TalkActionId"] = {
                [1] = "210004:ConfidentRToExplain_End",
                [2] = "210032:Agree",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120103/1E110880",
            },
        [12010305] = {
            ["Content"] = "最近<W>烛阴之灾</>势头愈烈。部分织星客对禁行令不满，绕开我们百年春，私自从外界雇了护卫，欲与险境一搏。",
            ["ContentKR"] = "최근 <W>촉룡의 재앙</>이 더욱 심각해지면서, 몇몇 별을 잇는 자들이 통행금지령에 불만을 품고, 우리 백년춘 밖에서 몰래 호위를 고용했습니다. 위험을 무릅쓰고라도 한몫 잡겠다는 속셈이지요.",
            ["DialogueId"] = 12010305,
            ["GUID"] = "1E1108AA",
            ["NextDialogue"] = 12010306,
            ["RelatedWikiId"] = {
                [1] = 304004,
                },
            ["SpeakNpcId"] = 210032,
            ["TalkActionId"] = {
                [1] = "210032:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120103/1E1108AA",
            },
        [12010306] = {
            ["Content"] = "结果找来了个品行不端的，就有了现在这个结果。",
            ["ContentKR"] = "그러다 이런 무도한 자까지 고용해, 이런 결과를 낳게 된 것입니다.",
            ["DialogueId"] = 12010306,
            ["GUID"] = "1E1108D4",
            ["NextDialogue"] = 12010307,
            ["SpeakNpcId"] = 210032,
            ["VoiceName"] = "voice/$Locale$/story/1201/120103/1E1108D4",
            },
        [12010307] = {
            ["Camera"] = "-24.557076,-109.239418,131.683594,0.000153,-0.802465,48.999199,50.0,257.290894,false,DoNotOverride,2.8",
            ["Content"] = "我赶来前，商人们还在为这事争执不休，吵得百年春前那叫一个沸反盈天。恐怕还需要您赶紧出面，从中调解一下。",
            ["ContentKR"] = "제가 여기 오기 전까지도 상인들이 계속 이 일로 다투는 바람에 백년춘 앞이 온통 아수라장이었습니다. 아무래도 대방님께서 직접 중재에 나서 주셔야 할 것 같습니다.",
            ["DialogueId"] = 12010307,
            ["GUID"] = "1E1108FE",
            ["NextDialogue"] = 12010308,
            ["SpeakNpcId"] = 210032,
            ["VoiceName"] = "voice/$Locale$/story/1201/120103/1E1108FE",
            },
        [12010308] = {
            ["Content"] = "嗯，大致情况我了解了。",
            ["ContentKR"] = "음, 대략적인 상황은 알겠어요.",
            ["DialogueId"] = 12010308,
            ["FacialId"] = {
                [1] = "210004:None",
                },
            ["GUID"] = "1E110928",
            ["NextDialogue"] = 12010309,
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210032:Explain02_End",
                [2] = "210004:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120103/1E110928",
            },
        [12010309] = {
            ["Camera"] = "-158.883514,-85.465759,136.083008,0.000155,-2.202388,31.597618,50.0,257.290894,false,DoNotOverride,2.8",
            ["Content"] = "抱歉，{nickname}……总有这些事务缠身。看来能陪伴你的时间已经结束了。",
            ["ContentKR"] = "미안, {nickname}... 항상 일이 이렇게 발목을 잡네. 함께할 수 있는 시간은 여기까지인 모양이야.",
            ["DialogueId"] = 12010309,
            ["FacialId"] = {
                [1] = "210004:Smile01",
                },
            ["FinalCamera"] = "-143.195038,-56.148727,137.883789,0.000157,-2.602418,27.796841,50.0,257.290894,false,DoNotOverride,2.8",
            ["GUID"] = "1E110952",
            ["LookAt"] = {
                [1] = "210004:n(100001)",
                [2] = "100001:n(210004)",
                [3] = "200002:n(210004)",
                [4] = "210003:n(210004)",
                [5] = "210032:n(100001)",
                },
            ["NextOptions"] = {
                [1] = 120103091,
                [2] = 120103092,
                },
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210004:ConfidentR_End",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["TurnTo"] = {
                [1] = "210032:n(100001)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120103/1E110952",
            },
        [12010310] = {
            ["Content"] = "只是，有一件要紧的事尚未交代你们。",
            ["ContentKR"] = "다만, 두 사람에게 미처 말하지 못한 중요한 이야기가 있어.",
            ["DialogueId"] = 12010310,
            ["FacialId"] = {
                [1] = "210004:Nervous",
                },
            ["GUID"] = "1E11097C",
            ["NextDialogue"] = 12010311,
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210004：Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120103/1E11097C",
            },
        [12010311] = {
            ["Camera"] = "-570.646729,-313.165039,402.481445,0.000143,-22.602468,31.792645,46.756084,257.290894,false,DoNotOverride,2.8",
            ["Content"] = "初入华胥者，必须了解<H>九诫</>的内容。若是不慎触犯了大风九章的诫律，或许就落得像刚刚歹人那般的下场。",
            ["ContentKR"] = "화서에 처음 온 사람은 반드시 <H>아홉 규율</>의 내용을 알아야 해. 혹시 실수로 대풍구장의 규율을 어기게 되면, 방금 전 그 괴한과 같은 최후를 맞이할 수 있거든.",
            ["DialogueId"] = 12010311,
            ["FinalCamera"] = "-606.82959,-335.576965,420.213379,0.000143,-22.602468,31.792645,46.756084,257.290894,false,DoNotOverride,2.8",
            ["GUID"] = "1E1109A6",
            ["NextDialogue"] = 12010312,
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210004:Talk03ToThink_Start",
                },
            ["ToFinalCameraBlendTime"] = 12,
            ["VoiceName"] = "voice/$Locale$/story/1201/120103/1E1109A6",
            },
        [12010312] = {
            ["Camera"] = "202.094421,-70.305641,138.647461,0.000175,-12.601808,127.792175,50.000008,318.602966,false,DoNotOverride,2.8",
            ["Content"] = "放心，止流掌柜！我会带他们去看诫碑的，就包在本皎皎身上吧！",
            ["ContentKR"] = "안심해, 지류 대방님! 내가 두 분을 계율이 쓰여진 비석으로 안내할게. 나한테 맡겨만 달라고!",
            ["DialogueId"] = 12010312,
            ["FacialId"] = {
                [1] = "210003:Confident01",
                },
            ["GUID"] = "1E1109D0",
            ["LookAt"] = {
                [1] = "210004:n(210003)",
                [2] = "100001:n(210003)",
                [3] = "210032:n(210003)",
                [4] = "200002:n(210003)",
                },
            ["NextDialogue"] = 12010313,
            ["SpeakNpcId"] = 210003,
            ["TalkActionId"] = {
                [1] = "210004:Think_End",
                [2] = "210003:Excited02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120103/1E1109D0",
            },
        [12010313] = {
            ["Camera"] = "-525.948059,104.858734,227.421875,0.000185,-12.003141,1.202763,50.0,572.522461,false,DoNotOverride,2.8",
            ["Content"] = "咦……你们两位已经认识了？",
            ["ContentKR"] = "호오... 두 사람, 벌써 아는 사이야?",
            ["DialogueId"] = 12010313,
            ["FacialId"] = {
                [1] = "210004:Doubt01",
                },
            ["GUID"] = "1E1109FA",
            ["LookAt"] = {
                [1] = "200002:n(210004)",
                },
            ["NextDialogue"] = 12010314,
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210004:Explain02_Start",
                [2] = "210003:Excited02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120103/1E1109FA",
            },
        [12010314] = {
            ["Camera"] = "202.094421,-70.305641,138.647461,0.000175,-12.601808,127.792175,50.000008,318.602966,false,DoNotOverride,2.8",
            ["Content"] = "这就是光之魔王大人走到哪里散发到哪里的人格魅力！",
            ["ContentKR"] = "이게 바로 빛의 마왕님이 어딜 가든 뿜어내는 인격적 매력이라는 거야!",
            ["DialogueId"] = 12010314,
            ["FacialId"] = {
                [1] = "200002:Confident02",
                },
            ["FinalCamera"] = "202.094421,-70.305641,138.647461,0.000182,-12.401793,125.792969,50.000011,318.602966,false,DoNotOverride,2.8",
            ["GUID"] = "1E110A24",
            ["LookAt"] = {
                [1] = "200002:n(210004)",
                },
            ["NextDialogue"] = 12010315,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1201/120103/1E110A24",
            },
        [12010315] = {
            ["Content"] = "这位冰湖城来的魔王大人和本皎皎可是拜把子的交情！我会担起东道主的责任，好好带领他们，让他们宾至如归的！",
            ["ContentKR"] = "아이스레이크 시티에서 오신 마왕님은 이 루나랑 의형제나 다름없는 사이야! 내가 안내를 맡아서, 두 사람이 편히 지낼 수 있도록 잘 데리고 다닐게!",
            ["DialogueId"] = 12010315,
            ["GUID"] = "1E110A4E",
            ["NextDialogue"] = 12010316,
            ["SpeakNpcId"] = 210003,
            ["TalkActionId"] = {
                [1] = "210003:SpecialHappy_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120103/1E110A4E",
            },
        [12010316] = {
            ["Camera"] = "-525.948059,104.858734,227.421875,0.000185,-12.003141,1.202763,50.0,572.522461,false,DoNotOverride,2.8",
            ["Content"] = "嗯，你对这片地界熟悉，交给你我却是放心。那你们随后到<H>百年春</>来找我就行。",
            ["ContentKR"] = "음, 넌 이곳 지리에 밝을 테니 안심이 되는구나. 그러면 너희는 나중에 <H>백년춘</>에 와서 날 찾도록 해.",
            ["DialogueId"] = 12010316,
            ["FacialId"] = {
                [1] = "210004:Smile01",
                },
            ["GUID"] = "1E110A78",
            ["NextDialogue"] = 12010317,
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210004:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120103/1E110A78",
            },
        [12010317] = {
            ["Camera"] = "-197.656311,99.099442,143.551758,0.000188,-4.202909,-1.79672,50.000008,572.522461,false,DoNotOverride,2.8",
            ["Content"] = "{nickname}，路上注意安全。逛得尽兴了再来即可。先前提到的委托，等你来了，我再把细节交代与你。",
            ["ContentKR"] = "조심해서 다녀와, {nickname}. 마음껏 구경하고 돌아오면 돼. 전에 말했던 의뢰는, 돌아오면 자세히 설명해 줄게.",
            ["DialogueId"] = 12010317,
            ["FacialId"] = {
                [1] = "210004:Smile01",
                },
            ["GUID"] = "1E110AA2",
            ["LookAt"] = {
                [1] = "210004:n(100001)",
                [2] = "100001:n(210004)",
                [3] = "210032:n(100001)",
                [4] = "200002:n(210004)",
                },
            ["NextDialogue"] = 12010318,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{210004},AnimationId{\"Explain02_End\"},Duration{1}},\
PlayAnimation{ActorId{210004},AnimationId{\"Explain01_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120103/1E110AA2",
            },
        [12010318] = {
            ["Camera"] = "221.316528,188.197891,147.143066,0.000172,-5.802731,-150.999084,50.000011,338.357025,false,DoNotOverride,2.8",
            ["Content"] = "我明白了。止流掌柜，您快去忙吧！",
            ["ContentKR"] = "알겠어요. 지류 사장님, 어서 볼일 보세요!",
            ["DialogueId"] = 12010318,
            ["FacialId"] = {
                [1] = "100001:Smile01",
                },
            ["GUID"] = "1E110ACC",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120103/1E110ACC",
            },
        [12010401] = {
            ["Camera"] = "1510.199219,3684.390625,1778.458984,0.000038,-13.800717,-84.392624,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这就是你们说的诫碑了吧，让我瞧瞧——",
            ["ContentKR"] = "이게 바로 아까 말했던 계율비인가 보네. 어디 보자...",
            ["DialogueId"] = 12010401,
            ["GUID"] = "1E11186A",
            ["NextDialogue"] = 12010402,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408011,
                [3] = 304003,
                [4] = 203002,
                [5] = 405009,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E11186A",
            },
        [12010402] = {
            ["Camera"] = "696.953125,-317.017578,277.799805,0.000066,-12.201128,149.811142,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "怎、怎么办，白完全看不懂……",
            ["ContentKR"] = "어, 어떡하지? 스노우는 하나도 모르겠어...",
            ["DialogueId"] = 12010402,
            ["GUID"] = "1E111894",
            ["NextDialogue"] = 12010403,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111894",
            },
        [12010403] = {
            ["Camera"] = "-185.355469,366.291016,89.310547,0.00007,1.398802,-55.587837,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我来给你们翻译——锦鲤皎皎的大风九章小课堂开始！为了在华胥玩得开心，大家一定要认真听哦！",
            ["ContentKR"] = "내가 번역해 줄게. 행운아 루나의 대풍구장 특별 강좌! 화서에서 신나게 놀 수 있도록, 두 사람 모두 열심히 들어야 해!",
            ["DialogueId"] = 12010403,
            ["GUID"] = "1E1118BE",
            ["NextDialogue"] = 12010404,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E1118BE",
            },
        [12010404] = {
            ["Content"] = "最上面这行是<H>戕身害命，不可为也</>。任何伤害别人的行为在华胥都是绝对禁止的！",
            ["ContentKR"] = "가장 위에 있는 이 줄은 \"<H>남을 해하거나 목숨을 빼앗지 말지어다</>\"야. 다른 사람을 해치는 행동은 화서에선 절대 안 돼!",
            ["DialogueId"] = 12010404,
            ["GUID"] = "1E1118E8",
            ["NextDialogue"] = 12010405,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E1118E8",
            },
        [12010405] = {
            ["Content"] = "这条的惩罚最为严重，一定一定要小心哦。不然就会像刚刚看到的坏强盗一样，被一下子定在原地，化作晶尘。",
            ["ContentKR"] = "이 조항을 어기면 가장 큰 벌을 받게 되니까, 꼭! 꼭! 조심하도록 해. 안 그러면 아까 봤던 그 강도처럼, 그 자리에서 수정 가루가 돼 버릴 거야.",
            ["DialogueId"] = 12010405,
            ["GUID"] = "1E111912",
            ["NextDialogue"] = 12010406,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111912",
            },
        [12010406] = {
            ["Content"] = "哇，这么吓人……",
            ["ContentKR"] = "와, 엄청 무섭네...",
            ["DialogueId"] = 12010406,
            ["GUID"] = "1E11193C",
            ["NextDialogue"] = 12010407,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E11193C",
            },
        [12010407] = {
            ["Content"] = "放心，只有坏人才需要害怕啦，好人才不用担心呢！",
            ["ContentKR"] = "걱정하지 마. 무서워해야 하는 건 나쁜 사람이지, 착한 사람은 걱정할 필요 없어!",
            ["DialogueId"] = 12010407,
            ["GUID"] = "1E111966",
            ["NextDialogue"] = 12010408,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111966",
            },
        [12010408] = {
            ["Content"] = "多亏了大风九章，现在的华胥压根就不会有什么战争呀犯罪呀，大家都和睦融融的。我听说外面的世界可不是这样。",
            ["ContentKR"] = "대풍구장 덕분에, 지금의 화서는 전쟁이나 범죄 같은 건 아예 없고, 다들 사이좋게 지내고 있어. 사람들이 바깥세상은 안 그렇다고 하더라고.",
            ["DialogueId"] = 12010408,
            ["GUID"] = "1E111990",
            ["NextDialogue"] = 12010409,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111990",
            },
        [12010409] = {
            ["Content"] = "这倒是。要是在冰湖城，有人犯了事，就只能指望治安署那些趾高气昂的士兵。",
            ["ContentKR"] = "그건 그래. 아이스레이크 시티에선 누가 범죄를 저지르면, 거들먹거리는 치안서 병사들이 잘 처리해 주길 바라는 수밖에 없으니까.",
            ["DialogueId"] = 12010409,
            ["GUID"] = "1E1119BA",
            ["NextDialogue"] = 12010410,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E1119BA",
            },
        [12010410] = {
            ["Content"] = "而且他们很少管卡戎和穷人的事，最后还是得靠我们自己去抓犯人。前几天好不容易遇到一个靠谱的大姐姐，最后还跑掉不干了……",
            ["ContentKR"] = "더군다나 걔들은 카론이나 가난한 사람들 일은 거의 신경도 안 써서, 결국엔 우리가 직접 범인을 잡아야 해. 며칠 전에 간신히 좀 믿음직한 언니를 만났었는데, 끝내는 안 하겠다고 도망가 버렸지...",
            ["DialogueId"] = 12010410,
            ["GUID"] = "1E1119E4",
            ["NextDialogue"] = 12010411,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E1119E4",
            },
        [12010411] = {
            ["Content"] = "华胥这些长得像冰原狼一样的，叫毕、毕什么的威风猛兽，可比冰湖城的治安署靠谱多啦！",
            ["ContentKR"] = "스노우 울프랑 닮은 폐, 폐 어쩌구 하는 화서의 위풍당당한 맹수들이 아이스레이크 시티의 치안서보다 훨씬 더 믿음직스러워!",
            ["DialogueId"] = 12010411,
            ["GUID"] = "1E111A0E",
            ["NextDialogue"] = 12010412,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111A0E",
            },
        [12010412] = {
            ["Content"] = "是狴犴，不要再记错它们的名字了！",
            ["ContentKR"] = "폐안이야! 이름을 제대로 기억해 줘!",
            ["DialogueId"] = 12010412,
            ["GUID"] = "1E111A38",
            ["NextOptions"] = {
                [1] = 120104121,
                [2] = 120104122,
                },
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111A38",
            },
        [12010413] = {
            ["Content"] = "当然，狴犴可是天命的使者！",
            ["ContentKR"] = "당연하지. 폐안은 하늘의 전령인걸!",
            ["DialogueId"] = 12010413,
            ["GUID"] = "1E111A62",
            ["NextDialogue"] = 12010415,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111A62",
            },
        [12010414] = {
            ["Content"] = "这可不行！狴犴可是天命的使者。",
            ["ContentKR"] = "그건 안 돼! 폐안은 하늘의 전령이란 말이야.",
            ["DialogueId"] = 12010414,
            ["GUID"] = "1E111A8C",
            ["NextDialogue"] = 12010415,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111A8C",
            },
        [12010415] = {
            ["Content"] = "这就要说到，为什么有龙氏是大家都很敬仰的存在啦。",
            ["ContentKR"] = "사람들이 용의 자손을 존경하고 우러러보는 이유도 바로 그래서라고.",
            ["DialogueId"] = 12010415,
            ["GUID"] = "1E111AB6",
            ["NextDialogue"] = 12010416,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111AB6",
            },
        [12010416] = {
            ["Content"] = "别卖关子啦，快说快说——",
            ["ContentKR"] = "빙빙 돌리지 말고, 얼른 말해 봐!",
            ["DialogueId"] = 12010416,
            ["GUID"] = "1E111AE0",
            ["NextDialogue"] = 12010417,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111AE0",
            },
        [12010417] = {
            ["Content"] = "一部分有龙氏到了成年左右的时间，会感应天命，被大风九章蒙召，化为狴犴。",
            ["ContentKR"] = "용의 자손 중엔 성년이 될 때쯤 하늘의 뜻을 느끼고, 대풍구장의 부름을 받아 폐안으로 변하는 사람들이 있어.",
            ["DialogueId"] = 12010417,
            ["GUID"] = "1E111B0A",
            ["NextDialogue"] = 12010418,
            ["RelatedWikiId"] = {
                [1] = 303009,
                },
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111B0A",
            },
        [12010418] = {
            ["Content"] = "（嗯？卡戎……<H>成年左右</>？）",
            ["ContentKR"] = "(음? 카론이... <H>성년이 될 무렵</>이라고?)",
            ["DialogueId"] = 12010418,
            ["DisableMouth"] = 1,
            ["GUID"] = "1E111B34",
            ["NextDialogue"] = 12010419,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111B34",
            },
        [12010419] = {
            ["Content"] = "再附赠一个知识点，其实狴犴只是大风九章最普通的执法者。",
            ["ContentKR"] = "한 가지 더 말해 주자면, 사실 폐안은 대풍구장에서 가장 평범한 법의 집행자일 뿐이야.",
            ["DialogueId"] = 12010419,
            ["GUID"] = "1E111B5E",
            ["NextDialogue"] = 12010420,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111B5E",
            },
        [12010420] = {
            ["Content"] = "有一些更厉害的有龙氏，能够直接以人身进入大风九章，作为<H>应天尉</>活动着，代天命威慑躲在暗中的坏人，让他们不敢造次！",
            ["ContentKR"] = "그보다 더 대단한 용의 자손들은, 인간의 몸으로 대풍구장에 들어가서 <H>응천위</>로 활약하고, 또 하늘의 대리자로서 어둠 속에 숨은 악당들을 압박하고 있어. 악당들이 함부로 날뛰지 못하게 말이야!",
            ["DialogueId"] = 12010420,
            ["GUID"] = "1E111B88",
            ["NextDialogue"] = 12010421,
            ["RelatedWikiId"] = {
                [1] = 405010,
                },
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111B88",
            },
        [12010421] = {
            ["Content"] = "对于那种非常棘手的坏人，应天尉就会出动，将他们缉拿，威风凛凛！",
            ["ContentKR"] = "아주 골치 아픈 악당이 나타나면, 응천위가 출동해서, 위풍당당하게 체포하는 거지!",
            ["DialogueId"] = 12010421,
            ["GUID"] = "1E111BB2",
            ["NextDialogue"] = 12010422,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111BB2",
            },
        [12010422] = {
            ["Content"] = "不过……当然还是希望你们永远不要遇到应天尉！",
            ["ContentKR"] = "물론... 두 사람이 응천위를 만날 일은 영원히 없길 바라!",
            ["DialogueId"] = 12010422,
            ["GUID"] = "1E111BDC",
            ["NextDialogue"] = 12010423,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111BDC",
            },
        [12010423] = {
            ["Content"] = "好啦，对于第一条诫律的解说到此为止！接下来——",
            ["ContentKR"] = "자, 첫 번째 규율에 대한 설명은 여기까지야! 다음은...",
            ["DialogueId"] = 12010423,
            ["GUID"] = "1E111C06",
            ["NextDialogue"] = 12010424,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111C06",
            },
        [12010424] = {
            ["Content"] = "眩晕屏幕特效",
            ["ContentKR"] = "화면이 어지럽게 흔들리는 특수 효과",
            ["DialogueId"] = 12010424,
            ["GUID"] = "1E111C30",
            ["NextDialogue"] = 12010425,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111C30",
            },
        [12010425] = {
            ["Content"] = "…………？",
            ["ContentKR"] = "......?",
            ["DialogueId"] = 12010425,
            ["GUID"] = "1E111C5A",
            ["NextDialogue"] = 12010426,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111C5A",
            },
        [12010426] = {
            ["Content"] = "（总觉得……那块诫碑，像是在<H>呼唤</>我一样……）",
            ["ContentKR"] = "(왠지... 저 비석이 날 <H>부르는</> 것 같아...)",
            ["DialogueId"] = 12010426,
            ["DisableMouth"] = 1,
            ["GUID"] = "1E111C84",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111C84",
            },
        [12010427] = {
            ["Content"] = "你触摸了诫碑，忽然你的脑内传来了一阵眩晕。",
            ["ContentKR"] = "비석에 손을 대자, 갑자기 머리가 어질해진다.",
            ["DialogueId"] = 12010427,
            ["GUID"] = "1E111CAE",
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111CAE",
            },
        [12010428] = {
            ["DialogueId"] = 12010428,
            ["GUID"] = "1E111CD8",
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111CD8",
            },
        [12010429] = {
            ["Camera"] = "265.414062,55.289062,169.237793,0.000002,-24.800047,-172.198669,11.88,100000.0,false,Manual,2.8",
            ["Content"] = "接下来，我要来讲第二条啦！大风九章的第二条即是——",
            ["ContentKR"] = "다음은, 두 번째 규율이야! 대풍구장의 두 번째 조항은...",
            ["DialogueId"] = 12010429,
            ["GUID"] = "1E111D02",
            ["NextOptions"] = {
                [1] = 120104291,
                [2] = 120104292,
                },
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408011,
                [3] = 304003,
                [4] = 405009,
                [5] = 203002,
                },
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111D02",
            },
        [12010432] = {
            ["Content"] = "完全正确！",
            ["ContentKR"] = "정확해!",
            ["DialogueId"] = 12010432,
            ["GUID"] = "1E111D80",
            ["NextDialogue"] = 12010433,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111D80",
            },
        [12010433] = {
            ["Content"] = "小仆从，你什么时候偷偷学会了华胥文字？白都不知道！",
            ["ContentKR"] = "시종, 너 언제 몰래 화서 글자를 배운 거야? 스노우는 전혀 몰랐어!",
            ["DialogueId"] = 12010433,
            ["GUID"] = "1E111DAA",
            ["NextDialogue"] = 12010434,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111DAA",
            },
        [12010434] = {
            ["Content"] = "不，我不认识这些文字……",
            ["ContentKR"] = "아니야, 난 이 글자들 몰라...",
            ["DialogueId"] = 12010434,
            ["GUID"] = "1E111DD4",
            ["NextDialogue"] = 12010435,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111DD4",
            },
        [12010435] = {
            ["Content"] = "刚刚我靠近诫碑时，脑海里突然冒出来了一个声音，告诉了我这些内容。你知道这是什么情况吗？",
            ["ContentKR"] = "아까 비석에 다가갔을 때, 갑자기 머릿속에 어떤 목소리가 들려오더니 이 내용들을 알려 줬어. 이게 어떻게 된 일인지 알아?",
            ["DialogueId"] = 12010435,
            ["GUID"] = "1E111DFE",
            ["NextDialogue"] = 12010436,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111DFE",
            },
        [12010436] = {
            ["Content"] = "从来没有听说过这种事情……不对，等等！",
            ["ContentKR"] = "이런 일은 들어본 적이 없는데... 아니, 잠깐만!",
            ["DialogueId"] = 12010436,
            ["GUID"] = "1E111E28",
            ["NextDialogue"] = 12010437,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111E28",
            },
        [12010437] = {
            ["Content"] = "有过这样的传说，大风九章的奠基者，也是悬衡派的创始人<H>飏</>，在史书中留下了“天人相感，阴阳相和”的评价。",
            ["ContentKR"] = "대풍구장과 현형파의 창시자인 <H>양</>은 \"하늘과 인간이 서로 감응하면, 음과 양이 조화롭다\"라는 평가를 역사서에 남겼다고 했어.",
            ["DialogueId"] = 12010437,
            ["GUID"] = "1E111E52",
            ["NextDialogue"] = 12010438,
            ["RelatedWikiId"] = {
                [1] = 203003,
                },
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111E52",
            },
        [12010438] = {
            ["Content"] = "据说，她能够与上天，与世间万物相感应，挟飞仙以遨游！好像和你的情况有点相似。",
            ["ContentKR"] = "그분은 하늘과 교감하고, 세상 만물과 감응하며, 신선과 함께 천하를 노녔다던데, 이 경우랑 좀 비슷한 것 같아!",
            ["DialogueId"] = 12010438,
            ["GUID"] = "1E111E7C",
            ["NextDialogue"] = 12010439,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111E7C",
            },
        [12010439] = {
            ["Content"] = "正是这位先辈，最后带着很多德高望重的祖先一起，祭献了身躯，化为大风九章流转不息的根基。",
            ["ContentKR"] = "바로 그 선조께서 마지막에 덕망 높은 조상님들과 함께, 자기 몸을 제물로 바쳐, 끊임없이 순환하는 대풍구장의 근간이 되어 주셨거든.",
            ["DialogueId"] = 12010439,
            ["GUID"] = "1E111EA6",
            ["NextDialogue"] = 12010440,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111EA6",
            },
        [12010440] = {
            ["Content"] = "白突然有了一个想法！莫非，小仆从就是这位前辈的不知道第几十代曾曾曾曾孙？",
            ["ContentKR"] = "갑자기 뭔가 떠올랐어! 시종, 혹시 너 그 선조님의 몇 대 증증증증손 같은 거 아냐?",
            ["DialogueId"] = 12010440,
            ["GUID"] = "1E111ED0",
            ["NextOptions"] = {
                [1] = 120104401,
                [2] = 120104402,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111ED0",
            },
        [12010441] = {
            ["Content"] = "诶，是吗？但是{性别：他|她}看着也不像华胥人呢……",
            ["ContentKR"] = "어? 그래? 하지만 {性别:공자|소저}는 화서 사람으론 안 보이는데...",
            ["DialogueId"] = 12010441,
            ["GUID"] = "1E111EFA",
            ["NextDialogue"] = 12010443,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111EFA",
            },
        [12010442] = {
            ["Content"] = "总而言之，大风九章的内容就是以上这些啦。止流大当家交代我的任务完成了，接下来，我带你们去百年春吧！",
            ["ContentKR"] = "아무튼, 대풍구장의 내용은 이게 다야. 지류 대방님이 나한테 맡긴 임무는 완수했으니까, 이제 백년춘에 데려다줄게!",
            ["DialogueId"] = 12010442,
            ["GUID"] = "1E111F24",
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111F24",
            },
        [12010443] = {
            ["Content"] = "一段时间后……",
            ["ContentKR"] = "잠시 후...",
            ["DialogueId"] = 12010443,
            ["GUID"] = "1E111EFB",
            ["NextDialogue"] = 12010442,
            },
        [12010451] = {
            ["Content"] = "跟我来！诫碑在这个方向哦！",
            ["ContentKR"] = "따라와! 계율비는 이쪽 방향이야!",
            ["DialogueId"] = 12010451,
            ["Duration"] = 4,
            ["GUID"] = "1E111F26",
            ["NextDialogue"] = 12010452,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111F26",
            },
        [12010452] = {
            ["Content"] = "锦鲤皎皎，他们刚刚提到的烛什么阴之灾……是什么呀？",
            ["ContentKR"] = "행운아 루나, 방금 저 사람들이 말한 촉...룡의 재...앙인가 뭔가 하는 게 뭐야?",
            ["DialogueId"] = 12010452,
            ["Duration"] = 4,
            ["GUID"] = "1E111F27",
            ["NextDialogue"] = 12010453,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111F27",
            },
        [12010453] = {
            ["Content"] = "唔，简而言之，就是一个害得大家没法好好做生意的很坏很坏的灾害。",
            ["ContentKR"] = "아, 쉽게 말하면, 사람들이 제대로 장사를 못하게 방해하는 못된 재앙이야.",
            ["DialogueId"] = 12010453,
            ["Duration"] = 4,
            ["GUID"] = "1E111F28",
            ["NextDialogue"] = 12010454,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111F28",
            },
        [12010454] = {
            ["Content"] = "不过你们放心，止流大当家已经在着手解决了！只要大当家一出手，事情都会咻的一下好起来的！",
            ["ContentKR"] = "하지만 안심해, 지류 대방님이 벌써 해결 중이시니까! 대방님이 나선 이상, 상황은 금세 좋아질 거야!",
            ["DialogueId"] = 12010454,
            ["Duration"] = 4,
            ["GUID"] = "1E111F29",
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111F29",
            },
        [12010500] = {
            ["Content"] = "一直听你们说百年春，那里到底是什么样的地方哇？",
            ["ContentKR"] = "계속 백년춘 얘길 하던데, 거긴 대체 어떤 곳이야?",
            ["DialogueId"] = 12010500,
            ["Duration"] = 2,
            ["GUID"] = "1E1128A8",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 12010501,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E1128A8",
            },
        [12010501] = {
            ["Content"] = "那可是织星客在烟津渡的最大据点，囊括了来自五湖四海的商品，可气派啦。",
            ["ContentKR"] = "별을 잇는 자들이 연진 나루터에 세운 가장 큰 거점이야. 방방곡곡, 세계 여러 나라의 상품이 다 모이는 엄청난 곳이지.",
            ["DialogueId"] = 12010501,
            ["Duration"] = 2,
            ["GUID"] = "1E1128D2",
            ["NextDialogue"] = 12010502,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E1128D2",
            },
        [12010502] = {
            ["Content"] = "说起来，开旅游团好像也是一门不错的生意经……没错没错，赶紧记在小本本上。",
            ["ContentKR"] = "그러고 보니까, 여행단을 꾸리는 것도 괜찮은 사업 같네... 음, 맞아, 얼른 수첩에 적어 놔야겠어.",
            ["DialogueId"] = 12010502,
            ["Duration"] = 2,
            ["GUID"] = "1E1128FC",
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E1128FC",
            },
        [12010503] = {
            ["Content"] = "吼————",
            ["ContentKR"] = "크르르르릉!",
            ["DialogueId"] = 12010503,
            ["Duration"] = 2,
            ["GUID"] = "1E112926",
            ["NextDialogue"] = 12010504,
            ["SnapShot"] = "ECHO",
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112926",
            },
        [12010504] = {
            ["Content"] = "（刚刚那是……？）",
            ["ContentKR"] = "(방금 그건...?)",
            ["DialogueId"] = 12010504,
            ["Duration"] = 2,
            ["GUID"] = "1E112950",
            ["GuideFacialId"] = "Angry",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 12010505,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112950",
            },
        [12010505] = {
            ["Content"] = "糟糕——是玄色狴犴！",
            ["ContentKR"] = "이런... 검은 폐안이야!",
            ["DialogueId"] = 12010505,
            ["Duration"] = 2,
            ["GUID"] = "1E11297A",
            ["NextDialogue"] = 12010506,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E11297A",
            },
        [12010506] = {
            ["Content"] = "那是什么？！——诶，人呢？",
            ["ContentKR"] = "그게 뭔데?! 뭐야? 얘 어디 갔어?",
            ["DialogueId"] = 12010506,
            ["Duration"] = 4,
            ["GUID"] = "1E1129A4",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E1129A4",
            },
        [12010507] = {
            ["Content"] = "咤——走、赶紧走开 ——",
            ["ContentKR"] = "큭... 어, 어서 물러...",
            ["DialogueId"] = 12010507,
            ["Duration"] = 3,
            ["GUID"] = "1E1129CE",
            ["SpeakNpcId"] = 210033,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E1129CE",
            },
        [12010508] = {
            ["Camera"] = "-2086.416992,-1506.259277,1044.228516,0.000102,-15.798794,37.99028,28.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "上天庇佑，白龙神君庇佑！你们还好吗？",
            ["ContentKR"] = "하늘이시여, 백룡신군이시여! 다들 괜찮으세요?",
            ["DialogueId"] = 12010508,
            ["FinalCamera"] = "-2543.464355,680.419128,896.21582,0.000097,-15.59871,-11.41056,28.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1E1129F8",
            ["LookAt"] = {
                [1] = "210033:n(100001)",
                },
            ["NextDialogue"] = 12010509,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408011,
                [3] = 304003,
                [4] = 303008,
                [5] = 303009,
                },
            ["SpeakNpcId"] = 210033,
            ["SpeakNpcName"] = "UI_Npc_CMName_LuGuoXingShang",
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E1129F8",
            },
        [12010509] = {
            ["Content"] = "你还好吗？你的声音都在颤抖……明明自己也怕得要死，怎么还来凑热闹呀！",
            ["ContentKR"] = "너 괜찮아? 목소리까지 떨리네... 무서워 죽겠으면서, 왜 위험한 일에 끼어드는 거야!",
            ["DialogueId"] = 12010509,
            ["GUID"] = "1E112A22",
            ["NextDialogue"] = 12010510,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112A22",
            },
        [12010510] = {
            ["Camera"] = "-309.597839,264.643616,19.609375,0.000098,-13.798676,-30.610697,28.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我并无大碍，只是被那骇人的双目瞪上一眼，腿有点麻，缓缓就好了。但你们看起来是刚来此地的外乡人，不能将你们置之不理。",
            ["ContentKR"] = "전 괜찮아요. 저 무시무시한 두 눈을 보는 바람에 다리가 살짝 저린 것뿐이니까, 조금 쉬면 나아질 거예요. 두 분이 이곳에 처음 오신 외지인 같아 보여서, 모른 체 할 수 없었어요.",
            ["DialogueId"] = 12010510,
            ["GUID"] = "1E112A4C",
            ["NextOptions"] = {
                [1] = 120105101,
                [2] = 120105102,
                },
            ["SpeakNpcId"] = 210033,
            ["SpeakNpcName"] = "UI_Npc_CMName_LuGuoXingShang",
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112A4C",
            },
        [12010511] = {
            ["Content"] = "其实你再晚来两步，小仆从唰唰两下就能解决啦，{性别：他|她}很厉害的！",
            ["ContentKR"] = "사실 네가 조금만 늦게 왔어도, 내 시종이 샤샤샥하고 금방 해결했을 거야. 얘 엄청 세거든!",
            ["DialogueId"] = 12010511,
            ["GUID"] = "1E112A76",
            ["NextDialogue"] = 12010512,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112A76",
            },
        [12010512] = {
            ["Content"] = "这样吗，那太好了……",
            ["ContentKR"] = "그런가요? 그렇다면 다행이네요...",
            ["DialogueId"] = 12010512,
            ["GUID"] = "1E112AA0",
            ["NextDialogue"] = 12010513,
            ["SpeakNpcId"] = 210033,
            ["SpeakNpcName"] = "UI_Npc_CMName_LuGuoXingShang",
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112AA0",
            },
        [12010513] = {
            ["Content"] = "但是，刚刚那是怎么回事？白没认错吧，华胥的执法者怎么突然冒出来攻击我们？！",
            ["ContentKR"] = "그런데 방금 그건 어떻게 된 거야? 스노우가 잘못 본 게 아니라면, 법의 집행자가 왜 갑자기 나타나서 우릴 공격한 거지?!",
            ["DialogueId"] = 12010513,
            ["GUID"] = "1E112ACA",
            ["NextDialogue"] = 12010514,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112ACA",
            },
        [12010514] = {
            ["Content"] = "事先说明，白可没有做什么违法乱纪的坏事——虽然现在说这个好像也已经晚了……",
            ["ContentKR"] = "미리 말해 두겠는데, 스노우는 범법 행위나 나쁜 짓은 절대 안 했어. 물론, 이제 와서 이런 얘길 해 봐야 늦은 것 같지만...",
            ["DialogueId"] = 12010514,
            ["GUID"] = "1E112AF4",
            ["NextDialogue"] = 12010515,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112AF4",
            },
        [12010515] = {
            ["Content"] = "怎、怎么办，小仆从，我们是不是得赶紧潜逃？你的水性怎么样？",
            ["ContentKR"] = "어, 어떡하지? 시종, 우리 빨리 도망쳐야 하는 거 아냐? 너 수영 잘해?",
            ["DialogueId"] = 12010515,
            ["GUID"] = "1E112B1E",
            ["NextDialogue"] = 12010516,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112B1E",
            },
        [12010516] = {
            ["Content"] = "噗嗤……烟津渡周围的水域如此广阔，光靠游，一天一夜也游不出几里。",
            ["ContentKR"] = "푸흡... 연진 나루터 주변은 넓은 바다라서, 하루 종일 헤엄쳐도 멀리 못 가요.",
            ["DialogueId"] = 12010516,
            ["GUID"] = "1E112B48",
            ["NextDialogue"] = 12010517,
            ["SpeakNpcId"] = 210033,
            ["SpeakNpcName"] = "UI_Npc_CMName_LuGuoXingShang",
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112B48",
            },
        [12010517] = {
            ["Content"] = "你们不必惊慌。玄色狴犴与狴犴仅仅是外形近似，但它们并非华胥的执法者，而是<H>烛阴之灾</>影响下紊乱失序的产物。",
            ["ContentKR"] = "그렇게 놀라실 필요는 없어요. 검은 폐안은 폐안과 비슷하게 생겼지만, 법의 집행자가 아니라 <H>촉룡의 재앙</> 때문에 혼란에 빠진 존재들이니까요.",
            ["DialogueId"] = 12010517,
            ["GUID"] = "1E112B72",
            ["NextDialogue"] = 12010518,
            ["RelatedWikiId"] = {
                [1] = 303010,
                },
            ["SpeakNpcId"] = 210033,
            ["SpeakNpcName"] = "UI_Npc_CMName_LuGuoXingShang",
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112B72",
            },
        [12010518] = {
            ["Content"] = "这些玄色狴犴神志浑浊暴虐，不受大风九章的控制。攻击它们不会招致责罚。\
",
            ["ContentKR"] = "검은 폐안들은 의식이 혼탁하고 매우 포악해요. 대풍구장의 통제를 받지도 않고요. 그래서 검은 폐안을 공격해도 처벌받는 일은 없어요.",
            ["DialogueId"] = 12010518,
            ["GUID"] = "1E112B9C",
            ["NextDialogue"] = 12010519,
            ["SpeakNpcId"] = 210033,
            ["SpeakNpcName"] = "UI_Npc_CMName_LuGuoXingShang",
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112B9C",
            },
        [12010519] = {
            ["Content"] = "只是最近这玄色狴犴袭人事件，是愈来愈频发了。我刚刚续上的香，这就又用完了……",
            ["ContentKR"] = "다만, 요즘 들어 검은 폐안이 사람을 습격하는 일이 늘어나고 있어요. 향을 피운 지 얼마 되지도 않았는데, 벌써 다 써 버렸네요...",
            ["DialogueId"] = 12010519,
            ["GUID"] = "1E112BC6",
            ["NextDialogue"] = 12010520,
            ["SpeakNpcId"] = 210033,
            ["SpeakNpcName"] = "UI_Npc_CMName_LuGuoXingShang",
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112BC6",
            },
        [12010520] = {
            ["Content"] = "玉笙姐姐！",
            ["ContentKR"] = "옥생 언니!",
            ["DialogueId"] = 12010520,
            ["GUID"] = "1E112BF0",
            ["NextDialogue"] = 12010521,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112BF0",
            },
        [12010521] = {
            ["Content"] = "锦鲤皎皎，你怎在此处？",
            ["ContentKR"] = "네가 여긴 어쩐 일이야?",
            ["DialogueId"] = 12010521,
            ["GUID"] = "1E112C1A",
            ["NextDialogue"] = 12010522,
            ["SpeakNpcId"] = 210033,
            ["SpeakNpcName"] = "UI_Npc_CMName_LuGuoXingShang",
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112C1A",
            },
        [12010522] = {
            ["Content"] = "这两位是止流大当家从异国带来的贵客，我正在招待他们呢！只是途中发生了一些……咳咳、小变故。",
            ["ContentKR"] = "이 두 분은 지류 대방님이 다른 나라에서 모셔 온 귀한 손님인데, 내가 이것저것 소개해 드리고 있었어! 도중에... 크흠, 작은 소동이 있긴 했지만.",
            ["DialogueId"] = 12010522,
            ["GUID"] = "1E112C44",
            ["NextDialogue"] = 12010523,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112C44",
            },
        [12010523] = {
            ["Content"] = "玉笙姐姐，你要去百年春前续香吗？我们一起同行吧！",
            ["ContentKR"] = "옥생 언니, 백년춘 앞에 새로 향 피우러 가는 거야? 우리도 같이 갈게!",
            ["DialogueId"] = 12010523,
            ["GUID"] = "1E112C6E",
            ["NextDialogue"] = 12010524,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112C6E",
            },
        [12010524] = {
            ["Content"] = "<H>香</>？",
            ["ContentKR"] = "<H>향</>?",
            ["DialogueId"] = 12010524,
            ["GUID"] = "1E112C98",
            ["NextDialogue"] = 12010525,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112C98",
            },
        [12010525] = {
            ["Content"] = "说起来，刚刚战斗时，好像有一阵异香飘过，然后仿佛有某种力量，帮我抵挡了对面的攻击……这就是你们说的香吗？",
            ["ContentKR"] = "그러고 보니까, 아까 한창 싸울 때 갑자기 특이한 향기가 나더니, 어떤 힘이 검은 폐안의 공격을 막아 준 것 같았어요... 그게 방금 얘기한 향인가요?",
            ["DialogueId"] = 12010525,
            ["GUID"] = "1E112CC2",
            ["NextDialogue"] = 12010526,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112CC2",
            },
        [12010526] = {
            ["Content"] = "确是如此。",
            ["ContentKR"] = "맞아요.",
            ["DialogueId"] = 12010526,
            ["GUID"] = "1E112CEC",
            ["NextDialogue"] = 12010527,
            ["SpeakNpcId"] = 210033,
            ["SpeakNpcName"] = "UI_Npc_CMName_LuGuoXingShang",
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112CEC",
            },
        [12010527] = {
            ["Content"] = "哎呀，原来你们还不知道<H>香</>的妙用，是我这个东道主失职了！",
            ["ContentKR"] = "앗, 아직 <H>향</>의 신비한 쓰임새를 모르고 있었구나. 안내역을 맡은 내 실수야!",
            ["DialogueId"] = 12010527,
            ["GUID"] = "1E112D16",
            ["NextDialogue"] = 12010528,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112D16",
            },
        [12010528] = {
            ["Content"] = "在华胥，香可不仅仅是装饰。它维持着大风九章的运转，也能让我们得到上天的庇佑。",
            ["ContentKR"] = "화서에서 향은 단순한 장식품이 아니야. 대풍구장의 순환을 유지시켜 주고, 우리가 하늘의 가호를 받을 수 있게 해 주거든.",
            ["DialogueId"] = 12010528,
            ["GUID"] = "1E112D40",
            ["NextDialogue"] = 12010529,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112D40",
            },
        [12010529] = {
            ["Content"] = "刚刚，我见你们受袭心急，便将身上佩戴的香囊扔了出去，希望能对你们有所裨益。",
            ["ContentKR"] = "조금 전에 여러분이 공격받는 걸 보고 제가 마음이 급해져서, 몸에 지니고 있던 향주머니를 던진 것도, 조금이나마 도움이 되길 바라서였어요.",
            ["DialogueId"] = 12010529,
            ["GUID"] = "1E112D6A",
            ["NextDialogue"] = 12010530,
            ["SpeakNpcId"] = 210033,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112D6A",
            },
        [12010530] = {
            ["Content"] = "它虽然无法杀伤玄色狴犴，但足以帮我们抵挡一阵子。只是，香的作用发挥之后，必须到白龙祠堂去重新获取赐福。",
            ["ContentKR"] = "향주머니만으론 검은 폐안을 해치울 수 없지만, 잠깐은 막아 줄 수 있거든요. 단지, 향은 한 번 효능을 발휘하고 나면, 반드시 백룡 사당에 가서 다시 축복을 받아야 해요.",
            ["DialogueId"] = 12010530,
            ["GUID"] = "1E112D94",
            ["NextDialogue"] = 12010531,
            ["RelatedWikiId"] = {
                [1] = 403005,
                },
            ["SpeakNpcId"] = 210033,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112D94",
            },
        [12010531] = {
            ["Content"] = "懂了懂了——也就是去白龙祠堂祈福，我们就不用那么害怕坏狴犴了，对吧！",
            ["ContentKR"] = "좋아, 이해했어. 그러니까 백룡 사당에 가서 기도를 드리면, 그 무시무시한 나쁜 폐안을 그렇게까지 무서워할 필요가 없다는 거네, 맞지?",
            ["DialogueId"] = 12010531,
            ["GUID"] = "1E112DBE",
            ["NextDialogue"] = 12010532,
            ["RelatedWikiId"] = {
                [1] = 405011,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112DBE",
            },
        [12010532] = {
            ["Content"] = "当然，白龙祠堂前的香火可旺盛啦。走吧，带你们一起去见识见识！",
            ["ContentKR"] = "그럼. 백룡 사당 앞은 향을 올리려는 사람들로 문전성시야. 가자. 구경시켜 줄게!",
            ["DialogueId"] = 12010532,
            ["GUID"] = "1E112DE8",
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112DE8",
            },
        [12010533] = {
            ["Content"] = "喂喂，刚刚打起来之后，你怎么一溜烟地就跑不见了。",
            ["ContentKR"] = "야, 너 아까 싸움이 시작되자마자 쏜살같이 도망치더라?",
            ["DialogueId"] = 12010533,
            ["GUID"] = "1E112E12",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 12010534,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112E12",
            },
        [12010534] = {
            ["Content"] = "毕竟我手无缚鸡之力……帮不上什么忙嘛。但是我有在一旁为你们摇旗呐喊哦！",
            ["ContentKR"] = "난 싸울 능력이 안 돼서... 도움이 안 되잖아. 그래도 옆에서 열심히 응원은 했어!",
            ["DialogueId"] = 12010534,
            ["GUID"] = "1E112E3C",
            ["NextDialogue"] = 12010535,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112E3C",
            },
        [12010535] = {
            ["Content"] = "这样说起来，第一次遇到白的时候，好像也发生过类似的事情呢。",
            ["ContentKR"] = "그러고 보니까, 스노우를 처음 만났을 때도 비슷한 일이 있었던 것 같은데.",
            ["DialogueId"] = 12010535,
            ["GUID"] = "1E112E66",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 12010536,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112E66",
            },
        [12010536] = {
            ["Content"] = "噗嗤，原来白魔王大人也这么不拘小节。",
            ["ContentKR"] = "풉, 알고 보니까 스노우 마왕님도 굉장히 소탈한 성격이었구나.",
            ["DialogueId"] = 12010536,
            ["GUID"] = "1E112E90",
            ["NextDialogue"] = 12010537,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112E90",
            },
        [12010537] = {
            ["Content"] = "小、小仆从，你不要搞错了，那明明是在考验你的实力……",
            ["ContentKR"] = "시, 시종, 착각하지 마. 그땐 네 실력을 시험해 본 거라고...",
            ["DialogueId"] = 12010537,
            ["GUID"] = "1E112EBA",
            ["GuideFacialId"] = "Angry",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112EBA",
            },
        [12010601] = {
            ["Camera"] = "362.59375,523.266724,128.501953,0.000092,0.196914,-127.178719,35.000011,100000.0,false,Manual,2.8",
            ["Content"] = "前面就是啦，位于巨木之根，烟津渡区域规模最大的商会——百年春！",
            ["ContentKR"] = "이 앞이 바로 거목의 뿌리에 자리한 연진 나루터 일대 최대 규모의 상회, 백년춘이야!",
            ["DialogueId"] = 12010601,
            ["Duration"] = 4,
            ["GUID"] = "1E11393A",
            ["NextDialogue"] = 12010602,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408011,
                [3] = 304003,
                [4] = 303008,
                },
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120106/1E11393A",
            },
        [12010602] = {
            ["Content"] = "愿此香华云，直达太皓处，恳求大慈悲，施与众生乐。",
            ["ContentKR"] = "이 향기로운 꽃구름이 태호께 이르기를 바라나이다. 부디 자비로운 마음으로, 모든 중생에게 즐거움을 베푸시옵소서.",
            ["DialogueId"] = 12010602,
            ["GUID"] = "1E113964",
            ["NextDialogue"] = 12010603,
            ["SpeakNpcName"] = "UI_CMName_Name_DevoutPilgrims",
            ["VoiceName"] = "voice/$Locale$/story/1201/120106/1E113964",
            },
        [12010603] = {
            ["Content"] = "这么多人在祈愿……白龙神君回应得过来吗？",
            ["ContentKR"] = "이렇게 많은 사람들의 소원을... 백룡신군께서 다 들어주실 수 있을까?",
            ["DialogueId"] = 12010603,
            ["GUID"] = "1E11398E",
            ["NextDialogue"] = 12010604,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120106/1E11398E",
            },
        [12010604] = {
            ["Content"] = "呵呵，<H>奉香</>可不能视为众人向白龙神君进行索取的仪式。",
            ["ContentKR"] = "후후, <H>봉향</>을 백룡신군께 뭔가를 달라고 요구하는 의식이라고 여기면 안 돼요.",
            ["DialogueId"] = 12010604,
            ["GUID"] = "1E1139B8",
            ["NextDialogue"] = 12010605,
            ["SpeakNpcId"] = 210033,
            ["VoiceName"] = "voice/$Locale$/story/1201/120106/1E1139B8",
            },
        [12010605] = {
            ["Content"] = "先前说过，大风九章需要以“香”为介质去维持运转。",
            ["ContentKR"] = "전에도 말한 적이 있지만, 대풍구장은 '향'을 매개로 그 순환을 유지해요.",
            ["DialogueId"] = 12010605,
            ["GUID"] = "1E1139E2",
            ["NextDialogue"] = 12010606,
            ["RelatedWikiId"] = {
                [1] = 403005,
                },
            ["SpeakNpcId"] = 210033,
            ["VoiceName"] = "voice/$Locale$/story/1201/120106/1E1139E2",
            },
        [12010606] = {
            ["Content"] = "人们向上天奉香维持着大风九章，大风九章的意志则化形为白龙神君。人们尊奉神君的意志，祂又通过香庇佑人们。",
            ["ContentKR"] = "사람들이 하늘에 향을 올려 대풍구장을 유지하면, 대풍구장의 의지는 백룡신군으로 변하게 되죠. 사람들은 백룡신군의 의지를 받들고, 신은 향을 통해 사람들을 굽어살피고요.",
            ["DialogueId"] = 12010606,
            ["GUID"] = "1E113A0C",
            ["NextDialogue"] = 12010607,
            ["SpeakNpcId"] = 210033,
            ["VoiceName"] = "voice/$Locale$/story/1201/120106/1E113A0C",
            },
        [12010607] = {
            ["Content"] = "愿望要靠勤耕不辍去一步步实现，白龙神君只是见证这一过程，千年皆是如此。",
            ["ContentKR"] = "소원은 부지런히 노력해서 차근차근 이뤄 나가는 거예요. 오랫동안 늘 그래 왔듯이, 백룡신군께선 그 과정을 지켜보실 뿐이고요.",
            ["DialogueId"] = 12010607,
            ["GUID"] = "1E113A36",
            ["NextDialogue"] = 12010608,
            ["SpeakNpcId"] = 210033,
            ["VoiceName"] = "voice/$Locale$/story/1201/120106/1E113A36",
            },
        [12010608] = {
            ["Content"] = "不过，偶尔也会出现几位福星，能够得到白龙神君的青睐，获得意想不到的好处呢。",
            ["ContentKR"] = "하지만 가끔은 백룡신군의 총애를 받는 귀인이 나타나, 예상치 못한 행운을 얻기도 한답니다.",
            ["DialogueId"] = 12010608,
            ["GUID"] = "1E113A60",
            ["NextDialogue"] = 12010609,
            ["SpeakNpcId"] = 210033,
            ["VoiceName"] = "voice/$Locale$/story/1201/120106/1E113A60",
            },
        [12010609] = {
            ["Content"] = "哎？白有点好奇。来都来了，白也想体验一下！",
            ["ContentKR"] = "어? 살짝 호기심이 생기는걸. 이왕 온 거, 스노우도 한번 해 보고 싶어!",
            ["DialogueId"] = 12010609,
            ["GUID"] = "1E113A8A",
            ["NextDialogue"] = 12010610,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120106/1E113A8A",
            },
        [12010610] = {
            ["Content"] = "那，你去找香案边上的那位！他是<H>悬衡派</>的香官，负责主持祠堂的秩序。",
            ["ContentKR"] = "그럼, 향로 옆에 있는 저 사람한테 가 봐! 저 사람은 <H>현형파</>의 향관인데, 이 사당의 질서를 관리하고 있어.",
            ["DialogueId"] = 12010610,
            ["GUID"] = "1E113AB4",
            ["NextDialogue"] = 12010611,
            ["RelatedWikiId"] = {
                [1] = 407006,
                },
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120106/1E113AB4",
            },
        [12010611] = {
            ["Content"] = "悬衡派……你好像说过，是那位“天人相感”的大风九章奠基者开创的门派？",
            ["ContentKR"] = "현형파라면... 아까 \"하늘과 인간이 서로 감응한다\"고 했다던 대풍구장의 창시자가 만든 문파 말이야?",
            ["DialogueId"] = 12010611,
            ["GUID"] = "1E113ADE",
            ["NextDialogue"] = 12010612,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120106/1E113ADE",
            },
        [12010612] = {
            ["Content"] = "没错！看来{nickname}有认真听课，我很欣慰哦。",
            ["ContentKR"] = "맞아! 수업을 열심히 들었구나, {nickname}. 아주 뿌듯해.",
            ["DialogueId"] = 12010612,
            ["GUID"] = "1E113B08",
            ["NextDialogue"] = 12010613,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120106/1E113B08",
            },
        [12010613] = {
            ["Content"] = "在上古时期，悬衡派最先发现了香的神奇功效，并作为独门秘方一直传承了下来。",
            ["ContentKR"] = "아주 오래전에 현형파는 향의 신비로운 효능을 가장 먼저 발견해서, 자신들만의 비법으로 만들어 전수하고 쭉 계승해 왔어.",
            ["DialogueId"] = 12010613,
            ["GUID"] = "1E113B32",
            ["NextDialogue"] = 12010614,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120106/1E113B32",
            },
        [12010614] = {
            ["Content"] = "直至今日，悬衡派也一直负责着华胥境内的奉香事宜。一路上看到的香炉都是他们的手笔。",
            ["ContentKR"] = "지금도 현형파는 화서에서 봉향을 담당하고 있어. 오면서 본 향로들도 전부 다 현형파 사람들이 만든 거야.",
            ["DialogueId"] = 12010614,
            ["GUID"] = "1E113B5C",
            ["NextDialogue"] = 12010615,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120106/1E113B5C",
            },
        [12010615] = {
            ["Content"] = "每人每天能找悬衡派的官员无偿领取三支香。你们也去试试看吧！",
            ["ContentKR"] = "누구나 하루에 3번씩 현형파 관료한테서 무료로 향을 3개 받을 수 있어. 두 사람도 한번 해 봐!",
            ["DialogueId"] = 12010615,
            ["GUID"] = "1E113B86",
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120106/1E113B86",
            },
        [12010616] = {
            ["Content"] = "愿你善根常驻。",
            ["ContentKR"] = "늘 선한 마음을 가지시길.",
            ["DialogueId"] = 12010616,
            ["GUID"] = "1E113BB0",
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{210034},AnimationId{\"Pray_Start\"},Duration{1.83}},\
PlayAnimation{ActorId{210034},AnimationId{\"Pray_Loop\"},Duration{1}},\
PlayAnimation{ActorId{210034},AnimationId{\"Pray_End\"},Duration{1.87}}\
}",
            ["SpeakNpcId"] = 210034,
            ["VoiceName"] = "voice/$Locale$/story/1201/120106/1E113BB0",
            },
        [12010617] = {
            ["Content"] = "来，最后一段路啦！",
            ["ContentKR"] = "자, 여기만 지나면 도착이야!",
            ["DialogueId"] = 12010617,
            ["Duration"] = 2,
            ["GUID"] = "1E113BDA",
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120106/1E113BDA",
            },
        [12010701] = {
            ["Camera"] = "520.380859,617.213379,-28.979492,0.000073,13.797665,-129.582932,35.000008,100000.0,false,Manual,2.8",
            ["Content"] = "前面就是百年春的办事处！止流大当家现在估计就在上面等着你们呢。我就带路到这里了，你们自己上去吧。",
            ["ContentKR"] = "저기가 바로 백년춘 사무실이야! 지금쯤이면 지류 대방님이 위에서 두 사람을 기다리고 있을 거야. 난 여기까지만 안내할 테니까, 얼른 올라가 봐.",
            ["DialogueId"] = 12010701,
            ["GUID"] = "1E1149A2",
            ["NextDialogue"] = 12010702,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408011,
                [3] = 304003,
                [4] = 406004,
                },
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120107/1E1149A2",
            },
        [12010702] = {
            ["Camera"] = "325.501953,283.450684,112.541016,0.000078,0.797322,-149.78244,35.000008,100000.0,false,Manual,2.8",
            ["Content"] = "我的铺位在这里，有空要来找我玩哦。如果想买什么，给你们打九九九八折！",
            ["ContentKR"] = "내 가게는 저기 있으니까, 시간 날 때 놀러 와. 사고 싶은 게 있다면 원래 가격의 0.002퍼센트 할인해서 받을게!",
            ["DialogueId"] = 12010702,
            ["GUID"] = "1E1149CC",
            ["NextDialogue"] = 12010703,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120107/1E1149CC",
            },
        [12010703] = {
            ["Content"] = "等等——多少？我没听错吧？怎么这么小气！",
            ["ContentKR"] = "잠깐, 얼마라고? 내가 잘못 들은 거 아니지? 진짜 쪼잔하네!",
            ["DialogueId"] = 12010703,
            ["GUID"] = "1E1149F6",
            ["NextDialogue"] = 12010704,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120107/1E1149F6",
            },
        [12010704] = {
            ["Content"] = "毕竟约定过了，要成为华胥第一的织星客嘛！",
            ["ContentKR"] = "어쩔 수 없어, 화서 최고의 별을 잇는 자가 되기로 약속했는걸!",
            ["DialogueId"] = 12010704,
            ["GUID"] = "1E114A20",
            ["NextDialogue"] = 12010705,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120107/1E114A20",
            },
        [12010705] = {
            ["Content"] = "锦鲤皎皎没有角，已经输在起跑线上了。如果不加倍地投机取巧，锱铢必较，勤能补拙，是达不到这个目标的！",
            ["ContentKR"] = "난 뿔이 없어서 출발선부터 뒤처졌잖아. 남들보다 2배로 얍삽하고, 쪼잔하고, 부지런히 노력해서 단점을 보완하지 않으면 내 목표를 달성할 수 없다고.",
            ["DialogueId"] = 12010705,
            ["GUID"] = "1E114A4A",
            ["NextDialogue"] = 12010706,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120107/1E114A4A",
            },
        [12010706] = {
            ["Content"] = "原、原来是这样吗……",
            ["ContentKR"] = "그, 그랬구나...",
            ["DialogueId"] = 12010706,
            ["GUID"] = "1E114A74",
            ["NextDialogue"] = 12010707,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120107/1E114A74",
            },
        [12010707] = {
            ["Content"] = "让你到处带坏别的皎皎，这下知道错了吧。",
            ["ContentKR"] = "여기저기 다니면서 루나들 다 물들이고 다니더니, 이제 뭘 잘못했는지 알겠지?",
            ["DialogueId"] = 12010707,
            ["GUID"] = "1E114A9E",
            ["NextDialogue"] = 12010708,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120107/1E114A9E",
            },
        [12010708] = {
            ["Content"] = "咳咳……小仆从，我们赶紧走吧，别让金主大人久等了！",
            ["ContentKR"] = "크흠... 시종, 우리 빨리 가자. 물주를 기다리게 하면 안 돼!",
            ["DialogueId"] = 12010708,
            ["GUID"] = "1E114AC8",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120107/1E114AC8",
            },
        [12010709] = {
            ["Camera"] = "-10.451172,-172.71875,172.462891,0.000043,-13.01181,100.396614,24.0,100000.0,false,Manual,22.0",
            ["Content"] = "……适才情绪激动，如今冷静下来仔细想想，确是我做得不妥了。",
            ["ContentKR"] = "...조금 전에는 감정이 격해져서 그랬습니다만, 차분히 생각해 보니 제 잘못이 맞습니다.",
            ["DialogueId"] = 12010709,
            ["FacialId"] = {
                [1] = "210006:CM_Sad01",
                },
            ["GUID"] = "1E114AF2",
            ["LookAt"] = {
                [1] = "210005:n(210006)",
                [2] = "210033:n(210006)",
                },
            ["NextDialogue"] = 12010710,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408011,
                [3] = 304003,
                [4] = 406004,
                },
            ["SpeakNpcId"] = 210005,
            ["TalkActionId"] = {
                [1] = "210006:Sigh_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120107/1E114AF2",
            },
        [12010710] = {
            ["Content"] = "实在是我病急乱投医，昏了头才会从外面雇来个底细不清的人，还想凭一己之力闯一闯，将货物运到对面去。",
            ["ContentKR"] = "마음이 조급한 나머지 제가 경솔했습니다. 신분도 확실하지 않은 외부 사람을 고용하고, 혼자 힘으로 화물을 건너편까지 운송하려 하다니, 제가 정신이 나갔었나 봅니다.",
            ["DialogueId"] = 12010710,
            ["GUID"] = "1E114B1C",
            ["NextDialogue"] = 12010711,
            ["SpeakNpcId"] = 210005,
            ["VoiceName"] = "voice/$Locale$/story/1201/120107/1E114B1C",
            },
        [12010711] = {
            ["Camera"] = "-23.115234,32.113281,166.745117,0.000075,-7.412141,88.993202,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "结果那武人是个花架子，非但应付不来玄色狴犴，还是个心术不正、鸡鸣狗盗之徒，平白惹出这么多事端。我在这里给乡亲父老们赔礼了！",
            ["ContentKR"] = "그런데 그 무인이라는 자가 겉만 번지르르했지, 검은 폐안과 맞설 수 있기는커녕, 음흉한 속셈을 지녀 공연히 이런 소동을 일으켰습니다. 이 자리를 빌려 모든 분께 사죄드립니다!",
            ["DialogueId"] = 12010711,
            ["GUID"] = "1E114B46",
            ["LookAt"] = {
                [1] = "210006:n(210005)",
                },
            ["NextDialogue"] = 12010712,
            ["SpeakNpcId"] = 210005,
            ["TalkActionId"] = {
                [1] = "210006:Sigh_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120107/1E114B46",
            },
        [12010712] = {
            ["Camera"] = "142.71875,232.458008,189.438477,0.000114,-18.212145,-157.608566,24.0,100000.0,false,Manual,22.0",
            ["Content"] = "您也不必如此自责。大家这些天心急如焚，百年春都看在眼里。",
            ["ContentKR"] = "자책하지 마십시오. 여러분의 절박한 마음은 백년춘에서도 잘 알고 있습니다.",
            ["DialogueId"] = 12010712,
            ["GUID"] = "1E114B70",
            ["LookAt"] = {
                [1] = "210005:n(210033)",
                [2] = "210006:n(210033)",
                },
            ["NextDialogue"] = 12010713,
            ["SpeakNpcId"] = 210022,
            ["TalkActionId"] = {
                [1] = "210033:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120107/1E114B70",
            },
        [12010713] = {
            ["Content"] = "目前我们也在积极寻找对策，早日化解当下的危机，让大家的生意可以重回正轨。",
            ["ContentKR"] = "저희도 적극적으로 대책을 강구하여, 하루빨리 위기를 해결하고, 여러분의 생업이 정상화될 수 있도록 노력하겠습니다.",
            ["DialogueId"] = 12010713,
            ["GUID"] = "1E114B9A",
            ["NextDialogue"] = 12010714,
            ["SpeakNpcId"] = 210022,
            ["TalkActionId"] = {
                [1] = "210033:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120107/1E114B9A",
            },
        [12010714] = {
            ["Camera"] = "-47.478516,-40.796875,121.547852,0.000145,2.387158,110.985695,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "只是，这禁行令还要延续多久呢？我们织星客等得起，货可等不起啊……",
            ["ContentKR"] = "그나저나, 이 통행금지령은 대체 언제까지 계속되는 겁니까? 저희 별을 잇는 자들은 그렇다곤 치더라도, 물건은 기다려 주지 않잖습니까...",
            ["DialogueId"] = 12010714,
            ["FacialId"] = {
                [1] = "210005:Unacceptable01",
                },
            ["GUID"] = "1E114BC4",
            ["LookAt"] = {
                [1] = "210006:n(210005)",
                [2] = "210033:n(210005)",
                },
            ["NextDialogue"] = 12010715,
            ["RelatedWikiId"] = {
                [1] = 407007,
                },
            ["SpeakNpcId"] = 210006,
            ["TalkActionId"] = {
                [1] = "210005:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120107/1E114BC4",
            },
        [12010715] = {
            ["Content"] = "这个时节的药草，要趁刚摘下来，还沾着露水的新鲜劲，才能卖出个好价钱。放在篮子里，那是日日都在贬值啊。",
            ["ContentKR"] = "이 시기의 약초는 갓 채취해 이슬이 채 마르지 않은 신선한 상태여야 제값을 받을 수 있습니다. 광주리에 담아두면, 하루가 다르게 값어치가 떨어지게 됩니다.",
            ["DialogueId"] = 12010715,
            ["FacialId"] = {
                [1] = "210005:CM_Idle",
                },
            ["GUID"] = "1E114BEE",
            ["NextDialogue"] = 12010716,
            ["SpeakNpcId"] = 210006,
            ["VoiceName"] = "voice/$Locale$/story/1201/120107/1E114BEE",
            },
        [12010716] = {
            ["Camera"] = "-53.175781,137.40918,147.086914,0.000151,-8.01328,-123.215157,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "这……烛阴之灾肆虐。它何时能偃旗息鼓，恐怕没人能给出承诺。",
            ["ContentKR"] = "그건... 촉룡의 재앙이 워낙 거세서, 언제쯤 잠잠해질지 아무도 장담할 수 없는 상황입니다.",
            ["DialogueId"] = 12010716,
            ["FacialId"] = {
                [1] = "210033:CM_Sad01",
                },
            ["GUID"] = "1E114C18",
            ["NextDialogue"] = 12010717,
            ["SpeakNpcId"] = 210022,
            ["TalkActionId"] = {
                [1] = "210005:Angry01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120107/1E114C18",
            },
        [12010717] = {
            ["Camera"] = "257.292969,-47.435547,8.095703,0.000389,-3.810276,90.187614,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "——放心，最多三日，必有解法。",
            ["ContentKR"] = "안심하세요. 사흘 안에, 반드시 해결책을 찾아내겠습니다.",
            ["DialogueId"] = 12010717,
            ["FacialId"] = {
                [1] = "210033:CM_Idle",
                [2] = "210005:CM_Idle",
                [3] = "210006:CM_Idle",
                },
            ["FinalCamera"] = "257.292969,-47.435547,8.095703,0.000394,-5.410247,120.785744,35.0,100000.0,false,Manual,22.0",
            ["GUID"] = "1E114C42",
            ["LookAt"] = {
                [1] = "210005:n(210004)",
                [2] = "210033:n(210004)",
                [3] = "210006:n(210004)",
                [4] = "210004:n(210005)",
                },
            ["NextDialogue"] = 12010718,
            ["Scripts"] = "PARA{\
MoveTo{ActorId{210004},MoveSpeed{90},TargetPoint{\"zhiliu_walkin_14\"}},\
SetRotation{SetRotationDescription{\"210005:n(210004)\"}},\
