            },
        [12011801] = {
            ["Content"] = "怎么……是你们？此处危险——",
            ["ContentKR"] = "너희가... 어떻게 이곳에? 이곳은 위험하니——",
            ["DialogueId"] = 12011801,
            ["Duration"] = 3,
            ["GUID"] = "1E11FE1A",
            ["VoiceName"] = "voice/$Locale$/story/1201/120118/1E11FE1A",
            },
        [12011802] = {
            ["Content"] = "我来帮你！",
            ["ContentKR"] = "도와줄게!",
            ["DialogueId"] = 12011802,
            ["Duration"] = 2,
            ["GUID"] = "1E11FE44",
            ["VoiceName"] = "voice/$Locale$/story/1201/120118/1E11FE44",
            },
        [12011901] = {
            ["Content"] = "你们是化外无关人士，不应卷入这场恶战。这里由我一人应对就好。",
            ["ContentKR"] = "관계없는 외부인을 이런 험한 싸움에 휘말리게 만들 수는 없어. 이곳은 나 혼자 감당해도 충분해.",
            ["DialogueId"] = 12011901,
            ["Duration"] = 3,
            ["GUID"] = "1E120E82",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 12011902,
            ["SpeakNpcId"] = 210007,
            ["SpeakNpcName"] = "UI_Npc_Name_Yingtianwei",
            ["VoiceName"] = "voice/$Locale$/story/1201/120119/1E120E82",
            },
        [12011902] = {
            ["Content"] = "敌人面前不能闲聊，你说过的。",
            ["ContentKR"] = "적 앞에선 한가하게 잡담하는 거 아니야. 아까 본인 입으로 그렇게 말했잖아.",
            ["DialogueId"] = 12011902,
            ["Duration"] = 2,
            ["GUID"] = "1E120EAC",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 12011903,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120119/1E120EAC",
            },
        [12011903] = {
            ["Content"] = "就是就是。都负伤了还嘴硬，你就乖乖接受我们的帮助吧！",
            ["ContentKR"] = "맞아, 맞아. 다쳤는데도 고집을 부리다니. 그냥 얌전히 우리 도움이나 받으라고!",
            ["DialogueId"] = 12011903,
            ["Duration"] = 3,
            ["GUID"] = "1E120ED6",
            ["GuideFacialId"] = "Angry",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 12011904,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120119/1E120ED6",
            },
        [12011904] = {
            ["Content"] = "……我明白了。",
            ["ContentKR"] = "...알았어.",
            ["DialogueId"] = 12011904,
            ["Duration"] = 2,
            ["GUID"] = "1E120F00",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 210007,
            ["SpeakNpcName"] = "UI_Npc_Name_Yingtianwei",
            ["VoiceName"] = "voice/$Locale$/story/1201/120119/1E120F00",
            },
        [12012001] = {
            ["Camera"] = "428.589844,98.277344,126.54541,0.0,0.0,-179.794739,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这些孽畜，总算是尽数清缴了。多谢两位施以援手。",
            ["ContentKR"] = "드디어 이 망할 짐승들을 전부 처치했군. 두 사람이 도와준 덕분이야.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012001,
            ["GUID"] = "1E121EEA",
            ["NextDialogue"] = 12012002,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 304003,
                },
            ["SpeakNpcId"] = 210007,
            ["SpeakNpcName"] = "UI_Npc_Name_Yingtianwei",
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E121EEA",
            },
        [12012002] = {
            ["Content"] = "抱歉，先前失了礼数，尚未互通姓名。在下煜明，请问你们是？",
            ["ContentKR"] = "미안, 아까는 경황이 없어 통성명도 못 했군. 나는 욱명이라고 해. 두 사람은...?",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012002,
            ["GUID"] = "1E121F14",
            ["NextDialogue"] = 12012003,
            ["RelatedWikiId"] = {
                [1] = 203004,
                },
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E121F14",
            },
        [12012003] = {
            ["Content"] = "我是外乡来的狩月人{nickname}。这位是……",
            ["ContentKR"] = "나는 외지에서 온 월석 사냥꾼, {nickname}, 이쪽은...",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012003,
            ["GUID"] = "1E121F3E",
            ["NextOptions"] = {
                [1] = 120120031,
                [2] = 120120032,
                },
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E121F3E",
            },
        [12012005] = {
            ["Content"] = "哼哼，没错！纯白的救赎☆光之魔王大人正是我！",
            ["ContentKR"] = "흥흥, 맞아! 내가 바로 순백의 구원자☆빛의 마왕님이야!",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012005,
            ["GUID"] = "1E121F92",
            ["NextDialogue"] = 12012009,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E121F92",
            },
        [12012007] = {
            ["Content"] = "异国文化，果真高深莫测……",
            ["ContentKR"] = "이국의 문화는 참으로 심오하군...",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012007,
            ["GUID"] = "1E121FE6",
            ["NextDialogue"] = 12012008,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E121FE6",
            },
        [12012008] = {
            ["Content"] = "从、从别人的嘴里说出来，怎么有一种莫名的羞耻感……叫我白就好了！",
            ["ContentKR"] = "나, 남의 입으로 들으니까 왠지 수치심이... 그냥 스노우라고 부르면 돼!",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012008,
            ["GUID"] = "1E122010",
            ["NextDialogue"] = 12012009,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E122010",
            },
        [12012009] = {
            ["Content"] = "刚刚还在说“无暇闲聊”，怎么这会儿就有空啦？",
            ["ContentKR"] = "아까는 \"한가히 이야기를 나눌 겨를이 없다\"더니, 지금은 괜찮은가 봐?",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012009,
            ["GUID"] = "1E12203A",
            ["NextDialogue"] = 12012010,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E12203A",
            },
        [12012010] = {
            ["Content"] = "先前我灭敌心切，待人接物有所轻慢，想来惭愧，还望阁下海涵。",
            ["ContentKR"] = "조금 전에는 적을 해치워야 한다는 마음이 급해 두 사람에게 실례를 범했어. 부끄럽군, 무례를 용서해 줘.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012010,
            ["GUID"] = "1E122064",
            ["NextDialogue"] = 12012011,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E122064",
            },
        [12012011] = {
            ["Content"] = "好吧。白就大人有大量，原谅你啦！",
            ["ContentKR"] = "좋아. 이 스노우님이 통 크게 용서해 줄게!",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012011,
            ["GUID"] = "1E12208E",
            ["NextDialogue"] = 12012012,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E12208E",
            },
        [12012012] = {
            ["Content"] = "你还好吗？",
            ["ContentKR"] = "괜찮아?",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012012,
            ["GUID"] = "1E1220B8",
            ["NextDialogue"] = 12012013,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E1220B8",
            },
        [12012013] = {
            ["Content"] = "……无妨。只是刚才应对的狴犴众多，难免左支右绌，受了些皮外伤。",
            ["ContentKR"] = "...괜찮아. 조금 전에 너무 많은 폐안을 상대하느라 힘에 부쳐, 가벼운 상처를 입었을 뿐이야.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012013,
            ["GUID"] = "1E1220E2",
            ["NextDialogue"] = 12012014,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E1220E2",
            },
        [12012014] = {
            ["Content"] = "这看起来可不只是一点点皮外伤啊喂！",
            ["ContentKR"] = "이게 어딜 봐서 가벼운 상처란 거야!",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012014,
            ["GUID"] = "1E12210C",
            ["NextDialogue"] = 12012015,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E12210C",
            },
        [12012015] = {
            ["Content"] = "给你。这是我为了应对突发情况，从冰湖城带上的绷带和治疗药水。",
            ["ContentKR"] = "받아. 혹시 몰라서 아이스레이크 시티에서 가져온 붕대랑 치료약이야.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012015,
            ["GUID"] = "1E122136",
            ["NextDialogue"] = 12012016,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E122136",
            },
        [12012016] = {
            ["Content"] = "多谢好意，给两位添忧了……这些伤势只需静坐休息，一晌之后就能痊愈。",
            ["ContentKR"] = "고마워. 두 사람에게 걱정을 끼쳐 버렸군... 이 정도 상처는 가만히 앉아 쉬면, 금방 나을 거야.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012016,
            ["GUID"] = "1E122160",
            ["NextDialogue"] = 12012017,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E122160",
            },
        [12012017] = {
            ["Content"] = "你确定吗？看起来已经伤到了筋骨，要不去找个医生看看？",
            ["ContentKR"] = "확실해? 상처가 깊어 보이는데, 의사한테 가 보는 게 좋지 않을까?",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012017,
            ["GUID"] = "1E12218A",
            ["NextDialogue"] = 12012018,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E12218A",
            },
        [12012018] = {
            ["Content"] = "应天尉既与大风九章立了契，力量来源自与常人不同。",
            ["ContentKR"] = "응천위는 대풍구장과 계약을 맺고 있어서, 평범한 이들과는 힘의 근원이 달라.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012018,
            ["GUID"] = "1E1221B4",
            ["NextDialogue"] = 12012019,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E1221B4",
            },
        [12012019] = {
            ["Content"] = "只要脊骨未损，再重的伤势，也能通过汲取大风九章传来的能量而缓慢修复，不过是多忍受些痛楚煎熬罢了。",
            ["ContentKR"] = "척추만 무사하다면, 아무리 깊은 상처라도 대풍구장에서 흘러드는 힘을 흡수해서 서서히 회복할 수 있어. 하지만 고통은 감내해야 하지.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012019,
            ["GUID"] = "1E1221DE",
            ["NextDialogue"] = 12012020,
            ["RelatedWikiId"] = {
                [1] = 405010,
                },
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E1221DE",
            },
        [12012020] = {
            ["Content"] = "听起来很厉害的样子……这不就是小说里的“不败金身”嘛！白都有点心动了！",
            ["ContentKR"] = "뭔가 엄청난데... 소설에서 나오는 '금강불괴' 같은 거잖아! 스노우도 살짝 관심이 가!",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012020,
            ["GUID"] = "1E122208",
            ["NextDialogue"] = 12012021,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E122208",
            },
        [12012021] = {
            ["Content"] = "那只是好的一面。",
            ["ContentKR"] = "그건 좋은 면일 뿐이야.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012021,
            ["GUID"] = "1E122232",
            ["NextDialogue"] = 12012022,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E122232",
            },
        [12012022] = {
            ["Content"] = "还有坏的一面？",
            ["ContentKR"] = "그럼 나쁜 면도 있어?",
            ["DialogueId"] = 12012022,
            ["GUID"] = "1E12225C",
            ["NextDialogue"] = 12012023,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E12225C",
            },
        [12012023] = {
            ["Content"] = "…………",
            ["ContentKR"] = "......",
            ["DialogueId"] = 12012023,
            ["GUID"] = "1E122286",
            ["NextDialogue"] = 12012024,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E122286",
            },
        [12012024] = {
            ["Content"] = "无事，一时失言。",
            ["ContentKR"] = "실언을 했군, 아무것도 아니야.",
            ["DialogueId"] = 12012024,
            ["GUID"] = "1E1222B0",
            ["NextDialogue"] = 12012025,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E1222B0",
            },
        [12012025] = {
            ["Content"] = "我曾是一介罪人，回首往去，纵是披坚执锐，却未能护下任何性命。为大风九章奔走，于我而言，是一件将功折罪的幸事。",
            ["ContentKR"] = "난 한때 죄인이었어. 돌이켜보면, 갑옷을 입고 무기를 들었음에도 단 하나의 생명도 지켜내지 못했지. 지금은 대풍구장을 위해 힘쓰며 죄를 씻을 수 있으니, 내겐 다행스러운 일이야.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012025,
            ["GUID"] = "1E1222DA",
            ["NextDialogue"] = 12012026,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E1222DA",
            },
        [12012026] = {
            ["Content"] = "多谢二位关怀。我在此疗伤，恕无法远送。",
            ["ContentKR"] = "염려해 줘서 고마워. 미안하지만 나는 여기서 상처를 치료해야 해서, 멀리 배웅하지 못할 것 같아.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012026,
            ["GUID"] = "1E122304",
            ["NextDialogue"] = 12012027,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E122304",
            },
        [12012027] = {
            ["Content"] = "二位身手了得，但烛阴之祸凶险，还望多多留意。",
            ["ContentKR"] = "두 사람 모두 실력이 뛰어나지만, 촉룡의 재앙은 아주 위험해. 부디 몸조심해.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012027,
            ["GUID"] = "1E12232E",
            ["NextDialogue"] = 12012028,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E12232E",
            },
        [12012028] = {
            ["Content"] = "放心，我们会的。",
            ["ContentKR"] = "그럴게, 걱정하지 마.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012028,
            ["GUID"] = "1E122358",
            ["NextDialogue"] = 12012029,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E122358",
            },
        [12012029] = {
            ["Content"] = "如此，便好……",
            ["ContentKR"] = "그렇다면 다행이고...",
            ["DialogueId"] = 12012029,
            ["GUID"] = "1E122382",
            ["NextDialogue"] = 12012030,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E122382",
            },
        [12012030] = {
            ["Content"] = "…………",
            ["ContentKR"] = "......",
            ["DialogueId"] = 12012030,
            ["GUID"] = "1E1223AC",
            ["NextDialogue"] = 12012031,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E1223AC",
            },
        [12012031] = {
            ["Content"] = "……睡、睡着了？",
            ["ContentKR"] = "...자, 잠들었네?",
            ["DialogueId"] = 12012031,
            ["GUID"] = "1E1223D6",
            ["NextDialogue"] = 12012032,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E1223D6",
            },
        [12012032] = {
            ["Content"] = "大概是太累了吧。我刚才转了一圈，这里的玄色狴犴都被我们清理干净了，应该暂时安全。我们找点什么把他藏起来吧。",
            ["ContentKR"] = "많이 피곤했나 봐. 아까 한 바퀴 둘러봤는데, 여기 있던 검은 폐안은 우리가 다 해치워서 일단은 안전할 거야. 뭐 좀 덮어서 숨겨 주자.",
            ["DialogueId"] = 12012032,
            ["GUID"] = "1E122400",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E122400",
            },
        [12012033] = {
            ["Camera"] = "-211.635849,61.618118,96.055908,0.000228,-13.199524,1.187723,50.000008,78.880096,false,Manual,6.0",
            ["Content"] = "就这样，大功告成！",
            ["ContentKR"] = "이걸로, 다 됐다!",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012033,
            ["FacialId"] = {
                [1] = "200002:Happy02",
                },
            ["FinalCamera"] = "-209.995361,89.062073,96.055908,0.000229,-12.999502,-3.412318,50.000008,384.850891,false,Manual,6.0",
            ["GUID"] = "1E12242A",
            ["LookAt"] = {
