            ["TalkActionId"] = {
                [1] = "200002:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E1224A8",
            },
        [12012037] = {
            ["Content"] = "时候不早了，我们赶紧去黑市吧。",
            ["ContentKR"] = "시간이 늦었네. 우리 빨리 암시장에 가자.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012037,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["GUID"] = "1E1224D2",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E1224D2",
            },
        [12012040] = {
            ["Content"] = "小仆从，这里看起来很隐蔽，我们就把他藏在这个地方吧！",
            ["ContentKR"] = "시종, 이쪽은 밖에서 잘 안 보일 것 같아. 저 사람, 여기다 숨겨 주자. ",
            ["DialogueId"] = 12012040,
            ["Duration"] = 3,
            ["GUID"] = "1E1224D3",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E1224D3",
            },
        [12012101] = {
            ["Camera"] = "1756.186523,733.326172,500.082031,0.000011,-8.799899,-159.191101,28.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "两位小朋友，迷路啦？这里可不是你们该来的地方。快回去找你们的妈妈吧。",
            ["ContentKR"] = "꼬맹이들, 길이라도 잃었어? 여긴 너희 같은 애들이 올 만한 곳이 아니야. 얼른 엄마한테 돌아가.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012101,
            ["FacialId"] = {
                [1] = "100001:Curious",
                [2] = "200002:Doubt01",
                },
