                },
            ["ToFinalCameraBlendTime"] = 18,
            ["VoiceName"] = "voice/$Locale$/story/1201/120121/1E122FD0",
            },
        [12012105] = {
            ["Camera"] = "224.868164,494.087891,93.266602,3.600096,0.399839,-123.796814,35.000011,542.746643,false,Manual,2.8",
            ["Content"] = "理是这个理。恕我眼拙，您二位的挂坠在哪儿……？",
            ["ContentKR"] = "틀린 말은 아니야. 그런데 내 눈이 어두운 건가, 너희 펜던트는 어디 있는데...?",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012105,
            ["FacialId"] = {
                [1] = "210008:Cin_Idle",
                },
            ["FinalCamera"] = "224.868164,494.087891,85.780762,3.600096,0.399839,-123.796814,35.000011,542.746643,false,Manual,2.8",
            ["GUID"] = "1E122FFA",
            ["LookAt"] = {
                [1] = "210058:n(200002)",
                [2] = "210059:n(200002)",
                },
            ["NextDialogue"] = 12012106,
            ["SpeakNpcId"] = 210008,
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1201/120121/1E122FFA",
            },
        [12012106] = {
            ["Camera"] = "119.799805,121.291016,153.04834,0.000202,-26.601059,109.391525,43.919346,184.618271,false,Manual,2.8",
            ["Content"] = "咦——它怎么不见了？！！",
            ["ContentKR"] = "어라? 왜 없지?!",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012106,
            ["FacialId"] = {
                [1] = "200002:Shock01",
                },
            ["FinalCamera"] = "124.908203,106.779297,160.753418,0.000215,-26.601044,109.391533,43.919346,184.618271,false,Manual,2.8",
            ["GUID"] = "1E123024",
            ["LookAt"] = {
                [1] = "200002:n(200002)",
                [2] = "100001:p(zhujue_look)",
                [3] = "210008:n(200002)",
                },
            ["NextDialogue"] = 12012107,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Bai_Story_Find",
                [2] = "210008:Think_End",
                },
            ["ToFinalCameraBlendTime"] = 0.2,
            ["VoiceName"] = "voice/$Locale$/story/1201/120121/1E123024",
            },
        [12012107] = {
            ["Camera"] = "129.969727,123.162109,79.043945,0.000153,6.198642,117.198296,35.000008,232.090149,false,Manual,3.746801",
            ["Content"] = "难道是刚刚和煜明一起对付狴犴时，不小心落在了某处……",
            ["ContentKR"] = "아까 욱명이랑 폐안들을 상대할 때, 어디다 떨어뜨렸나 본데...",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012107,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["GUID"] = "1E12304E",
            ["LookAt"] = {
                [1] = "100001:p(zhujue_look)",
                [2] = "200002:n(100001)",
                [3] = "210008:n(200002)",
                },
            ["NextDialogue"] = 12012108,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120121/1E12304E",
            },
        [12012108] = {
            ["Camera"] = "839.594727,803.324219,736.787598,0.00018,-31.401964,-139.199554,32.39727,542.31012,false,DoNotOverride,3.746801",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "煜明？这名字我听过——这不是鹰爪孙吗？！",
            ["ContentKR"] = "욱명? 어디서 들어 본 이름인데... 관청의 하수인 아니야?!",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012108,
            ["FacialId"] = {
                [1] = "210008:CM_Shock01",
                },
            ["FinalCamera"] = "927.117188,687.704102,736.787598,0.00022,-31.401964,-146.59816,32.39727,542.31012,false,DoNotOverride,3.746801",
            ["GUID"] = "1E123078",
            ["LookAt"] = {
                [1] = "100001:n(210008)",
                [2] = "200002:n(210008)",
                [3] = "210008:n(100001)",
                [4] = "210058:n(100001)",
                [5] = "210059:n(100001)",
                },
            ["NextDialogue"] = 12012109,
            ["SpeakNpcId"] = 210008,
            ["TalkActionId"] = {
                [1] = "210008:Explain02_Start",
                [2] = "100001:Confident_End",
                },
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/story/1201/120121/1E123078",
            },
        [12012109] = {
            ["Content"] = "哎哟喂，是我有眼不识泰山了。不知两位是哪路人马，有这兴致过来。莫非是——钓鱼执法？！",
            ["ContentKR"] = "아이고, 제가 높으신 분들을 몰라뵀네요. 어디서 나온 분들이시길래 이런 곳까지 행차하셨습니까? 혹시... 함정 수사라도 나오신 겁니까?",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012109,
            ["FacialId"] = {
                [1] = "210008:Cin_Happy01",
                },
            ["GUID"] = "1E1230A2",
            ["LookAt"] = {
                [1] = "210058:n(100001)",
                [2] = "210059:n(100001)",
                },
            ["NextDialogue"] = 12012110,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{6},ActorId{210008},AnimationId{\"Explain02_End\"},Duration{1}},\
PlayFacial{_delay{6},ActorId{210008},FacialId{\"Cin_Idle\"}},\
CameraMoveTo{_delay{9},TargetPosition{\"151.875,84.750977,99.082031,0.000186,11.998456,-153.202118,40.000023,187.179169,false,Manual,3.746801\"},duration{0}}\
}",
            ["SpeakNpcId"] = 210008,
            ["VoiceName"] = "voice/$Locale$/story/1201/120121/1E1230A2",
            },
        [12012110] = {
            ["Content"] = "我们这里都是小本生意，没什么值得您惦记的。",
            ["ContentKR"] = "저희는 다들 소소하게 장사하는 사람들이라, 눈에 차실 만한 물건은 없을 텐데요.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012110,
            ["FacialId"] = {
                [1] = "210008:Cin_Angry01",
                },
            ["GUID"] = "1E1230CC",
            ["NextDialogue"] = 12012111,
            ["SpeakNpcId"] = 210008,
            ["TalkActionId"] = {
                [1] = "210008:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120121/1E1230CC",
            },
        [12012111] = {
            ["Camera"] = "30.108398,-132.445312,151.695312,0.000212,-8.401153,95.996559,40.000023,452.333679,false,Manual,3.746801",
            ["Content"] = "您误会了。我们是百年春止流掌柜的朋友，受托来这里办事。",
            ["ContentKR"] = "오해예요. 저희는 백년춘의 지류 사장님 친구인데, 부탁을 받고 일을 처리하러 온 거예요.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012111,
            ["GUID"] = "1E1230F6",
            ["LookAt"] = {
                [1] = "100001:n(210008)",
                [2] = "200002:n(210008)",
                [3] = "210008:n(100001)",
                },
            ["NextDialogue"] = 12012112,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "210008:Talk01_End",
                [2] = "100001:Deny01",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120121/1E1230F6",
            },
        [12012112] = {
            ["Camera"] = "594.422852,573.201172,288.23291,0.000224,-13.401206,-141.804123,35.0,452.333679,false,DoNotOverride,3.746801",
            ["Content"] = "您认识止流止掌柜，我还认识这朗朗青天白龙神君呢！仅凭一张嘴说的，谁不会？",
            ["ContentKR"] = "그쪽이 지류 대방님과 아는 사이라면, 전 백룡신군과 아는 사이입니다! 말로는 뭔들 못 하겠습니까?",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012112,
            ["FinalCamera"] = "628.412109,530.005859,288.23291,0.000224,-13.401206,-141.804123,35.0,452.333679,false,DoNotOverride,3.746801",
            ["GUID"] = "1E123120",
            ["LookAt"] = {
                [1] = "210058:n(100001)",
                [2] = "210059:n(100001)",
                },
            ["NextDialogue"] = 12012113,
            ["SpeakNpcId"] = 210008,
            ["TalkActionId"] = {
                [1] = "210008:Confident_New_Start",
                },
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/1201/120121/1E123120",
            },
        [12012113] = {
            ["Content"] = "不用再多废话了。兄弟们，风紧，扯乎——",
            ["ContentKR"] = "쓸데없는 소리 더 할 필요 없어! 형제들, 상황이 안 좋아, 튀어!",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012113,
            ["GUID"] = "1E12314A",
            ["LookAt"] = {
                [1] = "210008:n(210008)",
                [2] = "210058:n(210008)",
                [3] = "210059:n(210008)",
                },
            ["NextDialogue"] = 12012114,
            ["Scripts"] = "PARA{\
SEQ{\
TurnTo{_delay{2},TurnToDescription{\"210008:p(-180)\"}},\
MoveTo{ActorId{210008},TargetPoint{\"MeichantA_Move2\"},MoveSpeed{80},Visibility{\"Show\"}}\
},\
