            },
        [12013901] = {
            ["Content"] = "这里也太整洁了吧！空空荡荡的……",
            ["ContentKR"] = "너무 깔끔한데! 텅 비어 있어...",
            ["DialogueId"] = 12013901,
            ["Duration"] = 3,
            ["GUID"] = "1E1356A2",
            ["NextDialogue"] = 12013902,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120139/1E1356A2",
            },
        [12013902] = {
            ["Content"] = "就好像……完全没有人居住一样。",
            ["ContentKR"] = "마치... 아무도 안 사는 것처럼.",
            ["DialogueId"] = 12013902,
            ["Duration"] = 2,
            ["GUID"] = "1E1356CC",
            ["NextDialogue"] = 12013903,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120139/1E1356CC",
            },
        [12013903] = {
            ["Content"] = "小仆从你你你不要随便讲鬼故事——扶疏她的确住在这里，没错吧……？",
            ["ContentKR"] = "시, 시종 너너너, 함부로 귀신 이야기 같은 거 하지 마! 부소 언니는 여기 살고 있는 거 맞잖아. 그, 그렇지...?",
            ["DialogueId"] = 12013903,
            ["Duration"] = 3,
            ["GUID"] = "1E1356F6",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120139/1E1356F6",
            },
        [12014001] = {
            ["Camera"] = "428.589844,98.277344,126.54541,0.0,0.0,-179.794739,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "唔……",
            ["ContentKR"] = "음...",
            ["DialogueId"] = 12014001,
            ["GUID"] = "1E13670A",
            ["NextDialogue"] = 12014002,
