        [12014003] = {
            ["Camera"] = "-148.077026,-18.083099,128.862305,0.000068,-0.798572,36.407757,40.0,100000.0,false,DoNotOverride,2.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "你该不会彻夜照料她，自己没顾得上休息吧？",
            ["ContentKR"] = "밤새도록 간호하느라 부소는 쉬지도 못한 거 아니야?",
            ["DialogueId"] = 12014003,
            ["FacialId"] = {
