            ["VoiceName"] = "voice/$Locale$/story/1201/120140/1E136884",
            },
        [12014011] = {
            ["Camera"] = "212.972397,181.786407,310.055664,0.000055,-23.796507,-148.173798,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这种无关紧要的小事，怎能算作要求。你无需为此浪费一份承诺。",
            ["ContentKR"] = "그런 사소한 일을 어찌 부탁이라고 할 수 있겠어요. 그런 일로 소중한 약속을 낭비하게 할 수는 없어요.",
            ["DialogueId"] = 12014011,
            ["FacialId"] = {
                [1] = "210013:None",
                },
            ["FinalCamera"] = "285.723572,226.953049,347.814453,0.000055,-23.796507,-148.173798,35.000008,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1E1368AE",
            ["LookAt"] = {
                [1] = "100001:n(210013)",
                },
            ["NextDialogue"] = 12014012,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{3.1},ActorId{210013},AnimationId{\"Talk02R_Start\"},Duration{1}},\
PlayAnimation{_delay{6.1},ActorId{210013},AnimationId{\"Talk02R_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 210013,
            ["ToFinalCameraBlendTime"] = 20,
            ["TurnTo"] = {
                [1] = "210013:n(100001)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120140/1E1368AE",
            },
        [12014012] = {
            ["Content"] = "我有个相依为命的家人也是这样，她总是不把自己的身体当回事，无论是被欺负了还是受伤了，都装出一副若无其事的样子。但我不喜欢她这样。",
            ["ContentKR"] = "나한테도 서로에게 전부나 마찬가지인 가족이 하나 있는데, 그 아이도 늘 자기 몸에 별로 신경을 안 쓰거든. 누가 괴롭히거나 다치게 해도, 늘 아무렇지 않은 척하지. 하지만 난 그런 모습이 정말 싫어.",
            ["DialogueId"] = 12014012,
            ["FacialId"] = {
                [1] = "100001:Sad03",
                },
            ["GUID"] = "1E1368D8",
            ["LookAt"] = {
                [1] = "100001:n(100001)",
                },
            ["NextDialogue"] = 12014013,
            ["Scripts"] = "PARA{\
