                [1] = "100001:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120140/1E1368D8",
            },
        [12014013] = {
            ["Camera"] = "-3558.072266,-1192.942871,267.723633,0.000177,19.579582,18.021456,25.0,100000.0,false,Manual,2.8",
            ["Content"] = "想到她可能在某处遭遇着危险，或许还会因此受伤，我就会难过得睡不着觉。",
            ["ContentKR"] = "그 아이가 어딘가에서 위험한 일을 겪고 있다거나, 혹시 그러다 다칠 수도 있다고 생각하면, 너무 마음이 아파서 잠을 이룰 수 없을 거야.",
            ["DialogueId"] = 12014013,
            ["FinalCamera"] = "-3558.072266,-1192.942871,267.723633,0.00018,25.379478,14.420898,25.0,100000.0,false,Manual,2.8",
            ["GUID"] = "1E136902",
            ["NextDialogue"] = 12014014,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "210013:Baiheng_Story_Special03_End",
                },
            ["ToFinalCameraBlendTime"] = 16,
            ["VoiceName"] = "voice/$Locale$/story/1201/120140/1E136902",
            },
        [12014014] = {
            ["Camera"] = "-195.013611,-319.483887,133.03418,0.000073,-0.997713,80.626976,40.0,272.017151,false,Manual,10.0",
            ["Content"] = "这个世界上，肯定有某个人像我担心她一样担心你。所以，照顾好自己，不要让那个人难过。",
            ["ContentKR"] = "이 세상 어딘가에는, 분명 내가 그 아이를 걱정하는 만큼 부소를 걱정하는 사람도 있을 거야. 그러니까 몸조심해, 그 사람이 슬퍼하지 않도록...",
            ["DialogueId"] = 12014014,
            ["Duration"] = 1,
            ["FacialId"] = {
                [1] = "210013:Sad03",
                },
            ["FinalCamera"] = "-208.24704,-317.102356,133.03418,0.000073,-0.397701,79.626984,40.0,257.81076,false,Manual,10.0",
