            ["VoiceName"] = "voice/$Locale$/story/1201/120140/1E136956",
            },
        [12014016] = {
            ["Content"] = "我明白了，我会郑重考虑你的这番话。",
            ["ContentKR"] = "알겠어요. 그 말, 잘 생각해 볼게요.",
            ["DialogueId"] = 12014016,
