        [12014019] = {
            ["Content"] = "她要醒了吗？！",
            ["ContentKR"] = "저 아이, 정신 차렸나 본데?!",
            ["DialogueId"] = 12014019,
            ["FacialId"] = {
                [1] = "200002:Shock01",
                },
            ["GUID"] = "1E1369FE",
            ["NextDialogue"] = 12014020,
