                [2] = "200002:n(210013)",
                },
            ["NextDialogue"] = 12014034,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{3.1},ActorId{200002},AnimationId{\"SpecialHappy_Start\"},Duration{1}},\
PlayFacial{_delay{2.5},ActorId{100001},FacialId{\"Happy01\"}}\
}",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
