            ["SpeakNpcId"] = 210013,
            ["TalkActionId"] = {
                [1] = "200002:SpecialHappy_End",
                [2] = "100001:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120140/1E136C74",
            },
        [12014201] = {
            ["Content"] = "……未想到此处也被这些尘漠影响了。",
            ["ContentKR"] = "...이곳도 그 낙진의 영향을 받았을 줄은 몰랐어요.",
            ["DialogueId"] = 12014201,
            ["Duration"] = 3,
            ["GUID"] = "1E1387DA",
            ["NextDialogue"] = 12014202,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120142/1E1387DA",
            },
        [12014202] = {
            ["Content"] = "放心，我有办法解决。",
            ["ContentKR"] = "걱정 마, 나한테 방법이 있어.",
            ["DialogueId"] = 12014202,
            ["Duration"] = 2,
            ["GUID"] = "1E138804",
            ["NextDialogue"] = 12014203,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120142/1E138804",
            },
        [12014203] = {
            ["Content"] = "哼哼，毕竟现在白和小仆从可是出师的机枢派荣誉学徒！你就看好了！",
            ["ContentKR"] = "흥흥, 나하고 시종은 이제 당당하게 하산한 기추파 명예 제자라고! 잘 봐!",
            ["DialogueId"] = 12014203,
            ["Duration"] = 2,
            ["GUID"] = "1E13882E",
            ["NextDialogue"] = 12014204,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120142/1E13882E",
            },
        [12014204] = {
            ["Content"] = "机枢派……？这个门派式微已久，你们怎与他们产生了交集？",
            ["ContentKR"] = "기추파...요? 그 문파는 명맥이 끊긴 지 오래인데, 어쩌다 인연이 닿았어요?",
            ["DialogueId"] = 12014204,
            ["Duration"] = 2,
            ["GUID"] = "1E138858",
            ["NextDialogue"] = 12014205,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120142/1E138858",
            },
        [12014205] = {
            ["Content"] = "哼哼，这就是小说里常说的奇遇！",
            ["ContentKR"] = "흥흥, 그게 바로 소설에서나 나오는 기연이라는 거 아니겠어!",
            ["DialogueId"] = 12014205,
            ["Duration"] = 3,
            ["GUID"] = "1E138882",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120142/1E138882",
            },
        [12014301] = {
            ["Camera"] = "428.589844,98.277344,126.54541,0.0,0.0,-179.794739,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "啊，是白色妖怪！",
            ["ContentKR"] = "앗, 하얀 요괴다!",
            ["DialogueId"] = 12014301,
            ["GUID"] = "1E139842",
            ["NextDialogue"] = 12014302,
            ["RelatedWikiId"] = {
                [1] = 408013,
                [2] = 303012,
                [3] = 203006,
                },
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210016,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1201/120143/1E139842",
            },
        [12014302] = {
            ["Content"] = "呜、呜哇——谁在说话？幽灵？！救命啊，小仆从！",
            ["ContentKR"] = "으, 으악! 누가 말하는 거야? 유령?! 살려줘, 시종!",
            ["DialogueId"] = 12014302,
            ["GUID"] = "1E13986C",
            ["NextDialogue"] = 12014303,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120143/1E13986C",
            },
        [12014303] = {
            ["Content"] = "无需惊慌，小白。这就是我先前所说的<H>无由生</>。只是未受它们邀请的人看不到它们的身形。",
            ["ContentKR"] = "놀랄 필요 없어요, 스노우. 이 아이들이 바로 제가 말했던 <H>무유생</>이에요. 다만 초대받지 않은 사람은 그 모습을 볼 수 없을 뿐이죠.",
            ["DialogueId"] = 12014303,
            ["GUID"] = "1E139896",
            ["NextDialogue"] = 12014304,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120143/1E139896",
            },
        [12014304] = {
            ["Content"] = "畏生，这二位是我的朋友。我们有事拜访长老，可以请你现身，为{性别：他|她}们指明前路吗？",
            ["ContentKR"] = "외생, 이 두 분은 내 벗이란다. 장로님께 볼일이 있어서 왔는데, 혹시 잠시 모습을 보여서 이분들께 길을 좀 알려줄 수 있겠니?",
            ["DialogueId"] = 12014304,
            ["GUID"] = "1E1398C0",
            ["NextDialogue"] = 12014305,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120143/1E1398C0",
            },
        [12014305] = {
            ["Content"] = "扶疏的朋友？那也是畏生的朋友！",
            ["ContentKR"] = "부소의 친구? 그럼 내 친구이기도 하네!",
            ["DialogueId"] = 12014305,
            ["GUID"] = "1E1398EA",
            ["NextDialogue"] = 12014306,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210016,
            ["VoiceName"] = "voice/$Locale$/story/1201/120143/1E1398EA",
            },
        }
  end },
  { MinKey = 12014306, MaxKey = 12018001, Loader = function()
      return {
        [12014306] = {
            ["Content"] = "哇……这就是无由生吗？小家伙长得圆溜溜的，还挺可爱的！",
            ["ContentKR"] = "와... 이게 무유생이구나? 조그맣고 동글동글한 게, 꽤 귀엽네!",
            ["DialogueId"] = 12014306,
            ["GUID"] = "1E139914",
            ["NextDialogue"] = 12014307,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120143/1E139914",
            },
        [12014307] = {
            ["Content"] = "你怎不在祠台，跑到外面来了？",
            ["ContentKR"] = "어째서 사당 제단에 있지 않고 이런 곳에 나와 있는 거니?",
            ["DialogueId"] = 12014307,
            ["GUID"] = "1E13993E",
            ["NextDialogue"] = 12014308,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120143/1E13993E",
            },
        [12014308] = {
            ["Content"] = "灰茫茫的尘漠从地里生出来……灰茫茫的尘漠畔住了畏生的脚！畏生走不动，也跑不动……",
            ["ContentKR"] = "땅에서 희뿌연 흙먼지가 솟아올랐어... 희뿌연 흙먼지가 내 발목을 붙잡았어! 나는 걷지도 못하고, 뛰지도 못해...",
            ["DialogueId"] = 12014308,
            ["GUID"] = "1E139968",
            ["NextDialogue"] = 12014309,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210016,
            ["VoiceName"] = "voice/$Locale$/story/1201/120143/1E139968",
            },
        [12014309] = {
            ["Content"] = "没能在天黑之前回家，阿娘要记挂了……",
            ["ContentKR"] = "깜깜해지기 전에 집에 못 돌아가면, 엄마가 걱정하실 텐데...",
            ["DialogueId"] = 12014309,
            ["GUID"] = "1E139992",
            ["NextDialogue"] = 12014310,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210016,
            ["VoiceName"] = "voice/$Locale$/story/1201/120143/1E139992",
            },
        [12014310] = {
            ["Content"] = "放心吧，我们带你回家。包在白身上！",
            ["ContentKR"] = "걱정 마, 우리가 집에 데려다줄게! 이 스노우한테 맡기라고!",
            ["DialogueId"] = 12014310,
            ["GUID"] = "1E1399BC",
            ["NextDialogue"] = 12014311,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120143/1E1399BC",
            },
        [12014311] = {
            ["Content"] = "家……畏生的家丢了！哪里都找不见阿娘，畏生没有地方可以去！",
            ["ContentKR"] = "집... 나, 집을 잃어버렸어! 엄마가 아무 데도 안 보여, 나는 갈 곳이 없어!",
            ["DialogueId"] = 12014311,
            ["GUID"] = "1E1399E6",
            ["NextDialogue"] = 12014312,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210016,
            ["VoiceName"] = "voice/$Locale$/story/1201/120143/1E1399E6",
            },
        [12014312] = {
            ["Content"] = "呜哇，它怎么一下子激动了起来？",
            ["ContentKR"] = "우와, 쟤 왜 갑자기 저렇게 흥분했지?",
            ["DialogueId"] = 12014312,
            ["GUID"] = "1E139A10",
            ["NextDialogue"] = 12014313,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120143/1E139A10",
            },
        [12014313] = {
            ["Content"] = "小白，让我来吧。",
            ["ContentKR"] = "스노우, 제가 해볼게요.",
            ["DialogueId"] = 12014313,
            ["GUID"] = "1E139A3A",
            ["NextDialogue"] = 12014314,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120143/1E139A3A",
            },
        [12014314] = {
            ["Content"] = "在外面待了这么久，你一定已经疲惫不堪了吧。我们先回祠台歇脚，可好？",
            ["ContentKR"] = "밖에서 이렇게 오래 있느라고 많이 지쳤겠구나. 우선 사당 제단으로 돌아가서 좀 쉴까?",
            ["DialogueId"] = 12014314,
            ["GUID"] = "1E139A64",
            ["NextDialogue"] = 12014315,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120143/1E139A64",
            },
        [12014315] = {
            ["Content"] = "……嗯！",
            ["ContentKR"] = "...응!",
            ["DialogueId"] = 12014315,
            ["GUID"] = "1E139A8E",
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210016,
            ["VoiceName"] = "voice/$Locale$/story/1201/120143/1E139A8E",
            },
        [12014316] = {
            ["Content"] = "姐姐带畏生回家！",
            ["ContentKR"] = "누나, 나 집으로 데려가 줘!",
            ["DialogueId"] = 12014316,
            ["GUID"] = "1E139A8F",
            ["VoiceName"] = "voice/$Locale$/story/1201/120143/1E139A8F",
            },
        [12014401] = {
            ["Camera"] = "787.018799,197.117432,202.770752,0.000005,-7.400913,-173.19368,35.000011,100000.0,false,DoNotOverride,2.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "——谢谢你们！",
            ["ContentKR"] = "모두 고마워!",
            ["DialogueId"] = 12014401,
            ["FinalCamera"] = "789.158203,179.179382,202.770752,0.000005,-7.400913,-173.19368,35.000011,100000.0,false,DoNotOverride,2.8",
