            ["DialogueId"] = 12018225,
            ["GUID"] = "1E161C0A",
            ["NextDialogue"] = 12018226,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161C0A",
            },
        [12018226] = {
            ["Content"] = "看着回到虞泉的出口，好远好远。不知不觉就泄气，走不动路了……",
            ["ContentKR"] = "우천으로 돌아가는 출구를 보니까, 너무너무 멀어. 왠지 기운이 빠져서 더는 못 걷겠어...",
            ["DialogueId"] = 12018226,
            ["GUID"] = "1E161C34",
            ["NextDialogue"] = 12018227,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161C34",
            },
        [12018227] = {
            ["Content"] = "好像在这里一觉睡过去，忘记一切，就此消失也无所谓了……",
            ["ContentKR"] = "차라리 여기서 한숨 푹 자고 모든 걸 잊은 채, 이대로 사라져도 상관없지 않을까...",
            ["DialogueId"] = 12018227,
            ["GUID"] = "1E161C5E",
            ["NextDialogue"] = 12018228,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161C5E",
            },
        [12018228] = {
            ["Content"] = "但是，既然同伴来了，就应当迈开脚步继续向前了吧！",
            ["ContentKR"] = "하지만, 동료가 왔으니까, 다시 힘내서 앞으로 나아가야지!",
            ["DialogueId"] = 12018228,
            ["GUID"] = "1E161C88",
            ["NextDialogue"] = 12018229,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161C88",
            },
        [12018229] = {
            ["Content"] = "在忘川中跋涉了许久，是否觉得灵魂有些沉重呢？我来减轻你们的负担，让你们身轻如燕吧！",
            ["ContentKR"] = "망각의 강에서 오랫동안 헤매느라, 영혼이 좀 무겁게 느껴지지 않아? 내가 너희 짐을 덜어줄게. 몸이 제비처럼 가벼워질 거야!",
            ["DialogueId"] = 12018229,
            ["GUID"] = "1E161CB2",
            ["NextDialogue"] = 12018230,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161CB2",
            },
        [12018230] = {
            ["Content"] = "那，我来帮你们扫清远处的障碍，让你们的行动更加灵活！",
            ["ContentKR"] = "그럼, 나는 멀리 있는 장애물을 치워서, 너희 움직임을 한결 수월하게 해 줄게!",
            ["DialogueId"] = 12018230,
            ["GUID"] = "1E161CDC",
            ["NextDialogue"] = 12018231,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161CDC",
            },
        [12018231] = {
            ["Content"] = "咿，咿呀！这下完全没问题了，我们赶紧出发吧！",
            ["ContentKR"] = "야하, 야하하! 이제 문제없어, 어서 출발하자!",
            ["DialogueId"] = 12018231,
            ["GUID"] = "1E161D06",
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["SpeakNpcName"] = "UI_Npc_Name_WuyoushengA&B",
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161D06",
            },
        [12018232] = {
            ["Content"] = "咿咿，呀！",
            ["ContentKR"] = "야하하, 야하!",
            ["DialogueId"] = 12018232,
            ["GUID"] = "1E161D30",
            ["NextDialogue"] = 12018233,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["SpeakNpcName"] = "UI_Npc_Name_WuyoushengShoukun",
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161D30",
            },
        [12018233] = {
            ["Content"] = "坏花困住了同伴，赶紧去帮忙！",
            ["ContentKR"] = "나쁜 꽃이 동료를 가둬버렸어, 어서 도와줘!",
            ["DialogueId"] = 12018233,
            ["GUID"] = "1E161D5A",
            ["NextDialogue"] = 12018234,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161D5A",
            },
        [12018234] = {
            ["Content"] = "我在古籍上见过此种异花。当其花瓣闭合时，刀枪难入，只能等候其绽开的时机。",
            ["ContentKR"] = "고서에서 이런 기이한 꽃을 본 적이 있어요. 꽃잎이 닫혀 있을 때는 어떤 공격도 통하지 않아서, 꽃이 활짝 피어날 때를 기다릴 수밖에 없어요.",
            ["DialogueId"] = 12018234,
            ["GUID"] = "1E161D84",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161D84",
            },
        [12018235] = {
            ["Content"] = "花蕊暴露在外了，就趁现在！",
            ["ContentKR"] = "꽃술이 밖으로 드러났어요, 바로 지금이에요!",
            ["DialogueId"] = 12018235,
            ["GUID"] = "1E161DAE",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161DAE",
            },
        [12018236] = {
            ["Content"] = "祝由大人，还有没见过的白发勇者，谢谢你们！",
            ["ContentKR"] = "축유 대인, 그리고 처음 보는 백발의 용사님, 고마워!",
            ["DialogueId"] = 12018236,
            ["GUID"] = "1E161DD8",
            ["NextDialogue"] = 12018237,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcName"] = "UI_Npc_Name_WuyoushengShoukun",
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161DD8",
            },
        [12018237] = {
            ["Content"] = "俺也来助你们一臂之力！俺的铁头槌，连大地都能砸的梆梆作响哟！",
            ["ContentKR"] = "나도 너희들한테 힘을 보태줄게! 내 쇠망치는 땅도 쿵쿵 울리게 할 수 있다고!",
            ["DialogueId"] = 12018237,
            ["GUID"] = "1E161E02",
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcName"] = "UI_Npc_Name_WuyoushengShoukun",
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161E02",
            },
        [12018238] = {
            ["Content"] = "最后的同伴，最后的同伴！",
            ["ContentKR"] = "마지막 동료다, 마지막 동료!",
            ["DialogueId"] = 12018238,
            ["GUID"] = "1E161E2C",
            ["NextDialogue"] = 12018239,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcName"] = "UI_Npc_Name_WuyoushengA",
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161E2C",
            },
        [12018239] = {
            ["Content"] = "还是先前那种异花。{nickname}，趁其绽开的时机，将花蕊连着枝蔓一举荡清吧。",
            ["ContentKR"] = "아까와 같은 기이한 꽃이네요. {nickname}, 꽃이 활짝 피었을 때를 노려서, 꽃술과 가지까지 한 번에 날려 버리세요.",
            ["DialogueId"] = 12018239,
            ["GUID"] = "1E161E56",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161E56",
            },
        [12018240] = {
            ["Content"] = "以老夫平生武艺，竟险些折在了此处。惭愧，惭愧……",
            ["ContentKR"] = "이 늙은이, 평생 무예를 갈고닦고도 하마터면 이곳에서 세상과 하직할 뻔했구려. 부끄럽고 또 부끄럽소이다...",
            ["DialogueId"] = 12018240,
            ["GUID"] = "1E161E80",
            ["NextDialogue"] = 12018241,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcName"] = "UI_CMName_Name_MatureWuyou",
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161E80",
            },
        [12018241] = {
            ["Content"] = "这样一来，同伴就集齐啦！没有人被落下，没有人被落下！",
            ["ContentKR"] = "이로써 동료들이 모두 모였어! 한 명도 빠짐없이 말이야!",
            ["DialogueId"] = 12018241,
            ["GUID"] = "1E161EAA",
            ["NextDialogue"] = 12018242,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcName"] = "UI_Npc_Name_WuyoushengA",
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161EAA",
            },
        [12018242] = {
            ["Content"] = "前方为一巨花秽兽所盘踞，其把持了前往此世之出口。让老夫随你们同去，降妖除魔，清源正本！",
            ["ContentKR"] = "앞에는 거대한 꽃 요괴가 이승으로 가는 길목을 떡하니 가로막고 있소이다. 이 늙은이가 자네들과 함께 가 요괴를 물리치고, 모든 것을 제자리로 돌려놓겠소!",
            ["DialogueId"] = 12018242,
            ["GUID"] = "1E161ED4",
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcName"] = "UI_CMName_Name_MatureWuyou",
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161ED4",
            },
        [12018243] = {
            ["Content"] = "{nickname}，忘川即将崩塌了，必须赶紧结束这一战！",
            ["ContentKR"] = "{nickname}, 망각의 강이 곧 무너져 내릴 거예요! 어서 이 싸움을 끝내야 해요!",
            ["DialogueId"] = 12018243,
            ["GUID"] = "1E161EFE",
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161EFE",
            },
        [12018244] = {
            ["Content"] = "趁现在，把手递给我。",
            ["ContentKR"] = "지금이에요, 손을 주세요.",
            ["DialogueId"] = 12018244,
            ["GUID"] = "1E161F28",
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161F28",
            },
        [12018300] = {
            ["Content"] = "多谢两位救命之恩，以后必将回报。我们便先离去啦！",
            ["ContentKR"] = "목숨을 구해 줘서 고마워. 나중에 꼭 보답할게. 그럼 우리 먼저 갈게!",
            ["DialogueId"] = 12018300,
            ["GUID"] = "1E162858",
            ["NextDialogue"] = 12018301,
            ["RelatedWikiId"] = {
                [1] = 408013,
                [2] = 303012,
                [3] = 203006,
                },
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["SpeakNpcName"] = "UI_Npc_Name_Wuyoushengmen",
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162858",
            },
        [12018301] = {
            ["Content"] = "……呜呜……扶疏，{nickname}，你们终于回来了！我都快急坏了……",
            ["ContentKR"] = "...훌쩍 ...드디어 돌아왔구나, 부소 언니, {nickname}! 나 진짜 걱정돼 죽는 줄 알았다고...",
            ["DialogueId"] = 12018301,
            ["GUID"] = "1E162882",
            ["NextDialogue"] = 12018302,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162882",
            },
        [12018302] = {
            ["Content"] = "我还以为差一点就……呸呸呸！坏话不说出来就不会灵验！",
            ["ContentKR"] = "조금만 늦었어도... 에이, 퉤퉤퉤! 나쁜 말은 입 밖에 안 내면 괜찮아!",
            ["DialogueId"] = 12018302,
            ["GUID"] = "1E1628AC",
            ["NextDialogue"] = 12018303,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E1628AC",
            },
        [12018303] = {
            ["Content"] = "扶疏，谢谢你以身涉险，把我带出来。",
            ["ContentKR"] = "부소, 위험을 무릅쓰고 날 데리고 나와줘서 고마워.",
            ["DialogueId"] = 12018303,
            ["GUID"] = "1E1628D6",
            ["NextDialogue"] = 12018304,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E1628D6",
            },
        [12018304] = {
            ["Content"] = "这是我应做的。",
            ["ContentKR"] = "제가 마땅히 해야 할 일인걸요.",
            ["DialogueId"] = 12018304,
            ["GUID"] = "1E162900",
            ["NextDialogue"] = 12018305,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162900",
            },
        [12018305] = {
            ["Content"] = "你没事吧？你看起来脸色好像不太好……",
            ["ContentKR"] = "괜찮아? 안색이 안 좋아 보이는데...",
            ["DialogueId"] = 12018305,
            ["GUID"] = "1E16292A",
            ["NextDialogue"] = 12018306,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E16292A",
            },
        [12018306] = {
            ["Content"] = "我身体无大碍。只是心有点乱，需要静一静，整理一下思绪。",
            ["ContentKR"] = "괜찮아요. 다만 마음이 좀 복잡해서, 조용히 생각을 정리할 시간이 필요해요.",
            ["DialogueId"] = 12018306,
            ["GUID"] = "1E162954",
            ["NextDialogue"] = 12018307,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162954",
            },
        [12018307] = {
            ["Content"] = "好……如果你有什么烦恼想找别人倾诉，我随时在。",
            ["ContentKR"] = "응... 혹시 무슨 고민이 있어서 누군가한테 털어놓고 싶다면, 난 언제든 괜찮아.",
            ["DialogueId"] = 12018307,
            ["GUID"] = "1E16297E",
            ["NextDialogue"] = 12018308,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E16297E",
            },
        [12018308] = {
            ["Content"] = "那是自然。毕竟经此一遭，你们便是我在世界上唯二的友人了。",
            ["ContentKR"] = "물론이죠. 이런 일을 겪었으니, 이제 두 분은 제게 세상에 둘도 없는 벗이나 마찬가지인걸요.",
            ["DialogueId"] = 12018308,
            ["GUID"] = "1E1629A8",
            ["NextDialogue"] = 12018309,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E1629A8",
            },
        [12018309] = {
            ["Content"] = "呜呜，扶疏……",
            ["ContentKR"] = "훌쩍, 부소...",
            ["DialogueId"] = 12018309,
            ["GUID"] = "1E1629D2",
            ["NextDialogue"] = 12018310,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E1629D2",
            },
        [12018310] = {
            ["Content"] = "好啦。虽然过程有所波折，但所需的药草已经采摘到了。趁着露水还未褪去，我要尽早将其带回，研磨入药。",
            ["ContentKR"] = "자. 비록 과정에 우여곡절이 좀 있었지만, 필요한 약초는 다 구했어요. 이슬이 마르기 전에 어서 가지고 돌아가 약으로 만들어야죠.",
            ["DialogueId"] = 12018310,
            ["GUID"] = "1E1629FC",
            ["NextDialogue"] = 12018311,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E1629FC",
            },
        [12018311] = {
            ["Content"] = "咿！",
            ["ContentKR"] = "야하!",
            ["DialogueId"] = 12018311,
            ["GUID"] = "1E162A26",
            ["NextDialogue"] = 12018312,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210036,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162A26",
            },
        [12018312] = {
            ["Content"] = "哇啊，你从哪里冒出来的！吓我一跳！",
            ["ContentKR"] = "와앗, 넌 또 어디서 갑자기 튀어나온 거야! 깜짝 놀랐네!",
            ["DialogueId"] = 12018312,
            ["GUID"] = "1E162A50",
            ["NextDialogue"] = 12018313,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162A50",
            },
        [12018313] = {
            ["Content"] = "你竟没有与它们一同离去……",
            ["ContentKR"] = "너는 다른 아이들과 함께 떠나지 않았네...",
            ["DialogueId"] = 12018313,
            ["GUID"] = "1E162A7A",
            ["NextDialogue"] = 12018314,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162A7A",
            },
        [12018314] = {
            ["Content"] = "我在往隙深处偶遇了它，将它顺手带出。这也是一种萍水相逢的缘分吧。",
            ["ContentKR"] = "과거의 틈 깊은 곳에서 우연히 이 아이를 만나서, 데리고 나왔어요. 이것도 뜻밖의 좋은 인연이겠죠.",
            ["DialogueId"] = 12018314,
            ["GUID"] = "1E162AA4",
            ["NextDialogue"] = 12018315,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162AA4",
            },
        [12018315] = {
            ["Content"] = "咿！咿！",
            ["ContentKR"] = "야하! 야하하!",
            ["DialogueId"] = 12018315,
            ["GUID"] = "1E162ACE",
            ["NextDialogue"] = 12018316,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210036,
            ["SpeakNpcName"] = "UI_CMName_Name_WuyouWuyan",
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162ACE",
            },
        [12018316] = {
            ["Content"] = "它看起来好像格外亲近你。",
            ["ContentKR"] = "유난히 부소를 잘 따르는 것 같네.",
            ["DialogueId"] = 12018316,
            ["GUID"] = "1E162AF8",
            ["NextDialogue"] = 12018317,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162AF8",
            },
        [12018317] = {
            ["Content"] = "这可有些头疼了……我接下来需要集中精神，治疗患者的过程中不好受外界打扰。",
            ["ContentKR"] = "좀 곤란하네요... 이제부터 집중해서 환자를 치료해야 해서, 방해를 받으면 안 되거든요.",
            ["DialogueId"] = 12018317,
            ["GUID"] = "1E162B22",
            ["NextDialogue"] = 12018318,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162B22",
            },
        [12018318] = {
            ["Content"] = "{nickname}，可以拜托你先照料它一段时间吗？",
            ["ContentKR"] = "{nickname} 씨, 잠시 이 아이를 좀 맡아줄 수 있어요?",
            ["DialogueId"] = 12018318,
            ["GUID"] = "1E162B4C",
            ["NextDialogue"] = 12018319,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162B4C",
            },
        [12018319] = {
            ["Content"] = "小跟班的小跟班……那岂不是小跟班二号！",
            ["ContentKR"] = "쫄병의 쫄병이라... 그럼 쫄병 2호잖아!",
            ["DialogueId"] = 12018319,
            ["GUID"] = "1E162B76",
            ["NextDialogue"] = 12018320,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162B76",
            },
        [12018320] = {
            ["Content"] = "咿呀咿！咿咿！",
            ["ContentKR"] = "야하하! 야하!",
            ["DialogueId"] = 12018320,
            ["GUID"] = "1E162BA0",
            ["NextDialogue"] = 12018321,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210036,
            ["SpeakNpcName"] = "UI_CMName_Name_WuyouWuyan",
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162BA0",
            },
        [12018321] = {
            ["Content"] = "它看起来似乎不太乐意的样子。",
            ["ContentKR"] = "썩 내키지 않는 눈치인데.",
            ["DialogueId"] = 12018321,
            ["GUID"] = "1E162BCA",
            ["NextDialogue"] = 12018322,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162BCA",
            },
        [12018322] = {
            ["Content"] = "……抱歉，是我轻慢了你的想法。既然你我有缘，从今往后，你就跟着我吧。我不会信手将你落下，可好？",
            ["ContentKR"] = "...미안, 네 생각을 너무 가볍게 여겼구나. 이왕 우리 인연이 닿았으니, 앞으로는 날 따라다니렴. 함부로 널 홀로 두진 않을게, 괜찮겠니?",
            ["DialogueId"] = 12018322,
            ["GUID"] = "1E162BF4",
            ["NextDialogue"] = 12018323,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162BF4",
            },
        [12018323] = {
            ["Content"] = "咿！",
            ["ContentKR"] = "야하!",
            ["DialogueId"] = 12018323,
            ["GUID"] = "1E162C1E",
            ["NextDialogue"] = 12018324,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210036,
            ["SpeakNpcName"] = "UI_CMName_Name_WuyouWuyan",
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162C1E",
            },
        [12018324] = {
            ["Content"] = "{nickname}，无由生长老处也烦请你去回报了。待患者的病情稍有好转，我会再与你们见面的。",
            ["ContentKR"] = "{nickname}, 무유생 장로님께도 돌아가서 보고 좀 부탁드릴게요. 전 환자분 상태가 좀 나아지면, 그때 다시 두 사람을 만나러 갈게요.",
            ["DialogueId"] = 12018324,
            ["GUID"] = "1E162C48",
            ["NextDialogue"] = 12018325,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162C48",
            },
        [12018325] = {
            ["Content"] = "那就一言为定了！",
            ["ContentKR"] = "좋아, 약속한 거야!",
            ["DialogueId"] = 12018325,
            ["GUID"] = "1E162C72",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162C72",
            },
        [12018401] = {
            ["Camera"] = "-82.743599,-22.173996,191.510315,0.000107,-18.000362,104.812141,25.000002,269.56311,false,Manual,6.0",
            ["Content"] = "小友来了？出发吧。",
            ["ContentKR"] = "왔나? 출발하지.",
            ["DialogueId"] = 12018401,
            ["FacialId"] = {
                [1] = "210012:Smile01",
                },
            ["FinalCamera"] = "-85.275848,-12.593918,188.29126,0.000105,-18.000381,104.811234,25.000002,269.806946,false,Manual,6.0",
            ["GUID"] = "1E1638EA",
            ["LookAt"] = {
                [1] = "100001:n(210012)",
                [2] = "210012:n(100001)",
                [3] = "200002:n(100001)",
                },
            ["NextDialogue"] = 12018402,
            ["RelatedWikiId"] = {
                [1] = 203005,
                },
            ["SpeakNpcId"] = 210012,
            ["TalkActionId"] = {
                [1] = "210012:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 3,
            ["VoiceName"] = "voice/$Locale$/story/1201/120184/1E1638EA",
            },
        [12018402] = {
            ["Camera"] = "31.293282,90.810593,118.199219,0.000119,3.198878,148.801849,35.000008,243.817368,false,Manual,6.0",
            ["Content"] = "出发？去哪儿？你总得先跟我说清楚吧？",
            ["ContentKR"] = "출발? 어디로요? 저한테 먼저 설명해주셔야 하지 않을까요?",
            ["DialogueId"] = 12018402,
            ["FacialId"] = {
                [1] = "100001:Doubt01",
                },
            ["GUID"] = "1E163914",
            ["NextDialogue"] = 12018403,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120184/1E163914",
            },
        [12018403] = {
            ["Camera"] = "17.345215,243.589844,108.354248,0.000138,7.597834,-130.80278,35.000008,255.516861,false,Manual,6.0",
            ["Content"] = "……说清楚？",
            ["ContentKR"] = "...설명?",
            ["DialogueId"] = 12018403,
            ["FacialId"] = {
                [1] = "210012:Think01",
                },
            ["FinalCamera"] = "17.345215,243.589844,108.354248,0.000137,10.997827,-130.802673,35.000008,255.516861,false,Manual,6.0",
            ["GUID"] = "1E16393E",
            ["NextDialogue"] = 12018404,
            ["SpeakNpcId"] = 210012,
            ["TalkActionId"] = {
                [1] = "210012:Talk03ToThink_Start",
                [2] = "100001:Explain02_End",
                },
            ["ToFinalCameraBlendTime"] = 2.5,
            ["VoiceName"] = "voice/$Locale$/story/1201/120184/1E16393E",
            },
        [12018404] = {
            ["Camera"] = "-52.819229,197.234238,148.239014,0.000148,5.597148,-120.211037,35.000011,164.675781,false,Manual,6.0",
            ["Content"] = "兵贵神速。若是为了无谓的口舌，耽误了最佳时机，那猎物可就要逃了。",
            ["ContentKR"] = "용병술은 속도가 생명인 법이지. 만약 자네에게 설명하느라 시간을 허비해서 사냥감이 달아나 버린다면, 뒷감당할 자신 있나?",
            ["DialogueId"] = 12018404,
            ["FacialId"] = {
                [1] = "210012:Doubt01",
                },
            ["GUID"] = "1E163968",
            ["NextDialogue"] = 12018405,
            ["Scripts"] = "PlayAnimation{_delay{1},ActorId{210012},AnimationId{\"Talk03ToThink_End\"},Duration{2}},",
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120184/1E163968",
            },
        [12018405] = {
            ["Camera"] = "-63.644783,133.544785,118.57605,0.000155,11.196975,138.185074,35.000011,122.361931,false,Manual,6.0",
            ["Content"] = "那是你要考虑的。我只在意这次行动有没有危险，以及——是否正当。",
            ["ContentKR"] = "그건 그쪽에서 고려하실 문제고요. 전 이번 행동이 위험하지는 않은지, 그리고 '정당'한 일인지에만 관심 있어요.",
            ["DialogueId"] = 12018405,
            ["FacialId"] = {
                [1] = "100001:Angry01",
                },
            ["FinalCamera"] = "-63.644783,133.544785,118.57605,0.000169,16.996433,-169.21553,35.000011,122.361931,false,Manual,6.0",
            ["GUID"] = "1E163992",
            ["LookAt"] = {
                [1] = "100001:n(210012)",
                [2] = "210012:n(100001)",
                [3] = "200002:n(100001)",
                },
            ["NextDialogue"] = 12018406,
