}",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "210012:Talk03_End",
                },
            ["ToFinalCameraBlendTime"] = 0.9,
            ["VoiceName"] = "voice/$Locale$/story/1201/120184/1E163992",
            },
        [12018406] = {
            ["Camera"] = "-113.994232,54.671646,165.879028,0.000155,-25.60232,96.198647,25.000002,113.956665,false,DoNotOverride,22.0",
            ["Content"] = "呜哇，气氛好紧张……小仆从，要不还是算了吧？",
            ["ContentKR"] = "우와, 분위기 엄청 살벌하네... 시종, 그냥 관두는 게 어떨까?",
            ["DialogueId"] = 12018406,
            ["FacialId"] = {
                [1] = "200002:Sad01",
                },
            ["GUID"] = "1E1639BC",
            ["LookAt"] = {
                [1] = "100001:n(210012)",
                [2] = "210012:n(210012)",
                [3] = "200002:n(100001)",
                },
            ["NextDialogue"] = 12018407,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Shock_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120184/1E1639BC",
            },
        [12018407] = {
            ["Camera"] = "295.454956,542.930176,371.227875,0.000125,-26.204176,-133.401733,24.0,113.956657,false,DoNotOverride,22.0",
            ["Content"] = "哈哈……不卑不亢，据理力争。颇有我年轻时候的风采，我很欣赏。",
            ["ContentKR"] = "후후... 비굴하지도 거만하지도 않고, 조목조목 따질 줄도 알고. 자못 내 젊은 시절의 풍모가 보이는 듯하여 아주 마음에 드는군.",
            ["DialogueId"] = 12018407,
            ["FacialId"] = {
                [1] = "210012:Ahaha01",
                },
            ["GUID"] = "1E1639E6",
            ["NextDialogue"] = 12018408,
            ["SpeakNpcId"] = 210012,
            ["TalkActionId"] = {
                [1] = "210012:Angry01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120184/1E1639E6",
            },
        [12018408] = {
            ["Camera"] = "-125.168137,93.99778,144.010498,0.000147,-24.602682,79.995262,25.000002,166.176483,false,Manual,6.0",
            ["Content"] = "……他竟然一下子变脸了！",
            ["ContentKR"] = "...저 사람 갑자기 얼굴색이 변했어!",
            ["DialogueId"] = 12018408,
            ["GUID"] = "1E163A10",
            ["NextDialogue"] = 12018409,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Shock_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120184/1E163A10",
            },
        [12018409] = {
            ["Camera"] = "-95.768387,166.50177,121.84198,0.000135,-26.202879,76.599541,24.0,113.956657,false,DoNotOverride,22.0",
            ["Content"] = "等等，哪有人用这么自恋的方式夸别人啊！简直是自大狂！",
            ["ContentKR"] = "잠깐, 누가 저렇게 자기 자랑하듯이 남을 칭찬해! 완전 자뻑대마왕이잖아!",
            ["DialogueId"] = 12018409,
            ["FacialId"] = {
                [1] = "200002:Angry01",
                },
            ["GUID"] = "1E163A3A",
            ["NextDialogue"] = 12018410,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120184/1E163A3A",
            },
        [12018410] = {
            ["Camera"] = "64.890961,321.150482,91.39502,0.000176,5.395296,-137.398178,24.0,297.770538,false,Manual,6.0",
            ["Content"] = "路上说吧，你们关心的问题，我都会尽力解答。",
            ["ContentKR"] = "가면서 이야기해 주겠네. 자네들이 궁금해하는 건, 내가 최대한 답해 주지.",
            ["DialogueId"] = 12018410,
            ["FacialId"] = {
                [1] = "210012:None",
                },
            ["GUID"] = "1E163A64",
            ["LookAt"] = {
                [1] = "100001:n(210012)",
                [2] = "210012:n(200002)",
                [3] = "200002:n(100001)",
                },
            ["SpeakNpcId"] = 210012,
            ["TalkActionId"] = {
                [1] = "210012:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120184/1E163A64",
            },
        [12018501] = {
            ["Content"] = "小友可曾有过疑惑，烛阴之灾为何以玄色狴犴的模样呈现？",
            ["ContentKR"] = "촉룡의 재앙이 어째서 검은 폐안의 모습으로 나타나는지 의문을 품어본 적 있나?",
            ["DialogueId"] = 12018501,
            ["Duration"] = 3,
            ["GUID"] = "1E164952",
            ["NextDialogue"] = 12018502,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120185/1E164952",
            },
        [12018502] = {
            ["Content"] = "华胥备受崇敬的狴犴，在外界却是引起灾厄和恐惧的秽兽。其间区别，便在于大风九章的约束。",
            ["ContentKR"] = "화서에서 깊은 존경을 받는 폐안은, 바깥세상에서는 도리어 재앙과 공포를 불러일으키는 필토이드네. 그 차이를 만드는 건 바로 대풍구장의 속박이지.",
            ["DialogueId"] = 12018502,
            ["Duration"] = 5,
            ["GUID"] = "1E16497C",
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120185/1E16497C",
            },
        [12018503] = {
            ["Content"] = "玄色狴犴的出现，只能引向一种猜测——大风九章，如今正在失控。",
            ["ContentKR"] = "검은 폐안의 출현은, 오직 한 가지 추측으로 귀결될 뿐이네. …대풍구장은, 지금 통제 불능 상태라는 거지.",
            ["DialogueId"] = 12018503,
            ["Duration"] = 3,
            ["GUID"] = "1E1649A6",
            ["NextDialogue"] = 12018504,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120185/1E1649A6",
            },
        [12018504] = {
            ["Content"] = "但止流掌柜说过，解决了烛阴之灾，这些问题就会正常。",
            ["ContentKR"] = "하지만 지류 사장님은 촉룡의 재앙을 해결하면 그런 문제는 정상으로 돌아올 거라고 했어요.",
            ["DialogueId"] = 12018504,
            ["Duration"] = 3,
            ["GUID"] = "1E1649D0",
            ["NextDialogue"] = 12018505,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120185/1E1649D0",
            },
        [12018505] = {
            ["Content"] = "是，但那也只能救得了一时。",
            ["ContentKR"] = "맞네. 하지만 그것도 임시변통일 뿐이야.",
            ["DialogueId"] = 12018505,
            ["Duration"] = 2,
            ["GUID"] = "1E1649FA",
            ["NextDialogue"] = 12018506,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120185/1E1649FA",
            },
        [12018506] = {
            ["Content"] = "若是烛阴之灾周而复返，长久引得民生积弱呢？",
            ["ContentKR"] = "만약 촉룡의 재앙이 반복되어, 오랜 세월 백성들의 삶을 피폐하게 만든다면 어찌하겠나?",
            ["DialogueId"] = 12018506,
            ["Duration"] = 3,
            ["GUID"] = "1E164A24",
            ["NextDialogue"] = 12018507,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120185/1E164A24",
            },
        [12018507] = {
            ["Content"] = "止流掌柜有她的考虑。有些猜测，她未必会与你说。",
            ["ContentKR"] = "지류 대방에게는 그 나름의 생각이 있을 것이네. 어떤 짐작들은, 자네에게 미처 말하지 않았을 수도 있고 말이지.",
            ["DialogueId"] = 12018507,
            ["Duration"] = 3,
            ["GUID"] = "1E164A4E",
            ["NextDialogue"] = 12018508,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120185/1E164A4E",
            },
        [12018508] = {
            ["Content"] = "在我看来，若是大风九章的根基出了问题，做再多修缮也只是表面功夫。",
            ["ContentKR"] = "내가 보기에, 대풍구장의 근간에 문제가 생겼다면, 아무리 손 써 봐야 그저 임시방편에 불과하네.",
            ["DialogueId"] = 12018508,
            ["Duration"] = 3,
            ["GUID"] = "1E164A78",
            ["NextDialogue"] = 12018509,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120185/1E164A78",
            },
        [12018509] = {
            ["Content"] = "你的意思是，你从一开始就不认同大风九章？",
            ["ContentKR"] = "그러니까, 애초에 대풍구장을 인정하지 않으신다는 건가요?",
            ["DialogueId"] = 12018509,
            ["Duration"] = 2,
            ["GUID"] = "1E164AA2",
            ["NextDialogue"] = 12018510,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120185/1E164AA2",
            },
        [12018510] = {
            ["Content"] = "哈哈哈……小友不用把话说得这么绝对。俗话说得好，知己知彼，方能百战百胜。",
            ["ContentKR"] = "허허허... 그렇게 딱 잘라 단정 지을 필요 있겠는가. 옛말에 지피지기면 백전백승이란 말이 있지 않나.",
            ["DialogueId"] = 12018510,
            ["Duration"] = 4,
            ["GUID"] = "1E164ACC",
            ["NextDialogue"] = 12018511,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120185/1E164ACC",
            },
        [12018511] = {
            ["Content"] = "此行的目的是捉来一只狴犴作为我的“收藏品”，试图研究透彻其中原理，做一些两手准备。",
            ["ContentKR"] = "이번에 가는 목적은 폐안 한 마리를 잡아 나의 '수집품'으로 삼아, 그 원리를 철저히 연구해서 만일의 사태에 대비하려는 것이네.",
            ["DialogueId"] = 12018511,
            ["Duration"] = 5,
            ["GUID"] = "1E164AF6",
            ["NextDialogue"] = 12018512,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120185/1E164AF6",
            },
        [12018512] = {
            ["Content"] = "如何，这个理由，足以说服你吗？",
            ["ContentKR"] = "어떤가? 이만하면 충분히 납득하겠나?",
            ["DialogueId"] = 12018512,
            ["Duration"] = 2,
            ["GUID"] = "1E164B20",
            ["NextDialogue"] = 12018513,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120185/1E164B20",
            },
        [12018513] = {
            ["Content"] = "……与狴犴为敌，不会招致大风九章的惩罚吗？",
            ["ContentKR"] = "...폐안과 적이 되면, 대풍구장의 벌을 받지는 않나요?",
            ["DialogueId"] = 12018513,
            ["Duration"] = 5,
            ["GUID"] = "1E164B4A",
            ["NextDialogue"] = 12018514,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120185/1E164B4A",
            },
        [12018514] = {
            ["Content"] = "呵呵，我等黑市中人常年游走于大风九章边缘，自有分寸。",
            ["ContentKR"] = "허허, 우리 암시장 사람들은 늘 대풍구장의 경계를 아슬아슬 넘나드니, 다 방도가 있다네.",
            ["DialogueId"] = 12018514,
            ["Duration"] = 2,
            ["GUID"] = "1E164B74",
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120185/1E164B74",
            },
        [12018601] = {
            ["Camera"] = "24.121033,469.795776,75.995605,0.000102,15.589243,-120.015869,25.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "头儿，您来了！",
            ["ContentKR"] = "두목, 오셨습니까!",
            ["DialogueId"] = 12018601,
            ["FacialId"] = {
                [1] = "210010:CM_Smile01",
