        [12018611] = {
            ["Camera"] = "-92.525726,134.76416,116.622314,0.000168,23.376129,15.452583,25.000002,141.235916,false,Manual,22.0",
            ["Content"] = "最终交战双方全数折于此地，无一人生还。机枢派也自此式微。",
            ["ContentKR"] = "결국 싸우던 양측 모두 이곳에서 전멸하여, 단 한 명도 살아남지 못했다. 기추파도 그때부터 세가 기울기 시작했고.",
