            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120188/1E167A8A",
            },
        [12018802] = {
            ["Content"] = "虬先生在前面。我们去找他问个明白。",
            ["ContentKR"] = "규선생이 앞에 있어. 가서 한번 물어보자.",
            ["DialogueId"] = 12018802,
            ["GUID"] = "1E167AB4",
