            ["Duration"] = 2,
            ["GUID"] = "1E1760B8",
            ["VoiceName"] = "voice/$Locale$/story/1201/120202/1E1760B8",
            },
        [12020205] = {
            ["Content"] = "无妨。",
            ["ContentKR"] = "괜찮다.",
            ["DialogueId"] = 12020205,
            ["Duration"] = 1,
            ["GUID"] = "1E1760E2",
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120202/1E1760E2",
            },
        [12020301] = {
            ["Camera"] = "-78.574219,498.462891,113.020996,0.000014,-0.99994,-74.596542,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "唉……好不容易见到师兄一面，又被旁人打搅，让他逃了去了。",
            ["ContentKR"] = "쳇... 간신히 사형을 만났는데, 이번에도 다른 놈들 때문에 놓쳐버렸구나.",
            ["DialogueId"] = 12020301,
            ["GUID"] = "1E1770A2",
            ["NextDialogue"] = 12020302,
            ["RelatedWikiId"] = {
                [1] = 203007,
                [2] = 203004,
                [3] = 203005,
                },
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120203/1E1770A2",
            },
        [12020302] = {
            ["Content"] = "这桂花糕，在怀里揣了半晌，揣得都冷了硬了。也不知道猴年马月才能让师兄吃上。",
            ["ContentKR"] = "이 계화떡도 품 안에 오래 넣고 다녔더니 다 식어서 딱딱해져 버렸네. 대체 언제쯤이나 사형께 맛보여 드릴 수 있을는지, 원.",
            ["DialogueId"] = 12020302,
            ["GUID"] = "1E1770CC",
            ["NextDialogue"] = 12020303,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120203/1E1770CC",
            },
        [12020303] = {
            ["Content"] = "原来你在找的人，就是煜明。",
            ["ContentKR"] = "찾고 있다던 사람이 욱명이었구나.",
            ["DialogueId"] = 12020303,
            ["GUID"] = "1E1770F6",
            ["NextDialogue"] = 12020304,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120203/1E1770F6",
            },
        [12020304] = {
            ["Content"] = "话说回来，你怎么在这。我赶到之前，这里都发生了什么？",
            ["ContentKR"] = "그건 그렇고, 넌 왜 여기에 있는 것이냐? 내가 오기 전에 여기서 무슨 일이 있었느냐?",
            ["DialogueId"] = 12020304,
            ["GUID"] = "1E177120",
            ["NextDialogue"] = 12020305,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120203/1E177120",
            },
        [12020305] = {
            ["Content"] = "（向刻舟讲述之前发生的事情。）",
            ["ContentKR"] = "(각주에게 이전 상황을 설명한다.)",
            ["DialogueId"] = 12020305,
            ["GUID"] = "1E17714A",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 12020306,
            ["VoiceName"] = "voice/$Locale$/story/1201/120203/1E17714A",
            },
        [12020306] = {
            ["Content"] = "这人怎么如此过分！{nickname}，你被他算计，没有受伤吧？！",
            ["ContentKR"] = "어찌 그런 심한 일을! {nickname}, 저자의 계략에 빠져 다치지는 않았느냐?!",
            ["DialogueId"] = 12020306,
            ["GUID"] = "1E177174",
            ["NextDialogue"] = 12020307,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120203/1E177174",
            },
        [12020307] = {
            ["Content"] = "可恶，师兄受那重重规矩束缚，我行事可是无法无天……惹了我，横竖也要让他吃点教训才是！",
            ["ContentKR"] = "빌어먹을. 사형은 그 숨 막히는 규율에 얽매여 있지만, 난 거칠 것이 없는 사람이다! ...그런 날 건드리다니, 어떻게든 저 작자를 혼쭐 내 줘야겠다!",
            ["DialogueId"] = 12020307,
            ["GUID"] = "1E17719E",
            ["NextDialogue"] = 12020308,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120203/1E17719E",
            },
        [12020308] = {
            ["Content"] = "白也看这伙人不爽很久了！我们联手把这里掀翻天吧！",
            ["ContentKR"] = "나도 저 사람 싫은 지 꽤 됐어! 우리 힘을 합쳐서 여길 확 뒤집어 버리자!",
            ["DialogueId"] = 12020308,
            ["GUID"] = "1E1771C8",
            ["NextDialogue"] = 12020309,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120203/1E1771C8",
            },
        [12020309] = {
            ["Content"] = "两位，你们的交谈我可都听见了。我向你们赔礼道歉可好？",
            ["ContentKR"] = "두 사람의 대화는 내가 다 들었다. 내가 사죄라도 하면 되겠나?",
            ["DialogueId"] = 12020309,
            ["GUID"] = "1E1771F2",
            ["NextDialogue"] = 12020310,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120203/1E1771F2",
            },
        [12020310] = {
            ["Content"] = "我劝你少说些话，我的气可还没消。",
            ["ContentKR"] = "난 아직 화가 안 풀렸으니, 조용히 있는 게 나을 거예요.",
            ["DialogueId"] = 12020310,
            ["GUID"] = "1E17721C",
            ["NextDialogue"] = 12020311,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120203/1E17721C",
            },
        [12020311] = {
            ["Content"] = "现在不对你出手，只是因为我不想变成和你一样的渣滓。",
            ["ContentKR"] = "내가 가만히 있는 건, 당신 같은 쓰레기가 되고 싶지 않아서예요.",
            ["DialogueId"] = 12020311,
            ["GUID"] = "1E177246",
            ["NextDialogue"] = 12020312,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120203/1E177246",
            },
        [12020312] = {
            ["Content"] = "好、好，小友宽宏大量。",
            ["ContentKR"] = "좋네, 좋아. 아량이 참 넓구먼.",
            ["DialogueId"] = 12020312,
            ["GUID"] = "1E177270",
            ["NextDialogue"] = 12020313,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120203/1E177270",
            },
        [12020313] = {
            ["Content"] = "小友的义气着实让人动容。虬某心服口服，甘愿担下任务失败的责任，也要卖小友一个面子，放归猎物。之后止掌柜那边，我会去交代。",
            ["ContentKR"] = "실로 감탄스러운 의협심이로군. 이 규 아무개, 진심으로 탄복하여 기꺼이 임무 실패의 책임을 지겠네. 그리고 사냥감은 자네 얼굴을 봐서 풀어 주지. 지류 대방께는 내가 잘 이야기하겠네.",
            ["DialogueId"] = 12020313,
            ["GUID"] = "1E17729A",
            ["NextDialogue"] = 12020314,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120203/1E17729A",
            },
        [12020314] = {
            ["Content"] = "这真是止流掌柜的意思吗？我不信你说的话。还有，我不想再听到“猎物”这个词。",
            ["ContentKR"] = "이게 정말 지류 사장님 뜻인가요? 당신 말은 못 믿어요. 그리고 '사냥감'이란 말, 다시는 듣고 싶지 않고요.",
            ["DialogueId"] = 12020314,
            ["GUID"] = "1E1772C4",
            ["NextDialogue"] = 12020315,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120203/1E1772C4",
            },
        [12020315] = {
            ["Content"] = "哈哈……正如我先前所说，止掌柜自有她的考虑。",
            ["ContentKR"] = "하하... 내가 전에 말했듯이, 지류 대방께는 그분 나름의 생각이 있을 것이네.",
            ["DialogueId"] = 12020315,
            ["GUID"] = "1E1772EE",
            ["NextDialogue"] = 12020316,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120203/1E1772EE",
            },
        [12020316] = {
            ["Content"] = "要不是你们这伙人横插一杠，我和师兄早就重新聚首了！黑瞎子，你欠我的如何赔？",
            ["ContentKR"] = "당신네 무리가 끼어들지만 않았어도, 나와 사형은 벌써 다시 만났을 것이다! 흑곰 양반, 내게 진 빚을 어찌 갚을 셈이냐?",
            ["DialogueId"] = 12020316,
            ["GUID"] = "1E177318",
            ["NextDialogue"] = 12020317,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120203/1E177318",
            },
        [12020317] = {
            ["Content"] = "哦？依我看，那应天尉分明是刻意躲着你。若是他留下，你俩二人联手，在场各位又有谁能抵挡？",
            ["ContentKR"] = "호오? 내가 보기엔, 그 응천위는 분명히 자네를 일부러 피하고 있었네. 만약 그가 남아서 자네 둘이 힘을 합쳤다면, 여기 있는 누가 당해낼 수 있었겠나?",
            ["DialogueId"] = 12020317,
            ["GUID"] = "1E177342",
            ["NextDialogue"] = 12020318,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120203/1E177342",
            },
        [12020318] = {
            ["Content"] = "住口！要你在这边啰嗦！",
            ["ContentKR"] = "닥쳐라! 누가 여기서 함부로 입을 놀려도 좋다고 했느냐!",
            ["DialogueId"] = 12020318,
            ["GUID"] = "1E17736C",
            ["NextDialogue"] = 12020319,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120203/1E17736C",
            },
        [12020319] = {
            ["Content"] = "哈哈哈！",
            ["ContentKR"] = "하하하!",
            ["DialogueId"] = 12020319,
            ["GUID"] = "1E177396",
            ["NextDialogue"] = 12020320,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120203/1E177396",
            },
        [12020320] = {
            ["Content"] = "我还有要事处理，便先行告退。",
            ["ContentKR"] = "나는 아직 처리할 일이 남아있어서, 먼저 실례하겠네.",
            ["DialogueId"] = 12020320,
            ["GUID"] = "1E1773C0",
            ["NextDialogue"] = 12020321,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120203/1E1773C0",
            },
        [12020321] = {
            ["Content"] = "这位朋友，我且提醒你一句。你师兄往那个方向撤离，再不去追怕是又要来不及了。",
            ["ContentKR"] = "이보게 친구. 한마디 일러두지. 자네 사형은 저쪽으로 달아났으니, 어서 뒤쫓지 않으면 또 놓치고 말 걸세.",
            ["DialogueId"] = 12020321,
            ["GUID"] = "1E1773EA",
            ["NextDialogue"] = 12020322,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120203/1E1773EA",
            },
        [12020322] = {
            ["Content"] = "小友，你也听我一句劝告。不是所有人行事都如我这般坦荡。知人知面，未必知心。",
            ["ContentKR"] = "그리고 자네에게도 충고 한마디 하지. 모든 사람이 나처럼 거리낌 없이 행동하는 것은 아닐세. 열 길 물 속은 알아도 한 길 사람 속은 모르는 법이야.",
            ["DialogueId"] = 12020322,
            ["GUID"] = "1E177414",
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120203/1E177414",
            },
        [12020401] = {
            ["Content"] = "他的自恋狂发言又增加了！",
            ["ContentKR"] = "또 저렇게 잘난척하면서 말하네!",
            ["DialogueId"] = 12020401,
            ["Duration"] = 2,
            ["GUID"] = "1E17810A",
            ["NextDialogue"] = 12020402,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120204/1E17810A",
            },
        [12020402] = {
            ["Content"] = "最后那句话到底是什么意思哇？神神秘秘的……",
            ["ContentKR"] = "마지막 말은 또 대체 무슨 뜻이야? 알쏭달쏭하게...",
            ["DialogueId"] = 12020402,
            ["Duration"] = 3,
            ["GUID"] = "1E178134",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120204/1E178134",
            },
        [12020501] = {
            ["Camera"] = "-8.78125,29.299316,151.603027,0.000004,-2.785276,-161.556458,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "唉……",
            ["ContentKR"] = "하아...",
            ["DialogueId"] = 12020501,
            ["FacialId"] = {
                [1] = "210021:Unhappy01",
                },
            ["FinalCamera"] = "-39.296875,19.130371,149.838379,0.000004,-2.785276,-161.556458,35.000008,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1E179172",
            ["LookAt"] = {
                [1] = "100001:n(210021)",
                [2] = "210021:n(100001)",
                },
            ["NextDialogue"] = 12020502,
            ["SpeakNpcId"] = 210021,
            ["TalkActionId"] = {
                [1] = "210021:ScratchHead_Start",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1201/120205/1E179172",
            },
        [12020502] = {
            ["Content"] = "{nickname}，你是不是和师兄挺熟的？",
            ["ContentKR"] = "{nickname}, 혹시 사형과 잘 아는 사이냐?",
            ["DialogueId"] = 12020502,
            ["FacialId"] = {
                [1] = "210021:Think01",
                },
            ["GUID"] = "1E17919C",
            ["NextDialogue"] = 12020503,
            ["SpeakNpcId"] = 210021,
            ["TalkActionId"] = {
                [1] = "210021:ScratchHead_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120205/1E17919C",
            },
        [12020503] = {
            ["Content"] = "师兄成为应天尉是因为一场意外变故。但我能感觉到，他并不开心……",
            ["ContentKR"] = "사형이 응천위가 된 것은 뜻밖의 사고 때문이다. 하지만 내가 느끼기에, 사형은 전혀 행복해 보이지 않아...",
            ["DialogueId"] = 12020503,
            ["FacialId"] = {
                [1] = "210021:Angry01",
                },
            ["GUID"] = "1E1791C6",
            ["NextDialogue"] = 12020504,
            ["SpeakNpcId"] = 210021,
            ["TalkActionId"] = {
                [1] = "210021:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120205/1E1791C6",
            },
        [12020504] = {
            ["Camera"] = "-64.742188,5.019531,189.497314,0.000005,-11.785204,-158.356918,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你下次要是见到他，帮我带一句话，就说当年那件事不怪他，山外山的大家都希望他回来。",
            ["ContentKR"] = "다음에 사형을 만나거든, 내 말 좀 전해다오. 그때 일은 사형 탓이 아니고, 산외산의 모두가 사형이 돌아오길 바란다고 말이다.",
            ["DialogueId"] = 12020504,
            ["GUID"] = "1E1791F0",
            ["NextDialogue"] = 12020505,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120205/1E1791F0",
            },
        [12020505] = {
            ["Camera"] = "-286.9375,-213.182617,178.568115,0.000013,-9.985319,62.043591,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "当年？发生了什么事情？",
            ["ContentKR"] = "그때라니? 무슨 일이 있었던 건데?",
            ["DialogueId"] = 12020505,
            ["FacialId"] = {
                [1] = "100001:Doubt01",
                },
            ["GUID"] = "1E17921A",
            ["NextDialogue"] = 12020506,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "210021:Talk02_End",
                [2] = "100001:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120205/1E17921A",
            },
        [12020506] = {
            ["Camera"] = "-64.742188,5.019531,189.497314,0.000005,-11.785204,-158.356918,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这件事儿挺麻烦的，三言两语说不清楚。我还得赶着去追师兄，下次再和你讲吧。",
            ["ContentKR"] = "그 일은 꽤 복잡해서, 한두 마디로 설명하기 어렵다. 난 아직 사형을 뒤쫓아야 하니, 다음에 다시 이야기해 주마.",
            ["DialogueId"] = 12020506,
            ["FacialId"] = {
                [1] = "210021:Uninterested01",
                },
            ["GUID"] = "1E179244",
            ["NextDialogue"] = 12020507,
            ["SpeakNpcId"] = 210021,
            ["TalkActionId"] = {
                [1] = "210021:Talk01_Start",
                [2] = "100001:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120205/1E179244",
            },
        [12020507] = {
            ["Camera"] = "254.949219,-102.718262,275.353027,0.000008,-18.585285,170.644135,30.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "{nickname}，你说，人活在这世上，为何不能随性所动，兴致来了便做自己想做的。偏偏要受这么多约束呢？",
            ["ContentKR"] = "{nickname}, 너는 어찌 보느냐? 이 세상을 살아가며, 마음 가는 대로 하고 싶은 일을 하면서 살면 안 되는 것이냐? 어찌하여 이리 많은 것에 얽매여야 한단 말이냐?",
            ["DialogueId"] = 12020507,
            ["FacialId"] = {
                [1] = "210021:Unhappy01",
                },
            ["FinalCamera"] = "465.136719,-137.344727,314.913086,0.000008,-18.585264,170.644104,30.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1E17926E",
            ["NextDialogue"] = 12020508,
            ["SpeakNpcId"] = 210021,
            ["TalkActionId"] = {
                [1] = "210021:DisagreeHead",
                },
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/1201/120205/1E17926E",
            },
        [12020508] = {
            ["Camera"] = "-8.78125,29.299316,151.603027,0.000004,-2.785276,-161.556458,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我得走了。别忘了我们的约定啊！下次见面，可得把盏言欢，畅谈至尽兴才行！",
            ["ContentKR"] = "난 이제 가봐야겠다. 약속 잊지 말아라! 다음에 만나면, 술잔을 나누며 밤새도록 이야기꽃을 피워 보는 거다!",
            ["DialogueId"] = 12020508,
            ["FacialId"] = {
                [1] = "210021:Smile01",
                },
            ["GUID"] = "1E179298",
            ["SpeakNpcId"] = 210021,
            ["TalkActionId"] = {
                [1] = "210021:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120205/1E179298",
            },
        [12020601] = {
            ["Content"] = "感觉出来逛了好久，不知道止流那边怎么样了……",
            ["ContentKR"] = "꽤 돌아다닌 것 같은데, 지류 사장님 쪽은 어떻게 됐을까...",
            ["DialogueId"] = 12020601,
            ["Duration"] = 3,
            ["GUID"] = "1E17A1DA",
            ["NextDialogue"] = 12020602,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120206/1E17A1DA",
            },
        [12020602] = {
            ["Content"] = "小仆从，我们回百年春看看吧！",
            ["ContentKR"] = "시종, 우리 백년춘으로 돌아가 보자!",
            ["DialogueId"] = 12020602,
            ["Duration"] = 2,
            ["GUID"] = "1E17A204",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120206/1E17A204",
            },
        [12020701] = {
            ["Camera"] = "428.589844,98.277344,126.54541,0.0,0.0,-179.794739,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这个动静……发生什么事情了吗？",
            ["ContentKR"] = "이 소란은... 무슨 일이라도 생긴 건가?",
            ["DialogueId"] = 12020701,
            ["GUID"] = "1E17B242",
            ["NextDialogue"] = 12020702,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120207/1E17B242",
            },
        [12020702] = {
            ["Content"] = "看来，是大当家在烛阴祭坛的布置已经完成了。",
            ["ContentKR"] = "아무래도, 대방님께서 촉룡 제단에서 준비를 마치신 모양입니다.",
            ["DialogueId"] = 12020702,
            ["GUID"] = "1E17B26C",
            ["NextDialogue"] = 12020703,
            ["RelatedWikiId"] = {
                [1] = 408015,
                [2] = 303011,
                },
            ["SpeakNpcId"] = 210022,
            ["VoiceName"] = "voice/$Locale$/story/1201/120207/1E17B26C",
            },
        [12020703] = {
            ["Content"] = "她曾嘱咐过，若您来寻她，让您在大厅静候。等到事成之后，她会回来见您。",
            ["ContentKR"] = "대방님께서 일전에, 혹시 {nickname} 씨가 돌아와서 대방님을 찾는다면, 우선 응접실에서 기다리게 하라고 당부하셨습니다. 일이 끝나면 만나시겠다면서요.",
            ["DialogueId"] = 12020703,
            ["GUID"] = "1E17B296",
            ["NextDialogue"] = 12020704,
            ["SpeakNpcId"] = 210022,
            ["VoiceName"] = "voice/$Locale$/story/1201/120207/1E17B296",
            },
        [12020704] = {
            ["Content"] = "等等，不需要我们去帮忙吗？！",
            ["ContentKR"] = "잠깐만, 우리가 도울 필요는 없어?!",
            ["DialogueId"] = 12020704,
            ["GUID"] = "1E17B2C0",
            ["NextDialogue"] = 12020705,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120207/1E17B2C0",
            },
        [12020705] = {
            ["Content"] = "封印烛阴之行险阻重重，你们若是前去，可能会受伤……",
            ["ContentKR"] = "촉룡을 봉인하는 건 굉장히 위험한 일입니다. 두 사람이 거기 갔다간, 다칠지도 모르고…",
            ["DialogueId"] = 12020705,
            ["GUID"] = "1E17B2EA",
            ["NextDialogue"] = 12020706,
            ["SpeakNpcId"] = 210022,
            ["VoiceName"] = "voice/$Locale$/story/1201/120207/1E17B2EA",
            },
        [12020706] = {
            ["Content"] = "吼——",
            ["ContentKR"] = "크르르릉!",
            ["DialogueId"] = 12020706,
            ["GUID"] = "1E17B314",
            ["NextDialogue"] = 12020707,
            ["VoiceName"] = "voice/$Locale$/story/1201/120207/1E17B314",
            },
        [12020707] = {
            ["Content"] = "那边的情况听起来不太妙。让我们去吧，多一个人就是多一份助力。",
            ["ContentKR"] = "아무래도 상황이 심상치 않은 것 같아요. 돕게 해 주세요. 머릿수는 많을수록 좋잖아요.",
            ["DialogueId"] = 12020707,
            ["GUID"] = "1E17B33E",
            ["NextDialogue"] = 12020708,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120207/1E17B33E",
            },
        [12020708] = {
            ["Content"] = "但，大当家的嘱咐……",
            ["ContentKR"] = "하지만, 대방님의 분부가...",
            ["DialogueId"] = 12020708,
            ["GUID"] = "1E17B368",
            ["NextDialogue"] = 12020709,
            ["SpeakNpcId"] = 210022,
            ["VoiceName"] = "voice/$Locale$/story/1201/120207/1E17B368",
            },
        [12020709] = {
            ["Content"] = "哎呀，都到这种时候了，你还在犹豫什么！",
            ["ContentKR"] = "아이, 참! 이럴 때 뭘 그렇게 망설이는 거야!",
            ["DialogueId"] = 12020709,
            ["GUID"] = "1E17B392",
            ["NextDialogue"] = 12020710,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120207/1E17B392",
            },
        [12020710] = {
            ["Content"] = "……我明白了。您可以去尘漠石海最高处的位置，那里通往烛阴祭坛的临时道路已经搭建完毕。",
            ["ContentKR"] = "...알겠습니다. 낙진의 바다 가장 높은 곳으로 가면, 촉룡 제단으로 가는 임시 통로가 마련돼 있을 겁니다.",
            ["DialogueId"] = 12020710,
            ["GUID"] = "1E17B3BC",
            ["NextDialogue"] = 12020711,
            ["SpeakNpcId"] = 210022,
            ["VoiceName"] = "voice/$Locale$/story/1201/120207/1E17B3BC",
            },
        [12020711] = {
            ["Content"] = "白嗅到了征服恶龙的决战气息……等等，怎么听起来不像是魔王该干的事情？！",
            ["ContentKR"] = "이 스노우 님이 사악한 용을 쓰러뜨릴 결전의 기운을 감지했다, 이거야! ...잠깐, 이거 마왕이 할 일은 아닌 것 같은데?!",
            ["DialogueId"] = 12020711,
            ["GUID"] = "1E17B3E6",
            ["NextDialogue"] = 12020712,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120207/1E17B3E6",
            },
        [12020712] = {
            ["Content"] = "……我们赶快过去吧。",
            ["ContentKR"] = "...어서 가 보자.",
            ["DialogueId"] = 12020712,
            ["GUID"] = "1E17B410",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120207/1E17B410",
            },
        [12020901] = {
            ["Camera"] = "-78.574219,498.462891,113.020996,0.000014,-0.99994,-74.596542,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "呼……千钧一发之际，险险成功了。",
            ["ContentKR"] = "휴... 아슬아슬한 순간에, 간신히 성공했군요.",
            ["DialogueId"] = 12020901,
            ["GUID"] = "1E17D312",
            ["NextDialogue"] = 12020902,
            ["RelatedWikiId"] = {
                [1] = 408015,
                [2] = 303011,
                },
            ["SpeakNpcId"] = 210005,
            ["SpeakNpcName"] = "UI_Npc_Name_Goodshangren",
            ["VoiceName"] = "voice/$Locale$/story/1201/120209/1E17D312",
            },
        [12020902] = {
            ["Content"] = "还不能松懈，我能感受到上方的封印尚不稳固。",
            ["ContentKR"] = "아직 방심할 수 없어요. 위쪽의 봉인이 아직 불안정한 게 느껴집니다.",
            ["DialogueId"] = 12020902,
            ["GUID"] = "1E17D33C",
            ["NextDialogue"] = 12020903,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120209/1E17D33C",
            },
        [12020903] = {
            ["Content"] = "我要维持此处阵眼，暂时无法抽身。你们谁能上去检查一下吗？",
            ["ContentKR"] = "저는 이 진형의 중심을 유지해야 하여 잠시 자리를 비울 수 없습니다. 올라가서 봉인을 확인해 주실 분 없으십니까?",
            ["DialogueId"] = 12020903,
            ["GUID"] = "1E17D366",
            ["NextDialogue"] = 12020904,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120209/1E17D366",
            },
        [12020904] = {
            ["Content"] = "止流掌柜，我去吧。",
            ["ContentKR"] = "지류 사장님, 제가 갈게요.",
            ["DialogueId"] = 12020904,
            ["GUID"] = "1E17D390",
            ["NextDialogue"] = 12020905,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120209/1E17D390",
            },
        [12020905] = {
            ["Content"] = "……{nickname}，怎么是你？",
            ["ContentKR"] = "…{nickname}, 네가 어떻게 여기에…?",
            ["DialogueId"] = 12020905,
            ["GUID"] = "1E17D3BA",
            ["NextDialogue"] = 12020906,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120209/1E17D3BA",
            },
        [12020906] = {
            ["Content"] = "你们的工作已经完成了。我分明嘱咐过望春，让你们在商会等候我归来即可。",
            ["ContentKR"] = "두 사람 일은 이미 끝났어. 내가 돌아올 때까지 상회에서 기다리라고, 춘망에게 분명히 전해 뒀을 텐데.",
            ["DialogueId"] = 12020906,
            ["GUID"] = "1E17D3E4",
            ["NextDialogue"] = 12020907,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120209/1E17D3E4",
            },
        [12020907] = {
            ["Content"] = "这里的动静太大，我放心不下来。不如来看看能做些什么。",
            ["ContentKR"] = "이곳 상황이 너무 심각해 보여서, 마음이 놓이지 않았어요. 혹시 제가 도울 수 있는 일이 있을까 해서요.",
            ["DialogueId"] = 12020907,
            ["GUID"] = "1E17D40E",
            ["NextDialogue"] = 12020908,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120209/1E17D40E",
            },
        [12020908] = {
            ["Content"] = "这就是我们狩月人倾情提供的售后服务，包老板满意！",
            ["ContentKR"] = "이건 우리 월석 사냥꾼들이 성심을 다해 제공하는 애프터서비스라고! 100% 만족할 거야!",
            ["DialogueId"] = 12020908,
            ["GUID"] = "1E17D438",
            ["NextDialogue"] = 12020909,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120209/1E17D438",
            },
        [12020909] = {
            ["Content"] = "您就放一百个心吧，止掌柜。{nickname}身手可灵活了，尤其擅长旋转跳跃，多高的障碍都不在话下！",
            ["ContentKR"] = "아주 그냥 마음 푹 놓으시라니까, 지류 사장님! {nickname} 말이야, 몸놀림이 아주 끝내줘. 특히 빙글빙글 돌면서 뛰어오르는 건 완전 선수급이라고! 아무리 높은 장애물도 문제없다니까!",
            ["DialogueId"] = 12020909,
            ["GUID"] = "1E17D462",
            ["NextDialogue"] = 12020910,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120209/1E17D462",
            },
        [12020910] = {
            ["Content"] = "若是你们坚持……",
            ["ContentKR"] = "정 그렇다면... 할 수 없지.",
            ["DialogueId"] = 12020910,
            ["GUID"] = "1E17D48C",
            ["NextDialogue"] = 12020911,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120209/1E17D48C",
            },
        [12020911] = {
            ["Content"] = "{nickname}，拿住这枚铜钱。将它放至烛阴的额首处，剩下的我会操作。",
            ["ContentKR"] = "{nickname}, 이 동전을 받아. 그걸 촉룡의 이마에 놓으면, 나머지는 내가 처리하지.",
            ["DialogueId"] = 12020911,
            ["GUID"] = "1E17D4B6",
            ["NextDialogue"] = 12020912,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120209/1E17D4B6",
            },
        [12020912] = {
            ["Content"] = "当心，别受伤了。",
            ["ContentKR"] = "다치지 않도록 조심해.",
            ["DialogueId"] = 12020912,
            ["GUID"] = "1E17D4E0",
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120209/1E17D4E0",
            },
        [12020913] = {
            ["Content"] = "杜立，先带着伤者下去吧。",
            ["ContentKR"] = "두립, 일단 부상자를 데리고 가죠.",
            ["DialogueId"] = 12020913,
            ["GUID"] = "1E13468F",
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120138/1E13468F",
            },
        [12020914] = {
            ["Content"] = "是，大当家！",
            ["ContentKR"] = "네, 대방님!",
            ["DialogueId"] = 12020914,
            ["GUID"] = "1E134691",
            ["SpeakNpcId"] = 210004,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Duli",
            ["VoiceName"] = "voice/$Locale$/story/1201/120138/1E134691",
            },
        [12021001] = {
            ["Content"] = "魂兮游离，北狩荒秽……彼我烛阴，罹殃千岁……",
            ["ContentKR"] = "혼이여 떠돌며, 북녘 황무지를 헤매는구나... 그대와 나 촉룡이여, 천년의 재앙을 입었도다...",
            ["DialogueId"] = 12021001,
            ["Duration"] = 2,
            ["GUID"] = "1E17E37A",
            ["NextDialogue"] = 12021002,
            ["SnapShot"] = "ECHO",
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1201/120210/1E17E37A",
            },
        [12021002] = {
            ["Content"] = "（……！又出现了，先前在尘漠石海听到的那个声音。）",
            ["ContentKR"] = "(...! 또야, 아까 낙진의 바다에서 들었던 그 목소리.)",
            ["DialogueId"] = 12021002,
            ["Duration"] = 2,
            ["GUID"] = "1E17E3A4",
            ["NextDialogue"] = 12021003,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120210/1E17E3A4",
            },
        [12021003] = {
            ["Content"] = "（果然，这就是烛阴的呓语吗？）",
            ["ContentKR"] = "(역시, 이건 촉룡의 잠꼬대였던 건가?)",
            ["DialogueId"] = 12021003,
            ["Duration"] = 2,
            ["GUID"] = "1E17E3CE",
            ["NextDialogue"] = 12021004,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120210/1E17E3CE",
            },
        [12021004] = {
            ["Content"] = "怎么了，{nickname}？",
            ["ContentKR"] = "왜 그래, {nickname}?",
            ["DialogueId"] = 12021004,
            ["Duration"] = 2,
            ["GUID"] = "1E17E3F8",
            ["NextDialogue"] = 12021005,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120210/1E17E3F8",
            },
        [12021005] = {
            ["Content"] = "不，没什么……",
            ["ContentKR"] = "아, 아무것도 아니에요...",
            ["DialogueId"] = 12021005,
            ["Duration"] = 2,
            ["GUID"] = "1E17E422",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120210/1E17E422",
            },
        [12021201] = {
            ["Content"] = "魂魄佚散，畴昔倾颓……荒忽焉极，循时索归……",
            ["ContentKR"] = "혼백은 흩어지고, 지난날은 무너졌네... 아득한 그 끝에서, 때를 따라 돌아갈 곳을 찾는구나...",
            ["DialogueId"] = 12021201,
            ["Duration"] = 2,
            ["GUID"] = "1E18044A",
            ["NextDialogue"] = 12021202,
            ["SnapShot"] = "ECHO",
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1201/120212/1E18044A",
            },
        [12021202] = {
            ["Content"] = "（烛阴的声音，越来越清晰了……）",
            ["ContentKR"] = "(촉룡의 목소리가, 점점 더 선명해지고 있어...)",
            ["DialogueId"] = 12021202,
            ["Duration"] = 2,
            ["GUID"] = "1E180474",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120212/1E180474",
            },
        [12021301] = {
            ["Content"] = "……汝乃何人？",
            ["ContentKR"] = "...그대는 누구인가?",
            ["DialogueId"] = 12021301,
            ["Duration"] = 2,
            ["GUID"] = "1E1814B2",
            ["SnapShot"] = "ECHO",
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1201/120213/1E1814B2",
            },
        [12021302] = {
            ["Content"] = "汝亦是来加害于吾乎？",
            ["ContentKR"] = "그대 또한 나를 해하러 왔는가?",
            ["DialogueId"] = 12021302,
            ["Duration"] = 2,
            ["GUID"] = "1E1814DC",
            ["SnapShot"] = "ECHO",
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1201/120213/1E1814DC",
            },
        [12021303] = {
            ["Content"] = "不好，它发狂了！小仆从！！！",
            ["ContentKR"] = "이런, 완전히 날뛰고 있어! 시종!!!",
            ["DialogueId"] = 12021303,
            ["Duration"] = 2,
            ["GUID"] = "1E181506",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120213/1E181506",
            },
        [12021304] = {
            ["Content"] = "听得到我的声音吗？你是不是想对我们说什么？",
            ["ContentKR"] = "제 목소리 들려요? 저희에게 뭔가 하고 싶은 말이 있는 거 아니에요?",
            ["DialogueId"] = 12021304,
            ["Duration"] = 4,
            ["GUID"] = "1E181530",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120213/1E181530",
            },
        [12021305] = {
            ["Content"] = "吼————",
            ["ContentKR"] = "크르르르릉!",
            ["DialogueId"] = 12021305,
            ["Duration"] = 2,
            ["GUID"] = "1E18155A",
            ["SnapShot"] = "ECHO",
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1201/120213/1E18155A",
            },
        [12021306] = {
            ["Content"] = "烛阴已力竭了。",
            ["ContentKR"] = "촉룡은 힘이 다했어.",
            ["DialogueId"] = 12021306,
            ["Duration"] = 2,
            ["GUID"] = "1E181584",
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120213/1E181584",
            },
        [12021307] = {
            ["Content"] = "最后一击，要拜托你了，{nickname}。",
            ["ContentKR"] = "마지막 일격은 {nickname}에게 부탁할게.",
            ["DialogueId"] = 12021307,
            ["Duration"] = 4,
            ["GUID"] = "1E1815AE",
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120213/1E1815AE",
            },
        [12022001] = {
            ["Content"] = "——至此，大风九章已成！",
            ["ContentKR"] = "——이로써, 대풍구장이 완성되었노라!",
            ["DialogueId"] = 12022001,
            ["GUID"] = "1E18878A",
            ["NextDialogue"] = 12022002,
            ["RelatedWikiId"] = {
                [1] = 304003,
                [2] = 303008,
                [3] = 303011,
                },
            ["SnapShot"] = "MEMORY",
            ["VoiceName"] = "voice/$Locale$/story/1201/120220/1E18878A",
            },
        [12022002] = {
            ["Content"] = "华胥黎庶，自兹以往，将永离战乱之苦，无受纷争之扰！",
            ["ContentKR"] = "화서의 만백성은, 이로부터 영원히 전란의 고통에서 벗어나고, 분쟁의 근심에서 해방될 것이니라!",
            ["DialogueId"] = 12022002,
            ["GUID"] = "1E1887B4",
            ["NextDialogue"] = 12022003,
            ["SnapShot"] = "MEMORY",
            ["VoiceName"] = "voice/$Locale$/story/1201/120220/1E1887B4",
            },
        [12022003] = {
            ["Content"] = "太皓，执理。烛阴，执心。",
            ["ContentKR"] = "태호는 이치를 관장하고, 촉룡은 마음을 관장하노라.",
            ["DialogueId"] = 12022003,
            ["GUID"] = "1E1887DE",
            ["NextDialogue"] = 12022004,
            ["SnapShot"] = "MEMORY",
            ["VoiceName"] = "voice/$Locale$/story/1201/120220/1E1887DE",
            },
        [12022004] = {
            ["Content"] = "二位尊神，将共御大风九章，庇佑苍生，护万世安泰——",
            ["ContentKR"] = "두 신께서, 함께 대풍구장을 다스리시어 만백성을 보살피고 만세의 안녕을 지키실 것이니라——",
            ["DialogueId"] = 12022004,
            ["GUID"] = "1E188808",
            ["NextDialogue"] = 12022005,
            ["SnapShot"] = "MEMORY",
            ["VoiceName"] = "voice/$Locale$/story/1201/120220/1E188808",
            },
        [12022005] = {
            ["Content"] = "心为一切混乱之肇始！",
            ["ContentKR"] = "마음은 모든 혼란의 시작이다!",
            ["DialogueId"] = 12022005,
            ["GUID"] = "1E188832",
            ["NextDialogue"] = 12022006,
            ["SnapShot"] = "MEMORY",
            ["VoiceName"] = "voice/$Locale$/story/1201/120220/1E188832",
            },
        [12022006] = {
            ["Content"] = "我泱泱华胥，卷入如今兵戈之乱，全因人心混沌所起！",
            ["ContentKR"] = "우리 드넓은 화서가 지금의 병란에 휘말린 것은, 모두 인심이 혼란한 탓이로다!",
            ["DialogueId"] = 12022006,
            ["GUID"] = "1E18885C",
            ["NextDialogue"] = 12022007,
            ["SnapShot"] = "MEMORY",
            ["VoiceName"] = "voice/$Locale$/story/1201/120220/1E18885C",
            },
        [12022007] = {
            ["Content"] = "今日，烛阴必须受封印。",
            ["ContentKR"] = "오늘, 촉룡은 반드시 봉인되어야 한다.",
            ["DialogueId"] = 12022007,
            ["GUID"] = "1E188886",
            ["NextDialogue"] = 12022008,
            ["SnapShot"] = "MEMORY",
            ["VoiceName"] = "voice/$Locale$/story/1201/120220/1E188886",
            },
        [12022008] = {
            ["Content"] = "唯有不受干扰之理，方有资格执掌统御之法！",
            ["ContentKR"] = "오직 방해받지 않는 이치만이, 통치의 법을 관장할 자격이 있느니라!",
            ["DialogueId"] = 12022008,
            ["GUID"] = "1E1888B0",
            ["NextDialogue"] = 12022009,
            ["SnapShot"] = "MEMORY",
            ["VoiceName"] = "voice/$Locale$/story/1201/120220/1E1888B0",
            },
        [12022009] = {
            ["Content"] = "此举不可！倘若心、理失衡， 后患无穷尽也！",
            ["ContentKR"] = "아니 될 일이오! 만약 마음과 이치가 균형을 잃으면, 그 후환은 끝이 없을 것이오!",
            ["DialogueId"] = 12022009,
            ["GUID"] = "1E1888DA",
            ["NextDialogue"] = 12022010,
            ["SnapShot"] = "MEMORY",
            ["VoiceName"] = "voice/$Locale$/story/1201/120220/1E1888DA",
            },
        [12022010] = {
            ["Content"] = "退下！休要坏了正事！",
            ["ContentKR"] = "물러가라! 중요한 일을 망치려 들지 마라!",
            ["DialogueId"] = 12022010,
            ["GUID"] = "1E188904",
            ["NextDialogue"] = 12022011,
            ["SnapShot"] = "MEMORY",
            ["VoiceName"] = "voice/$Locale$/story/1201/120220/1E188904",
            },
        [12022011] = {
            ["Content"] = "自尔后数百载，玄色狴犴生，灾祸暗起……今日之果，皆为当日之因呐！",
            ["ContentKR"] = "그 후 수백 년 동안, 검은 폐안이 생겨나고 재앙이 남몰래 시작되었으니… 오늘의 결과는, 모두 그날의 원인 때문이다!",
            ["DialogueId"] = 12022011,
            ["GUID"] = "1E18892E",
            ["NextDialogue"] = 12022012,
            ["SnapShot"] = "MEMORY",
            ["VoiceName"] = "voice/$Locale$/story/1201/120220/1E18892E",
            },
        [12022012] = {
            ["Content"] = "夫烛阴者，由心而生。人心不灭，烛阴如何能灭？",
            ["ContentKR"] = "무릇 촉룡이란, 마음에서 생겨나는 법. 사람의 마음이 사라지지 않는데, 촉룡이 어찌 사라지겠는가?",
            ["DialogueId"] = 12022012,
            ["GUID"] = "1E188958",
            ["NextDialogue"] = 12022013,
            ["SnapShot"] = "MEMORY",
            ["VoiceName"] = "voice/$Locale$/story/1201/120220/1E188958",
            },
        [12022013] = {
            ["Content"] = "以秘术暂封之，如扬汤止沸。俟烛阴挣脱封印，附骨之疽，必酿大患！",
            ["ContentKR"] = "비술로 봉인하는 것은, 끓는 솥에 물 한 바가지 붓는 것일 뿐, 솥이 다시 끓어오르는 것을 막을 수 없다. 촉룡은 봉인을 깨뜨리고 나와 큰 재앙을 초래할 것이다!",
            ["DialogueId"] = 12022013,
            ["GUID"] = "1E188982",
            ["NextDialogue"] = 12022014,
            ["SnapShot"] = "MEMORY",
            ["VoiceName"] = "voice/$Locale$/story/1201/120220/1E188982",
            },
        [12022014] = {
            ["Content"] = "……孰离合兮可为，蹇谁留兮他乡？",
            ["ContentKR"] = "...영원히 이지러지지 않았으면 좋으련만, 그 누가 만남과 헤어짐을 뜻대로 할 수 있으리오.",
            ["DialogueId"] = 12022014,
            ["GUID"] = "1E1889AC",
            ["NextDialogue"] = 12022015,
            ["SnapShot"] = "ECHO",
            ["SpeakNpcName"] = "UI_CMName_Name_ZhuYing",
            ["VoiceName"] = "voice/$Locale$/story/1201/120220/1E1889AC",
            },
        [12022015] = {
            ["Content"] = "烛阴，刚刚那些是你的记忆吗？！你究竟想告诉我什么？",
            ["ContentKR"] = "촉룡, 방금 그건 당신의 기억인가요?! 대체 제게 뭘 말하고 싶은 거죠?",
            ["DialogueId"] = 12022015,
            ["GUID"] = "1E1889D6",
            ["NextDialogue"] = 12022016,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120220/1E1889D6",
            },
        [12022016] = {
            ["Content"] = "万事已矣，不可复挽矣。天下将趋不可避之大祸……",
            ["ContentKR"] = "모든 것은 이미 되돌릴 수 없게 되었구나. 천하가 피할 수 없는 큰 재앙으로 치닫게 될 것이야...",
            ["DialogueId"] = 12022016,
            ["GUID"] = "1E188A00",
            ["SnapShot"] = "ECHO",
            ["SpeakNpcName"] = "UI_CMName_Name_ZhuYing",
            ["VoiceName"] = "voice/$Locale$/story/1201/120220/1E188A00",
            },
        [12022101] = {
            ["Camera"] = "-78.574219,498.462891,113.020996,0.000014,-0.99994,-74.596542,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "小仆从，你没事吧？",
            ["ContentKR"] = "시종, 괜찮아?",
            ["DialogueId"] = 12022101,
            ["GUID"] = "1E1897F2",
            ["NextDialogue"] = 12022102,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120221/1E1897F2",
            },
        [12022102] = {
            ["Content"] = "没事。我好像看到了一些……画面。",
            ["ContentKR"] = "괜찮아. 뭔가... 장면들을 본 것 같아.",
            ["DialogueId"] = 12022102,
            ["GUID"] = "1E18981C",
            ["NextDialogue"] = 12022103,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120221/1E18981C",
            },
        [12022103] = {
            ["Content"] = "诸位，趁它被束缚住，赶紧发动攻击！能否拿下便在此一举了！",
            ["ContentKR"] = "여러분, 촉룡이 속박된 틈에 서둘러 공격하세요! 성공 여부는 이 공격에 달려 있습니다!",
            ["DialogueId"] = 12022103,
            ["GUID"] = "1E189846",
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120221/1E189846",
            },
        [12022201] = {
            ["Content"] = "等等！",
            ["ContentKR"] = "잠깐만요!",
            ["DialogueId"] = 12022201,
            ["GUID"] = "1E18A85A",
            ["NextDialogue"] = 12022202,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120222/1E18A85A",
            },
        [12022202] = {
            ["Content"] = "就在刚刚，我好像从烛阴的记忆中瞥见了一些大风九章的内情……或许会和烛阴之灾有关！",
            ["ContentKR"] = "방금, 촉룡의 기억 속에서 대풍구장의 내막 일부를 엿본 것 같아요... 어쩌면 촉룡의 재앙과 관련이 있을지도 몰라요!",
            ["DialogueId"] = 12022202,
            ["GUID"] = "1E18A884",
            ["NextDialogue"] = 12022203,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120222/1E18A884",
            },
        [12022203] = {
            ["Content"] = "我们也许可以和它谈谈！如果能平息它的愤怒，或许我们不必与它为敌！",
            ["ContentKR"] = "한번 이야기해 볼 수도 있잖아요! 만약 그 분노를 가라앉힐 수 있다면, 굳이 적대할 필요가 없을지도 몰라요!",
            ["DialogueId"] = 12022203,
            ["GUID"] = "1E18A8AE",
            ["NextDialogue"] = 12022204,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120222/1E18A8AE",
            },
        [12022204] = {
            ["Content"] = "不必了。",
            ["ContentKR"] = "그럴 필요 없어.",
            ["DialogueId"] = 12022204,
            ["GUID"] = "1E18A8D8",
            ["NextDialogue"] = 12022205,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120222/1E18A8D8",
            },
        [12022205] = {
            ["Content"] = "看你的反应……你早就知道？",
            ["ContentKR"] = "그 반응은... 이미 다 알고 있었던 건가요?",
            ["DialogueId"] = 12022205,
            ["GUID"] = "1E18A902",
            ["NextDialogue"] = 12022206,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120222/1E18A902",
            },
        [12022206] = {
            ["Content"] = "你窥见的或许为真……可那又怎样？",
            ["ContentKR"] = "네가 엿본 것이 사실일지도 몰라... 하지만 그게 뭐 어떻다는 거지?",
            ["DialogueId"] = 12022206,
            ["GUID"] = "1E18A92C",
            ["NextDialogue"] = 12022207,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120222/1E18A92C",
            },
        [12022207] = {
            ["Content"] = "<H>白龙神君</>的时代，该结束了。而我，将执起祂的权柄。",
            ["ContentKR"] = "<H>백룡신군</>의 시대는, 이제 끝나야 해. 그리고 내가, 그 권능을 이어받겠어.",
            ["DialogueId"] = 12022207,
            ["GUID"] = "1E18A956",
            ["NextDialogue"] = 12022208,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120222/1E18A956",
            },
        [12022208] = {
            ["Content"] = "什么……",
            ["ContentKR"] = "그게 무슨...",
            ["DialogueId"] = 12022208,
            ["GUID"] = "1E18A980",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120222/1E18A980",
            },
        [12022209] = {
            ["Content"] = "真是遗憾……若不是事急从权，也不必对你用这种手段。",
            ["ContentKR"] = "참으로 안타깝군... 급박한 상황만 아니라면, 네게 이런 수단을 쓸 필요도 없었을 텐데.",
            ["DialogueId"] = 12022209,
            ["GUID"] = "1E18A9AA",
            ["NextDialogue"] = 12022210,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120222/1E18A9AA",
            },
        [12022210] = {
            ["Content"] = "……止流！！放我出去！",
            ["ContentKR"] = "...지류 사장님! 내보내 주세요!",
            ["DialogueId"] = 12022210,
            ["GUID"] = "1E18A9D4",
            ["NextDialogue"] = 12022211,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120222/1E18A9D4",
            },
        [12022211] = {
            ["Content"] = "秦虬先前对我说，你一片赤子之心，怕会影响到计划的实行。",
            ["ContentKR"] = "규선생이 그러더군. 네가 너무 순수해서, 계획에 차질을 빚을까 염려된다고.",
            ["DialogueId"] = 12022211,
            ["GUID"] = "1E18A9FE",
            ["NextDialogue"] = 12022212,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120222/1E18A9FE",
            },
        [12022212] = {
            ["Content"] = "我特意把你支走，未想到你还是来了。",
            ["ContentKR"] = "일부러 다른 곳으로 보냈는데, 결국은 오고 말았네.",
            ["DialogueId"] = 12022212,
            ["GUID"] = "1E18AA28",
            ["NextDialogue"] = 12022213,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120222/1E18AA28",
            },
        [12022213] = {
            ["Content"] = "在冰湖城和你相处的那段日子，确实是难得的闲暇时光，如一梦黄粱。",
            ["ContentKR"] = "아이스레이크 시티에서 너와 보냈던 시간은, 참으로 보기 드문 한가로운 시간이었어. 한바탕 꿈만 같았지.",
            ["DialogueId"] = 12022213,
            ["GUID"] = "1E18AA52",
            ["NextDialogue"] = 12022214,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120222/1E18AA52",
            },
        [12022214] = {
            ["Content"] = "倘若你没有恰好出现在这里，就好了。我们还能如往常一样谈天说笑。",
            ["ContentKR"] = "만약 네가 여기 나타나지 않았더라면 좋았을 거야. 그랬다면 우리는 여전히 평소처럼 웃으며 이야기 나눌 수 있었을 테니까.",
            ["DialogueId"] = 12022214,
            ["GUID"] = "1E18AA7C",
            ["NextDialogue"] = 12022215,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120222/1E18AA7C",
            },
        [12022215] = {
            ["Content"] = "可惜商人的行事准则里，不存在如果。",
            ["ContentKR"] = "안타깝게도, 상인의 행동 원칙에 '만약'이란 존재하지 않아.",
            ["DialogueId"] = 12022215,
            ["GUID"] = "1E18AAA6",
            ["NextDialogue"] = 12022216,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120222/1E18AAA6",
            },
        [12022216] = {
            ["Content"] = "你到底想做什么……",
            ["ContentKR"] = "대체 뭘 하려는...",
            ["DialogueId"] = 12022216,
            ["GUID"] = "1E18AAD0",
            ["NextDialogue"] = 12022217,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120222/1E18AAD0",
            },
        [12022217] = {
            ["Content"] = "嘘——这是为你好。虽然，可能不是以你喜欢的方式。",
            ["ContentKR"] = "쉿—— 이건 널 위한 거야. 비록, 네가 좋아하는 방식은 아닐지도 모르지만.",
            ["DialogueId"] = 12022217,
            ["GUID"] = "1E18AAFA",
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120222/1E18AAFA",
            },
        [12022219] = {
            ["Content"] = "（逐渐扭曲的嘶鸣声）",
            ["ContentKR"] = "(점점 뒤틀리는 울음소리)",
            ["DialogueId"] = 12022219,
            ["GUID"] = "1E18AB4E",
            ["VoiceName"] = "voice/$Locale$/story/1201/120222/1E18AB4E",
            },
        [12022220] = {
            ["Content"] = "喂，这里发生什么了？——放开{性别：他|她}！",
            ["ContentKR"] = "아니, 무슨 일이 일어난 것이냐? 어서 {性别:공자|소저}를 풀어 주어라!",
            ["DialogueId"] = 12022220,
            ["GUID"] = "1E18AB78",
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120222/1E18AB78",
            },
        [12022221] = {
            ["Content"] = "啧，撤。",
            ["ContentKR"] = "쯧, 철수.",
            ["DialogueId"] = 12022221,
            ["GUID"] = "1E18AB79",
            ["VoiceName"] = "voice/$Locale$/story/1201/120222/1E18AB79",
            },
        [12022250] = {
            ["Content"] = "一段时间后……",
            ["ContentKR"] = "잠시 후...",
            ["DialogueId"] = 12022250,
            ["GUID"] = "1E18AB8A",
            },
        [12022301] = {
            ["Camera"] = "-78.574219,498.462891,113.020996,0.000014,-0.99994,-74.596542,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "{nickname}，你受伤了吗？",
            ["ContentKR"] = "{nickname} 씨, 다쳤어요?",
            ["DialogueId"] = 12022301,
            ["GUID"] = "1E18B8C2",
            ["NextDialogue"] = 12022302,
            ["RelatedWikiId"] = {
                [1] = 203001,
                [2] = 203006,
                [3] = 203007,
                },
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18B8C2",
            },
        [12022302] = {
            ["Content"] = "深呼吸，排清杂念，我来为你调养。",
            ["ContentKR"] = "숨을 깊게 쉬고, 정신을 집중해요. 제가 몸 상태를 호전시켜 줄게요.",
            ["DialogueId"] = 12022302,
            ["GUID"] = "1E18B8EC",
            ["NextDialogue"] = 12022303,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18B8EC",
            },
        [12022303] = {
            ["Content"] = "我没事，只是有点头晕……扶疏，不要再消耗你的力量了，你答应过……",
            ["ContentKR"] = "괜찮아, 그냥 좀 어지러울 뿐이야... 부소, 더 이상 힘을 사용하면 안 돼. 약속했잖아...",
            ["DialogueId"] = 12022303,
            ["GUID"] = "1E18B916",
            ["NextDialogue"] = 12022304,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18B916",
            },
        [12022304] = {
            ["Content"] = "安心，我自有分寸。当下还是以你的安危为重。",
            ["ContentKR"] = "안심하세요, 제게 생각이 있어요. 지금은 {nickname} 씨 안전이 최우선이에요.",
            ["DialogueId"] = 12022304,
            ["GUID"] = "1E18B940",
            ["NextDialogue"] = 12022305,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18B940",
            },
        [12022305] = {
            ["Content"] = "可恶，今天怎么总是迟来一步！要是当初学轻功时没有偷懒就好了，都怪我总是睡到日上三竿才醒……",
            ["ContentKR"] = "제기랄, 오늘은 왜 이렇게 계속 한발 늦는 거야! 경공술을 배울 때 게으름 피우지 말아야 했는데, 매번 해가 중천에 뜰 때까지 잔 내 탓인가...",
            ["DialogueId"] = 12022305,
            ["GUID"] = "1E18B96A",
            ["NextDialogue"] = 12022306,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18B96A",
            },
        [12022306] = {
            ["Content"] = "我还好……你们怎么一起来了？",
            ["ContentKR"] = "난 괜찮아... 두 사람은 어떻게 같이 온 거야?",
            ["DialogueId"] = 12022306,
            ["GUID"] = "1E18B994",
            ["NextDialogue"] = 12022307,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18B994",
            },
        [12022307] = {
            ["Content"] = "我想明白了一些事情，正欲说与你听。",
            ["ContentKR"] = "깨달은 게 몇 가지 있어서, 당신한테 얘기해 줄 생각이었어요.",
            ["DialogueId"] = 12022307,
            ["GUID"] = "1E18B9BE",
            ["NextDialogue"] = 12022308,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18B9BE",
            },
        [12022308] = {
            ["Content"] = "我去百年春没有寻见你。听旁人说你往此处来了，便来碰碰运气，恰好在途中遇见了这位义士。",
            ["ContentKR"] = "백년춘에 갔었는데, 당신이 없더군요. 그런데 누군가 당신이 여기에 왔다고 해서, 혹시나 하고 와 보는 길에 이 의로운 분을 만난 거예요.",
            ["DialogueId"] = 12022308,
            ["GUID"] = "1E18B9E8",
            ["NextDialogue"] = 12022309,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18B9E8",
            },
        [12022309] = {
            ["Content"] = "听鸦原一别后，我寻思师兄可能往尘漠石海的方向去了，便在这附近徘徊游荡。",
            ["ContentKR"] = "청아원에서 헤어진 후, 사형께서 낙진의 바다 쪽으로 가셨을까 하여 이 근처를 배회하고 있었다.",
            ["DialogueId"] = 12022309,
            ["GUID"] = "1E18BA12",
            ["NextDialogue"] = 12022310,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18BA12",
            },
        [12022310] = {
            ["Content"] = "不想那祭坛处突然刮起大风，天地震荡。我便赶过来瞧，结果竟碰上了你……若是来得早点就好了！",
            ["ContentKR"] = "그런데 갑자기 저 제단 쪽에서 큰바람이 불고 천지가 진동을 해서 한번 와 봤다가, 뜻밖에도 널 만나게 된 거다. 좀 더 일찍 왔더라면 좋았을 것을...!",
            ["DialogueId"] = 12022310,
            ["GUID"] = "1E18BA3C",
            ["NextDialogue"] = 12022311,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18BA3C",
            },
        [12022311] = {
            ["Content"] = "我和你说，刚刚发生的事情太可怕了！就算十个你来了也没用！",
            ["ContentKR"] = "있잖아, 아까는 정말 무시무시했어! 너 같은 사람 10명이 와도 소용없었을걸!",
            ["DialogueId"] = 12022311,
            ["GUID"] = "1E18BA66",
            ["NextDialogue"] = 12022312,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18BA66",
            },
        [12022312] = {
            ["Content"] = "那个女人，她不仅把本魔王和小仆从囚禁起来，还硬生生地吞了一条龙！那可是龙诶！",
            ["ContentKR"] = "그 여자가, 이 마왕님이랑 시종을 가둬 놓더니, 용을 통째로 삼켜 버렸다니까! 용 말이야, 용!",
            ["DialogueId"] = 12022312,
            ["GUID"] = "1E18BA90",
            ["NextDialogue"] = 12022313,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18BA90",
            },
        [12022313] = {
            ["Content"] = "白现在想想还心有余悸……竟然和这样的人相处了这么久！",
            ["ContentKR"] = "저런 사람이랑 그렇게 오래 같이 있었다니... 스노우는 지금도 소름 끼쳐!",
            ["DialogueId"] = 12022313,
            ["GUID"] = "1E18BABA",
            ["NextDialogue"] = 12022314,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18BABA",
            },
        [12022314] = {
            ["Content"] = "{nickname}，真有此事吗？",
            ["ContentKR"] = "{nickname}, 정말 그런 일이 있었나요?",
            ["DialogueId"] = 12022314,
            ["GUID"] = "1E18BAE4",
            ["NextOptions"] = {
                [1] = 12022315,
                },
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18BAE4",
            },
        [12022315] = {
            ["Content"] = "（讲述事情经过。）",
            ["ContentKR"] = "(자초지종을 이야기한다.)",
            ["DialogueId"] = 12022315,
            ["GUID"] = "1E18BB0E",
            ["NextDialogue"] = 12022327,
            },
        [12022316] = {
            ["Content"] = "她弄这么一出，到底是何居心？",
            ["ContentKR"] = "그 여자가 대체 무슨 생각으로 이런 짓을 벌인 건지 짐작 가는 데가 있느냐?",
            ["DialogueId"] = 12022316,
            ["GUID"] = "1E18BB38",
            ["NextDialogue"] = 12022317,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18BB38",
            },
        [12022317] = {
            ["Content"] = "我也回答不上来……",
            ["ContentKR"] = "나도 잘 모르겠어...",
            ["DialogueId"] = 12022317,
            ["GUID"] = "1E18BB62",
            ["NextDialogue"] = 12022318,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18BB62",
            },
        [12022318] = {
            ["Content"] = "依我看，她就是想霸占烛阴的力量，征服世界，成为大魔王！",
            ["ContentKR"] = "내 생각에, 그 여자는 촉룡의 힘을 독차지해서, 세상을 정복하고 대마왕이 되려는 거야!",
            ["DialogueId"] = 12022318,
            ["GUID"] = "1E18BB8C",
            ["NextDialogue"] = 12022319,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18BB8C",
            },
        [12022319] = {
            ["Content"] = "征服世界……吗……",
            ["ContentKR"] = "세계 정복이라...",
            ["DialogueId"] = 12022319,
            ["GUID"] = "1E18BBB6",
            ["NextDialogue"] = 12022320,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18BBB6",
            },
        [12022320] = {
            ["Content"] = "她当时的确说了那样的话……",
            ["ContentKR"] = "지류 사장이 그때 이런 말을 했었어요...",
            ["DialogueId"] = 12022320,
            ["GUID"] = "1E18BBE0",
            ["NextDialogue"] = 12022321,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18BBE0",
            },
        [12022321] = {
            ["Content"] = "<H>白龙神君</>的时代，该结束了。而我，将执起祂的权柄。",
            ["ContentKR"] = "<H>백룡신군</>의 시대는, 이제 끝나야 해. 그리고 내가, 그 권능을 이어받겠어.",
            ["DialogueId"] = 12022321,
            ["GUID"] = "1E18BC0A",
            ["NextDialogue"] = 12022322,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18BC0A",
            },
        [12022322] = {
            ["Content"] = "她……想自己<H>成神</>吗？",
            ["ContentKR"] = "스스로... <H>신</>이 되려는 걸까요?",
            ["DialogueId"] = 12022322,
            ["GUID"] = "1E18BC34",
            ["NextDialogue"] = 12022323,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18BC34",
            },
        [12022323] = {
            ["Content"] = "依你所述，若止流早在万里之外的“冰湖城”就已开始布局，那她的计划恐怕比你我能猜到的更加周密。",
            ["ContentKR"] = "당신 말대로, 지류 사장이 저 먼 '아이스레이크 시티'에서부터 계획을 세웠던 거라면, 그 계획은 우리 생각보다 훨씬 치밀할 거예요.",
            ["DialogueId"] = 12022323,
            ["GUID"] = "1E18BC5E",
            ["NextDialogue"] = 12022324,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18BC5E",
            },
        [12022324] = {
            ["Content"] = "我看一时半会儿也商量不出啥，咱们不如都先回去收集些情报！唉，本来只是溜出来找师兄，不想竟撞见了不得了的大事……",
            ["ContentKR"] = "아무래도 당장은 뾰족한 수가 안 나올 것 같으니, 우선 각자 돌아가서 정보를 좀 모아 보자. 휴, 사형을 찾으러 몰래 빠져나온 것인데, 엄청난 일에 휘말려 버리다니...",
            ["DialogueId"] = 12022324,
            ["GUID"] = "1E18BC88",
            ["NextDialogue"] = 12022325,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18BC88",
            },
        [12022325] = {
            ["Content"] = "我得回去山外山一趟，把这事儿告诉他们才行。这样就算出了更大的变故，他们也好有个应对。",
            ["ContentKR"] = "일단 산외산으로 돌아가서, 이 일을 알려야겠다. 그래야 더 큰 변고가 생기더라도 대비할 수 있을 테니 말이야.",
            ["DialogueId"] = 12022325,
            ["GUID"] = "1E18BCB2",
            ["NextDialogue"] = 12022326,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18BCB2",
            },
        [12022326] = {
            ["Content"] = "我也会去无由生处打听消息。它们有些生于上古年间，或许了解失传的历史密辛。",
            ["ContentKR"] = "저도 무유생들에게 가서 소식을 알아볼게요. 상고 시대에 태어난 이들도 있으니, 어쩌면 기록으로 남지 않은 역사의 비밀을 알고 있을지도 몰라요.",
            ["DialogueId"] = 12022326,
            ["GUID"] = "1E18BCDC",
            ["NextDialogue"] = 12022328,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18BCDC",
            },
        [12022327] = {
            ["Content"] = "……我就知道，和黑瞎子一伙的，准没什么好东西！",
            ["ContentKR"] = "...내 그럴 줄 알았지. 흑곰하고 한패인 자들은 제대로 된 놈이 하나도 없어!",
            ["DialogueId"] = 12022327,
            ["GUID"] = "120223151.0",
            ["NextDialogue"] = 12022316,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/120223151",
            },
        [12022328] = {
            ["Content"] = "{nickname}，你作何打算？",
            ["ContentKR"] = "{nickname}, 넌 어찌할 생각이냐?",
            ["DialogueId"] = 12022328,
            ["GUID"] = "1E18BD30",
            ["NextOptions"] = {
                [1] = 120223281,
                [2] = 120223282,
                },
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18BD30",
            },
        [12022329] = {
            ["Content"] = "{性别：兄弟|姑娘}你竟也是一位心忧天下的侠士，刻舟果然不曾结交错人！",
            ["ContentKR"] = "{性别:공자|소저}도 천하를 지극히 염려하는 협객이었구나. 이 각주가 사람을 잘못 사귀진 않은 모양이야!",
            ["DialogueId"] = 12022329,
            ["GUID"] = "1E18BD5A",
            ["NextDialogue"] = 12022331,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18BD5A",
            },
        [12022330] = {
            ["Content"] = "由你一人承担诸多事宜，属实辛苦了。",
            ["ContentKR"] = "혼자서 그 많은 일을 감당하느라, 정말 고생 많았어요.",
            ["DialogueId"] = 12022330,
            ["GUID"] = "1E18BD84",
            ["NextDialogue"] = 12022331,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18BD84",
            },
        [12022331] = {
            ["Content"] = "眼见着太阳都快没影了，我们赶紧下山去吧。这儿到了晚上可是寒冷刺骨，继续在这待下去也没用。",
            ["ContentKR"] = "어느새 해가 거의 다 졌으니, 어서 산에서 내려가자. 여긴 밤이 되면 뼛속까지 시려서, 계속 있어 봐야 하등 도움 될 것이 없다.",
            ["DialogueId"] = 12022331,
            ["GUID"] = "1E18BDAE",
            ["NextDialogue"] = 12022332,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18BDAE",
            },
        [12022332] = {
            ["Content"] = "先离去吧。",
            ["ContentKR"] = "일단 떠나죠.",
            ["DialogueId"] = 12022332,
            ["GUID"] = "1E18BDD8",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18BDD8",
            },
        [12022401] = {
            ["Content"] = "等等，说好要给我们的报酬，该不会也要赖掉了吧？",
            ["ContentKR"] = "잠깐, 지류가 우리한테 주기로 한 보수는? 설마 그것도 떼먹으려는 건 아니겠지?",
            ["DialogueId"] = 12022401,
            ["Duration"] = 3,
            ["GUID"] = "1E18C92A",
            ["NextDialogue"] = 12022402,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120224/1E18C92A",
            },
        [12022402] = {
            ["Content"] = "委托就这样黄了……小仆从，你说我们大老远来华胥，是不是白跑一趟？",
            ["ContentKR"] = "의뢰가 이렇게 쫑나버리다니... 시종, 우리 멀리서 화서까지 왔는데 완전히 헛걸음한 거야?",
            ["DialogueId"] = 12022402,
            ["Duration"] = 4,
            ["GUID"] = "1E18C954",
            ["NextDialogue"] = 12022403,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120224/1E18C954",
            },
        [12022403] = {
            ["Content"] = "倒是还有止流给我们的天价零花钱就是了，也不亏。早知道，当初就该多拿点花！",
            ["ContentKR"] = "그래도 지류가 준 어마어마한 용돈이 있으니까, 손해는 아닌가? 이럴 줄 알았으면, 아까 더 많이 받아 둘걸!",
            ["DialogueId"] = 12022403,
            ["Duration"] = 4,
            ["GUID"] = "1E18C97E",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120224/1E18C97E",
            },
        [12022501] = {
            ["Content"] = "天地大德，其名为生。戕身害命，不可为也。",
            ["ContentKR"] = "천지의 가장 큰 덕을 '생'이라 이르나니, 남을 해하거나 목숨을 빼앗지 말지어다.",
            ["DialogueId"] = 12022501,
            ["GUID"] = "1E18D992",
            ["NextDialogue"] = 12022502,
            ["SnapShot"] = "ECHO",
            ["VoiceName"] = "voice/$Locale$/story/1201/120225/1E18D992",
            },
        [12022502] = {
            ["Content"] = "夫人根基，定文为信。毁约背盟，不可为也。",
            ["ContentKR"] = "사람의 근본은 신의를 지키는 것이니, 약조를 어기거나 맹세를 저버리지 말지어다.",
            ["DialogueId"] = 12022502,
            ["GUID"] = "1E18D9BC",
            ["NextDialogue"] = 12022503,
            ["SnapShot"] = "ECHO",
            ["VoiceName"] = "voice/$Locale$/story/1201/120225/1E18D9BC",
            },
        [12022503] = {
            ["Content"] = "著真去伪，赤心为诚。妄言欺众，不可为也。",
            ["ContentKR"] = "참을 드러내고 거짓을 버려 진실로서 정성을 다할지니,\
망령된 말로 무리를 속이지 말지어다.",
            ["DialogueId"] = 12022503,
            ["GUID"] = "1E18D9E6",
            ["SnapShot"] = "ECHO",
            ["VoiceName"] = "voice/$Locale$/story/1201/120225/1E18D9E6",
            },
        [12022504] = {
            ["Content"] = "卑以自牧，束己为谦。骄狂跋扈，不可为也。",
            ["ContentKR"] = "스스로를 낮추어 겸양으로 자신을 다스릴지니,\
오만방자하여 전횡을 일삼지 말지어다.",
            ["DialogueId"] = 12022504,
            ["GUID"] = "1E18DA10",
            ["NextDialogue"] = 12022505,
            ["SnapShot"] = "ECHO",
            ["VoiceName"] = "voice/$Locale$/story/1201/120225/1E18DA10",
            },
        [12022505] = {
            ["Content"] = "尊贤友客，守序为礼。放诞无忌，不可为也。",
            ["ContentKR"] = "어진 이를 높이고 손을 벗 삼아 질서를 지키는 것이 '예'이니,\
