            ["DialogueId"] = 12022506,
            ["GUID"] = "1E18DA64",
            ["SnapShot"] = "ECHO",
            ["VoiceName"] = "voice/$Locale$/story/1201/120225/1E18DA64",
            },
        [12022507] = {
            ["Content"] = "清心敛行，身正为廉。枉法贪酷，不可为也。",
            ["ContentKR"] = "맑은 마음으로 몸가짐을 단정히 하는 것이 '염'이니,\
법을 어기고 탐욕과 잔학을 행하지 말지어다.",
            ["DialogueId"] = 12022507,
            ["GUID"] = "1E18DA8E",
            ["NextDialogue"] = 12022508,
            ["SnapShot"] = "ECHO",
            ["VoiceName"] = "voice/$Locale$/story/1201/120225/1E18DA8E",
            },
        [12022508] = {
            ["Content"] = "裁辨是非，知之为明。淆乱颠倒，不可为也。",
            ["ContentKR"] = "시비를 분별하여 아는 것이 '명'이니, 이를 혼란케 하여 뒤바꾸지 말지어다.",
            ["DialogueId"] = 12022508,
            ["GUID"] = "1E18DAB8",
            ["NextDialogue"] = 12022509,
            ["SnapShot"] = "ECHO",
            ["VoiceName"] = "voice/$Locale$/story/1201/120225/1E18DAB8",
            },
        [12022509] = {
            ["Content"] = "垂聆天宪，恭肃为敬。离经叛道，不可为也。",
            ["ContentKR"] = "하늘의 법도에 경청하여 엄숙히 대하는 것이 '경'이니,\
