            ["DialogueId"] = 12022509,
            ["GUID"] = "1E18DAE2",
            ["SnapShot"] = "ECHO",
            ["VoiceName"] = "voice/$Locale$/story/1201/120225/1E18DAE2",
            },
        [12022510] = {
            ["Content"] = "我们继续前行吧。",
            ["ContentKR"] = "우리 계속 가보죠.",
            ["DialogueId"] = 12022510,
            ["GUID"] = "1E18DAE3",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120225/1E18DAE3",
            },
        [12022511] = {
