        [12022901] = {
            ["Camera"] = "445.980469,604.601562,199.662109,0.000176,-24.689903,-3.124238,11.88,100000.0,false,Manual,2.8",
            ["Content"] = "大当家。目前几处临时防御工事已经搭建起来了，异色狴犴的几波攻势都被抵御住了。",
            ["ContentKR"] = "대방님. 현재 몇 군데 임시 방어 시설은 구축되었고, 이색 폐안들이 펼친 몇 차례 공세도 모두 막아냈습니다.",
            ["DialogueId"] = 12022901,
            ["GUID"] = "1E191B32",
            ["NextDialogue"] = 12022902,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 304003,
                [3] = 304004,
                [4] = 303010,
                [5] = 406004,
                },
            ["SpeakNpcId"] = 210022,
            ["VoiceName"] = "voice/$Locale$/story/1201/120229/1E191B32",
            },
        [12022902] = {
            ["Content"] = "多亏了您的指挥，目前局势平稳，大伙的精神都很振奋！",
            ["ContentKR"] = "대방님의 지휘 덕분에 현재 상황은 안정적이고, 모두의 사기도 매우 높습니다!",
            ["DialogueId"] = 12022902,
            ["GUID"] = "1E191B5C",
            ["NextDialogue"] = 12022903,
            ["SpeakNpcId"] = 210022,
            ["VoiceName"] = "voice/$Locale$/story/1201/120229/1E191B5C",
            },
        [12022903] = {
            ["Content"] = "那些恶兽尝到了苦头，倒也停止了继续进攻。现在正徘徊在外围，仿佛等待着什么契机……您看，下一步该怎么做呢？",
            ["ContentKR"] = "그 악한 짐승들이 쓴맛을 본 모양인지, 일단은 공격을 멈추었으나, 기회를 노리는 듯이 외곽을 배회하고 있습니다... 다음은 어찌하는 것이 좋겠습니까?",
            ["DialogueId"] = 12022903,
            ["GUID"] = "1E191B86",
            ["NextDialogue"] = 12022904,
            ["SpeakNpcId"] = 210022,
            ["VoiceName"] = "voice/$Locale$/story/1201/120229/1E191B86",
            },
        [12022904] = {
            ["Content"] = "很好，多亏了你们办事利索。",
            ["ContentKR"] = "훌륭합니다. 여러분께서 일을 신속하게 처리해 주신 덕분입니다.",
            ["DialogueId"] = 12022904,
            ["GUID"] = "1E191BB0",
            ["NextDialogue"] = 12022905,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120229/1E191BB0",
            },
        [12022905] = {
            ["Content"] = "接下来，多备些人手巡查，留意那些山岭间的视线死角，莫让恶兽钻了空子。",
            ["ContentKR"] = "이제부터는 순찰 인원을 더 늘리도록 하세요. 산등성이 사이의 사각지대를 잘 살펴서 악한 짐승들이 빈틈을 파고들지 못하게 하시고요.",
            ["DialogueId"] = 12022905,
            ["GUID"] = "1E191BDA",
            ["NextDialogue"] = 12022906,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120229/1E191BDA",
            },
        [12022906] = {
            ["Content"] = "在此时节，对老弱妇孺的安置也不能疏忽了。对着名册清点好人数，煮些热姜茶送过去，暖暖他们的心。",
            ["ContentKR"] = "이런 때일수록 노약자와 부녀자들을 살피는 일도 소홀히 해서는 안 됩니다. 명부를 보고 인원을 정확히 파악해서, 따뜻한 생강차라도 끓여 보내 마음을 다독여 주세요.",
            ["DialogueId"] = 12022906,
            ["GUID"] = "1E191C04",
            ["NextDialogue"] = 12022907,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120229/1E191C04",
            },
        [12022907] = {
            ["Content"] = "从黑市那儿租借来的弹药已经就位了。分发到前线，让他们两人一组，互相照看好后路。",
            ["ContentKR"] = "암시장에서 빌려온 탄약은 이미 준비되었습니다. 전선에 나눠주고, 두 사람씩 조를 짜서 서로의 퇴로를 잘 살피도록 하세요.",
            ["DialogueId"] = 12022907,
            ["GUID"] = "1E191C2E",
            ["NextDialogue"] = 12022908,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120229/1E191C2E",
            },
        [12022908] = {
            ["Content"] = "是，止流大当家！",
            ["ContentKR"] = "네, 지류 대방님!",
            ["DialogueId"] = 12022908,
            ["GUID"] = "1E191C58",
            ["NextDialogue"] = 12022909,
            ["VoiceName"] = "voice/$Locale$/story/1201/120229/1E191C58",
            },
        [12022909] = {
            ["Content"] = "悬衡派的香官们在做最后的准备，再坚持片刻，这场危机就能化解。",
            ["ContentKR"] = "현형파 향관들이 마지막 준비를 하고 있으니, 조금만 더 버티면 이 위기를 넘길 수 있을 겁니다.",
            ["DialogueId"] = 12022909,
            ["GUID"] = "1E191C82",
            ["NextDialogue"] = 12022910,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120229/1E191C82",
            },
        [12022910] = {
            ["Content"] = "别让任何人受伤了。百年春丢了可以再打回来，若是人命丢了，可没有挽回的机会。",
            ["ContentKR"] = "누구도 다치게 해서는 안 됩니다. 백년춘은 잃어도 다시 일으켜 세울 수 있지만, 목숨은 한번 잃으면 되돌릴 방법이 없으니까요.",
            ["DialogueId"] = 12022910,
            ["GUID"] = "1E191CAC",
            ["NextDialogue"] = 12022911,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120229/1E191CAC",
            },
        [12022911] = {
            ["Content"] = "万万不可啊，止流大当家——",
            ["ContentKR"] = "지류 대방님, 아니 될 말입니다!",
            ["DialogueId"] = 12022911,
            ["GUID"] = "1E191CD6",
            ["NextDialogue"] = 12022912,
            ["SpeakNpcId"] = 210031,
            ["SpeakNpcName"] = "UI_CMName_Name_ZhongNianNan",
            ["VoiceName"] = "voice/$Locale$/story/1201/120229/1E191CD6",
            },
        [12022912] = {
            ["Content"] = "唉……是你啊。",
            ["ContentKR"] = "아... 또 이러시는군요.",
            ["DialogueId"] = 12022912,
            ["GUID"] = "1E191D00",
            ["NextDialogue"] = 12022913,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120229/1E191D00",
            },
        [12022913] = {
            ["Content"] = "请问您有什么高见，欲与我们分享呢？",
            ["ContentKR"] = "혹시, 저희에게 나눠주실 고견이라도 있으신가요?",
            ["DialogueId"] = 12022913,
            ["GUID"] = "1E191D2A",
            ["NextDialogue"] = 12022914,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120229/1E191D2A",
            },
        [12022914] = {
            ["Content"] = "<W>杀伤及盗者，天厌之</>，这是大风九章的古训！",
            ["ContentKR"] = "<W>남을 해치거나 도둑질하는 자는 하늘이 벌을 내린다</>는 것은 대풍구장의 오랜 가르침입니다!",
            ["DialogueId"] = 12022914,
            ["GUID"] = "1E191D54",
            ["NextDialogue"] = 12022915,
            ["SpeakNpcId"] = 210031,
            ["SpeakNpcName"] = "UI_CMName_Name_ZhongNianNan",
            ["VoiceName"] = "voice/$Locale$/story/1201/120229/1E191D54",
            },
        [12022915] = {
            ["Content"] = "……可是攻击玄色狴犴，并不会招致责罚呀？",
            ["ContentKR"] = "...하지만 검은 폐안은 공격해도 벌을 받지 않잖습니까?",
            ["DialogueId"] = 12022915,
            ["GUID"] = "1E191D7E",
            ["NextDialogue"] = 12022916,
            ["SpeakNpcId"] = 210077,
            ["SpeakNpcName"] = "UI_CMName_Name_WeiGuanZhe",
            ["VoiceName"] = "voice/$Locale$/story/1201/120229/1E191D7E",
            },
        [12022916] = {
            ["Content"] = "大风九章，岂能如此浅显地解读？！",
            ["ContentKR"] = "대풍구장을, 어찌 그리 단순하게만 해석하십니까?!",
            ["DialogueId"] = 12022916,
            ["GUID"] = "1E191DA8",
            ["NextDialogue"] = 12022917,
            ["SpeakNpcId"] = 210031,
            ["SpeakNpcName"] = "UI_CMName_Name_ZhongNianNan",
            ["VoiceName"] = "voice/$Locale$/story/1201/120229/1E191DA8",
            },
        [12022917] = {
            ["Content"] = "发乎于心，现乎于行。若是动了兵戈，人心就会变质。无论这兵戈朝向的是友邻还是恶敌，性质都是相同的！终是逆了天意呀！",
            ["ContentKR"] = "마음에서 비롯된 것은 행동으로 드러나는 법입니다. 일단 무기를 들면, 사람의 마음은 변질되기 마련이지요. 그 칼끝이 이웃을 향하든, 악한 적을 향하든 본질은 같습니다! 결국 하늘의 뜻을 거역하는 일입니다!",
            ["DialogueId"] = 12022917,
            ["GUID"] = "1E191DD2",
            ["NextDialogue"] = 12022918,
            ["SpeakNpcId"] = 210031,
            ["SpeakNpcName"] = "UI_CMName_Name_ZhongNianNan",
            ["VoiceName"] = "voice/$Locale$/story/1201/120229/1E191DD2",
            },
        [12022918] = {
            ["Content"] = "按照你的意思。我们应该在原地待着，什么都不做，束手就擒……是吗？",
            ["ContentKR"] = "그렇다면, 가만히 서서 아무것도 하지 말고 속수무책으로 당하라는 말씀이십니까...?",
            ["DialogueId"] = 12022918,
            ["GUID"] = "1E191DFC",
            ["NextDialogue"] = 12022919,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120229/1E191DFC",
            },
        [12022919] = {
            ["Content"] = "白龙神君会为我们驱除恶邪的！要是招来白龙神君的厌弃，失去了祂的庇护，那才是因小失大。您请三思啊！",
            ["ContentKR"] = "백룡신군께서 저희를 위해 사악한 기운을 물리쳐 주실 겁니다! 만약 백룡신군의 노여움을 사서 그분의 가호를 잃게 된다면, 그것이야말로 소탐대실입니다. 부디 다시 생각해 주십시오!",
            ["DialogueId"] = 12022919,
            ["GUID"] = "1E191E26",
            ["NextDialogue"] = 12022920,
            ["SpeakNpcId"] = 210031,
            ["SpeakNpcName"] = "UI_CMName_Name_ZhongNianNan",
            ["VoiceName"] = "voice/$Locale$/story/1201/120229/1E191E26",
            },
        [12022920] = {
            ["Content"] = "有了黍离之战的前车之鉴，难道还不够吗？！",
            ["ContentKR"] = "탄식의 전투라는 전철만으론 부족하다는 말씀이십니까?!",
            ["DialogueId"] = 12022920,
            ["GUID"] = "1E191E50",
            ["NextDialogue"] = 12022921,
            ["RelatedWikiId"] = {
                [1] = 401003,
                },
            ["SpeakNpcId"] = 210031,
            ["SpeakNpcName"] = "UI_CMName_Name_ZhongNianNan",
            ["VoiceName"] = "voice/$Locale$/story/1201/120229/1E191E50",
            },
        [12022921] = {
            ["Content"] = "好像言之有理……",
            ["ContentKR"] = "일리 있는 말 같기도 하고...",
            ["DialogueId"] = 12022921,
            ["GUID"] = "1E191E7A",
            ["NextDialogue"] = 12022922,
            ["SpeakNpcId"] = 210077,
            ["SpeakNpcName"] = "UI_CMName_Name_WeiGuanZhe",
            ["VoiceName"] = "voice/$Locale$/story/1201/120229/1E191E7A",
            },
        [12022922] = {
            ["Content"] = "嗯……那你且说说，如今异色狴犴攻来，白龙神君的庇护尚在何处呢？",
            ["ContentKR"] = "음... 그럼 한번 말씀해 보시지요. 지금 이색 폐안들이 공격해 오는데, 백룡신군의 가호는 대체 어디에 있는 겁니까?",
            ["DialogueId"] = 12022922,
            ["GUID"] = "1E191EA4",
            ["NextDialogue"] = 12022923,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120229/1E191EA4",
            },
        [12022923] = {
            ["Content"] = "狴犴和应天尉随后就能赶到，只要稍作等待……",
            ["ContentKR"] = "폐안과 응천위가 곧 당도할 것이니, 잠시만 기다리면...",
            ["DialogueId"] = 12022923,
            ["GUID"] = "1E191ECE",
            ["NextDialogue"] = 12022924,
            ["SpeakNpcId"] = 210031,
            ["SpeakNpcName"] = "UI_CMName_Name_ZhongNianNan",
            ["VoiceName"] = "voice/$Locale$/story/1201/120229/1E191ECE",
            },
        [12022924] = {
            ["Content"] = "那若是他们来迟了，你该如何是好呢？",
            ["ContentKR"] = "만약 그들이 늦는다면, 어찌하실 생각이십니까?",
            ["DialogueId"] = 12022924,
            ["GUID"] = "1E191EF8",
            ["NextDialogue"] = 12022925,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120229/1E191EF8",
            },
        [12022925] = {
            ["Content"] = "这……",
            ["ContentKR"] = "그건...",
            ["DialogueId"] = 12022925,
            ["GUID"] = "1E191F22",
            ["NextDialogue"] = 12022926,
            ["SpeakNpcId"] = 210031,
            ["SpeakNpcName"] = "UI_CMName_Name_ZhongNianNan",
            ["VoiceName"] = "voice/$Locale$/story/1201/120229/1E191F22",
            },
        [12022926] = {
            ["Content"] = "既然你认为“神”的规训重于你的性命，这种风骨，我十分敬佩。杜立，将这位人士请出去吧。",
            ["ContentKR"] = "'신'의 규율이 목숨보다 중하다고 여기신다니, 기개가 실로 존경스럽군요. 두립, 이분을 밖으로 모시세요.",
            ["DialogueId"] = 12022926,
            ["GUID"] = "1E191F4C",
            ["NextDialogue"] = 12022927,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120229/1E191F4C",
            },
        [12022927] = {
            ["Content"] = "道不同不相为谋。我这离经叛道的百年春地界，可能不适合你待着。",
            ["ContentKR"] = "길이 다르면 함께 일을 도모할 수 없는 법입니다. 정도를 벗어난 우리 백년춘이 아니라, 다른 곳에 머무시는 것이 좋겠군요.",
            ["DialogueId"] = 12022927,
            ["GUID"] = "1E191F76",
            ["NextDialogue"] = 12022928,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120229/1E191F76",
            },
        [12022928] = {
            ["Content"] = "这……止流大当家，外面异色狴犴肆虐，赶他一人出去，恐有危险。",
            ["ContentKR"] = "하지만 지류 대방님, 밖에는 이색 폐안들이 날뛰고 있어, 혼자 밖으로 내보냈다가 저분이 위험에 처할 수도 있는데요...",
            ["DialogueId"] = 12022928,
            ["GUID"] = "1E191FA0",
            ["NextDialogue"] = 12022929,
            ["SpeakNpcId"] = 210032,
            ["VoiceName"] = "voice/$Locale$/story/1201/120229/1E191FA0",
            },
        [12022929] = {
            ["Content"] = "怎么？我的命令，你也不听了吗？",
            ["ContentKR"] = "그래서요? 내 명령을 듣지 않겠다는 겁니까?",
            ["DialogueId"] = 12022929,
            ["GUID"] = "1E191FCA",
            ["NextDialogue"] = 12022930,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120229/1E191FCA",
            },
        [12022930] = {
            ["Content"] = "……遵命！",
            ["ContentKR"] = "...명을 받들겠습니다!",
            ["DialogueId"] = 12022930,
            ["GUID"] = "1E191FF4",
            ["SpeakNpcId"] = 210032,
            ["VoiceName"] = "voice/$Locale$/story/1201/120229/1E191FF4",
            },
        [12023001] = {
            ["Camera"] = "197.917969,691.520508,260.698242,0.000206,-17.289721,-77.722221,11.88,100000.0,false,Manual,2.8",
            ["Content"] = "止流掌柜……",
            ["ContentKR"] = "지류 사장님...",
            ["DialogueId"] = 12023001,
            ["GUID"] = "1E192B9A",
            ["NextDialogue"] = 12023002,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 304003,
                [3] = 304004,
                [4] = 303010,
                [5] = 406004,
                [6] = 401003,
                },
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120230/1E192B9A",
            },
        [12023002] = {
            ["Content"] = "……{nickname}，你来了。刚刚那幕，你也看到了？",
            ["ContentKR"] = "...{nickname}, 왔구나. 조금 전 상황, 너도 봤어?",
            ["DialogueId"] = 12023002,
            ["GUID"] = "1E192BC4",
            ["NextOptions"] = {
                [1] = 120230021,
                [2] = 120230022,
                [3] = 120230023,
                [4] = 120230024,
                },
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120230/1E192BC4",
            },
        [12023003] = {
            ["Content"] = "……人必自助，而后天助之。",
            ["ContentKR"] = "...하늘은 스스로 돕는 자를 돕는다고 하지.",
            ["DialogueId"] = 12023003,
            ["GUID"] = "1E192BEE",
            ["NextDialogue"] = 12023004,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120230/1E192BEE",
            },
        [12023004] = {
            ["Content"] = "目前情况紧急，这些不要紧的闲聊，放到之后再说吧。",
            ["ContentKR"] = "지금은 상황이 급박하니, 이런 사소한 이야기는 나중에 다시 하도록 하자.",
            ["DialogueId"] = 12023004,
            ["GUID"] = "1E192C18",
            ["NextDialogue"] = 12023005,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120230/1E192C18",
            },
        [12023005] = {
            ["Content"] = "{nickname}，可以委托你去支援白龙祠堂前的战局吗？",
            ["ContentKR"] = "{nickname}, 백룡 사당 앞 전투 상황을 좀 도와줄 수 있겠어?",
            ["DialogueId"] = 12023005,
            ["GUID"] = "1E192C42",
            ["NextDialogue"] = 12023006,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120230/1E192C42",
            },
        [12023006] = {
            ["Content"] = "只要再抵挡片刻，待香官的筹备完成后，此次危机就能一举化解。委托金会追加在之后给你的报酬当中。",
            ["ContentKR"] = "향관들의 준비가 끝날 때까지 잠시만 더 버티면, 이번 위기는 단번에 해결될 거야. 의뢰비는 나중에 줄 보수에 추가해 줄게.",
            ["DialogueId"] = 12023006,
            ["GUID"] = "1E192C6C",
            ["NextDialogue"] = 12023007,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120230/1E192C6C",
            },
        [12023007] = {
            ["Content"] = "嗯……我明白了。",
            ["ContentKR"] = "네... 알겠어요.",
            ["DialogueId"] = 12023007,
            ["GUID"] = "1E192C96",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120230/1E192C96",
            },
        [12023101] = {
            ["Content"] = "预备已毕——",
            ["ContentKR"] = "준비 끝났습니다——",
            ["DialogueId"] = 12023101,
            ["GUID"] = "1E193C02",
            ["VoiceName"] = "voice/$Locale$/story/1201/120231/1E193C02",
            },
        [12023102] = {
            ["Content"] = "昭昭华胥，四维有律。叩问穹苍，应天有序。",
            ["ContentKR"] = "눈부신 화서여, 천지사방에 법도가 있도다. 푸른 하늘에 엎드려 여쭈니, 질서 있게 하늘의 뜻을 따르노라.",
            ["DialogueId"] = 12023102,
            ["GUID"] = "1E193C2C",
            ["NextDialogue"] = 12023103,
            ["VoiceName"] = "voice/$Locale$/story/1201/120231/1E193C2C",
            },
        [12023103] = {
            ["Content"] = "萃馥积香，萦绕八方。远汶却秽，承泽流芳。",
            ["ContentKR"] = "짙은 향 모으니, 온 세상에 향기 감도네. 더러움 멀리 물리치고, 은택 입어 그 이름 길이 빛나리.",
            ["DialogueId"] = 12023103,
            ["GUID"] = "1E193C56",
            ["NextDialogue"] = 12023104,
            ["VoiceName"] = "voice/$Locale$/story/1201/120231/1E193C56",
            },
        [12023104] = {
            ["Content"] = "汝之黎元，端行守宪。定分止争，惟法恒常。",
            ["ContentKR"] = "이 땅의 백성들이여, 몸가짐을 바로 하고 법을 지킬지니, 분쟁과 다툼은 종식되고, 오직 법만이 영원하리라.",
            ["DialogueId"] = 12023104,
            ["GUID"] = "1E193C80",
            ["VoiceName"] = "voice/$Locale$/story/1201/120231/1E193C80",
            },
        [12023201] = {
            ["Content"] = "呼……终于结束了。",
            ["ContentKR"] = "휴... 드디어 끝났네.",
            ["DialogueId"] = 12023201,
            ["GUID"] = "1E194C6A",
            ["NextDialogue"] = 12023202,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120232/1E194C6A",
            },
        [12023202] = {
            ["Content"] = "小仆从，被这么一打岔，刚刚采来的烛阴鳞还没有交给止流姐姐呢！我们赶紧回去找她吧！",
            ["ContentKR"] = "시종! 아까 그 소란 때문에, 우리가 캐 온 촉룡 비늘을 아직 지류 사장님한테 못 줬어! 얼른 가서 전해 주자!",
            ["DialogueId"] = 12023202,
            ["GUID"] = "1E194C94",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120232/1E194C94",
            },
        [12023301] = {
            ["Camera"] = "212.574219,845.443359,223.21582,0.0,-10.914123,-63.608265,11.88,100000.0,false,Manual,2.8",
            ["Content"] = "百年春的危机已经化解了，实在是太好了。",
            ["ContentKR"] = "백년춘의 위기가 해결되어서 정말 다행이에요.",
            ["DialogueId"] = 12023301,
            ["GUID"] = "1E195CD2",
            ["NextDialogue"] = 12023302,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 304003,
                [3] = 304004,
                [4] = 303010,
                [5] = 406004,
                },
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120233/1E195CD2",
            },
        [12023302] = {
            ["Content"] = "止流姐姐，你要的烛阴鳞我们也采摘回来啦！怎么样，白和小仆从是不是很厉害？快夸夸我们！",
            ["ContentKR"] = "지류 사장님! 부탁한 촉룡 비늘 우리가 다 캐 왔어! 어때, 나랑 내 시종 엄청 대단하지? 얼른 칭찬해 줘!",
            ["DialogueId"] = 12023302,
            ["GUID"] = "1E195CFC",
            ["NextDialogue"] = 12023303,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120233/1E195CFC",
            },
        [12023303] = {
            ["Content"] = "嗯，真乖。多亏你们了。",
            ["ContentKR"] = "응, 잘했구나. 두 사람 덕분이야.",
            ["DialogueId"] = 12023303,
            ["GUID"] = "1E195D26",
            ["NextDialogue"] = 12023304,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120233/1E195D26",
            },
        [12023304] = {
            ["Content"] = "止流掌柜，你还好吗？",
            ["ContentKR"] = "지류 사장님, 괜찮으세요?",
            ["DialogueId"] = 12023304,
            ["GUID"] = "1E195D50",
            ["NextDialogue"] = 12023305,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120233/1E195D50",
            },
        [12023305] = {
            ["Content"] = "未想到此次的烛阴之灾来得如此迅疾，连日操劳，有些疲累罢了。",
            ["ContentKR"] = "이번 촉룡의 재앙이 이렇게 갑자기 닥칠 줄은 몰랐거든. 며칠 계속 신경을 썼더니 좀 피곤한 것뿐이야.",
            ["DialogueId"] = 12023305,
            ["GUID"] = "1E195D7A",
            ["NextDialogue"] = 12023306,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120233/1E195D7A",
            },
        [12023306] = {
            ["Content"] = "好在，有了你采来的这些烛阴鳞，事情也算是步上了正轨。之后只要重新将烛阴封印，此次的风波，便算是平定了。",
            ["ContentKR"] = "다행히 네가 가져온 이 촉룡 비늘 덕분에, 일도 제대로 진행할 수 있게 됐어. 이제 촉룡만 다시 봉인하면, 이번 소동도 마무리될 거야.",
            ["DialogueId"] = 12023306,
            ["GUID"] = "1E195DA4",
            ["NextDialogue"] = 12023307,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120233/1E195DA4",
            },
        [12023307] = {
            ["Content"] = "{nickname}，刚刚也是借了你的助力。你赶来得倒是及时。",
            ["ContentKR"] = "{nickname}, 아까도 큰 도움이 됐어. 아주 때맞춰 와주었네.",
            ["DialogueId"] = 12023307,
            ["GUID"] = "1E195DCE",
            ["NextDialogue"] = 12023308,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120233/1E195DCE",
            },
        [12023308] = {
            ["Content"] = "我们在尘漠石海的顶端预知到这里的危险，连忙赶了回来。好在还来得及。",
            ["ContentKR"] = "저희가 낙진의 바다 가장 높은 곳에서 이곳의 위험을 미리 감지하고 급히 돌아왔어요. 다행히 늦지 않았네요.",
            ["DialogueId"] = 12023308,
            ["GUID"] = "1E195DF8",
            ["NextDialogue"] = 12023309,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120233/1E195DF8",
            },
        [12023309] = {
            ["Content"] = "对了，小仆从，先前你采摘烛阴鳞时听到的那个声音，要不要也和止流姐姐说一声？",
            ["ContentKR"] = "참, 시종! 아까 촉룡 비늘 딸 때 들었던 그 목소리, 지류 사장님한테도 말하는 게 어때?",
            ["DialogueId"] = 12023309,
            ["GUID"] = "1E195E22",
            ["NextDialogue"] = 12023310,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120233/1E195E22",
            },
        [12023310] = {
            ["Content"] = "声音？",
            ["ContentKR"] = "목소리?",
            ["DialogueId"] = 12023310,
            ["GUID"] = "1E195E4C",
            ["NextOptions"] = {
                [1] = 120233101,
                },
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120233/1E195E4C",
            },
        [12023311] = {
            ["Content"] = "当我触碰到烛阴鳞的时候，突然听到了某个声音……它好像与异色狴犴有所联系，还掌握了它们的动向。",
            ["ContentKR"] = "촉룡 비늘에 손을 댔을 때, 갑자기 어떤 목소리가 들렸어요... 목소리의 주인은 이색 폐안들과 관련이 있는 것 같았는데, 그들의 움직임도 파악하고 있는 듯했어요.",
            ["DialogueId"] = 12023311,
            ["GUID"] = "1E195E76",
            ["NextDialogue"] = 12023312,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120233/1E195E76",
            },
        [12023312] = {
            ["Content"] = "如果能与它想办法沟通，说不定可以问到更多情报……",
            ["ContentKR"] = "만약 그 목소리와 어떻게든 소통할 수 있다면, 더 많은 정보를 얻을 수 있을지도 몰라요...",
            ["DialogueId"] = 12023312,
            ["GUID"] = "1E195EA0",
            ["NextDialogue"] = 12023313,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120233/1E195EA0",
            },
        [12023313] = {
            ["Content"] = "……你大约是听错了罢。",
            ["ContentKR"] = "...잘못 들은 걸 거야.",
            ["DialogueId"] = 12023313,
            ["GUID"] = "1E195ECA",
            ["NextOptions"] = {
                [1] = 120233131,
                },
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120233/1E195ECA",
            },
        [12023314] = {
            ["Content"] = "但是，它成功预测了异色狴犴攻击百年春的行为。我想，这至少说明它对我们没有敌意。",
            ["ContentKR"] = "하지만 그 목소리는 이색 폐안들이 백년춘을 공격할 거라는 걸 정확히 예측했어요. 적어도 저희한테 적의는 없다는 뜻 아닐까요?",
            ["DialogueId"] = 12023314,
            ["GUID"] = "1E195EF4",
            ["NextDialogue"] = 12023315,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120233/1E195EF4",
            },
        [12023315] = {
            ["Content"] = "我曾听闻，在尘漠石海的深处存在某种浊气。沾染上浊气的人，会出现幻听、幻视、幻忆等种种迹象，需要歇息半晌才能好转。",
            ["ContentKR"] = "일전에 낙진의 바다 깊은 곳에 어떤 탁한 기운이 있다고 들은 적이 있어. 그 기운에 닿은 사람은 환청이나 환각을 보기도 하고, 사실과 다른 기억을 떠올리는 등 여러 증상을 보이는데, 한나절쯤 푹 쉬면 나아진다고 하더군.",
            ["DialogueId"] = 12023315,
            ["GUID"] = "1E195F1E",
            ["NextDialogue"] = 12023316,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120233/1E195F1E",
            },
        [12023316] = {
            ["Content"] = "取来这些烛阴鳞，你们已经帮了大忙。你们一路上舟车劳顿，又马不停蹄地为我干活。现在得了空闲，去逛逛吧。",
            ["ContentKR"] = "이 촉룡 비늘을 가져다준 것만으로도 이미 큰 도움이 됐어. 두 사람 다 먼 길 오느라 피곤했을 텐데, 오자마자 내 일까지 돕느라 쉴 틈이 없었겠네. 이제 좀 한가해졌으니, 나가서 좀 돌아다녀 봐.",
            ["DialogueId"] = 12023316,
            ["GUID"] = "1E195F48",
            ["NextDialogue"] = 12023317,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120233/1E195F48",
            },
        [12023317] = {
            ["Content"] = "对了。你们在黑市搭救下来的那位姑娘，她的病情似乎有所发展。祝由扶氏托我带话给你们，让你们去枯荣阁看望病人，再做下一步打算。",
            ["ContentKR"] = "참, 두 사람이 암시장에서 구해준 그 아가씨는 병세가 조금 더 깊어진 모양이던데. 축유 부소가 말을 전해달라더군. 고영각으로 가서 그 아가씨를 살펴본 다음, 앞으로 어찌할지 정해달라고 말이야.",
            ["DialogueId"] = 12023317,
            ["GUID"] = "1E195F72",
            ["NextDialogue"] = 12023318,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120233/1E195F72",
            },
        [12023318] = {
            ["Content"] = "从百年春出去，左手边有条曲径通幽的小路。你们沿着小路走，看到杏林环绕中的一处医馆，便是枯荣阁所在。",
            ["ContentKR"] = "백년춘에서 나가 왼쪽으로 가면 오솔길이 하나 있어. 그 길을 따라가다 보면 살구나무 숲으로 둘러싸인 의원이 하나 보일 거야. 거기가 바로 고영각이야.",
            ["DialogueId"] = 12023318,
            ["GUID"] = "1E195F9C",
            ["NextDialogue"] = 12023319,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120233/1E195F9C",
            },
        [12023319] = {
            ["Content"] = "嗯……我明白了。",
            ["ContentKR"] = "네... 알겠어요.",
            ["DialogueId"] = 12023319,
            ["GUID"] = "1E195FC6",
            ["NextDialogue"] = 12023320,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120233/1E195FC6",
            },
        [12023320] = {
            ["Content"] = "止流掌柜，那之后封印烛阴的事宜，还需要我们帮忙吗？",
            ["ContentKR"] = "지류 사장님, 그럼 나중에 촉룡을 봉인하는 일에 저희 도움이 더 필요할까요?",
            ["DialogueId"] = 12023320,
            ["GUID"] = "1E195FF0",
            ["NextDialogue"] = 12023321,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120233/1E195FF0",
            },
        [12023321] = {
            ["Content"] = "呵呵，放心。若是出现了难以搞定的事情，我会再来委托你们的。",
            ["ContentKR"] = "후후, 걱정하지 마. 만약 해결하기 어려운 일이 생기면, 그때 두 사람에게 의뢰할게.",
            ["DialogueId"] = 12023321,
            ["GUID"] = "1E19601A",
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120233/1E19601A",
            },
        [12023401] = {
            ["Content"] = "白，你会觉得止流掌柜最后那段话像是在转移话题，想要支开我们吗？",
            ["ContentKR"] = "스노우, 마지막에 지류 사장님이 꼭 딴 데로 말 돌리면서 우리를 보내려는 것 같지 않았어?",
            ["DialogueId"] = 12023401,
            ["GUID"] = "1E196D3A",
            ["NextDialogue"] = 12023402,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120234/1E196D3A",
            },
        [12023402] = {
            ["Content"] = "哎？！小仆从，你这样一说，好像是有点。但她为什么要这样做呢？",
            ["ContentKR"] = "어?! 시종, 그렇게 말하니까 좀 그런 것 같기도 하네. 근데 왜 그런 걸까?",
            ["DialogueId"] = 12023402,
            ["GUID"] = "1E196D64",
            ["NextDialogue"] = 12023403,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120234/1E196D64",
            },
        [12023403] = {
            ["Content"] = "……算了。想不明白，我们先出去吧。还是即将要到手的报酬比较重要！",
            ["ContentKR"] = "...됐어. 생각해 봤자 머리만 아프고, 일단 나가자. 곧 손에 들어올 보수가 더 중요하다고!",
            ["DialogueId"] = 12023403,
            ["GUID"] = "1E196D8E",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120234/1E196D8E",
            },
        [12023500] = {
            ["Content"] = "无由生很感谢，给了你好东西。【待包装】",
            ["DialogueId"] = 12023500,
            ["GUID"] = "1E197D78",
            ["NextDialogue"] = 12023501,
            ["SpeakNpcId"] = 210041,
            },
        [12023501] = {
            ["Content"] = "介绍无由生被困的缘由（叙事向）【待包装】",
            ["DialogueId"] = 12023501,
            ["GUID"] = "1E197DA2",
            ["SpeakNpcId"] = 210041,
            },
        [12023510] = {
            ["Content"] = "无由生很感谢，给了你好东西。【待包装】",
            ["DialogueId"] = 12023510,
            ["GUID"] = "1E197F1C",
            ["NextDialogue"] = 12023511,
            ["SpeakNpcId"] = 210042,
            },
        [12023511] = {
            ["Content"] = "告诉你了有意思的秘辛。（可以用于解锁相关词条，任务事件）【待包装】",
            ["DialogueId"] = 12023511,
            ["GUID"] = "1E197F46",
            ["SpeakNpcId"] = 210042,
            },
        [12023520] = {
            ["Content"] = "无由生很感谢，给了你好东西。【待包装】",
            ["DialogueId"] = 12023520,
            ["GUID"] = "1E1980C0",
            ["NextDialogue"] = 12023521,
            ["SpeakNpcId"] = 210043,
            },
        [12023521] = {
            ["Content"] = "那边的山洞里有好东西。（引导向区域玩法）【待包装】",
            ["DialogueId"] = 12023521,
            ["GUID"] = "1E1980EA",
            ["SpeakNpcId"] = 210043,
            },
        [12023801] = {
            ["Content"] = "【机关】清除尘漠",
            ["DialogueId"] = 12023801,
            ["Duration"] = 4,
            ["GUID"] = "1E19AEDA",
            },
        [12023802] = {
            ["Content"] = "【战斗】+【机关】限时战斗后采集黑龙鳞",
            ["DialogueId"] = 12023802,
            ["Duration"] = 4,
