            ["DialogueId"] = 12025601,
            ["GUID"] = "1E1AD62A",
            ["NextDialogue"] = 12025602,
            ["SpeakNpcId"] = 210117,
            },
        [12025602] = {
            ["Content"] = "（这位负伤的应天尉在你眼前沉沉睡去，眉头紧蹙，似乎一时半会不会醒来……）",
            ["ContentKR"] = "(눈앞의 부상당한 응천위가 얼굴을 찡그린 채 깊은 잠에 빠져있다. 당분간 깨어나는 건 무리인 듯하다...)",
            ["DialogueId"] = 12025602,
            ["GUID"] = "1E1AD654",
            ["NextDialogue"] = 12025603,
            },
        [12025603] = {
            ["Content"] = "（应天尉也会做梦吗？他在自己的梦境中又会看到什么？你不禁开始思考。）",
            ["ContentKR"] = "(응천위도 꿈을 꾸는 걸까? 어떤 꿈일까? 꿈속에서 뭘 보게 될까? ...나도 모르게 생각에 잠긴다.)",
            ["DialogueId"] = 12025603,
            ["GUID"] = "1E1AD67E",
            ["NextDialogue"] = 12025604,
            },
        [12025604] = {
            ["Content"] = "怎么了小仆从，在欣赏本魔王的大作吗？",
            ["ContentKR"] = "시종, 왜 그래? 이 마왕님의 걸작을 감상하는 중이야?",
            ["DialogueId"] = 12025604,
            ["GUID"] = "1E1AD6A8",
            ["NextDialogue"] = 12025605,
            ["SpeakNpcName"] = "UI_Npc_Name_Bai",
            },
        [12025605] = {
            ["Content"] = "想要的话，我也可以给你脸上画一个皎皎涂鸦哟！只要是小仆从的要求，白都会满足！",
            ["ContentKR"] = "원한다면 네 얼굴에도 루나 낙서를 그려줄게! 시종의 부탁이라면, 당연히 들어줘야지!",
            ["DialogueId"] = 12025605,
