  { MinKey = 12025701, MaxKey = 12030511, Loader = function()
      return {
        [12025701] = {
            ["Content"] = "嘿，我说你们俩——还真是止流掌柜的客人。",
            ["ContentKR"] = "어이, 거기 둘... 진짜 지류 사장님의 손님이잖아.",
            ["DialogueId"] = 12025701,
            ["GUID"] = "1E1AE692",
            ["NextDialogue"] = 12025702,
            ["SpeakNpcId"] = 210118,
            },
        [12025702] = {
            ["Content"] = "我天天在这儿望风，想混进黑市的人可真不少，各种借口我都听得耳朵起茧子了。但像你们这么冒失的我还是头一回见。",
            ["ContentKR"] = "여기서 매일 망을 보는 게 내 일이야. 암시장에 숨어들려는 놈들이 한둘이 아니라서 말이지. 하도 들어서 웬만한 핑계는 다 꿰고 있다니까. 근데 너희처럼 무모한 손님은 처음이군.",
            ["DialogueId"] = 12025702,
            ["GUID"] = "1E1AE6BC",
            ["NextDialogue"] = 12025703,
            ["SpeakNpcId"] = 210118,
            },
        [12025703] = {
            ["Content"] = "既然你们现在已经是虬先生的座上宾了……嘿嘿，能不能帮我在老大面前美言两句。就说他手下的张三，愿意鞍前马后为他老人家效劳！",
            ["ContentKR"] = "너희는 규선생의 귀한 손님이니까... 헤헤, 대장한테 날 좀 좋게 얘기 좀 해줄 수 있을까? 이 장삼이 어르신을 곁에서 보필하고 싶어 한다고!",
            ["DialogueId"] = 12025703,
            ["GUID"] = "1E1AE6E6",
            ["NextDialogue"] = 12025704,
            ["SpeakNpcId"] = 210118,
            },
        [12025704] = {
            ["Content"] = "你们说，我天天在这儿望着，连潮声岩穴的对侧都快望穿了，按照风水轮流转的道理，也该轮到些能捞油水的位置了。",
            ["ContentKR"] = "여기서 맨날 파도의 동굴만 뚫어져라 쳐다보고 있다고. 운수는 돌고 돈다는데, 나도 이제 좀 좋은 자리에서 한몫 챙겨보고 싶어.",
            ["DialogueId"] = 12025704,
            ["GUID"] = "1E1AE710",
            ["NextDialogue"] = 12025705,
            ["SpeakNpcId"] = 210118,
            },
        [12025705] = {
            ["Content"] = "总不能苦活都给我一个人干了吧，是不是这个理？",
            ["ContentKR"] = "고생 좀 했으면 이제 볕들 날도 있어야 하는 거잖아, 안 그래?",
            ["DialogueId"] = 12025705,
            ["GUID"] = "1E1AE73A",
            ["SpeakNpcId"] = 210118,
            },
        [12025801] = {
            ["Content"] = "小友，你来了，坐。",
            ["ContentKR"] = "왔는가, 앉게.",
            ["DialogueId"] = 12025801,
            ["GUID"] = "1E1AF6FA",
            ["NextDialogue"] = 12025802,
            ["SpeakNpcId"] = 210119,
            },
        [12025802] = {
            ["Content"] = "百年的陈皮，刚沏好的，润润嗓子再来与我分享旅途的见闻吧。",
            ["ContentKR"] = "100년 된 진피로 갓 우려낸 차라네. 목부터 좀 축이고 여행에서 겪은 일들을 얘기해 보게나.",
            ["DialogueId"] = 12025802,
            ["GUID"] = "1E1AF724",
            ["NextDialogue"] = 12025828,
            ["SpeakNpcId"] = 210119,
            },
        [12025803] = {
            ["Content"] = "你为什么收藏这么多古董？",
            ["ContentKR"] = "골동품은 왜 이렇게 많이 수집하신 거예요?",
            ["DialogueId"] = 12025803,
            ["GUID"] = "1E1AF74E",
            ["NextDialogue"] = 12025804,
            },
        [12025804] = {
            ["Content"] = "物欲深重，想要自然就要得到，这是所有活物最真实的本能。",
            ["ContentKR"] = "물욕 때문이지. 갖고 싶은 건 가져야 한다, 그건 살아있다면 누구나 가진 본능 같은 것 아니겠나.",
            ["DialogueId"] = 12025804,
            ["GUID"] = "1E1AF778",
            ["NextDialogue"] = 12025805,
            ["SpeakNpcId"] = 210119,
            },
        [12025805] = {
            ["Content"] = "更何况，古董并非仅是眼前的死物，它们都曾经在他人的故事中活过，说是牵连着千百个春秋，也不为过。",
            ["ContentKR"] = "더구나 골동품은 그저 쓸모없는 물건이 아니라, 다른 사람의 이야기 속에 살았던 것들이지. 수많은 세월의 흐름이 깃들어 있다고 해도 과언이 아니야.",
            ["DialogueId"] = 12025805,
            ["GUID"] = "1E1AF7A2",
            ["NextDialogue"] = 12025806,
            ["SpeakNpcId"] = 210119,
            },
        [12025806] = {
            ["Content"] = "听着玄之又玄，怪难懂的。",
            ["ContentKR"] = "너무 오묘해서 이해하기 어렵네요.",
            ["DialogueId"] = 12025806,
            ["GUID"] = "1E1AF7CC",
            ["NextDialogue"] = 12025807,
            ["SpeakNpcId"] = 100001,
            },
        [12025807] = {
            ["Content"] = "这柄短剑，抵御过外敌，刺杀过君主，最后是殉了主。这碎茶盏呢，迎接了游子，送别了挚爱，最后是在赌书时被打翻在地。",
            ["ContentKR"] = "이 단검은 외적을 막아냈고, 군주를 암살했지만 결국 주인과 함께 쓰러졌네. 또, 이 금 간 찻잔은 길 떠난 나그네를 맞이했고, 사랑하는 이를 떠나보낸 후, 결국 글 겨루기 도중 바닥에 엎어지고 말았지.",
            ["DialogueId"] = 12025807,
            ["GUID"] = "1E1AF7F6",
            ["NextDialogue"] = 12025808,
            ["SpeakNpcId"] = 210119,
            },
        [12025808] = {
            ["Content"] = "当我触碰到这些古物时，好像此间并非只有你我二人，而是有七八幕景，十二三人，几百年事。这就是为什么我要收集它们，绝不收手。",
            ["ContentKR"] = "이 낡은 물건들을 만질 때, 이 자리엔 자네와 나만 있는 게 아니네. 수많은 장면과 사람들, 수백 년의 세월이 함께함을 느낄 수 있지. 그게 내가 결코 수집을 포기하지 못하는 이유네.",
            ["DialogueId"] = 12025808,
            ["GUID"] = "1E1AF820",
            ["NextDialogue"] = 12025828,
            ["SpeakNpcId"] = 210119,
            },
        [12025809] = {
            ["Content"] = "听说你很贪得无厌。",
            ["ContentKR"] = "당신은 욕심꾼이라고 들었어요.",
            ["DialogueId"] = 12025809,
            ["GUID"] = "1E1AF84A",
            ["NextDialogue"] = 12025810,
            },
        [12025810] = {
            ["Content"] = "贪得无厌？我喜欢这个评价。",
            ["ContentKR"] = "욕심꾼? 마음에 드는 평가로군.",
            ["DialogueId"] = 12025810,
            ["GUID"] = "1E1AF874",
            ["NextDialogue"] = 12025811,
            ["SpeakNpcId"] = 210119,
            },
        [12025811] = {
            ["Content"] = "我若不贪，便是暴殄天物，无数珍宝与秘密将被埋葬于过去，永世无人知晓。",
            ["ContentKR"] = "만약 내가 욕심이 없었다면, 그 진귀한 보물과 비밀들이 아무도 모르는 과거에 묻히는 것인데, 너무 아깝지 않은가?",
            ["DialogueId"] = 12025811,
            ["GUID"] = "1E1AF89E",
            ["NextDialogue"] = 12025812,
            ["SpeakNpcId"] = 210119,
            },
        [12025812] = {
            ["Content"] = "人若不贪，便是有违这世间最朴素的道理：物欲，才是让人前行的动力，让万物演进的根本。",
            ["ContentKR"] = "사람이 욕심을 부리지 않는 것은, 이 세상의 가장 근본적인 도리에 어긋나는 것이네. 물욕이야말로 앞으로 나아가게 하는 동력이고 만물을 발전시키는 근본이라네.",
            ["DialogueId"] = 12025812,
            ["GUID"] = "1E1AF8C8",
            ["NextDialogue"] = 12025813,
            ["SpeakNpcId"] = 210119,
            },
        [12025813] = {
            ["Content"] = "可并不是所有人都这么想。",
            ["ContentKR"] = "하지만 모두가 그렇게 생각하는 건 아니죠.",
            ["DialogueId"] = 12025813,
            ["GUID"] = "1E1AF8F2",
            ["NextDialogue"] = 12025814,
            ["SpeakNpcId"] = 100001,
            },
        [12025814] = {
            ["Content"] = "无所谓，你大可以说这是厚颜无耻的诡辩，但我更喜欢将它描述为，顺应自我，随心所欲。",
            ["ContentKR"] = "상관없네. 뻔뻔한 궤변이라고 해도 좋아. 물론 난 그걸 자기 자신에게 순응한다고 표현하고 싶지만.",
            ["DialogueId"] = 12025814,
            ["GUID"] = "1E1AF91C",
            ["NextDialogue"] = 12025815,
            ["SpeakNpcId"] = 210119,
            },
        [12025815] = {
            ["Content"] = "大部分人想成为虬先生，但是却不会做虬先生，不敢做虬先生。最终连自己也做不成，只会躲在道理规矩背后谩骂我，可怜呐。",
            ["ContentKR"] = "다들 규선생이 되고 싶어 하지만 규선생이 될 수 없고, 될 엄두도 내지 못하지. 결국엔 자기 자신도 되지 못하고, 도리와 규칙 뒤에 숨어 내 욕이나 하겠지. 참 가엾지 않은가.",
            ["DialogueId"] = 12025815,
            ["GUID"] = "1E1AF946",
            ["NextDialogue"] = 12025802,
            ["SpeakNpcId"] = 210119,
            },
        [12025816] = {
            ["Content"] = "公尚师傅是谁？",
            ["ContentKR"] = "공상 사부는 누구죠?",
            ["DialogueId"] = 12025816,
            ["GUID"] = "1E1AF970",
            ["NextDialogue"] = 12025817,
            },
        [12025817] = {
            ["Content"] = "我资助的一位机枢派奇人。",
            ["ContentKR"] = "내가 후원하고 있는 기추파의 기인이라네.",
            ["DialogueId"] = 12025817,
            ["GUID"] = "1E1AF99A",
            ["NextDialogue"] = 12025818,
            ["SpeakNpcId"] = 210119,
            },
        [12025818] = {
            ["Content"] = "俗语说“人无癖不可交”。他便是我所见之人中癖好最为深重，行事最为乖张的一位了。",
            ["ContentKR"] = "\"취미가 없는 사람과는 친구가 될 수 없다\"라는 말이 있지. 공상 사부는 내가 아는 이 중에서 가장 취향이 특이하고 엉뚱한 인물일세.",
            ["DialogueId"] = 12025818,
            ["GUID"] = "1E1AF9C4",
            ["NextDialogue"] = 12025819,
            ["SpeakNpcId"] = 210119,
            },
        [12025819] = {
            ["Content"] = "人不怕性情怪异，怕的是平庸。他那打造机枢的手艺，当世也没几位比得上的。要不是他看不上天梁司的做派，也不会流落民间受我资助。",
            ["ContentKR"] = "평범한 것보단 괴팍한 게 낫다 했지. 그의 기추 장치 제작술은 이 세상에 견줄 자가 없을 정도네. 그가 천량사의 작태를 못마땅하게 여기지만 않았어도, 재야에서 내 후원이나 받는 신세로 전락하진 않았을 것이야.",
            ["DialogueId"] = 12025819,
            ["GUID"] = "1E1AF9EE",
            ["NextDialogue"] = 12025820,
            ["SpeakNpcId"] = 210119,
            },
        [12025820] = {
            ["Content"] = "这等性情的奇人，就算当着面骂我，我也只会一笑了之。",
            ["ContentKR"] = "그런 성격의 기인이니, 내 면전에서 나를 욕해도, 그냥 웃어넘기는 것이네.",
            ["DialogueId"] = 12025820,
            ["GUID"] = "1E1AFA18",
            ["NextDialogue"] = 12025828,
            ["SpeakNpcId"] = 210119,
            },
        [12025821] = {
            ["Content"] = "你和止流掌柜是合作关系吗？",
            ["ContentKR"] = "지류 사장님과는 협력 관계인가요?",
            ["DialogueId"] = 12025821,
            ["GUID"] = "1E1AFA42",
            ["NextDialogue"] = 12025822,
            },
        [12025822] = {
            ["Content"] = "你如果这样定义各取所需，那便是。",
            ["ContentKR"] = "협력의 정의가 서로 필요한 것을 얻는 관계라면, 그렇다고 할 수 있지.",
            ["DialogueId"] = 12025822,
            ["GUID"] = "1E1AFA6C",
            ["NextDialogue"] = 12025823,
            ["SpeakNpcId"] = 210119,
            },
        [12025823] = {
            ["Content"] = "那要是有一天她不再能提供你需要的东西，你会背叛她吗？",
            ["ContentKR"] = "그럼 지류 사장님이 더 이상 필요한 걸 제공할 수 없게 된다면, 배신할 건가요?",
            ["DialogueId"] = 12025823,
            ["GUID"] = "1E1AFA96",
            ["NextDialogue"] = 12025824,
            ["SpeakNpcId"] = 100001,
            },
        [12025824] = {
            ["Content"] = "哈哈，小友这个问题有些天真了！世上无恒久之友，也无恒久之敌。人与人之间的立场流动不定，又何来背不背叛一说呢？",
            ["ContentKR"] = "하하, 순진한 질문이군! 이 세상엔 영원한 벗도, 영원한 적도 없다네. 상황과 입장은 끊임없이 바뀌는 것인데, 어찌 배신을 논할 수 있겠나?",
            ["DialogueId"] = 12025824,
            ["GUID"] = "1E1AFAC0",
            ["NextDialogue"] = 12025825,
            ["SpeakNpcId"] = 210119,
            },
        [12025825] = {
            ["Content"] = "不过有一件事你大可放心。你们止流掌柜是个聪明人，她会用利益将别人紧紧和她捆绑在一条战船上。你说的那一天，大抵是不会发生的。",
            ["ContentKR"] = "하지만 이것만은 걱정 말게. 지류 사장은 이익을 이용해 협력자를 단단히 묶어둘 줄 아는 현명한 사람이네. 자네가 말하는 상황은 아마 영원히 오지 않을 걸세.",
            ["DialogueId"] = 12025825,
            ["GUID"] = "1E1AFAEA",
            ["NextDialogue"] = 12025828,
            ["SpeakNpcId"] = 210119,
            },
        [12025826] = {
            ["Content"] = "我先走了。",
            ["ContentKR"] = "이만 가볼게요.",
            ["DialogueId"] = 12025826,
            ["GUID"] = "1E1AFB14",
            ["NextDialogue"] = 12025827,
            },
        [12025827] = {
            ["Content"] = "慢走，不送。",
            ["ContentKR"] = "잘 가게, 배웅은 생략하지.",
            ["DialogueId"] = 12025827,
            ["GUID"] = "1E1AFB3E",
            ["SpeakNpcId"] = 210119,
            },
        [12025828] = {
            ["DialogueId"] = 12025828,
            ["DialoguePanelType"] = "None",
            ["Duration"] = 0,
            ["FinalDialogueId"] = 12025827,
            ["GUID"] = "1E1AFB3F",
            ["NextOptions"] = {
                [1] = 12025803,
                [2] = 12025809,
                [3] = 12025816,
                [4] = 12025821,
                [5] = 51155701,
                [6] = 12025826,
                },
            },
        [12025901] = {
            ["Content"] = "恩人……谢……谢你…………",
            ["ContentKR"] = "은... 은인님... 감... 감사합니다...",
            ["DialogueId"] = 12025901,
            ["GUID"] = "1E1B0762",
            ["NextDialogue"] = 12025902,
            ["SpeakNpcId"] = 210120,
            },
        [12025902] = {
            ["Content"] = "（你眼前的姑娘面色苍白，额头上冒出豆大的汗珠，却还在勉力向你道谢。被狴犴惩戒后，她明显需要休息。）",
            ["ContentKR"] = "(소녀는 창백한 얼굴로 이마에 땀방울이 맺힌 채, 힘겹게 감사를 전한다. 폐안에게 벌을 받은 직후라 휴식이 필요해 보인다.)",
            ["DialogueId"] = 12025902,
            ["GUID"] = "1E1B078C",
            ["NextDialogue"] = 12025903,
            },
        [12025903] = {
            ["Content"] = "您放心，您放心，大家都是朋友！我一定把她照顾得妥妥帖帖，一根毫毛都不会伤到！",
            ["ContentKR"] = "걱정 마세요, 모두 친구 아닙니까! 제가 털끝 하나 다치지 않게 잘 돌볼테니 걱정일랑 붙들어 매시죠!",
            ["DialogueId"] = 12025903,
            ["GUID"] = "1E1B07B6",
            ["NextDialogue"] = 12025904,
            ["SpeakNpcName"] = "UI_Npc_Name_Badshangren",
            },
        [12025904] = {
            ["Content"] = "哎呀，我的{性别：姑爷爷|姑奶奶}，算我求求您，赶紧去见虬先生吧，别让他老人家久等。您们在这里，她也没法安心休息呀。",
            ["ContentKR"] = "어휴, 제발 부탁이니 어르신 기다리게 하지 말고 얼른 가시죠. 이렇게 다들 우르르 몰려 있으면 아가씨도 편히 쉴 수 없을 겁니다.",
            ["DialogueId"] = 12025904,
            ["GUID"] = "1E1B07E0",
            ["SpeakNpcName"] = "UI_Npc_Name_Badshangren",
            },
        [12026001] = {
            ["Content"] = "这位荣誉学徒，有什么想向我请教的？",
            ["ContentKR"] = "명예 제자, 묻고 싶은 거라도 있나?",
            ["DialogueId"] = 12026001,
            ["GUID"] = "1E1B17CA",
            ["NextDialogue"] = 12026025,
            ["SpeakNpcId"] = 210121,
            },
        [12026002] = {
            ["Content"] = "可以再说明一下什么是尘漠吗？",
            ["ContentKR"] = "낙진에 대해 다시 한번 설명해 주실 수 있나요?",
            ["DialogueId"] = 12026002,
            ["GUID"] = "1E1B17F4",
            ["NextDialogue"] = 12026003,
            },
        [12026003] = {
            ["Content"] = "唉，遥想当初，过目不忘可是入门我机枢派的最基础。资质愚钝者，早在娃娃之时就被刷下去了。",
            ["ContentKR"] = "휴우, 우리 기추파에 들어오려면 한 번 보면 절대 잊지 않는 게 기본 소양이었거늘. 자질이 모자란 녀석들은 걸음마를 시작할 때부터 걸러지곤 했어.",
            ["DialogueId"] = 12026003,
            ["GUID"] = "1E1B181E",
            ["NextDialogue"] = 12026004,
            ["SpeakNpcId"] = 210121,
            },
        [12026004] = {
            ["Content"] = "罢了罢了。做人不能强求，你有这份求知欲，也算是很珍贵了。我就再给你说明一次吧。",
            ["ContentKR"] = "됐네, 억지로 강요할 수야 없지. 그 학구열도 귀한 것이니, 다시 한번 설명해 주겠네.",
            ["DialogueId"] = 12026004,
            ["GUID"] = "1E1B1848",
            ["NextDialogue"] = 12026005,
            ["SpeakNpcId"] = 210121,
            },
        [12026005] = {
            ["Content"] = "这空气中弥漫着一种名为太虚，看不见摸不着的物质。这时你就要问了，既然是看不见摸不着，那怎么确定它存在呢？",
            ["ContentKR"] = "이 공기 중엔 태허라는 물질이 퍼져 있다네. 볼 수도 없고 만질 수도 없는 물질이지. 그렇다면 궁금하겠지. 볼 수도 없고 만질 수도 없는데 어떻게 존재한다고 확신하는지.",
            ["DialogueId"] = 12026005,
            ["GUID"] = "1E1B1872",
            ["NextDialogue"] = 12026006,
            ["SpeakNpcId"] = 210121,
            },
        [12026006] = {
            ["Content"] = "我们研究者自有各种手段去侧面观察它。这尘漠，便是太虚存在的最好佐证——",
            ["ContentKR"] = "우리 연구자들은 다양한 방법으로 태허를 간접적으로 관찰한다네. 이 낙진이 바로 태허가 존재한다는 가장 유력한 증거일세.",
            ["DialogueId"] = 12026006,
            ["GUID"] = "1E1B189C",
            ["NextDialogue"] = 12026007,
            ["SpeakNpcId"] = 210121,
            },
        [12026007] = {
            ["Content"] = "空气中的太虚受烛阴之灾影响，其性质发生转变，固化成蒙于物体表面的粉末。这对一般生命有害的粉末便是尘漠。这样一说，你可懂了？",
            ["ContentKR"] = "공기 중의 태허는 촉룡의 재앙의 영향을 받아 그 성질이 변하고, 고체화되어 물체 표면에 가루가 되어 쌓이네. 평범한 생물에게 해로운 이 가루가 바로 낙진이라네. 이제 이해가 됐나?",
            ["DialogueId"] = 12026007,
            ["GUID"] = "1E1B18C6",
            ["NextDialogue"] = 12026025,
            ["SpeakNpcId"] = 210121,
            },
        [12026008] = {
            ["Content"] = "可以再说明一下牵机方枢的用法吗？",
            ["ContentKR"] = "견기방추의 사용법에 대해 다시 한번 설명해 주실 수 있나요?",
            ["DialogueId"] = 12026008,
            ["GUID"] = "1E1B18F0",
            ["NextDialogue"] = 12026009,
            },
        [12026009] = {
            ["Content"] = "嗯？我手写的数百页使用说明书与牵机方枢一并存放于秦虬那里，他没有交给你们吗？",
            ["ContentKR"] = "응? 내가 직접 쓴 수백 페이지 분량의 사용 설명서를 견기방추와 함께 진규 놈에게 건네줬었는데, 못 받았나?",
            ["DialogueId"] = 12026009,
            ["GUID"] = "1E1B191A",
            ["NextDialogue"] = 12026010,
            ["SpeakNpcId"] = 210121,
            },
        [12026010] = {
            ["Content"] = "没有。他只让我来请教你。",
            ["ContentKR"] = "네, 사부님께 여쭤보라고 했어요.",
            ["DialogueId"] = 12026010,
            ["GUID"] = "1E1B1944",
            ["NextDialogue"] = 12026011,
            ["SpeakNpcId"] = 100001,
            },
        [12026011] = {
            ["Content"] = "……那老东西，我就知道。他一定觉得你会字多不看，没必要把这洋洋洒洒数十万字的说明书交给你。我机枢派的荣誉学徒，能是这种品性的人吗？",
            ["ContentKR"] = "...그놈이 그럴 줄 알았지. 내용이 길면 어차피 안 읽을 테니, 수십 만 자나 되는 설명서를 건네줄 필요가 없다고 생각한 거겠지. 이 기추파의 명예 제자가 어디 그럴 사람이겠는가?",
            ["DialogueId"] = 12026011,
            ["GUID"] = "1E1B196E",
            ["NextDialogue"] = 12026012,
            ["SpeakNpcId"] = 210121,
            },
        [12026012] = {
            ["Content"] = "算了，我就简单解说一下吧。很简单，按下这个按钮，对着尘漠，吸。完事了。",
            ["ContentKR"] = "됐네, 간단히 설명해 주지. 자, 이 버튼을 누르고 낙진을 향해 빨아당기면 된다네. 그게 다일세.",
            ["DialogueId"] = 12026012,
            ["GUID"] = "1E1B1998",
            ["NextDialogue"] = 12026013,
            ["SpeakNpcId"] = 210121,
            },
        [12026013] = {
            ["Content"] = "就这样？",
            ["ContentKR"] = "그게 다인가요?",
            ["DialogueId"] = 12026013,
            ["GUID"] = "1E1B19C2",
            ["NextDialogue"] = 12026014,
            ["SpeakNpcId"] = 100001,
            },
        [12026014] = {
            ["Content"] = "就这样。你莫非还要我从原理开始解说不成？",
            ["ContentKR"] = "그렇네. 혹시 원리부터 설명해 주길 바라는 건가?",
            ["DialogueId"] = 12026014,
            ["GUID"] = "1E1B19EC",
            ["NextDialogue"] = 12026015,
            ["SpeakNpcId"] = 210121,
            },
        [12026015] = {
            ["Content"] = "没有没有，这样就很好了。谢谢师父！",
            ["ContentKR"] = "아, 아뇨, 이 정도면 충분해요. 감사합니다, 스승님!",
            ["DialogueId"] = 12026015,
            ["GUID"] = "1E1B1A16",
            ["NextDialogue"] = 12026025,
            },
        [12026016] = {
            ["Content"] = "机枢派为什么没落了？",
            ["ContentKR"] = "기추파는 왜 몰락한 건가요?",
            ["DialogueId"] = 12026016,
            ["GUID"] = "1E1B1A40",
            ["NextDialogue"] = 12026017,
            },
        [12026017] = {
            ["Content"] = "我机枢派的人，首先要学会用辨证的思维看待事物——何为没落？",
            ["ContentKR"] = "기추파의 일원이라면 변증법적 사고로 사물을 바라볼 줄 알아야지... 몰락이란 무엇인가?",
            ["DialogueId"] = 12026017,
            ["GUID"] = "1E1B1A6A",
            ["NextDialogue"] = 12026018,
            ["SpeakNpcId"] = 210121,
            },
        [12026018] = {
            ["Content"] = "机枢派的造物从南向北遍布整个华胥，哪个码头见不到搬运货物的木走马？天梁司还高居华胥三大司之一，这能叫没落吗？",
            ["ContentKR"] = "기추파에서 만든 물건이 아직도 화서 전역에 퍼져있고, 어느 항구에 가든 화물을 나르는 목마를 볼 수 있지. 게다가 천량사는 여전히 화서의 3대 기관으로 우뚝 서 있네. 이게 몰락인가?",
            ["DialogueId"] = 12026018,
            ["GUID"] = "1E1B1A94",
            ["NextDialogue"] = 12026019,
            ["SpeakNpcId"] = 210121,
            },
        [12026019] = {
            ["Content"] = "那个……机枢派没落了招不到学生，好像是你和我说的？",
            ["ContentKR"] = "저기... 기추파가 몰락해서 학생 모집이 힘들다고 하신 건 스승님이시잖아요?",
            ["DialogueId"] = 12026019,
            ["GUID"] = "1E1B1ABE",
            ["NextDialogue"] = 12026020,
            ["SpeakNpcId"] = 100001,
            },
        [12026020] = {
            ["Content"] = "聪明，这就是辨证思维的另一面了。",
            ["ContentKR"] = "옳거니, 정반합의 '반'이로군. 변증법을 좀 아는구먼.",
            ["DialogueId"] = 12026020,
            ["GUID"] = "1E1B1AE8",
            ["NextDialogue"] = 12026021,
            ["SpeakNpcId"] = 210121,
            },
        [12026021] = {
            ["Content"] = "世人失去了求知欲，无人愿意考入机枢派，天梁司那些老东西只知道闭门造车，不再去穷事物之极理——这是没落。",
            ["ContentKR"] = "사람들은 학구열을 잃었고, 아무도 기추파에 들어오려 하지 않는다네. 천량사의 늙은이들은 현실을 외면한 채 연구에만 매달릴 뿐, 더 이상 사물의 궁극적인 이치를 탐구하지 않아. 그게 몰락이지.",
            ["DialogueId"] = 12026021,
            ["GUID"] = "1E1B1B12",
            ["NextDialogue"] = 12026022,
            ["SpeakNpcId"] = 210121,
            },
        [12026022] = {
            ["Content"] = "现在我回答你的问题，机枢派为什么没落？是悬衡派那些家伙干的，因为他们害怕知识带来的力量会超出他们的掌控，所以让机枢派没落了。就这么简单。",
            ["ContentKR"] = "이제 자네의 질문에 대답해 주지. 기추파는 몰락하게 된 건, 현형파 녀석들 때문이네. 지식이 가져올 힘이 자신의 통제를 벗어날까 두려워서, 기추파를 몰락으로 내몬 거네. 그게 다야.",
            ["DialogueId"] = 12026022,
            ["GUID"] = "1E1B1B3C",
            ["NextDialogue"] = 12026025,
            ["SpeakNpcId"] = 210121,
            },
        [12026023] = {
            ["Content"] = "还有好多问题，我想想。",
            ["ContentKR"] = "아직 궁금한 게 많은데, 좀 더 생각해 볼게요.",
            ["DialogueId"] = 12026023,
            ["GUID"] = "1E1B1B66",
            ["NextDialogue"] = 12026024,
            },
        [12026024] = {
            ["Content"] = "打破砂锅问到底，是个好苗子。好了，我要忙去了，你也不要疏忽了日常功课啊。",
            ["ContentKR"] = "끝까지 물고 늘어질 줄 아는 걸 보니, 미래가 기대되는군. 내 볼일이 있어 이만 가볼 테니, 평소에도 공부를 게을리하지 말게.",
            ["DialogueId"] = 12026024,
            ["GUID"] = "1E1B1B90",
            ["SpeakNpcId"] = 210121,
            },
        [12026025] = {
            ["DialogueId"] = 12026025,
            ["DialoguePanelType"] = "None",
            ["Duration"] = 0,
            ["FinalDialogueId"] = 12026024,
            ["GUID"] = "1E1B1B91",
            ["NextOptions"] = {
                [1] = 12026002,
                [2] = 12026008,
                [3] = 12026016,
                [4] = 12026023,
                },
            },
        [12026101] = {
            ["Content"] = "瞧瞧是谁来了——原来是帮百年春化解危机的大英雄{nickname}！",
            ["ContentKR"] = "어머, 백년춘의 위기를 해결하신 대영웅 {nickname} 님이 오셨네요!",
            ["DialogueId"] = 12026101,
            ["GUID"] = "1E1B2832",
            ["NextDialogue"] = 12026102,
            ["SpeakNpcId"] = 210122,
            },
        [12026102] = {
            ["Content"] = "哪里哪里。我只是做了一些微小的工作，主要还是靠止流掌柜和大家的力量。",
            ["ContentKR"] = "별말씀을요. 전 작은 도움을 드린 게 전부예요. 다 지류 사장님과 여러분의 노력 덕분이죠.",
            ["DialogueId"] = 12026102,
            ["GUID"] = "1E1B285C",
            ["NextDialogue"] = 12026103,
            ["SpeakNpcId"] = 100001,
            },
        [12026103] = {
            ["Content"] = "倒是你经历了这些之后，现在还好吗？",
            ["ContentKR"] = "그나저나, 그런 일들을 겪었는데 괜찮으세요?",
            ["DialogueId"] = 12026103,
            ["GUID"] = "1E1B2886",
            ["NextDialogue"] = 12026104,
            ["SpeakNpcId"] = 100001,
            },
        [12026104] = {
            ["Content"] = "呵呵，说出来不怕你笑话……现在比起后怕，我心里反而激荡着一种能够保卫家园的兴奋感，甚至感觉身体里充满了力量。",
            ["ContentKR"] = "후후, 부끄러운 말이지만... 두려움보단 여길 지켜냈다는 흥분감 때문에 오히려 힘이 넘치는 기분이에요.",
            ["DialogueId"] = 12026104,
            ["GUID"] = "1E1B28B0",
            ["NextDialogue"] = 12026105,
            ["SpeakNpcId"] = 210122,
            },
        [12026105] = {
            ["Content"] = "我甚至动了学几招防身手段的念头，这样以后去别的危险地区行商，也不用光等着护卫来保护自己了。",
            ["ContentKR"] = "심지어 호신술을 좀 배워볼까도 생각했어요. 그러면 위험한 지역에 장사하러 갔을 때, 마냥 호위만 기다리진 않을 테니까요.",
            ["DialogueId"] = 12026105,
            ["GUID"] = "1E1B28DA",
            ["NextDialogue"] = 12026106,
            ["SpeakNpcId"] = 210122,
            },
        [12026106] = {
            ["Content"] = "不过这种念头终归是不符合大风九章的吧……",
            ["ContentKR"] = "하지만 대풍구장에 맞지 않는 생각이겠죠...",
            ["DialogueId"] = 12026106,
            ["GUID"] = "1E1B2904",
            ["SpeakNpcId"] = 210122,
            },
        [12026201] = {
            ["Content"] = "怎么了，{nickname}？有什么事吗？",
            ["ContentKR"] = "{nickname}, 무슨 일이라도 있어?",
            ["DialogueId"] = 12026201,
            ["GUID"] = "1E1B389A",
            ["NextDialogue"] = 12026202,
            ["SpeakNpcId"] = 210123,
            },
        [12026202] = {
            ["Content"] = "（止流的举止一如往常，但你总觉得她有些不易察觉的疲惫……是错觉吗？）",
            ["ContentKR"] = "(지류 사장님은 평소와 다름없지만, 어딘가 모르게 피로감이 느껴진다... 착각일까?)",
            ["DialogueId"] = 12026202,
            ["GUID"] = "1E1B38C4",
            ["NextDialogue"] = 12026213,
            },
        [12026203] = {
            ["Content"] = "止流掌柜，你接下来有什么安排？",
            ["ContentKR"] = "지류 사장님, 앞으로 어떡하실 계획이세요?",
            ["DialogueId"] = 12026203,
            ["GUID"] = "1E1B38EE",
            ["NextDialogue"] = 12026204,
            },
        [12026204] = {
            ["Content"] = "有了你采来的这些烛阴鳞，封印烛阴的准备也算是完毕了。接下来我便要先筹备此事，可能暂时无法分神接待你们了，先说一句抱歉。",
            ["ContentKR"] = "네가 가져다준 촉룡 비늘 덕분에 촉룡 봉인 준비는 거의 끝났어. 이제 본격적으로 봉인을 준비해야 해서 당분간 시간이 나지 않을 것 같아, 미안.",
            ["DialogueId"] = 12026204,
            ["GUID"] = "1E1B3918",
            ["NextDialogue"] = 12026205,
            ["SpeakNpcId"] = 210123,
            },
        [12026205] = {
            ["Content"] = "真的不需要我帮忙吗？",
            ["ContentKR"] = "정말 도와드리지 않아도 괜찮으시겠어요?",
            ["DialogueId"] = 12026205,
            ["GUID"] = "1E1B3942",
            ["NextDialogue"] = 12026206,
            ["SpeakNpcId"] = 100001,
            },
        [12026206] = {
            ["Content"] = "呵呵，你倒是有心了。也不能总让你一个人忙前忙后。若出现了难以搞定的事情，我会再来委托你们的。",
            ["ContentKR"] = "후후, 말만이라도 고마워. 그래도 너한테만 모든 걸 맡길 순 없지. 처리하기 어려운 일이 생기면 그때 다시 부탁할게.",
            ["DialogueId"] = 12026206,
            ["GUID"] = "1E1B396C",
            ["NextDialogue"] = 12026213,
            ["SpeakNpcId"] = 210123,
            },
        [12026207] = {
            ["Content"] = "刚刚百年春的危机真是凶险。",
            ["ContentKR"] = "방금은 정말 아슬아슬했죠.",
            ["DialogueId"] = 12026207,
            ["GUID"] = "1E1B3996",
            ["NextDialogue"] = 12026208,
            },
        [12026208] = {
            ["Content"] = "嗯。这场危机化解也有你的一份功劳。多谢了，{nickname}。",
            ["ContentKR"] = "맞아, 네 덕분에 백년춘의 위기를 해결할 수 있었어. 고마워, {nickname}.",
            ["DialogueId"] = 12026208,
            ["GUID"] = "1E1B39C0",
            ["NextDialogue"] = 12026209,
            ["SpeakNpcId"] = 210123,
            },
        [12026209] = {
            ["Content"] = "我没做什么，主要还是靠你组织起来了大家，你当时的应对好迅速。",
            ["ContentKR"] = "별로 한 것도 없는데요, 뭘. 사장님이 잘 지휘하신 덕분이죠. 대처가 정말 빠르시던걸요.",
            ["DialogueId"] = 12026209,
            ["GUID"] = "1E1B39EA",
            ["NextDialogue"] = 12026210,
            ["SpeakNpcId"] = 100001,
            },
        [12026210] = {
            ["Content"] = "呵呵，做事若是畏手畏脚，瞻前顾后，又怎能负起众人之望呢？",
            ["ContentKR"] = "후후, 중요한 일 앞에서 결과를 걱정하느라 망설인다면, 어떻게 사람들의 기대에 부응할 수 있겠어?",
            ["DialogueId"] = 12026210,
            ["GUID"] = "1E1B3A14",
            ["NextDialogue"] = 12026213,
            ["SpeakNpcId"] = 210123,
            },
        [12026211] = {
            ["Content"] = "……",
            ["ContentKR"] = "......",
            ["DialogueId"] = 12026211,
            ["GUID"] = "1E1B3A3E",
            ["NextDialogue"] = 12026212,
            },
        [12026212] = {
            ["Content"] = "我要先去筹备封印烛阴的相关事宜了。你现在得了空闲，去逛逛吧。有什么开销记在我账上就行，不用对我客气。",
            ["ContentKR"] = "난 촉룡 봉인을 준비하러 먼저 가볼게. 너도 이제 시간이 생겼으니 이곳저곳 구경해 봐. 사고 싶은 게 있으면 사양 말고 내 이름으로 달아두고.",
            ["DialogueId"] = 12026212,
            ["GUID"] = "1E1B3A68",
            ["SpeakNpcId"] = 210123,
            },
        [12026213] = {
            ["DialogueId"] = 12026213,
            ["DialoguePanelType"] = "None",
            ["Duration"] = 0,
            ["FinalDialogueId"] = 12026212,
            ["GUID"] = "1E1B3A69",
            ["NextOptions"] = {
                [1] = 12026203,
                [2] = 12026207,
                [3] = 12026211,
                },
            },
        [12026301] = {
            ["Content"] = "恩人，你来看望我了……",
            ["ContentKR"] = "은인님, 절 보러 와주셨군요...",
            ["DialogueId"] = 12026301,
            ["GUID"] = "1E1B4902",
            ["NextDialogue"] = 12026302,
            ["SpeakNpcId"] = 210124,
            },
        [12026302] = {
            ["Content"] = "你现在好点了吗？",
            ["ContentKR"] = "좀 괜찮아요?",
            ["DialogueId"] = 12026302,
            ["GUID"] = "1E1B492C",
            ["NextDialogue"] = 12026303,
            ["SpeakNpcId"] = 100001,
            },
        [12026303] = {
            ["Content"] = "多亏了您和扶疏大人为我采回来的药，现在我的伤势已经稳定，再过一两天就能下床走动了。",
            ["ContentKR"] = "은인님과 부소 님이 구해주신 약 덕분에 많이 나았어요. 며칠 더 있으면 움직일 수 있을 것 같아요.",
            ["DialogueId"] = 12026303,
            ["GUID"] = "1E1B4956",
            ["NextDialogue"] = 12026304,
            ["SpeakNpcId"] = 210124,
            },
        [12026304] = {
            ["Content"] = "这一遭下来，不知道受了您的多少恩惠……除了言谢之外，我、我想不到别的方式可以报答你。以后有需要我做的，尽管开口，千万不用客气。",
            ["ContentKR"] = "이번 일로 얼마나 많은 은혜를 입었는지... 감사하다는 말 말곤 어, 어떻게 보답해야 할지 모르겠어요. 뭐든 제가 도와드릴 일이 있으면 언제든 말씀해 주세요.",
            ["DialogueId"] = 12026304,
            ["GUID"] = "1E1B4980",
            ["SpeakNpcId"] = 210124,
            },
        [12026401] = {
            ["Content"] = "如果你们在瀑布附近看到了受困的无由生，还请施以援手……多谢二位了。",
            ["ContentKR"] = "폭포 근처에서 도움이 필요한 무유생을 만난다면, 번거롭겠지만... 도와주면 고맙겠소...",
            ["DialogueId"] = 12026401,
            ["GUID"] = "1E1B596A",
            ["SpeakNpcId"] = 210125,
            },
        [12026501] = {
            ["Content"] = "多谢二位，失踪的无由生都被救回来了！真是功德一桩呐！",
            ["ContentKR"] = "정말 고맙소. 실종되었던 무유생들이 모두 무사히 돌아왔구려! 복 받으실 것이오!",
            ["DialogueId"] = 12026501,
            ["GUID"] = "1E1B69D2",
            ["SpeakNpcId"] = 210126,
            },
        [12026601] = {
            ["Content"] = "{nickname}，你来了。",
            ["ContentKR"] = "{nickname}, 오셨군요.",
            ["DialogueId"] = 12026601,
            ["GUID"] = "1E1B7A3A",
            ["NextDialogue"] = 12026602,
            ["SpeakNpcId"] = 210127,
            },
        [12026602] = {
            ["Content"] = "我性喜清净，这枯荣阁中没什么可以用来招待你的，只有半壁医书，一壶茗茶……希望不会使你感到枯燥。",
            ["ContentKR"] = "평소 고영각에서 조용하게 지내는 편이라 대접해 드릴 만한 것이 없네요. 책장을 반쯤 채운 의서와 차 한 주전자가 전부라... 부디 무료함을 느끼지 않으시길.",
            ["DialogueId"] = 12026602,
            ["GUID"] = "1E1B7A64",
            ["NextDialogue"] = 12026603,
            ["SpeakNpcId"] = 210127,
            },
        [12026603] = {
            ["Content"] = "你可以随意走动，把这里当做自己家一般便好。",
            ["ContentKR"] = "집이라고 생각하고 편하게 둘러보세요.",
            ["DialogueId"] = 12026603,
            ["GUID"] = "1E1B7A8E",
            ["NextDialogue"] = 12026640,
            ["SpeakNpcId"] = 210127,
            },
        [12026604] = {
            ["Content"] = "除了治病救人，你在闲暇时间还会做些什么？",
            ["ContentKR"] = "환자를 치료하는 일 외에는 여가 시간에 주로 뭘 하는 편이야?",
            ["DialogueId"] = 12026604,
            ["GUID"] = "1E1B7AB8",
            ["NextDialogue"] = 12026605,
            },
        [12026605] = {
            ["Content"] = "照料病人往往已占据我大部分时间。若是偷得浮生半日闲……我许是会研究家姐留下的医书吧。",
            ["ContentKR"] = "환자를 돌보는 데 대부분의 시간을 할애하는 편이에요. 바쁜 일상 속에 잠시 여유가 생긴다면... 아마도 언니가 남긴 의서를 연구할 것 같네요.",
            ["DialogueId"] = 12026605,
            ["GUID"] = "1E1B7AE2",
            ["NextDialogue"] = 12026606,
            ["SpeakNpcId"] = 210127,
            },
        [12026606] = {
            ["Content"] = "那不还是治病救人吗？！",
            ["ContentKR"] = "그것도 환자를 치료하는 일이잖아?!",
            ["DialogueId"] = 12026606,
            ["GUID"] = "1E1B7B0C",
            ["NextDialogue"] = 12026607,
            ["SpeakNpcId"] = 100001,
            },
        [12026607] = {
            ["Content"] = "若是病人就在眼前，我往往心思急切，无法沉下心去研究药理关联。反倒是漫无目的翻开某页医书，细细研究其晦涩之语时，能体会到一种茅塞顿开的喜悦。",
            ["ContentKR"] = "환자가 바로 눈앞에 있을 땐 마음이 조급해져서 약리학적 연관성을 제대로 연구할 수 없더라고요. 오히려 무작정 의서를 펼쳐 난해한 문장을 음미할 때면 문득 막혔던 것이 뚫리는 기쁨을 느낄 수 있어요.",
            ["DialogueId"] = 12026607,
            ["GUID"] = "1E1B7B36",
            ["NextDialogue"] = 12026608,
            ["SpeakNpcId"] = 210127,
            },
        [12026608] = {
            ["Content"] = "你就没有这之外的爱好了吗？",
            ["ContentKR"] = "다른 취미는 없는 거야?",
            ["DialogueId"] = 12026608,
            ["GUID"] = "1E1B7B60",
            ["NextDialogue"] = 12026609,
            ["SpeakNpcId"] = 100001,
            },
        [12026609] = {
            ["Content"] = "待我想想……抚上一首琴曲，或是与云螭嬉戏，这都是我少时的乐趣。",
            ["ContentKR"] = "음... 어린 시절에는 거문고를 연주하거나 운리와 놀곤 했어요.",
            ["DialogueId"] = 12026609,
            ["GUID"] = "1E1B7B8A",
            ["NextDialogue"] = 12026610,
            ["SpeakNpcId"] = 210127,
            },
        [12026610] = {
            ["Content"] = "那下次弹首琴曲给我听吧。",
            ["ContentKR"] = "그럼 다음에 기회가 생기면 연주 한 번 들려줘.",
            ["DialogueId"] = 12026610,
            ["GUID"] = "1E1B7BB4",
            ["NextDialogue"] = 12026611,
            ["SpeakNpcId"] = 100001,
            },
        [12026611] = {
            ["Content"] = "……是了，我怎么忘了呢。最大的乐趣还是与友人共处，无论赏曲或是谈天说地，都别有一份逸趣。",
            ["ContentKR"] = "...그렇네요, 어쩌다 잊은 걸까요? 가장 큰 즐거움은 친구와 함께하는 시간이라는 걸요. 음악을 감상하든, 이야기를 나누든, 저마다 색다른 묘미가 있잖아요.",
            ["DialogueId"] = 12026611,
            ["GUID"] = "1E1B7BDE",
            ["NextDialogue"] = 12026612,
            ["SpeakNpcId"] = 210127,
            },
        [12026612] = {
            ["Content"] = "{nickname}，你随时可以来枯荣阁找我打发闲暇。我会很乐意你来访。",
            ["ContentKR"] = "{nickname}, 시간 나면 언제든지 고영각에 오셔도 좋아요. 기꺼이 대접해 드릴게요.",
            ["DialogueId"] = 12026612,
            ["GUID"] = "1E1B7C08",
            ["NextDialogue"] = 12026613,
            ["SpeakNpcId"] = 210127,
            },
        [12026613] = {
            ["Content"] = "那就一言为定！",
            ["ContentKR"] = "그럼 약속한 거다!",
            ["DialogueId"] = 12026613,
            ["GUID"] = "1E1B7C32",
            ["NextDialogue"] = 12026640,
            ["SpeakNpcId"] = 100001,
            },
        [12026614] = {
            ["Content"] = "我最近有些不舒服。",
            ["ContentKR"] = "요즘 몸이 좀 안 좋아.",
            ["DialogueId"] = 12026614,
            ["GUID"] = "1E1B7C5C",
            ["NextDialogue"] = 12026615,
            },
        [12026615] = {
            ["Content"] = "怎么了？哪里痛，还是在烟津渡奔行时不慎受伤了？快把手递给我，我帮你细细查探一番。",
            ["ContentKR"] = "네? 어디가요? 연진 나루터에서 다치신 건가요? 얼른 손 이리 줘요. 진찰해 드릴게요.",
            ["DialogueId"] = 12026615,
            ["GUID"] = "1E1B7C86",
            ["NextDialogue"] = 12026616,
            ["SpeakNpcId"] = 210127,
            },
        [12026616] = {
            ["Content"] = "噗嗤，扶疏，你好紧张。",
            ["ContentKR"] = "푸흡, 부소. 너무 긴장하는 거 아냐?",
            ["DialogueId"] = 12026616,
            ["GUID"] = "1E1B7CB0",
            ["NextDialogue"] = 12026617,
            ["SpeakNpcId"] = 100001,
            },
        [12026617] = {
            ["Content"] = "没有那么严重，只是睡醒时常常感觉腰酸背痛而已。",
            ["ContentKR"] = "그렇게 심각한 건 아니고, 그냥 자고 일어나면 허리가 종종 아파.",
            ["DialogueId"] = 12026617,
            ["GUID"] = "1E1B7CDA",
            ["NextDialogue"] = 12026618,
            ["SpeakNpcId"] = 100001,
            },
        [12026618] = {
            ["Content"] = "健康乃大事，就算是小病小痛也不可随意对待。我这里有一套强身健体的五禽戏可以传授于你，助你活络筋骨。",
            ["ContentKR"] = "건강은 중요한 문제이니 사소한 병도 가볍게 생각해선 안 돼요. 오금희 체조를 가르쳐 드릴게요. 혈액 순환을 돕고 통증을 완화해 줄 거예요.",
            ["DialogueId"] = 12026618,
            ["GUID"] = "1E1B7D04",
            ["NextDialogue"] = 12026619,
            ["SpeakNpcId"] = 210127,
            },
        [12026619] = {
            ["Content"] = "为了充分领略五禽的形意，这套拳法须在鸡犬鸣叫，夜色将褪未褪之时开始练习。待到旭阳将出，清风拂面，你必定能感受到锻炼带来的身心舒畅……",
            ["ContentKR"] = "오금의 형태와 뜻을 완전히 이해하려면, 닭과 개가 울고 밤기운이 채 가시지 않은 새벽에 시작해야 해요. 해가 막 떠오르고 산들바람이 얼굴을 스칠 때, 단련으로 상쾌해진 심신을 느끼실 수 있을 거예요...",
            ["DialogueId"] = 12026619,
            ["GUID"] = "1E1B7D2E",
            ["NextDialogue"] = 12026620,
            ["SpeakNpcId"] = 210127,
            },
        [12026620] = {
            ["Content"] = "不、不用了！",
            ["ContentKR"] = "아, 아냐, 됐어!",
            ["DialogueId"] = 12026620,
            ["GUID"] = "1E1B7D58",
            ["NextDialogue"] = 12026621,
            ["SpeakNpcId"] = 100001,
            },
        [12026621] = {
            ["Content"] = "我又想了想，我很好，再好不过了，我从来没有这么健康过！所以你的好意我就心领了，千万不用实践。",
            ["ContentKR"] = "잘 생각해 보니까 나 멀쩡한 것 같아. 이보다 더 멀쩡할 순 없을 거야! 그러니까 마음만 고맙게 받을게!",
            ["DialogueId"] = 12026621,
            ["GUID"] = "1E1B7D82",
            ["NextDialogue"] = 12026622,
            ["SpeakNpcId"] = 100001,
            },
        [12026622] = {
            ["Content"] = "唉，你呀……",
            ["ContentKR"] = "휴, 정말...",
            ["DialogueId"] = 12026622,
            ["GUID"] = "1E1B7DAC",
            ["NextDialogue"] = 12026623,
            ["SpeakNpcId"] = 210127,
            },
        [12026623] = {
            ["Content"] = "这次便让你逃过去了。但若再遇到身体不适的情况，千万不要硬撑，我会为你排忧解难。",
            ["ContentKR"] = "이번에는 그냥 넘어가 주겠지만, 또 몸이 안 좋으면 절대 무리하지 말고 말씀해 주세요. 제가 도와드릴게요.",
            ["DialogueId"] = 12026623,
            ["GUID"] = "1E1B7DD6",
            ["NextDialogue"] = 12026640,
            ["SpeakNpcId"] = 210127,
            },
        [12026624] = {
            ["Content"] = "你离开往隙之后好像有什么烦恼。",
            ["ContentKR"] = "과거의 틈을 떠난 뒤로 무슨 걱정이라도 있는 것 같아.",
            ["DialogueId"] = 12026624,
            ["GUID"] = "1E1B7E00",
            ["NextDialogue"] = 12026625,
            },
        [12026625] = {
            ["Content"] = "这也被你察觉到了……多谢你牵挂着我。",
            ["ContentKR"] = "눈치채셨군요... 신경 써 주셔서 고마워요.",
            ["DialogueId"] = 12026625,
            ["GUID"] = "1E1B7E2A",
            ["NextDialogue"] = 12026626,
            ["SpeakNpcId"] = 210127,
            },
        [12026626] = {
            ["Content"] = "{nickname}，你也有对你而言意义重大的家人吧。倘若你犯下了言语过失，伤了那人的心，你会怎么做？",
            ["ContentKR"] = "{nickname}, 당신에게도 소중한 가족이 있겠죠? 심한 말로 가족에게 상처를 줬다면, 어떻게 해야 할까요?",
            ["DialogueId"] = 12026626,
            ["GUID"] = "1E1B7E54",
            ["NextDialogue"] = 12026627,
            ["SpeakNpcId"] = 210127,
            },
        [12026627] = {
            ["Content"] = "既然是家人，肯定不会有化解不了的矛盾。我想如果有一天真的发生了那种事情，我会很努力地去道歉，那样她一定会接受的。",
            ["ContentKR"] = "가족 사이에 풀지 못할 일은 없어. 그런 일이 생긴다면 진심으로 사과할 거고, 그러면 그 사람도 받아줄 거라 믿어.",
            ["DialogueId"] = 12026627,
            ["GUID"] = "1E1B7E7E",
            ["NextDialogue"] = 12026628,
            ["SpeakNpcId"] = 100001,
            },
        [12026628] = {
            ["Content"] = "但若是伊人已逝，此时再想道歉，也无人聆听……那又该如何是好？",
            ["ContentKR"] = "하지만 그 사람이 이미 이 세상에 없다면... 이제 와서 사과를 해도 받아줄 사람이 없다면... 어떻게 해야 하죠?",
            ["DialogueId"] = 12026628,
            ["GUID"] = "1E1B7EA8",
            ["NextDialogue"] = 12026629,
            ["SpeakNpcId"] = 210127,
            },
        [12026629] = {
            ["Content"] = "扶疏…………",
            ["ContentKR"] = "부소...",
            ["DialogueId"] = 12026629,
            ["GUID"] = "1E1B7ED2",
            ["NextDialogue"] = 12026630,
            ["SpeakNpcId"] = 100001,
            },
        [12026630] = {
            ["Content"] = "抱歉。不小心竟将自己的愁绪强加于你了。",
            ["ContentKR"] = "죄송해요. 괜히 제 고민을 떠넘겼네요.",
            ["DialogueId"] = 12026630,
            ["GUID"] = "1E1B7EFC",
            ["NextDialogue"] = 12026631,
            ["SpeakNpcId"] = 210127,
            },
        [12026631] = {
            ["Content"] = "没关系，如果你有什么不开心的，都可以来和我说，我随时在这里。",
            ["ContentKR"] = "괜찮아, 고민이 있다면 언제든지 털어놓아도 좋아. 난 항상 여기 있을 테니까.",
            ["DialogueId"] = 12026631,
            ["GUID"] = "1E1B7F26",
            ["NextDialogue"] = 12026640,
            ["SpeakNpcId"] = 100001,
            },
        [12026632] = {
            ["Content"] = "你真的是百年之前的人吗？",
            ["ContentKR"] = "부소는 정말 백 년 전의 사람이야?",
            ["DialogueId"] = 12026632,
            ["GUID"] = "1E1B7F50",
            ["NextDialogue"] = 12026633,
            },
        [12026633] = {
            ["Content"] = "嗯……如我先前所说，家姐为了延缓我的疾病进程，将我的躯体冻结。直至最近，我才被从百年的沉眠中唤醒。",
            ["ContentKR"] = "네... 전에 말씀드렸다시피, 언니가 제 병을 늦추기 위해 제 몸을 얼렸고, 최근에야 백 년간의 깊은 잠에서 깨어났어요.",
            ["DialogueId"] = 12026633,
            ["GUID"] = "1E1B7F7A",
            ["NextDialogue"] = 12026634,
            ["SpeakNpcId"] = 210127,
            },
        [12026634] = {
            ["Content"] = "这个世界会让你感到陌生吗？",
            ["ContentKR"] = "이 세상이 낯설게 느껴지진 않아?",
            ["DialogueId"] = 12026634,
            ["GUID"] = "1E1B7FA4",
            ["NextDialogue"] = 12026635,
            ["SpeakNpcId"] = 100001,
            },
        [12026635] = {
            ["Content"] = "或许吧。我刚刚醒来时，只感觉这世上的云卷云舒，一草一木，都不再和我有半分关联。",
            ["ContentKR"] = "그럴지도요. 막 깨어났을 땐, 이 세상의 구름 한 점이나 풀 한 포기조차 저와 아무런 상관이 없는 것처럼 느껴졌어요.",
            ["DialogueId"] = 12026635,
            ["GUID"] = "1E1B7FCE",
            ["NextDialogue"] = 12026636,
            ["SpeakNpcId"] = 210127,
            },
        [12026636] = {
            ["Content"] = "但随着时间发展，我也慢慢结识了你这样的友人。",
            ["ContentKR"] = "하지만 시간이 지나면서 당신 같은 친구도 사귀게 됐죠.",
            ["DialogueId"] = 12026636,
            ["GUID"] = "1E1B7FF8",
            ["NextDialogue"] = 12026637,
            ["SpeakNpcId"] = 210127,
            },
        [12026637] = {
            ["Content"] = "现今世间百态，抑或是医理发展，都使我感到新奇。换个角度来看，也是一件幸事。",
            ["ContentKR"] = "지금은 세상의 다양한 모습과 발전된 의학이 모두 새롭고 신기하게 느껴져요. 어떻게 보면 오히려 다행인 셈이죠.",
            ["DialogueId"] = 12026637,
            ["GUID"] = "1E1B8022",
            ["NextDialogue"] = 12026640,
            ["SpeakNpcId"] = 210127,
            },
        [12026638] = {
            ["Content"] = "我先走了。",
            ["ContentKR"] = "난 먼저 가볼게.",
            ["DialogueId"] = 12026638,
            ["GUID"] = "1E1B804C",
            ["NextDialogue"] = 12026639,
            },
        [12026639] = {
            ["Content"] = "你且去忙吧，注意身体。",
            ["ContentKR"] = "얼른 가보세요, 건강 조심하시고요.",
            ["DialogueId"] = 12026639,
            ["GUID"] = "1E1B8076",
            ["SpeakNpcId"] = 210127,
            },
        [12026640] = {
            ["DialogueId"] = 12026640,
            ["DialoguePanelType"] = "None",
            ["Duration"] = 0,
            ["FinalDialogueId"] = 12026639,
            ["GUID"] = "1E1B8077",
            ["NextOptions"] = {
                [1] = 12026604,
                [2] = 12026614,
                [3] = 12026624,
                [4] = 12026632,
                [5] = 12026638,
                },
            },
        [12026701] = {
            ["Content"] = "咿呀，咿咿呀，咿！",
            ["ContentKR"] = "야하, 야하, 야하하!",
            ["DialogueId"] = 12026701,
            ["GUID"] = "1E1B8AA2",
            ["NextDialogue"] = 12026702,
            ["SpeakNpcId"] = 210128,
            },
        [12026702] = {
            ["Content"] = "（它跟在扶疏身边，好像很开心的样子。）",
            ["ContentKR"] = "(부소 옆의 무유생은 무척 즐거워 보인다.)",
            ["DialogueId"] = 12026702,
            ["GUID"] = "1E1B8ACC",
            ["SpeakNpcId"] = 100001,
            },
        [12026801] = {
            ["Content"] = "猎物已经入网，此时行事须格外慎重，切忌打草惊蛇。",
            ["ContentKR"] = "사냥감이 함정에 걸어 들어왔으니 이제 더욱 신중하게 행동해야 해. 제풀에 놀라 도망칠 수 있거든.",
            ["DialogueId"] = 12026801,
            ["GUID"] = "1E1B9B0A",
            ["NextDialogue"] = 12026802,
            },
        [12026802] = {
            ["Content"] = "{nickname}，你若已经准备好了，我们就继续向前吧。",
            ["ContentKR"] = "{nickname}, 준비됐으면 계속 가보도록 하지.",
            ["DialogueId"] = 12026802,
            ["GUID"] = "1E1B9B34",
            },
        [12026901] = {
            ["Content"] = "如果我没有猜错，这上古机括战阵，其真名为千枢狩阵。取千枢为引，万隙囚光之意。",
            ["ContentKR"] = "내 예상대로라면, 이 오래된 기계 장치는 사냥 장치 법진일 거야. 수 천 개의 회전축으로 빛을 가두는 장치지.",
            ["DialogueId"] = 12026901,
            ["GUID"] = "1E1BAB72",
            ["NextDialogue"] = 12026902,
            },
        [12026902] = {
            ["Content"] = "古物于我们面前重焕生机……不觉得这景象很壮观吗？",
            ["ContentKR"] = "고대 유물이 우리 눈앞에서 되살아나는 모습... 참 장관이지 않나?",
            ["DialogueId"] = 12026902,
            ["GUID"] = "1E1BAB9C",
            },
        [12027001] = {
            ["Content"] = "您可以去尘漠石海最高处的位置，那里通往烛阴祭坛的临时道路已经搭建完毕。",
            ["ContentKR"] = "낙진의 바다 가장 높은 곳으로 가면, 촉룡 제단으로 가는 임시 통로가 이미 완성되어 있을 겁니다.",
            ["DialogueId"] = 12027001,
            ["GUID"] = "1E1BBBDA",
            ["NextDialogue"] = 12027002,
            ["SpeakNpcId"] = 210129,
            },
        [12027002] = {
            ["Content"] = "封印仪式一旦开启，烛阴极有可能受刺激狂化。祭坛周围危机四伏，不可大意。",
            ["ContentKR"] = "봉인 의식이 시작되면 촉룡이 자극을 받아 미쳐 날뛸 가능성이 높습니다. 제단 근처는 무척 위험하니 절대 방심하지 마세요.",
            ["DialogueId"] = 12027002,
            ["GUID"] = "1E1BBC04",
            ["NextDialogue"] = 12027003,
            ["SpeakNpcId"] = 210129,
            },
        [12027003] = {
            ["Content"] = "狩月人，您务必要小心，您的安危才是第一位的。我在这里等待您顺利归来。",
            ["ContentKR"] = "월석 사냥꾼님, 부디 몸조심 하십시오. 안전이 가장 중요하다는 거 잊지 마시고요. 전 여기서 무사히 돌아오시기만 기다리겠습니다.",
            ["DialogueId"] = 12027003,
            ["GUID"] = "1E1BBC2E",
            ["SpeakNpcId"] = 210129,
            },
        [12027101] = {
            ["Content"] = "姐姐不在菱生身边了……但是姐姐现在很高兴，菱生能感觉得到。",
            ["ContentKR"] = "언니는 더 이상 내 곁에 없지만... 난 느낄 수 있어. 언니는 지금 아주 행복하단 걸.",
            ["DialogueId"] = 12027101,
            ["GUID"] = "1E1BCC42",
            ["SpeakNpcId"] = 210130,
            },
        [12030001] = {
            ["Content"] = "那是不久之前，发生在冰湖城的一段故事——",
            ["ContentKR"] = "이것은 얼마 전, 아이스레이크 시티에서 있었던——",
            ["DialogueId"] = 12030001,
            ["Duration"] = 4,
            ["GUID"] = "1E1DA80A",
            ["NextDialogue"] = 12030002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DA80A",
            },
        [12030002] = {
            ["Content"] = "当一只小夜莺，决定勇敢地飞出它温暖的巢穴。",
            ["ContentKR"] = "작은 나이팅게일 한 마리가 따스한 둥지를 벗어나, 용감하게 날아오르기로 마음먹는 이야기이다.",
            ["DialogueId"] = 12030002,
            ["Duration"] = 4,
            ["GUID"] = "1E1DA834",
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DA834",
            },
        [12030003] = {
            ["Content"] = "菲娜坐在家里，看着故事书",
            ["DialogueId"] = 12030003,
            ["GUID"] = "1E1DA85E",
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DA85E",
            },
        [12030101] = {
            ["Content"] = "菲娜，晚上光线太暗，看书伤眼睛，还是早点睡吧。",
            ["DialogueId"] = 12030101,
            ["GUID"] = "1E1DB872",
            ["NextDialogue"] = 12030102,
            ["SpeakNpcId"] = 211002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DB872",
            },
        [12030102] = {
            ["Content"] = "唔……",
            ["DialogueId"] = 12030102,
            ["GUID"] = "1E1DB89C",
            ["NextDialogue"] = 12030103,
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DB89C",
            },
        [12030103] = {
            ["Content"] = "怎么了？",
            ["DialogueId"] = 12030103,
            ["GUID"] = "1E1DB8C6",
            ["NextDialogue"] = 12030104,
            ["SpeakNpcId"] = 211002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DB8C6",
            },
        [12030104] = {
            ["Content"] = "奥特赛德，菲娜……菲娜有一个愿望！",
            ["DialogueId"] = 12030104,
            ["GUID"] = "1E1DB8F0",
            ["NextDialogue"] = 12030105,
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DB8F0",
            },
        [12030105] = {
            ["Content"] = "是吗？你说，是什么愿望？",
            ["DialogueId"] = 12030105,
            ["GUID"] = "1E1DB91A",
            ["NextDialogue"] = 12030106,
            ["SpeakNpcId"] = 211002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DB91A",
            },
        [12030106] = {
            ["Content"] = "菲娜想出去看看。",
            ["DialogueId"] = 12030106,
            ["GUID"] = "1E1DB944",
            ["NextDialogue"] = 12030107,
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DB944",
            },
        [12030107] = {
            ["Content"] = "出去……？现在吗？",
            ["DialogueId"] = 12030107,
            ["GUID"] = "1E1DB96E",
            ["NextDialogue"] = 12030108,
            ["SpeakNpcId"] = 211002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DB96E",
            },
        [12030108] = {
            ["Content"] = "不是的，菲娜的意思是，菲娜也想像你和独角兽{性别：先生|小姐}一样，去外面的世界，认识很多的新朋友……",
            ["DialogueId"] = 12030108,
            ["GUID"] = "1E1DB998",
            ["NextDialogue"] = 12030109,
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DB998",
            },
        [12030109] = {
            ["Content"] = "这可不行，外面很危险的。我和{nickname}大多数时候遇到的都不是朋友，而是秽——怪兽，和很多坏——坏巫师，对，那些坏巫师可吓人了。",
            ["DialogueId"] = 12030109,
            ["GUID"] = "1E1DB9C2",
            ["NextDialogue"] = 12030110,
            ["SpeakNpcId"] = 211002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DB9C2",
            },
        [12030110] = {
            ["Content"] = "所以，你还是待在家里最安全。",
            ["DialogueId"] = 12030110,
            ["GUID"] = "1E1DB9EC",
            ["NextDialogue"] = 12030111,
            ["SpeakNpcId"] = 211002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DB9EC",
            },
        [12030111] = {
            ["Content"] = "呜……",
            ["DialogueId"] = 12030111,
            ["GUID"] = "1E1DBA16",
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DBA16",
            },
        [12030112] = {
            ["Content"] = "转场，菲娜在睡觉，奥特赛德看到桌上的故事书",
            ["ContentKR"] = "밤, 피나의 집.\
피나는 잠들어 있고, 아웃사이더는 피나가 책상 위에 놓아둔 동화책을 발견한다.",
            ["DialogueId"] = 12030112,
            ["GUID"] = "1E1DBA40",
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DBA40",
            },
        [12030201] = {
            ["Camera"] = "-345.501678,523.378906,124.574219,0.000322,-4.833527,90.822472,35.000008,77.550713,false,Manual,4.0",
            ["Content"] = "“大魔法师总是说，巢穴外的世界充满了危险，呆在巢穴里才是最安全的……可是小小的巢穴虽然温暖，却只能看到一小片方形的天空。”",
            ["ContentKR"] = "\"대마법사는 늘 둥지 밖은 위험으로 가득하니, 둥지 안이 가장 안전하다고 말했어요. 하지만... 자그마한 둥지는 따스해도, 그 안에선 네모난 하늘 조각만 보일 뿐이었죠.\"",
            ["DialogueId"] = 12030201,
            ["FinalCamera"] = "-351.068237,428.320312,123.277344,0.000143,-3.242031,91.01268,35.000008,212.663025,false,Manual,2.8",
            ["GUID"] = "1E1DC8DA",
            ["LookAt"] = {
                [1] = "211002:p(pFeina_FixSimple02_LookAt01)",
                },
            ["NextDialogue"] = 12030202,
            ["TalkActionId"] = {
                [1] = "211024:Feina_Story_Lieidle",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DC8DA",
            },
        [12030202] = {
            ["Camera"] = "-351.068237,428.320312,123.277344,0.000143,-3.242031,91.01268,35.000008,212.663025,false,Manual,2.8",
            ["Content"] = "“有一天，从很远很远的地方漂流而来的独角兽{性别：先生|小姐}来到了小夜莺的巢穴，为小夜莺捎来了远方的故事……”",
            ["ContentKR"] = "\"그러던 어느 날, 아주 멀리서 온 유니콘 {性别:오빠|언니}가 나이팅게일의 둥지로 찾아와, 먼 곳 이야기를 들려줬어요...\"",
            ["DialogueId"] = 12030202,
            ["FinalCamera"] = "-445.522095,482.669922,106.667969,0.000118,8.757859,54.209782,35.000008,212.663025,false,Manual,2.8",
            ["GUID"] = "1E1DC904",
            ["NextDialogue"] = 12030203,
            ["ToFinalCameraBlendTime"] = 7,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DC904",
            },
        [12030203] = {
            ["Camera"] = "-93.792816,296.109375,123.785156,0.000262,-14.836967,-25.180407,28.0,180.0,false,Manual,3.5",
            ["Content"] = "“在巢穴之外那广阔的世界里，有枝条能挂在月亮上的大树，有怀抱着一百座小岛的大海……”",
            ["ContentKR"] = "\"둥지 밖의 넓은 세상에는, 가지에 달이 걸릴 만큼 커다란 나무도 있고, 섬을 백 개나 품은 커다란 바다도 있었어요...\"",
            ["DialogueId"] = 12030203,
            ["FinalCamera"] = "-93.792816,296.109375,123.785156,0.000261,-34.236603,-38.179943,28.000006,63.699184,false,Manual,3.5",
            ["GUID"] = "1E1DC92E",
            ["NextDialogue"] = 12030204,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DC92E",
            },
        [12030204] = {
            ["Camera"] = "-93.792816,296.109375,123.785156,0.000249,-34.236633,-38.180016,28.0,180.0,false,Manual,3.5",
            ["Content"] = "“小夜莺也好想飞到大树的枝头，和每一朵绽放的花打招呼，去小松鼠的家里做客……”",
            ["ContentKR"] = "\"나이팅게일도 커다란 나무 꼭대기로 날아가, 활짝 핀 꽃송이들과 인사를 나누고, 아기 다람쥐의 집에 놀러 가고...\"",
            ["DialogueId"] = 12030204,
            ["FinalCamera"] = "-222.147125,357.158203,220.230469,0.000264,-30.234377,-29.18161,35.0,180.0,false,Manual,3.5",
            ["GUID"] = "1E1DC958",
            ["NextDialogue"] = 12030205,
            ["Scripts"] = "SEQ{LookAt{LookAtDescription{\"211002:p(pFeina_FixSimple02_LookAt01)\"}}}",
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DC958",
            },
        [12030205] = {
            ["Camera"] = "-139.631927,210.423828,144.097656,0.000295,7.366509,66.22287,35.0,112.741165,false,Manual,4.0",
            ["Content"] = "“想乘上柔软的云，和掠过高空的海燕并肩翱翔，和跃出海面的鱼儿一起嬉戏……”",
            ["ContentKR"] = "\"포근한 구름을 타고 바다제비와 함께 높은 하늘을 누비고, 바다 위로 뛰어오르는 물고기들과 함께 놀고 싶었답니다...\"",
            ["DialogueId"] = 12030205,
            ["GUID"] = "1E1DC982",
            ["NextDialogue"] = 12030206,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DC982",
            },
        [12030206] = {
            ["Content"] = "……",
            ["ContentKR"] = "......",
            ["DialogueId"] = 12030206,
            ["GUID"] = "1E1DC9AC",
            ["SpeakNpcId"] = 211002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DC9AC",
            },
        [12030207] = {
            ["Content"] = "转场，白天",
            ["DialogueId"] = 12030207,
            ["GUID"] = "1E1DC9D6",
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DC9D6",
            },
        [12030300] = {
            ["Camera"] = "-201.678467,47.8125,111.152344,0.000102,20.154959,-60.375671,28.0,293.312073,false,Manual,2.8",
            ["DialogueId"] = 12030300,
            ["FinalCamera"] = "-214.884705,6.785156,112.378906,0.00011,6.354692,-2.17627,28.0,125.074371,false,Manual,2.8",
            ["GUID"] = "1E1DD941",
            ["NextDialogue"] = 12030301,
            ["ToFinalCameraBlendTime"] = 5,
            },
        [12030301] = {
            ["Camera"] = "-214.884705,6.785156,112.378906,0.00011,6.354692,-2.17627,28.0,125.074371,false,Manual,2.8",
            ["Content"] = "菲娜。",
            ["ContentKR"] = "피나.",
            ["DialogueId"] = 12030301,
            ["FinalCamera"] = "-214.884705,6.785156,112.378906,0.00011,6.354692,-2.17627,28.0,324.258209,false,Manual,2.8",
            ["GUID"] = "1E1DD942",
            ["NextDialogue"] = 12030302,
            ["Scripts"] = "LookAt{LookAtDescription{\"211002:n(211001)\"}},\
",
            ["SpeakNpcId"] = 211002,
            ["ToFinalCameraBlendTime"] = 2,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DD942",
            },
        [12030302] = {
            ["Camera"] = "53.489204,-49.375,131.65625,0.000106,-4.241547,154.817291,35.0,172.252792,false,Manual,2.8",
            ["Content"] = "奥特赛德？你今天怎么回来得这么早……发生什么事了吗？",
            ["ContentKR"] = "아웃사이더? 오늘은 웬일로 이렇게 일찍 왔어... 무슨 일 있는 거야?",
            ["DialogueId"] = 12030302,
            ["FinalCamera"] = "26.751808,-36.806641,129.472656,0.00011,-4.24154,154.817642,35.0,132.363815,false,Manual,2.8",
            ["GUID"] = "1E1DD96C",
            ["NextDialogue"] = 12030303,
            ["Scripts"] = "SEQ{\
LookAt{LookAtDescription{\"211001:n(211002)\"}},\
PlayFacial{_delay{1.5},ActorId{211001},FacialId{\"Happy01\"}},\
PlayAnimation{_delay{1.5},ActorId{211001},AnimationId{\"Shy01_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 211001,
            ["ToFinalCameraBlendTime"] = 10,
            ["TurnTo"] = {
                [1] = "211001:p(40)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DD96C",
            },
        [12030303] = {
            ["Camera"] = "-10.235954,65.589844,155.683594,0.000051,-1.24011,-35.390144,35.000008,286.639435,false,Manual,2.8",
            ["Content"] = "确实有一件重要的事——今天是新手魔法师菲娜的第一次冒险之旅，我特地回来给她加油鼓劲。",
            ["ContentKR"] = "응, 아주 중요한 일이 있어. 오늘이 바로 초보 마법사 피나의 첫 모험이 시작되는 날이거든. 그래서 특별히 응원해 주러 왔지.",
            ["DialogueId"] = 12030303,
            ["FinalCamera"] = "4.515831,55.119141,155.300781,0.000051,-1.24011,-35.390144,35.000008,286.639435,false,Manual,2.8",
            ["GUID"] = "1E1DD996",
            ["NextDialogue"] = 12030304,
            ["Scripts"] = "PlayAnimation{ActorId{211002},AnimationId{\"ConfidentR_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 211002,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DD996",
            },
        [12030304] = {
            ["Camera"] = "80.626434,-20.03125,162.339844,0.000114,-10.841299,166.216843,55.000008,178.363068,false,Manual,2.8",
            ["Content"] = "咦？",
            ["ContentKR"] = "어어?",
            ["DialogueId"] = 12030304,
            ["GUID"] = "1E1DD9C0",
            ["NextDialogue"] = 12030305,
            ["Scripts"] = "PARA{\
PlayFacial{_delay{0.1},ActorId{211001},FacialId{\"None\"}},\
PlayAnimation{ActorId{211001},AnimationId{\"Shy01_End\"},Duration{1}},\
PlayAnimation{ActorId{211001},AnimationId{\"TilteHead_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DD9C0",
            },
        [12030305] = {
            ["Camera"] = "-108.768295,398.734375,113.765625,0.000063,0.559174,-73.189148,28.0,366.148499,false,Manual,2.8",
            ["Content"] = "我看了你写的故事，你很想去外面的世界看看，对吧？我同意了，你现在就可以出门去冒险啦。",
            ["ContentKR"] = "네가 쓴 이야기를 봤어. 바깥세상을 둘러보고 싶은 거지? 좋아, 지금 바로 모험을 떠나도 돼.",
            ["DialogueId"] = 12030305,
            ["FinalCamera"] = "-97.715012,362.148438,114.128906,0.000063,0.559174,-73.189117,28.000006,366.148499,false,Manual,2.8",
            ["GUID"] = "1E1DD9EA",
            ["NextDialogue"] = 12030306,
            ["Scripts"] = "\
SEQ{\
PlayAnimation{ActorId{211002},AnimationId{\"ConfidentRToExplain_Start\"},Duration{1}},\
PlayAnimation{ActorId{211001},AnimationId{\"TilteHead_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 211002,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DD9EA",
            },
        [12030306] = {
            ["Camera"] = "52.159672,-22.074219,168.640625,0.000079,-14.240568,163.610046,55.0,154.192795,false,Manual,2.8",
            ["Content"] = "可是，你不是说外面很危险，还有很多坏巫师吗……？",
            ["ContentKR"] = "그치만... 바깥은 위험하고, 나쁜 마법사도 많다고 했잖아...?",
            ["DialogueId"] = 12030306,
            ["FinalCamera"] = "37.80537,-17.855469,164.851562,0.000084,-14.240541,163.610001,55.0,138.46257,false,Manual,2.8",
            ["GUID"] = "1E1DDA14",
            ["NextDialogue"] = 12030307,
            ["Scripts"] = "PARA{\
PlayAnimation{ActorId{211001},AnimationId{\"Shy02_Start\"},Duration{1}},\
PlayFacial{ActorId{211001},FacialId{\"Sad01\"}}\
}\
\
",
            ["SpeakNpcId"] = 211001,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DDA14",
            },
        [12030307] = {
            ["Camera"] = "53.723839,-28.212891,158.828125,0.000089,-2.841516,-22.7857,28.000008,150.228668,false,Manual,2.8",
            ["Content"] = "不用担心，我这个“大魔法师”已经给你使用了最厉害的守护魔法，坏巫师根本不敢靠近。",
            ["ContentKR"] = "걱정 마. 이 '대마법사'가 너한테 세상에서 가장 강한 수호 마법을 걸어 뒀거든. 나쁜 마법사 따위는 절대 가까이 오지 못할 거야.",
            ["DialogueId"] = 12030307,
            ["FinalCamera"] = "68.022377,-34.214844,158.117188,0.000089,-2.6415,-22.785671,28.000008,150.228668,false,Manual,2.8",
            ["GUID"] = "1E1DDA3E",
            ["NextDialogue"] = 12030308,
            ["Scripts"] = "PARA{\
PlayAnimation{ActorId{211002},AnimationId{\"DisagreeHead\"},Duration{1}},\
PlayAnimation{ActorId{211002},AnimationId{\"ConfidentRToExplain_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 211002,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DDA3E",
            },
        [12030308] = {
            ["Content"] = "不过，就像故事书里说的，魔法不是永久的——所以你只能在白天出门，而且也不能走得太远，否则魔法就会失效了。",
            ["ContentKR"] = "근데, 동화책에서처럼 마법이 영원하진 않아. 그러니까 낮에만 나가야 하고, 너무 멀리 가도 안 돼. 안 그러면 마법의 힘이 사라질 테니까.",
            ["DialogueId"] = 12030308,
            ["FinalCamera"] = "74.63475,-33.244141,159.617188,0.000087,-1.641288,-22.979761,28.000006,146.329025,false,Manual,2.8",
            ["GUID"] = "1E1DDA68",
            ["NextDialogue"] = 12030309,
            ["Scripts"] = "PlayAnimation{ActorId{211002},AnimationId{\"Talk02_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 211002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DDA68",
            },
        [12030309] = {
            ["Camera"] = "68.511589,-59.673828,134.019531,0.000108,-2.441301,153.218155,55.0,178.363068,false,Manual,2.8",
            ["Content"] = "……好！",
            ["ContentKR"] = "...응, 좋아!",
            ["DialogueId"] = 12030309,
            ["FacialId"] = {
                [1] = "211001:Happy01",
                },
            ["GUID"] = "1E1DDA92",
            ["Scripts"] = "PARA{\
LookAt{LookAtDescription{\"211001:n(211002)\"}},\
PlayAnimation{ActorId{211001},AnimationId{\"Feina_Story_Wish_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 211001,
            ["TalkActionId"] = {
                [1] = "211001:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DDA92",
            },
        [12030310] = {
            ["Content"] = "菲娜拿着魔法书出门，奥特赛德看着她离开，随后主角入镜",
            ["ContentKR"] = "피나가 마법서를 들고 집을 나서고, 아웃사이더는 그녀가 떠나는 것을 지켜본다. 이윽고 주인공이 화면으로 들어온다.",
            ["DialogueId"] = 12030310,
            ["GUID"] = "1E1DDABC",
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DDABC",
            },
        [12030400] = {
            ["Camera"] = "1266.484619,-178.583984,366.181152,0.000043,-9.398552,-176.39032,35.000011,100000.0,false,Manual,4.0",
            ["Content"] = "冰湖城，上午【临时】",
            ["DialogueId"] = 12030400,
            ["Duration"] = 8,
            ["FinalCamera"] = "1301.278198,-365.192383,256.428711,0.000054,-9.198332,163.00029,35.000011,622.412903,false,Manual,4.0",
            ["GUID"] = "1E1DE9A9",
            ["NextDialogue"] = 12030401,
            ["ToFinalCameraBlendTime"] = 8,
            },
        [12030401] = {
            ["Camera"] = "1305.487793,-265.864258,306.96875,0.00014,-3.399658,179.117737,35.000008,272.126312,false,Manual,22.0",
            ["Content"] = "接下来就交给你了。",
            ["ContentKR"] = "뒷일은 너한테 맡길게.",
            ["DialogueId"] = 12030401,
            ["FinalCamera"] = "1354.122437,-266.613281,197.483887,0.00014,-2.999628,179.117737,35.000008,272.126312,false,Manual,22.0",
            ["GUID"] = "1E1DE9AA",
            ["NextDialogue"] = 12030402,
            ["Scripts"] = "PlayAnimation{ActorId{211001},AnimationId{\"Feina_Story_Look01_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 211002,
            ["ToFinalCameraBlendTime"] = 3,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DE9AA",
            },
        [12030402] = {
            ["Camera"] = "699.66394,-379.948242,204.811523,0.000031,-5.9989,24.603928,35.000011,249.091507,false,Manual,4.0",
            ["Content"] = "你大概也猜到了，菲娜在过去经历过一些……很复杂的事情。虽说都过去了，但我还是有点担心她会被什么人认出来，引来不必要的麻烦。",
            ["ContentKR"] = "대충 짐작했겠지만, 피나는 과거에... 좀 복잡한 일을 겪었어. 물론 다 지나간 일이지만, 혹시라도 누가 피나를 알아봐서 성가신 일에 엮일까 봐 걱정돼서 말이야.",
            ["DialogueId"] = 12030402,
            ["FinalCamera"] = "729.398315,-366.335938,201.375,0.000031,-5.9989,24.603533,35.000011,249.091507,false,Manual,4.0",
            ["GUID"] = "1E1DE9D4",
            ["NextDialogue"] = 12030403,
            ["SpeakNpcId"] = 211002,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DE9D4",
            },
        [12030403] = {
            ["Content"] = "你为什么不自己跟着她呢？",
            ["ContentKR"] = "왜 직접 따라가지 않고?",
            ["DialogueId"] = 12030403,
            ["GUID"] = "1E1DE9FE",
            ["NextDialogue"] = 12030404,
            ["Scripts"] = "LookAt{LookAtDescription{\"100001:n(211002)\"}}",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DE9FE",
            },
        [12030404] = {
            ["Camera"] = "775.80603,-164.087891,170.229492,0.000074,3.000078,-28.687651,39.289318,212.725189,false,Manual,2.8",
            ["Content"] = "毕竟是小朋友的娱乐活动，我跟着也不太合适……",
            ["ContentKR"] = "이러나저러나 애가 놀러 나가는 건데, 내가 따라다니긴 좀 그렇잖아...",
            ["DialogueId"] = 12030404,
            ["FinalCamera"] = "787.402832,-170.431641,170.922363,0.000074,3.000078,-28.687651,39.289318,212.725189,false,Manual,2.8",
            ["GUID"] = "1E1DEA28",
            ["NextDialogue"] = 12030405,
            ["Scripts"] = "PARA{\
LookAt{LookAtDescription{\"211002:n(100001)\"}},\
PlayAnimation{ActorId{211002},AnimationId{\"DisagreeHead\"},Duration{1}},\
PlayAnimation{ActorId{211002},AnimationId{\"Talk01_Start\"},Duration{1}}\
}\
",
            ["SpeakNpcId"] = 211002,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DEA28",
            },
        [12030405] = {
            ["Camera"] = "847.966919,-332.923828,167.130371,0.000161,-0.199687,43.514797,35.000008,140.89209,false,Manual,2.8",
            ["Content"] = "唉，可怜的奥特赛德，已经变成无聊的大人了呀。",
            ["ContentKR"] = "에구, 가엾은 아웃사이더. 어느새 시시한 어른이 돼 버렸네.",
            ["DialogueId"] = 12030405,
            ["FinalCamera"] = "858.939087,-322.508789,167.078125,0.000161,-0.199687,43.514797,35.000008,125.894028,false,Manual,2.8",
            ["GUID"] = "1E1DEA52",
            ["NextDialogue"] = 12030406,
            ["Scripts"] = "PARA{\
LookAt{LookAtDescription{\"100001:n(100001)\"}},\
PlayAnimation{_delay{0.5},ActorId{100001},AnimationId{\"DisagreeHead\"},Duration{1}},\
PlayAnimation{ActorId{211002},AnimationId{\"Talk01_End\"},Duration{1}},\
PlayAnimation{_delay{1},ActorId{100001},AnimationId{\"Talk01_Start\"},Duration{1}}\
}\
",
            ["SpeakNpcId"] = 100001,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DEA52",
            },
        [12030406] = {
            ["Camera"] = "704.098999,-7.766602,177.265137,0.000081,0.200049,-46.484791,39.289318,402.856293,false,Manual,2.8",
            ["Content"] = "哪有！主要是我都答应让她自己出门了，还跟在后面的话，我怕她会不高兴。",
            ["ContentKR"] = "아니거든! 혼자 나가게 해준다고 약속까지 했는데, 뒤에서 졸졸 따라다니면 피나가 싫어할까 봐 그래.",
            ["DialogueId"] = 12030406,
            ["FinalCamera"] = "690.504517,6.551758,177.196289,0.000081,0.200049,-46.484791,39.289318,402.856293,false,Manual,2.8",
            ["GUID"] = "1E1DEA7C",
            ["NextDialogue"] = 12030407,
            ["Scripts"] = "PARA{\
PlayAnimation{ActorId{100001},AnimationId{\"Talk01_End\"},Duration{1}},\
LookAt{LookAtDescription{\"211002:n(100001)\"}}\
}",
            ["SpeakNpcId"] = 211002,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DEA7C",
            },
        [12030407] = {
            ["Content"] = "我看她挺喜欢你这个“独角兽{性别：先生|小姐}”的，你就当帮我个忙嘛，我的好队长！",
            ["ContentKR"] = "피나가 너란 '유니콘 {性别:오빠|언니}'를 꽤 마음에 들어 하는 것 같던데, 나 좀 도와주라, 마음씨 고운 우리 대장!",
            ["DialogueId"] = 12030407,
            ["GUID"] = "1E1DEAA6",
            ["NextDialogue"] = 12030408,
            ["Scripts"] = "PlayAnimation{ActorId{211002},AnimationId{\"Talk02_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 211002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DEAA6",
            },
        [12030408] = {
            ["Camera"] = "854.199219,-325.050781,195.624023,0.000087,-9.39987,37.314049,39.289318,140.252518,false,Manual,2.8",
            ["Content"] = "我可不是免费的哦。",
            ["ContentKR"] = "공짜는 없다는 거 알지?",
            ["DialogueId"] = 12030408,
            ["FinalCamera"] = "871.305054,-312.015625,192.064453,0.000087,-9.39987,37.314049,39.289318,116.633705,false,Manual,2.8",
            ["GUID"] = "1E1DEAD0",
            ["NextDialogue"] = 12030409,
            ["Scripts"] = "PARA{\
LookAt{LookAtDescription{\"100001:n(211002)\"}},\
PlayFacial{ActorId{100001},FacialId{\"Smile02\"}},\
PlayAnimation{ActorId{211002},AnimationId{\"Talk03_Start\"},Duration{1}}\
}\
",
            ["SpeakNpcId"] = 100001,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DEAD0",
            },
        [12030409] = {
            ["Camera"] = "787.42334,-98.248047,152.363281,0.000112,6.400467,-44.484207,39.289318,176.364334,false,Manual,10.0",
            ["Content"] = "这好说，你想要什么报答尽管提，请你吃饭，帮你干活，或者叫你一个月{性别：大哥|大姐头}都行……学狗叫除外！",
            ["ContentKR"] = "문제없어. 보답으로 원하는 거 있으면 말만 해. 밥을 사든, 일을 돕든, 한 달 내내 {性别:형님|누님}으로 부르든 다 할게... 왈왈 짖으라는 것만 빼고!",
            ["DialogueId"] = 12030409,
            ["FinalCamera"] = "797.796387,-108.432617,153.995117,0.000112,6.400467,-44.484207,39.289318,176.364334,false,Manual,10.0",
            ["GUID"] = "1E1DEAFA",
            ["NextDialogue"] = 12030410,
            ["Scripts"] = "PlayAnimation{ActorId{211002},AnimationId{\"AgreeHead\"},Duration{1}}",
            ["SpeakNpcId"] = 211002,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DEAFA",
            },
        [12030410] = {
            ["Camera"] = "461.232666,-276.961914,161.877441,0.000121,-0.399593,4.115808,35.0,272.126312,false,Manual,10.0",
            ["Content"] = "那真是太可惜了，我正想复习一下驯兽技巧。",
            ["ContentKR"] = "그건 좀 아쉽네, 마침 조련술을 복습해 볼까 했거든.",
            ["DialogueId"] = 12030410,
            ["FinalCamera"] = "426.237671,-279.481445,162.121582,0.000121,-0.399593,4.115808,35.0,272.126312,false,Manual,10.0",
            ["GUID"] = "1E1DEB24",
            ["NextDialogue"] = 12030411,
            ["Scripts"] = "PARA{\
LookAt{LookAtDescription{\"100001:n(100001)\"}},\
PlayAnimation{ActorId{211002},AnimationId{\"Talk03_End\"},Duration{1}},\
PlayFacial{ActorId{100001},FacialId{\"None\"}}\
}",
            ["SpeakNpcId"] = 100001,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DEB24",
            },
        [12030411] = {
            ["Content"] = "你就饶了我吧……",
            ["ContentKR"] = "진짜 좀 봐줘...",
            ["DialogueId"] = 12030411,
            ["GUID"] = "1E1DEB4E",
