            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DEB78",
            },
        [12030425] = {
            ["Content"] = "这就是外面的世界……【待包装】",
            ["ContentKR"] = "뭐? 마크는 오늘 안 온대...?",
            ["DialogueId"] = 12030425,
            ["GUID"] = "1E1DEB79",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DEB79",
            },
        [12030451] = {
            ["Camera"] = "-454.439941,557.930664,150.488281,0.000084,-7.39984,-63.487518,35.000011,355.657684,false,Manual,22.0",
            ["Content"] = "什么，马克今天不来了吗……？",
            ["ContentKR"] = "뭐? 마크는 오늘 안 온대...?",
            ["DialogueId"] = 12030451,
            ["FinalCamera"] = "-432.604004,514.160156,144.135254,0.000084,-7.399847,-63.487595,35.000015,355.657684,false,Manual,22.0",
