",
            ["SpeakNpcId"] = 211013,
            ["TalkActionId"] = {
                [1] = "211013:Talk01_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DF1DE",
            },
        [12030452] = {
            ["Camera"] = "204.449219,394.667969,139.548828,0.000097,-5.599737,-123.286819,35.000015,355.657684,false,Manual,22.0",
            ["Content"] = "嗯，他说他要帮她妈妈看摊位。今天只有我们三个玩了。",
            ["ContentKR"] = "응, 엄마 가게 보시는 거 도와야 한대. 오늘은 우리 셋이서만 놀아야겠네.",
            ["DialogueId"] = 12030452,
            ["FinalCamera"] = "190.858887,374.125977,137.133789,0.000097,-5.599737,-123.486916,35.000015,355.657684,false,Manual,22.0",
            ["GUID"] = "1E1DF208",
            ["NextDialogue"] = 12030453,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{211010},AnimationId{\"Talk01_Start\"},Duration{1}},\
PlayAnimation{ActorId{211010},AnimationId{\"Talk01_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 211010,
            ["TalkActionId"] = {
                [1] = "211010:Explain01_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["TurnTo"] = {
                [1] = "211001:p(-60)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DF208",
            },
        [12030453] = {
            ["Content"] = "诶~三个人太少了，不好玩呀。我们再拉个人一起吧，让我看看——",
            ["ContentKR"] = "에이~ 세 명은 너무 적어서 재미없어. 한 명 더 끼워서 놀자. 어디...",
            ["DialogueId"] = 12030453,
            ["GUID"] = "1E1DF232",
            ["NextDialogue"] = 12030454,
            ["SpeakNpcId"] = 211011,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DF232",
            },
        [12030454] = {
            ["Camera"] = "-50.73291,28.598633,98.257812,0.00012,-2.799366,-114.086708,35.000015,355.657684,false,Manual,22.0",
            ["Content"] = "呀！你们快看！是奥特赛德的吸血鬼妹妹！！！",
            ["ContentKR"] = "얘들아! 저기 좀 봐! 아웃사이더네 흡혈귀 동생이다!!!",
            ["DialogueId"] = 12030454,
            ["GUID"] = "1E1DF25C",
