            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DFA12",
            },
        [12030502] = {
            ["Content"] = "就是奥特赛德的妹妹呀！我从来没见过她出门。只有吸血鬼才会不敢出门吧？",
            ["ContentKR"] = "아웃사이더 여동생 말이야! 쟤 절대 집 밖으로 안 나오잖아. 흡혈귀라 무서워서 밖에 못 나오는 거 아니야?",
            ["DialogueId"] = 12030502,
            ["GUID"] = "1E1DFA3C",
            ["NextDialogue"] = 12030503,
            ["Scripts"] = "PARA{\
