            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1E2CC4",
            },
        [12030811] = {
            ["Content"] = "菲娜拿出童话书看一眼",
            ["ContentKR"] = "피나가 동화책을 꺼내 한번 들여다본다.",
            ["DialogueId"] = 12030811,
            ["GUID"] = "1E1E2CEE",
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1E2CEE",
            },
        [12030901] = {
            ["Camera"] = "-69.249512,169.701172,119.054199,0.000114,2.200639,-59.584778,35.000011,113.605156,false,DoNotOverride,6.0",
            ["Content"] = "可是，故事里的主人公们总是充满勇气，无论遇到怎样的困难，都会和伙伴们一起克服……",
            ["ContentKR"] = "그치만, 동화 속 주인공들은 언제나 용기가 넘치고, 어떤 어려움이 닥쳐도 동료들과 함께 이겨내는데...",
            ["DialogueId"] = 12030901,
            ["GUID"] = "1E1E3BB2",
            ["NextDialogue"] = 12030902,
            ["Scripts"] = "PARA{\
PlayAnimation{ActorId{211001},AnimationId{\"Feina_Story_Wish_Start\"}},\
PlayFacial{ActorId{211001},FacialId{\"Think01\"}}\
}",
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1E3BB2",
            },
        [12030902] = {
            ["Camera"] = "21.739258,184.106445,139.543457,0.000111,-7.199613,-110.180969,35.000011,113.605156,false,DoNotOverride,6.0",
            ["Content"] = "对了，伙伴！可以让菲娜的魔法朋友们来帮忙——大魔法师有着世界上最灵敏的鼻子，它一定可以帮我找到烤土豆的！",
            ["ContentKR"] = "맞아, 동료! 피나의 마법 친구들한테 도와달라고 하면 돼! 대마법사는 세상에서 코가 가장 예민하니까, 분명 감자구이를 찾아줄 거야!",
            ["DialogueId"] = 12030902,
            ["GUID"] = "1E1E3BDC",
            ["NextDialogue"] = 12030903,
            ["Scripts"] = "SEQ{\
PARA{\
PlayAnimation{ActorId{211001},AnimationId{\"Feina_Story_Wish_End\"}},\
PlayFacial{ActorId{211001},FacialId{\"Shock01\"}}\
},\
PARA{\
PlayFacial{_delay{5},ActorId{211001},FacialId{\"Happy01\"}}\
}\
}",
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1E3BDC",
            },
        [12030903] = {
            ["Camera"] = "23.185059,-32.167969,158.042969,0.000149,-34.400173,112.224525,35.000011,113.605156,false,DoNotOverride,9.0",
            ["Content"] = "只要把大魔法师从书本里邀请出来……",
            ["ContentKR"] = "책에서 대마법사를 불러내기만 하면...!",
            ["DialogueId"] = 12030903,
            ["FinalCamera"] = "54.931641,20.5,138.690918,0.000164,-36.800129,141.424347,35.000011,113.605156,false,DoNotOverride,9.0",
