        [12031306] = {
            ["Camera"] = "-192.03418,66.044922,95.960938,0.000107,3.599728,-25.255419,35.000015,231.188461,false,DoNotOverride,4.5",
            ["Content"] = "我正在冒险的旅途中哦！",
            ["ContentKR"] = "나 지금 모험 중이야!",
            ["DialogueId"] = 12031306,
            ["GUID"] = "1E1E7E24",
            ["NextDialogue"] = 12031307,
            ["Scripts"] = "SEQ{\
