            ["VoiceName"] = "voice/$Locale$/story/1201/120112/1E1E7F9E",
            },
        [12031316] = {
            ["Camera"] = "33.406738,-173.764648,123.195068,0.000108,-4.399994,102.947136,35.000011,120.0,false,DoNotOverride,4.5",
            ["Content"] = "这是你的称号！每一位伟大的侦探身边都会有一位出色的助手。",
            ["ContentKR"] = "네 별명이야! 위대한 탐정 곁엔 뛰어난 조수가 있기 마련이니까.",
            ["DialogueId"] = 12031316,
            ["GUID"] = "1E1E7FC8",
            ["NextDialogue"] = 12031317,
            ["Scripts"] = "PARA{\
