        [12031401] = {
            ["Camera"] = "-222.93663,-4.119965,77.036377,0.000147,5.602271,18.947176,35.000008,242.208893,false,DoNotOverride,2.8",
            ["Content"] = "呜……全是垃圾……不，不能害怕！我是神通广大的缄默侦探的“小助手”，必须要勇敢地完成任务——",
            ["ContentKR"] = "으... 온통 쓰레기잖아.. 아, 아냐, 무서워하면 안 돼! 난 만능 해결사 침묵의 탐정의 '꼬마 조수'니까, 용감하게 임무를 완수해야 해!",
            ["DialogueId"] = 12031401,
            ["GUID"] = "1E1E8DBA",
            ["NextDialogue"] = 12031402,
            ["Scripts"] = "SEQ{\
PARA{\
LookAt{_delay{0},LookAtDescription{\"211001:p(QuestPoint_Feina02fx13)\"}},\
PlayFacial{_delay{0},ActorId{211001},FacialId{\"Shock02\"}}\
},\
PARA{\
CameraMoveTo{_delay{4.01},TargetPosition{\"-128.022781,66.455872,85.407471,0.000122,13.602055,-6.65639,35.000008,184.110672,false,DoNotOverride,2.8\"},duration{0}},\
PlayFacial{_delay{4},ActorId{211001},FacialId{\"Confident01\"}},\
PlayAnimation{_delay{4},ActorId{211001},AnimationId{\"Feina_Story_Wish_Start\"}}\
}\
}",
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/1E1E8DBA",
            },
        [12031402] = {
            ["Content"] = "让我看看……这里有一张纸，上面会有线索吗？",
            ["ContentKR"] = "어디 보자... 종이가 하나 있네? 단서가 될 만한 게 적혀 있으려나?",
            ["DialogueId"] = 12031402,
            ["GUID"] = "1E1E8DE4",
            ["NextDialogue"] = 12031403,
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{0},ActorId{211001},AnimationId{\"Give\"}},\
PlayAnimation{_delay{2},ActorId{211001},AnimationId{\"Think_Start\"}}\
}",
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/1E1E8DE4",
            },
        [12031403] = {
            ["Content"] = "“只要抓住时代的风口，人人都能成为下一个大老板”……“风口”是什么东西？不过，大老板应该不会当强盗吧。",
            ["ContentKR"] = "\"시대의 흐름만 잘 잡으면, 여러분 모두 부자가 될 수 있습니다!\"... '시대의 흐름'이 뭐지? 그래도 부자 정도 되는 사람이 강도질을 하진 않겠지.",
            ["DialogueId"] = 12031403,
            ["GUID"] = "1E1E8E0E",
            ["NextDialogue"] = 12031404,
            ["Scripts"] = "PARA{\
SEQ{\
PlayFacial{_delay{2},ActorId{211001},FacialId{\"Shock01\"}},\
PlayFacial{_delay{2},ActorId{211001},FacialId{\"Disappoint01\"}},\
PlayFacial{_delay{2},ActorId{211001},FacialId{\"Happy01\"}},\
PlayFacial{_delay{3},ActorId{211001},FacialId{\"Shock01\"}},\
},\
PlayAnimation{_delay{5},ActorId{211001},AnimationId{\"Think_End\"}}\
}",
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/1E1E8E0E",
            },
        [12031404] = {
            ["Content"] = "再看看这张……",
            ["ContentKR"] = "다른 종이도 확인해 보자...",
            ["DialogueId"] = 12031404,
            ["GUID"] = "1E1E8E38",
            ["NextDialogue"] = 12031405,
            ["Scripts"] = "PARA{\
