            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E1F94E2",
            },
        [12033005] = {
            ["Camera"] = "-49.170532,261.708984,124.851562,0.000172,1.722225,-48.768116,35.0,175.392136,false,Manual,2.8",
            ["Content"] = "咦？菲娜还有弟弟吗？",
            ["ContentKR"] = "어? 피나한테 남동생이 있었어?",
            ["DialogueId"] = 12033005,
            ["GUID"] = "1E1F950C",
            ["NextDialogue"] = 12033006,
            ["Scripts"] = "PlayAnimation{ActorId{100001},AnimationId{\"Talk03ToThink_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E1F950C",
            },
        [12033006] = {
            ["Camera"] = "-181.509048,147.714844,149.226562,0.000195,-13.278214,93.431587,35.0,104.654732,false,Manual,2.8",
            ["Content"] = "那是很久以前，我还住在一座大宅邸里的时候的事。塞维欧的妈妈也是我的妈妈，塞维欧的爸爸，是……呜……",
            ["ContentKR"] = "아주 오래전에, 내가 커다란 저택에 살고 있었을 때 얘기야. 우리 엄마는 세비오 엄마이기도 한데, 세비오네 아빠는... 훌쩍...",
            ["DialogueId"] = 12033006,
            ["FinalCamera"] = "-87.040627,199.931641,112.960938,0.000192,4.52222,147.628799,35.0,104.654732,false,Manual,2.8",
            ["GUID"] = "1E1F9536",
            ["NextDialogue"] = 12033007,
            ["Scripts"] = "PARA{\
TurnTo{_delay{2},TurnToDescription{\"211001:p(-90)\"}},\
PlayAnimation{ActorId{211001},AnimationId{\"Shy01_End\"},Duration{1}},\
PlayFacial{ActorId{211001},FacialId{\"Sad02\"}}\
}\
",
            ["SpeakNpcId"] = 211001,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E1F9536",
            },
        [12033007] = {
            ["Camera"] = "-27.086937,207.318359,130.097656,0.00019,2.721981,-40.169811,35.0,119.172356,false,Manual,2.8",
            ["Content"] = "没关系的，菲娜，不想说就不用说。",
            ["ContentKR"] = "말하기 싫으면 억지로 말 안 해도 돼. 괜찮아, 피나.",
            ["DialogueId"] = 12033007,
            ["GUID"] = "1E1F9560",
            ["NextDialogue"] = 12033008,
            ["Scripts"] = "PlayAnimation{ActorId{100001},AnimationId{\"Think_End\"},Duration{1}}",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E1F9560",
            },
        [12033008] = {
            ["Camera"] = "-216.786224,638.707031,116.921875,0.000216,-0.677821,-70.769394,35.0,406.579437,false,Manual,2.8",
            ["Content"] = "谢谢你，独角兽{性别：先生|小姐}……",
            ["ContentKR"] = "고마워, 유니콘 {性别:오빠|언니}...",
            ["DialogueId"] = 12033008,
            ["FinalCamera"] = "-211.665588,624.029297,116.75,0.000216,-0.677821,-70.769394,35.0,406.579437,false,Manual,2.8",
            ["GUID"] = "1E1F958A",
            ["NextDialogue"] = 12033009,
            ["SpeakNpcId"] = 211001,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E1F958A",
            },
        [12033009] = {
            ["Camera"] = "-103.942352,216.216797,150.742188,0.000137,-14.478873,152.218048,28.000006,103.690712,false,Manual,2.8",
            ["Content"] = "可是，我明明答应要帮忙，却中途逃走了……怎么办……",
            ["ContentKR"] = "그치만 도와주기로 해 놓고, 중간에 도망쳐 버렸어... 어떡하지...",
            ["DialogueId"] = 12033009,
            ["GUID"] = "1E1F95B4",
            ["NextDialogue"] = 12033010,
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E1F95B4",
            },
        [12033010] = {
            ["Camera"] = "-84.477493,229.648438,149.128906,0.000138,-4.679171,-33.583679,55.000008,174.406815,false,Manual,2.8",
            ["Content"] = "别担心，这件事就交给我吧，我是狩月人，完成委托可是我的强项。",
            ["ContentKR"] = "걱정하지 마. 그건 나한테 맡겨. 난 월석 사냥꾼이잖아. 의뢰를 완수하는 건 내 전문이야.",
            ["DialogueId"] = 12033010,
            ["FinalCamera"] = "-73.702179,222.496094,148.070312,0.000138,-4.679171,-33.583744,55.000008,158.766953,false,Manual,2.8",
            ["GUID"] = "1E1F95DE",
            ["NextDialogue"] = 12033011,
            ["Scripts"] = "PARA{\
PlayAnimation{ActorId{100001},AnimationId{\"Talk02_Start\"},Duration{1}},\
PlayFacial{ActorId{100001},FacialId{\"Smile02\"}}\
}",
            ["SpeakNpcId"] = 100001,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E1F95DE",
            },
        [12033011] = {
            ["Camera"] = "108.718094,134.107422,142.527344,0.000134,-3.278443,166.01561,28.000006,316.033936,false,Manual,2.8",
            ["Content"] = "……嗯！那，也请你帮我向卡珊德拉小姐道歉——",
            ["ContentKR"] = "...응! 그럼 나 대신 카산드라 양한테 미안하다고도...",
            ["DialogueId"] = 12033011,
            ["GUID"] = "1E1F9608",
            ["Scripts"] = "PARA{\
PlayOrStopBGM{PlayType{\"Stop\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt02/0051_story_danger\"}},\
