        [12033102] = {
            ["Camera"] = "345.997009,-2.503906,147.578125,0.000145,-10.572681,-123.136963,35.000008,116.474312,false,DoNotOverride,6.0",
            ["Content"] = "菲娜姐姐，你在家吗？有一个内城来的漂亮小孩在找你！",
            ["ContentKR"] = "피나 언니, 안에 있어? 내성에서 온 어떤 예쁜 꼬마가 언닐 찾아!",
            ["DialogueId"] = 12033102,
            ["GUID"] = "1E1FA4F6",
            ["NextDialogue"] = 12033103,
            ["SpeakNpcId"] = 211011,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E1FA4F6",
            },
        [12033103] = {
            ["Content"] = "菲娜？菲娜，快开门，是我！出大事了！",
            ["ContentKR"] = "피나? 피나, 나야, 빨리 문 열어! 큰일 났어!",
            ["DialogueId"] = 12033103,
            ["GUID"] = "1E1FA520",
            ["SpeakNpcId"] = 211012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E1FA520",
            },
        [12033104] = {
            ["Content"] = "主角开门，门外站着卡珊德拉，后面跟着三小孩（芙蕾达、珂芮，戴维）",
            ["DialogueId"] = 12033104,
            ["GUID"] = "1E1FA521",
            },
