            ["Scripts"] = "PARA{\
PlayAnimation{_delay{2.5},ActorId{211001},AnimationId{\"Feina_Story_Wish_End\"},Duration{1}},\
LookAt{LookAtDescription{\"211012:n(211001)\"}},\
