            },
        [12033617] = {
            ["Content"] = "抵达洞窟外，主角偷偷观察里面，发现塞维欧被六七个强盗围着",
            ["ContentKR"] = "도적의 거점 근처로 이동한다. 몰래 주변을 관찰하던 주인공은 세비오가 강도 6~7명에게 둘러싸여 있는 모습을 발견한다.",
            ["DialogueId"] = 12033617,
            ["GUID"] = "1E1FF94A",
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E1FF94A",
            },
        [12033701] = {
            ["Camera"] = "173.460236,214.176193,147.875977,0.000091,-9.0007,-142.292953,35.000008,267.529114,false,DoNotOverride,2.8",
            ["Content"] = "果然在这里……",
            ["ContentKR"] = "역시 여기 있었네...",
            ["DialogueId"] = 12033701,
            ["GUID"] = "1E200712",
            ["NextDialogue"] = 12033702,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E200712",
            },
        [12033702] = {
            ["Camera"] = "-2079.935303,-417.626953,280.476562,0.000107,-19.000505,-77.490654,35.000011,899.788879,false,DoNotOverride,2.8",
            ["Content"] = "对方人数倒也不算多，但是人质在他们手上，有点麻烦。如果能用什么办法引开他们就好了……",
            ["ContentKR"] = "머릿수는 많지 않지만, 인질을 데리고 있으니 골치 아픈걸. 어떻게든 녀석들의 시선을 다른 곳으로 돌릴 수 있으면 좋겠는데...",
            ["DialogueId"] = 12033702,
            ["GUID"] = "1E20073C",
            ["NextDialogue"] = 12033703,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20073C",
            },
        [12033703] = {
            ["Camera"] = "-375.408356,-63.121277,64.066406,0.00011,4.599183,30.708393,35.000011,165.810257,false,DoNotOverride,2.8",
            ["Content"] = "菲娜有办法！",
            ["ContentKR"] = "나한테 좋은 생각이 있어!",
            ["DialogueId"] = 12033703,
            ["GUID"] = "1E200766",
            ["Scripts"] = "PlayFacial{_delay{0.5},ActorId{211001},FacialId{\"Smile01\"}}",
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E200766",
            },
        [12033704] = {
            ["Content"] = "菲娜在空地（从洞窟内能看见，但离洞窟有一定距离的地方）召唤出大魔法师和独角兽",
            ["ContentKR"] = "피나가 도적의 거점 반대편에 대마법사와 유니콘을 소환한다.",
            ["DialogueId"] = 12033704,
            ["GUID"] = "1E200790",
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E200790",
            },
        [12033705] = {
            ["Camera"] = "-1684.510986,-4.19751,-121.415039,0.000114,-3.201071,-177.585098,35.000011,1074.249756,false,DoNotOverride,12.0",
            ["Content"] = "嗯？什么动静？",
            ["ContentKR"] = "응? 이게 무슨 소리지?",
            ["DialogueId"] = 12033705,
            ["GUID"] = "1E2007BA",
            ["NextDialogue"] = 12033706,
            ["Scripts"] = "PARA{\
PlayAnimation{ActorId{211037},AnimationId{\"Think_Start\"}},\
PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"}}\
}",
            ["SpeakNpcId"] = 211037,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E2007BA",
            },
        [12033706] = {
            ["Content"] = "大哥，你看，那边有两个怪模怪样的东西——该不会是秽兽吧？！",
            ["ContentKR"] = "형님, 저기 좀 보십쇼. 이상하게 생긴 놈들이 둘 있습니다. 혹시 필토이드 아닐까요?",
            ["DialogueId"] = 12033706,
            ["GUID"] = "1E2007E4",
            ["NextDialogue"] = 12033707,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{211037},AnimationId{\"Think_End\"}},\
PARA{\
TurnTo{_delay{0},TurnToDescription{\"211037:n(211007)\"}},\
TurnTo{_delay{0.5},TurnToDescription{\"211038:n(211007)\"}},\
TurnTo{_delay{3},TurnToDescription{\"211039:n(211007)\"}}\
}\
}",
            ["SpeakNpcId"] = 211039,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E2007E4",
            },
        [12033707] = {
            ["Camera"] = "-3754.34668,62.890381,8.548828,0.000148,-12.001126,-1.586581,35.000011,1074.249756,false,DoNotOverride,12.0",
            ["Content"] = "蠢货，那是魔灵！",
            ["ContentKR"] = "멍청한 놈, 저건 마령이다!",
            ["DialogueId"] = 12033707,
            ["GUID"] = "1E20080E",
            ["NextDialogue"] = 12033708,
            ["Scripts"] = "PlayAnimation{_delay{1.5},ActorId{211037},AnimationId{\"Angry01_Start\"}}",
            ["SpeakNpcId"] = 211037,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20080E",
            },
        [12033708] = {
            ["Camera"] = "-2936.262695,253.024292,-96.198242,0.000075,-4.800557,-24.382278,35.000008,267.529114,false,DoNotOverride,2.8",
            ["Content"] = "我怎么没见过长这样的魔灵……",
            ["ContentKR"] = "저렇게 생긴 마령은 처음 보는뎁쇼...",
            ["DialogueId"] = 12033708,
            ["GUID"] = "1E200838",
            ["NextDialogue"] = 12033709,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{2.5},ActorId{211037},AnimationId{\"Angry01_End\"}},\
SEQ{\
PlayAnimation{_delay{0.5},ActorId{211039},AnimationId{\"Talk03_Start\"}},\
PlayAnimation{_delay{2.5},ActorId{211039},AnimationId{\"Talk03_End\"}}\
}\
}",
            ["SpeakNpcId"] = 211039,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E200838",
            },
        [12033709] = {
            ["Camera"] = "-2712.877686,127.540527,-141.259766,0.000156,0.998758,-172.586914,35.000011,544.833557,false,DoNotOverride,12.0",
            ["Content"] = "我也没见过，估计是比较稀有的品种吧。",
            ["ContentKR"] = "그건 나도 마찬가지다. 아마 희귀한 녀석들이겠지.",
            ["DialogueId"] = 12033709,
            ["GUID"] = "1E200862",
            ["NextDialogue"] = 12033710,
            ["SpeakNpcId"] = 211037,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E200862",
            },
        [12033710] = {
            ["Camera"] = "-1975.500122,112.498108,-95.56543,0.000173,-4.801363,-175.988037,35.000011,544.833557,false,DoNotOverride,12.0",
            ["Content"] = "诶？我听道上的兄弟说，稀有的魔灵好像可以卖不少钱呢！要不咱们把它们抓了，说不定能多赚一笔？",
            ["ContentKR"] = "오? 희귀한 마령은 꽤 비싼 값에 팔린다던데요! 저 녀석들을 잡으면, 한몫 두둑이 챙길 수 있지 않을까요?",
            ["DialogueId"] = 12033710,
            ["GUID"] = "1E20088C",
            ["NextDialogue"] = 12033711,
            ["Scripts"] = "PlayAnimation{_delay{0.5},ActorId{211039},AnimationId{\"Talk02_Start\"}}",
            ["SpeakNpcId"] = 211039,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20088C",
            },
        [12033711] = {
            ["Content"] = "还有这事？没想到你小子还挺机灵……好哇，兄弟们，抄家伙，把那两个魔灵抓起来！",
            ["ContentKR"] = "그래? 자식, 제법이구나... 좋아, 얘들아, 연장 챙겨라. 저 두 마령을 잡아!",
            ["DialogueId"] = 12033711,
            ["GUID"] = "1E2008B6",
            ["Scripts"] = "PlayAnimation{_delay{7.5},ActorId{211037},AnimationId{\"Angry01_Start\"}}",
            ["SpeakNpcId"] = 211037,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E2008B6",
            },
        [12033712] = {
            ["Content"] = "一部分强盗离开洞窟，留两个在里面看人质",
            ["ContentKR"] = "강도 중 일부가 거점을 떠나고, 2명만 남아 인질을 감시한다.",
            ["DialogueId"] = 12033712,
            ["GUID"] = "1E2008E0",
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E2008E0",
            },
        [12033801] = {
            ["Content"] = "趁现在……！",
            ["ContentKR"] = "바로 지금이야...!",
            ["DialogueId"] = 12033801,
            ["GUID"] = "1E20177A",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20177A",
            },
        [12033802] = {
            ["Content"] = "主角冲进去，和里面留着的几个强盗打起来\
菲娜来到塞维欧身边",
            ["ContentKR"] = "주인공이 안으로 뛰어 들어가 남아 있던 강도들과 싸운다.\
피나가 세비오 곁으로 다가간다.",
            ["DialogueId"] = 12033802,
            ["GUID"] = "1E2017A4",
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E2017A4",
            },
        [12033803] = {
            ["Camera"] = "17.753981,46.233505,139.238281,-18.000107,15.599734,27.200218,35.000008,133.443878,false,Manual,2.8",
            ["Content"] = "塞维欧，醒醒！你没事吧？",
            ["ContentKR"] = "세비오, 정신 차려! 괜찮아?",
            ["DialogueId"] = 12033803,
            ["FinalCamera"] = "31.312517,53.192848,143.547852,-18.000196,15.799729,27.200317,35.000008,112.97599,false,Manual,2.8",
            ["GUID"] = "1E2017CE",
            ["NextDialogue"] = 12033805,
            ["Scripts"] = "PARA{\
PlayFacial{_delay{0.5},ActorId{211001},FacialId{\"Sad01\"}},\
PlayAnimation{_delay{0.5},ActorId{211001},AnimationId{\"Feina_Story_Wish_Start\"}}\
}",
            ["SpeakNpcId"] = 211001,
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E2017CE",
            },
        [12033804] = {
