            ["TurnTo"] = {
                [1] = "211012:p(60)",
                [2] = "\
211015:p(-60)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E205A6A",
            },
        [12034210] = {
            ["Camera"] = "-615.978088,484.191132,91.832031,0.000151,3.652819,-87.176445,50.000008,177.332092,false,Manual,8.0",
            ["Content"] = "不用客气。不如说，应该由我来向卡珊德拉小姐道谢才对。",
            ["ContentKR"] = "천만에. 오히려 내가 카산드라 양한테 고마워해야 하는걸.",
            ["DialogueId"] = 12034210,
            ["FinalCamera"] = "-614.42688,484.269348,91.832031,0.000151,3.652819,-87.176445,50.000008,177.332092,false,Manual,8.0",
            ["GUID"] = "1E205A94",
            ["LookAt"] = {
                [1] = "211012:n(211001)",
                [2] = "\
211015:n(211012)",
                },
            ["NextDialogue"] = 12034211,
            ["Scripts"] = "PlayAnimation{_delay{1},ActorId{211001},AnimationId{\"DisagreeHead\"},Duration{1}}",
