            },
        [12034302] = {
            ["Camera"] = "-191.809433,63.705963,132.844238,0.000047,-4.982602,40.37281,50.0,345.933563,false,Manual,8.0",
            ["Content"] = "怎么了，菲娜？",
            ["ContentKR"] = "왜 그래, 피나?",
            ["DialogueId"] = 12034302,
