        [12034608] = {
            ["Content"] = "菲娜，菲娜！我们也来咯！",
            ["ContentKR"] = "피나, 피나! 우리도 왔어!",
            ["DialogueId"] = 12034608,
            ["GUID"] = "1E209BE0",
            ["SpeakNpcId"] = 211012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E209BE0",
            },
        [12034609] = {
            ["Content"] = "菲娜去门口开门，主角和卡珊德拉出现",
            ["DialogueId"] = 12034609,
            ["GUID"] = "1E209C0A",
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E209C0A",
            },
        [12034701] = {
            ["Camera"] = "67.369461,704.07135,163.671875,0.000133,0.9707,-140.685501,28.000008,150.821991,false,Manual,10.0",
            ["Content"] = "菲娜，你听我说，刚才真是太巧啦，我在商店里遇到了那谁{性别：哥哥|姐姐}！嘿嘿，今天我请客，这些蛋糕、饼干和糖果，你们尽管吃！",
            ["ContentKR"] = "피나, 내 말 좀 들어 봐. 아까 가게에서 아무개 {性别:오빠|언니}랑 마주쳤어! 엄청난 우연이지! 헤헤, 오늘은 내가 사는 거니까, 다들 케이크랑 쿠키, 그리고 과자도 잔뜩 먹어!",
            ["DialogueId"] = 12034701,
            ["FinalCamera"] = "343.453094,606.111816,172.441406,0.00007,-6.629395,-144.681458,35.000011,261.24472,false,Manual,12.0",
            ["GUID"] = "1E20AB22",
            ["NextDialogue"] = 12034702,
            ["Scripts"] = "SEQ{\
LookAt{LookAtDescription{\"211012:n(211001)\"}},\
PlayAnimation{ActorId{211012},AnimationId{\"Confident_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 211012,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20AB22",
            },
        [12034702] = {
            ["Camera"] = "-205.539246,392.728455,111.792969,0.000099,-0.029329,53.919659,28.0,261.24472,false,Manual,12.0",
            ["Content"] = "哇……好棒！",
            ["ContentKR"] = "와... 굉장하다!",
            ["DialogueId"] = 12034702,
