}",
            ["SpeakNpcId"] = 211002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20AD98",
            },
        [12034717] = {
            ["Content"] = "你回来得正好，快来加入菲娜的茶会吧，大魔法狗，啊，不对，大魔法师。",
            ["ContentKR"] = "마침 잘 왔어. 어서 피나의 다과회에 참여해. 대마법개, 아, 아니지, 대마법사.",
            ["DialogueId"] = 12034717,
