            ["DialogueId"] = 12040211,
            ["GUID"] = "1E24331E",
            ["NextDialogue"] = 12040212,
            },
        [12040212] = {
            ["Content"] = "诶诶诶——你可别吓我啊！",
            ["ContentKR"] = "어?????? 너 무섭게 왜 이래!",
            ["DialogueId"] = 12040212,
            ["GUID"] = "1E243348",
