            },
        [12040215] = {
            ["Content"] = "（捉弄白。）",
            ["ContentKR"] = "(스노우를 놀린다.)",
            ["DialogueId"] = 12040215,
            ["GUID"] = "1E2433C6",
            ["ImprPlusId"] = 1205,
            ["NextDialogue"] = 12040217,
            },
        [12040216] = {
            ["Content"] = "（安慰白。）",
            ["ContentKR"] = "(스노우를 위로한다.)",
            ["DialogueId"] = 12040216,
            ["GUID"] = "1E2433F0",
            ["ImprPlusId"] = 1204,
            ["NextDialogue"] = 12040222,
            },
        [12040217] = {
            ["Content"] = "是啊，都忘了。包括你说要罩着我，结果躲在我身后瑟瑟发抖的那件事，都忘得一干二净了。",
            ["ContentKR"] = "응, 다 잊었어. 날 지켜주겠다며 큰소리치더니, 결국 내 등 뒤에 숨어서 덜덜 떨었던 것까지 전부 하나도 생각 안 나.",
            ["DialogueId"] = 12040217,
