            ["NextDialogue"] = 12040218,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E24341A",
            },
        [12040218] = {
            ["Content"] = "什么嘛！这不是该有不该有的记忆，统统都在嘛！",
            ["ContentKR"] = "뭐야! 굳이 기억 안 해도 되는 것까지 싹 다 기억하고 있잖아!",
