            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27A7E8",
            },
        [12045605] = {
            ["Content"] = "先问你一个问题，对于大风九章的来历，你知道多少？",
            ["ContentKR"] = "먼저 질문 하나 할게. 대풍구장의 탄생 배경에 대해서, 얼마나 알아?",
            ["DialogueId"] = 12045605,
            ["GUID"] = "1E27A812",
            ["NextDialogue"] = 12045606,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27A812",
            },
        [12045606] = {
            ["Content"] = "我记得我记得！是一个很厉害的家伙创立的，那个人叫……",
            ["ContentKR"] = "어어어... 맞아! 엄청 대단한 사람이 만들었다고 그랬어. 이름이 뭐였더라...",
            ["DialogueId"] = 12045606,
            ["GUID"] = "1E27A83C",
            ["NextOptions"] = {
                [1] = 12045607,
                [2] = 12045608,
                [3] = 12045609,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27A83C",
            },
        [12045607] = {
            ["Content"] = "是悬衡派的先人飏创立的。",
            ["ContentKR"] = "현형파의 시조인 양이란 사람!",
            ["DialogueId"] = 12045607,
            ["GUID"] = "1E27A866",
            ["ImprPlusId"] = 1203,
            ["NextDialogue"] = 12045610,
            },
        [12045608] = {
            ["Content"] = "是光之魔王大人白女士穿越时空创立的！",
            ["ContentKR"] = "이 빛의 마왕 스노우님께서 시공을 초월해 만들었지!",
            ["DialogueId"] = 12045608,
            ["GUID"] = "1E27A890",
            ["ImprPlusId"] = 1205,
            ["NextDialogue"] = 12045611,
            },
        [12045609] = {
            ["Content"] = "我想不起来了……",
            ["ContentKR"] = "기억이 안 나는데...",
            ["DialogueId"] = 12045609,
            ["GUID"] = "1E27A8BA",
            ["ImprPlusId"] = 1202,
            ["NextDialogue"] = 12045612,
            },
        [12045610] = {
            ["Content"] = "哼，就知道悬衡派会把功劳全都揽到自己头上。",
            ["ContentKR"] = "칫, 그럴 줄 알았어. 현형파가 모든 공을 자기들이 세운 것처럼 꾸며놨겠지.",
            ["DialogueId"] = 12045610,
            ["FacialId"] = {
                [1] = "240026:Angry01",
                },
            ["GUID"] = "1E27A8E4",
            ["NextDialogue"] = 12045612,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27A8E4",
            },
        [12045611] = {
            ["Content"] = "喂喂，回答太离谱可是会扣分的！",
            ["ContentKR"] = "너무 황당한 대답하면 감점이야!",
            ["DialogueId"] = 12045611,
            ["FacialId"] = {
                [1] = "240026:Angry01",
                },
            ["GUID"] = "1E27A90E",
            ["NextDialogue"] = 12045612,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27A90E",
            },
        [12045612] = {
            ["Content"] = "呀！小仆从你什么时候回来的！",
            ["ContentKR"] = "앗! 시종, 너 언제 돌아왔어!",
            ["DialogueId"] = 12045612,
            ["GUID"] = "1E27A938",
            ["NextDialogue"] = 12045613,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27A938",
            },
        [12045613] = {
            ["Content"] = "怎么啦，你能听师姐讲课，我就不能听了吗？",
            ["ContentKR"] = "왜? 나도 선배님 강의 좀 들으면 안 돼?",
            ["DialogueId"] = 12045613,
            ["FacialId"] = {
                [1] = "240026:None",
                },
            ["GUID"] = "1E27A962",
            ["NextDialogue"] = 12045614,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27A962",
            },
        [12045614] = {
            ["Content"] = "当然欢迎！那么，我继续讲——上古时期，秽兽频出，纷争不绝于境。",
            ["ContentKR"] = "난 언제나 환영이야! 그럼 수업 계속할게. 아주 먼 고대엔 필토이드가 자주 출몰해서, 온 세상에 분쟁이 끊이질 않았어.",
            ["DialogueId"] = 12045614,
            ["FacialId"] = {
                [1] = "240026:Smile01",
                },
            ["GUID"] = "1E27A98C",
            ["NextDialogue"] = 12045615,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27A98C",
            },
        [12045615] = {
            ["Content"] = "如何才能让华胥子民免受秽蚀和战争的困扰呢，开国先祖<H>矩</>和<H>飏</>二人进行了长足的思考。",
            ["ContentKR"] = "어떻게 하면 화서의 백성이 침식과 전쟁의 고통에서 벗어나게 만들 수 있을까, 건국시조 <H>구</>와<H>양</>, 두 분께선 아주 오랫동안 고뇌하셨지.",
            ["DialogueId"] = 12045615,
            ["GUID"] = "1E27A9B6",
            ["NextDialogue"] = 12045616,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27A9B6",
            },
        [12045616] = {
            ["Content"] = "最终，大风九章横空出世，给华胥带来了绵延数百年的和平。",
            ["ContentKR"] = "그러다 마침내, 대풍구장이 세상에 모습을 드러냈고, 화서는 수백 년 동안 긴 평화를 누리게 됐어.",
            ["DialogueId"] = 12045616,
            ["GUID"] = "1E27A9E0",
            ["NextDialogue"] = 12045617,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27A9E0",
            },
        [12045617] = {
            ["Content"] = "这庇佑华胥全境的惊世之术，可不是光凭飏一人就能完成的，我们机枢派的先人<H>矩</>在此过程中也发挥了必不可少的作用。",
            ["ContentKR"] = "화서 전체를 지켜주는 이 놀라운 술법은, 양 한 사람만의 힘으로 완성된 게 아니야. 우리 기추파의 시조이신 <H>구</>께서도 중요한 역할을 하셨어.",
            ["DialogueId"] = 12045617,
            ["GUID"] = "1E27AA0A",
            ["NextDialogue"] = 12045618,
            ["RelatedWikiId"] = {
                [1] = 203010,
                },
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AA0A",
            },
        [12045618] = {
            ["Content"] = "你们或许知道，飏有一种特殊的能力，通过焚烧“香”这种介质，她能够影响和操控区域中的秽兽，让它们乖乖听话，不再伤人。",
            ["ContentKR"] = "아는지 모르겠는데, 양한테는 특별한 능력이 있었어. '향'이란 매개체를 태워서, 특정 구역에 있는 필토이드에게 영향을 주고 조종해, 사람을 해치지 못하게 만드는 능력이었지.",
            ["DialogueId"] = 12045618,
            ["GUID"] = "1E27AA34",
            ["NextDialogue"] = 12045619,
            ["RelatedWikiId"] = {
                [1] = 203003,
                },
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AA34",
            },
        [12045619] = {
            ["Content"] = "但是怎么才能将这种能力固定和放大呢？",
            ["ContentKR"] = "그렇다면 어떻게 해야 그 능력을 영구적으로 고정하고, 증폭할 수 있을까?",
            ["DialogueId"] = 12045619,
            ["GUID"] = "1E27AA5E",
            ["NextDialogue"] = 12045620,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AA5E",
            },
        [12045620] = {
            ["Content"] = "为了寻找这个答案，矩四处游学，甚至最远抵达了艾利西安的“塔”下，与你们海伯利亚的先祖展开了一场激动人心的史诗大冒险——咳咳，扯远了。",
            ["ContentKR"] = "그 해답을 찾기 위해, 구께서는 온 세상을 떠돌며 지식을 탐구하셨어. 멀리는 엘리시안의 '탑'아래까지 말이야. 거기서 너희 휘페르보레아 제국의 선조와 만나 흥미진진한 모험의 대서사시를... 크흠, 얘기가 딴 데로 샜네.",
            ["DialogueId"] = 12045620,
            ["GUID"] = "1E27AA88",
            ["NextDialogue"] = 12045621,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AA88",
            },
        [12045621] = {
            ["Content"] = "总之，矩最后找到了答案。他带着这个答案回到华胥，集齐人力物力，打造了一个巨大的工程。",
            ["ContentKR"] = "아무튼! 구께서는 마침내 해답을 찾아내셨고, 그 지식을 가지고 화서로 돌아와 인력과 자원을 총동원해서 거대한 계획을 만들어 내셨어.",
            ["DialogueId"] = 12045621,
            ["GUID"] = "1E27AAB2",
            ["NextDialogue"] = 12045622,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AAB2",
            },
        [12045622] = {
            ["Content"] = "然后，飏、矩，还有许多有龙氏先人，一起在这个工程内祭献了身躯，用生命让飏的分香术永久固定下来，这就形成了大风九章的根基。",
            ["ContentKR"] = "그 후, 양, 구, 그리고 선대의 수많은 용의 자손이 그 계획에 스스로를 제물로 바쳐, 자신들의 생명을 동력 삼아, 영구적인 분향술을 걸어 둔 거지. 그게 바로 대풍구장의 뿌리야.",
            ["DialogueId"] = 12045622,
            ["GUID"] = "1E27AADC",
            ["NextDialogue"] = 12045623,
            ["RelatedWikiId"] = {
                [1] = 304003,
                },
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AADC",
            },
        [12045623] = {
            ["Content"] = "传闻中，那个工程的本体就藏在执律阁上方。其中原理以及用到的种种精妙术式，到今天已经失传了。",
            ["ContentKR"] = "전설에 따르면, 그 계획의 본체는 집률각 꼭대기에 숨겨져 있대. 거기 사용된 원리나 수많은 정교한 기술들은, 지금은 전부 사라져 버렸고.",
            ["DialogueId"] = 12045623,
            ["GUID"] = "1E27AB06",
            ["NextDialogue"] = 12045624,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AB06",
            },
        [12045624] = {
            ["Content"] = "要不是那里是常人无法进入的禁地，可真想进去看一看啊……",
            ["ContentKR"] = "거기가 일반인 출입 금지 구역만 아니었어도, 꼭 들어가 봤을 텐데...",
            ["DialogueId"] = 12045624,
            ["GUID"] = "1E27AB30",
            ["NextDialogue"] = 12045625,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AB30",
            },
        [12045625] = {
            ["Content"] = "飏和矩祭献了生命之后，太皓和烛阴作为他们意志的代行者，一直统领着华胥。他们所创立的悬衡和机枢两派，也携手在治理上出力。",
            ["ContentKR"] = "양과 구께서 자신을 희생하신 뒤로는, 태호와 촉룡이 두 분의 의지를 대리하여 화서를 다스렸어. 그리고 두 분이 창립한 현형파와 기추파, 두 문파가 힘을 합쳐 나라를 이끌었지.",
            ["DialogueId"] = 12045625,
            ["GUID"] = "1E27AB5A",
            ["NextDialogue"] = 12045626,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AB5A",
            },
        [12045626] = {
            ["Content"] = "那时候，机枢派的弟子名册每年都是厚厚一大本，研究经费更是要多少有多少，可不用像现在这样紧巴巴地过日子……这或许就是祖上阔过吧。",
            ["ContentKR"] = "그 시절엔 말이야, 기추파 소속 제자 명단만 해도 매년 이만큼 두꺼웠고, 연구비도 달라는 대로 줬다나 봐. 지금처럼 이렇게 쪼들리면서 살 필요가 없었다는 거지... 왕년엔 우리도 잘나갔다는 거야.",
            ["DialogueId"] = 12045626,
            ["GUID"] = "1E27AB84",
            ["NextDialogue"] = 12045627,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AB84",
            },
        [12045627] = {
            ["Content"] = "原来机枢派曾经这么风光——那怎么沦落到现在这种地步了？",
            ["ContentKR"] = "기추파가 그렇게 대단했었구나... 근데 어쩌다가 지금은 이렇게 된 거야?",
            ["DialogueId"] = 12045627,
            ["GUID"] = "1E27ABAE",
            ["NextDialogue"] = 12045628,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27ABAE",
            },
        [12045628] = {
            ["Content"] = "苏乙，你刚刚提到了烛阴曾经是受人崇敬的神明，但现在它在大家眼里却是带来祸患的恶龙。机枢派的衰落与这个也有关系吗？",
            ["ContentKR"] = "소을, 아까 촉룡도 한때는 존경받는 신이었다고 했잖아? 지금은 모두에게 재앙을 부르는 사악한 용 취급을 받고 있는데, 혹시 기추파의 몰락이랑 상관있어?",
            ["DialogueId"] = 12045628,
            ["GUID"] = "1E27ABD8",
            ["NextDialogue"] = 12045629,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27ABD8",
            },
        [12045629] = {
            ["Content"] = "很敏锐嘛，{nickname}，不愧是你。",
            ["ContentKR"] = "예리한데, {nickname}. 역시 대단해.",
            ["DialogueId"] = 12045629,
            ["GUID"] = "1E27AC02",
            ["NextDialogue"] = 12045630,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AC02",
            },
        [12045630] = {
            ["Content"] = "黍离之战的剧变后，悬衡派的那些家伙将很多事实都隐瞒了。这个版本的历史，也只有我们这支机枢派的亲传保留了下来。所以接下来也要听好了哦。",
            ["ContentKR"] = "탄식의 전투라는 대격변이 일어난 뒤로, 현형파 녀석들은 수많은 진실을 덮어버렸어. 지금부터 내가 할 얘기는, 우리 기추파 직계 제자들만 아는 진짜 역사야. 그러니까 집중해서 잘 들어.",
            ["DialogueId"] = 12045630,
            ["GUID"] = "1E27AC2C",
            ["NextDialogue"] = 12045631,
            ["RelatedWikiId"] = {
                [1] = 407006,
                },
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AC2C",
            },
        [12045631] = {
            ["Content"] = "说回上古时期，虽然悬衡和机枢派曾经共同治理华胥，但是双方的理念有所不同。那时候大风九章远不像现在这么死板——甚至人类是可以和神明共治华胥的。",
            ["ContentKR"] = "다시 고대 얘기로 돌아가 보자면, 현형파랑 기추파가 함께 화서를 다스리긴 했지만, 서로 추구하는 방향이 좀 달랐어. 그때만 해도, 대풍구장은 지금처럼 고지식하지 않아서, 인간도 신과 함께 화서를 다스릴 수도 있었지.",
            ["DialogueId"] = 12045631,
            ["GUID"] = "1E27AC56",
            ["NextDialogue"] = 12045632,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AC56",
            },
        [12045632] = {
            ["Content"] = "我们机枢派认为，应该以心为基准去衡量万物，悬衡派却坚持法不留情的原则，双方在很多案件的判定上有争执。这样日积月累下来，产生了很多摩擦。",
            ["ContentKR"] = "우리 기추파는 모든 걸 마음을 기준으로 판단해야 한다고 생각했지만, 현형파는 법에는 감정이 개입되지 않아야 한다는 원칙을 고수했어. 그러다 보니까, 사사건건 부딪쳤고, 갈등이 쌓이고 쌓여서, 충돌도 많이 일어났지.",
            ["DialogueId"] = 12045632,
            ["GUID"] = "1E27AC80",
            ["NextDialogue"] = 12045633,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AC80",
            },
        [12045633] = {
            ["Content"] = "当时积攒的种种矛盾，在黍离之战时被彻底引燃了。",
            ["ContentKR"] = "그렇게 쌓여가던 갈등이, 탄식의 전투를 계기로 완전히 폭발해 버린 거야.",
            ["DialogueId"] = 12045633,
            ["GUID"] = "1E27ACAA",
            ["NextDialogue"] = 12045634,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27ACAA",
            },
        [12045634] = {
            ["Content"] = "听鸦原所在的位置，曾经是机枢派的研究重地，却在内战中被彻底付之一炬。",
            ["ContentKR"] = "청아원이 있는 곳도, 원래는 우리 기추파의 핵심 연구 기지였는데, 내전 중에 잿더미가 돼 버렸어.",
            ["DialogueId"] = 12045634,
            ["GUID"] = "1E27ACD4",
            ["NextDialogue"] = 12045635,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27ACD4",
            },
        [12045635] = {
            ["Content"] = "当时的内情谁也不清楚。只知道悬衡派怀疑我们机枢派有叛乱风险，带兵前去探查，最后不知怎的就变成了战争，双方无一生还。",
            ["ContentKR"] = "그때 정확히 무슨 일이 있었는지는 아무도 몰라. 공식적으로 알려진 건, 현형파가 우리 기추파가 반란을 꾸미고 있다고 의심해서, 군대를 이끌고 조사하러 왔었는데, 그게 어쩌다 보니까 전면전으로 번져서, 양쪽 모두 전멸했다는 거야.",
            ["DialogueId"] = 12045635,
            ["GUID"] = "1E27ACFE",
            ["NextDialogue"] = 12045636,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27ACFE",
            },
        [12045636] = {
            ["Content"] = "这个消息传来后，所有人都非常震惊。明明有了为祈愿和平而诞生的大风九章，却依然酿成了如此大的灾祸，这是无论如何也不能允许的。",
            ["ContentKR"] = "그 소식이 퍼지자, 모두가 엄청난 충격에 휩싸였어. 평화를 지키기 위해 만든 대풍구장이 있었는데도, 그런 끔찍한 참사가 벌어졌다는 건 도저히 용납할 수 없는 일이었거든.",
            ["DialogueId"] = 12045636,
            ["GUID"] = "1E27AD28",
            ["NextDialogue"] = 12045637,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AD28",
            },
        [12045637] = {
            ["Content"] = "那时的悬衡派认为失控的愤怒和猜疑让人们割舍了理性，不再遵守秩序，从而引发了这场战争，因此心便是祸患之源。",
            ["ContentKR"] = "그때 현형파는 통제되지 않는 감정과 의심이 인간의 이성을 마비시키는 바람에 그런 비극이 생겼다고 판단했고, 그래서 모든 재앙의 근원은 마음이라고 결론지었어.",
            ["DialogueId"] = 12045637,
            ["GUID"] = "1E27AD52",
            ["NextDialogue"] = 12045638,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AD52",
            },
        [12045638] = {
            ["Content"] = "最终他们将机枢派的守护神烛阴封印了起来。也正是从那时开始，大风九章开始失衡，太皓变得一味强调死板的诫律，也不再聆听人类的声音。",
            ["ContentKR"] = "결국 현형파는 마음을 중시하던 우리 기추파의 수호신, 촉룡을 봉인해 버렸지. 그리고 바로 그때부터 대풍구장은 균형을 잃기 시작했어. 태호는 냉혹한 규율만을 내세우며, 더 이상 인간의 목소리에 귀를 기울이지 않게 됐고.",
            ["DialogueId"] = 12045638,
            ["GUID"] = "1E27AD7C",
            ["NextDialogue"] = 12045639,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AD7C",
            },
        [12045639] = {
            ["Content"] = "机枢派受到打压，很多技术从此成为禁忌。人们还需要匠矩阁的机傀技术帮助生产建设，但却添加了重重限制和偏见。",
            ["ContentKR"] = "우리 기추파는 탄압의 대상이 됐고, 수많은 기술이 금지됐어. 물건을 만들고 건물을 지으려면, 우리 장구각의 기계 꼭두각시 기술이 필요한 데도, 온갖 제약과 편견의 낙인이 찍혀버렸지.",
            ["DialogueId"] = 12045639,
            ["FacialId"] = {
                [1] = "240026:Sad03",
                },
            ["GUID"] = "1E27ADA6",
            ["NextDialogue"] = 12045640,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Sad02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27ADA6",
            },
        [12045640] = {
            ["Content"] = "有些机枢派传人不满大风九章的僵化，便单独分家出去，和飘零人一起找到这里作为藏身之处。这就是山外山的前身啦。",
            ["ContentKR"] = "그러자 융통성을 잃은 대풍구장에 불만을 품은 일부 기추파의 후예들이 따로 갈라져 나와, 다른 나그네들과 함께 여기 숨어들었어. 그게 바로 이 산외산의 시초야.",
            ["DialogueId"] = 12045640,
            ["GUID"] = "1E27ADD0",
            ["NextDialogue"] = 12045641,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27ADD0",
            },
        [12045641] = {
            ["Content"] = "嗯……事情经过大概就是这些。怎么样，你们还有问题吗？",
            ["ContentKR"] = "음... 대강 이런 이야기인데, 어때? 더 궁금한 거 있어?",
            ["DialogueId"] = 12045641,
            ["FacialId"] = {
                [1] = "240026:None",
                },
            ["GUID"] = "1E27ADFA",
            ["NextOptions"] = {
                [1] = 12045642,
                [2] = 12045643,
                [3] = 12045644,
                },
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Sad02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27ADFA",
            },
        [12045642] = {
            ["Content"] = "提到烛阴的回忆。",
            ["ContentKR"] = "촉룡의 기억에서 봤던 내용을 말해 준다.",
            ["DialogueId"] = 12045642,
            ["GUID"] = "1E27AE24",
            ["NextDialogue"] = 12045645,
            },
        [12045643] = {
            ["Content"] = "提到偃隐宫中的卷轴。",
            ["ContentKR"] = "언은궁에서 발견한 두루마리에 대해 이야기한다.",
            ["DialogueId"] = 12045643,
            ["GUID"] = "1E27AE4E",
            ["NextDialogue"] = 12045647,
            },
        [12045644] = {
            ["Content"] = "没什么想说的。",
            ["ContentKR"] = "내가 무슨 말을 해야 좋을지 모르겠네.",
            ["DialogueId"] = 12045644,
            ["GUID"] = "1E27AE78",
            ["NextDialogue"] = 12045651,
            },
        [12045645] = {
            ["Content"] = "是吗……原来这些过往历史的碎片，你曾经在烛阴的记忆中看到过。",
            ["ContentKR"] = "그랬구나... 촉룡의 기억 속에서 과거의 조각들을 직접 본 거네.",
            ["DialogueId"] = 12045645,
            ["GUID"] = "1E27AEA2",
            ["NextDialogue"] = 12045646,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AEA2",
            },
        [12045646] = {
            ["Content"] = "心理失衡，后患无穷……现在这风雨飘摇的现状，或许证明了当初悬衡派的做法过于激进吧。",
            ["ContentKR"] = "'마음'과 '이치' 사이의 균형이 무너지면, 반드시 화를 부르는 법이지... 난 위태로운 지금 현실이, 그때 현형파의 방식이 너무 과격했다는 증거가 아닐까 해.",
            ["DialogueId"] = 12045646,
            ["GUID"] = "1E27AECC",
            ["NextDialogue"] = 12045651,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AECC",
            },
        [12045647] = {
            ["Content"] = "没错，那位建造偃隐宫的前辈所留下的手记，或许能成为解开黍离之战内情的关键线索。",
            ["ContentKR"] = "맞아! 언은궁을 세운 그 선조가 남긴 기록이라면, 탄식의 전투의 내막을 밝힐 결정적인 단서가 돼 줄지도 몰라.",
            ["DialogueId"] = 12045647,
            ["GUID"] = "1E27AEF6",
            ["NextDialogue"] = 12045648,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AEF6",
            },
        [12045648] = {
            ["Content"] = "要是如他所说……当时机枢派并没有主动挑起叛乱，在那个大雾弥漫、地磁紊乱的拂晓之中，某具机傀突然失灵了，让双方都以为对面先动了手。",
            ["ContentKR"] = "그 기록이 사실이라면... 그때 기추파는 반란을 일으킨 게 아니야. 안개가 자욱하고, 땅의 자기장이 불안정하던 어느 새벽에, 기계 꼭두각시 하나가 갑자기 오작동하는 바람에, 상대가 공격했다고 오해한 거잖아.",
            ["DialogueId"] = 12045648,
            ["GUID"] = "1E27AF20",
            ["NextDialogue"] = 12045649,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AF20",
            },
        [12045649] = {
            ["Content"] = "数百年的打压和悲剧，竟是这种意外误解带来的。",
            ["ContentKR"] = "수백 년에 걸친 억압과 비극이... 그깟 오해 하나 때문이었다니.",
            ["DialogueId"] = 12045649,
            ["GUID"] = "1E27AF4A",
            ["NextDialogue"] = 12045650,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AF4A",
            },
        [12045650] = {
            ["Content"] = "事到如今，这个真相也失去了它本该拥有的意义……心与心之间的矛盾，并非是那么轻易就能弥合的。",
            ["ContentKR"] = "이제 와서 이런 진실이 무슨 소용이겠어... 사람 마음속에 생긴 깊은 골은, 그렇게 간단히 메워지지 않는걸.",
            ["DialogueId"] = 12045650,
            ["GUID"] = "1E27AF74",
            ["NextDialogue"] = 12045651,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AF74",
            },
        [12045651] = {
            ["Content"] = "呀，不知不觉就讲了这么长时间……总而言之，无论机枢派曾经是风光还是落寞，那都是过去的事情了！",
            ["ContentKR"] = "앗, 나도 모르게 말이 너무 길어졌네... 어쨌든, 과거에 우리 기추파가 아무리 대단했어도, 결국 다 지나간 일일 뿐이야!",
            ["DialogueId"] = 12045651,
            ["GUID"] = "1E27AF9E",
            ["NextDialogue"] = 12045652,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AF9E",
            },
        [12045652] = {
            ["Content"] = "比起那些陈年旧事，还是当下比较重要啦。还有这么多要务得赶紧去处理呢，可不是缅怀往事的时候。",
            ["ContentKR"] = "그런 옛날이야기보단, 현재가 더 중요해. 지금 해결해야 할 일이 태산인데, 과거에 매달려 있을 때가 아니지.",
            ["DialogueId"] = 12045652,
            ["GUID"] = "1E27AFC8",
            ["NextDialogue"] = 12045653,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AFC8",
            },
        [12045653] = {
            ["Content"] = "你们赶紧忙去吧。要是有什么问题，随时再来问我。本师姐会为你们好好答疑解惑的！",
            ["ContentKR"] = "너희도 얼른 가 봐. 궁금한 거 있으면, 언제든 찾아오고. 이 선배님이 친절하게 다 알려 줄게!",
            ["DialogueId"] = 12045653,
            ["GUID"] = "1E27AFF2",
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AFF2",
            },
        [12045701] = {
            ["Content"] = "……{nickname}，你来了啊。",
            ["ContentKR"] = "...왔구나, {nickname}.",
            ["DialogueId"] = 12045701,
            ["GUID"] = "1E27B7D2",
            ["NextDialogue"] = 12045702,
            ["RelatedWikiId"] = {
                [1] = 203007,
                [2] = 203004,
                },
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27B7D2",
            },
        [12045702] = {
            ["Content"] = "本欲来这竹林中练练剑，结果始终找不到手感。想来是我满心杂念，浑身不得劲，连剑老兄也看不过去了。",
            ["ContentKR"] = "이 대나무 숲에서 검이라도 휘둘러볼까 했는데, 통 집중이 안 되는구나. 마음이 복잡한 걸, 이 검도 아는 모양이다.",
            ["DialogueId"] = 12045702,
            ["GUID"] = "1E27B7FC",
            ["NextDialogue"] = 12045703,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27B7FC",
            },
        [12045703] = {
            ["Content"] = "刻舟，你还好吗？看你平时总是大咧咧的，没想到也会有这样心事重重的时候。",
            ["ContentKR"] = "각주, 너 무슨 일 있어? 평소답지 않게 왜 그렇게 풀이 죽어 있어.",
            ["DialogueId"] = 12045703,
            ["GUID"] = "1E27B826",
            ["NextDialogue"] = 12045704,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27B826",
            },
        [12045704] = {
            ["Content"] = "……以前看不起别人在深夜多愁善感，没想到风水轮流转，这种不潇洒的事也轮到自己身上了。",
            ["ContentKR"] = "...옛날엔 밤중에 청승떠는 놈들이 제일 꼴불견이라고 생각했는데, 세상일 모른다더니, 내가 지금 딱 그 꼴이다.",
            ["DialogueId"] = 12045704,
            ["GUID"] = "1E27B850",
            ["NextDialogue"] = 12045705,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27B850",
            },
        [12045705] = {
            ["Content"] = "我总想起当年的事，那时我也在这儿练剑，先是树枝，然后是木剑，最后才是真正的剑。",
            ["ContentKR"] = "자꾸 옛날 생각이 나지 뭐냐. 그때도 여기서 검을 휘둘렀거든. 처음엔 나뭇가지를, 그다음엔 목검을, 그리고 마지막엔 진검을 손에 쥐었지.",
            ["DialogueId"] = 12045705,
            ["GUID"] = "1E27B87A",
            ["NextDialogue"] = 12045706,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27B87A",
            },
        [12045706] = {
            ["Content"] = "师兄和不夏就站在你现在站的地方。师兄板着脸指点我招式，不夏就老在那儿上蹿下跳地喝彩，跳得老高。",
            ["ContentKR"] = "네가 지금 서 있는 그 자리엔, 사형과 불하가 있었다. 사형은 늘 무뚝뚝하게 내 자세를 고쳐줬고, 불하는 그 옆에서 날 응원해 줬다. 사방을 방방 뛰어다니면서 말이야.",
            ["DialogueId"] = 12045706,
            ["GUID"] = "1E27B8A4",
            ["NextDialogue"] = 12045707,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27B8A4",
            },
        [12045707] = {
            ["Content"] = "可如今这大好月色，只能照我一个心有郁结的失意人，属实是浪费了。",
            ["ContentKR"] = "그런데 지금은 이 좋은 달빛이 고작 이 울적한 각주만 비추고 있으니, 정말 아까울 노릇 아니냐.",
            ["DialogueId"] = 12045707,
            ["GUID"] = "1E27B8CE",
            ["NextDialogue"] = 12045708,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27B8CE",
            },
        [12045708] = {
            ["Content"] = "“不夏”……这个名字，煜明白天和你吵架的时候也提到过。她是谁？",
            ["ContentKR"] = "'불하'란 이름... 아까 낮에 욱명이랑 싸울 때도 얘기했었지? 그 사람은 누구야?",
            ["DialogueId"] = 12045708,
            ["GUID"] = "1E27B8F8",
            ["NextDialogue"] = 12045709,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27B8F8",
            },
        [12045709] = {
            ["Content"] = "是我和师兄从烟津渡捡来的小师妹，如今已经不在人世了。",
            ["ContentKR"] = "나하고 사형이 연진 나루터에서 데려온 막내 사매였다. 지금은 이 세상 사람이 아니지만.",
            ["DialogueId"] = 12045709,
            ["GUID"] = "1E27B922",
            ["NextDialogue"] = 12045710,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27B922",
            },
        [12045710] = {
            ["Content"] = "她是因为什么去世的？",
            ["ContentKR"] = "어쩌다 그렇게 됐는데?",
            ["DialogueId"] = 12045710,
            ["GUID"] = "1E27B94C",
            ["NextDialogue"] = 12045711,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27B94C",
            },
        [12045711] = {
            ["Content"] = "因为“自由”。",
            ["ContentKR"] = "'자유' 때문에.",
            ["DialogueId"] = 12045711,
            ["GUID"] = "1E27B976",
            ["NextDialogue"] = 12045712,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27B976",
            },
        [12045712] = {
            ["Content"] = "说来可笑吧？我们飘零人终其一生追求的自由无拘，最终害死了她。",
            ["ContentKR"] = "우습지 않으냐? 우리 나그네가 평생을 바쳐 좇는 그놈의 자유가, 결국 그 애를 죽음으로 몰아넣었단 게 말이야.",
            ["DialogueId"] = 12045712,
            ["GUID"] = "1E27B9A0",
            ["NextDialogue"] = 12045713,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27B9A0",
            },
        [12045713] = {
            ["Content"] = "你或许知道，华胥人打从一生下来就活在大风九章的条条框框之中。不许做这，不许做那。不许习武，不许打架，更不许对龙神不敬。",
            ["ContentKR"] = "네가 알진 모르겠지만, 화서 사람들은 태어날 때부터 대풍구장이 정해놓은 틀 안에서만 살아야 한다. 무예 수련도, 사사로운 다툼도 안 돼. 용신께 불경한 짓을 하는 건 더더욱 안 되지.",
            ["DialogueId"] = 12045713,
            ["GUID"] = "1E27B9CA",
            ["NextDialogue"] = 12045714,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27B9CA",
            },
        [12045714] = {
            ["Content"] = "那要是想争出一身自由怎么办？就只能想办法跳出这大风九章的重重束缚，这也正是飘零人一直以来追求的目标。",
            ["ContentKR"] = "그럼 자유를 원한다면 어떻게 해야겠느냐? 당연히 이 숨 막히는 대풍구장한테서 벗어나는 수밖에. 그게 바로 우리 나그네가 줄곧 추구해 온 목표였다.",
            ["DialogueId"] = 12045714,
            ["GUID"] = "1E27B9F4",
            ["NextDialogue"] = 12045715,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27B9F4",
            },
        [12045715] = {
            ["Content"] = "五年前，能将大风九章隔绝在外的天罗拒风仪发明出来了，我们终于做到了！",
            ["ContentKR"] = "그러다가 5년 전, 대풍구장의 감시를 완전히 차단할 수 있는 천라거풍의가 발명됐다. 우리가 마침내 해낸 거지!",
            ["DialogueId"] = 12045715,
            ["GUID"] = "1E27BA1E",
            ["NextDialogue"] = 12045716,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BA1E",
            },
        [12045716] = {
            ["Content"] = "山外山的每个人都高兴得紧，光是庆功宴就连着开了一场又一场。那阵子啊，隔着几米远就能闻到别人衣服上烤肉留下的烟熏味。",
            ["ContentKR"] = "산외산의 모두가 뛸 듯이 기뻐했다. 그땐 며칠이나 잔치를 벌였는지, 저 멀리서도 다른 사람 옷에서 나는 고기 냄새를 맡을 수 있을 정도였어.",
            ["DialogueId"] = 12045716,
            ["GUID"] = "1E27BA48",
            ["NextDialogue"] = 12045717,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BA48",
            },
        [12045717] = {
            ["Content"] = "但我们谁都忘了。大风九章不仅仅是惩戒逾矩的家伙，它还有个重要的功能——将秽蚀隔绝于外。",
            ["ContentKR"] = "그때의 우린 대풍구장이 규칙을 어긴 녀석을 벌하는 것 말고도, 침식을 막아 주는 방벽 역할도 한다는 사실을 까맣게 잊고 있었다.",
            ["DialogueId"] = 12045717,
            ["GUID"] = "1E27BA72",
            ["NextDialogue"] = 12045718,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BA72",
            },
        [12045718] = {
            ["Content"] = "难道说……？！",
            ["ContentKR"] = "설마...?!",
            ["DialogueId"] = 12045718,
            ["GUID"] = "1E27BA9C",
            ["NextDialogue"] = 12045719,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BA9C",
            },
        [12045719] = {
            ["Content"] = "……正是你想的那样。",
            ["ContentKR"] = "...네가 생각한 그대로야.",
            ["DialogueId"] = 12045719,
            ["GUID"] = "1E27BAC6",
            ["NextDialogue"] = 12045720,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BAC6",
            },
        [12045720] = {
            ["Content"] = "我们过了太久的太平日子，“秽蚀”这个对外国人来说很恐怖的词，在华胥这儿却只存在在古书里。",
            ["ContentKR"] = "너무 긴 시간 동안 평화로웠던 게 문제였지. 너 같은 이방인에겐 익숙한 단어일지 몰라도, 화서에서 '침식'은 고서에서나 나오는 말이었거든.",
            ["DialogueId"] = 12045720,
            ["GUID"] = "1E27BAF0",
            ["NextDialogue"] = 12045721,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BAF0",
            },
        [12045721] = {
            ["Content"] = "在大风九章治下，秽蚀者会直接化为狴犴，执行大风九章的意志。但当大风九章被我们隔绝之后，那些怪物……回来了。",
            ["ContentKR"] = "대풍구장의 감시 아래에선 침식자가 되면, 즉시 대풍구장의 의지를 집행하는 폐안으로 변하지. 하지만 우리가 대풍구장과의 연결을 끊자, 그 괴물들이... 돌아와 버린 거다.",
            ["DialogueId"] = 12045721,
            ["GUID"] = "1E27BB1A",
            ["NextDialogue"] = 12045722,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BB1A",
            },
        [12045722] = {
            ["Content"] = "不夏那时候快要成年了。就在成年的前一天，她变成了可怖的秽兽，袭击了我们的基地。很多人在那场事故中死去了，包括我们的师父。",
            ["ContentKR"] = "불하는 막 성인이 되려던 참이었다. 그리고 성인식을 하루 앞둔 날 밤, 그 애는 끔찍한 필토이드로 변해서 기지를 닥치는 대로 파괴하기 시작했지. 그 사고로 많은 사람이 목숨을 잃었다. 내 스승님도 그때 돌아가셨지.",
            ["DialogueId"] = 12045722,
            ["GUID"] = "1E27BB44",
            ["NextDialogue"] = 12045723,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BB44",
            },
        [12045723] = {
            ["Content"] = "她之前嚷嚷着头痛的时候，我们都没当回事，以为只是普通风寒，习武之人的身子骨硬朗，挺过去便是了。只有师兄细心，一人潜进城里药堂买药。",
            ["ContentKR"] = "그 애가 머리가 아프다며 칭얼댔을 때, 우리는 그저 고뿔에 걸렸나 생각하고 신경 쓰지 않았다. 무예를 익히는 사람은 튼튼하니까, 좀 앓다 보면 낫겠지 했거든. 하지만 사형만은 혼자 묵묵히 성안 약방에 약을 구하러 갔다.",
            ["DialogueId"] = 12045723,
            ["GUID"] = "1E27BB6E",
            ["NextDialogue"] = 12045724,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BB6E",
            },
        [12045724] = {
            ["Content"] = "师兄让我留下来看住她的情况。我没听。一点城里杂耍班子的消息就把我勾走了。是啊，照看小师妹，哪里有进城看热闹来得有意思。",
            ["ContentKR"] = "사형은 내게 불하 곁에 남아 상태를 봐 주라고 했지만, 난 듣지 않았다. 마침 성안에 곡예단이 온단 소리에 정신이 팔렸었거든. 막내 사매를 간호하는 것보단, 성안을 신나게 구경하는 게 훨씬 재미있으니까.",
            ["DialogueId"] = 12045724,
            ["GUID"] = "1E27BB98",
            ["NextDialogue"] = 12045725,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BB98",
            },
        [12045725] = {
            ["Content"] = "最后……怎么样了？",
            ["ContentKR"] = "그래서... 어떻게 됐어?",
            ["DialogueId"] = 12045725,
            ["GUID"] = "1E27BBC2",
            ["NextDialogue"] = 12045726,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BBC2",
            },
        [12045726] = {
            ["Content"] = "几个时辰后，我回到山外山，只看到一地血泊……以及站在血泊中的师兄。那让人几欲呕吐的鲜红，我恐怕这辈子都忘不掉了。",
            ["ContentKR"] = "실컷 구경하고 몇 시간 뒤에 돌아와 보니, 기지는 이미 피바다가 돼 있었다... 그 안에 우두커니 서 있던 사형의 모습과 구역질 날 것 같던 선홍색을, 난 아마 평생 잊지 못하겠지.",
            ["DialogueId"] = 12045726,
            ["GUID"] = "1E27BBEC",
            ["NextDialogue"] = 12045727,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BBEC",
            },
        [12045727] = {
            ["Content"] = "师兄亲手杀了她——这个我们亲手养大，视为妹妹的孩子。他求来的药洒了一地，和那些血混在一起。",
            ["ContentKR"] = "우리 손으로 거두고, 여동생처럼 아꼈던 그 애를, 사형이 직접 죽였다. 사형이 구해 온 약은, 바닥에 쏟아져 피와 뒤섞여 있었지.",
            ["DialogueId"] = 12045727,
            ["GUID"] = "1E27BC16",
            ["NextDialogue"] = 12045728,
            ["RelatedWikiId"] = {
                [1] = 203011,
                },
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BC16",
            },
        [12045728] = {
            ["Content"] = "从那之后，师兄几乎再也没有笑过，人也变得更加寡言少语。后来，一个满月的夜晚，师兄独自离开了。再见面时，他已经变成了应天尉。",
            ["ContentKR"] = "그날 이후로 사형은 거의 웃지 않았고, 말수도 눈에 띄게 적어졌다. 그러다가 보름달이 뜬 어느 날 밤, 사형은 홀연히 사라졌고, 다시 만났을 땐 응천위가 되어 있더군.",
            ["DialogueId"] = 12045728,
            ["GUID"] = "1E27BC40",
            ["NextDialogue"] = 12045729,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BC40",
            },
        [12045729] = {
            ["Content"] = "我不知道他和白龙达成了什么交易，我只知道，那个小时候带着我偷溜出去买桂花糕，会手把手指导我剑术的师兄再也不会回来了。",
            ["ContentKR"] = "백룡과 대체 무슨 거래를 한 건지는 몰라. 다만, 어릴 적에 날 몰래 데리고 나가 계화떡을 사주고, 내 손을 잡고 검술을 가르쳐 주던 그 사형은 이제 두 번 다시 돌아오지 않을 거란 건 안다.",
            ["DialogueId"] = 12045729,
            ["GUID"] = "1E27BC6A",
            ["NextDialogue"] = 12045730,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BC6A",
            },
        [12045730] = {
            ["Content"] = "自那天起，我也再没看过一次杂耍。",
            ["ContentKR"] = "그리고 그날 이후로, 나 역시 두 번 다시 곡예를 보러 가지 않아.",
            ["DialogueId"] = 12045730,
            ["GUID"] = "1E27BC94",
            ["NextDialogue"] = 12045731,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BC94",
            },
        [12045731] = {
            ["Content"] = "……其实，师兄说的那些，我全都明白。白天他质问我为何“只破不立”时，我也确实回答不上来。",
            ["ContentKR"] = "...사실, 사형이 말한 얘기, 난 이해해. 낮에 파괴 말고, 창조에 대해 고민해 본 적 있냐고 쏘아붙였을 때, 내가 제대로 받아치지 못한 것도 사실이고.",
            ["DialogueId"] = 12045731,
            ["GUID"] = "1E27BCBE",
            ["NextDialogue"] = 12045732,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BCBE",
            },
        [12045732] = {
            ["Content"] = "这些年来，我总是懊悔，如果不夏秽蚀发作的那一刻，我和师兄在她身边……该有多好。或者再往前，要是我们没有隔绝大风九章，是不是这一切都不会发生？",
            ["ContentKR"] = "지난 몇 년 동안, 난 늘 후회했다. 불하에게 침식이 일어났던 그 순간, 나나 사형이 곁에 있었더라면... 얼마나 좋았을까. 아니면 그보다 더 전에, 우리가 대풍구장을 차단하지 않았더라면, 아무 일도 일어나지 않았을 텐데 하고 말이야.",
            ["DialogueId"] = 12045732,
            ["GUID"] = "1E27BCE8",
            ["NextDialogue"] = 12045733,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BCE8",
            },
        [12045733] = {
            ["Content"] = "我们为了追求自由，却忽视了与之而来的危险。{nickname}，你说，难道从一开始，我们就做错了吗？",
            ["ContentKR"] = "자유를 추구하느라, 우리는 그 뒤에 도사린 위험을 외면했다. {nickname}, 우리가... 처음부터 잘못 생각했던 것일까?",
            ["DialogueId"] = 12045733,
            ["GUID"] = "1E27BD12",
            ["NextDialogue"] = 12045734,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BD12",
            },
        [12045734] = {
            ["Content"] = "……刻舟，我也有很要好的朋友因为秽蚀而去世了，所以我明白你的心情。",
            ["ContentKR"] = "...각주, 나도 침식으로 정말 소중한 친구를 잃은 적이 있어. 그래서 네 마음이 어떤지 알아.",
            ["DialogueId"] = 12045734,
            ["GUID"] = "1E27BD3C",
            ["NextDialogue"] = 12045735,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BD3C",
            },
        [12045735] = {
            ["Content"] = "但是，这件事的根源不在于大风九章，也不在于你们，而是秽蚀的错。所以不要自责。",
            ["ContentKR"] = "하지만 그 일은 애초에 침식 때문인 거지, 대풍구장의 잘못도, 너희의 잘못도 아니야. 그러니까 너무 자책하지 마.",
            ["DialogueId"] = 12045735,
            ["GUID"] = "1E27BD66",
            ["NextDialogue"] = 12045736,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BD66",
            },
        [12045736] = {
            ["Content"] = "就算在大风九章统治的地方，不夏照样会变成无神无志的狴犴，无法和亲人交谈……我想，那也并不算是活着。",
            ["ContentKR"] = "대풍구장의 힘이 미치는 곳에 있었다고 해도, 불하는 결국 의지도 감정도 사라진 채, 가족과 말 한마디 나누지 못하는 폐안이 됐을 거야... 난, 그건 살아도 사는 게 아니라고 생각해.",
            ["DialogueId"] = 12045736,
            ["GUID"] = "1E27BD90",
            ["NextDialogue"] = 12045737,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BD90",
            },
        [12045737] = {
            ["Content"] = "是非对错，往往难以判断……但我唯一可以肯定的是，你想要保护他人的心，绝不是错误的。",
            ["ContentKR"] = "뭐가 옳고 뭐가 그른지는 쉽게 판단할 수 없지만... 이거 하나만큼은 단언할 수 있어. 다른 사람을 지키고 싶어 하는 네 마음은, 절대 잘못이 아니야.",
            ["DialogueId"] = 12045737,
            ["GUID"] = "1E27BDBA",
            ["NextDialogue"] = 12045738,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BDBA",
            },
        [12045738] = {
            ["Content"] = "…………",
            ["ContentKR"] = "......",
            ["DialogueId"] = 12045738,
            ["GUID"] = "1E27BDE4",
            ["NextDialogue"] = 12045739,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BDE4",
            },
        [12045739] = {
            ["Content"] = "我曾经的生活非常简单。在鱼钩挂上饵食就能吸引鱼群，野兔被猎枪打中就会死，一切都遵循着最简单不过的原则。",
            ["ContentKR"] = "내가 살던 곳은 모든 게 단순했어. 낚싯대를 드리우면 고기가 잡히고, 총을 쏘면 토끼가 쓰러졌지. 아주 간단한 원칙이었어.",
            ["DialogueId"] = 12045739,
            ["GUID"] = "1E27BE0E",
            ["NextDialogue"] = 12045740,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BE0E",
            },
        [12045740] = {
            ["Content"] = "直到我离开故乡、踏上旅途，我才意识到世界远比我想象得更加复杂，事情也常常会偏离自己的预料。",
            ["ContentKR"] = "하지만 여행을 시작하고 나서 알았어. 이 세상은 그렇게 단순하지 않고, 늘 내 뜻대로만 되진 않는다는 걸.",
            ["DialogueId"] = 12045740,
            ["GUID"] = "1E27BE38",
            ["NextDialogue"] = 12045741,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BE38",
            },
        [12045741] = {
            ["Content"] = "我认识一个医生，他一直想拯救人，可他做不到。为了让那些人不至于死得更痛苦，他不得不杀死那些人，最终他也失去了生命。",
            ["ContentKR"] = "아는 의사가 한 명 있었어. 그 사람은 늘 사람을 구하고 싶어 했지만, 그러지 못했지. 오히려 환자들이 더 큰 고통을 겪지 않게 하려고 제 손으로 목숨을 끊어줘야만 했고, 결국 자신도 목숨을 잃었어.",
            ["DialogueId"] = 12045741,
            ["GUID"] = "1E27BE62",
            ["NextDialogue"] = 12045742,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BE62",
            },
        [12045742] = {
            ["Content"] = "我听说过一个孩子，他只想实现幼时的梦想。可是他为了追逐梦想做出的选择，却让他万劫不复。他失去了人类的身躯，在怪物的躯壳里苟延残喘。",
            ["ContentKR"] = "그리고 어떤 아이 이야기도 들었어. 그저 어릴 적 꿈을 이루고 싶었을 뿐인데, 그 꿈을 좇기 위한 선택 때문에 돌이킬 수 없는 길을 걷고 말았지. 결국 인간의 몸을 잃고, 괴물의 껍데기 속에서 간신히 목숨을 이어 나가고 있어.",
            ["DialogueId"] = 12045742,
            ["GUID"] = "1E27BE8C",
            ["NextDialogue"] = 12045743,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BE8C",
            },
        [12045743] = {
            ["Content"] = "短短数天，我发现原来命运是这么无常的东西。即使你做出其他选择，结果也未必一定比今天更好。",
            ["ContentKR"] = "불과 며칠 만에 내가 배운 건, 운명이란 참 얄궂다는 거야. 만약 네가 그때 다른 선택을 했더라도, 그 결과가 지금보다 더 나았으리란 보장은 없어.",
            ["DialogueId"] = 12045743,
            ["GUID"] = "1E27BEB6",
            ["NextDialogue"] = 12045744,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BEB6",
            },
        [12045744] = {
            ["Content"] = "所以我想，与其去哀叹无法挽回的过去，不如去做些还来得及的事情。比如，如果秽蚀再度发生，该如何保护这里的人们。",
            ["ContentKR"] = "난 이미 돌이킬 수 없는 과거를 후회하는 것보다, 지금이라도 할 수 있는 일을 하는 게 더 중요하다고 생각해. 예를 들면, 또다시 침식이 일어나면, 그땐 여기 사람들을 어떻게 지킬지 같은 거 말이야.",
            ["DialogueId"] = 12045744,
            ["GUID"] = "1E27BEE0",
            ["NextDialogue"] = 12045745,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BEE0",
            },
        [12045745] = {
            ["Content"] = "……但是，唯独不要停下脚步，因为躲在原地是解决不了任何问题的。",
            ["ContentKR"] = "...그러니까, 계속 나아가야 해. 주저앉아 있는다고 해결되는 건 하나도 없잖아.",
            ["DialogueId"] = 12045745,
            ["GUID"] = "1E27BF0A",
            ["NextDialogue"] = 12045746,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BF0A",
            },
        [12045746] = {
            ["Content"] = "“不要停下脚步”……",
            ["ContentKR"] = "'계속 나아가야 한다'라...",
            ["DialogueId"] = 12045746,
            ["GUID"] = "1E27BF34",
            ["NextDialogue"] = 12045747,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BF34",
            },
        [12045747] = {
            ["Content"] = "哈哈……是啊。光躲在这里自怨自艾有什么用。往事不可谏，但那来者，我刻舟还得去追上一追。",
            ["ContentKR"] = "하하... 그래. 여기서 혼자 끙끙 앓아봐야 뭐가 달라지겠어. 엎질러진 물은 주워 담을 수 없지만, 앞으로 닥쳐올 파도는, 내가 한번 막아 봐야지.",
            ["DialogueId"] = 12045747,
            ["GUID"] = "1E27BF5E",
            ["NextDialogue"] = 12045748,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BF5E",
            },
        [12045748] = {
            ["Content"] = "多谢你了……{nickname}。",
            ["ContentKR"] = "고맙다, {nickname}...",
            ["DialogueId"] = 12045748,
            ["GUID"] = "1E27BF88",
            ["NextDialogue"] = 12045749,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BF88",
            },
        [12045749] = {
            ["Content"] = "好啦，我们出来了这么久，姑奶奶嘴上不说，心中一定着急得很。我们还是赶紧回去商议正事吧，别让她老人家担心了！",
            ["ContentKR"] = "자, 슬슬 돌아가자. 고모할머니가 말은 안 해도 많이 걱정하고 있을 게 뻔해. 어르신 걱정 안 하시게 얼른 돌아가서 중요한 일이나 상의하자고!",
            ["DialogueId"] = 12045749,
            ["GUID"] = "1E27BFB2",
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BFB2",
            },
        [12045801] = {
            ["Content"] = "你们回来啦！",
            ["ContentKR"] = "돌아왔구나!",
            ["DialogueId"] = 12045801,
            ["GUID"] = "1E27C83A",
            ["NextDialogue"] = 12045802,
            ["RelatedWikiId"] = {
                [1] = 203007,
                [2] = 203009,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120458/1E27C83A",
            },
        [12045802] = {
            ["Content"] = "怎么都哭丧着脸？不会还在为白天的事发愁吧？没事没事，那么多应天尉呼啦啦一起上，还能守半个时辰，四舍五入不就是咱们和白龙五五开！",
            ["ContentKR"] = "왜 다들 죽상이야? 설마 아직도 낮에 쳐들어왔던 놈들 때문에 그래? 괜찮아, 응천위 놈들이 우르르 몰려왔는데도 반 시진 버텼으면 잘한 거다. 우리가 백룡이랑 막상막하란 거지!",
            ["DialogueId"] = 12045802,
            ["GUID"] = "1E27C864",
            ["NextDialogue"] = 12045803,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120458/1E27C864",
            },
        [12045803] = {
            ["Content"] = "谁沮丧了。我可是一直在这儿统计损失，修理机傀，可不像某些人躲去林子里偷偷哭鼻子。",
            ["ContentKR"] = "죽상이라니? 난 계속 여기서 피해 상황 확인하고, 기계 꼭두각시 수리하느라 정신없었거든? 숲에 숨어서 몰래 질질 짜던 누구랑은 다르다고.",
            ["DialogueId"] = 12045803,
            ["GUID"] = "1E27C88E",
            ["NextDialogue"] = 12045804,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120458/1E27C88E",
            },
        [12045804] = {
            ["Content"] = "倒是你，心情好点了没？可别拖我们的后腿哦。",
            ["ContentKR"] = "그래서, 기분은 좀 풀렸어? 괜히 우리 발목 잡지 마.",
            ["DialogueId"] = 12045804,
            ["GUID"] = "1E27C8B8",
            ["NextDialogue"] = 12045805,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120458/1E27C8B8",
            },
        [12045805] = {
            ["Content"] = "哈哈，谢姑奶奶关心！",
            ["ContentKR"] = "하하, 걱정해 줘서 고마워요, 고모할머니!",
            ["DialogueId"] = 12045805,
            ["GUID"] = "1E27C8E2",
            ["NextDialogue"] = 12045806,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120458/1E27C8E2",
            },
        [12045806] = {
            ["Content"] = "多亏了{nickname}的开解，师兄那个问题我想明白了——谁规定我们就一定要被大风九章保护了？",
            ["ContentKR"] = "{nickname} 덕분에 낮에 사형이 던졌던 질문에 대한 답을 찾았어요. 우리가 왜 꼭 대풍구장의 보호를 받아야만 하죠?",
            ["DialogueId"] = 12045806,
            ["GUID"] = "1E27C90C",
            ["NextDialogue"] = 12045807,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120458/1E27C90C",
            },
        [12045807] = {
            ["Content"] = "我刻舟一人除不完秽蚀。若是十人、百人联手起来，大家都拿起武器，众志成城，还怕打不过一两个秽蚀者？",
            ["ContentKR"] = "물론 저 혼자서 모든 침식을 막는 건 역부족이겠죠. 하지만 열 명, 또 백 명이 모여서 한마음으로 뭉쳐 싸운다면, 침식자 한둘을 못 이기겠어요?",
            ["DialogueId"] = 12045807,
            ["GUID"] = "1E27C936",
            ["NextDialogue"] = 12045808,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120458/1E27C936",
            },
        [12045808] = {
            ["Content"] = "事在人为。先前输止流两招，下一局，我们就一举把赢面扳回来。不管她在谋划什么，只要干脆利落地统统打破就可以！",
            ["ContentKR"] = "뜻이 있는 곳에 길이 있는 법이에요. 지류한테 두 번은 당했지만, 다음번엔 우리가 제대로 한 방 먹여주자고요. 그 여자가 무슨 수작을 부리든, 그냥 시원하게 깨부숴 버려요!",
            ["DialogueId"] = 12045808,
            ["GUID"] = "1E27C960",
            ["NextDialogue"] = 12045809,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120458/1E27C960",
            },
        [12045809] = {
            ["Content"] = "气势不错，但光有气势可不行。那么，商量一下接下来的计划吧。",
            ["ContentKR"] = "기세 하나는 좋네. 그런데 기세만으론 안 되는 거 알지? 자, 그럼 앞으로 어떻게 할지 계획부터 세워보자.",
            ["DialogueId"] = 12045809,
            ["GUID"] = "1E27C98A",
            ["NextDialogue"] = 12045810,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120458/1E27C98A",
            },
        [12045810] = {
            ["Content"] = "我想，山外山如今要做的是协助{nickname}，等{性别：他|她}解开止流的第三卦再做打算。对了，扶疏姑娘那边……",
            ["ContentKR"] = "난 일단 지류의 세 번째 예언이 뭔지 알아낼 수 있도록, 우리 산외산이 {nickname}한테 최대한 협조해야 한다고 봐... 아참, 부소 씨 쪽은...",
            ["DialogueId"] = 12045810,
            ["GUID"] = "1E27C9B4",
            ["NextDialogue"] = 12045811,
            ["RelatedWikiId"] = {
                [1] = 401005,
                },
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120458/1E27C9B4",
            },
        [12045811] = {
            ["Content"] = "我已经寻访到了无穷藏派传人隐居的地方，就在皓京西郊的椒兰村。",
            ["ContentKR"] = "무궁장파의 후손들이 숨어 지내는 곳을 알아냈어요. 호경 서쪽 교외에 있는 초란 마을이에요.",
            ["DialogueId"] = 12045811,
            ["GUID"] = "1E27C9DE",
            ["NextDialogue"] = 12045812,
            ["RelatedWikiId"] = {
                [1] = 408020,
                [2] = 407014,
                },
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120458/1E27C9DE",
            },
        [12045812] = {
            ["Content"] = "椒兰村？巧了，这里恰好有一位“本地向导”可以为你们带路。",
            ["ContentKR"] = "초란 마을? 마침 잘됐군. 그 동네 지리에 훤한 토박이가 여기 있어.",
            ["DialogueId"] = 12045812,
            ["GUID"] = "1E27CA08",
            ["NextDialogue"] = 12045813,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120458/1E27CA08",
            },
        [12045813] = {
            ["Content"] = "哎？难不成这个地方就是刻舟你的老家？",
            ["ContentKR"] = "어? 설마 거기가 각주 네 고향이야?",
            ["DialogueId"] = 12045813,
            ["GUID"] = "1E27CA32",
            ["NextDialogue"] = 12045814,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120458/1E27CA32",
            },
        [12045814] = {
            ["Content"] = "许久没回去了，没想到却是以这样的理由。哈哈，也好！是时候故地重游了！",
            ["ContentKR"] = "오랫동안 못 가봤는데, 이런 일로 돌아가게 될 줄이야. 하하, 아무렴 어때! 슬슬 고향에 들를 때가 되기도 했지!",
            ["DialogueId"] = 12045814,
            ["GUID"] = "1E27CA5C",
            ["NextDialogue"] = 12045815,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120458/1E27CA5C",
            },
        [12045815] = {
            ["Content"] = "根据线报，自从执律阁震动之后，原本追捕你们的应天尉已经全线回撤。如今你们回去不会引起太多注意，正是潜入调查的好时机。",
            ["ContentKR"] = "첩보로는, 집률각에서 진동이 퍼져 나가고 나서부터 너희를 추격하던 응천위가 전부 철수했대. 지금 움직이면 별로 눈에 안 띌 테니까, 숨어들어 조사하기엔 딱 좋을 거야.",
            ["DialogueId"] = 12045815,
            ["GUID"] = "1E27CA86",
            ["NextDialogue"] = 12045816,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120458/1E27CA86",
            },
        [12045816] = {
            ["Content"] = "好。待你们准备好了，我们就走吧。",
            ["ContentKR"] = "좋아. 다들 준비되는 대로, 바로 출발이다.",
            ["DialogueId"] = 12045816,
            ["GUID"] = "1E27CAB0",
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120458/1E27CAB0",
            },
        [12045901] = {
            ["Content"] = "小朋友，你知道村庄中关于“无穷藏派”的传闻吗？",
            ["ContentKR"] = "꼬마야, 혹시 마을에서 '무궁장파'랑 관련된 소문 들어본 적 있어?",
            ["DialogueId"] = 12045901,
            ["GUID"] = "1E27D8A2",
            ["NextDialogue"] = 12045902,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120459/1E27D8A2",
            },
        [12045902] = {
            ["Content"] = "虎子不太清楚……",
            ["ContentKR"] = "나는 잘 모르는데...",
            ["DialogueId"] = 12045902,
            ["GUID"] = "1E27D8CC",
            ["NextDialogue"] = 12045903,
            ["SpeakNpcId"] = 240037,
            ["TalkActionId"] = {
                [1] = "240037:Shy03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120459/1E27D8CC",
            },
        [12045903] = {
            ["Content"] = "对了，阿爸说过，不能和陌生人说话！你们是陌生人吗？",
            ["ContentKR"] = "아, 맞다! 아빠가 모르는 사람이랑은 말하지 말랬어! 우리 모르는 사람 아니야?",
            ["DialogueId"] = 12045903,
            ["GUID"] = "1E27D8F6",
            ["NextDialogue"] = 12045904,
            ["SpeakNpcId"] = 240037,
            ["VoiceName"] = "voice/$Locale$/story/1204/120459/1E27D8F6",
            },
        [12045904] = {
            ["Content"] = "哈哈，我们已经说过两句话，就是朋友，不能算陌生人了。",
            ["ContentKR"] = "하하, 이렇게 얘기도 나눴으면 친구지. 모르는 사람이라니.",
            ["DialogueId"] = 12045904,
            ["GUID"] = "1E27D920",
            ["NextDialogue"] = 12045905,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120459/1E27D920",
            },
        [12045905] = {
            ["Content"] = "对了，小朋友，你的阿爸现在在哪儿？",
            ["ContentKR"] = "참, 꼬마야, 아버지는 지금 어디 계셔?",
            ["DialogueId"] = 12045905,
            ["GUID"] = "1E27D94A",
            ["NextDialogue"] = 12045906,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120459/1E27D94A",
            },
        [12045906] = {
            ["Content"] = "阿爸不在家，早上就出去砍柴啦。如果有什么问题，问我阿娘吧，她就在对面那儿晒香呢！",
            ["ContentKR"] = "아빠는 집에 없어. 아침 일찍 땔감 구하러 산에 가셨으니까, 궁금한 거 있으면 엄마한테 물어봐. 엄마는 맞은편에서 향 말리고 계셔!",
            ["DialogueId"] = 12045906,
            ["GUID"] = "1E27D974",
            ["SpeakNpcId"] = 240037,
            ["VoiceName"] = "voice/$Locale$/story/1204/120459/1E27D974",
            },
        [12046001] = {
            ["Content"] = "请问，您对村中隐居的无穷藏派有所了解吗？",
            ["ContentKR"] = "실례지만, 혹시 이 마을에 숨어 지내는 무궁장파에 대해 아시나요?",
            ["DialogueId"] = 12046001,
            ["GUID"] = "1E27E90A",
            ["NextDialogue"] = 12046002,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120460/1E27E90A",
            },
        [12046002] = {
            ["Content"] = "无穷藏派？有些陌生……若说到能教经纶数算的先生，倒还能想起一二。",
            ["ContentKR"] = "무궁장파요? 글쎄요... 혹시 글이나 셈을 가르치는 서당 선생님을 찾으시는 거라면, 생각나는 분이 몇 분 있긴 해요.",
            ["DialogueId"] = 12046002,
            ["FacialId"] = {
                [1] = "240038:Cin_Think",
                },
            ["GUID"] = "1E27E934",
            ["NextDialogue"] = 12046003,
            ["SpeakNpcId"] = 240038,
            ["TalkActionId"] = {
                [1] = "240038:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120460/1E27E934",
            },
        [12046003] = {
            ["Content"] = "这些人精通卜算奇门之术，也就是说热爱捣鼓铜钱、龟壳这些玩意儿。这样说，能让你想起点什么吗？",
            ["ContentKR"] = "아니, 점을 치거나 신기한 술법을 부리는 사람들 말입니다. 왜, 엽전이나 거북 등껍질 같은 거 만지작거리는 양반들 있잖아요. 혹시 생각나는 사람들 없습니까?",
            ["DialogueId"] = 12046003,
            ["GUID"] = "1E27E95E",
            ["NextDialogue"] = 12046004,
            ["SpeakNpcId"] = 240013,
            ["TalkActionId"] = {
                [1] = "240038:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120460/1E27E95E",
            },
        [12046004] = {
            ["Content"] = "……刻舟，怎么是你？！",
            ["ContentKR"] = "...각주? 너 각주 아니야?!",
            ["DialogueId"] = 12046004,
            ["FacialId"] = {
                [1] = "240038:Cin_Angry01",
                },
            ["GUID"] = "1E27E988",
            ["NextDialogue"] = 12046005,
            ["SpeakNpcId"] = 240038,
            ["TalkActionId"] = {
                [1] = "240038:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120460/1E27E988",
            },
        [12046005] = {
            ["Content"] = "啊，咳，是啊……香芸姐。那个，你们身体可还好？一别数年，孩子都这么高了——",
            ["ContentKR"] = "아니, 크흠, 그... 향운 누님. 저, 다들 잘 지내셨어요? 못 본 사이에 아들이 많이 컸...",
            ["DialogueId"] = 12046005,
            ["GUID"] = "1E27E9B2",
            ["NextDialogue"] = 12046006,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120460/1E27E9B2",
            },
        [12046006] = {
            ["Content"] = "虎子，不许在外面玩了，赶紧回家做功课去！小心沾染上什么不三不四的人。",
            ["ContentKR"] = "호야, 그만 놀고 어서 집에 들어가 숙제해! 괜히 이상한 사람들이랑 어울리지 말고!",
            ["DialogueId"] = 12046006,
            ["GUID"] = "1E27E9DC",
            ["NextDialogue"] = 12046007,
            ["SpeakNpcId"] = 240038,
            ["VoiceName"] = "voice/$Locale$/story/1204/120460/1E27E9DC",
            },
        [12046007] = {
            ["Content"] = "恕我无话与各位可说。<H>罪人之后</>还是赶紧请回吧，可别把晦气带来村子了。",
            ["ContentKR"] = "더는 할 말 없으니까, <H>죄인의 자손</>은 썩 돌아가. 괜히 우리 마을 부정 탈라.",
            ["DialogueId"] = 12046007,
            ["GUID"] = "1E27EA06",
            ["SpeakNpcId"] = 240038,
            ["TalkActionId"] = {
                [1] = "240038:Angry01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120460/1E27EA06",
            },
        [12046101] = {
            ["Content"] = "李阿伯，我回来了。向你打听一件事可好？",
            ["ContentKR"] = "어르신, 저 각주입니다. 오랜만에 찾아뵙습니다. 혹시 뭐 하나 여쭤봐도 되겠습니까?",
            ["DialogueId"] = 12046101,
            ["GUID"] = "1E27F972",
            ["NextDialogue"] = 12046102,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27F972",
            },
        [12046102] = {
            ["Content"] = "……你是，刻舟……你长高了，也壮实了……",
            ["ContentKR"] = "...오오, 각주로구나... 키도 크고, 듬직해졌어...",
            ["DialogueId"] = 12046102,
            ["FacialId"] = {
                [1] = "240039:CM_Happy01",
                },
            ["GUID"] = "1E27F99C",
            ["NextDialogue"] = 12046103,
            ["SpeakNpcId"] = 240039,
            ["TalkActionId"] = {
                [1] = "240039:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27F99C",
            },
        [12046103] = {
            ["Content"] = "时隔十几年，你终于愿意回村看看了……",
            ["ContentKR"] = "십수 년 만에, 드디어 마을에 얼굴을 비추는구나...",
            ["DialogueId"] = 12046103,
            ["GUID"] = "1E27F9C6",
            ["NextDialogue"] = 12046104,
            ["SpeakNpcId"] = 240039,
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27F9C6",
            },
        [12046104] = {
            ["Content"] = "我想向您打听个人。放心，我只是帮朋友个忙，问完就走，一刻钟都不多留。",
            ["ContentKR"] = "제가 사람을 찾고 있습니다. 친구를 도우려는 것뿐이니 여쭙고 곧바로 떠나겠습니다. 걱정하지 마십시오.",
            ["DialogueId"] = 12046104,
            ["GUID"] = "1E27F9F0",
            ["NextDialogue"] = 12046105,
            ["SpeakNpcId"] = 240013,
            ["TalkActionId"] = {
                [1] = "240039:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27F9F0",
            },
        [12046105] = {
            ["Content"] = "唉，我不是这个意思……算了，你问吧。",
            ["ContentKR"] = "아이고, 그런 뜻으로 한 말이 아니었는데... 됐다, 궁금한 것이 무엇이냐?",
            ["DialogueId"] = 12046105,
            ["FacialId"] = {
                [1] = "240039:CM_Sad01",
                },
            ["GUID"] = "1E27FA1A",
            ["NextDialogue"] = 12046106,
            ["SpeakNpcId"] = 240039,
            ["TalkActionId"] = {
                [1] = "240039:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27FA1A",
            },
        [12046106] = {
            ["Content"] = "您知道有位无穷藏派高人在村里隐居吗？",
            ["ContentKR"] = "마을에 무궁장파의 고수가 은거하고 있다던데, 혹시 아십니까?",
            ["DialogueId"] = 12046106,
            ["GUID"] = "1E27FA44",
            ["NextDialogue"] = 12046107,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27FA44",
            },
        [12046107] = {
            ["Content"] = "你是说<H>静渊居士</>？断桥对面，崖边那处屋舍便是。",
            ["ContentKR"] = "<H>정연 거사</> 말이냐? 저기 무너진 다리 맞은편, 절벽 가장자리에 있는 집으로 가 보거라.",
            ["DialogueId"] = 12046107,
            ["FacialId"] = {
                [1] = "240039:CM_Idle",
                },
            ["GUID"] = "1E27FA6E",
            ["NextDialogue"] = 12046108,
            ["SpeakNpcId"] = 240039,
            ["TalkActionId"] = {
                [1] = "240039:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27FA6E",
            },
        [12046108] = {
            ["Content"] = "哦！原来就是我以前总是绕着走的那块地儿！",
            ["ContentKR"] = "아! 제가 옛날에 맨날 피해 다니던 그곳이군요!",
            ["DialogueId"] = 12046108,
            ["GUID"] = "1E27FA98",
            ["NextDialogue"] = 12046109,
            ["SpeakNpcId"] = 240013,
            ["TalkActionId"] = {
                [1] = "240039:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27FA98",
            },
        [12046109] = {
            ["Content"] = "我小时候到处上墙揭瓦，村里全都被我倒腾了个遍，每块石头在哪儿我都记得。唯有那里，我每次跑去，就迷迷瞪瞪，不知怎的就发现自己倒栽在树桩旁。",
            ["ContentKR"] = "제가 어릴 때 온 동네를 다 헤집고 다녀서, 마을 구석구석 돌멩이 위치까지 훤한데, 유독 거기만 가면 머리가 멍해지더니, 깨 보면 나무 그루터기 옆에 거꾸로 처박혀 있곤 했죠.",
            ["DialogueId"] = 12046109,
            ["GUID"] = "1E27FAC2",
            ["NextDialogue"] = 12046110,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27FAC2",
            },
        [12046110] = {
            ["Content"] = "若那是无穷藏派的地界，一切都说得通了！谢啦，伯伯。那我们就先告辞了——",
            ["ContentKR"] = "그런데 거기가 무궁장파의 영역이었군요. 이제야 모든 게 설명이 됩니다! 고맙습니다, 어르신. 그러면 저희는 이만...",
            ["DialogueId"] = 12046110,
            ["GUID"] = "1E27FAEC",
            ["NextDialogue"] = 12046111,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27FAEC",
            },
        [12046111] = {
            ["Content"] = "……刻舟，稍等片刻。",
            ["ContentKR"] = "...각주야, 잠시만 기다리거라.",
            ["DialogueId"] = 12046111,
            ["GUID"] = "1E27FB16",
            ["NextDialogue"] = 12046112,
            ["SpeakNpcId"] = 240039,
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27FB16",
            },
        [12046112] = {
            ["Content"] = "嗯？怎么了，阿伯？",
            ["ContentKR"] = "예? 왜 그러십니까, 어르신?",
            ["DialogueId"] = 12046112,
            ["GUID"] = "1E27FB40",
            ["NextDialogue"] = 12046113,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27FB40",
            },
        [12046113] = {
            ["Content"] = "当初赶走你们，我自觉亏欠。这些年来，你过得可还好？",
            ["ContentKR"] = "그때 너희를 내쫓은 것이, 이 늙은이 마음에 빚으로 남았구나. 그동안, 잘 지냈느냐?",
            ["DialogueId"] = 12046113,
            ["GUID"] = "1E27FB6A",
            ["NextDialogue"] = 12046114,
            ["SpeakNpcId"] = 240039,
            ["TalkActionId"] = {
                [1] = "240039:Sigh_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27FB6A",
            },
        [12046114] = {
            ["Content"] = "嗨呀，您千万别放在心上。我现在活得好好的，吃好喝好，逍遥自在。我爹心宽，也绝不会念你。",
            ["ContentKR"] = "어이쿠, 마음에 담아두지 마십시오. 전 지금 잘 먹고 잘살고, 아주 자유롭게 잘 지냅니다. 어버지도 워낙 너그러운 분이시니, 절대 어르신을 원망하지 않으실 겁니다.",
            ["DialogueId"] = 12046114,
            ["GUID"] = "1E27FB94",
            ["NextDialogue"] = 12046115,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27FB94",
            },
        [12046115] = {
            ["Content"] = "……唉。你爹他从始至终都是个好人。",
            ["ContentKR"] = "...후우. 네 아비는 늘 좋은 사람이었지.",
            ["DialogueId"] = 12046115,
            ["FacialId"] = {
                [1] = "240039:CM_Sad01",
                },
            ["GUID"] = "1E27FBBE",
            ["NextDialogue"] = 12046116,
            ["SpeakNpcId"] = 240039,
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27FBBE",
            },
        [12046116] = {
            ["Content"] = "可惜，可惜了。也怨我那时候没有站出来为你们说话……",
            ["ContentKR"] = "참으로 안타깝구나. 그때 내가 조금만 더 용기를 내 너희 편을 들어줬다면...",
            ["DialogueId"] = 12046116,
            ["GUID"] = "1E27FBE8",
            ["NextDialogue"] = 12046117,
            ["SpeakNpcId"] = 240039,
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27FBE8",
            },
        [12046117] = {
            ["Content"] = "别，您可千万别自责啊！我们家当初出事，您为我们送水送食，上下打点。我和我娘对您从来没有一分怨言。",
            ["ContentKR"] = "아뇨, 그런 말씀 마십시오! 저희 집에 일이 터졌을 때, 어르신께서 몰래 먹을 걸 가져다주시고 뒤에서 애써 주셨잖습니까. 저와 제 어머니는 단 한 순간도 어르신을 원망한 적이 없습니다.",
            ["DialogueId"] = 12046117,
            ["GUID"] = "1E27FC12",
            ["NextDialogue"] = 12046118,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27FC12",
            },
        [12046118] = {
            ["Content"] = "总是想那些过去的事情，会折寿的。您老可要放宽心，争取活到一百岁。到时候，我再来给您贺寿！",
            ["ContentKR"] = "자꾸 옛일 생각하시면 오래 못 사십니다. 마음 편히 가지시고, 꼭 백 살까지 사셔야 합니다. 그때는 제가 제대로 잔치 한번 열어 드리겠습니다!",
            ["DialogueId"] = 12046118,
            ["GUID"] = "1E27FC3C",
            ["NextDialogue"] = 12046119,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27FC3C",
            },
        [12046119] = {
            ["Content"] = "这次真得走啦，以后再来找您叙旧。希望下次见到您，您还能这么精神矍铄。",
            ["ContentKR"] = "이젠 정말 가 봐야겠습니다. 다음에 꼭 다시 찾아뵐 테니 그때까지 꼭, 정정하셔야 합니다.",
            ["DialogueId"] = 12046119,
            ["GUID"] = "1E27FC66",
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27FC66",
            },
        [12046201] = {
            ["Content"] = "……你们终于来了。",
            ["ContentKR"] = "...이제야 오셨는가.",
            ["DialogueId"] = 12046201,
            ["GUID"] = "1E2809DA",
            ["NextDialogue"] = 12046202,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120462/1E2809DA",
            },
        [12046202] = {
            ["Content"] = "今日自旭日初升，我便候在这棵梧桐树下，等着诸位的到访。",
            ["ContentKR"] = "오늘 동틀 녘부터, 이 오동나무 아래에서 그대들이 오기만을 기다리고 있었다네.",
            ["DialogueId"] = 12046202,
            ["GUID"] = "1E280A04",
            ["NextDialogue"] = 12046203,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120462/1E280A04",
            },
        [12046203] = {
            ["Content"] = "您早已知道我们要来？",
            ["ContentKR"] = "저희가 올 줄 미리 알고 계셨다는 건가요?",
            ["DialogueId"] = 12046203,
            ["GUID"] = "1E280A2E",
            ["NextDialogue"] = 12046204,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120462/1E280A2E",
            },
        [12046204] = {
            ["Content"] = "无穷藏派自诩以卜算奇门之术窥测天命。虽凭凡人之身，妄言未来，终为枉然。但这无伤大雅的预测还未曾失了准头。",
            ["ContentKR"] = "우리 무궁장파는 점괘와 기문으로 천기를 살피는 이들이지. 인간의 몸으로 앞날을 점치는 것이 부질없다 한들, 이 정도의 작은 흐름은 아직 헛짚은 적이 없다네.",
            ["DialogueId"] = 12046204,
            ["GUID"] = "1E280A58",
            ["NextDialogue"] = 12046205,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120462/1E280A58",
            },
        [12046205] = {
            ["Content"] = "却未自我介绍。我是本代掌门，号静渊居士，我那逆徒止流承蒙你们照顾了。",
            ["ContentKR"] = "소개가 늦었군. 나는 현 무궁장파의 장문, 정연 거사일세. 못난 제자 지류가 그간 여러모로 폐를 많이 끼쳤더군.",
            ["DialogueId"] = 12046205,
            ["GUID"] = "1E280A82",
            ["NextDialogue"] = 12046206,
            ["RelatedWikiId"] = {
                [1] = 203012,
                [2] = 203001,
                [3] = 407014,
                },
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120462/1E280A82",
            },
        [12046206] = {
            ["Content"] = "你说自己什么都能猜到，那让白考考你！你猜到我们此行的目的了吗？",
            ["ContentKR"] = "뭐든 다 꿰뚫어 본다 이거지? 그럼 스노우가 시험해 보겠어! 우리가 여기 왜 왔는지 맞혀 봐!",
            ["DialogueId"] = 12046206,
            ["GUID"] = "1E280AAC",
            ["NextDialogue"] = 12046207,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120462/1E280AAC",
            },
        [12046207] = {
            ["Content"] = "呵呵，放心。这位小友所中的迷卦，我随后就为你们化解。届时{性别：他|她}被遮蔽的记忆也将悉数复原。",
            ["ContentKR"] = "허허, 염려 말게나. 이 친구를 옭아맨 미혹의 괘는 내 조만간 풀어 주겠네. 그리하면 이 친구가 잊었던 기억도 온전히 돌아오겠지.",
            ["DialogueId"] = 12046207,
            ["GUID"] = "1E280AD6",
            ["NextDialogue"] = 12046208,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120462/1E280AD6",
            },
        [12046208] = {
            ["Content"] = "但在那之前，可否赏光，先听一则故事呢？",
            ["ContentKR"] = "다만 그 전에, 괜찮다면 이야기 하나 들어 주겠나?",
            ["DialogueId"] = 12046208,
            ["GUID"] = "1E280B00",
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120462/1E280B00",
            },
        [12046301] = {
            ["Content"] = "您故事中的那个小女孩……就是止流吗？",
            ["ContentKR"] = "방금 그 이야기 속 어린 소녀가... 지류 사장님인 거예요?",
            ["DialogueId"] = 12046301,
            ["GUID"] = "1E281A42",
            ["NextDialogue"] = 12046302,
            ["RelatedWikiId"] = {
                [1] = 203012,
                [2] = 203001,
                [3] = 203007,
                [4] = 407014,
                },
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120463/1E281A42",
            },
        [12046302] = {
            ["Content"] = "正是。",
            ["ContentKR"] = "그렇네.",
            ["DialogueId"] = 12046302,
            ["GUID"] = "1E281A6C",
            ["NextDialogue"] = 12046303,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120463/1E281A6C",
            },
        [12046303] = {
            ["Content"] = "……原来老爹救下的那个小女孩，从来没有忘掉过这件事情。",
            ["ContentKR"] = "아버지가 목숨을 걸고 구했던 그 소녀는... 지금껏 한 순간도 그 일을 잊지 않고 있었던 거군요.",
            ["DialogueId"] = 12046303,
            ["GUID"] = "1E281A96",
            ["NextDialogue"] = 12046304,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120463/1E281A96",
            },
        [12046304] = {
            ["Content"] = "老爹若是知道他当年的见义勇为，会在十几年后掀起这么大的风波，恐怕在虞渊之底都会吓一大跳吧。",
            ["ContentKR"] = "당신의 그 행동이 십수 년 뒤에 이런 거대한 파란을 몰고 올 줄 아셨다면, 아버지께선 아마 저세상에서도 뒷목 잡고 쓰러지셨을 겁니다.",
            ["DialogueId"] = 12046304,
            ["GUID"] = "1E281AC0",
            ["NextDialogue"] = 12046305,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120463/1E281AC0",
            },
        [12046305] = {
            ["Content"] = "我已出世。徒弟的是非对错，我无意评判。",
            ["ContentKR"] = "나는 이미 속세를 떠난 몸일세. 제자가 벌인 일의 옳고 그름을, 내가 평할 수는 없지.",
            ["DialogueId"] = 12046305,
            ["GUID"] = "1E281AEA",
            ["NextDialogue"] = 12046306,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120463/1E281AEA",
            },
        [12046306] = {
            ["Content"] = "{nickname}，我可为你解开你身上的迷卦。等你准备好，就与我说吧。",
            ["ContentKR"] = "{nickname}, 이제 자네의 기억을 가리고 있는 미혹의 괘를 풀어 주겠네. 준비가 되면, 말해주게.",
            ["DialogueId"] = 12046306,
            ["GUID"] = "1E281B14",
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120463/1E281B14",
            },
        [12046401] = {
            ["Content"] = "{nickname}，很抱歉把你卷入了这一切。",
            ["ContentKR"] = "{nickname}, 널 이 일에 끌어들인 건 미안하게 생각해.",
            ["DialogueId"] = 12046401,
            ["GUID"] = "1E282AAA",
            ["NextDialogue"] = 12046402,
            ["RelatedWikiId"] = {
                [1] = 203001,
                [2] = 401005,
                },
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282AAA",
            },
        [12046402] = {
            ["Content"] = "现在再说抱歉，是不是有点晚了？",
            ["ContentKR"] = "이제 와서 사과하는 건, 좀 늦은 거 아닌가요?",
            ["DialogueId"] = 12046402,
            ["GUID"] = "1E282AD4",
            ["NextDialogue"] = 12046403,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282AD4",
            },
        [12046403] = {
            ["Content"] = "呵呵……说的也是呢。我并没有留给你选择的机会。",
            ["ContentKR"] = "후후... 그것도 맞는 말이네. 어차피 난 네게 선택권조차 주지 않았으니까.",
            ["DialogueId"] = 12046403,
            ["GUID"] = "1E282AFE",
            ["NextDialogue"] = 12046404,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282AFE",
            },
        [12046404] = {
            ["Content"] = "我必须承认，从发现你的能力开始，我便谋划着如何将你带回华胥，让这份力量成为我的助力。",
            ["ContentKR"] = "인정할게. 난 네 능력을 처음 발견한 순간부터, 널 어떻게든 화서로 데려와서, 그 힘을, 나를 위해 쓸 계획을 세웠어.",
            ["DialogueId"] = 12046404,
            ["GUID"] = "1E282B28",
            ["NextDialogue"] = 12046405,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282B28",
            },
        [12046405] = {
            ["Content"] = "怀璧其罪。你有着这份奇异的和鸣之力，便注定与平凡的命运无缘。敌人接踵而至，夹道荆棘丛生，你接下来的路，一定走得很艰难。",
            ["ContentKR"] = "재능이 독이 된다는 말이 있지. 레조넌스란 희귀한 능력을 지닌 이상, 넌 평범한 삶을 살아갈 수 없어. 적들은 끝없이 나타날 거고, 네 앞길엔 가시밭길만 펼쳐지겠지. 순탄치는 않을 거야.",
            ["DialogueId"] = 12046405,
            ["GUID"] = "1E282B52",
            ["NextDialogue"] = 12046406,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282B52",
            },
        [12046406] = {
            ["Content"] = "那是我要面对的事情，与你无关。",
            ["ContentKR"] = "그건 제가 감당할 몫이지, 당신이 상관할 바 아니에요.",
            ["DialogueId"] = 12046406,
            ["GUID"] = "1E282B7C",
            ["NextDialogue"] = 12046407,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282B7C",
            },
        [12046407] = {
            ["Content"] = "我并非想故意为难你，恰恰相反，我是在允诺你一份报酬。",
            ["ContentKR"] = "널 곤경에 빠뜨리려는 게 아니야. 오히려, 네게 보상을 주겠다는 거지.",
            ["DialogueId"] = 12046407,
            ["GUID"] = "1E282BA6",
            ["NextDialogue"] = 12046408,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282BA6",
            },
        [12046408] = {
            ["Content"] = "憎恨我吗？认为我惺惺作态吗？",
            ["ContentKR"] = "내가 밉니? 내가 위선자 같아?",
            ["DialogueId"] = 12046408,
            ["GUID"] = "1E282BD0",
            ["NextDialogue"] = 12046409,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282BD0",
            },
        [12046409] = {
            ["Content"] = "怎样都好……我只希望，接下来的这起卦象可以成为对你的部分补偿。",
            ["ContentKR"] = "어떻게 생각하든 상관없어... 다만, 지금부터 내가 보여줄 마지막 예언이 네게 조금이나마 보상이 됐으면 좋겠네.",
            ["DialogueId"] = 12046409,
            ["GUID"] = "1E282BFA",
            ["NextDialogue"] = 12046410,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282BFA",
            },
        [12046410] = {
            ["Content"] = "第三起，革之明夷。大人虎变，晦若坠星，陵悬于虚，辰宿易主。",
            ["ContentKR"] = "세 번째 괘는, 음양이 뒤바뀌는 거대한 변화가 일어날 거야. 거물이 나타나 질서를 무너뜨리고, 빛나던 것들은 추락할 거야. 능은 허공 위에 흔들리고, 별은 주인이 바뀔 거야.",
            ["DialogueId"] = 12046410,
            ["GUID"] = "1E282C24",
            ["NextDialogue"] = 12046411,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282C24",
            },
        [12046411] = {
            ["Content"] = "大风九章的中枢，其名为太虚陵，高悬于执律阁上方的穹顶之中。那里是一切之始。",
            ["ContentKR"] = "대풍구장의 중추, '태허릉'은 집률각 최상층의 둥근 천장 너머에 매달려 있어. 거기가 바로 이 모든 것의 시작이야.",
            ["DialogueId"] = 12046411,
            ["GUID"] = "1E282C4E",
            ["NextDialogue"] = 12046412,
            ["RelatedWikiId"] = {
                [1] = 408021,
                },
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282C4E",
            },
        [12046412] = {
            ["Content"] = "弑神并非易事……凡人之力，岂可窥伺神明？",
            ["ContentKR"] = "신을 죽이는 건 쉬운 일이 아니야... 고작 인간의 힘으로 신을 상대할 수는 없으니까.",
            ["DialogueId"] = 12046412,
            ["GUID"] = "1E282C78",
            ["NextDialogue"] = 12046413,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282C78",
            },
        [12046413] = {
            ["Content"] = "即便太皓已被种种手段削弱，其力生生不息，与凡人之别，仍不啻天渊。能杀死神明的，唯有神明。",
            ["ContentKR"] = "비록 여러 방법으로 태호를 약하게 만들어 놓긴 했지만, 태호의 권능은 무한하고, 인간과 신의 격차는 여전히 하늘과 땅 차이야. 신을 죽일 수 있는 건, 오직 신뿐이지.",
            ["DialogueId"] = 12046413,
            ["GUID"] = "1E282CA2",
            ["NextDialogue"] = 12046414,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282CA2",
            },
        [12046414] = {
            ["Content"] = "因此，当初在祭坛之上，我必须与烛阴缔结同生共死的契约。此棋不容有失。",
            ["ContentKR"] = "그렇기 때문에, 그 제단에서 난 반드시 촉룡과 목숨을 하나로 묶는 계약을 맺어야만 했어. 이 수는 절대 실패해선 안 됐거든.",
            ["DialogueId"] = 12046414,
            ["GUID"] = "1E282CCC",
            ["NextDialogue"] = 12046415,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282CCC",
            },
        [12046415] = {
            ["Content"] = "魂契是亘古传下的几大术式其一。龙渊上卿的力量本为大风九章所授予，借助这点，我能成为承载魂契的容器，我的生命也从此与烛阴相连。",
            ["ContentKR"] = "혼의 계약은 고대로부터 전해오는 대주술 중 하나야. 용연상경의 힘은 대풍구장에게서 부여받은 거니까, 그걸 매개로 삼으면 내가 혼의 계약을 담는 그릇이 될 수 있고, 그 순간부터 내 생명도 촉룡과 이어지게 돼.",
            ["DialogueId"] = 12046415,
            ["GUID"] = "1E282CF6",
            ["NextDialogue"] = 12046416,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282CF6",
            },
        [12046416] = {
            ["Content"] = "烛阴久经封印，其力已衰。下一步，我将在天人陵墓之巅，燃烧己身性命，作为烛阴的祭牲，增幅其力量。",
            ["ContentKR"] = "촉룡은 오랫동안 봉인돼 힘이 턱없이 쇠약해졌어. 그러니까 난 다음 수순으로, 천인 능묘의 정상에서 내 생명을 제물로 바쳐 촉룡의 힘을 최대로 끌어올릴 거야.",
            ["DialogueId"] = 12046416,
            ["GUID"] = "1E282D20",
            ["NextDialogue"] = 12046417,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282D20",
            },
        [12046417] = {
            ["Content"] = "使烛阴归于巢，自相残杀，双龙同归于尽。这便是我能算出的解法。",
            ["ContentKR"] = "촉룡을 제 둥지로 돌려보내, 태호와 싸우게 하고, 두 용이 함께 소멸하게 만든다. 그게 바로 내가 찾아낸 유일한 해답이니까.",
            ["DialogueId"] = 12046417,
            ["GUID"] = "1E282D4A",
            ["NextDialogue"] = 12046418,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282D4A",
            },
        [12046418] = {
            ["Content"] = "而你在这棋局中，要做的事情很简单：在祂们双双力竭之时，杀死我，终结这一切。如此一来，大风九章便能宣告颠覆。",
            ["ContentKR"] = "그리고 이 계획에서 네 역할은 아주 간단해. 두 용 모두 힘이 다했을 때, 네 손으로 날 죽여서 이 모든 걸 끝내. 그걸로, 대풍구장의 시대는 막을 내리게 될 거야.",
            ["DialogueId"] = 12046418,
            ["GUID"] = "1E282D74",
            ["NextDialogue"] = 12046419,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282D74",
            },
        [12046419] = {
            ["Content"] = "……杀死你？",
            ["ContentKR"] = "...당신을 죽이라고요?",
            ["DialogueId"] = 12046419,
            ["GUID"] = "1E282D9E",
            ["NextDialogue"] = 12046420,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282D9E",
            },
        [12046420] = {
            ["Content"] = "没错。",
            ["ContentKR"] = "그래.",
            ["DialogueId"] = 12046420,
            ["GUID"] = "1E282DC8",
            ["NextDialogue"] = 12046421,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282DC8",
            },
        [12046421] = {
            ["Content"] = "魂契的一方死亡时，另一方也无法逃过契约的反噬。",
            ["ContentKR"] = "혼의 계약은 한쪽이 죽으면, 다른 한쪽 역시 그 반동을 고스란히 받게 돼 있거든.",
            ["DialogueId"] = 12046421,
            ["GUID"] = "1E282DF2",
            ["NextDialogue"] = 12046422,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282DF2",
            },
        [12046422] = {
            ["Content"] = "太皓、烛阴本出同源，无法真正给对方带来了断，但魂契的反噬却由祂们共同承担。此时借助契约的力量，就能以我的死亡给一切划下终结。",
            ["ContentKR"] = "태호와 촉룡은 한 뿌리에서 나왔기 때문에, 서로를 완전히 소멸시킬 수 없어. 하지만 계약의 반동은 두 신이 함께 감당해야 하지. 그래서 계약의 힘을 빌리려는 거야. 나의 죽음으로, 모든 것에 마침표를 찍을 수 있도록.",
            ["DialogueId"] = 12046422,
            ["GUID"] = "1E282E1C",
            ["NextDialogue"] = 12046423,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282E1C",
            },
        [12046423] = {
            ["Content"] = "鼎盛状态的神明，或许能够承受住契约的反噬。但力竭的神明可未必。",
            ["ContentKR"] = "멀쩡한 상태의 신이라면 계약의 반동쯤은 버텨낼지도 모르지만, 기력이 쇠한 후엔 다르지.",
            ["DialogueId"] = 12046423,
            ["GUID"] = "1E282E46",
            ["NextDialogue"] = 12046424,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282E46",
            },
        [12046424] = {
            ["Content"] = "而你，将收获名望，以及助力。",
            ["ContentKR"] = "그리고, 넌 그 대가로 명성과 힘을 얻게 될 거야.",
            ["DialogueId"] = 12046424,
            ["GUID"] = "1E282E70",
            ["NextDialogue"] = 12046425,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282E70",
            },
        [12046425] = {
            ["Content"] = "华胥已被神明护佑近千年，一旦龙神陨落，必将群龙无首。这时候，需要一个人走出来鼓舞他们，将人心重新凝聚起来。这个英雄，就是你。",
            ["ContentKR"] = "화서는 거의 천 년 가까이 신의 보호를 받아왔으니, 용신이 사라지면, 반드시 혼란에 빠질 거야. 그때, 흩어진 민심을 하나로 모을 구심점이 필요해. 네가 바로 그 영웅이 되는 거지.",
            ["DialogueId"] = 12046425,
            ["GUID"] = "1E282E9A",
            ["NextDialogue"] = 12046426,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282E9A",
            },
        [12046426] = {
            ["Content"] = "届时，英雄的名声能带来莫大的助力。这样的报酬，你满意吗？",
            ["ContentKR"] = "영웅이라는 명성은 엄청난 힘이 되어줄 거야. 어때, 이 정도 보상이면 마음에 드니?",
            ["DialogueId"] = 12046426,
            ["GUID"] = "1E282EC4",
            ["NextDialogue"] = 12046427,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282EC4",
            },
        [12046427] = {
            ["Content"] = "止流掌柜，你恐怕弄错了什么。",
            ["ContentKR"] = "지류 사장님, 뭔가 단단히 착각하신 모양인데요.",
            ["DialogueId"] = 12046427,
            ["GUID"] = "1E282EEE",
            ["NextDialogue"] = 12046428,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282EEE",
            },
        [12046428] = {
            ["Content"] = "你利用我、强迫我，确实使我愤怒。但这并不意味着我愿意看着任何一个人死去。",
            ["ContentKR"] = "당신이 절 속이고, 멋대로 이용한 건 화가 나요. 하지만 그렇다고 당신이 죽는 걸 보고 싶진 않아요.",
            ["DialogueId"] = 12046428,
            ["GUID"] = "1E282F18",
            ["NextDialogue"] = 12046429,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282F18",
            },
        [12046429] = {
            ["Content"] = "我们刚见面时，你问过我，究竟有什么值得用性命去衡量。你明明恐惧着死亡……又为何能如此轻易地献祭自己的生命。",
            ["ContentKR"] = "우리가 처음 만났을 때, 저한테 물었었죠? 목숨을 걸 만한 가치가 있는 게 뭐냐고요. 죽는 걸 그렇게 두려워했으면서... 왜 지금은 그렇게 쉽게 자기 목숨을 버리려고 해요?",
            ["DialogueId"] = 12046429,
            ["GUID"] = "1E282F42",
            ["NextDialogue"] = 12046430,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282F42",
            },
        [12046430] = {
            ["Content"] = "……那只是随口一提，你却当真了。",
            ["ContentKR"] = "...그냥 해 본 소리였는데, 그걸 곧이곧대로 믿었구나.",
            ["DialogueId"] = 12046430,
            ["GUID"] = "1E282F6C",
            ["NextDialogue"] = 12046431,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282F6C",
            },
        [12046431] = {
            ["Content"] = "为了达成既定的结局，这一切牺牲都是必须的。你愿或不愿，都别无选择。",
            ["ContentKR"] = "이건 정해진 결말에 도달하기 위해, 반드시 필요한 희생이야. 너한테 선택지는 없어.",
            ["DialogueId"] = 12046431,
            ["GUID"] = "1E282F96",
            ["NextDialogue"] = 12046432,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282F96",
            },
        }
  end },
  { MinKey = 12046432, MaxKey = 12048202, Loader = function()
      return {
        [12046432] = {
            ["Content"] = "若是我不死去，失控的太皓、烛阴将使华胥彻底陷入混乱。{nickname}，我只能寄希望于你去完成这最后一举。",
            ["ContentKR"] = "내가 죽지 않으면, 통제를 잃은 태호와 촉룡이 화서를 혼돈에 빠뜨릴 거야. 그러니까 {nickname}, 난 네가 이 마지막 한 수를 완성해 주길 바라.",
            ["DialogueId"] = 12046432,
            ["GUID"] = "1E282FC0",
            ["NextDialogue"] = 12046433,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282FC0",
            },
        [12046433] = {
            ["Content"] = "倘若有任何后果或是骂名，都由我来背负……这样便好。",
            ["ContentKR"] = "결과가 어떻든, 세상의 모든 비난은 내가 짊어지고 갈게... 그러면 돼.",
