            ["GUID"] = "1E282FEA",
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282FEA",
            },
        [12046501] = {
            ["Content"] = "烛阴的气息……是谁任由污秽沾染这神圣之地？",
            ["ContentKR"] = "촉룡의 기운이군... 누가 감히 이 신성한 곳을 더럽히려 하는 거지?",
            ["DialogueId"] = 12046501,
            ["GUID"] = "1E283B12",
            ["NextDialogue"] = 12046502,
            ["RelatedWikiId"] = {
                [1] = 203001,
