            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319AD0",
            },
        [12061129] = {
            ["Content"] = "离下午的赛事还有一段时间，我想研究一下姑姑的遗物，看看能不能获得什么有用的信息。",
            ["ContentKR"] = "오후 경기까지 시간이 남았으니까, 난 고모 유품 좀 살펴볼게. 어쩌면 단서를 발견할 수 있을지도 몰라.",
            ["DialogueId"] = 12061129,
            ["GUID"] = "1E319AFA",
            ["NextDialogue"] = 12061130,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319AFA",
            },
        [12061130] = {
            ["Content"] = "反正我的钱包也在你手里了……但你们别吃太多了，影响下午的比赛状态，听到了吗？",
            ["ContentKR"] = "내 지갑은 어차피 네가 가지고 있으니까, 돈은 알아서 내... 오후에 지장 없게, 너무 많이 먹진 말고, 알았지?",
            ["DialogueId"] = 12061130,
            ["GUID"] = "1E319B24",
            ["NextDialogue"] = 12061131,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319B24",
            },
        [12061131] = {
            ["Content"] = "知——道——啦——苏乙妈妈！",
            ["ContentKR"] = "알~겠~어~요~ 엄마!",
            ["DialogueId"] = 12061131,
