        [12061134] = {
            ["DialogueId"] = 12061134,
            ["GUID"] = "1E319BCC",
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319BCC",
            },
        [12061135] = {
            ["Content"] = "地狱辣挑战火热进行中——能吃完这碗担担面的挑战者，不仅能够免单，还将获得本店专门准备的豪华大礼！",
            ["ContentKR"] = "'지옥의 불짬뽕'에 도전해 보세요! 한 그릇 싹 비우시면 공짜입니다! 특별 상품까지 드려요!",
            ["DialogueId"] = 12061135,
