            ["SpeakNpcId"] = 250031,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319BF6",
            },
        [12061136] = {
            ["Content"] = "豪华大礼？",
            ["ContentKR"] = "특별 상품?",
            ["DialogueId"] = 12061136,
            ["GUID"] = "1E319C20",
            ["NextDialogue"] = 12061137,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319C20",
            },
        [12061137] = {
            ["Content"] = "嘻嘻，说出口的事情可不能再反悔，算上我一个！",
            ["ContentKR"] = "히힛, 나중에 다른 말 하기 없기다? 나, 그거 한 그릇 줘!",
