            ["NextDialogue"] = 12061138,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319C4A",
            },
        [12061138] = {
            ["Content"] = "好嘞！这就给您端上来！",
            ["ContentKR"] = "옙! 지금 바로 대령하죠!",
            ["DialogueId"] = 12061138,
            ["GUID"] = "1E319C74",
