            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319C74",
            },
        [12061201] = {
            ["Content"] = "一个小时后，奉香群英试报名处。",
            ["ContentKR"] = "1시간 후, 봉향 영웅대회 접수처.",
            ["DialogueId"] = 12061201,
            ["GUID"] = "1E31A6CA",
