            ["NextDialogue"] = 12063405,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120634/1E331038",
            },
        [12063405] = {
            ["Content"] = "塔比瑟，煜明，到时候只能交给你们咯？",
