            ["GUID"] = "1E33110A",
            ["NextDialogue"] = 12063410,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120634/1E33110A",
            },
        [12063410] = {
            ["Content"] = "等一下……止流的意思，莫非是……",
