            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120634/1E331134",
            },
        [12063411] = {
            ["Content"] = "狩月逐香队，经过司事会的综合评判，你们已经正式赢得本届奉香群英试的优胜，登上执律阁尽情庆祝吧，你们的胜利毋庸置疑。",
            ["ContentKR"] = "진행 위원회의 종합 심사 결과, 이번 대회의 최종 우승자는 월향 사냥꾼 팀이에요. 집률각 위에서 승리의 기쁨을 만끽하도록 해요.",
            ["DialogueId"] = 12063411,
            ["GUID"] = "1E33115E",
            ["NextDialogue"] = 12063412,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120634/1E33115E",
            },
        [12063412] = {
            ["Content"] = "我们赢了？！",
            ["ContentKR"] = "우리가 1등이야?!",
            ["DialogueId"] = 12063412,
            ["GUID"] = "1E331188",
            ["NextDialogue"] = 12063413,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120634/1E331188",
            },
        [12063413] = {
            ["Content"] = "嗯，我们赢了，苏乙……苏乙？",
            ["ContentKR"] = "응, 우리가 1등이래! 소을... 어?",
            ["DialogueId"] = 12063413,
            ["GUID"] = "1E3311B2",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120634/1E3311B2",
            },
        [12063414] = {
            ["Content"] = "找到了，原来她在那里。",
            ["ContentKR"] = "찾았다. 저기 있었네.",
            ["DialogueId"] = 12063414,
            ["GUID"] = "1E3311DC",
            ["NextDialogue"] = 12063415,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120634/1E3311DC",
            },
        [12063415] = {
            ["Content"] = "旁边的那是……潇湘？",
            ["ContentKR"] = "옆에 있는 건... 소향?",
            ["DialogueId"] = 12063415,
            ["GUID"] = "1E331206",
            ["NextDialogue"] = 12063416,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120634/1E331206",
            },
        [12063416] = {
            ["Content"] = "不知道她们会聊些什么，过去看看吧。",
            ["ContentKR"] = "둘이 무슨 얘기를 하는지 가서 들어보자.",
            ["DialogueId"] = 12063416,
            ["GUID"] = "1E331230",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120634/1E331230",
            },
        [12063501] = {
            ["Content"] = "请等一等，让我和她单独聊聊，可以吗？",
            ["ContentKR"] = "잠깐만요, 저 사람하고 단둘이 얘기하게 해 주실래요?",
            ["DialogueId"] = 12063501,
            ["GUID"] = "1E332022",
            ["NextDialogue"] = 12063502,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 203014,
                [3] = 103001,
                [4] = 407008,
                },
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E332022",
            },
        [12063502] = {
            ["Content"] = "苏乙姑娘是吧，龙渊上卿已有交代，不过还请您注意时间。",
            ["ContentKR"] = "소을 소저시군요. 용연상경님께 말씀 들었습니다만, 되도록 짧게 부탁드립니다.",
            ["DialogueId"] = 12063502,
            ["GUID"] = "1E33204C",
            ["NextDialogue"] = 12063503,
            ["SpeakNpcId"] = 250027,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E33204C",
            },
        [12063503] = {
            ["Content"] = "多谢。",
            ["ContentKR"] = "감사해요.",
            ["DialogueId"] = 12063503,
            ["GUID"] = "1E332076",
            ["NextDialogue"] = 12063504,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E332076",
            },
        [12063504] = {
            ["Content"] = "是专程来嘲讽你的手下败将的吗，苏氏传人？",
            ["ContentKR"] = "패배자를 비웃으러 왔나 봐, 소씨 가문의 후계자 아가씨?",
            ["DialogueId"] = 12063504,
            ["GUID"] = "1E3320A0",
            ["NextDialogue"] = 12063505,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E3320A0",
            },
        [12063505] = {
            ["Content"] = "不，我是来向你道谢的……",
            ["ContentKR"] = "아니요, 고맙다는 인사 하러 온 거예요...",
            ["DialogueId"] = 12063505,
            ["GUID"] = "1E3320CA",
            ["NextDialogue"] = 12063506,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E3320CA",
            },
        [12063506] = {
            ["Content"] = "谢谢你那个时候愿意把钥匙交出来，为我们争取了宝贵的救援时间。",
            ["ContentKR"] = "그때 열쇠 줘서 고마워요. 덕분에 제때 동료를 구할 수 있었어요.",
            ["DialogueId"] = 12063506,
            ["GUID"] = "1E3320F4",
            ["NextDialogue"] = 12063507,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E3320F4",
            },
        [12063507] = {
            ["Content"] = "别自作多情了，我这么做只是为了小安。仅此而已。",
            ["ContentKR"] = "착각하지 마. 재안이 때문에 그런 거니까. 다른 이유는 없어.",
            ["DialogueId"] = 12063507,
            ["GUID"] = "1E33211E",
            ["NextDialogue"] = 12063508,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E33211E",
            },
        [12063508] = {
            ["Content"] = "而且，这不代表我原谅了昔日种种，给我记住。",
            ["ContentKR"] = "그리고, 이걸로 내가 과거 일을 용서했다고 생각하면 오산이야. 명심해.",
            ["DialogueId"] = 12063508,
            ["GUID"] = "1E332148",
            ["NextDialogue"] = 12063509,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E332148",
            },
        [12063509] = {
            ["Content"] = "嗯，我知道。",
            ["ContentKR"] = "네, 알아요.",
            ["DialogueId"] = 12063509,
            ["GUID"] = "1E332172",
            ["NextDialogue"] = 12063510,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E332172",
            },
        [12063510] = {
            ["Content"] = "不管你怎么说，你愿意踏出这一步……我很高兴。",
            ["ContentKR"] = "어쨌든, 당신이 변하려고 해 줬다는 것만으로도... 기뻐요.",
            ["DialogueId"] = 12063510,
            ["GUID"] = "1E33219C",
            ["NextDialogue"] = 12063511,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E33219C",
            },
        [12063511] = {
            ["Content"] = "我曾经无数次想过，为何机枢派妄受非议，为何飘零人心生叛逆，为何大风九章如此蛮横强硬，为什么人们时常无法理解彼此……",
            ["ContentKR"] = "한때 수백 번도 더 생각했어요. 기추파는 왜 비난받고, 나그네는 왜 반항하고, 대풍구장은 왜 강압적으로 억누르기만 하는지, 그리고 사람들은 왜 서로를 이해하지 못하는지...",
            ["DialogueId"] = 12063511,
            ["GUID"] = "1E3321C6",
            ["NextDialogue"] = 12063512,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E3321C6",
            },
        [12063512] = {
            ["Content"] = "只可惜，无论再怎么懂得机枢工造，被旁人称作天才，我也只不过是数千年的历史中，一个再普通不过的庸人罢了。",
            ["ContentKR"] = "근데 제가 기추 쪽으론 아무리 천재라고 칭찬받아도, 수천 년의 역사 속에서 보면, 그냥 평범하기 짝이 없는 사람이잖아요.",
            ["DialogueId"] = 12063512,
            ["GUID"] = "1E3321F0",
            ["NextDialogue"] = 12063513,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E3321F0",
            },
        [12063513] = {
            ["Content"] = "我想不明白这个问题的答案，也不知道如何才能根绝纷争。曾经的悬衡派为了消灭纷争封印烛阴，但这片土地并没有因此变得更好。",
            ["ContentKR"] = "생각해 봐야, 문제의 답도 모르겠고, 해결법도 모르겠더라고요. 현형파도 분쟁을 없애려고 촉룡을 봉인했다지만, 그렇다고 이 세상이 더 좋아지진 않았죠.",
            ["DialogueId"] = 12063513,
            ["GUID"] = "1E33221A",
            ["NextDialogue"] = 12063514,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E33221A",
            },
        [12063514] = {
            ["Content"] = "我想，人与人终究是想法不同的，即使烛阴之灾结束，大风九章重启，人们也还是会因为各种各样的原因争论，冲突……",
            ["ContentKR"] = "사람의 마음이 다 같은 순 없으니까, 촉룡의 재앙이 끝나고, 대풍구장의 개혁이 끝나도, 사람은 또 다른 이유로 끝없이 부딪힐 거예요...",
            ["DialogueId"] = 12063514,
            ["GUID"] = "1E332244",
            ["NextDialogue"] = 12063515,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E332244",
            },
        [12063515] = {
            ["Content"] = "我所能做的，也就只是倾尽我的所有，试着去治愈曾经的冲突所造成的伤痛。",
            ["ContentKR"] = "그러니까 제가 할 수 있는 건, 그냥 있는 힘껏 그 상처들을 보듬어 보려고 애쓰는 것뿐이에요.",
            ["DialogueId"] = 12063515,
            ["GUID"] = "1E33226E",
            ["NextDialogue"] = 12063516,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E33226E",
            },
        [12063516] = {
            ["Content"] = "弥合些皮肉之伤罢了。",
            ["ContentKR"] = "고작 겉에 난 상처나 꿰매 주는 수준이겠지.",
            ["DialogueId"] = 12063516,
            ["GUID"] = "1E332298",
            ["NextDialogue"] = 12063517,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E332298",
            },
        [12063517] = {
            ["Content"] = "嗯，但这就是我眼下能够做到的事。",
            ["ContentKR"] = "네, 그게 바로 지금 제가 할 수 있는 일이니까요.",
            ["DialogueId"] = 12063517,
            ["GUID"] = "1E3322C2",
            ["NextDialogue"] = 12063518,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E3322C2",
            },
        [12063518] = {
            ["Content"] = "在那之后，我也会竭尽所能，让你与我经历的事不再上演。",
            ["ContentKR"] = "그리고, 전 우리가 겪은 비극이 되풀이되지 않게 최선을 다할 거예요.",
            ["DialogueId"] = 12063518,
            ["GUID"] = "1E3322EC",
            ["NextDialogue"] = 12063519,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E3322EC",
            },
        [12063519] = {
            ["Content"] = "就凭你？",
            ["ContentKR"] = "너 혼자 무슨 수로?",
            ["DialogueId"] = 12063519,
            ["GUID"] = "1E332316",
            ["NextDialogue"] = 12063520,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E332316",
            },
        [12063520] = {
            ["Content"] = "还有你，还有所有为了这个目标一同努力的人，就像千百年来，一直尝试着改变大风九章的人们一样。",
            ["ContentKR"] = "당신과 나, 그리고 우리랑 같은 목표를 가진 사람들도 함께할 거예요. 대풍구장을 바꾸기 위해 오랫동안 애써온 선조들처럼 말이에요.",
            ["DialogueId"] = 12063520,
            ["GUID"] = "1E332340",
            ["NextDialogue"] = 12063521,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E332340",
            },
        [12063521] = {
            ["Content"] = "现在，他们已经成功了，该轮到我们了。",
            ["ContentKR"] = "선조들은 대풍구장을 바꾸는 데 성공했잖아요. 그럼 이제 우리 차례죠.",
            ["DialogueId"] = 12063521,
            ["GUID"] = "1E33236A",
            ["NextDialogue"] = 12063522,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E33236A",
            },
        [12063522] = {
            ["Content"] = "无论如何，你放弃了你们的计划，阻止了那台失控的机关巨阙。你还有我，我们已经共同踏出了第一步。",
            ["ContentKR"] = "어쨌든, 당신은 원래 계획을 포기하고 폭주하는 거궐을 멈췄어요. 저 말고 당신도, 이미 첫걸음을 뗀 거죠.",
            ["DialogueId"] = 12063522,
            ["GUID"] = "1E332394",
            ["NextDialogue"] = 12063523,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E332394",
            },
        [12063523] = {
            ["Content"] = "也许我们也会成为不靠谱的前辈，只能把写了一半的答卷留给后人，甚至已经写好的部分也有可能是错误答案……",
            ["ContentKR"] = "어쩌면 우리는 반쪽짜리 답이나, 틀린 답만 잔뜩 남겨 주는 못 미더운 선조가 될 수도 있겠죠...",
            ["DialogueId"] = 12063523,
            ["GUID"] = "1E3323BE",
            ["NextDialogue"] = 12063524,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E3323BE",
            },
        [12063524] = {
            ["Content"] = "但我相信，我们一定可以离那个未来更近一些，再近一些……一步一步。",
            ["ContentKR"] = "그래도 전 믿어요. 우린 우리가 바라는 미래에 조금씩, 천천히... 다가갈 수 있을 거예요.",
            ["DialogueId"] = 12063524,
            ["GUID"] = "1E3323E8",
            ["NextDialogue"] = 12063525,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E3323E8",
            },
        [12063525] = {
            ["Content"] = "……天真，甚至近乎愚昧。",
            ["ContentKR"] = "...멍청할 정도로 순진하구나.",
            ["DialogueId"] = 12063525,
            ["GUID"] = "1E332412",
            ["NextDialogue"] = 12063526,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E332412",
            },
        [12063526] = {
            ["Content"] = "时间差不多了，该上路了。",
            ["ContentKR"] = "시간 다 됐습니다. 가시죠.",
            ["DialogueId"] = 12063526,
            ["GUID"] = "1E33243C",
            ["NextDialogue"] = 12063527,
            ["SpeakNpcId"] = 250027,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E33243C",
            },
        [12063527] = {
            ["Content"] = "即便身为阶下之囚，我也会一直看着你……",
            ["ContentKR"] = "이젠 죄인 신세지만, 계속 널 지켜볼 거야...",
            ["DialogueId"] = 12063527,
            ["GUID"] = "1E332466",
            ["NextDialogue"] = 12063528,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E332466",
            },
        [12063528] = {
            ["Content"] = "别让我看笑话，苏氏传人。",
            ["ContentKR"] = "나한테 망신당하지 않게 잘해봐, 소씨 가문의 후계자.",
            ["DialogueId"] = 12063528,
            ["GUID"] = "1E332490",
            ["NextDialogue"] = 12063529,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E332490",
            },
        [12063529] = {
            ["Content"] = "{nickname}，谢谢你一直指引我走到这一步。",
            ["ContentKR"] = "고마워, {nickname}. 네가 없었으면, 난 여전히 제자리걸음이었을 거야.",
            ["DialogueId"] = 12063529,
            ["GUID"] = "1E3324BA",
            ["NextDialogue"] = 12063530,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E3324BA",
            },
        [12063530] = {
            ["Content"] = "我并没有做什么。",
            ["ContentKR"] = "난 딱히 한 게 없는걸.(고개를 저으며)",
            ["DialogueId"] = 12063530,
            ["GUID"] = "1E3324E4",
            ["NextDialogue"] = 12063531,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E3324E4",
            },
        [12063531] = {
            ["Content"] = "真要说我有帮上什么忙，大概只是见证你用自己的意志一步一步走到这里吧。",
            ["ContentKR"] = "한 게 있다면, 네가 자신의 의지로 여기까지 오는 걸 지켜본 게 다겠네.",
            ["DialogueId"] = 12063531,
            ["GUID"] = "1E33250E",
            ["NextDialogue"] = 12063532,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E33250E",
            },
        [12063532] = {
            ["Content"] = "既然这样，那就见证我直到今天的最后一刻吧。",
            ["ContentKR"] = "그럼 오늘 하루가 끝날 때까지, 계속 날 지켜봐 줘야 해!(장난스러운 표정)",
            ["DialogueId"] = 12063532,
            ["GUID"] = "1E332538",
            ["NextDialogue"] = 12063533,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E332538",
            },
        [12063533] = {
            ["Content"] = "走吧，一起去执律阁，享受属于我们的胜利时刻！",
            ["ContentKR"] = "가자, 집률각에서 우리의 승리를 축하해야지!",
            ["DialogueId"] = 12063533,
            ["GUID"] = "1E332562",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E332562",
            },
        [12063534] = {
            ["Content"] = "准备好了吗？",
            ["ContentKR"] = "준비됐어?",
            ["DialogueId"] = 12063534,
            ["GUID"] = "1E33258C",
            ["NextDialogue"] = 12063535,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E33258C",
            },
        [12063535] = {
            ["Content"] = "嗯。",
            ["ContentKR"] = "응!",
            ["DialogueId"] = 12063535,
            ["GUID"] = "1E3325B6",
            ["NextDialogue"] = 12063536,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E3325B6",
            },
        [12063536] = {
            ["Content"] = "昊天苍苍，玄水泱泱。",
            ["ContentKR"] = "드넓은 하늘과 아득한 물결이여,",
            ["DialogueId"] = 12063536,
            ["GUID"] = "1E3325E0",
            ["NextDialogue"] = 12063537,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E3325E0",
            },
        [12063537] = {
            ["Content"] = "华胥承祀，爰奉馨香。",
            ["ContentKR"] = "화서에서 예를 갖춰, 맑은 향 올리나이다.",
            ["DialogueId"] = 12063537,
            ["GUID"] = "1E33260A",
            ["NextDialogue"] = 12063538,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E33260A",
            },
        [12063538] = {
            ["Content"] = "润其五谷，泽彼田桑。",
            ["ContentKR"] = "오곡에 단비를 내리시고,",
            ["DialogueId"] = 12063538,
            ["GUID"] = "1E332634",
            ["NextDialogue"] = 12063539,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E332634",
            },
        [12063539] = {
            ["Content"] = "禔福兆民，惠汲四方。",
            ["ContentKR"] = "만백성에게 은택을 베푸시어",
            ["DialogueId"] = 12063539,
            ["GUID"] = "1E33265E",
            ["NextDialogue"] = 12063540,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E33265E",
            },
        [12063540] = {
            ["Content"] = "永锡丰年，以宁万邦。",
            ["ContentKR"] = "영원한 풍요와 태평성대를 누리게 하소서.",
            ["DialogueId"] = 12063540,
            ["GUID"] = "1E332688",
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E332688",
            },
        [12063601] = {
            ["Content"] = "每个人的力量都是如此渺小，或许往后数十载，人们仍会对飘零人心生畏惧。",
            ["ContentKR"] = "사람의 힘은 참 보잘것없어서, 수십 년이 지나도, 사람들은 여전히 나그네를 두려워할지도 몰라.(독백)",
            ["DialogueId"] = 12063601,
            ["GUID"] = "1E33308A",
            ["NextDialogue"] = 12063602,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120636/1E33308A",
            },
        [12063602] = {
            ["Content"] = "或许即便付出一切，直至行将就木，我也无法见到人们彻底摒弃往日恩怨齐心协力的那一日。",
            ["ContentKR"] = "어쩌면 평생 노력해도, 사람들 사이의 해묵은 원한이 사라지는 날은 오지 않을 수도 있어.(독백)",
            ["DialogueId"] = 12063602,
            ["GUID"] = "1E3330B4",
            ["NextDialogue"] = 12063603,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120636/1E3330B4",
            },
        [12063603] = {
            ["Content"] = "姐姐，那个机关鸟儿是怎么飞起来的呀？",
            ["ContentKR"] = "언니, 저 기계 새는 어떻게 하늘을 나는 거야?",
            ["DialogueId"] = 12063603,
            ["GUID"] = "1E3330DE",
            ["NextDialogue"] = 12063604,
            ["SpeakNpcId"] = 250025,
            ["VoiceName"] = "voice/$Locale$/story/1206/120636/1E3330DE",
            },
        [12063604] = {
            ["Content"] = "但，我已经走上了这条道路。还有很多人，与我一起走上了这条道路——纵使星火黯然，改变也已然到来。",
            ["ContentKR"] = "하지만, 난 이미 이 길을 걷기 시작했어. 그리고 많은 사람이 나와 함께 이 길을 걸어 주고 있으니까—— 희미할지라도, 변화의 바람은 불기 시작한 거야.(독백)",
            ["DialogueId"] = 12063604,
            ["GUID"] = "1E333108",
            ["NextDialogue"] = 12063605,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120636/1E333108",
            },
        [12063605] = {
            ["Content"] = "你看到了吗，姑姑？",
            ["ContentKR"] = "지켜보고 있는 거지, 고모?(독백)",
            ["DialogueId"] = 12063605,
            ["GUID"] = "1E333132",
            ["NextDialogue"] = 12063606,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120636/1E333132",
            },
        [12063606] = {
            ["Content"] = "小妹妹，想学吗？",
            ["ContentKR"] = "꼬마야, 너도 만들어 보고 싶어?",
            ["DialogueId"] = 12063606,
            ["GUID"] = "1E33315C",
            ["NextDialogue"] = 12063607,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120636/1E33315C",
            },
        [12063607] = {
            ["Content"] = "——那便来当姐姐的第一个“学生”，好不好？",
            ["ContentKR"] = "...그러면, 언니의 첫 번째 '제자'가 돼 볼래?",
            ["DialogueId"] = 12063607,
            ["GUID"] = "1E333186",
            ["VoiceName"] = "voice/$Locale$/story/1206/120636/1E333186",
            },
        [12063701] = {
            ["Content"] = "一日后 浮星埠",
            ["ContentKR"] = "1일 후, 별빛 부두",
            ["DialogueId"] = 12063701,
            ["GUID"] = "1E3340F2",
            ["NextDialogue"] = 12063702,
            ["VoiceName"] = "voice/$Locale$/story/1206/120637/1E3340F2",
            },
        [12063702] = {
            ["Content"] = "小仆从，这次我们是真的要离开华胥了吧？",
            ["ContentKR"] = "시종, 우리 이번엔 진짜 화서 떠나는 거 맞지?",
            ["DialogueId"] = 12063702,
            ["GUID"] = "1E33411C",
            ["NextDialogue"] = 12063703,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120637/1E33411C",
            },
        [12063703] = {
            ["Content"] = "这么平平淡淡，没有波折，没有陷阱，没有奇怪的人突然冒出来阻止我们，还有点不习惯呢……",
            ["ContentKR"] = "너무 평화로운데? 사고도 안 터지고, 함정도 없고, 이상한 방해꾼도 안 나타나잖아. 뭔가 허전해...",
            ["DialogueId"] = 12063703,
            ["GUID"] = "1E334146",
            ["NextDialogue"] = 12063704,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120637/1E334146",
            },
        [12063704] = {
            ["Content"] = "呵呵……怎么，需要我扮演“奇怪的人”再来热情好客地阻拦一下你们的归程吗？",
            ["ContentKR"] = "후후... '이상한 방해꾼'이 필요한 거야? 그럼 너희가 못 돌아가도록, 내가 열정적으로 붙잡아 주면 어떨까?",
            ["DialogueId"] = 12063704,
            ["GUID"] = "1E334170",
            ["NextOptions"] = {
                [1] = 12063705,
                },
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120637/1E334170",
            },
        [12063705] = {
            ["Content"] = "白，闭嘴！",
            ["ContentKR"] = "스노우, 그 입...!",
            ["DialogueId"] = 12063705,
            ["GUID"] = "1E33419A",
            ["NextDialogue"] = 12063706,
            },
        [12063706] = {
            ["Content"] = "不不不不还是不用了！",
            ["ContentKR"] = "돼, 돼, 돼, 됐어! 사양할게!",
            ["DialogueId"] = 12063706,
            ["GUID"] = "1E3341C4",
            ["NextDialogue"] = 12063707,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120637/1E3341C4",
            },
        [12063707] = {
            ["Content"] = "白，{nickname}——",
            ["ContentKR"] = "스노우, {nickname}——",
            ["DialogueId"] = 12063707,
            ["GUID"] = "1E3341EE",
            ["NextDialogue"] = 12063708,
            ["VoiceName"] = "voice/$Locale$/story/1206/120637/1E3341EE",
            },
        [12063708] = {
            ["Content"] = "你们……怎么都来了？",
            ["ContentKR"] = "어? 다들 왜 여기 나와 있어...?",
            ["DialogueId"] = 12063708,
            ["GUID"] = "1E334218",
            ["NextDialogue"] = 12063709,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120637/1E334218",
            },
        [12063709] = {
            ["Content"] = "自然是来送别你了！要是你回到那个叫冰湖城的地方被人欺负了，给我写封信，兄弟我不远千里也要来两肋插刀，帮你打架！",
            ["ContentKR"] = "당연히 배웅 나온 거 아니냐! 아이스레이크 시틴지 뭔지에서 누가 괴롭히거든, 바로 편지를 띄워라. 내가 끝까지 쫓아가서 혼쭐을 내주마!",
            ["DialogueId"] = 12063709,
            ["GUID"] = "1E334242",
            ["NextDialogue"] = 12063710,
            ["SpeakNpcId"] = 250002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120637/1E334242",
            },
        [12063710] = {
            ["Content"] = "{nickname}，你要走了吗？保重。愿你平安无虞。但若是不慎有了伤痛，扶疏随时愿来为你治疗。",
            ["ContentKR"] = "떠나는군요, {nickname}. 몸 건강히 잘 지내요. 늘 평안하길 바라지만, 혹시라도 아프면 언제든 찾아오세요. 치료해 줄게요.",
            ["DialogueId"] = 12063710,
            ["GUID"] = "1E33426C",
            ["NextDialogue"] = 12063711,
            ["SpeakNpcId"] = 250001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120637/1E33426C",
            },
        [12063711] = {
            ["Content"] = "此去一别，山高水远。愿君万事顺遂。",
            ["ContentKR"] = "먼 길을 떠나는군. 부디 무탈하길 바랄게.",
            ["DialogueId"] = 12063711,
            ["GUID"] = "1E334296",
            ["NextDialogue"] = 12063712,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120637/1E334296",
            },
        [12063712] = {
            ["Content"] = "……呼。昨天比赛胜利后有好多好多事情要处理，又熬了个通宵，差一点没赶过来。",
            ["ContentKR"] = "...휴, 어제 우승하고 나서 처리해야 할 게 산더미라 또 밤을 꼬박 새웠지 뭐야. 하마터면 늦을 뻔했네.",
            ["DialogueId"] = 12063712,
            ["GUID"] = "1E3342C0",
            ["NextDialogue"] = 12063713,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120637/1E3342C0",
            },
        [12063713] = {
            ["Content"] = "但是，{nickname}，有些话，我一定要当面和你说出口！",
            ["ContentKR"] = "그래도, {nickname}. 가기 전에 이 얘긴 꼭 하고 싶었어!",
            ["DialogueId"] = 12063713,
            ["GUID"] = "1E3342EA",
            ["NextDialogue"] = 12063714,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120637/1E3342EA",
            },
        [12063714] = {
            ["Content"] = "谢谢你帮助我认清了自己真正想要做的事情……谢谢你！你一定也有不顾一切都想做的事情吧，你一定能做到的！",
            ["ContentKR"] = "내가 진짜 가고 싶었던 길을 찾을 수 있게 도와줘서 고마워... 진심이야! 너한테도 꼭 하고 싶은 일이 있겠지. 너라면 해낼 수 있을 거야!",
            ["DialogueId"] = 12063714,
            ["GUID"] = "1E334314",
            ["NextDialogue"] = 12063715,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120637/1E334314",
            },
        [12063715] = {
            ["Content"] = "多写信回来——还有，不要忘了大家！",
            ["ContentKR"] = "편지 자주 보내줘! 그리고! 우리 절대 잊어 버리면 안 돼!",
            ["DialogueId"] = 12063715,
            ["GUID"] = "1E33433E",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120637/1E33433E",
            },
        [12063801] = {
            ["Content"] = "扫描完成……正在建立追踪路径……",
            ["ContentKR"] = "스캔 완료... 추적 경로를 생성 중입니다...",
            ["DialogueId"] = 12063801,
            ["GUID"] = "1E33515A",
            ["NextDialogue"] = 12063802,
            ["SnapShot"] = "ROBOT",
            ["SpeakNpcName"] = "UI_Npc_Name_Qingluan",
            ["VoiceName"] = "voice/$Locale$/story/1206/120638/1E33515A",
            },
        [12063802] = {
            ["Content"] = "来，跟上青鸾贰型，它会为我们指明潇湘藏身的位置！",
            ["ContentKR"] = "자! 난새 2호를 따라가자! 소향이 숨어 있는 위치를 알려 줄 거야!",
            ["DialogueId"] = 12063802,
            ["GUID"] = "1E335184",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120638/1E335184",
            },
        [20000401] = {
            ["Content"] = "喂。",
            ["ContentKR"] = "어이.",
            ["DialogueId"] = 20000401,
            ["Duration"] = 3,
            ["GUID"] = "3211A3CA",
            ["NextDialogue"] = 20000402,
            ["SpeakNpcId"] = 200024,
            ["VoiceName"] = "voice/$Locale$/story/2001/200004/3211A3CA",
            },
        [20000402] = {
            ["Content"] = "我说，那边的年轻人……",
            ["ContentKR"] = "거기, 젊은이...",
            ["DialogueId"] = 20000402,
            ["Duration"] = 3,
            ["GUID"] = "3211A3CB",
            ["SpeakNpcId"] = 200024,
            ["VoiceName"] = "voice/$Locale$/story/2001/200004/3211A3CB",
            },
