            },
        [20000838] = {
            ["Camera"] = "-99.587891,5.36792,111.048828,0.000001,1.399991,-66.58712,22.803864,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "土壤？",
            ["ContentKR"] = "흙?",
            ["DialogueId"] = 20000838,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "3211EB7C",
            ["LookAt"] = {
                [1] = "100001:n(200027)",
