            },
        [20004301] = {
            ["Camera"] = "101.757812,-139.77832,28.292236,0.000069,0.600367,129.191574,12.5,133.732285,false,DoNotOverride,2.0",
            ["DialogueId"] = 20004301,
            ["GUID"] = "321423A2",
            },
        [20004501] = {
            ["Content"] = "我最亲爱的孩子，谢谢你来到世界上。",
            ["ContentKR"] = "세상에서 가장 사랑하는 아가, 이 세상에 태어나줘서 고마워. ",
            ["DialogueId"] = 20004501,
            ["Duration"] = 4,
            ["GUID"] = "32144472",
            ["NextDialogue"] = 20004502,
            ["SnapShot"] = "HEART",
            ["VoiceName"] = "voice/$Locale$/story/1002/200045/1950CA87",
            },
        [20004502] = {
            ["Content"] = "你是我们一生的骄傲。",
            ["ContentKR"] = "넌 우리 인생 최고의 자랑이란다. ",
            ["DialogueId"] = 20004502,
            ["Duration"] = 3,
            ["GUID"] = "3214449C",
            ["NextDialogue"] = 20004503,
            ["SnapShot"] = "HEART",
            ["VoiceName"] = "voice/$Locale$/story/1002/200045/1950CA88",
            },
        [20004503] = {
            ["Content"] = "赛琪，来拉钩，我们要做一辈子的好朋友！",
            ["ContentKR"] = "프시케, 자, 약속! 이제 우리는 영원한 친구야!",
            ["DialogueId"] = 20004503,
            ["Duration"] = 5,
            ["GUID"] = "321444C6",
            ["NextDialogue"] = 20004504,
            ["SnapShot"] = "HEART",
            ["VoiceName"] = "voice/$Locale$/story/1002/200045/1950CA89",
            },
        [20004504] = {
            ["Content"] = "我会记住你曾经活过。",
            ["ContentKR"] = "네가 살아있었음을 기억할게. ",
            ["DialogueId"] = 20004504,
            ["Duration"] = 3,
            ["GUID"] = "321444F0",
            ["NextDialogue"] = 20004505,
            ["SnapShot"] = "HEART",
            ["VoiceName"] = "voice/$Locale$/story/1002/200045/1950CA90",
            },
        [20004505] = {
            ["Content"] = "我们等你回来。",
            ["ContentKR"] = "우리가 널 기다리고 있어. ",
            ["DialogueId"] = 20004505,
            ["Duration"] = 3,
            ["GUID"] = "3214451A",
            ["NextDialogue"] = 20004506,
            ["SnapShot"] = "HEART",
            ["VoiceName"] = "voice/$Locale$/story/1002/200045/1950CA91",
            },
        [20004506] = {
            ["Content"] = "命运啊，求你怜悯我唯一一次，让我帮她实现这个愿望吧。",
            ["ContentKR"] = "운명이여, 한 번이라도 자비를 베풀어 그 아이의 소원을 이뤄줄 수 있게 해 주오. ",
            ["DialogueId"] = 20004506,
            ["Duration"] = 5,
            ["GUID"] = "32144544",
            ["NextDialogue"] = 20004507,
            ["SnapShot"] = "HEART",
            ["VoiceName"] = "voice/$Locale$/story/1002/200045/1950CA92",
            },
        [20004507] = {
            ["Content"] = "带上这朵花吧，它会给你带来好运。",
            ["ContentKR"] = "이 꽃을 가져가렴, 행운을 가져다줄 거야. ",
            ["DialogueId"] = 20004507,
            ["Duration"] = 4,
            ["GUID"] = "3214456E",
            ["NextDialogue"] = 20004508,
            ["SnapShot"] = "HEART",
            ["VoiceName"] = "voice/$Locale$/story/1002/200045/1950CA93",
            },
        [20004508] = {
            ["Content"] = "你可以去一座小岛，在那里盖几间房子，在房子边种满白色的花。",
            ["ContentKR"] = "작은 섬에 가면 집 몇 채를 짓고, 집 주변에 하얀 꽃을 가득 심을 수 있어. ",
            ["DialogueId"] = 20004508,
            ["Duration"] = 5,
            ["GUID"] = "32144598",
            ["NextDialogue"] = 20004509,
            ["SnapShot"] = "HEART",
            ["VoiceName"] = "voice/$Locale$/story/1002/200045/1950CA94",
            },
        [20004509] = {
            ["Content"] = "赛琪，我来带你回家。",
            ["ContentKR"] = "프시케, 집에 가자.",
            ["DialogueId"] = 20004509,
            ["Duration"] = 3,
            ["GUID"] = "321445C2",
            ["SnapShot"] = "HEART",
            ["VoiceName"] = "voice/$Locale$/story/1002/200045/1950CA95",
            },
