            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/2001/200048/321475FE",
            },
        [20004804] = {
            ["Camera"] = "-143.963196,-59.587891,62.005508,0.000066,10.798099,-99.194954,35.0,379.954346,false,Manual,3.328919",
            ["CameraBlendCurve"] = "easeInQuad",
            ["Content"] = "可不能慢慢说！我听说，有人在冰湖城外看到了一头巨大的猪，个子比你还高，脑袋比货车还大，蹄子蹬一下，能让冰湖城的城墙倒掉！",
            ["ContentKR"] = "천천히 말할 수 없다고! 누가 아이스레이크 시티 밖에서 엄청나게 큰 돼지를 봤대! 키는 너보다도 크고, 머리는 화물차보다 더 크고, 발굽으로 한 번 차면 아이스레이크 시티의 성벽도 무너뜨릴 수 있대!",
            ["DialogueId"] = 20004804,
            ["FinalCamera"] = "-140.150818,-60.366699,62.005493,0.000062,10.798099,-101.595215,35.0,379.954346,false,Manual,3.328919",
            ["GUID"] = "32147628",
