        [20004805] = {
            ["Camera"] = "-662.342529,29.628418,112.909363,0.000096,-2.999962,-41.401596,25.0,161.861893,false,Manual,1.2",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "这算什么好事！我看你是饿迷糊了。",
            ["ContentKR"] = "그게 무슨 좋은 일이야! 배고파서 제정신이 아니네.",
            ["DialogueId"] = 20004805,
            ["FinalCamera"] = "-660.245789,32.00293,112.909363,0.000096,-2.999962,-41.401596,25.0,824.858765,false,Manual,1.2",
