            ["Scripts"] = "PARA{\
SetRotation{SetRotationDescription{\"100001:p(30)\"}},\
MoveTo{_delay{0.1},ActorId{100001},TargetPoint{\"P200048Nvzhu2\"},MoveSpeed{50},Visibility{\"Show\"}}\
}",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Bai_Circle_End",
                },
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/story/2001/200048/3214767C",
            },
        [20004807] = {
            ["Camera"] = "-992.792297,-208.039062,42.167068,0.000105,1.999995,-0.499939,32.5,507.776001,false,Manual,1.2",
            ["CameraBlendCurve"] = "easeInQuad",
            ["Content"] = "总之，我就是很好奇嘛！来吧来吧，反正我看你现在也不是很忙，和我走一趟。",
            ["ContentKR"] = "아무튼, 그냥 너무 궁금하단 말이야! 자, 가자! 어차피 지금 별로 바빠 보이지도 않는데, 나랑 한 번 다녀오자.",
            ["DialogueId"] = 20004807,
            ["FinalCamera"] = "-920.479614,-208.66748,44.692398,0.000105,1.999995,-0.499969,35.0,507.776001,false,Manual,1.2",
            ["GUID"] = "321476A6",
