            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/2001/200050/3214967A",
            },
        [20005002] = {
            ["Camera"] = "133.203125,-98.626953,72.790039,0.000065,2.99999,-114.999947,25.0,147.187317,false,Manual,1.2",
            ["Content"] = "这不是什么都没有吗？",
