            ["TalkActionId"] = {
                [1] = "100001:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200050/321496F8",
            },
        [20005005] = {
            ["Camera"] = "64.757812,-576.111328,76.646484,0.000102,-2.499965,77.999962,35.0,143.409622,false,DoNotOverride,1.2",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "诶诶别急。你看，那边也有两个人，好像待了很久了，像是在等什么的样子——说不定也在等巨大的猪，去看看吧。",
            ["ContentKR"] = "잠깐만, 잠깐만. 저기 봐, 저기 두 사람 계속 저기 있는 걸 보면 뭔가를 기다리는 것 같지 않아? 거대한 돼지를 기다리고 있을지도 몰라, 가보자.",
            ["DialogueId"] = 20005005,
