        [20005722] = {
            ["Camera"] = "345.16864,317.928711,137.46875,-0.000763,1.607089,136.417633,35.0,169,false,Manual,12.0",
            ["Content"] = "你有头绪吗？",
            ["ContentKR"] = "단서라도 있어?",
            ["DialogueId"] = 20005722,
            ["FinalCamera"] = "311.653595,331.706055,134.34375,-0.000763,4.806766,132.015808,35.0,169.08606,false,Manual,12.0",
            ["GUID"] = "32150CC4",
