        [20006002] = {
            ["Camera"] = "-38.9104,-306.495117,391.232422,0.000209,-8.45895,-1.344757,35.000015,174.116943,false,Manual,12.0",
            ["Content"] = "嗯，这附近有很多水汽，而又没什么人，肯定会有魔灵出没的。",
            ["ContentKR"] = "응, 이 근처엔 습기가 많고 사람도 별로 없어서 분명히 마령이 나타날 거야.",
            ["DialogueId"] = 20006002,
            ["FinalCamera"] = "-508.082397,-300.290039,450.730469,0.000209,-7.058932,-0.744781,35.000019,174.116943,false,Manual,12.0",
            ["GUID"] = "32153AB4",
            ["NextDialogue"] = 20006003,
            ["SpeakNpcId"] = 200074,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153AB4",
            },
        [20006003] = {
            ["Camera"] = "-768.485962,-608.558594,293.948242,0.000155,-2.058947,167.054123,35.000015,174.116943,false,Manual,12.0",
            ["Content"] = "不过，刚刚那两处地方的魔灵都被抓走了，有点担心这里也……",
            ["ContentKR"] = "하지만, 방금 그 두 곳의 마령이 모두 잡혀갔잖아. 여기도 똑같이 당했을까 봐 좀 걱정돼...",
            ["DialogueId"] = 20006003,
            ["FinalCamera"] = "-796.652222,-602.085938,292.908691,0.000155,-0.458948,167.453751,35.000015,174.116943,false,Manual,12.0",
            ["GUID"] = "32153ADE",
            ["NextDialogue"] = 20006004,
            ["SpeakNpcId"] = 200074,
            ["TalkActionId"] = {
                [1] = "200074:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153ADE",
            },
        [20006004] = {
            ["Camera"] = "-913.889771,-785.241211,282.312012,0.000156,-6.059081,28.454039,35.000015,174.116943,false,Manual,12.0",
            ["Content"] = "啊，是还没被收走的陷阱！里面还有一只魔灵！",
            ["ContentKR"] = "앗, 아직 치워지지 않은 덫이야! 안에 마령이 한 마리 갇혀 있어!",
            ["DialogueId"] = 20006004,
            ["FinalCamera"] = "-932.27832,-741.113281,282.15332,0.000157,-6.459043,18.853708,35.000015,174.116943,false,Manual,12.0",
            ["GUID"] = "32153B08",
            ["NextDialogue"] = 20006005,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200074:Think_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153B08",
            },
        [20006005] = {
            ["Camera"] = "-264.765686,-875.787109,308.994629,0.000174,-6.859033,150.453903,35.000015,733.116943,false,Manual,22.0",
            ["Content"] = "太好了，这次总算赶上了。先把它放出来，再等那些魔灵猎人出现吧。",
            ["ContentKR"] = "잘됐다! 이번엔 드디어 제때 도착했네. 먼저 마령을 풀어주고, 그다음에 그 마령 사냥꾼들이 나타나길 기다리자.",
            ["DialogueId"] = 20006005,
            ["FinalCamera"] = "-222.946228,-1021.376953,416.390625,0.000172,-15.459046,141.053696,35.000015,733.116943,false,Manual,22.0",
            ["GUID"] = "32153B32",
            ["SpeakNpcId"] = 200074,
            ["TalkActionId"] = {
                [1] = "200002:SpecialHappy_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153B32",
            },
        [20006006] = {
            ["Content"] = "一阵手忙脚乱，困在陷阱里的魔灵被救了出来，但它的态度好像……不是非常友好。",
            ["ContentKR"] = "우왕좌왕하는 사이 덫에 갇혀 있던 마령을 구해냈지만 마령의 태도가 왠지... 별로 우호적이지 않은 것 같다.",
            ["DialogueId"] = 20006006,
            ["GUID"] = "32153B5C",
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153B5C",
            },
        [20006007] = {
            ["Camera"] = "-348.273315,-725.485352,348.286133,0.000093,-9.591675,168.57576,35.0,1674.542114,false,Manual,22.0",
            ["Content"] = "别害怕了小魔灵，本魔王大人以及小跟班，还有魔灵猎人猎人是来解救你们的，现在你自由了，远离这里吧！",
            ["ContentKR"] = "무서워하지 마, 마령아. 이 마왕님과 시종, 그리고 마령 사냥꾼 사냥꾼은 너희들을 구하러 온 거야. 이제 자유야, 여기서 멀리 떠나!",
            ["DialogueId"] = 20006007,
            ["FacialId"] = {
                [1] = "200002:Confident02",
                },
            ["GUID"] = "32153B86",
            ["LookAt"] = {
                [1] = "200002:n(820000)",
                },
            ["NextDialogue"] = 20006008,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:SpecialConfident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153B86",
            },
        [20006008] = {
            ["Camera"] = "-1100.135376,-637.394531,335.55957,0.000086,-3.391571,1.375749,35.0,1674.542114,false,Manual,6.0",
            ["Content"] = "咿咿呀——",
            ["ContentKR"] = "이이야~",
            ["DialogueId"] = 20006008,
            ["GUID"] = "32153BB0",
            ["NextDialogue"] = 20006009,
            ["SpeakNpcId"] = 820000,
            ["SpeakNpcName"] = "UI_Npc_Name_PanTuokun",
            ["TalkActionId"] = {
                [1] = "200002:SpecialConfident_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153BB0",
            },
        [20006009] = {
            ["Camera"] = "-619.304932,-686.379883,266.316895,0.000167,1.568205,-159.823883,35.000019,174.116943,false,Manual,12.0",
            ["Content"] = "不必如此激动，这都是我们应该做的——话说回来，有点眼熟诶？这只魔灵是不是在冰湖城外就被我们救过一次？",
            ["ContentKR"] = "그렇게 흥분할 필요 없어, 이건 우리가 당연히 해야 할 일이니까. 그런데 뭔가 눈에 좀 익은데? 혹시 아이스레이크 시티 밖에서 우리가 한 번 구해줬던 그 마령 아니야?",
            ["DialogueId"] = 20006009,
            ["FinalCamera"] = "-646.760498,-696.469727,267.117676,0.000167,1.568205,-159.823883,35.000019,174.116943,false,Manual,12.0",
            ["GUID"] = "32153BDA",
            ["NextDialogue"] = 20006010,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153BDA",
            },
        [20006010] = {
            ["Camera"] = "-422.686035,-758.615234,323.150879,0.000171,-5.031971,158.176743,35.000019,294.116943,false,Manual,12.0",
            ["Content"] = "你们也都快回家吧，可不要再被那些魔灵猎人抓到了哦，在我能被称为真正的魔灵猎人猎人之前，你们还是要小心一点才是。",
            ["ContentKR"] = "얼른 집으로 돌아가. 마령 사냥꾼들한테 다시 잡히면 안 되잖아! 내가 진정한 마령 사냥꾼 사냥꾼이 되기 전까지는, 더욱더 조심해야 해!",
            ["DialogueId"] = 20006010,
            ["GUID"] = "32153C04",
            ["LookAt"] = {
                [1] = "200074:n(820000)",
                },
            ["NextDialogue"] = 20006011,
            ["SpeakNpcId"] = 200074,
            ["TalkActionId"] = {
                [1] = "200074:Explain02_Start",
                [2] = "200002:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153C04",
            },
        [20006011] = {
            ["Camera"] = "-781.993408,-607.023438,317.071777,0.00017,-1.2322,-155.023941,35.000019,174.116943,false,Manual,12.0",
            ["Content"] = "看起来确实……很像。",
            ["ContentKR"] = "똑같이 생기긴... 했네.",
            ["DialogueId"] = 20006011,
            ["FacialId"] = {
                [1] = "100001:Think01",
                },
            ["GUID"] = "32153C2E",
            ["NextDialogue"] = 20006012,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                [2] = "200074:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153C2E",
            },
        [20006012] = {
            ["Camera"] = "-823.676147,-643.197266,314.435547,0.00011,-1.391562,0.574502,35.000008,242.039719,false,Manual,3.5",
            ["Content"] = "咿咿咿呀——",
            ["ContentKR"] = "이이이야——",
            ["DialogueId"] = 20006012,
            ["GUID"] = "32153C58",
            ["NextDialogue"] = 20006013,
            ["SpeakNpcId"] = 820000,
            ["SpeakNpcName"] = "UI_Npc_Name_PanTuokun",
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153C58",
            },
        [20006013] = {
            ["Camera"] = "-383.416382,-617.654297,369.226074,0.000175,-13.632108,-162.021347,35.000019,314.116943,false,Manual,2.8",
            ["Content"] = "哎呀，别乱叫了，快走快走。下一次再被抓的话，可就不一定有这么好的运气了。",
            ["ContentKR"] = "에잇 진짜, 시끄럽게 하지 말고 얼른 가. 다음에 또 잡히면 이번처럼 운이 좋을 거란 보장 없어.",
            ["DialogueId"] = 20006013,
            ["FacialId"] = {
                [1] = "200002:Confident01",
                },
            ["FinalCamera"] = "-444.914062,-637.505859,353.714355,0.000175,-13.432099,-162.221298,35.000019,324.116943,false,Manual,2.8",
            ["GUID"] = "32153C82",
            ["NextDialogue"] = 20006014,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153C82",
            },
        [20006014] = {
            ["Camera"] = "-615.953979,-649.889648,308.302246,0.000101,-13.6588,-149.769836,35.000023,174.116943,false,Manual,12.0",
            ["Content"] = "我看……这只魔灵不太聪明嘛，和它说了这么多，都还不走。",
            ["ContentKR"] = "내가 봤을 땐... 이 마령은 머리가 나쁜 것 같아, 이렇게 여러 번이나 말했는데도 안 가잖아.",
            ["DialogueId"] = 20006014,
            ["FacialId"] = {
                [1] = "200002:Unhappy02",
                },
            ["FinalCamera"] = "-644.868896,-667.681641,299.754395,0.000098,-11.858697,-147.368286,35.000023,174.116943,false,Manual,12.0",
            ["GUID"] = "32153CAC",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Confident_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153CAC",
            },
        [20006015] = {
            ["Content"] = "啪叽——",
            ["ContentKR"] = "철컥!",
            ["DialogueId"] = 20006015,
            ["GUID"] = "32153CD6",
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153CD6",
            },
        [20006016] = {
            ["Camera"] = "-828.218018,-695.823242,274.558105,0.0,-10.196652,12.391548,11.88,174.116943,false,Manual,12.0",
            ["Content"] = "诶？怎么又钻到陷阱里去了？这只魔灵，是不是太害怕我们，所以把陷阱当做是安全的地方了？",
            ["ContentKR"] = "어? 왜 또 덫 안으로 들어가는 거지? 이 마령, 설마 우리가 너무 무서워서 덫을 안전한 곳이라고 생각하는 거 아니야?",
            ["DialogueId"] = 20006016,
            ["FinalCamera"] = "-812.047607,-692.268555,271.699219,0.0,-9.796662,12.39166,11.88,174.116943,false,Manual,12.0",
            ["GUID"] = "32153D00",
            ["NextDialogue"] = 20006017,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:SpecialConfident_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153D00",
            },
        [20006017] = {
            ["Camera"] = "-760.560303,-565.728516,290.460938,0.000099,-1.191192,-176.627136,35.000011,174.459366,false,Manual,2.8",
            ["Content"] = "唔，不应该呀，我们明明救过它，并且也没有表现出敌意。魔灵们虽然不会说话，但是是能分清楚谁对它好，谁对它坏的。",
            ["ContentKR"] = "음, 이상하네. 분명 우리가 녀석을 구해줬고 적대적인 태도도 보이지 않았잖아. 마령들은 비록 말은 못 해도, 누가 자기한테 잘해줬는지, 누가 해를 끼치는지는 분명히 구분할 줄 아는데 말이야.",
            ["DialogueId"] = 20006017,
            ["FacialId"] = {
                [1] = "200074:Sad01",
                },
            ["FinalCamera"] = "-784.401123,-567.131836,289.964355,0.000099,-1.191192,-176.427139,35.000011,138.232086,false,Manual,2.8",
            ["GUID"] = "32153D2A",
            ["NextDialogue"] = 20006018,
            ["SpeakNpcId"] = 200074,
            ["TalkActionId"] = {
                [1] = "200074:Think_Start",
                [2] = "200002:SpecialConfident_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153D2A",
            },
        [20006018] = {
            ["Camera"] = "-538.68689,-695.786133,229.021973,0.000027,5.603125,151.387604,35.000008,345.779022,false,Manual,12.0",
            ["Content"] = "我想想……榛子有没有像这样，做的事我一开始完全无法理解的时候……",
            ["ContentKR"] = "생각해보자... 헤이즐넛이 이런 식으로 내가 전혀 이해할 수 없는 행동을 한 적이 있었나...?",
            ["DialogueId"] = 20006018,
            ["FinalCamera"] = "-556.785034,-685.914062,231.044922,0.000028,5.603125,151.387619,35.000008,278.757599,false,Manual,12.0",
            ["GUID"] = "32153D54",
            ["NextDialogue"] = 20006019,
            ["SpeakNpcId"] = 200074,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153D54",
            },
        [20006019] = {
            ["Camera"] = "-152.133362,-1170.719727,714.169434,0.000035,-27.996868,146.383102,35.0,674.116943,false,Manual,22.0",
            ["Content"] = "一次非得去看起来光秃秃的山谷里，后来才知道是因为它闻到了山谷深处有许多浆果……一次是停在花店门口不走，等我买了花，它就开心地一口吃掉……",
            ["ContentKR"] = "한 번은 꼭 아무것도 없는 골짜기에 가야 한다고 고집을 부렸었지. 나중에 알고 보니 골짜기 깊숙한 곳에서 잔뜩 나는 베리 냄새를 맡았던 거였고... 또 한 번은 꽃집 문 앞에서 꼼짝도 안 하고 서 있었는데, 내가 꽃을 사니까 기뻐하며 한입에 먹어 치웠어...",
            ["DialogueId"] = 20006019,
            ["FinalCamera"] = "-66.008728,-699.472656,615.159668,0.000042,-26.596804,175.382294,35.0,671.116943,false,Manual,22.0",
            ["GUID"] = "32153D7E",
            ["NextDialogue"] = 20006020,
            ["SpeakNpcId"] = 200074,
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153D7E",
            },
        [20006020] = {
            ["Content"] = "还有一次，是它丢下我，拼命往山坡上跑，是因为附近的草丛里有蛇……它想把蛇引开……",
            ["ContentKR"] = "또 한 번은, 갑자기 날 두고 산비탈 위로 필사적으로 뛰어간 거였어. 알고 보니 근처 풀숲에 뱀이 있었기 때문에... 뱀을 멀리 유인해 내려고 했던 거지...",
            ["DialogueId"] = 20006020,
            ["GUID"] = "32153DA8",
            ["NextDialogue"] = 20006021,
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153DA8",
            },
        [20006021] = {
            ["Camera"] = "-854.367188,-711.143555,293.184082,0.000106,-12.591494,30.173449,35.000008,1674.542114,false,Manual,8.0",
            ["Content"] = "嗯……都是因为有很在意的事情……魔灵会在意什么呢？食物……还有伙伴！",
            ["ContentKR"] = "음... 전부 뭔가 굉장히 신경 쓰이는 일이 있었기 때문이었네. 그렇다면 마령이 신경 쓸 만한 건 뭐가 있을까? 먹이... 그리고 동료!",
            ["DialogueId"] = 20006021,
            ["FinalCamera"] = "-942.035889,-762.558594,315.785645,0.000113,-12.391452,31.173887,35.000008,1674.542114,false,Manual,8.0",
            ["GUID"] = "32153DD2",
            ["NextDialogue"] = 20006022,
            ["SpeakNpcId"] = 200074,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153DD2",
            },
        [20006022] = {
            ["Camera"] = "-800.104004,-669.561523,327.374512,0.000095,-2.797638,176.175522,35.000008,104.665184,false,Manual,12.0",
            ["Content"] = "伙伴……我明白了！如果猜得没错的话，那些魔灵猎人的藏身之处就在下水道里。",
            ["ContentKR"] = "동료... 알겠다! 내 추측이 맞다면, 그 마령 사냥꾼들의 은신처는 하수도 안에 있는 게 분명해!",
            ["DialogueId"] = 20006022,
            ["FacialId"] = {
                [1] = "100001:Satisfy01",
                },
            ["GUID"] = "32153DFC",
            ["NextDialogue"] = 20006023,
            ["Scripts"] = "SEQ{CameraMoveTo{_delay{6},TargetPosition{\"535.722229,-1070.53125,709.230469,0.000068,-6.997009,79.177307,35.0,174.116943,false,Manual,12.0\"},duration{0}},CameraMoveTo{_delay{0.5},TargetPosition{\"868.026001,153.00293,482.812988,0.000102,-2.791628,85.174393,35.000008,1674.542114,false,Manual,2.8\"},duration{5}}}",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "200074:Think_End",
                [2] = "100001:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153DFC",
            },
        [20006023] = {
            ["Camera"] = "-687.931763,-671.883789,322.655273,0.000069,-2.197053,176.775879,35.0,174.116943,false,Manual,12.0",
            ["Content"] = "在这里能嗅到其他被抓的魔灵的气息，所以它才不愿意离开。",
            ["ContentKR"] = "사로잡힌 마령 친구들의 냄새를 맡을 수 있었던 거야. 그래서 이곳을 떠나기 싫어했던 거였어.",
            ["DialogueId"] = 20006023,
            ["FacialId"] = {
                [1] = "100001:Confident02",
                },
            ["FinalCamera"] = "-771.952148,-667.40625,310.516113,0.000069,5.202958,177.175873,35.0,174.116943,false,Manual,12.0",
            ["GUID"] = "32153E26",
            ["NextDialogue"] = 20006024,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153E26",
            },
        [20006024] = {
            ["Camera"] = "-821.866577,-728.666992,342.821289,0.000095,-11.597776,130.969742,35.000008,178.123947,false,Manual,2.8",
            ["Content"] = "很有可能噢，那这样一来的话，我们就可以在边上等着，要是那些魔灵猎人出现了，就跟着他们，狠狠教训他们一顿！",
            ["ContentKR"] = "그럴 가능성이 높아! 그럼, 여기서 숨어 기다리면 되겠네. 그 마령 사냥꾼들이 나타나면, 바로 뒤따라가서 제대로 혼쭐을 내주자!",
            ["DialogueId"] = 20006024,
            ["FacialId"] = {
                [1] = "200074:Confident01",
                },
            ["FinalCamera"] = "-828.375366,-721.172852,340.748047,0.000093,-11.797785,130.969742,35.000008,178.123947,false,Manual,2.8",
            ["GUID"] = "32153E50",
            ["NextDialogue"] = 20006025,
            ["Scripts"] = "SEQ{\
LookAt{LookAtDescription{\"200074:n(100001)\"}},\
LookAt{LookAtDescription{\"100001:n(200074)\"}},\
PlayAnimation{ActorId{200074},AnimationId{\"AgreeHead\"},Duration{1}},\
PlayAnimation{_delay{5},\
ActorId{200074},AnimationId{\"Angry01_Start\"},Duration{2}}}",
            ["SpeakNpcId"] = 200074,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153E50",
            },
        [20006025] = {
            ["Camera"] = "-788.137817,-637.754883,224.224121,0.000072,-2.597166,-0.625336,35.0,174.116943,false,Manual,12.0",
            ["Content"] = "嗯嗯嗯！",
            ["ContentKR"] = "응응응!",
            ["DialogueId"] = 20006025,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["FinalCamera"] = "-756.913574,-638.139648,223.32666,0.000072,-3.397097,-1.225342,35.0,174.116943,false,Manual,12.0",
            ["GUID"] = "32153E7A",
            ["NextDialogue"] = 20006026,
            ["SpeakNpcId"] = 700251,
            ["SpeakNpcName"] = "UI_Npc_Name_PanBeikun",
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153E7A",
            },
        [20006026] = {
            ["Camera"] = "-412.370728,-629.598633,225.119141,0.000073,3.802544,-175.221069,28.0,265.494751,false,Manual,12.0",
            ["Content"] = "唔，该说这只魔灵是聪明还是笨呢？能想着要去找伙伴，算得上是聪明吧，但又自己进到陷阱里，有点笨笨的。",
            ["ContentKR"] = "음, 이 마령은 똑똑하다고 해야 할지, 아니면 멍청하다고 해야 할지 모르겠네. 동료를 찾으려는 걸 보면 똑똑하다고 할 수 있는데 스스로 덫에 들어가는 건 좀 멍청한 것 같기도 하고.",
            ["DialogueId"] = 20006026,
            ["FinalCamera"] = "-412.370728,-629.598633,241.541992,0.000073,0.002452,-175.420853,28.0,265.494751,false,Manual,12.0",
            ["GUID"] = "32153EA4",
            ["LookAt"] = {
                [1] = "200002:n(700251)",
                },
            ["NextDialogue"] = 20006027,
            ["Scripts"] = "PARA{\
LookAt{LookAtDescription{\"200074:n(200074)\"}},\
LookAt{LookAtDescription{\"100001:n(100001)\"}},\
PlayAnimation{ActorId{200074},AnimationId{\"Angry01_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153EA4",
            },
        [20006027] = {
            ["Camera"] = "-700.815918,-705.999023,263.483887,0.000069,3.402636,153.177032,35.0,174.116943,false,Manual,12.0",
            ["Content"] = "说不定它是看到我们，才故意又进到陷阱里，让我们好跟踪呢。",
            ["ContentKR"] = "우리를 보고 일부러 다시 덫에 들어간 걸지도 모르잖아. 우리가 더 잘 추적할 수 있게 하려고 말이야. ",
            ["DialogueId"] = 20006027,
            ["FinalCamera"] = "-755.168457,-688.192383,266.806152,0.000068,3.602624,148.576843,35.0,174.116943,false,Manual,12.0",
            ["GUID"] = "32153ECE",
            ["NextDialogue"] = 20006028,
            ["SpeakNpcId"] = 200074,
            ["TalkActionId"] = {
                [1] = "200074:Talk02_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153ECE",
            },
        [20006028] = {
            ["Camera"] = "-486.203613,-623.530273,240.246582,0.000087,2.002625,-162.023193,35.0,174.116943,false,Manual,12.0",
            ["Content"] = "真的假的？我觉得——",
            ["ContentKR"] = "에이 설마, 내 생각엔...",
            ["DialogueId"] = 20006028,
            ["FacialId"] = {
                [1] = "200002:Shock02",
                },
            ["FinalCamera"] = "-531.324463,-638.469727,243.410156,0.000087,4.602584,-160.822952,35.0,174.116943,false,Manual,12.0",
            ["GUID"] = "32153EF8",
            ["NextDialogue"] = 20006029,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200074:Talk02_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153EF8",
            },
        [20006029] = {
            ["Content"] = "哎？不错啊，真抓到了一只。",
            ["ContentKR"] = "어라? 나쁘지 않네, 진짜 한 마리 잡았잖아.",
            ["DialogueId"] = 20006029,
            ["GUID"] = "32153F22",
            ["NextDialogue"] = 20006030,
            ["SpeakNpcId"] = 200075,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153F22",
            },
        [20006030] = {
            ["Camera"] = "-647.833496,-724.029297,337.969727,0.000094,-6.997679,159.175262,35.0,324.116943,false,Manual,12.0",
            ["Content"] = "是魔灵猎人，快躲起来。",
            ["ContentKR"] = "마령 사냥꾼이야, 얼른 숨자.",
            ["DialogueId"] = 20006030,
            ["GUID"] = "32153F4C",
            ["NextDialogue"] = 20006031,
            ["SpeakNpcId"] = 100001,
            ["TurnTo"] = {
                [1] = "100001:n(200074)",
                [2] = "200074:n(100001)",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153F4C",
            },
        [20006031] = {
            ["Content"] = "好！",
            ["ContentKR"] = "그래!",
            ["DialogueId"] = 20006031,
            ["GUID"] = "32153F76",
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153F76",
            },
        [20006032] = {
            ["Camera"] = "-593.543457,-336.325195,269.372559,0.000176,-9.390683,-128.619858,35.000008,268.984894,false,Manual,12.0",
            ["Content"] = "好想现在就揍他们一顿，不过算了，等会儿有他们好看的！",
            ["ContentKR"] = "지금 당장 때려주고 싶지만 참겠어. 이따가 혼쭐을 내줄 거야!",
            ["DialogueId"] = 20006032,
            ["FacialId"] = {
                [1] = "200002:Angry01",
                },
            ["FinalCamera"] = "-632.141357,-384.262695,260.398438,0.000174,-8.190715,-130.618393,35.000008,268.984894,false,Manual,12.0",
            ["GUID"] = "32153FA0",
            ["NextDialogue"] = 20006033,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153FA0",
            },
        [20006033] = {
            ["Camera"] = "-1663.477051,-843.626953,503.279785,0.000179,-12.99065,25.976145,35.0,1674.542114,false,Manual,2.8",
            ["Content"] = "本来以为冰湖城里的魔灵已经快被抓完了，没想到还有收获。",
            ["ContentKR"] = "아이스레이크 시티의 마령은 다 잡은 줄 알았는데, 뜻밖의 수확이군요.",
            ["DialogueId"] = 20006033,
            ["GUID"] = "32153FCA",
            ["NextDialogue"] = 20006034,
            ["SpeakNpcId"] = 200075,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153FCA",
            },
        [20006034] = {
            ["Camera"] = "-468.823608,196.549805,329.405273,0.000182,-6.590613,-5.024419,35.000008,1033.678345,false,Manual,22.0",
            ["Content"] = "还是得出城啊，出城才能抓到更多。也不知道那个骑猪的小女孩什么时候才走。",
            ["ContentKR"] = "역시 성 밖으로 나와야 더 많이 잡을 수 있어. 그 돼지 타고 다니는 꼬마는 언제쯤이면 떠날까.",
            ["DialogueId"] = 20006034,
            ["FinalCamera"] = "-443.855225,194.355469,326.509277,0.000182,-6.590613,-5.024419,35.000008,1033.678345,false,Manual,22.0",
            ["GUID"] = "32153FF4",
            ["NextDialogue"] = 20006035,
            ["SpeakNpcId"] = 200087,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153FF4",
            },
        [20006035] = {
            ["Content"] = "别急嘛，我就不信了，捱上半个月，她还能在那里守着。",
            ["ContentKR"] = "조급해할 거 없어요. 반달 정도 더 버티고, 그녀가 계속 거기 지킬 수 있을까요?",
            ["DialogueId"] = 20006035,
            ["GUID"] = "3215401E",
            ["NextDialogue"] = 20006036,
            ["SpeakNpcId"] = 200075,
            ["TalkActionId"] = {
                [1] = "200075:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/3215401E",
            },
        [20006036] = {
            ["Content"] = "也是，天寒地冻的还有秽兽，说不定明天她就哭着鼻子回家啦。",
            ["ContentKR"] = "그건 그렇지, 날도 춥고 필토이드들도 있는데, 어쩌면 내일쯤엔 울면서 집으로 돌아갈지도 몰라.",
            ["DialogueId"] = 20006036,
            ["GUID"] = "32154048",
            ["NextDialogue"] = 20006037,
            ["SpeakNpcId"] = 200087,
            ["TalkActionId"] = {
                [1] = "200075:Talk02_End",
                [2] = "200087:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32154048",
            },
        [20006037] = {
            ["Content"] = "最好这样！",
            ["ContentKR"] = "그럼 최고죠!",
            ["DialogueId"] = 20006037,
            ["GUID"] = "32154072",
            ["SpeakNpcId"] = 200075,
            ["TalkActionId"] = {
                [1] = "200075:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32154072",
            },
        [20006101] = {
            ["Camera"] = "-1302.360229,-832.505859,345.045898,0.000178,-0.789761,21.978495,35.0,1674.542114,false,Manual,2.8",
            ["Content"] = "他们回下水道里了，走，快跟上。",
            ["ContentKR"] = "놈들이 하수도로 돌아간다, 얼른 따라가자.",
            ["DialogueId"] = 20006101,
            ["FacialId"] = {
                [1] = "200002:Confident02",
                },
            ["GUID"] = "32154AF2",
            ["NextDialogue"] = 20006102,
            ["Scripts"] = "PARA{SEQ{TurnTo{TurnToDescription{\"200002:n(100001)\"}},PlayAnimation{_delay{0.1},ActorId{200002},AnimationId{\"Confident_Start\"},Duration{1}}},CameraMoveTo{_delay{2},TargetPosition{\"-840.86145,-688.524414,290.947754,0.000184,-10.389148,-19.824919,35.000008,95.310921,false,Manual,2.8\"},duration{0}}}",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/2001/200061/32154AF2",
            },
        [20006102] = {
            ["Camera"] = "-691.08667,-817.638672,263.54541,0.000229,8.209702,133.76033,35.000011,242.476578,false,Manual,2.8",
            ["Content"] = "小声点，别兴高采烈的，如果惊动了魔灵猎人，那只魔灵要是会说话，一定会骂你笨蛋的。",
            ["ContentKR"] = "조용히 해, 너무 들뜨지 말고, 마령 사냥꾼들한테 들키기라도 하면 저 마령이 널 바보라고 할 거야.",
            ["DialogueId"] = 20006102,
            ["FinalCamera"] = "-710.927734,-796.919922,267.683105,0.000229,8.209702,133.76033,35.000011,242.476578,false,Manual,2.8",
            ["GUID"] = "32154B1C",
            ["LookAt"] = {
                [1] = "100001:n(200002)",
                },
            ["NextDialogue"] = 20006103,
            ["Scripts"] = "LookAt{LookAtDescription{\"200074:n(200002)\"}}",
            ["SpeakNpcId"] = 100001,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200061/32154B1C",
            },
        [20006103] = {
            ["Camera"] = "-840.86145,-688.524414,290.947754,0.000184,-10.389148,-19.824919,35.000008,95.310921,false,Manual,2.8",
            ["Content"] = "哼，才不会，我刚刚那么关心它，一定给它留下了好印象！",
            ["ContentKR"] = "흥, 절대 아니거든! 내가 아까 그렇게 신경 써줬으니, 분명 나한테 좋은 인상이 남았을 거야!",
            ["DialogueId"] = 20006103,
            ["FacialId"] = {
                [1] = "200002:Confident01",
                },
            ["GUID"] = "32154B46",
            ["LookAt"] = {
                [1] = "200074:n(100001)",
                },
            ["NextDialogue"] = 20006104,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/2001/200061/32154B46",
            },
        [20006104] = {
            ["Camera"] = "-832.142822,-728.967773,342.387207,0.000241,-11.390535,127.158501,35.000011,192.086792,false,Manual,2.8",
            ["Content"] = "噗哧……你们啊……虽然我年纪不大，但是带着榛子也见过很多人了，但像你们这样，在意魔灵想法的人可不多。",
            ["ContentKR"] = "푸흡... 너희들... 내가 나이는 어리지만, 헤이즐넛이랑 같이 다니면서 사람도 많이 봤거든. 근데 마령 생각까지 신경 쓰는 사람은 정말 드물었어.",
            ["DialogueId"] = 20006104,
            ["FinalCamera"] = "-837.814453,-721.487305,340.496582,0.000241,-11.390535,127.158501,35.000011,192.086792,false,Manual,2.8",
            ["GUID"] = "32154B70",
            ["LookAt"] = {
                [1] = "100001:n(200074)",
                },
            ["NextDialogue"] = 20006105,
            ["SpeakNpcId"] = 200074,
            ["TalkActionId"] = {
                [1] = "200074:Talk02_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200061/32154B70",
            },
        [20006105] = {
            ["Content"] = "要是每个人都像你们一样，意识到动物和魔灵也是有自己喜好的，就不会有魔灵猎人了！",
            ["ContentKR"] = "누구나 다 너희들처럼 동물이랑 마령도 자기 취향이 있다는 걸 알았다면, 마령 사냥꾼 같은 건 없었을 거야!",
            ["DialogueId"] = 20006105,
            ["GUID"] = "32154B9A",
            ["NextDialogue"] = 20006106,
            ["SpeakNpcId"] = 200074,
            ["TalkActionId"] = {
                [1] = "200074:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200061/32154B9A",
            },
        [20006106] = {
            ["Camera"] = "-809.379883,-578.354492,277.954102,0.000212,5.809533,178.160782,35.000011,115.034302,false,Manual,2.8",
            ["Content"] = "走吧走吧，这一次我一定要让他们彻底知错！",
            ["ContentKR"] = "가자, 가자! 이번엔 제대로 잘못을 깨닫게 해줄 거야!",
            ["DialogueId"] = 20006106,
            ["FinalCamera"] = "-822.223877,-577.945312,279.260742,0.000213,5.809533,178.160782,35.000011,110.479393,false,Manual,2.8",
            ["GUID"] = "32154BC4",
            ["LookAt"] = {
                [1] = "200074:n(200074)",
                },
            ["SpeakNpcId"] = 200074,
            ["TalkActionId"] = {
                [1] = "200074:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200061/32154BC4",
            },
        [20006201] = {
            ["Camera"] = "-287.4375,38.861328,166.546265,0.000031,-8.400183,-1.804748,18.000004,100000.0,false,Manual,2.8",
            ["Content"] = "唔，原来这里的下水道这么复杂。榛子，能闻到魔灵的味道吗？",
            ["ContentKR"] = "음, 여기 하수도는 정말 복잡하네. 헤이즐넛, 마령의 냄새를 맡을 수 있겠어?",
            ["DialogueId"] = 20006201,
            ["GUID"] = "32155B5A",
            ["NextDialogue"] = 20006202,
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200062/32155B5A",
            },
        [20006202] = {
            ["Content"] = "哼唧……",
            ["ContentKR"] = "꿀...",
            ["DialogueId"] = 20006202,
            ["GUID"] = "32155B84",
            ["NextDialogue"] = 20006203,
            ["SpeakNpcId"] = 200086,
            ["VoiceName"] = "voice/$Locale$/story/2001/200062/32155B84",
            },
        [20006203] = {
            ["Content"] = "味道太多了反而无法分辨方向？唔，只能先向前走了。",
            ["ContentKR"] = "냄새가 너무 많아서 방향을 못 잡겠다고? 음, 그럼 일단 앞으로 가볼 수밖에 없겠네.",
            ["DialogueId"] = 20006203,
            ["GUID"] = "32155BAE",
            ["NextDialogue"] = 20006204,
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200062/32155BAE",
            },
        [20006204] = {
            ["Content"] = "跟着我走就好，我对这里可熟悉了。",
            ["ContentKR"] = "나만 따라오면 돼, 여긴 내가 잘 알아.",
            ["DialogueId"] = 20006204,
            ["GUID"] = "32155BD8",
            ["NextDialogue"] = 20006205,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/2001/200062/32155BD8",
            },
        [20006205] = {
            ["Content"] = "咦，原来小白平时住在这种地方吗？",
            ["ContentKR"] = "어? 스노우는 평소에 이런 곳에서 지내는 거야?",
            ["DialogueId"] = 20006205,
            ["GUID"] = "32155C02",
            ["NextDialogue"] = 20006206,
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200062/32155C02",
            },
        [20006206] = {
            ["Content"] = "不……不是的，只是身为魔王大人，之前来过这里巡视过几次，远来的魔灵猎人猎人哟，跟紧了。",
            ["ContentKR"] = "아니... 아니야! 마왕님으로서 전에 몇 번 여기 순찰하러 온 적이 있을 뿐이야. 멀리서 온 마령 사냥꾼 사냥꾼이여, 잘 따라오라고!",
            ["DialogueId"] = 20006206,
            ["GUID"] = "32155C2C",
            ["NextDialogue"] = 20006207,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/2001/200062/32155C2C",
            },
        [20006207] = {
            ["Content"] = "好~",
            ["ContentKR"] = "그래~",
            ["DialogueId"] = 20006207,
            ["GUID"] = "32155C56",
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200062/32155C56",
            },
        [20006301] = {
            ["Content"] = "啊，这个痕迹，之前巡视的时候可没有见到过。",
            ["ContentKR"] = "어? 이 흔적은, 전에 순찰할 땐 본 적 없었는데.",
            ["DialogueId"] = 20006301,
            ["GUID"] = "32156BC2",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 20006302,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/2001/200063/32156BC2",
            },
        [20006302] = {
            ["Content"] = "看起来像是被抓的那个魔灵留下来的，跟着这个痕迹吧。",
            ["ContentKR"] = "잡혀간 그 마령이 남긴 흔적 같아, 이 흔적을 따라가 보자.",
            ["DialogueId"] = 20006302,
            ["GUID"] = "32156BEC",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200063/32156BEC",
            },
        [20006401] = {
            ["Content"] = "痕迹越来越新，应该不远了……",
            ["ContentKR"] = "흔적이 점점 선명해져, 아마 멀지 않은 것 같아...",
            ["DialogueId"] = 20006401,
            ["GUID"] = "32157C2A",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 20006402,
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200064/32157C2A",
            },
        [20006402] = {
            ["Content"] = "我好像听见有人在说话——",
            ["ContentKR"] = "누군가 말하는 소리가 들리는 것 같아...",
            ["DialogueId"] = 20006402,
            ["GUID"] = "32157C54",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/2001/200064/32157C54",
            },
        [20006501] = {
            ["Camera"] = "802.462891,37.094727,399.100616,0.000002,-18.600189,1.600099,35.000011,403.34671,false,Manual,12.0",
            ["Content"] = "我跟你说，这只魔灵……据说是所有魔灵里最聪明、最稀有、也是所有魔灵的最初形态——潘神。",
            ["ContentKR"] = "이 마령 말이야... 모든 마령 중에 제일 똑똑하고 희귀한 존재이며, 모든 마령의 최초 형태인 판신이라고 하더라고.",
            ["DialogueId"] = 20006501,
            ["FinalCamera"] = "559.453125,30.306641,481.861816,0.000002,-18.800184,1.600099,35.000011,403.34671,false,Manual,12.0",
            ["GUID"] = "32158C92",
            ["NextDialogue"] = 20006502,
            ["SpeakNpcId"] = 200075,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200065/32158C92",
            },
        [20006502] = {
            ["Content"] = "最聪明？真的假的？真要是最聪明，怎么会被我们抓到？",
            ["ContentKR"] = "제일 똑똑하다고? 정말이요? 제일 똑똑한데 왜 우리한테 잡혔죠?",
            ["DialogueId"] = 20006502,
            ["GUID"] = "32158CBC",
            ["NextDialogue"] = 20006503,
            ["SpeakNpcId"] = 200087,
            ["TalkActionId"] = {
                [1] = "200087:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200065/32158CBC",
            },
        [20006503] = {
            ["Camera"] = "565.943359,-554.305664,435.741028,0.000025,-6.400112,56.795567,35.000008,100000.0,false,Manual,22.0",
            ["Content"] = "你什么意思？你是说我们很笨，所以不可能抓到最聪明的魔灵？",
            ["ContentKR"] = "무슨 뜻이야? 우리가 멍청해서 제일 똑똑한 마령을 잡을 수 없다는 거야?",
            ["DialogueId"] = 20006503,
            ["FinalCamera"] = "586.517578,-522.865234,431.526306,0.000026,-6.400112,56.795399,35.000008,100000.0,false,Manual,22.0",
            ["GUID"] = "32158CE6",
            ["LookAt"] = {
                [1] = "200075:n(200087)",
                },
            ["NextDialogue"] = 20006504,
            ["SpeakNpcId"] = 200075,
            ["TalkActionId"] = {
                [1] = "200075:Talk03_Start",
                [2] = "200087:Talk02_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200065/32158CE6",
            },
        [20006504] = {
            ["Camera"] = "485.179688,62.989258,489.663513,0.000012,-12.999386,-2.199652,35.000008,450.0,false,Manual,6.0",
            ["Content"] = "我……我没这个意思，老大你可聪明了，要不是靠着你做的陷阱，我们怎么能抓到这么多魔灵。",
            ["ContentKR"] = "전... 전 그런 뜻이 아니라, 형님 똑똑하다는 거죠. 형님 만든 덫이 아니면 어떻게 이렇게 많은 마령을 잡을 수 있었겠냐는 거죠.",
            ["DialogueId"] = 20006504,
            ["FinalCamera"] = "610.728516,58.283203,460.538757,0.000012,-13.199401,-1.999653,35.000008,450.0,false,Manual,6.0",
            ["GUID"] = "32158D10",
            ["LookAt"] = {
                [1] = "200087:n(200075)",
                },
            ["NextDialogue"] = 20006505,
            ["SpeakNpcId"] = 200087,
            ["TalkActionId"] = {
                [1] = "200087:Shock_Start",
                },
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/2001/200065/32158D10",
            },
        [20006505] = {
            ["Content"] = "那是，你看，咱们已经抓了这么多魔灵，慢慢来研究，总能找出从它们身上炼出月石的方法，写出论文来。",
            ["ContentKR"] = "당연하지, 봐봐, 이미 이렇게 많은 마령을 잡았잖아. 천천히 연구하다 보면, 마령들한테서 월석을 추출하는 방법을 찾아내고 논문도 쓸 수 있을 거야.",
            ["DialogueId"] = 20006505,
            ["GUID"] = "32158D3A",
            ["LookAt"] = {
                [1] = "200075:n(200075)",
                },
            ["NextDialogue"] = 20006506,
            ["SpeakNpcId"] = 200075,
            ["TalkActionId"] = {
                [1] = "200087:Shock_End",
                [2] = "200075:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200065/32158D3A",
            },
        [20006506] = {
            ["Content"] = "到时候，我看谁还敢嘲笑我是炼金院的肄业生！",
            ["ContentKR"] = "그때가 되면 아무도 내가 연금원의 중퇴생이라고 비웃을 수 없을 거야!",
            ["DialogueId"] = 20006506,
            ["GUID"] = "32158D64",
            ["NextDialogue"] = 20006507,
            ["SpeakNpcId"] = 200075,
            ["TalkActionId"] = {
                [1] = "200075:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200065/32158D64",
            },
        [20006507] = {
            ["Content"] = "老大，我对论文什么的不感兴趣，能分点银币给我就好了。",
            ["ContentKR"] = "형님, 전 논문엔 관심 없고, 실버나 조금 나눠주면 돼요.",
            ["DialogueId"] = 20006507,
            ["GUID"] = "32158D8E",
            ["NextDialogue"] = 20006508,
            ["SpeakNpcId"] = 200087,
            ["TalkActionId"] = {
                [1] = "200075:Angry01_End",
                [2] = "200087:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200065/32158D8E",
            },
        [20006508] = {
            ["Content"] = "好说，都好说。",
            ["ContentKR"] = "그럼, 그건 당연하지.",
            ["DialogueId"] = 20006508,
            ["GUID"] = "32158DB8",
            ["LookAt"] = {
                [1] = "200087:n(200087)",
                },
            ["NextDialogue"] = 20006509,
            ["SpeakNpcId"] = 200075,
            ["TalkActionId"] = {
                [1] = "200087:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200065/32158DB8",
            },
        [20006509] = {
            ["Camera"] = "0.919922,-0.328125,154.78241,0.000047,-0.999783,-169.994827,35.000008,147.718536,false,Manual,8.0",
            ["Content"] = "我觉得，不怎么好说。",
            ["ContentKR"] = "별로 당연하지 않은 것 같은데.",
            ["DialogueId"] = 20006509,
            ["FacialId"] = {
                [1] = "100001:Confident02",
                },
            ["GUID"] = "32158DE2",
            ["NextDialogue"] = 20006510,
