            ["GUID"] = "7D2E9912",
            ["SpeakNpcId"] = 700116,
            ["TalkActionId"] = {
                [1] = "700116:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/env/700116/7D2E9912",
            },
        [50005001] = {
            ["Content"] = "啧，生面孔啊。",
            ["ContentKR"] = "흠, 처음 보는 얼굴이군.",
            ["DialogueId"] = 50005001,
            ["Duration"] = 3,
            ["GUID"] = "7D2EA97A",
            ["SpeakNpcId"] = 700096,
            ["TalkActionId"] = {
                [1] = "700096:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/env/700096/7D2EA97A",
            },
        [50005101] = {
            ["Content"] = "要点什么。",
            ["ContentKR"] = "뭐, 살 거라도 있나?",
            ["DialogueId"] = 50005101,
            ["Duration"] = 3,
            ["GUID"] = "7D2EB9E2",
            ["SpeakNpcId"] = 700096,
            ["TalkActionId"] = {
                [1] = "700096:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/env/700096/7D2EB9E2",
            },
        [50005201] = {
            ["Content"] = "忠于欲望，忠于欲望，忠于欲望，哎，到底怎么才算忠于欲望啊……",
            ["ContentKR"] = "욕망에 충실하라, 욕망에 충실하라, 욕망에 충실하라... 아, 도대체 어떻게 해야 욕망에 충실한 거야...",
            ["DialogueId"] = 50005201,
            ["Duration"] = 4,
            ["GUID"] = "7D2ECA4A",
            ["SpeakNpcId"] = 700077,
            ["TalkActionId"] = {
                [1] = "700077:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/env/700077/7D2ECA4A",
            },
        [50005301] = {
            ["Content"] = "开往下一站的列车即将出发，如有购票需求请您在此处办理——什么？没钱？那就一边儿去！",
            ["ContentKR"] = "다음 역으로 가는 열차가 곧 출발합니다. 표는 이곳에서 구매하시면 됩니다. 뭐라고요? 돈이 없다고요? 헛된 꿈은 그만 꾸고 저리 가세요!",
            ["DialogueId"] = 50005301,
            ["Duration"] = 4,
            ["GUID"] = "7D2D1FBA",
            ["SpeakNpcId"] = 700147,
            ["TalkActionId"] = {
                [1] = "700147:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/env/700021/7D2D1FBA",
            },
        [50005401] = {
            ["Content"] = "哈哈哈，她跑得好快啊，比老鼠还快！",
            ["ContentKR"] = "하하하, 정말 빠르게 도망가네! 생쥐보다도 더 빠른걸!",
            ["DialogueId"] = 50005401,
            ["Duration"] = 3,
            ["GUID"] = "7D2EEB1A",
            ["SpeakNpcId"] = 700089,
            },
        [50005501] = {
            ["Content"] = "臭卡戎，还愣着干什么呀，快去追你家小崽子吧！",
            ["ContentKR"] = "이 더러운 카론 녀석아, 뭘 멍하니 서 있어! 어서 쫓아가라고!",
            ["DialogueId"] = 50005501,
            ["Duration"] = 3,
            ["GUID"] = "7D2EFB82",
            ["SpeakNpcId"] = 700088,
            ["TalkActionId"] = {
                [1] = "700088:Confident_Start",
                },
            },
        [50005601] = {
            ["Content"] = "要不要换一个大一点的看板啊……",
            ["ContentKR"] = "간판을 좀 더 큰 걸로 바꿔봐야 할까...",
            ["DialogueId"] = 50005601,
            ["Duration"] = 3,
            ["GUID"] = "7D2F0BEA",
            ["SpeakNpcId"] = 700143,
            },
        [50100101] = {
            ["Content"] = "针头线脑，香脂香囊，走过路过不要错过——",
            ["ContentKR"] = "바늘부터 실까지, 향유부터 향주머니까지 다 있어요! 구경하고 가세요~",
            ["DialogueId"] = 50100101,
            ["GUID"] = "7D6B9BD2",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6B9BD2",
            },
        [50100201] = {
            ["Content"] = "来看看华胥特色纪念品喽，给亲朋好友带一份吧！",
            ["ContentKR"] = "화서의 특별한 기념품 좀 보고 가세요! 가족, 친구 선물로 그만입니다!",
            ["DialogueId"] = 50100201,
            ["GUID"] = "7D6BAC3A",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6BAC3A",
            },
        [50100301] = {
            ["Content"] = "海的那边……是什么样子呢？",
            ["ContentKR"] = "저 바다 너머는... 어떤 모습일까?",
            ["DialogueId"] = 50100301,
            ["GUID"] = "7D6BBCA2",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6BBCA2",
            },
        [50100311] = {
            ["Content"] = "工头昨天心情好，给我们都发了赏钱！",
            ["ContentKR"] = "반장이 어제 기분이 좋았나 봐. 우리한테까지 장려금을 찔러 주더라니까!",
            ["DialogueId"] = 50100311,
            ["GUID"] = "7D6BBE46",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6BBE46",
            },
        [50100312] = {
            ["Content"] = "那有什么！出船之前，老板来请吃了茶呢！",
            ["ContentKR"] = "그게 끝이 아니야! 출항 전엔 사장님이 차도 한잔 사 줬다고!",
            ["DialogueId"] = 50100312,
            ["GUID"] = "7D6BBE70",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6BBE70",
            },
        [50100401] = {
            ["Content"] = "腰酸背痛啊，抽空得找人好好按按……",
            ["ContentKR"] = "허리 아파 죽겠네. 시간 날 때 시원하게 안마라도 받아야겠어...",
            ["DialogueId"] = 50100401,
            ["GUID"] = "7D6BCD0A",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6BCD0A",
            },
        [50100501] = {
            ["Content"] = "这箱货物贵重，先包上一层软垫再搬吧。",
            ["ContentKR"] = "이 상자는 귀한 물건이니까, 부드러운 천으로 한 겹 싸고 나서 옮기자고.",
            ["DialogueId"] = 50100501,
            ["GUID"] = "7D6BDD72",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6BDD72",
            },
        [50100601] = {
            ["Content"] = "这些木簪花钿，好看是好看，可我不会用呢。",
            ["ContentKR"] = "나무로 만든 이 비녀랑 장신구, 예쁘긴 한데 어떻게 쓰는 건지 모르겠네.",
            ["DialogueId"] = 50100601,
            ["GUID"] = "7D6BEDDA",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6BEDDA",
            },
        [50100701] = {
            ["Content"] = "香料丝绸茶叶油膏器皿……种类也太多了！",
            ["ContentKR"] = "향료, 비단, 찻잎, 기름, 그릇... 종류가 너무 많아!",
            ["DialogueId"] = 50100701,
            ["GUID"] = "7D6BFE42",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6BFE42",
            },
        [50100801] = {
            ["Content"] = "沉月香卖完了？怎么可能，昨天才进的货！",
            ["ContentKR"] = "침월향이 다 팔렸다고요? 말도 안 돼. 어제 막 들어왔잖아요!",
            ["DialogueId"] = 50100801,
            ["GUID"] = "7D6C0EAA",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6C0EAA",
            },
        [50100901] = {
            ["Content"] = "点数清，码数齐，今日开市不慌矣~",
            ["ContentKR"] = "수량 딱 맞고, 종류도 다 있고~ 오늘은 시작이 좋네~",
            ["DialogueId"] = 50100901,
            ["GUID"] = "7D6C1F12",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6C1F12",
            },
        [50101001] = {
            ["Content"] = "不愧是织星客的故乡，华胥果真名不虚传。",
            ["ContentKR"] = "역시 화서는 소문대로 대단한 곳이군. 별을 잇는 자들의 고향다워.",
            ["DialogueId"] = 50101001,
            ["GUID"] = "7D6C2F7A",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6C2F7A",
            },
        [50101101] = {
            ["Content"] = "山清水秀，在此品一盏香茗，妙趣横生呐~",
            ["ContentKR"] = "산 좋고 물 좋은 곳에서 마시는 차 한잔~ 캬, 정말 기가 막히다~",
            ["DialogueId"] = 50101101,
            ["GUID"] = "7D6C3FE2",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6C3FE2",
            },
        [50101201] = {
            ["Content"] = "说好打赌输了就欠我三根糖葫芦，你不许耍赖。",
            ["ContentKR"] = "내기에서 지면 나한테 탕후루 3개 사 줘야 돼. 나중에 딴소리하지 마.",
            ["DialogueId"] = 50101201,
            ["GUID"] = "7D6C504A",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6C504A",
            },
        [50101202] = {
            ["Content"] = "放心，明日阿娘给了零花钱就来请你！",
            ["ContentKR"] = "걱정 마, 내일 엄마한테 용돈 받으면 바로 사 줄게!",
            ["DialogueId"] = 50101202,
            ["GUID"] = "7D6C5074",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6C5074",
            },
        [50101203] = {
            ["Content"] = "浮星埠是一年比一年热闹了啊……",
            ["ContentKR"] = "별빛 부두는 해마다 더 활기가 넘치네...",
            ["DialogueId"] = 50101203,
            ["GUID"] = "7D6C509E",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6C509E",
            },
        [50101301] = {
            ["Content"] = "诶呀！撞得我发髻都散啦！",
            ["ContentKR"] = "어머나! 부딪히는 바람에 머리 모양이 다 망가졌잖아!",
            ["DialogueId"] = 50101301,
            ["GUID"] = "7D6C60B2",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6C60B2",
            },
        [50101401] = {
            ["Content"] = "嘿！小友走路别分心，撞到人可不好！",
            ["ContentKR"] = "어이! 한눈팔면서 걷지 마! 다른 사람이랑 부딪히잖아!",
            ["DialogueId"] = 50101401,
            ["GUID"] = "7D6C711A",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6C711A",
            },
        [50101501] = {
            ["Content"] = "绸缎齐整，杂粮归铺，心才安……",
            ["ContentKR"] = "비단은 가지런히 접어 두고, 잡곡은 가게 안에 들여놔야 마음이 편하다니까...",
            ["DialogueId"] = 50101501,
            ["GUID"] = "7D6C8182",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6C8182",
            },
        [50101601] = {
            ["Content"] = "祖传山参，百年阿胶，价优物美待君选！",
            ["ContentKR"] = "가문 대대로 전해 내려오는 산삼~ 백 년 된 아교~ 싸고 좋은 물건 들여가세요!",
            ["DialogueId"] = 50101601,
            ["GUID"] = "7D6C91EA",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6C91EA",
            },
        [50101701] = {
            ["Content"] = "好东西不贱卖哈，总有眼尖识货人！",
            ["ContentKR"] = "좋은 물건은 싸게 안 팔아요. 알아봐 주는 손님이 있기 마련이거든요!",
            ["DialogueId"] = 50101701,
            ["GUID"] = "7D6CA252",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6CA252",
            },
        [50101801] = {
            ["Content"] = "瓷器娇贵，客人轻拿轻放~",
            ["ContentKR"] = "도자기는 깨지기 쉽습니다~ 살살 다뤄 주세요~",
            ["DialogueId"] = 50101801,
            ["GUID"] = "7D6CB2BA",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6CB2BA",
            },
        [50101901] = {
            ["Content"] = "再便宜点，我直接拿了。",
            ["ContentKR"] = "조금만 더 깎아 주세요. 바로 살게요.",
            ["DialogueId"] = 50101901,
            ["GUID"] = "7D6CC322",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6CC322",
            },
        [50102001] = {
            ["Content"] = "瓶子看着精致……没什么瑕疵吧？",
            ["ContentKR"] = "예뻐 보이긴 하는데... 병에 흠집 같은 건 없죠?",
            ["DialogueId"] = 50102001,
            ["GUID"] = "7D6CD38A",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6CD38A",
            },
        [50102101] = {
            ["Content"] = "称点桂花糕，我带回去给娘子吃~",
            ["ContentKR"] = "계화떡 좀 싸 주세요. 집사람한테 갖다주려고요~",
            ["DialogueId"] = 50102101,
            ["GUID"] = "7D6CE3F2",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6CE3F2",
            },
        [50102201] = {
            ["Content"] = "这匹布料柔软顺滑，做成里衣定是舒适。",
            ["ContentKR"] = "보들보들하니까, 안에 받쳐 입는 옷을 만들면 딱이겠어.",
            ["DialogueId"] = 50102201,
            ["GUID"] = "7D6CF45A",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6CF45A",
            },
        [50102301] = {
            ["Content"] = "神君鉴上，我雪霁立誓一生不负初晴，如……",
            ["ContentKR"] = "신군님께 맹세하건대, 나는 평생 네 마음을 저버리지...",
            ["DialogueId"] = 50102301,
            ["GUID"] = "7D6D04C2",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6D04C2",
            },
        [50102401] = {
            ["Content"] = "嘘！后面的话不许你说！我都明白……",
            ["ContentKR"] = "쉿! 거기까지! 무슨 말을 할 건지 다 알아...",
            ["DialogueId"] = 50102401,
            ["GUID"] = "7D6D152A",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6D152A",
            },
        [50102501] = {
            ["Content"] = "白龙神君保佑此次出航平安无虞！",
            ["ContentKR"] = "백룡신군이시여, 무사히 이번 항해를 마치도록 굽어살펴 주시옵소서!",
            ["DialogueId"] = 50102501,
            ["GUID"] = "7D6D2592",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6D2592",
            },
        [50102601] = {
            ["Content"] = "小女愿家中长辈身体康健，福寿绵长。",
            ["ContentKR"] = "집안 어른들께서 건강하게 오래오래 사시게 해 주세요.",
            ["DialogueId"] = 50102601,
            ["GUID"] = "7D6D35FA",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6D35FA",
            },
        [50102701] = {
            ["Content"] = "明先生最近可是在哪发了大财？",
            ["ContentKR"] = "명 선생, 요즘 어디서 큰돈이라도 번 겁니까?",
            ["DialogueId"] = 50102701,
            ["GUID"] = "7D6D4662",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6D4662",
            },
        [50102702] = {
            ["Content"] = "侥幸而已！还是江先生的生意更稳当。",
            ["ContentKR"] = "운이 좋았던 겁니다! 사업은 역시 강 선생 쪽이 더 탄탄하죠.",
            ["DialogueId"] = 50102702,
            ["GUID"] = "7D6D468C",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6D468C",
            },
        [50102801] = {
            ["Content"] = "下次出航得往赫墨北边再走一走……",
            ["ContentKR"] = "다음 항해 때는 케메트 북쪽으로 조금만 더 가 보자...",
            ["DialogueId"] = 50102801,
            ["GUID"] = "7D6D56CA",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6D56CA",
            },
        [50102901] = {
            ["Content"] = "明明已经让了极大的利，为何销量还是……",
            ["ContentKR"] = "가격을 확 낮췄는데도, 어째서 판매량은 여전히 이 모양이지...",
            ["DialogueId"] = 50102901,
            ["GUID"] = "7D6D6732",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6D6732",
            },
        [50103001] = {
            ["Content"] = "我才加入织星客，凡事劳请前辈多指点！",
            ["ContentKR"] = "얼마 전에 별을 잇는 자가 됐습니다! 앞으로 많이 가르쳐 주세요!",
            ["DialogueId"] = 50103001,
            ["GUID"] = "7D6D779A",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6D779A",
            },
        [50103002] = {
            ["Content"] = "客气了，若有问题便尽管问吧。",
            ["ContentKR"] = "천만에, 궁금한 게 있으면 편히 물어봐.",
            ["DialogueId"] = 50103002,
            ["GUID"] = "7D6D77C4",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6D77C4",
            },
        [50103003] = {
            ["Content"] = "您说我是要继续追资还是见好就收呢？",
            ["ContentKR"] = "추가 투자를 해야 할까요, 아니면 좀 괜찮다 싶을 때 발을 빼는 게 맞을까요?",
            ["DialogueId"] = 50103003,
            ["GUID"] = "7D6D77EE",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6D77EE",
            },
        [50103101] = {
            ["Content"] = "新来的哥儿，皮子肥不肥？",
            ["ContentKR"] = "새로 온 녀석 말이야, 돈은 좀 있어 보여?",
            ["DialogueId"] = 50103101,
            ["GUID"] = "7D6D8802",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6D8802",
            },
        [50103201] = {
            ["Content"] = "穷地方来的，没挂多少老居米子。",
            ["ContentKR"] = "깡촌에서 온 놈이라 가진 것도 얼마 없는 것 같던데.",
            ["DialogueId"] = 50103201,
            ["GUID"] = "7D6D986A",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6D986A",
            },
        [50103301] = {
            ["Content"] = "客人来看看？爬山头来的正经古董。",
            ["ContentKR"] = "구경하시겠어요? 감쪽같이 수리한 진짜 골동품이랍니다.",
            ["DialogueId"] = 50103301,
            ["GUID"] = "7D6DA8D2",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6DA8D2",
            },
        [50103401] = {
            ["Content"] = "以前都只做洋庄，好不容易才运回国的！",
            ["ContentKR"] = "원래 외국인들하고만 거래했었는데, 정말 어렵게 다시 화서로 들여온 거예요!",
            ["DialogueId"] = 50103401,
            ["GUID"] = "7D6DB93A",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6DB93A",
            },
        [50103501] = {
            ["Content"] = "风里有太皓的意志，只需静下心感受……",
            ["ContentKR"] = "바람결엔 태호 님의 숨결이 서려 있어. 마음을 비우고 그냥 느끼면 돼...",
            ["DialogueId"] = 50103501,
            ["GUID"] = "7D6DC9A2",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6DC9A2",
            },
        [50103601] = {
            ["Content"] = "冰台五十斤，春一品三十斤，诶诶诶，那边的，香料都是稀奇货，搬运的时候可小心点！",
            ["ContentKR"] = "황해쑥 50근, 춘일품 30근... 어이, 거기! 향료는 다 귀한 물건이라니까! 옮길 때 조심하라고!",
            ["DialogueId"] = 50103601,
            ["GUID"] = "7D6DDA0A",
            ["SpeakNpcId"] = 701039,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6DDA0A",
            },
        [50103701] = {
            ["Content"] = "专供异国友人的纪念品摊铺，来华胥之游人必不可错过！香囊折扇古玩珍宝，您想要的，应有尽有！",
            ["ContentKR"] = "외국 손님들을 위한 기념품 가게입니다! 화서에 오셨다면 놓치지 마세요! 향주머니부터 부채, 골동품, 진귀한 보물까지 원하시는 건 뭐든 있습니다!",
            ["DialogueId"] = 50103701,
            ["GUID"] = "7D6DEA72",
            ["SpeakNpcId"] = 701040,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6DEA72",
            },
        [50103801] = {
            ["Content"] = "南来北往的慢走一步，且听我说道说道咱们这浮星埠的千年历史——做生意讲究明明白白，对自己的过去啊，也得清清楚楚才好。",
            ["ContentKR"] = "지나가는 분들은 다들 이 늙은이가 들려주는 별빛 부두의 역사를 들어 보시게. 장사꾼이라면 현명해야 하니, 이 땅의 과거도 훤히 알고 있어야지 않겠나.",
            ["DialogueId"] = 50103801,
            ["GUID"] = "7D6DFADA",
            ["SpeakNpcId"] = 701041,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6DFADA",
            },
        [50103901] = {
            ["Content"] = "您可听好了，这大风九章的第一章就是：戕身害命，不可为也。",
            ["ContentKR"] = "잘 들으세요. 대풍구장 제1장은 \"남을 해하거나 목숨을 빼앗지 말지어다\"로 규정하고 있어요.",
            ["DialogueId"] = 50103901,
            ["GUID"] = "7D6E0B42",
            ["SpeakNpcId"] = 701044,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6E0B42",
            },
        [50104001] = {
            ["Content"] = "怎么样才能长出角呢，我揪……我揪……嗷！好痛……",
            ["ContentKR"] = "뿔이 나게 하려면 어떻게 해야 하지? 끄으응... 아야! 당겨 봐야 아프기만 한데...",
            ["DialogueId"] = 50104001,
            ["GUID"] = "7D6E1BAA",
            ["SpeakNpcId"] = 701045,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6E1BAA",
            },
        [50104101] = {
            ["Content"] = "没想到成为织星客还有如此多的便利！百年春真是家大业大啊。",
            ["ContentKR"] = "별을 잇는 자가 되면 좋은 점이 정말 많구나! 백년춘은 정말 대단한 곳이네!",
            ["DialogueId"] = 50104101,
            ["GUID"] = "7D6E2C12",
            ["SpeakNpcId"] = 701046,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6E2C12",
            },
        [50104201] = {
            ["Content"] = "盖个会客厅怎么样？要不再加个小厨房？",
            ["ContentKR"] = "응접실을 하나 지을까? 아니면 작은 부엌을 추가해 볼까?",
            ["DialogueId"] = 50104201,
            ["GUID"] = "7D6E3C7A",
            ["SpeakNpcId"] = 701048,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6E3C7A",
            },
        [50104301] = {
            ["Content"] = "爬到月亮上？咱们爬得上去吗？",
            ["ContentKR"] = "달 위로 올라가자고? 그게 되겠어?",
            ["DialogueId"] = 50104301,
            ["GUID"] = "7D6E4CE2",
            ["SpeakNpcId"] = 701050,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6E4CE2",
            },
        [50104401] = {
            ["Content"] = "嚯，这块千星板的年岁可真够久了！",
            ["ContentKR"] = "이야, 정말 오래된 천성판이네!",
            ["DialogueId"] = 50104401,
            ["GUID"] = "7D6E5D4A",
            ["SpeakNpcId"] = 701051,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6E5D4A",
            },
        [50104501] = {
            ["Content"] = "不以利丰为荣，以义为荣；不以豪奢为高，以德为高……",
            ["ContentKR"] = "이익보다 상도가 먼저다, 사치가 아닌 덕망을 중시하라...",
            ["DialogueId"] = 50104501,
            ["GUID"] = "7D6E6DB2",
            ["SpeakNpcId"] = 701052,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6E6DB2",
            },
        [50104601] = {
            ["Content"] = "如若对百年春业务相关有所疑问，可至此处问询。",
            ["ContentKR"] = "백년춘의 업무와 관련해 궁금한 점 있으시면 제게 문의해 주세요.",
            ["DialogueId"] = 50104601,
            ["GUID"] = "7D6E7E1A",
            ["SpeakNpcId"] = 701054,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6E7E1A",
            },
        [50104701] = {
            ["Content"] = "昨天到港的北风莓酱，怎么现在还没通过检查！快把货给我！",
            ["ContentKR"] = "아이스베리잼은 어제 도착했는데, 왜 아직도 통관을 안 시켜줘! 빨리 물건 달라고!",
            ["DialogueId"] = 50104701,
            ["GUID"] = "7D6E8E82",
            ["SpeakNpcId"] = 701057,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6E8E82",
            },
        [50104801] = {
            ["Content"] = "回家……可是，我的家又在哪里？这里……又是什么地方？",
            ["ContentKR"] = "집에 가야 하는데... 우리 집은 어디 있지? 여긴... 대체 어디야?",
            ["DialogueId"] = 50104801,
            ["GUID"] = "7D6E9EEA",
            ["SpeakNpcId"] = 701059,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6E9EEA",
            },
        [50104901] = {
            ["Content"] = "敕愿亡魂，早离迷茫，急急如律，往生乐乡……",
            ["ContentKR"] = "바라옵건대 모든 미혹을 떨치고, 극락왕생하소서...",
            ["DialogueId"] = 50104901,
            ["GUID"] = "7D6EAF52",
            ["SpeakNpcId"] = 701060,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6EAF52",
            },
        [50105001] = {
            ["Content"] = "如果爷爷回来看我的话，就让叶子落在我的头上吧！",
            ["ContentKR"] = "할아버지, 저 보러 돌아오셨으면 제 머리에 나뭇잎을 떨어뜨려 주세요!",
            ["DialogueId"] = 50105001,
            ["GUID"] = "7D6EBFBA",
            ["SpeakNpcId"] = 701061,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6EBFBA",
            },
        [50105101] = {
            ["Content"] = "这棵树，一直在说话！",
            ["ContentKR"] = "이 나무, 계속 말을 해!",
            ["DialogueId"] = 50105101,
            ["GUID"] = "7D6ED022",
            ["SpeakNpcId"] = 701063,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6ED022",
            },
        [50105201] = {
            ["Content"] = "你也是从外面过来的？",
            ["ContentKR"] = "그쪽도 밖에서 왔어요?",
            ["DialogueId"] = 50105201,
            ["GUID"] = "7D6EE08A",
            ["SpeakNpcId"] = 701065,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6EE08A",
            },
        [50105301] = {
            ["Content"] = "小鬼，微茫市可不是你随便乱逛的地方。",
            ["ContentKR"] = "이봐, 어스름 시장은 너 같은 꼬맹이가 함부로 돌아다녀도 될 곳이 아니야.",
            ["DialogueId"] = 50105301,
            ["GUID"] = "7D6EF0F2",
            ["SpeakNpcId"] = 701066,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6EF0F2",
            },
        [50105401] = {
            ["Content"] = "这缝儿得趁早补，再泡些日子，木芯都得烂透咯。",
            ["ContentKR"] = "조금 더 놔두면 속까지 썩어 문드러지겠군. 얼른 틈새를 메워야겠어.",
            ["DialogueId"] = 50105401,
            ["GUID"] = "7D6F015A",
            ["SpeakNpcId"] = 701067,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6F015A",
            },
        [50105501] = {
            ["Content"] = "呼……呼……",
            ["ContentKR"] = "쉬익... 쉬익...",
            ["DialogueId"] = 50105501,
            ["GUID"] = "7D6F11C2",
            ["SpeakNpcId"] = 701071,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6F11C2",
            },
        [50105601] = {
            ["Content"] = "一会冷一会热……想当年我太姥姥还跟我说，这里是个春暖花开的好地方呢！",
            ["ContentKR"] = "왜 이리 추웠다 더웠다 하는지... 증조할머니한테 듣기론, 옛날엔 꽃들이 활짝 핀 따뜻한 곳이라고 했는데!",
            ["DialogueId"] = 50105601,
            ["GUID"] = "7D6F222A",
            ["SpeakNpcId"] = 701072,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6F222A",
            },
        [50105701] = {
            ["Content"] = "就在这里点香，白龙神君一定会像神话里那样挺身而出，将那恶兽赶尽杀绝！",
            ["ContentKR"] = "여기서 향을 피우는 거야! 그러면 신화에서처럼 백룡신군께서 나타나 저 사악한 짐승들을 모두 처치해 주시겠지!",
            ["DialogueId"] = 50105701,
            ["GUID"] = "7D6F3292",
            ["SpeakNpcId"] = 701073,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6F3292",
            },
        [50105801] = {
            ["Content"] = "千星板运作情况一切正常，算算时间，马上要到下一次保养的日子了……",
            ["ContentKR"] = "천성판 작동 상태는 전부 이상 없군. 어디 보자, 이제 곧 다음 정비일인가...",
            ["DialogueId"] = 50105801,
            ["GUID"] = "7D6F42FA",
            ["SpeakNpcId"] = 701042,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6F42FA",
            },
        [50105901] = {
            ["Content"] = "龙老板，好久不见，新到的银针要尝尝吗，香的嘞~",
            ["ContentKR"] = "오랜만입니다, 용 사장. 새로 들어온 은침차 좀 들어요. 향이 참 좋아요.",
            ["DialogueId"] = 50105901,
            ["GUID"] = "7D6F5362",
            ["SpeakNpcId"] = 701055,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6F5362",
            },
        [50106001] = {
            ["Content"] = "到底是什么时候就在这里的呢？",
            ["ContentKR"] = "대체 언제부터 여기 있었던 걸까?",
            ["DialogueId"] = 50106001,
            ["GUID"] = "7D6F63CA",
            ["SpeakNpcId"] = 701062,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6F63CA",
            },
        [50106101] = {
            ["Content"] = "最近微茫市来了些新面孔，买卖时闲话许多，上不得台面。",
            ["ContentKR"] = "요즘 어스름 시장에 처음 보는 얼굴이 많던데, 거래할 때 쓸데없는 말이 너무 많아. 격 떨어지게.",
            ["DialogueId"] = 50106101,
            ["GUID"] = "7D6F7432",
            ["SpeakNpcId"] = 701068,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6F7432",
            },
        [50106201] = {
            ["Content"] = "下次和虬先生约见之时，定要选个风雅茶楼，而不是这种……",
            ["ContentKR"] = "다음에 규선생과 약속을 잡을 땐, 이런 데 말고 품격 있는 찻집에서 만나자고 해야겠어...",
            ["DialogueId"] = 50106201,
            ["GUID"] = "7D6F849A",
            ["SpeakNpcId"] = 701070,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6F849A",
            },
        [50106301] = {
            ["Content"] = "福运蛋上新款式啦，要不要来扭一发试试？",
            ["ContentKR"] = "새로운 황금알 경품이 들어왔어! 한번 뽑아볼래?",
            ["DialogueId"] = 50106301,
            ["Duration"] = 5,
            ["GUID"] = "7D6F9502",
            ["SpeakNpcId"] = 900012,
            },
        [50107001] = {
            ["Content"] = "我的钱袋子呢？我的钱袋子怎么不见了？",
            ["ContentKR"] = "내 돈주머니가 어디 갔지? 갑자기 어디로 사라진 거야?",
            ["DialogueId"] = 50107001,
            ["GUID"] = "7D7007DA",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7028AA",
            },
        [50107002] = {
            ["Content"] = "定是那油嘴滑舌的小贩子偷的！",
            ["ContentKR"] = "그 입만 산 행상인 녀석 짓이 틀림없어!",
            ["DialogueId"] = 50107002,
            ["GUID"] = "7D700804",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7028D4",
            },
        [50107003] = {
            ["Content"] = "诶？怎么就是找不到呢？",
            ["ContentKR"] = "어? 왜 아무리 찾아도 없지?",
            ["DialogueId"] = 50107003,
            ["GUID"] = "7D70082E",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7028FE",
            },
        [50107004] = {
            ["Content"] = "我早跟你说了这街上有贼，之前有人看到了，一个小女孩，皮肤黑黢黢的！",
            ["ContentKR"] = "그러게 내가 뭐랬어. 까무잡잡한 여자애가 물건 슬쩍하는 거 본 사람이 있대도!",
            ["DialogueId"] = 50107004,
            ["GUID"] = "7D700858",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702928",
            },
        [50107005] = {
            ["Content"] = "博山香行周年店庆，来店订购香料满十赠五~",
            ["ContentKR"] = "박산향료에서 창립 기념 행사 중이에요! 향료를 10개 사시면 5개 더 드려요~",
            ["DialogueId"] = 50107005,
            ["GUID"] = "7D700882",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702952",
            },
        [50107006] = {
            ["Content"] = "你要知道一点——我对香料品质的要求很高，晒得太干我不要，香味散得太过我也不要。",
            ["ContentKR"] = "잘 들어요. 난 품질에 까다로운 사람이라, 바짝 말라도 탈락, 향이 옅어도 탈락이에요.",
            ["DialogueId"] = 50107006,
            ["GUID"] = "7D7008AC",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70297C",
            },
        [50107007] = {
            ["Content"] = "之前定的那批香料，品质相当不错，这次就按原先的订单再来一批，还是送到我家中。",
            ["ContentKR"] = "저번에 그 향료, 꽤 괜찮더라고요. 이번에도 같은 걸로 할게요, 똑같이 집으로 보내 주세요.",
            ["DialogueId"] = 50107007,
            ["GUID"] = "7D7008D6",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7029A6",
            },
        [50107008] = {
            ["Content"] = "噫！好酸的果干！",
            ["ContentKR"] = "으아! 이거 왜 이렇게 셔!",
            ["DialogueId"] = 50107008,
            ["GUID"] = "7D700900",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7029D0",
            },
        [50107009] = {
            ["Content"] = "为什么没人来试试我做的糕点呢……难道是卖相不太好？可是味道很香呀……",
            ["ContentKR"] = "내 떡은 와서 먹어 보려는 사람도 없네... 모양이 별론가? 향은 정말 좋은데...",
            ["DialogueId"] = 50107009,
            ["GUID"] = "7D70092A",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7029FA",
            },
        [50107010] = {
            ["Content"] = "华胥特色小吃，吃一口念一年！",
            ["ContentKR"] = "화서 명물 간식 사세요! 자꾸자꾸 생각나는 맛이랍니다!",
            ["DialogueId"] = 50107010,
            ["GUID"] = "7D700954",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702A24",
            },
        [50107011] = {
            ["Content"] = "各色果干，酸甜可口，欢迎试吃品尝~",
            ["ContentKR"] = "맛있는 건과일 사세요! 달콤하고 맛있어요! 편히 맛보고 가세요~",
            ["DialogueId"] = 50107011,
            ["GUID"] = "7D70097E",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702A4E",
            },
        [50107012] = {
            ["Content"] = "那里曾是家布鞋店，现在却已经改成了木雕摊……东市啊，大变样咯！",
            ["ContentKR"] = "신발 가게 자리였는데, 이젠 나무 조각상을 파네... 동문 시장도 많이 변했구나!",
            ["DialogueId"] = 50107012,
            ["GUID"] = "7D7009A8",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702A78",
            },
        [50107013] = {
            ["Content"] = "这位客人，看你身材匀称，要不要来试试我们千绣阁里的成衣？",
            ["ContentKR"] = "손님, 옷태가 너무 좋으신데요? 저희 천수각 옷 한 번 입어 보시겠어요?",
            ["DialogueId"] = 50107013,
            ["GUID"] = "7D7009D2",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702AA2",
            },
        [50107014] = {
            ["Content"] = "同福饭馆菜品上新，外域高人指点，香料入菜，佳肴更添新风味。",
            ["ContentKR"] = "동복반점에 새 메뉴 등장이요! 이국적인 향료를 넣어 새로운 풍미를 더했어요!",
            ["DialogueId"] = 50107014,
            ["GUID"] = "7D7009FC",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702ACC",
            },
        [50107015] = {
            ["Content"] = "香料做菜？听起来奇奇怪怪的，这做出来的东西能好吃吗？",
            ["ContentKR"] = "향료로 요리를 한다고? 별 이상한 소릴 다 듣네. 그런 게 맛이나 있겠어?",
            ["DialogueId"] = 50107015,
            ["GUID"] = "7D700A26",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702AF6",
            },
        [50107016] = {
            ["Content"] = "同福饭馆的厨子发了疯，居然把莞婆娘碾碎包进丸子里！",
            ["ContentKR"] = "동복반점 주방장이 미쳤나 봐. 완자에다 왕골을 갈아 넣었대!",
            ["DialogueId"] = 50107016,
            ["GUID"] = "7D700A50",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702B20",
            },
        [50107017] = {
            ["Content"] = "一天到晚就知道折腾看似新颖实则无用的花招，可别忘了华胥美食的精髓是什么！",
            ["ContentKR"] = "쓸데없이 겉멋만 잔뜩 들어 가지고는. 화서 요리의 근본이 뭔지 잊지 말라고!",
            ["DialogueId"] = 50107017,
            ["GUID"] = "7D700A7A",
            ["SpeakNpcId"] = 701266,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702B4A",
            },
        [50107018] = {
            ["Content"] = "秀芳……不要离开我……秀芳……",
            ["ContentKR"] = "수향아... 날 떠나지 마... 수향아...",
            ["DialogueId"] = 50107018,
            ["GUID"] = "7D700AA4",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702B74",
            },
        [50107019] = {
            ["Content"] = "把翠屏雀搬来了皓京城？！还有此等奇事！",
            ["ContentKR"] = "호경에 초록 공작새를 데려왔다고?! 살다 보니 별일이 다 있네!",
            ["DialogueId"] = 50107019,
            ["GUID"] = "7D700ACE",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702B9E",
            },
        [50107020] = {
            ["Content"] = "雀翎茗轩……是在这里吗？",
            ["ContentKR"] = "작영루가... 여기 맞나?",
            ["DialogueId"] = 50107020,
            ["GUID"] = "7D700AF8",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702BC8",
            },
        [50107021] = {
            ["Content"] = "东市雀翎茗轩开张，凡携亲眷者入座，皆送花茶一壶。",
            ["ContentKR"] = "동문 시장에 작영루가 문을 열었어요! 가족들과 오셔서 무료로 꽃차 드시고 가세요!",
            ["DialogueId"] = 50107021,
            ["GUID"] = "7D700B22",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702BF2",
            },
        [50107022] = {
            ["Content"] = "呜呜……龙君不公啊！这茶舍还未开张，怎料运来的雀儿都不见踪影，我该如何是好……",
            ["ContentKR"] = "흑흑... 용신님도 너무하셔! 찻집 개업이 코앞인데 새들이 다 어디 갔담. 난 이제 어떡해...",
            ["DialogueId"] = 50107022,
            ["GUID"] = "7D700B4C",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702C1C",
            },
        [50107023] = {
            ["Content"] = "游船游船，十文一趟，排队购票，客满即发。",
            ["ContentKR"] = "유람선~ 뱃놀이~ 단돈 열 냥! 줄 서서 표부터 사세요, 자리 차면 출발합니다!",
            ["DialogueId"] = 50107023,
            ["GUID"] = "7D700B76",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702C46",
            },
        [50107024] = {
            ["Content"] = "这皓京城的地形，怎么看怎么觉得邪乎呢……",
            ["ContentKR"] = "호경의 지형은, 아무리 봐도 좀 찜찜한 구석이 있단 말이지...",
            ["DialogueId"] = 50107024,
            ["GUID"] = "7D700BA0",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702C70",
            },
        [50107025] = {
            ["Content"] = "想当初咱这湖边多清净？钓竿一放，不消半个时辰就能钓上好几尾大鱼。",
            ["ContentKR"] = "여긴 옛날이 한적하고 좋았는데! 낚싯대만 툭 던지면 월척이 쑥쑥 낚였거든.",
            ["DialogueId"] = 50107025,
            ["GUID"] = "7D700BCA",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702C9A",
            },
        [50107026] = {
            ["Content"] = "若是能把这五禽戏练好，你平日的那些小病小灾，都可一并消弭！",
            ["ContentKR"] = "이 건강 체조만 제대로 따라하면, 평소에 잔병치레로 고생할 일은 싹 없어져!",
            ["DialogueId"] = 50107026,
            ["GUID"] = "7D700BF4",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702CC4",
            },
        [50107027] = {
            ["Content"] = "他们还真把那五禽戏当真了不成？",
            ["ContentKR"] = "저 사람들은 저 건강 체조를 진짜로 믿는 건가?",
            ["DialogueId"] = 50107027,
            ["GUID"] = "7D700C1E",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702CEE",
            },
        [50107028] = {
            ["Content"] = "自己要早起练功也便罢了，为何还要拖着我早起……呵欠……",
            ["ContentKR"] = "운동할 거면 자기나 일찍 일어날 것이지, 왜 나까지 끌고 나와서...",
            ["DialogueId"] = 50107028,
            ["GUID"] = "7D700C48",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702D18",
            },
        [50107029] = {
            ["Content"] = "这皓京城还没有我说不成的媒！",
            ["ContentKR"] = "내가 이 호경에서 성사 못 시킨 결혼은 한 번도 없어!",
            ["DialogueId"] = 50107029,
            ["GUID"] = "7D700C72",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702D42",
            },
        [50107030] = {
            ["Content"] = "我这般主动找人说亲，会不会……被他看出来了？",
            ["ContentKR"] = "제 쪽에서 먼저 중매 부탁한 거, 혹시라도... 그 사람이 눈치채진 않겠죠?",
            ["DialogueId"] = 50107030,
            ["GUID"] = "7D700C9C",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702D6C",
            },
        [50107031] = {
            ["Content"] = "咱皓京人，除了吃就是喝，没别的~",
            ["ContentKR"] = "우리 호경 사람들은, 먹고 마시는 재미로 사는 거 아니겠나~",
            ["DialogueId"] = 50107031,
            ["GUID"] = "7D700CC6",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702D96",
            },
        [50107032] = {
            ["Content"] = "瞧你这孩子，走起路来慌慌张张，留心点别踩到路上的石子了！",
            ["ContentKR"] = "얘, 그렇게 다니다간 넘어져. 돌부리에 발 걸리지 않게 조심해!",
            ["DialogueId"] = 50107032,
            ["GUID"] = "7D700CF0",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702DC0",
            },
        [50107033] = {
            ["Content"] = "什么？涨了这么多？我没看错吧？",
            ["ContentKR"] = "네? 값이 이렇게 올랐다고요? 제가 숫자 잘못 본 거 아니죠?",
            ["DialogueId"] = 50107033,
            ["GUID"] = "7D700D1A",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702DEA",
            },
        [50107034] = {
            ["Content"] = "父亲向来放不下娘亲，想必在天上也是不愿看见娘亲落泪的。",
            ["ContentKR"] = "아버지는 늘 어머니 걱정뿐이라, 하늘에서 어머니 우시는 거 보면 속상하실 거예요.",
            ["DialogueId"] = 50107034,
            ["GUID"] = "7D700D44",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702E14",
            },
        [50107035] = {
            ["Content"] = "现在都什么年代了，哪有在丧礼上请乐队的人家！",
            ["ContentKR"] = "언제 적 말씀을 하세요. 요즘 누가 장례 치르면서 악단을 불러요!",
            ["DialogueId"] = 50107035,
            ["GUID"] = "7D700D6E",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702E3E",
            },
        [50107036] = {
            ["Content"] = "林兄，昔日你我诗会相逢，一见如故。高山流水，难遇知音，这杯，我敬你！",
            ["ContentKR"] = "임형, 우린 처음부터 마음이 통했죠. 절 알아주는 건 형님뿐이었어요. 형님, 이 잔 받으세요!",
            ["DialogueId"] = 50107036,
            ["GUID"] = "7D700D98",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702E68",
            },
        [50107037] = {
            ["Content"] = "草木深胡同……是在这里？还是……",
            ["ContentKR"] = "초목정 골목이... 여기였나? 아니면...",
            ["DialogueId"] = 50107037,
            ["GUID"] = "7D700DC2",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702E92",
            },
        [50107038] = {
            ["Content"] = "你说那家私房菜？我是听说过，但那家地方小，难订座，现下去问恐怕是吃不上了。",
            ["ContentKR"] = "그 특선 요릿집 말이지? 얘기는 들었는데, 가게가 워낙 작아서 지금 가도 허탕만 칠걸.",
            ["DialogueId"] = 50107038,
            ["GUID"] = "7D700DEC",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702EBC",
            },
        [50107039] = {
            ["Content"] = "若非有仙人指路，怎知这小巷深处竟藏着这庖厨圣地！",
            ["ContentKR"] = "골목 안쪽에 이런 맛집이 숨어 있는 걸 이제야 알았네! 이게 다 신령님 덕분이야!",
            ["DialogueId"] = 50107039,
            ["GUID"] = "7D700E16",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702EE6",
            },
        [50107040] = {
            ["Content"] = "老张啊，你那只八哥，今日居然念了几句诗，是不是你孙子整日在家背书被它听着学了去？",
            ["ContentKR"] = "장 영감, 자네 집 구관조가 웬일로 시를 읊더군. 손주 녀석이 하도 글을 외워대니 귀동냥으로 배운 건가 보지?",
            ["DialogueId"] = 50107040,
            ["GUID"] = "7D700E40",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702F10",
            },
        [50107041] = {
            ["Content"] = "凡夫俗子溜凡羽俗鸟，他们那些鸟，能有我这只厉害吗？",
            ["ContentKR"] = "어중이떠중이들한테 딱 맞는 허접한 새들이군. 우리 새 발끝도 못 쫓아올걸?",
            ["DialogueId"] = 50107041,
            ["GUID"] = "7D700E6A",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702F3A",
            },
        [50107042] = {
            ["Content"] = "车三进六，将军！老友，这局棋，你该怎么破？",
            ["ContentKR"] = "차를 이렇게 옮기면, 장군! 자, 이 외통수를 무슨 수로 막을 건가?",
            ["DialogueId"] = 50107042,
            ["GUID"] = "7D700E94",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702F64",
            },
        [50107043] = {
            ["Content"] = "叫上陈老太太，咱们也在家里聚上一聚，打打骨牌？",
            ["ContentKR"] = "진씨 할멈도 불러서, 다 같이 우리 집에서 골패 놀이나 할까?",
            ["DialogueId"] = 50107043,
            ["GUID"] = "7D700EBE",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702F8E",
            },
        [50107044] = {
            ["Content"] = "我看你是蹬鼻子上脸，三天不打上房揭瓦！给我回去复习功课！",
            ["ContentKR"] = "오냐오냐했더니 아주 그냥! 언제까지 봐 줄 줄 알아! 얼른 들어가서 복습해!",
            ["DialogueId"] = 50107044,
            ["GUID"] = "7D700EE8",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702FB8",
            },
        [50107045] = {
            ["Content"] = "我来了！不好意思，今天翻墙出来被阿娘逮到了……",
            ["ContentKR"] = "늦어서 미안! 담 넘다가 엄마한테 딱 걸려가지고...",
            ["DialogueId"] = 50107045,
            ["GUID"] = "7D700F12",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702FE2",
            },
        [50107046] = {
            ["Content"] = "三……二……一……躲好了吗？无由生马上要出来抓你们咯？",
            ["ContentKR"] = "하나... 둘... 셋... 다 숨었어? 이제 무유생이 잡으러 간다?",
            ["DialogueId"] = 50107046,
            ["GUID"] = "7D700F3C",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70300C",
            },
        [50107047] = {
            ["Content"] = "今年的税账至今还在统计之中，明年的汇算眼见着也要来了……真是忙到头晕眼花。",
            ["ContentKR"] = "올해 세금 계산은 언제 다 하지. 내년 결산도 코앞인데... 이러다 진짜 쓰러질 것 같아.",
            ["DialogueId"] = 50107047,
            ["GUID"] = "7D700F66",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703036",
            },
        [50107048] = {
            ["Content"] = "昨夜通宵整理典籍，今日双眼昏花，恐一蹬腿就要去往虞泉了！",
            ["ContentKR"] = "밤샘 작업하느라 눈이 침침하네. 이러다 픽 쓰러져서 우천에 가 버리겠어!",
            ["DialogueId"] = 50107048,
            ["GUID"] = "7D700F90",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703060",
            },
        [50107049] = {
            ["Content"] = "奉香大典意味着什么？意味着休假呀！我一直想去海伯利亚看雪……",
            ["ContentKR"] = "봉향대전이 무슨 뜻이냐고? 쉬.는.날! 내 꿈은 휘페르보레아 가서 눈 구경하는 거야...",
            ["DialogueId"] = 50107049,
            ["GUID"] = "7D700FBA",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70308A",
            },
        [50107050] = {
            ["Content"] = "这般数据出现在这栏不太应当，莫非是填错了？",
            ["ContentKR"] = "여기에 이런 숫자가 나올 리 없는데. 설마 어디가 잘못 됐나?",
            ["DialogueId"] = 50107050,
            ["GUID"] = "7D700FE4",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7030B4",
            },
        [50107051] = {
            ["Content"] = "最近的日子，真是难得的清闲啊~",
            ["ContentKR"] = "요즘 참 살맛 나네~ 이렇게 한가한 게 얼마 만이냐~",
            ["DialogueId"] = 50107051,
            ["GUID"] = "7D70100E",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7030DE",
            },
        [50107052] = {
            ["Content"] = "下次遇到这种事情记得早些来泉通司，硬拖只会让事态恶化。",
            ["ContentKR"] = "늑장 부리면 상황만 악화되니까, 다음부턴 이런 일 생기면 바로 천통사로 오세요.",
            ["DialogueId"] = 50107052,
            ["GUID"] = "7D701038",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703108",
            },
        [50107053] = {
            ["Content"] = "祀香阁今年为何额外申请了一笔经费，是作何用处的？",
            ["ContentKR"] = "사연각에서 올해 예산을 더 신청했더군. 어디에 쓰려는 건가?",
            ["DialogueId"] = 50107053,
            ["GUID"] = "7D701062",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703132",
            },
        [50107054] = {
            ["Content"] = "搭台子，修香炉，后续还有各种开销，我都递交申请了，只是拨款何时能来？",
            ["ContentKR"] = "단상도 세우고, 향로도 고치고... 돈 들어갈 데가 많아요. 신청은 했는데, 예산은 언제 나온대요?",
            ["DialogueId"] = 50107054,
            ["GUID"] = "7D70108C",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70315C",
            },
        [50107055] = {
            ["Content"] = "是，就是往西郊那个方向，鬼鬼祟祟的，看起来不像什么好人。",
            ["ContentKR"] = "네, 서쪽 교외 방향 맞아요. 행동거지가 영 수상한 게, 딱 봐도 나쁜 놈 같더라고요.",
            ["DialogueId"] = 50107055,
            ["GUID"] = "7D7010B6",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703186",
            },
        [50107056] = {
            ["Content"] = "西郊西郊西郊，为何几封投诉信，来来回回都在提西郊？",
            ["ContentKR"] = "그놈의 서쪽 교외, 귀에 딱지 앉겠네! 민원만 들어왔다 하면 왜 죄다 서쪽 교외지?",
            ["DialogueId"] = 50107056,
            ["GUID"] = "7D7010E0",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7031B0",
            },
        [50107057] = {
            ["Content"] = "快给我来碗茶水，刚从西郊回来，渴死我了！",
            ["ContentKR"] = "얼른 차 한 잔 주세요! 서쪽 교외까지 갔다 오느라, 목말라 죽겠어요!",
            ["DialogueId"] = 50107057,
            ["GUID"] = "7D70110A",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7031DA",
            },
        [50107058] = {
            ["Content"] = "嗯，是说您负责运输的一船货物在码头丢失了……不是货物？那是……翠屏雀？！",
            ["ContentKR"] = "네, 그러니까 담당한 화물이 부두에서 분실됐다는... 네? 화물이 아니라... 초록 공작새라고요?!",
            ["DialogueId"] = 50107058,
            ["GUID"] = "7D701134",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703204",
            },
        [50107059] = {
            ["Content"] = "它到底是怎么跑出去的呢？",
            ["ContentKR"] = "대체 어떻게 빠져나간 거지?",
            ["DialogueId"] = 50107059,
            ["GUID"] = "7D70115E",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70322E",
            },
        [50107060] = {
            ["Content"] = "找不回来了……一切努力都付之东流了……",
            ["ContentKR"] = "못 찾아... 열심히 노력한 게 다 물거품이 됐어...",
            ["DialogueId"] = 50107060,
            ["GUID"] = "7D701188",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703258",
            },
        [50107061] = {
            ["Content"] = "已经找到一只了？在民居的屋顶上？到底是怎么飞上去的？！",
            ["ContentKR"] = "한 마리는 찾았다고? 남의 집 지붕에 있었어? 대체 거긴 어떻게 올라간 거야?!",
            ["DialogueId"] = 50107061,
            ["GUID"] = "7D7011B2",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703282",
            },
        [50107062] = {
            ["Content"] = "千绣阁今年的订货量又涨了许多，咱们的绣品在皓京城里很受欢迎呢~",
            ["ContentKR"] = "올해는 주문이 훨씬 늘었군. 역시 우리 천수각 수예품은 호경에서 인기 최고지~",
            ["DialogueId"] = 50107062,
            ["GUID"] = "7D7011DC",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7032AC",
            },
        [50107063] = {
            ["Content"] = "此趟运输甜果只有百分之三损毁？甚好甚好~",
            ["ContentKR"] = "이번엔 운송 도중에 멍든 과일이 겨우 100개 중에 3개 꼴이라고? 훌륭한데~",
            ["DialogueId"] = 50107063,
            ["GUID"] = "7D701206",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7032D6",
            },
        [50107064] = {
            ["Content"] = "太皓神君的纹样大家早就看腻啦~一点新意也没有。",
            ["ContentKR"] = "태호님 무늬는 이제 지겨운데~ 뻔하고 식상해.",
            ["DialogueId"] = 50107064,
            ["GUID"] = "7D701230",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703300",
            },
        [50107065] = {
            ["Content"] = "各位好姐姐好哥哥们，现在呢就已经到了咱们皓京，也是咱们华胥呢，最繁华的地方~",
            ["ContentKR"] = "여러분~ 드디어 호경에 도착하셨어요! 여기는요~ 우리 화서에서 제~일 번화한 곳이에요~",
            ["DialogueId"] = 50107065,
            ["GUID"] = "7D70125A",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70332A",
            },
        [50107066] = {
            ["Content"] = "三百九十九？！皓京三天两晚包吃包住包来回船票只需要三百九十九？",
            ["ContentKR"] = "399냥이라고?! 숙식에 왕복 뱃삯까지 포함된 2박 3일 호경 여행이 겨우 399냥?!",
            ["DialogueId"] = 50107066,
            ["GUID"] = "7D701284",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703354",
            },
        [50107067] = {
            ["Content"] = "恁大一个皓京城，比我屋头看着气派多了哟！",
            ["ContentKR"] = "호경은 허벌나게 크구마잉! 우리 집구석하곤 때깔부터 달라부러!",
            ["DialogueId"] = 50107067,
            ["GUID"] = "7D7012AE",
            ["SpecialConversation"] = "偏川普",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70337E",
            },
        [50107068] = {
            ["Content"] = "别靠过来！我……呕……我……头好晕……怎么有三个太阳……呕！",
            ["ContentKR"] = "가까이 오지 마! 나... 우욱... 머리가... 어지러워... 해가 왜 3개지... 욱!",
            ["DialogueId"] = 50107068,
            ["GUID"] = "7D7012D8",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7033A8",
            },
        [50107069] = {
            ["Content"] = "水龙车我先带走了。不知道哪个龟孙以为是普通木桶，居然往里面放香油，被老鼠啃得面目全非。",
            ["ContentKR"] = "수총기는 일단 회수하겠습니다. 어떤 얼간이가 여기다 참기름을 넣는 바람에, 쥐들이 다 갉아먹어서 엉망이 됐어요.",
            ["DialogueId"] = 50107069,
            ["GUID"] = "7D701302",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7033D2",
            },
        [50107070] = {
            ["Content"] = "匠矩阁的师傅已经来将水龙车全部取走了吗？太麻烦他们了。",
            ["ContentKR"] = "수총기는 장구각 쪽 분들이 벌써 다 가져가셨나요? 괜히 폐만 끼쳐 드렸네요.",
            ["DialogueId"] = 50107070,
            ["GUID"] = "7D70132C",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7033FC",
            },
        [50107071] = {
            ["Content"] = "为何匠矩阁的人回回要来参商港跑个好几趟，来回拉扯不嫌麻烦吗？",
            ["ContentKR"] = "장구각 사람들은 왜 매번 고생스럽게 삼상항까지 오는 거야? 왔다 갔다 귀찮지도 않나?",
            ["DialogueId"] = 50107071,
            ["GUID"] = "7D701356",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703426",
            },
        [50107072] = {
            ["Content"] = "凌波微步，且看我腾空起，驾云去，身似飞雁过南关，蜻蜓点水不留痕！嘿！哈！",
            ["ContentKR"] = "능파미보! 구름 위를 노니는 날쌘 기러기처럼! 고요히 물 위를 스치는 잠자리처럼! 이야압!",
            ["DialogueId"] = 50107072,
            ["GUID"] = "7D701380",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703450",
            },
        [50107073] = {
            ["Content"] = "天一热，潮一涨，这浸在水中的部分就开始疯狂长苔，转动都费劲……",
            ["ContentKR"] = "날이 더워져서 물이 불어나면, 이 물에 잠긴 부분에 이끼가 잔뜩 껴서 돌아가질 않아...",
            ["DialogueId"] = 50107073,
            ["GUID"] = "7D7013AA",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70347A",
            },
        [50107074] = {
            ["Content"] = "要不是他们把水车停了下来，怎会有这多事端？",
            ["ContentKR"] = "잘만 돌아가는 물레방아를 저 사람들이 괜히 건드려서, 이 난리가 난 거 아닙니까?",
            ["DialogueId"] = 50107074,
            ["GUID"] = "7D7013D4",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7034A4",
            },
        [50107075] = {
            ["Content"] = "你需谨记六字——明法、公心、勤谨。",
            ["ContentKR"] = "이 3가지를 기억하세요. 규칙 엄수, 공사 구분, 근면 성실.",
            ["DialogueId"] = 50107075,
            ["GUID"] = "7D7013FE",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7034CE",
            },
        [50107076] = {
            ["Content"] = "每至夜半三更，船舶抵港，那船工吆喝声、铁链撞击声、货箱搬运声，直吵得人不得安睡！",
            ["ContentKR"] = "밤마다 배가 들어오면, 뱃사람들이 고함 지르지, 쇠사슬 쩔그럭거리지, 짐 옮긴다고 쿵쾅대지! 도대체 잠을 못 자겠어!",
            ["DialogueId"] = 50107076,
            ["GUID"] = "7D701428",
            ["SpecialConversation"] = "该npc为一期印象npc",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7034F8",
            },
        [50107077] = {
            ["Content"] = "游船游船，十文一趟，排队购票，客满即发。",
            ["ContentKR"] = "유람선~ 뱃놀이~ 단돈 열 냥! 줄 서서 표부터 사세요, 자리 차면 출발합니다!",
            ["DialogueId"] = 50107077,
            ["GUID"] = "7D701452",
            ["SpecialConversation"] = "该npc与刘福最好为一人",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703522",
            },
        [50107078] = {
            ["Content"] = "稍……稍等一下……我查一下刚买的《华胥问候语录大全》。",
            ["ContentKR"] = "자, 잠시만요... 조, 조금 전에 산... 〈화서 인사말 대백과〉를 차자 볼게요.",
            ["DialogueId"] = 50107078,
            ["GUID"] = "7D70147C",
            ["SpecialConversation"] = "外国人",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70354C",
            },
        [50107079] = {
            ["Content"] = "他大舅母，晚上做了什么好吃的？可是来这儿散散步，消消食？",
            ["ContentKR"] = "호경댁, 저녁은 드셨수? 소화도 시킬 겸 산책 나오셨나 봐?",
            ["DialogueId"] = 50107079,
            ["GUID"] = "7D7014A6",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703576",
            },
        [50107080] = {
            ["Content"] = "一，二，三，铁柱呢？铁柱为何不在？你们来的时候看到他了吗？",
            ["ContentKR"] = "하나, 둘, 셋, 철주는? 철주는 어디 갔어? 너흰 오는 길에 못 봤어?",
            ["DialogueId"] = 50107080,
            ["GUID"] = "7D7014D0",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7035A0",
            },
        [50107081] = {
            ["Content"] = "尘香袅袅龙君现，典前争辉竞纷纭。奉香大典特别活动——灯谜会，待君赏玩！",
            ["ContentKR"] = "용신님이 강림하시는 화려한 축제의 장! 봉향대전 특별 이벤트... 등불 퀴즈 대회가, 여러분을 찾아갑니다!",
            ["DialogueId"] = 50107081,
            ["GUID"] = "7D7014FA",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7035CA",
            },
        [50107082] = {
            ["Content"] = "妈妈我到皓京了……",
            ["ContentKR"] = "어머니, 저 호경에 왔어요...",
            ["DialogueId"] = 50107082,
            ["GUID"] = "7D701524",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7035F4",
            },
        [50107083] = {
            ["Content"] = "这里面不能进去吗？我买票也不行？那有什么办法能进去看看？我想见白龙神君。",
            ["ContentKR"] = "못 들어간다는 게 말이 돼요? 표 사겠다니까요? 그럼 어떻게 들어가란 거예요? 난 백룡신군님을 뵙고 싶다고요.",
            ["DialogueId"] = 50107083,
            ["GUID"] = "7D70154E",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70361E",
            },
        [50107084] = {
            ["Content"] = "你看！只要内心足够虔诚，望向执律阁顶之时，就会看到白龙神君在云间遨游。",
            ["ContentKR"] = "저길 보렴! 착한 마음으로 집률각 꼭대기를 보면, 구름 속을 날아다니시는 백룡신군님이 보일 거야.",
            ["DialogueId"] = 50107084,
            ["GUID"] = "7D701578",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703648",
            },
        [50107085] = {
            ["Content"] = "朝报朝报，茶不思饭不想只想看朝报，皓京独家新闻，绝对真实绝对劲爆！",
            ["ContentKR"] = "신문 사세요~ 밥보다 좋은 신문이요~ 진짜배기 호경 독점 기사를 만나보세요!",
            ["DialogueId"] = 50107085,
            ["GUID"] = "7D7015A2",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703672",
            },
        [50107086] = {
            ["Content"] = "这字乍一看好似和海伯利亚那边没什么区别，可凑在一起为什么完全看不懂……",
            ["ContentKR"] = "휘페르보레아에서 쓰는 글자랑 닮긴 했는데, 합쳐 놓으니까 무슨 소린지 전혀 모르겠네...",
            ["DialogueId"] = 50107086,
            ["GUID"] = "7D7015CC",
            ["SpecialConversation"] = "外国人",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70369C",
            },
        [50107087] = {
            ["Content"] = "您听我说，您去一个地方，吃什么玩什么，都是次要，主要的是要来感受当地的氛围，您说对不对？",
            ["ContentKR"] = "그러니까, 여행 가서 먹고 노는 것도 중요하지만, 그보다 더 중요한 건, 그 지역 분위기에 흠뻑 취하는 거죠. 안 그래요?",
            ["DialogueId"] = 50107087,
            ["GUID"] = "7D7015F6",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7036C6",
            },
        [50107088] = {
            ["Content"] = "退一万步说，在人家办事处门口宣传这些也不合适吧……",
            ["ContentKR"] = "아무리 그래도 그렇지, 남들 일하는 사무실 문앞까지 와서 광고하시는 건 좀 아니지요...",
            ["DialogueId"] = 50107088,
            ["GUID"] = "7D701620",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7036F0",
            },
        [50107089] = {
            ["Content"] = "我家老婆子好好地走在街上，他路也不看，直接推着车撞了过来。",
            ["ContentKR"] = "내 아내는 얌전히 길 가던 죄밖에 없어. 저 인간이 앞도 안 보고 수레로 그냥 들이받은 거라고!",
            ["DialogueId"] = 50107089,
            ["GUID"] = "7D70164A",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70371A",
            },
        [50107090] = {
            ["Content"] = "以香论道法，坐实众生象，天地为共生，万物与我一……",
            ["ContentKR"] = "향으로 도를 말하고 세상의 참모습을 깨우치니, 천지와 공존하고 만물과 하나가 되리라...",
            ["DialogueId"] = 50107090,
            ["GUID"] = "7D701674",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703744",
            },
        [50107091] = {
            ["Content"] = "为人在世，奉天命当如沙洲，勤而学当如竹溪先生。",
            ["ContentKR"] = "하늘의 명은 서주처럼 받들어야 하고, 배움의 자세는 죽계 선생을 본받아야 합니다.",
            ["DialogueId"] = 50107091,
            ["GUID"] = "7D70169E",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70376E",
            },
        [50107092] = {
            ["Content"] = "我何时曾说我亲眼见过竹溪先生？我说的是父亲年幼之时，曾在学院听竹溪先生传授最后一课。",
            ["ContentKR"] = "언제 내가 죽계 선생을 직접 뵀다고 했나? 아버지께서 어린 시절에, 서당에서 그분의 마지막 강의를 들었다고 했지.",
            ["DialogueId"] = 50107092,
            ["GUID"] = "7D7016C8",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703798",
            },
        [50107093] = {
            ["Content"] = "吵死了……这怎么让人背书！",
            ["ContentKR"] = "시끄러 죽겠네, 진짜... 뭘 어떻게 외우란 거야!",
            ["DialogueId"] = 50107093,
            ["GUID"] = "7D7016F2",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7037C2",
            },
        [50107094] = {
            ["Content"] = "所谓理一，即天地万物都只有一个理，所谓分殊，即千差万殊的事物都是一个理的体现。",
            ["ContentKR"] = "'이일'이란, 천지 만물의 이치는 오직 하나라는 것이다. '분수'란, 만물은 모두 하나의 이치의 표상이라는 것이지.",
            ["DialogueId"] = 50107094,
            ["GUID"] = "7D70171C",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7037EC",
            },
        [50107095] = {
            ["Content"] = "五味万殊，而大同于美；曲变虽众，亦大同于和；子性各异，但大同于敏；教术众多，然大同于情。",
            ["ContentKR"] = "다양한 맛도 결국은 '아름다움'이라는 가치로 귀결되고, 수많은 곡조들은 '조화'라는 울림으로 수렴하게 되죠.",
            ["DialogueId"] = 50107095,
            ["GUID"] = "7D701746",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703816",
            },
        [50107096] = {
            ["Content"] = "这万事万物，道理总是只有一个，但一个道理却可涵盖了世间万物，所以理一定是在前面的！",
            ["ContentKR"] = "만물의 이치는 하나지만, 그 하나의 이치가 삼라만상을 품고 있습니다. 그래서 이치가 우선인 겁니다!",
            ["DialogueId"] = 50107096,
            ["GUID"] = "7D701770",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703840",
            },
        [50107097] = {
            ["Content"] = "今天该轮到你执勤了吧，之前你说你娘风寒，我可帮你顶了三天，夫子都起疑了！",
            ["ContentKR"] = "오늘은 네가 당번 서. 저번에 너희 엄마 아프다길래 내가 사흘이나 대신해 줬잖아. 이러다 훈장님한테 들켜!",
            ["DialogueId"] = 50107097,
            ["GUID"] = "7D70179A",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70386A",
            },
        [50107098] = {
            ["Content"] = "奉香大典期间放假，你们都去哪玩？我哥从外地回来了，说要给我带外国的新奇玩具呢。",
            ["ContentKR"] = "봉향대전 때 너네 어디 놀러 갈 거야? 난 이번에 외국 나갔던 형이 돌아오는데, 엄청 신기한 장난감 사다 준댔다~",
            ["DialogueId"] = 50107098,
            ["GUID"] = "7D7017C4",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703894",
            },
        [50107099] = {
            ["Content"] = "下午的蹴球赛，咱们队还差一人，你问过樾山哥没有？他要是肯来，咱们定能踢得对面满地找牙！",
            ["ContentKR"] = "축국 시합에 나갈 사람이 하나 모자란데, 월산이 형한테 부탁해 봤어? 그 형만 껴 주면 우리가 무조건 이기는데!",
            ["DialogueId"] = 50107099,
            ["GUID"] = "7D7017EE",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7038BE",
            },
        [50107100] = {
            ["Content"] = "按这个势头算下去，岂不是又要扩张？可这又还能往哪里扩呢？",
            ["ContentKR"] = "이 속도라면 당연히 규모를 키워야겠지? 그런데 주변에 남는 땅이 없잖아?",
            ["DialogueId"] = 50107100,
            ["GUID"] = "7D701818",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7038E8",
            },
        [50107101] = {
            ["Content"] = "是了，来年开春便要递上辞函，到时候自然是会念着大家的，放心！",
            ["ContentKR"] = "그래, 내년 봄엔 은퇴할 거야. 그만두고 나서도 다들 꼭 기억할 테니, 걱정 마!",
            ["DialogueId"] = 50107101,
            ["GUID"] = "7D701842",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703912",
            },
        [50107102] = {
            ["Content"] = "若华胥的安宁和平需要人们以不同的努力去守护，那为何飘零人的行为不能算是一种独特的方式？",
            ["ContentKR"] = "다들 각자의 방식으로 화서를 지키는 거라면, 나그네들의 방식도 그중 하나로 인정해 줘야 하는 거 아닌가요?",
            ["DialogueId"] = 50107102,
            ["GUID"] = "7D70186C",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70393C",
            },
        [50107103] = {
            ["Content"] = "好啊，今天的辩题有趣，我在学院许久没见过这么有意思的辩题了。",
            ["ContentKR"] = "이야, 오늘 토론 주제 재밌네. 간만에 학당에 흥미진진한 주제가 올라왔군.",
            ["DialogueId"] = 50107103,
            ["GUID"] = "7D701896",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703966",
            },
        [50107104] = {
            ["Content"] = "空口说白话，不亚于纸上谈兵。有这闲工夫，不如多读些书！",
            ["ContentKR"] = "입으로만 떠들어대 봐야 무슨 소용이 있느냐. 그럴 시간 있으면, 책이나 한 자 더 읽어라!",
            ["DialogueId"] = 50107104,
            ["GUID"] = "7D7018C0",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703990",
            },
        [50107105] = {
            ["Content"] = "椒兰村的香料自然是地道，处理方式也多样，只是要论品质，外面的许多园子都不遑多让。",
            ["ContentKR"] = "초란 마을은 향료의 본고장이죠. 가공법도 다양하고요. 하지만 품질만 놓고 보면, 다른 고장 것들도 꽤 훌륭해요.",
            ["DialogueId"] = 50107105,
            ["GUID"] = "7D7018EA",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7039BA",
            },
        [50107106] = {
            ["Content"] = "敢问祀烟阁的管事香官现在何处？鄙人自氤园而来，与他有约。",
            ["ContentKR"] = "사연각 주임 향관님은 어디 계십니까? 전 인원에서 왔습니다. 오늘 뵙기로 했는데요.",
            ["DialogueId"] = 50107106,
            ["GUID"] = "7D701914",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7039E4",
            },
        [50107107] = {
            ["Content"] = "今日怎得是你来奉香，你哥又回烟津渡了？",
            ["ContentKR"] = "왜 네가 향을 올리고 있어? 오라버니는 또 연진 나루터에 간 거야?",
            ["DialogueId"] = 50107107,
            ["GUID"] = "7D70193E",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703A0E",
            },
        }
  end },
  { MinKey = 50107108, MaxKey = 50107350, Loader = function()
      return {
        [50107108] = {
