            ["ContentKR"] = "언제 적 말씀을 하세요...",
            ["DialogueId"] = 50107235,
            ["GUID"] = "7D702E3E",
            ["SpeakNpcId"] = 701149,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702E3E",
            },
        [50107236] = {
            ["Content"] = "这杯，我敬你！",
            ["ContentKR"] = "형님, 이 잔 받으세요!",
            ["DialogueId"] = 50107236,
            ["GUID"] = "7D702E68",
            ["SpeakNpcId"] = 701150,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702E68",
            },
        [50107237] = {
            ["Content"] = "草木深胡同……是在这里？",
