            ["DialogueId"] = 50107237,
            ["GUID"] = "7D702E92",
            ["SpeakNpcId"] = 701151,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702E92",
            },
        [50107238] = {
            ["Content"] = "你说那家私房菜？",
            ["ContentKR"] = "그 특선 요릿집 말이지?",
            ["DialogueId"] = 50107238,
            ["GUID"] = "7D702EBC",
            ["SpeakNpcId"] = 701152,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702EBC",
            },
        [50107239] = {
            ["Content"] = "这小巷深处竟藏着这庖厨圣地！",
            ["ContentKR"] = "골목 안쪽에 이런 맛집이 숨어 있는 걸 이제야 알았네!",
            ["DialogueId"] = 50107239,
            ["GUID"] = "7D702EE6",
            ["SpeakNpcId"] = 701153,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702EE6",
            },
        [50107240] = {
            ["Content"] = "老张啊，你那只八哥……",
            ["ContentKR"] = "장 영감, 자네 집 구관조가...",
            ["DialogueId"] = 50107240,
            ["GUID"] = "7D702F10",
            ["SpeakNpcId"] = 701154,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702F10",
            },
        [50107241] = {
            ["Content"] = "凡夫俗子溜凡羽俗鸟！",
            ["ContentKR"] = "어중이떠중이들한테 딱 맞는 허접한 새들이군.",
            ["DialogueId"] = 50107241,
            ["GUID"] = "7D702F3A",
            ["SpeakNpcId"] = 701155,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702F3A",
            },
        [50107242] = {
            ["Content"] = "老友，这局棋，你该怎么破？",
            ["ContentKR"] = "자, 이 외통수를 무슨 수로 막을 건가?",
            ["DialogueId"] = 50107242,
            ["GUID"] = "7D702F64",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702F64",
            },
        [50107243] = {
            ["Content"] = "在家里聚上一聚，打打骨牌？",
            ["ContentKR"] = "다 같이 우리 집에서 골패 놀이나 할까?",
            ["DialogueId"] = 50107243,
            ["GUID"] = "7D702F8E",
            ["SpeakNpcId"] = 701157,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702F8E",
            },
        [50107244] = {
            ["Content"] = "给我回去复习功课！",
            ["ContentKR"] = "얼른 들어가서 복습해!",
            ["DialogueId"] = 50107244,
            ["GUID"] = "7D702FB8",
            ["SpeakNpcId"] = 701158,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702FB8",
            },
        [50107245] = {
            ["Content"] = "今天翻墙出来被阿娘逮到了……",
            ["ContentKR"] = "담 넘다가 엄마한테 딱 걸려가지고...",
            ["DialogueId"] = 50107245,
            ["GUID"] = "7D702FE2",
            ["SpeakNpcId"] = 701160,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702FE2",
            },
        [50107246] = {
            ["Content"] = "无由生马上要出来抓你们咯？",
            ["ContentKR"] = "이제 무유생이 잡으러 간다?",
            ["DialogueId"] = 50107246,
            ["GUID"] = "7D70300C",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70300C",
            },
        [50107247] = {
            ["Content"] = "真是忙到头晕眼花。",
            ["ContentKR"] = "이러다 진짜 쓰러질 것 같아.",
            ["DialogueId"] = 50107247,
            ["GUID"] = "7D703036",
            ["SpeakNpcId"] = 701162,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703036",
            },
        [50107248] = {
            ["Content"] = "恐一蹬腿就要去往虞泉了！",
            ["ContentKR"] = "이러다 픽 쓰러져서 우천에 가 버리겠어!",
            ["DialogueId"] = 50107248,
            ["GUID"] = "7D703060",
            ["SpeakNpcId"] = 701163,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703060",
            },
        [50107249] = {
            ["Content"] = "奉香大典意味着什么？",
            ["ContentKR"] = "봉향대전이 무슨 뜻이냐고?",
            ["DialogueId"] = 50107249,
            ["GUID"] = "7D70308A",
            ["SpeakNpcId"] = 701164,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70308A",
            },
        [50107250] = {
            ["Content"] = "莫非是填错了？",
            ["ContentKR"] = "설마 어디가 잘못 됐나?",
            ["DialogueId"] = 50107250,
            ["GUID"] = "7D7030B4",
            ["SpeakNpcId"] = 701165,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7030B4",
            },
        [50107251] = {
            ["Content"] = "真是难得的清闲啊~",
            ["ContentKR"] = "이렇게 한가한 게 얼마 만이냐~",
            ["DialogueId"] = 50107251,
            ["GUID"] = "7D7030DE",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7030DE",
            },
        [50107252] = {
            ["Content"] = "下次记得早些来泉通司……",
            ["ContentKR"] = "다음부턴 바로 천통사로 오세요...",
            ["DialogueId"] = 50107252,
            ["GUID"] = "7D703108",
            ["SpeakNpcId"] = 701166,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703108",
            },
        [50107253] = {
            ["Content"] = "祀香阁今年额外申请了一笔经费。",
            ["ContentKR"] = "사연각에서 올해 예산을 더 신청했더군.",
            ["DialogueId"] = 50107253,
            ["GUID"] = "7D703132",
            ["SpeakNpcId"] = 701167,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703132",
            },
        [50107254] = {
            ["Content"] = "搭台子，修香炉……",
            ["ContentKR"] = "단상도 세우고, 향로도 고치고...",
            ["DialogueId"] = 50107254,
            ["GUID"] = "7D70315C",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70315C",
            },
        [50107255] = {
            ["Content"] = "鬼鬼祟祟的，看起来不像什么好人。",
            ["ContentKR"] = "행동거지가 영 수상한 게, 딱 봐도 나쁜 놈 같더라고요.",
            ["DialogueId"] = 50107255,
            ["GUID"] = "7D703186",
            ["SpeakNpcId"] = 701168,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703186",
            },
        [50107256] = {
            ["Content"] = "为何来来回回都在提西郊？",
            ["ContentKR"] = "왜 죄다 서쪽 교외지?",
            ["DialogueId"] = 50107256,
            ["GUID"] = "7D7031B0",
            ["SpeakNpcId"] = 701169,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7031B0",
            },
        [50107257] = {
            ["Content"] = "快给我来碗茶水！",
            ["ContentKR"] = "얼른 차 한 잔 주세요!",
            ["DialogueId"] = 50107257,
            ["GUID"] = "7D7031DA",
            ["SpeakNpcId"] = 701170,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7031DA",
            },
        [50107258] = {
            ["Content"] = "不是货物？那是……翠屏雀？！",
            ["ContentKR"] = "화물이 아니라... 초록 공작새라고요?!",
            ["DialogueId"] = 50107258,
            ["GUID"] = "7D703204",
            ["SpeakNpcId"] = 701171,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703204",
            },
        [50107259] = {
            ["Content"] = "它到底是怎么跑出去的呢？",
            ["ContentKR"] = "대체 어떻게 빠져나간 거지?",
            ["DialogueId"] = 50107259,
            ["GUID"] = "7D70322E",
            ["SpeakNpcId"] = 701172,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70322E",
            },
        [50107260] = {
            ["Content"] = "一切努力都付之东流了……",
            ["ContentKR"] = "열심히 노력한 게 다 물거품이 됐어...",
