            ["GUID"] = "7D703258",
            ["SpeakNpcId"] = 701173,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703258",
            },
        [50107261] = {
            ["Content"] = "已经找到一只了？",
            ["ContentKR"] = "한 마리는 찾았다고?",
            ["DialogueId"] = 50107261,
            ["GUID"] = "7D703282",
            ["SpeakNpcId"] = 701174,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703282",
            },
        [50107262] = {
            ["Content"] = "咱们的绣品在皓京城里很受欢迎呢~",
            ["ContentKR"] = "역시 우리 천수각 수예품은 호경에서 인기 최고지~",
