            ["GUID"] = "7D7032AC",
            ["SpeakNpcId"] = 701175,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7032AC",
            },
        [50107263] = {
            ["Content"] = "甜果只有百分之三损毁？",
