            ["DialogueId"] = 50107266,
            ["GUID"] = "7D703354",
            ["SpeakNpcId"] = 701179,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703354",
            },
        [50107267] = {
            ["Content"] = "恁大一个皓京城！",
            ["ContentKR"] = "호경은 허벌나게 크구마잉!",
