            ["GUID"] = "7D70337E",
            ["SpeakNpcId"] = 701180,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70337E",
            },
        [50107268] = {
            ["Content"] = "别靠过来！",
            ["ContentKR"] = "가까이 오지 마!",
            ["DialogueId"] = 50107268,
            ["GUID"] = "7D7033A8",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7033A8",
            },
        [50107269] = {
            ["Content"] = "水龙车我先带走了。",
            ["ContentKR"] = "수총기는 일단 회수하겠습니다.",
            ["DialogueId"] = 50107269,
            ["GUID"] = "7D7033D2",
            ["SpeakNpcId"] = 701181,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7033D2",
            },
        [50107270] = {
            ["Content"] = "太麻烦他们了。",
            ["ContentKR"] = "괜히 폐만 끼쳐 드렸네요.",
            ["DialogueId"] = 50107270,
            ["GUID"] = "7D7033FC",
            ["SpeakNpcId"] = 701182,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7033FC",
            },
        [50107271] = {
            ["Content"] = "来回拉扯不嫌麻烦吗？",
            ["ContentKR"] = "왔다 갔다 귀찮지도 않나?",
            ["DialogueId"] = 50107271,
            ["GUID"] = "7D703426",
            ["SpeakNpcId"] = 701183,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703426",
            },
        [50107272] = {
            ["Content"] = "凌波疾步！",
            ["ContentKR"] = "능파미보!",
            ["DialogueId"] = 50107272,
            ["GUID"] = "7D703450",
            ["SpeakNpcId"] = 701184,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703450",
            },
        [50107273] = {
            ["Content"] = "疯狂长苔，转动都费劲……",
            ["ContentKR"] = "이끼가 잔뜩 껴서 돌아가질 않아...",
            ["DialogueId"] = 50107273,
            ["GUID"] = "7D70347A",
            ["SpeakNpcId"] = 701185,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70347A",
            },
        [50107274] = {
            ["Content"] = "怎会有这多事端？",
            ["ContentKR"] = "이 난리가 난 거 아닙니까?",
            ["DialogueId"] = 50107274,
            ["GUID"] = "7D7034A4",
            ["SpeakNpcId"] = 701186,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7034A4",
            },
        [50107275] = {
            ["Content"] = "明法、公心、勤谨。",
            ["ContentKR"] = "규칙 엄수, 공사 구분, 근면 성실.",
            ["DialogueId"] = 50107275,
            ["GUID"] = "7D7034CE",
            ["SpeakNpcId"] = 701187,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7034CE",
            },
        [50107276] = {
            ["Content"] = "直吵得人不得安睡！",
            ["ContentKR"] = "도대체 잠을 못 자겠어!",
            ["DialogueId"] = 50107276,
            ["GUID"] = "7D7034F8",
            ["SpeakNpcId"] = 701188,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7034F8",
            },
        [50107277] = {
            ["Content"] = "游船游船，十文一趟。",
            ["ContentKR"] = "유람선~ 뱃놀이~ 단돈 열 냥!",
            ["DialogueId"] = 50107277,
            ["GUID"] = "7D703522",
            ["SpeakNpcId"] = 701189,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703522",
            },
        [50107278] = {
            ["Content"] = "我查一下刚买的《华胥问候语录大全》。",
            ["ContentKR"] = "조, 조금 전에 산... 〈화서 인사말 대백과〉를 찾아 볼게요.",
            ["DialogueId"] = 50107278,
            ["GUID"] = "7D70354C",
            ["SpeakNpcId"] = 701190,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70354C",
            },
        [50107279] = {
            ["Content"] = "晚上做了什么好吃的？",
            ["ContentKR"] = "저녁은 드셨수?",
            ["DialogueId"] = 50107279,
            ["GUID"] = "7D703576",
            ["SpeakNpcId"] = 701191,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703576",
            },
        [50107280] = {
            ["Content"] = "铁柱呢？铁柱为何不在？",
            ["ContentKR"] = "철주는? 철주는 어디 갔어?",
            ["DialogueId"] = 50107280,
            ["GUID"] = "7D7035A0",
            ["SpeakNpcId"] = 701192,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7035A0",
            },
        [50107281] = {
            ["Content"] = "灯谜会，待君赏玩！",
            ["ContentKR"] = "등불 퀴즈 대회가, 여러분을 찾아갑니다!",
            ["DialogueId"] = 50107281,
            ["GUID"] = "7D7035CA",
            ["SpeakNpcId"] = 701193,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7035CA",
            },
        [50107282] = {
            ["Content"] = "妈妈我到皓京了……",
            ["ContentKR"] = "어머니, 저 호경에 왔어요...",
            ["DialogueId"] = 50107282,
            ["GUID"] = "7D7035F4",
            ["SpeakNpcId"] = 701194,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7035F4",
            },
        [50107283] = {
            ["Content"] = "这里面不能进去吗？",
            ["ContentKR"] = "못 들어간다는 게 말이 돼요?",
            ["DialogueId"] = 50107283,
            ["GUID"] = "7D70361E",
            ["SpeakNpcId"] = 701195,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70361E",
            },
        [50107284] = {
            ["Content"] = "会看到白龙神君在云间遨游。",
            ["ContentKR"] = "구름 속을 날아다니시는 백룡신군님이 보일 거야.",
            ["DialogueId"] = 50107284,
            ["GUID"] = "7D703648",
            ["SpeakNpcId"] = 701196,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703648",
            },
        [50107285] = {
            ["Content"] = "朝报朝报，茶不思饭不想只想看朝报。",
            ["ContentKR"] = "신문 사세요~ 밥보다 좋은 신문이요~",
            ["DialogueId"] = 50107285,
            ["GUID"] = "7D703672",
            ["SpeakNpcId"] = 701198,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703672",
            },
        [50107286] = {
            ["Content"] = "凑在一起为什么完全看不懂……",
            ["ContentKR"] = "합쳐 놓으니까 무슨 소린지 전혀 모르겠네...",
            ["DialogueId"] = 50107286,
            ["GUID"] = "7D70369C",
            ["SpeakNpcId"] = 701199,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70369C",
            },
        [50107287] = {
            ["Content"] = "主要的是感受当地的氛围，您说对不对？",
            ["ContentKR"] = "중요한 건, 그 지역 분위기에 흠뻑 취하는 거죠. 안 그래요?",
            ["DialogueId"] = 50107287,
            ["GUID"] = "7D7036C6",
            ["SpeakNpcId"] = 701200,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7036C6",
            },
        [50107288] = {
            ["Content"] = "退一万步说……",
            ["ContentKR"] = "아무리 그래도 그렇지...",
            ["DialogueId"] = 50107288,
            ["GUID"] = "7D7036F0",
            ["SpeakNpcId"] = 701201,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7036F0",
            },
        [50107289] = {
            ["Content"] = "直接推着车撞了过来……",
            ["ContentKR"] = "수레로 그냥 들이받은 거라고...",
            ["DialogueId"] = 50107289,
            ["GUID"] = "7D70371A",
            ["SpeakNpcId"] = 701202,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70371A",
            },
        [50107290] = {
            ["Content"] = "天地为共生，万物与我一……",
            ["ContentKR"] = "천지와 공존하고 만물과 하나가 되리라...",
            ["DialogueId"] = 50107290,
            ["GUID"] = "7D703744",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703744",
            },
        [50107291] = {
            ["Content"] = "为人在世……",
            ["ContentKR"] = "하늘의 명은...",
            ["DialogueId"] = 50107291,
            ["GUID"] = "7D70376E",
            ["SpeakNpcId"] = 701203,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70376E",
            },
        [50107292] = {
            ["Content"] = "曾在学院听竹溪先生传授最后一课。",
            ["ContentKR"] = "서당에서 그분의 마지막 강의를 들었다고 했지.",
            ["DialogueId"] = 50107292,
            ["GUID"] = "7D703798",
            ["SpeakNpcId"] = 701204,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703798",
            },
        [50107293] = {
            ["Content"] = "吵死了……",
            ["ContentKR"] = "시끄러 죽겠네, 진짜...",
            ["DialogueId"] = 50107293,
            ["GUID"] = "7D7037C2",
            ["SpeakNpcId"] = 701205,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7037C2",
            },
        [50107294] = {
            ["Content"] = "所谓理一……",
            ["ContentKR"] = "'이일'이란...",
            ["DialogueId"] = 50107294,
            ["GUID"] = "7D7037EC",
            ["SpeakNpcId"] = 701206,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7037EC",
            },
        [50107295] = {
            ["Content"] = "五味万殊，而大同于美。",
            ["ContentKR"] = "다양한 맛도 결국은 '아름다움'이라는 가치로 귀결되고...",
            ["DialogueId"] = 50107295,
            ["GUID"] = "7D703816",
            ["SpeakNpcId"] = 701207,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703816",
            },
        [50107296] = {
            ["Content"] = "所以理一定是在前面的！",
            ["ContentKR"] = "그래서 이치가 우선인 겁니다!",
            ["DialogueId"] = 50107296,
            ["GUID"] = "7D703840",
            ["SpeakNpcId"] = 701208,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703840",
            },
        [50107297] = {
            ["Content"] = "今天该轮到你执勤了吧？",
            ["ContentKR"] = "오늘은 네가 당번 서!",
            ["DialogueId"] = 50107297,
            ["GUID"] = "7D70386A",
            ["SpeakNpcId"] = 701209,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70386A",
            },
        [50107298] = {
            ["Content"] = "放假你们都去哪玩？",
            ["ContentKR"] = "봉향대전 때 너네 어디 놀러 갈 거야?",
            ["DialogueId"] = 50107298,
            ["GUID"] = "7D703894",
            ["SpeakNpcId"] = 701210,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703894",
            },
        [50107299] = {
            ["Content"] = "蹴球赛咱们队还差一人！",
            ["ContentKR"] = "축국 시합에 나갈 사람이 하나 모자란데!",
            ["DialogueId"] = 50107299,
            ["GUID"] = "7D7038BE",
            ["SpeakNpcId"] = 701211,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7038BE",
            },
        [50107300] = {
            ["Content"] = "可这又还能往哪里扩呢？",
            ["ContentKR"] = "그런데 주변에 남는 땅이 없잖아?",
            ["DialogueId"] = 50107300,
            ["GUID"] = "7D7038E8",
            ["SpeakNpcId"] = 701212,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7038E8",
            },
        [50107301] = {
            ["Content"] = "是了，来年开春便要递上辞函……",
            ["ContentKR"] = "그래, 내년 봄엔 은퇴할 거야...",
            ["DialogueId"] = 50107301,
            ["GUID"] = "7D703912",
            ["SpeakNpcId"] = 701213,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703912",
            },
        [50107302] = {
            ["Content"] = "为何飘零人的行为不能算是一种独特的方式？",
            ["ContentKR"] = "나그네들의 방식도 그중 하나로 인정해 줘야 하는 거 아닌가요?",
            ["DialogueId"] = 50107302,
            ["GUID"] = "7D70393C",
            ["SpeakNpcId"] = 701214,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70393C",
            },
        [50107303] = {
            ["Content"] = "今天的辩题有趣！",
            ["ContentKR"] = "오늘 토론 주제 재밌네!",
            ["DialogueId"] = 50107303,
            ["GUID"] = "7D703966",
            ["SpeakNpcId"] = 701215,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703966",
            },
        [50107304] = {
            ["Content"] = "有这闲工夫，不如多读些书！",
            ["ContentKR"] = "그럴 시간 있으면, 책이나 한 자 더 읽어라!",
            ["DialogueId"] = 50107304,
            ["GUID"] = "7D703990",
            ["SpeakNpcId"] = 701216,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703990",
            },
        [50107305] = {
            ["Content"] = "椒兰村的香料自然是地道。",
            ["ContentKR"] = "초란 마을은 향료의 본고장이죠.",
            ["DialogueId"] = 50107305,
            ["GUID"] = "7D7039BA",
            ["SpeakNpcId"] = 701217,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7039BA",
            },
        [50107306] = {
            ["Content"] = "鄙人自氤园而来，与他有约。",
            ["ContentKR"] = "전 인원에서 왔습니다. 오늘 뵙기로 했는데요.",
            ["DialogueId"] = 50107306,
            ["GUID"] = "7D7039E4",
            ["SpeakNpcId"] = 701219,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7039E4",
            },
        [50107307] = {
            ["Content"] = "你哥又回烟津渡了？",
            ["ContentKR"] = "오라버니는 또 연진 나루터에 간 거야?",
            ["DialogueId"] = 50107307,
            ["GUID"] = "7D703A0E",
            ["SpeakNpcId"] = 701220,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703A0E",
            },
        [50107308] = {
            ["Content"] = "愿家父身体健康，百病不侵。",
            ["ContentKR"] = "부디 아버지께서 무병장수할 수 있게 해주시옵소서.",
            ["DialogueId"] = 50107308,
            ["GUID"] = "7D703A38",
            ["SpeakNpcId"] = 701221,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703A38",
            },
        [50107309] = {
            ["Content"] = "唔……我的愿望是，长高一点！",
            ["ContentKR"] = "음... 난, 키가 좀 더 컸으면 좋겠어!",
            ["DialogueId"] = 50107309,
            ["GUID"] = "7D703A62",
            ["SpeakNpcId"] = 701222,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703A62",
            },
        [50107310] = {
            ["Content"] = "香官跟我说的。",
            ["ContentKR"] = "향관한테 들었는데...",
            ["DialogueId"] = 50107310,
            ["GUID"] = "7D703A8C",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703A8C",
            },
        [50107311] = {
            ["Content"] = "今年祀香阁怎得没动静了？",
            ["ContentKR"] = "올해는 사연각이 이상하게 조용하네?",
            ["DialogueId"] = 50107311,
            ["GUID"] = "7D703AB6",
            ["SpeakNpcId"] = 701223,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703AB6",
            },
        [50107312] = {
            ["Content"] = "尤其是中心广场水上的那个炉子！",
            ["ContentKR"] = "중앙 광장에 있는 수상 향로는 특히 더 꼼꼼히요!",
            ["DialogueId"] = 50107312,
            ["GUID"] = "7D703AE0",
            ["SpeakNpcId"] = 701224,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703AE0",
            },
        [50107313] = {
            ["Content"] = "难不成真是我思维迟缓？",
            ["ContentKR"] = "머리가 굳어 버렸나?",
            ["DialogueId"] = 50107313,
            ["GUID"] = "7D703B0A",
            ["SpeakNpcId"] = 701225,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703B0A",
            },
        [50107314] = {
            ["Content"] = "不同的香方自然作用也不相同。",
            ["ContentKR"] = "향은 조합법에 따라 작용도 달라진답니다.",
            ["DialogueId"] = 50107314,
            ["GUID"] = "7D703B34",
            ["SpeakNpcId"] = 701226,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703B34",
            },
        [50107315] = {
            ["Content"] = "祀香阁今年招了一位皎皎之民！",
            ["ContentKR"] = "올해 사연각에서 뽑은 향관 중에 루나가 있대!",
            ["DialogueId"] = 50107315,
            ["GUID"] = "7D703B5E",
            ["SpeakNpcId"] = 701227,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703B5E",
            },
        [50107316] = {
            ["Content"] = "那矮冬瓜大头鱼一样的家伙……",
            ["ContentKR"] = "그 쬐끄매서 머리만 큰 족속들이...",
            ["DialogueId"] = 50107316,
            ["GUID"] = "7D703B88",
            ["SpeakNpcId"] = 701228,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703B88",
            },
        [50107317] = {
            ["Content"] = "去泉通司问过了吗？",
            ["ContentKR"] = "천통사에 가서 확인해 봤어?",
            ["DialogueId"] = 50107317,
            ["GUID"] = "7D703BB2",
            ["SpeakNpcId"] = 701229,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703BB2",
            },
        [50107318] = {
            ["Content"] = "几番叨扰，自己都有点过意不去了。",
            ["ContentKR"] = "여쭤보러 오기도 이젠 죄송하네요.",
            ["DialogueId"] = 50107318,
            ["GUID"] = "7D703BDC",
            ["SpeakNpcId"] = 701230,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703BDC",
            },
        [50107319] = {
            ["Content"] = "你准备回家？",
            ["ContentKR"] = "본가에 내려갈 거야?",
            ["DialogueId"] = 50107319,
            ["GUID"] = "7D703C06",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703C06",
            },
        [50107320] = {
            ["Content"] = "这要我们如何兢兢业业干活？",
            ["ContentKR"] = "일을 하라는 거야 말라는 거야?",
            ["DialogueId"] = 50107320,
            ["GUID"] = "7D703C30",
            ["SpeakNpcId"] = 701231,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703C30",
            },
        [50107321] = {
            ["Content"] = "你这关节做的根本不行！",
            ["ContentKR"] = "관절을 이렇게 해놓으면 안 되지!",
            ["DialogueId"] = 50107321,
            ["GUID"] = "7D703C5A",
            ["SpeakNpcId"] = 701232,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703C5A",
            },
        [50107322] = {
            ["Content"] = "想学的话来机枢派报个名？",
            ["ContentKR"] = "기추파에 들어 오지 않을래?",
            ["DialogueId"] = 50107322,
            ["GUID"] = "7D703C84",
            ["SpeakNpcId"] = 701233,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703C84",
            },
        [50107323] = {
            ["Content"] = "叔叔，这是什么？",
            ["ContentKR"] = "아저씨, 이건 뭐예요?",
            ["DialogueId"] = 50107323,
            ["GUID"] = "7D703CAE",
            ["SpeakNpcId"] = 701234,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703CAE",
            },
        [50107324] = {
            ["Content"] = "与其把心思放在拉人进阁，还不如……",
            ["ContentKR"] = "매년 모집해 봐야 파리만 날리는데, 차라리...",
            ["DialogueId"] = 50107324,
            ["GUID"] = "7D703CD8",
            ["SpeakNpcId"] = 701235,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703CD8",
            },
        [50107326] = {
            ["Content"] = "香……这香……香啊……香。",
            ["ContentKR"] = "으음... 이 향... 정말 끝내준다.",
            ["DialogueId"] = 50107326,
            ["GUID"] = "7D703D2C",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703D2C",
            },
        [50107327] = {
            ["Content"] = "这就是华胥风格的服饰吗？",
            ["ContentKR"] = "화서 사람들은 이런 옷을 입는다는 거지?",
            ["DialogueId"] = 50107327,
            ["GUID"] = "7D703D56",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703D56",
            },
        [50107328] = {
            ["Content"] = "难道我真就无法找到相伴一生之人？",
            ["ContentKR"] = "정녕 나의 반쪽 하나 없단 말인가?",
            ["DialogueId"] = 50107328,
            ["GUID"] = "7D703D80",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703D80",
            },
        [50107329] = {
            ["Content"] = "要是我把这个人杀了……",
            ["ContentKR"] = "이 녀석을 없애 버리면...",
            ["DialogueId"] = 50107329,
            ["GUID"] = "7D703DAA",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703DAA",
            },
        [50107330] = {
            ["Content"] = "等开春，去收两斤新茶泡来喝！",
            ["ContentKR"] = "봄이 되면, 첫물차를 사다 차를 끓여야겠어!",
            ["DialogueId"] = 50107330,
            ["GUID"] = "7D703DD4",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703DD4",
            },
        [50107331] = {
            ["Content"] = "瞧见那远处的楼没？",
            ["ContentKR"] = "저기 있는 누각 보이니?",
            ["DialogueId"] = 50107331,
            ["GUID"] = "7D703DFE",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703DFE",
            },
        [50107332] = {
            ["Content"] = "所有目光向我看齐！",
            ["ContentKR"] = "다들 주목!",
            ["DialogueId"] = 50107332,
            ["GUID"] = "7D703E28",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703E28",
            },
        [50107333] = {
            ["Content"] = "怎就没有愿意与我辩论之人？",
            ["ContentKR"] = "왜 나랑 토론하려는 사람이 없지?",
            ["DialogueId"] = 50107333,
            ["GUID"] = "7D703E52",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703E52",
            },
        [50107334] = {
            ["Content"] = "要说最为复杂的调解案……",
            ["ContentKR"] = "가장 수습하기 힘들었던 건은...",
            ["DialogueId"] = 50107334,
            ["GUID"] = "7D703E7C",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703E7C",
            },
        [50107335] = {
            ["Content"] = "若是法理不通……",
            ["ContentKR"] = "법리가 바로 서지 않았는데...",
            ["DialogueId"] = 50107335,
            ["GUID"] = "7D703EA6",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703EA6",
            },
        [50107336] = {
            ["Content"] = "这些木头块都没意思！",
            ["ContentKR"] = "깨작깨작 나무토막이나 두드리고 있으니 이게 무슨 재미야!",
            ["DialogueId"] = 50107336,
            ["GUID"] = "7D703ED0",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703ED0",
            },
        [50107337] = {
            ["Content"] = "皎皎为何不能当香官？",
            ["ContentKR"] = "루나라고 왜 향관을 못 해?",
            ["DialogueId"] = 50107337,
            ["GUID"] = "7D703EFA",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703EFA",
            },
        [50107338] = {
            ["Content"] = "将那筐香料放下再说……",
            ["ContentKR"] = "향료 바구니부터 내려놓고 얘기해요...",
            ["DialogueId"] = 50107338,
            ["GUID"] = "7D703F24",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703F24",
            },
        [50107339] = {
            ["Content"] = "由来巷的事儿，我可全都记着呢！",
            ["ContentKR"] = "유래골에서 있었던 일, 난 다 기억하고 있어!",
            ["DialogueId"] = 50107339,
            ["GUID"] = "7D703F4E",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703F4E",
            },
        [50107340] = {
            ["Content"] = "飘零四杰啊……",
            ["ContentKR"] = "나그네 협객 사인방이라...",
            ["DialogueId"] = 50107340,
            ["GUID"] = "7D703F78",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703F78",
            },
        [50107341] = {
            ["Content"] = "笨笨的家伙建高高的台~",
            ["ContentKR"] = "높이높이 올라가 멀리멀리 봤더니~",
            ["DialogueId"] = 50107341,
            ["GUID"] = "7D703FA2",
            ["SpeakNpcId"] = 701236,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703FA2",
            },
        [50107342] = {
            ["Content"] = "诶呀诶呀，这家伙怎么看着我？",
            ["ContentKR"] = "어라라? 저 녀석 내가 보이는 건가?",
            ["DialogueId"] = 50107342,
            ["GUID"] = "7D703FCC",
            ["SpeakNpcId"] = 701237,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703FCC",
            },
        [50107343] = {
            ["Content"] = "我要开始抓你们了哦！",
            ["ContentKR"] = "다들 꼭꼭 숨었지?",
            ["DialogueId"] = 50107343,
            ["GUID"] = "7D703FF6",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703FF6",
            },
        [50107344] = {
            ["Content"] = "谁家的孩子穿一身白？",
            ["ContentKR"] = "허여멀겋게 옷이 그게 뭐니?",
            ["DialogueId"] = 50107344,
            ["GUID"] = "7D704020",
            ["SpeakNpcId"] = 701239,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D704020",
            },
        [50107345] = {
            ["Content"] = "你闻，香味还没散出来呢。",
            ["ContentKR"] = "맡아 봐, 향이 잘 안 퍼져.",
            ["DialogueId"] = 50107345,
            ["GUID"] = "7D70404A",
            ["SpeakNpcId"] = 701240,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70404A",
            },
        [50107346] = {
            ["Content"] = "收回来的新鲜吿苍要立即拿去晾晒。",
            ["ContentKR"] = "싱싱한 고창은 가져오자마자 말리라니까.",
            ["DialogueId"] = 50107346,
            ["GUID"] = "7D704074",
            ["SpeakNpcId"] = 701241,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D704074",
            },
        [50107347] = {
            ["Content"] = "落生香的原料研磨最讲究精细。",
            ["ContentKR"] = "낙생향을 만들 때는 재료를 곱게 갈아야 해.",
            ["DialogueId"] = 50107347,
            ["GUID"] = "7D70409E",
            ["SpeakNpcId"] = 701242,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70409E",
            },
        [50107348] = {
            ["Content"] = "快来帮忙，炉子又炸了！",
            ["ContentKR"] = "빨리 와서 도와줘! 화로가 또 터졌어!",
            ["DialogueId"] = 50107348,
            ["GUID"] = "7D7040C8",
            ["SpeakNpcId"] = 701243,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7040C8",
            },
        [50107349] = {
            ["Content"] = "合香是一门技术活。",
            ["ContentKR"] = "향 제작에도 기술이 있어.",
            ["DialogueId"] = 50107349,
            ["GUID"] = "7D7040F2",
            ["SpeakNpcId"] = 701244,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7040F2",
            },
        [50107350] = {
            ["Content"] = "那批香装好了吗？",
            ["ContentKR"] = "주문 들어온 향은 포장 다 하셨어요?",
            ["DialogueId"] = 50107350,
            ["GUID"] = "7D70411C",
