            ["DialogueId"] = 51001302,
            ["GUID"] = "7FAD291C",
            ["NextDialogue"] = 51001304,
            ["SpeakNpcId"] = 700014,
            },
        [51001303] = {
            ["Content"] = "医药费！必须给我医药费！你快把我鼻子打歪了！",
            ["ContentKR"] = "병원비! 병원비 내놔! 내 코를 부러뜨릴 뻔 했잖아!",
