            ["SpeakNpcId"] = 700210,
            ["ToFinalCameraBlendTime"] = 7,
            },
        [51002117] = {
            ["Content"] = "回去吧，这些应该能够缓解布鲁内托的乡愁了。",
            ["ContentKR"] = "이제 돌아가자. 이만하면 브루네토 씨의 향수를 달래드릴 수 있을 거야.",
            ["DialogueId"] = 51002117,
            ["Duration"] = 3,
            ["GUID"] = "7FADAC94",
            ["NextDialogue"] = 51002118,
            ["SpeakNpcId"] = 100001,
            },
        [51002118] = {
            ["Content"] = "孙子通过打架认识，爷爷通过坑骗认识……哈……真是奇怪的缘分……",
            ["ContentKR"] = "손자는 나한테 싸움질, 할아버지는 나한테 사기질... 하하... 별 희한한 인연이 다 있네...",
            ["DialogueId"] = 51002118,
            ["Duration"] = 4,
            ["GUID"] = "7FADAC95",
            ["SpeakNpcId"] = 100001,
            },
        [51002201] = {
            ["Content"] = "来往的朋友，稍微停一停脚步，给上几个银币，您就能加入冰湖城渔夫互助会，获得最好最新的——啊！是你……",
            ["ContentKR"] = "지나가는 친구들, 발걸음을 잠시 멈춰보시오. 약간의 쿠퍼만 주면 아이스레이크 시티 어부 공제조합의 일원이 되어 최고의 최신 정보를 얻을 수 있소...아! 당신이군...",
            ["DialogueId"] = 51002201,
            ["GUID"] = "7FADBC9A",
            ["NextDialogue"] = 51002202,
            ["SpeakNpcId"] = 700048,
            },
        [51002202] = {
            ["Content"] = "这应该是你的东西？",
            ["ContentKR"] = "이거 아저씨 물건이죠?",
            ["DialogueId"] = 51002202,
            ["GUID"] = "7FADBCC4",
            ["NextDialogue"] = 51002203,
            ["SpeakNpcId"] = 100001,
            },
        [51002203] = {
            ["Content"] = "啊！没错，这就是我小时候翻来覆去一直在看的书，那时候就是看着这本书，想离开巴掌大的小岛……",
            ["ContentKR"] = "오! 그렇소. 내가 어릴 적에 자주 본 책이라오. 그 무렵엔 늘 이 책을 읽으며 이 손바닥만 한 작은 섬을 떠나고 싶었다오...",
            ["DialogueId"] = 51002203,
            ["GUID"] = "7FADBCEE",
            ["NextDialogue"] = 51002204,
            ["SpeakNpcId"] = 700048,
            ["TalkActionId"] = {
                [1] = "700048:Agree",
                },
            },
        [51002204] = {
            ["Content"] = "谢谢，谢谢你，我今天晚上得要好好再翻一遍。不过现在先不说了，唉，挣钱糊口要紧。",
            ["ContentKR"] = "고맙소, 고마워. 오늘 밤에 다시 한번 꼼꼼히 읽어봐야겠소. 하지만 지금은 여기까지만 얘기해야겠소. 당장 먹고살 돈을 버는 게 더 급하니.",
            ["DialogueId"] = 51002204,
            ["GUID"] = "7FADBD18",
            ["NextDialogue"] = 51002205,
            ["SpeakNpcId"] = 700048,
            ["TalkActionId"] = {
                [1] = "700048:Explain01_Start",
                },
            },
        [51002205] = {
            ["Content"] = "再见，不要再骗人了。哦对了，这些鱼干也拿去，净界岛钓上来做的。",
            ["ContentKR"] = "전 이만 가 볼게요. 앞으론 정직하게 사세요. 참, 이 말린 생선들도 드릴게요. 연옥도에서 낚은 걸로 만들었어요.",
            ["DialogueId"] = 51002205,
            ["GUID"] = "7FADBD42",
            ["NextDialogue"] = 51002206,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700048:Explain01_End",
                },
            },
        [51002206] = {
            ["Content"] = "这是……谢谢，真的太谢谢你了……",
            ["ContentKR"] = "이건... 고맙소, 정말 고맙구려...",
            ["DialogueId"] = 51002206,
            ["GUID"] = "7FADBD6C",
            ["SpeakNpcId"] = 700048,
            },
        [51002207] = {
            ["Content"] = "冰湖城渔夫互助会，有兴趣的朋友了解一下，几十年经验老渔夫亲自指导，作为兴趣作为工作都棒极了！",
            ["ContentKR"] = "아이스레이크 시티 어부 공제조합에 관심 있는 사람은 이리 오시오. 수십 년 경력의 베테랑 어부가 직접 지도해 주니 취미로든 일로든 아주 좋다오!",
            ["DialogueId"] = 51002207,
            ["GUID"] = "7FADBD96",
            ["NextDialogue"] = 51002208,
            ["SpeakNpcId"] = 700048,
            },
        [51002208] = {
            ["Content"] = "哎呀，这不是{nickname}吗，都是老乡了，有空我们交流下捕鱼的技术？",
            ["ContentKR"] = "어이쿠, {Nickname} 자네였구려! 동향 사람끼리, 시간 날 때 낚시 노하우 이야기나 나눠 보는 건 어떻소?",
            ["DialogueId"] = 51002208,
            ["GUID"] = "7FADBD97",
            ["NextDialogue"] = 51002209,
            ["SpeakNpcId"] = 700048,
            },
        [51002209] = {
            ["Content"] = "下次一定。",
            ["ContentKR"] = "시간 나면요.",
            ["DialogueId"] = 51002209,
            ["GUID"] = "7FADBDC0",
            ["SpeakNpcId"] = 100001,
            },
        [51002301] = {
            ["Content"] = "年轻人，你有哈默尔·狄金森的消息了吗？",
            ["ContentKR"] = "젊은이, 하멜 디킨슨에 관해 새로 들은 소식이 있니?",
            ["DialogueId"] = 51002301,
            ["GUID"] = "7FADCD02",
            ["NextOptions"] = {
                [1] = 510023011,
                },
            ["SpeakNpcId"] = 700019,
            },
        [51002302] = {
            ["Content"] = "（是的，格雷姆矿坑的那本无名日记，它的扉页写着主人的名字——哈默尔·狄金森。）",
            ["ContentKR"] = "(그래, 글로스터 광갱의 그 이름 없는 일기장, 표지에 하멜 디킨슨이라는 일기 주인의 이름이 적혀 있었어.)",
            ["DialogueId"] = 51002302,
            ["GUID"] = "7FADCD2C",
            ["NextDialogue"] = 51002303,
            },
        [51002303] = {
            ["Content"] = "（如果没猜错的话，那只盘踞在矿坑深处的怪物，它的真实身份就是……）",
            ["ContentKR"] = "(내 추측이 맞다면, 그 광산 깊은 곳에 웅크리고 있는 괴물의 진짜 정체는...)",
            ["DialogueId"] = 51002303,
            ["GUID"] = "7FADCD56",
            ["NextDialogue"] = 51002304,
            },
        [51002304] = {
            ["Content"] = "（从言及那个男人开始，老妇人浑浊的眼睛就有了些光亮，看来哈默尔·狄金森这个名字对她而言并不一般。她在期待着一个答案。）",
            ["ContentKR"] = "(그 남자의 이름을 언급하자마자 노부인의 생기 없던 눈에 약간의 빛이 돈다. 하멜 디킨슨이라는 이름은 그녀에게 각별한 의미가 있는 듯하다. 그녀가 대답을 기다리고 있다.)",
            ["DialogueId"] = 51002304,
            ["GUID"] = "7FADCD80",
            ["NextOptions"] = {
                [1] = 510023041,
                [2] = 510023042,
                },
            ["bForbidSkipOptions"] = true,
            },
        [51002305] = {
            ["Content"] = "……",
            ["ContentKR"] = "......",
            ["DialogueId"] = 51002305,
            ["GUID"] = "7FADCDAA",
            ["NextDialogue"] = 51002306,
            ["SpeakNpcId"] = 700019,
            },
        [51002306] = {
            ["Content"] = "（老妇人逐字逐句地默念着那本日记。泪水从她满是皱纹的眼角不断滚落。）",
            ["ContentKR"] = "(노부인은 일기를 한 글자 한 글자 조용히 읽었다. 주름진 눈가에 눈물이 계속 흘러내렸다.)",
            ["DialogueId"] = 51002306,
            ["GUID"] = "7FADCDD4",
            ["NextDialogue"] = 51002307,
            },
        [51002307] = {
            ["Content"] = "（然后她将日记抱在胸前，像是在拥抱着一位久别重逢的爱人。）",
            ["ContentKR"] = "(그러고는 오랫동안 헤어진 연인을 안아주듯 일기장을 가슴에 꽉 움켜쥐었다.)",
            ["DialogueId"] = 51002307,
            ["GUID"] = "7FADCDFE",
            ["NextDialogue"] = 51002308,
            },
        [51002308] = {
            ["Content"] = "……年轻人，谢谢你。谢谢你帮忙找到这个埋藏了四十年的答案。",
            ["ContentKR"] = "... 젊은이, 고마워. 40년 동안 묻혀 있던 답을 찾아줘서 고마워.",
            ["DialogueId"] = 51002308,
            ["GUID"] = "7FADCE28",
            ["NextDialogue"] = 51002309,
            ["SpeakNpcId"] = 700019,
            ["TalkActionId"] = {
                [1] = "700019:Explain02_Start",
                },
            },
        [51002309] = {
            ["Content"] = "请你去找我的女仆莎莉领取报酬吧。我想一个人待一会儿。",
            ["ContentKR"] = "보수는 내 메이드 샐리에게 가면 될 거야. 잠시 혼자 있고 싶어.",
            ["DialogueId"] = 51002309,
            ["GUID"] = "7FADCE52",
            ["NextDialogue"] = 51002310,
            ["SpeakNpcId"] = 700019,
            },
        [51002310] = {
            ["Content"] = "（老妇人转过身去，只留下衰老佝偻的背影。）",
            ["ContentKR"] = "(노부인은 노쇠하고 구부정한 등만 남긴 채 돌아섰다.)",
            ["DialogueId"] = 51002310,
            ["GUID"] = "7FADCE7C",
            },
        [51002311] = {
            ["Content"] = "……",
            ["ContentKR"] = "......",
            ["DialogueId"] = 51002311,
            ["GUID"] = "7FADCEA6",
            ["SpeakNpcId"] = 700019,
            },
        [51002312] = {
            ["Content"] = "抱歉，我没听过这个名字。如果以后有消息，我会回来找你的。",
            ["ContentKR"] = "죄송합니다. 저는 이 이름을 들어본 적이 없어요. 나중에 소식이 있으면 다시 찾아뵐게요.",
            ["DialogueId"] = 51002312,
            ["GUID"] = "7FADCED0",
            ["NextDialogue"] = 51002313,
            ["SpeakNpcId"] = 100001,
            },
        [51002313] = {
            ["Content"] = "好……好，谢谢你，年轻人。",
            ["ContentKR"] = "그... 그래. 젊은이, 고마워.",
            ["DialogueId"] = 51002313,
            ["GUID"] = "7FADCEFA",
            ["NextDialogue"] = 51002314,
            ["SpeakNpcId"] = 700019,
            },
        [51002314] = {
            ["Content"] = "我备好了一份薄礼，请你到我家去找我的女仆莎莉吧，就说是希琳夫人让你来的。",
            ["ContentKR"] = "작은 선물을 준비했으니, 집으로 가서 내 메이드 샐리를 찾아 시린 부인이 오라고 하면 돼.",
            ["DialogueId"] = 51002314,
            ["GUID"] = "7FADCF24",
            ["NextDialogue"] = 51002315,
            ["SpeakNpcId"] = 700019,
            },
        [51002315] = {
            ["Content"] = "去吧，愿你一路顺风……",
            ["ContentKR"] = "가라, 앞으로 순조롭길 바랄게...",
            ["DialogueId"] = 51002315,
            ["GUID"] = "7FADCF4E",
            ["SpeakNpcId"] = 700019,
            },
        [51002320] = {
            ["Content"] = "孩子，你就是那位叫做{nickname}的狩月人吧。希琳夫人让我将报酬预支给你。",
            ["ContentKR"] = "월석 사냥꾼 {nickname} 맞지? 마님이 보상을 미리 주라고 하셨어.",
            ["DialogueId"] = 51002320,
            ["GUID"] = "7FADD020",
            ["NextDialogue"] = 51002321,
            ["SpeakNpcId"] = 700020,
            ["TalkActionId"] = {
                [1] = "700020:Agree",
                },
            },
        [51002321] = {
            ["Content"] = "如果你在哪里听说了哈默尔·狄金森的消息，一定要快点跟夫人讲！",
            ["ContentKR"] = "부탁할게. 하멜 디킨슨에 대해 무슨 소식이 있으면 꼭 빨리 마님께 알려줘.",
            ["DialogueId"] = 51002321,
            ["GUID"] = "7FADD04A",
            ["NextDialogue"] = 51002322,
            ["SpeakNpcId"] = 700020,
            ["TalkActionId"] = {
                [1] = "700020:Sigh_Start",
                },
            },
        [51002322] = {
            ["Content"] = "唉！她那身子从去年开始就越来越差，如今恐怕没有多少日子了。哈默尔的事情，是她的最后一桩心事……",
            ["ContentKR"] = "휴... 마님은 작년부터 몸이 점점 나빠졌으니, 이제 아마도 시간이 얼마 남지 않은 것 같아. 하멜은 그녀의 마지막 걱정거리다...",
            ["DialogueId"] = 51002322,
            ["GUID"] = "7FADD074",
            ["NextOptions"] = {
                [1] = 51002323,
                },
            ["SpeakNpcId"] = 700020,
            ["TalkActionId"] = {
                [1] = "700020:Sigh_End",
                },
            },
        [51002323] = {
            ["Content"] = "可以告诉我哈默尔的事情吗？",
            ["ContentKR"] = "하멜에 대해 이야기해 주실 수 있나요?",
            ["DialogueId"] = 51002323,
            ["GUID"] = "51002323.0",
            ["NextDialogue"] = 51002404,
            },
        [51002401] = {
            ["Content"] = "孩子，你就是那个叫做{nickname}的狩月人吧。希琳夫人让我将报酬转交给你。",
            ["ContentKR"] = "나와 마님을 위해 뛰어다녀줘서 고마워, 이건 그에 대한 작은 감사의 표시란다.",
            ["DialogueId"] = 51002401,
            ["GUID"] = "7FADDD6A",
            ["NextDialogue"] = 51002402,
            ["SpeakNpcId"] = 700020,
            ["TalkActionId"] = {
                [1] = "700020:Agree",
                },
            },
        [51002402] = {
            ["Content"] = "唉！她那身子从去年开始就越来越差，如今恐怕没有多少日子了。哈默尔的事情，是她的最后一桩心事……",
            ["ContentKR"] = "휴, 마님은 작년부터 몸이 점점 나빠지고 있었는데, 이제 정말 얼마 남지 않았을지도 몰라. 하멜의 일은 부인께 남은 마지막 마음의 짐이었던 거지...",
            ["DialogueId"] = 51002402,
            ["GUID"] = "7FADDD94",
            ["NextDialogue"] = 51002403,
            ["SpeakNpcId"] = 700020,
            ["TalkActionId"] = {
                [1] = "700020:Sigh_Start",
                },
            },
        [51002403] = {
            ["Content"] = "虽然不是什么好消息，但婶婶还是要谢谢你！圆了她最后一桩心愿。",
            ["ContentKR"] = "비록 좋은 소식은 아니었지만, 마님의 마지막 소원을 이뤄줘서 고마워!",
            ["DialogueId"] = 51002403,
            ["GUID"] = "7FADDDBE",
            ["NextOptions"] = {
                [1] = 510024031,
                },
            ["SpeakNpcId"] = 700020,
            ["TalkActionId"] = {
                [1] = "700020:Sigh_End",
                },
            },
        [51002404] = {
            ["Content"] = "唉……到这份上，我们确实不能再瞒着你了。",
            ["ContentKR"] = "에휴... 이제 와서 더 이상 숨길 수도 없겠지.",
            ["DialogueId"] = 51002404,
            ["GUID"] = "7FADDDE8",
            ["NextDialogue"] = 51002405,
            ["SpeakNpcId"] = 700020,
            ["TalkActionId"] = {
                [1] = "700020:Explain01_Start",
                },
            },
        [51002405] = {
            ["Content"] = "你可能猜到了，哈默尔是夫人四十年前的心上人。那时夫人……不，应该叫她小姐，还是个热情活泼的姑娘。哈默尔·狄金森是个和她年龄相仿的矿工，就在她父亲管理的格雷姆矿场工作。",
            ["ContentKR"] = "눈치챘겠지만, 하멜은 마님이 40년 전에 사랑했던 사람이야. 그때 마님은... 아니, 아가씨라고 불러야겠군. 그녀는 열정적이고 활발한 소녀였다네.하멜 디킨슨은 아가씨 또래의 광부로, 아가씨의 아버지가 관리하는 글로스터 광갱에서 일하고 있었지.",
            ["DialogueId"] = 51002405,
            ["GUID"] = "7FADDE12",
            ["NextDialogue"] = 51002406,
            ["SpeakNpcId"] = 700020,
            },
        [51002406] = {
            ["Content"] = "像所有俗套的浪漫故事那样，他们越是地位悬殊，就越是执拗，非得逆着全世界的意思在一起。",
            ["ContentKR"] = "많은 로맨스가 그렇듯, 둘은 신분 차이가 큰 만큼 고집스럽게 온 세상의 뜻을 거스르며 함께하려 했지.",
            ["DialogueId"] = 51002406,
            ["GUID"] = "7FADDE3C",
            ["NextDialogue"] = 51002407,
            ["SpeakNpcId"] = 700020,
            ["TalkActionId"] = {
                [1] = "700020:Explain01_End",
                },
            },
        [51002407] = {
            ["Content"] = "那些故事会告诉你，爱情就像一团火，旁人越想扑灭就越烧得旺。但他们不会告诉你，这团火在决堤的现实面前，是多么不值一提！",
            ["ContentKR"] = "그런 이야기들은 사랑이 불덩이 같아서, 다른 사람들이 끄려고 할수록 더 세차게 타오르려고 하지. 하지만 그런 이야기들은 그 불덩어리가 현실 앞에서 얼마나 보잘것없는지 말해주지 않아!",
            ["DialogueId"] = 51002407,
            ["GUID"] = "7FADDE66",
            ["NextDialogue"] = 51002408,
            ["SpeakNpcId"] = 700020,
            },
        [51002408] = {
            ["Content"] = "当这件事传到当年的老爷——也就是工程炼金院派驻格雷姆矿场的董事耳朵里的时候，哈默尔得到的不是祝福，而是一顿毒打。",
            ["ContentKR"] = "이 사실을 알게 된 당시 어르신, 그러니까 공학 연금원에서 글로스터로 파견 나온 관리인에게 하멜은 축복이 아닌 심한 매질을 당했지.",
            ["DialogueId"] = 51002408,
            ["GUID"] = "7FADDE90",
            ["NextDialogue"] = 51002409,
            ["SpeakNpcId"] = 700020,
            },
        [51002409] = {
            ["Content"] = "不只是因为他的身份，更因为老爷已经为小姐安排了一门门当户对的亲事，对方是弗莱格桑行省的贵族——富豪新贵与没落贵族各取所需的联姻，没有比这更合适的婚事了。",
            ["ContentKR"] = "그의 신분뿐만 아니라 어르신은 이미 아가씨를 플래그슨 주의 귀족에게 시집보내기로 하셨거든. 광산 재벌과 몰락 귀족이 서로 원하는 것을 얻을 수 있는 이보다 더 어울리는 결혼은 없었을 거야.",
            ["DialogueId"] = 51002409,
            ["GUID"] = "7FADDEBA",
            ["NextDialogue"] = 51002410,
            ["SpeakNpcId"] = 700020,
            ["TalkActionId"] = {
                [1] = "700020:Explain01_Start",
                },
            },
        [51002410] = {
            ["Content"] = "但小姐没有放弃，那时候的她勇敢又果决。她偷偷拜托我转交哈默尔一封信，约定一个月后，也就是4月26日零点，在银色和平广场见面。",
            ["ContentKR"] = "하지만 아가씨는 포기하지 않았어. 그때의 아가씨는 용감하고 결연했지. 아가씨는 몰래 나에게 하멜에게 편지 한 통을 전해 달라고 부탁했고, 한 달 후인 4월 26일 자정에 은색 평화 광장에서 만나기로 약속했지.",
            ["DialogueId"] = 51002410,
            ["GUID"] = "7FADDEE4",
            ["NextDialogue"] = 51002411,
            ["SpeakNpcId"] = 700020,
            },
        [51002411] = {
            ["Content"] = "那天正赶上老爷生日，仆人们都在为宴会忙前忙后。小姐便计划趁机逃出去，对她来说那是唯一一次逃离的机会。",
            ["ContentKR"] = "그날은 마침 어르신의 생신을 맞아 시종들이 연회 준비로 바쁠 테니까, 아가씨는 그날 도망칠 계획을 세웠어. 아가씨께 그것은 유일한 탈출 기회였다네.",
            ["DialogueId"] = 51002411,
            ["GUID"] = "7FADDF0E",
            ["NextDialogue"] = 51002412,
            ["SpeakNpcId"] = 700020,
            ["TalkActionId"] = {
                [1] = "700020:Explain01_End",
                },
            },
        [51002412] = {
            ["Content"] = "她下定决心，只要哈默尔来，她就打算和他一起走，无论去哪里。",
            ["ContentKR"] = "아가씨는 하멜이 오기만 하면 그와 함께 어디든 떠나기로 결심했어.",
            ["DialogueId"] = 51002412,
            ["GUID"] = "7FADDF38",
            ["NextOptions"] = {
                [1] = 510024141,
                },
            ["SpeakNpcId"] = 700020,
            },
        [51002415] = {
            ["Content"] = "是。希琳小姐在那里等到天亮，等来的却只有气急败坏的父亲。不久之后，她就像一件货物那样，被远嫁到了弗莱格桑行省。",
            ["ContentKR"] = "맞아. 시린 아가씨는 날이 밝을 때까지 그곳에서 기다렸지만, 아가씨를 맞이한 것은 화가 난 아버지뿐이었네. 얼마 후 그녀는 마치 화물처럼 플래그슨 주로 시집보내졌지.",
            ["DialogueId"] = 51002415,
            ["GUID"] = "7FADDFB6",
            ["NextDialogue"] = 51002416,
            ["SpeakNpcId"] = 700020,
            ["TalkActionId"] = {
                [1] = "700020:Agree",
                },
            },
        [51002416] = {
            ["Content"] = "万幸！她的丈夫——也就是后来的老爷对她挺和善的，夫人也度过了四十年平静的时光。她从来不提当年的事情，就像是哈默尔·狄金森从未存在过一样。",
            ["ContentKR"] = "다행히도! 아가씨의 남편, 즉 나중의 어르신은 아가씨께 정말 자상했고, 마님도 40년간 평온한 세월을 보낼 수 있었지.아가씨도 과거의 일을 입 밖에 내는 법이 없었고, 하멜 디킨슨이라는 사람이 존재한 적도 없는 것처럼 행동했지.",
            ["DialogueId"] = 51002416,
            ["GUID"] = "7FADDFE0",
            ["NextDialogue"] = 51002417,
            ["SpeakNpcId"] = 700020,
            },
        [51002417] = {
            ["Content"] = "一年前老爷去世了，夫人的身体也大不如前。一天，她突然告诉我，她想在人生的最后一段时间回到冰湖城，去找一个她一直未曾得到的答案。那时我才知道，哈默尔这个人，她从来都没有忘掉，只是变成了一根扎在心里的刺。",
            ["ContentKR"] = "1년 전 어르신이 돌아가시고 마님의 몸도 예전 같지 않아 지시더니, 하루는 그녀가 갑자기 나에게 인생의 마지막 시간을 아이스레이크 시티로 돌아가 한 번도 얻지 못한 답을 찾고 싶다고 말하더군.그때 알았지, 마님께 있어 하멜은 단 한 번도 잊힌 적이 없었고, 마음속의 가시가 되어버린 것뿐이었다는 것을.",
            ["DialogueId"] = 51002417,
            ["GUID"] = "7FADE00A",
            ["NextDialogue"] = 51002418,
            ["SpeakNpcId"] = 700020,
            },
        [51002418] = {
            ["Content"] = "我们搬来了冰湖城，然而城里没有人知道哈默尔的下落。我们找到了几个还在世的老矿工，但他们回忆了半天，只能想起，最后一次见到哈默尔，已经是四十年前的事了……",
            ["ContentKR"] = "우리는 아이스레이크 시티로 이주해 왔지만, 성안에는 하멜의 행방을 아는 사람이 아무도 없었어. 아직 살아 있는 늙은 광부들을 몇 찾아냈지만, 그들도 한참을 회고하다가 마지막으로 하멜을 본 것이 이미 40년 전의 일이었다는 것만 기억해 냈지...",
            ["DialogueId"] = 51002418,
            ["GUID"] = "7FADE034",
            ["NextDialogue"] = 51002419,
            ["SpeakNpcId"] = 700020,
            ["TalkActionId"] = {
                [1] = "700020:Sigh_Start",
                },
            },
        [51002419] = {
            ["Content"] = "唉，不知道夫人有生之年，还能不能了却最后的心事。",
            ["ContentKR"] = "에휴... 마님이 생전에 마지막 소원을 이루실 수 있을지 모르겠구나.",
            ["DialogueId"] = 51002419,
            ["GUID"] = "7FADE05E",
            ["NextDialogue"] = 51002420,
            ["SpeakNpcId"] = 700020,
            },
        [51002420] = {
            ["Content"] = "都是陈年往事……唉，拉着你唠唠叨叨了这么久，看来我也老了啊。",
            ["ContentKR"] = "다 오래된 일인데... 아, 너한테 이렇게 많은 얘기를 종알거리다니, 나도 이제 늙었나 봐.",
            ["DialogueId"] = 51002420,
            ["GUID"] = "7FADE088",
            ["NextDialogue"] = 51002421,
            ["SpeakNpcId"] = 700020,
            },
        [51002421] = {
            ["Content"] = "你是狩月人，那肯定挺忙的，婶婶就不打扰你啦。",
            ["ContentKR"] = "월석 사냥꾼이면 바쁘겠다. 이만 가볼게.",
            ["DialogueId"] = 51002421,
            ["GUID"] = "7FADE0B2",
            ["NextDialogue"] = 51002422,
            ["SpeakNpcId"] = 700020,
            },
        [51002422] = {
            ["Content"] = "（她不会得到答案了。）",
            ["ContentKR"] = "(그녀는 그 답을 알지 못할 것이다.)",
            ["DialogueId"] = 51002422,
            ["GUID"] = "7FADE0DC",
            ["NextDialogue"] = 51002423,
            },
        [51002423] = {
            ["Content"] = "（哈默尔为了希琳而前往矿坑深处，在那里变成了秽兽，成为了四十年间可怖的传说，最后被击杀——这真相对一位时日无多的老妇人来说，实在是太残酷了。）",
            ["ContentKR"] = "(하멜은 시린을 위해 광갱 깊숙이 들어가 필토이드가 되었고, 40년간 공포의 전설이 되어 마침내 사살되었다. 이 진실은 시간은 얼마 남지 않은 노부인에게 너무나 잔혹했다.)",
            ["DialogueId"] = 51002423,
            ["GUID"] = "7FADE106",
            ["NextDialogue"] = 51002424,
            },
        [51002424] = {
            ["Content"] = "（这个残酷的真相会被永远埋葬在废墟深处，而希琳夫人将带着希望走到生命尽头。也许这已经是最好的结局了。）",
            ["ContentKR"] = "(이 잔혹한 진실은 영원히 폐허 속에 묻히고, 시린 부인은 희망을 안고 마지막을 맞이할 거다. 어쩌면 이것이 최선의 결말인지도 모르겠다.)",
            ["DialogueId"] = 51002424,
            ["GUID"] = "7FADE130",
            },
        [51002425] = {
            ["Content"] = "……只是万万没想到会是这样！哈默尔并没有失约，而是为了和夫人的约定才会去那个矿坑……也不知道这对夫人来说，究竟算是宽慰还是残忍。",
            ["ContentKR"] = "...하지만 이런 결과였을 줄은 꿈에도 몰랐는데! 하멜은 약속을 어긴 게 아니라 마님과의 약속을 지키기 위해 그 광갱에 간 거였어... 이게 마님께 위안이 될지 잔인한 일인지는 모르겠지만 말이야.",
            ["DialogueId"] = 51002425,
            ["GUID"] = "7FADE15A",
            ["NextDialogue"] = 51002426,
            ["SpeakNpcId"] = 700020,
            },
        [51002426] = {
            ["Content"] = "……现在夫人把自己锁在房间里，我也不知道该怎么安慰她才好……",
            ["ContentKR"] = "...이제 와서 어떻게 마님을 위로해야 할지 정말 모르겠네...",
            ["DialogueId"] = 51002426,
            ["GUID"] = "7FADE184",
            ["NextDialogue"] = 51002427,
            ["SpeakNpcId"] = 700020,
            },
        [51002427] = {
            ["Content"] = "真头疼！只能先去准备晚饭了，至少让她喝点我煮的浓汤，身体稍微舒服点吧！",
            ["ContentKR"] = "정말 골치 아프단 말이지! 우선은 저녁 식사를 준비하러 가는 수밖에. 적어도 내가 끓인 진한 수프를 먹으면 몸이라도 조금은 편해지실 거라고 믿어!",
            ["DialogueId"] = 51002427,
            ["GUID"] = "7FADE1AE",
            ["NextDialogue"] = 51002428,
            ["SpeakNpcId"] = 700020,
            },
        [51002428] = {
            ["Content"] = "（是的，尽管真相是如此残酷，但在她最后的时日，终于还是找到了那个迟到了四十年的答案，而不是带着不解和不甘踏入坟墓。也许这已经是最好的结局了。）",
            ["ContentKR"] = "(그래, 진실은 잔혹하지만 마지막에 40년이나 기다린 해답을 찾았고, 의문과 불만을 해결하지 못한 채 무덤에 들어가지는 않게 되었으니까. 아마도 이게 최선의 결말일지도 몰라.)",
            ["DialogueId"] = 51002428,
            ["GUID"] = "7FADE1D8",
            },
        [51002432] = {
            ["Content"] = "唉……到这份上，我们确实不能再瞒着你了。",
            ["ContentKR"] = "에휴... 이제 와서 더 이상 숨길 수도 없겠지.",
            ["DialogueId"] = 51002432,
            ["GUID"] = "51002432.0",
            ["NextDialogue"] = 51002433,
            ["SpeakNpcId"] = 700020,
            ["TalkActionId"] = {
                [1] = "700020:Explain01_Start",
                },
            },
        [51002433] = {
            ["Content"] = "你可能猜到了，哈默尔是夫人四十年前的心上人。那时夫人……不，应该叫她小姐，还是个热情活泼的姑娘。哈默尔·狄金森是个和她年龄相仿的矿工，就在她父亲管理的格雷姆矿场工作。",
            ["ContentKR"] = "눈치챘겠지만, 하멜은 마님이 40년 전에 사랑했던 사람이야. 그때 마님은... 아니, 아가씨라고 불러야겠군. 그녀는 열정적이고 활발한 소녀였다네.하멜 디킨슨은 아가씨 또래의 광부로, 아가씨의 아버지가 관리하는 글로스터 광갱에서 일하고 있었지.",
            ["DialogueId"] = 51002433,
            ["GUID"] = "51002433.0",
            ["NextDialogue"] = 51002434,
            ["SpeakNpcId"] = 700020,
            },
        [51002434] = {
            ["Content"] = "像所有俗套的浪漫故事那样，他们越是地位悬殊，就越是执拗，非得逆着全世界的意思在一起。",
            ["ContentKR"] = "많은 로맨스가 그렇듯, 둘은 신분 차이가 큰 만큼 고집스럽게 온 세상의 뜻을 거스르며 함께하려 했지.",
            ["DialogueId"] = 51002434,
            ["GUID"] = "51002434.0",
            ["NextDialogue"] = 51002435,
            ["SpeakNpcId"] = 700020,
            ["TalkActionId"] = {
                [1] = "700020:Explain01_End",
                },
            },
        [51002435] = {
            ["Content"] = "那些故事会告诉你，爱情就像一团火，旁人越想扑灭就越烧得旺。但他们不会告诉你，这团火在决堤的现实面前，是多么不值一提！",
            ["ContentKR"] = "그런 이야기들은 사랑이 불덩이 같아서, 다른 사람들이 끄려고 할수록 더 세차게 타오르려고 하지. 하지만 그런 이야기들은 그 불덩어리가 현실 앞에서 얼마나 보잘것없는지 말해주지 않아!",
            ["DialogueId"] = 51002435,
            ["GUID"] = "51002435.0",
            ["NextDialogue"] = 51002436,
            ["SpeakNpcId"] = 700020,
            },
        [51002436] = {
            ["Content"] = "当这件事传到当年的老爷——也就是工程炼金院派驻格雷姆矿场的董事耳朵里的时候，哈默尔得到的不是祝福，而是一顿毒打。",
            ["ContentKR"] = "이 사실을 알게 된 당시 어르신, 그러니까 공학 연금원에서 글로스터로 파견 나온 관리인에게 하멜은 축복이 아닌 심한 매질을 당했지.",
            ["DialogueId"] = 51002436,
            ["GUID"] = "51002436.0",
            ["NextDialogue"] = 51002437,
            ["SpeakNpcId"] = 700020,
            },
        [51002437] = {
            ["Content"] = "不只是因为他的身份，更因为老爷已经为小姐安排了一门门当户对的亲事，对方是弗莱格桑行省的贵族——富豪新贵与没落贵族各取所需的联姻，没有比这更合适的婚事了。",
            ["ContentKR"] = "그의 신분뿐만 아니라 어르신은 이미 아가씨를 플래그슨 주의 귀족에게 시집보내기로 하셨거든. 광산 재벌과 몰락 귀족이 서로 원하는 것을 얻을 수 있는 이보다 더 어울리는 결혼은 없었을 거야.",
            ["DialogueId"] = 51002437,
            ["GUID"] = "51002437.0",
            ["NextDialogue"] = 51002438,
            ["SpeakNpcId"] = 700020,
            ["TalkActionId"] = {
                [1] = "700020:Explain01_Start",
                },
            },
        [51002438] = {
            ["Content"] = "但小姐没有放弃，那时候的她勇敢又果决。她偷偷拜托我转交哈默尔一封信，约定一个月后，也就是4月26日零点，在银色和平广场见面。",
            ["ContentKR"] = "하지만 아가씨는 포기하지 않았어. 그때의 아가씨는 용감하고 결연했지. 아가씨는 몰래 나에게 하멜에게 편지 한 통을 전해 달라고 부탁했고, 한 달 후인 4월 26일 자정에 은색 평화 광장에서 만나기로 약속했지.",
            ["DialogueId"] = 51002438,
            ["GUID"] = "51002438.0",
            ["NextDialogue"] = 51002439,
            ["SpeakNpcId"] = 700020,
            },
        [51002439] = {
            ["Content"] = "那天正赶上老爷生日，仆人们都在为宴会忙前忙后。小姐便计划趁机逃出去，对她来说那是唯一一次逃离的机会。",
            ["ContentKR"] = "그날은 마침 어르신의 생신을 맞아 시종들이 연회 준비로 바쁠 테니까, 아가씨는 그날 도망칠 계획을 세웠어. 아가씨께 그것은 유일한 탈출 기회였다네.",
            ["DialogueId"] = 51002439,
            ["GUID"] = "51002439.0",
            ["NextDialogue"] = 51002440,
            ["SpeakNpcId"] = 700020,
            ["TalkActionId"] = {
                [1] = "700020:Explain01_End",
                },
            },
        [51002440] = {
            ["Content"] = "她下定决心，只要哈默尔来，她就打算和他一起走，无论去哪里。",
            ["ContentKR"] = "아가씨는 하멜이 오기만 하면 그와 함께 어디든 떠나기로 결심했어.",
            ["DialogueId"] = 51002440,
            ["GUID"] = "51002440.0",
            ["NextOptions"] = {
                [1] = 51002441,
                },
            ["SpeakNpcId"] = 700020,
            },
        [51002441] = {
            ["Content"] = "但是哈默尔爽约了？",
            ["ContentKR"] = "그런데 하멜이 약속을 어겼나요?",
            ["DialogueId"] = 51002441,
            ["GUID"] = "51002441.0",
            ["NextDialogue"] = 51002442,
            },
        [51002442] = {
            ["Content"] = "是。希琳小姐在那里等到天亮，等来的却只有气急败坏的父亲。不久之后，她就像一件货物那样，被远嫁到了弗莱格桑行省。",
            ["ContentKR"] = "맞아. 시린 아가씨는 날이 밝을 때까지 그곳에서 기다렸지만, 아가씨를 맞이한 것은 화가 난 아버지뿐이었네. 얼마 후 그녀는 마치 화물처럼 플래그슨 주로 시집보내졌지.",
            ["DialogueId"] = 51002442,
            ["GUID"] = "51002442.0",
            ["NextDialogue"] = 51002443,
            ["SpeakNpcId"] = 700020,
            ["TalkActionId"] = {
                [1] = "700020:Agree",
                },
            },
        [51002443] = {
            ["Content"] = "万幸！她的丈夫——也就是后来的老爷对她挺和善的，夫人也度过了四十年平静的时光。她从来不提当年的事情，就像是哈默尔·狄金森从未存在过一样。",
            ["ContentKR"] = "다행히도! 아가씨의 남편, 즉 나중의 어르신은 아가씨께 정말 자상했고, 마님도 40년간 평온한 세월을 보낼 수 있었지.아가씨도 과거의 일을 입 밖에 내는 법이 없었고, 하멜 디킨슨이라는 사람이 존재한 적도 없는 것처럼 행동했지.",
            ["DialogueId"] = 51002443,
            ["GUID"] = "51002443.0",
            ["NextDialogue"] = 51002444,
            ["SpeakNpcId"] = 700020,
            },
        [51002444] = {
            ["Content"] = "一年前老爷去世了，夫人的身体也大不如前。一天，她突然告诉我，她想在人生的最后一段时间回到冰湖城，去找一个她一直未曾得到的答案。那时我才知道，哈默尔这个人，她从来都没有忘掉，只是变成了一根扎在心里的刺。",
            ["ContentKR"] = "1년 전 어르신이 돌아가시고 마님의 몸도 예전 같지 않아 지시더니, 하루는 그녀가 갑자기 나에게 인생의 마지막 시간을 아이스레이크 시티로 돌아가 한 번도 얻지 못한 답을 찾고 싶다고 말하더군.그때 알았지, 마님께 있어 하멜은 단 한 번도 잊힌 적이 없었고, 마음속의 가시가 되어버린 것뿐이었다는 것을.",
            ["DialogueId"] = 51002444,
            ["GUID"] = "51002444.0",
            ["NextDialogue"] = 51002445,
            ["SpeakNpcId"] = 700020,
            },
        [51002445] = {
            ["Content"] = "我们搬来了冰湖城，然而城里没有人知道哈默尔的下落。我们找到了几个还在世的老矿工，但他们回忆了半天，只能想起，最后一次见到哈默尔，已经是四十年前的事了……",
            ["ContentKR"] = "우리는 아이스레이크 시티로 이주해 왔지만, 성안에는 하멜의 행방을 아는 사람이 아무도 없었어. 아직 살아 있는 늙은 광부들을 몇 찾아냈지만, 그들도 한참을 회고하다가 마지막으로 하멜을 본 것이 이미 40년 전의 일이었다는 것만 기억해 냈지...",
            ["DialogueId"] = 51002445,
            ["GUID"] = "51002445.0",
            ["NextDialogue"] = 51002425,
            ["SpeakNpcId"] = 700020,
            ["TalkActionId"] = {
                [1] = "700020:Sigh_Start",
                },
            },
        [51002501] = {
            ["Content"] = "走，走开……不买月石的话就赶紧走……别把那群当兵的引来了……",
            ["ContentKR"] = "가, 가세요... 월석 살 생각 없으면 가세요... 괜히 병사들 눈길만 끌지 말고...",
            ["DialogueId"] = 51002501,
            ["GUID"] = "7FADEDD2",
            ["NextDialogue"] = 51002502,
            ["SpeakNpcId"] = 700113,
            ["TalkActionId"] = {
                [1] = "700113:Shock_Start",
                },
            },
        [51002502] = {
            ["Content"] = "（男人瑟缩在角落。他的眼神躲闪，渴望将身旁的月石脱手，却迟疑着要不要向他人寻求帮助。）",
            ["ContentKR"] = "(건장한 체격과는 달리 남자는 구석에서 떨고 있다. 갖고 있는 월석을 팔고 싶어 하는 눈치였지만, 도움을 청하기는 주저하고 있다.)",
            ["DialogueId"] = 51002502,
            ["GUID"] = "7FADEDFC",
            ["TalkActionId"] = {
                [1] = "700113:Shock_End",
                },
            ["TalkOptions"] = {
                [1] = 510025021,
                [2] = 510025022,
                [3] = 510025023,
                [4] = 510025024,
                },
            },
        [51002503] = {
            ["Content"] = "您高抬贵手，把我当个屁放了吧，我只要把这批月石卖掉就立马离开冰湖城，绝不回来。",
            ["ContentKR"] = "한 번만 못 본 척해주세요. 월석만 다 팔면 아이스레이크 시티를 떠나 다시 오지 않을게요.",
            ["DialogueId"] = 51002503,
            ["GUID"] = "7FADEE26",
            ["SpeakNpcId"] = 700113,
            },
        [51002504] = {
            ["Content"] = "（男人听罢提起袋子就要跑，好不容易向他说明玩笑并解释身份后，他才悄声说明了自己的难处。）",
            ["ContentKR"] = "(말을 듣자마자 남자는 자루를 챙겨 도망치려 한다. 겨우 농담이었다는 말과 함께 신분을 밝히니 슬그머니 본인의 고충을 털어놓는다.)",
            ["DialogueId"] = 51002504,
            ["GUID"] = "7FADEE50",
            },
        [51002505] = {
            ["Content"] = "只要你帮我找个买家，报酬分你七成，不，八成！拜托了，拜托！",
            ["ContentKR"] = "구매자를 찾아 주시면 몫의 70%... 아니, 80%를 드릴게요! 부탁이에요, 제발!",
            ["DialogueId"] = 51002505,
            ["GUID"] = "7FADEE7A",
            ["SpeakNpcId"] = 700113,
            ["TalkActionId"] = {
                [1] = "700113:Sigh_Start",
                },
            },
        [51002506] = {
            ["Content"] = "（虽说答应了男人的委托，但他的神色和袋子上干涸的血迹都宣告着这批月石的危险性，想到这里，那“买家”就只能找那个人了。）",
            ["ContentKR"] = "(남자의 의뢰를 수락하긴 했지만, 그의 표정과 자루에 말라붙어 있는 검붉은 흔적은 이 월석들이 정상적인 물건이 아니라는 걸 말해 주고 있었다.)",
            ["DialogueId"] = 51002506,
            ["GUID"] = "7FADEEA4",
            ["TalkActionId"] = {
                [1] = "700113:Sigh_End",
                },
            },
        [51002601] = {
            ["Content"] = "太好了，今天没碰到{nickname}……",
            ["ContentKR"] = "오늘은 {nickname}, 그 녀석과 안 마주쳐서 다행이야...",
            ["DialogueId"] = 51002601,
            ["GUID"] = "7FADFE3A",
            ["NextDialogue"] = 51002602,
            ["SpeakNpcId"] = 700111,
            ["TalkActionId"] = {
                [1] = "700111:Think_Start",
                },
            },
        [51002602] = {
            ["Content"] = "你找我吗。",
            ["ContentKR"] = "저 말씀인가요?",
            ["DialogueId"] = 51002602,
            ["GUID"] = "7FADFE64",
            ["NextDialogue"] = 51002603,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700111:Think_End",
                },
            },
        [51002603] = {
            ["Content"] = "……啊！你怎么又来了！",
            ["ContentKR"] = "...앗! 네가 왜...!",
            ["DialogueId"] = 51002603,
            ["GUID"] = "7FADFE8E",
            ["NextOptions"] = {
                [1] = 510026031,
                },
            ["SpeakNpcId"] = 700111,
            ["TurnTo"] = {
                [1] = "700111:n(0)",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51002604] = {
            ["Content"] = "啊……你想骗我，故意给我找点事做对吧。",
            ["ContentKR"] = "흠... 일부러 날 부려 먹으려고 수작 부리는 건 아니고?",
            ["DialogueId"] = 51002604,
            ["GUID"] = "7FADFEB8",
            ["SpeakNpcId"] = 700111,
            ["TalkActionId"] = {
                [1] = "700111:Disagree",
                },
            },
        [51002605] = {
            ["Content"] = "（大门旁突然响起急促的电话铃声，凯文如同受惊的兔子一般跳起，急匆匆地接起电话。）",
            ["ContentKR"] = "(입구 근처에서 갑자기 전화벨이 울린다. 화들짝 놀란 케빈이 다급히 전화를 받는다.)",
            ["DialogueId"] = 51002605,
            ["GUID"] = "7FADFEE2",
            ["NextDialogue"] = 51002606,
            ["TurnTo"] = {
                [1] = "700111:p(90)",
                },
            },
        [51002606] = {
            ["Content"] = "是我……有可疑人士出没？收到，我这就过去。",
            ["ContentKR"] = "나다. ...거동수상자가 출현했다고? 그래, 지금 바로 가지.",
            ["DialogueId"] = 51002606,
            ["GUID"] = "7FADFF0C",
            ["NextDialogue"] = 51002607,
            ["SpeakNpcId"] = 700111,
            ["TalkActionId"] = {
                [1] = "700111:Agree",
                },
            },
        [51002607] = {
            ["Content"] = "……该不会就是你说的那个人吧，走吧，带我去看看。",
            ["ContentKR"] = "...설마 네가 말한 그 사람인 건가... 같이 가보자.",
            ["DialogueId"] = 51002607,
            ["GUID"] = "7FADFF36",
            ["Scripts"] = "SEQ{TurnTo{TurnToDescription{\"700111:n(0)\"}},PlayAnimation{ActorId{700111},AnimationId{\"Think_Start\"},Duration{2}}}",
            ["SpeakNpcId"] = 700111,
            },
        [51002701] = {
            ["Camera"] = "221.641602,5.540039,120.836426,0.000002,0.200002,-178.397919,25.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "咦，这不是曾经的模范劳工拉里吗？你平时身边不是老跟着几个兄弟的吗，咋今天就一个人了。",
            ["ContentKR"] = "어? 넌 그 성실한 래리잖아? 평소엔 항상 친구랑 같이 다니면서 오늘은 혼자네?",
            ["DialogueId"] = 51002701,
            ["GUID"] = "7FAE0EA2",
            ["NextDialogue"] = 51002702,
            ["SpeakNpcId"] = 700112,
            ["TalkActionId"] = {
                [1] = "700112:Talk01_Start",
                [2] = "100001:Confident_Start",
                },
            ["TurnTo"] = {
                [1] = "700114:n(700112)",
                },
            },
        [51002702] = {
            ["Camera"] = "11.023438,10.769531,127.256836,0.0,0.0,8.403177,25.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "卫，卫戍部队？？！",
            ["ContentKR"] = "바, 방위대??!",
            ["DialogueId"] = 51002702,
            ["FinalCamera"] = "39.697266,15.063477,127.256836,0.0,0.0,8.403239,25.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FAE0ECC",
            ["NextDialogue"] = 51002703,
            ["SpeakNpcId"] = 700114,
            ["TalkActionId"] = {
                [1] = "700114:Shock_Start",
                [2] = "700112:Talk01_End",
                [3] = "100001:Confident_End",
                },
            ["ToFinalCameraBlendTime"] = 1,
            },
        [51002703] = {
            ["Camera"] = "221.641602,5.540039,120.836426,0.000002,0.200002,-178.397919,25.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "没事他们也不关键，倒是你啊，应该知道私自开采与贩卖月石都是违规行为的吧，我收到上级通知来……嘶，你这袋子上的血是怎么回事？",
            ["ContentKR"] = "지금 그게 중요한 건 아니고, 상부의 명으로 왔어. 몰래 월석을 캐서 파는 게 불법인 걸 네가 모를 리도 없고... 어라, 자루에 이 피는 뭐지?",
            ["DialogueId"] = 51002703,
            ["GUID"] = "7FAE0EF6",
            ["NextDialogue"] = 51002704,
            ["SpeakNpcId"] = 700112,
            ["TalkActionId"] = {
                [1] = "700114:Shock_End",
                [2] = "700112:Talk01_Start",
                },
            },
        [51002704] = {
            ["Camera"] = "-24.264648,5.625977,122.256836,0.0,0.0,8.403694,25.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我，我……",
            ["ContentKR"] = "그, 그게...",
            ["DialogueId"] = 51002704,
            ["GUID"] = "7FAE0F20",
            ["NextDialogue"] = 51002705,
            ["Scripts"] = "SEQ{LookAt{LookAtDescription{\"700114:n(100001)\"}},LookAt{LookAtDescription{\"700114:n(700114)\"}}}",
            ["SpeakNpcId"] = 700114,
            ["TalkActionId"] = {
                [1] = "700112:Talk01_End",
                },
            },
        [51002705] = {
            ["Camera"] = "121.136719,-1.510742,123.537598,0.000002,0.399996,-168.191696,25.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "别跑！{nickname}，搭把手！",
            ["ContentKR"] = "거기 서! {nickname}, 도와줘!",
            ["DialogueId"] = 51002705,
            ["GUID"] = "7FAE0F4A",
            ["Scripts"] = "SEQ{PlayAnimation{ActorId{700112},AnimationId{\"Angry01_Start\"},Duration{2}},LookAt{LookAtDescription{\"700112:n(100001)\"}},PlayAnimation{ActorId{100001},AnimationId{\"Talk03_Start\"},Duration{1}}}",
            ["SpeakNpcId"] = 700112,
            },
        [51002801] = {
            ["Camera"] = "-297.869141,-392.973633,116.237793,0.000001,0.0,37.400127,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你，你这家伙居然骗我！为什么要把当兵的叫过来！",
            ["ContentKR"] = "이, 이 자식 날 속이다니! 병사는 왜 불러온 거야!",
            ["DialogueId"] = 51002801,
            ["GUID"] = "7FAE1F0A",
            ["NextDialogue"] = 51002802,
            ["SpeakNpcId"] = 700114,
            ["TalkActionId"] = {
                [1] = "700114:Sigh_Start",
                },
            },
        [51002802] = {
            ["Camera"] = "435.016602,-46.152344,110.63623,0.000004,0.0,-169.994827,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "闭嘴，手放到我能看到的位置……双手张开，麻袋放下！",
            ["ContentKR"] = "조용히 해. 자루는 내려놓고, 손 들어!",
            ["DialogueId"] = 51002802,
            ["GUID"] = "7FAE1F34",
            ["NextDialogue"] = 51002803,
            ["SpeakNpcId"] = 700112,
            ["TalkActionId"] = {
                [1] = "700112:Angry01_Start",
                },
            },
        [51002803] = {
            ["Camera"] = "435.016602,-46.152344,110.63623,0.000004,0.0,-169.994827,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（黑洞洞的枪口顶在拉里头上，拉里犹豫了一下最终摊开双手。麻袋掉落地面，一颗颗沾血的月石顺势洒落在了众人脚下。）",
            ["ContentKR"] = "(시커먼 총구를 머리에 겨누자, 래리는 머뭇거리다 두 손을 펼친다. 그리고 바닥으로 떨어진 자루에서 피 묻은 월석이 쏟아진다.)",
            ["DialogueId"] = 51002803,
            ["GUID"] = "7FAE1F5E",
            ["NextDialogue"] = 51002804,
            ["TalkActionId"] = {
                [1] = "700114:Sigh_End",
                [2] = "700112:Angry01_End",
                },
            },
        [51002804] = {
            ["Camera"] = "435.016602,-46.152344,110.63623,0.000004,0.0,-169.994827,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……你用它们砸死了你的那群兄弟？",
            ["ContentKR"] = "...이걸로 친구들을 때려죽인 건가?",
            ["DialogueId"] = 51002804,
            ["GUID"] = "7FAE1F88",
            ["NextDialogue"] = 51002805,
            ["SpeakNpcId"] = 700112,
            },
        [51002805] = {
            ["Camera"] = "-297.869141,-392.973633,116.237793,0.000001,0.0,37.400127,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "是他们先动手的……我，我这都是正当防卫！",
            ["ContentKR"] = "걔네가 먼저 시작했어요... 저, 저는 정당방위라고요!",
            ["DialogueId"] = 51002805,
            ["GUID"] = "7FAE1FB2",
            ["NextDialogue"] = 51002806,
            ["SpeakNpcId"] = 700114,
            ["TalkActionId"] = {
                [1] = "700114:Sigh_Start",
                },
            },
        [51002806] = {
            ["Camera"] = "435.016602,-46.152344,110.63623,0.000004,0.0,-169.994827,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "正不正当我跟你说了不算，走！",
            ["ContentKR"] = "정당방위인지 아닌지는 이제 가서 따져 봐야지. 가자!",
            ["DialogueId"] = 51002806,
            ["GUID"] = "7FAE1FDC",
            ["NextDialogue"] = 51002807,
            ["SpeakNpcId"] = 700112,
            ["TalkActionId"] = {
                [1] = "700114:Sigh_End",
                [2] = "700112:Talk01_Start",
                },
            },
        [51002807] = {
            ["Camera"] = "435.016602,-46.152344,110.63623,0.000004,0.0,-169.994827,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "不能怪我，不能怪我……！啊啊，都怪这袋月石！要不是刚好翻开了这个破袋子，我们现在一定都还好好的，都好好的！",
            ["ContentKR"] = "아니, 내 탓이 아니에요...! 아, 다 이 월석 때문이라고요! 이 자루를 열지만 않았다면 모두 아무 일 없었을 거예요!",
            ["DialogueId"] = 51002807,
            ["GUID"] = "7FAE2006",
            ["NextDialogue"] = 51002808,
            ["SpeakNpcId"] = 700114,
            ["TalkActionId"] = {
                [1] = "700114:Disagree",
                [2] = "700112:Talk01_End",
                },
            },
        [51002808] = {
            ["Camera"] = "121.290039,-83.856445,144.21875,0.000003,-0.999905,-165.995453,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "唉……",
            ["ContentKR"] = "휴...",
            ["DialogueId"] = 51002808,
            ["GUID"] = "7FAE2030",
            ["NextDialogue"] = 51002809,
            ["SpeakNpcId"] = 700112,
            ["TalkActionId"] = {
                [1] = "700112:Disagree",
                },
            },
        [51002809] = {
            ["Camera"] = "-3.327148,-490.567383,115.4375,0.000011,0.0,94.803833,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "对了，还得例行公事一下。感谢{nickname}给卫戍部队提供的帮助，这些是协助的报酬。",
            ["ContentKR"] = "아, 참. 인사는 해야지. 도와줘서 고마워, {nickname}. 이건 방금 일에 대한 보답이야.",
            ["DialogueId"] = 51002809,
            ["GUID"] = "7FAE205A",
            ["Scripts"] = "SEQ{PARA{TurnTo{TurnToDescription{\"700112:n(100001)\"}},TurnTo{TurnToDescription{\"100001:n(700112)\"}}},PlayAnimation{ActorId{700112},AnimationId{\"Agree\"},Duration{1}},PlayAnimation{ActorId{700112},AnimationId{\"Talk01_Start\"},Duration{1}}}",
            ["SpeakNpcId"] = 700112,
            },
        [51002810] = {
            ["Content"] = "拉里被凯文押送着渐渐走远。",
            ["ContentKR"] = "케빈이 래리를 연행해 간다.",
            ["DialogueId"] = 51002810,
            ["Duration"] = 2,
            ["GUID"] = "7FAE2084",
            ["NextDialogue"] = 51002811,
            },
        [51002811] = {
            ["Content"] = "这袋“血石”背后所蕴含的血腥过往，也随着拉里的离去，淹没在冰湖城的又一片雪花之下。",
            ["ContentKR"] = "래리가 떠나며 '피 묻은 월석'에 숨겨진 잔인한 과거도 아이스레이크 시티의 눈 속에 묻혀 사라진다.",
            ["DialogueId"] = 51002811,
            ["Duration"] = 4,
            ["GUID"] = "7FAE20AE",
            },
        [51002901] = {
            ["Content"] = "（一个嗓门奇高的人在大声念诵着什么，酒客们有一搭没一搭听着，时不时发出快活的笑声。）",
            ["ContentKR"] = "(누군가 큰 목소리로 무언가를 읽고 있고, 술꾼들은 아랑곳하지 않고 신나게 웃고 있다.)",
            ["DialogueId"] = 51002901,
            ["GUID"] = "7FAE2F72",
            ["NextDialogue"] = 51002902,
            },
        [51002902] = {
            ["Content"] = "来自深山的幽魂，来自冰湖的鬼魅！",
            ["ContentKR"] = "깊은 산 속의 유령, 아이스레이크의 귀신!",
            ["DialogueId"] = 51002902,
            ["GUID"] = "7FAE2F9C",
            ["NextDialogue"] = 51002903,
            ["SpeakNpcId"] = 700015,
            },
        [51002903] = {
            ["Content"] = "它们在逼近！它们在逼近！",
            ["ContentKR"] = "다가온다! 여기로 다가온다!",
            ["DialogueId"] = 51002903,
            ["GUID"] = "7FAE2FC6",
            ["NextDialogue"] = 51002904,
            ["SpeakNpcId"] = 700015,
            },
        [51002904] = {
            ["Content"] = "你来了？",
            ["ContentKR"] = "왔어?",
            ["DialogueId"] = 51002904,
            ["GUID"] = "7FAE2FF0",
            ["NextOptions"] = {
                [1] = 510029041,
                },
            ["SpeakNpcId"] = 200003,
            },
        [51002905] = {
            ["Content"] = "我手里暂且没什么活儿给你，不过……",
            ["ContentKR"] = "아직은 맡길 일이 없어. 다만...",
            ["DialogueId"] = 51002905,
            ["GUID"] = "7FAE301A",
            ["NextDialogue"] = 51002906,
            ["SpeakNpcId"] = 200003,
            },
        [51002906] = {
            ["Content"] = "……你们无法想象！",
            ["ContentKR"] = "...다들 상상도 못 할 거야!",
            ["DialogueId"] = 51002906,
            ["GUID"] = "7FAE3044",
            ["NextDialogue"] = 51002907,
            ["SpeakNpcId"] = 700015,
            },
        [51002907] = {
            ["Content"] = "一个幽灵！！！一个穿门入户的无声行者！！！！",
            ["ContentKR"] = "유령이다!!! 소리 소문 없이 방문하는 존재지!!!!",
            ["DialogueId"] = 51002907,
            ["GUID"] = "7FAE306E",
            ["NextDialogue"] = 51002908,
            ["SpeakNpcId"] = 700015,
            },
        [51002908] = {
            ["Content"] = "如你所听，总是有碰上麻烦的人。",
            ["ContentKR"] = "보다시피 성가신 사람은 늘 있지.",
            ["DialogueId"] = 51002908,
            ["GUID"] = "7FAE3098",
            ["NextOptions"] = {
                [1] = 510029081,
                },
            ["SpeakNpcId"] = 200003,
            },
        [51002909] = {
            ["Content"] = "巴克先生，因为沾一点酒精就倒，所以平时只点果汁和牛奶。职业嘛……三流的剧作家，一流的不好懂。喏，已经在那里絮絮叨叨半天了。",
            ["ContentKR"] = "바크 씨야. 술은 입에도 못 대는 사람이라, 평소엔 주스나 우유만 시키지. 직업은... 삼류 극작가인데, 내용만큼은 일류급으로 난해해. 저거 봐, 벌써 한참이나 저기서 횡설수설하고 있어.",
            ["DialogueId"] = 51002909,
            ["GUID"] = "7FAE30C2",
            ["NextDialogue"] = 51002910,
            ["SpeakNpcId"] = 200003,
            },
        [51002910] = {
            ["Content"] = "如你所见，他好像没办法明确表达自己的诉求，你要给他翻译翻译吗？",
            ["ContentKR"] = "보다시피 원하는 걸 잘 표현하지 못하는 것 같아. 네가 해석해 줄래?",
            ["DialogueId"] = 51002910,
            ["GUID"] = "7FAE30EC",
            ["NextOptions"] = {
                [1] = 510029101,
                },
            ["RestartTag"] = 51002910,
            ["SpeakNpcId"] = 200003,
            ["bForbidSkipOptions"] = true,
            },
        [51002911] = {
            ["Content"] = "别沮丧，整个冰湖城能听懂他在说什么的也不超过一个巴掌数。",
            ["ContentKR"] = "괜찮아. 아이스레이크 시티에서 바크 씨의 말을 알아듣는 사람은 몇 명 없거든.",
            ["DialogueId"] = 51002911,
            ["GUID"] = "7FAE3116",
            ["SpeakNpcId"] = 200003,
            },
        [51002912] = {
            ["Content"] = "以你的才智，这份工作看来非你莫属了。",
            ["ContentKR"] = "너의 그 재치라면 문제없을 거야.",
            ["DialogueId"] = 51002912,
            ["GUID"] = "7FAE3140",
            ["SpeakNpcId"] = 200003,
            },
        [51003001] = {
            ["Content"] = "（你侧耳倾听剧作家的高谈阔论。）",
            ["ContentKR"] = "(극작가의 장황한 말에 집중한다.)",
            ["DialogueId"] = 51003001,
            ["GUID"] = "7FAE3FDA",
            ["NextDialogue"] = 51003002,
            },
        [51003002] = {
            ["Content"] = "诗人的夜晚总是漫长……剧作家也不例外！我们的笔书写着人间的脉动，我们的心自然也与潮汐和月亮为伴！",
            ["ContentKR"] = "시인의 밤은 늘 길고 깁니다... 극작가도 예외는 아니죠! 펜으로 세상이 살아 숨 쉬는 이야기를 쓰다 보면, 자연스레 조석과 달을 친구로 삼게 되는 법이죠!",
            ["DialogueId"] = 51003002,
            ["GUID"] = "7FAE4004",
            ["NextDialogue"] = 51003003,
            ["SpeakNpcId"] = 700015,
            ["TalkActionId"] = {
                [1] = "700015:Talk01_Start",
                },
            },
        [51003003] = {
            ["Content"] = "抛却了令人炫目的阳光，抛却了人间的声响，抛却了浮躁的心思，此时才是我与世界促膝长谈的时刻！",
            ["ContentKR"] = "눈부신 햇빛이 걷히고 세상의 소리와 들뜬 마음이 사라지는 그때가 바로 자신과 세상이 독대하는 시간입니다.",
            ["DialogueId"] = 51003003,
            ["GUID"] = "7FAE402E",
            ["NextOptions"] = {
                [1] = 510030031,
                [2] = 510030032,
                },
            ["SpeakNpcId"] = 700015,
            ["TalkActionId"] = {
                [1] = "700015:Talk01_End",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51003004] = {
            ["Content"] = "啊！要么是我不自知的怠慢惹恼了掌管灵感的女神，要么就是睡眠之神在刻意作弄我！否则我怎么会任由光阴的车轮滚滚而过，却没有半分察觉！",
            ["ContentKR"] = "아! 어쩌면 제 게으름 때문에 영감의 여신이 화났거나, 잠의 신이 장난치는 걸 거예요! 그게 아니라면 시간의 수레바퀴를 제가 못 느꼈을 리 없어요!",
            ["DialogueId"] = 51003004,
            ["GUID"] = "7FAE4058",
            ["NextDialogue"] = 51003005,
            ["SpeakNpcId"] = 700015,
            ["TalkActionId"] = {
                [1] = "700015:Sigh_Start",
                },
            },
        [51003005] = {
            ["Content"] = "我应当用写满文辞的纸张去迎接清晨的到来，而不是只留下一个徒有健康的我与空白的稿纸！",
            ["ContentKR"] = "저는 건강만 남은 저 자신과 새하얀 빈 종이가 아니라, 글이 가득 담긴 종이와 함께 새벽을 맞이해야 합니다.",
            ["DialogueId"] = 51003005,
            ["GUID"] = "7FAE4082",
            ["NextOptions"] = {
                [1] = 510030051,
                [2] = 510030052,
                },
            ["SpeakNpcId"] = 700015,
            ["TalkActionId"] = {
                [1] = "700015:Sigh_End",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51003006] = {
            ["Content"] = "在充满诱惑的睡梦中，我听到窸窣的足音，它是那么轻盈，像精灵的旋舞，我闻到饱满果实的气味，那上面一定浇着厚厚的蜜糖！",
            ["ContentKR"] = "유혹이 가득한 꿈속에서 발소리를 들었어요. 요정의 춤처럼 가벼웠고 과일 향이 풍겨왔죠. 분명 그 위에는 꿀이 떨어지고 있을 거예요!",
            ["DialogueId"] = 51003006,
            ["GUID"] = "7FAE40AC",
            ["NextDialogue"] = 51003007,
            ["SpeakNpcId"] = 700015,
            ["TalkActionId"] = {
                [1] = "700015:Explain01_Start",
                },
            },
        [51003007] = {
            ["Content"] = "或许我曾在梦中迷失，但这声息与味道引领我回到现实，他们缥缈不定，他们萦绕我身，他们确实存在……",
            ["ContentKR"] = "제가 꿈에서 길을 잃은 걸지도 몰라요. 하지만 그 소리와 향기가 저를 에워싸고 현실로 이끌었어요. 분명 실존할 거예요...",
            ["DialogueId"] = 51003007,
            ["GUID"] = "7FAE40D6",
            ["NextOptions"] = {
                [1] = 510030071,
                [2] = 510030072,
                },
            ["SpeakNpcId"] = 700015,
            ["TalkActionId"] = {
                [1] = "700015:Explain01_End",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51003008] = {
            ["Content"] = "他们绝不是我的幻觉，但我抓不住痕迹的尾巴，我勘不破这诡秘的行径，是幽灵？是鬼魅？是幻影？",
            ["ContentKR"] = "환상은 절대 아니었어요. 그렇지만 그 흔적을 찾을 수 없어서 확신은 못 하겠어요. 유령? 귀신? 아니면 환영인 걸까요?",
            ["DialogueId"] = 51003008,
            ["GUID"] = "7FAE4100",
            ["NextDialogue"] = 51003009,
            ["SpeakNpcId"] = 700015,
            ["TalkActionId"] = {
                [1] = "700015:Disagree",
                },
            },
        [51003009] = {
            ["Content"] = "我那贫瘠的破屋不增不减，他唯独偷窃了我视为生命的灵感！眼看他就要让我的梦破碎……",
            ["ContentKR"] = "제 허름한 집은 그대로 두고, 제 목숨과도 같은 영감만 훔쳐 달아났어요! 제 꿈이 산산조각 날 거예요...",
            ["DialogueId"] = 51003009,
            ["GUID"] = "7FAE412A",
            ["NextOptions"] = {
                [1] = 510030091,
                [2] = 510030092,
                },
            ["SpeakNpcId"] = 700015,
            ["bForbidSkipOptions"] = true,
            },
        [51003010] = {
            ["Content"] = "剧作家的夜晚是绝不可以付诸于睡眠的！在座的诸位谁能听从我的召唤，去为我、去为那即将问世的著作驱散那偷走灵感的窃贼！",
            ["ContentKR"] = "극작가의 밤은 잠에 굴복할 수 없는 법이죠! 여러분 중 저와 곧 탄생할 작품을 위해 영감을 훔친 그 도둑을 쫓아내 주실 분이 계신가요!",
            ["DialogueId"] = 51003010,
            ["GUID"] = "7FAE4154",
            ["NextDialogue"] = 51003011,
            ["SpeakNpcId"] = 700015,
            ["TalkActionId"] = {
                [1] = "700015:Talk03_Start",
                },
            },
        [51003011] = {
            ["Content"] = "我将给予你荣耀，给予你身为主角的可能，让我见识你的出色，让我愿意为狩月人作传吧！",
            ["ContentKR"] = "명예와 함께 주인공이 될 기회를 드리겠습니다. 당신의 능력을 보여주세요! 월석 사냥꾼의 이야기를 널리 알리게 해주세요!",
            ["DialogueId"] = 51003011,
            ["GUID"] = "7FAE417E",
            ["NextOptions"] = {
                [1] = 510030111,
                [2] = 510030112,
                },
            ["SpeakNpcId"] = 700015,
            ["TalkActionId"] = {
                [1] = "700015:Talk03_End",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51003012] = {
            ["Content"] = "虽然没什么钱赚，但听起来很有意思，你想接吗？",
            ["ContentKR"] = "돈은 안되지만 재밌을 것 같아. 네가 해볼래?",
            ["DialogueId"] = 51003012,
            ["GUID"] = "7FAE41A8",
            ["NextOptions"] = {
                [1] = 510030121,
                [2] = 510030122,
                },
            ["SpeakNpcId"] = 200003,
            ["bForbidSkipOptions"] = true,
            },
        [51003013] = {
            ["Content"] = "哦！回应我呼唤的勇士出现了，这说不定是一段崭新冒险的序幕！",
            ["ContentKR"] = "오! 부름에 응답한 용사가 나타났군요. 어쩌면 새로운 모험의 서막이 될 수도 있습니다!",
            ["DialogueId"] = 51003013,
            ["GUID"] = "7FAE41D2",
            ["NextDialogue"] = 51003014,
            ["SpeakNpcId"] = 700015,
            ["TalkActionId"] = {
                [1] = "700015:Talk01_Start",
                },
            ["TurnTo"] = {
                [1] = "700015:n(0)",
                },
            },
        [51003014] = {
            ["Content"] = "我对你们接下来碰到的事情抱以十足的兴趣，当你们归来，请为我讲述你们的故事吧！",
            ["ContentKR"] = "앞으로 벌어질 일이 기대되는군요. 돌아오면 당신들의 이야기를 들려주세요!",
            ["DialogueId"] = 51003014,
            ["GUID"] = "7FAE41FC",
            ["SpeakNpcId"] = 700015,
            ["TalkActionId"] = {
                [1] = "700015:Talk01_End",
                },
            },
        [51003101] = {
            ["Content"] = "据卡米拉所说，巴克先生不胜酒力、从不喝酒，那壶里的酒难道是其他人加进去的？",
            ["ContentKR"] = "카밀라는 바크 씨가 술을 전혀 못 마신다고 했었어. 그럼 주전자에 담겨 있는 술은 다른 사람이 넣은 건가?",
            ["DialogueId"] = 51003101,
            ["GUID"] = "7FAE5042",
            ["NextDialogue"] = 51003102,
            ["SpeakNpcId"] = 100001,
            },
        [51003102] = {
            ["Content"] = "仔细一看，这牛奶壶上还有个黏糊糊的手印……看起来那只手很小巧。",
            ["ContentKR"] = "자세히 보니까, 주전자에 끈적끈적한 손자국이 남아 있어... 꽤 작아 보이는데.",
            ["DialogueId"] = 51003102,
            ["GUID"] = "7FAE506C",
            ["SpeakNpcId"] = 100001,
            },
        [51003103] = {
            ["Content"] = "小小的脚印从屋外延伸至窗台，屋内还有雪化的积水。显然闯入者没有处理痕迹的意识，单纯就只是一个小孩子而已。",
            ["ContentKR"] = "집 바깥에서부터 창문까지 조그만 발자국이 이어져 있고, 집 안에는 눈 녹은 물이 고여 있어. 침입자는 흔적을 지워야겠단 생각조차 못 한 어린애였던 게 분명해.",
            ["DialogueId"] = 51003103,
            ["GUID"] = "7FAE5096",
            ["SpeakNpcId"] = 100001,
            },
        [51003104] = {
            ["Content"] = "看来似乎有个小孩把酒掺在牛奶里，灌醉了巴克先生。再去找找其他线索吧。",
            ["ContentKR"] = "아무래도 어떤 꼬마가 우유에 술을 섞어서 바크 씨를 취하게 만든 것 같아. 다른 단서도 찾아보자.",
            ["DialogueId"] = 51003104,
            ["Duration"] = 4,
            ["GUID"] = "7FAE50C0",
            ["SpeakNpcId"] = 100001,
            },
        [51003105] = {
            ["Content"] = "你好，请问平时会有小孩子来找巴克先生玩吗？",
            ["ContentKR"] = "안녕하세요, 혹시 평소에 바크 씨 댁에 아이들이 놀러 오기도 하나요?",
            ["DialogueId"] = 51003105,
            ["GUID"] = "7FAE50EA",
            ["NextDialogue"] = 51003106,
            ["SpeakNpcId"] = 100001,
            },
        [51003106] = {
            ["Content"] = "小孩找巴克玩？不可能不可能，哪有小孩会对那种只在<H>家里、酒馆和剧院</>三点一线，还满嘴怪话的家伙感兴趣啊。",
            ["ContentKR"] = "놀러 오는 아이가 있냐고? 설마. 오가는 곳이라곤 <H>집구석, 주점, 극장</>이 전부에, 입만 열었다 하면 이상한 소리나 해 대는 인간한테 어떤 꼬마가 관심을 갖겠니?",
            ["DialogueId"] = 51003106,
            ["GUID"] = "7FAE5114",
            ["NextDialogue"] = 51003107,
            ["SpeakNpcId"] = 700213,
            },
        [51003107] = {
            ["Content"] = "别说小孩了，连我们平时都很少跟他打交道，烦得要死还一句话都听不懂。他是不是犯什么事了？我跟你讲啊，我早就感觉他不是好东西了。",
            ["ContentKR"] = "애들은커녕 우리도 그 사람하곤 평소에 거의 말도 안 한단다. 사람 피곤하게 만드는 데다가, 뭐라는 건지 전혀 모르겠거든. 혹시 그 사람이 문제라도 일으킨 거니? 솔직히, 난 진작부터 별로 좋은 사람은 아닐 거라고 봤단다.",
            ["DialogueId"] = 51003107,
            ["GUID"] = "7FAE513E",
            ["NextDialogue"] = 51003108,
            ["SpeakNpcId"] = 700213,
            },
        [51003108] = {
            ["Content"] = "（老妇人滔滔不绝地数落着巴克，诸如这么大了没有正经工作，一天到晚不出门，没老婆没朋友。一直到她讲得口干舌燥，你才找到机会离开。）",
            ["ContentKR"] = "(노부인은 저 나이가 될 때까지 변변한 직업도 없고, 하루 종일 집구석에 박혀 있고, 아내도 친구도 없다는 등등의 험담을 폭포수처럼 쏟아 냈다. 나는 귀에 딱지가 앉을 때가 되어서야 간신히 자리를 피할 수 있었다.)",
            ["DialogueId"] = 51003108,
            ["GUID"] = "7FAE5168",
            ["NextDialogue"] = 51003109,
            },
        [51003109] = {
            ["Content"] = "（巴克先生深居简出没有社交，大部分人都不了解他。所以会想到用酒来灌醉巴克先生的小孩子，一定是从什么地方知道了这个秘密……）",
            ["ContentKR"] = "(평소에 거의 집에만 있는 바크 씨에 대해 아는 사람은 거의 없어. 그러니까 바크 씨한테 술을 먹일 생각을 한 아이는, 분명히 어디선가 그 비밀을 알아낸 거야...)",
            ["DialogueId"] = 51003109,
            ["GUID"] = "7FAE5192",
            ["NextDialogue"] = 51003110,
            ["SpeakNpcId"] = 100001,
            },
        [51003110] = {
            ["Content"] = "（水仙平原不招揽小孩子，家附近也没有小孩找巴克先生……那么就只剩下剧院了，过去看看吧。）",
            ["ContentKR"] = "(애들이 아스포델에 갈 리는 없고, 집 근처에도 바크 씨를 찾아온 아이는 없었어... 그렇다면 남는 건 극장 하나니까, 가서 확인해 보자.)",
            ["DialogueId"] = 51003110,
            ["GUID"] = "7FAE51BC",
            ["SpeakNpcId"] = 100001,
            },
        [51003111] = {
            ["Content"] = "（售票厅旁的卡戎小孩哈着冷气，打着冷颤。不停向来往行人推销着门票、海报、啤酒和爆米花。）",
            ["ContentKR"] = "(매표소 옆의 카론 꼬마가 추위에 입김을 내뿜으며 오들오들 떨면서도, 오가는 행인들에게 표, 포스터, 맥주, 팝콘을 팔려고 쉴 새 없이 애쓰고 있다.)",
            ["DialogueId"] = 51003111,
            ["GUID"] = "7FAE51E6",
            ["NextDialogue"] = 51003112,
            },
        [51003112] = {
            ["Content"] = "（不停向路人推销商品的小孩，会是他灌醉的巴克先生吗？）",
            ["ContentKR"] = "(오가는 사람들한테 계속 물건을 팔려는 저 꼬마가... 바크 씨를 취하게 만든 건 아닐까?)",
            ["DialogueId"] = 51003112,
            ["GUID"] = "7FAE5210",
            ["SpeakNpcId"] = 100001,
            },
        [51003113] = {
            ["Content"] = "巴克先生经常出入剧院，一定多次碰到并拒绝过那个小孩推销啤酒……",
            ["ContentKR"] = "바크 씨는 극장에 자주 드나드니까 저 아이를 자주 봤을 거고, 그때마다 맥주 사라는 걸 거절했겠지...",
            ["DialogueId"] = 51003113,
            ["Duration"] = 3,
            ["GUID"] = "7FAE523A",
            ["NextDialogue"] = 51003114,
            ["SpeakNpcId"] = 100001,
            },
        [51003114] = {
            ["Content"] = "他袖口粘着的那几枚爆米花，跟我窗户下捡到的一模一样。怎么看他的嫌疑都很大，过去聊聊看吧。",
            ["ContentKR"] = "저 아이 소매에 내가 바크 씨네 창문 아래서 발견한 팝콘이랑 똑같은 부스러기가 붙어 있어. 아무리 봐도 쟤가 제일 의심스러워. 가서 말을 걸어 보자.",
            ["DialogueId"] = 51003114,
            ["Duration"] = 4,
            ["GUID"] = "7FAE5264",
            ["SpeakNpcId"] = 100001,
            },
        [51003115] = {
            ["Content"] = "喝啊，我还能喝……不就是二十几瓶啤酒嘛，这才哪到哪啊！来，继续上酒继续喝！",
            ["ContentKR"] = "적셔! 나 아직 끄떡없어... 맥주 스물 몇 병이 뭐 대수야! 한참 더 마실 수 있다고! 어서! 술 더 가져와!",
            ["DialogueId"] = 51003115,
            ["GUID"] = "7FAE528E",
            ["NextDialogue"] = 51003116,
            ["SpeakNpcId"] = 700214,
            },
        [51003116] = {
            ["Content"] = "（浑身酒气的大叔。会是他灌醉的巴克先生吗？）",
            ["ContentKR"] = "(온몸에서 술 냄새가 진동하는 아저씨네. 저 사람이 바크 씨한테 술을 먹인 걸지도?)",
            ["DialogueId"] = 51003116,
            ["GUID"] = "7FAE52B8",
            ["SpeakNpcId"] = 100001,
            },
        [51003117] = {
            ["Content"] = "那个爆米花……是什么味道的呀，爸爸，我想尝尝看！",
            ["ContentKR"] = "저 팝콘... 무슨 맛일까? 아빠! 나 저거 먹어 볼래!",
            ["DialogueId"] = 51003117,
            ["GUID"] = "7FAE52E2",
            ["LookAt"] = {
                [1] = "700215:n(700219)",
                [2] = "700219:n(700215)",
                },
            ["NextDialogue"] = 51003118,
            ["SpeakNpcId"] = 700215,
            },
        [51003118] = {
            ["Content"] = "孩子，你是个淑女，不应该吃那种垃圾食品，等看完歌剧了，爸爸带你去银色和平餐厅吃大餐。",
            ["ContentKR"] = "얘야, 숙녀는 저런 불량 식품을 먹으면 안 된단다. 오페라 공연이 끝나면, 아빠가 실버 피스 레스토랑에 가서 맛있는 걸 잔뜩 사주마.",
            ["DialogueId"] = 51003118,
            ["GUID"] = "7FAE530C",
            ["NextDialogue"] = 51003119,
            ["SpeakNpcId"] = 700219,
            ["TalkActionId"] = {
                [1] = "700219:Talk03_Start",
                },
            },
        [51003119] = {
            ["Content"] = "好吧……",
            ["ContentKR"] = "그러지 뭐...",
            ["DialogueId"] = 51003119,
            ["GUID"] = "7FAE5336",
            ["NextDialogue"] = 51003120,
            ["SpeakNpcId"] = 700215,
            ["TalkActionId"] = {
                [1] = "700219:Talk03_End",
                },
            },
        [51003120] = {
            ["Content"] = "（出现在剧院附近的小孩，很想尝一口爆米花的样子。会是她灌醉的巴克先生吗？）",
            ["ContentKR"] = "(극장 근처에 팝콘을 엄청 먹고 싶어 하는 아이가 나타났어. 저 소녀가 바크 씨한테 술을 먹였을까?)",
            ["DialogueId"] = 51003120,
            ["GUID"] = "7FAE5360",
            ["SpeakNpcId"] = 100001,
            },
        [51003301] = {
            ["Content"] = "阿嚏！怎么好像更冷了……",
            ["ContentKR"] = "에취! 더 추워진 것 같아...",
            ["DialogueId"] = 51003301,
            ["GUID"] = "7FAE7112",
            ["NextDialogue"] = 51003302,
            ["SpeakNpcId"] = 700080,
            ["TalkActionId"] = {
                [1] = "700080:Sigh_Start",
                },
            },
        [51003302] = {
            ["Content"] = "就算是卡戎，不怕冷也是有极限的……到了晚上起码会降温二十多度，说不定又有孩子要冻死了，唉……",
            ["ContentKR"] = "아무리 카론이라도 심한 추위는 힘들다고... 밤이 되면 20도 이상 떨어질 텐데 이러다 또 얼어 죽는 아이가 생기겠어, 휴...",
            ["DialogueId"] = 51003302,
            ["GUID"] = "7FAE713C",
            ["NextDialogue"] = 51003303,
            ["SpeakNpcId"] = 700080,
            ["TalkActionId"] = {
                [1] = "700080:Sigh_End",
                },
            },
        [51003303] = {
            ["Content"] = "你好。",
            ["ContentKR"] = "안녕.",
            ["DialogueId"] = 51003303,
            ["GUID"] = "7FAE7166",
            ["NextDialogue"] = 51003304,
            ["SpeakNpcId"] = 100001,
            },
        [51003304] = {
            ["Content"] = "您好，尊敬的阁下！看戏辛苦了！坐了三个小时，您一定饿了吧！想来点零食和饮品吗？",
            ["ContentKR"] = "어서 오세요! 3시간 동안 공연 보느라 수고하셨어요! 배고프시죠? 간식이나 음료를 좀 드릴까요?",
            ["DialogueId"] = 51003304,
            ["GUID"] = "7FAE7190",
            ["NextDialogue"] = 51003305,
            ["SpeakNpcId"] = 700080,
            ["TalkActionId"] = {
                [1] = "700080:Explain02_Start",
                },
            },
        [51003305] = {
            ["Content"] = "或者您感动于精彩的表演，想看一看有演员签名的海报呢？",
            ["ContentKR"] = "아니면 멋진 공연에 감동해서, 배우의 사인이 있는 포스터를 찾고 계신가요?",
            ["DialogueId"] = 51003305,
            ["GUID"] = "7FAE71BA",
            ["NextOptions"] = {
                [1] = 510033051,
                [2] = 510033052,
                },
            ["SpeakNpcId"] = 700080,
            ["TalkActionId"] = {
                [1] = "700080:Explain02_End",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51003306] = {
            ["Content"] = "让我瞧瞧你都卖些什么。",
            ["ContentKR"] = "뭘 팔고 있는데?",
            ["DialogueId"] = 51003306,
            ["GUID"] = "7FAE71E4",
            ["NextDialogue"] = 51003307,
            ["SpeakNpcId"] = 100001,
            },
        [51003307] = {
            ["Content"] = "维蒂的珍藏版签名海报，《冰湖往事》的纪念手册，冰山融水，剧院联名版爆米花，以及清甜的啤酒！",
            ["ContentKR"] = "비티의 사인이 들어간 소장용 포스터, 〈아이스레이크의 이야기〉 기념 책자, 빙산수, 극장이랑 콜라보해서 만든 팝콘, 그리고 시원하고 맛있는 맥주요!",
            ["DialogueId"] = 51003307,
            ["GUID"] = "7FAE720E",
            ["NextDialogue"] = 51003308,
            ["SpeakNpcId"] = 700080,
            ["TalkActionId"] = {
                [1] = "700080:Explain01_Start",
                },
            },
        [51003308] = {
            ["Content"] = "您放心，这度数聊胜于无，喝不醉人的！",
            ["ContentKR"] = "걱정하지 마세요. 도수가 높지 않아서 마셔도 취하지 않아요!",
            ["DialogueId"] = 51003308,
            ["GUID"] = "7FAE7238",
            ["NextDialogue"] = 51003309,
            ["SpeakNpcId"] = 700080,
            ["TalkActionId"] = {
                [1] = "700080:Explain01_End",
                },
            },
        [51003309] = {
            ["Content"] = "那可不一定……你认识剧作家巴克先生吗？",
            ["ContentKR"] = "글쎄... 혹시 극작가인 바크 씨를 아니?",
            ["DialogueId"] = 51003309,
            ["GUID"] = "7FAE7262",
            ["NextDialogue"] = 51003310,
            ["SpeakNpcId"] = 100001,
            },
        [51003310] = {
            ["Content"] = "当然认识！他是剧院的常客，也经常光顾我的生意，身为贵族但尊重我这样的卡戎小孩，是难得一见的大好人！",
            ["ContentKR"] = "당연하죠! 극장 단골이신 데다가 이곳에도 자주 오시는걸요. 귀족 출신이지만 저 같은 카론도 존중해주는 보기 드문 분이세요.",
            ["DialogueId"] = 51003310,
            ["GUID"] = "7FAE728C",
            ["NextDialogue"] = 51003311,
            ["SpeakNpcId"] = 700080,
            ["TalkActionId"] = {
                [1] = "700080:Agree",
                },
            },
        [51003311] = {
            ["Content"] = "我知道有人嘲笑他，但比起那些人，巴克先生更值得尊敬。",
            ["ContentKR"] = "바크 씨를 비웃는 사람도 있지만, 전 그들보다 바크 씨가 더 존경스러워요.",
            ["DialogueId"] = 51003311,
            ["GUID"] = "7FAE72B6",
            ["NextDialogue"] = 51003312,
            ["SpeakNpcId"] = 700080,
            },
        [51003312] = {
            ["Content"] = "这不是你从窗台摸进他家，偷偷在他牛奶里倒酒的理由。",
            ["ContentKR"] = "그렇다고 네가 바크 씨네 집 창문을 넘어가서, 우유에 몰래 술을 탄 게 정당화되진 않아.",
            ["DialogueId"] = 51003312,
            ["GUID"] = "7FAE72E0",
            ["NextDialogue"] = 51003313,
            ["SpeakNpcId"] = 100001,
            },
        [51003313] = {
            ["Content"] = "你、你是怎么知道的……",
            ["ContentKR"] = "어, 어떻게 아셨죠...",
            ["DialogueId"] = 51003313,
            ["GUID"] = "7FAE730A",
            ["NextDialogue"] = 51003321,
            ["SpeakNpcId"] = 700080,
            ["TalkActionId"] = {
                [1] = "700080:Shock_Start",
                },
            },
        [51003314] = {
            ["Content"] = "巴克先生总在夜间进行创作，你的行为让他的剧本一个月都没有进展，于是他雇佣我去寻找神秘的“灵感飞贼”。",
            ["ContentKR"] = "바크 씨는 밤에 창작 활동을 해. 근데 너 때문에 극본을 한 달 동안 쓰지 못 했고, 나에게 누군지 모를 '영감 도둑'을 찾아달라고 의뢰했지.",
            ["DialogueId"] = 51003314,
            ["GUID"] = "7FAE7334",
            ["NextOptions"] = {
                [1] = 510033141,
                },
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700080:Shock_End",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51003315] = {
            ["Content"] = "（想说的话突然卡在嘴边，在脑海里重新整理一下措辞吧。）",
            ["ContentKR"] = "(갑자기 말문이 막혔다. 하고 싶은 말을 다시 정리하자.)",
            ["DialogueId"] = 51003315,
            ["GUID"] = "7FAE735E",
            },
        [51003316] = {
            ["Content"] = "你的生意并不支持你买到足够的过冬物资，巴克先生虽然没什么钱，但好歹是个贵族，他的房子足够暖和，所以你才想潜入巴克先生家取暖。",
            ["ContentKR"] = "장사만으로는 겨울나기에 필요한 것들을 다 살 수 없었던 거야. 귀족인 바크 씨는 돈은 없어도 집이 따뜻하니까, 그 집에서 몸을 녹이려고 한 거겠지.",
            ["DialogueId"] = 51003316,
            ["GUID"] = "7FAE7388",
            ["NextDialogue"] = 51003317,
            ["SpeakNpcId"] = 100001,
            },
        [51003317] = {
            ["Content"] = "至于为什么是巴克先生，那是因为不管度数有多低，只要沾一点点酒他都会睡过去，在这之后你就能安心地睡上一整晚而不必担心被冻死，对吗？",
            ["ContentKR"] = "그럼, 왜 하필 바크 씨였을까? 그건 바로 도수가 아무리 낮아도 술 한 방울이면 바크 씨는 잠이 들기 때문이지. 그럼 넌 마음 편히 자면서 얼어 죽을 걱정은 하지 않아도 됐을 거야. 그렇지?",
            ["DialogueId"] = 51003317,
            ["GUID"] = "7FAE73B2",
            ["NextDialogue"] = 51003318,
            ["SpeakNpcId"] = 100001,
            },
        [51003318] = {
            ["Content"] = "唉……您可真是名侦探再世，事情就像您说的一样。",
            ["ContentKR"] = "휴... 정말 대단하시네요. 말씀하신 게 맞아요.",
            ["DialogueId"] = 51003318,
            ["GUID"] = "7FAE73DC",
            ["NextDialogue"] = 51003319,
            ["SpeakNpcId"] = 700080,
            ["TalkActionId"] = {
                [1] = "700080:Explain02_Start",
                },
            },
        [51003319] = {
            ["Content"] = "您把我抓起来吧，我感到十分抱歉，但如果不这么做，我连被您抓起来的机会都没有……",
            ["ContentKR"] = "저를 잡아가세요. 정말 죄송해요. 근데 당시 그렇게라도 하지 않았다면 전 진작에 여기 있지도 못했을 거예요...",
            ["DialogueId"] = 51003319,
            ["GUID"] = "7FAE7406",
            ["NextDialogue"] = 51003320,
            ["SpeakNpcId"] = 700080,
            ["TalkActionId"] = {
                [1] = "700080:Explain02_End",
                },
            },
        [51003320] = {
            ["Content"] = "我没有权利决定怎么处理你，我会带你去见我的雇主。",
            ["ContentKR"] = "나라고 널 어떻게 할 수 있는 건 아냐. 대신 의뢰인한테 갈 때 함께 가줄게.",
            ["DialogueId"] = 51003320,
            ["GUID"] = "7FAE7430",
            ["SpeakNpcId"] = 100001,
            },
        [51003321] = {
            ["Content"] = "（果然如此。）",
            ["ContentKR"] = "(내 예상이 맞았네.)",
            ["DialogueId"] = 51003321,
            ["GUID"] = "7FAE730B",
            ["NextDialogue"] = 51003314,
            ["SpeakNpcId"] = 100001,
            },
        [51003401] = {
            ["Camera"] = "98.558472,-67.410156,133.285156,0.0,-1.600033,173.800858,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我找到人了。",
            ["ContentKR"] = "찾았어요.",
            ["DialogueId"] = 51003401,
            ["GUID"] = "7FAE817A",
            ["LookAt"] = {
                [1] = "700102:n(100001)",
                [2] = "100001:n(700102)",
                },
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Give",
                },
            },
        [51003402] = {
            ["Content"] = "你将事情的来龙去脉告知给了巴克先生。",
            ["ContentKR"] = "(바크 씨에게 사건의 전말을 알려준다.)",
            ["DialogueId"] = 51003402,
            ["Duration"] = 3,
            ["GUID"] = "7FAE81A4",
            },
        [51003403] = {
            ["Camera"] = "-262.830322,120.149414,121.775391,0.000007,-0.200008,-45.795547,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哦！我的勇士，对您道一万次的感谢！想必从今夜起，灵感女神的宠爱将重回我身！",
            ["ContentKR"] = "오! 용사님, 감사합니다! 오늘부터는 다시 영감 여신의 사랑을 받을 수 있겠어요!",
            ["DialogueId"] = 51003403,
            ["GUID"] = "7FAE81CE",
            ["LookAt"] = {
                [1] = "700102:n(100001)",
                },
            ["NextDialogue"] = 51003404,
            ["SpeakNpcId"] = 700015,
            ["TalkActionId"] = {
                [1] = "700102:Agree",
                },
            ["TurnTo"] = {
                [1] = "700103:n(700102)",
                },
            },
        [51003404] = {
            ["Camera"] = "-73.412354,63.213867,126.775391,0.000008,0.200002,-62.796665,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "至于你……我梦中的小飞贼，你可真是给了我一个莫大的意外！",
            ["ContentKR"] = "네가... 꿈속의 도둑이었구나. 정말 생각도 못 했어!",
            ["DialogueId"] = 51003404,
            ["GUID"] = "7FAE81F8",
            ["LookAt"] = {
                [1] = "700102:n(700103)",
                },
            ["NextDialogue"] = 51003405,
            ["SpeakNpcId"] = 700015,
            ["TurnTo"] = {
                [1] = "700102:n(700103)",
                },
            },
        [51003405] = {
            ["Camera"] = "-49.103394,-198.604492,136.482422,0.000076,-6.999994,74.199654,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "非常抱歉，巴克先生……但请您相信我，我从没有要伤害你的意思……",
            ["ContentKR"] = "죄송해요, 바크 씨... 하지만 바크 씨께 피해를 줄 생각은 없었어요, 믿어주세요...",
            ["DialogueId"] = 51003405,
            ["GUID"] = "7FAE8222",
            ["LookAt"] = {
                [1] = "700103:n(700102)",
                },
            ["NextDialogue"] = 51003406,
            ["SpeakNpcId"] = 700080,
            ["TalkActionId"] = {
                [1] = "700103:Explain02_Start",
                },
            },
        [51003406] = {
            ["Camera"] = "-92.579468,176.0,104.482422,0.000083,1.000179,-63.000008,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哦，小飞贼，我知道人们在背后是怎么笑话我的，我是个卖不出作品的废物剧作家。",
            ["ContentKR"] = "오, 난 남들이 뒤에서 날 어떻게 비웃는지 다 알고 있단다. 그들에게 난 작품도 못 파는 별 볼 일 없는 극작가 나부랭일 뿐이라는 걸.",
