                },
            },
        [51004003] = {
            ["Camera"] = "-415.09082,-71.93457,95.116699,0.000026,0.0,13.207663,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "快看，那家伙回来了！",
            ["ContentKR"] = "얘들아, 또 왔다!",
            ["DialogueId"] = 51004003,
            ["GUID"] = "7FAEE43E",
            ["LookAt"] = {
                [1] = "100001:n(100001)",
                [2] = "700104:n(700104)",
                },
            ["NextDialogue"] = 51004004,
            ["SpeakNpcId"] = 700089,
            ["TurnTo"] = {
                [1] = "700088:n(100001)",
                [2] = "700089:n(100001)",
                [3] = "700090:n(100001)",
                },
            },
        [51004004] = {
            ["Camera"] = "-415.09082,-71.93457,95.116699,0.000026,0.0,13.207663,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这就和卡戎勾搭上了？不是一家人不进一家门！",
            ["ContentKR"] = "그냥 카론이랑 놀기로 한 거야? 역시 끼리끼리라니까!",
            ["DialogueId"] = 51004004,
            ["GUID"] = "7FAEE468",
            ["NextDialogue"] = 51004005,
            ["SpeakNpcId"] = 700088,
            ["TalkActionId"] = {
                [1] = "700088:Confident_Start",
                },
            },
        [51004005] = {
            ["Camera"] = "-415.09082,-71.93457,95.116699,0.000026,0.0,13.207663,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我……",
            ["ContentKR"] = "난...",
            ["DialogueId"] = 51004005,
            ["GUID"] = "7FAEE492",
            ["NextDialogue"] = 51004006,
            ["SpeakNpcId"] = 700104,
            },
        [51004006] = {
            ["Camera"] = "-415.09082,-71.93457,95.116699,0.000026,0.0,13.207663,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（女孩努力地张嘴想要说什么，但似乎还没组织好语言，也许是需要一些小小的帮助。要对她的同学们说什么？）",
            ["ContentKR"] = "(소녀는 가까스로 입을 열었지만, 어떤 말을 해야 할지 몰라 도움이 필요한 것 같다. 친구들에게 뭐라고 할까?)",
            ["DialogueId"] = 51004006,
            ["GUID"] = "7FAEE4BC",
            ["NextOptions"] = {
                [1] = 510040061,
                [2] = 510040062,
                },
            },
        [51004007] = {
            ["Camera"] = "-415.09082,-71.93457,95.116699,0.000026,0.0,13.207663,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "是的……给我……给我……滚开！",
            ["ContentKR"] = "맞아... 그러니까... 그럼... 꺼져!",
            ["DialogueId"] = 51004007,
            ["GUID"] = "7FAEE4E6",
            ["NextDialogue"] = 51004008,
            ["SpeakNpcId"] = 700104,
            ["TalkActionId"] = {
                [1] = "700104:Agree",
                },
            },
        [51004008] = {
            ["Camera"] = "-415.09082,-71.93457,95.116699,0.000026,0.0,13.207663,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……不然我……我会和我的朋友一起把你们都送进地狱……！",
            ["ContentKR"] = "...안 그러면... 우리가 지옥으로 보내줄 테니까...!",
            ["DialogueId"] = 51004008,
            ["GUID"] = "7FAEE510",
            ["NextDialogue"] = 51004009,
            ["SpeakNpcId"] = 700104,
            },
        [51004009] = {
            ["Camera"] = "-415.09082,-71.93457,95.116699,0.000026,0.0,13.207663,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "或者，你们不是喜欢虫子、喜欢老鼠吗？就把你们丢进下水道好了……！",
            ["ContentKR"] = "아니면, 너희 벌레랑 쥐가 좋다며? 하수도로 빠뜨려 줄게...!",
            ["DialogueId"] = 51004009,
            ["GUID"] = "7FAEE53A",
            ["NextDialogue"] = 51004010,
            ["SpeakNpcId"] = 700104,
            ["TalkActionId"] = {
                [1] = "700104:Think_Start",
                },
            },
        [51004010] = {
            ["Camera"] = "-415.09082,-71.93457,95.116699,0.000026,0.0,13.207663,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "不，不行，老鼠肯定也会嫌弃你们的！",
            ["ContentKR"] = "아니, 안 되겠다. 쥐들도 너희는 싫을 테니까!",
            ["DialogueId"] = 51004010,
            ["GUID"] = "7FAEE564",
            ["NextDialogue"] = 51004011,
            ["SpeakNpcId"] = 700104,
            ["TalkActionId"] = {
                [1] = "700104:Think_End",
                },
            },
        [51004011] = {
            ["Camera"] = "-415.09082,-71.93457,95.116699,0.000026,0.0,13.207663,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（仿佛是打破了某种无形的束缚，女孩一反之前寡言少语的样子，滔滔不绝地骂了起来。）",
            ["ContentKR"] = "(말수가 적었던 소녀는 보이지 않는 속박에서 벗어나기라도 한 듯 거침없이 독설을 날렸다.)",
            ["DialogueId"] = 51004011,
            ["GUID"] = "7FAEE58E",
            ["NextDialogue"] = 51004012,
            },
        [51004012] = {
            ["Camera"] = "-415.09082,-71.93457,95.116699,0.000026,0.0,13.207663,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "她居然骂人？！她疯了吧？",
            ["ContentKR"] = "뭐라고?! 미쳤어?",
            ["DialogueId"] = 51004012,
            ["GUID"] = "7FAEE5B8",
            ["NextDialogue"] = 51004013,
            ["SpeakNpcId"] = 700088,
            ["TalkActionId"] = {
                [1] = "700088:Confident_Start",
                },
            ["TurnTo"] = {
                [1] = "700089:n(700104)",
                },
            },
        [51004013] = {
            ["Camera"] = "-415.09082,-71.93457,95.116699,0.000026,0.0,13.207663,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "气死我了！来人啊，给我教训教训她，让我满意了这些钱就都是你们的！",
            ["ContentKR"] = "어이가 없네! 누가 저 녀석 좀 혼쭐을 내줘. 제대로 혼쭐내면 이 돈을 다 줄게.",
            ["DialogueId"] = 51004013,
            ["GUID"] = "7FAEE5E2",
            ["SpeakNpcId"] = 700089,
            ["TalkActionId"] = {
                [1] = "700089:Angry01_Start",
                },
            },
        [51004101] = {
            ["Camera"] = "-342.361328,156.479492,90.07373,0.0,0.0,-33.384811,20.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这个白头发的，不好惹啊！",
            ["ContentKR"] = "저 백발 녀석, 쉽지 않은 상대야!",
            ["DialogueId"] = 51004101,
            ["GUID"] = "7FAEF452",
            ["NextDialogue"] = 51004102,
            ["SpeakNpcId"] = 700088,
            ["TalkActionId"] = {
                [1] = "700088:Sigh_Start",
                [2] = "700089:Shock_Start",
                },
            },
        [51004102] = {
            ["Camera"] = "-342.361328,156.479492,90.07373,0.0,0.0,-33.384811,20.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "喂……情况好像不太妙啊！我们还是先回去吧！",
            ["ContentKR"] = "휴... 우리가 불리한 것 같아! 일단 돌아가자!",
            ["DialogueId"] = 51004102,
            ["GUID"] = "7FAEF47C",
            ["LookAt"] = {
                [1] = "700089:n(700088)",
                },
            ["NextDialogue"] = 51004103,
            ["SpeakNpcId"] = 700089,
            },
        [51004103] = {
            ["Camera"] = "-97.533691,-5.197266,119.393066,0.000077,-0.399996,173.011871,20.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "等等。",
            ["ContentKR"] = "잠깐.",
            ["DialogueId"] = 51004103,
            ["GUID"] = "7FAEF4A6",
            ["NextDialogue"] = 51004104,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk03_Start",
                },
            },
        [51004104] = {
            ["Camera"] = "-97.533691,-5.197266,119.393066,0.000077,-0.399996,173.011871,20.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "费伊已经和我这个恶魔签了一份协议，如果你们再找她的麻烦，我会在一分钟之内出现在你们面前。",
            ["ContentKR"] = "페이는 악마인 나와 계약을 맺었어. 또 페이를 괴롭히면 내가 너희들 앞에 나타날 테니, 그렇게 알아.",
            ["DialogueId"] = 51004104,
            ["GUID"] = "7FAEF4D0",
            ["NextDialogue"] = 51004105,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700088:Sigh_End",
                },
            },
        [51004105] = {
            ["Camera"] = "-199.681152,34.707031,99.213867,0.000074,-2.198085,-15.786639,20.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你……你……哼！",
            ["ContentKR"] = "너... 너... 흥!",
            ["DialogueId"] = 51004105,
            ["GUID"] = "7FAEF4FA",
            ["SpeakNpcId"] = 700088,
            ["TalkActionId"] = {
                [1] = "700088:Angry01_Start",
                },
            },
        [51004106] = {
            ["Content"] = "学生们一溜烟逃走了。",
            ["ContentKR"] = "(학생들이 줄행랑친다.)",
            ["DialogueId"] = 51004106,
            ["GUID"] = "7FAEF524",
            },
        [51004107] = {
            ["Content"] = "你看，他们的胆量不过如此。",
            ["ContentKR"] = "봤지? 저 정도밖에 안 되는 애들이야.",
            ["DialogueId"] = 51004107,
            ["GUID"] = "7FAEF54E",
            ["NextDialogue"] = 51004108,
            ["SpeakNpcId"] = 100001,
            },
        [51004108] = {
            ["Content"] = "……嗯！",
            ["ContentKR"] = "...응!",
            ["DialogueId"] = 51004108,
            ["GUID"] = "7FAEF578",
            ["NextDialogue"] = 51004109,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Agree",
                },
            },
        [51004109] = {
            ["Content"] = "多亏了有你在……你抡起拳头的样子真的很威风呢！",
            ["ContentKR"] = "덕분이야... 주먹 휘두를 때 멋있더라!",
            ["DialogueId"] = 51004109,
            ["GUID"] = "7FAEF5A2",
            ["NextOptions"] = {
                [1] = 510041091,
                [2] = 510041092,
                },
            ["SpeakNpcId"] = 700105,
            ["bForbidSkipOptions"] = true,
            },
        [51004110] = {
            ["Content"] = "诶，是、是吗？我只是……把以前偷偷在心里想的话说出来了。",
            ["ContentKR"] = "아, 그, 그래? 난 그냥... 그동안 속으로만 했던 말을 한 것뿐인데.",
            ["DialogueId"] = 51004110,
            ["GUID"] = "7FAEF5CC",
            ["NextDialogue"] = 51004111,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Shock_Start",
                },
            },
        [51004111] = {
            ["Content"] = "谢谢你，我长这么大，还是头一次心里这么畅快呢！",
            ["ContentKR"] = "고마워. 이렇게 통쾌한 기분은 처음이야!",
            ["DialogueId"] = 51004111,
            ["GUID"] = "7FAEF5F6",
            ["NextDialogue"] = 51004112,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Shock_End",
                },
            },
        [51004112] = {
            ["Content"] = "不用谢，他们短时间应该不会来找你麻烦了，我送你回家吧。这是我的地址——如果他们再惹你，就来找我。",
            ["ContentKR"] = "고맙기는. 다들 당분간은 조용할 거야. 내가 데려다줄게. 그리고 이건 내 주소야. 또 누가 괴롭히면 나한테 찾아와.",
            ["DialogueId"] = 51004112,
            ["GUID"] = "7FAEF620",
            ["NextDialogue"] = 51004113,
            ["SpeakNpcId"] = 100001,
            },
        [51004113] = {
            ["Content"] = "我不想回家……！",
            ["ContentKR"] = "가기 싫어...!",
            ["DialogueId"] = 51004113,
            ["GUID"] = "7FAEF64A",
            ["NextDialogue"] = 51004114,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Disagree",
                },
            },
        [51004114] = {
            ["Content"] = "我是卡戎，我要和卡戎之民待在一起……",
            ["ContentKR"] = "나는 카론이니까 카론과 가까이 있고 싶어...",
            ["DialogueId"] = 51004114,
            ["GUID"] = "7FAEF674",
            ["NextOptions"] = {
                [1] = 510041141,
                },
            ["RestartTag"] = 51004114,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Agree",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51004115] = {
            ["Content"] = "（女孩固执地噘着嘴，并没有被你说服。）",
            ["ContentKR"] = "(소녀는 고집을 부렸고, 설득이 통하지 않았다.)",
            ["DialogueId"] = 51004115,
            ["GUID"] = "7FAEF69E",
            },
        [51004116] = {
            ["Content"] = "还没看清他们吗？他们平日里对着你威风凛凛，但真的有人比他们拳头更硬的时候，他们就会落荒而逃。",
            ["ContentKR"] = "아직도 모르겠어? 그렇게 기세등등한 녀석들이 강한 사람 앞에서는 도망치잖아.",
            ["DialogueId"] = 51004116,
            ["GUID"] = "7FAEF6C8",
            ["NextDialogue"] = 51004117,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700105:Think_Start",
                },
            },
        [51004117] = {
            ["Content"] = "他们不像自己表现得那么强大。所以，他们嘴里说的自然也不是事实。费伊，你是如假包换的索拉之民，不要被他们蹩脚的谎言骗了。",
            ["ContentKR"] = "그렇게 대단한 아이들이 아니야. 그러니까 쟤들이 하는 말도 사실이 아닌 거지. 페이, 넌 진짜 솔라니까 그런 거짓말에 휘둘리지 마.",
            ["DialogueId"] = 51004117,
            ["GUID"] = "7FAEF6F2",
            ["NextDialogue"] = 51004118,
            ["SpeakNpcId"] = 100001,
            },
        [51004118] = {
            ["Content"] = "记住，永远不要因为别人的恶意质疑自己，责备自己……这是我的家人教会我的，我也把它教给你。",
            ["ContentKR"] = "못된 사람들 때문에 스스로를 의심하거나 자책하지 마... 이건 우리 가족이 내게 했던 말인데, 이젠 네게 해줄게.",
            ["DialogueId"] = 51004118,
            ["GUID"] = "7FAEF71C",
            ["NextDialogue"] = 51004119,
            ["SpeakNpcId"] = 100001,
            },
        [51004119] = {
            ["Content"] = "（女孩略带困惑地眨了眨眼，似乎还不能完全理解你话语的含义，但是表情却有所缓和。）",
            ["ContentKR"] = "(소녀는 이해하지 못한 듯 아리송한 표정으로 눈을 깜빡였다. 그래도 표정은 한층 좋아졌다.)",
            ["DialogueId"] = 51004119,
            ["GUID"] = "7FAEF746",
            ["NextDialogue"] = 51004120,
            },
        [51004120] = {
            ["Content"] = "好吧……既然你这么说的话，我会努力试试看的！但在那之前，我还有最后一个小小的请求……",
            ["ContentKR"] = "알겠어... 그렇게 말해주니 나도 노력해 볼게! 그 전에 마지막으로 부탁이 하나 있어...",
            ["DialogueId"] = 51004120,
            ["GUID"] = "7FAEF770",
            ["NextDialogue"] = 51004121,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Think_End",
                },
            },
        [51004121] = {
            ["Content"] = "可以让我摸一下你的角吗？",
            ["ContentKR"] = "네 뿔, 한 번만 만져봐도 될까?",
            ["DialogueId"] = 51004121,
            ["GUID"] = "7FAEF79A",
            ["NextOptions"] = {
                [1] = 510041211,
                [2] = 510041212,
                },
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Explain02_Start",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51004122] = {
            ["Content"] = "谢谢！",
            ["ContentKR"] = "고마워!",
            ["DialogueId"] = 51004122,
            ["GUID"] = "7FAEF7C4",
            ["NextDialogue"] = 51004123,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Explain02_End",
                },
            },
        [51004123] = {
            ["Content"] = "（女孩小心翼翼地伸出纤瘦的手，摸了摸你头上的角。）",
            ["ContentKR"] = "(소녀가 가녀린 손을 뻗어 머리에 난 뿔을 쓰다듬었다.)",
            ["DialogueId"] = 51004123,
            ["GUID"] = "7FAEF7EE",
            ["NextDialogue"] = 51004126,
            },
        [51004124] = {
            ["Content"] = "好吧，那我不摸，就看一看……",
            ["ContentKR"] = "알겠어. 그럼 대신 보기만 할게...",
            ["DialogueId"] = 51004124,
            ["GUID"] = "7FAEF818",
            ["NextDialogue"] = 51004125,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Explain02_End",
                },
            },
        [51004125] = {
            ["Content"] = "（女孩小心翼翼地凑上来，仔细地打量着你头上的角。）",
            ["ContentKR"] = "(소녀가 살며시 다가와 머리에 난 뿔을 들여다본다.)",
            ["DialogueId"] = 51004125,
            ["GUID"] = "7FAEF842",
            ["NextDialogue"] = 51004126,
            },
        [51004126] = {
            ["Content"] = "原来真正的角，是这样的啊……",
            ["ContentKR"] = "진짜 뿔은 이렇게 생겼구나...",
            ["DialogueId"] = 51004126,
            ["GUID"] = "7FAEF86C",
            ["NextDialogue"] = 51004127,
            ["SpeakNpcId"] = 700105,
            },
        [51004127] = {
            ["Content"] = "红色的，很精巧……还会反射阳光呢。确实比我的辫子要可爱多了。",
            ["ContentKR"] = "붉은색이고 정교하구나... 햇빛에 반사되기도 하네. 내 땋은 머리보다 훨씬 더 귀여워.",
            ["DialogueId"] = 51004127,
            ["GUID"] = "7FAEF896",
            ["NextOptions"] = {
                [1] = 510041271,
                },
            ["SpeakNpcId"] = 700105,
            ["bForbidSkipOptions"] = true,
            },
        [51004128] = {
            ["Content"] = "你是第一个这么说的人。但它们现在都被弄乱了……我要重新梳好才行。",
            ["ContentKR"] = "그런 말은 처음 들어봐. 근데 다 흐트러졌네... 다시 묶어야겠어.",
            ["DialogueId"] = 51004128,
            ["GUID"] = "7FAEF8C0",
            ["NextDialogue"] = 51004129,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Explain01_Start",
                },
            },
        [51004129] = {
            ["Content"] = "（女孩从书包里找出一把梳子，认真地将头上的两条辫子重新梳好，然后将它们向上提起来，比划出角的样子。）",
            ["ContentKR"] = "(소녀는 가방에서 빗을 꺼내 머리를 양 갈래로 다시 땋고, 잡아 올려 뿔 모양을 만든다.)",
            ["DialogueId"] = 51004129,
            ["GUID"] = "7FAEF8EA",
            ["NextDialogue"] = 51004130,
            ["TalkActionId"] = {
                [1] = "700105:Explain01_End",
                },
            },
        [51004130] = {
            ["Content"] = "这样像不像恶魔角？",
            ["ContentKR"] = "이렇게 하면 악마 같아?",
            ["DialogueId"] = 51004130,
            ["GUID"] = "7FAEF914",
            ["NextOptions"] = {
                [1] = 510041301,
                [2] = 510041302,
                },
            ["SpeakNpcId"] = 700105,
            ["bForbidSkipOptions"] = true,
            },
        [51004131] = {
            ["Content"] = "嘿嘿。",
            ["ContentKR"] = "히히.",
            ["DialogueId"] = 51004131,
            ["GUID"] = "7FAEF93E",
            ["NextDialogue"] = 51004133,
            ["SpeakNpcId"] = 700105,
            },
        [51004132] = {
            ["Content"] = "哈哈，那也不错。",
            ["ContentKR"] = "하하, 그것도 괜찮네.",
            ["DialogueId"] = 51004132,
            ["GUID"] = "7FAEF968",
            ["NextDialogue"] = 51004133,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Agree",
                },
            },
        [51004133] = {
            ["Content"] = "啊，我口袋里还有多的发圈呢，要不要给你也扎个小辫子？",
            ["ContentKR"] = "아, 머리끈이 많은데, 네 머리도 땋아줄까?",
            ["DialogueId"] = 51004133,
            ["GUID"] = "7FAEF992",
            ["NextOptions"] = {
                [1] = 510041331,
                [2] = 510041332,
                },
            ["SpeakNpcId"] = 700105,
            ["bForbidSkipOptions"] = true,
            },
        [51004134] = {
            ["Content"] = "就扎一下让我看看嘛！",
            ["ContentKR"] = "한 번만 해보자!",
            ["DialogueId"] = 51004134,
            ["GUID"] = "7FAEF9BC",
            ["NextDialogue"] = 51004135,
            ["SpeakNpcId"] = 700105,
            },
        [51004135] = {
            ["Content"] = "（女孩不由分说地踮起脚尖，试图把你按到一个她能够得到的位置。看来，她已经精神多了。）",
            ["ContentKR"] = "(소녀는 까치발을 들고, 본인이 닿을 수 있을 정도로 나의 허리를 숙이게 했다. 이제 기운을 차린 것 같다.)",
            ["DialogueId"] = 51004135,
            ["GUID"] = "7FAEF9E6",
            ["NextDialogue"] = 51004136,
            },
        [51004136] = {
            ["Content"] = "来，稍微蹲下一些……",
            ["ContentKR"] = "음, 살짝만 숙여봐...",
            ["DialogueId"] = 51004136,
            ["GUID"] = "7FAEFA10",
            ["NextDialogue"] = 51004137,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Explain01_Start",
                },
            },
        [51004137] = {
            ["Content"] = "（你感到脑后的发丝被人轻轻地揪住了。女孩梳头的动作非常温柔，看来不用担心发际线受到伤害了。）",
            ["ContentKR"] = "(뒷머리를 땋는 게 느껴졌다. 소녀의 부드러운 동작 덕분에 이마를 다칠 걱정은 안 해도 될 것 같다.)",
            ["DialogueId"] = 51004137,
            ["GUID"] = "7FAEFA3A",
            ["NextDialogue"] = 51004138,
            ["TalkActionId"] = {
                [1] = "700105:Explain01_End",
                },
            },
        [51004138] = {
            ["Content"] = "好了！哇，你扎辫子的样子好可爱！",
            ["ContentKR"] = "다 됐어! 와, 머리를 땋으니까 너무 귀여워!",
            ["DialogueId"] = 51004138,
            ["GUID"] = "7FAEFA64",
            ["NextDialogue"] = 51004139,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Agree",
                },
            },
        [51004139] = {
            ["Content"] = "可惜我没有带镜子……",
            ["ContentKR"] = "거울을 안 가져와서 아쉽네...",
            ["DialogueId"] = 51004139,
            ["GUID"] = "7FAEFA8E",
            ["NextDialogue"] = 51004140,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Think_Start",
                },
            },
        [51004140] = {
            ["Content"] = "啊……我想到了！我可以画出来。",
            ["ContentKR"] = "아... 내가 그려줄게!",
            ["DialogueId"] = 51004140,
            ["GUID"] = "7FAEFAB8",
            ["NextDialogue"] = 51004141,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Think_End",
                },
            },
        [51004141] = {
            ["Content"] = "（女孩打开书包，在笔记本上认真画着你的样子。）",
            ["ContentKR"] = "(소녀는 가방에서 노트를 꺼내 그 위에 당신의 모습을 그린다.)",
            ["DialogueId"] = 51004141,
            ["GUID"] = "7FAEFAE2",
            ["NextDialogue"] = 51004142,
            },
        [51004142] = {
            ["Content"] = "对了，你叫什么名字呀？",
            ["ContentKR"] = "맞다, 이름이 뭐야?",
            ["DialogueId"] = 51004142,
            ["GUID"] = "7FAEFB0C",
            ["NextOptions"] = {
                [1] = 510041421,
                },
            ["SpeakNpcId"] = 700105,
            ["bForbidSkipOptions"] = true,
            },
        [51004143] = {
            ["Content"] = "嗯！{nickname}，我会一直一直记住你的。给，这是我给你画的画像，再见！",
            ["ContentKR"] = "응! {nickname}, 절대 잊지 않을게. 여기 내 그림이야. 그럼 이만 가볼게!",
            ["DialogueId"] = 51004143,
            ["GUID"] = "7FAEFB36",
            ["NextDialogue"] = 51004144,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Agree",
                },
            },
        [51004144] = {
            ["Content"] = "……太神秘了，这就是城里人的艺术吗……",
            ["ContentKR"] = "...신기해. 이게 바로 예술인가...",
            ["DialogueId"] = 51004144,
            ["GUID"] = "7FAEFB60",
            ["NextDialogue"] = 51004145,
            ["SpeakNpcId"] = 100001,
            },
        [51004145] = {
            ["Content"] = "（女孩正准备离开，忽然又回过头，认真地看向你。）",
            ["ContentKR"] = "(떠나려던 소녀가 갑자기 고개를 돌려 당신을 본다.)",
            ["DialogueId"] = 51004145,
            ["GUID"] = "7FAEFB8A",
            ["NextDialogue"] = 51004146,
            },
        [51004146] = {
            ["Content"] = "对了……刚才给你梳头的时候，我突然想到一件事。",
            ["ContentKR"] = "아, 참... 아까 머리 땋아줄 때 생각난 게 있어.",
            ["DialogueId"] = 51004146,
            ["GUID"] = "7FAEFBB4",
            ["NextDialogue"] = 51004147,
            ["SpeakNpcId"] = 700105,
            },
        [51004147] = {
            ["Content"] = "他们一直都告诉我，卡戎是恶魔的孩子，是脑袋笨笨又一肚子坏水的，总是在做坏事的……",
            ["ContentKR"] = "친구들이 카론은 악마의 아이라, 멍청하고 악해서 늘 못된 짓만 한다고 했거든...",
            ["DialogueId"] = 51004147,
            ["GUID"] = "7FAEFBDE",
            ["NextDialogue"] = 51004148,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Explain01_Start",
                },
            },
        [51004148] = {
            ["Content"] = "这些话……其实也不是真的吧？",
            ["ContentKR"] = "근데... 사실이 아닌 거지?",
            ["DialogueId"] = 51004148,
            ["GUID"] = "7FAEFC08",
            ["NextDialogue"] = 51004149,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Explain01_End",
                },
            },
        [51004149] = {
            ["Content"] = "那也是他们用来欺负你们的借口，对不对？",
            ["ContentKR"] = "너희들을 괴롭히려고 했던 핑계였던 거야, 그렇지?",
            ["DialogueId"] = 51004149,
            ["GUID"] = "7FAEFC32",
            ["NextOptions"] = {
                [1] = 510041491,
                [2] = 510041492,
                },
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Confident_Start",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51004150] = {
            ["Content"] = "你们一定……承受了比我多得多的痛苦吧。",
            ["ContentKR"] = "너희는... 나보다 더 힘들었겠구나.",
            ["DialogueId"] = 51004150,
            ["GUID"] = "7FAEFC5C",
            ["NextDialogue"] = 51004151,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Confident_End",
                },
            },
        [51004151] = {
            ["Content"] = "今后，如果有什么我能帮得上忙的事，请尽管说……不是因为我们是同类，而是因为我们是朋友。",
            ["ContentKR"] = "앞으로 내가 도울 일이 있으면 알려줘... 동족인 걸 떠나서 우리는 친구니까.",
            ["DialogueId"] = 51004151,
            ["GUID"] = "7FAEFC86",
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Explain02_Start",
                },
            },
        [51004152] = {
            ["Content"] = "同学们还是不喜欢我，但现在我已经不怕他们了！这都是多亏了你！",
            ["ContentKR"] = "학교 친구들은 여전히 날 싫어하지만, 더 이상 두렵지 않아! 다 네 덕분이야!",
            ["DialogueId"] = 51004152,
            ["GUID"] = "7FAEFCB0",
            ["SpeakNpcId"] = 700105,
            },
        [51004201] = {
            ["Content"] = "啧，生面孔啊。",
            ["ContentKR"] = "쯧, 처음 보는 얼굴이군.",
            ["DialogueId"] = 51004201,
            ["GUID"] = "7FAF04BA",
            ["NextDialogue"] = 51004202,
            ["SpeakNpcId"] = 700096,
            ["TalkActionId"] = {
                [1] = "700096:Talk03_Start",
                },
            },
        [51004202] = {
            ["Content"] = "（眼前的男人眯起眼，抿了抿嘴唇上锐利的裂口，吐出干燥的话语。）",
            ["ContentKR"] = "(눈을 가늘게 뜬 남자가 터진 입술을 문지르며 무미건조하게 말했다.)",
            ["DialogueId"] = 51004202,
            ["GUID"] = "7FAF04E4",
            ["NextDialogue"] = 51004203,
            },
        [51004203] = {
            ["Content"] = "说说吧，谁介绍你来的？",
            ["ContentKR"] = "누구 소개로 왔지?",
            ["DialogueId"] = 51004203,
            ["GUID"] = "7FAF050E",
            ["NextOptions"] = {
                [1] = 510042031,
                [2] = 510042032,
                [3] = 510042033,
                },
            ["SpeakNpcId"] = 700096,
            ["TalkActionId"] = {
                [1] = "700096:Talk03_End",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51004204] = {
            ["Content"] = "（一个新的问题，才是最好的回答。）",
            ["ContentKR"] = "(새로운 질문을 건네는 것이 최고의 대답이다.)",
            ["DialogueId"] = 51004204,
            ["GUID"] = "7FAF0538",
            ["NextDialogue"] = 51004207,
            },
        [51004205] = {
            ["Content"] = "（“介绍”？很明显，他是在等什么人。）",
            ["ContentKR"] = "('소개'라고? 그렇다는 건 분명 누군가를 기다리고 있다.)",
            ["DialogueId"] = 51004205,
            ["GUID"] = "7FAF0562",
            ["NextDialogue"] = 51004207,
            },
        [51004206] = {
            ["Content"] = "（不知道他在问什么，但没人会拒绝这个回答。）",
            ["ContentKR"] = "(뭘 물어보는 건지는 모르겠지만, 이런 대답은 아무도 거절할 수 없다.)",
            ["DialogueId"] = 51004206,
            ["GUID"] = "7FAF058C",
            ["NextDialogue"] = 51004207,
            },
        [51004207] = {
            ["Content"] = "（男人沉默了一阵，抬眼打量起你来，几乎能听见他抬头时脊椎疲惫地的异响。）",
            ["ContentKR"] = "(잠시 침묵하던 남자가 나를 훑어봤다. 고개를 들 때, 그의 등뼈에서 피로한 소리가 나는 것처럼 보였다.)",
            ["DialogueId"] = 51004207,
            ["GUID"] = "7FAF05B6",
            ["NextDialogue"] = 51004208,
            },
        [51004208] = {
            ["Content"] = "碎嘴子。",
            ["ContentKR"] = "시끄럽긴.",
            ["DialogueId"] = 51004208,
            ["GUID"] = "7FAF05E0",
            ["NextDialogue"] = 51004209,
            ["SpeakNpcId"] = 700096,
            ["TalkActionId"] = {
                [1] = "700096:Disagree",
                },
            },
        [51004209] = {
            ["Content"] = "（他轻哼了一声，又似乎很满意你的回答。）",
            ["ContentKR"] = "(그가 작게 콧방귀를 뀌었고, 내 대답에 만족한 것 같았다.)",
            ["DialogueId"] = 51004209,
            ["GUID"] = "7FAF060A",
            ["NextDialogue"] = 51004210,
            },
        [51004210] = {
            ["Content"] = "不管是谁介绍你来的，反正也是为了我口袋里的货，对吧？",
            ["ContentKR"] = "누가 불렀든, 내가 갖고 있는 물건 때문에 온 거잖아. 맞지?",
            ["DialogueId"] = 51004210,
            ["GUID"] = "7FAF0634",
            ["NextDialogue"] = 51004211,
            ["SpeakNpcId"] = 700096,
            ["TalkActionId"] = {
                [1] = "700096:Confident_Start",
                },
            },
        [51004211] = {
            ["Content"] = "（男人扯开衣领，黯淡的金属管自怀中闪过。）",
            ["ContentKR"] = "(남자가 옷깃을 젖히자 검은 물체가 반짝였다. )",
            ["DialogueId"] = 51004211,
            ["GUID"] = "7FAF065E",
            ["NextDialogue"] = 51004212,
            ["TalkActionId"] = {
                [1] = "700096:Confident_End",
                },
            },
        [51004212] = {
            ["Content"] = "（他立刻收紧了衣领，警惕地望了望四周。）",
            ["ContentKR"] = "(그리는 바로 옷깃을 여미고 주변을 경계한다.)",
            ["DialogueId"] = 51004212,
            ["GUID"] = "7FAF0688",
            ["NextDialogue"] = 51004213,
            },
        [51004213] = {
            ["Content"] = "4号口径，双管单发，不论是卡戎人还是秽兽，在它面前都走不过两下。",
            ["ContentKR"] = "4구경 연발식 샷건이다. 카론이든 필토이드든 한 방에 처리할 수 있지.",
            ["DialogueId"] = 51004213,
            ["GUID"] = "7FAF06B2",
            ["NextDialogue"] = 51004214,
            ["SpeakNpcId"] = 700096,
            },
        [51004214] = {
            ["Content"] = "（男人撇了撇嘴，像在谈论农用杀虫剂的功效。）",
            ["ContentKR"] = "(남자는 농업용 살충제의 효능을 설명하기라도 하듯 샐쭉한 표정을 짓는다.)",
            ["DialogueId"] = 51004214,
            ["GUID"] = "7FAF06DC",
            ["NextDialogue"] = 51004215,
            },
        [51004215] = {
            ["Content"] = "这回的货不要钱，只要你帮我办件事。",
            ["ContentKR"] = "물건값은 받지 않을게. 대신 내 부탁 좀 들어줘.",
            ["DialogueId"] = 51004215,
            ["GUID"] = "7FAF0706",
            ["NextOptions"] = {
                [1] = 510042151,
                [2] = 510042152,
                },
            ["SpeakNpcId"] = 700096,
            ["bForbidSkipOptions"] = true,
            },
        [51004216] = {
            ["Content"] = "哆嗦什么？你不就是冲着这玩意来的吗？",
            ["ContentKR"] = "뭘 그렇게 우물쭈물거려? 이것 때문에 온 거 아냐?",
            ["DialogueId"] = 51004216,
            ["GUID"] = "7FAF0730",
            ["NextDialogue"] = 51004217,
            ["SpeakNpcId"] = 700096,
            ["TalkActionId"] = {
                [1] = "700096:Explain01_Start",
                },
            },
        [51004217] = {
            ["Content"] = "事儿办利索了，不仅东西归你，我再追补给你一笔。",
            ["ContentKR"] = "일만 제대로 처리하면, 물건에다가 추가로 보수도 줄게.",
            ["DialogueId"] = 51004217,
            ["GUID"] = "7FAF075A",
            ["NextOptions"] = {
                [1] = 510042171,
                [2] = 510042172,
                },
            ["RestartTag"] = 51004216,
            ["SpeakNpcId"] = 700096,
            ["TalkActionId"] = {
                [1] = "700096:Explain01_End",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51004218] = {
            ["Content"] = "想快点，我等不了你太久。",
            ["ContentKR"] = "오래 못 기다리니까 빨리 결정해.",
            ["DialogueId"] = 51004218,
            ["GUID"] = "7FAF0784",
            ["SpeakNpcId"] = 700096,
            },
        [51004219] = {
            ["Content"] = "好吧，你要我做什么？",
            ["ContentKR"] = "좋아요. 제가 뭘 하면 되죠?",
            ["DialogueId"] = 51004219,
            ["GUID"] = "7FAF07AE",
            ["NextDialogue"] = 51004220,
            ["SpeakNpcId"] = 100001,
            },
        [51004220] = {
            ["Content"] = "爽快，一会儿我给你个地方，目标就是那地方除了女人之外的东西都清了。",
            ["ContentKR"] = "시원시원하군. 내가 주소를 알려줄 테니, 그곳에 있는 여자만 제외하고 나머지를 모두 없애버려.",
            ["DialogueId"] = 51004220,
            ["GUID"] = "7FAF07D8",
            ["NextDialogue"] = 51004221,
            ["SpeakNpcId"] = 700096,
            ["TalkActionId"] = {
                [1] = "700096:Agree",
                },
            },
        [51004221] = {
            ["Content"] = "这……感情问题……？",
            ["ContentKR"] = "혹시... 치정 문제인가요...?",
            ["DialogueId"] = 51004221,
            ["GUID"] = "7FAF0802",
            ["NextDialogue"] = 51004222,
            ["SpeakNpcId"] = 100001,
            },
        [51004222] = {
            ["Content"] = "别多嘴。",
            ["ContentKR"] = "조용히 해.",
            ["DialogueId"] = 51004222,
            ["GUID"] = "7FAF082C",
            ["NextDialogue"] = 51004223,
            ["SpeakNpcId"] = 700096,
            ["TalkActionId"] = {
                [1] = "700096:Disagree",
                },
            },
        [51004223] = {
            ["Content"] = "(男人紧了紧衣领，抿住干瘪的嘴唇，不愿再吐出任何一个字。)",
            ["ContentKR"] = "(남자는 다시 옷깃을 여미고, 마른 입술을 문지르며 말을 아꼈다.)",
            ["DialogueId"] = 51004223,
            ["GUID"] = "7FAF0856",
            },
        [51004301] = {
            ["Content"] = "行啊，收了钱就走吧，我不希望在这附近见到你。",
            ["ContentKR"] = "됐어. 돈 받았으면 이제 가 봐. 이 근처에서 다시 마주치는 일은 없었으면 좋겠군.",
            ["DialogueId"] = 51004301,
            ["GUID"] = "7FAF1522",
            ["NextDialogue"] = 51004302,
            ["SpeakNpcId"] = 700101,
            ["TalkActionId"] = {
                [1] = "700101:Agree",
                },
            },
        [51004302] = {
            ["Content"] = "你是想找人清理附近的秽兽？就算不雇佣我，也会有人处理那些秽兽的。",
            ["ContentKR"] = "이 부근의 필토이드를 처치하려는 거였어요? 제가 아니었어도 누군가는 필토이드를 처리했을 텐데요.",
            ["DialogueId"] = 51004302,
            ["GUID"] = "7FAF154C",
            ["NextDialogue"] = 51004303,
            ["SpeakNpcId"] = 100001,
            },
        [51004303] = {
            ["Content"] = "有人处理？谁？那群把卡戎人当狗的杂碎？",
            ["ContentKR"] = "누군가가 한다고? 누가? 설마 카론을 얕보는 그 비열한 자식들이?",
