            ["GUID"] = "7FAF161E",
            ["NextDialogue"] = 51004308,
            ["SpeakNpcId"] = 700101,
            },
        [51004308] = {
            ["Content"] = "这……也许你可以想办法帮她离开冰湖城，换个地方生活。",
            ["ContentKR"] = "그럼... 그 여자가 아이스레이크 시티가 아닌 다른 곳에서 살 방법을 생각하면 되잖아요.",
            ["DialogueId"] = 51004308,
            ["GUID"] = "7FAF1648",
            ["NextDialogue"] = 51004309,
            ["SpeakNpcId"] = 100001,
            },
        [51004309] = {
            ["Content"] = "……快了，快攒够了。",
            ["ContentKR"] = "...그것도 금방이야. 돈을 거의 다 모았거든.",
            ["DialogueId"] = 51004309,
