            ["SpeakNpcId"] = 100001,
            },
        [51004913] = {
            ["Content"] = "（露娜指了指喉咙上的疤痕，然后拿起一张空白的纸，奋笔疾书。）",
            ["ContentKR"] = "(루나가 자기 목을 가리키더니, 곧바로 빈 종이를 집어 들고 무언가를 급히 써 내려간다.)",
            ["DialogueId"] = 51004913,
