            ["GUID"] = "7FAF79DE",
            ["NextDialogue"] = 51004916,
            ["SpeakNpcId"] = 100001,
            },
        [51004916] = {
            ["Content"] = "（露娜低头在纸上写着什么。）",
            ["ContentKR"] = "(루나가 다시 고개를 숙여 종이에 뭔가를 쓴다.)",
