        [51004917] = {
            ["Content"] = "“憋在心里太难受。”",
            ["ContentKR"] = "'마음에 담아놓고 있기엔 너무 고통스러워요.'",
            ["DialogueId"] = 51004917,
            ["GUID"] = "7FAF7A32",
            ["NextOptions"] = {
                [1] = 510049171,
                [2] = 510049172,
                [3] = 510049173,
