                [1] = "700127:Confident_End",
                },
            },
        [51005213] = {
            ["Camera"] = "12.572754,75.52832,130.532715,-0.0,0.199879,-101.394386,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "外乡人，欢迎来到冰湖城！",
            ["ContentKR"] = "자, 그렇다면... 아이스레이크 시티에 오신 걸 환영합니다!",
            ["DialogueId"] = 51005213,
            ["FacialId"] = {
                [1] = "700127:Happy02",
                },
            ["GUID"] = "7FAFAAC2",
            ["SpeakNpcId"] = 700127,
            ["TalkActionId"] = {
                [1] = "700127:Talk02_Start",
                },
            },
        [51005301] = {
            ["Content"] = "只要消毒得当，就能成为一盘好菜！",
            ["ContentKR"] = "잘 처리하면 좋은 음식이 될 거야!",
            ["DialogueId"] = 51005301,
            ["GUID"] = "7FAFB932",
            ["NextDialogue"] = 51005302,
            ["SpeakNpcId"] = 700116,
            },
        [51005302] = {
            ["Content"] = "……腥味是没了，但这些水产本身的鲜甜味却没有激发出来……",
            ["ContentKR"] = "...비린내는 사라졌지만, 해물 본연의 맛이 나지 않아...",
            ["DialogueId"] = 51005302,
            ["GUID"] = "7FAFB95C",
            ["NextDialogue"] = 51005303,
            ["SpeakNpcId"] = 700116,
            ["TalkActionId"] = {
                [1] = "700116:Think_Start",
                },
            },
        [51005303] = {
            ["Content"] = "（面前这位男人语速飞快，布满血丝的双眼死死盯着手中的册子和身旁不知名的鱼虾，用还黏着葱叶的双手飞快地写着什么。）",
            ["ContentKR"] = "(남자는 빠르게 말하며 충혈된 눈으로 수첩을 뚫어지게 보고 있다. 옆에는 이름 모를 해산물이 널려 있다. 파가 달라붙은 손으로 빠르게 무언가 써 내려간다.)",
            ["DialogueId"] = 51005303,
            ["GUID"] = "7FAFB986",
            ["NextOptions"] = {
                [1] = 510053031,
                [2] = 510053032,
                },
            ["TalkActionId"] = {
                [1] = "700116:Think_End",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51005304] = {
            ["Content"] = "（装订环上的少量锈迹说明这本老旧册子近期才经历过不怎么细致的清理。）",
            ["ContentKR"] = "(고리가 살짝 녹슨 것을 보니, 최근엔 이 낡은 수첩을 깨끗이 관리한 것 같지는 않다.)",
            ["DialogueId"] = 51005304,
            ["GUID"] = "7FAFB9B0",
            ["NextDialogue"] = 51005305,
            },
        [51005305] = {
            ["Content"] = "（凑近观察，勉强从杂乱的图形与线条间拼凑出几个香料与烹调方式的词组，想来男人手中的大概是一本食谱。）",
            ["ContentKR"] = "(가까이 가서 보니, 복잡한 도형과 선 사이로 향신료와 조리법이 써 있다. 레시피인 것 같다.)",
            ["DialogueId"] = 51005305,
            ["GUID"] = "7FAFB9DA",
            ["NextDialogue"] = 51005307,
            },
        [51005306] = {
            ["Content"] = "（现在最好的选择就是转身离开，但身体在执行的时候却踩到了流淌在地面的粘液发出噗呲的闷响。）",
            ["ContentKR"] = "(지금은 자리를 뜨는 게 최선이다. 하지만 몸을 돌리는 순간 바닥에 흐르는 액체를 밟아 소리가 난다.)",
            ["DialogueId"] = 51005306,
            ["GUID"] = "7FAFBA04",
            ["NextDialogue"] = 51005307,
            },
        [51005307] = {
            ["Content"] = "（现在，这名男人注意到你了。）",
            ["ContentKR"] = "(남자가 나를 발견했다.)",
            ["DialogueId"] = 51005307,
            ["GUID"] = "7FAFBA2E",
            ["NextDialogue"] = 51005308,
            },
        [51005308] = {
            ["Content"] = "……你是？",
            ["ContentKR"] = "...누구시죠?",
            ["DialogueId"] = 51005308,
            ["GUID"] = "7FAFBA58",
            ["NextDialogue"] = 51005309,
            ["SpeakNpcId"] = 700116,
            },
        [51005309] = {
            ["Content"] = "路过的狩月人。",
            ["ContentKR"] = "지나가던 월석 사냥꾼입니다.",
            ["DialogueId"] = 51005309,
            ["GUID"] = "7FAFBA82",
            ["NextDialogue"] = 51005310,
            ["SpeakNpcId"] = 100001,
            },
        [51005310] = {
            ["Content"] = "既然是狩月人的话，你是否愿意接受我的委托，与我一起做出更加美味的菜品呢？",
            ["ContentKR"] = "월석 사냥꾼이라면, 저와 더 맛있는 요리를 만드는 의뢰는 어떤가요?",
            ["DialogueId"] = 51005310,
            ["GUID"] = "7FAFBAAC",
            ["NextOptions"] = {
                [1] = 51000001,
                [2] = 51000002,
                },
            ["SpeakNpcId"] = 700116,
            ["TalkActionId"] = {
                [1] = "700116:Explain02_Start",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51005311] = {
            ["Content"] = "万分感谢。这第一道菜，是在渔民间流传的腌制活鱼活虾的方法上，进行改良的。我这还有些饵料，麻烦你去钓一些用来腌制的东西吧。",
            ["ContentKR"] = "정말 고마워요. 첫 번째 요리는 활어와 새우를 절이는 어부들의 전통 방식을 응용한 거예요. 번거로우시겠지만, 절임에 쓸 재료들을 낚아 와 주세요. 미끼는 여기 있어요.",
            ["DialogueId"] = 51005311,
            ["GUID"] = "7FAFBAD6",
            ["NextOptions"] = {
                [1] = 510053111,
                [2] = 510053112,
                },
            ["SpeakNpcId"] = 700116,
            ["TalkActionId"] = {
                [1] = "700116:Explain02_End",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51005312] = {
            ["Content"] = "对啊！我会在这期间做好烹饪与消毒的准备。饵料用光了的话就再回来找我吧。",
            ["ContentKR"] = "네! 저는 그사이에 소독도 하고 요리 준비를 해 놓을게요. 미끼가 바닥나면, 다시 절 찾아오시면 돼요.",
            ["DialogueId"] = 51005312,
            ["GUID"] = "7FAFBB00",
            ["SpeakNpcId"] = 700116,
            ["TalkActionId"] = {
                [1] = "700116:Agree",
                },
            },
        [51005313] = {
            ["Content"] = "这里天然的盐泉似乎能提供腌制所需的材料，采集一些带回去吧。",
            ["ContentKR"] = "여기 있는 천연 염전에서 절임에 필요한 재료를 얻을 수 있을 것 같아. 조금 모아서 가져가자.",
            ["DialogueId"] = 51005313,
            ["GUID"] = "7FAFBB2A",
            ["SpeakNpcId"] = 100001,
            },
        [51005314] = {
            ["Content"] = "钓到了，回去找马库斯吧。",
            ["ContentKR"] = "물고기를 낚았다. 이제 마커스에게 돌아가자.",
            ["DialogueId"] = 51005314,
            ["GUID"] = "7FAFBB54",
            ["SpeakNpcId"] = 100001,
            },
        [51005315] = {
            ["Content"] = "钓到了，回去找马库斯吧。",
            ["ContentKR"] = "물고기를 낚았다. 이제 마커스에게 돌아가자.",
            ["DialogueId"] = 51005315,
            ["GUID"] = "7FAFBB7E",
            ["SpeakNpcId"] = 100001,
            },
        [51005401] = {
            ["Content"] = "滚滚葱叶切段备用……鱼虾冲净后加入盐、醋，考虑到冰湖城人的口味也许应该再加点糖……",
            ["ContentKR"] = "파는 작게 썰고... 해산물은 씻어서 소금과 식초를 넣어야 해. 아이스레이크 시티 사람들 입맛을 생각하면 설탕을 좀 더 넣어야겠어...",
            ["DialogueId"] = 51005401,
            ["GUID"] = "7FAFC99A",
            ["NextDialogue"] = 51005402,
            ["SpeakNpcId"] = 700116,
            },
        [51005402] = {
            ["Content"] = "（马库斯木讷地接过原料，一边念叨着烹调方式一边拖着它们走远了。）",
            ["ContentKR"] = "(재료를 받아 든 마커스는 조리법을 중얼거리며 길모퉁이로 사라진다.)",
            ["DialogueId"] = 51005402,
            ["GUID"] = "7FAFC9C4",
            },
        [51005403] = {
            ["Content"] = "（一段时间后，马库斯不知从哪里突然冲出，直到摔倒在雪地里才意识到自己的失态，尴尬地笑着用手拂去身上的尘土。）",
            ["ContentKR"] = "(얼마 후 갑자기 어디선가 마커스가 나타난다. 눈 위로 넘어진 뒤에야 본인의 추태를 깨달은 그는 민망한 듯 웃으며 일어나 옷을 턴다.)",
            ["DialogueId"] = 51005403,
            ["GUID"] = "7FAFC9EE",
            ["NextDialogue"] = 51005404,
            },
        [51005404] = {
            ["Content"] = "……抱歉。",
            ["ContentKR"] = "...죄송해요.",
            ["DialogueId"] = 51005404,
            ["GUID"] = "7FAFCA18",
            ["NextDialogue"] = 51005405,
            ["SpeakNpcId"] = 700116,
            },
        [51005405] = {
            ["Content"] = "你也尝尝味道怎么样？能不能感受到冰湖城特色风味？",
            ["ContentKR"] = "맛 좀 봐봐요. 아이스레이크 시티 특유의 맛이 느껴지나요?",
            ["DialogueId"] = 51005405,
            ["GUID"] = "7FAFCA42",
            ["NextDialogue"] = 51005406,
            ["SpeakNpcId"] = 700116,
            },
        [51005406] = {
            ["Content"] = "（他从怀里掏出一包密封的鱼虾，浸润在黝黑的酱汁中隐隐散发着晶莹的光芒。即使隔着密封的薄膜也能闻到浓郁的酱香。）",
            ["ContentKR"] = "(마커스가 품에서 밀봉된 해산물을 꺼낸다. 해산물이 담긴 어두운색의 소스는 은은한 빛이 반짝이고, 그 위를 덮은 랩을 뚫고 진한 향이 새어 나온다.)",
            ["DialogueId"] = 51005406,
            ["GUID"] = "7FAFCA6C",
            ["NextOptions"] = {
                [1] = 510054061,
                [2] = 510054062,
                [3] = 510054063,
                },
            ["TalkActionId"] = {
                [1] = "700116:Give",
                },
            },
        [51005407] = {
            ["Content"] = "不要用那么古板的思维看待菜肴。一个人一生中如果不挑战一下非常规食材，那么他人生的乐趣就减少了一半。",
            ["ContentKR"] = "요리에 대한 편견을 깨봐요. 이런 특별한 음식에 도전하지 않으면 인생의 즐거움은 줄어들게 되는 법이죠.",
            ["DialogueId"] = 51005407,
            ["GUID"] = "7FAFCA96",
            ["NextDialogue"] = 51005410,
            ["SpeakNpcId"] = 700116,
            ["TalkActionId"] = {
                [1] = "700116:Disagree",
                },
            },
        [51005408] = {
            ["Content"] = "哈哈，算了算了，看你都快哭出来了。",
            ["ContentKR"] = "하하, 됐어요, 됐어. 그러다 곧 울겠어요.",
            ["DialogueId"] = 51005408,
            ["GUID"] = "7FAFCAC0",
            ["NextDialogue"] = 51005410,
            ["SpeakNpcId"] = 700116,
            },
        [51005409] = {
            ["Content"] = "哼。还好不是所有人都像你一样，对食材的多样性心存偏见。",
            ["ContentKR"] = "흥. 모두가 당신처럼 다양한 식재료에 편견이 있는 게 아니라 다행이군요.",
            ["DialogueId"] = 51005409,
            ["GUID"] = "7FAFCAEA",
            ["NextDialogue"] = 51005410,
            ["SpeakNpcId"] = 700116,
            },
        [51005410] = {
            ["Content"] = "嗯……总之，还有些改良空间。",
            ["ContentKR"] = "음... 어쨌든 더 개선이 필요하겠네요.",
            ["DialogueId"] = 51005410,
            ["GUID"] = "7FAFCB14",
            ["NextDialogue"] = 51005411,
            ["SpeakNpcId"] = 700116,
            ["TalkActionId"] = {
                [1] = "700116:Agree",
                },
            },
        [51005411] = {
            ["Content"] = "之后第二道菜也拜托你了，我的美食搭档！",
            ["ContentKR"] = "두 번째 음식도 부탁해요, 요리 파트너님!",
            ["DialogueId"] = 51005411,
            ["GUID"] = "7FAFCB3E",
            ["SpeakNpcId"] = 700116,
            },
        }
  end },
  { MinKey = 51005501, MaxKey = 51006735, Loader = function()
      return {
        [51005501] = {
            ["Content"] = "炖的方式更暖胃，作为开胃菜刚刚好，现在还缺……",
            ["ContentKR"] = "삶는 건 속을 따뜻하게 해주니 에피타이저로 괜찮지만, 아직...",
            ["DialogueId"] = 51005501,
            ["GUID"] = "7FAFDA02",
            ["NextDialogue"] = 51005502,
            ["SpeakNpcId"] = 700117,
            ["TalkActionId"] = {
                [1] = "700117:Think_Start",
                },
            },
        [51005502] = {
            ["Content"] = "（马库斯泛白的脸即使在冰湖的冷风吹拂下也不见一丝血色，不注意观察甚至会以为这是一尊被人遗弃的冰雕。）",
            ["ContentKR"] = "(마커스의 하얀 얼굴은 아이스레이크의 찬바람에도 빨갛게 얼지 않았다. 얼핏 보면 누군가 두고 간 얼음 조각상처럼 보일 정도다.)",
            ["DialogueId"] = 51005502,
            ["GUID"] = "7FAFDA2C",
            ["NextDialogue"] = 51005503,
            },
        [51005503] = {
            ["Content"] = "（但他完全没关注环境的恶劣与身体的哀嚎。）",
            ["ContentKR"] = "(그렇지만 그는 열악한 환경과 아픈 몸을 신경 쓰지 않는다.)",
            ["DialogueId"] = 51005503,
            ["GUID"] = "7FAFDA56",
            ["NextDialogue"] = 51005504,
            },
        [51005504] = {
            ["Content"] = "（他只是专注地念出一个个原料、调味与烹饪方式，又快速将其否掉，在脑海中拼凑着通向极致菜肴的道路。）",
            ["ContentKR"] = "(그는 재료와 조미료, 조리법을 하나씩 말하며, 최고의 요리를 만들기 위한 방법을 고심 중이다.)",
            ["DialogueId"] = 51005504,
            ["GUID"] = "7FAFDA80",
            ["NextDialogue"] = 51005505,
            ["TalkActionId"] = {
                [1] = "700117:Think_End",
                },
            },
        [51005505] = {
            ["Content"] = "搭档，你来了！",
            ["ContentKR"] = "파트너님, 오셨군요!",
            ["DialogueId"] = 51005505,
            ["GUID"] = "7FAFDAAA",
            ["NextDialogue"] = 51005506,
            ["SpeakNpcId"] = 700117,
            ["TurnTo"] = {
                [1] = "700117:n(0)",
                },
            },
        [51005506] = {
            ["Content"] = "话不多说，现在还差些月牙鱼，拜托了！",
            ["ContentKR"] = "본론부터 말할게요. 마블 피쉬가 몇 마리 더 필요해요. 구하기 힘든 생선이지만, 파트너라면 문제없을 거라고 믿어요. 꼭 좀 부탁해요!",
            ["DialogueId"] = 51005506,
            ["GUID"] = "7FAFDAD4",
            ["NextDialogue"] = 51005507,
            ["SpeakNpcId"] = 700117,
            },
        [51005507] = {
            ["Content"] = "（听完马库斯的话你松了一口气。至少这次应该不会被要求试吃生食了。）",
            ["ContentKR"] = "(구하기는 더 어렵겠지만, 나로선 오히려 다행이었다. 적어도 이번에는 익히지 않은 음식을 맛볼 일은 없겠지.)",
            ["DialogueId"] = 51005507,
            ["GUID"] = "7FAFDAFE",
            },
        [51005508] = {
            ["Content"] = "垂钓了好一阵子，总算获得了马库斯所需的月牙鱼。",
            ["ContentKR"] = "한참을 낚시한 끝에 마커스가 필요하다는 마블 피쉬를 얻었다.",
            ["DialogueId"] = 51005508,
            ["Duration"] = 3,
            ["GUID"] = "7FAFDB28",
            },
        [51005601] = {
            ["Content"] = "（马库斯站在原地剥着北风莓的果皮，一言不发，愈发像是一尊冰雕。但不时抽动的眉头表明，他正在忍受着某种先前没有的刺痛。）",
            ["ContentKR"] = "(마커스는 가만히 서서 아이스베리의 껍질을 까고 있다. 아무 말도 하지 않으니 더 얼음 조각상처럼 보인다. 간혹 처음 겪는 고통을 참는 듯 미간을 찌푸린다.)",
            ["DialogueId"] = 51005601,
            ["GUID"] = "7FAFEA6A",
            ["NextOptions"] = {
                [1] = 510056011,
                [2] = 510056012,
                },
            ["bForbidSkipOptions"] = true,
            },
        [51005602] = {
            ["Content"] = "（果皮上有血渍与泥土，其中几枚还因用力过猛而发生了变形，结合马库斯手掌上崭新的划痕来看，这些北风莓应是马库斯刚才亲自攀上附近的山崖采摘的。）",
            ["ContentKR"] = "(껍질에 핏자국과 흙이 묻어 있다. 힘이 너무 강한 탓인지 몇 개는 모양이 망가졌다. 마커스의 손바닥에 난 상처를 보니, 이건 가까운 절벽에서 마커스가 직접 딴 아이스베리인 것 같다.)",
            ["DialogueId"] = 51005602,
            ["GUID"] = "7FAFEA94",
            ["NextOptions"] = {
                [1] = 51005604,
                },
            },
        [51005603] = {
            ["Content"] = "（鲜血将马库斯一侧的衣服浸透，应是刚才受过什么伤。虽已止血，但对他的伤势来说并没有太大帮助。）",
            ["ContentKR"] = "(마커스의 옷 한 부분에 방금 다친 것처럼 피가 배어 있었다. 피는 멎었지만, 꽤 큰 부상이다.)",
            ["DialogueId"] = 51005603,
            ["GUID"] = "7FAFEABE",
            ["NextOptions"] = {
                [1] = 51005604,
                },
            },
        [51005604] = {
            ["Content"] = "这些血……",
            ["ContentKR"] = "피가...",
            ["DialogueId"] = 51005604,
            ["GUID"] = "7FAFEAE8",
            ["NextDialogue"] = 51005605,
            },
        [51005605] = {
            ["Content"] = "小事，摘北风莓的时候摔伤了而已。看你的样子，月牙鱼到手了啊，我就知道你做得到，谢了。",
            ["ContentKR"] = "별건 아니고, 아이스베리를 따다가 살짝 넘어졌을 뿐이에요. 표정을 보니까, 마블 피쉬를 구한 모양이군요. 역시 해낼 줄 알았어요. 정말 고마워요.",
            ["DialogueId"] = 51005605,
            ["GUID"] = "7FAFEB12",
            ["NextDialogue"] = 51005606,
            ["SpeakNpcId"] = 700117,
            ["TurnTo"] = {
                [1] = "700117:n(0)",
                },
            },
        [51005606] = {
            ["Content"] = "（马库斯不愿过多讨论自己的伤势，抬手将北风莓丢进锅里，搅拌均匀后舀出一勺汤汁轻抿了一口。）",
            ["ContentKR"] = "(부상에 대한 말을 아낀 마커스는 냄비에 아이스베리를 넣고 저은 뒤 조금 맛본다.)",
            ["DialogueId"] = 51005606,
            ["GUID"] = "7FAFEB3C",
            ["NextDialogue"] = 51005607,
            },
        [51005607] = {
            ["Content"] = "新鲜的北风莓，加入汤汁的话果然让香气更浓了。",
            ["ContentKR"] = "신선한 아이스베리가 들어가니 향이 더 진해지는군요.",
            ["DialogueId"] = 51005607,
            ["GUID"] = "7FAFEB66",
            ["NextDialogue"] = 51005608,
            ["SpeakNpcId"] = 700117,
            ["TalkActionId"] = {
                [1] = "700117:Agree",
                },
            },
        [51005608] = {
            ["Content"] = "那月牙鱼也得换种处理方式……",
            ["ContentKR"] = "마블 피쉬 조리법도 바꿔야겠어요...",
            ["DialogueId"] = 51005608,
            ["GUID"] = "7FAFEB90",
            ["NextDialogue"] = 51005609,
            ["SpeakNpcId"] = 700117,
            },
        [51005609] = {
            ["Content"] = "（马库斯拖着受伤的身体完成剔油、翻焯、煨炖等一道道复杂又漫长的处理工序。）",
            ["ContentKR"] = "(마커스는 다친 몸으로 생선의 기름을 걷고, 데치고, 찌는 길고 복잡한 과정을 마친다.)",
            ["DialogueId"] = 51005609,
            ["GUID"] = "7FAFEBBA",
            ["NextDialogue"] = 51005610,
            },
        [51005610] = {
            ["Content"] = "（随着食物的香味在一点一滴的积累中迸发，他才从篝火旁起身，乘起满满一碗料理，期待着食客的评价。）",
            ["ContentKR"] = "(음식의 향이 나기 시작하자, 불 옆에 있던 마커스가 일어났다. 그리고 요리를 차리고 평가를 기다리고 있다.)",
            ["DialogueId"] = 51005610,
            ["GUID"] = "7FAFEBE4",
            ["NextDialogue"] = 51005611,
            },
        [51005611] = {
            ["Content"] = "咳咳……完成了，你尝尝够好吃、够有特色吗？",
            ["ContentKR"] = "흠흠... 다 됐어요. 먹어보고, 정말 맛있고 특별한지 알려줘요.",
            ["DialogueId"] = 51005611,
            ["GUID"] = "7FAFEC0E",
            ["NextOptions"] = {
                [1] = 51005612,
                },
            ["SpeakNpcId"] = 700117,
            ["TalkActionId"] = {
                [1] = "700117:Give",
                },
            },
        [51005612] = {
            ["Content"] = "好吃，很暖和。",
            ["ContentKR"] = "맛있어요. 아주 따뜻해요.",
            ["DialogueId"] = 51005612,
            ["GUID"] = "7FAFEC38",
            ["NextDialogue"] = 51005613,
            },
        [51005613] = {
            ["Content"] = "太好了，我回趟内城，给老板看看我们的成果！",
            ["ContentKR"] = "다행이에요. 내성으로 돌아가서 사장님께 이 소식을 전해야겠어요!",
            ["DialogueId"] = 51005613,
            ["GUID"] = "7FAFEC62",
            ["NextDialogue"] = 51005614,
            ["SpeakNpcId"] = 700117,
            },
        [51005614] = {
            ["Content"] = "多谢啦，搭档！这可是我们一起完成的菜品。大伙儿一定会喜欢的！老板也一定会赞不绝口！",
            ["ContentKR"] = "고마워요! 이건 우리가 같이 만든 음식이에요. 분명 모두 좋아할 거예요! 사장님도 칭찬을 아끼지 않을 거고요!",
            ["DialogueId"] = 51005614,
            ["GUID"] = "7FAFEC8C",
            ["SpeakNpcId"] = 700117,
            },
        [51005701] = {
            ["Content"] = "……",
            ["ContentKR"] = "......",
            ["DialogueId"] = 51005701,
            ["GUID"] = "7FAFFAD2",
            ["NextDialogue"] = 51005702,
            },
        [51005702] = {
            ["Content"] = "（第三次遇到马库斯时，他就静静地坐在那里，腿上放着一份饭盒。他的神情憔悴，皮肤干瘪，似是很久未曾入睡。）",
            ["ContentKR"] = "(세 번째 만난 마커스는 다리에 도시락을 올려놓은 채 가만히 앉아 있다. 오랫동안 잠을 못 잔 듯 초췌하고 지쳐 보인다.)",
            ["DialogueId"] = 51005702,
            ["GUID"] = "7FAFFAFC",
            ["NextDialogue"] = 51005703,
            },
        [51005703] = {
            ["Content"] = "（腹部的伤口依然没有得到妥善处置，若是在炎热的城市说不定那些伤口都会开始散发出腐臭的气息。）",
            ["ContentKR"] = "(몸에 난 상처는 아직도 제대로 치료하지 않았다. 이곳이 더운 곳이었다면 상처에서는 불쾌한 냄새가 났을 것이다.)",
            ["DialogueId"] = 51005703,
            ["GUID"] = "7FAFFB26",
            ["NextOptions"] = {
                [1] = 51005704,
                },
            },
        [51005704] = {
            ["Content"] = "……你还好吗，老板怎么说？",
            ["ContentKR"] = "...괜찮아요? 사장님은 뭐라고 하셨어요?",
            ["DialogueId"] = 51005704,
            ["GUID"] = "7FAFFB50",
            ["NextDialogue"] = 51005705,
            },
        [51005705] = {
            ["Content"] = "……",
            ["ContentKR"] = "......",
            ["DialogueId"] = 51005705,
            ["GUID"] = "7FAFFB7A",
            ["LookAt"] = {
                [1] = "700121:n(0)",
                },
            ["NextDialogue"] = 51005706,
            ["SpeakNpcId"] = 700121,
            },
        [51005706] = {
            ["Content"] = "……哈哈，他看都没看，说我之前做的菜一直赚不了大钱，也不准备再雇佣我了。",
            ["ContentKR"] = "...하하, 거들떠보지도 않았어요. 그동안 제 요리로는 돈을 못 벌었다면서, 저를 다시 고용하지 않겠대요.",
            ["DialogueId"] = 51005706,
            ["GUID"] = "7FAFFBA4",
            ["NextOptions"] = {
                [1] = 51005707,
                },
            ["SpeakNpcId"] = 700121,
            },
        [51005707] = {
            ["Content"] = "……",
            ["ContentKR"] = "......",
            ["DialogueId"] = 51005707,
            ["GUID"] = "7FAFFBCE",
            ["NextDialogue"] = 51005708,
            },
        [51005708] = {
            ["Content"] = "不重要，最后一道菜我也完成了，要不要尝尝看？",
            ["ContentKR"] = "괜찮아요. 이제 마지막 요리도 완성했는데, 먹어볼래요?",
            ["DialogueId"] = 51005708,
            ["GUID"] = "7FAFFBF8",
            ["NextDialogue"] = 51005709,
            ["SpeakNpcId"] = 700121,
            },
        [51005709] = {
            ["Content"] = "（马库斯颤抖着举起双手，将饭盒打开，炖菜与碎肉饼的香味便混在一起冲出饭盒，挑逗着食欲。）",
            ["ContentKR"] = "(마커스가 떨리는 두 손으로 도시락 뚜껑을 열자, 스튜와 미트볼의 향기가 한데 어우러져 흘러나오며 식욕을 자극한다.)",
            ["DialogueId"] = 51005709,
            ["GUID"] = "7FAFFC22",
            ["NextDialogue"] = 51005710,
            },
        [51005710] = {
            ["Content"] = "（虽说不是大人物们常吃的肉排，却也能支持人们一整天的劳作。几枚被雕刻成星星形状的薯饼点缀其间，为菜肴注入了别样的心意。）",
            ["ContentKR"] = "(높으신 분들이 즐겨 먹는 스테이크는 아니었지만, 하루의 고단함을 달래 줄 식사로는 충분하다. 게다가 별 모양 해시 브라운 몇 조각을 곁들여, 요리에 특별한 정성을 더했다.)",
            ["DialogueId"] = 51005710,
            ["GUID"] = "7FAFFC4C",
            ["NextDialogue"] = 51005711,
            },
        [51005711] = {
            ["Content"] = "（品尝一口，这些食物平凡的外表下绽放出无法言喻的美味，让全身都充满活力，精神也为之振奋，甚至不再畏惧冰湖的寒冬。）",
            ["ContentKR"] = "(한 입 먹으니 평범한 모습과 달리 황홀한 맛이 나서, 기운이 솟고 기분이 좋아진다. 심지어 아이스레이크의 추위도 두렵지 않을 정도다.)",
            ["DialogueId"] = 51005711,
            ["GUID"] = "7FAFFC76",
            ["NextDialogue"] = 51005712,
            },
        [51005712] = {
            ["Content"] = "（而在饭盒的下方，整齐地叠放着一张布满涂改痕迹的食谱。他点了点头，示意食谱现在起有了新的主人，并微笑等待着食客的评价。）",
            ["ContentKR"] = "(도시락 밑에는 수정한 흔적이 가득한 레시피가 적힌 종이가 있다. 그는 이제 레시피의 새로운 주인이 생겼다는 듯 고개를 끄덕인다. 그리고 웃으며 평가를 기다린다.)",
            ["DialogueId"] = 51005712,
            ["GUID"] = "7FAFFCA0",
            ["NextOptions"] = {
                [1] = 510057121,
                [2] = 510057122,
                },
            ["bForbidSkipOptions"] = true,
            },
        [51005713] = {
            ["Content"] = "谢谢你愿意吃我做的菜……",
            ["ContentKR"] = "제 음식을 먹어줘서 고마워요...",
            ["DialogueId"] = 51005713,
            ["GUID"] = "7FAFFCCA",
            ["NextDialogue"] = 51005714,
            ["SpeakNpcId"] = 700121,
            },
        [51005714] = {
            ["Content"] = "（他长呼一口气，手臂无力地垂下，缓缓闭上了双眼。）",
            ["ContentKR"] = "(마커스는 길게 숨을 내쉰 뒤, 팔을 축 늘어뜨린 채 천천히 눈을 감았다.)",
            ["DialogueId"] = 51005714,
            ["GUID"] = "7FAFFCF4",
            ["NextDialogue"] = 51005715,
            },
        [51005715] = {
            ["Content"] = "这段时间辛苦你陪我到处收集食材了，好好休息一下吧……我也是……",
            ["ContentKR"] = "그동안 재료를 찾아주느라 고생했으니 푹 쉬어요... 저도...",
            ["DialogueId"] = 51005715,
            ["GUID"] = "7FAFFD1E",
            ["NextDialogue"] = 51005719,
            ["SpeakNpcId"] = 700121,
            },
        [51005716] = {
            ["Content"] = "即使失败这么多次，你也愿意相信我能做出美味的食物啊……谢谢……你愿意吃我做的菜。",
            ["ContentKR"] = "그렇게 많이 실패했는데도, 당신은 제가 좋은 음식을 만들 수 있다고 믿는군요... 제 음식을 좋아해 줘서... 고마워요.",
            ["DialogueId"] = 51005716,
            ["GUID"] = "7FAFFD48",
            ["NextDialogue"] = 51005717,
            ["SpeakNpcId"] = 700121,
            },
        [51005717] = {
            ["Content"] = "（他长呼一口气，手臂无力地垂下，缓缓闭上了双眼。）",
            ["ContentKR"] = "(마커스는 길게 숨을 내쉰 뒤, 팔을 축 늘어뜨린 채 천천히 눈을 감는다.)",
            ["DialogueId"] = 51005717,
            ["GUID"] = "7FAFFD72",
            ["NextDialogue"] = 51005718,
            },
        [51005718] = {
            ["Content"] = "为了搭档，我自然要再努力一把才是。但现在，就让我稍微休息一下吧……",
            ["ContentKR"] = "파트너를 위해서 다시 힘을 내야죠. 우선 지금은 좀 쉴게요...",
            ["DialogueId"] = 51005718,
            ["GUID"] = "7FAFFD9C",
            ["NextDialogue"] = 51005719,
            ["SpeakNpcId"] = 700121,
            },
        [51005719] = {
            ["Content"] = "（从马库斯满足的笑容来看，他应该是找到了心中最想要的评价吧。）",
            ["ContentKR"] = "(흡족한 미소를 보니, 마커스는 그가 가장 원했던 평가를 들은 것 같다.)",
            ["DialogueId"] = 51005719,
            ["GUID"] = "7FAFFDC6",
            },
        [51005801] = {
            ["Camera"] = "-210.938385,14.624023,190.298828,0.000005,-33.268826,14.713709,27.0,1.5,false,Disable,1.2",
            ["Content"] = "（面前的箱子无论如何都打不开。）",
            ["ContentKR"] = "(어떻게 해도 상자가 열리지 않는다.)",
            ["DialogueId"] = 51005801,
            ["GUID"] = "7FB00B3A",
            ["NextDialogue"] = 51005802,
            ["Scripts"] = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0033_story_humour\"}}",
            },
        [51005802] = {
            ["Camera"] = "-330.6297,79.707031,109.34375,0.0,-0.468988,-3.087677,35.000011,1.5,false,Disable,1.2",
            ["Content"] = "喂喂喂，你这家伙怎么随便动别人的宝贝啊！",
            ["ContentKR"] = "이봐, 왜 남의 보물을 함부로 만지는 거야?",
            ["DialogueId"] = 51005802,
            ["FinalCamera"] = "-342.559265,80.349609,109.441406,0.0,-0.468988,-3.087677,35.000011,1.5,false,Disable,1.2",
            ["GUID"] = "7FB00B64",
            ["NextOptions"] = {
                [1] = 510058021,
                [2] = 510058022,
                [3] = 510058023,
                },
            ["Scripts"] = "TurnTo{_delay{1.5},TurnToDescription{\"100001:p(180)\"}}",
            ["SpeakNpcId"] = 700123,
            ["ToFinalCameraBlendTime"] = 6,
            ["bForbidSkipOptions"] = true,
            },
        [51005803] = {
            ["Camera"] = "-121.098236,-47.270508,134.38916,0.00009,-2.592344,127.106155,35.000011,1.5,false,Disable,1.2",
            ["Content"] = "好有气魄的发言，大哥，这{性别：小子|小妮子}感觉不好惹啊。",
            ["ContentKR"] = "뭔 소리를 하는 건지. 형, 말이 안 통하는 {性别:녀석|녀석}인 것 같아.",
            ["DialogueId"] = 51005803,
            ["GUID"] = "7FB00B8E",
            ["LookAt"] = {
                [1] = "700124:n(700123)",
                },
            ["NextDialogue"] = 51005807,
            ["SpeakNpcId"] = 700124,
            },
        [51005804] = {
            ["Camera"] = "-121.098236,-47.270508,134.38916,0.00009,-2.592344,127.106155,35.000011,1.5,false,Disable,1.2",
            ["Content"] = "没事没事，人家也不知道……",
            ["ContentKR"] = "아니, 괜찮아. 다들 잘 모르거든...",
            ["DialogueId"] = 51005804,
            ["GUID"] = "7FB00BB8",
            ["NextDialogue"] = 51005805,
            ["Scripts"] = "LookAt{_delay{2},LookAtDescription{\"700123:n(700124)\"}}",
            ["SpeakNpcId"] = 700124,
            ["TalkActionId"] = {
                [1] = "700124:Talk01_Start",
                },
            },
        [51005805] = {
            ["Content"] = "（二哥话还没说完就被大哥捂住嘴打了一拳。）",
            ["ContentKR"] = "(둘째의 말이 끝나기도 전에 첫째가 입을 틀어막고 한대 때린다.)",
            ["DialogueId"] = 51005805,
            ["GUID"] = "7FB00BE2",
            ["IsBlack"] = 1,
            ["LookAt"] = {
                [1] = "700123:n(700124)",
                },
            ["NextDialogue"] = 51005806,
            ["TalkActionId"] = {
                [1] = "700124:Talk01_End",
                },
            ["TurnTo"] = {
                [1] = "700123:n(700124)",
                },
            },
        [51005806] = {
            ["Camera"] = "-121.098236,-47.270508,134.38916,0.00009,-2.592344,127.106155,35.000011,1.5,false,Disable,1.2",
            ["Content"] = "爽……",
            ["ContentKR"] = "아...",
            ["DialogueId"] = 51005806,
            ["GUID"] = "7FB00C0C",
            ["NextDialogue"] = 51005807,
            ["SpeakNpcId"] = 700124,
            },
        [51005807] = {
            ["Camera"] = "-121.098236,-47.270508,134.38916,0.00009,-2.592344,127.106155,35.000011,1.5,false,Disable,1.2",
            ["Content"] = "哼，你再仔细看看！",
            ["ContentKR"] = "흥, 자세히 봐!",
            ["DialogueId"] = 51005807,
            ["GUID"] = "7FB00C36",
            ["LookAt"] = {
                [1] = "700123:n(100001)",
