                [3] = "700124:Onground02",
                [4] = "700125:Onground01_Loop",
                },
            },
        [51005902] = {
            ["Content"] = "我是死人，我是死人，我是死人……",
            ["ContentKR"] = "난 죽은 사람이다, 죽은 사람이다, 죽은 사람이다...",
            ["DialogueId"] = 51005902,
            ["GUID"] = "7FB01BCC",
            ["NextDialogue"] = 51005903,
            ["SpeakNpcId"] = 700124,
            },
        [51005903] = {
            ["Camera"] = "-31.010925,345.116211,221.408691,0.000395,-17.802675,-135.255722,70.0,1.5,false,Disable,1.2",
            ["Content"] = "你……你把我大哥二哥打死了……你、你赔我钱！！",
            ["ContentKR"] = "가... 감히 우리 형들을 죽이다니... 보, 보상해라!!",
            ["DialogueId"] = 51005903,
            ["FinalCamera"] = "-31.011719,345.116211,173.425293,0.000394,-17.802668,-135.255737,70.0,1.5,false,Disable,1.2",
            ["GUID"] = "7FB01BF6",
            ["LookAt"] = {
                [1] = "100001:n(700125)",
                },
            ["NextDialogue"] = 51005904,
            ["SpeakNpcId"] = 700125,
            ["ToFinalCameraBlendTime"] = 12,
            },
        [51005904] = {
            ["Content"] = "（二哥无论你怎么打都死死抱着箱子，三哥则抱着你的大腿不让你离开，显然是讹定你了。）",
            ["ContentKR"] = "(둘째는 맞으면서도 상자를 꼭 끌어안고 있었다. 셋째는 내가 떠나지 못하도록 다리를 붙잡았다. 분명 날 속이려고 하는 것이다.)",
            ["DialogueId"] = 51005904,
            ["GUID"] = "7FB01C20",
            ["TalkOptions"] = {
                [1] = 510059041,
                [2] = 510059042,
                },
            ["bForbidSkipOptions"] = true,
            },
        [51005905] = {
            ["Camera"] = "-506.111328,318.686523,121.462891,0.000001,-5.777739,-35.397011,28.0,1.5,false,Disable,1.2",
            ["Content"] = "哈哈哈哈复活！笨蛋笨蛋，知道我们帝国三兄弟的厉害了吧！",
            ["ContentKR"] = "하하하, 부활이다! 멍청한 자식, 제국 삼 형제의 위대함을 보았느냐!",
            ["DialogueId"] = 51005905,
            ["GUID"] = "7FB01C4A",
            ["NextDialogue"] = 51005906,
            ["SpeakNpcId"] = 700123,
            ["TalkActionId"] = {
                [1] = "700123:Confident_Start",
                },
            },
        [51005906] = {
            ["Content"] = "笨蛋，蛋……我饿了。",
            ["ContentKR"] = "바보, 멍청이, 해삼, 말미잘... 배고파졌어.",
            ["DialogueId"] = 51005906,
            ["GUID"] = "7FB01C74",
            ["NextDialogue"] = 51005907,
            ["SpeakNpcId"] = 700125,
            ["TalkActionId"] = {
                [1] = "700125:Sigh_Start",
                [2] = "700123:Confident_End",
                },
            },
        [51005907] = {
            ["Content"] = "把箱子抱走卖了钱就吃得起饭了，快走快走。",
            ["ContentKR"] = "상자를 가져다 팔면 음식을 사서 먹을 수 있어. 어서 가자.",
            ["DialogueId"] = 51005907,
            ["GUID"] = "7FB01C9E",
            ["NextDialogue"] = 51005908,
            ["SpeakNpcId"] = 700123,
            ["TurnTo"] = {
                [1] = "700123:p(180)",
                },
            },
        [51005908] = {
            ["Camera"] = "-405.640564,-14.355469,143.032715,0.000066,-10.778933,-143.991943,50.000008,1.5,false,Disable,1.2",
            ["Content"] = "人可以走，箱子放下。",
            ["ContentKR"] = "상자는 놓고 몸만 가도록.",
            ["DialogueId"] = 51005908,
            ["GUID"] = "7FB01CC8",
            ["NextDialogue"] = 51005912,
            ["SpeakNpcId"] = 700126,
            },
        [51005909] = {
            ["Content"] = "你打死了我两位兄弟，还踢我！哎哟，我胳膊被你踢断了，你赔钱！加倍！",
            ["ContentKR"] = "형들을 죽이고 나까지 발로 차다니! 아야! 너 때문에 팔이 부러졌어. 몇 배로 책임져!",
            ["DialogueId"] = 51005909,
            ["GUID"] = "7FB01CF2",
            ["IsBlack"] = 1,
            ["LookAt"] = {
                [1] = "100001:n(700125)",
                [2] = "700125:n(100001)",
                },
            ["NextDialogue"] = 51005910,
            ["SpeakNpcId"] = 700125,
            ["TalkActionId"] = {
                [1] = "100001:Talk03_Start",
                [2] = "700125:Onground01_Loop",
                },
            ["TurnTo"] = {
                [1] = "700123:p(180)",
                },
            },
        [51005910] = {
            ["Camera"] = "-237.173828,-25.819824,27.271973,0.000396,33.800621,119.541695,35.000008,1.5,false,Disable,1.2",
            ["Content"] = "（三哥依旧牢牢地抱着你的腿。）",
            ["ContentKR"] = "(셋째는 아직도 나의 다리를 꽉 붙잡고 있다.)",
            ["DialogueId"] = 51005910,
            ["GUID"] = "7FB01D1C",
            ["NextDialogue"] = 51005911,
            },
        [51005911] = {
            ["Camera"] = "-405.640564,-14.355469,143.032715,0.000066,-10.778933,-143.991943,50.000008,1.5,false,Disable,1.2",
            ["Content"] = "干什么呢这是？拿开你的爪子。",
            ["ContentKR"] = "뭐 하는 짓이야? 손 치워.",
            ["DialogueId"] = 51005911,
            ["GUID"] = "7FB01D46",
            ["NextDialogue"] = 51005912,
            ["SpeakNpcId"] = 700126,
            },
        [51005912] = {
            ["Camera"] = "-83.982361,289.22168,60.012695,0.000395,10.797306,-133.456161,70.000015,1.5,false,Disable,1.2",
            ["Content"] = "刚才我可全都看到了，箱子明明是{nickname}先捡到的。你们抢别人的东西不说，还在这儿敲诈。",
            ["ContentKR"] = "내가 봤는데 상자를 먼저 발견한 건 {nickname}, 이 녀석이야. 다른 사람의 물건을 빼앗은 데다가, 거짓말까지 하다니.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 51005912,
            ["GUID"] = "7FB01D70",
            ["NextDialogue"] = 51005913,
            ["Scripts"] = "PARA{\
MoveTo{ActorId{700126},TargetPoint{\"200216Aote1\"},MoveSpeed{90},Visibility{\"Show\"}},\
LookAt{_delay{2},LookAtDescription{\"100001:n(700126)\"}}\
}\
",
            ["SpeakNpcId"] = 700126,
            },
        [51005913] = {
            ["Content"] = "（奥特赛德向你使了一个眼色，似乎在示意“他来解决你的麻烦”。）",
            ["ContentKR"] = "(아웃사이더가 본인이 해결하겠다며 눈짓했다.)",
            ["DialogueId"] = 51005913,
            ["GUID"] = "7FB01D9A",
            ["LookAt"] = {
                [1] = "700126:n(100001)",
                },
            ["NextDialogue"] = 51005914,
            ["Scripts"] = "PARA{\
MoveTo{_delay{2},ActorId{700126},TargetPoint{\"200216Aote2\"},MoveSpeed{90},Visibility{\"Show\"}},\
LookAt{_delay{2},LookAtDescription{\"700126:n(700126)\"}}\
}",
            },
        [51005914] = {
            ["Camera"] = "-783.460938,-134.15332,202.978027,0.000408,-9.002374,17.755602,60.798176,1.5,false,Disable,1.2",
            ["Content"] = "谁说是你的了，这上面都写了人家的名了！",
            ["ContentKR"] = "여기 이름이 쓰여 있잖아. 대체 뭐가 네 거라는 거야?",
            ["DialogueId"] = 51005914,
            ["GUID"] = "7FB01DC4",
            ["LookAt"] = {
                [1] = "700123:n(700126)",
                },
            ["NextDialogue"] = 51005915,
            ["Scripts"] = "LookAt{_delay{1.1},LookAtDescription{\"700123:n(700126)\"}}",
            ["SpeakNpcId"] = 700124,
            ["TalkActionId"] = {
                [1] = "700124:Confident_Start",
                },
            ["TurnTo"] = {
                [1] = "700123:p(180)",
                },
            },
        [51005915] = {
            ["Content"] = "帝国三兄弟的宝贝，这写得还挺……狂野。",
            ["ContentKR"] = "제국 삼 형제의 보물이라. 아주... 거칠게도 써놨네.",
            ["DialogueId"] = 51005915,
            ["GUID"] = "7FB01DEE",
            ["LookAt"] = {
                [1] = "700126:n(700123)",
                },
            ["NextDialogue"] = 51005916,
            ["SpeakNpcId"] = 700126,
            },
        [51005916] = {
            ["Content"] = "漂亮吧，我用这支油笔练了好久呢。",
            ["ContentKR"] = "잘 썼지? 이 펜으로 내가 연습을 얼마나 많이 했는데.",
            ["DialogueId"] = 51005916,
            ["GUID"] = "7FB01E18",
            ["NextDialogue"] = 51005917,
            ["Scripts"] = "PlayAnimation{_delay{1.1},ActorId{700125},AnimationId{\"Confident_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 700125,
            },
        [51005917] = {
            ["Camera"] = "-86.712891,359.711426,133.382812,0.00039,-1.602663,-103.652168,62.179134,1.5,false,Disable,1.2",
            ["Content"] = "什么油笔这么好用，让我看看？",
            ["ContentKR"] = "얼마나 좋은 펜인지 좀 볼까?",
            ["DialogueId"] = 51005917,
            ["GUID"] = "7FB01E42",
            ["NextDialogue"] = 51005918,
            ["SpeakNpcId"] = 700126,
            ["TalkActionId"] = {
                [1] = "700126:Talk02_Start",
                },
            },
        [51005918] = {
            ["Content"] = "哼哼，冰湖城人都没什么见识嘛。喏，拿去给你开开眼。",
            ["ContentKR"] = "후후, 아이스레이크 시티 사람들은 보기 힘든 펜이야. 자, 한 번 보여주지.",
            ["DialogueId"] = 51005918,
            ["GUID"] = "7FB01E6C",
            ["NextDialogue"] = 51005919,
            ["SpeakNpcId"] = 700123,
            ["TalkActionId"] = {
                [1] = "700123:Give",
                },
            },
        [51005919] = {
            ["Content"] = "（奥特赛德接过笔后拿在手里转了几圈，然后在大哥背上写下了一行字。）",
            ["ContentKR"] = "(아웃사이더가 펜을 건네받은 후, 몇 번 빙글 돌리더니 첫째의 등에 무언가 써 내려간다.)",
            ["DialogueId"] = 51005919,
            ["GUID"] = "7FB01E96",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51005920,
            ["TalkActionId"] = {
                [1] = "700126:Talk02_End",
                [2] = "700124:Confident_End",
                },
            },
        [51005920] = {
            ["Content"] = "好了，按照你们的说法，从现在起，你们就是我奥特赛德的跟班了。",
            ["ContentKR"] = "좋아. 너희의 논리대로 지금부터 너희는 아웃사이더의 시종이다.",
            ["DialogueId"] = 51005920,
            ["GUID"] = "7FB01EC0",
            ["LookAt"] = {
                [1] = "700126:n(700123)",
                },
            ["NextDialogue"] = 51005921,
            ["SpeakNpcId"] = 700126,
            ["TalkActionId"] = {
                [1] = "700126:Talk03_Start",
                },
            },
        [51005921] = {
            ["Content"] = "嗯？啊？",
            ["ContentKR"] = "응? 뭐라고?",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 51005921,
            ["GUID"] = "7FB01EEA",
            ["NextDialogue"] = 51005922,
            ["SpeakNpcId"] = 700123,
            ["TalkActionId"] = {
                [1] = "700123:Sigh_Start",
                },
            },
        [51005922] = {
            ["Camera"] = "-317.345703,-158.464355,126.776367,0.000416,-0.602566,56.548306,62.738827,1.5,false,Disable,1.2",
            ["Content"] = "啊……大哥背上确实写着……“奥特赛德的跟班”。还、还真是……",
            ["ContentKR"] = "앗... 큰형 등에... '아웃사이더의 시종'이라고 쓰여 있어. 저, 정말...",
            ["DialogueId"] = 51005922,
            ["GUID"] = "7FB01F14",
            ["NextDialogue"] = 51005923,
            ["SpeakNpcId"] = 700125,
            },
        [51005923] = {
            ["Content"] = "既然大哥成了奥特赛德的跟班，咱们又是大哥的小弟，所以咱、咱们也是这个奥特赛德的……？",
            ["ContentKR"] = "우리는 큰형의 동생이고, 큰형은 아웃사이더의 시종이 됐으니까... 그럼, 우, 우리도 아웃사이더의...?",
            ["DialogueId"] = 51005923,
            ["GUID"] = "7FB01F3E",
            ["NextDialogue"] = 51005924,
            ["SpeakNpcId"] = 700125,
            },
        [51005924] = {
            ["Content"] = "好耶，人家是奥特赛德的跟班了。跟班是什么意思啊？",
            ["ContentKR"] = "오예! 아웃사이더의 시종이라니. 근데 시종이 뭐야?",
            ["DialogueId"] = 51005924,
            ["GUID"] = "7FB01F68",
            ["LookAt"] = {
                [1] = "700124:n(700125)",
                },
            ["NextDialogue"] = 51005925,
            ["SpeakNpcId"] = 700124,
            ["TalkActionId"] = {
                [1] = "700124:Confident_Start",
                },
            },
        [51005925] = {
            ["Content"] = "跟班就是……就是……",
            ["ContentKR"] = "시종은 그러니까... 바로...",
            ["DialogueId"] = 51005925,
            ["GUID"] = "7FB01F92",
            ["NextOptions"] = {
                [1] = 510059251,
                [2] = 510059252,
                [3] = 510059253,
                },
            ["SpeakNpcId"] = 700125,
            ["TalkActionId"] = {
                [1] = "700125:Think_Start",
                [2] = "700126:Talk03_End",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51005926] = {
            ["Camera"] = "-127.353516,-290.64502,141.182129,0.000389,-4.003146,93.954231,45.828033,1.5,false,Disable,1.2",
            ["Content"] = "哦哦，原来如此……还是不懂。",
            ["ContentKR"] = "오호, 그렇구나... 그래도 모르겠어.",
            ["DialogueId"] = 51005926,
            ["GUID"] = "7FB01FBC",
            ["LookAt"] = {
                [1] = "700123:n(700126)",
                [2] = "700124:n(700126)",
                [3] = "700125:n(700126)",
                },
            ["NextDialogue"] = 51005927,
            ["Scripts"] = "PlayAnimation{_delay{2},ActorId{700124},AnimationId{\"Disagree\"},Duration{0.1}}",
            ["SpeakNpcId"] = 700124,
            ["TalkActionId"] = {
                [1] = "700124:Agree",
                },
            },
        [51005927] = {
            ["Content"] = "跟班就是你们听我的话，我就不会亏待你们，以后有我和{nickname}一口肉吃，就少不了你们一口汤喝。",
            ["ContentKR"] = "시종은 내 말을 들으면 손해 보지 않는 사람이라는 뜻이야. 나와 {nickname}, 이 녀석이 맛있는 걸 먹으면 너희도 콩고물을 먹을 수 있다는 뜻이지.",
            ["DialogueId"] = 51005927,
            ["GUID"] = "7FB01FE6",
            ["NextDialogue"] = 51005928,
            ["SpeakNpcId"] = 700126,
            ["TalkActionId"] = {
                [1] = "700126:Talk01_Start",
                },
            },
        [51005928] = {
            ["Camera"] = "-397.066406,36.696777,151.856934,0.000385,-6.203246,11.162275,50.000008,1.5,false,Disable,1.2",
            ["Content"] = "听起来很不赖啊！以后我们管你们叫大大哥，你们叫我们大哥二哥三哥就好，咱们各论各的，二哥三哥，来。",
            ["ContentKR"] = "괜찮은데? 그럼 이제부터 왕형님이라고 부를게. 우리는 첫째, 둘째, 셋째라고 부르면 돼. 자, 그럼 둘째, 셋째...",
            ["DialogueId"] = 51005928,
            ["GUID"] = "7FB02010",
            ["NextDialogue"] = 51005929,
            ["Scripts"] = "PlayAnimation{_delay{2},ActorId{700123},AnimationId{\"Confident_End\"},Duration{0.1}}",
            ["SpeakNpcId"] = 700123,
            ["TalkActionId"] = {
                [1] = "700123:Confident_Start",
                },
            },
        [51005929] = {
            ["Content"] = "大大哥们好！",
            ["ContentKR"] = "왕형님들 최고!",
            ["DialogueId"] = 51005929,
            ["GUID"] = "7FB0203A",
            ["NextDialogue"] = 51005930,
            ["SpeakNpcName"] = "UI_CMNpc_Name_SanXiongdi",
            ["TalkActionId"] = {
                [1] = "700123:Agree",
                [2] = "700124:Agree",
                [3] = "700125:Agree",
                },
            },
        [51005930] = {
            ["Content"] = "行了行了，先说说看，为什么非得抢箱子。",
            ["ContentKR"] = "됐어. 일단 상자를 뺏으려고 했던 이유부터 얘기해 봐.",
            ["DialogueId"] = 51005930,
            ["GUID"] = "7FB02064",
            ["NextDialogue"] = 51005931,
            ["SpeakNpcId"] = 700126,
            ["TalkActionId"] = {
                [1] = "700126:Talk03_End",
                },
            },
        [51005931] = {
            ["Camera"] = "-691.196594,-40.563477,185.212402,0.000427,-10.603089,11.55783,35.0,1.5,false,Disable,1.2",
            ["Content"] = "我们是从丹流城过来讨生活的。谁知道这一路又是秽兽又是雪狼，甚至还有神弃者同盟跟军团打架的。但是，咱们也得吃饭的嘛，所以……",
            ["ContentKR"] = "우리는 이곳에 살려고 스칼렛에서 왔어. 오는 길 내내 필토이드와 스노우 울프가 도사리고 있을 거라고는 생각도 못 했지. 아, 심지어 군단과 싸우는 포세이큰 동맹도 있었어. 그렇지만 우리도 먹고 살아야 되잖아, 그래서...",
            ["DialogueId"] = 51005931,
            ["FinalCamera"] = "-688.296509,-54.745117,185.212402,0.000428,-10.603083,11.557263,35.0,1.5,false,Disable,1.2",
            ["GUID"] = "7FB0208E",
            ["NextDialogue"] = 51005932,
            ["SpeakNpcId"] = 700123,
            ["TalkActionId"] = {
                [1] = "700123:Talk02_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            },
        [51005932] = {
            ["Content"] = "那么远的地方你们怎么来的。",
            ["ContentKR"] = "그렇게 먼 곳에서 어떻게 온 거야?",
            ["DialogueId"] = 51005932,
            ["GUID"] = "7FB020B8",
            ["NextDialogue"] = 51005933,
            ["SpeakNpcId"] = 700126,
            },
        [51005933] = {
            ["Content"] = "那点路当然是用脚走过来的啦！",
            ["ContentKR"] = "당연히 두 발로 걸어왔지!",
            ["DialogueId"] = 51005933,
            ["GUID"] = "7FB020E2",
            ["NextDialogue"] = 51005934,
            ["SpeakNpcId"] = 700124,
            ["TalkActionId"] = {
                [1] = "700124:Talk01_Start",
                },
            },
        [51005934] = {
            ["Content"] = "那你们还……挺有毅力的。",
            ["ContentKR"] = "그렇다면... 정신력이 대단하군.",
            ["DialogueId"] = 51005934,
            ["GUID"] = "7FB0210C",
            ["NextDialogue"] = 51005935,
            ["SpeakNpcId"] = 700126,
            ["TalkActionId"] = {
                [1] = "700126:Agree",
                },
            },
        [51005935] = {
            ["Camera"] = "-415.045776,25.477539,88.027344,0.000006,12.016644,20.329792,35.000008,1.5,false,Disable,1.2",
            ["Content"] = "走过来是个什么概念？",
            ["ContentKR"] = "걸어왔다는 데 뭔가 특별한 거라도 있는 거야?",
            ["DialogueId"] = 51005935,
            ["GUID"] = "7FB02136",
            ["LookAt"] = {
                [1] = "700126:n(100001)",
                },
            ["NextDialogue"] = 51005936,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700124:Talk01_End",
                },
            },
        [51005936] = {
            ["Content"] = "没个半年走不过来，脑子正常的人都不会这么干。",
            ["ContentKR"] = "쉽게 걸어올 거리가 아니야. 정상인이라면 그렇게 안 하지.",
            ["DialogueId"] = 51005936,
            ["GUID"] = "7FB02160",
            ["NextDialogue"] = 51005937,
            ["SpeakNpcId"] = 700126,
            ["TalkActionId"] = {
                [1] = "700126:Talk01_Start",
                },
            },
        [51005937] = {
            ["Camera"] = "94.544922,-72.209961,230.001465,0.000072,-21.18392,156.51619,41.357956,1.5,false,Disable,1.2",
            ["Content"] = "咳咳，我作为大大哥，一向是很厚道的。你们把箱子还给{nickname}，再帮我跑几个腿，我就宽宏大量，不和你们计较了。",
            ["ContentKR"] = "흠흠, 왕형님으로서 나는 한없이 너그러운 사람이다. 상자를 {nickname}에게 돌려주고, 나의 심부름을 하면 아량을 베풀겠다.",
            ["DialogueId"] = 51005937,
            ["GUID"] = "7FB0218A",
            ["LookAt"] = {
                [1] = "700126:n(700123)",
                },
            ["NextOptions"] = {
                [1] = 510059371,
                [2] = 510059372,
                },
            ["SpeakNpcId"] = 700126,
            ["TalkActionId"] = {
                [1] = "700126:Talk01_End",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51005938] = {
            ["Camera"] = "-80.927734,-14.502441,185.629883,0.000013,-16.983728,145.126053,40.0,1.5,false,Disable,1.2",
            ["Content"] = "这不得给你找回场子嘛。再说了，这可不是欺负，他们还得谢谢咱们呢。",
            ["ContentKR"] = "지금 네 몫을 되찾는 것뿐이야. 그리고 이건 괴롭히는 게 아니라고. 오히려 우리한테 고마워해야지.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 51005938,
            ["GUID"] = "7FB021B4",
            ["LookAt"] = {
                [1] = "700126:n(100001)",
                },
            ["NextDialogue"] = 51005940,
            ["Scripts"] = "PlayAnimation{_delay{2},ActorId{700126},AnimationId{\"Confident_End\"},Duration{0.1}}",
            ["SpeakNpcId"] = 700126,
            ["TalkActionId"] = {
                [1] = "700126:Confident_Start",
                },
            },
        [51005939] = {
            ["Camera"] = "-497.850647,19.27832,106.201172,0.000021,-0.383638,8.526095,35.000008,1.5,false,Disable,1.2",
            ["Content"] = "啊？没有了，真的没有了！我们的兜比你的脸还干净！",
            ["ContentKR"] = "아? 아니, 정말 한 푼도 없어! 털어도 먼지 밖에 안 나온다고!",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 51005939,
            ["GUID"] = "7FB021DE",
            ["NextDialogue"] = 51005940,
            ["SpeakNpcId"] = 700123,
            ["TalkActionId"] = {
                [1] = "700123:Disagree",
                },
            },
        [51005940] = {
            ["Camera"] = "97.474609,-59.709961,145.413574,0.000075,-3.983646,159.516525,41.357956,1.5,false,Disable,1.2",
            ["Content"] = "好吧，那就下次再说。",
            ["ContentKR"] = "좋아. 그럼 그 얘기는 다음에 다시 하지.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 51005940,
            ["GUID"] = "7FB02208",
            ["LookAt"] = {
                [1] = "700126:n(700123)",
                },
            ["NextDialogue"] = 51005941,
            ["SpeakNpcId"] = 700126,
            },
        [51005941] = {
            ["Content"] = "谢谢大大哥们！",
            ["ContentKR"] = "왕형님들, 고맙습니다!",
            ["DialogueId"] = 51005941,
            ["GUID"] = "7FB02232",
            ["NextDialogue"] = 51005942,
            ["SpeakNpcName"] = "UI_CMNpc_Name_SanXiongdi",
            ["TalkActionId"] = {
                [1] = "700123:Agree",
                [2] = "700124:Agree",
                [3] = "700125:Agree",
                },
            },
        [51005942] = {
            ["Camera"] = "-425.447266,140.77002,126.579102,0.000018,-1.584133,-13.274455,35.000011,1.5,false,Disable,1.2",
            ["Content"] = "你看。",
            ["ContentKR"] = "자, 봐.",
            ["DialogueId"] = 51005942,
            ["GUID"] = "7FB0225C",
            ["LookAt"] = {
                [1] = "700126:n(100001)",
