                },
            },
        [51005946] = {
            ["Content"] = "大大哥们好！",
            ["ContentKR"] = "왕형님들 최고!",
            ["DialogueId"] = 51005946,
            ["GUID"] = "7FB02304",
            ["LookAt"] = {
                [1] = "700130:n(0)",
