            ["Content"] = "就是就是！",
            ["ContentKR"] = "그러게 말이야!",
            ["DialogueId"] = 51006018,
            ["GUID"] = "7FB02ED4",
            ["LookAt"] = {
                [1] = "700145:n(100001)",
                [2] = "100001:n(700145)",
