                [1] = "700144:Agree",
                },
            },
        [51006020] = {
            ["Camera"] = "-81.742432,-73.919922,111.949219,0.000021,-10.600009,-24.396614,33.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "不——好——！你们这样下去，队伍一定会变成看板上倒数第一的！",
            ["ContentKR"] = "안—돼—! 그러다 우리 팀이 게시판 꼴찌 되는 거 아니야?",
            ["DialogueId"] = 51006020,
            ["GUID"] = "7FB02F28",
            ["LookAt"] = {
                [1] = "700145:n(100001)",
                [2] = "100001:n(700145)",
                [3] = "700144:n(700145)",
                },
            ["NextDialogue"] = 51006021,
            ["SpeakNpcId"] = 700144,
            ["TalkActionId"] = {
                [1] = "700144:Disagree",
                },
            },
        [51006021] = {
            ["Camera"] = "-29.963501,-92.201172,138.935547,0.000018,8.199928,169.801865,33.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "倒数第一不也会让人好奇——",
            ["ContentKR"] = "꼴찌도 나름 관심 끌 수 있지 않을까...",
            ["DialogueId"] = 51006021,
            ["GUID"] = "7FB02F52",
            ["NextDialogue"] = 51006022,
            ["SpeakNpcId"] = 700145,
            },
        [51006022] = {
            ["Camera"] = "-81.742432,-73.919922,111.949219,0.000021,-10.600009,-24.396614,33.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "停停停！",
            ["ContentKR"] = "그만, 그만!",
            ["DialogueId"] = 51006022,
            ["GUID"] = "7FB02F7C",
            ["NextDialogue"] = 51006023,
            ["SpeakNpcId"] = 700144,
