            ["Content"] = "就是，弱诶！",
            ["ContentKR"] = "맞아, 약해 빠졌어!",
            ["DialogueId"] = 51006715,
            ["GUID"] = "7FB0A12E",
            ["LookAt"] = {
                [1] = "700145:n(700146)",
                [2] = "700146:n(700145)",
