        [51006716] = {
            ["Camera"] = "73.404785,8.581055,112.754639,0.000019,13.999578,-134.799911,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你们……我不和你们较真！",
            ["ContentKR"] = "야, 너희들... 에이 됐다!",
            ["DialogueId"] = 51006716,
            ["GUID"] = "7FB0A158",
            ["NextDialogue"] = 51006717,
            ["SpeakNpcId"] = 700145,
            ["TalkActionId"] = {
                [1] = "700145:Disagree",
                },
            },
        [51006717] = {
            ["Camera"] = "70.664551,-61.835938,124.763184,0.000051,-13.200255,-30.598364,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那，我们回到一开始的话题，既然是{nickname}赢了，那小队名字还是由{性别：他|她}起好啦。",
            ["ContentKR"] = "자, 처음 주제로 돌아가자. {nickname}(이)가 이겼으니까 팀 이름은 {nickname}(이)가 정하는 거야.",
            ["DialogueId"] = 51006717,
            ["GUID"] = "7FB0A182",
            ["LookAt"] = {
                [1] = "700144:n(700145)",
                [2] = "700145:n(700144)",
                },
            ["NextDialogue"] = 51006718,
            ["SpeakNpcId"] = 700144,
            ["TalkActionId"] = {
                [1] = "700144:Confident_Start",
                },
            ["TurnTo"] = {
                [1] = "700144:n(700145)",
                [2] = "700145:n(700144)",
                },
            },
        [51006718] = {
            ["Camera"] = "73.404785,8.581055,112.754639,0.000019,13.999578,-134.799911,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "行吧，行吧，我没意见。",
            ["ContentKR"] = "알겠어, 알겠어. 난 뭐라 안 할게.",
            ["DialogueId"] = 51006718,
            ["GUID"] = "7FB0A1AC",
            ["NextDialogue"] = 51006719,
            ["SpeakNpcId"] = 700145,
            ["TalkActionId"] = {
                [1] = "700144:Confident_End",
                [2] = "700145:Agree",
                },
            },
        [51006719] = {
            ["Camera"] = "-318.093262,330.265869,317.277344,0.00005,-21.599884,-51.000023,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "不过，真的不考虑一下“食用昆虫研究队”这样让人看一眼后在半夜惊醒也会想到的如惊雷一般的好名字吗！",
            ["ContentKR"] = "그래도 '식용 곤충 연구팀' 같은 이름은 진짜 안 돼? 한번 들으면 밤에 깜짝 놀라 깨어날 정도로 충격적인 좋은 이름인데!",
            ["DialogueId"] = 51006719,
            ["GUID"] = "7FB0A1D6",
            ["NextDialogue"] = 51006720,
            ["SpeakNpcId"] = 700145,
            ["TalkActionId"] = {
                [1] = "700145:Think_Start",
                [2] = "100001:Sigh_Start",
                },
            },
        [51006720] = {
            ["Camera"] = "70.664551,-61.835938,124.763184,0.000051,-13.200255,-30.598364,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我不觉得！我还是觉得什么“光之魔王见习小队“这样的名字更能吸引人！",
            ["ContentKR"] = "안 돼! 차라리 '빛의 마왕 견습 팀' 같은 게 훨씬 더 눈길 끌 것 같아!",
            ["DialogueId"] = 51006720,
            ["GUID"] = "7FB0A200",
            ["NextDialogue"] = 51006721,
            ["SpeakNpcId"] = 700144,
            ["TalkActionId"] = {
                [1] = "700144:Disagree",
                },
            },
        [51006721] = {
            ["Camera"] = "73.404785,8.581055,112.754639,0.000019,13.999578,-134.799911,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那……“光之魔王的食用昆虫研究见习小队”？",
            ["ContentKR"] = "그럼... '빛의 마왕의 식용 곤충 연구 견습 팀'은 어때?",
            ["DialogueId"] = 51006721,
            ["GUID"] = "7FB0A22A",
            ["NextDialogue"] = 51006722,
            ["SpeakNpcId"] = 700145,
            ["TalkActionId"] = {
                [1] = "100001:Sigh_End",
                },
            },
        [51006722] = {
            ["Camera"] = "70.664551,-61.835938,124.763184,0.000051,-13.200255,-30.598364,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "唔……昆虫还是很显眼，那“真·纯白地狱之极光大魔王的昆虫研究见习小队”？",
