        [51007507] = {
            ["Content"] = "小朋友，你一个人待在这里不安全，我送你回家吧。",
            ["ContentKR"] = "꼬마야, 혼자 여기 이러고 있으면 위험해. 내가 집에 데려다줄게.",
            ["DialogueId"] = 51007507,
            ["GUID"] = "7FB1231E",
            ["NextDialogue"] = 51007508,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "0:Explain01_Start",
                },
            },
        [51007508] = {
            ["Content"] = "谢谢你，你人真好啊！不过我要先做完实验再回家。",
            ["ContentKR"] = "정말 친절하신 분이네요! 그런데 고맙지만, 전 실험부터 끝내고 집에 갈래요.",
            ["DialogueId"] = 51007508,
            ["GUID"] = "7FB12348",
            ["NextDialogue"] = 51007512,
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Agree",
                },
            },
        [51007509] = {
            ["Content"] = "（询问他说的实验是否能获取报酬。）",
            ["ContentKR"] = "(실험을 도와주면 보수를 받을 수 있는지 물어보자.)",
            ["DialogueId"] = 51007509,
            ["GUID"] = "7FB12372",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51007510,
            },
        [51007510] = {
            ["Content"] = "诶？啊……有，当然有！我的零花钱都可以给你。",
            ["ContentKR"] = "어? 아... 그럼요! 물론이죠! 제 용돈을 전부 다 드릴게요.",
            ["DialogueId"] = 51007510,
            ["GUID"] = "7FB1239C",
            ["NextDialogue"] = 51007512,
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Agree",
                },
            },
        [51007512] = {
            ["Content"] = "是这样的，我正在开展一项针对卡戎之民的实验调查，恭喜你被选中成为我的第一个实验对象！",
            ["ContentKR"] = "실은요. 제가 카론을 대상으로 실험이랑 조사를 진행 중인데, 제 첫 번째 실험 대상으로 선정되셨어요! 축하해요!",
            ["DialogueId"] = 51007512,
            ["GUID"] = "7FB123F0",
            ["NextDialogue"] = 51007513,
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Explain01_Start",
                },
            },
        [51007513] = {
            ["Content"] = "为什么选我？",
            ["ContentKR"] = "왜 날 뽑은 거야?",
            ["DialogueId"] = 51007513,
            ["GUID"] = "7FB1241A",
            ["NextDialogue"] = 51007514,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "0:Think_Start",
                },
            },
        [51007514] = {
            ["Content"] = "是随机抽选的哦，这样才能排除主观因素影响！",
            ["ContentKR"] = "아무나 뽑은 거예요! 그래야 주관적인 요소를 배제할 수 있거든요!",
            ["DialogueId"] = 51007514,
            ["GUID"] = "7FB12444",
            ["NextDialogue"] = 51007515,
            ["SpeakNpcId"] = 700011,
            },
        [51007515] = {
            ["Content"] = "咳咳，请先告诉我你的名字吧。",
            ["ContentKR"] = "크흠, 우선 이름부터 알려 주시겠어요?",
            ["DialogueId"] = 51007515,
            ["GUID"] = "7FB1246E",
            ["NextOptions"] = {
                [1] = 51007516,
                [2] = 51007519,
                },
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Explain01_End",
                },
            },
        [51007516] = {
            ["Content"] = "我叫诞生于净界岛·重生之焰·冰湖城守护者·光荣的·{nickname}。",
            ["ContentKR"] = "내 이름을 묻는다면, 난 연옥도에서 탄생한 부활의 화염이자 아이스레이크 시티의 영광스러운 수호자 {nickname}!",
            ["DialogueId"] = 51007516,
            ["GUID"] = "7FB12498",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51007517,
            ["Scripts"] = "SetTag{Tag{\"XiAoTag\"}, Value{\"Value_1\"}}",
            },
        [51007517] = {
            ["Content"] = "啊，请你说慢点……！那么，诞生于净界岛·重生……诞……蛋……",
            ["ContentKR"] = "앗, 조금 천천히 말해 주세요...! 그러니까, 연옥도에서 탄생한 부활의... 탄성... 탄...",
            ["DialogueId"] = 51007517,
            ["GUID"] = "7FB124C2",
            ["NextDialogue"] = 51007518,
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Talk01_Start",
                },
            },
        [51007518] = {
            ["Content"] = "呜，好难念！方便起见我就叫你{$XiAoTag(Value_1,Value_2)$|蛋蛋:西比尔}{性别：哥哥|姐姐}好了。",
            ["ContentKR"] = "으, 발음하기 너무 어려워요! 그냥 편하게 {$XiAoTag(Value_1,Value_2)$|탄이:시빌라} {性别:형|누나}라고 부를게요.",
            ["DialogueId"] = 51007518,
            ["GUID"] = "7FB124EC",
            ["NextDialogue"] = 51007522,
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Agree",
                },
            },
        [51007519] = {
            ["Content"] = "我叫西比尔。",
            ["ContentKR"] = "내 이름은 시빌라야.",
            ["DialogueId"] = 51007519,
            ["GUID"] = "7FB12516",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51007520,
            ["Scripts"] = "SetTag{Tag{\"XiAoTag\"}, Value{\"Value_2\"}}",
            },
        [51007520] = {
            ["Content"] = "总觉得这个名字有点耳熟，从哪里听过来着……",
            ["ContentKR"] = "뭔가 익숙한 이름이네요. 어디서 들어 본 거지...",
            ["DialogueId"] = 51007520,
            ["GUID"] = "7FB12540",
            ["NextDialogue"] = 51007521,
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Think_Start",
                },
            },
        [51007521] = {
            ["Content"] = "算了，不重要。{$XiAoTag(Value_1,Value_2)$|蛋蛋:西比尔}{性别：哥哥|姐姐}，我们开始吧。",
            ["ContentKR"] = "됐어요, 딱히 중요하진 않으니까요. 그럼 {$XiAoTag(Value_1,Value_2)$|탄이:시빌라} {性别:형|누나}, 시작하죠.",
            ["DialogueId"] = 51007521,
            ["GUID"] = "7FB1256A",
            ["NextDialogue"] = 51007522,
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Disagree",
                },
            },
        [51007522] = {
            ["Content"] = "放心，实验内容很简单，你只要填完这个调查问卷就行了！",
            ["ContentKR"] = "걱정하실 거 없어요. 실험 내용은 엄청 간단해요. 이 설문지만 다 작성해 주시면 되거든요!",
            ["DialogueId"] = 51007522,
            ["GUID"] = "7FB12594",
            ["NextDialogue"] = 51007523,
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Explain01_Start",
                },
            },
        [51007523] = {
            ["Content"] = "（男孩双手捧起一沓厚厚的纸递给了你。）",
            ["ContentKR"] = "(소년이 두 손에 든 두툼한 종이 뭉치를 건넨다.)",
            ["DialogueId"] = 51007523,
            ["GUID"] = "7FB125BE",
            ["NextDialogue"] = 51007524,
            },
        [51007524] = {
            ["Content"] = "（纸张的边缘并不整齐，似乎是从作业本上撕下来的；纸上是用稚嫩但工整的字体写下的一长串问题，序号甚至标到了三位数。）",
            ["ContentKR"] = "(종이는 공책에서 찢어 낸 것처럼 가장자리가 삐뚤삐뚤했고, 그 위에는 서툴지만 또박또박한 글씨체로 세 자릿수에 달하는 질문들이 적혀 있었다.)",
            ["DialogueId"] = 51007524,
            ["GUID"] = "7FB125E8",
            ["NextOptions"] = {
                [1] = 51007525,
                [2] = 51007527,
                [3] = 51007529,
                },
            },
        [51007525] = {
            ["Content"] = "你这问卷未免也太长了吧……",
            ["ContentKR"] = "이 설문지, 분량이 너무 많은 것 같은데...",
            ["DialogueId"] = 51007525,
            ["GUID"] = "7FB12612",
            ["NextDialogue"] = 51007526,
            },
        [51007526] = {
            ["Content"] = "也还好吧，只有七百七十七个问题哦！",
            ["ContentKR"] = "이 정도면 괜찮지 않아요? 문항도 딱 777개밖에 없어요!",
            ["DialogueId"] = 51007526,
            ["GUID"] = "7FB1263C",
            ["NextDialogue"] = 51007531,
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Explain01_Start",
                },
            },
        [51007527] = {
            ["Content"] = "这个长度的问卷要加钱。",
            ["ContentKR"] = "이렇게 많으면 돈을 더 받아야겠는데.",
            ["DialogueId"] = 51007527,
            ["GUID"] = "7FB12666",
            ["NextDialogue"] = 51007528,
            },
        [51007528] = {
            ["Content"] = "啊……可是我已经没有多的钱了……可以分期付款吗？",
            ["ContentKR"] = "앗... 더 드릴 돈이 없는데... 혹시 할부도 될까요?",
            ["DialogueId"] = 51007528,
            ["GUID"] = "7FB12690",
            ["NextDialogue"] = 51007531,
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Explain01_Start",
                },
            },
        [51007529] = {
            ["Content"] = "好的，我争取十年内填完。",
            ["ContentKR"] = "좋아, 열심히 써서 10년 안에는 줄게.",
            ["DialogueId"] = 51007529,
            ["GUID"] = "7FB126BA",
            ["NextDialogue"] = 51007530,
            },
        [51007530] = {
            ["Content"] = "咦？！那也太久了吧！",
            ["ContentKR"] = "어?! 10년은 너무 길어요!",
            ["DialogueId"] = 51007530,
            ["GUID"] = "7FB126E4",
            ["NextDialogue"] = 51007531,
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Explain01_Start",
                },
            },
        [51007531] = {
            ["Content"] = "拜托你答应我吧，冰湖城有这么多的卡戎，偏偏是你成为了我随机选中的那个观察目标，这可是天大的运气呢！",
            ["ContentKR"] = "제발요! 제 실험에 참여해 주세요! 아이스레이크 시티의 많고 많은 카론 중에 제 실험 대상으로 뽑혔단 건 엄청난 행운이라고요!",
            ["DialogueId"] = 51007531,
            ["GUID"] = "7FB1270E",
            ["NextDialogue"] = 51007532,
            ["SpeakNpcId"] = 700011,
            },
        [51007532] = {
            ["Content"] = "（此时，一个高大的卡戎之民从你们旁边路过，男孩的身影在一瞬间消失不见了。你转过头，发现他缩进了你身后的阴影里。）",
            ["ContentKR"] = "(바로 그때, 덩치 큰 카론 하나가 우리 곁을 지나갔고, 소년의 모습이 감쪽같이 사라졌다. 고개를 돌리자, 그는 어느새 내 등 뒤 그림자에 몸을 숨기고 있었다.)",
            ["DialogueId"] = 51007532,
            ["GUID"] = "7FB12738",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51007533,
            },
        [51007533] = {
            ["Content"] = "（高大的卡戎之民离开后，男孩又在一瞬间回到了原来的站立位置，仿佛什么都没发生过那样。）",
            ["ContentKR"] = "(덩치 큰 카론이 지나가고 나자, 소년은 방금 전의 일은 없었다는 듯이, 아무렇지도 않게 순식간에 원래 자리로 돌아왔다.)",
            ["DialogueId"] = 51007533,
            ["GUID"] = "7FB12762",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51007534,
            },
        [51007534] = {
            ["Content"] = "好不好嘛，{$XiAoTag(Value_1,Value_2)$|蛋蛋:西比尔}{性别：哥哥|姐姐}？",
            ["ContentKR"] = "어떻게 안 될까요, {$XiAoTag(Value_1,Value_2)$|탄이:시빌라} {性别:형|누나}?",
            ["DialogueId"] = 51007534,
            ["GUID"] = "7FB1278C",
            ["NextDialogue"] = 51007535,
            ["SpeakNpcId"] = 700011,
            },
        [51007535] = {
            ["Content"] = "你刚才是在害怕吗？",
            ["ContentKR"] = "아깐 무서워서 그랬던 거야?",
            ["DialogueId"] = 51007535,
            ["GUID"] = "7FB127B6",
            ["NextDialogue"] = 51007536,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "0:Explain01_Start",
                },
            },
        [51007536] = {
            ["Content"] = "才、才没有呢！我、我只是……担心不打招呼会显得不礼貌而已！",
            ["ContentKR"] = "아, 아니에요! 저, 전 그냥... 인사를 안 하면 예의 없어 보일까 봐 걱정됐던 거예요!",
            ["DialogueId"] = 51007536,
            ["GUID"] = "7FB127E0",
            ["NextDialogue"] = 51007537,
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Disagree",
                },
            },
        [51007537] = {
            ["Content"] = "研究者不能撒谎。",
            ["ContentKR"] = "연구자는 거짓말하면 못써.",
            ["DialogueId"] = 51007537,
            ["GUID"] = "7FB1280A",
            ["NextDialogue"] = 51007538,
            ["SpeakNpcId"] = 100001,
            },
        [51007538] = {
            ["Content"] = "呃……可、可能是有一点点点点害怕……总之，这些小事不重要啦！",
            ["ContentKR"] = "으... 어, 어쩌면 쪼오오오오금은 무서웠을지도요... 아무튼, 이런 사소한 건 중요하지 않아요!",
            ["DialogueId"] = 51007538,
            ["GUID"] = "7FB12834",
            ["NextDialogue"] = 51007539,
            ["SpeakNpcId"] = 700011,
            },
        [51007539] = {
            ["Content"] = "刚才说到哪儿了……噢，对了，问卷！如果你实在不愿意填的话，我就挑几个重要的问题问吧，你只要口头回答就行了！",
            ["ContentKR"] = "아까 어디까지 얘기했었죠...? 아, 맞다, 설문지! 도저히 작성하기 싫다면, 제가 중요한 질문 몇 개만 골라서 물어볼 테니까, 대답만 해 주시면 돼요!",
            ["DialogueId"] = 51007539,
            ["GUID"] = "7FB1285E",
            ["NextDialogue"] = 51007540,
            ["SpeakNpcId"] = 700011,
            },
        [51007540] = {
            ["Content"] = "如果你现在有空的话，我们就立刻开始问答吧？",
            ["ContentKR"] = "괜찮으시면, 지금 바로 질문을 드려도 될까요?",
            ["DialogueId"] = 51007540,
            ["GUID"] = "7FB12888",
            ["SpeakNpcId"] = 700011,
            },
        [51007543] = {
            ["Content"] = "好耶！那就听好咯——",
            ["ContentKR"] = "좋아요! 그러면 잘 듣고 대답해 주세요...",
            ["DialogueId"] = 51007543,
            ["GUID"] = "7FB12906",
            ["NextDialogue"] = 51007544,
            ["SpeakNpcId"] = 700011,
            },
        [51007544] = {
            ["Content"] = "问题1：你为什么只有一只角？",
            ["ContentKR"] = "첫 번째 질문이에요. 왜 뿔이 한쪽밖에 없어요?",
            ["DialogueId"] = 51007544,
            ["GUID"] = "7FB12930",
            ["NextOptions"] = {
                [1] = 51007545,
                [2] = 51007547,
                [3] = 51007550,
                },
            ["SpeakNpcId"] = 700011,
            },
        [51007545] = {
            ["Content"] = "生来就是这样。",
            ["ContentKR"] = "태어날 때부터 이랬어.",
            ["DialogueId"] = 51007545,
            ["GUID"] = "7FB1295A",
            ["NextDialogue"] = 51007546,
            },
        [51007546] = {
            ["Content"] = "噢，所以是先天的差异……",
            ["ContentKR"] = "음, 선천적인 거란 얘기네요...",
            ["DialogueId"] = 51007546,
            ["GUID"] = "7FB12984",
            ["NextDialogue"] = 51007553,
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Agree",
                },
            },
        [51007547] = {
            ["Content"] = "另一只被我卖掉换钱了。",
            ["ContentKR"] = "다른 한쪽은 팔아서 돈으로 바꿨거든.",
            ["DialogueId"] = 51007547,
            ["GUID"] = "7FB129AE",
            ["NextDialogue"] = 51007548,
            },
        [51007548] = {
            ["Content"] = "咦，还能这样？！",
            ["ContentKR"] = "어? 팔기도 하나 봐요?!",
            ["DialogueId"] = 51007548,
            ["GUID"] = "7FB129D8",
            ["NextDialogue"] = 51007549,
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Shock_Start",
                },
            },
        [51007549] = {
            ["Content"] = "好想买一个用来研究啊……",
            ["ContentKR"] = "저도 하나 사서 연구해 보고 싶네요...",
            ["DialogueId"] = 51007549,
            ["GUID"] = "7FB12A02",
            ["NextDialogue"] = 51007553,
            ["SpeakNpcId"] = 700011,
            },
        [51007550] = {
            ["Content"] = "只有聪明的孩子才能看到另一只。",
            ["ContentKR"] = "다른 한쪽은 똑똑한 아이 눈에만 보이는 거야.",
            ["DialogueId"] = 51007550,
            ["GUID"] = "7FB12A2C",
            ["NextDialogue"] = 51007551,
            },
        [51007551] = {
            ["Content"] = "……我才不会信这种骗小孩的话呢。",
            ["ContentKR"] = "...그런 유치한 말은 안 믿어요.",
            ["DialogueId"] = 51007551,
            ["GUID"] = "7FB12A56",
            ["NextDialogue"] = 51007552,
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Disagree",
                },
            },
        [51007552] = {
            ["Content"] = "不过，原来卡戎也会开玩笑啊……",
            ["ContentKR"] = "그런데, 카론도 농담을 할 줄 아는군요...",
            ["DialogueId"] = 51007552,
            ["GUID"] = "7FB12A80",
            ["NextDialogue"] = 51007553,
            ["SpeakNpcId"] = 700011,
            },
        [51007553] = {
            ["Content"] = "嗯……下面是问题2：你的角摸起来是什么感觉，可以切一片给我摸摸吗？",
            ["ContentKR"] = "음... 다음은 두 번째 질문이에요. 뿔은 만지면 어떤 느낌인가요? 조금만 잘라서 만져 보게 해 줄 수 있나요?",
            ["DialogueId"] = 51007553,
            ["GUID"] = "7FB12AAA",
            ["NextOptions"] = {
                [1] = 51007554,
                [2] = 51007556,
                [3] = 51007558,
                },
            ["SpeakNpcId"] = 700011,
            },
        [51007554] = {
            ["Content"] = "会痛，不可以。",
            ["ContentKR"] = "아프니까 안 돼.",
            ["DialogueId"] = 51007554,
            ["GUID"] = "7FB12AD4",
            ["NextDialogue"] = 51007555,
            },
        [51007555] = {
            ["Content"] = "对不起！……不过，原来恶魔的孩子也会感到痛吗，好像和爸爸说的不太一样……",
            ["ContentKR"] = "미안해요! ...그런데 악마의 아이도 아픔을 느끼는 거예요? 아빠가 말씀하셨던 거랑 좀 다른걸요...",
            ["DialogueId"] = 51007555,
            ["GUID"] = "7FB12AFE",
            ["NextDialogue"] = 51007562,
            ["SpeakNpcId"] = 700011,
            },
        [51007556] = {
            ["Content"] = "一片三万银币。",
            ["ContentKR"] = "한 조각에 3만 실버야.",
            ["DialogueId"] = 51007556,
            ["GUID"] = "7FB12B28",
            ["NextDialogue"] = 51007557,
            },
        [51007557] = {
            ["Content"] = "诶诶诶——？那、那就算了吧……",
            ["ContentKR"] = "어?!!! 그, 그럼 됐어요...",
            ["DialogueId"] = 51007557,
            ["GUID"] = "7FB12B52",
            ["NextDialogue"] = 51007562,
            ["SpeakNpcId"] = 700011,
            },
        [51007558] = {
            ["Content"] = "摸了会中毒哦。",
            ["ContentKR"] = "만졌다간 몸에 독이 퍼질걸.",
            ["DialogueId"] = 51007558,
            ["GUID"] = "7FB12B7C",
            ["NextDialogue"] = 51007559,
            },
        [51007559] = {
            ["Content"] = "真的吗？毒性有多大呢？有解毒的方法吗？你自己也会中毒吗？",
            ["ContentKR"] = "정말요? 독성은 어느 정도예요? 해독할 방법은 있나요? 혹시 본인도 중독돼요?",
            ["DialogueId"] = 51007559,
            ["GUID"] = "7FB12BA6",
            ["NextDialogue"] = 51007560,
            ["SpeakNpcId"] = 700011,
            },
        [51007560] = {
            ["Content"] = "……没毒，只是开个玩笑。但是受伤会痛，所以不可以切。",
            ["ContentKR"] = "...독 없어. 그냥 농담한 거야. 그래도 다치면 아프니까, 잘라 줄 순 없어.",
            ["DialogueId"] = 51007560,
            ["GUID"] = "7FB12BD0",
            ["NextDialogue"] = 51007561,
            ["SpeakNpcId"] = 100001,
            },
        [51007561] = {
            ["Content"] = "对不起！……不过，原来恶魔的孩子也会感到痛吗，好像和爸爸说的不太一样……",
            ["ContentKR"] = "미안해요! ...그런데 악마의 아이도 아픔을 느끼는 거예요? 아빠가 말씀하셨던 거랑 좀 다른걸요...",
            ["DialogueId"] = 51007561,
            ["GUID"] = "7FB12BFA",
            ["NextDialogue"] = 51007562,
            ["SpeakNpcId"] = 700011,
            },
        [51007562] = {
            ["Content"] = "既然你们是恶魔的孩子，那你的爸爸妈妈长什么样啊，是不是超凶的那种……可以把人一口吞掉？",
            ["ContentKR"] = "엄마, 아빠는 어떻게 생겼어요? 카론들은 악마의 아이라던데... 사람을 한입에 꿀꺽 삼킬 수 있을 정도로 무시무시한가요?",
            ["DialogueId"] = 51007562,
            ["GUID"] = "7FB12C24",
            ["NextOptions"] = {
                [1] = 51007563,
                [2] = 51007565,
                [3] = 51007567,
                },
            ["SpeakNpcId"] = 700011,
            },
        [51007563] = {
            ["Content"] = "应该只是普普通通的卡戎吧。",
            ["ContentKR"] = "그냥 평범한 카론일 거야.",
            ["DialogueId"] = 51007563,
            ["GUID"] = "7FB12C4E",
            ["NextDialogue"] = 51007564,
            },
        [51007564] = {
            ["Content"] = "这样啊……没劲。",
            ["ContentKR"] = "그런가요... 의욕이 떨어지네요.",
            ["DialogueId"] = 51007564,
            ["GUID"] = "7FB12C78",
            ["NextDialogue"] = 51007569,
            ["SpeakNpcId"] = 700011,
            },
        [51007565] = {
            ["Content"] = "不知道，我没见过他们。",
            ["ContentKR"] = "몰라. 본 적이 없거든.",
            ["DialogueId"] = 51007565,
            ["GUID"] = "7FB12CA2",
            ["NextDialogue"] = 51007566,
            },
        [51007566] = {
            ["Content"] = "“亲眼见过才能给出答案”——看来你也很有研究者的天赋嘛！",
            ["ContentKR"] = "'직접 보지 못한 건 대답할 수 없다'는 거군요! 연구자 쪽으로 엄청난 자질이 있는걸요!",
            ["DialogueId"] = 51007566,
            ["GUID"] = "7FB12CCC",
            ["NextDialogue"] = 51007569,
            ["SpeakNpcId"] = 700011,
            },
        [51007567] = {
            ["Content"] = "是精灵。",
            ["ContentKR"] = "요정이야.",
            ["DialogueId"] = 51007567,
            ["GUID"] = "7FB12CF6",
            ["NextDialogue"] = 51007568,
            },
        [51007568] = {
            ["Content"] = "哎，和我之前见过的哥哥说的一样！",
            ["ContentKR"] = "앗, 전에 만났던 형도 똑같은 대답을 했었어요!",
            ["DialogueId"] = 51007568,
            ["GUID"] = "7FB12D20",
            ["NextDialogue"] = 51007569,
            ["SpeakNpcId"] = 700011,
            },
        [51007569] = {
            ["Content"] = "几年前我遇到过一个很友善的卡戎哥哥，他对我说自己是“精灵”。",
            ["ContentKR"] = "몇 년 전에, 자기가 '요정'이라는 엄청나게 친절한 카론 형을 만났어요.",
            ["DialogueId"] = 51007569,
            ["GUID"] = "7FB12D4A",
            ["NextDialogue"] = 51007570,
            ["SpeakNpcId"] = 700011,
            },
        [51007570] = {
            ["Content"] = "他当时急着去见什么人，我就没来得及细问……",
            ["ContentKR"] = "마침 그 형은 급하게 누굴 만나러 가던 중이라, 자세히 물어볼 순 없었지만...",
            ["DialogueId"] = 51007570,
            ["GUID"] = "7FB12D74",
            ["NextDialogue"] = 51007571,
            ["SpeakNpcId"] = 700011,
            },
        [51007571] = {
            ["Content"] = "但关于卡戎的来源，他是第一个给我不同回答的人，所以我一直很在意。可惜后来我再也没见到他了。",
            ["ContentKR"] = "카론의 기원에 대해 색다른 대답을 해 준 건 그 형이 처음이라 아직 기억에 남아요. 그날 이후로 다시는 못 만나서 좀 아쉽네요.",
            ["DialogueId"] = 51007571,
            ["GUID"] = "7FB12D9E",
            ["NextDialogue"] = 51007576,
            ["NextOptions"] = {
                [1] = 51007572,
                [2] = 51007574,
                },
            ["SpeakNpcId"] = 700011,
            },
        [51007572] = {
            ["Content"] = "他确实是精灵。",
            ["ContentKR"] = "그 사람 진짜 요정 맞아.",
            ["DialogueId"] = 51007572,
            ["GUID"] = "7FB12DC8",
            ["NextDialogue"] = 51007573,
            ["TriggerCondition"] = {
                ["ImprComp"] = {
                    ["TalkTriggerId"] = 500080,
                    },
                },
