        [51007573] = {
            ["Content"] = "嗯，既然你也这么说，那应该就是了吧！",
            ["ContentKR"] = "음, 그렇게까지 말하는 걸 보면, 정말 그런가 보네요!",
            ["DialogueId"] = 51007573,
            ["GUID"] = "7FB12DF2",
            ["NextDialogue"] = 51007576,
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Agree",
                },
            },
        [51007574] = {
