            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Agree",
                },
            },
        [51007576] = {
            ["Content"] = "唔……总而言之，大家对问题3的答案都不太一样，看来我还需要收集更多的样本。",
            ["ContentKR"] = "음... 아무튼, 세 번째 질문에 대한 대답은 다들 다르네요. 아무래도 더 많은 샘플을 모아야 할 것 같아요.",
            ["DialogueId"] = 51007576,
            ["GUID"] = "7FB12E70",
