            ["GUID"] = "7FB12F96",
            ["SpeakNpcId"] = 700011,
            },
        [51007601] = {
            ["Content"] = "老鼠们去哪儿了呢……",
            ["ContentKR"] = "쥐들이 다 어디 간 걸까...",
            ["DialogueId"] = 51007601,
