            ["SpeakNpcId"] = 700204,
            ["TalkActionId"] = {
                [1] = "700204:Think_Start",
                },
            },
        [51007602] = {
            ["Content"] = "（男孩伸长了脖子，好奇地打量着下水道入口。）",
            ["ContentKR"] = "(소년은 목을 길게 빼고, 호기심 가득한 눈으로 하수도 입구를 살피고 있다.)",
