            ["SpeakNpcId"] = 700204,
            ["TalkActionId"] = {
                [1] = "700204:Agree",
                },
            },
        [51007689] = {
            ["Content"] = "（不远处忽然传来了一阵急促的脚步声，一位打扮得体的女士怒气冲冲地朝你们走来。）",
            ["ContentKR"] = "(근처에서 갑자기 다급한 발소리가 들려오더니, 반듯하게 차려입은 한 여성이 우리를 향해 씩씩거리며 다가왔다.)",
            ["DialogueId"] = 51007689,
            ["GUID"] = "7FB140FA",
            ["IsBlack"] = 1,
            },
        [51007690] = {
            ["Camera"] = "524.909058,-5.945312,503.180176,0.00013,-34.597534,178.391556,22.109655,100000.0,false,Manual,22.0",
            ["Content"] = "西奥，你又跑到哪里去了？天呐，瞧瞧你，怎么把衣服弄得这么脏！",
            ["ContentKR"] = "테오! 너 또 어디 갔었니? 세상에, 꼴이 이게 뭐야. 옷이 왜 이렇게 더러워졌어!",
            ["DefaultLookAt"] = "1.0",
