        [51009111] = {
            ["Camera"] = "-109.266235,212.040771,142.030579,0.000303,-12.201387,-63.418461,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哇——铁匠前辈，好厉害！",
            ["ContentKR"] = "우와! 대장장이 할아버지, 진짜 엄청나!",
            ["DialogueId"] = 51009111,
            ["FacialId"] = {
                [1] = "230001:Smile02",
                },
            ["GUID"] = "7FB22A46",
            ["NextOptions"] = {
                [1] = 510091111,
                [2] = 510091112,
                },
            ["SpeakNpcId"] = 230001,
            ["TalkActionId"] = {
                [1] = "230001:Shock03_Start",
                },
            },
        [51009112] = {
            ["Camera"] = "-98.319763,-208.091797,193.145508,0.000145,-22.401394,63.002728,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "放心吧，这次是特别服务。",
            ["ContentKR"] = "이번엔 특별 서비스일세. 걱정 말게나.",
            ["DialogueId"] = 51009112,
            ["GUID"] = "7FB22A70",
            ["LookAt"] = {
                [1] = "230002:n(100001)",
                },
            ["NextDialogue"] = 51009114,
            ["SpeakNpcId"] = 230002,
            ["TalkActionId"] = {
                [1] = "230001:Shock03_End",
                },
            },
        [51009113] = {
            ["Camera"] = "-98.319763,-208.091797,193.145508,0.000145,-22.401394,63.002728,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "当然，这就是专门为你打造的。",
            ["ContentKR"] = "써 봐도 되고말고. 자네를 위해 특별히 만들었다네.",
            ["DialogueId"] = 51009113,
            ["GUID"] = "7FB22A9A",
            ["LookAt"] = {
                [1] = "230002:n(100001)",
                },
            ["NextDialogue"] = 51009114,
            ["SpeakNpcId"] = 100001,
            },
        [51009114] = {
            ["Camera"] = "-24.090881,-40.348145,106.749283,0.00021,-8.600826,75.590508,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "虽然还比不上你原本的剑，但也算是老朽的得意之作了。",
            ["ContentKR"] = "자네가 원래 사용하던 검엔 미치지 못하겠지만, 그래도 나름 이 늙은이의 회심작일세.",
            ["DialogueId"] = 51009114,
            ["FacialId"] = {
                [1] = "230002:Confident02",
                },
            ["GUID"] = "7FB22AC4",
            ["NextDialogue"] = 51009115,
            ["SpeakNpcId"] = 230002,
            },
        [51009115] = {
            ["Camera"] = "-45.129822,68.886719,129.014465,0.000222,1.198575,-71.808838,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "谢谢前辈，不过为什么突然会为我锻造这个？我已经……",
            ["ContentKR"] = "감사해요, 어르신. 그런데 어째서 갑자기 이런 걸 만들어 주신 건가요? 전 이미... 그, 그게...",
            ["DialogueId"] = 51009115,
            ["FacialId"] = {
                [1] = "100001:Shy",
                },
            ["GUID"] = "7FB22AEE",
            ["NextDialogue"] = 51009116,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_Start",
                },
            },
        [51009116] = {
            ["Camera"] = "-47.538391,-157.203125,145.923813,0.00021,-15.601462,76.384178,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "武器是每个踏上旅途的年轻人最重要的伙伴，当然要做到有备无患。",
            ["ContentKR"] = "여행을 떠나는 젊은이에게는 무기만큼 든든한 동료가 없지. 걱정할 일이 없도록, 미리 준비해 두어야 한다네.",
            ["DialogueId"] = 51009116,
            ["FacialId"] = {
                [1] = "230002:Happy02",
                },
            ["GUID"] = "7FB22B18",
            ["NextDialogue"] = 51009117,
            ["SpeakNpcId"] = 230002,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_End",
                },
            },
        [51009117] = {
            ["Content"] = "老朽见过太多和你一样的年轻人，不管默默无闻，还是成为了阿特拉西亚的传奇，最开始也都只是些带着好奇心和鲁莽的毛头小子。",
            ["ContentKR"] = "이 늙은이는 자네 같은 젊은이를 너무나 많이 봐 왔다네. 이름 없이 스러져 버렸든, 아트라시아의 전설이 되었든, 다들 처음에는 호기심 많고 무모한 철부지에 불과했지.",
            ["DialogueId"] = 51009117,
            ["FacialId"] = {
                [1] = "230002:Ahaha02",
                },
            ["GUID"] = "7FB22B42",
            ["NextDialogue"] = 51009118,
            ["SpeakNpcId"] = 230002,
            },
        [51009118] = {
            ["Content"] = "一把可靠的武器，正是补足毛躁和稚嫩的良药。",
            ["ContentKR"] = "믿음직한 무기야말로, 그런 경솔함과 미숙함을 보완해 주는 좋은 약이 되어 준다네.",
            ["DialogueId"] = 51009118,
            ["FacialId"] = {
                [1] = "230002:Satisfy01",
                },
            ["GUID"] = "7FB22B6C",
            ["NextDialogue"] = 51009119,
            ["SpeakNpcId"] = 230002,
            },
        [51009119] = {
            ["Camera"] = "-11.187744,-30.125488,113.694717,0.000209,-16.401381,81.782051,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "虽然你可能不那么需要，就算是当备用品也好，这把武器就交给你了，就当是老朽对年轻人的一句忠告吧。",
            ["ContentKR"] = "그다지 필요 없을지도 모르지만, 예비용으로라도 좋으니 이 무기를 받아 두게. 이 늙은이가 해 주는 충고라고 생각하게나.",
            ["DialogueId"] = 51009119,
            ["GUID"] = "7FB22B96",
            ["NextDialogue"] = 51009120,
            ["SpeakNpcId"] = 230002,
            },
        [51009120] = {
            ["Camera"] = "-36.630005,38.096924,125.536903,0.000215,5.798011,-71.413826,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "前辈……",
            ["ContentKR"] = "어르신...",
            ["DialogueId"] = 51009120,
            ["FacialId"] = {
                [1] = "100001:Smile01",
                },
            ["GUID"] = "7FB22BC0",
            ["NextDialogue"] = 51009121,
            ["SpeakNpcId"] = 100001,
            },
        [51009121] = {
            ["Camera"] = "-23.448242,-113.345947,147.890976,0.000217,-16.601587,81.187027,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "以后要是有新的素材和图谱就找老朽，到时候会给你锻造新武器的。",
            ["ContentKR"] = "나중에 새로운 소재나 도면을 손에 넣거든 이 늙은이를 찾아오게. 그때 새 무기를 만들어 주겠네.",
            ["DialogueId"] = 51009121,
            ["FacialId"] = {
                [1] = "230002:Confident02",
                },
            ["GUID"] = "7FB22BEA",
            ["NextDialogue"] = 51009122,
            ["SpeakNpcId"] = 230002,
            },
        [51009122] = {
            ["Content"] = "不过唯独这一把……如果有一天，它不再锋利、残缺、甚至折断，就把它带回来，无论多少次老朽都会帮你重锻。",
            ["ContentKR"] = "하지만 이 무기만큼은... 몇 번이고 다시 벼려 줄 테니, 날이 무뎌지거나, 이가 빠지거나, 심지어는 부러진다 해도 다시 가져와 주게나.",
            ["DialogueId"] = 51009122,
            ["GUID"] = "7FB22C14",
            ["NextDialogue"] = 51009123,
            ["SpeakNpcId"] = 230002,
            },
        [51009123] = {
            ["Camera"] = "-72.498413,-159.67749,187.376312,0.000227,-25.601515,61.982807,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "希望无论什么时候，只要握住它，你都会想起促使你踏上旅途的心情。",
            ["ContentKR"] = "언제든 이 무기를 손에 쥘 때마다, 자네를 모험으로 이끌었던 처음 그 마음을 떠올릴 수 있기를 바라네.",
            ["DialogueId"] = 51009123,
            ["FacialId"] = {
                [1] = "230002:Happy02",
                },
            ["GUID"] = "7FB22C3E",
            ["NextDialogue"] = 51009124,
            ["SpeakNpcId"] = 230002,
            },
        [51009124] = {
            ["Camera"] = "-77.020996,37.951172,120.615501,0.000228,5.798578,-53.617523,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我会好好使用它的。",
            ["ContentKR"] = "정말 잘 쓸게요.",
            ["DialogueId"] = 51009124,
            ["FacialId"] = {
                [1] = "100001:Confident02",
                },
            ["GUID"] = "7FB22C68",
            ["NextDialogue"] = 51009125,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_Start",
                },
            },
        [51009125] = {
            ["Camera"] = "7.467804,-22.984863,112.509064,0.000025,-21.401974,93.791664,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "喔，真是不错的眼神，像你这样的年轻人可不多见咯。",
            ["ContentKR"] = "오, 눈빛이 아주 좋구먼. 요즘 세상에 자네 같은 젊은이는 흔치 않지.",
            ["DialogueId"] = 51009125,
            ["FacialId"] = {
                [1] = "230002:Satisfy01",
                },
            ["FinalCamera"] = "6.965179,-18.811523,117.716042,0.000023,-25.002098,92.79113,35.000011,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FB22C92",
            ["NextDialogue"] = 51009126,
            ["SpeakNpcId"] = 230002,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            },
        [51009126] = {
            ["Content"] = "…………",
            ["ContentKR"] = "......",
            ["DialogueId"] = 51009126,
            ["GUID"] = "7FB22CBC",
            ["LookAt"] = {
                [1] = "230002:n(230002)",
                },
            ["NextDialogue"] = 51009127,
            ["SpeakNpcId"] = 230002,
            },
        [51009127] = {
            ["Camera"] = "-70.951233,159.355713,107.396042,0.000206,-7.602048,-68.41877,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "铁匠前辈，你的表情有点怪怪的，是有什么事吗？",
            ["ContentKR"] = "대장장이 할아버지, 표정이 좀 이상한데? 무슨 일 있어?",
            ["DialogueId"] = 51009127,
            ["FacialId"] = {
                [1] = "230001:Shock01",
                },
            ["GUID"] = "7FB22CE6",
            ["NextDialogue"] = 51009128,
            ["SpeakNpcId"] = 230001,
            ["TalkActionId"] = {
                [1] = "230001:Explain02_Start",
                },
            },
        [51009128] = {
            ["Camera"] = "6.965179,-18.811523,117.716042,0.000023,-25.002098,92.79113,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "没什么，只是想起来一些往事罢了。",
            ["ContentKR"] = "아무것도 아닐세. 그저 옛일이 조금 떠올랐을 뿐이라네.",
            ["DialogueId"] = 51009128,
            ["FacialId"] = {
                [1] = "230002:Syouganai01",
                },
            ["GUID"] = "7FB22D10",
            ["LookAt"] = {
                [1] = "230002:n(230001)",
                },
            ["NextDialogue"] = 51009129,
            ["SpeakNpcId"] = 230002,
            ["TalkActionId"] = {
                [1] = "230001:Explain02_End",
                },
            },
        [51009129] = {
            ["Content"] = "年轻人，能不能帮老朽一个忙？",
            ["ContentKR"] = "젊은이, 이 늙은이의 부탁 하나만 들어줄 수 있겠나?",
            ["DialogueId"] = 51009129,
            ["FacialId"] = {
                [1] = "230002:None",
                },
            ["GUID"] = "7FB22D3A",
            ["LookAt"] = {
                [1] = "230002:n(100001)",
                },
            ["NextDialogue"] = 51009130,
            ["SpeakNpcId"] = 230002,
            },
        [51009130] = {
            ["Camera"] = "-47.573486,44.222656,131.574463,0.000207,1.597875,-67.619141,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "什么忙？",
            ["ContentKR"] = "어떤 부탁이신데요?",
            ["DialogueId"] = 51009130,
            ["FacialId"] = {
                [1] = "100001:Smile01",
                },
            ["GUID"] = "7FB22D64",
            ["NextDialogue"] = 51009131,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_Start",
                },
            },
        [51009131] = {
            ["Camera"] = "-40.003357,-158.163818,175.533508,0.000306,-22.201714,78.178841,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "如果在你冒险的途中，见到……或者听说一把如火焰般赤红的剑，记得告诉我。",
            ["ContentKR"] = "모험을 하다가, 혹시라도... 불꽃처럼 붉은 검을 보거나 그 검에 대한 소문이라도 듣게 된다면, 잊지 말고 내게 알려 주게.",
            ["DialogueId"] = 51009131,
            ["GUID"] = "7FB22D8E",
            ["NextDialogue"] = 51009132,
            ["SpeakNpcId"] = 230002,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_End",
                },
            },
        [51009132] = {
            ["Camera"] = "-79.764465,168.026123,112.217056,0.000226,-5.602353,-64.817764,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那也是铁匠前辈的作品吗？",
            ["ContentKR"] = "그 검도 대장장이 할아버지가 만든 작품이야?",
            ["DialogueId"] = 51009132,
            ["GUID"] = "7FB22DB8",
            ["NextDialogue"] = 51009133,
            ["SpeakNpcId"] = 230001,
            ["TalkActionId"] = {
                [1] = "230001:Think_Start",
                },
            },
        [51009133] = {
            ["Camera"] = "-54.818481,-149.708496,145.451065,0.00023,-15.002154,70.382484,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "应该是吧，不过什么时候锻造的它，为谁锻造的它……为什么想不起来呢……",
            ["ContentKR"] = "아마 그럴 걸세. 하지만 어째서인지... 언제, 누구를 위해 만들었는지 통 기억이 안 나는구먼...",
            ["DialogueId"] = 51009133,
            ["FinalCamera"] = "-23.610504,-51.820557,117.260406,0.000222,-15.60216,74.782066,35.000011,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FB22DE2",
            ["NextDialogue"] = 51009134,
            ["SpeakNpcId"] = 230002,
            ["ToFinalCameraBlendTime"] = 15,
            },
        [51009134] = {
            ["Content"] = "老朽对那把剑的印象只剩下那像在燃烧着一般的颜色，但总觉得必须要找到那把剑不可……",
            ["ContentKR"] = "기억나는 거라고는 불타는 듯한 붉은 빛이었다는 점 하나인데, 자꾸만 그 검을 꼭 찾아야 한다는 느낌이 드네...",
            ["DialogueId"] = 51009134,
            ["GUID"] = "7FB22E0C",
            ["NextDialogue"] = 51009135,
            ["SpeakNpcId"] = 230002,
            },
        [51009135] = {
            ["Camera"] = "4.024445,-18.40332,83.317413,0.00013,3.196528,91.587433,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "年轻人，只有一些传闻也好，拜托你稍微注意一下。",
            ["ContentKR"] = "젊은이, 뜬소문이라도 좋으니, 부디 조금만 신경 써 주게나.",
            ["DialogueId"] = 51009135,
            ["FacialId"] = {
                [1] = "230002:Satisfy01",
                },
            ["FinalCamera"] = "0.602966,-57.215332,91.756393,0.000139,-1.603605,87.387039,35.000011,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FB22E36",
            ["LookAt"] = {
                [1] = "230002:n(100001)",
                },
            ["NextDialogue"] = 51009136,
            ["SpeakNpcId"] = 230002,
            ["ToFinalCameraBlendTime"] = 15,
            },
        [51009136] = {
            ["Camera"] = "-74.956299,70.125977,132.865021,0.000285,-2.00201,-61.222034,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我明白了，会替前辈留意的。",
            ["ContentKR"] = "알겠어요. 알아봐 드릴게요.",
            ["DialogueId"] = 51009136,
            ["GUID"] = "7FB22E60",
            ["NextDialogue"] = 51009137,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_Start",
                },
            },
        [51009137] = {
            ["Camera"] = "-45.467529,-102.451904,136.414795,0.000299,-15.201719,72.779053,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "好了，长辈的唠叨到此为止。新的奇迹即将开始，让阿特拉西亚见证你的冒险吧。",
            ["ContentKR"] = "자, 이 늙은이의 잔소리는 여기까지일세. 곧 새로운 기적이 시작되겠지. 이 아트라시아에 자네의 모험을 똑똑히 보여 주게나.",
            ["DialogueId"] = 51009137,
            ["FacialId"] = {
                [1] = "230002:Happy02",
                },
            ["FinalCamera"] = "-109.385742,-261.364746,203.023361,0.000271,-18.801235,65.979637,35.000011,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FB22E8A",
            ["SpeakNpcId"] = 230002,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_End",
                },
            ["ToFinalCameraBlendTime"] = 15,
            },
        [51009201] = {
            ["Camera"] = "438.621582,138.591309,121.772217,0.000022,0.399839,-164.795059,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "抱歉打扰到你，请容许我占用你英雄诗篇上那微不足道的一行用以自我介绍。",
            ["ContentKR"] = "방해가 되었다면 죄송하지만, 영웅 서사시 중 아주 보잘것없는 한 줄을 빌려 제 소개를 올릴 수 있게 허락해 주셨으면 합니다.",
            ["DialogueId"] = 51009201,
            ["GUID"] = "7FB2390A",
            ["LookAt"] = {
                [1] = "230003:n(100001)",
                },
            ["NextDialogue"] = 51009202,
            ["SpeakNpcId"] = 230003,
            ["TalkActionId"] = {
                [1] = "230003:Explain02_Start",
                },
            },
        [51009202] = {
            ["Camera"] = "184.849121,-47.185059,77.377197,0.000079,-13.401609,165.810257,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "本人名叫阿米埃特，至于职业……本人所从事的事业比较难以用语言概括，因为那样做比较有违美学。",
            ["ContentKR"] = "제 이름은 아미에트입니다. 직업은... 대략적으로 설명해 드리기 어려울 것 같습니다. 그건 미학에 반하는 행동이라서 말이지요.",
            ["DialogueId"] = 51009202,
            ["FinalCamera"] = "155.654297,64.67334,157.197266,0.000115,-0.001284,-158.590393,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FB23934",
            ["NextDialogue"] = 51009203,
            ["SpeakNpcId"] = 230003,
            ["TalkActionId"] = {
                [1] = "230003:Explain02_End",
                },
            ["ToFinalCameraBlendTime"] = 15,
            },
        [51009203] = {
            ["Camera"] = "155.654297,64.67334,157.197266,0.000115,-0.001284,-158.590393,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "如果一定要用一个词去称呼本人的职业，那还请叫做——艺术家。",
            ["ContentKR"] = "정녕코 제 직업을 한 마디로 칭해야 한다면, 부디... 예술가라고 불러 주십시오.",
            ["DialogueId"] = 51009203,
            ["FinalCamera"] = "133.85498,-3.754883,152.920898,0.000117,0.198506,175.208954,35.000008,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FB2395E",
            ["NextDialogue"] = 51009204,
            ["SpeakNpcId"] = 230003,
            ["TalkActionId"] = {
                [1] = "230003:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 15,
            },
        [51009204] = {
            ["Camera"] = "-116.031738,-138.629395,169.49292,0.000161,-6.801338,43.0089,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "好可疑……",
            ["ContentKR"] = "엄청 수상쩍은데요...",
            ["DialogueId"] = 51009204,
            ["FacialId"] = {
                [1] = "100001:Uninterested01",
                },
            ["FinalCamera"] = "-50.322266,-81.086426,160.310791,0.000161,-6.001311,41.20895,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FB23988",
            ["LookAt"] = {
                [1] = "100001:n(230003)",
                },
            ["NextDialogue"] = 51009205,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                [2] = "230003:Confident_End",
                },
            ["ToFinalCameraBlendTime"] = 30,
            },
        [51009205] = {
            ["Camera"] = "182.905762,56.904785,140.219238,0.000167,0.19811,-165.575302,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "请不必无端怀疑，本人在这里徘徊只是因为一些<H>美学</>上的疑惑。",
            ["ContentKR"] = "근거 없는 의심은 부디 거두어 주십시오. 저는 몇 가지 <H>미학</>적인 의문들 때문에 이곳을 배회하는 것뿐이니까요.",
            ["DialogueId"] = 51009205,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["FinalCamera"] = "209.431152,63.451172,140.220459,0.000167,-0.001858,-166.175751,35.000008,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FB239B2",
            ["NextDialogue"] = 51009206,
            ["SpeakNpcId"] = 230003,
            ["TalkActionId"] = {
                [1] = "100001:Think_End",
                [2] = "230003:Explain01_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            },
        [51009206] = {
            ["Content"] = "不知道你有没有这种感觉，朋友——最近的武器似乎都只注重杀伤力和成本，却忽略了锻造物应有的美学。",
            ["ContentKR"] = "이런 느낌을 받으셨는지 모르겠습니다만... 최근의 무기는 살상력과 비용만 중시하고, 응당 지녀야 할 미학은 등한시하는 것 같습니다.",
            ["DialogueId"] = 51009206,
            ["GUID"] = "7FB239DC",
            ["NextDialogue"] = 51009207,
            ["SpeakNpcId"] = 230003,
            ["TalkActionId"] = {
                [1] = "230003:Explain01_End",
                },
            },
        [51009207] = {
            ["Camera"] = "-2849.924805,472.516602,-933.664307,0.000118,-4.801397,-111.175285,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "武器原本并非我主要的研究对象，只是你有没有发现，如今这座城市的士兵变得越来越粗鄙了。",
            ["ContentKR"] = "무기는 원래 제 주요 연구 대상은 아니었습니다만, 요즘 이 도시의 병사들이 갈수록 상스러워지고 있다는 사실을 눈치채셨는지요?",
            ["DialogueId"] = 51009207,
            ["FinalCamera"] = "-2585.590332,363.479004,-933.664307,0.000116,-5.401429,-115.973396,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FB23A06",
            ["NextDialogue"] = 51009208,
            ["SpeakNpcId"] = 230003,
            ["ToFinalCameraBlendTime"] = 15,
            },
        [51009208] = {
            ["Camera"] = "323.17334,117.169922,145.404541,0.000149,-2.002072,-168.165207,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我想正是海伯利亚的炼金院放弃了他们的美学追求，使用者才会如此粗俗，不成体统。而本人把他们的装备在美学上加以矫正，却遭到了不公的对待……",
            ["ContentKR"] = "무기 사용자들이 이토록 저속하고 격이 떨어진 까닭은, 휘페르보레아 제국 연금원이 미학적 탐구를 내팽개쳤기 때문이라고 봅니다. 그런데 저는 그들의 장비를 미학적으로 교정해 주고도, 도리어 부당한 대우를 받게 되었지요...",
            ["DialogueId"] = 51009208,
            ["GUID"] = "7FB23A30",
            ["NextDialogue"] = 51009209,
            ["SpeakNpcId"] = 230003,
            ["TalkActionId"] = {
                [1] = "230003:Explain02_Start",
                },
            },
        [51009209] = {
            ["Camera"] = "107.540039,43.087402,155.901123,0.000135,-9.202333,39.223675,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "“矫正”？你做了什么出格的事吗？",
            ["ContentKR"] = "'교정'이요? 상식 밖의 행동이라도 하신 건가요?",
            ["DialogueId"] = 51009209,
            ["GUID"] = "7FB23A5A",
            ["NextDialogue"] = 51009210,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                },
            },
        [51009210] = {
            ["Camera"] = "323.17334,117.169922,145.404541,0.000149,-2.002072,-168.165207,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "出格？当然没有，只是趁换岗的时候把他们的武器和配饰稍加修改，和他们对我下达监禁十五日的处罚相比，谈何出格？",
            ["ContentKR"] = "상식 밖의 행동요? 그럴 리가요. 저는 그저 경비원들이 교대하는 틈에 그들의 무기와 장신구를 아주 약간 손봐 주었을 뿐입니다. 제게 내려진 보름간의 감금형에 비하면, 제 행동은 지극히 상식적이지요!",
            ["DialogueId"] = 51009210,
            ["GUID"] = "7FB23A84",
            ["NextDialogue"] = 51009211,
            ["SpeakNpcId"] = 230003,
            ["TalkActionId"] = {
                [1] = "230003:Angry01_Start",
                },
            },
        [51009211] = {
            ["Content"] = "本人理解让所有人拥有基本的美学素养是一项艰巨的伟大事业，但我们不应该因为前路艰险就停下脚步——",
            ["ContentKR"] = "모든 이에게 기초적인 미학적 소양을 심어 주는 것이 얼마나 어려운 과업인지 압니다. 하지만 앞길이 아무리 험난한들 걸음을 멈춰선 안 되지요.",
            ["DialogueId"] = 51009211,
            ["GUID"] = "7FB23AAE",
            ["NextDialogue"] = 51009212,
            ["SpeakNpcId"] = 230003,
            ["TalkActionId"] = {
                [1] = "230003:Angry01_End",
                },
            },
        [51009212] = {
            ["Camera"] = "355.351074,108.127441,146.656494,0.000137,-3.402848,-172.570343,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "本人以艺术名义起誓，上到传说英雄的利剑，下到聊以防身的小刀，无关出身无关价格，其本身都应具备美的要素！",
            ["ContentKR"] = "예술의 이름으로 맹세컨대, 전설적 영웅의 명검부터 호신용 단검에 이르기까지, 대상과 가격에 상관없이, 무기는 그 존재 자체로 미의 요소를 갖춰야 합니다!",
            ["DialogueId"] = 51009212,
            ["GUID"] = "7FB23AD8",
            ["NextDialogue"] = 51009213,
            ["SpeakNpcId"] = 230003,
            ["TalkActionId"] = {
                [1] = "230003:Agree",
                },
            },
        [51009213] = {
            ["Camera"] = "179.876953,-270.89502,193.723389,0.00005,-10.001951,105.430725,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哦？老朽好像听到了些很有趣的话。",
            ["ContentKR"] = "오호? 이 늙은이가 조금 전에 아주 흥미로운 이야기를 들은 것 같구먼.",
            ["DialogueId"] = 51009213,
            ["FinalCamera"] = "170.026367,-235.211914,187.194336,0.00005,-10.001951,105.430725,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FB23B02",
            ["LookAt"] = {
                [1] = "100001:n(230002)",
                [2] = "230003:n(230002)",
                },
            ["NextDialogue"] = 51009214,
            ["Scripts"] = "PlayOrStopBGM{PlayType{\"Play\"},SoundPriority{\"StoryCustom\"},SoundType{\"SOUND_BGM\"},SoundUnitKey{\"sidestory_tiejiangjiaojiao\"},EventPath{\"event:/bgm/cbt02/0041_story_jiaojiao_tiejiang\"}}",
            ["SpeakNpcId"] = 230002,
            ["ToFinalCameraBlendTime"] = 30,
            },
        [51009214] = {
            ["Camera"] = "25.713867,-203.86377,194.304688,0.000058,-11.801876,80.425873,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这个后辈虽然从外表看起来不太靠谱，但似乎对武器的美学颇有一些见解。",
            ["ContentKR"] = "겉보기에는 영 미덥지 않아도, 무기의 미학에 대해서는 제법 식견이 있는 젊은이인 모양일세.",
            ["DialogueId"] = 51009214,
            ["FinalCamera"] = "71.773438,-210.437012,194.733398,0.000048,-11.601704,88.225449,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FB23B2C",
            ["LookAt"] = {
                [1] = "230002:n(230003)",
                },
            ["NextDialogue"] = 51009215,
            ["Scripts"] = "PARA{\
LookAt{_delay{0.5},LookAtDescription{\"230003:n(230002)\"}}\
}",
            ["SpeakNpcId"] = 230002,
            ["TalkActionId"] = {
                [1] = "100001:Think_End",
                },
            ["ToFinalCameraBlendTime"] = 30,
            },
        [51009215] = {
            ["Camera"] = "77.210938,30.784668,120.665283,0.000054,-10.001801,93.224159,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "现在的武器总是粗枝大叶，锤锻造就的线条，淬炼形成的纹路，恰到好处的平衡，每一个环节都应该饱含锻造者的心血才是。",
            ["ContentKR"] = "모름지기 무기란, 망치질로 벼려낸 선과 담금질로 아로새긴 무늬, 절묘한 무게 중심까지도, 대장장이의 피와 땀이 담겨 있어야 하네만, 요즘 무기들은 조악하기 짝이 없지.",
            ["DialogueId"] = 51009215,
            ["FacialId"] = {
                [1] = "230002:Happy01",
                },
            ["FinalCamera"] = "109.248535,35.82959,120.665283,0.000053,-10.801848,106.024544,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FB23B56",
            ["LookAt"] = {
                [1] = "230002:n(230002)",
                },
            ["NextDialogue"] = 51009216,
            ["SpeakNpcId"] = 230002,
            ["ToFinalCameraBlendTime"] = 30,
            },
        [51009216] = {
            ["Camera"] = "192.502441,42.003906,148.640137,0.000075,-3.202395,-170.373978,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "线条？纹路？平衡？",
            ["ContentKR"] = "선? 무늬?? 무게 중심이요???",
            ["DialogueId"] = 51009216,
            ["GUID"] = "7FB23B80",
            ["NextDialogue"] = 51009217,
            ["SpeakNpcId"] = 230003,
            ["TalkActionId"] = {
                [1] = "230003:Think_Start",
                },
            },
        [51009217] = {
            ["Content"] = "请等一等，这些和美学有什么关系？",
            ["ContentKR"] = "잠깐, 그런 것들이 미학과 무슨 관계가 있다는 겁니까?",
            ["DialogueId"] = 51009217,
            ["GUID"] = "7FB23BAA",
            ["NextDialogue"] = 51009218,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{230003},AnimationId{\"Think_End\"},Duration{0.7}},\
PlayAnimation{ActorId{230003},AnimationId{\"Explain01_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 230003,
            },
        [51009218] = {
            ["Camera"] = "2.193848,-80.82959,191.693848,0.000078,-22.189302,81.527405,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "啊？",
            ["ContentKR"] = "음?",
            ["DialogueId"] = 51009218,
            ["FacialId"] = {
                [1] = "230002:Shock01",
                },
            ["GUID"] = "7FB23BD4",
            ["LookAt"] = {
                [1] = "230002:n(230003)",
                },
            ["NextDialogue"] = 51009219,
            ["SpeakNpcId"] = 230002,
            },
        [51009219] = {
            ["Camera"] = "249.694824,-158.883301,265.504639,0.000084,-27.202122,132.82428,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "美学真正的灵魂所在是色彩啊！色彩！",
            ["ContentKR"] = "미학의 영혼은 바로 색채, 색채에 있습니다!",
            ["DialogueId"] = 51009219,
            ["GUID"] = "7FB23BFE",
            ["NextDialogue"] = 51009220,
            ["SpeakNpcId"] = 230003,
            ["TalkActionId"] = {
                [1] = "230003:Angry01_Start",
                },
            },
        [51009220] = {
            ["Camera"] = "66.329102,29.245117,148.397217,0.000144,-18.801685,88.624496,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "喔——原来是考虑这个方面吗？",
            ["ContentKR"] = "오호라, 방향이 그쪽이었던 건가?",
            ["DialogueId"] = 51009220,
            ["FinalCamera"] = "67.455566,76.165527,132.418457,0.000147,-18.801685,88.624504,25.0,100000.0,false,DoNotOverride,2.8",
