            ["SpeakNpcId"] = 700300,
            ["TalkActionId"] = {
                [1] = "700306:Talk01_End",
                [2] = "700300:Confident_Start",
                },
            },
        [51009421] = {
            ["Content"] = "我喜欢看着人们为我的表演喝彩，喜欢听到他们在街头巷尾讨论某个唱段。",
            ["ContentKR"] = "난 사람들이 내 공연에 환호하는 모습을 보는 게 좋아. 길거리에서 내 노래의 한 구절을 흥얼거리는 소리를 듣는 것도.",
            ["DialogueId"] = 51009421,
            ["GUID"] = "7FB25D22",
            ["NextDialogue"] = 51009422,
            ["SpeakNpcId"] = 700300,
            },
        [51009422] = {
            ["Content"] = "每一次不同的舞台样貌，又或者是单纯突发奇想的临场发挥，都会在接下来的一个月占据所有的娱乐报刊——我很享受这样的感觉。",
            ["ContentKR"] = "무대마다 달라지는 새로운 모습, 혹은 무심코 시도한 즉흥 연기 하나가, 한 달간 모든 연예 신문을 장식하곤 하지... 난 그런 기분을 참 좋아한단다.",
            ["DialogueId"] = 51009422,
            ["GUID"] = "7FB25D4C",
            ["NextDialogue"] = 51009423,
            ["SpeakNpcId"] = 700300,
            },
        [51009423] = {
