            ["Camera"] = "695.307617,-554.236328,471.275024,0.000054,-20.794161,139.593384,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "薇奥莱塔女士说的地址就是这里，不过附近好像没什么住宅的样子。",
            ["ContentKR"] = "비올레타 씨가 말한 주소는 여기인데, 근처에 집은 없는 것 같네.",
            ["DialogueId"] = 51009448,
            ["GUID"] = "7FB26190",
            ["NextDialogue"] = 51009449,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700313:Think_Start",
                },
            },
        [51009449] = {
            ["Content"] = "旁边有个卫兵，过去打听一下吧。",
            ["ContentKR"] = "옆에 경비병이 있으니까, 가서 물어보자.",
            ["DialogueId"] = 51009449,
            ["GUID"] = "7FB261BA",
            ["NextDialogue"] = 51009450,
            ["SpeakNpcId"] = 100001,
            },
        [51009450] = {
            ["Camera"] = "232.955078,593.629395,162.682861,0.000058,-3.794279,-115.003006,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你好，我想和你打听点事情。",
            ["ContentKR"] = "안녕하세요. 뭐 좀 여쭤볼게요.",
            ["DialogueId"] = 51009450,
            ["GUID"] = "7FB261E4",
            ["NextDialogue"] = 51009451,
            ["Scripts"] = "MoveTo{ActorId{100001},TargetPoint{\"Questpoint_Nvzhu_20023002\"},MoveSpeed{150},Visibility{\"Show\"}}",
            ["SpeakNpcId"] = 100001,
            },
        [51009451] = {
            ["Camera"] = "112.706055,-213.83313,198.990479,0.000058,-8.794134,109.594849,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我在忙，等我有空再说吧。奇怪，这里应该是这样啊……这唱机怎么了……",
            ["ContentKR"] = "지금은 바쁘니까 나중에 얘기하자. 이상하네, 이렇게 하는 게 맞는데... 왜 또 말썽이야...",
            ["DialogueId"] = 51009451,
            ["GUID"] = "7FB2620E",
            ["NextDialogue"] = 51009452,
            ["SpeakNpcId"] = 700313,
            },
        [51009452] = {
            ["Camera"] = "408.029297,-87.160217,216.346191,0.000075,-13.994142,150.79335,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（男人焦头烂额地摆弄着地上的一台旧唱机。）",
            ["ContentKR"] = "(남자는 쩔쩔매며 바닥에 놓인 낡은 축음기를 만지작거린다.)",
            ["DialogueId"] = 51009452,
            ["GUID"] = "7FB26238",
            ["NextDialogue"] = 51009453,
            },
        [51009453] = {
            ["Content"] = "它坏掉了吗？",
            ["ContentKR"] = "고장 난 거예요?",
            ["DialogueId"] = 51009453,
            ["GUID"] = "7FB26262",
            ["NextDialogue"] = 51009454,
            ["SpeakNpcId"] = 100001,
            },
        [51009454] = {
            ["Camera"] = "112.706055,-213.83313,198.990479,0.000058,-8.794134,109.594849,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "应该也不算坏掉……但有些年头了，偶尔会失灵。我明明记得这么来一下就行啊……",
            ["ContentKR"] = "고장이라기보단... 연식이 좀 돼서 가끔 작동이 잘 안 돼. 분명 이렇게 하면 됐던 것 같은데...",
            ["DialogueId"] = 51009454,
            ["GUID"] = "7FB2628C",
            ["NextOptions"] = {
                [1] = 510093641,
                },
            ["SpeakNpcId"] = 700313,
            ["TalkActionId"] = {
                [1] = "700313:Talk01_Start",
                },
            },
        [51009455] = {
            ["Camera"] = "112.706055,-213.83313,198.990479,0.000058,-8.794134,109.594849,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你会折腾这东西？那这样，如果你能帮我修好我一定知无不言。",
            ["ContentKR"] = "이런 것도 만질 줄 알아? 좋아, 그럼 이렇게 하지. 이걸 고쳐준다면, 아는 건 뭐든 알려줄게.",
            ["DialogueId"] = 51009455,
            ["GUID"] = "7FB262B6",
            ["NextDialogue"] = 51009456,
            ["SpeakNpcId"] = 700313,
            ["TalkActionId"] = {
                [1] = "700313:Talk01_End",
                },
            },
        [51009456] = {
            ["Camera"] = "96.858398,213.679291,148.014893,0.00006,-3.794279,-114.800949,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "一言为定。",
            ["ContentKR"] = "약속 지키셔야 돼요.",
            ["DialogueId"] = 51009456,
            ["FacialId"] = {
                [1] = "100001:Confident02",
                },
            ["GUID"] = "7FB262E0",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_Start",
                [2] = "700313:Talk01_End",
                },
            },
        [51009457] = {
            ["Camera"] = "92.020508,225.958801,156.641846,0.000078,-5.994201,-113.997604,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这样应该就可以了。",
            ["ContentKR"] = "이제 될 거예요.",
            ["DialogueId"] = 51009457,
            ["FacialId"] = {
                [1] = "100001:Ahaha02",
                },
            ["GUID"] = "7FB2630A",
            ["NextDialogue"] = 51009458,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk01_Start",
                },
            },
        [51009458] = {
            ["Camera"] = "490.863281,-71.149292,246.487061,0.000077,-14.394158,157.593735,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "有两下子啊，这样总算能听我的录音带了。啊，薇奥莱塔女士的歌喉——",
            ["ContentKR"] = "제법이군. 덕분에 이제 녹음테이프를 들을 수 있겠어. 아, 비올레타 님의 노랫소리는 정말...",
            ["DialogueId"] = 51009458,
            ["GUID"] = "7FB26334",
            ["NextDialogue"] = 51009459,
            ["SpeakNpcId"] = 700313,
            ["TalkActionId"] = {
                [1] = "100001:Talk01_End",
                [2] = "700313:Shock_Start",
                },
            },
        [51009459] = {
            ["Camera"] = "92.020508,225.958801,156.641846,0.000078,-5.994201,-113.997604,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你知道薇奥莱塔？",
            ["ContentKR"] = "비올레타 씨를 아세요?",
            ["DialogueId"] = 51009459,
            ["FacialId"] = {
                [1] = "100001:Doubt01",
                },
            ["GUID"] = "7FB2635E",
            ["NextDialogue"] = 51009460,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_Start",
                [2] = "700313:Shock_End",
                },
            },
        [51009460] = {
            ["Camera"] = "112.706055,-213.83313,198.990479,0.000058,-8.794134,109.594849,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这冰湖城有谁不知道吗？她的首部唱片都已经炒到了天价，我攒了三个月的薪水还买不起！唉，只能先听便宜录音带解解馋。",
            ["ContentKR"] = "이 아이스레이크 시티에서 그분을 모르는 사람이 있어? 초판 앨범은 가격이 천정부지라, 석 달 치 월급을 모아도 살 수가 없다고! 하, 그러니까 저렴한 녹음테이프나 들으면서 아쉬움을 달랠 수밖에.",
            ["DialogueId"] = 51009460,
            ["GUID"] = "7FB26388",
            ["NextDialogue"] = 51009461,
            ["SpeakNpcId"] = 700313,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_End",
                [2] = "700313:Confident_Start",
                },
            },
        [51009461] = {
            ["Camera"] = "92.020508,225.958801,156.641846,0.000078,-5.994201,-113.997604,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那就好说了，我要问的事刚好和薇奥莱塔女士有关。",
            ["ContentKR"] = "그럼 얘기가 쉽겠네요. 마침 비올레타 씨에 관한 걸 여쭤보려고 했거든요.",
            ["DialogueId"] = 51009461,
            ["FacialId"] = {
                [1] = "100001:Smile01",
                },
            ["GUID"] = "7FB263B2",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain01_Start",
                },
            },
        [51009462] = {
            ["Content"] = "（再三叮嘱对方务必保密后，向卫兵大概说明了薇奥莱塔女士遭遇骚扰的事。）",
            ["ContentKR"] = "(꼭 비밀을 지켜달라고 몇 번이고 당부한 후, 비올레타 씨가 스토킹 당하고 있다는 사실을 대략적으로 말해 준다.)",
            ["DialogueId"] = 51009462,
            ["GUID"] = "7FB263DC",
            },
        [51009463] = {
            ["Camera"] = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "什么？居然有这种事？！这真的是太不成体统了！如果犯人真的住在这片街区，我一定帮你把他揪出来好好教训一顿！",
            ["ContentKR"] = "뭐? 그런 일이?! 정말 말도 안 되는 일이로군! 범인이 이 근처에 산다면, 찾아내서 혼꾸멍을 내 주겠어!",
            ["DialogueId"] = 51009463,
            ["GUID"] = "7FB26406",
            ["NextDialogue"] = 51009464,
            ["SpeakNpcId"] = 700313,
            ["TalkActionId"] = {
                [1] = "100001:Explain01_End",
                [2] = "700313:Angry01_Start",
                },
            },
        [51009464] = {
            ["Camera"] = "92.020508,225.958801,156.641846,0.000078,-5.994201,-113.997604,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "倒也不用这么夸张……",
            ["ContentKR"] = "그렇게까지 하실 필요는...",
            ["DialogueId"] = 51009464,
            ["FacialId"] = {
                [1] = "100001:Smile01",
                },
            ["GUID"] = "7FB26430",
            ["NextDialogue"] = 51009465,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:ScratchHead_Start",
                },
            },
        [51009465] = {
            ["Camera"] = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "怎么就夸张了？我生平最见不得这种危害社会治安的败类，你放心，这一带的住户我都或多或少打过交道，只要有点线索我一定能把犯人抓到！",
            ["ContentKR"] = "그게 무슨 소리야? 사회 질서를 해치는 그런 몹쓸 녀석들은 절대 가만 못 둬. 안심해, 이 근처 주민들은 내가 웬만큼 다 아니까, 단서만 있으면 범인을 찾을 수 있어.",
            ["DialogueId"] = 51009465,
            ["GUID"] = "7FB2645A",
            ["NextDialogue"] = 51009466,
            ["SpeakNpcId"] = 700313,
            ["TalkActionId"] = {
                [1] = "100001:ScratchHead_End",
                [2] = "700313:Confident_Start",
                },
            },
        [51009466] = {
            ["Camera"] = "92.020508,225.958801,156.641846,0.000078,-5.994201,-113.997604,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "线索的话……这封信你有什么头绪吗？",
            ["ContentKR"] = "단서라면... 이 편지, 뭔가 짚이는 거 없으세요?",
            ["DialogueId"] = 51009466,
            ["GUID"] = "7FB26484",
            ["NextDialogue"] = 51009467,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Give",
                },
            },
        [51009467] = {
            ["Camera"] = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "什么信？我看看。",
            ["ContentKR"] = "무슨 편지? 이리 줘 봐.",
            ["DialogueId"] = 51009467,
            ["GUID"] = "7FB264AE",
            ["NextDialogue"] = 51009468,
            ["SpeakNpcId"] = 700313,
            ["TalkActionId"] = {
                [1] = "700313:Confident_End",
                },
            },
        [51009468] = {
            ["Camera"] = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "…………",
            ["ContentKR"] = "......",
            ["DialogueId"] = 51009468,
            ["FinalCamera"] = "28.276367,114.675842,163.198242,0.000057,-8.794093,105.195099,12.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FB264D8",
            ["NextDialogue"] = 51009469,
            ["SpeakNpcId"] = 700313,
            ["ToFinalCameraBlendTime"] = 1,
            },
        [51009469] = {
            ["Camera"] = "92.020508,225.958801,156.641846,0.000078,-5.994201,-113.997604,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "…………",
            ["ContentKR"] = "......",
            ["DialogueId"] = 51009469,
            ["FacialId"] = {
                [1] = "100001:Doubt01",
                },
            ["GUID"] = "7FB26502",
            ["NextDialogue"] = 51009470,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk03_Start",
                },
            },
        [51009470] = {
            ["Content"] = "怎么了，你为什么不说话？",
            ["ContentKR"] = "뭐예요? 왜 아무 말씀도 안 하세요?",
            ["DialogueId"] = 51009470,
            ["GUID"] = "7FB2652C",
            ["NextDialogue"] = 51009471,
            ["SpeakNpcId"] = 100001,
            },
        [51009471] = {
            ["Camera"] = "28.276367,114.675842,163.198242,0.000057,-8.794093,105.195099,12.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这……这对吗？这不对吧？我觉得这封信言辞恳切情感真挚，和骚扰信天差地别。",
            ["ContentKR"] = "스토커...라고? 그럴 리가? 글솜씨는 서툴러도 진심이 느껴지는 게, 그런 불순한 녀석들하곤 차원이 다른걸.",
            ["DialogueId"] = 51009471,
            ["GUID"] = "7FB26556",
            ["NextDialogue"] = 51009472,
            ["SpeakNpcId"] = 700313,
            ["TalkActionId"] = {
                [1] = "700313:Talk01_Start",
                },
            },
        [51009472] = {
            ["Camera"] = "224.37207,502.975342,173.965332,0.000078,-3.594175,-121.197639,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "看来寄信的人已经找到了。刚才好像有人说要把犯人好好教训一顿？",
            ["ContentKR"] = "누가 쓴 건지는 이미 알겠네요. 아까는 범인을 따끔하게 혼내 주신다면서요?",
            ["DialogueId"] = 51009472,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["GUID"] = "7FB26580",
            ["NextDialogue"] = 51009473,
            ["SpeakNpcId"] = 100001,
            },
        [51009473] = {
            ["Camera"] = "28.276367,114.675842,163.198242,0.000057,-8.794093,105.195099,12.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这是误会，一定是误会。我发誓我对薇奥莱塔女士一片真心——不是说薇奥莱塔女士最喜欢热情洋溢的表白吗？她怎么会说那是骚扰啊？",
            ["ContentKR"] = "오해야, 분명 오해라고! 맹세컨대 비올레타 님을 향한 내 진심은... 아니지, 비올레타 님은 열정적인 고백을 가장 좋아한다고 하셨는데? 그런 분이 이걸 스토킹이라고 하셨을 리가 없어!",
            ["DialogueId"] = 51009473,
            ["GUID"] = "7FB265AA",
            ["NextDialogue"] = 51009474,
            ["SpeakNpcId"] = 700313,
            },
        [51009474] = {
            ["Content"] = "……难道是<H>那家伙在骗我</>……",
            ["ContentKR"] = "...설마 <H>그 녀석이 날 속인 건가</>...?",
            ["DialogueId"] = 51009474,
            ["GUID"] = "7FB265D4",
            ["NextDialogue"] = 51009475,
            ["SpeakNpcId"] = 700313,
            },
        [51009475] = {
            ["Content"] = "等一下，我明白了！是你！你根本不是薇奥莱塔女士派来的，你是来拆散我们的！",
            ["ContentKR"] = "잠깐, 이제 알겠다! 너구나! 넌 비올레타 님이 보낸 사람이 아니라, 우리 사이를 갈라놓으려고 하는 거야!",
            ["DialogueId"] = 51009475,
            ["GUID"] = "7FB265FE",
            ["NextDialogue"] = 51009476,
            ["SpeakNpcId"] = 700313,
            ["TalkActionId"] = {
                [1] = "700313:Angry01_Start",
                },
            },
        [51009476] = {
            ["Content"] = "你有什么证据证明是薇奥莱塔女士让你来的？依我看你就是在挑拨离间！",
            ["ContentKR"] = "널 보낸 게 비올레타 님이란 증거라도 있어? 넌 그냥 나하고 그분 사이를 이간질하려는 거잖아!",
            ["DialogueId"] = 51009476,
            ["GUID"] = "7FB26628",
            ["NextDialogue"] = 51009477,
            ["SpeakNpcId"] = 700313,
            },
        [51009477] = {
            ["Camera"] = "112.706055,-213.83313,198.990479,0.000058,-8.794134,109.594849,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "居然试图用这样的手段来破坏薇奥莱塔女士和追随者之间的信任，我必须要好好教训一下你！",
            ["ContentKR"] = "감히 이 따위 수작으로 비올레타 님과 추종자들 사이의 믿음을 깨뜨리려고 하다니, 버르장머리를 아주 단단히 고쳐 줘야겠군!",
            ["DialogueId"] = 51009477,
            ["GUID"] = "7FB26652",
            ["NextDialogue"] = 51009478,
            ["SpeakNpcId"] = 700313,
            },
        [51009478] = {
            ["Camera"] = "92.173828,227.503815,153.63623,0.000067,-3.594264,-113.599007,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你这人怎么……",
            ["ContentKR"] = "저한테 왜 이러세요...",
            ["DialogueId"] = 51009478,
            ["GUID"] = "7FB2667C",
            ["NextDialogue"] = 51009479,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk03_End",
                },
            },
        [51009479] = {
            ["Camera"] = "112.706055,-213.83313,198.990479,0.000058,-8.794134,109.594849,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（还是先想办法让这个自说自话的家伙冷静一下吧。）",
            ["ContentKR"] = "(일단 이 막무가내인 녀석을 어떻게든 진정시켜야겠어.)",
            ["DialogueId"] = 51009479,
            ["GUID"] = "7FB266A6",
            ["SpeakNpcId"] = 100001,
            },
        [51009480] = {
            ["Camera"] = "112.706055,-213.83313,198.990479,0.000058,-8.794134,109.594849,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "薇奥莱塔女士，是我……是我太弱小……",
            ["ContentKR"] = "비올레타 님, 제가... 조금 더 강했더라면...",
            ["DialogueId"] = 51009480,
            ["GUID"] = "7FB266D0",
            ["NextDialogue"] = 51009481,
            ["SpeakNpcId"] = 700313,
            ["TalkActionId"] = {
                [1] = "700313:Stop01_Start",
                },
            },
        [51009481] = {
            ["Camera"] = "172.162109,534.255371,170.810547,0.000068,-3.594264,-113.598976,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "闹够了？看看这个吧。",
            ["ContentKR"] = "이제 끝난 거죠? 이거 좀 보세요.",
            ["DialogueId"] = 51009481,
            ["DialoguePanelType"] = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_ChapterFire_Ribbon01.T_Guide_ChapterFire_Ribbon01'}",
            ["FacialId"] = {
                [1] = "100001:Angry01",
                },
            ["GUID"] = "7FB266FA",
            ["NextDialogue"] = 51009482,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Give",
                [2] = "700313:Stop01_End",
                },
            },
        [51009482] = {
            ["Camera"] = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这是，薇奥莱塔女士的缎带？她从十多年前第一次公开演出开始就一直带着的……",
            ["ContentKR"] = "이건, 비올레타 님의 리본이잖아? 10년 전쯤에 있었던 첫 공연 때부터 쭉 하고 계시는...",
            ["DialogueId"] = 51009482,
            ["GUID"] = "7FB26724",
            ["NextDialogue"] = 51009483,
            ["SpeakNpcId"] = 700313,
            ["TalkActionId"] = {
                [1] = "700313:Shock_Start",
                },
            },
        [51009483] = {
            ["Camera"] = "92.173828,227.503815,153.63623,0.000067,-3.594264,-113.599007,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这也能认出来？",
            ["ContentKR"] = "이런 것도 알아보시네요?",
            ["DialogueId"] = 51009483,
            ["FacialId"] = {
                [1] = "100001:Shock01",
                },
            ["GUID"] = "7FB2674E",
            ["NextDialogue"] = 51009484,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Disagree",
                },
            },
        [51009484] = {
            ["Camera"] = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "怎么可能认不出来！我跟你说这些干吗……",
            ["ContentKR"] = "이걸 어떻게 못 알아보겠어! 하긴 너한테 이런 얘길 해 봐야 무슨 소용이겠냐만...",
            ["DialogueId"] = 51009484,
            ["GUID"] = "7FB26778",
            ["NextDialogue"] = 51009485,
            ["SpeakNpcId"] = 700313,
            ["TalkActionId"] = {
                [1] = "700313:Shock_End",
                },
            },
        [51009485] = {
            ["Content"] = "既然你拿着这个，那看来我是真的被拒绝了。我不会再去骚扰薇奥莱塔女士了，祝你们幸福。",
            ["ContentKR"] = "네가 이걸 가지고 있다는 건, 내 마음이 확실히 거절당했단 거겠지. 앞으로 다시는 비올레타 님께 폐 끼치는 일 없을 거야. 그분과 행복하길 기원할게.",
            ["DialogueId"] = 51009485,
            ["GUID"] = "7FB267A2",
            ["NextOptions"] = {
                [1] = 510093951,
                [2] = 510093952,
                },
            ["SpeakNpcId"] = 700313,
            },
        [51009486] = {
            ["Camera"] = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "不要再说了，就让一颗炽烈的心在角落默默哭泣吧！",
            ["ContentKR"] = "알아들었다니까. 이 불타는 심장에 흐르는 쓸쓸한 눈물을 이해해 달라고!",
            ["DialogueId"] = 51009486,
            ["GUID"] = "7FB267CC",
            ["NextDialogue"] = 51009487,
            ["SpeakNpcId"] = 700313,
            ["TalkActionId"] = {
                [1] = "700313:Stop01_Start",
                },
            },
        [51009487] = {
            ["Camera"] = "92.173828,227.503815,153.63623,0.000067,-3.594264,-113.599007,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（卫兵不再回答，只是一味流泪……还是让他自己安静一会儿吧。）",
            ["ContentKR"] = "(경비병은 더 이상 대답하지 않고 눈물만 흘린다... 혼자 조용히 있게 내버려두자.)",
            ["DialogueId"] = 51009487,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["GUID"] = "7FB267F6",
            ["SpeakNpcId"] = 100001,
            },
        [51009488] = {
            ["Camera"] = "154.741699,155.880859,184.548828,0.000014,-8.400074,-153.591629,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "薇奥莱塔女士，我回来了。",
            ["ContentKR"] = "비올레타 씨, 저 왔어요.",
            ["DialogueId"] = 51009488,
            ["GUID"] = "7FB26820",
            ["NextDialogue"] = 51009489,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain01_Start",
                },
            },
        [51009489] = {
            ["Camera"] = "-225.489746,72.248535,138.279785,0.000003,0.400024,-11.196657,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "辛苦你了，看起来问题已经解决了。",
            ["ContentKR"] = "수고했어. 문제는 해결된 모양이구나.",
            ["DialogueId"] = 51009489,
            ["FacialId"] = {
                [1] = "700300:CM_Happy01",
                },
            ["GUID"] = "7FB2684A",
            ["NextDialogue"] = 51009490,
            ["SpeakNpcId"] = 700300,
            ["TalkActionId"] = {
                [1] = "100001:Explain01_End",
                [2] = "700300:Talk02_Start",
                },
            },
        [51009490] = {
            ["Camera"] = "154.741699,155.880859,184.548828,0.000014,-8.400074,-153.591629,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嗯，他不会再来骚扰你了。这条缎带也还给你，如果没有它，恐怕还要再被纠缠一段时间。",
            ["ContentKR"] = "네, 앞으로는 귀찮게 굴지 않을 거예요. 이 리본도 돌려드릴게요. 이 리본 덕분에 일을 금방 해결할 수 있었어요.",
            ["DialogueId"] = 51009490,
            ["DialoguePanelType"] = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_ChapterFire_Ribbon01.T_Guide_ChapterFire_Ribbon01'}",
            ["FacialId"] = {
                [1] = "100001:Confident01",
                },
            ["GUID"] = "7FB26874",
            ["NextDialogue"] = 51009491,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700300:Talk02_End",
                [2] = "100001:Give",
                },
            },
        [51009491] = {
            ["Content"] = "听说这条缎带，你从十几年前就一直戴着？",
            ["ContentKR"] = "그런데 이 리본을 10년 전부터 하고 다니셨다면서요?",
            ["DialogueId"] = 51009491,
            ["FacialId"] = {
                [1] = "100001:Doubt01",
                },
            ["GUID"] = "7FB2689E",
            ["NextDialogue"] = 51009492,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain01_Start",
                },
            },
        [51009492] = {
            ["Camera"] = "-225.489746,72.248535,138.279785,0.000003,0.400024,-11.196719,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "是的，这是一位友人留给我的纪念，她才华横溢，但却不受命运垂怜……",
            ["ContentKR"] = "응, 이건 내 친구가 남긴 물건이야. 재능은 넘쳤지만, 운명이 외면한 친구였지...",
            ["DialogueId"] = 51009492,
            ["FacialId"] = {
                [1] = "700300:CM_Sad01",
                },
            ["GUID"] = "7FB268C8",
            ["NextDialogue"] = 51009493,
            ["SpeakNpcId"] = 700300,
            ["TalkActionId"] = {
                [1] = "100001:Explain01_End",
                [2] = "700300:Sigh_Start",
                },
            },
        [51009493] = {
            ["Content"] = "出于某些原因，她无法实现自己的梦想了，不过我可以，所以我希望能够让她也一起在舞台上闪耀。",
            ["ContentKR"] = "그 친구는 사정이 있어서 꿈을 이룰 수 없게 됐지만, 난 무대에 올랐으니까, 그 친구도 나와 함께 무대에서 빛나게 해 주고 싶었어.",
            ["DialogueId"] = 51009493,
            ["FacialId"] = {
                [1] = "700300:CM_Sad01",
                },
            ["GUID"] = "7FB268F2",
            ["NextDialogue"] = 51009494,
            ["SpeakNpcId"] = 700300,
            ["TalkActionId"] = {
                [1] = "700300:Sigh_End",
                },
            },
        [51009494] = {
            ["Content"] = "所以在我第一次公演的时候，我亲自设计了一张海报，在黑白的画面里，只有一抹紫色格外亮眼——",
            ["ContentKR"] = "내 손으로 첫 공연 포스터를 제작할 때, 흑백 포스터에 이 보랏빛만 선명하게 빛나도록 디자인한 것도 그래서였고.",
            ["DialogueId"] = 51009494,
            ["FacialId"] = {
                [1] = "700300:CM_Sad01",
                },
            ["GUID"] = "7FB2691C",
            ["NextDialogue"] = 51009495,
            ["SpeakNpcId"] = 700300,
            ["TalkActionId"] = {
                [1] = "700300:Talk02_Start",
                },
            },
        [51009495] = {
            ["Content"] = "你应该听说过“千面的薇奥莱塔”这个称呼，我有着足以让自己变成另一个人的化妆技术，在每场演出都会根据角色用不同的容貌登台。",
            ["ContentKR"] = "'천의 얼굴 비올레타'라는 별명, 들어 봤겠지? 난 아예 다른 사람이라고 해도 믿을 만큼 분장을 잘해. 공연 때마다 역할에 맞는 다른 모습으로 무대에 서지.",
            ["DialogueId"] = 51009495,
            ["FacialId"] = {
                [1] = "700300:CM_Sad01",
                },
            ["GUID"] = "7FB26946",
            ["NextDialogue"] = 51009496,
            ["SpeakNpcId"] = 700300,
            },
        [51009496] = {
            ["Content"] = "但唯独这条缎带，我每次都会戴上。久而久之，<H>它也就成了我独有的标志</>。",
            ["ContentKR"] = "하지만 언제든 이 리본만큼은 꼭 착용해. 시간이 지나면서, <H>이 리본은 나만의 상징이 됐지</>.",
            ["DialogueId"] = 51009496,
            ["FacialId"] = {
                [1] = "700300:CM_Sad01",
                },
            ["GUID"] = "7FB26970",
            ["NextDialogue"] = 51009497,
            ["SpeakNpcId"] = 700300,
            ["TalkActionId"] = {
                [1] = "700300:Talk02_End",
                },
            },
        [51009497] = {
            ["Camera"] = "6.950195,47.361328,152.822266,0.000007,-4.600037,-165.990051,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "原来如此……",
            ["ContentKR"] = "그랬군요...",
            ["DialogueId"] = 51009497,
            ["FacialId"] = {
                [1] = "100001:Unhappy02",
                },
            ["GUID"] = "7FB2699A",
            ["NextDialogue"] = 51009498,
            ["SpeakNpcId"] = 100001,
            },
        [51009498] = {
            ["Content"] = "老师！",
            ["ContentKR"] = "선생님!",
            ["DialogueId"] = 51009498,
            ["GUID"] = "7FB269C4",
            ["LookAt"] = {
                [1] = "100001:n(700306)",
                [2] = "700300:n(700306)",
                },
            ["NextDialogue"] = 51009499,
            ["SpeakNpcId"] = 700306,
            },
        [51009499] = {
            ["Camera"] = "-225.489746,72.248535,138.279785,0.000003,0.400024,-11.196657,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "费恩，我应该教过你不要大呼小叫。",
            ["ContentKR"] = "페온, 그렇게 큰 소리로 부르지 말라고 이야기했잖니.",
            ["DialogueId"] = 51009499,
            ["FacialId"] = {
                [1] = "700300:CM_Angry01",
                },
            ["GUID"] = "7FB269EE",
            ["NextDialogue"] = 51009500,
            ["SpeakNpcId"] = 700300,
            ["TalkActionId"] = {
                [1] = "700300:Confident_Start",
                },
            },
        [51009500] = {
            ["Camera"] = "-401.135742,235.075195,139.57666,0.000003,-1.799823,-39.399132,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "对不起……但是老师你必须看看这个！",
            ["ContentKR"] = "죄송합니다... 하지만 이건 꼭 보셔야 해요!",
            ["DialogueId"] = 51009500,
            ["GUID"] = "7FB26A18",
            ["NextDialogue"] = 51009501,
            ["Scripts"] = "PARA{\
PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt02/0043_story_empire\"}},\
