            ["NextDialogue"] = 51009617,
            ["SpeakNpcId"] = 700303,
            ["TalkActionId"] = {
                [1] = "700303:Explain02_Start",
                },
            },
        [51009617] = {
            ["Content"] = "多纳特大叔他病得很重，我好怕——",
            ["ContentKR"] = "아저씨가 많이 아프니까 걱정된단 말이야. 혹시라도 아저씨가...",
            ["DialogueId"] = 51009617,
            ["GUID"] = "7FB27D4A",
            ["NextDialogue"] = 51009618,
            ["SpeakNpcId"] = 700303,
            },
        [51009618] = {
            ["Camera"] = "-195.67627,-36.560547,82.240234,0.00003,-0.800662,3.794627,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那里太危险了，我不能带一个小孩子去。如果找到了，我会带他回来。你在这里等着就好。",
            ["ContentKR"] = "거긴 너무 위험해서 어린애는 못 데려가니까, 넌 여기서 기다리고 있어. 가서 찾으면 꼭 모시고 올게.",
            ["DialogueId"] = 51009618,
            ["FacialId"] = {
                [1] = "100001:Confident01",
                },
            ["GUID"] = "7FB27D74",
            ["NextDialogue"] = 51009619,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700303:Explain02_End",
                [2] = "100001:Disagree",
                },
            },
        [51009619] = {
            ["Camera"] = "231.359863,-211.90625,128.92334,0.000026,-9.600595,128.990936,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "唔，好吧……那就麻烦你了！",
            ["ContentKR"] = "으, 알겠어... 그럼 부탁할게!",
            ["DialogueId"] = 51009619,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["GUID"] = "7FB27D9E",
            ["NextDialogue"] = 51009620,
            ["SpeakNpcId"] = 700303,
            },
        [51009620] = {
            ["Camera"] = "-195.67627,-36.560547,82.240234,0.00003,-0.800662,3.794627,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "多纳特……他是怎样一个人？",
            ["ContentKR"] = "도나트 씨에 대해... 말해 줄래?",
            ["DialogueId"] = 51009620,
            ["FacialId"] = {
                [1] = "100001:Doubt01",
                },
            ["GUID"] = "7FB27DC8",
            ["NextDialogue"] = 51009621,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_Start",
                },
            },
        [51009621] = {
            ["Camera"] = "231.359863,-211.90625,128.92334,0.000026,-9.600595,128.990936,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "多纳特大叔是全冰湖城最好心的人！",
            ["ContentKR"] = "도나트 아저씨는 아이스레이크 시티에서 제일 좋은 분이야!",
            ["DialogueId"] = 51009621,
            ["GUID"] = "7FB27DF2",
            ["NextDialogue"] = 51009622,
            ["SpeakNpcId"] = 700303,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_End",
                [2] = "700303:Confident_Start",
                },
            },
        [51009622] = {
            ["Content"] = "他总是把吃的分给我们，还会拿钱给雾区的孩子买新衣服和书本。",
            ["ContentKR"] = "항상 먹을 걸 나눠 주시거든. 안개 구역 아이들한테 새 옷이랑 책 사라고 돈도 주셔.",
            ["DialogueId"] = 51009622,
            ["GUID"] = "7FB27E1C",
            ["NextDialogue"] = 51009623,
            ["SpeakNpcId"] = 700303,
            },
        [51009623] = {
            ["Content"] = "他还经常帮大家修补房屋和家具，给受伤的人送去药物，在大雪天收留无家可归的乞丐……贫民窟的每个人几乎都得到过他的帮助。",
            ["ContentKR"] = "사람들 집이랑 가구도 고쳐 주시고, 다친 사람한테 약도 가져다주시고, 눈이 펑펑 오는 날엔 갈 곳 없는 사람들을 거둬 주시기도 해... 빈민가 사람들은 거의 다 아저씨한테 도움을 받았다고 보면 돼.",
            ["DialogueId"] = 51009623,
            ["GUID"] = "7FB27E46",
            ["NextDialogue"] = 51009624,
            ["SpeakNpcId"] = 700303,
            },
        [51009624] = {
            ["Content"] = "还有还有——",
            ["ContentKR"] = "그리고 또...",
            ["DialogueId"] = 51009624,
            ["GUID"] = "7FB27E70",
            ["NextDialogue"] = 51009625,
            ["SpeakNpcId"] = 700303,
            },
        [51009625] = {
