            ["Content"] = "……呃，我的意思是，他长什么样？",
            ["ContentKR"] = "...음, 그게 아니라, 어떻게 생기셨어?",
            ["DialogueId"] = 51009625,
            ["FacialId"] = {
                [1] = "100001:Smile02",
                },
            ["GUID"] = "7FB27E9A",
            ["NextDialogue"] = 51009626,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Sigh_Start",
                },
            },
        [51009626] = {
            ["Camera"] = "47.982422,-602.043945,9.373535,0.00001,7.999701,87.596718,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哎？噢噢……对不起。",
            ["ContentKR"] = "어? 아차... 미안해.",
            ["DialogueId"] = 51009626,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["GUID"] = "7FB27EC4",
            ["NextDialogue"] = 51009627,
            ["SpeakNpcId"] = 700303,
            ["TalkActionId"] = {
                [1] = "100001:Sigh_End",
                [2] = "700303:Explain02_Start",
                },
            },
        [51009627] = {
            ["Content"] = "大叔四十岁出头，棕色头发，高高瘦瘦的……穿着很旧的衣服。",
            ["ContentKR"] = "마흔 좀 넘으셨고, 갈색 머리에, 키는 크고 마른 편이셔... 엄청 낡은 옷을 입고 계실 거야.",
            ["DialogueId"] = 51009627,
            ["GUID"] = "7FB27EEE",
            ["NextDialogue"] = 51009628,
            ["SpeakNpcId"] = 700303,
            },
        [51009628] = {
            ["Camera"] = "-195.67627,-36.560547,82.240234,0.00003,-0.800662,3.794627,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "好，我记住了。",
            ["ContentKR"] = "알겠어, 기억해 둘게. ",
            ["DialogueId"] = 51009628,
            ["FacialId"] = {
