            ["GUID"] = "7FB29124",
            ["NextDialogue"] = 51009739,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain01_Start",
                },
            },
        [51009739] = {
            ["Content"] = "我明白，你在疑惑。",
            ["ContentKR"] = "알아요, 의심스러운 거.",
            ["DialogueId"] = 51009739,
            ["GUID"] = "7FB2914E",
            ["NextDialogue"] = 51009740,
            ["SpeakNpcId"] = 700309,
            },
        [51009740] = {
            ["Content"] = "每个人都认为一只木箱不应该说话，就像他们记忆中那个只会响起回音的树洞一样。但是扪心自问，谁不想要一个会说话的木箱呢？",
            ["ContentKR"] = "옹이구멍처럼 메아리나 울려 퍼지면 모를까, 상자가 말할 리 없다고 생각하는 거죠. 그렇지만 솔직히 말해서, 말하는 상자를 마다할 사람이 있나요?",
            ["DialogueId"] = 51009740,
            ["GUID"] = "7FB29178",
            ["NextDialogue"] = 51009741,
            ["SpeakNpcId"] = 700309,
            },
        [51009741] = {
            ["Content"] = "既然你没有第一时间掀开我，说明你还是希望会有一只木箱陪你说说话不是吗？",
            ["ContentKR"] = "당신이 바로 절 열어 보지 않은 것도, 내심 상자가 말을 걸어 줬으면 하는 마음이 있어서 아닐까요?",
            ["DialogueId"] = 51009741,
