            ["NextDialogue"] = 51010206,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510102/7FB2DD98",
            },
        [51010205] = {
            ["Content"] = "很抱歉打扰到你！不过我问过那边的士兵，这座城市的广场并没有张贴律令，禁止一位吟游诗人在这里唱歌。",
            ["ContentKR"] = "방해가 됐다면 미안해! 그런데 저 병사분께 물어봤을 땐, 이 도시엔 광장에서 음유시인이 노래하면 안 된다는 법은 없다고 했어.",
            ["DialogueId"] = 51010205,
            ["GUID"] = "7FB2DDC2",
            ["NextDialogue"] = 51010206,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510102/7FB2DDC2",
