            ["DialogueId"] = 51103056,
            ["GUID"] = "7FEE5D2B",
            ["NextDialogue"] = 51103014,
            ["SpeakNpcId"] = 100001,
            },
        [51104001] = {
            ["Content"] = "小仆从小仆从，听我说！锦鲤皎皎告诉了本魔王一个天大的秘密——",
            ["ContentKR"] = "시종, 내 말 좀 들어 봐! 행운아 루나가 이 마왕님한테 엄청난 비밀을 얘기해 줬어...",
            ["DialogueId"] = 51104001,
            ["GUID"] = "7FEEFA2A",
            ["NextDialogue"] = 51104002,
            ["SpeakNpcId"] = 700324,
            },
        [51104002] = {
            ["Content"] = "整个烟津渡最好吃最地道的小吃，就藏在这个码头的摊子里！这可是只有本地人才能知道的秘密，一般人她才不告诉！",
            ["ContentKR"] = "연진 나루터의 진짜 맛집은 바로 이 나루터에 있는 노점이래! 여기 토박이가 아니면 절대 모르는 극비 정보고, 아무한테나 알려주는 게 아니래!",
            ["DialogueId"] = 51104002,
            ["GUID"] = "7FEEFA54",
            ["NextDialogue"] = 51104003,
            ["SpeakNpcId"] = 700324,
            },
        [51104003] = {
            ["Content"] = "就是前面的桂花糕摊位了，我们赶紧去看看吧！",
            ["ContentKR"] = "바로 저 앞에 있는 계화떡 노점이야! 빨리 가 보자!",
            ["DialogueId"] = 51104003,
            ["GUID"] = "7FEEFA7E",
            ["SpeakNpcId"] = 700324,
            },
