            ["TalkActionId"] = {
                [1] = "700326:Talk01_End",
                },
            },
        [51104011] = {
            ["Content"] = "我不管！今天吃不到桂花糕我就不回去了，到时候阿娘一着急你就惨咯。",
            ["ContentKR"] = "몰라, 몰라! 오늘 계화떡 안 사 주면, 나 집에 안 가. 그럼 엄만 형만 혼내겠지!",
            ["DialogueId"] = 51104011,
