            },
        [51105092] = {
            ["Camera"] = "-93.003906,-42.301758,148.769531,0.000082,-13.200105,37.594505,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "萍萍，中午了，我们看会书吧。",
            ["ContentKR"] = "평아, 점심 때가 됐구나. 같이 책을 읽자꾸나.",
            ["DialogueId"] = 51105092,
            ["GUID"] = "7FEF61B0",
            ["NextDialogue"] = 51105093,
            ["SpeakNpcId"] = 700331,
            },
        [51105093] = {
            ["Camera"] = "-8.46875,144.892578,124.898438,0.000009,2.799899,-77.20108,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "看来他把你认成了思萍奶奶，这大概是你奶奶的爷爷，辈分上应该是……？",
            ["ContentKR"] = "아무래도 저분은 널 네 할머니로 착각하고 계신 것 같아. 네 할머니의 할아버지라면, 아마 네...",
            ["DialogueId"] = 51105093,
            ["GUID"] = "7FEF61DA",
            ["NextDialogue"] = 51105094,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_End",
                },
            ["TurnTo"] = {
                [1] = "700329:n(100001)",
                },
            },
        [51105094] = {
            ["Camera"] = "-91.40625,-207.694824,175.608398,0.000038,-12.000027,61.9986,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "是灵灵的高祖父！以前，奶奶说我和她小时候长得很像，原来是真的……",
            ["ContentKR"] = "고조할아버지요! 예전에 할머니 말씀이 제가 할머니 어렸을 때랑 똑같이 생겼다고 그러셨는데, 진짜였나 봐요...",
            ["DialogueId"] = 51105094,
            ["GUID"] = "7FEF6204",
            ["NextDialogue"] = 51105095,
            ["SpeakNpcId"] = 700329,
            ["TalkActionId"] = {
                [1] = "700329:Explain01_Start",
                },
            },
        [51105095] = {
            ["Camera"] = "-91.40625,-207.694824,175.608398,0.000038,-12.000027,61.9986,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "原来，奶奶也不是天生的奶奶，她也有疼爱她的长辈……",
            ["ContentKR"] = "할머니도 태어날 때부터 할머니는 아니었던 거네요. 할머니한테도 할머니를 아끼고 사랑해 주시던 할아버지가 계셨던 거예요...",
            ["DialogueId"] = 51105095,
            ["GUID"] = "7FEF622E",
            ["NextDialogue"] = 51105096,
            ["SpeakNpcId"] = 700329,
            ["TalkActionId"] = {
                [1] = "700329:Explain01_End",
                },
            },
        [51105096] = {
            ["Camera"] = "-93.003906,-42.301758,148.769531,0.000082,-13.200105,37.594505,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "萍萍，你什么时候回来的？",
            ["ContentKR"] = "평아, 언제 돌아온 게냐?",
            ["DialogueId"] = 51105096,
            ["GUID"] = "7FEF6258",
            ["NextDialogue"] = 51105097,
            ["SpeakNpcId"] = 700331,
            ["TurnTo"] = {
                [1] = "700329:n(700331)",
                },
            },
        [51105097] = {
            ["Camera"] = "-49.523438,-67.03125,140.350586,0.000003,-9.599905,56.198746,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……我从来没见过高祖父，据说他在奶奶年轻的时候去世了，那时奶奶刚刚搬到皓京。因为没能及时收到消息，奶奶错过了见他的最后一面……",
            ["ContentKR"] = "...전 한 번도 뵌 적이 없지만, 고조할아버지는 할머니가 젊었을 때 돌아가셨다고 했어요. 그때 할머니께선 호경으로 이사 간 지 얼마 안 돼서, 소식을 늦게 받는 바람에, 고조할아버지의 마지막을 지키지 못하셨대요...",
            ["DialogueId"] = 51105097,
            ["FacialId"] = {
                [1] = "700329:Sad01",
                },
            ["GUID"] = "7FEF6282",
            ["NextDialogue"] = 51105098,
            ["SpeakNpcId"] = 700329,
            },
        [51105098] = {
            ["Camera"] = "-8.46875,144.892578,124.898438,0.000009,2.799899,-77.20108,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "所以，他变成了无由生，一直在等萍萍回来。",
            ["ContentKR"] = "그래서, 너희 고조할아버지는 무유생이 돼서 계속 너희 할머니를 기다리고 계셨던 거구나.",
            ["DialogueId"] = 51105098,
            ["GUID"] = "7FEF62AC",
            ["NextDialogue"] = 51105099,
