            ["ImprPlusId"] = 1206,
            ["NextDialogue"] = 51105902,
            },
        [51105902] = {
            ["Content"] = "嗯？不行不行，没人说过奇遇还能跟别人分的啊？",
            ["ContentKR"] = "네? 아뇨, 그건 안 되죠. 기연을 나눈다는 이야기는 처음 듣는걸요.",
