            ["DialogueId"] = 51105905,
            ["GUID"] = "7FF0328A",
            ["ImprPlusId"] = 1208,
            ["NextDialogue"] = 51105906,
            },
        [51105906] = {
            ["Content"] = "啊？那是什么？",
