            ["DialogueId"] = 51105906,
            ["GUID"] = "7FF032B4",
            ["NextDialogue"] = 51105907,
            ["SpeakNpcId"] = 701005,
            ["TalkActionId"] = {
                [1] = "701005:Talk02_Start",
                },
            },
        [51105907] = {
            ["Content"] = "呃，一种游戏形式？扮演故事里的角色一起互动……你小时候没这么玩过吗？",
            ["ContentKR"] = "음, 일종의 놀이인데요, 이야기 속 등장인물 흉내를 내면서 노는... 어렸을 때 안 해 보셨어요?",
            ["DialogueId"] = 51105907,
            ["GUID"] = "7FF032DE",
            ["NextDialogue"] = 51105908,
            ["SpeakNpcId"] = 100001,
            },
        [51105908] = {
            ["Content"] = "扮演？不不不，要来当然就来真的，扮演多没意思。",
