            ["GUID"] = "7FF03332",
            ["ImprPlusId"] = 1210,
            ["NextDialogue"] = 51105910,
            },
        [51105910] = {
            ["Content"] = "果真如此？！我就知道自己一定有天命加身！",
            ["ContentKR"] = "그렇습니까? 역시 하늘의 뜻은 제게 있었군요!",
            ["DialogueId"] = 51105910,
