            },
        [51109027] = {
            ["Content"] = "（面前的老人抹干净了眼泪，抬起疲惫的双眼看着你。）",
            ["ContentKR"] = "(노인은 눈물을 훔친 후, 지친 기색이 역력한 눈으로 나를 본다.)",
            ["DialogueId"] = 51109027,
            ["GUID"] = "7FF232BE",
            ["NextDialogue"] = 51109028,
            },
        [51109028] = {
            ["Content"] = "不好意思哈，让你在我们这两个老家伙身上耽误时间了。你忙去吧，我带老婆子在附近转转，再散会心。",
            ["ContentKR"] = "괜히 시간 뺏어서 미안했네. 난 집사람하고 바람이나 조금 더 쐬다 들어갈 테니, 자네는 얼른 가 보게.",
            ["DialogueId"] = 51109028,
            ["GUID"] = "7FF232E8",
            ["NextDialogue"] = 51109029,
            ["SpeakNpcId"] = 701009,
            },
        [51109029] = {
            ["Content"] = "嗯……",
            ["ContentKR"] = "네...",
            ["DialogueId"] = 51109029,
            ["GUID"] = "7FF23312",
            ["NextDialogue"] = 51109030,
            ["SpeakNpcId"] = 100001,
            },
        [51109030] = {
            ["Content"] = "（程老头扶着程夫人向远方走去，如同两片干枯的落叶，被广阔的地平线掩埋，最终消失在了视线的尽头。）",
            ["ContentKR"] = "(정씨 할아버지가 아내를 부축해 먼 곳으로 떠난다. 마치 광활한 지평선이 메마른 낙엽 한 쌍을 집어삼키듯, 두 노인의 뒷모습이 시야에서 점점 멀어진다.)",
            ["DialogueId"] = 51109030,
            ["GUID"] = "7FF2333C",
            },
        [51109031] = {
            ["Content"] = "于理来说，我们不该这么自私……但心里这难过的念头，不是讲讲道理就能消失啊……",
            ["ContentKR"] = "이기적인 마음이라는 거 아네... 그렇지만 아무리 우리가 틀렸다고 해도, 가슴에 맺힌 응어리를 어찌하겠는가...",
            ["DialogueId"] = 51109031,
            ["GUID"] = "7FF23366",
            ["SpeakNpcId"] = 701009,
            },
        [51110000] = {
            ["Content"] = "嗷呜，吼……嗷呜呜呜！",
            ["ContentKR"] = "아우, 크앙... 크르르르!",
            ["DialogueId"] = 51110000,
            ["GUID"] = "7FF2D260",
            ["NextOptions"] = {
                [1] = 51110001,
                [2] = 51110002,
                [3] = 51110003,
                },
            ["SpeakNpcId"] = 701011,
            },
        [51110001] = {
            ["Content"] = "好孩子不能到处乱咬人。",
            ["ContentKR"] = "착한 어린이는 사람 무는 거 아니야.",
            ["DialogueId"] = 51110001,
            ["GUID"] = "7FF2D28A",
            ["ImprPlusId"] = 1207,
            ["NextDialogue"] = 51110004,
            },
        [51110002] = {
            ["Content"] = "（离远点，别是有什么病吧。）",
            ["ContentKR"] = "(얘 어디 아픈가? 멀리 떨어져 있자.)",
            ["DialogueId"] = 51110002,
            ["GUID"] = "7FF2D2B4",
            ["ImprPlusId"] = 1206,
            ["NextDialogue"] = 51110004,
            },
        [51110003] = {
            ["Content"] = "嗷嗷！嗷嗷嗷嗷嗷！",
            ["ContentKR"] = "크르릉! 크르르르르릉!",
            ["DialogueId"] = 51110003,
            ["GUID"] = "7FF2D2DE",
            ["ImprPlusId"] = 1210,
            ["NextDialogue"] = 51110004,
            },
        [51110004] = {
            ["Content"] = "你干嘛呀！我这可是为了成为狴犴而做的修行呢！",
            ["ContentKR"] = "뭐 하는 거야! 난 훌륭한 폐안이 되려고 수행 중이라고!",
            ["DialogueId"] = 51110004,
            ["GUID"] = "7FF2D308",
            ["LookAt"] = {
                [1] = "701011:n(0)",
                },
            ["NextOptions"] = {
                [1] = 51110005,
                },
            ["RestartTag"] = 51110004,
            ["SpeakNpcId"] = 701011,
            },
        [51110005] = {
            ["Content"] = "你……不是有龙氏吧，抟土氏是做不成狴犴的。",
            ["ContentKR"] = "넌... 용의 자손이 아니잖아. 땅의 자손은 폐안이 될 수 없어.",
            ["DialogueId"] = 51110005,
            ["FailDialogue"] = 51110006,
            ["GUID"] = "7FF2D332",
            ["ImprCheckId"] = 1121,
            ["NextDialogue"] = 51110008,
            },
        [51110006] = {
            ["Content"] = "嗷呜——",
            ["ContentKR"] = "크르르릉!!",
            ["DialogueId"] = 51110006,
            ["GUID"] = "7FF2D35C",
            ["NextDialogue"] = 51110007,
            ["SpeakNpcId"] = 701011,
            ["TalkActionId"] = {
                [1] = "701011:Angry01_Start",
                },
            },
        [51110007] = {
            ["Content"] = "（面前的小孩好像没有听到你的话一样，继续趴在地上嚎叫着。）",
            ["ContentKR"] = "(아이는 나의 말을 들은 체 만 체하며, 계속 바닥에 엎드려 울부짖는다.)",
            ["DialogueId"] = 51110007,
            ["GUID"] = "7FF2D386",
            ["TalkActionId"] = {
                [1] = "701011:Angry01_End",
                },
            },
        [51110008] = {
            ["Content"] = "华胥有句古话，叫做功夫不负有心人，白龙神君看我这么努力，肯定不会辜负我的！",
            ["ContentKR"] = "옛말에 지성이면 감천이라는 말이 있어! 백룡신군께서도 내가 이렇게 열심히 하는 걸 보시면, 감동해서 소원을 들어주실 거야!",
            ["DialogueId"] = 51110008,
            ["GUID"] = "7FF2D3B0",
            ["NextDialogue"] = 51110009,
            ["SpeakNpcId"] = 701011,
            ["TalkActionId"] = {
                [1] = "701011:Talk01_Start",
                },
            },
        [51110009] = {
            ["Content"] = "……",
            ["ContentKR"] = "......",
            ["DialogueId"] = 51110009,
            ["GUID"] = "7FF2D3DA",
            ["NextDialogue"] = 51110010,
            ["SpeakNpcId"] = 100001,
            },
        [51110010] = {
            ["Content"] = "等我成了威风凛凛的狴犴，一定每天都在烟津渡来回巡逻，然后把所有坏家伙都绳之以法！想想就觉得好酷！",
            ["ContentKR"] = "난 위풍당당한 폐안이 되면, 매일 연진 나루터를 순찰하면서, 나쁜 녀석들을 싹 다 잡아 혼내 줄 거야! 생각만 해도 진짜 멋져!",
            ["DialogueId"] = 51110010,
            ["GUID"] = "7FF2D404",
            ["NextDialogue"] = 51110011,
            ["SpeakNpcId"] = 701011,
            },
        [51110011] = {
            ["Content"] = "……哇，你竟然没有要说教我的意思，不像别的大人一样扫兴。那正好来看看我修行的成果吧！",
            ["ContentKR"] = "...와, 넌 다른 어른들처럼 안 된다고 하면서 잔소리 안 하네? 그럼 내 수련 성과를 보여 줄게!",
            ["DialogueId"] = 51110011,
            ["GUID"] = "7FF2D42E",
            ["NextDialogue"] = 51110012,
            ["SpeakNpcId"] = 701011,
            },
        [51110012] = {
            ["Content"] = "首先，要成为狴犴去打坏人，那肯定得有健美的肌肉。你看看我练得怎么样？",
            ["ContentKR"] = "일단, 폐안이 돼서 나쁜 놈들을 혼내 주려면, 멋진 근육이 있어야 하잖아? 내 근육, 어때?",
            ["DialogueId"] = 51110012,
            ["GUID"] = "7FF2D458",
            ["NextDialogue"] = 51110013,
            ["SpeakNpcId"] = 701011,
            },
        [51110013] = {
            ["Content"] = "（小孩说着握紧拳头举起了胳膊，但你透过衣服，只能看到一点点起伏。）",
            ["ContentKR"] = "(아이가 주먹을 꽉 쥐고 팔을 들어 올리지만, 옷 위로는 보이는 건 미세한 굴곡뿐이다.)",
            ["DialogueId"] = 51110013,
            ["GUID"] = "7FF2D482",
            ["NextOptions"] = {
                [1] = 51110014,
                [2] = 51110015,
                [3] = 51110016,
                },
            ["TalkActionId"] = {
                [1] = "701011:Talk01_End",
                },
            },
        [51110014] = {
            ["Content"] = "嗯……很棒的肱二头肌。",
            ["ContentKR"] = "음... 이두박근이 엄청난데.",
            ["DialogueId"] = 51110014,
            ["GUID"] = "7FF2D4AC",
            ["ImprPlusId"] = 1209,
            ["NextDialogue"] = 51110017,
            },
        [51110015] = {
            ["Content"] = "还得多练。",
            ["ContentKR"] = "더 열심히 해야겠는데.",
            ["DialogueId"] = 51110015,
            ["GUID"] = "7FF2D4D6",
            ["ImprPlusId"] = 1207,
            ["NextDialogue"] = 51110017,
            },
        [51110016] = {
            ["Content"] = "噗……",
            ["ContentKR"] = "풉...",
            ["DialogueId"] = 51110016,
            ["GUID"] = "7FF2D500",
            ["ImprPlusId"] = 1210,
            ["NextDialogue"] = 51110017,
            },
        [51110017] = {
            ["Content"] = "我，我还小，肌肉早晚会有的！我之前主要练的是速度，看我给你秀一手。",
            ["ContentKR"] = "나, 난 아직 어리잖아! 근육은 나중에 다 생기게 돼 있어! 사실 내가 주로 연습한 건 속도니까, 한번 보여 줄게.",
            ["DialogueId"] = 51110017,
            ["GUID"] = "7FF2D52A",
            ["NextDialogue"] = 51110018,
            ["SpeakNpcId"] = 701011,
            ["TalkActionId"] = {
                [1] = "701011:Talk02_Start",
                },
            },
        [51110018] = {
            ["Content"] = "（小孩说完突然趴倒在地，手脚并用地飞快爬行，扬起一层层的尘沙。）",
            ["ContentKR"] = "(아이는 말이 끝나기 무섭게 바닥에 엎드리더니, 손발로 흙먼지를 일으키며 기어다니기 시작한다.)",
            ["DialogueId"] = 51110018,
            ["GUID"] = "7FF2D554",
            ["NextDialogue"] = 51110019,
            },
        [51110019] = {
            ["Content"] = "咳咳咳。",
            ["ContentKR"] = "콜록, 콜록콜록.",
            ["DialogueId"] = 51110019,
            ["GUID"] = "7FF2D57E",
            ["NextDialogue"] = 51110020,
            ["SpeakNpcId"] = 100001,
            },
        [51110020] = {
            ["Content"] = "怎么样，这可是我的绝招，叫做狴犴乘风而行——是不是有点感觉了？",
            ["ContentKR"] = "어때? 내 필살기 '폐안님이 나가신다'! 느낌 좀 오지 않아?",
            ["DialogueId"] = 51110020,
            ["GUID"] = "7FF2D5A8",
            ["NextOptions"] = {
                [1] = 51110021,
                [2] = 51110022,
                [3] = 51110023,
                },
            ["SpeakNpcId"] = 701011,
            ["TalkActionId"] = {
                [1] = "701011:Talk02_End",
                },
            },
        [51110021] = {
            ["Content"] = "嗯……快的都看不到影了。",
            ["ContentKR"] = "음... 너무 빨라서 보이지도 않더라.",
            ["DialogueId"] = 51110021,
            ["GUID"] = "7FF2D5D2",
            ["ImprPlusId"] = 1209,
            ["NextDialogue"] = 51110024,
            },
        [51110022] = {
            ["Content"] = "还得多练。",
            ["ContentKR"] = "더 열심히 해야겠는데.",
            ["DialogueId"] = 51110022,
            ["GUID"] = "7FF2D5FC",
            ["ImprPlusId"] = 1207,
            ["NextDialogue"] = 51110024,
            },
        [51110023] = {
            ["Content"] = "噗……咳，我想起了一些高兴的事。",
            ["ContentKR"] = "풉... 크흠, 갑자기 웃긴 일이 생각나서 그랬어.",
            ["DialogueId"] = 51110023,
            ["GUID"] = "7FF2D626",
            ["ImprPlusId"] = 1210,
            ["NextDialogue"] = 51110024,
            },
        [51110024] = {
            ["Content"] = "哼哼，除了这些，我最近还在练习狴犴的叫声哦，嗷嗷——",
            ["ContentKR"] = "흥! 나 이거 말고도 요즘엔 폐안 울음소리도 연습하고 있어! 크르르릉~",
            ["DialogueId"] = 51110024,
            ["GUID"] = "7FF2D650",
            ["NextDialogue"] = 51110025,
            ["SpeakNpcId"] = 701011,
            ["TalkActionId"] = {
                [1] = "701011:Confident_Start",
                },
            },
        [51110025] = {
            ["Content"] = "（小孩突然嚎叫了起来，想来这就是他之前趴在地上怪叫的原因。）",
            ["ContentKR"] = "(아이가 갑자기 괴성을 지르기 시작한다. 아이가 조금 전에 바닥에 엎드려 내던 소리가 이거였나 보다.)",
            ["DialogueId"] = 51110025,
            ["GUID"] = "7FF2D67A",
            ["NextDialogue"] = 51110026,
            },
        [51110026] = {
            ["Content"] = "嗷嗷嗷……",
            ["ContentKR"] = "크르릉...",
            ["DialogueId"] = 51110026,
            ["GUID"] = "7FF2D6A4",
            ["NextDialogue"] = 51110027,
            ["SpeakNpcId"] = 701011,
            },
        [51110027] = {
            ["Content"] = "我说……",
            ["ContentKR"] = "저기...",
            ["DialogueId"] = 51110027,
            ["GUID"] = "7FF2D6CE",
            ["NextDialogue"] = 51110028,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "701011:Confident_End",
                },
            },
        [51110028] = {
            ["Content"] = "嗷哦哦哦哦哦……",
            ["ContentKR"] = "크르르르르르릉...",
            ["DialogueId"] = 51110028,
            ["GUID"] = "7FF2D6F8",
            ["NextDialogue"] = 51110029,
            ["SpeakNpcId"] = 701011,
            ["TalkActionId"] = {
                [1] = "701011:Angry01_Start",
                },
            },
        [51110029] = {
            ["Content"] = "（小孩忘我地嚎叫了起来，无论你怎么搭话都不再回应，最后你只得默默走开，离这位“小狴犴”越远越好。）",
            ["ContentKR"] = "(아이는 아무리 말을 걸어도 대답은커녕, 무아지경에 빠져 울부짖는다. 결국 나는 이 '꼬마 폐안'에게서 멀리 떨어지기 위해 조용히 자리를 뜬다.)",
            ["DialogueId"] = 51110029,
            ["GUID"] = "7FF2D722",
            ["TalkActionId"] = {
                [1] = "701011:Angry01_End",
                },
            },
        [51110030] = {
            ["Content"] = "嗷呜——怎么样，是不是真以为狴犴来了呀。",
            ["ContentKR"] = "크르르릉... 어때? 진짜 폐안이 나타난 줄 알았지?",
            ["DialogueId"] = 51110030,
            ["GUID"] = "7FF2D74C",
            ["SpeakNpcId"] = 701011,
            },
        [51111000] = {
            ["Content"] = "呕呕呕呕……啊啊啊不用了不用了我真吃不下了。",
            ["ContentKR"] = "우욱, 우우욱... 으아아, 아니에요, 그만요, 저 더는 못 먹겠어요.",
            ["DialogueId"] = 51111000,
            ["GUID"] = "7FF37670",
            ["NextDialogue"] = 51111001,
            ["SpeakNpcId"] = 701012,
            ["TalkActionId"] = {
                [1] = "701012:Sigh_Start",
                },
            },
        [51111001] = {
            ["Content"] = "呼……吓我一跳，原来不是织星客啊。",
            ["ContentKR"] = "휴... 깜짝이야. 별을 잇는 자가 아니었군요.",
            ["DialogueId"] = 51111001,
            ["GUID"] = "7FF3769A",
            ["NextOptions"] = {
                [1] = 51111002,
                [2] = 51111004,
                },
            ["SpeakNpcId"] = 701012,
            },
        [51111002] = {
            ["Content"] = "织星客……吃……是他们逼你吃什么东西了吗？",
            ["ContentKR"] = "그 반응은... 별을 잇는 자들이 억지로 뭘 먹이기라도 한 거예요?",
            ["DialogueId"] = 51111002,
            ["GUID"] = "7FF376C4",
            ["ImprPlusId"] = 1208,
            ["NextDialogue"] = 51111003,
            },
        [51111003] = {
            ["Content"] = "没，没有，都是我自愿的……",
            ["ContentKR"] = "아뇨, 그건 아니고, 다 제가 원해서 먹은 거긴 해요...",
            ["DialogueId"] = 51111003,
            ["GUID"] = "7FF376EE",
            ["NextDialogue"] = 51111006,
            ["SpeakNpcId"] = 701012,
            },
        [51111004] = {
            ["Content"] = "你好，我是织星客帝国分客。",
            ["ContentKR"] = "안녕하세요, 전 제국 지부 소속의 별을 잇는 자예요.",
            ["DialogueId"] = 51111004,
            ["GUID"] = "7FF37718",
            ["ImprPlusId"] = 1210,
            ["NextDialogue"] = 51111005,
            },
        [51111005] = {
            ["Content"] = "呃啊啊……只要不是吃饭，那就什么都好说。",
            ["ContentKR"] = "으아아... 다른 건 다 괜찮으니까, 제발 같이 밥 먹자는 소리는 하지 말아 줘요.",
            ["DialogueId"] = 51111005,
            ["GUID"] = "7FF37742",
            ["NextDialogue"] = 51111006,
            ["SpeakNpcId"] = 701012,
            ["TalkActionId"] = {
                [1] = "701012:Sigh_End",
                },
            },
        [51111006] = {
            ["Content"] = "所以这是怎么了？",
            ["ContentKR"] = "대체 무슨 일이 있었길래 그래요?",
            ["DialogueId"] = 51111006,
            ["GUID"] = "7FF3776C",
            ["NextDialogue"] = 51111007,
            ["SpeakNpcId"] = 100001,
            },
        [51111007] = {
            ["Content"] = "我叫萨米，是跟着织星客来到华胥的赫墨行商。",
            ["ContentKR"] = "제 이름은 사미예요. 케메트의 행상인인데, 별을 잇는 자들을 따라서 화서에 왔죠.",
            ["DialogueId"] = 51111007,
            ["GUID"] = "7FF37796",
            ["NextDialogue"] = 51111008,
            ["SpeakNpcId"] = 701012,
            },
        [51111008] = {
            ["Content"] = "我本来是想找织星客们谈谈香料生意的，结果来烟津渡一周多，生意没怎么谈，天天光吃饭了。",
            ["ContentKR"] = "별을 잇는 자들이랑 향료 거래를 해 보려고 온 건데, 연진 나루터에 온 지 일주일이 넘게 사업 얘기는커녕, 매일같이 밥만 먹고 있어요.",
            ["DialogueId"] = 51111008,
            ["GUID"] = "7FF377C0",
            ["NextDialogue"] = 51111009,
            ["SpeakNpcId"] = 701012,
            ["TalkActionId"] = {
                [1] = "701012:Explain01_Start",
                },
            },
        [51111009] = {
            ["Content"] = "要我说，华胥这边的人对吃也太执着了！每天一睁眼就吃早餐，泡一壶茶喝到中午无缝衔接到午餐。",
            ["ContentKR"] = "여기 사람들은요, 먹는 데 너무 진심이에요! 눈 뜨자마자 아침 먹고, 차 좀 마시다 보면 점심때 돼서 또 점심 먹어야 해요.",
            ["DialogueId"] = 51111009,
            ["GUID"] = "7FF377EA",
            ["NextDialogue"] = 51111010,
            ["SpeakNpcId"] = 701012,
            },
        [51111010] = {
            ["Content"] = "午餐吃完想着好不容易能歇一会了，结果又有人端来一大盘点心和水果，好不容易吃完又到了晚餐时间。",
            ["ContentKR"] = "점심 다 먹고 이제 좀 쉬나 싶으면, 또 누가 과일이랑 간식을 잔뜩 들고 온다니까요. 간신히 다 먹었다 싶으면 또 저녁 시간이고요.",
            ["DialogueId"] = 51111010,
            ["GUID"] = "7FF37814",
            ["NextDialogue"] = 51111011,
            ["SpeakNpcId"] = 701012,
            },
        [51111011] = {
            ["Content"] = "晚餐结束后快睡觉了，又有人敲门喊我出去吃宵夜。",
            ["ContentKR"] = "저녁 식사 끝나고 이제 자야겠다 싶으면, 또 누가 와서 야식 먹으러 가자고 불러요.",
            ["DialogueId"] = 51111011,
            ["GUID"] = "7FF3783E",
            ["NextDialogue"] = 51111012,
            ["SpeakNpcId"] = 701012,
            ["TalkActionId"] = {
                [1] = "701012:Explain01_End",
                },
            },
        [51111012] = {
            ["Content"] = "呕呃……光想想就又要吐了……",
            ["ContentKR"] = "우우욱... 생각만 해도 속이...",
            ["DialogueId"] = 51111012,
            ["GUID"] = "7FF37868",
            ["NextDialogue"] = 51111013,
            ["SpeakNpcId"] = 701012,
            ["TalkActionId"] = {
                [1] = "701012:Sigh_Start",
                },
            },
        [51111013] = {
            ["Content"] = "你为什么不直接说吃不下了呢？",
            ["ContentKR"] = "그냥 더 못 먹겠다고 하면 되는 거 아니에요?",
            ["DialogueId"] = 51111013,
            ["GUID"] = "7FF37892",
            ["NextDialogue"] = 51111014,
            ["SpeakNpcId"] = 100001,
            },
        [51111014] = {
            ["Content"] = "一开始不好意思，毕竟是华胥的主场。吃吐几次后我撑不下去了，鼓起勇气对他们说真吃饱了，结果……就发生了更恐怖的事……",
            ["ContentKR"] = "처음엔 성의가 있으니까 미안해서 말을 못 꺼냈어요. 그러다 속이 몇 번 뒤집어지고 나니까, 도저히 안 되겠다 싶어서, 진짜 배불러서 못 먹겠다고 했거든요... 그랬더니 더 무시무시한 일이 벌어졌어요...",
            ["DialogueId"] = 51111014,
            ["GUID"] = "7FF378BC",
            ["NextDialogue"] = 51111015,
            ["SpeakNpcId"] = 701012,
            },
        [51111015] = {
            ["Content"] = "那群织星客听完立马开始往我碗里夹菜，一边说有营养一边说别客气不用不好意思之类的，然后那顿饭我整整多吃了三大碗！",
            ["ContentKR"] = "제 얘기를 들은 별을 잇는 자들이 몸에 좋은 거다, 사양하지 마라, 부끄러워할 거 없다 이러면서 막 제 그릇에 반찬을 더 쌓아 주는 거예요! 그래서 결국 세 공기나 더 먹었다니까요!",
            ["DialogueId"] = 51111015,
            ["GUID"] = "7FF378E6",
            ["NextDialogue"] = 51111016,
            ["SpeakNpcId"] = 701012,
            },
        [51111016] = {
            ["Content"] = "呕……不行了，我去那边接着吐会……华胥人的热情……太沉重了，呕呕……",
            ["ContentKR"] = "우욱... 안 되겠어요. 저기 가서 마저 좀 게워 낼게요... 화서 사람들의 열정은... 정말 무시무시해요. 우우욱...",
            ["DialogueId"] = 51111016,
            ["GUID"] = "7FF37910",
            ["SpeakNpcId"] = 701012,
            ["TalkActionId"] = {
                [1] = "701012:Sigh_End",
                },
            },
        [51111017] = {
            ["Content"] = "呕……呼，呼……",
            ["ContentKR"] = "우욱... 우욱, 우웩...",
            ["DialogueId"] = 51111017,
            ["GUID"] = "7FF3793A",
            ["SpeakNpcId"] = 701012,
            },
        [51112000] = {
            ["Content"] = "抄家伙，我们走。",
            ["ContentKR"] = "연장 챙겨. 가자.",
            ["DialogueId"] = 51112000,
            ["GUID"] = "7FF41A80",
            ["NextDialogue"] = 51112001,
            ["SpeakNpcId"] = 701013,
            },
        [51112001] = {
            ["Content"] = "（刚一来到黑市，你就看到一帮人乌泱泱地走了出来。）",
            ["ContentKR"] = "(암시장에 도착하자마자, 안에서 한 무리의 사람들이 우르르 몰려나온다.)",
            ["DialogueId"] = 51112001,
            ["GUID"] = "7FF41AAA",
            ["NextDialogue"] = 51112002,
            },
        [51112002] = {
            ["Content"] = "（一位奄奄一息的黑市商人躺在他们身后，仔细一瞧，原来是那位用假契书诓骗无辜姑娘、并在对决中使诈的家伙。）",
            ["ContentKR"] = "(그 뒤로, 반죽음 상태가 된 암시장 상인이 쓰러져 있다. 자세히 보니, 가짜 계약서로 어떤 아가씨한테 사기를 치고, 대결에서도 수작을 부리던 그 인간이다.)",
            ["DialogueId"] = 51112002,
            ["GUID"] = "7FF41AD4",
            ["NextOptions"] = {
                [1] = 51112003,
                [2] = 51112004,
                [3] = 51112005,
                },
            },
        [51112003] = {
            ["Content"] = "你们抄家伙是要去做什么坏事！",
            ["ContentKR"] = "연장까지 챙겨 들고 대체 무슨 짓을 하려는 거야!",
            ["DialogueId"] = 51112003,
            ["GUID"] = "7FF41AFE",
            ["ImprPlusId"] = 1207,
            ["NextDialogue"] = 51112006,
            },
        [51112004] = {
            ["Content"] = "（他们的目标看起来并不是你，所以还是把路让开为好。）",
            ["ContentKR"] = "(아무래도 목표는 내가 아닌 것 같다. 그렇다면 빨리 길을 비켜 주는 편이 좋겠지.)",
            ["DialogueId"] = 51112004,
            ["GUID"] = "7FF41B28",
            ["ImprPlusId"] = 1206,
            ["NextDialogue"] = 51112006,
            },
        [51112005] = {
            ["Content"] = "呦，几天不见，这么惨了啊。",
            ["ContentKR"] = "이야, 며칠 사이에 꼴이 아주 말이 아니시네요?",
            ["DialogueId"] = 51112005,
            ["GUID"] = "7FF41B52",
            ["ImprPlusId"] = 1210,
            ["NextDialogue"] = 51112006,
            },
        [51112006] = {
            ["Content"] = "原来是虬先生的贵客，有失远迎。",
            ["ContentKR"] = "아, 규선생의 손님이셨군요. 조금 더 일찍 마중을 나올걸 그랬네요.",
            ["DialogueId"] = 51112006,
            ["GUID"] = "7FF41B7C",
            ["LookAt"] = {
                [1] = "701013:n(0)",
                },
            ["NextDialogue"] = 51112007,
            ["SpeakNpcId"] = 701013,
            },
        [51112007] = {
            ["Content"] = "（领头的男子见到你后，对着你微微作揖，展现出与这黑市格格不入的风度。）",
            ["ContentKR"] = "(우두머리로 보이는 남자가 두 손을 포개어 잡고 인사를 건넨다. 암시장과는 어울리지 않는 묘한 기품이 느껴진다.)",
            ["DialogueId"] = 51112007,
            ["GUID"] = "7FF41BA6",
            ["NextDialogue"] = 51112008,
            },
        [51112008] = {
            ["Content"] = "既已被你撞见，那我便把此事说清为好，以免再生误会。",
            ["ContentKR"] = "마주친 김에, 괜한 오해가 생기지 않게 설명해 드리죠.",
            ["DialogueId"] = 51112008,
            ["GUID"] = "7FF41BD0",
            ["NextDialogue"] = 51112009,
            ["SpeakNpcId"] = 701013,
            ["TalkActionId"] = {
                [1] = "701013:Explain01_Start",
                },
            },
        [51112009] = {
            ["Content"] = "（他看出了你眼中的疑惑，微微侧身指向躺在地上的那位黑市商人。）",
            ["ContentKR"] = "(남자는 의심스러워하는 나의 눈빛을 읽은 듯, 살짝 몸을 돌려 바닥에 쓰러져 있는 상인을 가리킨다.)",
            ["DialogueId"] = 51112009,
            ["GUID"] = "7FF41BFA",
            ["NextDialogue"] = 51112010,
            },
        [51112010] = {
            ["Content"] = "他不久前做生意吃了亏，与人家争执中恼羞成怒，动了手脚，遂招致狴犴惩戒，沦为这幅半死不活的模样。",
            ["ContentKR"] = "저자는 얼마 전에 사업에서 손해를 보곤 울컥해서 장난질을 했는데, 그게 폐안한테 걸려서 결국 저 꼴이 됐습니다.",
            ["DialogueId"] = 51112010,
            ["GUID"] = "7FF41C24",
            ["NextOptions"] = {
                [1] = 51112011,
                },
            ["RestartTag"] = 51112011,
            ["SpeakNpcId"] = 701013,
            },
        [51112011] = {
            ["Content"] = "所以……你要带着这一帮人去报复别人？",
            ["ContentKR"] = "그래서... 다 같이 우르르 몰려가서 저 사람 대신 복수하려는 건가요?",
            ["DialogueId"] = 51112011,
            ["FailDialogue"] = 51112012,
            ["GUID"] = "7FF41C4E",
            ["ImprCheckId"] = 1122,
            ["NextDialogue"] = 51112013,
            },
        [51112012] = {
            ["Content"] = "抱歉，无可奉告。",
            ["ContentKR"] = "죄송하지만, 그건 말씀드릴 수 없습니다.",
            ["DialogueId"] = 51112012,
            ["GUID"] = "7FF41C78",
            ["SpeakNpcId"] = 701013,
            },
        [51112013] = {
            ["Content"] = "呵呵，黑市从不会为了谁而去报复别人。愿赌服输，这是虬先生为黑市立下的规矩，也是他自己应该接受的现实。",
            ["ContentKR"] = "후후, 암시장은 의리로 대신 복수해 주는 곳이 아닙니다. \"도박판에 들어왔으면, 결과에 승복하라.\" 그게 규선생이 세운 규칙이고, 저자가 받아들여야 할 현실입니다.",
            ["DialogueId"] = 51112013,
            ["GUID"] = "7FF41CA2",
            ["NextDialogue"] = 51112014,
            ["SpeakNpcId"] = 701013,
            },
        [51112014] = {
            ["Content"] = "输了，那就独自承受后果。活不活得下来，活下来又当如何，与他人无关。",
            ["ContentKR"] = "졌으면, 뒷감당은 알아서 해야지요. 살아남는 것도, 살아남아서 뭘 할지도, 다 본인 사정인 겁니다.",
            ["DialogueId"] = 51112014,
            ["GUID"] = "7FF41CCC",
            ["NextDialogue"] = 51112015,
            ["SpeakNpcId"] = 701013,
            ["TalkActionId"] = {
                [1] = "701013:Explain01_End",
                },
            },
        [51112015] = {
            ["Content"] = "我还以为你们会更极端一些。",
            ["ContentKR"] = "솔직히 암시장 사람들은 좀 더 막 나갈 줄 알았어요.",
            ["DialogueId"] = 51112015,
            ["GUID"] = "7FF41CF6",
            ["NextDialogue"] = 51112016,
            ["SpeakNpcId"] = 100001,
            },
        [51112016] = {
            ["Content"] = "很多人都会有这样的误解，但黑市说到底也只是一个比较松散的组织。",
            ["ContentKR"] = "다들 그런 오해들을 하더군요. 하지만 암시장은 사실 생각보다 느슨한 조직입니다.",
            ["DialogueId"] = 51112016,
            ["GUID"] = "7FF41D20",
            ["NextDialogue"] = 51112017,
            ["SpeakNpcId"] = 701013,
            ["TalkActionId"] = {
                [1] = "701013:Talk01_Start",
                },
            },
        [51112017] = {
            ["Content"] = "最后能留下来的，只有不受秩序约束，并有能力承担相应后果的人。",
            ["ContentKR"] = "끝까지 남는 건, 질서에 얽매이지 않으면서도, 제 앞가림은 확실히 할 줄 아는 놈들뿐이죠.",
            ["DialogueId"] = 51112017,
            ["GUID"] = "7FF41D4A",
            ["NextDialogue"] = 51112018,
            ["SpeakNpcId"] = 701013,
            },
        [51112018] = {
            ["Content"] = "我们不怕输，吃完亏再爬起来便是。只怕那些输不起的人，顺风时践踏秩序，逆风时却乞求秩序的庇护，黑市的大门不对这种弱者敞开。",
            ["ContentKR"] = "지는 건 상관없습니다. 다시 털고 일어나면 그만이니까요. 하지만 제멋대로 굴다가, 질 때만 법 찾는 놈들이 문제입니다. 암시장에 그런 약해빠진 놈들을 위한 자리는 없습니다.",
            ["DialogueId"] = 51112018,
            ["GUID"] = "7FF41D74",
            ["NextDialogue"] = 51112019,
            ["SpeakNpcId"] = 701013,
            },
        [51112019] = {
            ["Content"] = "所以话说到这里，小友也能明白我们这些人并不是去报复谁的了吧。",
            ["ContentKR"] = "이렇게까지 말씀드렸으니, 이젠 우리가 복수 따위를 하러 가는 게 아니란 걸 아셨겠죠?",
            ["DialogueId"] = 51112019,
            ["GUID"] = "7FF41D9E",
            ["NextDialogue"] = 51112020,
            ["SpeakNpcId"] = 701013,
            },
        [51112020] = {
            ["Content"] = "至于具体要去做什么……不过是在烛阴之灾止息后，去灾后的阴影里攫取一些利益罢了。",
            ["ContentKR"] = "우리는... 촉룡의 재앙이 휩쓸고 간 자리에 남은 찌꺼기들 속에서, 돈이 될 만한 걸 주우러 가는 겁니다.",
            ["DialogueId"] = 51112020,
            ["GUID"] = "7FF41DC8",
            ["NextDialogue"] = 51112021,
            ["SpeakNpcId"] = 701013,
            ["TalkActionId"] = {
                [1] = "701013:Talk01_End",
                },
            },
        [51112021] = {
            ["Content"] = "（男人说完便带着身后众人离开，没走几步，他突然停了下来，转头看向你。）",
            ["ContentKR"] = "(남자는 부하들을 이끌고 떠나려다가, 잠시 멈칫하더니 고개를 돌려 나를 바라본다.)",
            ["DialogueId"] = 51112021,
            ["GUID"] = "7FF41DF2",
            ["NextDialogue"] = 51112022,
            },
        [51112022] = {
            ["Content"] = "既是虬先生的贵客，那我便免费送你一句忠告吧。",
            ["ContentKR"] = "규선생의 손님이니, 공짜로 충고 하나 해 드리죠.",
            ["DialogueId"] = 51112022,
            ["GUID"] = "7FF41E1C",
            ["NextDialogue"] = 51112023,
            ["SpeakNpcId"] = 701013,
            ["TalkActionId"] = {
                [1] = "701013:Talk02_Start",
                },
            },
        [51112023] = {
            ["Content"] = "有些无主之物，有能者自可得之。若是稍加留意，也许你便能在烟津渡寻得一些不错的宝贝，告辞。",
            ["ContentKR"] = "주인 없는 물건은 먼저 집는 놈이 임자죠. 연진 나루터 근처를 뒤지면, 쓸만한 보물들을 건질 수 있을 겁니다. 그럼 이만.",
            ["DialogueId"] = 51112023,
            ["GUID"] = "7FF41E46",
            ["SpeakNpcId"] = 701013,
            ["TalkActionId"] = {
                [1] = "701013:Talk02_End",
                },
            },
        [51112024] = {
            ["Content"] = "有失远迎，是有什么生意要谈吗？",
            ["ContentKR"] = "조금 더 일찍 마중을 나올걸 그랬군요. 사업 얘기라도 하실 겁니까?",
            ["DialogueId"] = 51112024,
            ["GUID"] = "7FF41E70",
            ["SpeakNpcId"] = 701013,
            },
        [51113000] = {
            ["Content"] = "嗯~前调粗犷，后调绵长，还是百年春的香地道儿。",
            ["ContentKR"] = "으음~ 처음에는 강하게 훅 들어오다가, 끝은 길게 여운이 남네. 역시 향은 백년춘 게 제대로라니까.",
            ["DialogueId"] = 51113000,
            ["GUID"] = "7FF4BE90",
            ["NextDialogue"] = 51113001,
            ["SpeakNpcId"] = 701014,
            ["TalkActionId"] = {
                [1] = "701014:Confident_Start",
                },
            },
        [51113001] = {
            ["Content"] = "（面前这位男人说完举起一把香凑到鼻尖，猛吸一口，露出回味十足的表情。）",
            ["ContentKR"] = "(남자는 향 뭉치를 코끝에 가져다 대더니, 숨을 깊게 들이마시고는 흡족한 표정을 짓는다.)",
            ["DialogueId"] = 51113001,
            ["GUID"] = "7FF4BEBA",
            ["NextDialogue"] = 51113002,
            },
        [51113002] = {
            ["Content"] = "嗯~爽也爽也，太纯了！",
            ["ContentKR"] = "캬~ 좋구나 좋아! 잡냄새 없이 깔끔해!",
            ["DialogueId"] = 51113002,
            ["GUID"] = "7FF4BEE4",
            ["NextOptions"] = {
                [1] = 51113003,
                [2] = 51113004,
                },
            ["SpeakNpcId"] = 701014,
            ["TalkActionId"] = {
                [1] = "701014:Confident_End",
                },
            },
        [51113003] = {
            ["Content"] = "（此人疯疯癫癫，还是别跟他有所牵连为好。）",
            ["ContentKR"] = "(머리가 좀 이상한 사람 같으니까, 엮이지 않는 편이 좋을 것 같다.)",
            ["DialogueId"] = 51113003,
            ["GUID"] = "7FF4BF0E",
            ["ImprPlusId"] = 1207,
            ["NextDialogue"] = 51113005,
            },
        [51113004] = {
            ["Content"] = "你有问题，该叫应天尉了。",
            ["ContentKR"] = "이상한 사람이네. 응천위 부를 거예요.",
            ["DialogueId"] = 51113004,
            ["GUID"] = "7FF4BF38",
            ["ImprPlusId"] = 1208,
            ["NextDialogue"] = 51113005,
            },
        [51113005] = {
            ["Content"] = "诶诶诶，你这小朋友好生奇怪，见了我这华胥知名的品香大师不顶礼膜拜也就罢了，居然还做出这般无礼的反应。",
            ["ContentKR"] = "어이쿠, 별 이상한 녀석이 다 있네. 이 화서의 저명한 향 품평가님을 만났으면 절은 못 할망정, 이게 무슨 실례되는 태도야?",
            ["DialogueId"] = 51113005,
            ["GUID"] = "7FF4BF62",
            ["LookAt"] = {
                [1] = "701014:n(0)",
                },
            ["NextOptions"] = {
                [1] = 51113006,
                [2] = 51113007,
                },
            ["SpeakNpcId"] = 701014,
            },
        [51113006] = {
            ["Content"] = "还整上优越感了。",
            ["ContentKR"] = "콧대가 아주 하늘을 찌르겠어요.",
            ["DialogueId"] = 51113006,
            ["GUID"] = "7FF4BF8C",
            ["ImprPlusId"] = 1210,
            ["NextDialogue"] = 51113008,
            },
        [51113007] = {
            ["Content"] = "好熟悉的骗子话术。",
            ["ContentKR"] = "딱 사기꾼들 단골 멘트네요.",
            ["DialogueId"] = 51113007,
            ["GUID"] = "7FF4BFB6",
            ["ImprPlusId"] = 1206,
            ["NextDialogue"] = 51113008,
            },
        [51113008] = {
            ["Content"] = "嘿，这我可得跟你好好说道说道了。",
            ["ContentKR"] = "이야, 또 이 몸이 한 수 가르쳐 드려야겠네.",
            ["DialogueId"] = 51113008,
            ["GUID"] = "7FF4BFE0",
            ["NextDialogue"] = 51113009,
            ["SpeakNpcId"] = 701014,
            ["TalkActionId"] = {
                [1] = "701014:Talk01_Start",
                },
            },
        [51113009] = {
            ["Content"] = "点香这事，大部分人也就走个流程，却忽略了香本身就是一件艺术品的事实。",
            ["ContentKR"] = "사람들은 대부분 향이 제례의 절차일 뿐이라고 생각해서, 향 자체가 하나의 예술품이란 걸 간과해 버리거든.",
            ["DialogueId"] = 51113009,
            ["GUID"] = "7FF4C00A",
            ["NextDialogue"] = 51113010,
            ["SpeakNpcId"] = 701014,
            },
        [51113010] = {
            ["Content"] = "且说这百年春制的香……让我再闻一口啊……",
            ["ContentKR"] = "그런데 백년춘에서 만든 이 향은 말이지... 일단 한 번 더 맡자...",
            ["DialogueId"] = 51113010,
            ["GUID"] = "7FF4C034",
            ["NextDialogue"] = 51113011,
            ["SpeakNpcId"] = 701014,
            },
        [51113011] = {
            ["Content"] = "嗯~想必是用了浮星埠周遭的碧檀木，辅以青云艾、浮露草而成。",
            ["ContentKR"] = "으음~ 별빛 부두 주변에서 자라는 박달나무에다, 청운쑥과 부노초를 곁들였겠군.",
            ["DialogueId"] = 51113011,
            ["GUID"] = "7FF4C05E",
            ["NextDialogue"] = 51113012,
            ["SpeakNpcId"] = 701014,
            },
        [51113012] = {
            ["Content"] = "烟津渡自古以来便是华胥的航运要地，这里的水不仅养人，还造就了得天独厚的生态，百年春就地取材制香，妙哉妙哉。",
            ["ContentKR"] = "연진 나루터는 예부터 화서 수운의 요충지였어. 이곳의 물은 사람들을 키우고, 독특한 풍토를 만들어 냈지. 백년춘은 거기서 나는 재료들로 향을 만드니, 절묘하지 절묘해!",
            ["DialogueId"] = 51113012,
            ["GUID"] = "7FF4C088",
            ["NextDialogue"] = 51113013,
            ["SpeakNpcId"] = 701014,
            },
        [51113013] = {
            ["Content"] = "你闻闻，能体会到木头那种粗犷的，刺刺的感觉吗？",
            ["ContentKR"] = "자, 자, 한번 맡아봐. 나무 특유의 거칠고 톡 쏘는 느낌이 오지?",
            ["DialogueId"] = 51113013,
            ["GUID"] = "7FF4C0B2",
            ["NextDialogue"] = 51113014,
            ["SpeakNpcId"] = 701014,
            ["TalkActionId"] = {
                [1] = "701014:Talk01_End",
                },
            },
        [51113014] = {
            ["Content"] = "没有。",
            ["ContentKR"] = "잘 모르겠는데요.",
            ["DialogueId"] = 51113014,
            ["GUID"] = "7FF4C0DC",
            ["NextDialogue"] = 51113015,
            ["SpeakNpcId"] = 100001,
            },
        [51113015] = {
            ["Content"] = "好吧好吧，那你再闻闻这皓京产的香，能感觉到有什么不同吗？",
            ["ContentKR"] = "그래, 뭐 그러면 이 호경에서 온 향을 맡아봐. 어때, 차이가 느껴져?",
            ["DialogueId"] = 51113015,
            ["GUID"] = "7FF4C106",
            ["NextDialogue"] = 51113016,
            ["SpeakNpcId"] = 701014,
            ["TalkActionId"] = {
                [1] = "701014:Give",
                },
            },
        [51113016] = {
            ["Content"] = "（男人从怀里取出一根香，点燃后递到你的面前。）",
            ["ContentKR"] = "(남자는 품에서 향을 하나 꺼내 불을 붙이고, 내 얼굴 앞에 가져다 댄다.)",
            ["DialogueId"] = 51113016,
            ["GUID"] = "7FF4C130",
            ["NextDialogue"] = 51113017,
            },
        [51113017] = {
            ["Content"] = "还是没有。",
            ["ContentKR"] = "이번에도 잘 모르겠는데요.",
            ["DialogueId"] = 51113017,
            ["GUID"] = "7FF4C15A",
            ["NextDialogue"] = 51113018,
            ["SpeakNpcId"] = 100001,
            },
        [51113018] = {
            ["Content"] = "皓京群山环绕，制香者常采山中原料炮制，所以那里产的香总带着一点苦涩。",
            ["ContentKR"] = "호경은 산으로 둘러싸인 곳이라서, 보통 산속에서 재료를 구해다 쓰거든. 그래서 거기 건 대부분 약간 쌉싸름한 향이 나.",
            ["DialogueId"] = 51113018,
            ["GUID"] = "7FF4C184",
            ["NextDialogue"] = 51113019,
            ["SpeakNpcId"] = 701014,
            ["TalkActionId"] = {
                [1] = "701014:Confident_Start",
                },
            },
        [51113019] = {
            ["Content"] = "但苦涩之后鼻腔之中便能嗅到一丝芬芳，就像攀登山崖的辛苦，在抵达顶峰之后一扫而空一样。",
            ["ContentKR"] = "그 쌉싸름한 향이 날아갈 때쯤이면, 콧속으로 싱그러운 향기가 올라와. 절벽을 기어올라 정상에 서면, 피로가 씻은 듯이 사라지는 것처럼 말이지.",
            ["DialogueId"] = 51113019,
            ["GUID"] = "7FF4C1AE",
            ["NextDialogue"] = 51113020,
            ["SpeakNpcId"] = 701014,
            },
        [51113020] = {
            ["Content"] = "以后你要是有机会去到皓京的山巅，想必就能理解我说的这种感觉了。",
            ["ContentKR"] = "나중에 호경에 있는 산에 올라가 보면, 내 말이 무슨 뜻인지 이해하게 될 거야.",
            ["DialogueId"] = 51113020,
            ["GUID"] = "7FF4C1D8",
            ["NextDialogue"] = 51113021,
            ["SpeakNpcId"] = 701014,
            },
        [51113021] = {
            ["Content"] = "（男人说完，突然向着远方猛吸了一口气。）",
            ["ContentKR"] = "(남자가 말을 마친 후, 갑자기 먼 곳을 향해 코를 벌름거린다.)",
            ["DialogueId"] = 51113021,
            ["GUID"] = "7FF4C202",
            ["NextDialogue"] = 51113022,
            },
        [51113022] = {
            ["Content"] = "嘶……那边有股不一样的香气……",
            ["ContentKR"] = "스으으으읍... 저쪽에서 뭔가 독특한 향이 나는데...",
            ["DialogueId"] = 51113022,
            ["GUID"] = "7FF4C22C",
            ["NextDialogue"] = 51113023,
            ["SpeakNpcId"] = 701014,
            },
        [51113023] = {
            ["Content"] = "好了，闲话就说到这，我该继续寻香去了，有缘再会~",
            ["ContentKR"] = "자, 대화는 여기까지. 난 계속 향을 찾으러 다녀야겠어. 인연이 닿으면 또 만나자고~",
            ["DialogueId"] = 51113023,
            ["GUID"] = "7FF4C256",
            ["LookAt"] = {
                [1] = "701014:n(701014)",
                },
            ["NextDialogue"] = 51113024,
            ["SpeakNpcId"] = 701014,
            ["TalkActionId"] = {
                [1] = "701014:Confident_End",
                },
            },
        [51113024] = {
            ["Content"] = "（他说完便向着远处狂奔，哪怕已经离了很远，你好像还是能听到他那爽也爽也的喊声。）",
            ["ContentKR"] = "(남자는 말이 끝나자마자 멀리 달려간다. 거리가 꽤 멀어졌지만, 아직도 귓가에서 '좋구나 좋아'가 들리는 것만 같다.)",
            ["DialogueId"] = 51113024,
            ["GUID"] = "7FF4C280",
            ["Scripts"] = "MoveTo{ActorId{701014},TargetPoint{\"WuYe_Target\"},MoveSpeed{120},Visibility{\"Hide\"}}",
            },
        [51114000] = {
            ["Camera"] = "-272.671875,-120.883789,144.290039,0.000001,-3.199971,23.596222,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这位{性别：小兄弟|姑娘}，请留步！可否帮个小忙？",
            ["ContentKR"] = "저기, {性别:친구|아가씨}, 잠깐만! 부탁 하나만 들어줄 수 있을까?",
            ["DialogueId"] = 51114000,
            ["GUID"] = "7FF562A0",
            ["LookAt"] = {
                [1] = "701015:n(100001)",
                [2] = "701016:n(100001)",
                [3] = "100001:n(701015)",
                },
            ["NextDialogue"] = 51114001,
            ["SpeakNpcId"] = 701015,
            ["TalkActionId"] = {
                [1] = "701015:Talk01_Start",
                },
            },
        [51114001] = {
            ["Content"] = "我的孩子吵着想吃梨，但眼下我不便离开，可否请你帮我买两个来？放心，报酬不会少了你的。",
            ["ContentKR"] = "우리 아들이 배가 먹고 싶다고 보채는데, 내가 자리를 비울 수가 없거든. 나 대신 두 개만 사다 줄 수 있을까? 수고비는 넉넉히 챙겨 줄게.",
            ["DialogueId"] = 51114001,
            ["GUID"] = "7FF562CA",
            ["LookAt"] = {
                [1] = "701015:n(701016)",
                [2] = "701016:n(701015)",
                },
            ["NextOptions"] = {
                [1] = 51114002,
                },
            ["RestartTag"] = 51114001,
            ["SpeakNpcId"] = 701015,
            },
        [51114002] = {
            ["Content"] = "有报酬……",
            ["ContentKR"] = "수고비를 준다고요...",
            ["DialogueId"] = 51114002,
            ["FailDialogue"] = 51114003,
            ["GUID"] = "7FF562F4",
            ["ImprCheckId"] = 1123,
            ["NextDialogue"] = 51114004,
            },
        [51114003] = {
            ["Content"] = "（有报酬你也懒得管。）",
            ["ContentKR"] = "(돈을 준다고 해도, 귀찮은 건 질색이다.)",
            ["DialogueId"] = 51114003,
            ["GUID"] = "7FF5631E",
            ["LookAt"] = {
                [1] = "701015:n(100001)",
                [2] = "701016:n(100001)",
                },
            ["TalkActionId"] = {
                [1] = "701015:Talk01_End",
                },
            },
        [51114004] = {
            ["Camera"] = "5.535156,127.534668,137.970703,0.000004,-1.200132,-101.204422,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "好，我帮你买。",
            ["ContentKR"] = "좋아요, 사다 드릴게요.",
            ["DialogueId"] = 51114004,
            ["FacialId"] = {
                [1] = "100001:Smile01",
                },
            ["GUID"] = "7FF56348",
            ["LookAt"] = {
                [1] = "701015:n(100001)",
                [2] = "701016:n(100001)",
                },
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "701015:Talk01_End",
                [2] = "100001:AgreeHead",
                },
            },
        [51114005] = {
            ["Content"] = "你按照男人的交代，去附近的水果铺子买了两只梨。",
            ["ContentKR"] = "남자의 부탁대로 근처의 과일 가게에서 배를 두 개 사 왔다.",
            ["DialogueId"] = 51114005,
            ["GUID"] = "7FF56372",
            ["NextDialogue"] = 51114006,
            },
        [51114006] = {
            ["Content"] = "只是当你回到原地的时候，这里的家长和小孩不知何时如同被复制一般变成了两组。",
            ["ContentKR"] = "하지만 돌아오자, 아까 그 부자 곁에, 언제 온 건지 모를 또 다른 아버지와 아들이 서 있다.",
            ["DialogueId"] = 51114006,
            ["GUID"] = "7FF5639C",
            ["IsBlack"] = 1,
            },
        [51114007] = {
            ["Camera"] = "70.517578,-345.901733,138.587891,0.000038,-2.400115,100.211617,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我把梨买回来了。",
            ["ContentKR"] = "부탁하신 배 사 왔어요.",
            ["DialogueId"] = 51114007,
            ["GUID"] = "7FF563C6",
            ["LookAt"] = {
                [1] = "701015:n(100001)",
                [2] = "701016:n(100001)",
                [3] = "701017:n(100001)",
                [4] = "701018:n(100001)",
                [5] = "100001:n(701015)",
                },
            ["NextDialogue"] = 51114008,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Give",
                },
            },
        [51114008] = {
            ["Camera"] = "-51.375,-217.30188,136.371094,0.000038,-0.000157,60.812229,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "谢谢{性别：小兄弟|姑娘}！",
            ["ContentKR"] = "고맙네, {性别:친구|아가씨}.",
            ["DialogueId"] = 51114008,
            ["GUID"] = "7FF563F0",
            ["NextDialogue"] = 51114009,
            ["SpeakNpcId"] = 701015,
            ["TalkActionId"] = {
                [1] = "701015:Talk02_Start",
                },
            },
        [51114009] = {
            ["Content"] = "哇，有梨吃了！",
            ["ContentKR"] = "우와! 배다!",
            ["DialogueId"] = 51114009,
            ["GUID"] = "7FF5641A",
            ["NextDialogue"] = 51114010,
            ["SpeakNpcId"] = 701016,
            ["TalkActionId"] = {
                [1] = "701015:Talk02_End",
                [2] = "701016:Huanhu_Nan_Start",
                },
            },
        [51114010] = {
            ["Camera"] = "114.041016,-238.422974,146.254883,0.000062,-1.999872,116.998978,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "梨……我也想吃……",
            ["ContentKR"] = "배... 나도 먹고 싶은데...",
            ["DialogueId"] = 51114010,
            ["GUID"] = "7FF56444",
            ["LookAt"] = {
                [1] = "100001:n(701018)",
                },
            ["NextDialogue"] = 51114011,
            ["SpeakNpcId"] = 701018,
            ["TalkActionId"] = {
                [1] = "701018:Explain02_Start",
                },
            },
        [51114011] = {
            ["Content"] = "你这孩子，怎么能馋别人的东西！",
            ["ContentKR"] = "요 녀석, 남 먹을 거에 눈독 들이면 못 써!",
            ["DialogueId"] = 51114011,
            ["GUID"] = "7FF5646E",
            ["LookAt"] = {
                [1] = "701015:n(701017)",
                [2] = "701016:n(701017)",
                [3] = "701017:n(701018)",
                [4] = "701018:n(701017)",
                [5] = "100001:n(701017)",
                },
            ["NextDialogue"] = 51114012,
            ["SpeakNpcId"] = 701017,
            ["TalkActionId"] = {
                [1] = "701018:Explain02_End",
                },
            },
        [51114012] = {
            ["Camera"] = "70.517578,-345.901733,138.587891,0.000038,-2.400115,100.211617,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "无妨，恰好这里有两个梨，给孩子们一人一个吧。",
            ["ContentKR"] = "뭐 어때. 마침 2개 있으니까, 하나씩 먹으면 되지.",
            ["DialogueId"] = 51114012,
            ["GUID"] = "7FF56498",
            ["LookAt"] = {
                [1] = "701015:n(701017)",
                [2] = "701016:n(701015)",
                [3] = "701017:n(701015)",
                [4] = "701018:n(701015)",
                [5] = "100001:n(701015)",
                },
            ["NextDialogue"] = 51114013,
            ["SpeakNpcId"] = 701015,
            ["TalkActionId"] = {
                [1] = "701015:Give",
                },
            },
        [51114013] = {
            ["Content"] = "（小杨伸手拿起了较大的那只梨。）",
            ["ContentKR"] = "(양씨 아저씨의 아들이 그중 커다란 배를 집어 든다.)",
            ["DialogueId"] = 51114013,
            ["GUID"] = "7FF564C2",
            ["NextDialogue"] = 51114014,
            },
        [51114014] = {
            ["Content"] = "瞧瞧，你这孩子真不懂事，哥哥是客人，你应该把大的让给他。",
            ["ContentKR"] = "아니 녀석이, 철이 없어도 이렇게 없어서야. 네가 더 어리니까, 형아한테 더 큰 걸 줘야지.",
            ["DialogueId"] = 51114014,
            ["GUID"] = "7FF564EC",
            ["LookAt"] = {
                [1] = "701015:n(701016)",
                },
            ["NextDialogue"] = 51114015,
            ["SpeakNpcId"] = 701015,
            ["TalkActionId"] = {
                [1] = "701015:Explain01_Start",
                },
            },
        [51114015] = {
            ["Camera"] = "-14.386719,-150.782349,116.589844,0.000093,-4.200163,89.193451,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哥哥，给你……",
            ["ContentKR"] = "형아, 이거 줄게...",
            ["DialogueId"] = 51114015,
            ["GUID"] = "7FF56516",
            ["LookAt"] = {
                [1] = "701016:n(701018)",
                [2] = "701017:n(701016)",
                [3] = "701018:n(701016)",
                [4] = "100001:n(701016)",
                },
            ["NextDialogue"] = 51114016,
            ["SpeakNpcId"] = 701016,
            ["TalkActionId"] = {
                [1] = "701015:Explain01_End",
                [2] = "701016:Give",
                },
            },
        [51114016] = {
            ["Content"] = "（小杨苦着脸把大梨递给了小张，小张欢天喜地地接了过去。）",
            ["ContentKR"] = "(양씨 아저씨의 아들이 울상을 지으며 커다란 배를 건네자, 장씨 아저씨의 아들은 신이 나서 덥석 받아 든다.)",
            ["DialogueId"] = 51114016,
            ["GUID"] = "7FF56540",
            ["NextDialogue"] = 51114017,
            },
        [51114017] = {
            ["Camera"] = "114.041016,-238.422974,146.254883,0.000062,-1.999872,116.998978,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "不行，这怎么好意思！弟弟年纪小，你快把大的让给弟弟。",
            ["ContentKR"] = "얘 좀 봐, 그러면 못 써! 형은 동생한테 양보할 줄 알아야 하는 거야. 얼른 동생한테 줘.",
            ["DialogueId"] = 51114017,
            ["GUID"] = "7FF5656A",
            ["LookAt"] = {
                [1] = "701015:n(701017)",
                [2] = "701016:n(701017)",
                [3] = "701017:n(701018)",
                [4] = "701018:n(701017)",
                [5] = "100001:n(701017)",
                },
            ["NextDialogue"] = 51114018,
            ["SpeakNpcId"] = 701017,
            },
        [51114018] = {
            ["Camera"] = "-14.386719,-150.782349,116.589844,0.000093,-4.200163,89.193451,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "还是给你吧，弟弟……",
            ["ContentKR"] = "이거 그냥 너 먹어, 동생아...",
            ["DialogueId"] = 51114018,
            ["GUID"] = "7FF56594",
            ["LookAt"] = {
                [1] = "701015:n(701018)",
                [2] = "701016:n(701018)",
                [3] = "701017:n(701018)",
                [4] = "701018:n(701016)",
