                [1] = "701018:Give",
                },
            },
        [51114019] = {
            ["Content"] = "（小张把大梨还了回去，他脸上的笑容也随之转移到了小杨脸上。）",
            ["ContentKR"] = "(울적해진 형의 표정과 달리, 배를 돌려받은 동생의 표정은 다시금 해맑아져 있다.)",
            ["DialogueId"] = 51114019,
            ["GUID"] = "7FF565BE",
            ["NextDialogue"] = 51114020,
            },
        [51114020] = {
            ["Camera"] = "-51.375,-217.30188,136.371094,0.000038,-0.000157,60.812229,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "张兄不必客气，小张这年纪正是长身体的时候，该多吃点。",
            ["ContentKR"] = "장형도 참, 한창 자랄 나이인 애가 더 많이 먹어야죠.",
            ["DialogueId"] = 51114020,
            ["GUID"] = "7FF565E8",
            ["LookAt"] = {
                [1] = "701015:n(701017)",
                [2] = "701016:n(701015)",
                [3] = "701017:n(701015)",
                [4] = "701018:n(701015)",
                [5] = "100001:n(701015)",
                },
            ["NextDialogue"] = 51114021,
            ["SpeakNpcId"] = 701015,
            ["TalkActionId"] = {
                [1] = "701015:Talk01_Start",
                },
            },
        [51114021] = {
            ["Camera"] = "114.041016,-238.422974,146.254883,0.000062,-1.999872,116.998978,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这梨是你们买的，我们白拿来吃已经很惭愧了，怎么能还挑大的呢……",
            ["ContentKR"] = "우리 애가 얻어먹는 건데 어떻게 큰 걸 먹겠어, 사람은 염치가 있어야 하는 법이야.",
            ["DialogueId"] = 51114021,
            ["GUID"] = "7FF56612",
            ["LookAt"] = {
                [1] = "701015:n(701017)",
                [2] = "701016:n(701017)",
                [3] = "701017:n(701015)",
                [4] = "701018:n(701017)",
                [5] = "100001:n(701017)",
                },
            ["NextDialogue"] = 51114022,
            ["SpeakNpcId"] = 701017,
            ["TalkActionId"] = {
                [1] = "701015:Talk01_End",
                [2] = "701017:Talk02_Start",
                },
            },
        [51114022] = {
            ["Camera"] = "-14.386719,-150.782349,116.589844,0.000093,-4.200163,89.193451,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……",
            ["ContentKR"] = "......",
            ["DialogueId"] = 51114022,
            ["GUID"] = "7FF5663C",
            ["LookAt"] = {
                [1] = "701016:n(701018)",
                [2] = "701018:n(701016)",
                },
            ["NextDialogue"] = 51114023,
            ["SpeakNpcName"] = "UI_CMNpc_Yanjindu_Name_YangJRAndZhangJR",
            ["TalkActionId"] = {
                [1] = "701017:Talk02_End",
                },
            },
        [51114023] = {
            ["Content"] = "（两个孩子眼巴巴地看向你，似乎很希望你能结束这场推让。）",
            ["ContentKR"] = "(이 골치 아픈 상황을 해결해 달라는 것처럼, 두 아이가 나를 애처롭게 바라본다.)",
            ["DialogueId"] = 51114023,
            ["GUID"] = "7FF56666",
            ["LookAt"] = {
                [1] = "701015:n(100001)",
                [2] = "701016:n(100001)",
                [3] = "701017:n(100001)",
                [4] = "701018:n(100001)",
                },
            ["NextOptions"] = {
                [1] = 51114024,
                [2] = 51114026,
                [3] = 51114028,
                },
            ["TalkActionId"] = {
                [1] = "701016:Explain02_Start",
                [2] = "701018:Think_Start",
                },
            },
        [51114024] = {
            ["Content"] = "要不我再去买两个一样大的？",
            ["ContentKR"] = "지금 거랑 똑같은 크기로 두 개 더 사다 드릴까요?",
            ["DialogueId"] = 51114024,
            ["GUID"] = "7FF56690",
            ["ImprPlusId"] = 1207,
            ["NextDialogue"] = 51114025,
            },
        [51114025] = {
            ["Camera"] = "70.517578,-345.901733,138.587891,0.000038,-2.400115,100.211617,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "再劳烦你就说不过去了……",
            ["ContentKR"] = "그러면 내가 너무 미안한데...",
            ["DialogueId"] = 51114025,
            ["GUID"] = "7FF566BA",
            ["NextDialogue"] = 51114030,
            ["SpeakNpcId"] = 701015,
            ["TalkActionId"] = {
                [1] = "701016:Explain02_End",
                [2] = "701018:Think_End",
                },
            },
        [51114026] = {
            ["Content"] = "切成片大家分着吃吧。",
            ["ContentKR"] = "그냥 인원수에 맞춰서 갈라 먹으면 되잖아요.",
            ["DialogueId"] = 51114026,
            ["GUID"] = "7FF566E4",
            ["ImprPlusId"] = 1208,
            ["NextDialogue"] = 51114027,
            },
        [51114027] = {
            ["Camera"] = "70.517578,-345.901733,138.587891,0.000038,-2.400115,100.211617,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "万万不可，把梨切开就成了“分离”，不吉利的。",
            ["ContentKR"] = "그건 절대 안 돼! '배'를 '가르다'니! 그런 무시무시한 소리를...!",
            ["DialogueId"] = 51114027,
            ["GUID"] = "7FF5670E",
            ["NextDialogue"] = 51114030,
            ["SpeakNpcId"] = 701015,
            ["TalkActionId"] = {
                [1] = "701016:Explain02_End",
                [2] = "701018:Think_End",
                },
            },
        [51114028] = {
            ["Content"] = "我是外国人，我也长身体，两个都给我吃。",
            ["ContentKR"] = "전 외국 사람이라 아직도 한창 클 나이예요. 두 개 다 제가 먹을게요.",
            ["DialogueId"] = 51114028,
            ["GUID"] = "7FF56738",
            ["ImprPlusId"] = 1210,
            ["NextDialogue"] = 51114029,
            },
        [51114029] = {
            ["Camera"] = "70.517578,-345.901733,138.587891,0.000038,-2.400115,100.211617,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这位{性别：小兄弟|姑娘}说话真是风趣……",
            ["ContentKR"] = "농담을 참 잘하는 {性别:친구|아가씨}네...",
            ["DialogueId"] = 51114029,
            ["GUID"] = "7FF56762",
            ["NextDialogue"] = 51114030,
            ["SpeakNpcId"] = 701015,
            ["TalkActionId"] = {
                [1] = "701016:Explain02_End",
                [2] = "701018:Think_End",
                },
            },
        [51114030] = {
            ["Camera"] = "-51.375,-217.30188,136.371094,0.000038,-0.000157,60.812229,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "真是对不住，我们光顾着推让，把你晾在一边了。",
            ["ContentKR"] = "우리끼리 실랑이하느라 계속 세워 둬서 미안해.",
            ["DialogueId"] = 51114030,
            ["GUID"] = "7FF5678C",
            ["LookAt"] = {
                [1] = "701015:n(100001)",
                [2] = "701016:n(100001)",
                [3] = "701017:n(100001)",
                [4] = "701018:n(100001)",
                [5] = "100001:n(701015)",
                },
            ["NextDialogue"] = 51114031,
            ["SpeakNpcId"] = 701015,
            ["TalkActionId"] = {
                [1] = "701015:Explain01_Start",
                },
            },
        [51114031] = {
            ["Content"] = "来，{性别：小兄弟|姑娘}，请收下报酬吧。",
            ["ContentKR"] = "자, {性别:친구|아가씨}, 수고비야. 어서 받아.",
            ["DialogueId"] = 51114031,
            ["GUID"] = "7FF567B6",
            ["LookAt"] = {
                [1] = "701015:n(701017)",
                [2] = "701016:n(701015)",
                [3] = "701017:n(701015)",
                [4] = "701018:n(701015)",
                [5] = "100001:n(701015)",
                },
            ["NextDialogue"] = 51114032,
            ["SpeakNpcId"] = 701015,
            ["TalkActionId"] = {
                [1] = "701015:Explain01_End",
                },
            },
        [51114032] = {
            ["Camera"] = "114.041016,-238.422974,146.254883,0.000062,-1.999872,116.998978,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哎，这钱我来出吧！",
            ["ContentKR"] = "어허, 이 돈은 내가 내겠네!",
            ["DialogueId"] = 51114032,
            ["GUID"] = "7FF567E0",
            ["LookAt"] = {
                [1] = "701015:n(701017)",
                [2] = "701016:n(701017)",
                [3] = "701017:n(701015)",
                [4] = "701018:n(701017)",
                [5] = "100001:n(701017)",
                },
            ["NextDialogue"] = 51114033,
            ["SpeakNpcId"] = 701017,
            ["TalkActionId"] = {
                [1] = "701017:Talk01_Start",
                },
            },
        [51114033] = {
            ["Camera"] = "-51.375,-217.30188,136.371094,0.000038,-0.000157,60.812229,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哪有让客人出钱的道理？",
            ["ContentKR"] = "손님이 돈을 내는 경우가 어디 있습니까?",
            ["DialogueId"] = 51114033,
            ["GUID"] = "7FF5680A",
            ["LookAt"] = {
                [1] = "701015:n(701017)",
                [2] = "701016:n(701015)",
                [3] = "701017:n(701015)",
                [4] = "701018:n(701015)",
                [5] = "100001:n(701015)",
                },
            ["NextDialogue"] = 51114034,
            ["SpeakNpcId"] = 701015,
            ["TalkActionId"] = {
                [1] = "701017:Talk01_End",
                },
            },
        [51114034] = {
            ["Camera"] = "70.517578,-345.901733,138.587891,0.000038,-2.400115,100.211617,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你看我今天来也没带什么礼物……",
            ["ContentKR"] = "오늘 빈손으로 온 것도 민망한데, 이거라도 내야지...",
            ["DialogueId"] = 51114034,
            ["GUID"] = "7FF56834",
            ["LookAt"] = {
                [1] = "701015:n(701017)",
                [2] = "701016:n(701017)",
                [3] = "701017:n(701015)",
                [4] = "701018:n(701017)",
                [5] = "100001:n(701017)",
                },
            ["NextDialogue"] = 51114035,
            ["SpeakNpcId"] = 701017,
            ["TalkActionId"] = {
                [1] = "701017:Sigh_Start",
                },
            },
        [51114035] = {
            ["Content"] = "客气什么呀！我早就和这位{性别：小兄弟|姑娘}说好了，理应我来付钱……",
            ["ContentKR"] = "왜 그런 섭섭한 말씀을 하십니까! 이 {性别:친구|아가씨}한테 부탁한 건 접니다. 그러니 당연히 제가...",
            ["DialogueId"] = 51114035,
            ["GUID"] = "7FF5685E",
            ["LookAt"] = {
                [1] = "701015:n(701017)",
                [2] = "701016:n(701015)",
                [3] = "701017:n(701015)",
                [4] = "701018:n(701015)",
                [5] = "100001:n(701015)",
                },
            ["NextOptions"] = {
                [1] = 51114036,
                },
            ["SpeakNpcId"] = 701015,
            ["TalkActionId"] = {
                [1] = "701017:Sigh_End",
                },
            },
        [51114036] = {
            ["Content"] = "……我说，要不你们一人出一半吧？",
            ["ContentKR"] = "...저기요, 그냥 두 분이 반반씩 내면 되지 않아요?",
            ["DialogueId"] = 51114036,
            ["GUID"] = "7FF56888",
            ["NextDialogue"] = 51114037,
            ["TalkActionId"] = {
                [1] = "701015:Talk02_Start",
                },
            },
        [51114037] = {
            ["Content"] = "呃……既然你这么说了，那倒也行？",
            ["ContentKR"] = "음... 자네가 정 그렇다면야, 그것도 나쁘지 않겠군.",
            ["DialogueId"] = 51114037,
            ["GUID"] = "7FF568B2",
            ["LookAt"] = {
                [1] = "701015:n(100001)",
                [2] = "701016:n(100001)",
                [3] = "701017:n(100001)",
                [4] = "701018:n(100001)",
                },
            ["NextDialogue"] = 51114038,
            ["SpeakNpcId"] = 701015,
            ["TalkActionId"] = {
                [1] = "701015:Talk02_End",
                },
            },
        [51114038] = {
            ["Content"] = "呵呵，这位异邦的{性别：小兄弟|姑娘}倒是机灵。那就这么办，咱们一人出一半！",
            ["ContentKR"] = "하하, 참 지혜로운 외국 {性别:친구|아가씨}군요! 그러면 그렇게 하죠! 딱 반씩 냅시다!",
            ["DialogueId"] = 51114038,
            ["GUID"] = "7FF568DC",
            ["NextDialogue"] = 51114039,
            ["SpeakNpcId"] = 701017,
            ["TalkActionId"] = {
                [1] = "701017:Explain01_Start",
                },
            },
        [51114039] = {
            ["Content"] = "（虽然大梨之争还没有结果，但你已经拿到了报酬，就随他们去吧。）",
            ["ContentKR"] = "(누가 큰 배를 먹을지는 아직 결론이 안 났지만, 어쨌든 나는 돈을 받았다. 나머지는 알아서들 하겠지.)",
            ["DialogueId"] = 51114039,
            ["GUID"] = "7FF56906",
            ["TalkActionId"] = {
                [1] = "701017:Explain01_End",
                },
            },
        [51114040] = {
            ["Content"] = "乖，还是把大的让给哥哥吧！",
            ["ContentKR"] = "착하지, 커다란 건 형한테 양보하렴!",
            ["DialogueId"] = 51114040,
            ["GUID"] = "7FF56930",
            ["SpeakNpcId"] = 701015,
            },
        [51115000] = {
            ["Content"] = "哼哼哼……我一定会让你们都尝到苦头的……",
            ["ContentKR"] = "흥... 두고 봐. 내가 뜨거운 맛을 보여 줄 테니까...",
            ["DialogueId"] = 51115000,
            ["GUID"] = "7FF606B0",
            ["NextOptions"] = {
                [1] = 51115001,
                },
            ["SpeakNpcId"] = 701019,
            },
        [51115001] = {
            ["Content"] = "谁？",
            ["ContentKR"] = "누구한테?",
            ["DialogueId"] = 51115001,
            ["GUID"] = "7FF606DA",
            ["NextDialogue"] = 51115002,
            },
        [51115002] = {
            ["Content"] = "咦？！",
            ["ContentKR"] = "으앗?!",
            ["DialogueId"] = 51115002,
            ["GUID"] = "7FF60704",
            ["LookAt"] = {
                [1] = "701019:n(0)",
                },
            ["NextDialogue"] = 51115003,
            ["SpeakNpcId"] = 701019,
            ["TalkActionId"] = {
                [1] = "701019:Shock_Start",
                },
            },
        [51115003] = {
            ["Content"] = "你、你听到什么了？",
            ["ContentKR"] = "내, 내가 뭐라고 했는데?",
            ["DialogueId"] = 51115003,
            ["GUID"] = "7FF6072E",
            ["NextDialogue"] = 51115004,
            ["SpeakNpcId"] = 701019,
            ["TalkActionId"] = {
                [1] = "701019:Shock_End",
                },
            },
        [51115004] = {
            ["Content"] = "听到你在盘算做一些坏事。",
            ["ContentKR"] = "나쁜 짓 같은 걸 꾸미고 있던데.",
            ["DialogueId"] = 51115004,
            ["GUID"] = "7FF60758",
            ["NextDialogue"] = 51115005,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "701019:Explain01_Start",
                },
            },
        [51115005] = {
            ["Content"] = "才不是坏事呢，我是要报仇！",
            ["ContentKR"] = "나쁜 짓 아니거든! 난 복수하려는 거야!",
            ["DialogueId"] = 51115005,
            ["GUID"] = "7FF60782",
            ["NextDialogue"] = 51115006,
            ["SpeakNpcId"] = 701019,
            },
        [51115006] = {
            ["Content"] = "报什么仇？找谁报仇？",
            ["ContentKR"] = "무슨 복수? 누구한테?",
            ["DialogueId"] = 51115006,
            ["GUID"] = "7FF607AC",
            ["NextDialogue"] = 51115007,
            ["SpeakNpcId"] = 100001,
            },
        [51115007] = {
            ["Content"] = "我们商队的货品供应商呀！跟他们合作真是气死人啦！",
            ["ContentKR"] = "우리 상단 거래처 녀석들한테! 같이 일하면 진짜 속 터져 죽을 것 같단 말이야!",
            ["DialogueId"] = 51115007,
            ["GUID"] = "7FF607D6",
            ["NextOptions"] = {
                [1] = 51115008,
                [2] = 51115009,
                },
            ["SpeakNpcId"] = 701019,
            ["TalkActionId"] = {
                [1] = "701019:Explain01_End",
                },
            },
        [51115008] = {
            ["Content"] = "工作中难免有糟心事，气坏自己就得不偿失了，还是放宽心吧。",
            ["ContentKR"] = "일하다 보면 다 그럴 때가 있어. 화내면 너만 손해니까, 웬만하면 그냥 넘어가.",
            ["DialogueId"] = 51115008,
            ["GUID"] = "7FF60800",
            ["ImprPlusId"] = 1209,
            ["NextDialogue"] = 51115010,
            },
        [51115009] = {
            ["Content"] = "如果有人欺负你，大风九章应该会惩罚他们吧？",
            ["ContentKR"] = "누가 널 괴롭히는 거라면, 대풍구장이 벌을 내리지 않을까?",
            ["DialogueId"] = 51115009,
            ["GUID"] = "7FF6082A",
            ["ImprPlusId"] = 1208,
            ["NextDialogue"] = 51115010,
            },
        [51115010] = {
            ["Content"] = "嗨呀，你是不知道，这些人狡猾的很！",
            ["ContentKR"] = "아오! 네가 몰라서 그래! 그 녀석들이 얼마나 얍삽한데!",
            ["DialogueId"] = 51115010,
            ["GUID"] = "7FF60854",
            ["NextDialogue"] = 51115011,
            ["SpeakNpcId"] = 701019,
            ["TalkActionId"] = {
                [1] = "701019:Talk01_Start",
                },
            },
        [51115011] = {
            ["Content"] = "开工的时候吧，总是说着什么“相信贵方的实力”、“能力越大责任越大”，然后把困难的部分“让”给我们做。",
            ["ContentKR"] = "일 시작할 땐, 우리의 능력을 믿는다는 둥, 큰 힘에는 큰 책임이 따른다는 둥 하면서, 골치 아픈 건 다 이쪽으로 슬쩍 '양보'해 버린다고.",
            ["DialogueId"] = 51115011,
            ["GUID"] = "7FF6087E",
            ["NextDialogue"] = 51115012,
            ["SpeakNpcId"] = 701019,
            },
        [51115012] = {
            ["Content"] = "出了岔子呢，又总是念着“唇齿相依”、“同舟共济”云云，支使我们帮忙收拾烂摊子，给他们善后。",
            ["ContentKR"] = "그러다 문제 터지면, 서로서로 돕고 살아야 한다느니, 우린 한배를 탄 사이라느니 하면서, 우리한테 다 뒤치다꺼리를 떠넘겨.",
            ["DialogueId"] = 51115012,
            ["GUID"] = "7FF608A8",
            ["NextDialogue"] = 51115013,
            ["SpeakNpcId"] = 701019,
            },
        [51115013] = {
            ["Content"] = "要是拒绝这些呀，他们就会闹别扭，在各种地方偷懒，虽然谁都看得出是故意的，但这种事情也没法证明……",
            ["ContentKR"] = "싫다고 그러지? 그러면 삐쳐서 일은 제쳐놓고 농땡이를 부려. 누가 봐도 일부러 그러는 건데, 증거가 없으니까...",
            ["DialogueId"] = 51115013,
            ["GUID"] = "7FF608D2",
            ["NextDialogue"] = 51115014,
            ["SpeakNpcId"] = 701019,
            },
        [51115014] = {
            ["Content"] = "当面问的话，他们就会装出一副特别愧疚的样子，连声说“真是太对不住了下次一定注意”之类的鬼话……真是气煞我也！",
            ["ContentKR"] = "이게 뭐냐고 따지면, 세상에서 제일 억울한 표정으로 \"아이고, 정말 죄송합니다. 다음부턴 주의할게요.\"같은 소리나 해 댄다니까... 진짜 짜증 나서 죽을 것 같아!",
            ["DialogueId"] = 51115014,
            ["GUID"] = "7FF608FC",
            ["NextDialogue"] = 51115015,
            ["SpeakNpcId"] = 701019,
            ["TalkActionId"] = {
                [1] = "701019:Talk01_End",
                },
            },
        [51115015] = {
            ["Content"] = "要不换一家合作呢？",
            ["ContentKR"] = "거래처를 바꾸면 해결되지 않을까?",
            ["DialogueId"] = 51115015,
            ["GUID"] = "7FF60926",
            ["NextDialogue"] = 51115016,
            ["SpeakNpcId"] = 100001,
            },
        [51115016] = {
            ["Content"] = "我倒是想……可是我们商队进的货品比较罕有，只有这一家能供应。",
            ["ContentKR"] = "그러고야 싶지... 그런데 우리 상단이 취급하는 물건이 좀 희귀한 거라, 공급해 주는 데가 거기밖에 없어.",
            ["DialogueId"] = 51115016,
            ["GUID"] = "7FF60950",
            ["NextDialogue"] = 51115017,
            ["SpeakNpcId"] = 701019,
            ["TalkActionId"] = {
                [1] = "701019:Talk02_Start",
                },
            },
        [51115017] = {
            ["Content"] = "不过，我是不会就这么忍着的！我已经在写复仇计划了，待我准备妥当，定要叫那帮老东西跪下求饶，呵呵呵……",
            ["ContentKR"] = "그렇지만, 난 당하곤 못 살아! 벌써 복수할 계획을 세우고 있으니까, 준비만 끝나면, 다들 내 앞에 무릎 꿇고 싹싹 빌게 만들어 주겠어! 후후후...",
            ["DialogueId"] = 51115017,
            ["GUID"] = "7FF6097A",
            ["NextDialogue"] = 51115018,
            ["SpeakNpcId"] = 701019,
            },
        [51115018] = {
            ["Content"] = "具体什么计划？",
            ["ContentKR"] = "뭘 어떻게 할 건데?",
            ["DialogueId"] = 51115018,
            ["GUID"] = "7FF609A4",
            ["NextDialogue"] = 51115019,
            ["SpeakNpcId"] = 100001,
            },
        [51115019] = {
            ["Content"] = "可多啦，我给你念几条——",
            ["ContentKR"] = "방법이야 많지! 몇 개만 알려 줄게...",
            ["DialogueId"] = 51115019,
            ["GUID"] = "7FF609CE",
            ["NextDialogue"] = 51115020,
            ["SpeakNpcId"] = 701019,
            },
        [51115020] = {
            ["Content"] = "一，把他们的桌子砍掉一截腿，让他们没法平稳地写字！",
            ["ContentKR"] = "첫째! 녀석들의 책상 다리 하나를 톱으로 살짝 잘라서, 뭘 적을 때마다 덜컹거리게 만든다!",
            ["DialogueId"] = 51115020,
            ["GUID"] = "7FF609F8",
            ["NextDialogue"] = 51115021,
            ["SpeakNpcId"] = 701019,
            },
        [51115021] = {
            ["Content"] = "二，在他们的茶里放泻药，让他们上不了班！",
            ["ContentKR"] = "둘째! 녀석들 차에 설사약을 타서, 일을 못 하게 만든다!",
            ["DialogueId"] = 51115021,
            ["GUID"] = "7FF60A22",
            ["NextDialogue"] = 51115022,
            ["SpeakNpcId"] = 701019,
            },
        [51115022] = {
            ["Content"] = "三，在他们祈求财运的盆栽里浇开水，让他们发不了财！",
            ["ContentKR"] = "셋째! 녀석들이 재물운 빌겠다고 갖다 놓은 화분에 뜨거운 물을 줘서, 재물운이 도망치게 만든다!",
            ["DialogueId"] = 51115022,
            ["GUID"] = "7FF60A4C",
            ["NextDialogue"] = 51115023,
            ["SpeakNpcId"] = 701019,
            ["TalkActionId"] = {
                [1] = "701019:Talk02_End",
                },
            },
        [51115023] = {
            ["Content"] = "……听起来都没有什么杀伤力。而且，这些应该也是大风九章禁止的内容吧？",
            ["ContentKR"] = "...별반 타격도 없을 것 같은데. 그리고, 그랬다간 대풍구장한테 걸리는 거 아냐?",
            ["DialogueId"] = 51115023,
            ["GUID"] = "7FF60A76",
            ["NextDialogue"] = 51115024,
            ["SpeakNpcId"] = 100001,
            },
        [51115024] = {
            ["Content"] = "不然你以为我为什么还没行动！不过无妨，这都还只是初稿呢。",
            ["ContentKR"] = "그러니까 내가 아직 실행을 못 하고 있는 거지! 그래도 괜찮아, 이건 초안일 뿐이니까.",
            ["DialogueId"] = 51115024,
            ["GUID"] = "7FF60AA0",
            ["NextDialogue"] = 51115025,
            ["SpeakNpcId"] = 701019,
            ["TalkActionId"] = {
                [1] = "701019:Think_Start",
                },
            },
        [51115025] = {
            ["Content"] = "古语有云：“勤能补拙”！只要我写得足够多，一定可以发现一个能完美地躲过大风九章的复仇方法。",
            ["ContentKR"] = "\"노력도 재능이다\"라는 말도 있잖아! 열심히 적다 보면, 대풍구장한테 전혀 안 들킬 완벽한 복수 방법이 하나는 떠오르겠지, 뭐.",
            ["DialogueId"] = 51115025,
            ["GUID"] = "7FF60ACA",
            ["NextDialogue"] = 51115026,
            ["SpeakNpcId"] = 701019,
            },
        [51115026] = {
            ["Content"] = "你看，我已经写了这么多了！",
            ["ContentKR"] = "짠! 벌써 이만큼이나 썼어!",
            ["DialogueId"] = 51115026,
            ["GUID"] = "7FF60AF4",
            ["NextDialogue"] = 51115027,
            ["SpeakNpcId"] = 701019,
            ["TalkActionId"] = {
                [1] = "701019:Think_End",
                },
            },
        [51115027] = {
            ["Content"] = "（少女翻动着手中的簿子——用黑色墨水写就的字迹力透纸背，据你目测足足有七八十页。）",
            ["ContentKR"] = "(소녀가 손에 든 공책을 넘긴다. 빽빽하게 채워진 종이가 적어도 70~80장은 넘어 보인다.)",
            ["DialogueId"] = 51115027,
            ["GUID"] = "7FF60B1E",
            ["NextDialogue"] = 51115028,
            },
        [51115028] = {
            ["Content"] = "这么多……你写了多久啊？",
            ["ContentKR"] = "되게 많이 적었네... 언제부터 적기 시작한 거야?",
            ["DialogueId"] = 51115028,
            ["GUID"] = "7FF60B48",
            ["NextDialogue"] = 51115029,
            ["SpeakNpcId"] = 100001,
            },
        [51115029] = {
            ["Content"] = "唔……好像是前年秋天开始写的？也可能是再往前一年，记不太清了。",
            ["ContentKR"] = "음... 재작년 가을부터였나? 재재작년이었을지도... 기억이 잘 안 나.",
            ["DialogueId"] = 51115029,
            ["GUID"] = "7FF60B72",
            ["NextDialogue"] = 51115030,
            ["SpeakNpcId"] = 701019,
            },
        [51115030] = {
            ["Content"] = "……你这复仇周期是不是有点长。",
            ["ContentKR"] = "...준비가 너무 긴 거 아니야?",
            ["DialogueId"] = 51115030,
            ["GUID"] = "7FF60B9C",
            ["NextDialogue"] = 51115031,
            ["SpeakNpcId"] = 100001,
            },
        [51115031] = {
            ["Content"] = "古语有云：“君子报仇，十年不晚”！",
            ["ContentKR"] = "\"군자의 복수는 10년이 걸려도 늦지 않는다\"잖아!",
            ["DialogueId"] = 51115031,
            ["GUID"] = "7FF60BC6",
            ["NextDialogue"] = 51115032,
            ["SpeakNpcId"] = 701019,
            },
        [51115032] = {
