            ["DialogueId"] = 51115032,
            ["GUID"] = "7FF60BF0",
            ["NextDialogue"] = 51115033,
            ["SpeakNpcId"] = 100001,
            },
        [51115033] = {
            ["Content"] = "你怎么知道？！",
