        [51116005] = {
            ["Content"] = "为什么一定要找动物？",
            ["ContentKR"] = "왜 하필 동물이어야 하는데요?",
            ["DialogueId"] = 51116005,
            ["GUID"] = "7FF6AB92",
            ["NextDialogue"] = 51116006,
            ["SpeakNpcId"] = 100001,
            },
        [51116006] = {
            ["Content"] = "你有所不知，这古时的华胥有一位名扬天下的琴师，相传她的音乐造诣出神入化，每每抚起琴来，就连动物也会在她身边驻足倾听。",
            ["ContentKR"] = "이 얘기를 모르시는군요. 옛날, 화서에는 아주 유명한 악사가 하나 있었어요. 연주 솜씨가 신의 경지에 이를 정도라, 동물들까지 와서 듣고 갈 정도였다고 해요.",
            ["DialogueId"] = 51116006,
            ["GUID"] = "7FF6ABBC",
            ["NextDialogue"] = 51116007,
            ["SpeakNpcId"] = 701020,
            ["TalkActionId"] = {
                [1] = "701020:Talk01_End",
                },
            },
        [51116007] = {
            ["Content"] = "在下毕生所求，便是达到此般境界！",
            ["ContentKR"] = "제 평생의 꿈이, 바로 그런 경지에 도달하는 거랍니다!",
            ["DialogueId"] = 51116007,
            ["GUID"] = "7FF6ABE6",
            ["NextDialogue"] = 51116008,
            ["SpeakNpcId"] = 701020,
            ["TalkActionId"] = {
                [1] = "701020:Confident_Start",
                },
            },
        [51116008] = {
            ["Content"] = "可这烟津渡附近的小动物似乎都极怕生，我甫一坐下，还没开始弹呢，它们就都跑开了。",
            ["ContentKR"] = "그런데 이 연진 나루터 근처에 사는 동물들은 어찌나 겁이 많은지, 제가 와서 앉으면, 연주를 시작하기도 전에 다 도망가 버리더군요.",
            ["DialogueId"] = 51116008,
            ["GUID"] = "7FF6AC10",
            ["NextDialogue"] = 51116009,
            ["SpeakNpcId"] = 701020,
            },
        [51116009] = {
            ["Content"] = "因此，我一直没有机会让小动物们听到我精心编写的乐曲，实在遗憾……",
            ["ContentKR"] = "그래서 안타깝게도 제가 공들여 만든 곡을 들려 줄 기회가 없었어요...",
            ["DialogueId"] = 51116009,
            ["GUID"] = "7FF6AC3A",
            ["NextDialogue"] = 51116010,
            ["SpeakNpcId"] = 701020,
            ["TalkActionId"] = {
                [1] = "701020:Confident_End",
                },
            },
        [51116010] = {
            ["Content"] = "若{性别：兄台|姑娘}能将它们带来此处，助我圆梦，我必有重谢！",
            ["ContentKR"] = "제가 꿈을 이룰 수 있도록, {性别:친구|아가씨}가 동물들을 여기로 데려와 준다면, 사례는 섭섭지 않게 할게요.",
            ["DialogueId"] = 51116010,
            ["GUID"] = "7FF6AC64",
            ["NextOptions"] = {
                [1] = 51116011,
                },
            ["RestartTag"] = 51116010,
            ["SpeakNpcId"] = 701020,
            },
        [51116011] = {
            ["Content"] = "那好吧，我想想办法。",
            ["ContentKR"] = "알겠어요. 방법을 찾아보죠.",
            ["DialogueId"] = 51116011,
            ["FailDialogue"] = 51116012,
            ["GUID"] = "7FF6AC8E",
            ["ImprCheckId"] = 1124,
            ["NextDialogue"] = 51116013,
            },
        [51116012] = {
            ["Content"] = "（再想想，该怎么把动物带到这里呢？）",
            ["ContentKR"] = "(다시 생각해 보자. 동물들을 어떻게 여기까지 데려오지?)",
            ["DialogueId"] = 51116012,
            ["GUID"] = "7FF6ACB8",
            ["SpeakNpcId"] = 100001,
            },
        [51116013] = {
            ["Content"] = "你思考了一番，最后决定用食物将小动物引诱到附近。",
            ["ContentKR"] = "잠시 고민한 끝에, 먹이를 이용해 동물들을 이 근처로 유인하기로 했다.",
            ["DialogueId"] = 51116013,
            ["GUID"] = "7FF6ACE2",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51116014,
            },
        [51116014] = {
            ["Content"] = "经过你的努力，几只鸟雀和鹿循着食物的香气接近了具睦身边。",
            ["ContentKR"] = "노력 끝에, 사슴과 새 몇 마리가 먹이 냄새를 쫓아 목현의 곁으로 다가왔다.",
            ["DialogueId"] = 51116014,
            ["GUID"] = "7FF6AD0C",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51116015,
            },
        [51116015] = {
            ["Content"] = "竟有如此妙招，{性别：兄台|姑娘}好生聪明！报酬我已备好，请{性别：兄台|姑娘}收下。",
            ["ContentKR"] = "이런 기막힌 방법이 있었다니! 정말 똑똑한 {性别:친구|아가씨}로군요! 보수는 여기 있으니 받아요, {性别:친구|아가씨}!",
            ["DialogueId"] = 51116015,
            ["GUID"] = "7FF6AD36",
            ["NextDialogue"] = 51116016,
            ["SpeakNpcId"] = 701020,
            ["TalkActionId"] = {
                [1] = "701020:Give",
                },
            },
        [51116016] = {
            ["Content"] = "事不宜迟，我这就开始抚琴。{性别：兄台|姑娘}若是有雅兴，也请务必驻足垂听！",
            ["ContentKR"] = "이럴 때가 아니라, 지금 바로 연주를 시작해야겠어요. 혹시 {性别:친구|아가씨}도 관심 있으면, 꼭 듣고 가 줘요!",
            ["DialogueId"] = 51116016,
            ["GUID"] = "7FF6AD60",
            ["NextDialogue"] = 51116017,
            ["SpeakNpcId"] = 701020,
            },
        [51116017] = {
            ["Content"] = "（具睦煞有介事地席地而坐，捋起袖子，抬起手腕，开始了他的演奏——）",
            ["ContentKR"] = "(목현이 진지하게 바닥에 앉아 소매를 걷어붙이더니, 손목을 위로 들어 연주를 시작한다...)",
            ["DialogueId"] = 51116017,
            ["GUID"] = "7FF6AD8A",
            ["NextDialogue"] = 51116018,
            },
        [51116018] = {
            ["Content"] = "（……现在，你终于知道之前那阵奇怪的噪音是哪儿来的了。）",
            ["ContentKR"] = "(...그 순간, 아까 들렸던 기묘한 소음의 정체를 알 수 있었다.)",
            ["DialogueId"] = 51116018,
            ["GUID"] = "7FF6ADB4",
            ["NextDialogue"] = 51116019,
            },
        [51116019] = {
            ["Content"] = "啾？！",
            ["ContentKR"] = "짹?!",
            ["DialogueId"] = 51116019,
            ["GUID"] = "7FF6ADDE",
            ["NextDialogue"] = 51116020,
            ["SpeakNpcName"] = "UI_CMNpc_Yanjindu_Name_Bird",
            },
        [51116020] = {
            ["Content"] = "呦——！！",
            ["ContentKR"] = "끼이잉——!",
            ["DialogueId"] = 51116020,
            ["GUID"] = "7FF6AE08",
            ["NextDialogue"] = 51116021,
            ["SpeakNpcName"] = "UI_CMNpc_Yanjindu_Name_Deer",
            },
        [51116021] = {
            ["Content"] = "（小动物们不顾吃到一半的食物，四散而逃。）",
            ["ContentKR"] = "(동물들은 먹던 음식마저 내팽개치고, 사방으로 뿔뿔이 도망친다.)",
            ["DialogueId"] = 51116021,
            ["GUID"] = "7FF6AE32",
            ["NextOptions"] = {
                [1] = 51116022,
                [2] = 51116023,
                [3] = 51116024,
                },
            },
        [51116022] = {
            ["Content"] = "看来你还需要多加练习。",
            ["ContentKR"] = "연습을 더 많이 하셔야겠는데요.",
            ["DialogueId"] = 51116022,
            ["GUID"] = "7FF6AE5C",
            ["ImprPlusId"] = 1207,
            ["NextDialogue"] = 51116025,
            },
        [51116023] = {
            ["Content"] = "你应该向我支付听这段演奏的费用。",
            ["ContentKR"] = "제 귀에 비용을 지불하셔야겠는데요.",
            ["DialogueId"] = 51116023,
            ["GUID"] = "7FF6AE86",
            ["ImprPlusId"] = 1206,
            ["NextDialogue"] = 51116025,
            },
        [51116024] = {
            ["Content"] = "天哪，你弹得太好了，小动物们听完都热血沸腾了！",
            ["ContentKR"] = "와! 연주가 너무 훌륭해서 동물들도 가슴이 벅차올랐나 봐요!",
            ["DialogueId"] = 51116024,
            ["GUID"] = "7FF6AEB0",
            ["ImprPlusId"] = 1210,
            ["NextDialogue"] = 51116025,
            },
        [51116025] = {
            ["Content"] = "怎、怎会如此……这究竟是何缘故……？",
            ["ContentKR"] = "이, 이런 일이... 대체 뭐가 문제지...?",
            ["DialogueId"] = 51116025,
            ["GUID"] = "7FF6AEDA",
            ["NextDialogue"] = 51116026,
            ["SpeakNpcId"] = 701020,
            },
        [51116026] = {
            ["Content"] = "你弹的东西真的是音乐吗？",
            ["ContentKR"] = "아까 연주한 거, 진짜 음악 맞아요?",
            ["DialogueId"] = 51116026,
            ["GUID"] = "7FF6AF04",
            ["NextDialogue"] = 51116027,
            ["SpeakNpcId"] = 100001,
            },
        [51116027] = {
            ["Content"] = "这“出神入化之曲”，总应与一般的音乐有异啊。",
            ["ContentKR"] = "'신의 경지에 이른 연주'는, 평범한 음악하곤 다른 면이 있어야 하잖아요.",
            ["DialogueId"] = 51116027,
            ["GUID"] = "7FF6AF2E",
            ["NextDialogue"] = 51116028,
            ["SpeakNpcId"] = 701020,
            ["TalkActionId"] = {
                [1] = "701020:Talk02_Start",
                },
            },
        [51116028] = {
            ["Content"] = "我想既是要让动物也能欣赏，想必最好取材于自然……好比我刚才弹的这一曲，便是融合了树枝撕裂之声、蚊虫振翅之声、野狗刨地之声……",
            ["ContentKR"] = "동물들도 감상할 수 있으려면, 소재를 자연에서 찾는 게 좋겠다고 생각했어요... 아까 그 곡은, 나뭇가지 부러지는 소리, 모기 날갯짓 소리, 들개가 땅 파는 소리 같은 걸 한데 모은 곡이었고요...",
            ["DialogueId"] = 51116028,
            ["GUID"] = "7FF6AF58",
            ["NextDialogue"] = 51116029,
            ["SpeakNpcId"] = 701020,
            },
        [51116029] = {
            ["Content"] = "我自以为此曲完美无缺，没想到，终究是错付了……",
            ["ContentKR"] = "완벽한 곡이라고 생각했는데, 지금 보니 다 헛수고였던 거군요...",
            ["DialogueId"] = 51116029,
            ["GUID"] = "7FF6AF82",
            ["NextOptions"] = {
                [1] = 51116030,
                },
            ["SpeakNpcId"] = 701020,
            ["TalkActionId"] = {
                [1] = "701020:Talk02_End",
                },
            },
        [51116030] = {
            ["Content"] = "有没有可能你选的这些声音本来也不好听……",
            ["ContentKR"] = "소재로 삼은 소리부터 별로였던 건 아닐까요...",
            ["DialogueId"] = 51116030,
            ["GUID"] = "7FF6AFAC",
            ["NextDialogue"] = 51116031,
            },
        [51116031] = {
            ["Content"] = "……！",
            ["ContentKR"] = "......!",
            ["DialogueId"] = 51116031,
            ["GUID"] = "7FF6AFD6",
            ["NextDialogue"] = 51116032,
            ["SpeakNpcId"] = 701020,
            },
        [51116032] = {
            ["Content"] = "{性别：兄台|姑娘}可真是一语惊醒梦中人！",
            ["ContentKR"] = "{性别:친구|아가씨} 얘길 들으니 정신이 확 드네요!",
            ["DialogueId"] = 51116032,
            ["GUID"] = "7FF6B000",
            ["NextDialogue"] = 51116033,
            ["SpeakNpcId"] = 701020,
            ["TalkActionId"] = {
                [1] = "701020:Sigh_Start",
                },
            },
        [51116033] = {
            ["Content"] = "原来如此，是我取材有误……我这就回去重新谱曲！让我想想……乌鸦高鸣之声、野鼠啃噬之声、金石摩擦之声……嗯，应当不错！",
            ["ContentKR"] = "소재를 잘못 골랐던 거예요... 당장 돌아가서 곡을 다시 써야겠어요! 이번엔... 까마귀 울음소리, 들쥐가 뭔가 갉아 먹는 소리, 금속 긁히는 소리를 소재로... 음, 괜찮겠네요!",
            ["DialogueId"] = 51116033,
            ["GUID"] = "7FF6B02A",
            ["NextDialogue"] = 51116034,
            ["SpeakNpcId"] = 701020,
            ["TalkActionId"] = {
                [1] = "701020:Sigh_End",
                },
            },
        [51116034] = {
            ["Content"] = "（具睦似乎已经完全沉浸在了自己的艺术之中。无论如何，你已经拿到了报酬，还是赶紧离开，保护好自己的耳朵吧。）",
            ["ContentKR"] = "(목현은 이미 자기만의 예술 세계에 푹 빠진 것 같다. 어쨌든 보수는 이미 받았으니, 귀 건강을 위해서라도 어서 자리를 뜨는 편이 좋겠다.)",
            ["DialogueId"] = 51116034,
            ["GUID"] = "7FF6B054",
            },
        [51116035] = {
            ["Content"] = "小鸟儿、小狐狸、小野猫你们别跑呀，再听一曲吧！",
            ["ContentKR"] = "새야, 여우야, 고양이야~ 도망가지 말고 한 곡만 더 듣고 가렴!",
            ["DialogueId"] = 51116035,
            ["GUID"] = "7FF6B07E",
            ["SpeakNpcId"] = 701020,
            },
        [51117000] = {
            ["Camera"] = "-56.007812,179.976562,127.53125,0.000043,-7.60004,-107.399704,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "一定是无由生啦！",
            ["ContentKR"] = "무유생이라니까!",
            ["DialogueId"] = 51117000,
            ["GUID"] = "7FF74ED0",
            ["LookAt"] = {
                [1] = "701021:n(701022)",
                [2] = "701022:n(701021)",
                [3] = "100001:n(701021)",
                },
            ["NextDialogue"] = 51117001,
            ["SpeakNpcId"] = 701021,
            ["TalkActionId"] = {
                [1] = "701021:Angry01_Start",
                },
            },
        [51117001] = {
            ["Camera"] = "-175.459961,-170.417969,118.708984,0.000063,-4.799348,68.995163,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "一定是狴犴啦！",
            ["ContentKR"] = "폐안 맞거든!",
            ["DialogueId"] = 51117001,
            ["GUID"] = "7FF74EFA",
            ["NextDialogue"] = 51117002,
            ["SpeakNpcId"] = 701022,
            ["TalkActionId"] = {
                [1] = "701022:Angry01_Start",
                },
            },
        [51117002] = {
            ["Camera"] = "-102.625977,389.867188,178.47168,0.000117,-10.004881,-94.054535,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（枯荣阁外，两个小孩吵吵嚷嚷的，不知在争论些什么。你无意中放慢了脚步，引起了他们的注意——）",
            ["ContentKR"] = "(고영각 밖에서 꼬마 둘이 말다툼을 하고 있다. 무슨 일인가 싶어 걸음을 늦추자, 아이들의 눈길이 나에게 쏠린다...)",
            ["DialogueId"] = 51117002,
            ["GUID"] = "7FF74F24",
            ["NextDialogue"] = 51117003,
            ["TalkActionId"] = {
                [1] = "701021:Angry01_End",
                [2] = "701022:Angry01_End",
                },
            },
        [51117003] = {
            ["Content"] = "{性别：大哥哥|大姐姐}，{性别：大哥哥|大姐姐}！你说呢？",
            ["ContentKR"] = "{性别:오빠|언니}!, {性别:오빠|언니}는 어떻게 생각해?",
            ["DialogueId"] = 51117003,
            ["GUID"] = "7FF74F4E",
            ["LookAt"] = {
                [1] = "701021:n(100001)",
                [2] = "701022:n(100001)",
                },
            ["NextOptions"] = {
                [1] = 51117004,
                },
            ["SpeakNpcId"] = 701021,
            },
        [51117004] = {
            ["Content"] = "我说什么？",
            ["ContentKR"] = "뭘 말이야?",
            ["DialogueId"] = 51117004,
            ["GUID"] = "7FF74F78",
            ["NextDialogue"] = 51117005,
            },
        [51117005] = {
            ["Content"] = "你说那个白色的影子到底是什么？",
            ["ContentKR"] = "하얀 그림자 말이야. 그게 도대체 뭘까?",
            ["DialogueId"] = 51117005,
            ["GUID"] = "7FF74FA2",
            ["NextDialogue"] = 51117006,
            ["SpeakNpcId"] = 701021,
            ["TalkActionId"] = {
                [1] = "701021:Think_Start",
                },
            },
        [51117006] = {
            ["Content"] = "什么白色的影子？",
            ["ContentKR"] = "하얀 그림자라니?",
            ["DialogueId"] = 51117006,
            ["GUID"] = "7FF74FCC",
            ["NextDialogue"] = 51117007,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "701021:Think_End",
                },
            },
        [51117007] = {
            ["Camera"] = "807.511719,-81.339844,690.010742,0.000093,5.194338,77.734879,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "就是旁边的这间宅子里出现的那个呀！我们几个都看见过。",
            ["ContentKR"] = "옆에 있는 저택에 나타나는 그거 말이야! 우리 다 봤잖아.",
            ["DialogueId"] = 51117007,
            ["GUID"] = "7FF74FF6",
            ["NextDialogue"] = 51117008,
            ["SpeakNpcId"] = 701021,
            },
        [51117008] = {
            ["Content"] = "那白色的影子会飞，会浮在空中，还会突然出现、突然消失，你觉得那到底是什么？",
            ["ContentKR"] = "이리저리 날아다녔다가, 공중에 둥둥 떠 있다가, 갑자기 뿅 나타났다, 슉 사라졌다 하던데, 그게 대체 뭘까?",
            ["DialogueId"] = 51117008,
            ["GUID"] = "7FF75020",
            ["NextDialogue"] = 51117009,
            ["SpeakNpcId"] = 701021,
            },
        [51117009] = {
            ["Camera"] = "-102.625977,389.867188,178.47168,0.000117,-10.004881,-94.054535,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我觉得是狴犴！身为执法者，狴犴在有人的地方要时刻保持威严，但一直这样多累呀，所以它们会偷偷跑进这间没人的宅子里嬉戏玩耍。",
            ["ContentKR"] = "폐안 맞다니까! 폐안은 법의 집행자라 사람들 앞에선 근엄해야 하는데, 맨날 얼마나 힘들겠어. 그러니까 빈집에 몰래 들어가서 노는 거야.",
            ["DialogueId"] = 51117009,
            ["GUID"] = "7FF7504A",
            ["LookAt"] = {
                [1] = "701021:n(701022)",
                [2] = "701022:n(701021)",
                [3] = "100001:n(701022)",
                },
            ["NextDialogue"] = 51117010,
            ["SpeakNpcId"] = 701022,
            ["TalkActionId"] = {
                [1] = "701022:Talk01_Start",
                },
            },
        [51117010] = {
            ["Content"] = "说什么傻话呢，狴犴可是大风九章的使者，又不是你家的狗狗，才不需要玩呢！而且这座宅子最近有人住了。",
            ["ContentKR"] = "바보야? 폐안이 대풍구장의 사자지 너네 집 강아지야? 놀긴 뭘 놀아! 그리고 저 집에 요즘 사람 살거든!",
            ["DialogueId"] = 51117010,
            ["GUID"] = "7FF75074",
            ["LookAt"] = {
                [1] = "100001:n(701021)",
                },
            ["NextDialogue"] = 51117011,
            ["SpeakNpcId"] = 701021,
            ["TalkActionId"] = {
                [1] = "701022:Talk01_End",
                },
            },
        [51117011] = {
            ["Content"] = "我觉得那个白色影子一定是无由生。它可能是这个宅子的上一任主人变的，因为太喜欢这座宅子，所以不愿意离开……",
            ["ContentKR"] = "내 생각엔 틀림없이 무유생이야. 저 집 집주인이었던 사람이 무유생이 된 거지. 집을 너무너무 좋아해서, 떠나기 싫으니까...",
            ["DialogueId"] = 51117011,
            ["GUID"] = "7FF7509E",
            ["NextDialogue"] = 51117012,
            ["SpeakNpcId"] = 701021,
            ["TalkActionId"] = {
                [1] = "701021:Talk02_Start",
                },
            },
        [51117012] = {
            ["Content"] = "如果真的是宅子主人变的，怎么会现在才出现呢？",
            ["ContentKR"] = "집주인이 변한 거면, 왜 이제야 나타난 건데?",
            ["DialogueId"] = 51117012,
            ["GUID"] = "7FF750C8",
            ["LookAt"] = {
                [1] = "100001:n(701022)",
                },
            ["NextDialogue"] = 51117013,
            ["SpeakNpcId"] = 701022,
            ["TalkActionId"] = {
                [1] = "701021:Talk02_End",
                },
            },
        [51117013] = {
            ["Content"] = "无由生可以活很久很久，说不定它之前是出门玩了呀。",
            ["ContentKR"] = "무유생은 엄청 오래 살잖아. 그동안 어디 놀러 갔다 왔나 보지.",
            ["DialogueId"] = 51117013,
            ["GUID"] = "7FF750F2",
            ["LookAt"] = {
                [1] = "100001:n(701021)",
                },
            ["NextDialogue"] = 51117014,
            ["SpeakNpcId"] = 701021,
            },
        [51117014] = {
            ["Content"] = "可是无由生的颜色也不是白的呀！",
            ["ContentKR"] = "그치만 무유생은 하얀색이 아니잖아!",
            ["DialogueId"] = 51117014,
            ["GUID"] = "7FF7511C",
            ["LookAt"] = {
                [1] = "100001:n(701022)",
                },
            ["NextDialogue"] = 51117015,
            ["SpeakNpcId"] = 701022,
            ["TalkActionId"] = {
                [1] = "701022:Explain01_Start",
                },
            },
        [51117015] = {
            ["Content"] = "你怎么知道没有白的无由生？无由生才会飞，狴犴又不会飞。",
            ["ContentKR"] = "하얀색 무유생이 있는지 없는지 네가 어떻게 알아? 그리고 무유생은 날 수 있잖아. 폐안은 못 날고!",
            ["DialogueId"] = 51117015,
            ["GUID"] = "7FF75146",
            ["LookAt"] = {
                [1] = "100001:n(701021)",
                },
            ["NextDialogue"] = 51117016,
            ["SpeakNpcId"] = 701021,
            ["TalkActionId"] = {
                [1] = "701022:Explain01_End",
                },
            },
        [51117016] = {
            ["Content"] = "你怎么知道没有会飞的狴犴？",
            ["ContentKR"] = "너야말로 하늘을 나는 폐안이 있는지 없는지 어떻게 알아!",
            ["DialogueId"] = 51117016,
            ["GUID"] = "7FF75170",
            ["LookAt"] = {
                [1] = "100001:n(701022)",
                },
            ["NextDialogue"] = 51117017,
            ["SpeakNpcId"] = 701022,
            },
        [51117017] = {
            ["Content"] = "……哼！{性别：大哥哥|大姐姐}，你说呢，你觉得那是无由生还是狴犴？",
            ["ContentKR"] = "...흥! {性别:오빠|언니} 생각은 어때? 그건 무유생일까, 아니면 폐안일까?",
            ["DialogueId"] = 51117017,
            ["GUID"] = "7FF7519A",
            ["LookAt"] = {
                [1] = "701021:n(100001)",
                [2] = "701022:n(100001)",
                },
            ["NextOptions"] = {
                [1] = 51117018,
                },
            ["RestartTag"] = 51117017,
            ["SpeakNpcId"] = 701021,
            },
        [51117018] = {
            ["Content"] = "（白色影子吗……会是什么呢？）",
            ["ContentKR"] = "(하얀 그림자라... 대체 뭘까?)",
            ["DialogueId"] = 51117018,
            ["FailDialogue"] = 51117019,
            ["GUID"] = "7FF751C4",
            ["ImprCheckId"] = 1125,
            ["NextDialogue"] = 51117020,
            },
        [51117019] = {
            ["Content"] = "（一时没想到答案。）",
            ["ContentKR"] = "(지금은 딱히 떠오르는 게 없다.)",
            ["DialogueId"] = 51117019,
            ["GUID"] = "7FF751EE",
            },
        [51117020] = {
            ["Content"] = "我觉得你们说的都不对。我猜那个白色影子是住在这里的人养的小宠物。",
            ["ContentKR"] = "둘 다 아닐 것 같아. 그냥 저 집에 사는 사람이 키우는 동물이겠지.",
            ["DialogueId"] = 51117020,
            ["GUID"] = "7FF75218",
            ["NextDialogue"] = 51117021,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk01_Start",
                },
            },
        [51117021] = {
            ["Content"] = "啊……？",
            ["ContentKR"] = "엥...?",
            ["DialogueId"] = 51117021,
            ["GUID"] = "7FF75242",
            ["NextDialogue"] = 51117022,
            ["SpeakNpcId"] = 701021,
            },
        [51117022] = {
            ["Content"] = "小宠物……是说小猫小狗吗？可是我们看到的那个影子会瞬间消失诶！",
            ["ContentKR"] = "키운다면... 고양이나 강아지 같은 거? 근데 우리가 본 건 순식간에 뿅 사라졌단 말이야!",
            ["DialogueId"] = 51117022,
            ["GUID"] = "7FF7526C",
            ["NextDialogue"] = 51117023,
            ["SpeakNpcId"] = 701021,
            ["TalkActionId"] = {
                [1] = "701021:Talk02_Start",
                },
            },
        [51117023] = {
            ["Content"] = "对呀，而且它有时候飞得特别快，比我们家的小猫被擀面杖吓得跳起来的速度还快。",
            ["ContentKR"] = "맞아! 그리고 엄청 빨리 날아다녔어! 우리 집 고양이가 화들짝 놀라서 폴짝 뛸 때보다 빨랐다니까!",
            ["DialogueId"] = 51117023,
            ["GUID"] = "7FF75296",
            ["NextDialogue"] = 51117024,
            ["SpeakNpcId"] = 701022,
            ["TalkActionId"] = {
                [1] = "701022:Think_Start",
                [2] = "701021:Talk02_End",
                },
            },
        [51117024] = {
            ["Content"] = "不信的话，你们就敲门问问看。",
            ["ContentKR"] = "못 믿겠으면 찾아가서 물어보면 되잖아.",
            ["DialogueId"] = 51117024,
            ["GUID"] = "7FF752C0",
            ["NextDialogue"] = 51117025,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "701022:Think_End",
                },
            },
        [51117025] = {
            ["Content"] = "可、可是里面住的是个陌生人……",
            ["ContentKR"] = "그, 그치만 누가 사는지 모르는데...",
            ["DialogueId"] = 51117025,
            ["GUID"] = "7FF752EA",
            ["NextDialogue"] = 51117026,
            ["SpeakNpcId"] = 701021,
            ["TalkActionId"] = {
                [1] = "100001:Talk01_End",
                },
            },
        [51117026] = {
            ["Content"] = "听我外婆讲，这个宅子里住的好像是很厉害的大人物，万一那个大人物听了生气了怎么办？",
            ["ContentKR"] = "우리 할머니가, 저 집엔 엄청나게 대단한 사람이 산다고 그랬어. 괜히 물어봤다가 막 화내면 어떡해?",
            ["DialogueId"] = 51117026,
            ["GUID"] = "7FF75314",
            ["NextDialogue"] = 51117028,
            ["SpeakNpcId"] = 701022,
            },
        [51117027] = {
            ["Content"] = "第三个小孩入场",
            ["ContentKR"] = "세 번째 아이 등장",
            ["DialogueId"] = 51117027,
            ["GUID"] = "7FF7533E",
            },
        [51117028] = {
            ["Camera"] = "-183.449219,717.648438,135.62793,0.000058,-3.004539,-77.045387,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "咦？兰叶，望南，你们两个怎么在这里呀？",
            ["ContentKR"] = "어? 란예야, 왕남아, 너네 여기서 뭐 해?",
            ["DialogueId"] = 51117028,
            ["GUID"] = "7FF75368",
            ["LookAt"] = {
                [1] = "701021:n(701023)",
                [2] = "701022:n(701023)",
                [3] = "100001:n(701023)",
                [4] = "701023:n(100001)",
                },
            ["NextDialogue"] = 51117029,
            ["Scripts"] = "MoveTo{ActorId{701023},TargetPoint{\"YuXian_Target\"},MoveSpeed{100},Visibility{\"Show\"}}",
            ["SpeakNpcId"] = 701023,
            },
        [51117029] = {
            ["Camera"] = "-157.855469,429.066406,150.193359,0.000067,-5.60486,-83.644531,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我们正在辩论那个白色影子的真身呢！",
            ["ContentKR"] = "전에 봤던 그 하얀 그림자가 뭔지 토론하고 있었어!",
            ["DialogueId"] = 51117029,
            ["GUID"] = "7FF75392",
            ["LookAt"] = {
                [1] = "701021:n(701021)",
                [2] = "701022:n(701021)",
                [3] = "100001:n(701021)",
                [4] = "701023:n(701021)",
                },
            ["NextDialogue"] = 51117030,
            ["SpeakNpcId"] = 701021,
            },
        [51117030] = {
            ["Content"] = "噢，这个呀，我已经知道啦。我昨天经过这里的时候恰好遇见了住在里面的姐姐，她说那个白色的影子是“鱼龙”。",
            ["ContentKR"] = "아, 그거? 난 뭔지 아는데. 어제 여기 지나가다가 안에 사는 언니를 만났거든. 그 하얀 그림자는 '어룡'이래.",
            ["DialogueId"] = 51117030,
            ["GUID"] = "7FF753BC",
            ["LookAt"] = {
                [1] = "701021:n(701023)",
                [2] = "701022:n(701023)",
                [3] = "100001:n(701023)",
                [4] = "701023:n(701023)",
                },
            ["NextDialogue"] = 51117031,
            ["SpeakNpcId"] = 701023,
            ["TalkActionId"] = {
                [1] = "701023:Explain01_Start",
                },
            },
        [51117031] = {
            ["Content"] = "她解释了一大堆什么“寄托”呀，“思念”呀什么的，我不太听得懂……反正就是类似于小宠物的东西啦！",
            ["ContentKR"] = "'염원'이랑 '그리움' 같은 어려운 말을 잔뜩 써서 설명해 줬는데, 잘은 모르겠고... 아무튼 애완동물 비슷한 거야!",
            ["DialogueId"] = 51117031,
            ["GUID"] = "7FF753E6",
            ["NextDialogue"] = 51117032,
            ["SpeakNpcId"] = 701023,
            },
        [51117032] = {
            ["Content"] = "她还变了一只出来给我看呢，“鱼龙”摸上去就像水做的一样，凉凉的，可神奇了！",
            ["ContentKR"] = "그 언니가 '어룡'을 한 마리 소환해서 보여 줬는데, 물 만지는 느낌처럼 차가워서, 엄청 신기했어!",
            ["DialogueId"] = 51117032,
            ["GUID"] = "7FF75410",
            ["NextDialogue"] = 51117033,
            ["SpeakNpcId"] = 701023,
            ["TalkActionId"] = {
                [1] = "701023:Explain01_End",
                },
            },
        [51117033] = {
            ["Content"] = "什么？！",
            ["ContentKR"] = "뭐?!",
            ["DialogueId"] = 51117033,
            ["GUID"] = "7FF7543A",
            ["LookAt"] = {
                [1] = "701021:n(701021)",
                [2] = "701022:n(701021)",
                [3] = "100001:n(701021)",
                [4] = "701023:n(701021)",
                },
            ["NextDialogue"] = 51117034,
            ["SpeakNpcId"] = 701021,
            },
        [51117034] = {
            ["Content"] = "居、居然真的是小宠物……",
            ["ContentKR"] = "지, 진짜 애완동물이었을 줄이야...",
            ["DialogueId"] = 51117034,
            ["GUID"] = "7FF75464",
            ["LookAt"] = {
                [1] = "701021:n(701022)",
                [2] = "701022:n(701022)",
                [3] = "100001:n(701022)",
                [4] = "701023:n(701022)",
                },
            ["NextDialogue"] = 51117035,
            ["SpeakNpcId"] = 701023,
            },
        [51117035] = {
            ["Content"] = "没想到最后是这个{性别：大哥哥|大姐姐}猜对了……",
            ["ContentKR"] = "결국 이 {性别:오빠|언니} 말이 맞았네...",
            ["DialogueId"] = 51117035,
            ["GUID"] = "7FF7548E",
            ["LookAt"] = {
                [1] = "701021:n(100001)",
                [2] = "701022:n(100001)",
                [3] = "100001:n(100001)",
                [4] = "701023:n(100001)",
                },
            ["NextOptions"] = {
                [1] = 51117036,
                [2] = 51117040,
                [3] = 51117044,
                },
            ["SpeakNpcId"] = 701021,
            },
        [51117036] = {
            ["Content"] = "其实是因为我也见过那位姐姐，所以才能猜对的。",
            ["ContentKR"] = "사실 나도 저 집에 사는 사람을 만나 본 적이 있거든. 그래서 맞힌 거야.",
            ["DialogueId"] = 51117036,
            ["GUID"] = "7FF754B8",
            ["ImprPlusId"] = 1207,
            ["NextDialogue"] = 51117037,
            },
        [51117037] = {
            ["Content"] = "怎么你也见过？那我也要见。",
            ["ContentKR"] = "그게 진짜야? 나도 만나러 갈래!",
            ["DialogueId"] = 51117037,
            ["GUID"] = "7FF754E2",
            ["LookAt"] = {
                [1] = "701021:n(701023)",
                [2] = "701022:n(701021)",
                [3] = "100001:n(701021)",
                [4] = "701023:n(701021)",
                },
            ["NextDialogue"] = 51117038,
            ["SpeakNpcId"] = 701021,
            ["TalkActionId"] = {
                [1] = "701021:Talk01_Start",
                },
            },
        [51117038] = {
            ["Content"] = "我也要，我也要！",
            ["ContentKR"] = "나도! 나도, 나도!",
            ["DialogueId"] = 51117038,
            ["GUID"] = "7FF7550C",
            ["LookAt"] = {
                [1] = "701021:n(701023)",
                [2] = "701022:n(701023)",
                [3] = "100001:n(701022)",
                [4] = "701023:n(701022)",
                },
            ["NextDialogue"] = 51117039,
            ["SpeakNpcId"] = 701022,
            },
        [51117039] = {
            ["Content"] = "嗯……那下次我们带点好吃的去找那个姐姐玩，让她也给我们看看“鱼龙”吧~",
            ["ContentKR"] = "음... 그럼 다음엔 맛있는 거 챙겨가서 그 언니랑 같이 놀자. '어룡'도 보여 달라고 하고~",
            ["DialogueId"] = 51117039,
            ["GUID"] = "7FF75536",
            ["NextDialogue"] = 51117048,
            ["SpeakNpcId"] = 701021,
            ["TalkActionId"] = {
                [1] = "701021:Talk01_End",
                },
            },
        [51117040] = {
            ["Content"] = "也可能你们看到的是其他的白色影子。",
            ["ContentKR"] = "어쩌면 너희가 본 건 어룡이 아닐 수도 있어.",
            ["DialogueId"] = 51117040,
            ["GUID"] = "7FF75560",
            ["ImprPlusId"] = 1209,
            ["NextDialogue"] = 51117041,
            },
        [51117041] = {
            ["Content"] = "有道理诶！",
            ["ContentKR"] = "하긴 그러네!",
            ["DialogueId"] = 51117041,
            ["GUID"] = "7FF7558A",
            ["LookAt"] = {
                [1] = "701021:n(701021)",
                [2] = "701022:n(701021)",
                [3] = "100001:n(701021)",
                [4] = "701023:n(701021)",
                },
            ["NextDialogue"] = 51117042,
            ["SpeakNpcId"] = 701021,
            ["TalkActionId"] = {
                [1] = "701021:Talk01_Start",
                },
            },
        [51117042] = {
            ["Content"] = "也许这宅子里既有鱼龙，也有狴犴，还有无由生！",
            ["ContentKR"] = "그 집엔 어룡이랑 폐안이랑 무유생이 다 같이 사는 걸지도 몰라!",
            ["DialogueId"] = 51117042,
            ["GUID"] = "7FF755B4",
            ["NextDialogue"] = 51117043,
            ["SpeakNpcId"] = 701021,
            },
        [51117043] = {
            ["Content"] = "那我们都说对了，好耶~",
            ["ContentKR"] = "그러면 우리 둘 다 맞힌 거네! 야호~",
            ["DialogueId"] = 51117043,
            ["GUID"] = "7FF755DE",
            ["LookAt"] = {
                [1] = "701021:n(701022)",
                [2] = "701022:n(701022)",
                [3] = "100001:n(701022)",
                [4] = "701023:n(701022)",
                },
            ["NextDialogue"] = 51117048,
            ["SpeakNpcId"] = 701022,
            ["TalkActionId"] = {
                [1] = "701021:Talk01_End",
                },
            },
        [51117044] = {
            ["Content"] = "哼哼，这就是大人的实力。",
            ["ContentKR"] = "후후, 이게 바로 어른의 실력이란 거야.",
            ["DialogueId"] = 51117044,
            ["GUID"] = "7FF75608",
            ["ImprPlusId"] = 1210,
            ["NextDialogue"] = 51117045,
            },
        [51117045] = {
            ["Content"] = "那我长大以后也要变得这么聪明。",
            ["ContentKR"] = "그럼 나도 커서 이렇게 똑똑한 어른이 될래.",
            ["DialogueId"] = 51117045,
            ["GUID"] = "7FF75632",
            ["LookAt"] = {
