                [2] = "701022:n(701022)",
                [3] = "100001:n(701022)",
                [4] = "701023:n(701022)",
                },
            ["NextDialogue"] = 51117046,
            ["SpeakNpcId"] = 701022,
            ["TalkActionId"] = {
                [1] = "701022:Talk01_Start",
                },
            },
        [51117046] = {
            ["Content"] = "我要变得比这个{性别：大哥哥|大姐姐}还聪明！",
            ["ContentKR"] = "난 이 {性别:오빠|언니}보다 훨씬 더 똑똑해질 거야!",
