            ["NextDialogue"] = 51120014,
            },
        [51120014] = {
            ["Content"] = "假药？如何见得？那姑娘现在还没服下一口，客人您也未见成效，如何能断定我卖的是假药呢？",
            ["ContentKR"] = "가짜 약이라뇨? 무슨 말씀이신지요? 그 아가씨는 아직 약을 먹지 않았고, 손님께서도 약의 효과를 못 보셨지요. 그런데 어찌 가짜라 단정 지으십니까?",
            ["DialogueId"] = 51120014,
            ["GUID"] = "7FF93D4C",
            ["NextDialogue"] = 51120017,
            ["SpeakNpcId"] = 701027,
            },
        [51120015] = {
            ["Content"] = "你得给我开点封口费了吧。",
