            },
        [51125087] = {
            ["Content"] = "呔！哪里逃！",
            ["ContentKR"] = "이 녀석! 어딜 도망가느냐!",
            ["DialogueId"] = 51125087,
            ["GUID"] = "7FFC7D96",
            ["NextDialogue"] = 51125088,
            ["SpeakNpcId"] = 700379,
            },
        [51125088] = {
            ["Content"] = "看针！",
            ["ContentKR"] = "이 독침 맛을 봐라!",
            ["DialogueId"] = 51125088,
            ["GUID"] = "7FFC7DC0",
            ["NextDialogue"] = 51125089,
            ["SpeakNpcId"] = 100001,
            },
        [51125089] = {
            ["Content"] = "哼！区区毒针，我避它锋芒！",
            ["ContentKR"] = "하핫! 그까짓 독침 따윈 가뿐히 피해 주마!",
            ["DialogueId"] = 51125089,
            ["GUID"] = "7FFC7DEA",
            ["SpeakNpcId"] = 700379,
            },
        [51125090] = {
            ["DialogueId"] = 51125090,
            ["GUID"] = "7FFC7E14",
            ["IsBlack"] = 1,
            },
        [51125091] = {
            ["Content"] = "等等，这不在剧本里吧。",
            ["ContentKR"] = "저기요, 방금 건 대본에 없었잖아요.",
            ["DialogueId"] = 51125091,
            ["GUID"] = "7FFC7E3E",
            ["NextDialogue"] = 51125092,
            ["SpeakNpcId"] = 100001,
            },
        [51125092] = {
            ["Content"] = "咿嘻嘻嘻嘻，你这小毒针算什么啊。我手上这把，可是沾满了剧毒的大斧哦~",
            ["ContentKR"] = "이히히히히, 그 쪼그만 독침으로 뭘 하겠다는 거야. 이 보검엔 맹독이 잔뜩 발려 있다고~",
            ["DialogueId"] = 51125092,
            ["GUID"] = "7FFC7E68",
            ["NextDialogue"] = 51125093,
            ["SpeakNpcId"] = 700379,
            },
        [51125093] = {
            ["Content"] = "（怎么又在加戏！）",
            ["ContentKR"] = "(왜 또 애드리브야!)",
            ["DialogueId"] = 51125093,
            ["GUID"] = "7FFC7E92",
            ["SpeakNpcId"] = 100001,
            },
        [51125094] = {
            ["DialogueId"] = 51125094,
            ["GUID"] = "7FFC7EBC",
            ["IsBlack"] = 1,
            },
        [51125095] = {
            ["Camera"] = "493.785156,-135.24707,12.011719,0.017552,14.799428,162.905365,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "应天尉大人，你再英明神武，也敌不过这背后的毒针吧！",
            ["ContentKR"] = "날고 기는 응천위 나리라도 뒤에서 날아드는 독침은 당해 낼 수 없나 보군!",
            ["DialogueId"] = 51125095,
            ["GUID"] = "7FFC7EE6",
            ["NextDialogue"] = 51125096,
            ["SpeakNpcId"] = 100001,
            },
        [51125096] = {
            ["Camera"] = "43.136719,-3.177734,147.396484,0.017532,-2.399165,-177.490891,45.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……………………",
            ["ContentKR"] = "......",
            ["DialogueId"] = 51125096,
            ["GUID"] = "7FFC7F10",
            ["NextDialogue"] = 51125097,
            ["SpeakNpcId"] = 700379,
            },
        [51125097] = {
            ["Camera"] = "-63.742188,-75.883789,146.362305,0.017534,-2.399595,19.908815,45.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "说台词啊！",
            ["ContentKR"] = "대사 쳐야죠!",
            ["DialogueId"] = 51125097,
            ["GUID"] = "7FFC7F3A",
            ["NextDialogue"] = 51125098,
            ["SpeakNpcId"] = 100001,
            },
        [51125098] = {
            ["Camera"] = "55.546875,-172.925781,148.643555,0.017533,-2.399322,141.50882,45.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "什么词来着？",
            ["ContentKR"] = "대사가 뭐였지?",
            ["DialogueId"] = 51125098,
            ["GUID"] = "7FFC7F64",
            ["NextDialogue"] = 51125099,
            ["SpeakNpcId"] = 700379,
            },
        [51125099] = {
            ["Camera"] = "-40.277344,-15.838867,165.15625,0.017561,-8.200645,2.511383,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "“你家族世代为悬衡派香官，满门忠良，怎就出了你这败类！”",
            ["ContentKR"] = "\"네 녀석의 가문은 대대로 현형파의 향관을 배출한 충신 집안이거늘, 어찌 너 같은 인간 말종이 나왔단 말이냐!\"",
            ["DialogueId"] = 51125099,
            ["GUID"] = "7FFC7F8E",
            ["NextDialogue"] = 51125100,
            ["SpeakNpcId"] = 100001,
            },
        [51125100] = {
            ["Camera"] = "7.867188,-1148.030273,172.847656,0.017538,-3.199889,90.504539,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嘿，骂谁败类呢？怎么就败类了呢？你想想，我们在悬衡派干的那都是什么活啊，报酬没给多少，一天到晚烧个破香熏得要死，假期也没几天。",
            ["ContentKR"] = "와, 인간 말종이라니? 말이 너무 심하네? 있지, 우리 현형파는 쥐꼬리만 한 보수나 받으면서, 일 년에 며칠 쉬지도 못하고, 하루 종일 죽어라 향만 피운다고.",
            ["DialogueId"] = 51125100,
            ["GUID"] = "7FFC7FB8",
            ["NextDialogue"] = 51125101,
            ["SpeakNpcId"] = 700379,
            },
        [51125101] = {
            ["Content"] = "还整天受大风九章的条条框框拘束，连踹条路边的狗都不行，万一一不小心踹到了主人，还得担心被当成行凶。",
            ["ContentKR"] = "게다가 우리는 지나다니는 개 한 마리도 못 건드려. 개 주인이 학대니 뭐니 따지고 들면, 대풍구장을 어기는 게 돼 버릴 테니까.",
            ["DialogueId"] = 51125101,
            ["GUID"] = "7FFC7FE2",
            ["NextDialogue"] = 51125102,
            ["SpeakNpcId"] = 700379,
            },
        [51125102] = {
            ["Camera"] = "-40.277344,-15.838867,165.15625,0.017561,-8.200645,2.511383,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "等一下……",
            ["ContentKR"] = "아니, 잠깐만요...",
            ["DialogueId"] = 51125102,
            ["GUID"] = "7FFC800C",
            ["NextDialogue"] = 51125103,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:RaiseHand_Start",
                },
            },
        [51125103] = {
            ["Camera"] = "55.546875,-172.925781,148.643555,0.017533,-2.399322,141.50882,45.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "事儿办好了都是白龙神君英明神武，办砸了都是我们办事不力！还不如当个飘零人，逍遥自在！",
            ["ContentKR"] = "다들 그냥, 잘되면 백룡신군 덕이고 안되면 우리 때문이지! 그럴 바에야 자유로운 나그네가 되는 게 훨씬 낫다고!",
            ["DialogueId"] = 51125103,
            ["GUID"] = "7FFC8036",
            ["NextDialogue"] = 51125104,
            ["SpeakNpcId"] = 700379,
            },
        [51125104] = {
            ["Content"] = "嘻嘻，看是你应天尉的命硬，还是我飘零人的刀子硬！吃我正义的毒针！",
            ["ContentKR"] = "흐흐, 우리가 나가떨어지는 게 먼저일지, 응천위 나리 목숨줄이 끊어지는 게 먼저일지 보자고! 내 정의의 독침을 받아랏!",
            ["DialogueId"] = 51125104,
            ["GUID"] = "7FFC8060",
            ["SpeakNpcId"] = 700379,
            },
        [51125105] = {
            ["DialogueId"] = 51125105,
            ["GUID"] = "7FFC808A",
            },
        [51125106] = {
            ["Camera"] = "2.65625,-886.189453,212.766602,0.017553,-6.600674,89.711586,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "精彩，一气呵成行云流水！果然横生你就是万里挑一的天选反派！",
            ["ContentKR"] = "훌륭해! 물 흐르듯 자연스러웠어! 진상, 넌 역시 하늘이 내린 타고난 악역이야!",
            ["DialogueId"] = 51125106,
            ["FacialId"] = {
                [1] = "700365:CM_Happy01",
                },
            ["GUID"] = "7FFC80B4",
            ["NextDialogue"] = 51125107,
            ["SpeakNpcId"] = 700365,
            },
        [51125107] = {
            ["Content"] = "不拍了不拍了，收工！烟津渡这几场最后就靠我的导演剪辑版来救一救吧。",
            ["ContentKR"] = "자, 촬영 끝! 철수! 연진 나루터 장면들은 내가 감독판 편집할 때 어떻게든 살려 볼게.",
            ["DialogueId"] = 51125107,
            ["GUID"] = "7FFC80DE",
            ["LookAt"] = {
                [1] = "700365:n(700379)",
                },
            ["NextDialogue"] = 51125108,
            ["SpeakNpcId"] = 700365,
            },
        [51125108] = {
            ["Content"] = "{性别：兄弟|姑娘}，这是你今天拍戏的报酬，拿好了。",
            ["ContentKR"] = "{性别:친구|아가씨}, 이거 오늘 출연료야. 받아 둬.",
            ["DialogueId"] = 51125108,
            ["GUID"] = "7FFC8108",
            ["LookAt"] = {
                [1] = "700365:n(100001)",
                },
            ["NextDialogue"] = 51125109,
            ["SpeakNpcId"] = 700365,
            },
        [51125109] = {
            ["Content"] = "（这一场荒唐的闹剧总算是落下了帷幕。横生如愿以偿地留下了他的高光时刻……或许。）",
            ["ContentKR"] = "(이 황당한 소동도 드디어 막을 내렸다. 진상은 바라던 대로 관객의 시선을 사로잡을 수 있을 것이다... 아마도.)",
            ["DialogueId"] = 51125109,
            ["GUID"] = "7FFC8132",
            ["IsBlack"] = 1,
            },
        [51125201] = {
            ["Content"] = "呼……可算搬完了，这下没有遗漏了吧？",
            ["ContentKR"] = "휴... 겨우 다 옮겼네. 이제 빠뜨린 거 없지?",
            ["DialogueId"] = 51125201,
            ["GUID"] = "7FFC904A",
            ["NextDialogue"] = 51125202,
            ["SpeakNpcId"] = 701034,
            },
        [51125202] = {
            ["Content"] = "还没完呢，今天阿庄哥休工，咱俩得把他那一份也搬完。",
            ["ContentKR"] = "아니, 오늘은 장 형이 쉬는 날이라, 우리가 그 형 몫까지 다 옮겨야 해.",
            ["DialogueId"] = 51125202,
            ["GUID"] = "7FFC9074",
            ["NextDialogue"] = 51125203,
            ["SpeakNpcId"] = 701035,
            },
        [51125203] = {
            ["Content"] = "为何不让他明天自己来？",
            ["ContentKR"] = "내일 자기가 직접 옮기라고 하면 되잖아?",
            ["DialogueId"] = 51125203,
            ["GUID"] = "7FFC909E",
            ["NextDialogue"] = 51125204,
            ["SpeakNpcId"] = 701034,
            },
        [51125204] = {
            ["Content"] = "阿庄哥说家里有喜事，回来请咱们吃茶呢！",
            ["ContentKR"] = "집에 좋은 일이 있대. 돌아오면 차 한잔 사 주겠다던데.",
            ["DialogueId"] = 51125204,
            ["GUID"] = "7FFC90C8",
            ["NextDialogue"] = 51125205,
            ["SpeakNpcId"] = 701035,
            },
        [51125205] = {
            ["Content"] = "嘿！有好事也不叫我们，可得敲他一壶上好的碧茅！",
            ["ContentKR"] = "어이쿠! 좋은 일이 있는데 우릴 안 불러? 제일 비싼 차로 얻어 마셔야겠어!",
            ["DialogueId"] = 51125205,
            ["GUID"] = "7FFC90F2",
            ["SpeakNpcId"] = 701034,
            },
        [51125301] = {
            ["Content"] = "您别说，咱们华胥就是数一数二的安全，看到那四处巡逻的狴犴了没？但凡有奸人作恶，都会被迅速逮捕！",
            ["ContentKR"] = "아니, 우리 화서만큼 안전한 곳이 없다니까? 저기 순찰 도는 폐안들 보여? 나쁜 놈이 나쁜 짓 하려고 하면, 바로 잡혀가!",
            ["DialogueId"] = 51125301,
            ["GUID"] = "7FFCA0B2",
            ["NextDialogue"] = 51125302,
            ["SpeakNpcId"] = 701036,
            },
        [51125302] = {
            ["Content"] = "哼，我们海伯利亚也很安全的，知道帝国军团的威名吗？帝国的铁骑会踏破每一句反抗的声音。",
            ["ContentKR"] = "흥, 우리 휘페르보레아 제국도 안전하거든? 제국 군단의 명성을 들어는 봤어? 반항의 싹이 돋기도 전에 뽑아 버리는 게 제국 철기군의 방식이야.",
            ["DialogueId"] = 51125302,
            ["GUID"] = "7FFCA0DC",
            ["NextDialogue"] = 51125303,
            ["SpeakNpcId"] = 701037,
            },
        [51125303] = {
            ["Content"] = "拉倒吧！从外头回来的织星客谁不说你们海伯利亚隔三差五就和南边打仗，这也能叫安全？",
            ["ContentKR"] = "웃기시네! 외국 갔다 온 별을 잇는 자들이 휘페르보레아 제국은 허구한 날 남쪽이랑 싸운다던데? 그게 안전한 거야?",
            ["DialogueId"] = 51125303,
            ["GUID"] = "7FFCA106",
            ["NextDialogue"] = 51125304,
            ["SpeakNpcId"] = 701036,
            },
        [51125304] = {
            ["Content"] = "打仗那是……那是帝国的本事……打仗的目的就是为了和平！",
            ["ContentKR"] = "그건... 능력이 되니까 싸우는 거야... 평화를 위한 투쟁이라고!",
            ["DialogueId"] = 51125304,
            ["GUID"] = "7FFCA130",
            ["NextDialogue"] = 51125305,
            ["SpeakNpcId"] = 701037,
            },
        [51125305] = {
            ["Content"] = "啧啧，那你为何苦苦要来华胥生活？姐们，来了华胥，只要你一心向善，白龙神君就会护佑你日日平安。",
            ["ContentKR"] = "쯧쯧, 그런데 왜 굳이 화서에서 지내려고 하는 건데? 이봐, 화서에 왔으면 마음 곱게 먹고 착하게 살아. 백룡신군께서 늘 지켜 주실 테니까.",
            ["DialogueId"] = 51125305,
            ["GUID"] = "7FFCA15A",
            ["SpeakNpcId"] = 701036,
            },
        [51125401] = {
            ["Content"] = "这荒塔倒是上了年头了，想来曾经也是咱们机枢派的杰作，竟任由它被风吹雨打，无人维护……",
            ["ContentKR"] = "이 버려진 탑도 꽤 오래됐네. 한때는 우리 기추파의 걸작이었는데, 관리해 주는 사람이 아무도 없다니...",
            ["DialogueId"] = 51125401,
            ["GUID"] = "7FFCB11A",
            ["NextOptions"] = {
                [1] = 51125402,
                },
            ["SpeakNpcId"] = 701038,
            },
        [51125402] = {
            ["Content"] = "这是做什么用的？",
            ["ContentKR"] = "이 탑의 용도는 뭐예요?",
            ["DialogueId"] = 51125402,
            ["GUID"] = "7FFCB144",
            ["NextDialogue"] = 51125403,
            },
        [51125403] = {
            ["Content"] = "放在以前，是机枢派帮助织星客们建造的卜天楼，但要说现在……无人在意的废铜烂铁罢了。",
            ["ContentKR"] = "기추파가 별을 잇는 자들을 도와 지었던 복천루야. 그렇지만 지금은... 거들떠보는 사람 하나 없는 고철 덩어리지.",
            ["DialogueId"] = 51125403,
            ["GUID"] = "7FFCB16E",
            ["NextOptions"] = {
                [1] = 51125404,
                },
            ["SpeakNpcId"] = 701038,
            },
        [51125404] = {
            ["Content"] = "卜天楼是？",
            ["ContentKR"] = "복천루는 뭐죠?",
            ["DialogueId"] = 51125404,
            ["GUID"] = "7FFCB198",
            ["NextDialogue"] = 51125405,
            },
        [51125405] = {
            ["Content"] = "卜算天象，测绘吉凶。说是这么说，但没这么玄乎，只是用于更好观测星空，推断后几日的天气情况的装置罢了。",
            ["ContentKR"] = "하늘의 움직임을 보고 길흉을 점치는 탑이야. 말이 그렇지, 실제론 별자리를 잘 관찰해서 며칠 뒤 날씨를 예측하는 장치에 불과하지만.",
            ["DialogueId"] = 51125405,
            ["GUID"] = "7FFCB1C2",
            ["NextOptions"] = {
                [1] = 51125406,
                },
            ["SpeakNpcId"] = 701038,
            },
        [51125406] = {
            ["Content"] = "那为什么荒废了？",
            ["ContentKR"] = "그런데 왜 버려진 거예요?",
            ["DialogueId"] = 51125406,
            ["GUID"] = "7FFCB1EC",
            ["NextDialogue"] = 51125407,
            },
        [51125407] = {
            ["Content"] = "……那可就说来话长了。最开始只是机枢派落魄，塔楼少人维护，计量结果也不怎么灵准了。",
            ["ContentKR"] = "...말하자면 길지만, 어쨌든 가장 큰 이유는 기추파가 몰락하면서 관리할 사람이 없어졌고, 정확도가 떨어졌기 때문일 거야.",
            ["DialogueId"] = 51125407,
            ["GUID"] = "7FFCB216",
            ["NextDialogue"] = 51125408,
            ["SpeakNpcId"] = 701038,
            },
        [51125408] = {
            ["Content"] = "后面织星客们改良了千星板，也能起到一定预测天气的作用，这塔便失去了作用。",
            ["ContentKR"] = "나중엔 별을 잇는 자들이 개량한 천성판으로도 날씨를 어느 정도 예측할 수 있게 되면서, 이 탑은 쓸모가 없어져 버린 거지.",
            ["DialogueId"] = 51125408,
            ["GUID"] = "7FFCB240",
            ["NextDialogue"] = 51125409,
            ["SpeakNpcId"] = 701038,
            },
        [51125409] = {
            ["Content"] = "不过要我说，若是机枢派还和百年以前一样风光，这塔应早该被后人迭新出其他作用才对。",
            ["ContentKR"] = "기추파의 위세가 백 년 전처럼 드높았다면, 후학들이 진작에 새로운 쓸모를 찾아 줬겠지만 말이야.",
            ["DialogueId"] = 51125409,
            ["GUID"] = "7FFCB26A",
            ["NextDialogue"] = 51125410,
            ["SpeakNpcId"] = 701038,
            },
        [51125410] = {
            ["Content"] = "唉……都成过往，何必追溯。罢了，罢了……",
            ["ContentKR"] = "하아... 다 지나간 일을 붙잡고 뭐 하겠어. 미련을 버려야지, 훌훌 털어 버려야지...",
            ["DialogueId"] = 51125410,
            ["GUID"] = "7FFCB294",
            ["SpeakNpcId"] = 701038,
            },
        [51125501] = {
            ["Content"] = "这位远来的小友，可否靠边站站？",
            ["ContentKR"] = "멀리서 온 친구, 옆으로 좀 비켜서 주지 않겠어?",
            ["DialogueId"] = 51125501,
            ["GUID"] = "7FFCC182",
            ["NextOptions"] = {
                [1] = 51125502,
                [2] = 51125505,
                },
            ["SpeakNpcId"] = 701039,
            },
        [51125502] = {
            ["Content"] = "不好意思。",
            ["ContentKR"] = "죄송해요.",
            ["DialogueId"] = 51125502,
            ["GUID"] = "7FFCC1AC",
            ["ImprPlusId"] = 1207,
            ["NextDialogue"] = 51125503,
            },
        [51125503] = {
            ["Content"] = "都是小事，异国小友来咱们华胥，恐怕也是人生地不熟，若是有什么地方疑惑不解，可以随时来问我。",
            ["ContentKR"] = "뭐 이런 걸로. 다른 나라 친구가 화서에 왔으니까, 낯설기도 하고 뭐가 뭔지 모르겠지. 궁금하거나 이해 안 되는 게 있으면 언제든 와서 물어봐.",
            ["DialogueId"] = 51125503,
            ["GUID"] = "7FFCC1D6",
            ["NextDialogue"] = 51125504,
            ["SpeakNpcId"] = 701039,
            },
        [51125504] = {
            ["Content"] = "虽说我看起来平平无奇，但怎么也算是这浮星埠数一数二的点货人，上到天文地理下到民生风情，我啊，信手拈来。",
            ["ContentKR"] = "보기엔 이래도, 난 이 별빛 부두에선 잘나가는 검수원이거든. 난 말이야, 천문, 지리부터 시작해서 사람 사는 얘기까지 모르는 게 없어.",
            ["DialogueId"] = 51125504,
            ["GUID"] = "7FFCC200",
            ["SpeakNpcId"] = 701039,
            },
        [51125505] = {
            ["Content"] = "这路好像也不是你的吧？",
            ["ContentKR"] = "그쪽이 이 길 전세 냈어요?",
            ["DialogueId"] = 51125505,
            ["GUID"] = "7FFCC22A",
            ["ImprPlusId"] = 1210,
            ["NextDialogue"] = 51125506,
            },
        [51125506] = {
            ["Content"] = "诶呀这异国小友脾气就是有些大，我这是好心提醒你，这码头货工人来人往，搬运的全是重物，要是一个不小心磕碰到了你可如何是好？",
            ["ContentKR"] = "어이쿠, 한 성격 하네. 그냥 걱정돼서 하는 얘기였어. 이 부두는 일꾼들이 무거운 짐 들고 왔다 갔다 하는데, 부딪히기라도 하면 큰일 나잖아.",
            ["DialogueId"] = 51125506,
            ["GUID"] = "7FFCC254",
            ["NextDialogue"] = 51125507,
            ["SpeakNpcId"] = 701039,
            },
        [51125507] = {
            ["Content"] = "小友初来乍到，对咱们华胥不熟悉也是正常，若是有什么不解，可随时来问我，虽说我只是个点货人，但毕竟也是土生土长的华胥之民。",
            ["ContentKR"] = "화서에 처음 왔으니까, 아무래도 익숙하지 않겠지. 뭐든 모르는 게 있으면 언제든 물어봐. 검수원 나부랭이지만, 그래도 화서 토박이거든.",
            ["DialogueId"] = 51125507,
            ["GUID"] = "7FFCC27E",
            ["SpeakNpcId"] = 701039,
            },
        [51125508] = {
            ["Content"] = "冰台五十斤，春一品三十斤，诶诶诶，那边的，香料都是稀奇货，搬运的时候可小心点！",
            ["ContentKR"] = "황해쑥 50근, 춘일품 30근... 어이, 거기! 향료는 다 귀한 물건이라니까! 옮길 때 조심하라고!",
            ["DialogueId"] = 51125508,
            ["GUID"] = "7FFCC2A8",
            ["NextDialogue"] = 51125509,
            },
        [51125509] = {
            ["Content"] = "哟，你是那位刚来华胥的异国小友吧，还在浮星埠？莫非其实是来经商的小掌柜？专门来看看我这点货人的日常活计。",
            ["ContentKR"] = "오, 얼마 전에 화서에 온 외국 친구 맞지? 아직 별빛 부두에 있었네? 혹시 장사하러 온 젊은 사장이었던 건가? 검수원은 평소에 뭐 하는지 구경하러 온 거야?",
            ["DialogueId"] = 51125509,
            ["GUID"] = "7FFCC2D2",
            ["NextOptions"] = {
                [1] = 51125510,
                [2] = 51125527,
                },
            ["SpeakNpcId"] = 701039,
            },
        [51125510] = {
            ["Content"] = "我有事要问你。",
            ["ContentKR"] = "물어볼 게 있어요.",
            ["DialogueId"] = 51125510,
            ["GUID"] = "7FFCC2FC",
            ["NextDialogue"] = 51125511,
            },
        [51125511] = {
            ["Content"] = "你便问吧，我知晓的，必定一一答复于你。",
            ["ContentKR"] = "뭐든 물어봐. 내가 아는 거라면, 전부 다 대답해 줄게.",
            ["DialogueId"] = 51125511,
            ["GUID"] = "7FFCC326",
            ["NextOptions"] = {
                [1] = 51125512,
                [2] = 51125516,
                },
            ["SpeakNpcId"] = 701039,
            },
        [51125512] = {
            ["Content"] = "点货人是干什么的？",
            ["ContentKR"] = "검수원은 무슨 일을 해요?",
            ["DialogueId"] = 51125512,
            ["GUID"] = "7FFCC350",
            ["NextDialogue"] = 51125513,
            },
        [51125513] = {
            ["Content"] = "点货人，字如其名，自然是帮着织星客们清点货品的人物啦。",
            ["ContentKR"] = "말 그대로 별을 잇는 자들 대신 화물을 검수해 주는 사람이지.",
            ["DialogueId"] = 51125513,
            ["GUID"] = "7FFCC37A",
            ["NextDialogue"] = 51125514,
            ["SpeakNpcId"] = 701039,
            },
        [51125514] = {
            ["Content"] = "这浮星埠，每日吞吐船只容量大得很，要是只让织星客们自己清点这些货物，岂不是要忙坏他们了。",
            ["ContentKR"] = "이 별빛 부두는 매일 드나드는 배가 굉장히 많아. 별을 잇는 자들이 직접 화물 수량을 확인한다면, 몸이 몇 개라도 모자랄걸.",
            ["DialogueId"] = 51125514,
            ["GUID"] = "7FFCC3A4",
            ["NextDialogue"] = 51125515,
            ["SpeakNpcId"] = 701039,
            },
        [51125515] = {
            ["Content"] = "所以我们点货人便应运而生，我们的主要任务就是帮着织星客们清点出入境的货物数量，防止有缺漏，届时也不好向国外的订购商们交代。",
            ["ContentKR"] = "그래서 우리 같은 검수원이 필요한 거야. 해외로 나가는 화물의 수량을 세서 누락된 게 없는지 확인해야, 별을 잇는 자들도 나중에 외국 상인들한테 할 말이 생기잖아.",
            ["DialogueId"] = 51125515,
            ["GUID"] = "7FFCC3CE",
            ["NextOptions"] = {
                [1] = 51125516,
                [2] = 51125527,
                },
            ["SpeakNpcId"] = 701039,
            },
        [51125516] = {
            ["Content"] = "华胥的织星客们进出运输货物都需要登记吗？",
            ["ContentKR"] = "화서의 별을 잇는 자들은 화물이 드나들 때마다 신고를 해야 하나요?",
            ["DialogueId"] = 51125516,
            ["GUID"] = "7FFCC3F8",
            ["NextDialogue"] = 51125517,
            },
        [51125517] = {
            ["Content"] = "那是自然，一方面华胥贸易发达，天禄司上下管理繁琐，这出去和进来的货多少是要收些税金。",
            ["ContentKR"] = "당연하지. 화서는 무역이 발달한 곳이라 천록사에서 꼼꼼하고 까다롭게 관리하거든. 다 세금이랑 관련된 거니까.",
            ["DialogueId"] = 51125517,
            ["GUID"] = "7FFCC422",
            ["NextDialogue"] = 51125518,
            ["SpeakNpcId"] = 701039,
            },
        [51125518] = {
            ["Content"] = "另一方面，华胥本身对一些重要香料配额管理便十分严苛，尤其是像吿苍这种本地人大量需求香料，若是任由织星客们贩至海外，咱们自己不够用如何是好？",
            ["ContentKR"] = "다른 이유는 화서에선 중요한 향료는 할당량을 아주 엄격하게 관리하기 때문이야. 고창처럼 여기서 많이 쓰는 향료를 싹 다 외국에 팔아 버리면, 정작 우리가 쓸 게 없어지잖아?",
            ["DialogueId"] = 51125518,
            ["GUID"] = "7FFCC44C",
            ["NextDialogue"] = 51125519,
            ["SpeakNpcId"] = 701039,
            },
        [51125519] = {
            ["Content"] = "这进来的东西自然更是需要登记，就说那什么海伯利亚，刀啊枪啊的，要是都进了华胥岂不是乱了套！",
            ["ContentKR"] = "들어오는 물건은 더 철저히 신고해야지. 그 휘페르보레아 제국인가 뭔가 하는 데서 칼이나 총 같은 게 화서에 마구 들어오면 난리 날 거 아냐!",
            ["DialogueId"] = 51125519,
            ["GUID"] = "7FFCC476",
            ["NextOptions"] = {
                [1] = 51125520,
                [2] = 51125524,
                [3] = 51125527,
                },
            ["SpeakNpcId"] = 701039,
            },
        [51125520] = {
            ["Content"] = "如果混进了违禁品呢？",
            ["ContentKR"] = "금지품이 몰래 섞여 들어올 수도 있잖아요?",
            ["DialogueId"] = 51125520,
            ["GUID"] = "7FFCC4A0",
            ["NextDialogue"] = 51125521,
            },
        [51125521] = {
            ["Content"] = "小友啊小友，不是那么简单的事呀！且不说我们这样的点货人做得久了，光是看一眼货物大小，闻一闻香气，就能知道是运的何种货物。",
            ["ContentKR"] = "이 친구 보게, 그건 말처럼 쉽지가 않아요! 우리처럼 오래 일한 검수원들은, 화물 크기나 냄새만 맡아도 무슨 물건인지 다 알아.",
            ["DialogueId"] = 51125521,
            ["GUID"] = "7FFCC4CA",
            ["NextDialogue"] = 51125522,
            ["SpeakNpcId"] = 701039,
            },
        [51125522] = {
            ["Content"] = "你再看看在这码头四周游走的狴犴大人们，我们点得出来的错额他们能知晓，我们点不出来的，更是瞒不过它们。",
            ["ContentKR"] = "게다가 이 부두 주변을 돌아다니는 폐안님들을 봐. 우리가 잡아내는 오차 정돈 다 알고 계셔. 우리가 못 찾아도 저분들 눈을 속일 순 없다고.",
            ["DialogueId"] = 51125522,
            ["GUID"] = "7FFCC4F4",
            ["NextDialogue"] = 51125523,
            ["SpeakNpcId"] = 701039,
            },
        [51125523] = {
            ["Content"] = "为了防止有不好的东西进入咱们华胥，狴犴大人整日都在码头游走巡逻，大人们的鼻子可灵啦，一闻便知道有谁偷偷藏了东西。",
            ["ContentKR"] = "폐안님들은 몹쓸 물건들이 우리 화서엔 얼씬도 못 하게 하루 종일 부두를 순찰하셔. 냄새를 기가 막히게 맡아서, 숨겨 봤자 바로 들켜 버린다니까.",
            ["DialogueId"] = 51125523,
            ["GUID"] = "7FFCC51E",
            ["SpeakNpcId"] = 701039,
            },
        [51125524] = {
            ["Content"] = "所以你不是织星客？",
            ["ContentKR"] = "그러니까, 그쪽은 별을 잇는 자가 아닌 거예요?",
            ["DialogueId"] = 51125524,
            ["GUID"] = "7FFCC548",
            ["NextDialogue"] = 51125525,
            },
        [51125525] = {
            ["Content"] = "是，也不是，在华胥想成为织星客简单，但却没有必要一定要当个织星客。",
            ["ContentKR"] = "응. 뭐랄까, 이 화서에서 별을 잇는 자가 되긴 쉬워. 그렇지만 모두가 그래야 할 필요는 없잖아?",
            ["DialogueId"] = 51125525,
            ["GUID"] = "7FFCC572",
            ["NextDialogue"] = 51125526,
            ["SpeakNpcId"] = 701039,
            },
        [51125526] = {
            ["Content"] = "商人做生意有赚有亏，我只想过好自己的日子，干着悠闲不忙碌的工作，拿着稳定的工资岂不美哉？何必与他们一样出海远航，家也不见得顾上。",
            ["ContentKR"] = "장사하다 보면 벌 때도 있고 손해 볼 때도 있잖아. 배 타고 멀리 나가면 가족한테 신경도 못 쓰게 되고. 그러느니 설렁설렁 일하면서 꼬박꼬박 월급 받는 게 낫지. 난 인생 편히 살고 싶어.",
            ["DialogueId"] = 51125526,
            ["GUID"] = "7FFCC59C",
            ["SpeakNpcId"] = 701039,
            },
        [51125527] = {
            ["Content"] = "我先走了。",
            ["ContentKR"] = "이만 가 볼게요.",
            ["DialogueId"] = 51125527,
            ["GUID"] = "7FFCC5C6",
            ["NextDialogue"] = 51125528,
            },
        [51125528] = {
            ["Content"] = "小友慢逛~有事再来问我哈！",
            ["ContentKR"] = "잘 가~ 궁금한 거 있으면 또 찾아오라고!",
            ["DialogueId"] = 51125528,
            ["GUID"] = "7FFCC5F0",
            ["SpeakNpcId"] = 701039,
            },
        [51125601] = {
            ["Content"] = "这位客人您上上眼，小店卖的啊，都是在华胥游历必不可缺的尖货，样样好！尤其是这沉月香的香囊啊，想要得到咱们华胥的白龙神君的庇佑啊，必不可缺！",
            ["ContentKR"] = "구경하고 가세요. 화서 여행에 빠뜨려선 안 될 핫템만 모았습니다! 특히 이 침월향 향주머니는 화서 백룡신군의 가호를 받고 싶다면 무조건 사셔야 해요!",
            ["DialogueId"] = 51125601,
            ["GUID"] = "7FFCD1EA",
            ["NextOptions"] = {
                [1] = 51125602,
                [2] = 51125604,
                },
            ["SpeakNpcId"] = 701040,
            },
        [51125602] = {
            ["Content"] = "有人送过我了。",
            ["ContentKR"] = "다른 사람한테 받은 게 있어요.",
            ["DialogueId"] = 51125602,
            ["GUID"] = "7FFCD214",
            ["ImprPlusId"] = 1209,
            ["NextDialogue"] = 51125603,
            },
        [51125603] = {
            ["Content"] = "哦？客人是来华胥见朋友？难不成是哪位织星客将客人带来的？没事！除了香囊我这还有别的呢，要不您看看这把绢面的折扇？或者这柄金漆的雕花镜？",
            ["ContentKR"] = "어? 화서에 친구분을 만나러 오셨나 보군요? 어느 별을 잇는 자가 모시고 온 거려나? 괜찮습니다! 향주머니 말고도 많거든요. 이 비단 부채는 어떠신가요? 화려한 금칠과 조각이 돋보이는 이 거울은요?",
            ["DialogueId"] = 51125603,
            ["GUID"] = "7FFCD23E",
            ["SpeakNpcId"] = 701040,
            },
        [51125604] = {
            ["Content"] = "我没钱，你可以送我吗？",
            ["ContentKR"] = "돈이 없는데, 공짜로 주시면 안 돼요?",
            ["DialogueId"] = 51125604,
            ["GUID"] = "7FFCD268",
            ["ImprPlusId"] = 1210,
            ["NextDialogue"] = 51125605,
            },
        [51125605] = {
            ["Content"] = "哈哈哈，客人真会说笑，但其实并无不可，沉月香香囊在咱们华胥本就不是什么稀奇之物，客人不嫌弃的话，便从我这随便挑一个拿走吧！",
            ["ContentKR"] = "하하하, 농담도 잘하시네요. 하긴, 뭐, 안 될 것도 없죠. 침월향 향주머니는 화서에선 그렇게 귀한 것도 아니니까요. 괜찮으시다면, 여기서 아무거나 하나 골라 가세요!",
            ["DialogueId"] = 51125605,
            ["GUID"] = "7FFCD292",
            ["NextDialogue"] = 51125606,
            ["SpeakNpcId"] = 701040,
            },
        [51125606] = {
            ["Content"] = "等客人在华胥发了财，可别忘了来我这再挑挑，选些纪念品带给亲朋好友啊！",
            ["ContentKR"] = "나중에 화서에서 돈 많이 버시면, 저희 가게에 꼭 들러서 친구분들 줄 기념품을 구입해 주세요!",
            ["DialogueId"] = 51125606,
            ["GUID"] = "7FFCD2BC",
            ["SpeakNpcId"] = 701040,
            },
        [51125607] = {
            ["Content"] = "专供异国友人的纪念品摊铺，来华胥之游人必不可错过！香囊折扇古玩珍宝，您想要的，应有尽有！",
            ["ContentKR"] = "외국 손님들을 위한 기념품 가게입니다! 화서에 오셨다면 놓치지 마세요! 향주머니부터 부채, 골동품, 진귀한 보물까지 원하시는 건 뭐든 있습니다!",
            ["DialogueId"] = 51125607,
            ["GUID"] = "7FFCD2E6",
            ["NextDialogue"] = 51125608,
            ["SpeakNpcId"] = 701040,
            },
        [51125608] = {
            ["Content"] = "客人来啦，随便瞧随便看，有什么喜欢的您尽管说，价格好商量。",
            ["ContentKR"] = "편하게 구경하고 가세요. 마음에 드시는 게 있으면 말씀하시고요. 가격은 최대한 맞춰 드릴게요.",
            ["DialogueId"] = 51125608,
            ["GUID"] = "7FFCD310",
            ["NextOptions"] = {
                [1] = 51125609,
                [2] = 51125620,
                [3] = 51125622,
                },
            ["SpeakNpcId"] = 701040,
            },
        [51125609] = {
            ["Content"] = "有什么推荐的必备物品吗？除了香囊。",
            ["ContentKR"] = "'이건 무조건 사야 한다'하는 물건 있나요? 향주머니 말고요.",
            ["DialogueId"] = 51125609,
            ["GUID"] = "7FFCD33A",
            ["NextDialogue"] = 51125610,
            },
        [51125610] = {
            ["Content"] = "有，自然是有的！首先便是这大风九章挂轴，上面把条目写得一清二楚。这样啊，您离开华胥回到故国，和朋友们讲起大风九章，就能有实物说明啦，不至于用手比划！",
            ["ContentKR"] = "있고 말고요! 이 대풍구장 족자랍니다. 대풍구장의 내용이 빠짐없이 적혀 있어서, 귀국해서 친구분들께 설명할 때 딱 꺼내서 보여 주면 되거든요! 손짓발짓하며 설명할 필요가 없죠!",
            ["DialogueId"] = 51125610,
            ["GUID"] = "7FFCD364",
            ["NextDialogue"] = 51125611,
            ["SpeakNpcId"] = 701040,
            },
        [51125611] = {
            ["Content"] = "客人再看看这华胥特有的首饰，咱们华胥上至老人下至小孩，都喜欢这种古色古香的款式，经典！",
            ["ContentKR"] = "그리고 이 화서 특유의 장신구도 좋아요. 화서에선 어르신부터 아이까지 고풍스러운 디자인을 좋아한답니다! 유행을 안 타거든요!",
            ["DialogueId"] = 51125611,
            ["GUID"] = "7FFCD38E",
            ["NextDialogue"] = 51125612,
            ["SpeakNpcId"] = 701040,
            },
        [51125612] = {
            ["Content"] = "您要是喜欢与众不同呢，也有这种以昆虫为主题的，更能凸显客人气质独特，品位不凡。",
            ["ContentKR"] = "특이한 걸 원하신다면, 이런 곤충 모양 장신구도 있어요. 남다른 안목을 지닌 사람이란 걸 제대로 보여 줄 수 있죠.",
            ["DialogueId"] = 51125612,
            ["GUID"] = "7FFCD3B8",
            ["NextDialogue"] = 51125613,
            ["SpeakNpcId"] = 701040,
            },
        [51125613] = {
            ["Content"] = "对了对了，客人一定不能错过我们店里新到的香薰蜡烛，比普通蜡烛多了一份来自华胥的芳香，许多异国客人买过之后还想要呢！",
            ["ContentKR"] = "참! 저희 가게의 이 신상품 향초도 꼭 고려해 주세요. 다른 초랑은 다르게 화서 특유의 은은한 향이 일품이거든요. 다른 나라 손님들도 꼭 재구매하시는 물건이에요!",
            ["DialogueId"] = 51125613,
            ["GUID"] = "7FFCD3E2",
            ["NextOptions"] = {
                [1] = 51125614,
                [2] = 51125618,
                },
            ["SpeakNpcId"] = 701040,
            },
        [51125614] = {
            ["Content"] = "这些我都不喜欢，有没有更实用的东西？",
            ["ContentKR"] = "다 별로 마음에 안 드는데, 더 실용적인 건 없어요?",
            ["DialogueId"] = 51125614,
            ["GUID"] = "7FFCD40C",
            ["NextDialogue"] = 51125615,
            },
        [51125615] = {
            ["Content"] = "客人呀~我就是个卖纪念品的小贩，纪念品这种东西，主打的就是一个没什么实际意义，买着好玩的存在呀。",
            ["ContentKR"] = "손님~ 전 그냥 기념품 상인이에요. 원래 기념품이란 게 딱히 쓸모는 없지만, 재미로 사는 물건이잖아요.",
            ["DialogueId"] = 51125615,
            ["GUID"] = "7FFCD436",
            ["NextDialogue"] = 51125616,
            ["SpeakNpcId"] = 701040,
            },
        [51125616] = {
            ["Content"] = "来咱们华胥的外国客人，要么是旅游要么是做生意，多少都想带点东西给家乡里没法亲自过来的人作为纪念，要是有用的华胥之物，他们也用不惯的。",
            ["ContentKR"] = "외국분들은 관광하러 오셨든 일로 오셨든, 여기 못 와 본 친구들한테 줄 기념품을 사 가고 싶어 하세요. 실용적인 물건은 가져가 봐야 취향에 안 맞으실 수 있으니까요.",
            ["DialogueId"] = 51125616,
            ["GUID"] = "7FFCD460",
            ["NextDialogue"] = 51125617,
            ["SpeakNpcId"] = 701040,
            },
        [51125617] = {
            ["Content"] = "再说了，要是真有大用的货物，早就会有商人把它当做紧俏货，卖得各国都是啦，又怎么会只有华胥才能买到呢。",
            ["ContentKR"] = "그리고 솔직히, 엄청나게 유용한 물건이었으면, 상인들이 진작에 좋은 물건이라면서 여기저기 수출했겠죠. 이 화서에서만 팔겠어요.",
            ["DialogueId"] = 51125617,
            ["GUID"] = "7FFCD48A",
            ["NextOptions"] = {
                [1] = 51125622,
                },
            ["SpeakNpcId"] = 701040,
            },
        [51125618] = {
            ["Content"] = "都想要，但我没钱，能不能赊账。",
            ["ContentKR"] = "전부 다 마음에 드는데, 돈이 없네요. 외상도 되나요?",
            ["DialogueId"] = 51125618,
            ["GUID"] = "7FFCD4B4",
            ["NextDialogue"] = 51125619,
            },
        [51125619] = {
            ["Content"] = "客人这……我这是小本生意，客人别难为我啦，要是客人想找点活，我可以帮您引荐引荐，织星客们经常在码头招募搬货的工人，客人要不去问问？",
            ["ContentKR"] = "손님... 이거 팔아 봐야 얼마나 남는다고 이러세요. 아니면 제가 일자리를 소개해 드릴게요. 별을 잇는 자들이 부두에서 짐꾼을 자주 구하던데, 가서 물어보시는 건 어때요?",
            ["DialogueId"] = 51125619,
            ["GUID"] = "7FFCD4DE",
            ["NextOptions"] = {
                [1] = 51125622,
                },
            ["SpeakNpcId"] = 701040,
            },
        [51125620] = {
            ["Content"] = "卖给外国人的货，不会在价格上坑我吧？",
            ["ContentKR"] = "외국인이라고 바가지 씌우는 건 아니겠죠?",
            ["DialogueId"] = 51125620,
            ["GUID"] = "7FFCD508",
            ["NextDialogue"] = 51125621,
            },
        [51125621] = {
            ["Content"] = "客人这话说的！我在这档口待了快有十年，远近闻名的好信用，货品都是尽量给客人最大的优惠。",
            ["ContentKR"] = "무슨 그런 섭섭한 말씀을 하세요! 제가 이 자리에서만 거의 10년을 장사했어요. 신용이라면 이름 나 있고, 가격도 최대한 저렴하게 드리고 있다고요.",
            ["DialogueId"] = 51125621,
            ["GUID"] = "7FFCD532",
            ["NextOptions"] = {
                [1] = 51125609,
                [2] = 51125622,
                },
            ["SpeakNpcId"] = 701040,
            },
        [51125622] = {
            ["Content"] = "没什么要说的，走了。",
            ["ContentKR"] = "딱히 별거 없네요. 전 가 볼게요.",
            ["DialogueId"] = 51125622,
            ["GUID"] = "7FFCD55C",
            ["NextDialogue"] = 51125623,
            },
        [51125623] = {
            ["Content"] = "客人慢走，以后有空再来看看，定能找到您喜欢的东西！",
            ["ContentKR"] = "안녕히 가세요! 나중에 시간 나시면 또 들러 주시고요. 마음에 쏙 드는 물건을 찾으실 수 있을 거예요!",
            ["DialogueId"] = 51125623,
            ["GUID"] = "7FFCD586",
            ["SpeakNpcId"] = 701040,
            },
        [51125701] = {
            ["Content"] = "诸位有所不知啊，咱们浮星埠现在呢，只是织星客们货物往来的小小码头，平平无奇，但是在千年之前呢，这里可出过一位大人物。",
            ["ContentKR"] = "이 별빛 부두가 지금은 별을 잇는 자들의 화물이나 오가는 조그만 부둣가에 불과하지만, 천 년 전만 해도 아주 대단한 분을 배출한 곳이라네.",
            ["DialogueId"] = 51125701,
            ["GUID"] = "7FFCE252",
            ["NextDialogue"] = 51125702,
            ["SpeakNpcId"] = 701041,
            },
        [51125702] = {
            ["Content"] = "哪位呢？说来大家也都听过名字，就是那大风九章的创立者之一，也是匠矩派的老祖宗——矩！",
            ["ContentKR"] = "그게 누구냐고? 이름만 대면 다들 알 양반이지. 바로 대풍구장의 창시자이시자, 장구파의 시조 되시는 '구' 님일세!",
            ["DialogueId"] = 51125702,
            ["GUID"] = "7FFCE27C",
            ["NextOptions"] = {
                [1] = 51125703,
                [2] = 51125720,
                },
            ["SpeakNpcId"] = 701041,
            },
        [51125703] = {
            ["Content"] = "继续听下去。",
            ["ContentKR"] = "계속 듣는다.",
            ["DialogueId"] = 51125703,
            ["GUID"] = "7FFCE2A6",
            ["NextDialogue"] = 51125704,
            },
        [51125704] = {
            ["Content"] = "南来北往的慢走一步，且听我说道说道咱们这浮星埠的千年历史——做生意讲究明明白白，对自己的过去啊，也得清清楚楚才好。",
            ["ContentKR"] = "지나가는 분들은 다들 이 늙은이가 들려주는 별빛 부두의 역사를 들어 보시게. 장사꾼이라면 현명해야 하니, 이 땅의 과거도 훤히 알고 있어야지 않겠나.",
            ["DialogueId"] = 51125704,
            ["GUID"] = "7FFCE2D0",
            ["NextDialogue"] = 51125705,
            ["SpeakNpcId"] = 701041,
            },
        [51125705] = {
            ["Content"] = "当年的华胥，没有大风九章的庇佑，秽兽四起，袭击无辜之人，为了活命，是不分老幼，都得想着法和那些凶恶的野兽去斗来斗去。",
            ["ContentKR"] = "그 옛날, 화서에 대풍구장의 가호가 없었던 시절에는 사방에 들끓는 필토이드가 죄 없는 사람들을 닥치는 대로 공격했지. 살기 위해선 너 나 할 것 없이 녀석들과 목숨을 걸고 싸워야만 했어.",
            ["DialogueId"] = 51125705,
            ["GUID"] = "7FFCE2FA",
            ["NextDialogue"] = 51125706,
            ["SpeakNpcId"] = 701041,
            },
        [51125706] = {
            ["Content"] = "有争斗就会有伤亡，那时，华胥人口数量极少，因为大多数出生的孩子都难在这乱世之中活下来，为了寻找到让华胥境内安宁的办法，有龙一族上下求索。",
            ["ContentKR"] = "싸움이 있으면 죽고 다치는 사람이 생기는 법이라, 그때 화서는 사람의 씨가 마를 지경이었다네. 세상이 험해 아이들 태반이 살아남질 못했거든. 그래서 용의 자손들은 이 땅에 평화를 가져올 방법을 찾아 곳곳을 헤매고 다녔어.",
            ["DialogueId"] = 51125706,
            ["GUID"] = "7FFCE324",
            ["NextDialogue"] = 51125707,
            ["SpeakNpcId"] = 701041,
            },
        [51125707] = {
            ["Content"] = "而我们的前辈矩呢，走遍了华胥，发现哪儿都是不得安生，于是他想着，不如出去看看，去看看人家是怎么做的，取其长处再充盈自身。",
            ["ContentKR"] = "우리의 선조이신 구 님도 화서 땅 구석구석을 다녔지만, 두 다리 뻗고 잘 곳이 없었다네. 그러다가 '차라리 이 나라 밖으로 나가서, 다른 사람들이 어찌 사는지 보고, 뛰어난 걸 배워서 우리 것으로 만들자'라는 생각이 드셨지.",
            ["DialogueId"] = 51125707,
            ["GUID"] = "7FFCE34E",
            ["NextOptions"] = {
                [1] = 51125708,
                },
            ["SpeakNpcId"] = 701041,
            },
        [51125708] = {
            ["Content"] = "继续听下去。",
            ["ContentKR"] = "계속 듣는다.",
            ["DialogueId"] = 51125708,
            ["GUID"] = "7FFCE378",
            ["NextDialogue"] = 51125709,
            },
        [51125709] = {
            ["Content"] = "当年啊，还没现在这么厉害的船，也没有织星客的存在，想要出海，全凭运气，运气好便漂流到荒岛看鸟，运气不好，就只能葬身海底喂鱼喽。",
            ["ContentKR"] = "그 시절엔 지금처럼 튼튼한 배도 없었고, 별을 잇는 자도 없었다네. 바다로 나간다는 건 순전히 하늘에 목숨을 맡기는 일이라, 운 좋으면 무인도에 떠내려가서 새 구경이나 하는 거고, 운 나쁘면 물고기 밥 신세였어.",
            ["DialogueId"] = 51125709,
            ["GUID"] = "7FFCE3A2",
            ["NextDialogue"] = 51125710,
            ["SpeakNpcId"] = 701041,
            },
        [51125710] = {
            ["Content"] = "但矩呢，抱定要为万民谋安宁的一颗赤心，自制了艘船，说是不连累别人，愣是一个人就从咱们这浮星埠下了海！",
            ["ContentKR"] = "그렇지만 구 님께선 모두가 평화로이 살게 하겠다는 마음 하나만으로, 손수 배를 만드셨다네. 게다가 남에게 폐 끼칠 순 없다고 덜컥 혼자서 이 별빛 부두에서 바다로 나가셨지!",
            ["DialogueId"] = 51125710,
            ["GUID"] = "7FFCE3CC",
            ["NextDialogue"] = 51125711,
            ["SpeakNpcId"] = 701041,
            },
        [51125711] = {
            ["Content"] = "好在，白龙神君眷顾，矩在风浪里去了那神秘的塔之国，但可惜的是，那边也不得安生，矩认为外民也无法给华胥带来希望，于是便带着同样想要安定的人回来了。",
            ["ContentKR"] = "다행히도 백룡신군께서 보살펴 주신 덕분에, 구 님께선 거센 풍랑을 헤치고 신비로운 탑의 나라에 당도하셨네. 안타깝게도 그 나라도 제 코가 석 자라, 오히려 평온한 삶을 바라던 그곳 사람들을 데리고 귀국 길에 오르셨지.",
            ["DialogueId"] = 51125711,
            ["GUID"] = "7FFCE3F6",
            ["NextDialogue"] = 51125712,
            ["SpeakNpcId"] = 701041,
            },
        [51125712] = {
            ["Content"] = "这都多少年过去了，大家都以为矩早就是个死人，结果啊非但没死，还又带了许许多多的活人回来了浮星埠。",
            ["ContentKR"] = "몇 년이 지났을까, 다들 구 님은 진작 죽은 줄로만 알고 있었어. 그런데 이게 웬걸, 멀쩡히 살아 있는 걸로도 모자라, 수많은 사람을 데리고 떡하니 이 별빛 부두로 돌아오신 거네.",
            ["DialogueId"] = 51125712,
            ["GUID"] = "7FFCE420",
            ["NextOptions"] = {
                [1] = 51125713,
                },
            ["SpeakNpcId"] = 701041,
            },
        [51125713] = {
            ["Content"] = "继续听下去。",
            ["ContentKR"] = "계속 듣는다.",
            ["DialogueId"] = 51125713,
            ["GUID"] = "7FFCE44A",
            ["NextDialogue"] = 51125714,
            },
        [51125714] = {
            ["Content"] = "你们可能好奇，矩是如何做到如此准确的寻路，是有神灵庇佑还是靠的信念和直觉？",
            ["ContentKR"] = "어떻게 망망대해에서 정확히 길을 찾았는지 다들 궁금하지? 신령님의 가호일까? 아니면 엄청난 신념과 직감 덕분일까?",
            ["DialogueId"] = 51125714,
            ["GUID"] = "7FFCE474",
            ["NextDialogue"] = 51125715,
            ["SpeakNpcId"] = 701041,
            },
        [51125715] = {
            ["Content"] = "都不是，老柳头啊也不卖关子了，现在织星者们出海时用的引路的工具不是叫千星板吗？矩也是一样，只是啊，他手里用的那个，就是第一个。",
            ["ContentKR"] = "둘 다 아니야! 속 시원히 알려 주지. 요새 별을 잇는 자들이 바다에서 길 찾는 데 쓰는 도구를 천성판이라고 하지? 구 님도 그걸 쓰셨던 거라네. 단지, 그분 건 최초의 천성판이었다 이 말일세.",
            ["DialogueId"] = 51125715,
            ["GUID"] = "7FFCE49E",
            ["NextDialogue"] = 51125716,
            ["SpeakNpcId"] = 701041,
            },
        [51125716] = {
            ["Content"] = "他用几块木板测绘星辰，记录航向，这才能在茫茫大海上自由来去，不受羁绊。",
            ["ContentKR"] = "그분은 나무판 몇 개로 별자리를 읽고 항로를 기록해서, 그 넓은 바다를 거침없이 자유자재로 오갈 수 있으셨던 거야.",
            ["DialogueId"] = 51125716,
            ["GUID"] = "7FFCE4C8",
            ["NextDialogue"] = 51125717,
            ["SpeakNpcId"] = 701041,
            },
        [51125717] = {
            ["Content"] = "矩的成功出海与归来，让华胥的有龙们不再畏惧海洋，现在浮星埠的繁华和织星客们的昌盛，也是多亏了当年矩的先行。",
            ["ContentKR"] = "구 님이 바다에서 무사히 돌아오신 뒤로, 화서의 용의 자손들은 더는 바다를 두려워하지 않게 됐지. 오늘날 별빛 부두와 별을 잇는 자들의 번영도 다 물꼬를 터 주신 그분 덕분이라네.",
            ["DialogueId"] = 51125717,
            ["GUID"] = "7FFCE4F2",
            ["NextDialogue"] = 51125718,
            ["SpeakNpcId"] = 701041,
            },
        [51125718] = {
            ["Content"] = "所以，矩和飏，都是咱们要时时牢记于心的开国贤君，没有他们，就没有今天的华胥，我们要时时刻刻记住他们的名字和事迹！懂了吗？",
            ["ContentKR"] = "그러니까 우리는 늘 이 나라의 기틀을 닦아 주신 구와 양 두 선조님과 그분들의 업적을 가슴 깊이 새겨야 하네. 지금의 화서를 존재하게 해 주신 분들이니 말이야! 알겠는가?",
            ["DialogueId"] = 51125718,
            ["GUID"] = "7FFCE51C",
            ["NextDialogue"] = 51125719,
            ["SpeakNpcId"] = 701041,
            },
        [51125719] = {
            ["Content"] = "（响起一阵叫好声。）",
            ["ContentKR"] = "(여기저기서 환호성이 터져 나온다.)",
            ["DialogueId"] = 51125719,
            ["GUID"] = "7FFCE546",
            },
        [51125720] = {
            ["Content"] = "不听了。",
            ["ContentKR"] = "듣지 않는다.",
            ["DialogueId"] = 51125720,
            ["GUID"] = "7FFCE570",
            ["NextDialogue"] = 51125721,
            },
        [51125721] = {
            ["Content"] = "（身后传来老柳头宣扬两位华胥开国贤君事迹的声音和喝茶群众的叫好声……）",
            ["ContentKR"] = "(등 뒤로 노인이 화서의 기틀을 닦은 두 선조를 칭송하는 이야기보따리를 풀어놓는 소리와 차를 마시던 이들의 환호성이 들려온다...)",
            ["DialogueId"] = 51125721,
            ["GUID"] = "7FFCE59A",
            },
        [51125801] = {
            ["Content"] = "千星板运作情况一切正常，算算时间，马上要到下一次保养的日子了……",
            ["ContentKR"] = "천성판 작동 상태는 전부 이상 없군. 어디 보자, 이제 곧 다음 정비일인가...",
            ["DialogueId"] = 51125801,
            ["GUID"] = "7FFCF2BA",
            ["NextDialogue"] = 51125802,
            ["SpeakNpcId"] = 701042,
            },
        [51125802] = {
            ["Content"] = "这千星板上了船还没个三年，怎么就这么快就要去保养了呢，这次不知道他们还记不记得提前预约机枢派的师傅……先看看刻度有没有被磨坏吧！",
            ["ContentKR"] = "설치한 지 3년도 안 됐는데 정비를 왜 벌써 받아야 하는 거람. 이번엔 기추파 기술자들한테 미리 예약해 뒀으려나... 일단 눈금이 닳았는지부터 확인해 보자!",
            ["DialogueId"] = 51125802,
            ["GUID"] = "7FFCF2E4",
            ["NextDialogue"] = 51125803,
            ["SpeakNpcId"] = 701042,
            },
        [51125803] = {
            ["Content"] = "呀！吓了我一跳，你是异国人吗？在咱们船上做什么？",
            ["ContentKR"] = "꺅! 깜짝이야! 외국분이세요? 우리 배엔 왜 올라오셨어요?",
            ["DialogueId"] = 51125803,
            ["GUID"] = "7FFCF30E",
            ["NextOptions"] = {
                [1] = 51125804,
                [2] = 51125807,
                },
            ["SpeakNpcId"] = 701042,
            },
        [51125804] = {
            ["Content"] = "好奇你在做什么。",
            ["ContentKR"] = "뭐 하시는 건지 궁금해서요.",
            ["DialogueId"] = 51125804,
            ["GUID"] = "7FFCF338",
            ["ImprPlusId"] = 1208,
            ["NextDialogue"] = 51125805,
            },
        [51125805] = {
            ["Content"] = "我？我在查看这船上千星板的情况呀，我是这艘船上配的工匠，专门负责日常维护这千星板的运作，要是没有这千星板，这船只可就没法出航啦。",
            ["ContentKR"] = "저요? 이 배의 천성판 상태를 점검하고 있었어요. 전 이 배에 배정된 기술자인데, 천성판이 잘 작동하는지 매일 확인하고 관리하는 게 제 일이거든요. 이게 없으면 배가 출항을 못 해요.",
            ["DialogueId"] = 51125805,
            ["GUID"] = "7FFCF362",
            ["NextDialogue"] = 51125806,
            ["SpeakNpcId"] = 701042,
            },
        [51125806] = {
            ["Content"] = "你有事的话，以后再来找我吧，现在我还要仔细检查一下过热情况……",
            ["ContentKR"] = "근데 볼일이 있으면 나중에 다시 찾아와 주실래요? 지금은 과열 상태를 점검해야 하거든요...",
            ["DialogueId"] = 51125806,
            ["GUID"] = "7FFCF38C",
            ["SpeakNpcId"] = 701042,
            },
        [51125807] = {
            ["Content"] = "闲逛到这里了。",
            ["ContentKR"] = "구경하다 보니까 여기 오게 됐네요.",
            ["DialogueId"] = 51125807,
            ["GUID"] = "7FFCF3B6",
            ["ImprPlusId"] = 1207,
            ["NextDialogue"] = 51125808,
            },
        [51125808] = {
            ["Content"] = "哦哦是吗？可我在检查千星板的情况呢，要是出了问题，这船就没法出航啦，你有什么事情的话以后再来找我聊吧。",
            ["ContentKR"] = "아, 그래요? 그런데 제가 지금 천성판 상태를 점검하는 중이라서요. 이게 고장 나면 배가 출항을 못 하거든요. 혹시 볼일이 있는 거면 나중에 다시 와서 얘기해 주세요.",
            ["DialogueId"] = 51125808,
            ["GUID"] = "7FFCF3E0",
            ["SpeakNpcId"] = 701042,
            },
        [51125809] = {
            ["Content"] = "千星板运作情况一切正常，算算时间，马上要到下一次保养的日子了……",
            ["ContentKR"] = "천성판 작동 상태는 전부 이상 없군. 어디 보자, 이제 곧 다음 정비일인가...",
            ["DialogueId"] = 51125809,
            ["GUID"] = "7FFCF40A",
            ["NextDialogue"] = 51125810,
            ["SpeakNpcId"] = 701042,
            },
        [51125810] = {
            ["Content"] = "这个刻度误差……我手动增加五次校准运算后结果也大差不差……那是不是可以申请延期保养时间了。",
            ["ContentKR"] = "눈금 오차가... 수동으로 다섯 번이나 보정을 해도 결과가 비슷하네... 이러면 정비를 연기해 달라고 해도 되려나?",
            ["DialogueId"] = 51125810,
            ["GUID"] = "7FFCF434",
            ["NextDialogue"] = 51125811,
            ["SpeakNpcId"] = 701042,
            },
        [51125811] = {
            ["Content"] = "呀，又是你，异国人，你又逛到我这啦。",
            ["ContentKR"] = "앗, 또 만났네요, 외국분. 이번에도 구경하다 여기까지 온 모양이군요.",
            ["DialogueId"] = 51125811,
            ["GUID"] = "7FFCF45E",
            ["NextOptions"] = {
                [1] = 51125812,
                [2] = 51125815,
                [3] = 51125825,
                },
            ["SpeakNpcId"] = 701042,
            },
        [51125812] = {
            ["Content"] = "师傅你是做什么的？",
            ["ContentKR"] = "하시는 일이 어떻게 되세요?",
            ["DialogueId"] = 51125812,
            ["GUID"] = "7FFCF488",
            ["NextDialogue"] = 51125813,
            },
        [51125813] = {
            ["Content"] = "我吗？自然是这船上配的工匠啦，我的工作就是负责维护千星板的运作情况，保证它一切正常，不会临时出意外，不然会影响到下一次出航。",
            ["ContentKR"] = "저요? 그야 이 배에 배정된 기술자죠. 항해 중에 갑자기 문제가 생기지 않도록, 천성판이 문제없이 잘 작동하는지 확인하는 게 제 일이에요.",
            ["DialogueId"] = 51125813,
            ["GUID"] = "7FFCF4B2",
            ["NextDialogue"] = 51125814,
            ["SpeakNpcId"] = 701042,
            },
        [51125814] = {
            ["Content"] = "这些信息都要记录下来，找天禄司申请通文时用得到呢。",
            ["ContentKR"] = "이런 정보들은 전부 꼼꼼하게 기록해 둬야 해요. 나중에 천록사에 통행증 신청할 때 필요하거든요.",
            ["DialogueId"] = 51125814,
            ["GUID"] = "7FFCF4DC",
            ["NextOptions"] = {
                [1] = 51125815,
                [2] = 51125825,
                },
            ["SpeakNpcId"] = 701042,
            },
        [51125815] = {
            ["Content"] = "千星板是什么？",
            ["ContentKR"] = "천성판이 뭐예요?",
            ["DialogueId"] = 51125815,
            ["GUID"] = "7FFCF506",
            ["NextDialogue"] = 51125816,
            },
        [51125816] = {
            ["Content"] = "千星板可是咱们织星客们赖以生存的传家宝呢！在一望无际的大海上，只有它能观测天上的星星的方位，给船只导航指路，怎么都不会跑偏。",
            ["ContentKR"] = "우리 별을 잇는 자들한테는 목숨줄이나 다름없는 보물이에요! 망망대해에서 길을 잘못 들고 싶지 않다면, 별의 위치를 관측해서 항로를 알려 주는 천성판이 필수죠.",
            ["DialogueId"] = 51125816,
            ["GUID"] = "7FFCF530",
            ["NextDialogue"] = 51125817,
            ["SpeakNpcId"] = 701042,
            },
        [51125817] = {
            ["Content"] = "华胥四周的海域紊乱，没有千星板的正确指引，织星客们很容易在乱流之间迷路，所以啊，我们每回远航之前，都需要仔细检查千星板的情况。",
            ["ContentKR"] = "화서 주변은 해류가 복잡해서, 천성판이 없으면 길을 잃고 헤매기 쉽거든요. 그래서, 별을 잇는 자들은 먼바다로 나가기 전에 항상 천성판의 상태를 꼼꼼히 점검해요.",
            ["DialogueId"] = 51125817,
            ["GUID"] = "7FFCF55A",
            ["NextOptions"] = {
                [1] = 51125818,
                [2] = 51125822,
                },
            ["SpeakNpcId"] = 701042,
            },
        [51125818] = {
            ["Content"] = "你说的保养是什么意思？",
            ["ContentKR"] = "방금 정비란 건 무슨 말이에요?",
            ["DialogueId"] = 51125818,
            ["GUID"] = "7FFCF584",
            ["NextDialogue"] = 51125819,
            },
        [51125819] = {
            ["Content"] = "保养吗？其实就是让机枢派的老师傅们帮咱们看看千星板是否出现一些零件松动之类的情况，虽然大多数情况都没什么问题，但是在海上航行，难免会有浪涛大时磕碰。",
            ["ContentKR"] = "정비요? 기추파의 전문가들한테 천성판의 부품이 헐거워지거나 하진 않았는지 봐 달라고 하는 거예요. 대개는 별문제 없지만, 항해하다 보면 풍랑 때문에 부딪히거나 할 수 있으니까요.",
            ["DialogueId"] = 51125819,
            ["GUID"] = "7FFCF5AE",
            ["NextDialogue"] = 51125820,
            ["SpeakNpcId"] = 701042,
            },
        [51125820] = {
            ["Content"] = "我们这种普通工匠能看出问题但不会修，只有去机枢派找有专门检测器材的老师傅们帮着看看，但是频率不需要太高，大概四五年一次就好。",
            ["ContentKR"] = "저 같은 일반 기술자들은 문제를 찾아내긴 해도 수리는 못 하거든요. 그래서 전문 측정 장비를 가진 기추파 기술자들한테 점검을 받아야 해요. 자주는 아니고, 4~5년에 한 번이면 돼요.",
            ["DialogueId"] = 51125820,
            ["GUID"] = "7FFCF5D8",
            ["NextDialogue"] = 51125821,
            ["SpeakNpcId"] = 701042,
            },
        [51125821] = {
            ["Content"] = "不过即使是过去找他们，也需要给到日常测量的一些数据，方便给出更好的判断。",
            ["ContentKR"] = "근데 무작정 찾아가면 안 되고, 평소에 측정한 이런 데이터들을 같이 드려야 그분들도 정확한 판단을 내릴 수 있어요.",
            ["DialogueId"] = 51125821,
            ["GUID"] = "7FFCF602",
            ["SpeakNpcId"] = 701042,
            },
        [51125822] = {
            ["Content"] = "千星板在哪，我怎么没看到？",
            ["ContentKR"] = "천성판이 어디 있어요? 제 눈엔 안 보이는데요?",
            ["DialogueId"] = 51125822,
            ["GUID"] = "7FFCF62C",
            ["NextDialogue"] = 51125823,
            },
        [51125823] = {
            ["Content"] = "哈哈，笨家伙，就在咱们脚下呀，咱们这种用来出海的大船，千星板都是装在船舱里的，只有最大的那块板会倒置朝向天空，方便观测星空。",
            ["ContentKR"] = "하하, 바보 같긴. 바로 우리 발밑에 있잖아요. 이런 큰 배는 천성판을 선실 안에 설치해 둬요. 대신 별을 관측하기 쉽게, 가장 커다란 판 하나는 하늘을 향해 거꾸로 달아 두죠.",
            ["DialogueId"] = 51125823,
            ["GUID"] = "7FFCF656",
            ["NextDialogue"] = 51125824,
            ["SpeakNpcId"] = 701042,
            },
        [51125824] = {
            ["Content"] = "用你们外国人能听懂的话来形容，大概有些像那种大型的吊灯，我们在海上的时候，每时每刻都需要有人在船舱里值班记录千星板转动的幅度，不然就容易偏航呢。",
            ["ContentKR"] = "외국분이 이해하기 쉽게 설명하자면, 커다란 샹들리에 같다고 생각하면 돼요. 바다에 나가 있을 땐, 누구 하나는 선실에서 계속 천성판이 얼마큼 돌아갔는지 기록해야 해요. 안 그러면 항로에서 벗어나기 쉽거든요.",
            ["DialogueId"] = 51125824,
            ["GUID"] = "7FFCF680",
            ["SpeakNpcId"] = 701042,
            },
        [51125825] = {
            ["Content"] = "没什么要问的。",
            ["ContentKR"] = "이제 궁금한 거 없어요.",
            ["DialogueId"] = 51125825,
            ["GUID"] = "7FFCF6AA",
            ["NextDialogue"] = 51125826,
            },
        [51125826] = {
            ["Content"] = "有事再来找我吧，我要测量新的数据啦。",
            ["ContentKR"] = "전 이제 새로운 데이터를 측정해야겠네요. 무슨 일 있으면 또 찾아와요.",
            ["DialogueId"] = 51125826,
            ["GUID"] = "7FFCF6D4",
            ["SpeakNpcId"] = 701042,
            },
        [51125901] = {
            ["Content"] = "白女士，这个什么什么身，是什么意思，我听不懂。",
            ["ContentKR"] = "선생님, '해하다'가 무슨 뜻이죠? 잘 이해가 안 돼요.",
            ["DialogueId"] = 51125901,
            ["GUID"] = "7FFD0322",
            ["NextDialogue"] = 51125902,
            ["SpeakNpcId"] = 701043,
            },
        [51125902] = {
            ["Content"] = "戕，这个字念戕，就是和你们异国人经常用的枪字一个读音。",
            ["ContentKR"] = "'해하다'는 해친다는 뜻이에요. 발음도 비슷하고 뜻도 같죠.",
            ["DialogueId"] = 51125902,
            ["GUID"] = "7FFD034C",
            ["NextDialogue"] = 51125903,
            ["SpeakNpcId"] = 701044,
            },
        [51125903] = {
            ["Content"] = "哦哦！枪！枪身就是，用枪打对方的身子，对不对？",
            ["ContentKR"] = "아! '회 치다'요? 그렇죠, 그렇죠! 사람을 회를 치면 큰일 나죠.",
            ["DialogueId"] = 51125903,
            ["GUID"] = "7FFD0376",
            ["NextDialogue"] = 51125904,
            ["SpeakNpcId"] = 701043,
            },
        [51125904] = {
            ["Content"] = "这……诶，你就这么理解吧，也没什么问题，总之就是，在我们华胥，不能出现伤人之事，所以你带来的枪我们就先没收了，等你离开华胥之时再还给你。",
            ["ContentKR"] = "음... 네, 그렇게 이해하셔도 돼요. 아무튼, 화서에선 남을 해치는 행위가 용납되지 않아요. 그러니까 그 총도 저희가 가지고 있다가, 나중에 떠나실 때 돌려드릴게요.",
            ["DialogueId"] = 51125904,
            ["GUID"] = "7FFD03A0",
            ["NextDialogue"] = 51125905,
            ["SpeakNpcId"] = 701044,
            },
        [51125905] = {
            ["Content"] = "可以可以，我来做生意，听本地的规矩，大风什么的，还有别的吗？",
            ["ContentKR"] = "오케이, 노 프라블럼. 비즈니스 하러 왔으니까, 여기 규칙 따를게요. 그 대풍 어쩌고 말인데, 다른 규칙도 있어요?",
            ["DialogueId"] = 51125905,
            ["GUID"] = "7FFD03CA",
            ["NextDialogue"] = 51125906,
            ["SpeakNpcId"] = 701043,
            },
        [51125906] = {
            ["Content"] = "你既然是来做生意的，那这第二条：毁约背盟，不可为也。你可得谨记于心。",
            ["ContentKR"] = "사업을 하러 오셨다면, 두 번째 조항 \"약조를 어기거나 맹세를 저버리지 말지어다\"를 명심하세요.",
            ["DialogueId"] = 51125906,
            ["GUID"] = "7FFD03F4",
            ["NextDialogue"] = 51125907,
            ["SpeakNpcId"] = 701044,
            },
        [51125907] = {
            ["Content"] = "毁约，听得懂，背萌是什么意思？背上萌萌的吗？",
            ["ContentKR"] = "약조 그건 무슨 뜻인지 알겠는데, 맹세를 저버리지 말라는 건 무슨 뜻이죠? 맹세한 종이를 접지 말라는 건가요?",
            ["DialogueId"] = 51125907,
            ["GUID"] = "7FFD041E",
