        [51127725] = {
            ["Content"] = "不说了。",
            ["ContentKR"] = "그만 얘기하죠.",
            ["DialogueId"] = 51127725,
            ["GUID"] = "7FFE2E62",
            ["NextDialogue"] = 51127726,
            },
        [51127726] = {
            ["Content"] = "就走了？不再多说几句了？",
            ["ContentKR"] = "벌써 가려고? 앉아서 얘기 좀 더 하다 가지?",
            ["DialogueId"] = 51127726,
            ["GUID"] = "7FFE2E8C",
            ["SpeakNpcId"] = 701068,
            },
        [51127727] = {
            ["DialogueId"] = 51127727,
            ["DialoguePanelType"] = "None",
            ["Duration"] = 0.1,
            ["FinalDialogueId"] = 51127726,
            ["GUID"] = "7FFE2EB6",
            ["NextOptions"] = {
                [1] = 51127706,
                [2] = 51127711,
                [3] = 51127716,
                [4] = 51127725,
                },
            },
        [51127801] = {
            ["Content"] = "下次和虬先生约见之时，定要选个风雅茶楼，而不是这种……",
            ["ContentKR"] = "다음에 규선생과 약속을 잡을 땐, 이런 데 말고 품격 있는 찻집에서 만나자고 해야겠어...",
            ["DialogueId"] = 51127801,
            ["GUID"] = "7FFE3ADA",
            ["NextDialogue"] = 51127802,
            ["SpeakNpcId"] = 701070,
            },
        [51127802] = {
            ["Content"] = "总得要隔三岔五来这微茫市，实在有损我钱老五的名声……要是被人看到了……我这脸还要不要了，不定说我与这些奸诈小人同流合污呢！",
            ["ContentKR"] = "자꾸만 이 어스름 시장에 들락거려야 하니, 체면이 말이 아니야... 누가 보기라도 하면... 뭐가 되겠어. 이런 간사한 소인배들하고 한패 취급받을 거 아냐!",
            ["DialogueId"] = 51127802,
            ["GUID"] = "7FFE3B04",
            ["NextDialogue"] = 51127803,
            ["SpeakNpcId"] = 701070,
            },
        [51127803] = {
            ["Content"] = "你对微茫市意见很大嘛。",
            ["ContentKR"] = "어스름 시장에 불만이 많나 봐요?",
            ["DialogueId"] = 51127803,
            ["GUID"] = "7FFE3B2E",
            ["NextDialogue"] = 51127804,
            ["SpeakNpcId"] = 100001,
            },
        [51127804] = {
            ["Content"] = "你是谁？看起来不像这里的人，难道是虬先生的考古协会的？不，看起来也不像，考古协会的那些学生而可不会随身携带如此危险的刀械。",
            ["ContentKR"] = "넌 누구지? 여기 사람은 아닌 모양인데, 규선생의 고고학 협회 소속인가? 아니, 그렇지도 않군. 거기 학생들은 그런 위험한 흉기는 안 들고 다니니까.",
            ["DialogueId"] = 51127804,
            ["GUID"] = "7FFE3B58",
            ["NextDialogue"] = 51127805,
            ["SpeakNpcId"] = 701070,
            },
        [51127805] = {
            ["Content"] = "所以你到底是做什么呢，事先声明，我可是虬先生的贵客，是要与他谈生意的，你可不能对我舞刀弄枪的，我身上可还有沉月香囊！",
            ["ContentKR"] = "그래서, 정체가 뭐야? 미리 말해 두지만, 난 규선생과 사업 얘기를 하러 온 손님이니까, 날 공격할 생각 마. 난 침월향 향주머니도 가지고 있어!",
            ["DialogueId"] = 51127805,
            ["GUID"] = "7FFE3B82",
            ["NextOptions"] = {
                [1] = 51127806,
                [2] = 51127817,
                [3] = 51127831,
                },
            ["SpeakNpcId"] = 701070,
            },
        [51127806] = {
            ["Content"] = "瞧给你吓得。",
            ["ContentKR"] = "꽤나 겁먹었네요.",
            ["DialogueId"] = 51127806,
            ["GUID"] = "7FFE3BAC",
            ["NextDialogue"] = 51127807,
            },
        [51127807] = {
            ["Content"] = "什么吓不吓的，我这是对微茫市出没的家伙都有戒心，如果你跟他们不是一伙的，我建议你也提起心思来打交道，别被骗了都帮人数钱。",
            ["ContentKR"] = "겁먹은 게 아니라, 어스름 시장에서 활동하는 녀석들을 경계하는 거야. 녀석들과 한패가 아니라면, 눈 뜨고 코 베이지 말고 정신 바짝 차리고 다녀.",
            ["DialogueId"] = 51127807,
            ["GUID"] = "7FFE3BD6",
            ["NextDialogue"] = 51127808,
            ["SpeakNpcId"] = 701070,
            },
        [51127808] = {
            ["Content"] = "如果你和他们也是一伙的……那……那就当我没说！",
            ["ContentKR"] = "만약 너도 녀석들과 한통속이라면... 저기... 내 말은 못 들은 걸로 해 줘!",
            ["DialogueId"] = 51127808,
            ["GUID"] = "7FFE3C00",
            ["NextOptions"] = {
                [1] = 51127809,
                },
            ["SpeakNpcId"] = 701070,
            },
        [51127809] = {
            ["Content"] = "所以你对微茫市的人又很厌恶？",
            ["ContentKR"] = "그러니까 어스름 시장뿐 사람들을 엄청 싫어하는 거예요?",
            ["DialogueId"] = 51127809,
            ["GUID"] = "7FFE3C2A",
            ["NextDialogue"] = 51127810,
            },
        [51127810] = {
            ["Content"] = "哼，那帮草菅人命，不顾王法的亡命之徒，他们就是华胥的败类，华胥的风气都是被他们带坏了的！",
            ["ContentKR"] = "흥, 사람 목숨 귀한 줄 모르고, 준법정신이라곤 없는 범죄자들이니까. 죄다 화서의 물을 흐려 놓는 쓰레기들이라고!",
            ["DialogueId"] = 51127810,
            ["GUID"] = "7FFE3C54",
            ["NextDialogue"] = 51127811,
            ["SpeakNpcId"] = 701070,
            },
        [51127811] = {
            ["Content"] = "什么微茫市，就是个彻彻底底的黑市，他们根本不讲道义，有钱就赚，赚得全是昧良心钱……我呸！这些人哪有什么良心！",
            ["ContentKR"] = "그리고 어스름 시장은 무슨 얼어 죽을, 그냥 암시장이지. 돈만 되면 무슨 짓이든 하는 녀석들인데, 사람의 도리는 무슨... 카악, 퉤! 양심 같은 소리 하고 앉았네!",
            ["DialogueId"] = 51127811,
            ["GUID"] = "7FFE3C7E",
            ["NextDialogue"] = 51127812,
            ["SpeakNpcId"] = 701070,
            },
        [51127812] = {
            ["Content"] = "你可离他们远些，别看这些披着人皮道貌岸然的样子，他们的头上，多少都背着几桩冤案呢。",
            ["ContentKR"] = "절대 가까이 지내지 마. 인두겁을 뒤집어쓰고 있어도, 녀석들 머리 위엔 억울하게 죽은 영혼들이 둥둥 떠다닐 거라고.",
            ["DialogueId"] = 51127812,
            ["GUID"] = "7FFE3CA8",
            ["NextOptions"] = {
                [1] = 51127813,
                [2] = 51127815,
                },
            ["SpeakNpcId"] = 701070,
            },
        [51127813] = {
            ["Content"] = "可是虬先生不也是这样的人吗？",
            ["ContentKR"] = "근데 규선생이야말로 그런 사람 아니에요?",
            ["DialogueId"] = 51127813,
            ["GUID"] = "7FFE3CD2",
            ["NextDialogue"] = 51127814,
            },
        [51127814] = {
            ["Content"] = "不，虬先生是不一样的，虬先生在这里是为了约束他们，让他们不要再做那些伤天害理的事情，所以虬先生才是这里唯一的好人。",
            ["ContentKR"] = "아니, 규선생은 달라. 이 망나니들이 하늘 무서운 줄 모르고 날뛰지 못하게 고삐를 쥐고 있는 게 바로 규선생이야. 이곳의 유일한 좋은 사람이란 거지.",
            ["DialogueId"] = 51127814,
            ["GUID"] = "7FFE3CFC",
            ["SpeakNpcId"] = 701070,
            },
        [51127815] = {
            ["Content"] = "你觉得虬先生就是干净的？",
            ["ContentKR"] = "규선생은 깨끗하다고 생각해요?",
            ["DialogueId"] = 51127815,
            ["GUID"] = "7FFE3D26",
            ["NextDialogue"] = 51127816,
            },
        [51127816] = {
            ["Content"] = "虬先生就是黑市里开出的荷花！出淤泥而不染，他能在这大染缸之中自保，并混出了自己的名头，已经很了不起了，你这种小孩不会理解的。",
            ["ContentKR"] = "규선생은 암시장이랑 진흙탕 속에서 피어난 연꽃 같은 분이지. 너 같은 어린애는 이해 못 하겠지만, 이런 시궁창 속에서 나쁜 물 안 들고 명성까지 얻는 건 정말 대단한 거야.",
            ["DialogueId"] = 51127816,
            ["GUID"] = "7FFE3D50",
            ["SpeakNpcId"] = 701070,
            },
        [51127817] = {
            ["Content"] = "你这么厌恶微茫市，为什么还和虬先生做生意？",
            ["ContentKR"] = "어스름 시장을 그렇게 싫어하면서, 규선생하고 거래는 왜 하는 거예요?",
            ["DialogueId"] = 51127817,
            ["GUID"] = "7FFE3D7A",
            ["NextDialogue"] = 51127818,
            },
        [51127818] = {
            ["Content"] = "虬先生……虬先生他不一样……",
            ["ContentKR"] = "규선생은... 다른 녀석들하곤 다르다니까...",
            ["DialogueId"] = 51127818,
            ["GUID"] = "7FFE3DA4",
            ["NextDialogue"] = 51127819,
            ["SpeakNpcId"] = 701070,
            },
        [51127819] = {
            ["Content"] = "虬先生是大才，无论是生意场还是收藏界，他可都是鼎鼎有名的人物。不止如此，和他相处时的感觉也让人舒服，他总能洞察你真实的需求。",
            ["ContentKR"] = "규선생은 사업이든 수집이든, 두 영역에서 모두가 알아주는 유명 인사야. 게다가 사람 마음을 편하게 해 주고, 상대가 진짜 원하는 걸 꿰뚫어 보는 큰 인물이라고.",
            ["DialogueId"] = 51127819,
            ["GUID"] = "7FFE3DCE",
            ["NextDialogue"] = 51127820,
            ["SpeakNpcId"] = 701070,
            },
        [51127820] = {
            ["Content"] = "有句话怎么说来着，和聪明人做事，话只用说一半，对方便能知晓你的想法，并竭力满足你。",
            ["ContentKR"] = "왜 그, 똑똑한 사람이랑 일을 하면, 말을 개떡같이 해도 찰떡같이 알아듣고, 알아서 딱 잘해준다는 말도 있잖아.",
            ["DialogueId"] = 51127820,
            ["GUID"] = "7FFE3DF8",
            ["NextOptions"] = {
                [1] = 51127821,
                },
            ["SpeakNpcId"] = 701070,
            },
        [51127821] = {
            ["Content"] = "还有呢？",
            ["ContentKR"] = "그리고요?",
            ["DialogueId"] = 51127821,
            ["GUID"] = "7FFE3E22",
            ["NextDialogue"] = 51127822,
            },
        [51127822] = {
            ["Content"] = "还有，那可太多了，虬先生出钱爽快，从我这定的陈皮，都是百年起步的，在这华胥没几个人买得起这么稀有的东西！",
            ["ContentKR"] = "그리고... 또 많지. 규선생은 통이 커. 나한테 귤껍질을 말린 진피를 주문할 때도, 100년 이상 된 귀한 걸 찾거든. 이 화서에 그럴 여유가 있는 사람이 몇이나 있겠어?",
            ["DialogueId"] = 51127822,
            ["GUID"] = "7FFE3E4C",
            ["NextDialogue"] = 51127823,
            ["SpeakNpcId"] = 701070,
            },
        [51127823] = {
            ["Content"] = "他还私下资助考古事业，我们华胥泱泱前年的历史，若不是虬先生出资挖掘，怕是多少时日都难见天日。",
            ["ContentKR"] = "게다가 개인적으로 고고학 발굴에 자금 후원도 하고 있어. 화서의 장엄한 역사가 다시 세상 빛을 보게 해 주는 거지.",
            ["DialogueId"] = 51127823,
            ["GUID"] = "7FFE3E76",
            ["NextDialogue"] = 51127824,
            ["SpeakNpcId"] = 701070,
            },
        [51127824] = {
            ["Content"] = "还有……",
            ["ContentKR"] = "그리고 또...",
            ["DialogueId"] = 51127824,
            ["GUID"] = "7FFE3EA0",
            ["NextOptions"] = {
                [1] = 51127825,
                [2] = 51127828,
                },
            ["SpeakNpcId"] = 701070,
            },
        [51127825] = {
            ["Content"] = "还有呢？",
            ["ContentKR"] = "그리고 또요?",
            ["DialogueId"] = 51127825,
            ["GUID"] = "7FFE3ECA",
            ["NextDialogue"] = 51127826,
            },
        [51127826] = {
            ["Content"] = "讲义气啊！我们这些经常来往的熟人，逢年过节，虬先生总是会给咱们都寄上些礼品，有时候是精致名点，有时是珍奇古玩，总是少不了的。",
            ["ContentKR"] = "의리가 있어! 우리처럼 자주 거래하는 지인들에겐 명절 때마다 꼭 선물을 보내 준다고. 고급 과자일 때도 있고, 희귀한 골동품일 때도 있는데, 한 번도 빠뜨린 적이 없어.",
            ["DialogueId"] = 51127826,
            ["GUID"] = "7FFE3EF4",
            ["NextDialogue"] = 51127827,
            ["SpeakNpcId"] = 701070,
            },
        [51127827] = {
            ["Content"] = "如果不是虬先生对大家如此之好，我何必还苦兮兮跑来这黑市等着他与他交易……",
            ["ContentKR"] = "규선생이 사람들한테 잘하니까 오는 거지, 아니면 내가 뭐 하러 이 고생을 해 가며 암시장까지 와서 거래를 하겠어...",
            ["DialogueId"] = 51127827,
            ["GUID"] = "7FFE3F1E",
            ["SpeakNpcId"] = 701070,
            },
        [51127828] = {
            ["Content"] = "好了不要再说了，知道你是虬吹了。",
            ["ContentKR"] = "거기까지만 하죠. 그쪽이 규선생 '찐팬'인 건 잘 알았어요.",
            ["DialogueId"] = 51127828,
            ["GUID"] = "7FFE3F48",
            ["NextDialogue"] = 51127829,
            },
        [51127829] = {
            ["Content"] = "什么意思，你们这些小孩嘴里说出的词语总是让我听不明白，就像我那八岁的女儿，一天到晚都在那说什么……又能怎……语气怪怪的。",
            ["ContentKR"] = "그건 또 뭐야? 요즘 애들이 쓰는 말은 정말 모르겠단 말이야. 우리 여덟 살 난 딸내미도 하루 종일 쫑알거리다가 갑자기 이상한 말투로 \"듀아아아!\"라고 하던데.",
            ["DialogueId"] = 51127829,
            ["GUID"] = "7FFE3F72",
            ["NextDialogue"] = 51127830,
            ["SpeakNpcId"] = 701070,
            },
        [51127830] = {
            ["Content"] = "说起来我那女儿，也很喜欢老虬，老虬来我家时，总会给她额外捎上些甜品果子，她每回都盼着他来……",
            ["ContentKR"] = "그러고 보니까, 우리 딸도 규선생을 참 좋아해. 우리 집에 방문할 땐 딸 몫으로 달달한 간식을 챙겨 와 주거든. 애가 매번 목이 빠지게 기다린다니까...",
            ["DialogueId"] = 51127830,
            ["GUID"] = "7FFE3F9C",
            ["SpeakNpcId"] = 701070,
            },
        [51127831] = {
            ["Content"] = "我先溜了！",
            ["ContentKR"] = "전 이만 가 볼게요!",
            ["DialogueId"] = 51127831,
            ["GUID"] = "7FFE3FC6",
            ["NextDialogue"] = 51127832,
            },
        [51127832] = {
            ["Content"] = "怎么就走了，你还没说你来这里是做什么的呢！",
            ["ContentKR"] = "왜 그냥 가? 여기 온 이유는 말해 주고 가야지!",
            ["DialogueId"] = 51127832,
            ["GUID"] = "7FFE3FF0",
            ["SpeakNpcId"] = 701070,
            },
        [51127901] = {
            ["Content"] = "（这只狴犴的状态看起来很不对劲，似乎在变黑与保持白色之间摇摆不定……）",
            ["ContentKR"] = "(폐안의 상태가 심상치 않아 보인다. 마치 흑백이 서로 주도권을 뺏으려는 것처럼 아슬아슬하게 맞서고 있다...)",
            ["DialogueId"] = 51127901,
            ["GUID"] = "7FFE4B42",
            ["NextOptions"] = {
                [1] = 51127902,
                [2] = 51127907,
                },
            },
        [51127902] = {
            ["Content"] = "我能帮你什么吗？",
            ["ContentKR"] = "혹시 내가 도와줄까?",
            ["DialogueId"] = 51127902,
            ["GUID"] = "7FFE4B6C",
            ["NextDialogue"] = 51127903,
            },
        [51127903] = {
            ["Content"] = "呼……",
            ["ContentKR"] = "쉬익...",
            ["DialogueId"] = 51127903,
            ["GUID"] = "7FFE4B96",
            ["NextDialogue"] = 51127904,
            ["SpeakNpcId"] = 701071,
            },
        [51127904] = {
            ["Content"] = "（它看了你一眼，眼底猩红，不知是受了伤还是在竭力保持清醒。）",
            ["ContentKR"] = "(이쪽으로 시선을 향한 폐안의 눈동자가 붉게 물들어 있다. 다친 건지, 간신히 제정신을 붙들고 있는 건지 알 수 없다.)",
            ["DialogueId"] = 51127904,
            ["GUID"] = "7FFE4BC0",
            ["NextDialogue"] = 51127905,
            },
        [51127905] = {
            ["Content"] = "……呜……噫呜……呜……",
            ["ContentKR"] = "...우우...우으...우...",
            ["DialogueId"] = 51127905,
            ["GUID"] = "7FFE4BEA",
            ["NextDialogue"] = 51127906,
            ["SpeakNpcId"] = 701071,
            },
        [51127906] = {
            ["Content"] = "（狴犴在你面前自绝了。）",
            ["ContentKR"] = "(폐안이 눈앞에서 스스로 목숨을 끊는다.)",
            ["DialogueId"] = 51127906,
            ["GUID"] = "7FFE4C14",
            ["NextOptions"] = {
                [1] = 51127912,
                [2] = 51127914,
                },
            },
        [51127907] = {
            ["Content"] = "（拿起武器，做好防备。）",
            ["ContentKR"] = "(무기를 꺼내고 자세를 다잡는다.)",
            ["DialogueId"] = 51127907,
            ["GUID"] = "7FFE4C3E",
            ["NextDialogue"] = 51127908,
            },
        [51127908] = {
            ["Content"] = "嗷！",
            ["ContentKR"] = "크르르릉!",
            ["DialogueId"] = 51127908,
            ["GUID"] = "7FFE4C68",
            ["NextDialogue"] = 51127909,
            ["SpeakNpcId"] = 701071,
            },
        [51127909] = {
            ["Content"] = "（在你露出刀光的那一刹，狴犴仰天长啸，向你冲来，却因力竭跌倒在地。）",
            ["ContentKR"] = "(무기를 꺼내 든 순간, 폐안은 더 이상 억누를 수 없다는 듯 검게 변해 당신을 향해 달려든다.)",
            ["DialogueId"] = 51127909,
            ["GUID"] = "7FFE4C92",
            ["NextDialogue"] = 51127910,
            },
        [51127910] = {
            ["Content"] = "嗷呜呜……呜……",
            ["ContentKR"] = "우으으... 우...",
            ["DialogueId"] = 51127910,
            ["GUID"] = "7FFE4CBC",
            ["NextDialogue"] = 51127911,
            ["SpeakNpcId"] = 701071,
            },
        [51127911] = {
            ["Content"] = "（狴犴在你面前咽了气。）",
            ["ContentKR"] = "(폐안이 눈앞에서 숨을 거뒀다.)",
            ["DialogueId"] = 51127911,
            ["GUID"] = "7FFE4CE6",
            ["NextOptions"] = {
                [1] = 51127912,
                [2] = 51127914,
                },
            },
        [51127912] = {
            ["Content"] = "安葬狴犴。",
            ["ContentKR"] = "폐안을 묻어 준다.",
            ["DialogueId"] = 51127912,
            ["GUID"] = "7FFE4D10",
            ["ImprPlusId"] = 1207,
            ["NextDialogue"] = 51127913,
            },
        [51127913] = {
            ["Content"] = "（你将这只死去的狴犴好好安葬了……）",
            ["ContentKR"] = "(당신은 숨을 거둔 폐안을 정성껏 묻어 준다...)",
            ["DialogueId"] = 51127913,
            ["GUID"] = "7FFE4D3A",
            },
        [51127914] = {
            ["Content"] = "离开吧。",
            ["ContentKR"] = "떠난다.",
            ["DialogueId"] = 51127914,
            ["GUID"] = "7FFE4D64",
            ["ImprPlusId"] = 1211,
            ["NextDialogue"] = 51127915,
            },
        [51127915] = {
            ["Content"] = "（自尘土中来，归尘土中去……）",
            ["ContentKR"] = "(흙에서 태어나, 흙으로 돌아갔구나...)",
            ["DialogueId"] = 51127915,
            ["GUID"] = "7FFE4D8E",
            },
        [51128001] = {
            ["Content"] = "嘶……又冷起来了，这鬼天气！我带来的考古器材全都结了一层晶，零件迟钝，反应不灵，诶！又要让虬先生破费维修了！",
            ["ContentKR"] = "으... 또 추워지네. 뭔 날씨가 이래! 가져온 고고학 장비에 성에가 껴서, 부품도 잘 안 움직이고 반응도 느려졌잖아! 또 규선생한테 수리비를 부탁해야 되겠어!",
            ["DialogueId"] = 51128001,
            ["GUID"] = "7FFE5BAA",
            ["NextDialogue"] = 51128002,
            ["SpeakNpcId"] = 701072,
            },
        [51128002] = {
            ["Content"] = "咦？你是谁？你怎么会跑到这种地方来？快回去快回去，这里可不是等闲之辈可以随意来往的地方！",
            ["ContentKR"] = "어라? 넌 누구야? 왜 이런 데 있어? 여긴 아무나 함부로 돌아다닐 수 있는 곳이 아니야, 얼른 돌아가! 훠이, 훠이!",
            ["DialogueId"] = 51128002,
            ["GUID"] = "7FFE5BD4",
            ["NextOptions"] = {
                [1] = 51128003,
                [2] = 51128005,
                },
            ["SpeakNpcId"] = 701072,
            },
        [51128003] = {
            ["Content"] = "（听到她提起虬先生……）我是虬先生叫过来的。",
            ["ContentKR"] = "규선생이 보내서 온 거야.",
            ["DialogueId"] = 51128003,
            ["GUID"] = "7FFE5BFE",
            ["ImprPlusId"] = 1208,
            ["NextDialogue"] = 51128004,
            },
        [51128004] = {
            ["Content"] = "虬先生叫你来的？怎么可能？不是说了尘漠石海区域只由我一人来负责就好吗？来之前还说的……什么什么，无甚旧史，不必细考的……",
            ["ContentKR"] = "규선생이? 그럴 리 없는데? 낙진의 바다는 나 혼자 담당하는 거 아니었나? 출발하기 전에도 분명히... 별다른 역사도 없으니까, 자세히 조사할 필요 없다고 했는데...",
            ["DialogueId"] = 51128004,
            ["GUID"] = "7FFE5C28",
            ["SpeakNpcId"] = 701072,
            },
        [51128005] = {
            ["Content"] = "看你一个人在这很危险，就过来看看。",
            ["ContentKR"] = "혼자 있는 게 위험해 보이길래 와 본 거야.",
            ["DialogueId"] = 51128005,
            ["GUID"] = "7FFE5C52",
            ["ImprPlusId"] = 1207,
            ["NextDialogue"] = 51128006,
            },
        [51128006] = {
            ["Content"] = "呜呜呜，谢谢你好心人，我在这太久了，风餐露宿的，都快忘了还有除了玄色狴犴之外的正常人存在了。",
            ["ContentKR"] = "훌쩍, 너 되게 착하구나. 제대로 먹지도, 자지도 못하고 여기 너무 오래 있었더니, 검은 폐안 말고 멀쩡한 사람이 있단 것도 까먹을 뻔했는데, 고마워.",
            ["DialogueId"] = 51128006,
            ["GUID"] = "7FFE5C7C",
            ["NextDialogue"] = 51128007,
            ["SpeakNpcId"] = 701072,
            },
        [51128007] = {
            ["Content"] = "不管怎么说，你也得先回去多带些衣服，这里的温差特殊，没一会就要冷得结冰了。",
            ["ContentKR"] = "아무튼, 일단 돌아가서 옷부터 더 챙겨 와. 여긴 유별나게 기온 차가 심한 곳이라, 금방 또 꽁꽁 얼어붙을 만큼 추워질 거야.",
            ["DialogueId"] = 51128007,
            ["GUID"] = "7FFE5CA6",
            ["NextDialogue"] = 51128008,
            ["SpeakNpcId"] = 701072,
            },
        [51128008] = {
            ["Content"] = "呼……我也得去加上两件衣服了。",
            ["ContentKR"] = "우으... 나도 옷 좀 더 껴입어야겠다.",
            ["DialogueId"] = 51128008,
            ["GUID"] = "7FFE5CD0",
            ["SpeakNpcId"] = 701072,
            },
        [51128101] = {
            ["Content"] = "一会冷一会热……想当年我姥姥还跟我说，这里是个春暖花开的好地方呢！",
            ["ContentKR"] = "왜 이리 추웠다 더웠다 하는지... 외할머니한테 듣기론, 옛날엔 꽃들이 활짝 핀 따뜻한 곳이라고 했는데!",
            ["DialogueId"] = 51128101,
            ["GUID"] = "7FFE6C12",
            ["NextDialogue"] = 51128102,
            ["SpeakNpcId"] = 701072,
            },
        [51128102] = {
            ["Content"] = "啊啊啊！又热起来了！一热起来我就心烦气躁！臭外套，滚一边去吧！",
            ["ContentKR"] = "아아악! 또 더워지기 시작했네! 더워지면 확 짜증이 난다고! 이 망할 외투, 저리 꺼져!",
            ["DialogueId"] = 51128102,
            ["GUID"] = "7FFE6C3C",
            ["NextDialogue"] = 51128103,
            ["SpeakNpcId"] = 701072,
            },
        [51128103] = {
            ["Content"] = "你！你是谁！哦！我想起来了，你之前来过这里！衣服带好了吗？这就回来啦？",
            ["ContentKR"] = "너! 누구야? 아! 기억났다. 전에 여기 왔었잖아! 옷은 챙겨 왔어? 어떻게 벌써 돌아왔네?",
            ["DialogueId"] = 51128103,
            ["GUID"] = "7FFE6C66",
            ["NextOptions"] = {
                [1] = 51128104,
                [2] = 51128106,
                [3] = 51128120,
                },
            ["SpeakNpcId"] = 701072,
            },
        [51128104] = {
            ["Content"] = "我包里有很多件。",
            ["ContentKR"] = "옷이라면 가방 안에 많이 있어.",
            ["DialogueId"] = 51128104,
            ["GUID"] = "7FFE6C90",
            ["NextDialogue"] = 51128105,
            },
        [51128105] = {
            ["Content"] = "那就好，你可不知道这里的天气有多怪，一会冷得牙齿打颤，一会又热得满头大汗，真是要了命了。",
            ["ContentKR"] = "그럼 됐어. 여기 날씨가 얼마나 변덕스러운데. 이가 덜덜 떨릴 정도로 추웠다가도, 땀이 뻘뻘 날 만큼 더워진다니까. 진짜 죽을 맛이야.",
            ["DialogueId"] = 51128105,
            ["GUID"] = "7FFE6CBA",
            ["NextOptions"] = {
                [1] = 51128108,
                },
            ["SpeakNpcId"] = 701072,
            },
        [51128106] = {
            ["Content"] = "我不怕冷，也不怕热。",
            ["ContentKR"] = "난 추위도, 더위도 잘 안 타.",
            ["DialogueId"] = 51128106,
            ["GUID"] = "7FFE6CE4",
            ["NextDialogue"] = 51128107,
            },
        [51128107] = {
            ["Content"] = "什么？！那是你没见识过这里的天气有多怪！一会冷得牙齿打颤，一会又热得满头大汗，真是要了命了。",
            ["ContentKR"] = "뭐?! 너 여기 날씨가 얼마나 변덕스러운지 아직 안 겪어 봤구나! 추워서 덜덜 떨다가도, 순식간에 더워서 땀이 뻘뻘 난다니까. 진짜 죽을 맛이야.",
            ["DialogueId"] = 51128107,
            ["GUID"] = "7FFE6D0E",
            ["NextOptions"] = {
                [1] = 51128108,
                },
            ["SpeakNpcId"] = 701072,
            },
        [51128108] = {
            ["Content"] = "这里的天气为什么奇怪？",
            ["ContentKR"] = "여긴 날씨가 왜 그 모양인 거야?",
            ["DialogueId"] = 51128108,
            ["GUID"] = "7FFE6D38",
            ["NextDialogue"] = 51128109,
            },
        [51128109] = {
            ["Content"] = "嘿！你要问这个，我可太有发言权了，我在这待了这么久，可算把这地方的历史和劳什子浊化现象整明白了七七八八。",
            ["ContentKR"] = "이야! 물어볼 상대를 제대로 찾았어. 난 여기 진짜 오래 있었거든. 이 동네 역사랑 그 망할 혼탁화 현상에 대해선 얼추 다 알고 있어.",
            ["DialogueId"] = 51128109,
            ["GUID"] = "7FFE6D62",
            ["NextDialogue"] = 51128122,
            ["SpeakNpcId"] = 701072,
            },
        [51128110] = {
            ["Content"] = "聊聊这里的曾经。",
            ["ContentKR"] = "이곳의 과거 이야기를 듣고 싶어.",
            ["DialogueId"] = 51128110,
            ["GUID"] = "7FFE6D8C",
            ["NextDialogue"] = 51128111,
            },
        [51128111] = {
            ["Content"] = "以前啊，我太姥姥说的，说这里是个好地方，好山好水，山川纵横，美景如画，四季如春。那时这还没那么荒，有人会在山上种半步仙。",
            ["ContentKR"] = "증조할머니 말씀으론, 산 좋고 물 좋은 곳이었대. 그땐 경치도 예쁘고 일 년 내내 따뜻하고. 이렇게 황량하지도 않아서, 산에 반보선도 심었었다더라.",
            ["DialogueId"] = 51128111,
            ["GUID"] = "7FFE6DB6",
            ["NextDialogue"] = 51128112,
            ["SpeakNpcId"] = 701072,
            },
        [51128112] = {
            ["Content"] = "那花一开，满山都是红艳艳的，香气熏得人昏昏沉沉，扰得路过的织星客们纷纷投诉，说是从这路上走就会香昏迷过去。",
            ["ContentKR"] = "반보선이 피면, 산 전체가 빨갛게 물들고 꽃향기도 엄청 진했는데, 어떤 별을 잇는 자들은 그걸로 불평도 했다나 봐. 향기에 취해서 기절할 것 같다고 말이야.",
            ["DialogueId"] = 51128112,
            ["GUID"] = "7FFE6DE0",
            ["SpeakNpcId"] = 701072,
            },
        [51128113] = {
            ["Content"] = "聊聊这里为什么会变成这样。",
            ["ContentKR"] = "어쩌다 이렇게 변한 건지 알고 싶어.",
            ["DialogueId"] = 51128113,
            ["GUID"] = "7FFE6E0A",
            ["NextDialogue"] = 51128114,
            },
        [51128114] = {
            ["Content"] = "还能因为什么，烛阴之灾呗。那恶兽，贼心不死，吞吐之间全是黑雾，雾气从海上向内地不断扩散，直至覆盖整个区域。",
            ["ContentKR"] = "뭐 때문이겠어, 다 촉룡의 재앙 때문이지. 그 사악하고 못된 짐승이 내뱉는 검은 숨결 때문에, 바다는 물론이고 내륙까지 싹 다 안개로 뒤덮여 버린 거야.",
            ["DialogueId"] = 51128114,
            ["GUID"] = "7FFE6E34",
            ["NextDialogue"] = 51128115,
            ["SpeakNpcId"] = 701072,
            },
        [51128115] = {
            ["Content"] = "黑雾还邪气着呢！被影响的地方一会冷一会热，山上的石头受不住这温差，全碎成了块块。那花啊草啊的也不长了，盖上了一层不知道什么东西。",
            ["ContentKR"] = "진짜 지독한 안개라니까! 하도 더웠다 추웠다 하니까, 산에 있는 돌들도 못 버티고 죄다 조각나 버렸지 뭐야. 꽃이나 풀들도 정체 모를 뭔가에 뒤덮여서 자라지도 않아.",
            ["DialogueId"] = 51128115,
            ["GUID"] = "7FFE6E5E",
            ["NextDialogue"] = 51128116,
            ["SpeakNpcId"] = 701072,
            },
        [51128116] = {
            ["Content"] = "这种现象就是浊化，也是我一直在这里研究的方向。",
            ["ContentKR"] = "이게 바로 혼탁화 현상이란 거야. 난 여기서 쭉 그걸 연구하고 있어.",
            ["DialogueId"] = 51128116,
            ["GUID"] = "7FFE6E88",
            ["SpeakNpcId"] = 701072,
            },
        [51128117] = {
            ["Content"] = "聊聊浊化。",
            ["ContentKR"] = "혼탁화가 뭔지 자세히 설명해 줘.",
            ["DialogueId"] = 51128117,
            ["GUID"] = "7FFE6EB2",
            ["NextDialogue"] = 51128118,
            },
        [51128118] = {
            ["Content"] = "唔……这其实很难说，但我的初步推测是，黑雾里有种晶尘，肉眼看不到，但是会在呼吸之间被吸入体内。",
            ["ContentKR"] = "음... 설명하기 좀 어려운데, 내 생각엔 검은 안개 속에 결정 가루 같은 게 있을 거야. 눈에는 안 보여도, 숨 쉴 때 몸 안으로 들어오는 거지.",
            ["DialogueId"] = 51128118,
            ["GUID"] = "7FFE6EDC",
            ["NextDialogue"] = 51128119,
            ["SpeakNpcId"] = 701072,
            },
        [51128119] = {
            ["Content"] = "被这种晶尘影响的生物，原本的形态就会被破坏。原理嘛……搞不懂！但是邪门的很，不是我说，狴犴大人都抵挡不了呢！",
            ["ContentKR"] = "그리고 그 결정 가루에 영향을 받은 생물은, 원래의 형태를 잃게 돼. 원리는... 나도 몰라! 그런데 괜히 하는 말이 아니라 진짜 지독한 녀석이야! 폐안님들도 못 당해댄다고!",
            ["DialogueId"] = 51128119,
            ["GUID"] = "7FFE6F06",
            ["SpeakNpcId"] = 701072,
            },
        [51128120] = {
            ["Content"] = "不和你聊了",
            ["ContentKR"] = "이제 그만 얘기하자.",
            ["DialogueId"] = 51128120,
            ["GUID"] = "7FFE6F30",
            ["NextDialogue"] = 51128121,
            },
        [51128121] = {
            ["Content"] = "好不容易等来个聊聊天的，诶……再不和正常人说说话，我的嘴巴可就要生锈啦。",
            ["ContentKR"] = "에휴, 겨우 말 상대가 생겼나 했더니만... 멀쩡한 사람이랑 얘기 좀 해야지, 이러다 말하는 법도 까먹겠어.",
            ["DialogueId"] = 51128121,
            ["GUID"] = "7FFE6F5A",
            ["SpeakNpcId"] = 701072,
            },
        [51128122] = {
            ["DialogueId"] = 51128122,
            ["DialoguePanelType"] = "None",
            ["Duration"] = 0.1,
            ["FinalDialogueId"] = 51128121,
            ["GUID"] = "7FFE6F84",
            ["NextOptions"] = {
                [1] = 51128110,
                [2] = 51128113,
                [3] = 51128117,
                [4] = 51128120,
                },
            },
        [51128201] = {
            ["Content"] = "这怎么连个插香的地方都没有……还好我带了香炉！不然今天好不容易铤而走险过来一趟，要是啥也没干就回去可太丢面子了！",
            ["ContentKR"] = "그런데 향 꽂을 데가 없네... 향로를 가져오길 망정이지, 목숨 걸고 여기까지 왔는데, 하마터면 아무것도 못 하고 돌아가서 망신만 당할 뻔했잖아!",
            ["DialogueId"] = 51128201,
            ["GUID"] = "7FFE7C7A",
            ["NextOptions"] = {
                [1] = 51128202,
                [2] = 51128204,
                },
            ["SpeakNpcId"] = 701073,
            },
        [51128202] = {
            ["Content"] = "你怎么一个人在这，这里很危险。",
            ["ContentKR"] = "왜 이런 데 혼자 있어? 여기 엄청 위험한 곳이야.",
            ["DialogueId"] = 51128202,
            ["GUID"] = "7FFE7CA4",
            ["ImprPlusId"] = 1207,
            ["NextDialogue"] = 51128203,
            },
        [51128203] = {
            ["Content"] = "我当然知道危险啦，多谢你的提醒，但我就是图着危险才特意来此处的！我偏要来这旁人不敢涉足之地，点上一根沉月香给白龙神君，求他将烛阴之灾彻底扫除！",
            ["ContentKR"] = "그건 당연히 알지. 신경 써 주는 건 고마운데, 난 일부러 찾아온 거야! 남들은 올 엄두도 못 내는 여기서, 백룡신군께 침월향 하나 올리고, 촉룡의 재앙을 완전히 없애 달라고 빌려고!",
            ["DialogueId"] = 51128203,
            ["GUID"] = "7FFE7CCE",
            ["SpeakNpcId"] = 701073,
            },
        [51128204] = {
            ["Content"] = "再等一会就有玄色狴犴来吃你咯。",
            ["ContentKR"] = "조금 있으면 검은 폐안이 널 잡아먹으러 올걸.",
            ["DialogueId"] = 51128204,
            ["GUID"] = "7FFE7CF8",
            ["ImprPlusId"] = 1205,
            ["NextDialogue"] = 51128205,
            },
        [51128205] = {
            ["Content"] = "莫慌莫慌，我自是知道此地危险，但是我偏要来这旁人不敢涉足之地，点上一根沉月香给白龙神君，求他将烛阴之灾彻底扫除！",
            ["ContentKR"] = "괜찮아, 괜찮아. 위험한 곳인 줄은 아는데, 남들은 올 엄두도 못 내는 여기서, 백룡신군께 침월향 하나 올리고, 촉룡의 재앙을 완전히 없애 달라고 빌러 온 거니까!",
            ["DialogueId"] = 51128205,
            ["GUID"] = "7FFE7D22",
            ["NextDialogue"] = 51128206,
            ["SpeakNpcId"] = 701073,
            },
        [51128206] = {
            ["Content"] = "不必担心我，我虽手无寸铁，但胜在机灵跑得快，且不是第一天来这了。反倒是你要担心自己，是那玄色狴犴找过来，我拔腿就跑时带不上你。",
            ["ContentKR"] = "걱정 마. 난 여기가 처음도 아니고, 무기는 없지만 눈치가 빨라서 도망엔 자신 있거든. 근데 검은 폐안이 오면 난 곧바로 튈 거라 널 챙겨 줄 여유는 없다? 네 몸이나 걱정하는 게 어때?",
            ["DialogueId"] = 51128206,
            ["GUID"] = "7FFE7D4C",
            ["NextDialogue"] = 51128207,
            ["SpeakNpcId"] = 701073,
            },
        [51128207] = {
            ["Content"] = "所以你先走吧，不用管我！",
            ["ContentKR"] = "그러니까 난 신경 쓰지 말고, 얼른 가 봐!",
            ["DialogueId"] = 51128207,
            ["GUID"] = "7FFE7D76",
            ["SpeakNpcId"] = 701073,
            },
        [51128208] = {
            ["Content"] = "就在这里点香，白龙神君一定会像神话里那样挺身而出，将那恶兽赶尽杀绝！",
            ["ContentKR"] = "여기서 향을 피우는 거야! 그러면 신화에서처럼 백룡신군께서 나타나 저 사악한 짐승들을 모두 처치해 주시겠지!",
            ["DialogueId"] = 51128208,
            ["GUID"] = "7FFE7DA0",
            ["NextDialogue"] = 51128209,
            ["SpeakNpcId"] = 701073,
            },
        [51128209] = {
            ["Content"] = "诶哟，怎么又是你，你也真不害怕呢，这种地方你还一遍又一遍地来。",
            ["ContentKR"] = "이야, 또 만났네. 자꾸만 이런 델 오다니, 너 정말 겁도 없구나.",
            ["DialogueId"] = 51128209,
            ["GUID"] = "7FFE7DCA",
            ["NextOptions"] = {
                [1] = 51128210,
                [2] = 51128233,
                },
            ["SpeakNpcId"] = 701073,
            },
        [51128210] = {
            ["Content"] = "这话该是我说你吧……",
            ["ContentKR"] = "그건 오히려 내가 할 말 같은데...",
            ["DialogueId"] = 51128210,
            ["GUID"] = "7FFE7DF4",
            ["NextDialogue"] = 51128211,
            },
        [51128211] = {
            ["Content"] = "哦！说的也是呢，我才是一遍又一遍来这的，不过不是说了嘛，我机灵跑得快，哪怕遇到危险也可以逃走的，为了你的安全，你还是先走吧。",
            ["ContentKR"] = "어! 하긴 그렇네. 너보단 내가 더 자주 왔으니까. 근데 전에도 말했지만, 난 눈치가 백단이라 위험해져도 도망칠 수 있어. 그러니까 네 안전을 생각해서, 너 먼저 돌아가.",
            ["DialogueId"] = 51128211,
            ["GUID"] = "7FFE7E1E",
            ["NextOptions"] = {
                [1] = 51128212,
                },
            ["SpeakNpcId"] = 701073,
            },
        [51128212] = {
            ["Content"] = "我压根不用逃，直接击退玄色狴犴都可以。",
            ["ContentKR"] = "난 도망 안 쳐도 돼. 검은 폐안 정도는 쉽게 해치울 수 있거든.",
            ["DialogueId"] = 51128212,
            ["GUID"] = "7FFE7E48",
            ["NextDialogue"] = 51128213,
            },
        [51128213] = {
            ["Content"] = "看不出来啊，没想到你这么厉害，那你应该不是华胥人吧，唔……穿着打扮的确不是很像……",
            ["ContentKR"] = "그렇게 안 보이는데, 너 엄청 세구나. 그러면 화서 사람은 아니겠네. 음... 옷차림을 보니까 아닌 게 확실하네...",
            ["DialogueId"] = 51128213,
            ["GUID"] = "7FFE7E72",
            ["NextDialogue"] = 51128214,
            ["SpeakNpcId"] = 701073,
            },
        [51128214] = {
            ["Content"] = "那你要跟我一起奉香吗？要是有两个人一起，想必白龙神君更能听到我们的求助！",
            ["ContentKR"] = "나랑 같이 향 피우지 않을래? 기도드리는 사람이 2명이면, 백룡신군께서 소원을 들어주실 확률도 2배잖아!",
            ["DialogueId"] = 51128214,
            ["GUID"] = "7FFE7E9C",
            ["NextOptions"] = {
                [1] = 51128215,
                [2] = 51128221,
                },
            ["SpeakNpcId"] = 701073,
            },
        [51128215] = {
            ["Content"] = "你在这荒郊野岭奉香不是很奇怪吗？",
            ["ContentKR"] = "이런 외딴 산골짜기에서 향 피우는 거, 엄청 이상하지 않아?",
            ["DialogueId"] = 51128215,
            ["GUID"] = "7FFE7EC6",
            ["NextDialogue"] = 51128216,
            },
        [51128216] = {
            ["Content"] = "诶，这你就有所不知了，你应该知道此地天象异诡是何原因吧，就是那百年之前危害华胥的烛阴之灾，可你知不知道，烛阴这只恶兽为何会造成灾害呢？",
            ["ContentKR"] = "에이, 그건 네가 잘 몰라서 하는 소리야. 지금 이 이상한 날씨는 백 년 전에 화서를 덮친 촉룡의 재앙 때문이란 건 알지? 그런데, 촉룡이 왜 재앙을 일으켰을까?",
            ["DialogueId"] = 51128216,
            ["GUID"] = "7FFE7EF0",
            ["NextDialogue"] = 51128217,
            ["SpeakNpcId"] = 701073,
            },
        [51128217] = {
            ["Content"] = "算啦，我也就不卖关子了，直接告诉你吧。在咱们华胥上古时期，有一只为非作歹的妖兽，名为烛阴。",
            ["ContentKR"] = "관두자, 뜸 그만 들이고 바로 알려 줄게. 까마득한 옛날, 우리 화서엔 온갖 나쁜 짓은 다 하는 촉룡이란 짐승이 있었어.",
            ["DialogueId"] = 51128217,
            ["GUID"] = "7FFE7F1A",
            ["NextDialogue"] = 51128218,
            ["SpeakNpcId"] = 701073,
            },
        [51128218] = {
            ["Content"] = "其以不安之心篡夺华胥人行凶作恶，伤人见血，百姓因其作乱民不聊生，叫苦不迭。百姓们便轮番点香，求助于神君。",
            ["ContentKR"] = "녀석은 사람들의 불안을 이용해, 서로를 다치게 하고 온갖 악행을 저지르게 부추겼지. 화서 백성들은 하루도 편할 날이 없어서, 다 같이 돌아가며 신군님께 향을 올리며 도움을 청했어.",
            ["DialogueId"] = 51128218,
            ["GUID"] = "7FFE7F44",
            ["NextDialogue"] = 51128219,
            ["SpeakNpcId"] = 701073,
            },
        [51128219] = {
            ["Content"] = "白龙神君在九天之上，闻到了百姓们点的沉月香，遂勃然大怒。动用神力将之驱逐至华胥海外。",
            ["ContentKR"] = "침월향의 향기는 하늘에 계신 백룡신군께 닿았고, 분노한 신군께선 신통력으로 녀석을 화서 밖으로 쫓아내셨지.",
            ["DialogueId"] = 51128219,
            ["GUID"] = "7FFE7F6E",
            ["NextDialogue"] = 51128220,
            ["SpeakNpcId"] = 701073,
            },
        [51128220] = {
            ["Content"] = "悬衡派仙人们齐心协力，以锁龙环将烛阴层层束缚在仙山之上，才让华胥重回安宁与祥和之中。",
            ["ContentKR"] = "그리고 현형파의 신선들이 힘을 합쳐, 사슬로 촉룡을 신선들의 산에 칭칭 묶어 두고 나서야 화서는 다시 평화를 되찾을 수 있었어.",
            ["DialogueId"] = 51128220,
            ["GUID"] = "7FFE7F98",
            ["NextOptions"] = {
                [1] = 51128223,
                },
            ["SpeakNpcId"] = 701073,
            },
        [51128221] = {
            ["Content"] = "好，给我一支。",
            ["ContentKR"] = "좋아, 나도 하나 줘.",
            ["DialogueId"] = 51128221,
            ["GUID"] = "7FFE7FC2",
            ["NextDialogue"] = 51128222,
            },
        [51128222] = {
            ["Content"] = "（你陪着他一起奉了根香。）",
            ["ContentKR"] = "(남자와 함께 향을 피운다.)",
            ["DialogueId"] = 51128222,
            ["GUID"] = "7FFE7FEC",
            ["NextOptions"] = {
                [1] = 51128223,
                },
            },
        [51128223] = {
            ["Content"] = "所以你是想来复刻神话里的奉香行为，呼唤白龙神君？",
            ["ContentKR"] = "그러니까 넌 신화에 나온 대로 향을 피워서 백룡신군을 부르겠다는 거네?",
            ["DialogueId"] = 51128223,
            ["GUID"] = "7FFE8016",
            ["NextDialogue"] = 51128224,
            },
        [51128224] = {
            ["Content"] = "正是如此！我想着，定是现在大家整日都在奉香，白龙神君闻到哪哪都是香味，不知该帮哪里了。不如我来这无人之境奉香，神君一定会很好奇。",
            ["ContentKR"] = "바로 그거야! 요즘은 다들 여기저기서 종일 향을 피우니까, 어디서 도움을 요청하는지 모르실 수도 있잖아. 이렇게 아무도 없는 데서 향을 올리면, 엄청 궁금해하실 거야.",
            ["DialogueId"] = 51128224,
            ["GUID"] = "7FFE8040",
            ["NextDialogue"] = 51128225,
            ["SpeakNpcId"] = 701073,
            },
        [51128225] = {
            ["Content"] = "好奇什么？",
            ["ContentKR"] = "뭘 말이야?",
            ["DialogueId"] = 51128225,
            ["GUID"] = "7FFE806A",
            ["NextDialogue"] = 51128226,
            ["SpeakNpcId"] = 100001,
            },
        [51128226] = {
            ["Content"] = "好奇为何这人烟稀少之地会有香气啊！足见我心诚之滔滔！",
            ["ContentKR"] = "왜 사람 하나 없는 곳에서 향냄새가 날까?' 말이야! 내 이 지극한 정성에 감동하실걸!",
            ["DialogueId"] = 51128226,
            ["GUID"] = "7FFE8094",
            ["NextDialogue"] = 51128227,
            ["SpeakNpcId"] = 701073,
            },
        [51128227] = {
            ["Content"] = "……",
            ["ContentKR"] = "......",
            ["DialogueId"] = 51128227,
            ["GUID"] = "7FFE80BE",
            ["NextDialogue"] = 51128228,
            ["SpeakNpcId"] = 100001,
            },
        [51128228] = {
            ["Content"] = "好啦，不多说了，你要跟我一起来奉吗？",
            ["ContentKR"] = "자, 설명 끝. 나랑 같이 향 피울래?",
            ["DialogueId"] = 51128228,
            ["GUID"] = "7FFE80E8",
            ["NextOptions"] = {
                [1] = 51128229,
                [2] = 51128231,
                },
            ["SpeakNpcId"] = 701073,
            },
        [51128229] = {
            ["Content"] = "可以。",
            ["ContentKR"] = "좋아.",
            ["DialogueId"] = 51128229,
            ["GUID"] = "7FFE8112",
            ["NextDialogue"] = 51128230,
            },
        [51128230] = {
            ["Content"] = "来！今日我等一起奉香，明日你我皆是挚友！",
            ["ContentKR"] = "자! 같이 향 피우고 기도했으니까, 내일부터 우린 둘도 없는 친구야!",
            ["DialogueId"] = 51128230,
            ["GUID"] = "7FFE813C",
            ["SpeakNpcId"] = 701073,
            },
        [51128231] = {
            ["Content"] = "算了吧。",
            ["ContentKR"] = "사양할게.",
            ["DialogueId"] = 51128231,
            ["GUID"] = "7FFE8166",
            ["NextDialogue"] = 51128232,
            },
        [51128232] = {
            ["Content"] = "那好吧，你们外国人是不懂我们这些讲究的。",
            ["ContentKR"] = "할 수 없지, 뭐. 아무래도 외국 사람은 이해가 잘 안될 테니까.",
            ["DialogueId"] = 51128232,
            ["GUID"] = "7FFE8190",
            ["SpeakNpcId"] = 701073,
            },
        [51128233] = {
            ["Content"] = "有别的事，我先走了。",
            ["ContentKR"] = "다른 일이 있어서, 난 이만 가 볼게.",
            ["DialogueId"] = 51128233,
            ["GUID"] = "7FFE81BA",
            ["NextDialogue"] = 51128234,
            },
        [51128234] = {
            ["Content"] = "哦哦，那好吧！有缘再会！",
            ["ContentKR"] = "앗, 그렇다면 할 수 없지! 인연이 있으면 또 보자!",
            ["DialogueId"] = 51128234,
            ["GUID"] = "7FFE81E4",
            ["SpeakNpcId"] = 701073,
            },
        [51128301] = {
            ["Content"] = "（不知何人立的碑，碑上的字是……）",
            ["ContentKR"] = "(누가 세웠는지 모를 비석 위에 글자들이 새겨져 있다...)",
            ["DialogueId"] = 51128301,
            ["GUID"] = "7FFE8CE2",
            ["NextDialogue"] = 51128302,
            },
        [51128302] = {
            ["DialogueId"] = 51128302,
            ["DialoguePanelType"] = "{type:showtext;topic:SCEREAD_NAME_1000001;content:SCEREAD_TEXT_1000001}",
            ["GUID"] = "7FFE8D0C",
            },
        [51128401] = {
            ["Content"] = "（石碑上刻着密密麻麻的铭文，似是对一些人的纪念。）",
            ["ContentKR"] = "(비석 위에 사람들을 기리는 글귀가 빽빽이 새겨져 있다.)",
            ["DialogueId"] = 51128401,
            ["GUID"] = "7FFE9D4A",
            ["NextDialogue"] = 51128402,
            },
        [51128402] = {
            ["DialogueId"] = 51128402,
            ["DialoguePanelType"] = "{type:showtext;topic:SCEREAD_NAME_1000002;content:SCEREAD_TEXT_1000002}",
            ["GUID"] = "7FFE9D74",
            },
        [51140001] = {
            ["Camera"] = "-113.539062,61.592773,195.840332,0.000114,-25.089722,-48.41589,35.000008,218.514374,false,Manual,1.894586",
            ["Content"] = "不知道为什么……每次走在幽明涧，总觉得身后有阵阵凉风，冷飕飕地往我的领口里钻……",
            ["ContentKR"] = "왤까... 이 유명 계곡을 지날 때면, 옷 속으로 바람이 슝슝 들어오는 것 같고, 등 뒤가 왠지 서늘해...",
            ["DialogueId"] = 51140001,
            ["GUID"] = "80060C6A",
            ["LookAt"] = {
                [1] = "100001:n(200002)",
                [2] = "200002:n(100001)",
                },
            ["Scripts"] = "SetVisibility{ActorId{701074},Visibility{\"Hide\"}}",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Talk03_Start",
                },
            },
        [51140002] = {
            ["Camera"] = "-113.539062,61.592773,195.840332,0.000114,-25.089722,-48.41589,35.000008,218.514374,false,Manual,1.894586",
            ["Content"] = "那种感觉就像是我在水仙平原偷懒，卡米拉从背后阴恻恻地靠过来，然后……",
            ["ContentKR"] = "꼭 아스포델에서 딴짓할 때, 카밀라가 뒤에서 스윽 다가오는 것 같은 그런 느낌이랄까...",
            ["DialogueId"] = 51140002,
            ["GUID"] = "80060C94",
            ["Scripts"] = "SetVisibility{ActorId{701074},Visibility{\"Hide\"}}",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Talk03_End",
                },
            },
        [51140003] = {
            ["Camera"] = "121.967773,-57.251953,229.506348,0.000098,-10.894431,176.76123,35.0,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "敢问二位……",
            ["ContentKR"] = "실례합니다...",
            ["DialogueId"] = 51140003,
            ["FinalCamera"] = "-25.474121,-45.555664,158.86438,0.000091,5.70566,175.16095,35.000008,100000.0,false,DoNotOverride,7.0",
            ["GUID"] = "80060CBE",
            ["Scripts"] = "SetVisibility{ActorId{701074},Visibility{\"Show\"}}",
            ["SpeakNpcId"] = 701074,
            ["SpeakNpcName"] = "UI_NPC_Name_mosheng_Sce",
            ["TalkActionId"] = {
                [1] = "701074:Wuyou_Born",
                },
            ["ToFinalCameraBlendTime"] = 0.2,
            },
        [51140004] = {
            ["Camera"] = "-339.228027,-47.569336,251.475708,0.000101,-29.99987,-4.83933,61.07761,402.688873,false,Manual,7.0",
            ["Content"] = "呜啊！有鬼啊！！！",
            ["ContentKR"] = "끼야아아악! 귀신이다!",
            ["DialogueId"] = 51140004,
            ["GUID"] = "80060CE8",
            ["LookAt"] = {
                [1] = "200002:n(200002)",
                [2] = "100001:n(200002)",
                },
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Afraid_Start",
                [2] = "100001:Talk03_Start",
                },
            },
        [51140005] = {
            ["Camera"] = "-339.228027,-47.569336,251.475708,0.000101,-29.99987,-4.83933,61.07761,402.688873,false,Manual,7.0",
            ["Content"] = "哪哪——哪里来的妖魔鬼怪！胆胆胆敢恐——恐吓本魔王大人！信不信我——玄黄什么什么……糟糕，后面想不起来了！",
            ["ContentKR"] = "뭐, 뭐야 이 귀신 녀석! 가, 가, 감히 이 마왕님을 놀라게 만들다니! 잡귀야 물러가라... 분신사바... 아, 이게 아닌가?",
            ["DialogueId"] = 51140005,
            ["GUID"] = "80060D12",
            ["LookAt"] = {
                [1] = "100001:n(701074)",
                },
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "100001:Talk03_End",
                },
            },
        [51140006] = {
            ["Camera"] = "763.383301,600.294922,831.858032,0.000046,-32.495926,-142.840744,35.000008,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "竟然听得到我说话？太好了！惊扰二位非尾生有意之举，在此向二位致歉，还望海涵。",
            ["ContentKR"] = "제 목소리가 들리시는군요? 다행입니다! 저 때문에 놀라셨다면, 정중히 사과드리겠습니다.",
            ["DialogueId"] = 51140006,
            ["GUID"] = "80060D3C",
            ["SpeakNpcId"] = 701074,
            ["TalkActionId"] = {
                [1] = "200002:Afraid_End",
                },
            },
        [51140007] = {
            ["Camera"] = "-205.567871,-119.201172,110.475708,0.000172,0.0,5.771363,35.000015,187.02475,false,Manual,7.0",
            ["Content"] = "什么嘛，原来是无由生，你怎么突然冒出来，吓了我好一大跳……看在你道歉态度诚恳的份上，魔王大人就原谅你了。",
            ["ContentKR"] = "뭐야, 무유생이었네. 갑자기 튀어나와서 놀랐잖아... 뭐, 진심으로 사과했으니까, 이 마왕님이 특별히 봐줄게.",
            ["DialogueId"] = 51140007,
            ["GUID"] = "80060D66",
            ["Scripts"] = "SEQ\
{\
PARA{\
PlayAnimation{ActorId{200002},AnimationId{\"Alright_Start\"},Duration{1}},\
PlayFacial{ActorId{200002},FacialId{\"Unhappy02\"}}\
},\
PARA{\
PlayAnimation{ActorId{200002},AnimationId{\"Alright_End\"}},\
PlayFacial{ActorId{200002},FacialId{\"None\"}}\
}\
}",
            ["SpeakNpcId"] = 200002,
            },
        [51140008] = {
            ["Camera"] = "333.445312,-77.007812,119.176392,0.000049,3.105147,176.364456,35.0,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "多谢二位大人不计小人过。在下拦路却是另有隐情，实不相瞒，在下有一要事……",
            ["ContentKR"] = "정말 감사합니다. 그런데 제가 이렇게 불쑥 튀어나온 건, 다름이 아니라 두 분께 부탁드릴 게...",
            ["DialogueId"] = 51140008,
            ["GUID"] = "80060D90",
            ["LookAt"] = {
                [1] = "100001:n(100001)",
                },
            ["SpeakNpcId"] = 701074,
            },
        [51140009] = {
            ["Content"] = "（敏锐察觉到一丝不对劲，脚步偷偷向后挪了挪。）",
            ["ContentKR"] = "(불길한 낌새에 몸이 저절로 뒷걸음질 쳐진다.)",
            ["DialogueId"] = 51140009,
            ["GUID"] = "80060DBA",
            ["ImprPlusId"] = 1208,
            },
        [51140010] = {
            ["Content"] = "要我跑腿是吧？打扰了这就走！",
            ["ContentKR"] = "나한테 심부름시키려는 거잖아? 미안하지만, 난 갈게!",
            ["DialogueId"] = 51140010,
            ["GUID"] = "80060DE4",
            ["ImprPlusId"] = 1206,
            },
        [51140011] = {
            ["Camera"] = "-455.513672,-227.362305,283.345703,0.000077,-20.494774,26.363897,35.0,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "是委托的气息！小仆从！准备——诶？你怎么一副要逃跑的样子？！",
            ["ContentKR"] = "의뢰의 냄새가 나는데! 시종! 바로 준비... 뭐야? 왜 도망가는 거야?!",
            ["DialogueId"] = 51140011,
            ["GUID"] = "80060E0E",
            ["LookAt"] = {
                [1] = "200002:n(100001)",
                [2] = "100001:n(200002)",
                },
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{100001},AnimationId{\"Shock02_Start\"},Duration{1}},\
PlayAnimation{ActorId{200002},AnimationId{\"Angry01_Start\"}}\
}",
            ["SpeakNpcId"] = 200002,
            },
        [51140012] = {
            ["Content"] = "（你正想离开，却觉得好像有什么轻飘飘的东西靠近了你，然后……）",
            ["ContentKR"] = "(자리를 뜨려던 순간, 하늘하늘한 무언가가 스윽 다가오더니...)",
            ["DialogueId"] = 51140012,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["GUID"] = "80060E38",
            ["IsBlack"] = 1,
            ["LookAt"] = {
                [1] = "200002:n(701074);100001:n(100001)",
                },
            ["SpeakNpcId"] = 0,
            },
        [51140013] = {
            ["Content"] = "（尾生蹦到了你的脚边。）",
            ["ContentKR"] = "(우직생이 내 바짓가랑이를 잡는다.)",
            ["DialogueId"] = 51140013,
            ["GUID"] = "80060E62",
            ["IsBlack"] = 1,
            ["SpeakNpcId"] = 0,
            },
        [51140014] = {
            ["Camera"] = "29.751953,-50.233398,225.475708,0.000091,-14.99999,175.16095,35.000011,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "在下只希望二位能<H>帮我寻找爱妻闲书下落</>，若是你不帮我，我就……我就一直跟着你，直到你答应为止！",
            ["ContentKR"] = "제발 <H>제 아내 처현의 행방</>을 알아내 주세요! 싫다고 하시면, 도와주신다고 할 때까지... 조, 졸졸 따라다닐 겁니다!",
            ["DialogueId"] = 51140014,
            ["GUID"] = "80060E8C",
            ["SpeakNpcId"] = 701074,
            ["TalkActionId"] = {
                [1] = "100001:Shock02_End",
                },
            },
        [51140015] = {
            ["Camera"] = "-194.939453,-70.49707,155.490723,0.000079,-19.495415,-7.838241,35.000011,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "你——你这家伙耍赖！",
            ["ContentKR"] = "이, 이거 완전 떼쟁이네!",
            ["DialogueId"] = 51140015,
            ["FacialId"] = {
                [1] = "200002:Angry01",
                },
            ["GUID"] = "80060EB6",
            ["LookAt"] = {
                [1] = "200002:n(200002)",
                [2] = "100001:n(100001)",
                },
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Angry01_Start",
                },
            },
        [51140016] = {
            ["Camera"] = "11.114258,106.112305,84.475708,0.000119,19.999981,-140.838303,64.81044,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "他们都看不到听不到我，你们是第一个回应我说话的。我晓得你们比旁人特殊，只有你们才能帮我！",
            ["ContentKR"] = "사람들은 절 보지도 듣지도 못 합니다. 제 말에 대꾸해 주신 건 두 분이 처음이에요. 두 분이 아니면, 제가 도와달라고 할 사람이 없어요!",
            ["DialogueId"] = 51140016,
            ["GUID"] = "80060EE0",
            ["SpeakNpcId"] = 701074,
            ["TalkActionId"] = {
                [1] = "200002:Angry01_End",
                },
            },
        [51140017] = {
            ["Camera"] = "-243.208984,-3.944336,191.368408,-0.0,-15.293783,-3.434053,35.000015,266.740662,false,Manual,7.0",
            ["Content"] = "……你说说看吧。",
            ["ContentKR"] = "...일단 무슨 일인지 얘기해 보세요.",
            ["DialogueId"] = 51140017,
            ["FacialId"] = {
                [1] = "100001:Uninterested01",
                },
            ["GUID"] = "80060F0A",
            ["LookAt"] = {
                [1] = "100001:n(701074)",
                },
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:ConfidentLR_Start",
                },
            },
        [51140018] = {
            ["Camera"] = "333.445312,-77.007812,119.176392,0.000049,3.105147,176.364456,35.0,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "真……真的吗？你，你愿意帮我找我妻子了？",
            ["ContentKR"] = "저, 정말 들어 주시는 겁니까? 제 아, 아내를 찾아 주시는 건가요?",
            ["DialogueId"] = 51140018,
            ["GUID"] = "80060F34",
            ["SpeakNpcId"] = 701074,
            },
        [51140019] = {
            ["Camera"] = "29.751953,-50.233398,225.475708,0.000091,-14.99999,175.16095,35.000011,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "好，好的！事情是这样的。我生前住蒹葭浦附近，靠做些小买卖维持生计，虽没赚到什么大钱，但日子过得倒也舒坦。",
            ["ContentKR"] = "아, 알겠습니다. 그게, 저는 살아생전에 갈대늪 근처에 살았습니다. 조그맣게 장사를 했었는데, 벌이가 좋지는 않아도 마음만은 참 편했죠.",
            ["DialogueId"] = 51140019,
            ["GUID"] = "80060F5E",
            ["SpeakNpcId"] = 701074,
            },
        [51140020] = {
            ["Camera"] = "29.751953,-50.233398,225.475708,0.000091,-14.99999,175.16095,35.000011,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "本以为一生就这样平平淡淡过去了，直到我认识了爱妻闲书，我与她情投意合，很快便成了婚，婚后更是如胶似漆，伉俪情深……",
            ["ContentKR"] = "평생 그렇게 평범하게 살다 갈 줄 알았는데, 제 아내를 만났습니다. 저희는 첫눈에 반해 혼례를 올렸고, 한시도 떨어지지 않을 만큼 깨가 쏟아졌는데...",
            ["DialogueId"] = 51140020,
            ["GUID"] = "80060F88",
            ["SpeakNpcId"] = 701074,
            },
        [51140021] = {
            ["Camera"] = "-125.262207,40.953125,171.12085,0.000126,-15.293818,-18.234081,35.000015,117.407356,false,Manual,3.0",
            ["Content"] = "说重点。",
            ["ContentKR"] = "요점만 간단히요.",
            ["DialogueId"] = 51140021,
            ["FacialId"] = {
                [1] = "100001:Uninterested01",
                },
            ["GUID"] = "80060FB2",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:ConfidentLRToExplainL_Start",
                },
            },
        [51140022] = {
            ["Camera"] = "121.967773,-57.251953,229.506348,0.000098,-10.894431,176.76123,35.0,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "是是！只可惜天有不测风云，闲书不知为何得了一种怪病，痛苦异常。我便去求助枯荣阁里的药师为其治疗，药师为我开了些药剂。",
            ["ContentKR"] = "넵! 그런데 하늘도 무심하시지, 아내가 이상한 병에 걸린 겁니다! 몹시 고통스러워했죠. 그래서 제가 고영각에 찾아가, 약사님께 약을 받아 왔고요.",
            ["DialogueId"] = 51140022,
            ["FinalCamera"] = "25.034668,-51.429688,210.820923,0.000096,-10.894411,176.561234,35.000008,100000.0,false,DoNotOverride,7.0",
            ["GUID"] = "80060FDC",
            ["SpeakNpcId"] = 701074,
            ["ToFinalCameraBlendTime"] = 5,
            },
        [51140023] = {
            ["Content"] = "那日后，我日日为她煎药试药，悉心照料，依旧不见好转，我便想着将她带去皓京问问有没有更好的药师治疗，谁知道……她一直不同意。",
            ["ContentKR"] = "전 아내에게 매일 약을 달여 먹였습니다. 의원님 말씀대로 매번 미리 맛도 봤고요. 그런데 정성껏 간호해도 차도가 없길래, 호경에 있는 더 용한 의원한테 가 보자고 했는데... 한사코 싫다지 뭡니까.",
            ["DialogueId"] = 51140023,
            ["GUID"] = "80061006",
            ["SpeakNpcId"] = 701074,
            ["TalkActionId"] = {
                [1] = "100001:ConfidentLRToExplainL_End",
                },
            },
        [51140024] = {
            ["Content"] = "她失踪那日，我终于耐不住性子，第一次凶了她……我直至今日都在后悔。",
            ["ContentKR"] = "아내가 실종된 그날, 전 참다못해 처음으로 아내에게 화를 냈습니다... 지금까지도 후회하고 있어요.",
            ["DialogueId"] = 51140024,
            ["GUID"] = "80061030",
            ["SpeakNpcId"] = 701074,
            },
        [51140025] = {
            ["Camera"] = "11.114258,106.112305,84.475708,0.000119,19.999981,-140.838303,64.81044,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "我那天好说歹说，她终于点头愿意随我去看病。我便去铺子上拜托伙计看摊，和闲书约好晚上直接在码头见面，不耽误出发时间。",
            ["ContentKR"] = "아내는 제 성화에 못 이겨 호경에 가겠다고 했죠. 전 가게에 돌아가서 점원에게 며칠 가게일을 부탁했고요. 아내하곤 밤에 나루터에서 만나 곧바로 배를 타고 떠나기로 했습니다.",
            ["DialogueId"] = 51140025,
            ["GUID"] = "8006105A",
            ["SpeakNpcId"] = 701074,
            },
        [51140026] = {
            ["Camera"] = "11.114258,106.112305,84.475708,0.000119,19.999981,-140.838303,64.81044,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "可谁知道……我在码头等到天亮，却根本没等到她！",
            ["ContentKR"] = "그런데 어찌 된 영문인지... 나루터에서 밤새 기다려도 아내가 오지를 않는 겁니다!",
            ["DialogueId"] = 51140026,
            ["GUID"] = "80061084",
            ["SpeakNpcId"] = 701074,
            },
        [51140027] = {
            ["Camera"] = "-175.286621,11.260742,161.297852,0.000068,-19.495415,-35.038132,35.000008,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "等一下等一下？她会不会是因为生病倒在家里了？",
            ["ContentKR"] = "뭐? 잠깐만, 혹시 상태가 확 나빠져서 집에 쓰러져 있던 거 아냐?",
            ["DialogueId"] = 51140027,
            ["GUID"] = "800610AE",
            ["LookAt"] = {
                [1] = "100001:n(200002)",
                },
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "100001:ConfidentLR_End",
                [2] = "200002:Think_Start",
                },
            },
        [51140028] = {
            ["Camera"] = "-25.474121,-45.555664,158.86438,0.000091,5.70566,175.16095,35.000008,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "家中自然是看过了，但却没有找到一丝闲书的痕迹，她好像就这样，突然轻轻地挥一挥袖，从我的世界里消失了……",
            ["ContentKR"] = "당연히 집에 가 봤지만, 아내는 흔적조차 없었습니다. 아내라는 존재가, 마치 제가 사는 세상에서 증발해 버린 것처럼요...",
            ["DialogueId"] = 51140028,
            ["GUID"] = "800610D8",
            ["SpeakNpcId"] = 701074,
            },
        [51140029] = {
            ["Camera"] = "-25.474121,-45.555664,158.86438,0.000091,5.70566,175.16095,35.000008,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "我怕她是否会有一日归来，便一直在码头等她。那日下了很大的雨，浮星埠水位上涨，我却担心她要是此时回来找不到我，于是我便执意不走。",
            ["ContentKR"] = "혹시 늦게라도 와 줄까 싶어서, 계속 나루터에서 기다렸는데, 그날따라 쏟아진 폭우에 별빛 부두의 물이 계속 불어났습니다. 하지만 길이 엇갈릴까 봐, 발이 떨어지지 않더군요.",
            ["DialogueId"] = 51140029,
            ["GUID"] = "80061102",
            ["SpeakNpcId"] = 701074,
            },
        [51140030] = {
            ["Camera"] = "-205.567871,-119.201172,110.475708,0.000172,0.0,5.771363,35.000015,187.02475,false,Manual,7.0",
            ["Content"] = "为什么不去找地方避雨呢？你就傻傻等着吗？",
            ["ContentKR"] = "비를 피하지도 않고, 계속 거기서 기다리고 있었다는 거야?",
            ["DialogueId"] = 51140030,
            ["FacialId"] = {
                [1] = "200002:Shock01",
                },
            ["GUID"] = "8006112C",
            ["LookAt"] = {
                [1] = "200002:n(701074)",
                },
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Think_End",
                },
            },
        [51140031] = {
            ["Camera"] = "333.445312,-77.007812,119.176392,0.000049,3.105147,176.364456,35.0,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "那日洪水暴涨，我只能抓住一切随手能见着的东西……人力终不能胜天，我被水卷走，死不见全尸，幸而化作无由之身，游荡于此。",
            ["ContentKR"] = "물은 계속 불어났고, 전 아무거나 붙잡고 버텨 봤지만... 결국 물살에 휩쓸려 떠내려가고 말았습니다. 그렇게 무유생이 되어 여길 떠돌게 된 겁니다.",
            ["DialogueId"] = 51140031,
            ["GUID"] = "80061156",
            ["SpeakNpcId"] = 701074,
            },
        [51140032] = {
            ["Camera"] = "-272.66748,181.339844,236.877319,0.000052,-19.999928,-51.83622,27.780128,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "你……你……诶……真是个笨蛋啊！",
            ["ContentKR"] = "너... 이... 우으... 바보 멍청아!",
            ["DialogueId"] = 51140032,
            ["FacialId"] = {
                [1] = "200002:Sad03",
                },
            ["GUID"] = "80061180",
            ["LookAt"] = {
                [1] = "200002:n(701074)",
                [2] = "100001:n(200002)",
                },
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Sigh_Start",
                },
            },
        [51140033] = {
            ["Camera"] = "333.445312,-77.007812,119.176392,0.000049,3.105147,176.364456,35.0,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "鸿毛之命，此时不必再提及，我只求二位帮忙，去扶氏<H>枯荣阁</>那里帮我问问闲书的踪迹。",
            ["ContentKR"] = "제 목숨 같은 게 이제 와서 뭐가 중요하겠습니까. 다만, 두 분께서 부씨 가문의 <H>고영각</>에 가서 아내의 행방을 알아봐 주십시오.",
            ["DialogueId"] = 51140033,
            ["GUID"] = "800611AA",
            ["SpeakNpcId"] = 701074,
            },
        [51140034] = {
            ["Camera"] = "333.445312,-77.007812,119.176392,0.000049,3.105147,176.364456,35.0,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "我妻子那病需要以药吊命，要是她回来了，想必第一时间一定会去找那里的药师开药的。",
            ["ContentKR"] = "아내는 병에 걸려 약으로 목숨을 연명하고 있었으니, 돌아왔다면 약을 타러 약사님을 찾아갔을 게 틀림없습니다.",
            ["DialogueId"] = 51140034,
            ["GUID"] = "800611D4",
            ["SpeakNpcId"] = 701074,
            },
        [51140035] = {
            ["Camera"] = "-174.360352,-43.571289,181.889648,0.000123,-15.293852,16.366138,35.000011,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "知道了，我会帮你去问问，但结果如何我不能保证。",
            ["ContentKR"] = "알겠어요. 가서 물어는 보겠지만, 결과는 장담 못 해요.",
            ["DialogueId"] = 51140035,
            ["FacialId"] = {
                [1] = "100001:Smile01",
                },
            ["GUID"] = "800611FE",
            ["LookAt"] = {
                [1] = "100001:n(701074)",
                },
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk02R_Start",
                },
            },
        [51140036] = {
            ["Camera"] = "-25.474121,-45.555664,158.86438,0.000091,5.70566,175.16095,35.000008,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "大恩大德，尾生来世必报！",
            ["ContentKR"] = "정말 감사합니다! 이 은혜는 다음 생에라도 반드시 갚겠습니다!",
            ["DialogueId"] = 51140036,
            ["GUID"] = "80061228",
            ["SpeakNpcId"] = 701074,
            ["TalkActionId"] = {
                [1] = "701074:Wuyou_Disappear",
                },
            },
        [51140037] = {
            ["Camera"] = "-287.652344,948.660156,170.522461,0.000065,-3.551971,-72.129524,35.0,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "（扶疏正痴痴望着一个方向发呆，连鱼龙也显得垂头丧气。）",
            ["ContentKR"] = "(부소가 얼이 빠진 사람처럼 어딘가를 멍하니 바라본다. 어룡마저 풀이 죽어 있다.)",
            ["DialogueId"] = 51140037,
            ["FinalCamera"] = "-170.042969,583.894531,146.733398,0.000065,-3.551971,-72.129524,35.0,100000.0,false,DoNotOverride,7.0",
            ["GUID"] = "80061252",
            ["Scripts"] = "PARA{\
MoveTo{ActorId{100001},MoveSpeed{100},TargetPoint{\"Targetpoint_20030901\"},Visibility{\"Show\"}},\
MoveTo{ActorId{200002},MoveSpeed{100},TargetPoint{\"Targetpoint_20030902\"},Visibility{\"Show\"}}\
}",
            ["SpeakNpcId"] = 0,
            ["TalkActionId"] = {
                [1] = "701075:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 4,
            },
        [51140038] = {
            ["Content"] = "是有什么心事吗？",
            ["ContentKR"] = "무슨 걱정거리라도 있는 거야?",
            ["DialogueId"] = 51140038,
            ["GUID"] = "8006127C",
            ["ImprPlusId"] = 1209,
            },
        [51140039] = {
            ["Content"] = "（等她发现自己。）",
            ["ContentKR"] = "(부소가 알아차릴 때까지 기다린다.)",
            ["DialogueId"] = 51140039,
            ["GUID"] = "800612A6",
            ["ImprPlusId"] = 1207,
            },
        [51140040] = {
            ["Camera"] = "-170.042969,583.894531,146.733398,0.000065,-3.551971,-72.129524,35.0,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "唔，{nickname}，是你……怎么得空来了枯荣阁，温习时想起一些往事，不免失神，让你见笑了。",
            ["ContentKR"] = "아, {nickname}, 당신이었군요... 책을 읽다가 옛날 생각이 났어요. 신경 쓰지 말아요. 그나저나 고영각엔 무슨 일인가요?",
            ["DialogueId"] = 51140040,
            ["GUID"] = "800612D0",
            ["LookAt"] = {
                [1] = "701075:n(100001)",
                },
            ["SpeakNpcId"] = 701075,
            ["TalkActionId"] = {
                [1] = "701075:Think_End",
                },
            ["TurnTo"] = {
                [1] = "701075:n(100001)",
                },
            },
        [51140041] = {
            ["Camera"] = "-170.042969,583.894531,146.733398,0.000065,-3.551971,-72.129524,35.0,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "唔，{nickname}，是你……怎么得空来了枯荣阁，温书入迷一时失神，居然没注意到你进来。",
            ["ContentKR"] = "아, {nickname}, 당신이었군요... 책을 읽는 데 정신이 팔려서 온 줄도 몰랐네요. 그나저나 고영각엔 무슨 일인가요?",
            ["DialogueId"] = 51140041,
            ["GUID"] = "800612FA",
            ["LookAt"] = {
                [1] = "701075:n(100001)",
                },
            ["SpeakNpcId"] = 701075,
            ["TalkActionId"] = {
                [1] = "701075:Think_End",
                },
            ["TurnTo"] = {
                [1] = "701075:n(100001)",
                },
            },
        [51140042] = {
            ["Camera"] = "-24.294922,12.818359,82.566406,0.000001,0.0,-178.519165,18.36294,75.471931,false,Manual,2.8",
            ["Content"] = "我都要把这里的诊籍都翻遍了，不是发烧感冒就是胃痛腹泻，怎么也和尾生说的那种情况对不上呀。",
            ["ContentKR"] = "여기 있는 건 싹 다 뒤져 봤는데, 죄다 감기나 배탈이고, 우직생이 말한 그런 병을 앓던 사람은 없어.",
            ["DialogueId"] = 51140042,
            ["GUID"] = "80061324",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Alright_Start",
                },
            },
        [51140043] = {
            ["Camera"] = "147.988281,-372.753906,263.493164,0.000021,-23.151232,113.072533,76.142418,493.532471,false,Manual,3.0",
            ["Content"] = "扶疏扶疏，我们这次来是有一件奇怪的事情要问你呢！",
            ["ContentKR"] = "부소 언니! 우리한테 엄청 이상한 일이 생겨서 언니한테 물어보러 온 거야!",
            ["DialogueId"] = 51140043,
            ["FacialId"] = {
                [1] = "200002:Happy01",
                },
            ["GUID"] = "8006134E",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Excited01_Start",
                },
            ["TurnTo"] = {
                [1] = "100001:n(701075)",
                [2] = "701075:n(200002)",
                },
            },
        [51140044] = {
            ["Camera"] = "-74.871094,-49.457031,176.993164,0.000086,-14.999942,-17.730551,35.000015,130.112747,false,Manual,7.0",
            ["Content"] = "是身体不适还是另有心疾，能帮到你的地方，扶疏定然鼎力相助。",
            ["ContentKR"] = "몸이 불편하세요? 아니면 마음에 병이 생긴 건가요? 제가 힘닿는 데까지 도와드릴게요.",
            ["DialogueId"] = 51140044,
            ["FacialId"] = {
                [1] = "701075:Smile01",
                },
            ["GUID"] = "80061378",
            ["SpeakNpcId"] = 701075,
            },
        [51140045] = {
            ["Content"] = "（你向扶疏讲述了一位无由生在寻找生病妻子的事。）",
            ["ContentKR"] = "(당신은 부소에게 병에 걸린 아내를 찾고 있는 무유생의 사연을 이야기해 준다.)",
            ["DialogueId"] = 51140045,
            ["GUID"] = "800613A2",
            ["IsBlack"] = 1,
            ["SpeakNpcId"] = 0,
            ["TurnTo"] = {
                [1] = "701075:n(100001)",
                },
            },
        [51140046] = {
            ["Camera"] = "30.617188,116.332031,137.268555,0.000109,-3.549711,-71.720947,19.814159,203.327576,false,Manual,5.20548",
            ["Content"] = "大抵是家姐生前收治过的病人。据记载，烟津渡上次洪灾致人溺亡已是九十余年前……",
            ["ContentKR"] = "언니가 살아 있을 때 돌봤던 환자분 같네요. 기록을 보면, 연진 나루터에 홍수가 나서 사람이 죽은 건 90년 도 더 된 일이거든요...",
            ["DialogueId"] = 51140046,
            ["GUID"] = "800613CC",
            ["SpeakNpcId"] = 701075,
            ["TalkActionId"] = {
                [1] = "701075:Explain01_Start",
                [2] = "200002:Excited01_End",
                },
            },
        [51140047] = {
            ["Camera"] = "30.617188,116.332031,137.268555,0.000109,-3.549711,-71.720947,19.814159,203.327576,false,Manual,5.20548",
            ["Content"] = "那时家姐年纪尚轻，尚未自立门户，还在枯荣阁坐诊。",
            ["ContentKR"] = "그땐 언니도 나이가 어려서, 독립하지 않고 고영각에서 진료를 봤었고요.",
            ["DialogueId"] = 51140047,
            ["GUID"] = "800613F6",
            ["SpeakNpcId"] = 701075,
            ["TalkActionId"] = {
                [1] = "701075:Explain01_End",
                },
            },
        [51140048] = {
            ["Camera"] = "171.115234,-119.117188,100.751953,0.000108,-4.999999,154.070587,35.000008,300.780701,false,Manual,5.20548",
            ["Content"] = "那个尾生竟然已经死了九十多年了吗！",
            ["ContentKR"] = "그럼 그 우직생이란 녀석은 죽은 지 벌써 90년이 넘었단 거네!",
            ["DialogueId"] = 51140048,
            ["FacialId"] = {
                [1] = "200002:Shock01",
                },
            ["GUID"] = "80061420",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Shock03_Start",
                },
            },
        [51140049] = {
            ["Camera"] = "-170.042969,583.894531,146.733398,0.000065,-3.551971,-72.129524,35.0,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "没错，他的妻子如今还活着的希望已是渺茫。",
            ["ContentKR"] = "네, 그러니 아내분이 지금까지 살아 계실 가능성은 희박해요.",
            ["DialogueId"] = 51140049,
            ["FacialId"] = {
                [1] = "701075:Think01",
                },
            ["GUID"] = "8006144A",
            ["SpeakNpcId"] = 701075,
            ["TalkActionId"] = {
                [1] = "701075:Think_Start",
                },
            },
        [51140050] = {
            ["Camera"] = "-170.042969,583.894531,146.733398,0.000065,-3.551971,-72.129524,35.0,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "但如此痴情之人，帮他寻得当年妻子下落，权当圆他一个念想，让他得以了却执念，回归往生也好。",
            ["ContentKR"] = "하지만 그렇게 간절하시다면, 미련을 내려놓고 이 세상을 떠나실 수 있게, 행방을 알아봐 드리는 것도 나쁘진 않겠군요.",
            ["DialogueId"] = 51140050,
            ["GUID"] = "80061474",
            ["SpeakNpcId"] = 701075,
            ["TalkActionId"] = {
                [1] = "200002:Shock03_End",
                },
            },
        [51140051] = {
            ["Camera"] = "-113.632812,-83.152344,198.851562,0.00007,-17.949545,-0.526916,35.000011,645.22876,false,DoNotOverride,7.0",
            ["Content"] = "家姐历年行医都有诊籍留档，{nickname}，我随你去阁中找找。",
            ["ContentKR"] = "언니는 모든 진료 기록을 남겨 뒀어요. 같이 가서 찾아보죠, {nickname} 씨.",
            ["DialogueId"] = 51140051,
            ["FacialId"] = {
                [1] = "701075:None",
                },
            ["GUID"] = "8006149E",
            ["SpeakNpcId"] = 701075,
            ["TalkActionId"] = {
                [1] = "701075:Think_End",
                },
            },
        [51140052] = {
            ["Camera"] = "95.519531,110.679688,109.566406,0.000037,0.0,-126.112823,11.880002,248.943176,false,Manual,2.8",
            ["Content"] = "找到诊籍了吗？",
            ["ContentKR"] = "찾으시는 기록은 발견하셨나요?",
            ["DialogueId"] = 51140052,
            ["GUID"] = "800614C8",
            ["Scripts"] = "SEQ{ MoveTo{ActorId{701075},MoveSpeed{150},TargetPoint{\"Targetpoint_20030907\"}}, TurnTo{TurnToDescription{\"701075:n(100001)\"}}\
}",
            ["SpeakNpcId"] = 701075,
            ["TalkActionId"] = {
                [1] = "200002:Alright_End",
                },
            },
        [51140053] = {
            ["Camera"] = "-6.933594,-41.625,141.566406,0.000099,-5.84296,-115.514038,14.773981,58.703678,false,Manual,2.8",
            ["Content"] = "没有，似乎没有对得上的，只有这一篇有些奇怪。",
            ["ContentKR"] = "아니, 딱 맞아떨어지는 건 없네. 그나마 좀 수상해 보이는 건 이거 하나야.",
            ["DialogueId"] = 51140053,
            ["GUID"] = "800614F2",
            ["LookAt"] = {
                [1] = "100001:n(100001)",
                },
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:DisagreeHead",
                },
            },
        [51140054] = {
            ["Content"] = "（你将诊籍递给扶疏，她仔细看了一会儿。）",
            ["ContentKR"] = "(부소가 진료 기록을 받아 들고 꼼꼼히 읽어 내려간다.)",
            ["DialogueId"] = 51140054,
            ["GUID"] = "8006151C",
            ["IsBlack"] = 1,
            ["SpeakNpcId"] = 0,
            },
        [51140055] = {
            ["Camera"] = "-81.537109,-85.851562,132.566406,0.000039,0.0,11.891485,18.482418,157.042984,false,Manual,1.41721",
            ["Content"] = "咦……这里面有个人……我曾在姐姐的日记里见过……",
            ["ContentKR"] = "음... 이 사람이라면... 언니의 일기에서 본 적 있어요...",
            ["DialogueId"] = 51140055,
            ["GUID"] = "80061546",
            ["SpeakNpcId"] = 701075,
            ["TalkActionId"] = {
                [1] = "701075:Think_Start",
                },
            },
        [51140056] = {
            ["Camera"] = "120.662109,32.841797,142.3125,0.000078,-19.999907,-159.908264,22.322252,236.840927,false,Manual,7.0",
            ["Content"] = "日记？你姐姐还写过日记呀？",
            ["ContentKR"] = "일기? 언니가 일기도 썼었어?",
            ["DialogueId"] = 51140056,
            ["GUID"] = "80061570",
            ["LookAt"] = {
                [1] = "100001:n(200002)",
                [2] = "701075:n(200002)",
                },
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Talk01_Start",
                [2] = "701075:Think_End",
                },
            },
        [51140057] = {
            ["Camera"] = "-93.105469,39.958984,123.023438,0.000084,6.0,-18.908363,35.000008,178.587616,false,Manual,7.0",
            ["Content"] = "嗯，姐姐怕我醒了后她不在，我对她不与我重叠的生活毫无了解，便将自己的经历以日记形式记录了下来。",
            ["ContentKR"] = "네. 자기가 세상을 떠난 후에 제가 눈을 뜨면, 그동안 무슨 일이 있었는지 설명해 줄 사람이 없을 테니까, 자기 경험을 일기 형식으로 기록해 뒀대요.",
            ["DialogueId"] = 51140057,
            ["GUID"] = "8006159A",
            ["LookAt"] = {
                [1] = "100001:n(100001)",
                [2] = "701075:n(200002)",
                },
            ["SpeakNpcId"] = 701075,
            ["TalkActionId"] = {
                [1] = "701075:Explain02_Start",
                [2] = "200002:Talk01_End",
                },
            },
        [51140058] = {
            ["Camera"] = "313.945312,521.587891,463.705078,0.000028,-29.999958,-121.712296,35.000008,275.432831,false,DoNotOverride,7.0",
            ["Content"] = "……不好意思，又提到你的伤心事了。",
            ["ContentKR"] = "...슬픈 기억을 떠올리게 해서 미안해.",
            ["DialogueId"] = 51140058,
            ["GUID"] = "800615C4",
            ["LookAt"] = {
                [1] = "701075:n(100001)",
                },
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Give",
                [2] = "701075:Explain02_End",
                },
            },
        [51140059] = {
            ["Camera"] = "-81.537109,-85.851562,132.566406,0.000039,0.0,11.891485,18.482418,157.042984,false,Manual,1.41721",
            ["Content"] = "并无感伤，姐姐想必也是不愿看到我伤怀才如此行事。",
            ["ContentKR"] = "슬프지는 않아요. 언니도 제가 슬퍼하지 않기를 바라서 기록을 남겨 뒀던 걸 거고요.",
            ["DialogueId"] = 51140059,
            ["GUID"] = "800615EE",
            ["SpeakNpcId"] = 701075,
            ["TalkActionId"] = {
                [1] = "701075:Disagree",
                },
            },
        [51140060] = {
            ["Camera"] = "-81.537109,-85.851562,132.566406,0.000039,0.0,11.891485,18.482418,157.042984,false,Manual,1.41721",
            ["Content"] = "姐姐曾在年轻时的日记里提过一名患者，其妻在大疫中不幸殒命，自此患上心病，终日幻想其妻尚存于世，与那个不存在的人对话。",
            ["ContentKR"] = "언니의 젊은 시절 일기에, 역병 때문에 아내를 잃은 환자 이야기가 적혀 있었어요. 그 환자는 마음의 병을 얻었고, 계속 아내가 살아 있다고 믿으며 대화까지 나눴대요.",
            ["DialogueId"] = 51140060,
            ["GUID"] = "80061618",
            ["SpeakNpcId"] = 701075,
            ["TalkActionId"] = {
                [1] = "701075:Talk03_Start",
                },
            },
        [51140061] = {
            ["Camera"] = "-51.0,-35.339844,149.195312,0.000083,1.15922,9.291944,35.000008,116.515465,false,Manual,7.0",
            ["Content"] = "姐姐写道，这让她照见了自己的影子，如同姐姐与沉睡中的我对话一样，有趣却又愚痴。",
            ["ContentKR"] = "언니는 그 환자한테서 잠든 제게 말을 거는 자기 모습이 비쳐 보였대요. 그래서 미련해 보이기도 하고, 우습기도 했다더군요.",
            ["DialogueId"] = 51140061,
            ["GUID"] = "80061642",
            ["LookAt"] = {
                [1] = "100001:n(200002)",
