        [51151061] = {
            ["Camera"] = "501.320312,-108.880371,210.521484,0.000008,-12.845597,152.96994,35.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "哈哈。你们来之前，我早就绕着这房子转了两圈，除了檐角又长了些青苔之外，并无其他异样。等你们准备好了，咱们就进去。",
            ["ContentKR"] = "하하, 너희가 오기 전에 내가 건물 주변을 두 바퀴 둘러봤는데, 처마 끝에 이끼가 좀 낀 거 빼곤 이상한 건 없었어. 준비됐으면 들어가자.",
            ["DialogueId"] = 51151061,
            ["FacialId"] = {
                [1] = "700373:CM_Smile01",
                [2] = "100001:None",
                [3] = "200002:None",
                },
            ["GUID"] = "800D22F2",
            ["LookAt"] = {
                [1] = "700373:n(100001)",
                [2] = "100001:n(700373)",
                [3] = "200002:n(700373)",
                },
            ["NextDialogue"] = 51151062,
            ["SpeakNpcId"] = 700373,
            ["TalkActionId"] = {
                [1] = "200002:Shock03_End",
                },
            },
        [51151062] = {
            ["Content"] = "好，我们走吧。",
            ["ContentKR"] = "그래, 들어가자.",
            ["DialogueId"] = 51151062,
            ["FacialId"] = {
                [1] = "100001:Smile01",
                },
            ["GUID"] = "800D231C",
            ["NextDialogue"] = 51151063,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:AgreeHead",
                [2] = "200002:Confident_Start",
                },
            },
        [51151063] = {
            ["Content"] = "勇气可嘉，不愧是我看中的人，我这就……咦？",
            ["ContentKR"] = "역시 내가 사람 보는 눈이 있어. 배짱이 두둑해서 좋군. 자, 그럼... 어?",
            ["DialogueId"] = 51151063,
            ["GUID"] = "800D2346",
            ["NextDialogue"] = 51151064,
            ["SpeakNpcId"] = 700373,
            ["TalkActionId"] = {
                [1] = "700373:Talk03_End",
                },
            },
        [51151064] = {
            ["Content"] = "等等，我好像……没带开门的钥匙……",
            ["ContentKR"] = "잠깐, 아무래도 나... 열쇠를 안 가져온 모양이야...",
            ["DialogueId"] = 51151064,
            ["FacialId"] = {
