            ["SpeakNpcId"] = 701258,
            },
        [51158710] = {
            ["Content"] = "等咱们店的翠屏雀从码头找回来了，就可以开门了，到时候，记得来玩哦。",
            ["DialogueId"] = 51158710,
            ["GUID"] = "801209DC",
