            ["SpeakNpcId"] = 701258,
            },
        [51158711] = {
            ["Content"] = "东市雀翎茗轩开张，凡携亲眷者入座，皆送花茶一壶。",
            ["DialogueId"] = 51158711,
            ["GUID"] = "80120861",
            ["NextDialogue"] = 51158701,
            ["SpeakNpcId"] = 701258,
            },
        [51158712] = {
            ["Content"] = "薄薄一张纸，其上绘的翠屏雀却是栩栩如生，像是要随时跃出纸张一样……看来绘制者是位画技高超之人。",
            ["DialogueId"] = 51158712,
            ["DialoguePanelType"] = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter_NewsPaper.T_Guide_Chapter_NewsPaper'}",
            },
        [51158801] = {
            ["Content"] = "如今选购好的茶叶一直压在家中，喂雀的饲料也只能放在店内受潮，连给请的伙计开日钱都要开不起了！",
