            ["GUID"] = "80121A44",
            ["NextDialogue"] = 51158811,
            ["SpeakNpcId"] = 701135,
            },
        [51158811] = {
            ["Content"] = "现在是叫天天不灵，叫地地不应，只能祈祷那些送翠屏雀的伙计们负责些，找回来几只便是几只……",
            ["DialogueId"] = 51158811,
            ["GUID"] = "80121A6E",
            ["SpeakNpcId"] = 701135,
            },
        [51158812] = {
