            ["DialogueId"] = 51159921,
            ["GUID"] = "8012D08A",
            ["NextDialogue"] = 51159922,
            },
        [51159922] = {
            ["Content"] = "（你转身的瞬间，似乎看到这孩子的眼角有些湿润。）",
            ["DialogueId"] = 51159922,
            ["GUID"] = "8012D0B4",
