            },
        [51159923] = {
            ["Content"] = "父亲向来放不下娘亲，想必在天上也是不愿看见娘亲落泪的。",
            ["DialogueId"] = 51159923,
            ["GUID"] = "8012CD41",
            ["NextDialogue"] = 51159901,
            ["SpeakNpcId"] = 701148,
            },
        [51160001] = {
            ["ContentKR"] = "여씨 소녀, 12세, 음력 11월 6일 내원.",
            ["DialogueId"] = 51160001,
            ["DialoguePanelType"] = "{type:showtext;topic:READ_NAME_fushuyian01;content:READ_TEXT_fushuyian01}",
            ["GUID"] = "8012DDAA",
            ["OptionTopic"] = "家姐历年行医都有诊籍留档，{nickname}，我随你去阁中找找。",
            },
        [51160002] = {
            ["ContentKR"] = "진씨 여인, 31세, 음력 12월 1일 내원.",
            ["DialogueId"] = 51160002,
            ["DialoguePanelType"] = "{type:showtext;topic:READ_NAME_fushuyian02;content:READ_TEXT_fushuyian02}",
            ["GUID"] = "8012DDD4",
            },
        [51160003] = {
            ["ContentKR"] = "유씨 남자, 40세, 3월 내원.",
            ["DialogueId"] = 51160003,
            ["DialoguePanelType"] = "{type:showtext;topic:READ_NAME_fushuyian03;content:READ_TEXT_fushuyian03}",
            ["GUID"] = "8012DDFE",
            },
        [51160004] = {
            ["Content"] = "是这个刘姓女吗？可这是一个贪玩冻感冒了的小女孩，怎么看也和尾生的妻子不搭边。",
            ["ContentKR"] = "이건 아무리 봐도 우직생의 아내는 아니야. 그냥 눈밭에서 놀다가 감기 걸린 애잖아.",
            ["DialogueId"] = 51160004,
            ["GUID"] = "8012DE28",
            ["SpeakNpcId"] = 100001,
            },
        [51160005] = {
            ["Content"] = "难道是陈姓女？性别和年龄倒是对的上，但怎么看也只是眼睛不舒服的小病诶……",
            ["ContentKR"] = "성별이랑 나이는 비슷하지만, 그냥 눈이 좀 침침한 거지 심각한 병은 아닌 거 같은데...",
            ["DialogueId"] = 51160005,
            ["GUID"] = "8012DE52",
            ["SpeakNpcId"] = 200002,
            },
        [51160006] = {
            ["Content"] = "这是一个中年男人，显然和尾生描述里的妻子对不上号。",
            ["ContentKR"] = "우직생이 찾는 건 자기 아내인데, 이 사람은 중년 남성이니까 안 맞아.",
            ["DialogueId"] = 51160006,
            ["GUID"] = "8012DE7C",
            ["SpeakNpcId"] = 100001,
            },
        [51160101] = {
            ["Content"] = "去年修书一封，邀你去家乡做客，我给你打树上的核桃来吃，你只说你生了病，后续我忙起别事，竟是忘了这茬。",
            ["DialogueId"] = 51160101,
            ["GUID"] = "8012EE12",
            ["NextDialogue"] = 51160102,
            ["SpeakNpcId"] = 701150,
            },
        [51160102] = {
            ["Content"] = "哪里传来的声音……好熟悉……",
            ["DialogueId"] = 51160102,
            ["GUID"] = "8012EE3C",
            ["NextOptions"] = {
                [1] = 51160103,
                },
            ["SpeakNpcId"] = 701150,
            },
        [51160103] = {
            ["Content"] = "我没听到啊。",
            ["DialogueId"] = 51160103,
            ["GUID"] = "8012EE66",
            ["NextDialogue"] = 51160104,
            },
        [51160104] = {
            ["Content"] = "这是喜乐啊……是哪家在办喜事吗？",
            ["DialogueId"] = 51160104,
            ["GUID"] = "8012EE90",
            ["NextDialogue"] = 51160105,
            ["SpeakNpcId"] = 701150,
            },
        [51160105] = {
            ["Content"] = "哈哈……林兄，你可听见了？当年你我同游之时，你折柳击水而歌，唱的便是这首《贺新郎》，你说待我五十寿辰，定要与我共饮这杯酒。",
            ["DialogueId"] = 51160105,
            ["GUID"] = "8012EEBA",
            ["NextDialogue"] = 51160106,
            ["SpeakNpcId"] = 701150,
            },
        [51160106] = {
            ["Content"] = "此杯酒，我给你带来了，以往你总舍不得喝，每次只说小酌便好，而今日……",
            ["DialogueId"] = 51160106,
            ["GUID"] = "8012EEE4",
            ["NextDialogue"] = 51160107,
            ["SpeakNpcId"] = 701150,
            },
        [51160107] = {
            ["Content"] = "哈哈哈！随意喝吧！畅快喝吧！本来悲喜总同筵，虞泉人间共举杯！",
            ["DialogueId"] = 51160107,
            ["GUID"] = "8012EF0E",
            ["SpeakNpcId"] = 701150,
            },
        [51160108] = {
            ["Content"] = "林兄，昔日你我诗会相逢，一见如故。高山流水，难遇知音，这杯，我敬你！",
            ["DialogueId"] = 51160108,
            ["GUID"] = "8012EE11",
            ["NextDialogue"] = 51160101,
            ["SpeakNpcId"] = 701150,
            },
        [51160109] = {
            ["Content"] = "这话什么意思，葬礼吹唢呐不是传统吗？大舅一辈子操劳，走了还不得是风风光光，热热闹闹的？",
            ["DialogueId"] = 51160109,
            ["GUID"] = "8012EF62",
            ["NextDialogue"] = 51160110,
            ["SpeakNpcName"] = "UI_NPC_Name_shubai_Sce",
            },
        [51160110] = {
            ["Content"] = "那都多少年前的老古董做法，现在城里早不兴这套了。唢呐一吹扰民得很，到时候还有人去泉通阁投诉。",
            ["DialogueId"] = 51160110,
            ["GUID"] = "8012EF8C",
            ["NextDialogue"] = 51160111,
            ["SpeakNpcId"] = 701149,
            },
        [51160111] = {
            ["Content"] = "可我早八百年就联系过了，定金也付过了，街坊邻居也知晓此事。我不信旁人会忘本到这种地步，家里出了事还要来怪罪。",
            ["DialogueId"] = 51160111,
            ["GUID"] = "8012EFB6",
            ["NextDialogue"] = 51160112,
            ["SpeakNpcName"] = "UI_NPC_Name_shubai_Sce",
            },
        [51160112] = {
            ["Content"] = "这和别人没关系，是皓京的规矩。那我问你，现在是不是奉香大典期间也不让在皓京城内放烟花了？",
            ["DialogueId"] = 51160112,
            ["GUID"] = "8012EFE0",
            ["NextDialogue"] = 51160113,
            ["SpeakNpcId"] = 701149,
            },
        [51160113] = {
            ["Content"] = "匠矩阁的师傅说了，只要他们研发出硝烟净化器就给放！",
            ["DialogueId"] = 51160113,
            ["GUID"] = "8012F00A",
            ["NextDialogue"] = 51160114,
            ["SpeakNpcName"] = "UI_NPC_Name_shubai_Sce",
            },
        [51160114] = {
            ["Content"] = "那是不是还没研究出来？",
            ["DialogueId"] = 51160114,
            ["GUID"] = "8012F034",
            ["NextDialogue"] = 51160115,
            ["SpeakNpcId"] = 701149,
            },
        [51160115] = {
            ["Content"] = "少胡说八道，今年就研究出来了，今年就能在皓京城里放烟花！这事听我的！",
            ["DialogueId"] = 51160115,
            ["GUID"] = "8012F05E",
            ["SpeakNpcName"] = "UI_NPC_Name_shubai_Sce",
            },
        [51160116] = {
            ["Content"] = "现在都什么年代了，哪有在丧礼上请乐队的人家！",
            ["DialogueId"] = 51160116,
            ["GUID"] = "8012EF61",
            ["NextDialogue"] = 51160109,
            ["SpeakNpcId"] = 701149,
            },
        [51160201] = {
            ["Content"] = "草木深胡同……是在这里？还是……",
            ["DialogueId"] = 51160201,
            ["GUID"] = "8012FEA3",
            ["NextDialogue"] = 51160202,
            ["SpeakNpcId"] = 701151,
            },
        [51160202] = {
            ["Content"] = "再找不到地方，这做好的菜肴送到手就凉了，这个月已吃了三次投诉，再来一次怕是要被骂惨啦。",
            ["DialogueId"] = 51160202,
            ["GUID"] = "8012FEA4",
            ["NextDialogue"] = 51160203,
            ["SpeakNpcId"] = 701151,
            },
        [51160203] = {
            ["Content"] = "不过……这事怎么想都和我没关系，要怪也是怪别人，",
            ["DialogueId"] = 51160203,
            ["GUID"] = "8012FECE",
            ["NextOptions"] = {
                [1] = 51160204,
                },
            ["SpeakNpcId"] = 701151,
            },
        [51160204] = {
            ["Content"] = "怪谁？",
            ["DialogueId"] = 51160204,
            ["GUID"] = "8012FEF8",
            ["NextDialogue"] = 51160205,
            },
        [51160205] = {
            ["Content"] = "那可就多了！首先啊，这厨子做菜时候就开始磨磨唧唧，说今天锅气不好，非要先炒两个菜试试手再做客人定的餐。",
            ["DialogueId"] = 51160205,
            ["GUID"] = "8012FF22",
            ["NextDialogue"] = 51160206,
            ["SpeakNpcId"] = 701151,
            },
        [51160206] = {
            ["Content"] = "然后呢，我刚将菜肴装进食盒，准备撒腿就跑，老板的小女儿又缠住我，非要我给她讲个故事才放我走。",
            ["DialogueId"] = 51160206,
            ["GUID"] = "8012FF4C",
            ["NextDialogue"] = 51160207,
            ["SpeakNpcId"] = 701151,
            },
        [51160207] = {
            ["Content"] = "最后就是，这客人给的地址也表述不清晰，只说是草木深胡同，但却没说具体在哪里，是更靠近参商港还是更靠近泉通阁。",
            ["DialogueId"] = 51160207,
            ["GUID"] = "8012FF76",
            ["NextOptions"] = {
                [1] = 51160208,
                [2] = 51160212,
                [3] = 51160216,
                },
            ["SpeakNpcId"] = 701151,
            },
        [51160208] = {
            ["Content"] = "老板的小女儿为什么在店里？",
            ["DialogueId"] = 51160208,
            ["GUID"] = "8012FFA0",
            ["NextDialogue"] = 51160209,
            },
        [51160209] = {
            ["Content"] = "可说呢！你不晓得咱这私房菜馆有多讲究，当年只是老板做菜好吃，逐渐在西市这一片传出了名声，于是大家都爱到他家里蹭饭。",
            ["DialogueId"] = 51160209,
            ["GUID"] = "8012FFCA",
            ["NextDialogue"] = 51160210,
            ["SpeakNpcId"] = 701151,
            },
        [51160210] = {
            ["Content"] = "后面有人蹭饭蹭到不好意思了，就怂恿让他开家私房菜馆，这样大家就能名正言顺吃他做的菜。",
            ["DialogueId"] = 51160210,
            ["GUID"] = "8012FFF4",
            ["NextDialogue"] = 51160211,
            ["SpeakNpcId"] = 701151,
            },
        [51160211] = {
            ["Content"] = "所以，其实饭馆就是老板的家，家中有孩子这不是常见之事嘛。",
            ["DialogueId"] = 51160211,
            ["GUID"] = "8013001E",
            ["NextOptions"] = {
                [1] = 51160220,
                },
            ["SpeakNpcId"] = 701151,
            },
        [51160212] = {
            ["Content"] = "锅气是怎么个说法？",
            ["DialogueId"] = 51160212,
            ["GUID"] = "80130048",
            ["NextDialogue"] = 51160213,
            },
        [51160213] = {
            ["Content"] = "我其实也不怎么清楚，毕竟我这种连酱油和醋都分不清的烹饪菜鸟，让我去解释如此专业的词还是太难为我了。",
            ["DialogueId"] = 51160213,
            ["GUID"] = "80130072",
            ["NextDialogue"] = 51160214,
            ["SpeakNpcId"] = 701151,
            },
        [51160214] = {
            ["Content"] = "但是我可跟你说，要是老板本人来炒这个菜，绝不会说什么锅气不锅气的，但他最近出远门，把整个生意都交给了自己的学徒来打理。",
            ["DialogueId"] = 51160214,
            ["GUID"] = "8013009C",
            ["NextDialogue"] = 51160215,
            ["SpeakNpcId"] = 701151,
            },
        [51160215] = {
            ["Content"] = "那家伙事情可多了，总说不能丢师傅的脸，所以一道菜要做上三四遍，耽误我送餐的时间……",
            ["DialogueId"] = 51160215,
            ["GUID"] = "801300C6",
            ["NextOptions"] = {
                [1] = 51160220,
                },
            ["SpeakNpcId"] = 701151,
            },
        [51160216] = {
            ["Content"] = "你既然是专门送餐的，为什么会不认路呢？",
            ["DialogueId"] = 51160216,
            ["GUID"] = "801300F0",
            ["NextDialogue"] = 51160217,
            },
        [51160217] = {
            ["Content"] = "我又不是皓京城土生土长的本地人，怎么能要求我认清皓京所有的路呢？",
            ["DialogueId"] = 51160217,
            ["GUID"] = "8013011A",
            ["NextDialogue"] = 51160218,
            ["SpeakNpcId"] = 701151,
            },
        [51160218] = {
            ["Content"] = "再说了，我可是最近才来的皓京，算来也就……三个月？一个月前，我连皓京本地话都不怎么听得懂，现在也还在学习中。",
            ["DialogueId"] = 51160218,
            ["GUID"] = "80130144",
            ["NextDialogue"] = 51160219,
            ["SpeakNpcId"] = 701151,
            },
        [51160219] = {
            ["Content"] = "你是不是对一个外来者的要求太高了！",
            ["DialogueId"] = 51160219,
            ["GUID"] = "8013016E",
            ["NextOptions"] = {
                [1] = 51160220,
                },
            ["SpeakNpcId"] = 701151,
            },
        [51160220] = {
            ["Content"] = "你还是快些去送餐吧。",
            ["DialogueId"] = 51160220,
            ["GUID"] = "80130198",
            ["NextDialogue"] = 51160221,
            },
        [51160221] = {
            ["Content"] = "哎呀！这下要怪你了！要不是跟你聊了这么久，我一定早就送到了！",
            ["DialogueId"] = 51160221,
            ["GUID"] = "801301C2",
            ["SpeakNpcId"] = 701151,
            },
        [51160301] = {
            ["Content"] = "你说那家私房菜？我是听说过，但那家地方小，难订座，现下去问恐怕是吃不上了。",
            ["DialogueId"] = 51160301,
            ["GUID"] = "80130EE2",
            ["NextDialogue"] = 51160302,
            ["SpeakNpcId"] = 701152,
            },
        [51160302] = {
            ["Content"] = "我说一个你便拒绝一个，那我还能说什么，别吃了！",
            ["DialogueId"] = 51160302,
            ["GUID"] = "80130F0C",
            ["NextDialogue"] = 51160303,
            ["SpeakNpcId"] = 701259,
            },
        [51160303] = {
            ["Content"] = "诶呀，兄台莫生气，气出病来谁如意。这再怎么说也是家里来了远客，我是想着照顾妥帖些，所以才左右为难，瞻前顾后。",
            ["DialogueId"] = 51160303,
            ["GUID"] = "80130F36",
            ["NextDialogue"] = 51160304,
            ["SpeakNpcId"] = 701152,
            },
        [51160304] = {
            ["Content"] = "花言巧语，我是没法给你答案了，你还是问别人吧，诶，就那边那位穿着白衣服的……",
            ["DialogueId"] = 51160304,
            ["GUID"] = "80130F60",
            ["NextDialogue"] = 51160305,
            ["SpeakNpcId"] = 701259,
            },
        [51160305] = {
            ["Content"] = "（两人齐齐看向你。）",
            ["DialogueId"] = 51160305,
            ["GUID"] = "80130F8A",
            ["NextDialogue"] = 51160306,
            },
        [51160306] = {
            ["Content"] = "白衣服的朋友，不知方不方便替我做个决断。这事情的来龙去脉，适才你也听过了吧？",
            ["DialogueId"] = 51160306,
            ["GUID"] = "80130FB4",
            ["NextOptions"] = {
                [1] = 51160307,
                [2] = 51160310,
                },
            ["SpeakNpcId"] = 701259,
            },
        [51160307] = {
            ["Content"] = "没仔细听。",
            ["DialogueId"] = 51160307,
            ["GUID"] = "80130FDE",
            ["NextDialogue"] = 51160308,
            },
        [51160308] = {
            ["Content"] = "无妨，那我再说一遍，是这样的，我家中来了远客，我想在皓京城里挑家餐馆，款待客人，可却怎么也拿不定主意，所以想请人来帮我参谋参谋。",
            ["DialogueId"] = 51160308,
            ["GUID"] = "80131008",
            ["NextDialogue"] = 51160309,
            ["SpeakNpcId"] = 701152,
            },
        [51160309] = {
            ["Content"] = "得了吧，哪里是来找人参谋，是来给我找气受。",
            ["DialogueId"] = 51160309,
            ["GUID"] = "80131032",
            ["NextOptions"] = {
                [1] = 51160320,
                [2] = 51160322,
                [3] = 51160324,
                },
            ["SpeakNpcId"] = 701259,
            },
        [51160310] = {
            ["Content"] = "听过了。",
            ["DialogueId"] = 51160310,
            ["GUID"] = "8013105C",
            ["NextDialogue"] = 51160311,
            },
        [51160311] = {
            ["Content"] = "太好了！那便省得我多解释一番。目前已选定了三家，我来细细说给你听。",
            ["DialogueId"] = 51160311,
            ["GUID"] = "80131086",
            ["NextDialogue"] = 51160312,
            ["SpeakNpcId"] = 701152,
            },
        [51160312] = {
            ["Content"] = "第一家是同福饭馆，开在东市，算是皓京城新开的店铺，菜品多为融合菜，十分有新意，只是……",
            ["DialogueId"] = 51160312,
            ["GUID"] = "801310B0",
            ["NextDialogue"] = 51160313,
            ["SpeakNpcId"] = 701152,
            },
        [51160313] = {
            ["Content"] = "只是你觉得融合菜有些失了皓京特色。",
            ["DialogueId"] = 51160313,
            ["GUID"] = "801310DA",
            ["NextDialogue"] = 51160314,
            ["SpeakNpcId"] = 701259,
            },
        [51160314] = {
            ["Content"] = "是也不是……总之，这第二家则是八珍楼，倒是皓京有些历史的店铺了，以前开在西市，后来店面扩大便搬到东市。",
            ["DialogueId"] = 51160314,
            ["GUID"] = "80131104",
            ["NextDialogue"] = 51160315,
            ["SpeakNpcId"] = 701152,
            },
        [51160315] = {
            ["Content"] = "要我说就这家最好，菜品都是老皓京人的口味，档次也足够，是最好的。",
            ["DialogueId"] = 51160315,
            ["GUID"] = "8013112E",
            ["NextDialogue"] = 51160316,
            ["SpeakNpcId"] = 701259,
            },
        [51160316] = {
            ["Content"] = "你怎么不说他家多少年没有上过新，一直在吃老本。",
            ["DialogueId"] = 51160316,
            ["GUID"] = "80131158",
            ["NextDialogue"] = 51160317,
            ["SpeakNpcId"] = 701152,
            },
        [51160317] = {
            ["Content"] = "行啊，那第三家，西市私房菜馆，多少人来这排队就为了吃上那一口，这也不行。",
            ["DialogueId"] = 51160317,
            ["GUID"] = "80131182",
            ["NextDialogue"] = 51160318,
            ["SpeakNpcId"] = 701259,
            },
        [51160318] = {
            ["Content"] = "你都说了排队……我那朋友没几天就要来了，要是没排上号那该如何是好？",
            ["DialogueId"] = 51160318,
            ["GUID"] = "801311AC",
            ["NextDialogue"] = 51160319,
            ["SpeakNpcId"] = 701152,
            },
        [51160319] = {
            ["Content"] = "你看看你看看，他就是这般给我找气受，我不说了！你来给他支支招吧！",
            ["DialogueId"] = 51160319,
            ["GUID"] = "801311D6",
            ["NextOptions"] = {
                [1] = 51160320,
                [2] = 51160322,
                [3] = 51160324,
                },
            ["SpeakNpcId"] = 701259,
            },
        [51160320] = {
            ["Content"] = "同福饭馆吧。",
            ["DialogueId"] = 51160320,
            ["GUID"] = "80131200",
            ["NextDialogue"] = 51160321,
            },
        [51160321] = {
            ["Content"] = "同福饭馆菜品新颖，想必你朋友也很愿意尝鲜。",
            ["DialogueId"] = 51160321,
            ["GUID"] = "8013122A",
            ["NextDialogue"] = 51160326,
            ["SpeakNpcId"] = 100001,
            },
        [51160322] = {
            ["Content"] = "八珍楼吧。",
            ["DialogueId"] = 51160322,
            ["GUID"] = "80131254",
            ["NextDialogue"] = 51160323,
            },
        [51160323] = {
            ["Content"] = "八珍楼十分传统，一些不那么容易被外人接受的你避开点就是。",
            ["DialogueId"] = 51160323,
            ["GUID"] = "8013127E",
            ["NextDialogue"] = 51160326,
            ["SpeakNpcId"] = 100001,
            },
        [51160324] = {
            ["Content"] = "私房菜吧。",
            ["DialogueId"] = 51160324,
            ["GUID"] = "801312A8",
            ["NextDialogue"] = 51160325,
            },
        [51160325] = {
            ["Content"] = "你还没去排队就说放弃，怎么知道究竟有没有空座预定呢？",
            ["DialogueId"] = 51160325,
            ["GUID"] = "801312D2",
            ["NextDialogue"] = 51160326,
            ["SpeakNpcId"] = 100001,
            },
        [51160326] = {
            ["Content"] = "你看，这位朋友说的就十分中肯，和我的推荐也并无多大的差别。我看你啊，就别纠结了，就听我们的吧！",
            ["DialogueId"] = 51160326,
            ["GUID"] = "801312FC",
            ["NextDialogue"] = 51160327,
            ["SpeakNpcId"] = 701259,
            },
        [51160327] = {
            ["Content"] = "倒是确实有道理，那要不……",
            ["DialogueId"] = 51160327,
            ["GUID"] = "80131326",
            ["NextDialogue"] = 51160328,
            ["SpeakNpcId"] = 701152,
            },
        [51160328] = {
            ["Content"] = "还要不什么呀，再磨磨唧唧可就一家都选不出来了！",
            ["DialogueId"] = 51160328,
            ["GUID"] = "80131350",
            ["SpeakNpcId"] = 701259,
            },
        [51160401] = {
            ["Content"] = "若非有仙人指路，怎知这小巷深处竟藏着这庖厨圣地！",
            ["DialogueId"] = 51160401,
            ["GUID"] = "80131F4A",
            ["NextDialogue"] = 51160402,
            ["SpeakNpcId"] = 701153,
            },
        [51160402] = {
            ["Content"] = "适才品过几道菜肴，最为印象深刻的便是那道青玉鲙，纹理如云，入口即溶，用的是那上好的冬瓜瓤，用笋汁慢煨数时，竟比珍猪蹄还要丰腴肥润……",
            ["DialogueId"] = 51160402,
            ["GUID"] = "80131F74",
            ["NextDialogue"] = 51160403,
            ["SpeakNpcId"] = 701153,
            },
        [51160403] = {
            ["Content"] = "还有那甜品，桂花香气混进了乳奶，出了蒸锅，再用腌渍过的酸梅放在上方，轻轻碾压，不破坏原先糕体的基础上，让酸液渗入其中。",
            ["DialogueId"] = 51160403,
            ["GUID"] = "80131F9E",
            ["NextDialogue"] = 51160404,
            ["SpeakNpcId"] = 701153,
            },
        [51160404] = {
            ["Content"] = "这般滋味，甚好……甚好……想我也算半个老饕，纵横华胥多年，本以为再吃到什么口味都不会惊叹了，竟被一家名不见经传的小店厨艺折服。",
            ["DialogueId"] = 51160404,
            ["GUID"] = "80131FC8",
            ["NextDialogue"] = 51160405,
            ["SpeakNpcId"] = 701153,
            },
        [51160405] = {
            ["Content"] = "皓京还是……卧虎藏龙之地啊……",
            ["DialogueId"] = 51160405,
            ["GUID"] = "80131FF2",
            ["SpeakNpcId"] = 701153,
            },
        [51160501] = {
            ["Content"] = "老张啊，你那只八哥，今日居然念了几句诗，是不是你孙子整日在家背书被它听着学了去？",
            ["DialogueId"] = 51160501,
            ["GUID"] = "80132FB2",
            ["NextDialogue"] = 51160502,
            ["SpeakNpcId"] = 701154,
            },
        [51160502] = {
            ["Content"] = "胡说八道！你怎么不说是鸟儿聪明，听了一遍就学会了，和我那小孙儿一样，学什么都是一点通。",
            ["DialogueId"] = 51160502,
            ["GUID"] = "80132FDC",
            ["NextDialogue"] = 51160503,
            ["SpeakNpcName"] = "UI_NPC_Name_zhangweng_Sce",
            },
        [51160503] = {
            ["Content"] = "我都不好说你，老张，你那孙子……你那，嗐……你就说这话说出来你脸不脸红……",
            ["DialogueId"] = 51160503,
            ["GUID"] = "80133006",
            ["NextDialogue"] = 51160504,
            ["SpeakNpcId"] = 701154,
            },
        [51160504] = {
            ["Content"] = "我老张一辈子行得正坐得直，说话从无虚言！",
            ["DialogueId"] = 51160504,
            ["GUID"] = "80133030",
            ["NextDialogue"] = 51160505,
            ["SpeakNpcName"] = "UI_NPC_Name_zhangweng_Sce",
            },
        [51160505] = {
            ["Content"] = "行啦，都多大岁数了还整天吵个不停，还是聊聊别的吧，我那窝啾啾莺，今晨搬了家，竟在门口那棵老槐树上坐了窝。",
            ["DialogueId"] = 51160505,
            ["GUID"] = "8013305A",
            ["NextDialogue"] = 51160506,
            ["SpeakNpcName"] = "UI_NPC_Name_jinpopo_Sce",
            },
        [51160506] = {
            ["Content"] = "怪不得你今天没给提出来溜溜呢，原来是换了个场子。",
            ["DialogueId"] = 51160506,
            ["GUID"] = "80133084",
            ["NextDialogue"] = 51160507,
            ["SpeakNpcId"] = 701154,
            },
        [51160507] = {
            ["Content"] = "不过……你们谁知道那老李头今天又犯什么毛病了，从哪抓了只……",
            ["DialogueId"] = 51160507,
            ["GUID"] = "801330AE",
            ["NextDialogue"] = 51160508,
            ["SpeakNpcName"] = "UI_NPC_Name_jinpopo_Sce",
            },
        [51160508] = {
            ["Content"] = "蓑翁鹭是吧？他那脾气，太古怪了！怎么说我俩的孙儿都在一起念书，我便和他攀谈孙儿学业之事，他却连正眼也不瞧我！",
            ["DialogueId"] = 51160508,
            ["GUID"] = "801330D8",
            ["NextDialogue"] = 51160509,
            ["SpeakNpcName"] = "UI_NPC_Name_zhangweng_Sce",
            },
        [51160509] = {
            ["Content"] = "气得我跟他吵了一架，今日居然又来当这显眼咖。",
            ["DialogueId"] = 51160509,
            ["GUID"] = "80133102",
            ["NextDialogue"] = 51160510,
            ["SpeakNpcName"] = "UI_NPC_Name_zhangweng_Sce",
            },
        [51160510] = {
            ["Content"] = "嘿，你脾气又好到哪里去呢？",
            ["DialogueId"] = 51160510,
            ["GUID"] = "8013312C",
            ["NextDialogue"] = 51160511,
            ["SpeakNpcId"] = 701154,
            },
        [51160511] = {
            ["Content"] = "你什么意思？",
            ["DialogueId"] = 51160511,
            ["GUID"] = "80133156",
            ["NextDialogue"] = 51160512,
            ["SpeakNpcName"] = "UI_NPC_Name_zhangweng_Sce",
            },
        [51160512] = {
            ["Content"] = "差不多得啦……",
            ["DialogueId"] = 51160512,
            ["GUID"] = "80133180",
            ["SpeakNpcName"] = "UI_NPC_Name_jinpopo_Sce",
            },
        [51160601] = {
            ["Content"] = "来，二楞，叫两嗓子给他们听听看，什么叫皓京城里最神气的鸟！",
            ["DialogueId"] = 51160601,
            ["GUID"] = "8013401A",
            ["NextDialogue"] = 51160602,
            ["SpeakNpcId"] = 701155,
            },
        [51160602] = {
            ["Content"] = "叫！叫啊！你怎么不叫？",
            ["DialogueId"] = 51160602,
            ["GUID"] = "80134044",
            ["NextOptions"] = {
                [1] = 51160603,
                [2] = 51160606,
                },
            ["SpeakNpcId"] = 701155,
            },
        [51160603] = {
            ["Content"] = "你喂点吃的？",
            ["DialogueId"] = 51160603,
            ["GUID"] = "8013406E",
            ["ImprPlusId"] = 1208,
            ["NextDialogue"] = 51160604,
            },
        [51160604] = {
            ["Content"] = "早上出门前才喂过一盆鱼，那时候吃的肚子鼓鼓囊囊，怎可能现在就饿了呢？",
            ["DialogueId"] = 51160604,
            ["GUID"] = "80134098",
            ["NextDialogue"] = 51160605,
            ["SpeakNpcId"] = 701155,
            },
        [51160605] = {
            ["Content"] = "看着肚子也不算大，难不成真是无底洞？",
            ["DialogueId"] = 51160605,
            ["GUID"] = "801340C2",
            ["SpeakNpcId"] = 701155,
            },
        [51160606] = {
            ["Content"] = "你这么凶它会害怕的。",
            ["DialogueId"] = 51160606,
            ["GUID"] = "801340EC",
            ["ImprPlusId"] = 1209,
            ["NextDialogue"] = 51160607,
            },
        [51160607] = {
            ["Content"] = "什么意思？这鸟……难道还能听懂人的话？我这也不算凶它吧，只是让它嚎一嗓子，好让那边的几个老东西看看，到底谁更厉害！",
            ["DialogueId"] = 51160607,
            ["GUID"] = "80134116",
            ["SpeakNpcId"] = 701155,
            },
        [51160608] = {
            ["Content"] = "凡夫俗子溜凡夫俗鸟，他们那些，能有我这只厉害吗？",
            ["DialogueId"] = 51160608,
            ["GUID"] = "80134140",
            ["NextDialogue"] = 51160609,
            ["SpeakNpcId"] = 701155,
            },
        [51160609] = {
            ["Content"] = "水也喝上了，鱼也吃过了，你不是会发出咕咕嘎嘎的叫声吗？叫给他们听听啊？",
            ["DialogueId"] = 51160609,
            ["GUID"] = "8013416A",
            ["NextDialogue"] = 51160610,
            ["SpeakNpcId"] = 701155,
            },
        [51160610] = {
            ["Content"] = "咕咕！嘎嘎！咕嘎！咕咕嘎嘎！",
            ["DialogueId"] = 51160610,
            ["GUID"] = "80134194",
            ["NextOptions"] = {
                [1] = 51160611,
                [2] = 51160613,
                },
            ["SpeakNpcId"] = 701155,
            },
        [51160611] = {
            ["Content"] = "咕咕嘎嘎！",
            ["DialogueId"] = 51160611,
            ["GUID"] = "801341BE",
            ["NextDialogue"] = 51160612,
            },
        [51160612] = {
            ["Content"] = "是你啊，你之前给我说的招数不好用，这蓑翁鹭还是没叫，我又是给它吃的又是哄它开心，但怎么也不见它叫。",
            ["DialogueId"] = 51160612,
            ["GUID"] = "801341E8",
            ["NextOptions"] = {
                [1] = 51160615,
                },
            ["SpeakNpcId"] = 701155,
            },
        [51160613] = {
            ["Content"] = "你为什么一定要它叫呢？",
            ["DialogueId"] = 51160613,
            ["GUID"] = "80134212",
            ["NextDialogue"] = 51160614,
            },
        [51160614] = {
            ["Content"] = "当然是要给那些白痴老头听啊！叫的越大声越好！要是能把他们的耳朵震聋，那才最好！",
            ["DialogueId"] = 51160614,
            ["GUID"] = "8013423C",
            ["NextOptions"] = {
                [1] = 51160615,
                },
            ["SpeakNpcId"] = 701155,
            },
        [51160615] = {
            ["Content"] = "你和他们有仇吗？",
            ["DialogueId"] = 51160615,
            ["GUID"] = "80134266",
            ["NextDialogue"] = 51160616,
            },
        [51160616] = {
            ["Content"] = "仇？哼！我才没那个闲工夫和人结仇！",
            ["DialogueId"] = 51160616,
            ["GUID"] = "80134290",
            ["NextDialogue"] = 51160617,
            ["SpeakNpcId"] = 701155,
            },
        [51160617] = {
            ["Content"] = "不过是他们平日行径令人不齿，我看不过去，才特意从外买来一只蓑翁鹭，准备狠狠报复他们一顿！",
            ["DialogueId"] = 51160617,
            ["GUID"] = "801342BA",
            ["NextOptions"] = {
                [1] = 51160618,
                },
            ["SpeakNpcId"] = 701155,
            },
        [51160618] = {
            ["Content"] = "他们做了什么伤天害理的事情？",
            ["DialogueId"] = 51160618,
            ["GUID"] = "801342E4",
            ["NextDialogue"] = 51160619,
            },
        [51160619] = {
            ["Content"] = "看那个，满头白发的那个，他那混账孙子，在家惯的无法无天，在外念书更是一窍不通。",
            ["DialogueId"] = 51160619,
            ["GUID"] = "8013430E",
            ["NextDialogue"] = 51160620,
            ["SpeakNpcId"] = 701155,
            },
        [51160620] = {
            ["Content"] = "明明没有我家乖乖孙儿考得好，却回回在外吹说他那混账孙子有多聪明伶俐，简直胡扯！",
            ["DialogueId"] = 51160620,
            ["GUID"] = "80134338",
            ["NextDialogue"] = 51160621,
            ["SpeakNpcId"] = 701155,
            },
        [51160621] = {
            ["Content"] = "再说那个，牙齿豁口的那个，一天到晚不知道想的什么，非要在皓京城养鸟，还一次养一窝！",
            ["DialogueId"] = 51160621,
            ["GUID"] = "80134362",
            ["NextDialogue"] = 51160622,
            ["SpeakNpcId"] = 701155,
            },
        [51160622] = {
            ["Content"] = "那啾啾莺是直肠子，飞来飞去管不住自己的肚子，我那日在院子里躺着纳凉，那莺儿居然径自飞到我头上，朝我——！",
            ["DialogueId"] = 51160622,
            ["GUID"] = "8013438C",
            ["NextDialogue"] = 51160623,
            ["SpeakNpcId"] = 701155,
            },
        [51160623] = {
            ["Content"] = "（老头子的声音戛然而止，你再看过去之时，他涨红了脸，却是憋不出一句话来。）",
            ["DialogueId"] = 51160623,
            ["GUID"] = "801343B6",
            ["NextDialogue"] = 51160624,
            },
        [51160624] = {
            ["Content"] = "不说了不说了！说起来就来气！总之这些老家伙都是混账！我这回一定要狠狠报复他们！",
            ["DialogueId"] = 51160624,
            ["GUID"] = "801343E0",
            ["NextDialogue"] = 51160625,
            ["SpeakNpcId"] = 701155,
            },
        [51160625] = {
            ["Content"] = "来！蓑翁鹭，给我叫！",
            ["DialogueId"] = 51160625,
            ["GUID"] = "8013440A",
            ["SpeakNpcId"] = 701155,
            },
        [51160626] = {
            ["Content"] = "凡夫俗子溜凡羽俗鸟，他们那些鸟，能有我这只厉害吗？",
            ["DialogueId"] = 51160626,
            ["GUID"] = "8013401B",
            ["NextDialogue"] = 51160601,
            ["SpeakNpcId"] = 701155,
            },
        [51160701] = {
            ["Content"] = "车三进六，将军！老友，这局棋，你该怎么破？",
            ["DialogueId"] = 51160701,
            ["GUID"] = "80135082",
            },
        [51160702] = {
            ["Content"] = "唔……难……难啊……",
            ["DialogueId"] = 51160702,
            ["GUID"] = "801350AC",
            },
        [51160801] = {
            ["Content"] = "（这似乎是华胥的一种娱乐用品，你曾在百年春看到过相关介绍，但并不怎么了解规则）。",
            ["DialogueId"] = 51160801,
            ["GUID"] = "801360EA",
            ["NextDialogue"] = 51160802,
            },
        [51160802] = {
            ["Content"] = "小友也对象棋感兴趣？",
            ["DialogueId"] = 51160802,
            ["GUID"] = "80136114",
            ["NextOptions"] = {
                [1] = 51160803,
                [2] = 51160804,
                },
            ["SpeakNpcId"] = 701156,
            },
        [51160803] = {
            ["Content"] = "懂一点，但不多。",
            ["DialogueId"] = 51160803,
            ["GUID"] = "8013613E",
            ["NextDialogue"] = 51160805,
            },
        [51160804] = {
            ["Content"] = "完全不懂。",
            ["DialogueId"] = 51160804,
            ["GUID"] = "80136168",
            ["NextDialogue"] = 51160805,
            },
        [51160805] = {
            ["Content"] = "你看这当下局面，黑方多一卒却缺一象，红方双车联动却难破担子炮，以你之见，你觉得这局棋局会是谁胜谁负？",
            ["DialogueId"] = 51160805,
            ["GUID"] = "80136192",
            ["NextOptions"] = {
                [1] = 51160806,
                [2] = 51160808,
                [3] = 51160810,
                },
            ["SpeakNpcId"] = 701156,
            },
        [51160806] = {
            ["Content"] = "黑方胜红方输。",
            ["DialogueId"] = 51160806,
            ["GUID"] = "801361BC",
            ["NextDialogue"] = 51160807,
            },
        [51160807] = {
            ["Content"] = "的确，若是他走一招马四进六，再接一手炮八平六打双车，那红方若是逃车便会丢马，若是保马则可惜失了先手。",
            ["DialogueId"] = 51160807,
            ["GUID"] = "801361E6",
            ["SpeakNpcId"] = 701156,
            },
        [51160808] = {
            ["Content"] = "红方胜黑方输。",
            ["DialogueId"] = 51160808,
            ["GUID"] = "80136210",
            ["NextDialogue"] = 51160809,
            },
        [51160809] = {
            ["Content"] = "车四平六，若是黑方吃车则车八平六，若是避让却会丢炮弃势。",
            ["DialogueId"] = 51160809,
            ["GUID"] = "8013623A",
            ["SpeakNpcId"] = 701156,
            },
        [51160810] = {
            ["Content"] = "我不知道。",
            ["DialogueId"] = 51160810,
            ["GUID"] = "80136264",
            ["NextDialogue"] = 51160811,
            },
        [51160811] = {
            ["Content"] = "此局棋看似注定，实则双方都有回旋余地，的确难辨。",
            ["DialogueId"] = 51160811,
            ["GUID"] = "8013628E",
            ["NextDialogue"] = 51160812,
            ["SpeakNpcId"] = 701156,
            },
        [51160812] = {
            ["Content"] = "你既然都知道，为什么不告诉他们呢？",
            ["DialogueId"] = 51160812,
            ["GUID"] = "801362B8",
            ["NextDialogue"] = 51160813,
            },
        [51160813] = {
            ["Content"] = "小友，华胥有句古言，叫——观棋不语真君子，你懂了吧？",
            ["DialogueId"] = 51160813,
            ["GUID"] = "801362E2",
            ["SpeakNpcId"] = 701156,
            },
        [51160901] = {
            ["Content"] = "最近没得空，儿子和媳妇成日吵架，我天一黑就歇下了，睡到半夜却被吵醒，想着毕竟是夫妻俩之间的事，我们做长辈的也不好插手。",
            ["DialogueId"] = 51160901,
            ["GUID"] = "80137152",
            ["NextDialogue"] = 51160902,
            ["SpeakNpcName"] = "UI_NPC_Name_wangxiulian_Sce",
            },
        [51160902] = {
            ["Content"] = "于是就只能等他们吵到天蒙蒙亮，唉……老啦，体力跟不上了，稍微熬个大夜，第二天哪哪都难受……",
            ["DialogueId"] = 51160902,
            ["GUID"] = "8013717C",
            ["NextDialogue"] = 51160903,
            ["SpeakNpcName"] = "UI_NPC_Name_wangxiulian_Sce",
            },
        [51160903] = {
            ["Content"] = "也不能总是这么由着他们，你也要照顾好自己的身体，实在不行，你让他俩搬出去住上几天，不闹了再回家。",
            ["DialogueId"] = 51160903,
            ["GUID"] = "801371A6",
            ["NextDialogue"] = 51160904,
            ["SpeakNpcId"] = 701157,
            },
        [51160904] = {
            ["Content"] = "得闲我去说道说道，要是他俩搬出去，到时你们都来我家里打骨牌。",
            ["DialogueId"] = 51160904,
            ["GUID"] = "801371D0",
            ["NextDialogue"] = 51160905,
            ["SpeakNpcName"] = "UI_NPC_Name_wangxiulian_Sce",
            },
        [51160905] = {
            ["Content"] = "前些日子我还从外面淘了一套羊脂玉做的骨牌，手感温润，到时候你们可得陪我好好打个三天三夜。",
            ["DialogueId"] = 51160905,
            ["GUID"] = "801371FA",
            ["NextDialogue"] = 51160906,
            ["SpeakNpcName"] = "UI_NPC_Name_wangxiulian_Sce",
            },
        [51160906] = {
            ["Content"] = "你不是才说自己熬夜难受的吗？怎么提到打骨牌就又精神起来了？",
            ["DialogueId"] = 51160906,
            ["GUID"] = "80137224",
            ["NextDialogue"] = 51160907,
            ["SpeakNpcId"] = 701157,
            },
        [51160907] = {
            ["Content"] = "不是一回事，你就说打不打吧？陈老太太上次还输我一根簪子，这次不知道又要输些什么。",
            ["DialogueId"] = 51160907,
            ["GUID"] = "8013724E",
            ["NextDialogue"] = 51160908,
            ["SpeakNpcName"] = "UI_NPC_Name_wangxiulian_Sce",
            },
        [51160908] = {
            ["Content"] = "打！我这就去叫人！",
            ["DialogueId"] = 51160908,
            ["GUID"] = "80137278",
            ["SpeakNpcId"] = 701157,
            },
        [51160909] = {
            ["Content"] = "叫上陈老太太，咱们也在家里聚上一聚，打打骨牌？",
            ["DialogueId"] = 51160909,
            ["GUID"] = "80137151",
            ["NextDialogue"] = 51160901,
            ["SpeakNpcId"] = 701157,
            },
        [51161001] = {
            ["Content"] = "我不要回家！我要在外面跟棠豆玩！我不要看书，我不要练字！不要！",
            ["DialogueId"] = 51161001,
            ["GUID"] = "801381BA",
            ["NextDialogue"] = 51161002,
            ["SpeakNpcId"] = 701159,
            },
        [51161002] = {
            ["Content"] = "棠豆回回拿前三，你呢？回回倒数第一。先生几次找我过去谈话，说我在家对你放任自流，不管不顾。",
            ["DialogueId"] = 51161002,
            ["GUID"] = "801381E4",
            ["NextDialogue"] = 51161003,
            ["SpeakNpcId"] = 701158,
            },
        [51161003] = {
            ["Content"] = "我真——我真恨不得抽你一顿！",
            ["DialogueId"] = 51161003,
            ["GUID"] = "8013820E",
            ["NextOptions"] = {
                [1] = 51161004,
                [2] = 51161005,
                },
            ["SpeakNpcId"] = 701158,
            },
        [51161004] = {
            ["Content"] = "不可以！",
            ["DialogueId"] = 51161004,
            ["GUID"] = "80138238",
            ["ImprPlusId"] = 1207,
            ["NextDialogue"] = 51161006,
            },
        [51161005] = {
            ["Content"] = "嘿嘿，打小孩咯。",
            ["DialogueId"] = 51161005,
            ["GUID"] = "80138262",
            ["ImprPlusId"] = 1210,
            ["NextDialogue"] = 51161006,
            },
        [51161006] = {
            ["Content"] = "（母亲因为愤怒而高高扬起的手，却始终悬于半空没有落下来，犹豫再三，她还是将手放了下去。）",
            ["DialogueId"] = 51161006,
            ["GUID"] = "8013828C",
            ["NextDialogue"] = 51161007,
            },
        [51161007] = {
            ["Content"] = "你这混账孩子！诶！",
            ["DialogueId"] = 51161007,
            ["GUID"] = "801382B6",
            ["NextDialogue"] = 51161008,
            ["SpeakNpcId"] = 701158,
            },
        [51161008] = {
            ["Content"] = "娘……",
            ["DialogueId"] = 51161008,
            ["GUID"] = "801382E0",
            ["NextDialogue"] = 51161009,
            ["SpeakNpcId"] = 701159,
            },
        [51161009] = {
            ["Content"] = "算了算了，去找你那帮狐朋狗友玩吧，记得早点回家。",
            ["DialogueId"] = 51161009,
            ["GUID"] = "8013830A",
            ["NextDialogue"] = 51161010,
            ["SpeakNpcId"] = 701158,
            },
        [51161010] = {
            ["Content"] = "谢谢娘！娘是全天下最好的娘亲！",
            ["DialogueId"] = 51161010,
            ["GUID"] = "80138334",
            ["NextDialogue"] = 51161011,
            ["SpeakNpcId"] = 701159,
            },
        [51161011] = {
            ["Content"] = "（他一溜烟跑了个没影。）",
            ["DialogueId"] = 51161011,
            ["GUID"] = "8013835E",
            },
        [51161012] = {
            ["Content"] = "一天到晚就只知道出去玩，功课写得像鬼画符，一张纸上愣是看不懂一个字。",
            ["DialogueId"] = 51161012,
            ["GUID"] = "80138388",
            ["NextDialogue"] = 51161013,
            ["SpeakNpcId"] = 701158,
            },
        [51161013] = {
            ["Content"] = "这是什么啊？春眠不觉晓的下一句……夏天睡不着？这都什么乱七八糟的！真得好好修理他一顿了！",
            ["DialogueId"] = 51161013,
            ["GUID"] = "801383B2",
            ["NextOptions"] = {
                [1] = 51161014,
                },
            ["SpeakNpcId"] = 701158,
            },
        [51161014] = {
            ["Content"] = "你说的修理是指？",
            ["DialogueId"] = 51161014,
            ["GUID"] = "801383DC",
            ["NextDialogue"] = 51161015,
            },
        [51161015] = {
            ["Content"] = "干嘛这么看我？你以为我要揍他吗？我告诉你，大风九章可不允许随意伤人。",
            ["DialogueId"] = 51161015,
            ["GUID"] = "80138406",
            ["NextOptions"] = {
                [1] = 51161016,
                [2] = 51161017,
                },
            ["SpeakNpcId"] = 701158,
            },
        [51161016] = {
            ["Content"] = "我没这么想。",
            ["DialogueId"] = 51161016,
            ["GUID"] = "80138430",
            ["NextDialogue"] = 51161018,
            },
        [51161017] = {
            ["Content"] = "要是没有大风九章是不是真要揍他了？",
            ["DialogueId"] = 51161017,
            ["GUID"] = "8013845A",
            ["NextDialogue"] = 51161018,
            },
        [51161018] = {
            ["Content"] = "只要你来辅导他一次功课，你也会气到牙根发痒。",
            ["DialogueId"] = 51161018,
            ["GUID"] = "80138484",
            ["NextDialogue"] = 51161019,
            ["SpeakNpcId"] = 701158,
            },
        [51161019] = {
            ["Content"] = "之前算学先生留了一道题，他在那掰了半天手指也没算出来，题目是说：六个有龙氏去集市，每人买了八条鱼，问一共带回来几条鱼？",
            ["DialogueId"] = 51161019,
            ["GUID"] = "801384AE",
            ["NextOptions"] = {
                [1] = 51161020,
                [2] = 51161022,
                },
            ["SpeakNpcId"] = 701158,
            },
        [51161020] = {
            ["Content"] = "48条！",
            ["DialogueId"] = 51161020,
            ["GUID"] = "801384D8",
            ["NextDialogue"] = 51161021,
            },
        [51161021] = {
            ["Content"] = "对了！我家那个要是有你一半聪明就好了！",
            ["DialogueId"] = 51161021,
            ["GUID"] = "80138502",
            ["NextDialogue"] = 51161024,
            ["SpeakNpcId"] = 701158,
            },
        [51161022] = {
            ["Content"] = "999条！",
            ["DialogueId"] = 51161022,
            ["GUID"] = "8013852C",
            ["NextDialogue"] = 51161023,
            },
        [51161023] = {
            ["Content"] = "你是在跟我开玩笑吧？难不成你的算术也是一塌糊涂？",
            ["DialogueId"] = 51161023,
            ["GUID"] = "80138556",
            ["NextDialogue"] = 51161024,
            ["SpeakNpcId"] = 701158,
            },
        [51161024] = {
            ["Content"] = "我家那混账小子，先是盯着书本发了半个时辰的呆，我催了他半天，他才回过神，偷瞄了我一眼。",
            ["DialogueId"] = 51161024,
            ["GUID"] = "80138580",
            ["NextDialogue"] = 51161025,
            ["SpeakNpcId"] = 701158,
            },
        [51161025] = {
            ["Content"] = "我问他，怎么不说话？他便随意掰扯了一个十八，我说不对，他又在那沉思半天，说二十八。",
            ["DialogueId"] = 51161025,
            ["GUID"] = "801385AA",
            ["NextDialogue"] = 51161026,
            ["SpeakNpcId"] = 701158,
            },
        [51161026] = {
            ["Content"] = "真是要把我气笑了，我说你干脆从零开始把每个数字都猜上一遍得了呗？他点点头，说娘说得对。",
            ["DialogueId"] = 51161026,
            ["GUID"] = "801385D4",
            ["NextDialogue"] = 51161027,
            ["SpeakNpcId"] = 701158,
            },
        [51161027] = {
            ["Content"] = "气得我哟……但又有什么办法呢？我只能给他支邪招，我说不行你就把有龙和鱼都画出来，画六个有龙，每个有龙带八条鱼，全画出来之后你再一个个数。",
            ["DialogueId"] = 51161027,
            ["GUID"] = "801385FE",
            ["NextDialogue"] = 51161028,
            ["SpeakNpcId"] = 701158,
            },
        [51161028] = {
            ["Content"] = "你以为这就好了？呵！想起来我现在还来气！他按我说的画了一个有龙，手提两条鱼，肩上挑着两条鱼，脚下踩着两条鱼。",
            ["DialogueId"] = 51161028,
            ["GUID"] = "80138628",
            ["NextOptions"] = {
                [1] = 51161029,
                },
            ["SpeakNpcId"] = 701158,
            },
        [51161029] = {
            ["Content"] = "还差两条呢？",
            ["DialogueId"] = 51161029,
            ["GUID"] = "80138652",
            ["NextDialogue"] = 51161030,
            },
        [51161030] = {
            ["Content"] = "对！我也这么问他，你知道他怎么说的吗？他思来想去半天，说：娘，他没地方拿鱼了！",
            ["DialogueId"] = 51161030,
            ["GUID"] = "8013867C",
            ["NextOptions"] = {
                [1] = 51161031,
                [2] = 51161032,
                },
            ["SpeakNpcId"] = 701158,
            },
        [51161031] = {
            ["Content"] = "你儿子……难不成是天才？",
            ["DialogueId"] = 51161031,
            ["GUID"] = "801386A6",
            ["NextDialogue"] = 51161033,
            },
        [51161032] = {
            ["Content"] = "哈哈哈哈哈哈！",
            ["DialogueId"] = 51161032,
            ["GUID"] = "801386D0",
            ["NextDialogue"] = 51161033,
            },
        [51161033] = {
            ["Content"] = "这一点也不好笑！现在真是想起来气都不打一处来……要我说，大风九章就该给咱们这些家长出些教育免责。",
            ["DialogueId"] = 51161033,
            ["GUID"] = "801386FA",
            ["NextDialogue"] = 51161034,
            ["SpeakNpcId"] = 701158,
            },
        [51161034] = {
            ["Content"] = "好让我在气到要晕过去之前，还能脱下鞋狠狠打他两下屁股解气！",
            ["DialogueId"] = 51161034,
            ["GUID"] = "80138724",
            ["SpeakNpcId"] = 701158,
            },
        [51161035] = {
            ["Content"] = "我看你是蹬鼻子上脸，三天不打上房揭瓦！给我回去复习功课！",
            ["DialogueId"] = 51161035,
            ["GUID"] = "801381BB",
            ["NextDialogue"] = 51161001,
            ["SpeakNpcId"] = 701158,
            },
        [51161101] = {
            ["Content"] = "我来了！不好意思，今天翻墙出来被阿娘逮到了……",
            ["DialogueId"] = 51161101,
            ["GUID"] = "80139222",
            ["NextDialogue"] = 51161102,
            ["SpeakNpcId"] = 701160,
            },
        [51161102] = {
            ["Content"] = "你没挨骂吧？其实如果你娘会骂你的话，你不出来也是可以的。",
            ["DialogueId"] = 51161102,
            ["GUID"] = "8013924C",
            ["NextDialogue"] = 51161103,
            ["SpeakNpcId"] = 701161,
            },
        }
  end },
  { MinKey = 51161103, MaxKey = 51162601, Loader = function()
      return {
        [51161103] = {
            ["Content"] = "那怎么行呢？我们不是说好了每天都要来照顾小猫的吗？我今天给它带了火腿，我娘晒在院子里的。",
            ["DialogueId"] = 51161103,
            ["GUID"] = "80139276",
            ["NextDialogue"] = 51161104,
            ["SpeakNpcId"] = 701160,
            },
        [51161104] = {
            ["Content"] = "诶呀！那是过节吃的！你娘知道了肯定又要骂你了！",
            ["DialogueId"] = 51161104,
            ["GUID"] = "801392A0",
            ["NextDialogue"] = 51161105,
            ["SpeakNpcId"] = 701161,
            },
        [51161105] = {
            ["Content"] = "反正我做什么事她都要骂我的，也不差这一件两件。之前写算学题，明明是她让我算不出就画出来，结果我真画了她又要骂我……",
            ["DialogueId"] = 51161105,
            ["GUID"] = "801392CA",
            ["NextDialogue"] = 51161106,
            ["SpeakNpcId"] = 701160,
            },
        [51161106] = {
            ["Content"] = "为何要骂你？",
            ["DialogueId"] = 51161106,
            ["GUID"] = "801392F4",
            ["NextDialogue"] = 51161107,
            ["SpeakNpcId"] = 701161,
            },
        [51161107] = {
            ["Content"] = "对啊！明明是题的问题，那题说一个有龙氏去集市买八条鱼带回家，哪有这种事？谁家一次要买八条鱼回去吃？一次也拿不下呀。",
            ["DialogueId"] = 51161107,
            ["GUID"] = "8013931E",
            ["NextDialogue"] = 51161108,
            ["SpeakNpcId"] = 701160,
            },
        [51161108] = {
            ["Content"] = "嘻嘻~题目只是先生出的比喻，本质上只是一个题目呀，笨蛋~",
            ["DialogueId"] = 51161108,
            ["GUID"] = "80139348",
            ["NextDialogue"] = 51161109,
            ["SpeakNpcId"] = 701161,
            },
        [51161109] = {
            ["Content"] = "管他呢……反正就是不合常理，算不出来！不过……",
            ["DialogueId"] = 51161109,
            ["GUID"] = "80139372",
            ["NextDialogue"] = 51161110,
            ["SpeakNpcId"] = 701160,
            },
        [51161110] = {
            ["Content"] = "不过什么？",
            ["DialogueId"] = 51161110,
            ["GUID"] = "8013939C",
            ["NextDialogue"] = 51161111,
            ["SpeakNpcId"] = 701161,
            },
        [51161111] = {
            ["Content"] = "小猫可不可以吃八条鱼？要不我们去给小猫带八条鱼吧？",
            ["DialogueId"] = 51161111,
            ["GUID"] = "801393C6",
            ["SpeakNpcId"] = 701160,
            },
        [51161202] = {
            ["Content"] = "明明说好这次让我来当无由生的……",
            ["DialogueId"] = 51161202,
            ["GUID"] = "8013A2B4",
            },
        [51161203] = {
            ["Content"] = "躲在这里一定不会被无由生抓到的！",
            ["DialogueId"] = 51161203,
            ["GUID"] = "8013A2DE",
            },
        [51161204] = {
            ["Content"] = "无由生怎么还不来抓我呀？",
            ["DialogueId"] = 51161204,
            ["GUID"] = "8013A308",
            },
        [51161301] = {
            ["Content"] = "不过比起那些繁杂的数据统计，眼下最急迫的事是——啊！港口消防！我完全忘记了这回事！",
            ["DialogueId"] = 51161301,
            ["GUID"] = "8013B2F2",
            ["NextOptions"] = {
                [1] = 51161302,
                },
            ["SpeakNpcId"] = 701162,
            },
        [51161302] = {
            ["Content"] = "港口消防是什么工作？",
            ["DialogueId"] = 51161302,
            ["GUID"] = "8013B31C",
            ["NextDialogue"] = 51161303,
            },
        [51161303] = {
            ["Content"] = "港口消防……港口消防就是消防呀，还能是什么工作？就像普通的消防工作一样，哪里有火就扑灭哪里。",
            ["DialogueId"] = 51161303,
            ["GUID"] = "8013B346",
            ["NextDialogue"] = 51161304,
            ["SpeakNpcId"] = 701162,
            },
        [51161304] = {
            ["Content"] = "看你的样子，也不像是会问出这么浅显的问题呀？哦！我知道了！你一定是想知道，港口明明最靠近水域，为什么需要消防工作，是不是？",
            ["DialogueId"] = 51161304,
            ["GUID"] = "8013B370",
            ["NextOptions"] = {
                [1] = 51161305,
                [2] = 51161310,
                [3] = 51161317,
                },
            ["SpeakNpcId"] = 701162,
            },
        [51161305] = {
            ["Content"] = "是我想问的。",
            ["DialogueId"] = 51161305,
            ["GUID"] = "8013B39A",
            ["NextDialogue"] = 51161306,
            },
        [51161306] = {
            ["Content"] = "果然还是我神机妙算！这个问题呢……怎么说呢，一部分原因是历史遗留。皓京的参商港建立时间较早，当年没怎么考虑过规划的问题。",
            ["DialogueId"] = 51161306,
            ["GUID"] = "8013B3C4",
            ["NextDialogue"] = 51161307,
            ["SpeakNpcId"] = 701162,
            },
        [51161307] = {
            ["Content"] = "所以岸边仓库建筑间隔十分密集，一旦火势传播极难快速控制。即使请上一堆擅长仙术的有龙氏来，一时半会也控制不住。",
            ["DialogueId"] = 51161307,
            ["GUID"] = "8013B3EE",
            ["NextDialogue"] = 51161308,
            ["SpeakNpcId"] = 701162,
            },
        [51161308] = {
            ["Content"] = "再加上咱们华胥人最离不开的就是香料，而港口仓库多半也是放香料的，还有一些丝绸木材油纸之类，都是一个火星子就能快速引燃的物件。",
            ["DialogueId"] = 51161308,
            ["GUID"] = "8013B418",
            ["NextDialogue"] = 51161309,
            ["SpeakNpcId"] = 701162,
            },
        [51161309] = {
            ["Content"] = "这要是哪个不长眼的笨蛋一不小心忘了吹熄日常奉香……诶呀……想想就很可怕了！",
            ["DialogueId"] = 51161309,
            ["GUID"] = "8013B442",
            ["SpeakNpcId"] = 701162,
            },
        [51161310] = {
            ["Content"] = "我是想问消防工作的具体内容。",
            ["DialogueId"] = 51161310,
            ["GUID"] = "8013B46C",
            ["NextDialogue"] = 51161311,
            },
        [51161311] = {
            ["Content"] = "原来是这样啊？等等——你怎么会问这种专业的问题？难不成……你是上面派下来日常考察我的家伙？看起来也不像呀……",
            ["DialogueId"] = 51161311,
            ["GUID"] = "8013B496",
            ["NextDialogue"] = 51161312,
            ["SpeakNpcId"] = 701162,
            },
        [51161312] = {
            ["Content"] = "算了，不纠结这些，反正像我这样的天才是不会被轻易问倒的！",
            ["DialogueId"] = 51161312,
            ["GUID"] = "8013B4C0",
            ["NextDialogue"] = 51161313,
            ["SpeakNpcId"] = 701162,
            },
        [51161313] = {
            ["Content"] = "消防工作还能是什么，预防、扑救加善后，不就是这些。参商港的工作麻烦在以前大家并没有预防的意识。",
            ["DialogueId"] = 51161313,
            ["GUID"] = "8013B4EA",
            ["NextDialogue"] = 51161314,
            ["SpeakNpcId"] = 701162,
            },
        [51161314] = {
            ["Content"] = "不过新上任那位奏书使大人很重视，毕竟之前是起过一场大火嘛……现在我们筹备了一批巡夜人，每天晚上在港口区域巡逻，预防灾情。",
            ["DialogueId"] = 51161314,
            ["GUID"] = "8013B514",
            ["NextDialogue"] = 51161315,
            ["SpeakNpcId"] = 701162,
            },
        [51161315] = {
            ["Content"] = "后面又重建了一大批仓库，拆了好些棚屋，还给易燃的灯油专门建了特殊墙体仓库，最近又在请匠矩阁的师傅们帮忙掘池掘井，改良水龙车。",
            ["DialogueId"] = 51161315,
            ["GUID"] = "8013B53E",
            ["NextDialogue"] = 51161316,
            ["SpeakNpcId"] = 701162,
            },
        [51161316] = {
            ["Content"] = "总之，差不多就是这样了，不过后续的工作我们还在更进呢，你要是有什么好点子，也可以给泉通阁信箱投建议信，我们是有专人处理的~",
            ["DialogueId"] = 51161316,
            ["GUID"] = "8013B568",
            ["SpeakNpcId"] = 701162,
            },
        [51161317] = {
            ["Content"] = "我的意思是这种工作为什么现在才做？",
            ["DialogueId"] = 51161317,
            ["GUID"] = "8013B592",
            ["NextDialogue"] = 51161318,
            },
        [51161318] = {
            ["Content"] = "额……这个……这个嘛……你也知道，皓京城可是有着千年历史的古城，早年在修建参商港的时候，大家确实没有那方面的意识……",
            ["DialogueId"] = 51161318,
            ["GUID"] = "8013B5BC",
            ["NextDialogue"] = 51161319,
            ["SpeakNpcId"] = 701162,
            },
        [51161319] = {
            ["Content"] = "不过也不是完全没有，只是原先的许多消防站因为经年不用失效或者报废或者水力太小之类的……毕竟是偶发性的事件嘛……",
            ["DialogueId"] = 51161319,
            ["GUID"] = "8013B5E6",
            ["NextDialogue"] = 51161320,
            ["SpeakNpcId"] = 701162,
            },
        [51161320] = {
            ["Content"] = "前几年，不知道为什么，起了一场大火，好像是一些外来商船来皓京参观奉香大典，批发了一大批香料，结果却……",
            ["DialogueId"] = 51161320,
            ["GUID"] = "8013B610",
            ["NextDialogue"] = 51161321,
            ["SpeakNpcId"] = 701162,
            },
        [51161321] = {
            ["Content"] = "总之，现在每到奉香大典，我们就要重新检查翻修一遍港口的消防设施，预防再出现那样的事故。",
            ["DialogueId"] = 51161321,
            ["GUID"] = "8013B63A",
            ["SpeakNpcId"] = 701162,
            },
        [51161322] = {
            ["Content"] = "今年的税账至今还在统计之中，明年的汇算眼见着也要来了……真是忙到头晕眼花。",
            ["DialogueId"] = 51161322,
            ["GUID"] = "8013B2F1",
            ["NextDialogue"] = 51161301,
            ["SpeakNpcId"] = 701162,
            },
        [51161401] = {
            ["Content"] = "昨夜通宵整理典籍，今日双眼昏花，恐一蹬腿就要去往虞泉了！",
            ["DialogueId"] = 51161401,
            ["GUID"] = "8013C35A",
            ["NextDialogue"] = 51161402,
            ["SpeakNpcId"] = 701163,
            },
        [51161402] = {
            ["Content"] = "想来之前刚入泉通阁之时，看到李兄每日煮药，那时还觉得他老气横秋……现在想来，还是他有先见之明啊！",
            ["DialogueId"] = 51161402,
            ["GUID"] = "8013C384",
            ["NextDialogue"] = 51161403,
            ["SpeakNpcId"] = 701163,
            },
        [51161403] = {
            ["Content"] = "看来我也得抽空去趟泽生阁，开一剂养生良药，好保我这条小命能多过些日子。",
            ["DialogueId"] = 51161403,
            ["GUID"] = "8013C3AE",
            ["NextOptions"] = {
                [1] = 51161404,
                [2] = 51161408,
                [3] = 51161413,
                },
            ["SpeakNpcId"] = 701163,
            },
        [51161404] = {
            ["Content"] = "泉通阁的工作很累吗？",
            ["DialogueId"] = 51161404,
            ["GUID"] = "8013C3D8",
            ["NextDialogue"] = 51161405,
            },
        [51161405] = {
            ["Content"] = "诶呀……您这话问得……我都不知道该怎么回答好了。累是自然累的，但倒也不是像体力活那般伤筋动骨，动不动这里擦伤那里扭伤之类的。",
            ["DialogueId"] = 51161405,
            ["GUID"] = "8013C402",
            ["NextDialogue"] = 51161406,
            ["SpeakNpcId"] = 701163,
            },
        [51161406] = {
            ["Content"] = "而是大多数时间要与各式各样的人交流沟通，一日内还要连续审阅核算诸多繁杂数据，要是一个不小心算差了……",
            ["DialogueId"] = 51161406,
            ["GUID"] = "8013C42C",
            ["NextDialogue"] = 51161407,
            ["SpeakNpcId"] = 701163,
            },
        [51161407] = {
            ["Content"] = "噫……不愿想起！不愿提及！",
            ["DialogueId"] = 51161407,
            ["GUID"] = "8013C456",
            ["SpeakNpcId"] = 701163,
            },
        [51161408] = {
            ["Content"] = "泽生阁不是看病的吗？",
            ["DialogueId"] = 51161408,
            ["GUID"] = "8013C480",
            ["NextDialogue"] = 51161409,
            },
        [51161409] = {
            ["Content"] = "这话说得，头疼脑热是病，操劳忙碌不也是病嘛，泽生阁的医师们可有创新精神了，针对不同年龄段的不同需求都出了特需药方，方便大家选购。",
            ["DialogueId"] = 51161409,
            ["GUID"] = "8013C4AA",
            ["NextDialogue"] = 51161410,
            ["SpeakNpcId"] = 701163,
            },
        [51161410] = {
            ["Content"] = "比如对于刻苦求学的学子，就出了一些明目利脑的丸子，方便服用；像我们这种苦于案牍劳苦的成年人，就把消乏的药饮做成小袋装，每日只需加热便可服用。",
            ["DialogueId"] = 51161410,
            ["GUID"] = "8013C4D4",
            ["NextDialogue"] = 51161411,
            ["SpeakNpcId"] = 701163,
            },
        [51161411] = {
            ["Content"] = "当然，还有老人往往会喜欢买些大补之物，但空口吃又不好，泽生阁便出了代加工，比如把阿胶什么的做成糕点……",
            ["DialogueId"] = 51161411,
            ["GUID"] = "8013C4FE",
            ["NextDialogue"] = 51161412,
            ["SpeakNpcId"] = 701163,
            },
        [51161412] = {
            ["Content"] = "家妻买过几次，我尝了，味道还挺好吃，要不是她拦着，我都当零嘴吃了。",
            ["DialogueId"] = 51161412,
            ["GUID"] = "8013C528",
            ["SpeakNpcId"] = 701163,
            },
        [51161413] = {
            ["Content"] = "再见。",
            ["DialogueId"] = 51161413,
            ["GUID"] = "8013C552",
            ["NextDialogue"] = 51161414,
            },
        [51161414] = {
            ["Content"] = "你要不要也去开点药？我看你面色有些苍白，不知道是衣服衬的还是贫血，以防万一，也该补补了。",
            ["DialogueId"] = 51161414,
            ["GUID"] = "8013C57C",
            ["SpeakNpcId"] = 701163,
            },
        [51161501] = {
            ["Content"] = "停停停！畅想你的美好假期之前，能不能先把奉香大典的一堆活儿干完？",
            ["DialogueId"] = 51161501,
            ["GUID"] = "8013D3C2",
            ["NextDialogue"] = 51161502,
            ["SpeakNpcName"] = "UI_NPC_Name_linxia_Sce",
            },
        [51161502] = {
            ["Content"] = "不行了不行了……我的思绪已经飞出泉通阁了，我的魂灵已经乘着啾啾莺的翅膀，飞过湖泊，飞过高山，飞到太皓神君身边了！",
            ["DialogueId"] = 51161502,
            ["GUID"] = "8013D3EC",
            ["NextDialogue"] = 51161503,
            ["SpeakNpcId"] = 701164,
            },
        [51161503] = {
            ["Content"] = "好……你飞到太皓神君身边的时候，记得问问今年才采购的节货他是否满意，再问问你落下的这些活能不能让神君帮忙做完。",
            ["DialogueId"] = 51161503,
            ["GUID"] = "8013D416",
            ["NextDialogue"] = 51161504,
            ["SpeakNpcName"] = "UI_NPC_Name_linxia_Sce",
            },
        [51161504] = {
            ["Content"] = "好你个临夏，居然敢让神君帮我们干活！",
            ["DialogueId"] = 51161504,
            ["GUID"] = "8013D440",
            ["NextDialogue"] = 51161505,
            ["SpeakNpcId"] = 701164,
            },
        [51161505] = {
            ["Content"] = "诶？你搞错了，不是我让神君帮我们干活，是你明明还有一堆事情等着去做，却非要在这里畅想未来。",
            ["DialogueId"] = 51161505,
            ["GUID"] = "8013D46A",
            ["NextDialogue"] = 51161506,
            ["SpeakNpcName"] = "UI_NPC_Name_linxia_Sce",
            },
        [51161506] = {
            ["Content"] = "嘁——你明明年纪轻轻，却死板得跟个老古董一样，玩笑也开不得，现在不是出来透透气的时候嘛！",
            ["DialogueId"] = 51161506,
            ["GUID"] = "8013D494",
            ["SpeakNpcId"] = 701164,
            },
        [51161507] = {
            ["Content"] = "奉香大典意味着什么？意味着休假呀！我一直想去海伯利亚看雪……",
            ["DialogueId"] = 51161507,
            ["GUID"] = "8013D3C1",
            ["NextDialogue"] = 51161501,
            ["SpeakNpcId"] = 701164,
            },
        [51161601] = {
            ["Content"] = "这般数据出现在这栏不太应当，莫非是填错了？",
            ["DialogueId"] = 51161601,
            ["GUID"] = "8013E42A",
            ["NextDialogue"] = 51161602,
            ["SpeakNpcId"] = 701165,
            },
        [51161602] = {
            ["Content"] = "不应当吧，那措施出了之后，按理说是应该没有不来登记的居民和商贩了。",
            ["DialogueId"] = 51161602,
            ["GUID"] = "8013E454",
            ["NextOptions"] = {
                [1] = 51161603,
                [2] = 51161607,
                },
            ["SpeakNpcId"] = 701165,
            },
        [51161603] = {
            ["Content"] = "为什么会不来登记？",
            ["DialogueId"] = 51161603,
            ["GUID"] = "8013E47E",
            ["NextDialogue"] = 51161604,
            },
        [51161604] = {
            ["Content"] = "大多是因为麻烦，只是来皓京短暂工作一段时间，如果不是涉及到落户安家之类的大事，很少会主动来泉通阁登记。",
            ["DialogueId"] = 51161604,
            ["GUID"] = "8013E4A8",
            ["NextDialogue"] = 51161605,
            ["SpeakNpcId"] = 701165,
            },
        [51161605] = {
            ["Content"] = "哪怕是我们挨家挨户上门询问，也会出现一些——出门工作旅游一类的状况，出现误差。",
            ["DialogueId"] = 51161605,
            ["GUID"] = "8013E4D2",
            ["NextDialogue"] = 51161606,
            ["SpeakNpcId"] = 701165,
            },
        [51161606] = {
            ["Content"] = "至于商户……那就更简单了，毕竟皓京的商人们需要按期缴纳市籍税，如果不登记，自然就少交了这一笔。",
            ["DialogueId"] = 51161606,
            ["GUID"] = "8013E4FC",
            ["NextOptions"] = {
                [1] = 51161614,
                },
            ["SpeakNpcId"] = 701165,
            },
        [51161607] = {
            ["Content"] = "什么措施？",
            ["DialogueId"] = 51161607,
            ["GUID"] = "8013E526",
            ["NextDialogue"] = 51161608,
            },
        [51161608] = {
            ["Content"] = "唔……其实说起来很简单，就是我们和祀烟阁的香官说了一声，凡是登记了身份的居民，每日去祀烟阁奉香时，可额外领取一柱奉君香。",
            ["DialogueId"] = 51161608,
            ["GUID"] = "8013E550",
            ["NextDialogue"] = 51161609,
            ["SpeakNpcId"] = 701165,
            },
        [51161609] = {
            ["Content"] = "虽说也不是什么十分名贵的香，但是大家本着有便宜不占白不占的心态——我好像不该……算了！我什么也没说！你刚才什么都没有听到！",
            ["DialogueId"] = 51161609,
            ["GUID"] = "8013E57A",
            ["NextOptions"] = {
                [1] = 51161610,
                },
            ["SpeakNpcId"] = 701165,
            },
        [51161610] = {
            ["Content"] = "你们怎么区分登记过和没有登记的人？",
            ["DialogueId"] = 51161610,
            ["GUID"] = "8013E5A4",
            ["NextDialogue"] = 51161611,
            },
        [51161611] = {
            ["Content"] = "这……这就要归功于一种神奇的术法了。我们拜托了悬衡派的分香官，为登记的居民身上印上与其他香料不同的独特的气味。",
            ["DialogueId"] = 51161611,
            ["GUID"] = "8013E5CE",
            ["NextDialogue"] = 51161612,
            ["SpeakNpcId"] = 701165,
            },
        [51161612] = {
            ["Content"] = "这种气味寻常人分辨不出来，但擅长分香术的则可以一眼看出，毕竟修习分香术的第一课就是识香嘛~",
            ["DialogueId"] = 51161612,
            ["GUID"] = "8013E5F8",
            ["NextDialogue"] = 51161613,
            ["SpeakNpcId"] = 701165,
            },
        [51161613] = {
            ["Content"] = "但这种术法的持续时间并不会太久，约莫两三个月就会淡去。但好在皓京的居民对于每日奉香一事十分推崇，在期限之内可以再次去祀烟阁那处补上。",
            ["DialogueId"] = 51161613,
            ["GUID"] = "8013E622",
            ["NextOptions"] = {
                [1] = 51161614,
                },
            ["SpeakNpcId"] = 701165,
            },
        [51161614] = {
            ["Content"] = "我先走了。",
            ["DialogueId"] = 51161614,
            ["GUID"] = "8013E64C",
            ["NextDialogue"] = 51161615,
            },
        [51161615] = {
            ["Content"] = "你要是准备在皓京久居，提前来泉通阁办理户籍。现在可以加赠太皓神君定制款棉花娃娃，怎么样？心动不如行动吧！",
            ["DialogueId"] = 51161615,
            ["GUID"] = "8013E676",
            ["SpeakNpcId"] = 701165,
            },
        [51161701] = {
            ["Content"] = "这不是想着你们日理万机，这些小忙小乱的我们自己解决了也便罢了……不给你们添麻烦……",
            ["DialogueId"] = 51161701,
            ["GUID"] = "8013F492",
            ["NextDialogue"] = 51161702,
            ["SpeakNpcName"] = "UI_NPC_Name_yuxian_Sce",
            },
        [51161702] = {
            ["Content"] = "如果真的是你们自己能解决了倒也还好，问题是……",
            ["DialogueId"] = 51161702,
            ["GUID"] = "8013F4BC",
            ["NextDialogue"] = 51161703,
            ["SpeakNpcId"] = 701166,
            },
        [51161703] = {
            ["Content"] = "你就说这口井，你们要是发现没水了就来找我们，现在早就通了，结果呢？偏要自己挖，现在好了，把邻居墙跟挖通了，塌下来还砸到了人！",
            ["DialogueId"] = 51161703,
            ["GUID"] = "8013F4E6",
            ["NextDialogue"] = 51161704,
            ["SpeakNpcId"] = 701166,
            },
        [51161704] = {
            ["Content"] = "这……这实在是无心之举……我也没想到我的方向感能这么差，我分明是想往下挖的……",
            ["DialogueId"] = 51161704,
            ["GUID"] = "8013F510",
            ["NextDialogue"] = 51161705,
            ["SpeakNpcName"] = "UI_NPC_Name_yuxian_Sce",
            },
        [51161705] = {
            ["Content"] = "无论怎么说，以后遇事第一时间就来找泉通阁，我们一定第一时间帮你们解决，不要自己瞎折腾了！",
            ["DialogueId"] = 51161705,
            ["GUID"] = "8013F53A",
            ["SpeakNpcId"] = 701166,
            },
        [51161706] = {
            ["Content"] = "下次遇到这种事情记得早些来泉通阁，硬拖只会让事态恶化。",
            ["DialogueId"] = 51161706,
            ["GUID"] = "8013F491",
            ["NextDialogue"] = 51161701,
            ["SpeakNpcId"] = 701166,
            },
        [51161801] = {
            ["Content"] = "你不知道？哦对，前段时间你休沐不在，他们来申请时你没见到。",
            ["DialogueId"] = 51161801,
            ["GUID"] = "801404FA",
            ["NextDialogue"] = 51161802,
            ["SpeakNpcId"] = 701167,
            },
        [51161802] = {
            ["Content"] = "他们说，烛阴之灾未平，为了安定民心，今年的奉香大典要办的更加隆重。",
            ["DialogueId"] = 51161802,
            ["GUID"] = "80140524",
            ["NextDialogue"] = 51161803,
            ["SpeakNpcId"] = 701167,
            },
        [51161803] = {
            ["Content"] = "比如说……皓京城内的沉月香，往年只是从普通香农那边收吿苍，今年要专门从园子里收。",
            ["DialogueId"] = 51161803,
            ["GUID"] = "8014054E",
            ["NextDialogue"] = 51161804,
            ["SpeakNpcId"] = 701167,
            },
        [51161804] = {
            ["Content"] = "那些园子里种的吿苍都是优质货，成本要翻好几倍吧……",
            ["DialogueId"] = 51161804,
            ["GUID"] = "80140578",
            ["NextDialogue"] = 51161805,
            ["SpeakNpcId"] = 701260,
            },
        [51161805] = {
            ["Content"] = "所以原本的预算不够了，不过好在今年的年收确实不错。",
            ["DialogueId"] = 51161805,
            ["GUID"] = "801405A2",
            ["NextDialogue"] = 51161806,
            ["SpeakNpcId"] = 701167,
            },
        [51161806] = {
            ["Content"] = "因为海外贸易生意做的大，所以商税收入繁荣，也吸引来了更多游客。但吸引来更多游客，所以奉香大典便要办得优质些，好给来宾留下更好的印象。",
            ["DialogueId"] = 51161806,
            ["GUID"] = "801405CC",
            ["NextDialogue"] = 51161807,
            ["SpeakNpcId"] = 701167,
            },
        [51161807] = {
            ["Content"] = "行啦行啦，简直要给我绕晕了。既然他们祀烟阁铆足了劲要办个隆重的大典，那我们泉通阁也不能落于人后。",
            ["DialogueId"] = 51161807,
            ["GUID"] = "801405F6",
            ["NextDialogue"] = 51161808,
            ["SpeakNpcId"] = 701260,
            },
        [51161808] = {
            ["Content"] = "所以说——趁此机会，出个更详细的大典计划吧？",
            ["DialogueId"] = 51161808,
            ["GUID"] = "80140620",
            ["SpeakNpcId"] = 701260,
            },
        [51161809] = {
            ["Content"] = "前脚刚和我一起写了申请奉香大典流程优化的报告，后脚居然卧病不起了……",
            ["DialogueId"] = 51161809,
            ["GUID"] = "8014064A",
            ["NextDialogue"] = 51161810,
            ["SpeakNpcId"] = 701260,
            },
        [51161810] = {
            ["Content"] = "现在这事直接落到了我头上，哎呀……真是难办……",
            ["DialogueId"] = 51161810,
            ["GUID"] = "80140674",
            ["NextOptions"] = {
                [1] = 51161811,
                [2] = 51161814,
                },
            ["SpeakNpcId"] = 701260,
            },
        [51161811] = {
            ["Content"] = "太不靠谱了吧！",
            ["DialogueId"] = 51161811,
            ["GUID"] = "8014069E",
            ["NextDialogue"] = 51161812,
            },
        [51161812] = {
            ["Content"] = "诶……怎么说呢……这也没办法。这家伙的身体本就不好，这么一说我又想起来，前段时间他休沐也是因为旧疾发作。",
            ["DialogueId"] = 51161812,
            ["GUID"] = "801406C8",
            ["NextDialogue"] = 51161813,
            ["SpeakNpcId"] = 701260,
            },
        [51161813] = {
            ["Content"] = "这么一想，过段时间还是买些补品去看看他好了……",
            ["DialogueId"] = 51161813,
            ["GUID"] = "801406F2",
            ["SpeakNpcId"] = 701260,
            },
        [51161814] = {
            ["Content"] = "什么事情这么难办？",
            ["DialogueId"] = 51161814,
            ["GUID"] = "8014071C",
            ["NextDialogue"] = 51161815,
            },
        [51161815] = {
            ["Content"] = "你知道奉香大典吗？就是对咱们华胥人来说四年一度最重要的节日。",
            ["DialogueId"] = 51161815,
            ["GUID"] = "80140746",
            ["NextDialogue"] = 51161816,
            ["SpeakNpcId"] = 701260,
            },
        [51161816] = {
            ["Content"] = "今年祀烟阁提议，想将奉香大典办的隆重些，我们报了上去后，上面也同意了这个想法，但到具体的步骤……",
            ["DialogueId"] = 51161816,
            ["GUID"] = "80140770",
            ["NextDialogue"] = 51161817,
            ["SpeakNpcId"] = 701260,
            },
        [51161817] = {
            ["Content"] = "毕竟不是我提出的意见，现在的确是摸不着头脑。诶？你应该是异国来客？从你的角度，你觉得节日大典上出现什么会让你感到有趣？",
            ["DialogueId"] = 51161817,
            ["GUID"] = "8014079A",
            ["SpeakNpcId"] = 701260,
            },
        [51161818] = {
            ["Content"] = "可爱吸睛的吉祥物。",
            ["DialogueId"] = 51161818,
            ["GUID"] = "801407C4",
            ["NextDialogue"] = 51161819,
            },
        [51161819] = {
            ["Content"] = "吉祥物？意思是能带来吉祥的物件吗？吸睛这一点我倒是理解，但为什么要可爱呢？",
            ["DialogueId"] = 51161819,
            ["GUID"] = "801407EE",
            ["NextDialogue"] = 51161820,
            ["SpeakNpcId"] = 701260,
            },
        [51161820] = {
            ["Content"] = "要说带来吉祥……那可非太皓神君莫属了！但神君可不是我们能随随便便请动的！",
            ["DialogueId"] = 51161820,
            ["GUID"] = "80140818",
            ["SpeakNpcId"] = 701260,
            },
        [51161821] = {
            ["Content"] = "（详细解释吉祥物。）",
            ["DialogueId"] = 51161821,
            ["GUID"] = "80140842",
            ["NextDialogue"] = 51161822,
            },
        [51161822] = {
            ["Content"] = "你是说，吉祥物是一种被人创作出来的可爱玩偶？这这这……华胥可从来没听说过这样的东西？不，不对！偶人！",
            ["DialogueId"] = 51161822,
            ["GUID"] = "8014086C",
            ["NextDialogue"] = 51161823,
            ["SpeakNpcId"] = 701260,
            },
        [51161823] = {
            ["Content"] = "我这就去联系匠矩阁，请他们帮忙设计一款以可爱为特色的可控偶人，这样就可以吸引外来的客人了吧！",
            ["DialogueId"] = 51161823,
            ["GUID"] = "80140896",
            ["SpeakNpcId"] = 701260,
            },
        [51161824] = {
            ["Content"] = "丰富有趣的活动。",
            ["DialogueId"] = 51161824,
            ["GUID"] = "801408C0",
            ["NextDialogue"] = 51161825,
            },
        [51161825] = {
            ["Content"] = "的确，有新意的活动是最吸引人的娱乐项目了，今年我们也准备了一些猜灯谜活动，就在殿前广场那边，参与的居民非常多呢。",
            ["DialogueId"] = 51161825,
            ["GUID"] = "801408EA",
            ["SpeakNpcId"] = 701260,
            },
        [51161826] = {
            ["Content"] = "这活动适合异国人吗？",
            ["DialogueId"] = 51161826,
            ["GUID"] = "80140914",
            ["NextDialogue"] = 51161827,
            },
        [51161827] = {
            ["Content"] = "额……好像……好像……的确是……外国的友人们的确不太了解华胥的人文风情，也就很难猜出一些灯谜……",
            ["DialogueId"] = 51161827,
            ["GUID"] = "8014093E",
            ["NextDialogue"] = 51161828,
            ["SpeakNpcId"] = 701260,
            },
        [51161828] = {
            ["Content"] = "谢谢你的建议啊，好像有点道理。我再琢磨琢磨……",
            ["DialogueId"] = 51161828,
            ["GUID"] = "80140968",
            ["SpeakNpcId"] = 701260,
            },
        [51161829] = {
            ["Content"] = "祀烟阁今年为何额外申请了一笔经费，是作何用处的？",
            ["DialogueId"] = 51161829,
            ["GUID"] = "801404FB",
            ["NextDialogue"] = 51161801,
            ["SpeakNpcId"] = 701260,
            },
        [51162001] = {
            ["Content"] = "你当时去问了？他们有说运这些东西是要做什么用吗？",
            ["DialogueId"] = 51162001,
            ["GUID"] = "801425CA",
            ["NextDialogue"] = 51162002,
            ["SpeakNpcName"] = "UI_NPC_Name_leigu_Sce",
            },
        [51162002] = {
            ["Content"] = "没去，要是去了我现在还来这儿做什么？我那时正在山上捡菌子，弯着身子找着呢，就看到几个人抬着一个大箱子往里面走。",
            ["DialogueId"] = 51162002,
            ["GUID"] = "801425F4",
            ["NextDialogue"] = 51162003,
            ["SpeakNpcId"] = 701168,
            },
        [51162003] = {
            ["Content"] = "我就寻思啊——这平白无故搬东西去山里做什么？总不能是要在里面建寨子吧？",
            ["DialogueId"] = 51162003,
            ["GUID"] = "8014261E",
            ["NextDialogue"] = 51162004,
            ["SpeakNpcId"] = 701168,
            },
        [51162004] = {
            ["Content"] = "是稀奇，但也有可能是今年奉香大典在山里办呢，说不准的，还是去问问司里的官员，看看他们怎么说吧。",
            ["DialogueId"] = 51162004,
            ["GUID"] = "80142648",
            ["SpeakNpcName"] = "UI_NPC_Name_leigu_Sce",
            },
        [51162005] = {
            ["Content"] = "是，就是往西郊那个方向，鬼鬼祟祟的，看起来不像什么好人。",
            ["DialogueId"] = 51162005,
            ["GUID"] = "801425CB",
            ["NextDialogue"] = 51162001,
            ["SpeakNpcId"] = 701168,
            },
        [51162101] = {
            ["Content"] = "西郊西郊西郊，为何几封投诉信，来来回回都在提西郊？",
            ["DialogueId"] = 51162101,
            ["GUID"] = "80143632",
            ["NextDialogue"] = 51162102,
            ["SpeakNpcId"] = 701169,
            },
        [51162102] = {
            ["Content"] = "虽说的确有些要在西郊筹备的事情，也通知了一部分居民，但这投诉信还是纷迭而来……",
            ["DialogueId"] = 51162102,
            ["GUID"] = "8014365C",
            ["NextDialogue"] = 51162103,
            ["SpeakNpcId"] = 701169,
            },
        [51162103] = {
            ["Content"] = "你看，这封，说西郊深夜有人敲敲打打，像是在钉什么铁皮，附近巡林的听到了赶过去，现场却什么动静也没有。",
            ["DialogueId"] = 51162103,
            ["GUID"] = "80143686",
            ["NextDialogue"] = 51162104,
            ["SpeakNpcId"] = 701169,
            },
        [51162104] = {
            ["Content"] = "这封，是个酒楼的伙计，说怀疑有人恶意捉弄他们，让往西郊入口处放几十份伙食，不知道是要孝敬哪路野神仙。",
            ["DialogueId"] = 51162104,
            ["GUID"] = "801436B0",
            ["NextDialogue"] = 51162105,
            ["SpeakNpcId"] = 701169,
            },
        [51162105] = {
            ["Content"] = "条条桩桩，竟全和西郊有关，难不成西郊真出了什么事？",
            ["DialogueId"] = 51162105,
            ["GUID"] = "801436DA",
            ["NextOptions"] = {
                [1] = 51162106,
                [2] = 51162108,
                },
            ["SpeakNpcId"] = 701169,
            },
        [51162106] = {
            ["Content"] = "可能闹无由生了。",
            ["DialogueId"] = 51162106,
            ["GUID"] = "80143704",
            ["NextDialogue"] = 51162107,
            },
        [51162107] = {
            ["Content"] = "无由生……？这种没有科学证据的无稽之谈，怎么可以采信呢。不妥不妥。",
            ["DialogueId"] = 51162107,
            ["GUID"] = "8014372E",
            ["NextOptions"] = {
                [1] = 51162111,
                },
            ["SpeakNpcId"] = 701169,
            },
        [51162108] = {
            ["Content"] = "可能有不法分子！",
            ["DialogueId"] = 51162108,
            ["GUID"] = "80143758",
            ["NextDialogue"] = 51162109,
            },
        [51162109] = {
            ["Content"] = "虽然你肯定是想多了，但是排除一万种错误答案，最离谱的那个说不定就是正确答案。",
            ["DialogueId"] = 51162109,
            ["GUID"] = "80143782",
            ["NextDialogue"] = 51162110,
            ["SpeakNpcId"] = 701169,
            },
        [51162110] = {
            ["Content"] = "但要我说，最多也就是哪个富商兴头来了没有登记就在山中大兴土木这种事。",
            ["DialogueId"] = 51162110,
            ["GUID"] = "801437AC",
            ["NextOptions"] = {
                [1] = 51162111,
                },
            ["SpeakNpcId"] = 701169,
            },
        [51162111] = {
            ["Content"] = "你去看看不就知道了。",
            ["DialogueId"] = 51162111,
            ["GUID"] = "801437D6",
            ["NextDialogue"] = 51162112,
            },
        [51162112] = {
            ["Content"] = "这不是奉香大典前事务繁杂，能去的话我早就去了，还是拜托别人帮忙跑一趟吧。",
            ["DialogueId"] = 51162112,
            ["GUID"] = "80143800",
            ["SpeakNpcId"] = 701169,
            },
        [51162201] = {
            ["Content"] = "快给我来碗茶水，刚从西郊回来，渴死我了！",
            ["DialogueId"] = 51162201,
            ["GUID"] = "8014469A",
            ["NextDialogue"] = 51162202,
            ["SpeakNpcId"] = 701170,
            },
        [51162202] = {
            ["Content"] = "给你——怎么回事？平白无故去西郊做什么？",
            ["DialogueId"] = 51162202,
            ["GUID"] = "801446C4",
            ["NextDialogue"] = 51162203,
            ["SpeakNpcName"] = "UI_NPC_Name_xiangshi_Sce",
            },
        [51162203] = {
            ["Content"] = "喘口气再说……哈！累死我了！还不是最近总有百姓来投诉，说西郊有人鬼鬼祟祟，不知道在做什么，上面就派我过去看看。",
            ["DialogueId"] = 51162203,
            ["GUID"] = "801446EE",
            ["NextDialogue"] = 51162204,
            ["SpeakNpcId"] = 701170,
            },
        [51162204] = {
            ["Content"] = "这么一说我想起来是有这事，我怀疑是不是……飘零……",
            ["DialogueId"] = 51162204,
            ["GUID"] = "80144718",
            ["NextDialogue"] = 51162205,
            ["SpeakNpcName"] = "UI_NPC_Name_xiangshi_Sce",
            },
        [51162205] = {
            ["Content"] = "什么呀！什么都不是！飘零人要想作奸犯科肯定要选在皓京城内，就像之前的那谁谁……放把火烧了个干净。",
            ["DialogueId"] = 51162205,
            ["GUID"] = "80144742",
            ["NextDialogue"] = 51162206,
            ["SpeakNpcId"] = 701170,
            },
        [51162206] = {
            ["Content"] = "说的也是，但华胥的危险分子，除了飘零人还能有谁……所以到底是怎么了？",
            ["DialogueId"] = 51162206,
            ["GUID"] = "8014476C",
            ["NextDialogue"] = 51162207,
            ["SpeakNpcName"] = "UI_NPC_Name_xiangshi_Sce",
            },
        [51162207] = {
            ["Content"] = "真相就是——什么都没有！我绕着山来来回回爬了几圈，什么也没看到，之前我还猜测是有人在山上盖违章建筑。",
            ["DialogueId"] = 51162207,
            ["GUID"] = "80144796",
            ["NextDialogue"] = 51162208,
            ["SpeakNpcId"] = 701170,
            },
        [51162208] = {
            ["Content"] = "结果呢，瓦都不见一个！去时我背了壶水，衣衫也算体面，你看现在！你看我！",
            ["DialogueId"] = 51162208,
            ["GUID"] = "801447C0",
            ["NextDialogue"] = 51162209,
            ["SpeakNpcId"] = 701170,
            },
        [51162209] = {
            ["Content"] = "劳驾你了，那我去帮你跑一趟，和上面说一声。",
            ["DialogueId"] = 51162209,
            ["GUID"] = "801447EA",
            ["NextDialogue"] = 51162210,
            ["SpeakNpcName"] = "UI_NPC_Name_xiangshi_Sce",
            },
        [51162210] = {
            ["Content"] = "行，我得去按按腿，诶哟……抬不起来了，你背我过去先！",
            ["DialogueId"] = 51162210,
            ["GUID"] = "80144814",
            ["SpeakNpcId"] = 701170,
            },
        [51162211] = {
            ["Content"] = "是啊，我从烟津渡运过来的，是你们皓京的一位……画师？画师定的。",
            ["DialogueId"] = 51162211,
            ["GUID"] = "8014483E",
            ["NextDialogue"] = 51162212,
            ["SpeakNpcName"] = "UI_NPC_Name_shige_Sce",
            },
        [51162212] = {
            ["Content"] = "不……等等……你让我理一下思绪，首先，买卖翠屏雀是可以的吗？天禄司的交易规定中有说翠屏雀属于可买卖的物种吗？",
            ["DialogueId"] = 51162212,
            ["GUID"] = "80144868",
            ["NextDialogue"] = 51162213,
            ["SpeakNpcId"] = 701171,
            },
        [51162213] = {
            ["Content"] = "那你这说得——我就是个船夫，你都不知道我怎么知道呢？",
            ["DialogueId"] = 51162213,
            ["GUID"] = "80144892",
            ["NextDialogue"] = 51162214,
            ["SpeakNpcName"] = "UI_NPC_Name_shige_Sce",
            },
        [51162214] = {
            ["Content"] = "但是这事稍微有些棘手了……如果是货物失窃，大风九章自然早已调来狴犴介入。",
            ["DialogueId"] = 51162214,
            ["GUID"] = "801448BC",
            ["NextDialogue"] = 51162215,
            ["SpeakNpcId"] = 701171,
            },
        [51162215] = {
            ["Content"] = "可此时参商港一切如常，这只能说明——那些翠屏雀是自己跑的！",
            ["DialogueId"] = 51162215,
            ["GUID"] = "801448E6",
            ["NextDialogue"] = 51162216,
            ["SpeakNpcId"] = 701171,
            },
        [51162216] = {
            ["Content"] = "这、这可怎么办？那些翠屏雀金贵着呢！难道就放任这些它们在皓京城里乱跑？",
            ["DialogueId"] = 51162216,
            ["GUID"] = "80144910",
            ["NextDialogue"] = 51162217,
            ["SpeakNpcName"] = "UI_NPC_Name_shige_Sce",
            },
        [51162217] = {
            ["Content"] = "您先别急，我想想……这样！我先通知参商港的办事员，让他们帮你留意翠屏雀，然后你那边最好也配合一下，比如提供运输过程中它们的饲料作为诱饵。",
            ["DialogueId"] = 51162217,
            ["GUID"] = "8014493A",
            ["NextDialogue"] = 51162218,
            ["SpeakNpcId"] = 701171,
            },
        [51162218] = {
            ["Content"] = "好好好，就这么办，就这么办！",
            ["DialogueId"] = 51162218,
            ["GUID"] = "80144964",
            ["SpeakNpcName"] = "UI_NPC_Name_shige_Sce",
            },
        [51162219] = {
            ["Content"] = "嗯，是说您负责运输的一船货物在码头丢失了……不是货物？那是……翠屏雀？！",
            ["DialogueId"] = 51162219,
            ["GUID"] = "8014483F",
            ["NextDialogue"] = 51162211,
            ["SpeakNpcId"] = 701171,
            },
        [51162301] = {
            ["Content"] = "船上不可能会有人把它们放出去，压根不会获得什么好处，只是平白添乱罢了。",
            ["DialogueId"] = 51162301,
            ["GUID"] = "80145702",
            ["NextDialogue"] = 51162302,
            ["SpeakNpcId"] = 701172,
            },
        [51162302] = {
            ["Content"] = "可要是说它们是自己跑出去的，未免也有些太过离谱。说来说去不过是鸟类，就算是再有灵气，也不至于一夜成精，学会自己开门？",
            ["DialogueId"] = 51162302,
            ["GUID"] = "8014572C",
            ["NextOptions"] = {
                [1] = 51162303,
                [2] = 51162304,
                },
            ["SpeakNpcId"] = 701172,
            },
        [51162303] = {
            ["Content"] = "鸟类是指？",
            ["DialogueId"] = 51162303,
            ["GUID"] = "80145756",
            ["NextDialogue"] = 51162305,
            },
        [51162304] = {
            ["Content"] = "什么跑出去了？",
            ["DialogueId"] = 51162304,
            ["GUID"] = "80145780",
            ["NextDialogue"] = 51162305,
            },
        [51162305] = {
            ["Content"] = "现在参商港不是应该早就传得沸沸扬扬了？你居然不晓得？我们是从烟津渡来的货运船，几天前，头儿接到一份生意，说要运一批翠屏雀到皓京。",
            ["DialogueId"] = 51162305,
            ["GUID"] = "801457AA",
            ["NextDialogue"] = 51162306,
            ["SpeakNpcId"] = 701172,
            },
        [51162306] = {
            ["Content"] = "那价钱出得极高，接到活第二天，我们一船的伙计都去抓了，好不容易凑齐数量，连赶带围地送上船，又一路颠簸，运到皓京。",
            ["DialogueId"] = 51162306,
            ["GUID"] = "801457D4",
            ["NextDialogue"] = 51162307,
            ["SpeakNpcId"] = 701172,
            },
        [51162307] = {
            ["Content"] = "结果就在昨天，我们船只到港后，头儿要去登记货运物品信息，结果船舶司的人似乎是第一次听说有人运翠屏雀，说什么也不让咱们进皓京。",
            ["DialogueId"] = 51162307,
            ["GUID"] = "801457FE",
            ["NextDialogue"] = 51162308,
            ["SpeakNpcId"] = 701172,
            },
        [51162308] = {
            ["Content"] = "我们没办法，只能在船上歇了一晚上，结果呢，今早一看，那笼子不知道怎么就打开了，里面关着的翠屏雀全跑了！",
            ["DialogueId"] = 51162308,
            ["GUID"] = "80145828",
            ["NextOptions"] = {
                [1] = 51162309,
                [2] = 51162313,
                [3] = 51162318,
                },
            ["SpeakNpcId"] = 701172,
            },
        [51162309] = {
            ["Content"] = "为什么不让进皓京？",
            ["DialogueId"] = 51162309,
            ["GUID"] = "80145852",
            ["NextDialogue"] = 51162310,
            },
        [51162310] = {
            ["Content"] = "原因太多了，随便挑一条就够抓我们去天禄司那喝上两壶。第一，翠屏雀本来就不算在买卖运输的商品之类，当然，在我们之前，也没人做过这生意。",
            ["DialogueId"] = 51162310,
            ["GUID"] = "8014587C",
            ["NextDialogue"] = 51162311,
            ["SpeakNpcId"] = 701172,
            },
        [51162311] = {
            ["Content"] = "第二，鸟都是直肠子，管不住肚子的，它们吃得饱饱的，进了城随地……诶你懂得，总之这不是和人一样，你教它就能会的事情。",
            ["DialogueId"] = 51162311,
            ["GUID"] = "801458A6",
            ["NextDialogue"] = 51162312,
            ["SpeakNpcId"] = 701172,
            },
        [51162312] = {
            ["Content"] = "第三……下这份订单的买家，以及我们，压根就没有想到皓京城居然这么大，咱们之前谁都没有想过翠屏雀到皓京之后要如何运送去目的地。",
            ["DialogueId"] = 51162312,
            ["GUID"] = "801458D0",
            ["SpeakNpcId"] = 701172,
            },
        [51162313] = {
            ["Content"] = "怎么会有人订购翠屏雀？",
            ["DialogueId"] = 51162313,
            ["GUID"] = "801458FA",
            ["NextDialogue"] = 51162314,
            },
        [51162314] = {
            ["Content"] = "有的，华胥之大，无奇不有，我们之前还做过一些运输生意，比如珍猪，你知道吧？",
            ["DialogueId"] = 51162314,
            ["GUID"] = "80145924",
            ["NextDialogue"] = 51162315,
            ["SpeakNpcId"] = 701172,
            },
        [51162315] = {
            ["Content"] = "那是一种肉质很肥美的动物，城里的贵人爱吃。但是翠屏雀……诶，说实话，确实是第一次做这种生意。",
            ["DialogueId"] = 51162315,
            ["GUID"] = "8014594E",
            ["NextDialogue"] = 51162316,
            ["SpeakNpcId"] = 701172,
            },
        [51162316] = {
            ["Content"] = "以前会有专门饲养它们收集掉落尾羽的产业，但是那都是在野外养，没有在城里养的说法。",
            ["DialogueId"] = 51162316,
            ["GUID"] = "80145978",
            ["NextDialogue"] = 51162317,
            ["SpeakNpcId"] = 701172,
            },
        [51162317] = {
            ["Content"] = "你要说收购来吃吧……我虽然没吃过，但是听说肉是酸的，不好吃……不过要是好吃，想必烟津渡也不会漫山遍野都是游荡的野生翠屏雀。",
            ["DialogueId"] = 51162317,
            ["GUID"] = "801459A2",
            ["SpeakNpcId"] = 701172,
            },
        [51162318] = {
            ["Content"] = "它们是怎么逃出去的？",
            ["DialogueId"] = 51162318,
            ["GUID"] = "801459CC",
            ["NextDialogue"] = 51162319,
            },
        [51162319] = {
            ["Content"] = "呵！我正琢磨呢！你看，我们用来运输翠屏雀的，都是这种竖条的铁笼，这边开了门，但会用门闩给关住。",
            ["DialogueId"] = 51162319,
            ["GUID"] = "801459F6",
            ["NextDialogue"] = 51162320,
            ["SpeakNpcId"] = 701172,
            },
        [51162320] = {
            ["Content"] = "要想开门，只有把那门闩逆时针绕上大半圈，再从内向外推开铁门，这样里面的东西才能走出来。",
            ["DialogueId"] = 51162320,
            ["GUID"] = "80145A20",
            ["NextDialogue"] = 51162321,
            ["SpeakNpcId"] = 701172,
            },
        [51162321] = {
            ["Content"] = "你说这能是翠屏雀那小脑袋瓜能琢磨明白的流程吗？绝无可能！",
            ["DialogueId"] = 51162321,
            ["GUID"] = "80145A4A",
            ["NextDialogue"] = 51162322,
            ["SpeakNpcId"] = 701172,
            },
        [51162322] = {
            ["Content"] = "不管怎么说，我都想不到它们自己开门出去的原因，听说赫墨那有可以和动物沟通的能人异士，要是翠屏雀能找回来，拜托他们问问原因就好了……",
            ["DialogueId"] = 51162322,
            ["GUID"] = "80145A74",
            ["SpeakNpcId"] = 701172,
            },
        [51162323] = {
            ["Content"] = "它到底是怎么跑出去的呢？",
            ["DialogueId"] = 51162323,
            ["GUID"] = "80145701",
            ["NextDialogue"] = 51162301,
            ["SpeakNpcId"] = 701172,
            },
        [51162401] = {
            ["Content"] = "有什么比明知道做了没用还不得不做的事情更没意义呢？",
            ["DialogueId"] = 51162401,
            ["GUID"] = "8014676A",
            ["NextOptions"] = {
                [1] = 51162402,
                },
            ["SpeakNpcId"] = 701173,
            },
        [51162402] = {
            ["Content"] = "你在苦恼什么？",
            ["DialogueId"] = 51162402,
            ["GUID"] = "80146794",
            ["NextDialogue"] = 51162403,
            },
        [51162403] = {
            ["Content"] = "苦恼？我可没苦恼，我只是觉得我现在做的事情太没有意义了，大家都应该把宝贵的时间用在更有价值的事情上不是吗？",
            ["DialogueId"] = 51162403,
            ["GUID"] = "801467BE",
            ["NextDialogue"] = 51162404,
            ["SpeakNpcId"] = 701173,
            },
        [51162404] = {
            ["Content"] = "而不是在这偌大的皓京城里，寻找六只丢失的翠屏雀，简直荒谬至极！",
            ["DialogueId"] = 51162404,
            ["GUID"] = "801467E8",
            ["NextOptions"] = {
                [1] = 51162405,
                [2] = 51162407,
                [3] = 51162410,
                },
            ["SpeakNpcId"] = 701173,
            },
        [51162405] = {
            ["Content"] = "你觉得更有价值的事情是什么？",
            ["DialogueId"] = 51162405,
            ["GUID"] = "80146812",
            ["NextDialogue"] = 51162406,
            },
        [51162406] = {
            ["Content"] = "好不容易到了皓京，不是应该去逛逛东市，吃吃美食，去祀烟阁奉香，去执律阁参拜神君吗？",
            ["DialogueId"] = 51162406,
            ["GUID"] = "8014683C",
            ["SpeakNpcId"] = 701173,
            },
        [51162407] = {
            ["Content"] = "找不到没法交差吧？",
            ["DialogueId"] = 51162407,
            ["GUID"] = "80146866",
            ["NextDialogue"] = 51162408,
            },
        [51162408] = {
            ["Content"] = "说的也是……只是这样找下去未免也效率太低了，咱们华胥民族上千年的智慧积累，只能想出如此简单粗暴的应对方法吗？",
            ["DialogueId"] = 51162408,
            ["GUID"] = "80146890",
            ["NextDialogue"] = 51162409,
            ["SpeakNpcId"] = 701173,
            },
        [51162409] = {
            ["Content"] = "我想象之中，皓京城的香官们可以以香诱人，用分香术把那些丢失的翠屏雀全都牵引回来，就像是他们在战斗的时候控制狴犴一样！",
            ["DialogueId"] = 51162409,
            ["GUID"] = "801468BA",
            ["SpeakNpcId"] = 701173,
            },
        [51162410] = {
            ["Content"] = "加油找吧！",
            ["DialogueId"] = 51162410,
            ["GUID"] = "801468E4",
            ["NextDialogue"] = 51162411,
            },
        [51162411] = {
            ["Content"] = "是……你的好意我心领了……所以我很快就会鼓起干劲然后去城中乱跑一通直到抱回六只翠屏雀……那个场面一定很酷，到时候你可千万别错过，好了吧？",
            ["DialogueId"] = 51162411,
            ["GUID"] = "8014690E",
            ["SpeakNpcId"] = 701173,
            },
        [51162412] = {
            ["Content"] = "找不回来了……一切努力都付之东流了……",
            ["DialogueId"] = 51162412,
            ["GUID"] = "8014676B",
            ["NextDialogue"] = 51162401,
            ["SpeakNpcId"] = 701173,
            },
        [51162501] = {
            ["Content"] = "已经找到一只了？在民居的屋顶上？到底是怎么飞上去的？！",
            ["DialogueId"] = 51162501,
            ["GUID"] = "801477D2",
            ["NextDialogue"] = 51162502,
            ["SpeakNpcId"] = 701174,
            },
        [51162502] = {
            ["Content"] = "现在该怎么办啊，那翠屏雀占屋为王，疯狂在人家的屋顶上……",
            ["DialogueId"] = 51162502,
            ["GUID"] = "801477FC",
            ["NextDialogue"] = 51162503,
            ["SpeakNpcName"] = "UI_NPC_Name_shanyaliu_Sce",
            },
        [51162503] = {
            ["Content"] = "不要再继续说下去了！你说的场面我已经完全清楚了。不管怎么说，先把它赶下来才是正事。",
            ["DialogueId"] = 51162503,
            ["GUID"] = "80147826",
            ["NextDialogue"] = 51162504,
            ["SpeakNpcId"] = 701174,
            },
        [51162504] = {
            ["Content"] = "倒是想抓，但是怎么抓呢？人上去了，刚一靠近它就叫个不停，然后往反方向逃窜，我们也不敢进一步靠近，怕它又跑了个没影。",
            ["DialogueId"] = 51162504,
            ["GUID"] = "80147850",
            ["NextDialogue"] = 51162505,
            ["SpeakNpcName"] = "UI_NPC_Name_shanyaliu_Sce",
            },
        [51162505] = {
            ["Content"] = "真笨！用食物勾引它呀！你在地上放些瓜果蔬菜，然后人走远些，它不就乖乖下来了吗？",
            ["DialogueId"] = 51162505,
            ["GUID"] = "8014787A",
            ["NextDialogue"] = 51162506,
            ["SpeakNpcId"] = 701174,
            },
        [51162506] = {
            ["Content"] = "这种简单的伎俩当然是早就试过了，可就算它下来了，我们飞扑过去要抓的时候，它又扑腾飞上去了！",
            ["DialogueId"] = 51162506,
            ["GUID"] = "801478A4",
            ["NextDialogue"] = 51162507,
            ["SpeakNpcName"] = "UI_NPC_Name_shanyaliu_Sce",
            },
        [51162507] = {
            ["Content"] = "那肥身细脖的模样，到底是怎么飞上去的啊！！！",
            ["DialogueId"] = 51162507,
            ["GUID"] = "801478CE",
            ["NextOptions"] = {
                [1] = 51162508,
                [2] = 51162517,
                },
            ["SpeakNpcId"] = 701174,
            },
        [51162508] = {
            ["Content"] = "（你开始回忆你之前遇到翠屏雀时的样子。）",
            ["DialogueId"] = 51162508,
            ["GUID"] = "801478F8",
            ["NextDialogue"] = 51162509,
            },
        [51162509] = {
            ["Content"] = "我在烟津渡也待过一段时间，那里的翠屏雀满山遍野都是，见到我时却从不害怕。",
            ["DialogueId"] = 51162509,
            ["GUID"] = "80147922",
            ["NextDialogue"] = 51162510,
            ["SpeakNpcId"] = 100001,
            },
        [51162510] = {
            ["Content"] = "……不害怕？你的意思就是，它们看到你不会躲开，也不会惊吓地乱叫？",
            ["DialogueId"] = 51162510,
            ["GUID"] = "8014794C",
            ["NextDialogue"] = 51162511,
            ["SpeakNpcName"] = "UI_NPC_Name_shanyaliu_Sce",
            },
        [51162511] = {
            ["Content"] = "额……开屏不算是惊吓吧？",
            ["DialogueId"] = 51162511,
            ["GUID"] = "80147976",
            ["NextDialogue"] = 51162512,
            ["SpeakNpcId"] = 100001,
            },
        [51162512] = {
            ["Content"] = "什么情况，早听说有龙氏里能人异士居多，难道你就是天生拥有亲鸟体质的高人？",
            ["DialogueId"] = 51162512,
            ["GUID"] = "801479A0",
            ["NextDialogue"] = 51162513,
            ["SpeakNpcId"] = 701174,
            },
        [51162513] = {
            ["Content"] = "不对不对，翠屏雀见到这家伙会开屏的话，说不定{性别:他|她}其实是……雌孔雀成精！",
            ["DialogueId"] = 51162513,
            ["GUID"] = "801479CA",
            ["NextDialogue"] = 51162514,
            ["SpeakNpcName"] = "UI_NPC_Name_shanyaliu_Sce",
            },
        [51162514] = {
            ["Content"] = "胡说！龙君辖下动物不许成精！",
            ["DialogueId"] = 51162514,
            ["GUID"] = "801479F4",
            ["NextDialogue"] = 51162515,
            ["SpeakNpcId"] = 701174,
            },
        [51162515] = {
            ["Content"] = "总之，我的意思是你们可能对待翠屏雀一事过于紧张了，如果像我一样装作若无其事的样子走过去，或许反而不会惊吓到它们。",
            ["DialogueId"] = 51162515,
            ["GUID"] = "80147A1E",
            ["NextDialogue"] = 51162516,
            ["SpeakNpcId"] = 100001,
            },
        [51162516] = {
            ["Content"] = "好像很有道理……那个谁，你你你，快去！就按{性别:他|她}说的做！",
            ["DialogueId"] = 51162516,
            ["GUID"] = "80147A48",
            ["SpeakNpcId"] = 701174,
            },
        [51162517] = {
            ["Content"] = "（你开始思索起一些抓鸟的好方法。）",
            ["DialogueId"] = 51162517,
            ["GUID"] = "80147A72",
            ["NextDialogue"] = 51162518,
            },
        [51162518] = {
            ["Content"] = "我长大的地方，每到丰收的季节，村民们会把谷子铺在地上晾晒，那时总会有鸟雀来偷吃。",
            ["DialogueId"] = 51162518,
            ["GUID"] = "80147A9C",
            ["NextDialogue"] = 51162519,
            ["SpeakNpcId"] = 100001,
            },
        [51162519] = {
            ["Content"] = "为了不让它们偷吃，大家会提前制作一个用于抓鸟的框子，用一根细细的树枝支撑，就这样倒扣在地上，留出可以让小鸟进去的缝隙，放上它们爱吃的食物。",
            ["DialogueId"] = 51162519,
            ["GUID"] = "80147AC6",
            ["NextDialogue"] = 51162520,
            ["SpeakNpcId"] = 100001,
            },
        [51162520] = {
            ["Content"] = "然后啊，大家就在旁边等着，等小鸟落下来，一蹦一跳地进入框子里，用以支撑的树枝会被它们撞倒，框子自然倒下来，盖住小鸟。",
            ["DialogueId"] = 51162520,
            ["GUID"] = "80147AF0",
            ["NextDialogue"] = 51162521,
            ["SpeakNpcId"] = 100001,
            },
        [51162521] = {
            ["Content"] = "好聪明的法子！你这么一说我想起来，我小时候在村子里倒是真这么干过，但我们那时候是年纪小，抓鸟来玩的……",
            ["DialogueId"] = 51162521,
            ["GUID"] = "80147B1A",
            ["NextDialogue"] = 51162522,
            ["SpeakNpcName"] = "UI_NPC_Name_shanyaliu_Sce",
            },
        [51162522] = {
            ["Content"] = "我在皓京长大，怎么从来没听说过这种事？算了算了，你试试按照{性别:他|她}说的办法试试？做一个……那么胖的翠屏雀要用多大的框呀……",
            ["DialogueId"] = 51162522,
            ["GUID"] = "80147B44",
            ["NextDialogue"] = 51162523,
            ["SpeakNpcId"] = 701174,
            },
        [51162523] = {
            ["Content"] = "我家里有个装米用的，我现在去讨来！",
            ["DialogueId"] = 51162523,
            ["GUID"] = "80147B6E",
            ["SpeakNpcName"] = "UI_NPC_Name_shanyaliu_Sce",
            },
        [51162601] = {
            ["Content"] = "但可惜的是，此趟来皓京是为了婉拒这批订单，天不遂人愿啊，刚想将锦云谷刺绣的名头传享华胥，居然就出了这样的事情……",
            ["DialogueId"] = 51162601,
            ["GUID"] = "8014883A",
            ["NextDialogue"] = 51162602,
            ["SpeakNpcId"] = 701175,
            },
        }
  end },
  { MinKey = 51162602, MaxKey = 51165418, Loader = function()
      return {
        [51162602] = {
            ["Content"] = "锦云谷发生了什么？",
            ["DialogueId"] = 51162602,
            ["GUID"] = "80148864",
            ["NextDialogue"] = 51162603,
            },
        [51162603] = {
            ["Content"] = "实不相瞒，最近锦云谷的气候着实怪异，往年本是水土丰茂之地，最是适宜栽桑养蚕，但今年却不知为何，连日炎热，溪流干涸，桑树大面积枯死。",
            ["DialogueId"] = 51162603,
            ["GUID"] = "8014888E",
            ["NextDialogue"] = 51162604,
            ["SpeakNpcId"] = 701175,
            },
        [51162604] = {
            ["Content"] = "出了这样的事情，养蚕量自然也大批量下降，许多蚕农没办法，被迫换了生计。",
            ["DialogueId"] = 51162604,
            ["GUID"] = "801488B8",
            ["NextDialogue"] = 51162605,
            ["SpeakNpcId"] = 701175,
            },
        [51162605] = {
            ["Content"] = "因为供丝不足，所以绣娘们也没法给外地供货，此趟入京，即是为了与城中成衣店商议取消订单。",
            ["DialogueId"] = 51162605,
            ["GUID"] = "801488E2",
            ["SpeakNpcId"] = 701175,
            },
        [51162606] = {
            ["Content"] = "千绣阁今年的订货量又涨了许多，咱们的绣品在皓京城里很受欢迎呢~",
            ["DialogueId"] = 51162606,
            ["GUID"] = "8014890C",
            ["NextDialogue"] = 51162607,
            ["SpeakNpcId"] = 701175,
            },
        [51162607] = {
            ["Content"] = "就算现在涨价收购了，原材料跟不上，我们这些收购商人还是束手无策啊……罢了，锦云谷来回皓京一趟也不容易，还是要和他们再掰扯两天。",
            ["DialogueId"] = 51162607,
            ["GUID"] = "80148936",
            ["NextDialogue"] = 51162608,
            ["SpeakNpcId"] = 701175,
            },
        [51162608] = {
            ["Content"] = "是你啊，之前你也来和我说过话吧？本来想问问你是否知道皓京城里有没有可供外客留宿之地，但看你面相也不是本地人，遂罢了。",
            ["DialogueId"] = 51162608,
            ["GUID"] = "80148960",
            ["NextOptions"] = {
                [1] = 51162609,
                },
            ["SpeakNpcId"] = 701175,
            },
        [51162609] = {
            ["Content"] = "（回忆你对皓京的了解。）",
            ["DialogueId"] = 51162609,
            ["GUID"] = "8014898A",
            ["NextDialogue"] = 51162610,
            },
        [51162610] = {
            ["Content"] = "我确实不是皓京人，但我知道东市是热闹的商业街，你去那边转转或许会有收获。",
            ["DialogueId"] = 51162610,
            ["GUID"] = "801489B4",
            ["NextDialogue"] = 51162611,
            ["SpeakNpcId"] = 100001,
            },
        [51162611] = {
            ["Content"] = "哦？原来如此，谢谢你了，我请助手帮我去跑一趟。实不相瞒，我有些晕船，本不想坐船来皓京，但锦云谷到皓京，最快的方式便是坐船。",
            ["DialogueId"] = 51162611,
            ["GUID"] = "801489DE",
            ["NextDialogue"] = 51162612,
            ["SpeakNpcId"] = 701175,
            },
        [51162612] = {
            ["Content"] = "不过说起来，也多亏了曾经匠矩阁帮助开拓了运河，不然现在大家还在走那难走的山路，十天半个月也走不出锦云谷呢。",
            ["DialogueId"] = 51162612,
            ["GUID"] = "80148A08",
            ["NextOptions"] = {
                [1] = 51162613,
                [2] = 51162619,
                [3] = 51162662,
                },
            ["SpeakNpcId"] = 701175,
            },
        [51162613] = {
            ["Content"] = "锦云谷是个怎么样的地方？",
            ["DialogueId"] = 51162613,
            ["GUID"] = "80148A32",
            ["NextDialogue"] = 51162614,
            },
        [51162614] = {
            ["Content"] = "唔……你倒是问了个好问题，让我想想该从哪里给你说起呢？那里可是个和皓京大相径庭之地。",
            ["DialogueId"] = 51162614,
            ["GUID"] = "80148A5C",
            ["NextDialogue"] = 51162615,
            ["SpeakNpcId"] = 701175,
            },
        [51162615] = {
            ["Content"] = "皓京及周围地势多半平坦，锦云谷却是在群山之间，昔日为躲避秽兽的追袭，小批先人迁徙至此，逐渐发展出了一脉文明。",
            ["DialogueId"] = 51162615,
            ["GUID"] = "80148A86",
            ["NextDialogue"] = 51162616,
            ["SpeakNpcId"] = 701175,
            },
        [51162616] = {
            ["Content"] = "锦云谷全年温和，降水频繁，空气湿润，也有冬暖夏凉的美称，不似皓京这般温差明显，我冬日里来过一趟，冰刀子一样的风冷冷往脸上划。",
            ["DialogueId"] = 51162616,
            ["GUID"] = "80148AB0",
            ["NextDialogue"] = 51162617,
            ["SpeakNpcId"] = 701175,
            },
        [51162617] = {
            ["Content"] = "在饮食上，锦云谷和皓京也完全不同，我们那里口味可重了，皓京这边一比较就显得十分寡淡，我来只开始吃习惯一两顿，后面便开始怀念家乡菜。",
            ["DialogueId"] = 51162617,
            ["GUID"] = "80148ADA",
            ["NextDialogue"] = 51162618,
            ["SpeakNpcId"] = 701175,
            },
        [51162618] = {
            ["Content"] = "虽是说了半天，但具体的区别太多，还是得你亲眼看看才好，若是有空，多多去华胥各地看看吧。",
            ["DialogueId"] = 51162618,
            ["GUID"] = "80148B04",
            ["SpeakNpcId"] = 701175,
            },
        [51162619] = {
            ["Content"] = "锦云谷为什么会以养蚕为业？",
            ["DialogueId"] = 51162619,
            ["GUID"] = "80148B2E",
            ["NextDialogue"] = 51162620,
            },
        [51162620] = {
            ["Content"] = "这个问题嘛……其实我倒是完全可以用一句锦云谷水土丰沛之类的直接糊弄你过去，毕竟要是好好解释，就不得不和你提及锦云谷曾经的历史。",
            ["DialogueId"] = 51162620,
            ["GUID"] = "80148B58",
            ["NextDialogue"] = 51162621,
            ["SpeakNpcId"] = 701175,
            },
        [51162621] = {
            ["Content"] = "在很早以前，大概千年前？华胥尚未完全统一之时，锦云谷一带同样有一个强大的有龙氏族，氏族的领导者名为桑。",
            ["DialogueId"] = 51162621,
            ["GUID"] = "80148B82",
            ["NextDialogue"] = 51162622,
            ["SpeakNpcId"] = 701175,
            },
        [51162622] = {
            ["Content"] = "桑拥有与草木共鸣的魔法，在觉醒后，她很快带领氏族将锦云谷一代危害一方的秽兽诛杀，并利用自己的天赋教习部族内的普通人养蚕。",
            ["DialogueId"] = 51162622,
            ["GUID"] = "80148BAC",
            ["NextDialogue"] = 51162623,
            ["SpeakNpcId"] = 701175,
            },
        [51162623] = {
            ["Content"] = "桑的部族产出的蚕丝质量优异，很快远近闻名，之后便有织星客不远千里来到锦云谷收购，并带来了大风九章的消息。",
            ["DialogueId"] = 51162623,
            ["GUID"] = "80148BD6",
            ["NextDialogue"] = 51162624,
            ["SpeakNpcId"] = 701175,
            },
        [51162624] = {
            ["Content"] = "再后来，桑成为了当年进入大风九章内部的第一批有龙氏之一，锦云谷在匠矩阁的帮助下开拓运河，与皓京的关联也更为紧密。",
            ["DialogueId"] = 51162624,
            ["GUID"] = "80148C00",
            ["NextDialogue"] = 51162625,
            ["SpeakNpcId"] = 701175,
            },
        [51162625] = {
            ["Content"] = "所以养蚕这一生意，自然也被保留了下来。时至今日，虽然华胥各地早已不止有锦云谷有丝绸，但由于我们的进展较早，所以织工能力也更为先进。",
            ["DialogueId"] = 51162625,
            ["GUID"] = "80148C2A",
            ["SpeakNpcId"] = 701175,
            },
        [51162627] = {
            ["Content"] = "运河……就是运河！不对，好像说了一句废话啊！哈哈！不过我想你问的应该也不只是运河是用来做什么的这种一听名字就能猜到的问题？",
            ["DialogueId"] = 51162627,
            ["GUID"] = "80148C7E",
            ["NextDialogue"] = 51162628,
            ["SpeakNpcId"] = 701175,
            },
        [51162628] = {
            ["Content"] = "锦云谷由于地势和天气的特殊原因，极其容易发生水旱无常等问题，昔年桑还在世之时，想了许多法子也没能完全治理水灾。",
            ["DialogueId"] = 51162628,
            ["GUID"] = "80148CA8",
            ["NextDialogue"] = 51162629,
            ["SpeakNpcId"] = 701175,
            },
        [51162629] = {
            ["Content"] = "但后来，机枢派的高人们为我们支了一招，他们提议直接建造运河，将洪灾水分流，引水灌田，遂设计了这项工程。",
            ["DialogueId"] = 51162629,
            ["GUID"] = "80148CD2",
            ["NextDialogue"] = 51162630,
            ["SpeakNpcId"] = 701175,
            },
        [51162630] = {
            ["Content"] = "结果想必你也知道了，这条运河虽耗资巨大，但有机枢派高人的巨型机傀帮忙，克服了诸多困难，在当年也是一则佳话。",
            ["DialogueId"] = 51162630,
            ["GUID"] = "80148CFC",
            ["NextDialogue"] = 51162631,
            ["SpeakNpcId"] = 701175,
            },
        [51162631] = {
            ["Content"] = "即使现在的机枢派早已不同往日辉煌，但在锦云谷，他们仍旧受到大家的尊重和爱戴，此趟来皓京，我甚至还感叹了一下这京城还没我们锦云谷看着先进呢！",
            ["DialogueId"] = 51162631,
            ["GUID"] = "80148D26",
            ["SpeakNpcId"] = 701175,
            },
        [51162632] = {
            ["Content"] = "千绣阁今年的订货量又涨了许多，咱们的绣品在皓京城里很受欢迎呢~",
            ["DialogueId"] = 51162632,
            ["GUID"] = "8014883B",
            ["NextDialogue"] = 51162601,
            ["SpeakNpcId"] = 701175,
            },
        [51162662] = {
            ["Content"] = "运河是什么？",
            ["DialogueId"] = 51162662,
            ["GUID"] = "8014923C",
            ["NextDialogue"] = 51162627,
            },
        [51162701] = {
            ["Content"] = "必须重金将那位擅长冷冻魔法的有龙氏留下来，哦！只是那位有龙并非华胥中人，想让她留下来，似乎要先帮她申请长居证？",
            ["DialogueId"] = 51162701,
            ["GUID"] = "801498A2",
            ["NextDialogue"] = 51162702,
            ["SpeakNpcId"] = 701176,
            },
        [51162702] = {
            ["Content"] = "唔……少年人，见你在此盯着我看了半天，有何贵干？在下南山商贾，并非皓京中人，如果是问路打听之类的，我可能也不便回答。",
            ["DialogueId"] = 51162702,
            ["GUID"] = "801498CC",
            ["NextOptions"] = {
                [1] = 51162703,
                },
            ["SpeakNpcId"] = 701176,
            },
        [51162703] = {
            ["Content"] = "南山是哪里？",
            ["DialogueId"] = 51162703,
            ["GUID"] = "801498F6",
            ["NextDialogue"] = 51162704,
            },
        [51162704] = {
            ["Content"] = "南山啊……南山可就远了去了，南山是华胥南方的一处岛屿，岛上最瞩目的便是高耸入云的南山，故而得名南山岛。",
            ["DialogueId"] = 51162704,
            ["GUID"] = "80149920",
            ["NextDialogue"] = 51162705,
            ["SpeakNpcId"] = 701176,
            },
        [51162705] = {
            ["Content"] = "南山岛虽同样归属华胥，但位置较为偏僻，故而与内地联系并不密切，我们那天气炎热，难以种植香料，为维护大风九章，往往需要从皓京进货。",
            ["DialogueId"] = 51162705,
            ["GUID"] = "8014994A",
            ["NextDialogue"] = 51162706,
            ["SpeakNpcId"] = 701176,
            },
        [51162706] = {
            ["Content"] = "但同样，我们也会向皓京出售一些南山岛特产，只是运输流程较为复杂，往往需要擅长魔法的有龙一族相助。",
            ["DialogueId"] = 51162706,
            ["GUID"] = "80149974",
            ["NextOptions"] = {
                [1] = 51162707,
                },
            ["SpeakNpcId"] = 701176,
            },
        [51162707] = {
            ["Content"] = "都有什么特产？",
            ["DialogueId"] = 51162707,
            ["GUID"] = "8014999E",
            ["NextDialogue"] = 51162708,
            },
        [51162708] = {
            ["Content"] = "多半都是一些吃吃喝喝，还有特制的工艺品之类的，不足挂齿，能抵消部分来时路费便好了。",
            ["DialogueId"] = 51162708,
            ["GUID"] = "801499C8",
            ["NextDialogue"] = 51162709,
            ["SpeakNpcId"] = 701176,
            },
        [51162709] = {
            ["Content"] = "要说最贵的货物……大概是我们此趟运送的甜果。因为运输损耗太大，导致不得不定价高些。",
            ["DialogueId"] = 51162709,
            ["GUID"] = "801499F2",
            ["NextOptions"] = {
                [1] = 51162710,
                [2] = 51162713,
                },
            ["SpeakNpcId"] = 701176,
            },
        [51162710] = {
            ["Content"] = "甜果是什么？",
            ["DialogueId"] = 51162710,
            ["GUID"] = "80149A1C",
            ["NextDialogue"] = 51162711,
            },
        [51162711] = {
            ["Content"] = "甜果就是南山岛最有名的特产之一，在我们那，漫山遍野种的都是甜果，甜果汁水丰盈，香甜可口，受到各方欢迎。",
            ["DialogueId"] = 51162711,
            ["GUID"] = "80149A46",
            ["NextDialogue"] = 51162712,
            ["SpeakNpcId"] = 701176,
            },
        [51162712] = {
            ["Content"] = "但由于这种果子极其特殊，从成熟到落地只需短短十天，摘下来更是头疼，一天之内便失了味，所以很少能在其他地区见到。",
            ["DialogueId"] = 51162712,
            ["GUID"] = "80149A70",
            ["NextOptions"] = {
                [1] = 51162716,
                [2] = 51162718,
                [3] = 51162721,
                },
            ["SpeakNpcId"] = 701176,
            },
        [51162713] = {
            ["Content"] = "那要怎么运输？",
            ["DialogueId"] = 51162713,
            ["GUID"] = "80149A9A",
            ["NextDialogue"] = 51162714,
            },
        [51162714] = {
            ["Content"] = "匠矩阁的师傅们曾为甜果专门定制过一种冷罐，用的是特制的冰瓷，甜果一摘下来便放进双层瓷罐里，再在外面一层里填上许多冰。",
            ["DialogueId"] = 51162714,
            ["GUID"] = "80149AC4",
            ["NextDialogue"] = 51162715,
            ["SpeakNpcId"] = 701176,
            },
        [51162715] = {
            ["Content"] = "大伙将瓷瓶搬到织星客最先进的船上，船只再以疾速奔驰，到皓京时堪堪只能十中留五，所以我们每每都会多准备许多用以填充损耗。",
            ["DialogueId"] = 51162715,
            ["GUID"] = "80149AEE",
            ["NextOptions"] = {
                [1] = 51162716,
                [2] = 51162718,
                [3] = 51162721,
                },
            ["SpeakNpcId"] = 701176,
            },
        [51162716] = {
            ["Content"] = "为什么不在皓京种这种果树？",
            ["DialogueId"] = 51162716,
            ["GUID"] = "80149B18",
            ["NextDialogue"] = 51162717,
            },
        [51162717] = {
            ["Content"] = "这个嘛……之前是想过，但这甜果怪就怪在只能用南山岛上的土壤培育，在其他地方，哪怕是气温相似，一样结不出果。",
            ["DialogueId"] = 51162717,
            ["GUID"] = "80149B42",
            ["SpeakNpcId"] = 701176,
            },
        [51162718] = {
            ["Content"] = "这和匠矩阁有什么关系？",
            ["DialogueId"] = 51162718,
            ["GUID"] = "80149B6C",
            ["NextDialogue"] = 51162719,
            },
        [51162719] = {
            ["Content"] = "几十年前还没有甜果运送链，第一次提出运输甜果这个想法的人是曾经在南山岛帮助基建的匠矩阁师傅。",
            ["DialogueId"] = 51162719,
            ["GUID"] = "80149B96",
            ["NextDialogue"] = 51162720,
            ["SpeakNpcId"] = 701176,
            },
        [51162720] = {
            ["Content"] = "他们在南山居住的时间里，不可自拔地爱上了甜果，回到皓京后也时常念着这一口，故而再度回到南山，考虑如何运输甜果至华胥各地。",
            ["DialogueId"] = 51162720,
            ["GUID"] = "80149BC0",
            ["SpeakNpcId"] = 701176,
            },
        [51162721] = {
            ["Content"] = "运输损耗这么大，为什么还要一直运？",
            ["DialogueId"] = 51162721,
            ["GUID"] = "80149BEA",
            ["NextDialogue"] = 51162722,
            },
        [51162722] = {
            ["Content"] = "自然是因为有需求，我们也不想让此等美物只能留在南山岛，而是更想与全华胥的百姓共同分享。",
            ["DialogueId"] = 51162722,
            ["GUID"] = "80149C14",
            ["NextDialogue"] = 51162723,
            ["SpeakNpcId"] = 701176,
            },
        [51162723] = {
            ["Content"] = "何况甜果在南山岛遍地都是，大家整日都吃腻了，送来皓京换些香料，对我们来说也是两全其美之事。",
            ["DialogueId"] = 51162723,
            ["GUID"] = "80149C3E",
            ["NextDialogue"] = 51162724,
            ["SpeakNpcId"] = 701176,
            },
        [51162724] = {
            ["Content"] = "不过此趟运输倒是多了高人相助，我们商队来了一位卢卡的有龙氏，她掌握着冰冻相关的魔法，在她的帮助下，我们的损耗大大降低！",
            ["DialogueId"] = 51162724,
            ["GUID"] = "80149C68",
            ["NextDialogue"] = 51162725,
            ["SpeakNpcId"] = 701176,
            },
        [51162725] = {
            ["Content"] = "不过她似乎只是暂留华胥，要是能一直留下她来帮忙就好了，你说如果我们给她开出更高昂的薪资她会同意吗？",
            ["DialogueId"] = 51162725,
            ["GUID"] = "80149C92",
            ["SpeakNpcId"] = 701176,
            },
        [51162726] = {
            ["Content"] = "此趟运输甜果只有百分之三损毁？甚好甚好~",
            ["DialogueId"] = 51162726,
            ["GUID"] = "801498A1",
            ["NextDialogue"] = 51162701,
            ["SpeakNpcId"] = 701176,
            },
        [51162801] = {
            ["Content"] = "太皓神君的纹样大家早就看腻啦~一点新意也没有。",
            ["DialogueId"] = 51162801,
            ["GUID"] = "8014A90A",
            ["NextDialogue"] = 51162802,
            ["SpeakNpcId"] = 701177,
            },
        [51162802] = {
            ["Content"] = "每年来来回回都是那老几样，花鸟鱼虫，一点品味也没有~没有意思的啦~",
            ["DialogueId"] = 51162802,
            ["GUID"] = "8014A934",
            ["NextOptions"] = {
                [1] = 51162803,
                },
            ["SpeakNpcId"] = 701177,
            },
        [51162803] = {
            ["Content"] = "你在说什么的啦？",
            ["DialogueId"] = 51162803,
            ["GUID"] = "8014A95E",
            ["NextDialogue"] = 51162804,
            },
        [51162804] = {
            ["Content"] = "还能是什么，当然是瓷瓶的花纹选图的啦~诶呀你为什么模仿我说话的啦？",
            ["DialogueId"] = 51162804,
            ["GUID"] = "8014A988",
            ["NextOptions"] = {
                [1] = 51162805,
                [2] = 51162807,
                },
            ["SpeakNpcId"] = 701177,
            },
        [51162805] = {
            ["Content"] = "没有的啦~",
            ["DialogueId"] = 51162805,
            ["GUID"] = "8014A9B2",
            ["NextDialogue"] = 51162806,
            },
        [51162806] = {
            ["Content"] = "分明就是有的啦~每次来皓京都要碰到些讨厌的家伙的啦！要不就是祀烟阁里面笨笨的香官，要不就是故意模仿我说话的白衣服笨蛋的啦！",
            ["DialogueId"] = 51162806,
            ["GUID"] = "8014A9DC",
            ["NextOptions"] = {
                [1] = 51162809,
                },
            ["SpeakNpcId"] = 701177,
            },
        [51162807] = {
            ["Content"] = "不好意思。",
            ["DialogueId"] = 51162807,
            ["GUID"] = "8014AA06",
            ["NextDialogue"] = 51162808,
            },
        [51162808] = {
            ["Content"] = "这还差不多~不过我也没有生气的啦，比起那个笨笨的祀烟阁香官，你倒是好多了的啦~",
            ["DialogueId"] = 51162808,
            ["GUID"] = "8014AA30",
            ["NextOptions"] = {
                [1] = 51162809,
                },
            ["SpeakNpcId"] = 701177,
            },
        [51162809] = {
            ["Content"] = "你和祀烟阁之间有什么过节？",
            ["DialogueId"] = 51162809,
            ["GUID"] = "8014AA5A",
            ["NextDialogue"] = 51162810,
            },
        [51162810] = {
            ["Content"] = "那当然没有的啦~只是感叹一下他们每年都这么笨笨的啦。",
            ["DialogueId"] = 51162810,
            ["GUID"] = "8014AA84",
            ["NextDialogue"] = 51162811,
            ["SpeakNpcId"] = 701177,
            },
        [51162811] = {
            ["Content"] = "我是芙蓉浦来的瓷器商人，祀烟阁每年都会找我们定制一批瓷器用来保存香料，一般找我们定货的客人都是可以自选花纹的啦。",
            ["DialogueId"] = 51162811,
            ["GUID"] = "8014AAAE",
            ["NextDialogue"] = 51162812,
            ["SpeakNpcId"] = 701177,
            },
        [51162812] = {
            ["Content"] = "那些长期定制的客人，每年多少会有些新花样，但祀烟阁每回要的都是一样的花纹，要不是太皓神君，要不是花鸟鱼虫，超没意思的啦~",
            ["DialogueId"] = 51162812,
            ["GUID"] = "8014AAD8",
            ["NextDialogue"] = 51162813,
            ["SpeakNpcId"] = 701177,
            },
        [51162813] = {
            ["Content"] = "所以我就说，那些香官笨笨的啦，虽然大家都说拿钱办事绝不多管闲事，但是……但是每年都做一样的，超级无聊的啦~",
            ["DialogueId"] = 51162813,
            ["GUID"] = "8014AB02",
            ["NextOptions"] = {
                [1] = 51162814,
                [2] = 51162819,
                },
            ["SpeakNpcId"] = 701177,
            },
        [51162814] = {
            ["Content"] = "或许每个花纹都有特殊含义。",
            ["DialogueId"] = 51162814,
            ["GUID"] = "8014AB2C",
            ["NextDialogue"] = 51162815,
            },
        [51162815] = {
            ["Content"] = "如果他们定制瓷罐是用来装香料，有没有可能是因为不同花纹所代表的是不同品种的香料呢？",
            ["DialogueId"] = 51162815,
            ["GUID"] = "8014AB56",
            ["NextDialogue"] = 51162816,
            ["SpeakNpcId"] = 100001,
            },
        [51162816] = {
            ["Content"] = "咦？你这么一说好像是有些道理的啦……所以这就是他们十几年来纹样不变的道理吗？",
            ["DialogueId"] = 51162816,
            ["GUID"] = "8014AB80",
            ["NextDialogue"] = 51162817,
            ["SpeakNpcId"] = 701177,
            },
        [51162817] = {
            ["Content"] = "随意改变的话，之后新进的香官也不是很方便记忆……按照相同花纹存放香料想必也更好管理。",
            ["DialogueId"] = 51162817,
            ["GUID"] = "8014ABAA",
            ["NextDialogue"] = 51162818,
            ["SpeakNpcId"] = 100001,
            },
        [51162818] = {
            ["Content"] = "好吧好吧，我明白了的啦，勉强接受这个说法，以后我就不说香官们是笨蛋好了啦~",
            ["DialogueId"] = 51162818,
            ["GUID"] = "8014ABD4",
            ["SpeakNpcId"] = 701177,
            },
        [51162819] = {
            ["Content"] = "确实没有新意。",
            ["DialogueId"] = 51162819,
            ["GUID"] = "8014ABFE",
            ["NextDialogue"] = 51162820,
            },
        [51162820] = {
            ["Content"] = "我建议在瓷瓶上推陈出新，比如印一个皎皎之民怎么样？",
            ["DialogueId"] = 51162820,
            ["GUID"] = "8014AC28",
            ["NextDialogue"] = 51162821,
            ["SpeakNpcId"] = 100001,
            },
        [51162821] = {
            ["Content"] = "诶？好主意！皎皎之民看起来小小一只，可可爱爱的，最适合印在瓷瓶上的啦！",
            ["DialogueId"] = 51162821,
            ["GUID"] = "8014AC52",
            ["NextDialogue"] = 51162822,
            ["SpeakNpcId"] = 701177,
            },
        [51162822] = {
            ["Content"] = "不过这些想法还是我自己私下制瓷之时再尝试好了啦……反正他们每次要的都是一样的。",
            ["DialogueId"] = 51162822,
            ["GUID"] = "8014AC7C",
            ["SpeakNpcId"] = 701177,
            },
        [51162901] = {
            ["Content"] = "请大家带好随身行李，提不动的呢就放在我们指定的寄存点，等下会有师傅帮咱们搬到入住的客栈内。",
            ["DialogueId"] = 51162901,
            ["GUID"] = "8014B972",
            ["NextDialogue"] = 51162902,
            ["SpeakNpcId"] = 701178,
            },
        [51162902] = {
            ["Content"] = "咱们现在已经身处皓京最热闹的地点之一，就是参商港，每天都有几百艘船只从这里进出啊，很多也是像咱们一样，从锦云谷来。",
            ["DialogueId"] = 51162902,
            ["GUID"] = "8014B99C",
            ["NextDialogue"] = 51162903,
            ["SpeakNpcId"] = 701178,
            },
        [51162903] = {
            ["Content"] = "大家请跟紧我，我们现在一路走到西市，先去吃个饭，毕竟一路奔波，就算哥哥姐姐们不饿，我的肚子却是早就咕咕作响了。",
            ["DialogueId"] = 51162903,
            ["GUID"] = "8014B9C6",
            ["NextOptions"] = {
                [1] = 51162904,
                [2] = 51162906,
                },
            ["SpeakNpcId"] = 701178,
            },
        [51162904] = {
            ["Content"] = "（目送他们离开。)",
            ["DialogueId"] = 51162904,
            ["GUID"] = "8014B9F0",
            ["ImprPlusId"] = 1211,
            ["NextDialogue"] = 51162905,
            },
        [51162905] = {
            ["Content"] = "好，就从这条路一直走，大家注意跟着我的小红旗哦~",
            ["DialogueId"] = 51162905,
            ["GUID"] = "8014BA1A",
            ["SpeakNpcId"] = 701178,
            },
        [51162906] = {
            ["Content"] = "（跟随他们离开。）",
            ["DialogueId"] = 51162906,
            ["GUID"] = "8014BA44",
            ["ImprPlusId"] = 1206,
            ["NextDialogue"] = 51162907,
            },
        [51162907] = {
            ["Content"] = "咦？你是哪个团的团友？似乎不是咱们团的吧？你最好还是回到自己的队伍里去哦，不然走丢了到时候你们团长会着急的。",
            ["DialogueId"] = 51162907,
            ["GUID"] = "8014BA6E",
            ["SpeakNpcId"] = 701178,
            },
        [51162908] = {
            ["Content"] = "各位好姐姐好哥哥们，现在呢就已经到了咱们皓京，也是咱们华胥呢，最繁华的地方~",
            ["DialogueId"] = 51162908,
            ["GUID"] = "8014B971",
            ["NextDialogue"] = 51162901,
            ["SpeakNpcId"] = 701178,
            },
        [51164901] = {
            ["Content"] = "故人来之，不曾相迎，是我逍遥生之过，二位恕罪恕罪~",
            ["DialogueId"] = 51164901,
            ["GUID"] = "80160192",
            ["SpeakNpcId"] = 700385,
            },
        [51164902] = {
            ["Content"] = "你你你——就是那个……之前莫名其妙抢我们东西，却又在后面救了我们一命的那个无由生对吧！又见到你了！",
            ["DialogueId"] = 51164902,
            ["GUID"] = "801601BC",
            ["SpeakNpcId"] = 200002,
            },
        [51164903] = {
            ["Content"] = "之前救了我们的事情，谢谢。",
            ["DialogueId"] = 51164903,
            ["GUID"] = "801601E6",
            ["SpeakNpcId"] = 100001,
            },
        [51164904] = {
            ["Content"] = "虽是萍水相逢，但小生所为却被二位牢记于心，让我很是感动，想要送你们什么东西用以报答这份知遇之恩啊……",
            ["DialogueId"] = 51164904,
            ["GUID"] = "80160210",
            ["SpeakNpcId"] = 700385,
            },
        [51164905] = {
            ["Content"] = "谢谢你，但是不用啦，我们也没做什么事。",
            ["DialogueId"] = 51164905,
            ["GUID"] = "8016023A",
            ["ImprPlusId"] = 1209,
            },
        [51164906] = {
            ["Content"] = "无功不受禄，我们也没做什么，报答的事还是算了。",
            ["DialogueId"] = 51164906,
            ["GUID"] = "80160264",
            ["ImprPlusId"] = 1206,
            },
        [51164907] = {
            ["Content"] = "无由生还能送什么东西？",
            ["DialogueId"] = 51164907,
            ["GUID"] = "8016028E",
            ["ImprPlusId"] = 1210,
            },
        [51164908] = {
            ["Content"] = "此言差矣~我们三次相遇，第一次你手中有一我心许之物，乌龙一场，第二次是你们置身危境之中，我出手相助，这一次是你我荒野偶遇，缘分天成，实在难得。",
            ["DialogueId"] = 51164908,
            ["GUID"] = "801602B8",
            ["SpeakNpcId"] = 700385,
            },
        [51164909] = {
            ["Content"] = "且不说功禄一事，仅你我相遇三次之缘分，便是值得上我这一份礼物，你看如何？",
            ["DialogueId"] = 51164909,
            ["GUID"] = "801602E2",
            ["SpeakNpcId"] = 700385,
            },
        [51164910] = {
            ["Content"] = "说的也是，无由生便是这般，无由而死，无由往生，死前了无牵挂，死后也岌岌无名啊。",
            ["DialogueId"] = 51164910,
            ["GUID"] = "8016030C",
            ["SpeakNpcId"] = 700385,
            },
        [51164911] = {
            ["Content"] = "所以你要送我们什么？",
            ["DialogueId"] = 51164911,
            ["GUID"] = "80160336",
            ["SpeakNpcId"] = 100001,
            },
        [51164912] = {
            ["Content"] = "小生近日碰巧得知一绝世琴谱的下落，据说这琴谱乃是一名琴师的传家之宝，那琴师凭借高超琴艺，堆金积玉，驰名华胥。",
            ["DialogueId"] = 51164912,
            ["GUID"] = "80160360",
            ["SpeakNpcId"] = 700385,
            },
        [51164913] = {
            ["Content"] = "多有人心向往之，斥资千金求购琴谱，他却守谱如玉，只为找到心中适合继承琴谱之人选，将琴谱传授于他。",
            ["DialogueId"] = 51164913,
            ["GUID"] = "8016038A",
            ["SpeakNpcId"] = 700385,
            },
        [51164914] = {
            ["Content"] = "你的意思是……让我和小仆从去继承他的琴谱？虽然白魔王是什么都很厉害啦，但是弹琴这种事情之前压根没学过。",
            ["DialogueId"] = 51164914,
            ["GUID"] = "801603B4",
            ["SpeakNpcId"] = 200002,
            },
        [51164915] = {
            ["Content"] = "非也非也，在下得知的琴谱，并非需要经过漫长学习才可获得，而是轻而易举便能到手。",
            ["DialogueId"] = 51164915,
            ["GUID"] = "801603DE",
            ["SpeakNpcId"] = 700385,
            },
        [51164916] = {
            ["Content"] = "怎么样，二位可有兴趣？有了琴谱，二位随意将之抛售于织星客，便可赚得盆满钵满，届时用这笔钱游山玩水，岂不逍遥？",
            ["DialogueId"] = 51164916,
            ["GUID"] = "80160408",
            ["SpeakNpcId"] = 700385,
            },
        [51164917] = {
            ["Content"] = "听起来好像的确很有诱惑力……小仆从，我们要不要听他的试试看，反正在华胥也不会遇到什么很大的危险吧。",
            ["DialogueId"] = 51164917,
            ["GUID"] = "80160432",
            ["SpeakNpcId"] = 200002,
            },
        [51164918] = {
            ["Content"] = "好，逍遥生，我们想知道这绝世琴谱的下落。",
            ["DialogueId"] = 51164918,
            ["GUID"] = "8016045C",
            ["SpeakNpcId"] = 100001,
            },
        [51164919] = {
            ["Content"] = "触机便悟，玲珑心思啊，这琴谱的下落呢，远在天边，近在眼前~",
            ["DialogueId"] = 51164919,
            ["GUID"] = "80160486",
            ["SpeakNpcId"] = 700385,
            },
        [51164920] = {
            ["Content"] = "（逍遥生转身，看向了一旁的水面。）",
            ["DialogueId"] = 51164920,
            ["GUID"] = "801604B0",
            },
        [51164921] = {
            ["Content"] = "在湖里？那不是早就被水泡发了吗？算了算了，小仆从，我们用<H>钓鱼</>的方式试试看能不能把琴谱捞上来吧！",
            ["DialogueId"] = 51164921,
            ["GUID"] = "801604DA",
            ["SpeakNpcId"] = 200002,
            },
        [51165001] = {
            ["Content"] = "小小小小仆从……你你你，你钓上了……什么东西啊……",
            ["DialogueId"] = 51165001,
            ["GUID"] = "801611FA",
            ["SpeakNpcId"] = 200002,
            },
        [51165002] = {
            ["Content"] = "一具骷髅。",
            ["DialogueId"] = 51165002,
            ["GUID"] = "80161224",
            ["ImprPlusId"] = 1208,
            },
        [51165003] = {
            ["Content"] = "怎么会有人横死在此？",
            ["DialogueId"] = 51165003,
            ["GUID"] = "8016124E",
            ["ImprPlusId"] = 1209,
            },
        [51165004] = {
            ["Content"] = "我再钓一下看看能不能钓上琴谱。",
            ["DialogueId"] = 51165004,
            ["GUID"] = "80161278",
            ["ImprPlusId"] = 1210,
            },
        [51165005] = {
            ["Content"] = "谁都看得出来这是骷髅啦！但是我是想问，为什么钓鱼会钓上这种东西？！",
            ["DialogueId"] = 51165005,
            ["GUID"] = "801612A2",
            ["SpeakNpcId"] = 200002,
            },
        [51165006] = {
            ["Content"] = "这里不是华胥吗？最和平的国家，怎么会在湖里钓上一副骷髅嘛！",
            ["DialogueId"] = 51165006,
            ["GUID"] = "801612CC",
            ["SpeakNpcId"] = 200002,
            },
        [51165007] = {
            ["Content"] = "你在说什么胡话啊！现在的紧急情况是你钓上了一副骷髅，这到底是怎么回事嘛！",
            ["DialogueId"] = 51165007,
            ["GUID"] = "801612F6",
            ["SpeakNpcId"] = 200002,
            },
        [51165008] = {
            ["Content"] = "光天化日朗朗乾坤，你二位居然从湖中打捞上一具无名尸骨，实在惊悚，着实荒唐！",
            ["DialogueId"] = 51165008,
            ["GUID"] = "80161320",
            ["SpeakNpcId"] = 700385,
            },
        [51165009] = {
            ["Content"] = "是你搞的鬼吧？逍遥生。",
            ["DialogueId"] = 51165009,
            ["GUID"] = "8016134A",
            ["SpeakNpcId"] = 100001,
            },
        [51165010] = {
            ["Content"] = "诶呀，你可别将脏水往我这里泼呀，我本逍遥，天地悠悠，如何与这水中枯骨沾上关系呢？",
            ["DialogueId"] = 51165010,
            ["GUID"] = "80161374",
            ["SpeakNpcId"] = 700385,
            },
        [51165011] = {
            ["Content"] = "你还狡辩，要不是你跟我们说什么水里有琴谱，我们才不会……才不会……",
            ["DialogueId"] = 51165011,
            ["GUID"] = "8016139E",
            ["SpeakNpcId"] = 200002,
            },
        [51165012] = {
            ["Content"] = "所以这到底是怎么回事，逍遥生，这不是华胥吗？也会出现这种藏尸冤案？",
            ["DialogueId"] = 51165012,
            ["GUID"] = "801613C8",
            ["SpeakNpcId"] = 100001,
            },
        [51165013] = {
            ["Content"] = "嗯……到底是怎么回事呢？小生也不知情呀。",
            ["DialogueId"] = 51165013,
            ["GUID"] = "801613F2",
            ["SpeakNpcId"] = 700385,
            },
        [51165014] = {
            ["Content"] = "他开始装傻了，看起来明明一副什么都知道的样子却硬要说自己不知道……",
            ["DialogueId"] = 51165014,
            ["GUID"] = "8016141C",
            ["SpeakNpcId"] = 200002,
            },
        [51165015] = {
            ["Content"] = "二位先别急嘛，虽然小生不知道这白骨姓甚名谁从何而来，但却知晓琴谱的线索就在这尸体之中。",
            ["DialogueId"] = 51165015,
            ["GUID"] = "80161446",
            ["SpeakNpcId"] = 700385,
            },
        [51165016] = {
            ["Content"] = "不如这样~若是你们能调查出尸骨的真相，我就将这琴谱作为报偿送你，如何？",
            ["DialogueId"] = 51165016,
            ["GUID"] = "80161470",
            ["SpeakNpcId"] = 700385,
            },
        [51165017] = {
            ["Content"] = "本来说的是送我们，现在又变成了查案的奖励，逍遥生，你不会又耍我们一次吧……",
            ["DialogueId"] = 51165017,
            ["GUID"] = "8016149A",
            ["SpeakNpcId"] = 100001,
            },
        [51165018] = {
            ["Content"] = "诚心寻宝物，信物通妙境啊，这弥足珍贵之物总不能乖乖跳到你怀里是不是？你定然是需要付出一些小小的努力，才能寻到你想要的东西呀。",
            ["DialogueId"] = 51165018,
            ["GUID"] = "801614C4",
            ["SpeakNpcId"] = 700385,
            },
        [51165019] = {
            ["Content"] = "说的信誓旦旦，说不定真的有什么绝世琴谱。",
            ["DialogueId"] = 51165019,
            ["GUID"] = "801614EE",
            ["ImprPlusId"] = 1208,
            },
        [51165020] = {
            ["Content"] = "即使琴谱的下落是假，但白骨是真，得还白骨一个清白。",
            ["DialogueId"] = 51165020,
            ["GUID"] = "80161518",
            ["ImprPlusId"] = 1207,
            },
        [51165021] = {
            ["Content"] = "如果琴谱真的如他所说，那拿到想必真能赚上一大笔。",
            ["DialogueId"] = 51165021,
            ["GUID"] = "80161542",
            ["ImprPlusId"] = 1210,
            },
        [51165022] = {
            ["Content"] = "虽然我平日里爱插科打诨，但此事我倒是真没骗你们，只可惜我已是无由生的身份，不然此等美物，我定是不能放手的呀。",
            ["DialogueId"] = 51165022,
            ["GUID"] = "8016156C",
            ["SpeakNpcId"] = 700385,
            },
        [51165023] = {
            ["Content"] = "你倒是个慈心善念之人，浮名重利在前也不为所动，倒先想起了还人清白一事，鉴事如高屋建瓴，实在逍遥。",
            ["DialogueId"] = 51165023,
            ["GUID"] = "80161596",
            ["SpeakNpcId"] = 700385,
            },
        [51165024] = {
            ["Content"] = "啧啧，事境千转，只世人所追求之物从未变革，或许钱财或许功名或许神力，困之扰之，难得逍遥啊。",
            ["DialogueId"] = 51165024,
            ["GUID"] = "801615C0",
            ["SpeakNpcId"] = 700385,
            },
        [51165025] = {
            ["Content"] = "小仆从，你要是带着这样的想法以后一定会被骗的，诶……没办法，谁叫本魔王惯着你呢~就交给我吧，一定会陪你把真相调查到底的！",
            ["DialogueId"] = 51165025,
            ["GUID"] = "801615EA",
            ["SpeakNpcId"] = 200002,
            },
        [51165101] = {
            ["Content"] = "（你强忍着内心的不适，试图从白骨之上寻找线索。）",
            ["DialogueId"] = 51165101,
            ["GUID"] = "80162262",
            },
        [51165102] = {
            ["Content"] = "这位……大哥，或者大姐，在你去世多年后我们还摆弄你的遗骨，非常抱歉，但我们没有恶意，不要怪我们！",
            ["DialogueId"] = 51165102,
            ["GUID"] = "8016228C",
            ["SpeakNpcId"] = 200002,
            },
        [51165103] = {
            ["Content"] = "按照骨架大小来看，应该是男的吧……但距离去世多久已经没法判断了。",
            ["DialogueId"] = 51165103,
            ["GUID"] = "801622B6",
            ["SpeakNpcId"] = 100001,
            },
        [51165104] = {
            ["Content"] = "大哥，大哥，非常抱歉……",
            ["DialogueId"] = 51165104,
            ["GUID"] = "801622E0",
            ["SpeakNpcId"] = 200002,
            },
        [51165105] = {
            ["Content"] = "检查是否有受伤。",
            ["DialogueId"] = 51165105,
            ["GUID"] = "8016230A",
            },
        [51165106] = {
            ["Content"] = "看起来骨骼上面没有刀剑痕迹，应该不是外伤。",
            ["DialogueId"] = 51165106,
            ["GUID"] = "80162334",
            ["SpeakNpcId"] = 100001,
            },
        [51165107] = {
            ["Content"] = "检查是否有中毒的痕迹。",
            ["DialogueId"] = 51165107,
            ["GUID"] = "8016235E",
            },
        [51165108] = {
            ["Content"] = "骨头颜色都是正常的话，应该也不是被下毒。",
            ["DialogueId"] = 51165108,
            ["GUID"] = "80162388",
            ["SpeakNpcId"] = 100001,
            },
        [51165109] = {
            ["Content"] = "检查是否有挣扎的迹象。",
            ["DialogueId"] = 51165109,
            ["GUID"] = "801623B2",
            },
        [51165110] = {
            ["Content"] = "骸骨的排列都很自然，也不像是被人扔进水中的。",
            ["DialogueId"] = 51165110,
            ["GUID"] = "801623DC",
            ["SpeakNpcId"] = 100001,
            },
        [51165111] = {
            ["Content"] = "检查是否有其他值得注意的点。",
            ["DialogueId"] = 51165111,
            ["GUID"] = "80162406",
            },
        [51165112] = {
            ["Content"] = "他的右手掌部分的骨骼完全不见了。",
            ["DialogueId"] = 51165112,
            ["GUID"] = "80162430",
            ["SpeakNpcId"] = 200002,
            },
        [51165113] = {
            ["Content"] = "也许是因为被什么东西压着，还留在水里。",
            ["DialogueId"] = 51165113,
            ["GUID"] = "8016245A",
            ["SpeakNpcId"] = 100001,
            },
        [51165114] = {
            ["Content"] = "再次检查找到白骨的水域。",
            ["DialogueId"] = 51165114,
            ["GUID"] = "80162484",
            },
        [51165115] = {
            ["Content"] = "唔……找到手掌的骨头了，被压在这个盒子下面。",
            ["DialogueId"] = 51165115,
            ["GUID"] = "801624AE",
            ["SpeakNpcId"] = 100001,
            },
        [51165116] = {
            ["Content"] = "盒子！打开看看，说不定逍遥生说的琴谱就藏在了这里面！",
            ["DialogueId"] = 51165116,
            ["GUID"] = "801624D8",
            ["SpeakNpcId"] = 200002,
            },
        [51165117] = {
            ["Content"] = "打开盒子",
            ["DialogueId"] = 51165117,
            ["GUID"] = "80162502",
            },
        [51165118] = {
            ["Content"] = "里面真有东西，是一个香囊……还有一件帛书！不过……不是琴谱，是一封信，我来看看写着什么。",
            ["DialogueId"] = 51165118,
            ["GUID"] = "8016252C",
            ["SpeakNpcId"] = 100001,
            },
        [51165119] = {
            ["Content"] = "让我看看让我看看！师亲启……众徒之中，独余秀之……随师往椒兰……什么乱七八糟的？",
            ["DialogueId"] = 51165119,
            ["GUID"] = "80162556",
            ["SpeakNpcId"] = 200002,
            },
        [51165120] = {
            ["Content"] = "落款是……商……",
            ["DialogueId"] = 51165120,
            ["GUID"] = "80162580",
            ["SpeakNpcId"] = 100001,
            },
        [51165121] = {
            ["Content"] = "商？是说他姓商吗？这好像是写给这个人的师父的信呢。",
            ["DialogueId"] = 51165121,
            ["GUID"] = "801625AA",
            ["SpeakNpcId"] = 200002,
            },
        [51165201] = {
            ["Content"] = "大叔您好！可以稍微打扰你一下下吗？",
            ["DialogueId"] = 51165201,
            ["GUID"] = "801632CA",
            ["SpeakNpcId"] = 200002,
            },
        [51165202] = {
            ["Content"] = "皎皎之民？有什么事吗，我正准备回家奉香呢。",
            ["DialogueId"] = 51165202,
            ["GUID"] = "801632F4",
            ["SpeakNpcId"] = 700389,
            },
        [51165203] = {
            ["Content"] = "您好，我们想向你打探一下，你们村子里是否曾有姓商，或名字中有商字的人居住？",
            ["DialogueId"] = 51165203,
            ["GUID"] = "8016331E",
            ["SpeakNpcId"] = 100001,
            },
        [51165204] = {
            ["Content"] = "商？这字起的倒是雅，我在这住了大半辈子，倒是没听过本地人起这种雅字。",
            ["DialogueId"] = 51165204,
            ["GUID"] = "80163348",
            ["SpeakNpcId"] = 700389,
            },
        [51165205] = {
            ["Content"] = "那不打扰了，谢谢您。",
            ["DialogueId"] = 51165205,
            ["GUID"] = "80163372",
            ["SpeakNpcId"] = 100001,
            },
        [51165206] = {
            ["Content"] = "慢着慢着！我突然想起来……商……村里好像还真住过这号人物，但现在好像已经搬走了。",
            ["DialogueId"] = 51165206,
            ["GUID"] = "8016339C",
            ["SpeakNpcId"] = 700389,
            },
        [51165207] = {
            ["Content"] = "大概是五年前？具体时间我也没什么印象了，有个皓京城来的琴师，名唤宫先生，曾带着他的徒弟搬来椒兰村，他那徒弟就叫清商。",
            ["DialogueId"] = 51165207,
            ["GUID"] = "801633C6",
            ["SpeakNpcId"] = 700389,
            },
        [51165208] = {
            ["Content"] = "他们为什么会搬过来呀？",
            ["DialogueId"] = 51165208,
            ["GUID"] = "801633F0",
            ["SpeakNpcId"] = 200002,
            },
        [51165209] = {
            ["Content"] = "谁知道呢……宫先生好像说是要远离喧嚣之地，静心锻炼徒弟的琴艺，结果好像是出了什么矛盾，反正后面清商也跑了。",
            ["DialogueId"] = 51165209,
            ["GUID"] = "8016341A",
            ["SpeakNpcId"] = 700389,
            },
        [51165210] = {
            ["Content"] = "跑了？是主动离开还是……",
            ["DialogueId"] = 51165210,
            ["GUID"] = "80163444",
            ["SpeakNpcId"] = 100001,
            },
        [51165211] = {
            ["Content"] = "那我就不清楚了，那宫先生在清商跑了之后没多久就搬走了，但具体在哪……我还真不晓得。",
            ["DialogueId"] = 51165211,
            ["GUID"] = "8016346E",
            ["SpeakNpcId"] = 700389,
            },
        [51165301] = {
            ["Content"] = "您好，阿姨，我们想问些问题，不知道你有没有空。",
            ["DialogueId"] = 51165301,
            ["GUID"] = "80164332",
            ["SpeakNpcId"] = 100001,
            },
        [51165302] = {
            ["Content"] = "什么？怎么没空呢，今儿天好，我刚把吿苍送到晾晒场，现在正闲呢，娃娃有什么事，你就问吧。",
            ["DialogueId"] = 51165302,
            ["GUID"] = "8016435C",
            ["SpeakNpcId"] = 240038,
            },
        [51165303] = {
            ["Content"] = "我们想问问你知不知道村子里有一位琴师，名唤宫先生。",
            ["DialogueId"] = 51165303,
            ["GUID"] = "80164386",
            ["SpeakNpcId"] = 200002,
            },
        [51165304] = {
            ["Content"] = "咦？你们不像本地人啊，这事你们都知道，宫先生可是当年名动皓京的奇人呢，想听他弹琴的每回都花个上千白银，他搬来我们村子那天，我们都可高兴了。",
            ["DialogueId"] = 51165304,
            ["GUID"] = "801643B0",
            ["SpeakNpcId"] = 240038,
            },
        [51165305] = {
            ["Content"] = "他是在我们村子住过一段时间，不过后面他对那收来的徒弟坏的很，我们都看不惯，椒兰村不收这种铁石心肠的家伙，就把他劝走了。",
            ["DialogueId"] = 51165305,
            ["GUID"] = "801643DA",
            ["SpeakNpcId"] = 240038,
            },
        [51165306] = {
            ["Content"] = "对徒弟很坏？",
            ["DialogueId"] = 51165306,
            ["GUID"] = "80164404",
            ["SpeakNpcId"] = 100001,
            },
        [51165307] = {
            ["Content"] = "对啊，清商！多好的娃娃，闲下来就来村子里帮我们挑水砍柴，但那老头却说什么……做这些杂活沾染了俗气，弹不出好琴，就罚他在雨天跪了一夜。",
            ["DialogueId"] = 51165307,
            ["GUID"] = "8016442E",
            ["SpeakNpcId"] = 240038,
            },
        [51165308] = {
            ["Content"] = "啊？这也太夸张了吧，哪有这种说法啊。",
            ["DialogueId"] = 51165308,
            ["GUID"] = "80164458",
            ["SpeakNpcId"] = 200002,
            },
        [51165309] = {
            ["Content"] = "还不止呢，你可知晓咱们这到了冬天便冷的出奇，檐下滴水成冰，那老头说什么，在大寒之日练琴更有醍醐灌顶，振聋发聩之功，对练琴更有益处啊。",
            ["DialogueId"] = 51165309,
            ["GUID"] = "80164482",
            ["SpeakNpcId"] = 240038,
            },
        [51165310] = {
            ["Content"] = "可怜那娃娃，手上生的全是冻疮，大冷天来我这里借冻伤药，我看他可怜，还塞了他好些个热馍馍。",
            ["DialogueId"] = 51165310,
            ["GUID"] = "801644AC",
            ["SpeakNpcId"] = 240038,
            },
        [51165311] = {
            ["Content"] = "太过分了，怎么会有这样的师父！这简直就是虐待嘛！",
            ["DialogueId"] = 51165311,
            ["GUID"] = "801644D6",
            ["SpeakNpcId"] = 200002,
            },
        [51165312] = {
            ["Content"] = "要说虐待，倒也谈不上，毕竟那个宫先生对自己比对徒弟还要狠。那些娃娃在练琴的时候跟着练，那些娃娃没在练琴的时候，他也在练。",
            ["DialogueId"] = 51165312,
            ["GUID"] = "80164500",
            ["SpeakNpcId"] = 240038,
            },
        [51165313] = {
            ["Content"] = "我曾经问过他为什么要对自己这么狠心，他理都没理我，脾气古怪的很，感觉像是受过什么刺激一样。",
            ["DialogueId"] = 51165313,
            ["GUID"] = "8016452A",
            ["SpeakNpcId"] = 240038,
            },
        [51165314] = {
            ["Content"] = "后来有一天，清商那娃娃就不见了，也不知道是受不了这个宫先生，还是被宫先生赶走了，不过不管怎么样，都算是逃离了苦日子，是好事。",
            ["DialogueId"] = 51165314,
            ["GUID"] = "80164554",
            ["SpeakNpcId"] = 240038,
            },
        [51165315] = {
            ["Content"] = "不见了？……那宫先生现在住在哪里呢？",
            ["DialogueId"] = 51165315,
            ["GUID"] = "8016457E",
            ["SpeakNpcId"] = 100001,
            },
        [51165316] = {
            ["Content"] = "谁知道呢，清商离开后他就搬走了，但应该也没搬远，毕竟没人愿意帮他搬家了。",
            ["DialogueId"] = 51165316,
            ["GUID"] = "801645A8",
            ["SpeakNpcId"] = 240038,
            },
        [51165317] = {
            ["Content"] = "谢谢你，那我们再打探打探。",
            ["DialogueId"] = 51165317,
            ["GUID"] = "801645D2",
            ["SpeakNpcId"] = 100001,
            },
        [51165401] = {
            ["Content"] = "又香又甜的大包子嘞，皮薄馅厚，面劲十足，要来一个吗？",
            ["DialogueId"] = 51165401,
            ["GUID"] = "8016539A",
            ["SpeakNpcId"] = 700388,
            },
        [51165402] = {
            ["Content"] = "你好，我们不买包子，我们想从你这问个人，你认识一名琴师吗？",
            ["DialogueId"] = 51165402,
            ["GUID"] = "801653C4",
            ["SpeakNpcId"] = 100001,
            },
        [51165403] = {
            ["Content"] = "琴师？哦！我知晓了，你们是宫先生从外面请来的医师是吗？他怎么连地址都不跟你们说清楚呢？",
            ["DialogueId"] = 51165403,
            ["GUID"] = "801653EE",
            ["SpeakNpcId"] = 700388,
            },
        [51165404] = {
            ["Content"] = "（说实话）",
            ["DialogueId"] = 51165404,
            ["GUID"] = "80165418",
            ["ImprPlusId"] = 1207,
            },
        [51165405] = {
            ["Content"] = "（将计就计）",
            ["DialogueId"] = 51165405,
            ["GUID"] = "80165442",
            ["ImprPlusId"] = 1208,
            },
        [51165406] = {
            ["Content"] = "不是，我们只是外乡来客，想向你打听他现在的住址，找他有些事。",
            ["DialogueId"] = 51165406,
            ["GUID"] = "8016546C",
            ["SpeakNpcId"] = 100001,
            },
        [51165407] = {
            ["Content"] = "不是？他居然真没听我的劝，诶……这倔老头。",
            ["DialogueId"] = 51165407,
            ["GUID"] = "80165496",
            ["SpeakNpcId"] = 700388,
            },
        [51165408] = {
            ["Content"] = "他生了什么病呀？",
            ["DialogueId"] = 51165408,
            ["GUID"] = "801654C0",
            ["SpeakNpcId"] = 200002,
            },
        [51165409] = {
            ["Content"] = "自从宫先生的徒弟走了之后，他那咳疾便一天比一天严重，现在更是连每日奉香都没法了，他又住的偏，要是哪天被什么野兽盯上了……",
            ["DialogueId"] = 51165409,
            ["GUID"] = "801654EA",
            ["SpeakNpcId"] = 700388,
            },
        [51165410] = {
