            ["GUID"] = "8017FE54",
            ["NextDialogue"] = 51168003,
            ["Scripts"] = "SetOutport{FinishType{2},OptionIdx{1}}",
            },
        [51168003] = {
            ["Content"] = "（游船把你送到了东市。）",
            ["DialogueId"] = 51168003,
            ["GUID"] = "8017FE7E",
            ["IsBlack"] = 1,
            },
        [51168004] = {
            ["Content"] = "你……有些面熟？",
            ["DialogueId"] = 51168004,
            ["GUID"] = "8017FEA8",
            ["NextDialogue"] = 51168005,
            ["Scripts"] = "SetOutport{FinishType{2},OptionIdx{2}}",
            },
        [51168005] = {
            ["Content"] = "客人好眼力，莫不是刚从东市过来？东市那片的卖票人是我哥哥刘福，你们二位已经见过了？",
            ["DialogueId"] = 51168005,
            ["GUID"] = "8017FED2",
            ["NextDialogue"] = 51168006,
            ["SpeakNpcId"] = 701189,
            },
        [51168006] = {
            ["Content"] = "原来如此……难道还有一个兄弟叫……",
            ["DialogueId"] = 51168006,
            ["GUID"] = "8017FEFC",
            ["NextDialogue"] = 51168007,
            ["SpeakNpcId"] = 100001,
            },
        [51168007] = {
            ["Content"] = "是了，还有一位刘寿兄弟，正是为客人您撑船的船夫呢！",
            ["DialogueId"] = 51168007,
            ["GUID"] = "8017FF26",
            ["NextDialogue"] = 51168008,
            ["SpeakNpcId"] = 701189,
            },
        [51168008] = {
            ["Content"] = "福禄寿吗……哈哈……",
            ["DialogueId"] = 51168008,
            ["GUID"] = "8017FF50",
            ["SpeakNpcId"] = 100001,
            },
        [51168009] = {
