            ["GUID"] = "8017FF7A",
            ["NextDialogue"] = 51168010,
            ["SpeakNpcId"] = 701189,
            },
        [51168010] = {
            ["Content"] = "客人您早！是要来坐船去东市吗？",
            ["DialogueId"] = 51168010,
