            ["Scripts"] = "SetOutport{FinishType{2},OptionIdx{2}}",
            },
        [51168015] = {
            ["Content"] = "客人回见！",
            ["DialogueId"] = 51168015,
            ["GUID"] = "80180076.0",
            ["SpeakNpcId"] = 701189,
            },
        [51168016] = {
            ["Content"] = "游船游船，十文一趟，排队购票，客满即发。",
            ["DialogueId"] = 51168016,
            ["GUID"] = "8017FE2B",
            ["NextDialogue"] = 51168001,
            ["SpeakNpcId"] = 701189,
            },
        [51168101] = {
            ["Content"] = "额，这位素喂贫生的盆友，笔人初来炸弹，人生地鼠，敢问厕所……啊不对，玉溪室路在何处？",
            ["DialogueId"] = 51168101,
            ["GUID"] = "80180EBB",
            ["NextOptions"] = {
                [1] = 51168102,
                [2] = 51168103,
                },
            ["SpeakNpcId"] = 701190,
            },
        [51168102] = {
            ["Content"] = "？？？",
            ["DialogueId"] = 51168102,
            ["GUID"] = "80180EBC",
            ["NextDialogue"] = 51168104,
            },
        [51168103] = {
            ["Content"] = "你在说什么呢？",
            ["DialogueId"] = 51168103,
            ["GUID"] = "80180EE6",
            ["NextDialogue"] = 51168104,
            },
        [51168104] = {
            ["Content"] = "听不懂？这什么破字典……不是说这么说话华胥人一定听得懂吗？",
            ["DialogueId"] = 51168104,
            ["GUID"] = "80180F10",
            ["NextDialogue"] = 51168105,
            ["SpeakNpcId"] = 701190,
            },
        [51168105] = {
            ["Content"] = "难道是我说错了？等下，我再翻一下……这位情头一盒的死生只有，笔人出入华胥，人地两生，敢问玉溪识在何方？",
            ["DialogueId"] = 51168105,
            ["GUID"] = "80180F3A",
            ["NextOptions"] = {
                [1] = 51168106,
                [2] = 51168108,
                },
            ["SpeakNpcId"] = 701190,
            },
        [51168106] = {
            ["Content"] = "能不能正常说话？",
            ["DialogueId"] = 51168106,
            ["GUID"] = "80180F64",
            ["NextDialogue"] = 51168107,
            },
        [51168107] = {
            ["Content"] = "能不能在大全里对应的是……能否，正常对应的是……诶？不对？你……你不是华胥人？你听得懂我说话？",
            ["DialogueId"] = 51168107,
            ["GUID"] = "80180F8E",
            ["NextDialogue"] = 51168110,
            ["SpeakNpcId"] = 701190,
            },
        [51168108] = {
            ["Content"] = "你要问的不会是厕所在哪吧？",
            ["DialogueId"] = 51168108,
            ["GUID"] = "80180FB8",
            ["NextDialogue"] = 51168109,
            },
        [51168109] = {
            ["Content"] = "对对对，就是厕所！诶？不是……你……你能听得懂我说话？你不是华胥人？",
            ["DialogueId"] = 51168109,
            ["GUID"] = "80180FE2",
            ["NextDialogue"] = 51168110,
            ["SpeakNpcId"] = 701190,
            },
        [51168110] = {
            ["Content"] = "我的打扮也不像华胥人吧？",
            ["DialogueId"] = 51168110,
            ["GUID"] = "8018100C",
            ["NextDialogue"] = 51168111,
            ["SpeakNpcId"] = 100001,
            },
        [51168111] = {
            ["Content"] = "诶呀！可算给我找着同乡了！我请的那个，华胥翻译，刚刚跟我说肚子疼，让我在这里等他一会，就把我丢在这里。",
            ["DialogueId"] = 51168111,
            ["GUID"] = "80181036.0",
            ["NextDialogue"] = 51168112,
            ["SpeakNpcId"] = 701190,
            },
        [51168112] = {
            ["Content"] = "现在已经过去了半小时，他还没回来，我一个人在这也不敢乱走，可总在这站着也不是办法呀！",
            ["DialogueId"] = 51168112,
            ["GUID"] = "80181060.0",
            ["NextDialogue"] = 51168113,
            ["SpeakNpcId"] = 701190,
            },
        [51168113] = {
            ["Content"] = "我就想着，要不要直接去找他回来得了。但我也不知道华胥人平常都怎么说话，就去买了一本这个……喏，你看！",
            ["DialogueId"] = 51168113,
            ["GUID"] = "8018108A",
            ["NextDialogue"] = 51168114,
            ["SpeakNpcId"] = 701190,
            },
        [51168114] = {
            ["Content"] = "（泛黄的扉页上工工整整地写着——华胥问候语录大全。）",
            ["DialogueId"] = 51168114,
            ["GUID"] = "801810B4",
            ["NextOptions"] = {
                [1] = 51168115,
                },
            },
        [51168115] = {
            ["Content"] = "谁卖给你的？",
            ["DialogueId"] = 51168115,
            ["GUID"] = "801810DE",
            ["NextDialogue"] = 51168116,
            },
        [51168116] = {
            ["Content"] = "就在广场附近，有个卖报的小孩，说是看在我是外乡客的面子上便宜卖我，只收五十铜！",
            ["DialogueId"] = 51168116,
            ["GUID"] = "80181108.0",
            ["NextDialogue"] = 51168117,
            ["SpeakNpcId"] = 701190,
            },
        [51168117] = {
            ["Content"] = "还说有了这本书，所有不了解华胥语言的家伙都能变成华胥通！只需要简单的对照就好了。",
            ["DialogueId"] = 51168117,
            ["GUID"] = "80181132.0",
            ["NextOptions"] = {
                [1] = 51168118,
                [2] = 51168121,
                },
            ["SpeakNpcId"] = 701190,
            },
        [51168118] = {
            ["Content"] = "这本书过时了。",
            ["DialogueId"] = 51168118,
            ["GUID"] = "8018115C",
            ["NextDialogue"] = 51168119,
            },
        [51168119] = {
            ["Content"] = "过时了？你的意思是，华胥现在早就不这么说话了？",
            ["DialogueId"] = 51168119,
            ["GUID"] = "80181186.0",
            ["NextDialogue"] = 51168120,
            ["SpeakNpcId"] = 701190,
            },
        [51168120] = {
            ["Content"] = "你手上的那些可能是一些古华胥人说话的教学，现在大家说话都比较随意，你随便找一些华胥人聊聊天就知道了。",
            ["DialogueId"] = 51168120,
            ["GUID"] = "801811B0",
            ["NextOptions"] = {
                [1] = 51168128,
                },
            ["SpeakNpcId"] = 100001,
            },
        [51168121] = {
            ["Content"] = "问题是你也没读对啊。",
            ["DialogueId"] = 51168121,
            ["GUID"] = "801811DA",
            ["NextDialogue"] = 51168122,
            },
        [51168122] = {
            ["Content"] = "没读对？什么意思？是说我读的语录不对？",
            ["DialogueId"] = 51168122,
            ["GUID"] = "80181204.0",
            ["NextDialogue"] = 51168123,
            ["SpeakNpcId"] = 701190,
            },
        }
  end },
  { MinKey = 51168123, MaxKey = 51169731, Loader = function()
      return {
        [51168123] = {
            ["Content"] = "虽然我也对华胥语不是特别了解，但是你刚刚念的只交，应该是知交吧？初来炸弹听起来也很奇怪，应该是初来乍到？",
            ["DialogueId"] = 51168123,
            ["GUID"] = "8018122E",
            ["NextDialogue"] = 51168124,
            ["SpeakNpcId"] = 100001,
            },
        [51168124] = {
            ["Content"] = "啊！原来是这样啊！哎呀，你看我这……所以其实这翻译也没必要请，现在大家说话也都差不多？",
            ["DialogueId"] = 51168124,
            ["GUID"] = "80181258.0",
            ["NextDialogue"] = 51168125,
            ["SpeakNpcId"] = 701190,
            },
        [51168125] = {
            ["Content"] = "差不多……吧。",
            ["DialogueId"] = 51168125,
