        [51168503] = {
            ["Content"] = "甜橙",
            ["DialogueId"] = 51168503,
            ["GUID"] = "80185086.0",
            },
        [51168504] = {
            ["Content"] = "大蒜",
            ["DialogueId"] = 51168504,
            ["GUID"] = "801850B0",
            },
        [51168601] = {
            ["Content"] = "白又方，嫩又香，能做菜，能煮汤，豆子是它爹和娘，它和爹娘不一样。",
            ["DialogueId"] = 51168601,
            ["GUID"] = "8018609A",
            ["NextOptions"] = {
                [1] = 51168602,
                [2] = 51168603,
                [3] = 51168604,
                },
            },
        [51168602] = {
            ["Content"] = "豆腐",
            ["DialogueId"] = 51168602,
            ["GUID"] = "801860C4",
            },
        [51168603] = {
            ["Content"] = "千张",
            ["DialogueId"] = 51168603,
            ["GUID"] = "801860EE",
            },
        [51168604] = {
            ["Content"] = "豆泡",
            ["DialogueId"] = 51168604,
            ["GUID"] = "80186118.0",
            },
        [51168605] = {
            ["Content"] = "我考考你，这道题的谜底是什么？",
            ["DialogueId"] = 51168605,
            ["GUID"] = "80186142.0",
            },
        [51168606] = {
            ["Content"] = "还用你考我呢？我可随便就答出来了~",
            ["DialogueId"] = 51168606,
            ["GUID"] = "8018616C",
            },
        [51168701] = {
            ["Content"] = "年终岁尾，不缺鱼米。",
