            ["GUID"] = "80193732.0",
            ["NextDialogue"] = 51169910,
            },
        [51169910] = {
            ["Content"] = "倒也没那么绝对……只是你也看出来了，这种行为十分冒犯，尤其是选址还是在这执律阁前，皓京最庄严的地方！",
