            ["GUID"] = "801D0EC0",
            },
        [51175905] = {
            ["Content"] = "不用了，谢谢阿伯。",
            ["DialogueId"] = 51175905,
            ["GUID"] = "801D0EEA",
            },
        [51175906] = {
