            ["DialogueId"] = 60140401,
            ["Duration"] = 4,
            ["GUID"] = "968E208A",
            ["VoiceName"] = "voice/$Locale$/story/1002/101125/968E208A",
            },
        [60140402] = {
            ["Content"] = "你是我们一生的骄傲。",
            ["ContentKR"] = "넌 우리 인생 최고의 자랑이란다. ",
            ["DialogueId"] = 60140402,
            ["Duration"] = 3,
            ["GUID"] = "968E20B4",
            ["VoiceName"] = "voice/$Locale$/story/1002/101125/968E20B4",
            },
        [60140403] = {
            ["Content"] = "赛琪，来拉钩，我们要做一辈子的好朋友！",
            ["ContentKR"] = "프시케, 자, 약속! 이제 우리는 영원한 친구야!",
            ["DialogueId"] = 60140403,
            ["Duration"] = 4,
            ["GUID"] = "968E20DE",
            ["VoiceName"] = "voice/$Locale$/story/1002/101125/968E20DE",
            },
        [60140404] = {
            ["Content"] = "我会记住你曾经活过。",
            ["ContentKR"] = "네가 살아있었음을 기억할게. ",
            ["DialogueId"] = 60140404,
            ["Duration"] = 3,
            ["GUID"] = "968E2108",
            ["VoiceName"] = "voice/$Locale$/story/1002/101125/968E2108",
            },
        [60140405] = {
            ["Content"] = "我们等你回来。",
            ["ContentKR"] = "우리가 널 기다리고 있어. ",
            ["DialogueId"] = 60140405,
            ["Duration"] = 2.5,
            ["GUID"] = "968E2132",
            ["VoiceName"] = "voice/$Locale$/story/1002/101125/968E2132",
            },
        [60140406] = {
            ["Content"] = "命运啊，求你怜悯我唯一一次，让我帮她实现这个愿望吧。",
            ["ContentKR"] = "운명이여, 한 번이라도 자비를 베풀어 그 아이의 소원을 이뤄줄 수 있게 해 주오. ",
            ["DialogueId"] = 60140406,
            ["Duration"] = 6,
            ["GUID"] = "968E215C",
            ["VoiceName"] = "voice/$Locale$/story/1002/101125/968E215C",
            },
        [60140407] = {
            ["Content"] = "带上这朵花吧，它会给你带来好运。",
            ["ContentKR"] = "이 꽃을 가져가렴, 행운을 가져다줄 거야. ",
            ["DialogueId"] = 60140407,
            ["Duration"] = 3,
            ["GUID"] = "968E2186",
            ["VoiceName"] = "voice/$Locale$/story/1002/101125/968E2186",
            },
        [60140408] = {
            ["Content"] = "你可以去一座小岛，在那里盖几间房子，在房子边种满白色的花。",
            ["ContentKR"] = "작은 섬에 가면 집 몇 채를 짓고, 집 주변에 하얀 꽃을 가득 심을 수 있어. ",
            ["DialogueId"] = 60140408,
            ["Duration"] = 6,
            ["GUID"] = "968E21B0",
            ["VoiceName"] = "voice/$Locale$/story/1002/101125/968E21B0",
            },
        [60140409] = {
            ["Content"] = "赛琪，我来带你回家。",
            ["ContentKR"] = "프시케, 집에 가자.",
            ["DialogueId"] = 60140409,
            ["Duration"] = 3,
            ["GUID"] = "968E21DA",
            ["VoiceName"] = "voice/$Locale$/story/1002/101125/968E21DA",
            },
        [60140501] = {
            ["Content"] = "所有审判，皆为正义。",
            ["ContentKR"] = "심판은 곧 정의다.",
            ["DialogueId"] = 60140501,
            ["Duration"] = 5,
            ["GUID"] = "968E30F2",
            ["VoiceName"] = "sfx/boss/Lianhuo/vo_$Locale$_battleStart",
            },
        [60140502] = {
            ["Content"] = "竟敢反抗律法……",
            ["ContentKR"] = "감히 법에 맞서다니...",
            ["DialogueId"] = 60140502,
            ["Duration"] = 5,
            ["GUID"] = "968E311C",
            ["VoiceName"] = "sfx/boss/Lianhuo/vo_$Locale$_condemn",
            },
        [60140503] = {
            ["Content"] = "你……在怒火面前证明了自己。",
            ["ContentKR"] = "넌... 맹렬한 불 앞에서 자신을 증명했다.",
            ["DialogueId"] = 60140503,
            ["Duration"] = 5,
            ["GUID"] = "968E3146",
            ["VoiceName"] = "sfx/boss/Lianhuo/vo_$Locale$_battleEnd",
            },
        [60140504] = {
            ["Content"] = "开始你最后的狡辩。",
            ["ContentKR"] = "마지막 변명을 시작해 봐라.",
            ["DialogueId"] = 60140504,
            ["Duration"] = 5,
            ["GUID"] = "968E3170",
            ["VoiceName"] = "sfx/boss/Lianhuo/vo_$Locale$_skill06_01",
            },
        [60140505] = {
            ["Content"] = "在宣判前，丑陋地挣扎吧。",
            ["ContentKR"] = "추하게 발버둥 쳐봐라.",
            ["DialogueId"] = 60140505,
            ["Duration"] = 5,
            ["GUID"] = "968E319A",
            ["VoiceName"] = "sfx/boss/Lianhuo/vo_$Locale$_skill06_02",
            },
        [60140506] = {
            ["Content"] = "在枷锁中迎接死亡。",
            ["ContentKR"] = "족쇄 속에서 죽음을 맞이해라.",
            ["DialogueId"] = 60140506,
            ["Duration"] = 5,
            ["GUID"] = "968E31C4",
            ["VoiceName"] = "sfx/boss/Lianhuo/vo_$Locale$_skill08_01",
            },
        [60140507] = {
            ["Content"] = "律法会历数你的罪状。",
            ["ContentKR"] = "법이 너의 죄상을 낱낱이 밝혀낼 것이다.",
            ["DialogueId"] = 60140507,
            ["Duration"] = 5,
            ["GUID"] = "968E31EE",
            ["VoiceName"] = "sfx/boss/Lianhuo/vo_$Locale$_skill08_02",
            },
        [60140508] = {
            ["Content"] = "休想逃脱火焰的囚笼。",
            ["ContentKR"] = "불의 감옥에서 도망칠 생각은 마라.",
            ["DialogueId"] = 60140508,
            ["Duration"] = 5,
            ["GUID"] = "968E3218",
            ["VoiceName"] = "sfx/boss/Lianhuo/vo_$Locale$_skill03",
            },
        [60149001] = {
            ["Content"] = "打打打打打劫，唔……这家伙看起来好猛，溜了溜了。",
            ["ContentKR"] = "가가가가가진 것 다 내놔! 윽... 만만치 않은 녀석 같은데... 도, 도망가야겠다.",
            ["DialogueId"] = 60149001,
            ["Duration"] = 5,
            ["GUID"] = "9693A37A",
            ["SpeakNpcId"] = 920001,
            ["VoiceName"] = "voice/$Locale$/char/Dajiebai/vo_birth_r01",
            },
        [60149002] = {
            ["Content"] = "可恶！怎么是你，再再再见。",
            ["ContentKR"] = "악! 왜 또 너야. 다다, 다음에 보자고.",
            ["DialogueId"] = 60149002,
            ["Duration"] = 3.8,
            ["GUID"] = "9693A3A4",
            ["SpeakNpcId"] = 920001,
            ["VoiceName"] = "voice/$Locale$/char/Dajiebai/vo_birth_r02",
            },
        [60149003] = {
            ["Content"] = "留留留下买路财！啧，怎么今天一上来就碰到硬茬子，告辞。",
            ["ContentKR"] = "지, 지나가려면 통행료를 내놔! 칫, 오늘은 왜 이렇게 강한 녀석만 나오는 거야. 그럼 이만.",
            ["DialogueId"] = 60149003,
            ["Duration"] = 6.7,
            ["GUID"] = "9693A3CE",
            ["SpeakNpcId"] = 920001,
            ["VoiceName"] = "voice/$Locale$/char/Dajiebai/vo_birth_r03",
            },
        [60149004] = {
            ["Content"] = "除了打劫，逃跑我也是专业的！",
            ["ContentKR"] = "통행료 받기 말고 도망가기도 내 전문이라고!",
            ["DialogueId"] = 60149004,
            ["Duration"] = 3.5,
            ["GUID"] = "9693A3F8",
            ["SpeakNpcId"] = 920001,
            ["VoiceName"] = "voice/$Locale$/char/Dajiebai/vo_Skill01",
            },
        [60149005] = {
            ["Content"] = "舍不得孩子套不着狼，这些都给你，别再追啦！",
            ["ContentKR"] = "보물 같은 건 없다니까! 자 이거 다 줄 테니까 그만 쫓아와!",
            ["DialogueId"] = 60149005,
            ["Duration"] = 5.1,
            ["GUID"] = "9693A422",
            ["SpeakNpcId"] = 920001,
            ["VoiceName"] = "voice/$Locale$/char/Dajiebai/vo_Skill02",
            },
        [60149006] = {
            ["Content"] = "咋还在追我啊，这个给你行了吧。",
            ["ContentKR"] = "왜 자꾸 쫓아오는 거야?! 여, 여기 주면 됐지?",
            ["DialogueId"] = 60149006,
            ["Duration"] = 3.5,
            ["GUID"] = "9693A44C",
            ["SpeakNpcId"] = 920001,
            ["VoiceName"] = "voice/$Locale$/char/Dajiebai/vo_Skill03",
            },
        [60149007] = {
            ["Content"] = "你使那么大劲干啥呢！",
            ["ContentKR"] = "왜 그, 그렇게 세게 때리는 거야!",
            ["DialogueId"] = 60149007,
            ["Duration"] = 2.5,
            ["GUID"] = "9693A476",
            ["SpeakNpcId"] = 920001,
            ["VoiceName"] = "voice/$Locale$/char/Dajiebai/vo_be_hit_heavy_r01",
            },
        [60149008] = {
            ["Content"] = "可恶，以后走夜路小心点！",
            ["ContentKR"] = "젠장, 앞으로 밤, 밤길 조심하라고!",
            ["DialogueId"] = 60149008,
            ["Duration"] = 3.2,
            ["GUID"] = "9693A4A0",
            ["SpeakNpcId"] = 920001,
            ["VoiceName"] = "voice/$Locale$/char/Dajiebai/vo_be_hit_heavy_r02",
            },
        [60149009] = {
            ["Content"] = "啊啊啊啊啊，我要生气了！",
            ["ContentKR"] = "으아아아아앗! 나 화, 화, 화낸다!",
            ["DialogueId"] = 60149009,
            ["Duration"] = 3.4,
            ["GUID"] = "9693A4CA",
            ["SpeakNpcId"] = 920001,
            ["VoiceName"] = "voice/$Locale$/char/Dajiebai/vo_be_hit_heavy_r03",
            },
        [60149010] = {
            ["Content"] = "笨笨笨蛋，追不上我吧，桀桀桀桀桀桀~",
            ["ContentKR"] = "바, 바, 바보, 못 잡겠지? 키키키킥~",
            ["DialogueId"] = 60149010,
            ["Duration"] = 6,
            ["GUID"] = "9693A4F4",
            ["SpeakNpcId"] = 920001,
            ["VoiceName"] = "voice/$Locale$/char/Dajiebai/vo_Skill04",
            },
        [60149011] = {
            ["Content"] = "这次是我大意了，下次我一定要把你打得抱头大哭，呜……",
            ["ContentKR"] = "이번엔 너무 방, 방심했네. 다음엔 네가 각, 가오하라고. 흑...",
            ["DialogueId"] = 60149011,
            ["Duration"] = 10.4,
            ["GUID"] = "9693A51E",
            ["SpeakNpcId"] = 920001,
            ["VoiceName"] = "voice/$Locale$/char/Dajiebai/vo_death",
            },
        [60149012] = {
            ["Content"] = "东西南北四条街，打听打听谁是爹，道上谁不知道我打劫皎皎的名号！",
            ["ContentKR"] = "길에서 아무나 붙잡고 물어봐! 이 강도 루나 님의 명성을 모르는 사람이 있을 것 같아!",
            ["DialogueId"] = 60149012,
            ["Duration"] = 6.9,
            ["GUID"] = "9693A548",
            ["SpeakNpcId"] = 920001,
            ["VoiceName"] = "voice/$Locale$/char/Dajiebai/vo_Run_r01",
            },
        [60149013] = {
            ["Content"] = "跟我斗，你还是太年轻了呀~",
            ["ContentKR"] = "내 상대가 되려면 넌 아직 한~~참 멀었다고~",
            ["DialogueId"] = 60149013,
            ["Duration"] = 5.7,
            ["GUID"] = "9693A572",
            ["SpeakNpcId"] = 920001,
            ["VoiceName"] = "voice/$Locale$/char/Dajiebai/vo_Run_r02",
            },
        [60149014] = {
            ["Content"] = "哼，我打打打劫皎皎可不是好惹的。",
            ["ContentKR"] = "흥~ 이 강, 강도 루나 님을 만만하게 본 건 아니겠지.",
            ["DialogueId"] = 60149014,
            ["Duration"] = 4.8,
            ["GUID"] = "9693A59C",
            ["SpeakNpcId"] = 920001,
            ["VoiceName"] = "voice/$Locale$/char/Dajiebai/vo_Run_r03",
            },
        [60149015] = {
            ["Content"] = "呼，呼……你咋还不累呢，吃啥玩意长大的啊。",
            ["ContentKR"] = "헥헥... 뭘 먹고 자랐길래 아직도 팔팔한 거야.",
            ["DialogueId"] = 60149015,
            ["Duration"] = 8.8,
            ["GUID"] = "9693A5C6",
            ["SpeakNpcId"] = 920001,
            ["VoiceName"] = "voice/$Locale$/char/Dajiebai/vo_Run_r04",
            },
        [60150001] = {
            ["Content"] = "离我远点！",
            ["ContentKR"] = "저리 꺼져!",
            ["DialogueId"] = 60150001,
            ["Duration"] = 3,
            ["GUID"] = "9694478A",
            ["SpeakNpcId"] = 200053,
            ["VoiceName"] = "sfx/enemy/Mn/Haer/vo_$Locale$_Attack01",
            },
        [60150002] = {
            ["Content"] = "非要吃点苦头？",
            ["ContentKR"] = "고통을 맛보고 싶다면 원하는 대로 해주지!",
            ["DialogueId"] = 60150002,
            ["Duration"] = 3,
            ["GUID"] = "969447B4",
            ["SpeakNpcId"] = 200053,
            ["VoiceName"] = "sfx/enemy/Mn/Haer/vo_$Locale$_Attack02",
            },
        [60150003] = {
            ["Content"] = "我跑不动了……我投降……",
            ["ContentKR"] = "더는 못 뛰겠어... 항복할게...",
            ["DialogueId"] = 60150003,
            ["Duration"] = 5,
            ["GUID"] = "969447DE",
            ["SpeakNpcId"] = 200053,
            ["VoiceName"] = "sfx/enemy/Mn/Haer/vo_$Locale$_Die",
            },
        [60150004] = {
            ["Content"] = "别逞能了！",
            ["ContentKR"] = "힘 좀 쓴다고 으스대지 마!",
            ["DialogueId"] = 60150004,
            ["Duration"] = 3,
            ["GUID"] = "96944808",
            ["SpeakNpcId"] = 200053,
            ["VoiceName"] = "sfx/enemy/Mn/Haer/vo_$Locale$_Skill01",
            },
        [60150005] = {
            ["Content"] = "别追了!",
            ["ContentKR"] = "그만 쫓아오라고!",
            ["DialogueId"] = 60150005,
            ["Duration"] = 3,
            ["GUID"] = "96944832",
            ["SpeakNpcId"] = 200053,
            ["VoiceName"] = "sfx/enemy/Mn/Haer/vo_$Locale$_Skill02",
            },
        [60150006] = {
            ["Content"] = "追不上的你们！",
            ["ContentKR"] = "날 따라잡을 순 없을 거다!",
            ["DialogueId"] = 60150006,
            ["Duration"] = 4,
            ["GUID"] = "9694485C",
            ["SpeakNpcId"] = 200053,
            ["VoiceName"] = "sfx/enemy/Mn/Haer/vo_$Locale$_Skill03",
            },
        [60160001] = {
            ["Content"] = "欢迎乘坐帝国铁道的最新专列——极光号！",
            ["DialogueId"] = 60160001,
            ["Duration"] = 4,
            ["GUID"] = "969AB02A",
            ["SpeakNpcId"] = 920001,
            },
        [60160002] = {
            ["Content"] = "最终防卫状态已经启动，进入最终防御状态。",
            ["DialogueId"] = 60160002,
            ["Duration"] = 4,
            ["GUID"] = "969AB054",
            ["SpeakNpcId"] = 920001,
            },
        [60160003] = {
            ["Content"] = "列车主炮已无反应，已记录战斗数据，后续继续优化。",
            ["DialogueId"] = 60160003,
            ["Duration"] = 4,
            ["GUID"] = "969AB07E",
            ["SpeakNpcId"] = 920001,
            },
        [60160004] = {
            ["Content"] = "月髓引擎运转已经过载，失去控制，失去控制……",
            ["DialogueId"] = 60160004,
            ["Duration"] = 4,
            ["GUID"] = "969AB0A8",
            ["SpeakNpcId"] = 920001,
            },
        [60160005] = {
            ["Content"] = "和钢铁掰掰手腕吧。",
            ["DialogueId"] = 60160005,
            ["Duration"] = 4,
            ["GUID"] = "969AB0D2",
            ["SpeakNpcId"] = 920001,
            },
        [60160006] = {
            ["Content"] = "来点惊喜，笑一笑。",
            ["DialogueId"] = 60160006,
            ["Duration"] = 4,
            ["SpeakNpcId"] = 920001,
            },
        [60160007] = {
            ["Content"] = "极光号将会以最快的速度抵达远方——",
            ["DialogueId"] = 60160007,
            ["Duration"] = 4,
            ["SpeakNpcId"] = 920001,
            },
        [60160008] = {
            ["Content"] = "听说你们一直在找炸弹？",
            ["DialogueId"] = 60160008,
            ["Duration"] = 4,
            ["SpeakNpcId"] = 920001,
            },
        [60160009] = {
            ["Content"] = "别躲嘛，别害羞。",
            ["DialogueId"] = 60160009,
            ["Duration"] = 4,
            ["SpeakNpcId"] = 920001,
            },
        [60170001] = {
            ["Content"] = "死……死！",
            ["ContentKR"] = "죽어... 죽어!",
            ["DialogueId"] = 60170001,
            ["Duration"] = 1.5,
            ["GUID"] = "96A118CA",
            ["VoiceName"] = "sfx/boss/Tuosi/vo_$Locale$_BattleStart01",
            },
        [60170002] = {
            ["Content"] = "吼……呃……啊啊啊啊……",
            ["ContentKR"] = "크아... 윽... 아아아아...",
            ["DialogueId"] = 60170002,
            ["Duration"] = 1.5,
            ["GUID"] = "96A118F4",
            ["VoiceName"] = "sfx/boss/Tuosi/vo_$Locale$_Skill06",
            },
        [60170003] = {
            ["Content"] = "嘎嗷嗷嗷……吼……吼！！",
            ["ContentKR"] = "캬오오오... 크아... 크아!!",
            ["DialogueId"] = 60170003,
            ["Duration"] = 4,
            ["GUID"] = "96A1191E",
            ["VoiceName"] = "sfx/boss/Tuosi/vo_$Locale$_Skill08",
            },
        [60180001] = {
            ["Content"] = "近吾者，必罹天劫！",
            ["ContentKR"] = "가까이 오는 자는 천벌을 받을지어다!",
            ["DialogueId"] = 60180001,
            ["Duration"] = 3,
            ["GUID"] = "9834E965",
            ["VoiceName"] = "sfx/boss/Heilong/vo_$Locale$_BattleStart",
            },
        [60180002] = {
            ["Content"] = "吼————",
            ["ContentKR"] = "크억————!",
            ["DialogueId"] = 60180002,
            ["Duration"] = 3,
            ["GUID"] = "9834E966",
            ["VoiceName"] = "sfx/boss/Heilong/vo_$Locale$_Condemn",
            },
        [60180003] = {
            ["Content"] = "俱往矣……",
            ["ContentKR"] = "끝나버렸구나...",
            ["DialogueId"] = 60180003,
            ["Duration"] = 3,
            ["GUID"] = "9834E967",
            ["VoiceName"] = "sfx/boss/Heilong/vo_$Locale$_BattleEnd",
            },
        [60180004] = {
            ["Content"] = "晦暝临世。",
            ["ContentKR"] = "진정한 암흑이 깨어난다.",
            ["DialogueId"] = 60180004,
            ["Duration"] = 4,
            ["GUID"] = "9834E968",
            ["VoiceName"] = "sfx/boss/Heilong/vo_$Locale$_Skill05",
            },
        [60180005] = {
            ["Content"] = "吼————",
            ["ContentKR"] = "어둠 속 번개여 내리쳐라——!",
            ["DialogueId"] = 60180005,
            ["Duration"] = 5,
            ["GUID"] = "9834E969",
            ["VoiceName"] = "sfx/boss/Heilong/vo_$Locale$_Skill06",
            },
        [60180006] = {
            ["Content"] = "曀曀其阴，虺虺其雷——",
            ["ContentKR"] = "크아악————!",
            ["DialogueId"] = 60180006,
            ["Duration"] = 3,
            ["GUID"] = "9834E970",
            ["VoiceName"] = "sfx/boss/Heilong/vo_$Locale$_Skill07",
            },
        [60200101] = {
            ["Content"] = "不好，我们被敌人发现了！",
            ["ContentKR"] = "이런, 적에게 들켰어!",
            ["DialogueId"] = 60200101,
            ["Duration"] = 4,
            ["GUID"] = "96B46312",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602001/96B46312",
            ["bTurnOffVoice"] = true,
            },
        [60200201] = {
            ["Content"] = "发现敌人，在他们呼叫同伴前阻止他们吧。",
            ["ContentKR"] = "적을 발견했어. 녀석들이 동료를 부르기 전에 적을 막아야 해.",
            ["DialogueId"] = 60200201,
            ["Duration"] = 4,
            ["GUID"] = "96B4737A",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602002/96B4737A",
            ["bTurnOffVoice"] = true,
            },
        [60200301] = {
            ["Content"] = "当心，敌人要去呼叫同伴了！再这样下去就麻烦啦。",
            ["ContentKR"] = "조심해, 적이 동료를 부르러 갈 거야! 이대로라면 골치 아프겠어.",
            ["DialogueId"] = 60200301,
            ["Duration"] = 4,
            ["GUID"] = "96B483E2",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602003/96B483E2",
            ["bTurnOffVoice"] = true,
            },
        [60200401] = {
            ["Content"] = "他们要去呼叫同伴，快想想办法阻止一下呀！",
            ["ContentKR"] = "그들이 동료를 부르러 갔어. 얼른 막을 방법을 생각해야 해!",
            ["DialogueId"] = 60200401,
            ["Duration"] = 4,
            ["GUID"] = "96B4944A",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602004/96B4944A",
            ["bTurnOffVoice"] = true,
            },
        [60200501] = {
            ["Content"] = "真是的，我们躲藏得这么好居然都被发现了，没办法，快点解决掉他们吧。",
            ["ContentKR"] = "나 참, 이렇게 잘 숨어 있었는데 들켜버리다니... 어쩔 수 없지. 얼른 처치해 버리자.",
            ["DialogueId"] = 60200501,
            ["Duration"] = 4,
            ["GUID"] = "96B4A4B2",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602005/96B4A4B2",
            ["bTurnOffVoice"] = true,
            },
        [60210101] = {
            ["Content"] = "委托人只能帮我们争取到一点点时间，我们趁现在快把那三台奇奇怪怪的装置拆掉吧！",
            ["ContentKR"] = "의뢰인이 벌어준 시간은 얼마 없어. 빨리빨리 저 이상한 장치 세 대를 처리하자!",
            ["DialogueId"] = 60210101,
            ["Duration"] = 4,
            ["GUID"] = "9687C88C",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602101/9687C88C",
            ["bTurnOffVoice"] = true,
            },
        [60210201] = {
            ["Content"] = "好耶，全都拆掉了，委托圆满完成！",
            ["ContentKR"] = "야호! 다 처리했어! 의뢰 임무 완벽하게 끝냈어!",
            ["DialogueId"] = 60210201,
            ["Duration"] = 3,
            ["GUID"] = "9687C892",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602102/9687C892",
            ["bTurnOffVoice"] = true,
            },
        [60210301] = {
            ["Content"] = "委托人说没时间了，我们也快撤吧！",
            ["ContentKR"] = "의뢰인이 시간이 얼마 없다고 해. 우리도 서둘러 빠져나가자!",
            ["DialogueId"] = 60210301,
            ["Duration"] = 3,
            ["GUID"] = "9687C896",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602103/9687C896",
            ["bTurnOffVoice"] = true,
            },
        [60220101] = {
            ["Content"] = "什么什么，第一场比赛这就开始了吗？",
            ["ContentKR"] = "뭐야 뭐야, 1 라운드가 벌써 시작된 거야?",
            ["DialogueId"] = 60220101,
            ["Duration"] = 4,
            ["GUID"] = "9687C89A",
            ["NextDialogue"] = 60220102,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602201/9687C89A",
            ["bTurnOffVoice"] = true,
            },
        [60220102] = {
            ["Content"] = "我看看哇……第一场我们要做的是淘汰“神奇的同盟”这支队伍的种子选手！",
            ["ContentKR"] = "어디 보자... 우리가 1 라운드에서 할 일은 '포세이돈 동맹'이라는 팀의 시드 선수를 탈락시키는 거야!",
            ["DialogueId"] = 60220102,
            ["Duration"] = 3,
            ["GUID"] = "9687C89E",
            ["NextDialogue"] = 60220103,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602201/9687C89E",
            ["bTurnOffVoice"] = true,
            },
        [60220103] = {
            ["Content"] = "但我们根本不知道其他人藏在哪嘛！去周围找找线索吧。",
            ["ContentKR"] = "근데 우린 다른 사람들이 어디 숨어 있는지 모르잖아! 일단 주변에서 단서를 찾아보자.",
            ["DialogueId"] = 60220103,
            ["Duration"] = 3,
            ["GUID"] = "9687C8A2",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602201/9687C8A2",
            ["bTurnOffVoice"] = true,
            },
        [60220201] = {
            ["Content"] = "知道他们的种子选手藏在哪了！去打败啊不是，淘汰他们吧~",
            ["ContentKR"] = "시드 선수가 어디 숨어 있는지 알았어! 가서 혼내주... 아니, 탈락시키자!",
            ["DialogueId"] = 60220201,
            ["Duration"] = 3,
            ["GUID"] = "9687C8A6",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602202/9687C8A6",
            ["bTurnOffVoice"] = true,
            },
        [60220301] = {
            ["Content"] = "下场好像是个抢地盘的比赛耶，我们快过去吧。",
            ["ContentKR"] = "다음은 땅따먹기 시합인가 본데? 얼른 가보자.",
            ["DialogueId"] = 60220301,
            ["Duration"] = 3,
            ["GUID"] = "9687C8AA",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602203/9687C8AA",
            ["bTurnOffVoice"] = true,
            },
        [60220401] = {
            ["Content"] = "把他们从指定区域赶走！这场比赛的胜利必将属于我们“军团长天下第一”。",
            ["ContentKR"] = "녀석들을 우리 구역에서 쫓아내라! 이번 시합은 꼭 우리 '천하제일 군단장'에서 승리해야 한다.",
            ["DialogueId"] = 60220401,
            ["Duration"] = 4,
            ["GUID"] = "9687C8AE",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 930002,
            ["VoiceName"] = "voice/$Locale$/story/0/602204/9687C8AE",
            ["bTurnOffVoice"] = true,
            },
        [60220501] = {
            ["Content"] = "军团的骄傲，靠你们了。",
            ["ContentKR"] = "군단의 명예는 너희에게 달렸다!",
            ["DialogueId"] = 60220501,
            ["Duration"] = 4,
            ["GUID"] = "9687C8B2",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 930002,
            ["VoiceName"] = "voice/$Locale$/story/0/602205/9687C8B2",
            ["bTurnOffVoice"] = true,
            },
        [60220601] = {
            ["Content"] = "可恶，居然如此难缠，看来不是保留实力的时候了。",
            ["ContentKR"] = "젠장, 생각보다 끈질기군. 어쩔 수 없이 진짜 실력을 보여줘야겠구나.",
            ["DialogueId"] = 60220601,
            ["Duration"] = 4,
            ["GUID"] = "9687C8B6",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 930002,
            ["VoiceName"] = "voice/$Locale$/story/0/602206/9687C8B6",
            ["bTurnOffVoice"] = true,
            },
        [60220701] = {
            ["Content"] = "虽然输了……但下场比赛，我们还有机会！",
            ["ContentKR"] = "져버리다니... 하지만 다음 시합에선 아직 기회가 있다!",
            ["DialogueId"] = 60220701,
            ["Duration"] = 3,
            ["GUID"] = "9687C8BA",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 930002,
            ["VoiceName"] = "voice/$Locale$/story/0/602207/9687C8BA",
            ["bTurnOffVoice"] = true,
            },
        [60220801] = {
            ["Content"] = "终于到第三场比赛了呀，快去奖箱那里吧，绝不能让其他人抢走！",
            ["ContentKR"] = "드디어 3 라운드야. 얼른 보물 상자로 가자, 절대 다른 사람한테 빼앗기면 안 돼!",
            ["DialogueId"] = 60220801,
            ["Duration"] = 4,
            ["GUID"] = "9687C8BE",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602208/9687C8BE",
            ["bTurnOffVoice"] = true,
            },
        [60220901] = {
            ["Content"] = "开始了开始了！从这群家伙手里夺回钥匙，打开最后的宝箱吧。",
            ["ContentKR"] = "자, 시작됐어! 저 녀석들한테서 열쇠를 빼앗아서, 마지막 보물 상자를 열어야 해.",
            ["DialogueId"] = 60220901,
            ["Duration"] = 3,
            ["GUID"] = "9687C8C2",
            ["NextDialogue"] = 60220902,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602209/9687C8C2",
            ["bTurnOffVoice"] = true,
            },
        [60220902] = {
            ["Content"] = "一群异教徒，妄想染指神赐的宝物。准备好承受祂的怒火了吗？",
            ["ContentKR"] = "이교도 놈들, 감히 신이 내린 보물에 손대려 하다니! 신의 노여움을 감당할 수 있겠느냐!",
            ["DialogueId"] = 60220902,
            ["Duration"] = 4,
            ["GUID"] = "9687C8C4",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 930003,
            ["VoiceName"] = "voice/$Locale$/story/0/602209/9687C8C4",
            ["bTurnOffVoice"] = true,
            },
        [60221001] = {
            ["Content"] = "去吧，神最虔诚的信徒们，为祂摘下名为胜利的果实。",
            ["ContentKR"] = "가자, 가장 경건한 신도들이여! 신에게 바칠 승리의 열매를 위하여!",
            ["DialogueId"] = 60221001,
            ["Duration"] = 4,
            ["GUID"] = "9687C8C6",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 930003,
            ["VoiceName"] = "voice/$Locale$/story/0/602210/9687C8C6",
            ["bTurnOffVoice"] = true,
            },
        [60221101] = {
            ["Content"] = "为了军团的荣耀，前进！",
            ["ContentKR"] = "군단의 영광을 위하여, 전진하라!",
            ["DialogueId"] = 60221101,
            ["Duration"] = 4,
            ["GUID"] = "9687C8CA",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 930002,
            ["VoiceName"] = "voice/$Locale$/story/0/602211/9687C8CA",
            ["bTurnOffVoice"] = true,
            },
        [60221201] = {
            ["Content"] = "如我所料，大赛最重要的还是第三场。现在，该我们大显身手了。",
            ["ContentKR"] = "생각했던 대로, 역시 3라운드가 가장 중요하군. 이제 우리 실력을 제대로 보여주자.",
            ["DialogueId"] = 60221201,
            ["Duration"] = 4,
            ["GUID"] = "9687C8CE",
            ["SpeakNpcId"] = 930004,
            ["VoiceName"] = "voice/$Locale$/story/0/602212/9687C8CE",
            ["bTurnOffVoice"] = true,
            },
        [60221301] = {
            ["Content"] = "这样就打开第一把锁了，剩下的也继续加油吧！",
            ["ContentKR"] = "첫 번째 잠금장치를 열었어. 힘내서 나머지 것들도 계속 열어 보자!",
            ["DialogueId"] = 60221301,
            ["Duration"] = 3,
            ["GUID"] = "9687C8D2",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602213/9687C8D2",
            ["bTurnOffVoice"] = true,
            },
        [60221401] = {
            ["Content"] = "宝箱开啦，好耶！是我们赢喽~",
            ["ContentKR"] = "와, 보물 상자가 열렸다! 우리가 이겼어~",
            ["DialogueId"] = 60221401,
            ["Duration"] = 3,
            ["GUID"] = "9687C8D6",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602214/9687C8D6",
            ["bTurnOffVoice"] = true,
            },
        [60221501] = {
            ["Content"] = "看那边看那边，主办方往赛场里丢进来一把新钥匙！",
            ["ContentKR"] = "우와, 저기 봐! 주최 측에서 경기장에 새로운 열쇠 하나를 추가했어!",
            ["DialogueId"] = 60221501,
            ["Duration"] = 4,
            ["GUID"] = "9687C8DA",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602215/9687C8DA",
            ["bTurnOffVoice"] = true,
            },
        [60221601] = {
            ["Content"] = "为了军团的荣耀，前进！",
            ["ContentKR"] = "군단의 영광을 위하여, 전진하라!",
            ["DialogueId"] = 60221601,
            ["Duration"] = 4,
            ["GUID"] = "9687C8DE",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 930005,
            ["VoiceName"] = "voice/$Locale$/story/0/602216/9687C8DE",
            ["bTurnOffVoice"] = true,
            },
        [60230101] = {
            ["Content"] = "赶快去找药剂台吧。",
            ["ContentKR"] = "제약 설비를 얼른 찾아보자.",
            ["DialogueId"] = 60230101,
            ["Duration"] = 4,
            ["GUID"] = "96910001",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602301/96910001",
            ["bTurnOffVoice"] = true,
            },
        [60230201] = {
            ["Content"] = "对了对了，要让药剂台回收血清的话，就得在它附近打倒敌人才行！",
            ["ContentKR"] = "아참, 제약 설비에 혈청을 회수하려면, 설비 근처에서 적을 쓰러뜨려야 해!",
            ["DialogueId"] = 60230201,
            ["Duration"] = 4,
            ["GUID"] = "96910029",
            ["NextDialogue"] = 60230202,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602302/96910029",
            ["bTurnOffVoice"] = true,
            },
        [60230202] = {
            ["Content"] = "把药剂台装满就能完成委托了，加油加油。",
            ["ContentKR"] = "제약 설비를 가득 채우면 의뢰를 완료할 수 있어. 힘내!",
            ["DialogueId"] = 60230202,
            ["Duration"] = 4,
            ["GUID"] = "96910191",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602302/96910191",
            ["bTurnOffVoice"] = true,
            },
        [60230301] = {
            ["Content"] = "嘘……我听到一些奇怪的动静，好像有大家伙要来了！",
            ["ContentKR"] = "쉿... 뭔가 수상한 소리가 들리는 것 같아. 덩치 큰 녀석이 오고 있나 봐!",
            ["DialogueId"] = 60230301,
            ["Duration"] = 4,
            ["GUID"] = "96910321",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602303/96910321",
            ["bTurnOffVoice"] = true,
            },
        [60230401] = {
            ["Content"] = "哇啊啊，有个大家伙带着一大片毒雾冲过来了，药剂台里的血清一下子就会被它侵蚀干净的，快解决掉它吧！",
            ["ContentKR"] = "으아아, 저 녀석이 거대한 독 안개를 몰고 왔잖아. 이러다간 제약 설비 안에 있는 혈청이 전부 다 침식돼 버릴 거야. 얼른 해치워야 해!",
            ["DialogueId"] = 60230401,
            ["Duration"] = 4,
            ["GUID"] = "969104B1",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602304/969104B1",
            ["bTurnOffVoice"] = true,
            },
        [60240101] = {
            ["Content"] = "比赛开始了，启动计数装置，在它们周围淘汰别的参赛队伍吧！",
            ["DialogueId"] = 60240101,
            ["Duration"] = 4,
            ["GUID"] = "96A20000",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602401/96A20000",
            },
        [60240201] = {
            ["Content"] = "打开计数装置喽，在装置周围狠狠地淘汰他们吧！",
            ["DialogueId"] = 60240201,
            ["Duration"] = 4,
            ["GUID"] = "96A20004",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602402/96A20004",
            },
        [60240301] = {
            ["Content"] = "计数装置怎么又关掉啦，快去重新启动一下吧。",
            ["DialogueId"] = 60240301,
            ["Duration"] = 4,
            ["GUID"] = "96A20008",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602403/96A20008",
            },
        [60240401] = {
            ["Content"] = "好耶！淘汰了这么多人总算凑够这台计数装置的要求了，去下一台装置吧。",
            ["DialogueId"] = 60240401,
            ["Duration"] = 4,
            ["GUID"] = "96A2000C",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602404/96A2000C",
            },
        [60240501] = {
            ["Content"] = "第一场比赛轻轻松松嘛，去下个赛场，拿下固定载具的控制权吧~",
            ["DialogueId"] = 60240501,
            ["Duration"] = 3,
            ["GUID"] = "96A20010",
            ["NextDialogue"] = 60240502,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602405/96A20010",
            },
        [60240502] = {
            ["Content"] = "找到第一台固定载具啦，赶紧激活它吧。",
            ["DialogueId"] = 60240502,
            ["Duration"] = 4,
            ["GUID"] = "96A20014",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602405/96A20014",
            },
        [60240601] = {
            ["Content"] = "其他参赛选手靠过来啦，快点淘汰他们，保护好固定载具吧。",
            ["DialogueId"] = 60240601,
            ["Duration"] = 4,
            ["GUID"] = "96A20018",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602406/96A20018",
            },
        [60240701] = {
            ["Content"] = "保护成功！赶在其他人之前激活下一个固定载具吧。",
            ["DialogueId"] = 60240701,
            ["Duration"] = 4,
            ["GUID"] = "96A2001C",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602407/96A2001C",
            },
        [60240801] = {
            ["Content"] = "第二场比赛也赢啦！去最后一场比赛的起点吧。",
            ["DialogueId"] = 60240801,
            ["Duration"] = 3,
            ["GUID"] = "96A20020",
            ["NextDialogue"] = 60240802,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602408/96A20020",
            },
        [60240802] = {
            ["Content"] = "移动载具好像塞在很里面的位置呢，把它找出来再送到终点就算我们赢喽！",
            ["DialogueId"] = 60240802,
            ["Duration"] = 4,
