            ["DialogueId"] = 71002105,
            ["GUID"] = "B1BF0EDA",
            ["SpeakNpcId"] = 818008,
            },
        [71002106] = {
            ["Content"] = "啊？？我上个厕所的工夫，大伙怎么打起来了！",
            ["ContentKR"] = "엥?? 내가 화장실 좀 다녀온 사이에 무슨 일이 일어난 거야!",
            ["DialogueId"] = 71002106,
            ["GUID"] = "B1BF0F04",
            ["NextDialogue"] = 71002107,
            ["SpeakNpcId"] = 818007,
            },
        [71002107] = {
            ["Content"] = "他们先动手的。",
            ["ContentKR"] = "저쪽이 먼저 시작했어요.",
            ["DialogueId"] = 71002107,
            ["GUID"] = "B1BF0F2E",
            ["NextDialogue"] = 71002108,
            ["SpeakNpcId"] = 100001,
            },
        [71002108] = {
            ["Content"] = "你这家伙找的什么人啊，连军团的物资都敢偷。",
            ["ContentKR"] = "이런 사람을 어떻게 구했냐, 군단의 물자까지 감히 훔치려 들다니.",
            ["DialogueId"] = 71002108,
            ["GUID"] = "B1BF0F58",
            ["NextDialogue"] = 71002109,
            ["SpeakNpcId"] = 818008,
            },
        [71002109] = {
            ["Content"] = "啊？哦！2条弹匣和1把步枪是吧，在我这儿呢，我把自己那份直接拿走了。",
            ["ContentKR"] = "엥? 아! 탄창 2개랑 소총 1정? 여기 있어, 여기. 내 몫은 미리 챙겼거든.",
            ["DialogueId"] = 71002109,
            ["GUID"] = "B1BF0F82",
            ["NextDialogue"] = 71002110,
            ["SpeakNpcId"] = 818007,
            },
        [71002110] = {
            ["Content"] = "你也太不谨慎了——军团的物资随手丢给路人？万一是同盟的家伙怎么交差？",
            ["ContentKR"] = "너무 경솔했잖아요. 군단 물자를 지나가는 사람한테 맡기다니? 만약 동맹 놈들이었으면 어쩔 뻔했어요?",
            ["DialogueId"] = 71002110,
