        [71005504] = {
            ["Content"] = "（几只秽兽徘徊在水道上游，不时发出嘶哑的吼叫。这大概就是吓到男子的声音。）",
            ["ContentKR"] = "(수로 상류에서 필토이드 몇 마리가 어슬렁거리며 쉰 목소리로 울부짖고 있다. 남자를 놀라게 한 것도 아마 이 소리일 것이다.)",
            ["DialogueId"] = 71005504,
            ["GUID"] = "B1C13CFE",
            ["SpeakNpcId"] = 800006,
            },
        [71005505] = {
            ["Content"] = "（所有秽兽被你击退，四周恢复了寂静。回去告诉男子吧。）",
            ["ContentKR"] = "(필토이드를 전부 처치하고 나니, 주변은 다시 조용해졌다. 이제 돌아가서, 남자에게 알려주자.)",
            ["DialogueId"] = 71005505,
            ["GUID"] = "B1C13D28",
            ["SpeakNpcId"] = 800006,
            },
        [71005506] = {
            ["Content"] = "（几块金属卡在了水道旁，不时发出刺耳的声响。这大概就是吓到男子的声音。）",
            ["ContentKR"] = "(수로 옆에 금속 조각 몇 개가 끼어 있어, 가끔 날카로운 소리를 낸다. 남자를 놀라게 한 것도 아마 이 소리일 것이다.)",
            ["DialogueId"] = 71005506,
            ["Duration"] = 3,
            ["GUID"] = "B1C13D52",
            ["NextDialogue"] = 71005507,
            ["SpeakNpcId"] = 800006,
            },
        [71005507] = {
            ["Content"] = "（你将金属捡起，因为金属永远不缺买家。等完成男子的委托就找个地方把它们卖掉吧。）",
            ["ContentKR"] = "(금속을 주웠다. 금속을 사려는 사람은 어디든 있으니, 남자의 의뢰를 마친 후, 적당한 곳에 팔아넘기자.)",
            ["DialogueId"] = 71005507,
            ["GUID"] = "B1C13D53",
            ["SpeakNpcId"] = 800006,
            },
        [71005508] = {
            ["Content"] = "我听不到可怕的声音了，谢谢你。",
            ["ContentKR"] = "무서운 소리가 이제 안 들려요. 정말 감사해요...",
            ["DialogueId"] = 71005508,
            ["GUID"] = "B1C13D7C",
            ["SpeakNpcId"] = 818049,
            },
        [71005601] = {
            ["Content"] = "哼啊啊啊……好重……鱼线，拉不起来了……",
            ["ContentKR"] = "으아아... 너무 무거워... 낚싯줄이 도무지 안 올라와...",
            ["DialogueId"] = 71005601,
            ["GUID"] = "B1C14C6A",
            ["SpeakNpcId"] = 818050,
            },
        [71005602] = {
            ["Content"] = "发生什么了？",
            ["ContentKR"] = "무슨 일인가요?",
            ["DialogueId"] = 71005602,
            ["GUID"] = "B1C14C94",
            ["NextDialogue"] = 71005603,
            ["SpeakNpcId"] = 100001,
            },
        [71005603] = {
            ["Content"] = "狩月人是你啊，我的鱼线被下面几块垃圾缠住了，你能帮帮我吗？",
            ["ContentKR"] = "월석 사냥꾼이시군. 내 낚싯줄이 저 밑에 쓰레기에 걸렸는데, 도와줄 수 있겠나?",
            ["DialogueId"] = 71005603,
            ["GUID"] = "B1C14CBE",
            ["NextOptions"] = {
                [1] = 710056031,
                [2] = 710056032,
                },
            ["SpeakNpcId"] = 818050,
            },
        [71005604] = {
            ["Content"] = "好，那我在这边拉，你去那边打碎垃圾。",
            ["ContentKR"] = "좋아, 내가 이쪽에서 당길 테니, 당신은 저쪽에서 쓰레기를 처리해 줘.",
            ["DialogueId"] = 71005604,
            ["GUID"] = "B1C14CE8",
            ["SpeakNpcId"] = 818050,
            },
        [71005605] = {
            ["Content"] = "呼……拉起来了，谢谢你哈。",
            ["ContentKR"] = "휴— 드디어 올라왔군. 고맙네.",
            ["DialogueId"] = 71005605,
            ["GUID"] = "B1C14D12",
            ["SpeakNpcId"] = 818050,
            },
        [71005701] = {
            ["Content"] = "救命啊，有没有人来救救我。",
            ["ContentKR"] = "살려주세요, 누가 좀 도와주세요.",
            ["DialogueId"] = 71005701,
            ["GUID"] = "B1C15CD2",
            ["SpeakNpcId"] = 818051,
            },
        [71005702] = {
            ["Content"] = "多谢……那个，能不能再帮我一个小忙。我逃跑的时候把鱼竿落在前面了，但那里还有几只秽兽……",
            ["ContentKR"] = "고맙네... 그런데 혹시, 부탁 하나만 더 해도 될까? 도망치다 보니 낚싯대를 저 앞에 두고 와버렸는데, 거기 필토이드가 몇 마리 있어서 말이지...",
            ["DialogueId"] = 71005702,
            ["GUID"] = "B1C15CFC",
            ["NextOptions"] = {
                [1] = 710057021,
                [2] = 710057022,
                },
            ["SpeakNpcId"] = 818051,
            },
        [71005703] = {
            ["Content"] = "谢谢谢谢，我就在这等你哈。",
            ["ContentKR"] = "고마워! 난 그럼 여기서 기다리지.",
            ["DialogueId"] = 71005703,
            ["GUID"] = "B1C15D26",
            ["SpeakNpcId"] = 818051,
            },
        [71005704] = {
            ["Content"] = "就是这根鱼竿，谢谢你！",
            ["ContentKR"] = "맞아, 바로 이 낚싯대야, 고마워!",
            ["DialogueId"] = 71005704,
            ["GUID"] = "B1C15D50",
            ["SpeakNpcId"] = 818051,
            },
        [71005801] = {
            ["Content"] = "喂，那边的狩月人，我这里有个大便宜要不要来看看。",
            ["ContentKR"] = "저기요, 월석 사냥꾼님! 제가 대박 기회를 찾아냈는데, 보실래요?",
            ["DialogueId"] = 71005801,
            ["GUID"] = "B1C16D3A",
            ["SpeakNpcId"] = 818052,
            },
        [71005802] = {
            ["Content"] = "我在前面发现了一堆银辉石，但我实在拿不下了，就全让给你吧。有兴趣的话我就带你过去。",
            ["ContentKR"] = "앞쪽에서 실버라이트 더미를 발견했는데, 혼자선 도저히 다 못 들겠더라고요. 전부 드릴 테니 관심 있으시면 같이 가요!",
            ["DialogueId"] = 71005802,
            ["GUID"] = "B1C16D64",
            ["NextOptions"] = {
                [1] = 710058031,
                [2] = 710058032,
                },
            ["SpeakNpcId"] = 818052,
            },
        [71005804] = {
            ["Content"] = "好，跟我来。",
            ["ContentKR"] = "좋아요, 따라오세요.",
            ["DialogueId"] = 71005804,
            ["GUID"] = "B1C16DB8",
            ["SpeakNpcId"] = 818052,
            },
        [71005805] = {
            ["Content"] = "第一批在这。",
            ["ContentKR"] = "첫 번째 더미는 여기 있어요.",
            ["DialogueId"] = 71005805,
            ["GUID"] = "B1C16DE2",
            ["SpeakNpcId"] = 818052,
            },
        [71005806] = {
            ["Content"] = "前面还有，你还要吗？",
            ["ContentKR"] = "앞에 더 있는데, 더 가져가실래요?",
            ["DialogueId"] = 71005806,
            ["GUID"] = "B1C16E0C",
            ["NextOptions"] = {
                [1] = 710058061,
                [2] = 710058062,
                },
            ["SpeakNpcId"] = 818052,
            },
        [71005807] = {
            ["Content"] = "好，跟我来。",
            ["ContentKR"] = "좋아요, 따라오세요.",
            ["DialogueId"] = 71005807,
            ["GUID"] = "B1C16E36",
            ["SpeakNpcId"] = 818052,
            },
        [71005808] = {
            ["Content"] = "第二批在这。",
            ["ContentKR"] = "두 번째 더미는 여기 있어요.",
            ["DialogueId"] = 71005808,
            ["GUID"] = "B1C16E60",
            ["SpeakNpcId"] = 818052,
            },
        [71005809] = {
            ["Content"] = "前面还有，你还要吗？",
            ["ContentKR"] = "앞에 더 있는데, 더 가져가실래요?",
            ["DialogueId"] = 71005809,
            ["GUID"] = "B1C16E8A",
            ["NextOptions"] = {
                [1] = 710058091,
                [2] = 710058092,
                },
            ["SpeakNpcId"] = 818052,
            },
        [71005810] = {
            ["Content"] = "好，你往前走就看到了。",
            ["ContentKR"] = "좋아요, 앞으로 가면 보일 거예요.",
            ["DialogueId"] = 71005810,
            ["GUID"] = "B1C16EB4",
            ["SpeakNpcId"] = 818052,
            },
        [71005811] = {
            ["Content"] = "就是现在，兄弟们动手！",
            ["ContentKR"] = "지금이다! 얘들아, 덮쳐!",
            ["DialogueId"] = 71005811,
            ["GUID"] = "B1C16EDE",
            ["NextDialogue"] = 71005812,
            ["SpeakNpcId"] = 818052,
            },
        [71005812] = {
            ["Content"] = "（显然银辉石都是这几名矿工装扮的强盗布置的陷阱，击退他们吧。）",
            ["ContentKR"] = "(실버라이트는 모두 광부로 변장한 강도들이 꾸민 함정이었다. 그들을 물리치자.)",
            ["DialogueId"] = 71005812,
            ["Duration"] = 3,
            ["GUID"] = "B1C16F08",
            ["SpeakNpcId"] = 800006,
            },
        [71005813] = {
            ["Content"] = "（你击退了所有人，现在可以清点一下今天的收获了。）",
            ["ContentKR"] = "(모든 강도를 물리쳤다. 이제 오늘의 수확을 차분히 정리해 보자.)",
            ["DialogueId"] = 71005813,
            ["GUID"] = "B1C16F32",
            ["SpeakNpcId"] = 800006,
            },
        [71005814] = {
            ["Content"] = "可恶，就差一点……不，我的意思是真可惜。那我就不打扰你了，再见。",
            ["ContentKR"] = "젠장, 조금만 더하면... 아, 아니요, 그냥... 진짜 아쉽네요. 더 방해하지 않을게요. 안녕히 가세요.",
            ["DialogueId"] = 71005814,
            ["GUID"] = "B1C16F5C",
            ["SpeakNpcId"] = 818052,
            },
        [71005901] = {
            ["Content"] = "爸爸跑得好快，所有人都输给你了！",
            ["ContentKR"] = "아빠 진짜 빨라요! 아빠한텐 아무도 못 이겨요!",
            ["DialogueId"] = 71005901,
            ["GUID"] = "B1C17DA2",
            ["SpeakNpcId"] = 818053,
            },
        [71005902] = {
            ["Content"] = "又有人过来了。我告诉你哦，我爸爸跑得可快了，你要不要跟他比比看！",
            ["ContentKR"] = "있잖아요, 우리 아빠 달리기 진짜 빠르거든요! 우리 아빠랑 달리기 시합하실래요?",
            ["DialogueId"] = 71005902,
            ["GUID"] = "B1C17DCC",
            ["NextOptions"] = {
                [1] = 710059021,
                [2] = 710059022,
                },
            ["SpeakNpcId"] = 818053,
            ["bForbidSkipOptions"] = true,
            },
        [71005903] = {
            ["Content"] = "咳，既然要比那就来吧。不过比之前我有几句话要跟你交代一下，请跟我来。",
            ["ContentKR"] = "하아, 시합이요... 해야죠. 다만, 시합 전에 잠깐 드릴 말씀이 있어서요. 이쪽으로 좀 와주시겠어요?",
            ["DialogueId"] = 71005903,
            ["GUID"] = "B1C17DF6",
            ["SpeakNpcId"] = 818054,
            },
        [71005904] = {
            ["Content"] = "这些钱你拿着，等会比的时候拜托你放放水哈……我……不想让儿子失望，所以就跟他编了个瞎话说谁都跑不过我。",
            ["ContentKR"] = "이 돈을 드릴 테니, 잠시 뒤 시합에서 살~짝만 봐주실 수 있을까요? 사실... 아들한테 제가 세상에서 제일 빠르다고 허풍을 떨었는데, 괜히 실망할까 봐...",
            ["DialogueId"] = 71005904,
            ["GUID"] = "B1C17E20",
            ["NextOptions"] = {
                [1] = 710059041,
                [2] = 710059042,
                },
            ["SpeakNpcId"] = 818054,
            ["bForbidSkipOptions"] = true,
            },
        [71005905] = {
            ["Content"] = "谢谢，给你添麻烦了……",
            ["ContentKR"] = "고맙습니다... 괜히 폐 끼쳐드렸네요...",
            ["DialogueId"] = 71005905,
            ["GUID"] = "B1C17E4A",
            ["SpeakNpcId"] = 818054,
            },
        [71005906] = {
            ["Content"] = "唉……好吧。",
            ["ContentKR"] = "휴... 알겠습니다.",
            ["DialogueId"] = 71005906,
            ["GUID"] = "B1C17E74",
            ["SpeakNpcId"] = 818054,
            },
        [71005907] = {
            ["Content"] = "那么比赛马上开始，爸爸加油哦！",
            ["ContentKR"] = "그럼 시합 시작이에요! 아빠, 힘내요! 화이팅!!",
            ["DialogueId"] = 71005907,
            ["GUID"] = "B1C17E9E",
            ["NextDialogue"] = 71005908,
            ["SpeakNpcId"] = 818053,
            },
        [71005908] = {
            ["Content"] = "三……",
            ["ContentKR"] = "셋...",
            ["DialogueId"] = 71005908,
            ["Duration"] = 1,
            ["GUID"] = "B1C17EC8",
            ["NextDialogue"] = 71005909,
            ["SpeakNpcId"] = 818053,
            },
        [71005909] = {
            ["Content"] = "二……",
            ["ContentKR"] = "둘...",
            ["DialogueId"] = 71005909,
            ["Duration"] = 1,
            ["GUID"] = "B1C17EF2",
            ["NextDialogue"] = 71005910,
            ["SpeakNpcId"] = 818053,
            },
        [71005910] = {
            ["Content"] = "一！",
            ["ContentKR"] = "하나!",
            ["DialogueId"] = 71005910,
            ["Duration"] = 1,
            ["GUID"] = "B1C17F1C",
            ["SpeakNpcId"] = 818053,
            },
        [71005911] = {
            ["Content"] = "哇，爸爸真的好厉害！",
            ["ContentKR"] = "와아! 아빠 진짜 최고예요!",
            ["DialogueId"] = 71005911,
            ["GUID"] = "B1C17F46",
            ["NextDialogue"] = 71005912,
            ["SpeakNpcId"] = 818053,
            },
        [71005912] = {
            ["Content"] = "谢谢……这是我的一点心意，都拿去吧。",
            ["ContentKR"] = "저기... 일부러 그러신 거죠? 고맙습니다... 이건 제 작은 성의예요. 모두 가져가세요.",
            ["DialogueId"] = 71005912,
            ["GUID"] = "B1C17F70",
            ["SpeakNpcId"] = 818054,
            },
        [71005913] = {
            ["Content"] = "喂，这跟我们说好的不一样啊……",
            ["ContentKR"] = "어라, 약속했던 거랑 다르잖아요...",
            ["DialogueId"] = 71005913,
            ["GUID"] = "B1C17F9A",
            ["NextDialogue"] = 71005914,
            ["SpeakNpcId"] = 818054,
            },
        [71005914] = {
            ["Content"] = "咦，说好的什么？",
            ["ContentKR"] = "약속? 무슨 뜻이에요?",
            ["DialogueId"] = 71005914,
            ["GUID"] = "B1C17FC4",
            ["NextDialogue"] = 71005915,
            ["SpeakNpcId"] = 818053,
            },
        [71005915] = {
            ["Content"] = "咳，没什么。抱歉啊儿子，我输了……",
            ["ContentKR"] = "흐음... 아무것도 아니란다. 미안하다, 아빠가 졌어...",
            ["DialogueId"] = 71005915,
            ["GUID"] = "B1C17FEE",
            ["NextDialogue"] = 71005916,
            ["SpeakNpcId"] = 818054,
            },
        [71005916] = {
            ["Content"] = "没事的爸爸，这次只是失误！下次我们一起赢回来！",
            ["ContentKR"] = "괜찮아요 아빠! 이번엔 실수였잖아요. 다음엔 우리 꼭 같이 이겨요!",
            ["DialogueId"] = 71005916,
            ["GUID"] = "B1C18018",
            ["NextDialogue"] = 71005917,
            ["SpeakNpcId"] = 818053,
            },
        [71005917] = {
            ["Content"] = "唉……好，好吧。来，这是你应得的奖品，都拿去吧。",
            ["ContentKR"] = "하아... 알겠다, 알겠어. 그리고 월석 사냥꾼님, 고마워요. 이건 당신이 받아야 할 보상이니 전부 가져가세요.",
            ["DialogueId"] = 71005917,
            ["GUID"] = "B1C18042",
            ["SpeakNpcId"] = 818054,
            },
        [71005918] = {
            ["Content"] = "抱歉啊儿子，我输了……",
            ["ContentKR"] = "미안하구나, 아빠가 졌어...",
            ["DialogueId"] = 71005918,
            ["GUID"] = "B1C1806C",
            ["NextDialogue"] = 71005919,
            ["SpeakNpcId"] = 818054,
            },
        [71005919] = {
            ["Content"] = "没事的爸爸，这次只是失误！下次我们一起赢回来！",
            ["ContentKR"] = "괜찮아요 아빠! 이번엔 실수였잖아요. 다음엔 우리 꼭 같이 이겨요!",
            ["DialogueId"] = 71005919,
            ["GUID"] = "B1C18096",
            ["NextDialogue"] = 71005920,
            ["SpeakNpcId"] = 818053,
            },
        [71005920] = {
            ["Content"] = "唉……好，好吧。也要谢谢这位狩月人了，这是你应得的奖品，都拿去吧。",
            ["ContentKR"] = "하아... 알겠다, 알겠어. 그리고 월석 사냥꾼님, 고마워요. 이건 당신이 받아야 할 보상이니 전부 가져가세요.",
            ["DialogueId"] = 71005920,
            ["GUID"] = "B1C180C0",
            ["SpeakNpcId"] = 818054,
            },
        [71005921] = {
            ["Content"] = "哇，爸爸真的好厉害！",
            ["ContentKR"] = "와아! 아빠 진짜 최고예요!",
            ["DialogueId"] = 71005921,
            ["GUID"] = "B1C180EA",
            ["NextDialogue"] = 71005922,
            ["SpeakNpcId"] = 818053,
            },
        [71005922] = {
            ["Content"] = "嘿……你是故意的吧。谢谢……这是我的一点心意，都拿去吧。",
            ["ContentKR"] = "고맙습니다... 이건 제 작은 성의예요. 모두 가져가세요.",
            ["DialogueId"] = 71005922,
            ["GUID"] = "B1C18114",
            ["SpeakNpcId"] = 818054,
            },
        [71006001] = {
            ["Content"] = "（游荡的秽兽挤满了四周，先击退它们，再去解救魔灵吧。）",
            ["ContentKR"] = "(주변에 떠돌던 필토이드들이 몰려들고 있다. 먼저 녀석들을 처리하고, 마령을 포획하자.)",
            ["DialogueId"] = 71006001,
            ["GUID"] = "B1C18E0A",
            ["SpeakNpcId"] = 800006,
            },
        [71006002] = {
            ["Content"] = "（争斗的声响引来了更多秽兽。）",
            ["ContentKR"] = "(싸움 소리에 이끌려, 더 많은 필토이드가 나타났다.)",
            ["DialogueId"] = 71006002,
            ["GUID"] = "B1C18E34",
            ["SpeakNpcId"] = 800006,
            },
        [71006003] = {
            ["Content"] = "（附近暂时安全了，趁现在解救魔灵吧。）",
            ["ContentKR"] = "(주변이 잠시 안전해졌다. 지금이 마령을 포획할 기회다.)",
            ["DialogueId"] = 71006003,
            ["GUID"] = "B1C18E5E",
            ["SpeakNpcId"] = 800006,
            },
        [71006101] = {
            ["Content"] = "咱不想……不想……不想上工啊……",
            ["ContentKR"] = "아흑... 일하기 싫어... 진짜 너무너무너무 일하기 싫다...",
            ["DialogueId"] = 71006101,
            ["GUID"] = "B1C19E72",
            ["SpeakNpcId"] = 818019,
            },
        [71006102] = {
            ["Content"] = "可恶……怎么这次还要往废矿送吃的啊。大家就不能挑点正常的地方吃饭吗！不怕出事吗！跑死我了……",
            ["ContentKR"] = "하윽... 왜 이번엔 또 폐광까지 배달이야?! 좀 평범한 데서 먹으면 안 돼? 사고라도 나면 어쩌려고! 진짜 이리 뛰고 저리 뛰고 죽겠어...",
            ["DialogueId"] = 71006102,
            ["GUID"] = "B1C19E9C",
            ["NextDialogue"] = 71006103,
            ["SpeakNpcId"] = 818019,
            },
        [71006103] = {
            ["Content"] = "需要帮忙吗？",
            ["ContentKR"] = "내가 도와줄까?",
            ["DialogueId"] = 71006103,
            ["GUID"] = "B1C19EC6",
            ["NextDialogue"] = 71006104,
            ["SpeakNpcId"] = 100001,
            },
        [71006104] = {
            ["Content"] = "需要！这下面全是秽兽我过不去，你帮我把这份吃的送过去吧。",
            ["ContentKR"] = "응! 저 아래는 필토이드 천지라 도저히 못 가겠어. 이거 대신 좀 배달해 줘.",
            ["DialogueId"] = 71006104,
            ["GUID"] = "B1C19EF0",
            ["NextDialogue"] = 71006105,
            ["SpeakNpcId"] = 818019,
            },
        [71006105] = {
            ["Content"] = "好，交给我吧。",
            ["ContentKR"] = "좋아, 나한테 맡겨.",
            ["DialogueId"] = 71006105,
            ["GUID"] = "B1C19F1A",
            ["SpeakNpcId"] = 100001,
            },
        [71006106] = {
            ["Content"] = "（大批秽兽拦住了你的去路，击退它们再过去吧。）",
            ["ContentKR"] = "(수많은 필토이드들이 길을 막고 있다. 다 물리치고 나서 지나가자.)",
            ["DialogueId"] = 71006106,
            ["GUID"] = "B1C19F44",
            ["SpeakNpcId"] = 800006,
            },
        [71006107] = {
            ["Content"] = "怎么还没送到……",
            ["ContentKR"] = "왜 이렇게 늦지...",
            ["DialogueId"] = 71006107,
            ["GUID"] = "B1C19F6E",
            ["SpeakNpcId"] = 818058,
            },
        [71006108] = {
            ["Content"] = "你好，你订的饭送到了。",
            ["ContentKR"] = "안녕하세요, 주문하신 음식 배달 왔습니다.",
            ["DialogueId"] = 71006108,
            ["GUID"] = "B1C19F98",
            ["NextDialogue"] = 71006109,
            ["SpeakNpcId"] = 100001,
            },
        [71006109] = {
            ["Content"] = "我看看，这都洒成什么样子，根本没法吃啊！银色和平餐厅这新服务真是不靠谱！",
            ["ContentKR"] = "잠깐만요, 이게 뭐예요? 다 쏟아져서 먹을 수가 없잖아요! '은빛 평화 식당'에서 새로 시작한 배달 서비스라더니 완전 엉망이네요!",
            ["DialogueId"] = 71006109,
            ["GUID"] = "B1C19FC2",
            ["NextOptions"] = {
                [1] = 710061091,
                [2] = 710061092,
                },
            ["SpeakNpcId"] = 818058,
            ["bForbidSkipOptions"] = true,
            },
        [71006110] = {
            ["Content"] = "这样啊……那你来送餐，比我写论文也简单不了多少。算了，这些给你，刚刚凶了你不好意思啊。",
            ["ContentKR"] = "그렇군요... 배달일도 제 논문 작성만큼 힘든 일이네요. 됐으니까 이거 받으세요. 방금 화내서 미안해요.",
            ["DialogueId"] = 71006110,
            ["GUID"] = "B1C19FEC",
            ["SpeakNpcId"] = 818058,
            },
        [71006111] = {
            ["Content"] = "（你当着地质学者的面快速吃完了饭菜。）",
            ["ContentKR"] = "(당신은 지질학자 앞에서 음식을 빠르게 먹어 치웠다.)",
            ["DialogueId"] = 71006111,
            ["Duration"] = 3,
            ["GUID"] = "B1C1A016",
            ["NextDialogue"] = 71006112,
            ["SpeakNpcId"] = 800006,
            },
        [71006112] = {
            ["Content"] = "慢点慢点，要是我害你噎死了怎么办……唉……你来送餐，比我写论文也简单不了多少。算了，这些给你，刚刚凶了你不好意思啊。",
            ["ContentKR"] = "천천히 먹어요! 괜히 체하기라도 하면 제 탓이 되잖아요... 하아... 배달일도 제 논문 작성만큼 힘든 일이네요. 됐으니까 이거 받으세요. 방금 화내서 미안해요.",
            ["DialogueId"] = 71006112,
            ["GUID"] = "B1C1A040",
            ["SpeakNpcId"] = 818058,
            },
        [71006201] = {
            ["Content"] = "今天怎么回事，这么久了一条鱼都没上钩。",
            ["ContentKR"] = "오늘 왜 이러지... 도무지 한 마리도 낚이질 않잖아.",
            ["DialogueId"] = 71006201,
            ["GUID"] = "B1C1AEDA",
            ["SpeakNpcId"] = 818055,
            },
        [71006202] = {
            ["Content"] = "狩月人你来啦，我怀疑这地方今天根本没有鱼，你能不能帮我试试？",
            ["ContentKR"] = "오, 월석 사냥꾼이군. 여긴 오늘 물고기 자체가 없는 것 같아. 그쪽이 한번 낚아보겠나?",
            ["DialogueId"] = 71006202,
            ["GUID"] = "B1C1AF04",
            ["SpeakNpcId"] = 818055,
            },
        [71006203] = {
            ["Content"] = "好，拜托你了。",
            ["ContentKR"] = "그럼 부탁하네.",
            ["DialogueId"] = 71006203,
            ["GUID"] = "B1C1AF2E",
            ["SpeakNpcId"] = 818055,
            },
        [71006204] = {
            ["Content"] = "（待捕鱼系统做好后接入捕鱼系统）",
            ["DialogueId"] = 71006204,
            ["Duration"] = 3,
            ["GUID"] = "B1C1AF58",
            ["SpeakNpcId"] = 800006,
            },
        [71006205] = {
            ["Content"] = "太厉害了，一下就钓上来了。看来不是地方的问题。",
            ["ContentKR"] = "이야, 한 번에 낚다니 대단하군. 장소 탓은 아니었나 봐...",
            ["DialogueId"] = 71006205,
            ["GUID"] = "B1C1AF82",
            ["NextDialogue"] = 71006206,
            ["SpeakNpcId"] = 818055,
            },
        [71006206] = {
            ["Content"] = "谢谢你帮我验证了一下哈，我自己再在这里试试看。今天绝对不能再提着空桶回去了！",
            ["ContentKR"] = "확인해 줘서 고맙네. 이젠 내가 해보지. 절대 오늘은 빈손으로 돌아갈 순 없으니까 말이야!",
            ["DialogueId"] = 71006206,
            ["GUID"] = "B1C1AFAC",
            ["SpeakNpcId"] = 818055,
            },
        [71006301] = {
            ["Content"] = "救命啊，有没有人来救救我。",
            ["ContentKR"] = "살려주세요, 누가 좀 도와주세요.",
            ["DialogueId"] = 71006301,
            ["GUID"] = "B1C1BF42",
            ["SpeakNpcId"] = 818056,
            },
        [71006302] = {
            ["Content"] = "多谢……那个，能不能再帮我一个小忙。我这几天一条鱼都没钓上，回去总被大家笑话。你能不能帮我钓一条呢。",
            ["ContentKR"] = "고맙네... 저기, 부탁 하나만 더 해도 될까? 요 며칠 물고기를 하나도 못 잡아서, 돌아갈 때마다 사람들한테 놀림받거든... 한 마리만 잡아주겠나?",
            ["DialogueId"] = 71006302,
            ["GUID"] = "B1C1BF6C",
            ["SpeakNpcId"] = 818056,
            },
        [71006303] = {
            ["Content"] = "谢谢谢谢，桶我给你放边上了哈。",
            ["ContentKR"] = "고맙네 고마워, 양동이는 옆에 뒀으니 그럼 부탁해~",
            ["DialogueId"] = 71006303,
            ["GUID"] = "B1C1BF96",
            ["SpeakNpcId"] = 818056,
            },
        [71006304] = {
            ["Content"] = "（待捕鱼系统做好后接入捕鱼系统）",
            ["DialogueId"] = 71006304,
            ["Duration"] = 3,
            ["GUID"] = "B1C1BFC0",
            ["SpeakNpcId"] = 800006,
            },
        [71006305] = {
            ["Content"] = "太好了，今天终于不用被大伙嘲笑了！这是我的谢礼，真是辛苦你啦。",
            ["ContentKR"] = "아이고, 드디어 오늘은 비웃음당할 일 없겠군! 이건 수고에 대한 감사의 표시네!",
            ["DialogueId"] = 71006305,
            ["GUID"] = "B1C1BFEA",
            ["SpeakNpcId"] = 818056,
            },
        [71006401] = {
            ["Content"] = "（玄色狴犴骤然出现，击退它们！）",
            ["ContentKR"] = "(갑자기 검은 폐안이 나타났다! 녀석들을 처치하자!)",
            ["DialogueId"] = 71006401,
            ["GUID"] = "B1C1CFAA",
            ["SpeakNpcId"] = 800006,
            },
        [71006501] = {
            ["Content"] = "有奖竞猜有奖竞猜，那边那位朋友要不要来看看呀。",
            ["ContentKR"] = "정답을 맞히고 상품도 타 가세요! 거기 친구, 한번 도전해 봐요.",
            ["DialogueId"] = 71006501,
            ["GUID"] = "B1C1E012",
            ["SpeakNpcId"] = 818060,
            },
        [71006502] = {
            ["Content"] = "恰逢奉香大典临近，本店特推出节庆活动，在举办一个叫非常大脑的智力问答活动，答错也有安慰奖，要不要来挑战一下？",
            ["ContentKR"] = "얼마 안 있으면 봉향대전이라, 슈퍼 브레인이라는 특별 이벤트를 준비했거든요. 틀려도 참가상은 받을 수 있는데, 어때요?",
            ["DialogueId"] = 71006502,
            ["GUID"] = "B1C1E03C",
            ["NextOptions"] = {
                [1] = 710065021,
                [2] = 710065022,
                },
            ["SpeakNpcId"] = 818060,
            ["bForbidSkipOptions"] = true,
            },
        [71006504] = {
            ["Content"] = "好，你先稍作休息，我们马上开始。",
            ["ContentKR"] = "좋아요. 금방 시작할 테니까, 잠깐 쉬고 있어요.",
            ["DialogueId"] = 71006504,
            ["GUID"] = "B1C1E090",
            ["SpeakNpcId"] = 818060,
            },
        [71006505] = {
            ["Content"] = "喂，那边的朋友先别急着去答题，要不要听听我的提议？",
            ["ContentKR"] = "이봐, 서두르지 말고 내 제안부터 들어보는 게 어때?",
            ["DialogueId"] = 71006505,
            ["GUID"] = "B1C1E0BA",
            ["SpeakNpcId"] = 818061,
            },
        [71006506] = {
            ["Content"] = "那家伙净出一些麻烦的脑筋急转弯，你要是帮我搬下货，我就直接告诉你答案。如何？这样也省得你动脑子了。",
            ["ContentKR"] = "나 대신 짐을 옮겨 주면, 내가 정답을 가르쳐 줄게. 저 녀석은 죄다 엉뚱한 문제만 내거든. 어때? 괜히 머리 싸맬 필요 없잖아.",
            ["DialogueId"] = 71006506,
            ["GUID"] = "B1C1E0E4",
            ["NextOptions"] = {
                [1] = 710065071,
                [2] = 710065072,
                },
            ["SpeakNpcId"] = 818061,
            },
        [71006507] = {
            ["Content"] = "辛苦了，货就在那边的船上。",
            ["ContentKR"] = "짐은 저 배에 실려 있어. 수고 좀 해 줘.",
            ["DialogueId"] = 71006507,
            ["GUID"] = "B1C1E10E",
            ["SpeakNpcId"] = 818061,
            },
        [71006508] = {
            ["Content"] = "辛苦了，他今天这个问题应该选第一个。",
            ["ContentKR"] = "고생했어. 오늘 문제는 1번이 정답이야.",
            ["DialogueId"] = 71006508,
            ["GUID"] = "B1C1E138",
            ["SpeakNpcId"] = 818061,
            },
        [71006509] = {
            ["Content"] = "辛苦了，他今天这个问题应该选第二个。",
            ["ContentKR"] = "고생했어. 오늘 문제는 2번이 정답이야.",
            ["DialogueId"] = 71006509,
            ["GUID"] = "B1C1E162",
            ["SpeakNpcId"] = 818061,
            },
        [71006510] = {
            ["Content"] = "辛苦了，他今天这个问题应该选第三个。",
            ["ContentKR"] = "고생했어. 오늘 문제는 3번이 정답이야.",
            ["DialogueId"] = 71006510,
            ["GUID"] = "B1C1E18C",
            ["SpeakNpcId"] = 818061,
            },
        [71006511] = {
            ["Content"] = "休息好了吗？",
            ["ContentKR"] = "잘 쉬셨나요?",
            ["DialogueId"] = 71006511,
            ["GUID"] = "B1C1E1B6",
            ["NextOptions"] = {
                [1] = 710065111,
                [2] = 710065112,
                },
            ["SpeakNpcId"] = 818060,
            ["bForbidSkipOptions"] = true,
            },
        [71006512] = {
            ["Content"] = "休息好了吗？",
            ["ContentKR"] = "잘 쉬셨나요?",
            ["DialogueId"] = 71006512,
            ["GUID"] = "B1C1E1E0",
            ["NextOptions"] = {
                [1] = 710065121,
                [2] = 710065122,
                },
            ["SpeakNpcId"] = 818060,
            ["bForbidSkipOptions"] = true,
            },
        [71006513] = {
            ["Content"] = "休息好了吗？",
            ["ContentKR"] = "잘 쉬셨나요?",
            ["DialogueId"] = 71006513,
            ["GUID"] = "B1C1E20A",
            ["NextOptions"] = {
                [1] = 710065131,
                [2] = 710065132,
                },
            ["SpeakNpcId"] = 818060,
            ["bForbidSkipOptions"] = true,
            },
        [71006514] = {
            ["Content"] = "请听题！织星客丢了一件商品，经过调查找到了甲乙丙三人。甲指责：“是乙偷的！”。乙声称：“是丙偷的！”。丙说：“确实是我偷的！”。仅一人说了真话，请问到底是谁偷走了商品？",
            ["ContentKR"] = "문제 나갑니다! 별을 잇는 자가 물건을 도둑맞아서 갑, 을, 병 세 사람을 조사했어요. 그랬더니 갑은 \"을이 훔쳤어!\"라고 했고, 을은 \"병이 훔친 거야!\"라고 했는데, 병은 \"내가 훔친 거 맞아!\"라고 했답니다. 딱 한 사람만 사실을 말하고 있다면, 범인은 누구일까요?",
            ["DialogueId"] = 71006514,
            ["GUID"] = "B1C1E234",
            ["NextOptions"] = {
                [1] = 710065141,
                [2] = 710065142,
                [3] = 710065143,
                },
            ["SpeakNpcId"] = 818060,
            ["bForbidSkipOptions"] = true,
            },
        [71006515] = {
            ["Content"] = "请听题！锦鲤皎皎的好友有三个皎皎朋友，第一个叫黄金皎皎，第二个叫白银皎皎，第三个叫什么？",
            ["ContentKR"] = "문제입니다! 행운아 루나한테는 세 명의 친구가 있어요. 그중 첫 번째는 황금 루나, 두 번째는 백은 루나인데, 세 번째 친구는 무슨 루나일까요?",
            ["DialogueId"] = 71006515,
            ["GUID"] = "B1C1E25E",
            ["NextOptions"] = {
                [1] = 710065151,
                [2] = 710065152,
                [3] = 710065153,
                },
            ["SpeakNpcId"] = 818060,
            ["bForbidSkipOptions"] = true,
            },
        [71006516] = {
            ["Content"] = "请听题！三人前后排队，各带帽子一顶，帽子颜色可能会出现红、黄、蓝其中一种。最后一人能看到前两人的帽子，中间的人只能看前面。最后一人沉默，接着中间人也沉默。第一人说自己戴黄帽。已知至少一人戴黄帽。下列哪个说法是正确的？",
            ["ContentKR"] = "잘 들으세요. 세 사람이 순서대로 줄을 서서, 각자 빨강, 노랑, 파랑 중 한 색깔의 모자를 쓰고 있어요. 맨 뒷사람은 앞의 두 명이 보이고, 중간 사람은 맨 앞사람만 보이죠. 맨 뒷사람이 침묵하자, 중간 사람도 침묵했어요. 그러니까 맨 앞사람이 자긴 노란 모자라고 했고요. 셋 중 하나는 반드시 노란 모자를 쓰고 있다면, 다음 중 올바른 추론은 무엇일까요?",
            ["DialogueId"] = 71006516,
            ["GUID"] = "B1C1E288",
            ["NextOptions"] = {
                [1] = 710065161,
                [2] = 710065162,
                [3] = 710065163,
                },
            ["SpeakNpcId"] = 818060,
            ["bForbidSkipOptions"] = true,
            },
        [71006517] = {
            ["Content"] = "恭喜你答对了！这是为你准备的豪华奖品，请拿好～",
            ["ContentKR"] = "정답이에요! 축하합니다! 자, 호화 상품이에요, 받아 주세요~",
            ["DialogueId"] = 71006517,
            ["GUID"] = "B1C1E2B2",
            ["SpeakNpcId"] = 818060,
            },
        [71006518] = {
            ["Content"] = "回答错误，这是你的安慰奖，欢迎下次再来挑战哦～",
            ["ContentKR"] = "틀렸습니다! 이건 참가상이에요. 다음에 또 도전해 주세요~",
            ["DialogueId"] = 71006518,
            ["GUID"] = "B1C1E2DC",
            ["SpeakNpcId"] = 818060,
            },
        [71006519] = {
            ["Content"] = "好吧好吧，还是年轻人有干劲，那你加油。",
            ["ContentKR"] = "그래, 알겠어. 젊으니까 역시 의욕이 넘치네. 그럼 잘해 봐.",
            ["DialogueId"] = 71006519,
            ["GUID"] = "B1C1E306",
            ["SpeakNpcId"] = 818061,
            },
        [71006520] = {
            ["Content"] = "嗯，准备好了再来找我吧！",
            ["ContentKR"] = "자, 준비되면 다시 찾아와 주세요!",
            ["DialogueId"] = 71006520,
            ["GUID"] = "B1C1E330",
            ["SpeakNpcId"] = 818060,
            },
        [71006601] = {
            ["Content"] = "好想要小青蛙呀，咕咕呱呱呱。",
            ["ContentKR"] = "개구리 갖고 싶다. 개굴개굴개굴.",
            ["DialogueId"] = 71006601,
            ["GUID"] = "B1C1F07A",
            ["SpeakNpcId"] = 818062,
            },
        [71006602] = {
            ["Content"] = "小青蛙，好想要小青蛙，小青蛙小青蛙小青蛙。",
            ["ContentKR"] = "개구리, 진짜 가지고 싶은데. 개구리, 개구리, 개구리.",
            ["DialogueId"] = 71006602,
            ["GUID"] = "B1C1F0A4",
            ["NextOptions"] = {
                [1] = 710066021,
                [2] = 710066022,
                },
            ["SpeakNpcId"] = 818062,
            ["bForbidSkipOptions"] = true,
            },
        [71006603] = {
            ["Content"] = "（它似乎对青蛙有什么执念，帮它找找看吧。）",
            ["ContentKR"] = "(왠지 개구리에 엄청나게 집착하네. 좀 찾아봐 주자.)",
            ["DialogueId"] = 71006603,
            ["GUID"] = "B1C1F0CE",
            ["SpeakNpcId"] = 100001,
            },
        [71006604] = {
            ["Content"] = "这些应该足够了，回去交给它吧。",
            ["ContentKR"] = "이만큼 모았으면 됐겠지. 어서 가져다주자.",
            ["DialogueId"] = 71006604,
            ["GUID"] = "B1C1F0F8",
            ["SpeakNpcId"] = 100001,
            },
        [71006605] = {
            ["Content"] = "小青蛙，好耶，小青蛙，好～咕呱咕呱。",
            ["ContentKR"] = "개구리다, 와아! 개구리, 좋아~ 개굴개굴.",
            ["DialogueId"] = 71006605,
            ["GUID"] = "B1C1F122",
            ["NextDialogue"] = 71006606,
            ["SpeakNpcId"] = 818062,
            },
        [71006606] = {
            ["Content"] = "（就这样，无由生消失在了你的面前。）",
            ["ContentKR"] = "(그 말을 끝으로, 무유생은 당신 앞에서 사라졌다.)",
            ["DialogueId"] = 71006606,
            ["GUID"] = "B1C1F14C",
            ["SpeakNpcId"] = 800006,
            },
        [71006701] = {
            ["Content"] = "这么简单的题要是再答错，今晚就给我留下来抄一百遍吧。",
            ["ContentKR"] = "이렇게 간단한 걸 또 틀렸다간, 오늘 밤에 집에도 못 가고 계속 베껴 쓰기만 할 줄 알아.",
            ["DialogueId"] = 71006701,
            ["GUID"] = "B1C200E2",
            ["NextDialogue"] = 71006702,
            ["SpeakNpcId"] = 818064,
            },
        [71006702] = {
            ["Content"] = "（愤怒的声音从远处传来，过去看看发生了什么吧。）",
            ["ContentKR"] = "(멀리서 누군가 화내는 소리가 들린다. 무슨 일인지 확인하러 가보자.)",
            ["DialogueId"] = 71006702,
            ["GUID"] = "B1C2010C",
            ["SpeakNpcId"] = 800006,
            },
        [71006703] = {
            ["Content"] = "这是怎么了？",
            ["ContentKR"] = "무슨 일인가요?",
            ["DialogueId"] = 71006703,
            ["GUID"] = "B1C20136",
            ["NextDialogue"] = 71006704,
            ["SpeakNpcId"] = 100001,
            },
        [71006704] = {
            ["Content"] = "呼……这孩子连大风九章都默写不下来。这点定性都没有，以后还怎么精进学业？",
            ["ContentKR"] = "하아... 이 녀석이 대풍구장을 도무지 못 외우네요. 이렇게 진득하지 못해서야, 무슨 공부를 하겠어요?",
            ["DialogueId"] = 71006704,
            ["GUID"] = "B1C20160",
            ["NextDialogue"] = 71006705,
            ["SpeakNpcId"] = 818064,
            },
        [71006705] = {
            ["Content"] = "不行，越想越气，我去喝口茶冷静一下，你帮我盯一下吧。",
            ["ContentKR"] = "생각할수록 화가 나서 안 되겠네요. 차 한잔 마시면서 머리 좀 식히고 올 테니까, 잠깐 얘 좀 감시해 주세요.",
            ["DialogueId"] = 71006705,
            ["GUID"] = "B1C2018A",
            ["NextOptions"] = {
                [1] = 710067051,
                [2] = 710067052,
                },
            ["SpeakNpcId"] = 818064,
            ["bForbidSkipOptions"] = true,
            },
        [71006706] = {
            ["Content"] = "劳烦你了，我很快回来。",
            ["ContentKR"] = "금방 다녀올게요. 수고 좀 해 줘요.",
            ["DialogueId"] = 71006706,
            ["GUID"] = "B1C201B4",
            ["SpeakNpcId"] = 818064,
            },
        [71006707] = {
            ["Content"] = "呜呜呜呜……下一句到底是什么来着……",
            ["ContentKR"] = "훌쩍훌쩍... 다음 구절이 대체 뭐였지...",
            ["DialogueId"] = 71006707,
            ["GUID"] = "B1C201DE",
            ["NextDialogue"] = 71006708,
            ["SpeakNpcId"] = 818063,
            },
        [71006708] = {
            ["Content"] = "这位朋友，你能不能也帮帮我呀……",
            ["ContentKR"] = "있잖아, 나 좀 도와주라...",
            ["DialogueId"] = 71006708,
            ["GUID"] = "B1C20208",
            ["SpeakNpcId"] = 818063,
            },
        [71006709] = {
            ["Content"] = "我写到“著真去伪，赤心为诚。”了，但下一句怎么都想不起来，你能帮我翻下书看看后面是什么吗？",
            ["ContentKR"] = "\"참을 드러내고 거짓을 버려 진실로서 정성을 다할지니\" 이다음이 죽어도 생각이 안 나서 그런데, 책 좀 펴서 확인해 주면 안 될까?",
            ["DialogueId"] = 71006709,
            ["GUID"] = "B1C20232",
            ["NextOptions"] = {
                [1] = 710067091,
                [2] = 710067092,
                },
            ["SpeakNpcId"] = 818063,
            ["bForbidSkipOptions"] = true,
            },
        [71006711] = {
            ["Content"] = "不……我想出去玩啊……",
            ["ContentKR"] = "안 돼... 나 나가 놀고 싶단 말이야...",
            ["DialogueId"] = 71006711,
            ["GUID"] = "B1C20286",
            ["SpeakNpcId"] = 818063,
            },
        [71006712] = {
            ["Content"] = "真是帮了大忙了！谢谢你谢谢你！",
            ["ContentKR"] = "덕분에 살았어! 고마워! 진짜 고마워!",
            ["DialogueId"] = 71006712,
            ["GUID"] = "B1C202B0",
            ["SpeakNpcId"] = 818063,
            },
        [71006713] = {
            ["Content"] = "（你翻开抄写着大风九章的册子，“著真去伪，赤心为诚。”下一句是“妄言欺众，不可为也。”）",
            ["ContentKR"] = "(대풍구장이 적힌 책을 펼치자, \"참을 드러내고 거짓을 버려 진실로서 정성을 다할지니\" 뒤에 \"망령된 말로 무리를 속이지 말지어다\"가 적혀 있다.)",
            ["DialogueId"] = 71006713,
            ["GUID"] = "B1C202DA",
            ["NextDialogue"] = 71006714,
            ["SpeakNpcId"] = 800006,
            },
        [71006714] = {
            ["Content"] = "找到了，回去告诉他答案吧。",
            ["ContentKR"] = "찾았다. 가서 답을 알려 주자.",
            ["DialogueId"] = 71006714,
            ["GUID"] = "B1C20304",
            ["SpeakNpcId"] = 100001,
            },
        [71006715] = {
            ["Content"] = "你可算回来了，快快快，下一句是什么？",
            ["ContentKR"] = "드디어 왔구나! 얼른 말해 봐, 다음 구절은 뭐였어?",
            ["DialogueId"] = 71006715,
            ["GUID"] = "B1C2032E",
            ["SpeakNpcId"] = 818063,
            },
        [71006717] = {
            ["Content"] = "哼，这都能错！今晚给我再抄五百遍，少一遍都不准走！",
            ["ContentKR"] = "으이구, 이걸 틀려?! 오늘 밤에 500번 더 베껴 적어. 다 적기 전까진 한 짝도 못 가!",
            ["DialogueId"] = 71006717,
            ["GUID"] = "B1C20382",
            ["NextDialogue"] = 71006718,
            ["SpeakNpcId"] = 818064,
            },
        [71006718] = {
            ["Content"] = "不——",
            ["ContentKR"] = "안 돼——",
            ["DialogueId"] = 71006718,
            ["GUID"] = "B1C203AC",
            ["NextDialogue"] = 71006719,
            ["SpeakNpcId"] = 818063,
            },
        [71006719] = {
            ["Content"] = "谢谢你帮我盯着他了，这是给你的谢礼，还请收下。",
            ["ContentKR"] = "대신 감시해 줘서 고마워요. 이건 답례니까, 받아 두세요.",
            ["DialogueId"] = 71006719,
            ["GUID"] = "B1C203D6",
            ["SpeakNpcId"] = 818064,
            },
        [71006720] = {
            ["Content"] = "你看，只要沉下心来仔细回想，这不是能写出来吗！",
            ["ContentKR"] = "거 봐, 차분하게 생각하니까 다 적을 수 있잖아!",
            ["DialogueId"] = 71006720,
            ["GUID"] = "B1C20400",
            ["NextDialogue"] = 71006721,
            ["SpeakNpcId"] = 818064,
            },
        [71006721] = {
            ["Content"] = "好耶，出去玩喽！",
            ["ContentKR"] = "야호! 이제 놀러 가야지!",
            ["DialogueId"] = 71006721,
            ["GUID"] = "B1C2042A",
            ["NextDialogue"] = 71006722,
            ["SpeakNpcId"] = 818063,
            },
        [71006722] = {
            ["Content"] = "站住！因为你今日的默写达标，所以只用再抄五十遍就行，抄完再走。",
            ["ContentKR"] = "잠깐! 오늘 외워 쓰기는 통과했으니까, 베껴 쓰기는 50번으로 줄여 줄게. 다 적고 가렴.",
            ["DialogueId"] = 71006722,
            ["Duration"] = 3,
            ["GUID"] = "B1C20454",
            ["NextDialogue"] = 71006723,
            ["SpeakNpcId"] = 818064,
            },
        [71006723] = {
            ["Content"] = "不——",
            ["ContentKR"] = "안 돼——",
            ["DialogueId"] = 71006723,
            ["GUID"] = "B1C2047E",
            ["NextDialogue"] = 71006724,
            ["SpeakNpcId"] = 818063,
            },
        [71006724] = {
            ["Content"] = "谢谢你帮我盯着他了，这是给你的谢礼，还请收下。",
            ["ContentKR"] = "대신 감시해 줘서 고마워요. 이건 답례니까, 받아 두세요.",
            ["DialogueId"] = 71006724,
            ["GUID"] = "B1C204A8",
            ["SpeakNpcId"] = 818064,
            },
        [71006801] = {
            ["Content"] = "喂，那边的朋友，能帮我拍张照吗？",
            ["ContentKR"] = "저기요~ 거기 계신 분! 사진 한 장만 찍어주실 수 있을까요?",
            ["DialogueId"] = 71006801,
            ["GUID"] = "B1C2114A",
            ["SpeakNpcId"] = 818041,
            },
        [71006802] = {
            ["Content"] = "这位朋友，你能帮我拍几张照片吗？难得来一趟百年春，不留点合影就太可惜了。",
            ["ContentKR"] = "이봐요, 친구. 사진 몇 장만 부탁드릴게요. 백년춘까지 왔는데, 기념사진 하나 없이 돌아가긴 너무 아쉽잖아요.",
            ["DialogueId"] = 71006802,
            ["GUID"] = "B1C21174",
            ["NextOptions"] = {
                [1] = 710068021,
                [2] = 710068022,
                },
            ["SpeakNpcId"] = 818041,
            ["bForbidSkipOptions"] = true,
            },
        [71006804] = {
            ["Content"] = "太好了，记得把我后面的这条白龙也拍进去哦，我很喜欢它的造型。",
            ["ContentKR"] = "정말 감사합니다! 찍으실 때 제 뒤에 있는 저 백룡도 꼭 같이 담아주세요~ 저 건물, 제가 진짜 좋아하는 스타일이라서요!",
            ["DialogueId"] = 71006804,
            ["GUID"] = "B1C211C8",
            ["SpeakNpcId"] = 818041,
            },
        [71006805] = {
            ["Content"] = "你拍得也太好了，真棒呀，多谢多谢。",
            ["ContentKR"] = "사진 너무 잘 찍으셨네요! 완전 감탄했어요~ 진짜 감사해요!",
            ["DialogueId"] = 71006805,
            ["GUID"] = "B1C211F2",
            ["SpeakNpcId"] = 818041,
            },
        [71006901] = {
            ["Content"] = "哎呀哎呀，这可糟了……",
            ["ContentKR"] = "아이고, 이걸 어떡한다...",
            ["DialogueId"] = 71006901,
            ["GUID"] = "B1C221B2",
            ["SpeakNpcId"] = 818065,
            },
        [71006902] = {
            ["Content"] = "这位朋友，我不小心把酒壶、鱼饵还有鱼竿全掉水里了，你能不能帮我钓几条鱼上来啊，不然回去又要被大伙嘲笑了。",
            ["ContentKR"] = "저기, 내가 실수로 술병이랑 미끼, 그리고 낚싯대까지 죄다 물에 빠뜨려서 그런데, 나 대신 물고기 몇 마리만 잡아 주면 안 될까? 친구들이 또 놀려댈까 봐 그래.",
            ["DialogueId"] = 71006902,
            ["GUID"] = "B1C221DC",
            ["NextOptions"] = {
                [1] = 710069021,
                [2] = 710069022,
                },
            ["SpeakNpcId"] = 818065,
            },
        [71006903] = {
            ["Content"] = "好好好，拜托你了。",
            ["ContentKR"] = "다행이다, 그럼 부탁할게.",
            ["DialogueId"] = 71006903,
            ["GUID"] = "B1C22206",
            ["SpeakNpcId"] = 818065,
            },
        [71006904] = {
            ["Content"] = "怎么还能钓上这种鱼，总不会是被我的酒壶吸引过来的吧？！算了算了，以后再研究。",
            ["ContentKR"] = "아니, 어떻게 이런 물고기가 낚였지? 내가 빠뜨린 술병 때문인가?! 에이, 아무렴 어때, 나중에 생각하자.",
            ["DialogueId"] = 71006904,
            ["GUID"] = "B1C22230",
            ["NextDialogue"] = 71006905,
            ["SpeakNpcId"] = 818065,
            },
        [71006905] = {
            ["Content"] = "谢谢你今天帮我钓的这些鱼啊，帮大忙了！",
            ["ContentKR"] = "오늘 물고기 잡아 줘서 고마워! 덕분에 살았어!",
            ["DialogueId"] = 71006905,
            ["GUID"] = "B1C2225A",
            ["SpeakNpcId"] = 818065,
            },
        [71007001] = {
            ["Content"] = "这可怎生是好？白龙神君，派个人来帮帮我吧！",
            ["ContentKR"] = "어떡하지? 백룡신군이시여, 제발 절 도와줄 사람 하나만 보내 주세요!",
            ["DialogueId"] = 71007001,
            ["GUID"] = "B1C2321A",
            ["SpeakNpcId"] = 818066,
            },
        [71007002] = {
            ["Content"] = "发生什么了？",
            ["ContentKR"] = "무슨 일 있어요?",
            ["DialogueId"] = 71007002,
            ["GUID"] = "B1C23244",
            ["NextDialogue"] = 71007003,
            ["SpeakNpcId"] = 100001,
            },
        [71007003] = {
            ["Content"] = "我与心上人约在此处相见，但场地尚未布置妥当。阁下可以替我跑一趟，买件礼物回来吗？",
            ["ContentKR"] = "좋아하는 사람이랑 여기서 만나기로 했는데, 아직 장소 꾸미는 게 안 끝나서요. 저 대신 가서 선물 하나만 사다 주실 수 있나요?",
            ["DialogueId"] = 71007003,
            ["GUID"] = "B1C2326E",
            ["NextOptions"] = {
                [1] = 710070031,
                [2] = 710070032,
                },
            ["SpeakNpcId"] = 818066,
            ["bForbidSkipOptions"] = true,
            },
        [71007004] = {
            ["Content"] = "那可真是有劳了！啊对了，我那心上人对花过敏，切记不要买含花的礼物啊。",
            ["ContentKR"] = "덕분에 살았어요! 참, 그 사람은 꽃 알레르기가 심하니까, 꽃이 포함된 건 사시면 안 돼요!",
            ["DialogueId"] = 71007004,
            ["GUID"] = "B1C23298",
            ["SpeakNpcId"] = 818066,
            },
        [71007005] = {
            ["Content"] = "你好，我想挑一件适合送人的礼物。",
            ["ContentKR"] = "안녕하세요, 선물하기 좋은 물건을 추천받고 싶은데요.",
            ["DialogueId"] = 71007005,
            ["GUID"] = "B1C232C2",
            ["NextDialogue"] = 71007006,
            ["SpeakNpcId"] = 100001,
            },
        [71007006] = {
            ["Content"] = "好嘞，现在这三款礼物最受欢迎，且听我慢慢道来。",
            ["ContentKR"] = "네~ 요즘은 이 세 가지가 제일 인기가 많아요. 천천히 설명해 드릴게요.",
            ["DialogueId"] = 71007006,
            ["GUID"] = "B1C232EC",
            ["NextDialogue"] = 71007007,
            ["SpeakNpcId"] = 818067,
            },
        [71007007] = {
            ["Content"] = "第一件是蒹葭浦现采的告苍花，还带着清晨的露珠，送女孩子准没错。",
            ["ContentKR"] = "첫 번째는 갈대늪에서 방금 꺾어 온 고창꽃이에요. 아침 이슬을 머금고 있어서, 여성분들 선물로 딱이죠.",
            ["DialogueId"] = 71007007,
            ["GUID"] = "B1C23316",
            ["NextDialogue"] = 71007008,
            ["SpeakNpcId"] = 818067,
            },
        [71007008] = {
            ["Content"] = "第二件是机枢派名家打磨的青铜吊坠，做功考究，细节精致。",
            ["ContentKR"] = "두 번째는 기추파 장인의 세심한 손길로 탄생한 청동 목걸이예요. 섬세하고, 마감도 고급스러워요.",
            ["DialogueId"] = 71007008,
            ["GUID"] = "B1C23340",
            ["NextDialogue"] = 71007009,
            ["SpeakNpcId"] = 818067,
            },
        [71007009] = {
            ["Content"] = "第三件是悬衡派特制的白龙神君造型摆件，技艺精湛，栩栩如生。",
