            ["bAllowClickSkipScript"] = false,
            },
        [72000502] = {
            ["Content"] = "谢谢你，草丛一样的人类……我被卡在这个圆圆的冰冰的桶里好久了……",
            ["ContentKR"] = "고마워, 풀숲 같은 인간... 난 이 둥글고 차가운 통에 오랫동안 갇혀 있었어...",
            ["DialogueId"] = 72000502,
            ["FacialId"] = {
                [1] = "820000:PetPan_Dizzy",
                },
            ["GUID"] = "B43EE65C",
            ["NextDialogue"] = 72000503,
            ["SpeakNpcId"] = 820000,
            },
        [72000503] = {
            ["Content"] = "唔，草丛不见了，但还是谢谢你，雪一样的人类。",
            ["ContentKR"] = "음, 풀숲은 사라졌지만, 그래도 고마워, 눈 같은 인간.",
