            ["SpeakNpcId"] = 820000,
            },
        [72000703] = {
            ["Content"] = "人类也喜欢玩捉迷藏吗？但是好像你们玩得并不是很开心……",
            ["ContentKR"] = "인간도 숨바꼭질을 좋아해? 하지만 너희는 별로 즐거워 보이지 않네...",
