            ["bAllowClickSkipScript"] = false,
            },
        [72000802] = {
            ["Content"] = "三个士兵去动物园……两个士兵去晒太阳……",
            ["ContentKR"] = "세 명의 병사가 동물원으로 갔네... 두 명의 병사가 햇볕을 쬐러 가고...",
