            },
        [72001101] = {
            ["Camera"] = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
            ["DialogueId"] = 72001101,
            ["DialoguePanelType"] = "AllHide",
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43F48A2",
            ["NextDialogue"] = 72001102,
            ["Scripts"] = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
            ["bAllowClickSkipScript"] = false,
            },
        [72001102] = {
            ["Content"] = "我以为这个箱子是你好箱，劝他动起来劝了好久。",
            ["ContentKR"] = "이 상자가 안녕 상자인 줄 알았어. 움직이라고 한참을 설득했지.",
            ["DialogueId"] = 72001102,
            ["FacialId"] = {
                [1] = "820000:PetPan_Wink",
                },
            ["GUID"] = "B43F48CC",
            ["NextDialogue"] = 72001103,
            ["SpeakNpcId"] = 820000,
            },
        [72001103] = {
            ["Content"] = "原来不是，看来，我应该早一点踢这个箱子一脚。",
            ["ContentKR"] = "그런데 아니었어, 차라리 진작에 발로 차 버릴 걸 그랬네.",
            ["DialogueId"] = 72001103,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43F48F6",
            ["NextDialogue"] = 72001104,
            ["SpeakNpcId"] = 820000,
            },
        [72001104] = {
            ["DialogueId"] = 72001104,
            ["DialoguePanelType"] = "AllHide",
            ["Duration"] = 0.63,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43F4920",
            ["Scripts"] = "PlayAnimation{ActorId{820000},AnimationId{\"Wuyou_Disappear\"}}",
            ["bAllowClickSkipScript"] = false,
            },
        [72001201] = {
            ["Camera"] = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
            ["DialogueId"] = 72001201,
            ["DialoguePanelType"] = "AllHide",
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43F590A",
            ["NextDialogue"] = 72001202,
            ["Scripts"] = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
            ["bAllowClickSkipScript"] = false,
            },
        [72001202] = {
            ["Content"] = "这棵树好像累了，躺在地上休息。",
            ["ContentKR"] = "이 나무는 많이 피곤한가 봐. 땅에 누워 쉬고 있네.",
            ["DialogueId"] = 72001202,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43F5934",
            ["NextDialogue"] = 72001203,
            ["SpeakNpcId"] = 820000,
            },
        [72001203] = {
            ["Content"] = "所以那些落到地上的雪，是不是也飞累了，想要躺下来呢？",
            ["ContentKR"] = "그럼, 땅에 떨어진 저 눈들도 피곤해서 누워 있는 걸까?",
            ["DialogueId"] = 72001203,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43F595E",
            ["NextDialogue"] = 72001204,
            ["SpeakNpcId"] = 820000,
            },
        [72001204] = {
            ["DialogueId"] = 72001204,
            ["DialoguePanelType"] = "AllHide",
            ["Duration"] = 0.63,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43F5988",
            ["Scripts"] = "PlayAnimation{ActorId{820000},AnimationId{\"Wuyou_Disappear\"}}",
            ["bAllowClickSkipScript"] = false,
            },
        [72001301] = {
            ["Camera"] = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
            ["DialogueId"] = 72001301,
            ["DialoguePanelType"] = "AllHide",
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43F6972",
            ["NextDialogue"] = 72001302,
            ["Scripts"] = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
            ["bAllowClickSkipScript"] = false,
            },
        [72001302] = {
            ["Content"] = "这里很暖和哦，你也可以坐在这里。",
            ["ContentKR"] = "여기는 아주 따뜻해, 너도 여기 앉아 봐.",
            ["DialogueId"] = 72001302,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43F699C",
            ["NextDialogue"] = 72001303,
            ["SpeakNpcId"] = 820000,
            },
        [72001303] = {
            ["Content"] = "但是不可以坐太久，我也有其他朋友会冷。",
            ["ContentKR"] = "하지만 너무 오래 앉아 있으면 안돼. 다른 친구들도 추울 테니까.",
            ["DialogueId"] = 72001303,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43F69C6",
            ["NextDialogue"] = 72001304,
            ["SpeakNpcId"] = 820000,
            },
        [72001304] = {
            ["DialogueId"] = 72001304,
            ["DialoguePanelType"] = "AllHide",
            ["Duration"] = 0.63,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43F69F0",
            ["Scripts"] = "PlayAnimation{ActorId{820000},AnimationId{\"Wuyou_Disappear\"}}",
            ["bAllowClickSkipScript"] = false,
            },
        [72001401] = {
            ["Camera"] = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
            ["DialogueId"] = 72001401,
            ["DialoguePanelType"] = "AllHide",
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43F79DA",
            ["NextDialogue"] = 72001402,
            ["Scripts"] = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
            ["bAllowClickSkipScript"] = false,
            },
        [72001402] = {
            ["Content"] = "此路不通，嗯……",
            ["ContentKR"] = "이 길은 막혔어, 음...",
            ["DialogueId"] = 72001402,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43F7A04",
            ["NextDialogue"] = 72001403,
            ["SpeakNpcId"] = 820000,
            },
        [72001403] = {
            ["Content"] = "或者说，我想说的是，我想独处一段时间。你要和我一起独处吗？",
            ["ContentKR"] = "그게 아니라 내가 하고 싶은 말은, 잠시 혼자 있고 싶다는 거야. 너도 나와 함께 혼자 있고 싶어?",
            ["DialogueId"] = 72001403,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43F7A2E",
            ["NextDialogue"] = 72001404,
            ["SpeakNpcId"] = 820000,
            },
        [72001404] = {
            ["Content"] = "但这样是不是不能叫作独处了。",
            ["ContentKR"] = "하지만 그러면 혼자 있는 게 아니잖아.",
            ["DialogueId"] = 72001404,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43F7A58",
            ["NextDialogue"] = 72001405,
            ["Scripts"] = "PlayAnimation{ActorId{820000},AnimationId{\"Wuyou_Disagree\"}}",
            ["SpeakNpcId"] = 820000,
            ["bAllowClickSkipScript"] = false,
            },
        [72001405] = {
            ["DialogueId"] = 72001405,
            ["DialoguePanelType"] = "AllHide",
            ["Duration"] = 0.63,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43F7A82",
            ["Scripts"] = "PlayAnimation{ActorId{820000},AnimationId{\"Wuyou_Disappear\"}}",
            ["bAllowClickSkipScript"] = false,
            },
        [72001501] = {
            ["Camera"] = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
            ["DialogueId"] = 72001501,
            ["DialoguePanelType"] = "AllHide",
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43F8A42",
            ["NextDialogue"] = 72001502,
            ["Scripts"] = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
            ["bAllowClickSkipScript"] = false,
            },
        [72001502] = {
            ["Content"] = "这里的房子看起来都很疲惫呢，皮肤上都斑斑驳驳。",
            ["ContentKR"] = "여기 집들은 다들 피곤해 보이네, 피부가 얼룩덜룩해.",
            ["DialogueId"] = 72001502,
            ["FacialId"] = {
                [1] = "820000:PetPan_Speechless",
                },
            ["GUID"] = "B43F8A6C",
            ["NextDialogue"] = 72001503,
            ["SpeakNpcId"] = 820000,
            },
        [72001503] = {
            ["Content"] = "真希望他们能够好起来。",
            ["ContentKR"] = "모두가 낫기를, 진심으로 바래.",
            ["DialogueId"] = 72001503,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43F8A96",
            ["NextDialogue"] = 72001504,
            ["SpeakNpcId"] = 820000,
            },
        [72001504] = {
            ["DialogueId"] = 72001504,
            ["DialoguePanelType"] = "AllHide",
            ["Duration"] = 0.63,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43F8AC0",
            ["Scripts"] = "PlayAnimation{ActorId{820000},AnimationId{\"Wuyou_Disappear\"}}",
            ["bAllowClickSkipScript"] = false,
            },
        [72001601] = {
            ["Camera"] = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
            ["DialogueId"] = 72001601,
            ["DialoguePanelType"] = "AllHide",
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43F9AAA",
            ["NextDialogue"] = 72001602,
            ["Scripts"] = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
            ["bAllowClickSkipScript"] = false,
            },
        [72001602] = {
            ["Content"] = "这座山好高，好亮！站在山顶的我，厉害！",
            ["ContentKR"] = "이 산은 정말 높고 밝네! 산 꼭대기에 서 있는 나도 대단해!",
            ["DialogueId"] = 72001602,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43F9AD4",
            ["NextDialogue"] = 72001603,
            ["SpeakNpcId"] = 820000,
            },
        [72001603] = {
            ["Content"] = "咿呀？这里不是山？怎么会？",
            ["ContentKR"] = "야하? 여기가 산이 아니라고? 그게 말이 돼?",
            ["DialogueId"] = 72001603,
            ["FacialId"] = {
                [1] = "820000:PetPan_Speechless",
                },
            ["GUID"] = "B43F9AFE",
            ["NextDialogue"] = 72001604,
            ["SpeakNpcId"] = 820000,
            },
        [72001604] = {
            ["Content"] = "山不就是高高的，尖尖的地方，这里就是山！",
            ["ContentKR"] = "산은 높고 뾰족한 곳이잖아. 여기가 바로 산이야!",
            ["DialogueId"] = 72001604,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43F9B28",
            ["NextDialogue"] = 72001605,
            ["SpeakNpcId"] = 820000,
            },
        [72001605] = {
            ["DialogueId"] = 72001605,
            ["DialoguePanelType"] = "AllHide",
            ["Duration"] = 0.63,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43F9B52",
            ["Scripts"] = "PlayAnimation{ActorId{820000},AnimationId{\"Wuyou_Disappear\"}}",
            ["bAllowClickSkipScript"] = false,
            },
        [72001701] = {
            ["Camera"] = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
            ["DialogueId"] = 72001701,
            ["DialoguePanelType"] = "AllHide",
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43FAB12",
            ["NextDialogue"] = 72001702,
            ["Scripts"] = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
            ["bAllowClickSkipScript"] = false,
            },
        [72001702] = {
            ["Content"] = "如果能看清脚下的路，你是不是就不怕秽兽了？",
            ["ContentKR"] = "발밑의 길이 잘 보인다면, 더 이상 필토이드를 두려워하지 않겠지?",
            ["DialogueId"] = 72001702,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43FAB3C",
            ["NextDialogue"] = 72001703,
            ["SpeakNpcId"] = 820000,
            },
        [72001703] = {
            ["Content"] = "那么，这里亮起来了哦。",
            ["ContentKR"] = "자, 여기가 밝아졌어.",
            ["DialogueId"] = 72001703,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43FAB66",
            ["NextDialogue"] = 72001704,
            ["Scripts"] = "PlayAnimation{ActorId{820000},AnimationId{\"Wuyou_Agree\"}}",
            ["SpeakNpcId"] = 820000,
            ["bAllowClickSkipScript"] = false,
            },
        [72001704] = {
            ["DialogueId"] = 72001704,
            ["DialoguePanelType"] = "AllHide",
            ["Duration"] = 0.63,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43FAB90",
            ["Scripts"] = "PlayAnimation{ActorId{820000},AnimationId{\"Wuyou_Disappear\"}}",
            ["bAllowClickSkipScript"] = false,
            },
        [72001801] = {
            ["Camera"] = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
            ["DialogueId"] = 72001801,
            ["DialoguePanelType"] = "AllHide",
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43FBB7A",
            ["NextDialogue"] = 72001802,
            ["Scripts"] = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
            ["bAllowClickSkipScript"] = false,
            },
        [72001802] = {
            ["Content"] = "这里有许多人的气息，但是他们都不见了。",
            ["ContentKR"] = "여기 많은 사람들의 흔적이 남아 있지만, 그들은 모두 사라졌어.",
            ["DialogueId"] = 72001802,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43FBBA4",
            ["NextDialogue"] = 72001803,
            ["SpeakNpcId"] = 820000,
            },
        [72001803] = {
            ["Content"] = "到底去了哪里呢？",
            ["ContentKR"] = "도대체 어디로 갔을까?",
            ["DialogueId"] = 72001803,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43FBBCE",
            ["NextDialogue"] = 72001804,
            ["SpeakNpcId"] = 820000,
            },
        [72001804] = {
            ["DialogueId"] = 72001804,
            ["DialoguePanelType"] = "AllHide",
            ["Duration"] = 0.63,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43FBBF8",
            ["Scripts"] = "PlayAnimation{ActorId{820000},AnimationId{\"Wuyou_Disappear\"}}",
            ["bAllowClickSkipScript"] = false,
            },
        [72001901] = {
            ["Camera"] = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
            ["DialogueId"] = 72001901,
            ["DialoguePanelType"] = "AllHide",
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43FCBE2",
            ["NextDialogue"] = 72001902,
            ["Scripts"] = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
            ["bAllowClickSkipScript"] = false,
            },
        [72001902] = {
            ["Content"] = "哼哼，大家都坐在一起，只有它跑开了。",
            ["ContentKR"] = "흠흠, 다같이 앉아 있는데 혼자만 도망갔네.",
            ["DialogueId"] = 72001902,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43FCC0C",
            ["NextDialogue"] = 72001903,
            ["SpeakNpcId"] = 820000,
            },
        [72001903] = {
            ["Content"] = "那么，现在，我宣布，箱箱大会开始！",
            ["ContentKR"] = "그러면 선포하겠어, 상자 회의 시작!",
            ["DialogueId"] = 72001903,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43FCC36",
            ["NextDialogue"] = 72001904,
            ["Scripts"] = "PlayAnimation{ActorId{820000},AnimationId{\"Wuyou_Agree\"}}",
            ["SpeakNpcId"] = 820000,
            ["bAllowClickSkipScript"] = false,
            },
        [72001904] = {
            ["DialogueId"] = 72001904,
            ["DialoguePanelType"] = "AllHide",
            ["Duration"] = 0.63,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43FCC60",
            ["Scripts"] = "PlayAnimation{ActorId{820000},AnimationId{\"Wuyou_Disappear\"}}",
            ["bAllowClickSkipScript"] = false,
            },
        [72002201] = {
            ["Camera"] = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
            ["DialogueId"] = 72002201,
            ["DialoguePanelType"] = "AllHide",
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43FFD1A",
            ["NextDialogue"] = 72002202,
            ["Scripts"] = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
            ["bAllowClickSkipScript"] = false,
            },
        [72002202] = {
            ["Content"] = "我想要和路上的车比一比谁跑得快。",
            ["ContentKR"] = "난 길 위의 차들과 누가 더 빠른지 겨뤄보고 싶어.",
            ["DialogueId"] = 72002202,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43FFD44",
            ["NextDialogue"] = 72002203,
            ["SpeakNpcId"] = 820000,
            },
        [72002203] = {
            ["Content"] = "但是他们跑得太快的话，会滑倒，真担心他们。",
            ["ContentKR"] = "하지만 그들이 너무 빨리 달리면 미끄러질 텐데, 정말 걱정돼.",
            ["DialogueId"] = 72002203,
            ["FacialId"] = {
                [1] = "820000:PetPan_Wink",
                },
            ["GUID"] = "B43FFD6E",
            ["NextDialogue"] = 72002204,
            ["SpeakNpcId"] = 820000,
            },
        [72002204] = {
            ["DialogueId"] = 72002204,
            ["DialoguePanelType"] = "AllHide",
            ["Duration"] = 0.63,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43FFD98",
            ["Scripts"] = "PlayAnimation{ActorId{820000},AnimationId{\"Wuyou_Disappear\"}}",
            ["bAllowClickSkipScript"] = false,
            },
        [72002301] = {
            ["Camera"] = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
            ["DialogueId"] = 72002301,
            ["DialoguePanelType"] = "AllHide",
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B4400D82",
            ["NextDialogue"] = 72002302,
            ["Scripts"] = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
            ["bAllowClickSkipScript"] = false,
            },
        [72002302] = {
            ["Content"] = "花朵们都很善良，所有收到她们的人都会开心。",
            ["ContentKR"] = "꽃들은 모두 착해서, 그 애들을 받은 사람들은 모두 행복해질 거야.",
            ["DialogueId"] = 72002302,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B4400DAC",
            ["NextDialogue"] = 72002303,
            ["SpeakNpcId"] = 820000,
            },
        [72002303] = {
            ["Content"] = "是不是这些花背着我们，和收到的人说悄悄话。",
