            ["bAllowClickSkipScript"] = false,
            },
        [72003902] = {
            ["Content"] = "会动的鸟，不会动的鸟，还有不会动的人都还在这里。",
            ["ContentKR"] = "움직이는 새, 움직이지 않는 새, 움직이지 않는 사람은 다 여기에 있어.",
