            ["SpeakNpcId"] = 820000,
            },
        [72003903] = {
            ["Content"] = "但是会动的人都离开了，他们还会回来吗？",
            ["ContentKR"] = "하지만 움직일 줄 아는 사람은 전부 떠나 버렸어. 그들이 돌아올까?",
