            ["GUID"] = "B47EBAFC",
            ["NextDialogue"] = 72100103,
            ["SpeakNpcId"] = 830001,
            },
        [72100103] = {
            ["Content"] = "远道而来的朋友，你拂开繁花，可曾窥见自己明朗的本心呢？",
            ["ContentKR"] = "멀리서 찾아온 친구! 화려한 치장을 걷어내면, 자신의 본심이 환하게 드러날 거야.",
            ["DialogueId"] = 72100103,
