            ["NextDialogue"] = 72100203,
            ["SpeakNpcId"] = 830001,
            },
        [72100203] = {
            ["Content"] = "梦见孩提时，娘亲牵着我的手去渡口买糖人。",
            ["ContentKR"] = "꿈에서 어머니를 봤어. 어린 내 손을 잡고 나루터에 가서 설탕엿을 사 주셨지.",
            ["DialogueId"] = 72100203,
