            ["SpeakNpcId"] = 830001,
            },
        [72100503] = {
            ["Content"] = "咦？不是我儿？你是谁……？",
            ["ContentKR"] = "으응? 우리 아들이 아니잖아? 넌 누구...?",
            ["DialogueId"] = 72100503,
