            },
        [72100702] = {
            ["Content"] = "好冷……浑身都好冷，感觉牙齿要被冻掉下来了。",
            ["ContentKR"] = "추워요... 너무 추워서, 이가 다 얼어서 떨어져 나갈 것 같아요.",
            ["DialogueId"] = 72100702,
            ["FacialId"] = {
                [1] = "830001:PetPan_Common",
                },
            ["GUID"] = "B47F1D6C",
            ["NextDialogue"] = 72100703,
            ["SpeakNpcId"] = 830001,
            },
        [72100703] = {
            ["Content"] = "等等，原来我没有牙齿吗？那这种战栗的感觉是……",
            ["ContentKR"] = "어엇, 전 이가 없다고요? 그럼 이 으슬으슬 떨리는 기분은...",
            ["DialogueId"] = 72100703,
