        [72100902] = {
            ["Content"] = "你喜欢什么颜色？豆绿还是鹤灰？",
            ["ContentKR"] = "넌 무슨 색이 좋아? 연두색? 아니면 회색?",
            ["DialogueId"] = 72100902,
            ["FacialId"] = {
                [1] = "830001:PetPan_Common",
                },
            ["GUID"] = "B47F3E3C",
            ["NextDialogue"] = 72100903,
            ["SpeakNpcId"] = 830001,
            },
        [72100903] = {
            ["Content"] = "我啊，我喜欢云水蓝，就像我的身体一样蓝。",
            ["ContentKR"] = "난 옅은 물빛이 좋아. 나랑 똑같은 색이니까.",
            ["DialogueId"] = 72100903,
            ["FacialId"] = {
                [1] = "830001:PetPan_Common",
