            ["SpeakNpcId"] = 830001,
            },
        [72200603] = {
            ["Content"] = "它的背紧靠着岩石，它的脸贴紧了木板，它的根系没法向四周伸展，它被困在这里了……",
            ["DialogueId"] = 72200603,
            ["FacialId"] = {
