        [80002001] = {
            ["Content"] = "哇，这是一座迷宫花园！",
            ["ContentKR"] = "와, 이건 미로 화원이네!",
            ["DialogueId"] = 80002001,
            ["GUID"] = "C846D04A",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80002002,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D04A",
            },
        [80002002] = {
            ["Content"] = "独角兽{性别：先生|小姐}会藏在哪里呢？",
            ["ContentKR"] = "유니콘 {性别:오빠|언니}는 어디 숨어 있을까?",
            ["DialogueId"] = 80002002,
            ["GUID"] = "C846D074",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D074",
            },
        [80002003] = {
            ["Content"] = "嗯？没有反应……也许是需要用和它相同的颜色来画？",
            ["ContentKR"] = "으응? 반응이 없네... 혹시 똑같은 색깔로 그려야 하나?",
            ["DialogueId"] = 80002003,
            ["GUID"] = "C846D09E",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D09E",
            },
        [80002004] = {
            ["Content"] = "我还没有其他的颜料，去迷宫里找找看吧。",
            ["ContentKR"] = "피나한텐 다른 물감이 없으니까, 미로에 가서 찾아봐야겠다.",
            ["DialogueId"] = 80002004,
            ["GUID"] = "C846D0C8",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D0C8",
            },
        [80002005] = {
            ["Content"] = "唔，这一侧的迷宫被锁住了，看来要按从另一侧开始解谜呀。",
            ["ContentKR"] = "엇, 미로 이쪽 편은 잠겨 있잖아. 다른 쪽부터 먼저 시작해야겠네.",
            ["DialogueId"] = 80002005,
            ["GUID"] = "C846D0F2",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D0F2",
            },
        [80002006] = {
            ["Content"] = "独角兽{性别：先生|小姐}曾经为了躲避怪兽，和家人一起躲在狭窄的山洞里……",
            ["ContentKR"] = "유니콘 {性别:오빠|언니}는 예전에 가족과 함께, 괴물을 피해서 좁은 동굴에 숨어 지냈지...",
            ["DialogueId"] = 80002006,
            ["GUID"] = "C846D11C",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D11C",
            },
        [80002007] = {
            ["Content"] = "后来，{性别：他们|她们}勇敢地拿起武器，与怪兽对抗。",
            ["ContentKR"] = "그러다 나중엔 용감하게 무기를 들고 괴물에게 맞섰어.",
            ["DialogueId"] = 80002007,
            ["GUID"] = "C846D146",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D146",
            },
        [80002008] = {
            ["Content"] = "终于，独角兽{性别：先生|小姐}和家人一起打跑了拦路的秽兽，冲出重围……",
            ["ContentKR"] = "마침내, 유니콘 {性别:오빠|언니}는 가족과 함께, 길을 막는 필토이드를 물리치고, 겹겹의 포위를 뚫었지...",
            ["DialogueId"] = 80002008,
            ["GUID"] = "C846D170",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D170",
            },
        [80002009] = {
            ["Content"] = "却又遇到了更强大的敌人！",
            ["ContentKR"] = "그런데 더 강한 적이 나타난 거야!",
            ["DialogueId"] = 80002009,
            ["GUID"] = "C846D19A",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D19A",
            },
        [80002010] = {
            ["Content"] = "他们拼命地战斗，使出了全部的力量，却还是被迫失散了……",
            ["ContentKR"] = "그들은 죽을힘을 다해 싸웠지만, 결국은 뿔뿔이 흩어지고 말았어...",
            ["DialogueId"] = 80002010,
            ["GUID"] = "C846D1C4",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80002011,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D1C4",
            },
        [80002011] = {
            ["Content"] = "希望独角兽{性别：先生|小姐}能早一点找回重要的家人。",
            ["ContentKR"] = "유니콘 {性别:오빠|언니}가 빨리 소중한 가족을 되찾았으면 좋겠어.",
            ["DialogueId"] = 80002011,
            ["GUID"] = "C846D1EE",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D1EE",
            },
        [80002012] = {
            ["Content"] = "来到寒冰的国度之后，独角兽{性别：先生|小姐}遇到了新的伙伴，展开了一次次精彩的冒险。",
            ["ContentKR"] = "차가운 얼음 도시에 도착한 유니콘 {性别:오빠|언니}는, 새로운 동료를 만나서, 멋진 모험을 계속했어.",
            ["DialogueId"] = 80002012,
            ["GUID"] = "C846D218",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D218",
            },
        [80002013] = {
            ["Content"] = "嗯？水池里的圆环亮起了半边……看来我已经完成一半的谜题啦！",
            ["ContentKR"] = "어? 물웅덩이에 있는 둥근 고리 반쪽에 불이 들어왔네... 수수께끼의 절반은 풀었나 봐!",
            ["DialogueId"] = 80002013,
            ["GUID"] = "C846D242",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D242",
            },
        [80002014] = {
