            },
        [80002016] = {
            ["Content"] = "现在我有新的颜料了，试着改变它的颜色吧！",
            ["ContentKR"] = "이제 새로운 물감이 생겼으니까, 색깔을 바꿔 보자!",
            ["DialogueId"] = 80002016,
            ["GUID"] = "C846D2C0",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D2C0",
            },
        [80002017] = {
            ["Content"] = "这个颜色好像不对……试试看刚获得的新颜料吧。",
            ["ContentKR"] = "이 색깔이 아닌가 봐... 방금 얻은 색깔을 써보자.",
            ["DialogueId"] = 80002017,
            ["GUID"] = "C846D2EA",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D2EA",
            },
        [80002018] = {
            ["Content"] = "换一种颜料试试看吧。",
            ["ContentKR"] = "다른 색깔로 해보자.",
            ["DialogueId"] = 80002018,
            ["GUID"] = "C846D314",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D314",
            },
        [80002019] = {
            ["Content"] = "成功了！现在可以去另一侧的迷宫探险啦。",
            ["ContentKR"] = "성공이야! 이제 다른 쪽 미로를 탐험할 수 있겠어.",
            ["DialogueId"] = 80002019,
            ["GUID"] = "C846D33E",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D33E",
            },
        [80002020] = {
            ["Content"] = "看，这里有积木！独角兽{性别：先生|小姐}曾经陪菲娜一起玩过叫做“弹壳”的积木呢。",
            ["ContentKR"] = "와, 여기 블록 장난감이 있네! 유니콘 {性别:오빠|언니}하고 같이 '탄피'라는 블록을 가지고 놀았었는데.",
            ["DialogueId"] = 80002020,
            ["GUID"] = "C846D368",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D368",
            },
        [80002021] = {
            ["Content"] = "哇，是星星！好想再和独角兽{性别：先生|小姐}一起看一次真正的星空呀。",
            ["ContentKR"] = "와, 별이다! 유니콘 {性别:오빠|언니}랑 같이 진짜 별하늘을 다시 한번 보고 싶다.",
            ["DialogueId"] = 80002021,
            ["GUID"] = "C846D392",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D392",
            },
        [80002022] = {
            ["Content"] = "这里也有宝物，是独角兽{性别：先生|小姐}通过委托得到的报酬吗？",
            ["ContentKR"] = "여기도 보물 상자가 있네. 유니콘 {性别:오빠|언니}가 의뢰에서 받은 보수인가?",
            ["DialogueId"] = 80002022,
            ["GUID"] = "C846D3BC",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D3BC",
            },
        [80002023] = {
            ["Content"] = "又发现了宝物！独角兽{性别：先生|小姐}，这是你给菲娜的惊喜吗？",
            ["ContentKR"] = "또 보물 상자야! 유니콘 {性别:오빠|언니}, 이건 피나한테 주는 깜짝선물이야?",
            ["DialogueId"] = 80002023,
            ["GUID"] = "C846D3E6",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D3E6",
            },
        [80002024] = {
            ["Content"] = "菲娜和独角兽{性别：先生|小姐}一起书写的故事，一定会很长很长……嗯，我希望它永远也不要结束。",
            ["ContentKR"] = "피나랑 유니콘 {性别:오빠|언니}가 함께 쓰는 이야기는 아주아주 길 거야... 응, 영원히 끝나지 않는 이야기였으면 좋겠어.",
            ["DialogueId"] = 80002024,
            ["GUID"] = "C846D410",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D410",
            },
        [80002025] = {
            ["Content"] = "另一半的圆环也被点亮了。",
            ["ContentKR"] = "고리의 나머지 절반에도 불이 들어왔어.",
            ["DialogueId"] = 80002025,
            ["GUID"] = "C846D43A",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80002026,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D43A",
            },
        [80002026] = {
            ["Content"] = "回到水池旁边，看看有没有发生什么神奇的变化吧~",
            ["ContentKR"] = "물웅덩이 근처로 돌아가서, 신기한 변화가 생겼는지 한번 보자~",
            ["DialogueId"] = 80002026,
            ["GUID"] = "C846D464",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D464",
            },
        [80002027] = {
            ["Content"] = "哇……地板飞起来了？看来我们找到迷宫的出口啦！",
            ["ContentKR"] = "와... 바닥이 떠오르고 있어! 우리가 미로의 출구를 찾아냈나 봐!",
            ["DialogueId"] = 80002027,
            ["GUID"] = "C846D48E",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80002028,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D48E",
            },
        [80002028] = {
            ["Content"] = "谢谢你的帮忙，独角兽{性别：先生|小姐}。你这么聪明，一定也可以帮助菲娜解开现实世界中的谜题吧？",
            ["ContentKR"] = "도와줘서 고마워, 유니콘 {性别:오빠|언니}. {性别:오빠|언니}는 똑똑하니까, 피나가 현실 세계의 수수께끼를 푸는 것도 도와줄 수 있지?",
            ["DialogueId"] = 80002028,
            ["GUID"] = "C846D4B8",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D4B8",
            },
        [80002029] = {
