        [80003101] = {
            ["Content"] = "好漂亮的一片湖呀~",
            ["ContentKR"] = "와, 호수가 정말 예쁘다~",
            ["DialogueId"] = 80003101,
            ["Duration"] = 3,
            ["GUID"] = "C84784C2",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
