        [80003201] = {
            ["Content"] = "唔，前面的航路被藤蔓挡住了……",
            ["ContentKR"] = "어, 덩굴이 항로를 막고 있네...",
            ["DialogueId"] = 80003201,
            ["Duration"] = 3,
            ["GUID"] = "C847952A",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80003202,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120113/C847952A",
            },
        [80003202] = {
            ["Content"] = "下船找找有没有其他的路吧。",
            ["ContentKR"] = "내려서 다른 길이 없는지 찾아보자.",
            ["DialogueId"] = 80003202,
            ["Duration"] = 3,
            ["GUID"] = "C8479554",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120113/C8479554",
            },
        [80003203] = {
            ["Content"] = "咦，是蝴蝶小姐！你特地飞过来帮助菲娜吗，谢谢！",
            ["ContentKR"] = "응? 나비 소녀잖아! 피나를 도우러 날아와 준 거야? 정말 고마워!",
            ["DialogueId"] = 80003203,
            ["Duration"] = 3,
            ["GUID"] = "C847957E",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120113/C847957E",
            },
        [80003204] = {
            ["Content"] = "圆圆的荷叶浮起来，连成了一条路呢~这样菲娜就可以走在水面上啦。",
            ["ContentKR"] = "동그란 연잎이 떠올라서 길을 만들어 줬구나~ 이제 물 위를 지나갈 수 있게 됐어.",
            ["DialogueId"] = 80003204,
            ["Duration"] = 3,
            ["GUID"] = "C84795A8",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120113/C84795A8",
            },
        [80003205] = {
            ["Content"] = "藤蔓都消失啦，可以回去再次开动“白色夜莺号”了！",
            ["ContentKR"] = "덩굴이 사라졌네! 이제 '하얀 나이팅게일호'로 돌아갈 수 있겠어!",
            ["DialogueId"] = 80003205,
            ["Duration"] = 3,
            ["GUID"] = "C84795D2",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120113/C84795D2",
            },
        [80003206] = {
            ["Content"] = "又出现了水盆，这次它们会藏着什么机关呢？",
            ["ContentKR"] = "또 세면대네. 이번엔 어떤 장치를 숨겨 놨을까?",
            ["DialogueId"] = 80003206,
            ["Duration"] = 3,
            ["GUID"] = "C84795FC",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80003207,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120113/C84795FC",
            },
        [80003207] = {
            ["Content"] = "也许……是和这些石柱有关？",
            ["ContentKR"] = "혹시... 이 기둥이랑 관계 있는 걸까?",
            ["DialogueId"] = 80003207,
            ["Duration"] = 3,
            ["GUID"] = "C8479626",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120113/C8479626",
            },
        [80003208] = {
            ["Content"] = "蝴蝶小姐，我们成功抵达目的地啦！",
            ["ContentKR"] = "나비 소녀야, 우리 무사히 목적지에 도착했어!",
            ["DialogueId"] = 80003208,
            ["Duration"] = 3,
            ["GUID"] = "C8479650",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80003209,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120113/C8479650",
            },
        [80003209] = {
            ["Content"] = "菲娜需要你帮一个小小的忙，请和我一起回到现实世界去吧~",
            ["ContentKR"] = "피나한테 작은 부탁이 있는데 들어 줄래? 피나랑 같이 현실 세계로 돌아가 줘~",
            ["DialogueId"] = 80003209,
            ["Duration"] = 3,
