            ["Duration"] = 3,
            ["GUID"] = "C8482926",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80004104,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/C8482926",
            },
        [80004104] = {
            ["Content"] = "等我给空白的部分涂上颜色，也许它就会动起来啦。",
            ["ContentKR"] = "빈 곳에 색깔을 칠해 주자. 그럼 움직일지도 몰라.",
            ["DialogueId"] = 80004104,
            ["Duration"] = 3,
            ["GUID"] = "C8482950",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/C8482950",
            },
        [80004105] = {
            ["Content"] = "小夜莺，你怎么待在里面不出来呀？是这些荆棘把你困住了吗？",
            ["ContentKR"] = "나이팅게일아, 왜 그 안에 있어? 혹시 이 가시들 때문에 못 나오는 거야?",
            ["DialogueId"] = 80004105,
            ["Duration"] = 3,
            ["GUID"] = "C848297A",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80004106,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/C848297A",
            },
        [80004106] = {
            ["Content"] = "别害怕，菲娜会帮助你的！",
            ["ContentKR"] = "걱정 마, 피나가 도와줄게!",
            ["DialogueId"] = 80004106,
            ["Duration"] = 3,
            ["GUID"] = "C84829A4",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/C84829A4",
            },
        [80004107] = {
            ["Content"] = "这里的荆棘长得太高，把小夜莺的巢穴都挡住了。",
            ["ContentKR"] = "가시덤불이 너무 커서, 나이팅게일의 둥지를 가려버렸네.",
            ["DialogueId"] = 80004107,
            ["Duration"] = 3,
            ["GUID"] = "C84829CE",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80004108,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/C84829CE",
            },
        [80004108] = {
            ["Content"] = "用刚才的方法给它们涂上颜色，他们就会给小夜莺让路了吧？",
            ["ContentKR"] = "방금처럼 색깔을 칠해주면, 나이팅게일한테 길을 열어주겠지?",
