            },
        [80004202] = {
            ["Content"] = "小夜莺，你来给菲娜带路吧！",
            ["ContentKR"] = "나이팅게일아, 네가 길을 안내해 줄래?",
            ["DialogueId"] = 80004202,
            ["Duration"] = 3,
            ["GUID"] = "C8483964",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/C8483964",
            },
        [80004203] = {
            ["Content"] = "哇……原来这块石头是一盏灯呀！灯光亮起来，雾气就散开了。",
            ["ContentKR"] = "와... 이 돌은 등불이었구나! 등불을 켜니까 안개가 사라졌어.",
            ["DialogueId"] = 80004203,
            ["Duration"] = 3,
            ["GUID"] = "C848398E",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80004204,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/C848398E",
            },
        [80004204] = {
            ["Content"] = "我们再去找找别的石头吧。",
            ["ContentKR"] = "우리 다른 돌도 찾아보자.",
            ["DialogueId"] = 80004204,
            ["Duration"] = 3,
            ["GUID"] = "C84839B8",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/C84839B8",
            },
        [80004205] = {
            ["Content"] = "雾气会让人迷失方向，要紧跟在小夜莺身边才安全哦。",
            ["ContentKR"] = "안개 때문에 방향을 헷갈릴 수 있으니까, 나이팅게일을 바짝 따라가야 해.",
            ["DialogueId"] = 80004205,
            ["Duration"] = 3,
            ["GUID"] = "C84839E2",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/C84839E2",
            },
        [80004206] = {
            ["Content"] = "终于走出迷雾了！快看，森林的出口就在前面。",
            ["ContentKR"] = "드디어 안개 구역을 빠져나왔어! 봐, 숲의 출구가 저 앞에 있어.",
            ["DialogueId"] = 80004206,
            ["Duration"] = 3,
            ["GUID"] = "C8483A0C",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/C8483A0C",
            },
        [80004207] = {
            ["Content"] = "走出森林之后，会见到怎样的风景呢？好期待呀！",
            ["ContentKR"] = "숲을 나가면 어떤 풍경이 기다리고 있을까? 정말 기대돼!",
            ["DialogueId"] = 80004207,
            ["Duration"] = 3,
            ["GUID"] = "C8483A36",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/C8483A36",
            },
        [80004208] = {
            ["Content"] = "咦，那是……大魔法师、独角兽{性别：先生|小姐}和蝴蝶小姐！大家都在等我们呢。",
            ["ContentKR"] = "어, 저건... 대마법사랑 유니콘 {性别:오빠|언니}랑 나비 소녀잖아! 다들 여기서 우릴 기다리고 있었구나.",
            ["DialogueId"] = 80004208,
            ["Duration"] = 3,
            ["GUID"] = "C8483A60",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80004209,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/C8483A60",
            },
        [80004209] = {
            ["Content"] = "小夜莺，我们赶快过去和它们会合吧！",
            ["ContentKR"] = "나이팅게일아, 얼른 모두를 만나러 가자!",
            ["DialogueId"] = 80004209,
            ["Duration"] = 3,
            ["GUID"] = "C8483A8A",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/C8483A8A",
            },
        [80004210] = {
            ["Camera"] = "-393.173828,-198.093201,117.472694,0.000079,-4.382597,17.344532,35.000008,348.827637,false,Manual,20.0",
            ["Content"] = "看来这里就是故事的终点啦！",
            ["ContentKR"] = "여기가 바로 이야기의 종착지인가 봐!",
            ["DialogueId"] = 80004210,
            ["GUID"] = "C8483AB4",
