            ["SpeakNpcId"] = 94202,
            ["TalkActionId"] = {
                [1] = "94202:Sit_Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Landi/002/C858E400",
            },
        [80030209] = {
            ["Content"] = "而小时候，我的姐姐们总和我说，成为绅士是一个小男孩的终极目标，人生意义。",
            ["ContentKR"] = "어렸을 때, 누나들은 항상 나한테 신사가 되는 게 소년의 궁극적인 목표이자 인생에서 가치 있는 일이라고 했거든.",
            ["DialogueId"] = 80030209,
            ["GUID"] = "C858E42A",
            ["NextOptions"] = {
