        [80040113] = {
            ["Camera"] = "-204.043701,-27.717529,129.719727,-0.000641,-3.196262,-3.505373,40.0,272.0336,false,Manual,4.253633",
            ["Content"] = "嗯，“食材之间的相互作用是一门大学问，只有将合适的食材搭配在一起才能让它们都发挥出最佳的味道”——这是《烹饪的艺术》这本书上讲的。",
            ["ContentKR"] = "〈요리의 예술〉이라는 책에는 '식재료 사이의 상호작용은 많은 연구가 필요하다. 어울리는 식재료를 조화롭게 활용해야만 최고의 맛을 낼 수 있다'라는 내용이 있을 정도라고.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80040113,
            ["FacialId"] = {
                [1] = "790008:Confident02",
                },
            ["FinalCamera"] = "-203.907471,-22.408691,129.719727,-0.000641,-3.196262,-4.905429,40.0,272.0336,false,Manual,4.253633",
            ["GUID"] = "C85F3D0A",
            ["NextDialogue"] = 80040114,
