        [80040125] = {
            ["Camera"] = "113.315186,151.120361,105.79834,0.000122,6.203184,-112.57106,40.0,164.391006,false,Manual,5.845709",
            ["Content"] = "没有没有，你做饭大多数时候都很棒，只是刚好这两次有点不巧。",
            ["ContentKR"] = "아니야, 아니야. 대체로 정말로 맛있었어. 다만 이 두 번이 공교로웠던 거지.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80040125,
            ["FacialId"] = {
                [1] = "790008:Ahaha02",
                },
            ["FinalCamera"] = "122.489502,147.21582,105.446533,0.000123,3.003179,-140.170731,40.000011,313.635376,false,Manual,5.845709",
            ["GUID"] = "C85F3F02",
            ["NextDialogue"] = 80040126,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Disagree",
                },
            ["ToFinalCameraBlendTime"] = 25,
            ["VoiceName"] = "voice/$Locale$/inv/Heitao/001/C85F3F02",
            },
        [80040126] = {
            ["Content"] = "每次你做饭的时候我都等着尝你又有什么新的花样，嗯没错……是《烹饪的艺术》这本书的作者没品味！他根本不懂什么是新奇的食材组合。",
            ["ContentKR"] = "네가 요리할 때마다 또 어떤 새로운 게 날 기다리고 있을지 기대했거든. 아무래도... 〈요리의 예술〉의 작가가 맛을 잘 모르는 것 같아! 새로운 방식의 식재료 조합에 대해 전혀 모르는 거지.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80040126,
            ["FacialId"] = {
                [1] = "790008:Satisfy01",
                },
            ["GUID"] = "C85F3F2C",
            ["NextDialogue"] = 80040127,
            ["Scripts"] = "PARA{SEQ{PlayAnimation{ActorId{790008},AnimationId{\"Agree\"},Duration{1}},PlayAnimation{_delay{3},ActorId{790008},AnimationId{\"Confident_Start\"},Duration{3}}},SEQ{CameraMoveTo{_delay{3},TargetPosition{\"-451.446045,109.144287,58.609131,0.000133,5.802526,-23.556147,40.0,62.233727,false,Manual,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-448.734375,115.36499,58.609131,0.000134,5.802526,-23.555901,40.0,62.233727,false,Manual,22.0\"},duration{15}}}}",
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Heitao/001/C85F3F2C",
            },
        [80040127] = {
