            ["Content"] = "……嗯。",
            ["ContentKR"] = "...알겠어.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80040129,
            ["GUID"] = "C85F3FAA",
            ["NextDialogue"] = 80040130,
            ["SpeakNpcId"] = 790007,
