            ["TalkActionId"] = {
                [1] = "790008:Explain02_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Heitao/001/C85F3FD4",
            },
        [80040131] = {
            ["Camera"] = "-221.572266,-16.551514,137.419067,0.00028,-4.399502,-7.360059,40.0,282.428741,false,Manual,2.79054",
            ["Content"] = "一点点甜、一点点酸，还有——嗯，不行，这个先保密。",
            ["ContentKR"] = "달콤하고, 새콤하기도 해. 그리고... 아, 아니지. 우선 비밀로 해야 겠다.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80040131,
            ["FinalCamera"] = "-220.866455,-10.840088,137.419067,0.000279,-4.399502,-9.360314,40.0,282.428741,false,Manual,2.79054",
