            },
        [80040207] = {
            ["Content"] = "……嗯。",
            ["ContentKR"] = "...응.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80040207,
            ["GUID"] = "C85F4C76",
            ["NextDialogue"] = 80040208,
