            ["TalkActionId"] = {
                [1] = "790007:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Heitao/002/C85F4C76",
            },
        [80040208] = {
            ["Camera"] = "-202.862793,-154.904297,120.652222,-0.000091,-1.500019,57.155331,40.0,286.969482,false,Manual,2.991984",
            ["Content"] = "说过很多次了吧，遇到危险的时候先保护自己。",
            ["ContentKR"] = "내가 여러 번 말했잖아. 위험한 상황에서는 너 자신부터 챙기라고.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80040208,
            ["FinalCamera"] = "-202.862793,-154.904297,120.652222,-0.000092,-0.500004,57.155106,40.0,286.969482,false,Manual,2.991984",
            ["GUID"] = "C85F4CA0",
            ["NextDialogue"] = 80040209,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Talk03_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Heitao/002/C85F4CA0",
            },
        [80040209] = {
            ["Content"] = "像刚才那只海雕，你直接躲开不就好了吗！为什么非得正面拦住它，被它抓那一下子——还疼不疼？",
            ["ContentKR"] = "방금 그 독수리도 바로 피했으면 되잖아! 왜 굳이 정면으로 독수리를 막아서서 다치고 그래?! 아프진 않아?",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80040209,
            ["GUID"] = "C85F4CCA",
            ["NextDialogue"] = 80040210,
            ["Scripts"] = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"-90.239258,-23.222412,118.679077,-0.000091,6.299606,53.554245,40.0,286.969482,false,DoNotOverride,2.991984\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-83.696533,-27.761963,118.679077,-0.000092,6.099605,56.553841,40.0,286.969482,false,DoNotOverride,2.991984\"},duration{5}}}",
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Heitao/002/C85F4CCA",
            },
        [80040210] = {
            ["Camera"] = "43.03418,84.666992,133.484863,-0.000092,-1.89996,-156.048233,40.0,225.258224,false,Manual,5.068474",
            ["Content"] = "那时你就在我身后。如果躲开，它会伤到你。",
            ["ContentKR"] = "그때 네가 내 뒤에 있었으니까. 내가 피하면 네가 다쳤을 거야.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80040210,
            ["FinalCamera"] = "43.81665,82.903076,133.484863,-0.000092,-1.89996,-156.848312,40.0,225.258224,false,Manual,5.068474",
            ["GUID"] = "C85F4CF4",
            ["NextDialogue"] = 80040211,
            ["SpeakNpcId"] = 790007,
            ["TalkActionId"] = {
                [1] = "790008:Explain01_End",
                [2] = "790007:Disagree",
                },
            ["ToFinalCameraBlendTime"] = 10,
