            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/004/C865DEC2",
            },
        [80050462] = {
            ["Content"] = "谢谢你，独角兽{性别：先生|小姐}。我想，我需要更久的时间——",
            ["ContentKR"] = "유니콘 {性别:오빠|언니}, 고마워. 나, 더 생각해봐야 할 것 같아...",
            ["DialogueId"] = 80050462,
            ["GUID"] = "C865DEEC",
            ["NextDialogue"] = 80050463,
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/004/C865DEEC",
            },
        [80050463] = {
            ["Content"] = "等我再多长大一些、懂得更多、走过更多的路之后，我才能把这本空白的故事写完。",
            ["ContentKR"] = "내가 더 커서 아는 게 많아지고, 더 많은 경험을 해봐야만 이 이야기를 완성할 수 있을 것 같아.",
            ["DialogueId"] = 80050463,
            ["GUID"] = "C865DF16",
            ["NextDialogue"] = 80050464,
            ["SpeakNpcId"] = 790017,
            ["VoiceName"] = "voice/$Locale$/inv/Feina/004/C865DF16",
            },
        [80050464] = {
            ["Content"] = "所以，独角兽{性别：先生|小姐}，你还欠着菲娜这个愿望哦！",
            ["ContentKR"] = "그러니까 유니콘 {性别:오빠|언니}, 이 소원은 일단 보류해 줘!",
            ["DialogueId"] = 80050464,
            ["FacialId"] = {
                [1] = "790017:Confident01",
                },
            ["GUID"] = "C865DF40",
            ["NextOptions"] = {
                [1] = 80050465,
                [2] = 80050466,
                },
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/004/C865DF40",
            },
        [80050465] = {
            ["Content"] = "好好好，答应你。",
            ["ContentKR"] = "알겠어. 그렇게 할게.",
            ["DialogueId"] = 80050465,
            ["GUID"] = "C865DF6A",
            ["NextDialogue"] = 80050467,
            },
        [80050466] = {
            ["Content"] = "感觉被套牢了……",
            ["ContentKR"] = "뭔가 코가 꿰인 느낌인데...",
            ["DialogueId"] = 80050466,
            ["GUID"] = "C865DF94",
            ["NextDialogue"] = 80050467,
            },
        [80050467] = {
            ["Content"] = "嘿嘿……那就让我们在以后的日子，一起把这个故事写完吧。",
            ["ContentKR"] = "헤헤... 그럼 이제부터 이야기를 같이 만드는 거야!",
            ["DialogueId"] = 80050467,
            ["FacialId"] = {
                [1] = "790017:Happy02",
                },
            ["GUID"] = "C865DFBE",
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/004/C865DFBE",
            },
        [80060100] = {
            ["Content"] = "天大地大，吃饭最大！让我看看你有没有吃得饱饱的呢？",
            ["ContentKR"] = "세상에서 밥 먹는 것보다 중요한 건 없지! 배불리 먹었는지 한번 확인해 볼까?",
            ["DialogueId"] = 80060100,
            ["GUID"] = "C86C0C28",
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/001/C86C0C28",
            },
        [80060101] = {
            ["Camera"] = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
            ["Content"] = "嗯——好香的面包饮料，这是你做的吗？真厉害！",
            ["ContentKR"] = "음, 이 맛있는 냄새. 네가 만든 거야? 진짜 대단해!",
            ["DialogueId"] = 80060101,
            ["FacialId"] = {
                [1] = "95101:Smile02",
                },
            ["GUID"] = "C86C0C52",
            ["LookAt"] = {
                [1] = "95101:p(18000P3)",
                },
            ["NextDialogue"] = 80060102,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/001/C86C0C52",
            },
        [80060102] = {
            ["Content"] = "在传颂会布施的时候，有位好心肠的太太就带过来她亲自调制的面包饮料。她说做这个可麻烦了呢！",
            ["ContentKR"] = "교회 기부금을 전달할 때, 한 친절한 아주머니께서 직접 만든 빵 음료를 가져오셨는데, 만드는 법이 정말 복잡하다고 하시더라구.",
            ["DialogueId"] = 80060102,
            ["GUID"] = "C86C0C7C",
            ["NextDialogue"] = 80060103,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/001/C86C0C7C",
            },
        [80060103] = {
            ["Content"] = "嗯，得先把面包切成小块，撒上甜丝丝的麦芽糖，再放在烤箱里烘得热乎乎，最后还要泡在水里，咕嘟嘟发酵……",
            ["ContentKR"] = "음, 빵을 작은 조각으로 자르고, 달콤한 맥아당을 뿌린 다음 오븐에서 구워야 해. 마지막에는 물에 담궈서 보글보글 발효시키고...",
            ["DialogueId"] = 80060103,
            ["FacialId"] = {
                [1] = "95101:None",
                },
            ["GUID"] = "C86C0CA6",
            ["NextDialogue"] = 80060104,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_Talk02R_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/001/C86C0CA6",
            },
        [80060104] = {
            ["Content"] = "唔……你做的和那个太太做的一样好喝！",
            ["ContentKR"] = "우웅... 네가 만든 것도 아주머니께서 만든 거처럼 맛있어!",
            ["DialogueId"] = 80060104,
            ["GUID"] = "C86C0CD0",
            ["NextOptions"] = {
                [1] = 80060105,
                },
            ["TalkActionId"] = {
                [1] = "95101:Sit_Talk02R_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/001/C86C0CD0",
            },
        [80060105] = {
            ["Content"] = "你连这个都知道？",
            ["ContentKR"] = "와, 그런 것도 알아?",
            ["DialogueId"] = 80060105,
            ["GUID"] = "C86C0CFA",
            ["NextDialogue"] = 80060106,
            },
        [80060106] = {
            ["Content"] = "哼哼，能让大家吃饱喝好的东西我全都知道！",
            ["ContentKR"] = "흐흥, 배를 부르게 할 수 있는 거라면 다 알고 있지!",
            ["DialogueId"] = 80060106,
            ["GUID"] = "C86C0D24",
            ["NextDialogue"] = 80060107,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/001/C86C0D24",
            },
        [80060107] = {
            ["Content"] = "可不是吹牛哦，我可是艾利西安的食物百科全书，没有粮秣专员松露不知道的食物！",
            ["ContentKR"] = "막 말하는 거 아냐. 나는 엘리시안의 음식 백과사전이라구. 나 식량보급원 트러플이 모르는 음식은 이 세상에 없다니까!",
            ["DialogueId"] = 80060107,
            ["FacialId"] = {
                [1] = "95101:Confident02",
                },
            ["GUID"] = "C86C0D4E",
            ["NextDialogue"] = 80060108,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/001/C86C0D4E",
            },
        [80060108] = {
            ["Content"] = "所以，你在“吃”上有任何问题都可以来问我！这个季节最好吃的蔬菜在哪里呀，这道菜是用什么做的呀……我统统都知道！",
            ["ContentKR"] = "그러니까, '먹을 것'이라면 뭐든지 물어봐도 돼! 지금 제철 음식은 무엇인지, 또 이 요리에는 뭐가 들어갔는지... 난 전부 다 안다구!",
            ["DialogueId"] = 80060108,
            ["FacialId"] = {
                [1] = "95101:None",
                },
            ["GUID"] = "C86C0D78",
            ["NextOptions"] = {
                [1] = 80060109,
                },
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/001/C86C0D78",
            },
        [80060109] = {
            ["Content"] = "真的这么厉害？你能猜出来你刚才喝的饮料里放了什么水果吗？",
            ["ContentKR"] = "정말? 그렇다면 방금 네가 마신 음료수에 무슨 과일이 들어갔는지 맞힐 수 있어?",
            ["DialogueId"] = 80060109,
            ["GUID"] = "C86C0DA2",
            ["NextDialogue"] = 80060110,
            },
        [80060110] = {
            ["Content"] = "好呀，让我再尝一尝！……是北风莓！不过你用的莓子还是有些涩，要是过几天再摘，莓子会更大更甜的！",
            ["ContentKR"] = "그럼, 한 번 더 마셔볼게! ...아이스베리네! 근데 네가 사용한 베리는 좀 떫은 거 같아. 며칠만 더 지나고 땄으면 더 크고 달콤했을 텐데!",
            ["DialogueId"] = 80060110,
            ["FacialId"] = {
                [1] = "95101:Happy01",
                },
            ["GUID"] = "C86C0DCC",
            ["NextOptions"] = {
                [1] = 80060111,
                },
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/001/C86C0DCC",
            },
        [80060111] = {
            ["Content"] = "还有一种浆果没猜出来。",
            ["ContentKR"] = "아이스베리 말고 과일 한 가지가 더 있어.",
            ["DialogueId"] = 80060111,
            ["GUID"] = "C86C0DF6",
            ["NextDialogue"] = 80060112,
            },
        [80060112] = {
            ["Content"] = "确实还有另外的味道，好熟悉……让我想想……让我想想……",
            ["ContentKR"] = "확실히 다른 맛도 있긴 해. 익숙한 맛인데... 음... 뭘까...",
            ["DialogueId"] = 80060112,
            ["GUID"] = "C86C0E20",
            ["NextOptions"] = {
                [1] = 80060113,
                },
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/001/C86C0E20",
            },
        [80060113] = {
            ["Content"] = "猜不出来就让我告诉你吧，是——",
            ["ContentKR"] = "못 맞출 것 같으니 내가 알려줄게. 바로...",
            ["DialogueId"] = 80060113,
            ["GUID"] = "C86C0E4A",
            ["NextDialogue"] = 80060114,
            },
        [80060114] = {
            ["Content"] = "——是朱红泪滴！今天早晨从野外刚刚采摘的朱红泪滴，对吧？",
            ["ContentKR"] = "...붉은 눈물방울이구나! 오늘 아침 밖에서 갓 딴 붉은 눈물방울, 맞지?",
            ["DialogueId"] = 80060114,
            ["FacialId"] = {
                [1] = "95101:Shock01",
                },
            ["GUID"] = "C86C0E74",
            ["NextOptions"] = {
                [1] = 80060115,
                },
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/001/C86C0E74",
            },
        [80060115] = {
            ["Content"] = "你说对了……",
            ["ContentKR"] = "맞아...",
            ["DialogueId"] = 80060115,
            ["GUID"] = "C86C0E9E",
            ["NextDialogue"] = 80060116,
            },
        [80060116] = {
            ["Content"] = "嘿嘿，不用这么惊讶，可别小瞧我松露的舌头哦！我和榛子一起找了这——么久的吃的，别说是朱红泪滴，什么稀奇古怪的东西我都尝过啦。",
            ["ContentKR"] = "헤헤, 그렇게 놀랄 필요 없어. 이 트러플의 혀를 얕보지 말라고! 난 헤이즐넛이랑 먹을 걸 찾는다고 엄~청나게 많은 걸 먹어봤거든. 붉은 눈물방울 말고도 별의별 이상한 음식도 다 먹어봤다고.",
            ["DialogueId"] = 80060116,
            ["FacialId"] = {
                [1] = "95101:None",
                },
            ["GUID"] = "C86C0EC8",
            ["NextDialogue"] = 80060117,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/001/C86C0EC8",
            },
        [80060117] = {
            ["Content"] = "朱红泪滴的味道有点酸，像梅子，最适合和甜甜的浆果放在一起；巨松果的皮特别厚实，但是里面的果仁又白又嫩，脆脆的、甜甜的！",
            ["ContentKR"] = "매실처럼 새콤한 붉은 눈물방울은 달콤한 베리와 가장 잘 어울려. 커다란 솔방울은 껍질이 두껍지만 그 안에 있는 견과류는 하얗고, 연한데다, 바삭하고, 달달해!",
            ["DialogueId"] = 80060117,
            ["FacialId"] = {
                [1] = "95101:Satisfy01",
                },
            ["GUID"] = "C86C0EF2",
            ["NextDialogue"] = 80060118,
            ["SpeakNpcId"] = 95101,
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/001/C86C0EF2",
            },
        [80060118] = {
            ["Content"] = "匍地枝黑黢黢的，看着就难吃，吃到嘴里果然又苦又涩；罐子里装着的隔热涂胶看着像牛奶，闻着像果子，但吃下去会肚子疼，你记着千万别吃！",
            ["ContentKR"] = "땅의 가지는 새까매서 그런지 딱 봐도 맛없어 보이는데, 입에 넣으면 떫고 쓴 맛이 느껴져. 단지 안에 들어있는 단열 코팅 접착제는 우유처럼 보이고 과일 냄새가 나지만, 먹으면 탈 날 수 있니 절대로 먹으면 안 돼!",
            ["DialogueId"] = 80060118,
            ["FacialId"] = {
                [1] = "95101:Sad01",
                },
            ["GUID"] = "C86C0F1C",
            ["NextOptions"] = {
                [1] = 80060119,
                [2] = 80060122,
                },
            ["SpeakNpcId"] = 95101,
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/001/C86C0F1C",
            },
        [80060119] = {
            ["Content"] = "你该不会连秽兽触手什么的都尝过吧……",
            ["ContentKR"] = "설마 필토이드의 촉수까지 먹어본 건 아니겠지...",
            ["DialogueId"] = 80060119,
            ["GUID"] = "C86C0F46",
            ["NextDialogue"] = 80060120,
            },
        [80060120] = {
            ["Content"] = "这个倒是没有。会是什么味道呢？我猜应该会很滑，弹性很好……要不下次和榛子一起去看看……",
            ["ContentKR"] = "그건 아직이야. 어떤 맛일까? 음, 미끌미끌하고 쫄깃할 것 같은데... 다음에 헤이즐넛이랑 같이 구하러 가볼까...",
            ["DialogueId"] = 80060120,
            ["FacialId"] = {
                [1] = "95101:None",
                },
            ["GUID"] = "C86C0F70",
            ["NextDialogue"] = 80060121,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/001/C86C0F70",
            },
        [80060121] = {
            ["Content"] = "啊……不行不行！虽然榛子能撞飞小个儿的秽兽，但大秽兽很可怕，不能让榛子冒这个险！",
            ["ContentKR"] = "아... 안 돼! 덩치가 작은 필토이드는 헤이즐넛의 힘으로 날려버릴 수 있지만 덩치가 큰 애들은 엄청 무섭다고. 헤이즐넛을 위험에 빠지게 할 수는 없어!",
            ["DialogueId"] = 80060121,
            ["FacialId"] = {
                [1] = "95101:Shock01",
                },
            ["GUID"] = "C86C0F9A",
            ["NextOptions"] = {
                [1] = 80060125,
                },
            ["SpeakNpcId"] = 95101,
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/001/C86C0F9A",
            },
        [80060122] = {
            ["Content"] = "你能健康活到现在，真不容易……",
            ["ContentKR"] = "지금까지 멀쩡한 게 기적일 지경인데...",
            ["DialogueId"] = 80060122,
            ["GUID"] = "C86C0FC4",
            ["NextDialogue"] = 80060123,
            },
        [80060123] = {
            ["Content"] = "嗯，小时候和榛子流浪的时候确实偶尔会吃到有毒的果子，吃坏肚子。",
            ["ContentKR"] = "맞아. 어릴 때 헤이즐넛과 떠돌이 생활을 할 적엔 가끔 독이 있는 열매를 먹어서 배탈이 나곤 했어.",
            ["DialogueId"] = 80060123,
            ["FacialId"] = {
                [1] = "95101:None",
                },
            ["GUID"] = "C86C0FEE",
            ["NextDialogue"] = 80060124,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/001/C86C0FEE",
            },
        [80060124] = {
            ["Content"] = "不过放心吧，现在路边的野花野果，我已经可以看一眼，闻一闻，就知道有没有毒，能不能吃啦。",
            ["ContentKR"] = "하지만 걱정 마. 이제는 길가에 있는 꽃이나 열매는 보기만 해도, 아니면 냄새만 맡아도 독이 있는지, 먹을 수 있는지 알 수 있으니까.",
            ["DialogueId"] = 80060124,
            ["GUID"] = "C86C1018",
            ["NextOptions"] = {
                [1] = 80060125,
                },
            ["SpeakNpcId"] = 95101,
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/001/C86C1018",
            },
        [80060125] = {
            ["Content"] = "你怎么尝过这么多食物？",
            ["ContentKR"] = "어쩌다 그렇게 많은 음식을 먹어보게 된 거야?",
            ["DialogueId"] = 80060125,
            ["GUID"] = "C86C1042",
            ["NextDialogue"] = 80060126,
            },
        [80060126] = {
            ["Content"] = "因为没有东西吃呀。很小很小的时候，我就在外面一个人流浪了。",
            ["ContentKR"] = "그야 먹을 게 없었으니까. 아주 어릴 때부터 나는 혼자서 떠돌이 생활을 했거든.",
            ["DialogueId"] = 80060126,
            ["FacialId"] = {
                [1] = "95101:Iyada01",
                },
            ["GUID"] = "C86C106C",
            ["NextDialogue"] = 80060127,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/001/C86C106C",
            },
        [80060127] = {
            ["Content"] = "我从小就比别人吃得多一些，所以就算偶尔遇到好心人掰给我几块点心，我还是吃不饱，每天都觉得好饿好饿……",
            ["ContentKR"] = "어릴 때부터 남들보다 더 많이 먹어서 그런지, 마음씨 좋은 분이 먹을 걸 나눠줘도 배가 여전히 고팠어. 배가 고프지 않은 날이 없었지...",
            ["DialogueId"] = 80060127,
            ["FacialId"] = {
                [1] = "95101:Sad01",
                },
            ["GUID"] = "C86C1096",
            ["NextDialogue"] = 80060128,
            ["SpeakNpcId"] = 95101,
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/001/C86C1096",
            },
        [80060128] = {
            ["Content"] = "哎呀，你不要这个表情嘛，我早就不难过了，因为我很快就遇到榛子啦。",
            ["ContentKR"] = "어라? 그런 표정 짓지 마, 난 이제 괜찮으니까! 얼마 지나지 않아서 헤이즐넛을 만났거든.",
            ["DialogueId"] = 80060128,
            ["FacialId"] = {
                [1] = "95101:None",
                },
            ["GUID"] = "C86C10C0",
            ["NextDialogue"] = 80060129,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/001/C86C10C0",
            },
        [80060129] = {
            ["Content"] = "那天我很饿，榛子也很饿，可是榛子明明也是个小不点儿，却把它从垃圾桶里翻出来的唯一一块面包给了我。",
            ["ContentKR"] = "하루는 나랑 헤이즐넛이 엄청 배고팠거든. 그런데 헤이즐넛이, 그때는 쬐끄맸는데... 아무튼, 그 쬐끄만 녀석이 쓰레기통에서 찾아낸 유일한 빵 조각을 내게 주더라고.",
            ["DialogueId"] = 80060129,
            ["FacialId"] = {
                [1] = "95101:Satisfy01",
                },
            ["GUID"] = "C86C10EA",
            ["NextDialogue"] = 80060130,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/001/C86C10EA",
            },
        [80060130] = {
            ["Content"] = "我也忘了那时候我怎么想的，我只记得自己趴在它耳朵边，对它说，“我们一起离开这座城市，到外面去找食物吧！”",
            ["ContentKR"] = "나도 내가 무슨 생각이었는지 모르지만, 그때 내가 헤이즐넛에게 '우리 함께 이 도시를 떠나서 음식을 찾으러 가자!'라고 했던 게 기억나.",
            ["DialogueId"] = 80060130,
            ["FacialId"] = {
                [1] = "95101:Smile02",
                },
            ["GUID"] = "C86C1114",
            ["NextOptions"] = {
                [1] = 80060131,
                },
            ["SpeakNpcId"] = 95101,
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/001/C86C1114",
            },
        [80060131] = {
            ["Content"] = "猪竟然能听懂人话……",
            ["ContentKR"] = "돼지가 사람 말도 알아듣다니...",
            ["DialogueId"] = 80060131,
            ["GUID"] = "C86C113E",
            ["NextDialogue"] = 80060132,
            },
        [80060132] = {
            ["Content"] = "嗯，很神奇，对吧！榛子一定是神明大人赐给我的朋友。",
            ["ContentKR"] = "응, 정말 신기하지? 헤이즐넛은 신이 내게 보낸 친구인 게 분명해.",
            ["DialogueId"] = 80060132,
            ["GUID"] = "C86C1168",
            ["NextDialogue"] = 80060133,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/001/C86C1168",
            },
        [80060133] = {
            ["Content"] = "从那天之后，榛子驮着我，去田野，去山林……我们再也没有饿过肚子，甚至还能存下食物，分给和我们一样饥饿的人。",
            ["ContentKR"] = "그날 이후로 헤이즐넛은 나를 업고 들판과 산속을 다녔어... 그 후로 우린 다시는 배고프지 않았고, 심지어 남은 음식을 모아서 그때의 우리처럼 배고픈 사람에게 나눠줄 수 있게 됐어.",
            ["DialogueId"] = 80060133,
            ["GUID"] = "C86C1192",
            ["NextDialogue"] = 80060134,
            ["SpeakNpcId"] = 95101,
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/001/C86C1192",
            },
        [80060134] = {
            ["Content"] = "啊……榛子，不知道它一个在外头会不会饿。那个那个，请问我可以把你送给我的饮料打包半份带给榛子吗？",
            ["ContentKR"] = "아... 헤이즐넛이 혼자 밖에 있거든. 배가 고플지도 모르겠다. 그, 혹시 나한테 준 음료수를 반 정도만 헤이즐넛에게 나눠 줘도 될까?",
            ["DialogueId"] = 80060134,
            ["FacialId"] = {
                [1] = "95101:Satisfy01",
                },
            ["GUID"] = "C86C11BC",
            ["NextOptions"] = {
                [1] = 80060135,
                [2] = 80060138,
                },
            ["SpeakNpcId"] = 95101,
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/001/C86C11BC",
            },
        [80060135] = {
            ["Content"] = "当然可以。",
            ["ContentKR"] = "물론이지.",
            ["DialogueId"] = 80060135,
            ["GUID"] = "C86C11E6",
            ["NextDialogue"] = 80060136,
            },
        [80060136] = {
            ["Content"] = "哇……你真是好心肠！之前总有人看不惯榛子长得像小猪，看到我分给它好吃的就唠叨个没完。可是对我来说，榛子是很好很好的同伴……",
            ["ContentKR"] = "와... 넌 정말 좋은 사람이야! 전에 어떤 사람은 헤이즐넛을 그냥 돼지로만 취급해서, 내가 맛있는 걸 나눠줄 때마다 옆에서 잔소리를 끝도 없이 했거든. 근데 헤이즐넛은 내 최고의 동료인걸...",
            ["DialogueId"] = 80060136,
            ["FacialId"] = {
                [1] = "95101:Happy01",
                },
            ["GUID"] = "C86C1210",
            ["NextDialogue"] = 80060137,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/001/C86C1210",
            },
        [80060137] = {
            ["Content"] = "总之真的谢谢你不嫌弃它！",
            ["ContentKR"] = "어쨌든 진짜 고마워!",
            ["DialogueId"] = 80060137,
            ["GUID"] = "C86C123A",
            ["NextDialogue"] = 80060141,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/001/C86C123A",
            },
        [80060138] = {
            ["Content"] = "不想给猪喝……",
            ["ContentKR"] = "돼지에게 주긴 싫은데...",
            ["DialogueId"] = 80060138,
            ["GUID"] = "C86C1264",
            ["NextDialogue"] = 80060139,
            },
        [80060139] = {
            ["Content"] = "好吧，那、那我也不喝了。",
            ["ContentKR"] = "그래. 그, 그러면 나도 그만 마실게.",
            ["DialogueId"] = 80060139,
            ["FacialId"] = {
                [1] = "95101:None",
                },
            ["GUID"] = "C86C128E",
            ["NextDialogue"] = 80060140,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/001/C86C128E",
            },
        [80060140] = {
            ["Content"] = "榛子是我最好的同伴，你嫌弃它和嫌弃我是一样的……榛子会伤心的，我也会。不过，还是要谢谢你的面包饮料。",
            ["ContentKR"] = "헤이즐넛은 내 최고의 동료야. 헤이즐넛을 미워하는 건 나를 미워하는 것과 같아... 헤이즐넛은 분명 상처받을 거야. 물론 나도 그렇고. 그래도, 빵 음료수를 대접해 줘서 고마워.",
            ["DialogueId"] = 80060140,
            ["FacialId"] = {
                [1] = "95101:Happy02",
                },
            ["GUID"] = "C86C12B8",
            ["NextDialogue"] = 80060141,
            ["SpeakNpcId"] = 95101,
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/001/C86C12B8",
            },
        [80060141] = {
            ["Content"] = "我已经喝饱啦。改天见！",
            ["ContentKR"] = "다 마셨다. 다음에 봐!",
            ["DialogueId"] = 80060141,
            ["FacialId"] = {
                [1] = "95101:None",
                },
            ["GUID"] = "C86C12E2",
            ["SpeakNpcId"] = 95101,
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/001/C86C12E2",
            },
        [80060201] = {
            ["Camera"] = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
            ["Content"] = "嗯……唔唔……",
            ["ContentKR"] = "음... 으음...",
            ["DialogueId"] = 80060201,
            ["GUID"] = "C86C1CBA",
            ["LookAt"] = {
                [1] = "95101:p(18000P3)",
                },
            ["NextDialogue"] = 80060202,
            ["SpeakNpcId"] = 95101,
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/002/C86C1CBA",
            },
        [80060202] = {
            ["Content"] = "唉……",
            ["ContentKR"] = "에휴...",
            ["DialogueId"] = 80060202,
            ["FacialId"] = {
                [1] = "95101:Sad01",
                },
            ["GUID"] = "C86C1CE4",
            ["NextOptions"] = {
                [1] = 80060203,
                },
            ["SpeakNpcId"] = 95101,
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/002/C86C1CE4",
            },
        [80060203] = {
            ["Content"] = "嗯？怎么这么不开心？",
            ["ContentKR"] = "어라? 왜 기분이 별로야?",
            ["DialogueId"] = 80060203,
            ["GUID"] = "C86C1D0E",
            ["NextDialogue"] = 80060204,
            },
        [80060204] = {
            ["Content"] = "嗯？没，没有啊……没有不开心。嘿嘿，嘿嘿嘿！",
            ["ContentKR"] = "어? 아, 아냐... 나 지금 기분 완전 좋은데. 헤헤, 하하하!",
            ["DialogueId"] = 80060204,
            ["FacialId"] = {
                [1] = "95101:Shock01",
                },
            ["GUID"] = "C86C1D38",
            ["NextOptions"] = {
                [1] = 80060205,
                },
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/002/C86C1D38",
            },
        [80060205] = {
            ["Content"] = "别强撑了，刚刚你脸蛋鼓得像塞了面包。",
            ["ContentKR"] = "거짓말하지 마. 방금 네 볼이 빵이라도 넣은 것처럼 볼록 튀어나와 있었는 걸.",
            ["DialogueId"] = 80060205,
            ["GUID"] = "C86C1D62",
            ["NextDialogue"] = 80060206,
            },
        [80060206] = {
            ["Content"] = "唉，你都看出来了呀……好吧，虽然分给人面包好，分给人烦恼不好，但既然你问了，那你就来帮我评评理吧！",
            ["ContentKR"] = "휴, 들켰네... 그래, 다른 사람에게 먹는 게 아니라 고민을 나누는 건 별로지만, 네가 물었으니까 말해줄게. 잘 들어봐!",
            ["DialogueId"] = 80060206,
            ["FacialId"] = {
                [1] = "95101:None",
                },
            ["GUID"] = "C86C1D8C",
            ["NextDialogue"] = 80060207,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/002/C86C1D8C",
            },
        [80060207] = {
            ["Content"] = "我前两天遇到了一个很讨厌的家伙……他好像是哪个贵族家里的管家，跑来找我们粮秣专员说要收购坚果。",
            ["ContentKR"] = "며칠 전에 진짜 얄미운 녀석을 만났어... 한 귀족의 저택에서 일하는 관리인 같던데, 식량보급원인 우릴 찾아와서 견과류를 사겠다고 하더라고.",
            ["DialogueId"] = 80060207,
            ["FacialId"] = {
                [1] = "95101:Unacceptable01",
                },
            ["GUID"] = "C86C1DB6",
            ["NextDialogue"] = 80060208,
            ["SpeakNpcId"] = 95101,
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/002/C86C1DB6",
            },
        [80060208] = {
            ["Content"] = "他让仆人带了整整七个麻袋，这能让我们赚好多好多钱呢！",
            ["ContentKR"] = "그 사람은 일곱 자루나 사겠다고 했고, 주문서에는 엄청나게 큰 금액의 수고비도 적혀 있었어!",
            ["DialogueId"] = 80060208,
            ["GUID"] = "C86C1DE0",
            ["NextDialogue"] = 80060209,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/002/C86C1DE0",
            },
        [80060209] = {
            ["Content"] = "司祭姐姐说啦：“有钱不赚，公鸡下蛋！” 所以我和榛子忙活了整整一天呢。",
            ["ContentKR"] = "사제 언니가 전에 돈을 벌 수 있는 기회를 날리면 바보라고 했었거든. 그래서 나와 헤이즐넛은 이 주문을 위해 종일 바쁘게 일했어.",
            ["DialogueId"] = 80060209,
            ["FacialId"] = {
                [1] = "95101:None",
                },
            ["GUID"] = "C86C1E0A",
            ["NextOptions"] = {
                [1] = 80060210,
                },
            ["SpeakNpcId"] = 95101,
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/002/C86C1E0A",
            },
        [80060210] = {
            ["Content"] = "难道他收了东西却不给钱？",
            ["ContentKR"] = "설마 물건만 가져가고 돈을 안 준 거야?",
            ["DialogueId"] = 80060210,
            ["GUID"] = "C86C1E34",
            ["NextDialogue"] = 80060211,
            },
        [80060211] = {
            ["Content"] = "正好相反，他不仅给足了钱，还因为我们干活快，给了额外的报酬。本来是件好得不能再好的事啦——",
            ["ContentKR"] = "그 반대야. 돈은 충분히 받았어. 심지어 우리가 일을 빨리 해결했다고 더 많이 챙겨주셨지. 이보다 더 좋을 수가 없는데...",
            ["DialogueId"] = 80060211,
            ["FacialId"] = {
                [1] = "95101:Sad01",
                },
            ["GUID"] = "C86C1E5E",
            ["NextDialogue"] = 80060212,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/002/C86C1E5E",
            },
        [80060212] = {
            ["Content"] = "但偏偏我眼尖，他们临走的时候，我看见管家从麻袋里挑出了好几个新鲜的扭扭果扔掉了。",
            ["ContentKR"] = "그 사람들이 떠날 때, 하필 그 관리인이 자루에서 신선한 매듭 열매를 여러 개 골라 버리는 걸 내가 봐버렸지 뭐야.",
            ["DialogueId"] = 80060212,
            ["GUID"] = "C86C1E88",
            ["NextDialogue"] = 80060213,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_Talk02R_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/002/C86C1E88",
            },
        [80060213] = {
            ["Content"] = "我赶紧拦住他，告诉他，这都是很好吃很好吃的坚果，扭扭果天生就长了一层白绒绒，并不是发霉！",
            ["ContentKR"] = "내가 재빨리 가서 그 사람한테 버리지 말라고, 또 매듭 열매는 맛있는 견과류고 그 위에 난 하얀 털은 곰팡이가 아니라고도 말해줬거든.",
            ["DialogueId"] = 80060213,
            ["GUID"] = "C86C1EB2",
            ["NextDialogue"] = 80060214,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_Talk02R_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/002/C86C1EB2",
            },
        [80060214] = {
            ["Content"] = "结果你猜猜他说什么——他说他知道这些不是坏掉的坚果，只是榨不出什么油水，所以才扔掉了！",
            ["ContentKR"] = "그랬더니 그 사람이... 상한 걸 버린 게 아니라, 기름을 짤 수 없는 걸 골라 버린 거라고 하는 거 있지?",
            ["DialogueId"] = 80060214,
            ["FacialId"] = {
                [1] = "95101:Unacceptable01",
                },
            ["GUID"] = "C86C1EDC",
            ["NextOptions"] = {
                [1] = 80060215,
                },
            ["SpeakNpcId"] = 95101,
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/002/C86C1EDC",
            },
        [80060215] = {
            ["Content"] = "榨油水……？",
            ["ContentKR"] = "기름을 짠다고...?",
            ["DialogueId"] = 80060215,
            ["GUID"] = "C86C1F06",
            ["NextDialogue"] = 80060216,
            },
        [80060216] = {
            ["Content"] = "是呀，他们要这——么多的坚果根本不是用来吃的！说出来气死你！",
            ["ContentKR"] = "맞아. 그러니까 그 사람들은 먹기 위해 그렇게 많은 견과류를 산 게 아니었어! 너무 화가 나!",
            ["DialogueId"] = 80060216,
            ["FacialId"] = {
                [1] = "95101:None",
                },
            ["GUID"] = "C86C1F30",
            ["NextDialogue"] = 80060217,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/002/C86C1F30",
            },
        [80060217] = {
            ["Content"] = "他说他的雇主这家人，每天都要用煮好的牛奶泡澡，牛奶要挑牧场里最壮实的奶牛产的！",
            ["ContentKR"] = "또 자신이 모시는 사람은 매일 목욕할 때 따뜻한 우유를 사용하는데, 우유도 목장에서 제일 튼튼한 젖소가 짠 우유만 쓴다는 거야!",
            ["DialogueId"] = 80060217,
            ["FacialId"] = {
                [1] = "95101:Unacceptable01",
                },
            ["GUID"] = "C86C1F5A",
            ["NextDialogue"] = 80060218,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/002/C86C1F5A",
            },
        [80060218] = {
            ["Content"] = "不仅如此，他们还要在泡澡的牛奶里加新鲜的香料，之前用的是花圃的郁金香花瓣制成的香薰，现在又要用坚果做精油啦！",
            ["ContentKR"] = "이게 다가 아니야. 심지어 그 목욕용 우유에 넣는 신선한 향료도 전에는 꽃밭의 튤립 꽃잎으로 만든 아로마를 사용했었다고 하더라고. 그리고 이제는 견과류로 만든 오일을 사용하려 한다는 거 있지?!",
            ["DialogueId"] = 80060218,
            ["GUID"] = "C86C1F84",
            ["NextDialogue"] = 80060219,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/002/C86C1F84",
            },
        [80060219] = {
            ["Content"] = "至于那些不能用来榨油的坚果，他们竟然全都要扔进垃圾桶。",
            ["ContentKR"] = "그것 때문에 기름을 짤 수 없는 견과류는 모조리 버릴 거래.",
            ["DialogueId"] = 80060219,
            ["FacialId"] = {
                [1] = "95101:Sad01",
                },
            ["GUID"] = "C86C1FAE",
            ["NextOptions"] = {
                [1] = 80060220,
                [2] = 80060222,
                },
            ["SpeakNpcId"] = 95101,
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/002/C86C1FAE",
            },
        [80060220] = {
            ["Content"] = "好浪费啊……",
            ["ContentKR"] = "너무 아깝다...",
            ["DialogueId"] = 80060220,
            ["GUID"] = "C86C1FD8",
            ["NextDialogue"] = 80060221,
            },
        [80060221] = {
            ["Content"] = "就是嘛，就算我看得下去，榛子也肯定不会同意的！",
            ["ContentKR"] = "그러니까 말이야. 나는 몰라도 헤이즐넛은 절대 동의하지 못할 거야!",
            ["DialogueId"] = 80060221,
            ["FacialId"] = {
                [1] = "95101:None",
                },
            ["GUID"] = "C86C2002",
            ["NextDialogue"] = 80060224,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/002/C86C2002",
            },
        [80060222] = {
            ["Content"] = "好羡慕啊……",
            ["ContentKR"] = "부럽다...",
            ["DialogueId"] = 80060222,
            ["GUID"] = "C86C202C",
            ["NextDialogue"] = 80060223,
            },
        [80060223] = {
            ["Content"] = "啊，不可以羡慕他！教典里说过，浪费粮食是很大的罪恶！他一定会倒大霉的！",
            ["ContentKR"] = "뭐? 부러워하면 어떡해! 음식을 낭비하는 건 큰 죄라고 했어! 그렇게 하다가는 분명 큰 벌을 받을 거야!",
            ["DialogueId"] = 80060223,
            ["FacialId"] = {
                [1] = "95101:Confident01",
                },
            ["GUID"] = "C86C2056",
            ["NextDialogue"] = 80060224,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/002/C86C2056",
            },
        [80060224] = {
            ["Content"] = "我把那家伙给的银币丢还给了他，抢回了我的坚果。我才不能看着他们把坚果浪费掉！在神明大人的种种教诲中，最不可饶恕的罪过就是浪费！",
            ["ContentKR"] = "그래서 나는 그 사람이 준 실버를 돌려주고 견과류를 되찾아왔어. 견과류를 낭비하는 걸 두고 볼 수는 없었거든! 신의 가르침에서 낭비는 가장 용서받을 수 없는 죄라고 했어.",
            ["DialogueId"] = 80060224,
            ["GUID"] = "C86C2080",
            ["NextOptions"] = {
                [1] = 80060225,
                [2] = 80060227,
                },
            ["SpeakNpcId"] = 95101,
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/002/C86C2080",
            },
        [80060225] = {
            ["Content"] = "松露说得对，挥霍食物确实很不应该。",
            ["ContentKR"] = "트러플 말이 맞아. 음식을 낭비하는 건 잘못된 행동이야.",
            ["DialogueId"] = 80060225,
            ["GUID"] = "C86C20AA",
            ["NextDialogue"] = 80060226,
            },
        [80060226] = {
            ["Content"] = "对吧对吧！浪费一份食物，就多一个吃不饱的人。哪怕多一个也不行！",
            ["ContentKR"] = "그렇지? 음식을 낭비하면 그만큼 배고픔에 시달리는 사람이 늘어나. 그런 일이 더 늘어나는 건 용납할 수 없어!",
            ["DialogueId"] = 80060226,
            ["FacialId"] = {
                [1] = "95101:None",
                },
            ["GUID"] = "C86C20D4",
            ["NextDialogue"] = 80060231,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/002/C86C20D4",
            },
        [80060227] = {
            ["Content"] = "既然是付了钱的，怎么处置也是他们的自由……",
            ["ContentKR"] = "그런데 돈을 지불했다면, 어떻게 사용하는지는 그들의 자유가 아닐까...",
            ["DialogueId"] = 80060227,
            ["GUID"] = "C86C20FE",
            ["NextDialogue"] = 80060228,
            },
        [80060228] = {
            ["Content"] = "啊……？神明不是这么说的……唔，可是你说的好像也有道理……但我还是觉得好像哪儿不对劲——",
            ["ContentKR"] = "어...? 신은 그렇게 말하지 않았어... 음, 근데 네 말도 일리가 있는 것 같은데... 어쨌든 난 좀 찝찝했어...",
            ["DialogueId"] = 80060228,
            ["GUID"] = "C86C2128",
            ["NextDialogue"] = 80060229,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/002/C86C2128",
            },
        [80060229] = {
            ["Content"] = "呜，好麻烦，不想了。",
            ["ContentKR"] = "아, 복잡해. 그만 생각할래. 그 사람에게 음식을 마음대로 할 자유가 있다면, 내게도 판매하지 않을 자유가 있어!",
            ["DialogueId"] = 80060229,
            ["FacialId"] = {
                [1] = "95101:Confident01",
                },
            ["GUID"] = "C86C2152",
            ["NextDialogue"] = 80060230,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/002/C86C2152",
            },
        [80060230] = {
            ["Content"] = "要是这些不为食物发愁的家伙们也能知道，在他们看不到的地方有好些人还饿着肚子就好了。",
            ["ContentKR"] = "태어날 때부터 음식이 부족한 적 없이 자란 사람들이 보이지 않는 곳에는 여전히 굶주리는 사람들이 많다는 사실을 알았으면 좋겠어.",
            ["DialogueId"] = 80060230,
            ["FacialId"] = {
                [1] = "95101:None",
                },
            ["GUID"] = "C86C217C",
            ["NextDialogue"] = 80060231,
            ["SpeakNpcId"] = 95101,
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/002/C86C217C",
            },
        [80060231] = {
            ["Content"] = "最后，虽然到手的银币丢了，被司祭姐姐唠叨了好久，但我还是把那些坚果都分给了穷人。",
            ["ContentKR"] = "결국 실버도 못 벌고 사제 언니한테도 한소리 들었지만, 그래도 나는 그 견과류를 가난한 사람들에게 나눠주었어.",
            ["DialogueId"] = 80060231,
            ["FacialId"] = {
                [1] = "95101:Happy02",
                },
            ["GUID"] = "C86C21A6",
            ["NextDialogue"] = 80060232,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/002/C86C21A6",
            },
        [80060232] = {
            ["Content"] = "我知道饿肚子是什么感觉，一点也不好受！……我再也不要饿肚子了，也不想看其他人饿肚子。",
            ["ContentKR"] = "나는 배고픈 게 어떤 건지 알거든, 정말 너무 고통스럽다고! ...더 이상 경험하고 싶지 않아. 다른 사람이 굶주린 것도 보고 싶지 않고.",
            ["DialogueId"] = 80060232,
            ["FacialId"] = {
                [1] = "95101:None",
                },
            ["GUID"] = "C86C21D0",
            ["NextOptions"] = {
                [1] = 80060233,
                },
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/002/C86C21D0",
            },
        [80060233] = {
            ["Content"] = "松露是个善良的孩子。",
            ["ContentKR"] = "트러플은 정말로 착한 아이네.",
            ["DialogueId"] = 80060233,
            ["GUID"] = "C86C21FA",
            ["NextDialogue"] = 80060234,
            },
        [80060234] = {
            ["Content"] = "唉……总感觉距离完成我和榛子——“让世界上所有人都吃饱”的梦想还有好远、好远的路啊。",
            ["ContentKR"] = "휴, 나와 헤이즐넛이 품은 '모두가 배불리 먹을 수 있는 세상'이라는 꿈을 이루려면 아직 갈 길이 먼 것 같아.",
            ["DialogueId"] = 80060234,
            ["FacialId"] = {
                [1] = "95101:Sad01",
                },
            ["GUID"] = "C86C2224",
            ["NextDialogue"] = 80060235,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/002/C86C2224",
            },
        [80060235] = {
            ["Content"] = "嗯——不能再等啦！我和榛子现在就去筹备粮食！改天再来找你玩，你要记得多吃饭哦！",
            ["ContentKR"] = "휴, 더는 안 되겠어! 헤이즐넛과 지금 당장 식량을 모으러 가야겠어! 다음에 또 올게. 너도 밥 잘 챙겨 먹고!",
            ["DialogueId"] = 80060235,
            ["FacialId"] = {
                [1] = "95101:Smile02",
                },
            ["GUID"] = "C86C224E",
            ["SpeakNpcId"] = 95101,
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/002/C86C224E",
            },
        [80060301] = {
            ["Camera"] = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
            ["Content"] = "嘿嘿，这个季节的北风莓汁果然是最香的，一点也不酸，甜滋滋的，真好喝！",
            ["ContentKR"] = "헤헤, 지금 계절에는 역시 아이스베리 주스가 최고야. 하나도 시지 않고, 달콤해서 정말 맛있어!",
            ["DialogueId"] = 80060301,
            ["FacialId"] = {
                [1] = "95101:Smile02",
                },
            ["GUID"] = "C86C2D22",
            ["LookAt"] = {
                [1] = "95101:p(18000P3)",
                },
            ["NextOptions"] = {
                [1] = 80060302,
                },
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/003/C86C2D22",
            },
        [80060302] = {
            ["Content"] = "你喜欢就好。",
            ["ContentKR"] = "마음에 들어서 다행이네.",
            ["DialogueId"] = 80060302,
            ["GUID"] = "C86C2D4C",
            ["NextDialogue"] = 80060303,
            },
        [80060303] = {
            ["Content"] = "可以把配方也分我一份吗？榛子要是能尝到一定会开心地跳起来！",
            ["ContentKR"] = "혹시 레시피를 알려줄 수 있어? 헤이즐넛도 맛본다면 기뻐서 폴짝 뛸 거야!",
            ["DialogueId"] = 80060303,
            ["FacialId"] = {
                [1] = "95101:Satisfy01",
                },
            ["GUID"] = "C86C2D76",
            ["NextOptions"] = {
                [1] = 80060304,
                },
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_Talk02R_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/003/C86C2D76",
            },
        [80060304] = {
            ["Content"] = "当然可以。",
            ["ContentKR"] = "물론이지.",
            ["DialogueId"] = 80060304,
            ["GUID"] = "C86C2DA0",
            ["NextDialogue"] = 80060305,
            },
        [80060305] = {
            ["Content"] = "谢谢你！你真是个至诚至善、亲厚什么良什么——反正就是经文里说的大大大大好人！",
            ["ContentKR"] = "고마워! 넌 정말 최고로, 성실하고 자상하고 뭐더라... 아무튼 경전에서 말하는 아주 아주 좋은 사람이야!",
            ["DialogueId"] = 80060305,
            ["FacialId"] = {
                [1] = "95101:Happy02",
                },
            ["GUID"] = "C86C2DCA",
            ["NextDialogue"] = 80060306,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/003/C86C2DCA",
            },
        [80060306] = {
            ["Content"] = "我们以前也经常去摘北风莓，只要轻轻扭一扭，莓子就落到手心啦。我每次都会摘满满几大篮，榛子驮回去的时候也好开心。",
            ["ContentKR"] = "우리도 자주 아이스베리를 따러 갔어. 살짝 비틀면 쉽게 톡 딸 수 있잖아. 매번 바구니 여러 개를 가득 채워 돌아가면 헤이즐넛도 좋아했었어.",
            ["DialogueId"] = 80060306,
            ["FacialId"] = {
                [1] = "95101:Smile02",
                },
            ["GUID"] = "C86C2DF4",
            ["NextDialogue"] = 80060307,
            ["SpeakNpcId"] = 95101,
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/003/C86C2DF4",
            },
        [80060307] = {
            ["Content"] = "有一次吃了太多莓子，我和榛子的舌头和嘴巴都被染成紫色的了，在小河边怎么洗都洗不干净。",
            ["ContentKR"] = "한 번은 베리를 너무 많이 먹어서 그런지 나랑 헤이즐넛의 혀와 입이 전부 보라색으로 변한 적도 있거든. 아무리 헹궈도 지워지지 않더라고.",
            ["DialogueId"] = 80060307,
            ["GUID"] = "C86C2E1E",
            ["NextDialogue"] = 80060308,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/003/C86C2E1E",
            },
        [80060308] = {
            ["Content"] = "榛子一着急就跳进河里，结果被石头下的溪蟹夹住了脚，痛得直哼哼。我当时想也不想冲进河里救榛子啦，没想到石头下面还有一只大溪蟹……",
            ["ContentKR"] = "헤이즐넛이 당황했는지 강에 뛰어들어서 씻는데, 바위 밑에 있던 게에 발을 물려서 아파하길래 나도 도와주려고 강에 뛰어들었는데 바위 밑에 큰 게가 한 마리 더 있더라니까...",
            ["DialogueId"] = 80060308,
            ["FacialId"] = {
                [1] = "95101:None",
                },
            ["GUID"] = "C86C2E48",
            ["NextDialogue"] = 80060309,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/003/C86C2E48",
            },
        [80060309] = {
            ["Content"] = "最后我们两个身上都湿哒哒的，只能一瘸一拐地花着脸回去。麦格芬司祭一边给我们包扎，一边板起脸来教训我们。",
            ["ContentKR"] = "그날 쫄딱 젖은 우리는 절뚝거리면서 돌아갔는데, 매그핀 사제님께 치료받으면서 얼마나 혼났는지 몰라.",
            ["DialogueId"] = 80060309,
            ["GUID"] = "C86C2E72",
            ["NextDialogue"] = 80060310,
            ["SpeakNpcId"] = 95101,
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/003/C86C2E72",
            },
        [80060310] = {
            ["Content"] = "从那以后榛子每次路过浆果丛的时候，都会眼巴巴地看着，但再也不敢吃北风莓了。",
            ["ContentKR"] = "헤이즐넛은 그 후로 베리 숲을 지나도 쳐다보기만 하고, 아이스베리를 먹을 엄두는 내지 못하고 있어.",
            ["DialogueId"] = 80060310,
            ["FacialId"] = {
                [1] = "95101:Smile02",
                },
            ["GUID"] = "C86C2E9C",
            ["NextOptions"] = {
                [1] = 80060311,
                },
            ["SpeakNpcId"] = 95101,
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/003/C86C2E9C",
            },
        [80060311] = {
            ["Content"] = "那位麦格芬司祭……你们很怕她？",
            ["ContentKR"] = "그 매그핀 사제라는 분 말이야... 엄청 무서운 분이야?",
            ["DialogueId"] = 80060311,
            ["GUID"] = "C86C2EC6",
            ["NextDialogue"] = 80060312,
            },
        [80060312] = {
            ["Content"] = "我还好！但是榛子每次看到她都会瑟瑟发抖，大概是她一开始总是吓唬榛子，说要赶它出门吧。",
            ["ContentKR"] = "난 괜찮아! 근데 헤이즐넛은 그분을 볼 때마다 덜덜 떨어. 아마도 전에 자꾸 쫓아내겠다고 겁을 줘서 그런 것 같아.",
            ["DialogueId"] = 80060312,
            ["FacialId"] = {
                [1] = "95101:Iyada01",
                },
            ["GUID"] = "C86C2EF0",
            ["NextDialogue"] = 80060313,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/003/C86C2EF0",
            },
        [80060313] = {
            ["Content"] = "麦格芬司祭刚收养我的时候，总是担心榛子饭量太大，会吃掉很多很多口粮，害得大家没饭吃。",
            ["ContentKR"] = "매그핀 사제님께서 나를 처음 거두어주셨을 때, 헤이즐넛이 너무 많이 먹어서 식량이 부족할까 봐 걱정하셨거든.",
            ["DialogueId"] = 80060313,
            ["GUID"] = "C86C2F1A",
            ["NextDialogue"] = 80060340,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_Talk02R_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/003/C86C2F1A",
            },
        [80060314] = {
            ["Content"] = "后来麦格芬司祭虽然答应留下榛子，但还是经常抱怨榛子不够酷，像这样——",
            ["ContentKR"] = "그 후 매그핀 사제님께서는 헤이즐넛을 쫓아내지 않겠다고 약속하셨어. 하지만 맨날 헤이즐넛이 멋지지 않다고 투덜거리더라고. 예를 들자면...",
            ["DialogueId"] = 80060314,
            ["GUID"] = "C86C2F44",
            ["NextDialogue"] = 80060315,
            ["SpeakNpcId"] = 95101,
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/003/C86C2F44",
            },
        [80060315] = {
            ["Content"] = "“小松露啊，你看这本小说，海伯利亚人写的，讲的是勇者和龙交朋友的故事。怎么人家的动物伙伴都那么帅气，咱们却只能带着头猪？”",
            ["ContentKR"] = "\"트러플, 이 소설 좀 보렴. 용사와 용이 서로의 친구가 된 이야기의 휘페르보레아 제국 소설이란다. 다른 사람들의 동물 친구는 모두 멋진데, 왜 우리는 하필 돼지일까?\"라고 하신 적도 있어.",
            ["DialogueId"] = 80060315,
            ["GUID"] = "C86C2F6E",
            ["NextDialogue"] = 80060316,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/003/C86C2F6E",
            },
        [80060316] = {
            ["Content"] = "“还有这本，华胥人写的，虽然人家也带了猪……但人家的猪好歹是个天堂来的将军，还能帮忙打打怪物，咱们这个……真就没点儿特异功能什么的？”",
            ["ContentKR"] = "\"그리고 화서인이 쓴 이 책에도 돼지가 등장하지만... 그 돼지는 하늘에서 내려온 장군이라 괴물도 처치할 수 있어. 그런데 우리 돼지는... 무슨 특별한 능력이 없을까?\"",
            ["DialogueId"] = 80060316,
            ["GUID"] = "C86C2F98",
            ["NextOptions"] = {
                [1] = 80060317,
                [2] = 80060319,
                [3] = 80060320,
                },
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/003/C86C2F98",
            },
        [80060317] = {
            ["Content"] = "她说得对，你应该找个更酷的同伴。",
            ["ContentKR"] = "맞는 말이네. 너에게는 더 멋진 동료가 필요해.",
            ["DialogueId"] = 80060317,
            ["GUID"] = "C86C2FC2",
            ["NextDialogue"] = 80060318,
            },
        [80060318] = {
            ["Content"] = "不行，不行！我怎么可以抛下榛子呢！",
            ["ContentKR"] = "안돼, 안돼! 난 헤이즐넛과 떨어질 수 없어!",
            ["DialogueId"] = 80060318,
            ["FacialId"] = {
                [1] = "95101:Shock01",
                },
            ["GUID"] = "C86C2FEC",
            ["NextOptions"] = {
                [1] = 80060322,
                },
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/003/C86C2FEC",
            },
        [80060319] = {
            ["Content"] = "不，榛子是无可取代的。",
            ["ContentKR"] = "이런, 어느 것도 헤이즐넛을 대체할 수 없지.",
            ["DialogueId"] = 80060319,
            ["GUID"] = "C86C3016",
            ["NextDialogue"] = 80060321,
            },
        [80060320] = {
            ["Content"] = "真没品位！骑猪多酷啊！",
            ["ContentKR"] = "진짜 뭘 모르네! 돼지를 타고 다니는 게 얼마나 멋있는데!",
            ["DialogueId"] = 80060320,
            ["GUID"] = "C86C3040",
            ["NextDialogue"] = 80060321,
            },
        [80060321] = {
            ["Content"] = "哇，你也这么觉得呀——你真好，生命之神，丰饶之神，北风莓之神，遁地土豆之神……总之什么神都会祝福你的！",
            ["ContentKR"] = "와, 너도 그렇게 생각하는구나! 넌 최고야, 생명의 신, 풍요의 신, 아이스베리의 신, 감자의 신... 아무튼 어떤 신이든간에 다 너에게 축복을 내릴 거야!",
            ["DialogueId"] = 80060321,
            ["FacialId"] = {
                [1] = "95101:Happy02",
                },
            ["GUID"] = "C86C306A",
            ["NextOptions"] = {
                [1] = 80060322,
                },
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/003/C86C306A",
            },
        [80060322] = {
            ["Content"] = "松露真的很喜欢榛子呢，它一定很特别。",
            ["ContentKR"] = "트러플은 헤이즐넛을 정말로 아끼는구나. 엄청 특별한 마령인 것 같네.",
            ["DialogueId"] = 80060322,
            ["GUID"] = "C86C3094",
            ["NextDialogue"] = 80060323,
            },
        [80060323] = {
            ["Content"] = "特别？是这样没错啦，不过我想知道，{nickname}为什么也这么觉得呢？",
            ["ContentKR"] = "특별한 돼지? 맞아. 그런데 {nickname}, 너는 왜 그렇게 생각하게 된 거야?",
            ["DialogueId"] = 80060323,
            ["FacialId"] = {
                [1] = "95101:None",
                },
            ["GUID"] = "C86C30BE",
            ["NextOptions"] = {
                [1] = 80060324,
                [2] = 80060326,
                },
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/003/C86C30BE",
            },
        [80060324] = {
            ["Content"] = "榛子跑得很快。",
            ["ContentKR"] = "헤이즐넛은 엄청나게 빨리 달릴 수 있잖아.",
            ["DialogueId"] = 80060324,
            ["GUID"] = "C86C30E8",
            ["NextDialogue"] = 80060325,
            },
        [80060325] = {
            ["Content"] = "其实很多魔灵都可以跑得很快的，好多真正的猪也能做到，榛子的速度还远远排不上号呢。",
            ["ContentKR"] = "사실 많은 마령들이 꽤 빠르게 달릴 수 있어, 진짜 돼지도 마찬가지고. 그들과 비교하면 헤이즐넛은 한참 부족한걸.",
            ["DialogueId"] = 80060325,
            ["FacialId"] = {
                [1] = "95101:Smile01",
                },
            ["GUID"] = "C86C3112",
            ["NextDialogue"] = 80060328,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/003/C86C3112",
            },
        [80060326] = {
            ["Content"] = "榛子会寻找食物。",
            ["ContentKR"] = "헤이즐넛은 먹을 걸 찾아오잖아.",
            ["DialogueId"] = 80060326,
            ["GUID"] = "C86C313C",
            ["NextDialogue"] = 80060327,
            },
        [80060327] = {
            ["Content"] = "榛子是依靠它的鼻子去找红蕈，其实呢，很多魔灵的鼻子都很好用，好好拜托它们的话，它们也可以帮你找食物的。",
            ["ContentKR"] = "헤이즐넛은 후각을 통해 붉은 버섯을 찾을 수 있어. 사실 대부분 마령들의 후각도 엄청나거든. 그들한테 잘 부탁하면, 너를 위해 먹을 걸 찾아다 줄 수도 있을 거야.",
            ["DialogueId"] = 80060327,
            ["FacialId"] = {
                [1] = "95101:Smile01",
                },
            ["GUID"] = "C86C3166",
            ["NextDialogue"] = 80060328,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/003/C86C3166",
            },
        [80060328] = {
            ["Content"] = "其实，这个问题我认真想过的，从麦格芬司祭问我的时候，我就开始问自己了。",
            ["ContentKR"] = "사실 이 문제에 대해 나는 진지하게 생각해 본 적 있어. 매그핀 사제님이 물었을 때부터 스스로에게 묻기 시작했거든.",
            ["DialogueId"] = 80060328,
            ["GUID"] = "C86C3190",
            ["NextDialogue"] = 80060329,
            ["SpeakNpcId"] = 95101,
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/003/C86C3190",
            },
        [80060329] = {
            ["Content"] = "世界上有那么多魔灵，帅气的，可爱的……为什么我的同伴非榛子不可呢？",
            ["ContentKR"] = "세상에 마령이 그렇게 많고, 멋진 것도 있고, 귀여운 것도 있는데... 왜 나의 동료는 꼭 헤이즐넛이어야 할까?",
            ["DialogueId"] = 80060329,
            ["GUID"] = "C86C31BA",
            ["NextDialogue"] = 80060330,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/003/C86C31BA",
            },
        [80060330] = {
            ["Content"] = "不过我只想了一晚上。等第二天榛子用鼻子蹭我的脸叫我起床的时候，我就想明白啦。",
            ["ContentKR"] = "하지만 그 생각은 하루로 끝났어. 다음 날 아침 헤이즐넛이 코로 내 얼굴을 비비며 날 깨웠을 때 질문의 답을 깨달았거든.",
            ["DialogueId"] = 80060330,
            ["FacialId"] = {
                [1] = "95101:Satisfy01",
                },
            ["GUID"] = "C86C31E4",
            ["NextDialogue"] = 80060331,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/003/C86C31E4",
            },
        [80060331] = {
            ["Content"] = "因为只有榛子……是我的榛子呀！一直以来，从厚厚的泥里挖红蕈、帮我驮着发给大家沉甸甸的食物、陪我一起教训坏蛋的是榛子……",
            ["ContentKR"] = "헤이즐넛은... 나의 헤이즐넛이니까! 항상 두꺼운 진흙 속에서 붉은 버섯을 캐고, 나를 도와 모두에게 나눠줄 무거운 음식도 나르고, 또 함께 악당들을 혼내준 건 늘 헤이즐넛이었으니까...",
            ["DialogueId"] = 80060331,
            ["FacialId"] = {
                [1] = "95101:Smile02",
                },
            ["GUID"] = "C86C320E",
            ["NextDialogue"] = 80060332,
            ["SpeakNpcId"] = 95101,
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/003/C86C320E",
            },
        [80060332] = {
            ["Content"] = "和我一起背根本记不住的教典、在我生病时安慰我、和我在清晨或者傍晚飞奔的也是榛子。",
            ["ContentKR"] = "내가 전혀 외우지 못하는 경전 구절을 함께 외우고, 아플 때 위로해 주고, 이른 아침부터 늦은 저녁까지 함께 뛰어다닌 것도 헤이즐넛이었어.",
            ["DialogueId"] = 80060332,
            ["GUID"] = "C86C3238",
            ["NextOptions"] = {
                [1] = 80060333,
                },
            ["SpeakNpcId"] = 95101,
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/003/C86C3238",
            },
        [80060333] = {
            ["Content"] = "因为一起经历过许许多多的小事，所以才是最特别的？",
            ["ContentKR"] = "함께 많은 일을 겪었으니까, 서로에게 가장 특별한 존재가 된 게 아닐까?",
            ["DialogueId"] = 80060333,
            ["GUID"] = "C86C3262",
            ["NextDialogue"] = 80060334,
            },
        [80060334] = {
            ["Content"] = "嗯！虽然很多人都觉得榛子不酷，虽然这个世界上还有很多魔灵比榛子跑得更快、长得更漂亮、挖的红蕈更多……哪怕榛子只是一只平平无奇的小猪……",
            ["ContentKR"] = "응! 사람들이 헤이즐넛이 멋지지 않다고 말해도, 헤이즐넛보다 더 빨리 달리고, 더 예쁘고, 붉은 버섯을 더 많이 캘 수 있는 마령이 있다고 해도... 또, 헤이즐넛이 그냥 평범한 돼지였어도...",
            ["DialogueId"] = 80060334,
            ["FacialId"] = {
                [1] = "95101:Happy01",
                },
            ["GUID"] = "C86C328C",
            ["NextDialogue"] = 80060335,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/003/C86C328C",
            },
        [80060335] = {
            ["Content"] = "榛子依然是全世界只有一个的榛子，是粮秣专员松露最好的伙伴！",
            ["ContentKR"] = "헤이즐넛은 나에게 유일한 존재야. 식량보급원 트러플의 최고의 동료지!",
            ["DialogueId"] = 80060335,
            ["GUID"] = "C86C32B6",
            ["NextOptions"] = {
                [1] = 80060336,
                },
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_Talk02R_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/003/C86C32B6",
            },
        [80060336] = {
            ["Content"] = "嗯，我记得。是“粮秣特别专员”。",
            ["ContentKR"] = "맞아, '특별 식량보급원'이라는 거 잊지 않았어.",
            ["DialogueId"] = 80060336,
            ["GUID"] = "C86C32E0",
            ["NextDialogue"] = 80060337,
            },
        [80060337] = {
            ["Content"] = "对！松露和榛子一起，赶跑饥饿——",
            ["ContentKR"] = "맞아! 트러플과 헤이즐넛은 함께 배고픔을 이겨낼 거야.",
            ["DialogueId"] = 80060337,
            ["GUID"] = "C86C330A",
            ["NextDialogue"] = 80060338,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_Talk02R_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/003/C86C330A",
            },
        [80060338] = {
            ["Content"] = "啊！我差点忘了，我今天还没把募集的粮食分发给大家……",
            ["ContentKR"] = "아! 깜빡할 뻔했다. 오늘 모은 식량을 아직 사람들에게 못 나눠줬잖아...",
            ["DialogueId"] = 80060338,
            ["FacialId"] = {
                [1] = "95101:Shock01",
                },
            ["GUID"] = "C86C3334",
            ["NextDialogue"] = 80060339,
            ["SpeakNpcId"] = 95101,
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/003/C86C3334",
            },
        [80060339] = {
            ["Content"] = "我得先走了，{nickname}，我们下次再见吧！",
            ["ContentKR"] = "난 먼저 가볼게. {nickname}, 다음에 또 보자!",
            ["DialogueId"] = 80060339,
            ["FacialId"] = {
                [1] = "95101:None",
                },
            ["GUID"] = "C86C335E",
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/003/C86C335E",
            },
        [80060340] = {
            ["Content"] = "但大家很快就发现了，榛子虽然长得像猪，但并没有猪猪那么大的食量，不会吃掉很多口粮的。",
            ["ContentKR"] = "하지만 다들 곧 알게 됐지, 헤이즐넛이 돼지처럼 보이지만 생각보다 많이 먹지 않았어.",
            ["DialogueId"] = 80060340,
            ["FacialId"] = {
                [1] = "95101:None",
                },
            ["GUID"] = "C86C2F1B",
            ["NextDialogue"] = 80060314,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_Talk02R_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/003/C86C2F1B",
            },
        [80060401] = {
            ["Camera"] = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
            ["Content"] = "{nickname}！那个……我有个很急很急的问题！你可以现在就回答我吗？",
            ["ContentKR"] = "{nickname}! 그게... 나 아주 급한 질문이 있어! 바로 대답해 줄 수 있을까?",
            ["DialogueId"] = 80060401,
            ["FacialId"] = {
                [1] = "95101:Smile02",
                },
            ["GUID"] = "C86C3D8A",
            ["LookAt"] = {
                [1] = "95101:p(18000P3)",
                },
            ["NextOptions"] = {
                [1] = 80060402,
                },
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/004/C86C3D8A",
            },
        [80060402] = {
            ["Content"] = "什么问题？",
            ["ContentKR"] = "어떤 질문인데?",
            ["DialogueId"] = 80060402,
            ["GUID"] = "C86C3DB4",
            ["NextDialogue"] = 80060403,
            },
        [80060403] = {
            ["Content"] = "我想问——如果你天天都能把肚子填饱的话！是不是就会很开心呀？",
            ["ContentKR"] = "그러니까... 매일 배불리 먹을 수 있다면 행복할 것 같아?",
            ["DialogueId"] = 80060403,
            ["GUID"] = "C86C3DDE",
            ["NextOptions"] = {
                [1] = 80060404,
                [2] = 80060405,
                },
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/004/C86C3DDE",
            },
        [80060404] = {
            ["Content"] = "当然啦。",
            ["ContentKR"] = "당연하지.",
            ["DialogueId"] = 80060404,
            ["GUID"] = "C86C3E08",
            ["NextDialogue"] = 80060406,
            },
        [80060405] = {
            ["Content"] = "不好说。",
            ["ContentKR"] = "글쎄.",
            ["DialogueId"] = 80060405,
            ["GUID"] = "C86C3E32",
            ["NextDialogue"] = 80060406,
            },
        [80060406] = {
            ["Content"] = "那下一个问题……对你来说，是不是只要能天天都把肚子填饱，就会很开心呀？",
            ["ContentKR"] = "그렇다면 다음 질문... 배불리 먹을 수만 있어도 행복할 수 있을 것 같아?",
            ["DialogueId"] = 80060406,
            ["FacialId"] = {
                [1] = "95101:Satisfy01",
                },
            ["GUID"] = "C86C3E5C",
            ["NextOptions"] = {
                [1] = 80060407,
                [2] = 80060409,
                },
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_Talk02R_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/004/C86C3E5C",
            },
        [80060407] = {
            ["Content"] = "是啊，都能吃饱了还能有什么不高兴？",
            ["ContentKR"] = "그렇지, 배가 불렀는데 왜 행복하지 않겠어.",
            ["DialogueId"] = 80060407,
            ["GUID"] = "C86C3E86",
            ["NextDialogue"] = 80060408,
            },
        [80060408] = {
            ["Content"] = "对嘛对嘛，吃饱是最最最重要的事啦。",
            ["ContentKR"] = "맞지 맞지! 먹는 게 제일 제일 중요하지.",
            ["DialogueId"] = 80060408,
            ["FacialId"] = {
                [1] = "95101:Smile02",
                },
            ["GUID"] = "C86C3EB0",
            ["NextDialogue"] = 80060411,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_Talk02R_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/004/C86C3EB0",
            },
        [80060409] = {
            ["Content"] = "也不是，让人烦心的事还有一大堆呢。",
            ["ContentKR"] = "그건 아닐 것 같아. 그 외에도 고민거리가 많으니까.",
            ["DialogueId"] = 80060409,
            ["GUID"] = "C86C3EDA",
            ["NextDialogue"] = 80060410,
            },
        [80060410] = {
            ["Content"] = "嗯？是这样吗？那我们好像有些不同喔。",
            ["ContentKR"] = "어라? 그래? 우리 생각이 좀 다른가봐.",
            ["DialogueId"] = 80060410,
            ["FacialId"] = {
                [1] = "95101:Smile02",
                },
            ["GUID"] = "C86C3F04",
            ["NextDialogue"] = 80060411,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_Talk02R_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/004/C86C3F04",
            },
        [80060411] = {
            ["Content"] = "对我来说，只要能天天吃得饱饱的就很开心啦。可我有两个朋友，他们和我完全不一样，把我搞得有点儿糊涂了。",
            ["ContentKR"] = "나는 말이야, 매일 배만 불러도 엄청나게 행복할 거야. 그런데 내 두 친구는 완전 달라서 좀 헷갈려.",
            ["DialogueId"] = 80060411,
            ["GUID"] = "C86C3F2E",
            ["NextDialogue"] = 80060412,
            ["SpeakNpcId"] = 95101,
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/004/C86C3F2E",
            },
        [80060412] = {
            ["Content"] = "一个是住在郊外的、富商家的姐姐，她家有好多亮晶晶的宝石，可以换好多好多银币，请很多厉害的厨师大叔给她做数不清的好吃的。",
            ["ContentKR"] = "한 명은 근교에 사는 언니인데, 부유한 상인 집안이라 집에 반짝거리는 보석이 가득해. 그래서 그것들을 많은 돈으로 바꿔서 유명한 쉐프가 만들어주는 산해진미를 먹을 수 있어.",
            ["DialogueId"] = 80060412,
            ["FacialId"] = {
                [1] = "95101:Doubt01",
                },
            ["GUID"] = "C86C3F58",
            ["NextDialogue"] = 80060413,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/004/C86C3F58",
            },
        [80060413] = {
            ["Content"] = "可是富商姐姐还是闷闷不乐的，司祭姐姐说，是因为她要去很远的地方，去一个她不喜欢的城市，和一个陌生人一起生活。",
            ["ContentKR"] = "그런데도 행복하지 않대. 사제 언니 말로는 그 언니가 자기가 싫어하는 도시로 가서 낯선 사람들이랑 같이 살아야 한다나봐.",
            ["DialogueId"] = 80060413,
            ["GUID"] = "C86C3F82",
            ["NextDialogue"] = 80060414,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/004/C86C3F82",
            },
        [80060414] = {
            ["Content"] = "还、还有另外一个朋友！他是传颂会里最最最虔诚的信徒啦，但是他却用一个月攒下的所有吃的，到圣堂交换一套新版的经卷。",
            ["ContentKR"] = "다, 다른 한 친구는! 교회의 가장 독실한 신자거든. 글쎄 한 달 동안 모은 음식으로 교회의 새 경전을 교환하더라고.",
            ["DialogueId"] = 80060414,
            ["FacialId"] = {
                [1] = "95101:None",
                },
            ["GUID"] = "C86C3FAC",
            ["NextDialogue"] = 80060415,
            ["SpeakNpcId"] = 95101,
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/004/C86C3FAC",
            },
        [80060415] = {
            ["Content"] = "唉，这难道不会饿肚子吗，他一直瘦瘦小小的，都快变成一片叶子被风吹走了！可他说，只要阅读着经卷，就能做到什么什么——“让灵魂吃饱”！",
            ["ContentKR"] = "설마 배가 고프지 않은 걸까? 그렇지만 너무 말라서 바람에 나뭇잎처럼 날아갈 것 같은데! 그런데도 그 친구는 경전을 읽으면... 아, '영혼의 배가 부르다'고 했어!",
            ["DialogueId"] = 80060415,
            ["GUID"] = "C86C3FD6",
            ["NextDialogue"] = 80060416,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/004/C86C3FD6",
            },
        [80060416] = {
            ["Content"] = "唔，我实在想不明白……为什么大家和我不一样？",
            ["ContentKR"] = "흠, 난 정말 이해가 안돼... 왜 나랑 다른 걸까?",
            ["DialogueId"] = 80060416,
            ["FacialId"] = {
                [1] = "95101:Iyada01",
                },
            ["GUID"] = "C86C4000",
            ["NextDialogue"] = 80060417,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/004/C86C4000",
            },
        [80060417] = {
            ["Content"] = "为什么有的人就算吃得饱饱的也不会快乐，为什么有的人就算吃都吃不饱也能感到幸福呢。",
            ["ContentKR"] = "왜 누군가는 배부르게 먹어도 행복하지 않고, 또 누군가는 배가 고픈데도 행복할 수 있는 걸까?",
            ["DialogueId"] = 80060417,
            ["GUID"] = "C86C402A",
            ["NextDialogue"] = 80060418,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/004/C86C402A",
            },
        [80060418] = {
            ["Content"] = "经文里神明大人说过，我们每个人都要努力给他人幸福……可是，到底要怎么做才能让大家都开开心心呢？",
            ["ContentKR"] = "경전 속 신의 말씀에 따르면 우리 모두 다른 사람에게 행복을 주기 위해 노력해야 한다고 했어... 그러면 어떻게 해야 모두가 행복해질 수 있을까?",
            ["DialogueId"] = 80060418,
            ["FacialId"] = {
                [1] = "95101:None",
                },
            ["GUID"] = "C86C4054",
            ["NextOptions"] = {
                [1] = 80060419,
                [2] = 80060420,
                },
            ["SpeakNpcId"] = 95101,
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/004/C86C4054",
            },
        [80060419] = {
            ["Content"] = "人心是最复杂的东西，没有两个人的想法完全一样。",
            ["ContentKR"] = "사람의 마음보다 복잡한 건 없어. 모든 사람의 생각이 같을 수는 없지.",
            ["DialogueId"] = 80060419,
            ["GUID"] = "C86C407E",
            ["NextDialogue"] = 80060421,
            },
        [80060420] = {
            ["Content"] = "你无法让所有人快乐，神是瞎说的，别信。",
            ["ContentKR"] = "너는 모든 사람을 행복하게 할 수 없어. 신이 멋대로 말한 거니 너무 마음에 담아두지 마.",
            ["DialogueId"] = 80060420,
            ["GUID"] = "C86C40A8",
            ["NextDialogue"] = 80060421,
            },
        [80060421] = {
            ["Content"] = "这是什么意思？我不太明白……",
            ["ContentKR"] = "그게 무슨 말이야? 못 알아듣겠어...",
            ["DialogueId"] = 80060421,
            ["FacialId"] = {
                [1] = "95101:Iyada01",
                },
            ["GUID"] = "C86C40D2",
            ["NextDialogue"] = 80060422,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/004/C86C40D2",
            },
        [80060422] = {
            ["Content"] = "大家难过了会哭鼻子，开心了会大声笑，生气了会发脾气，饿肚子了要吃东西，这不是很简单的道理嘛。",
            ["ContentKR"] = "슬프면 울고, 기쁘면 웃고, 화가 나면 화를 내고, 배고프면 음식을 먹고... 엄청 간단하잖아.",
            ["DialogueId"] = 80060422,
            ["FacialId"] = {
                [1] = "95101:None",
                },
            ["GUID"] = "C86C40FC",
            ["NextOptions"] = {
                [1] = 80060423,
                },
            ["SpeakNpcId"] = 95101,
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/004/C86C40FC",
            },
        [80060423] = {
            ["Content"] = "榛子很喜欢喝盐须菜汁，对吧？",
            ["ContentKR"] = "헤이즐넛은 고수 주스를 엄청 좋아하지?",
            ["DialogueId"] = 80060423,
            ["GUID"] = "C86C4126",
            ["NextDialogue"] = 80060424,
            },
        [80060424] = {
            ["Content"] = "是呀，司祭姐姐每天都会给榛子做新鲜的盐须菜汁！",
            ["ContentKR"] = "맞아, 사제 언니가 헤이즐넛을 위해 매일 신선한 고수 주스를 만들어줘!",
            ["DialogueId"] = 80060424,
            ["FacialId"] = {
                [1] = "95101:Smile02",
                },
            ["GUID"] = "C86C4150",
            ["NextOptions"] = {
                [1] = 80060425,
                },
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/004/C86C4150",
            },
        [80060425] = {
            ["Content"] = "那你喜欢盐须菜吗？",
            ["ContentKR"] = "그럼 너는 고수를 좋아해?",
            ["DialogueId"] = 80060425,
            ["GUID"] = "C86C417A",
            ["NextDialogue"] = 80060426,
            },
        [80060426] = {
            ["Content"] = "盐须菜的味道怪怪的，一进到嘴里舌根都苦了但又有股怪怪的香味，捏着鼻子吃的话也不是不行……哦，原来是这样！",
            ["ContentKR"] = "고수는 이상해. 맛도 쓰고, 또 이상한 향이 있어. 코를 막고 먹으면 먹을 수는 있겠지만... 아, 이런 거구나!",
            ["DialogueId"] = 80060426,
            ["FacialId"] = {
                [1] = "95101:Sad01",
                },
            ["GUID"] = "C86C41A4",
            ["NextDialogue"] = 80060427,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_Talk02R_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/004/C86C41A4",
            },
        [80060427] = {
            ["Content"] = "有的人喜欢榛仁露的味道，也有的人闻到榛仁露就要躲得远远的，榛子喜欢盐须菜，但我不喜欢……也就是说，让大家感到幸福的事情也是不一样的……",
            ["ContentKR"] = "누군가는 헤이즐넛 음료수를 좋아하지만, 또 누군가는 냄새만 맡아도 싫다고 해. 헤이즐넛은 고수를 좋아하지만, 나는 아니야... 그러니까, 사람마다 행복해지는 방법은 다 다른 거야...",
            ["DialogueId"] = 80060427,
            ["GUID"] = "C86C41CE",
            ["NextDialogue"] = 80060428,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_Talk02R_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/004/C86C41CE",
            },
        [80060428] = {
            ["Content"] = "我知道了，富商姐姐他们应该也是这样，或许有些东西要比吃得饱饱更令他们感到幸福快乐，所以连肚子饿都可以忍受啦。",
            ["ContentKR"] = "알겠어. 내 친구들은 배불리 먹는 게 아니라 다른 일을 통해 행복을 느낄 수 있는 거였어. 그러니 배고픔을 참을 수 있었던 거지.",
            ["DialogueId"] = 80060428,
            ["FacialId"] = {
                [1] = "95101:Unhappy01",
                },
            ["GUID"] = "C86C41F8",
            ["NextDialogue"] = 80060429,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/004/C86C41F8",
            },
        [80060429] = {
            ["Content"] = "那……我还能做什么呢？",
            ["ContentKR"] = "그럼... 내가 할 수 있는 일은 뭘까?",
            ["DialogueId"] = 80060429,
            ["FacialId"] = {
                [1] = "95101:None",
                },
            ["GUID"] = "C86C4222",
            ["NextOptions"] = {
                [1] = 80060430,
                [2] = 80060434,
                },
            ["SpeakNpcId"] = 95101,
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/004/C86C4222",
            },
        [80060430] = {
            ["Content"] = "你让很多人填饱肚子，已经很了不起了。",
            ["ContentKR"] = "많은 사람을 배부르게 했잖아. 그것만으로도 이미 충분히 대단한걸.",
            ["DialogueId"] = 80060430,
            ["GUID"] = "C86C424C",
            ["NextDialogue"] = 80060431,
            },
        [80060431] = {
            ["Content"] = "真的吗？我已经让很多人感到幸福了吗？",
            ["ContentKR"] = "진짜? 내가 이미 많은 사람이 행복하도록 도운 걸까?",
            ["DialogueId"] = 80060431,
            ["FacialId"] = {
                [1] = "95101:Shock01",
                },
            ["GUID"] = "C86C4276",
            ["NextDialogue"] = 80060432,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/004/C86C4276",
            },
        [80060432] = {
            ["Content"] = "是的。对很多人来说，吃饱不一定幸福，但如果吃不饱一定会不幸。",
            ["ContentKR"] = "응. 배가 부르다고 다 행복한 건 아니지만, 대부분의 사람은 배가 고프면 절대 행복할 수 없거든.",
            ["DialogueId"] = 80060432,
            ["FacialId"] = {
                [1] = "95101:None",
                },
            ["GUID"] = "C86C42A0",
            ["NextDialogue"] = 80060433,
            ["SpeakNpcId"] = 10001,
            ["TalkActionId"] = {
                [1] = "95101:Sit_Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/004/C86C42A0",
            },
        [80060433] = {
            ["Content"] = "谢谢你！你说话真好听！虽然今天摘果子的时候从树上掉下来摔了好大一跤，但听你这么说，我一点都不疼了！",
            ["ContentKR"] = "고마워! 큰 위로가 됐어! 오늘 열매를 따다 나무에서 떨어져서 엄청 아팠는데 네 말 듣고 나니까 하나도 안 아파!",
            ["DialogueId"] = 80060433,
            ["FacialId"] = {
                [1] = "95101:Happy02",
                },
            ["GUID"] = "C86C42CA",
            ["NextDialogue"] = 80060438,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/004/C86C42CA",
            },
        [80060434] = {
            ["Content"] = "你无法满足每个人，让自己开心就足够了。",
            ["ContentKR"] = "모두를 만족시킬 수 없어. 그러니 네가 하면 행복한 일을 찾아봐.",
            ["DialogueId"] = 80060434,
            ["GUID"] = "C86C42F4",
            ["NextDialogue"] = 80060435,
            },
        [80060435] = {
            ["Content"] = "我会开心的事？嗯，我想想……！",
            ["ContentKR"] = "내가 하면 행복한 일이라고? 음, 생각해 볼게...!",
            ["DialogueId"] = 80060435,
            ["GUID"] = "C86C431E",
            ["NextDialogue"] = 80060436,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/004/C86C431E",
            },
        [80060436] = {
            ["Content"] = "看大家吃饱饭会开心，司祭姐姐夸奖我、摸我头的时候会开心，榛子用鼻子蹭我的时候会开心，还有还有……和你坐在这里闲聊也很开心！",
            ["ContentKR"] = "다들 배부르게 먹으면 행복하고... 사제 언니가 칭찬하고 머리를 쓰다듬어 줄 때, 헤이즐넛이 나한테 코를 비빌 때, 그리고... 너와 이렇게 이야기를 나눌 때 행복해!",
            ["DialogueId"] = 80060436,
            ["FacialId"] = {
                [1] = "95101:Happy01",
                },
            ["GUID"] = "C86C4348",
            ["NextDialogue"] = 80060437,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/004/C86C4348",
            },
        [80060437] = {
            ["Content"] = "这么说的话……好像我只要像现在这样不变，就可以了？",
            ["ContentKR"] = "그렇다면... 나는 지금까지 하던 대로 하면 되는 거네?",
            ["DialogueId"] = 80060437,
            ["GUID"] = "C86C4372",
            ["NextDialogue"] = 80060438,
            ["SpeakNpcId"] = 95101,
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/004/C86C4372",
            },
        [80060438] = {
            ["Content"] = "…………",
            ["ContentKR"] = "......",
            ["DialogueId"] = 80060438,
            ["FacialId"] = {
                [1] = "95101:None",
                },
            ["GUID"] = "C86C439C",
            ["NextDialogue"] = 80060439,
            ["SpeakNpcId"] = 95101,
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/004/C86C439C",
            },
        [80060439] = {
            ["Content"] = "唉，你是个聪明人，松露是个笨蛋。如果连你也不知道让所有人开心的方式，那我肯定也找不到了。",
            ["ContentKR"] = "휴, 너처럼 똑똑한 사람도 모든 사람을 행복하게 만드는 방법을 모르는데, 나같은 바보는 분명 알아내지 못할 거야.",
            ["DialogueId"] = 80060439,
            ["FacialId"] = {
                [1] = "95101:Sad02",
                },
            ["GUID"] = "C86C43C6",
            ["NextDialogue"] = 80060440,
            ["SpeakNpcId"] = 95101,
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/004/C86C43C6",
            },
        [80060440] = {
            ["Content"] = "不过我已经决定了，继续当好粮秣专员！",
            ["ContentKR"] = "하지만 난 이미 결심했어. 계속 식량보급원의 일을 열심히 하기로!",
            ["DialogueId"] = 80060440,
            ["FacialId"] = {
                [1] = "95101:None",
                },
            ["GUID"] = "C86C43F0",
            ["NextDialogue"] = 80060441,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/004/C86C43F0",
            },
        [80060441] = {
            ["Content"] = "也许我不能让所有人都开心。但如果填饱肚子能让大家比现在开心一点点……只要一点点，我应该就没有辜负神明大人的教诲吧？",
            ["ContentKR"] = "모든 사람을 다 행복하게 만들 수는 없겠지. 하지만 사람들이 배불리 먹고 지금보다 조금이라도 더 행복할 수 있다면, 그게 아주 조금이라도... 신의 가르침을 잘 따른 게 아닐까?",
            ["DialogueId"] = 80060441,
            ["FacialId"] = {
                [1] = "95101:Smile02",
                },
            ["GUID"] = "C86C441A",
            ["NextOptions"] = {
                [1] = 80060442,
                },
            ["SpeakNpcId"] = 95101,
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/004/C86C441A",
            },
        [80060442] = {
            ["Content"] = "嗯，是很伟大的事业。",
            ["ContentKR"] = "응, 엄청 위대한 일이지.",
            ["DialogueId"] = 80060442,
            ["GUID"] = "C86C4444",
            ["NextDialogue"] = 80060443,
            },
        [80060443] = {
            ["Content"] = "嘿嘿……谢谢你！这个世界上有好多好多我搞不明白的事情哦。以后我有什么搞不懂的，就来找你，你还是会帮我解答吧？",
            ["ContentKR"] = "헤헤... 고마워! 이 세상에는 내가 아직 이해하지 못하는 일이 많은 것 같아. 앞으로 또 이해되지 않는 게 있으면 너한테 물어봐도 될까?",
            ["DialogueId"] = 80060443,
            ["GUID"] = "C86C446E",
            ["NextOptions"] = {
                [1] = 80060444,
                [2] = 80060446,
                },
            ["SpeakNpcId"] = 95101,
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/004/C86C446E",
            },
        [80060444] = {
            ["Content"] = "没问题。",
            ["ContentKR"] = "당연하지.",
            ["DialogueId"] = 80060444,
            ["GUID"] = "C86C4498",
            ["NextDialogue"] = 80060445,
            },
        [80060445] = {
            ["Content"] = "好耶！嗯，谢谢！",
            ["ContentKR"] = "너무 좋아!",
            ["DialogueId"] = 80060445,
            ["FacialId"] = {
                [1] = "95101:Happy02",
                },
            ["GUID"] = "C86C44C2",
            ["NextDialogue"] = 80060449,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/004/C86C44C2",
            },
        [80060446] = {
            ["Content"] = "一个问题一颗榛子。",
            ["ContentKR"] = "문제 하나에 헤이즐넛 하나야.",
            ["DialogueId"] = 80060446,
            ["GUID"] = "C86C44EC",
            ["NextDialogue"] = 80060447,
            },
        [80060447] = {
            ["Content"] = "啊，这个不行，榛子如果离开了我，会害怕的……",
            ["ContentKR"] = "아, 그건 안돼. 헤이즐넛이 내 곁에 없으면 무서울 것 같아...",
            ["DialogueId"] = 80060447,
            ["FacialId"] = {
                [1] = "95101:Shock01",
                },
            ["GUID"] = "C86C4516",
            ["NextDialogue"] = 80060448,
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/004/C86C4516",
            },
        [80060448] = {
            ["Content"] = "哦，原来你说的是吃的榛子啊——那没问题，我会给你带好多好多榛子，把你的肚皮塞得鼓鼓的！",
            ["ContentKR"] = "아, 먹는 헤이즐넛을 말하는 거였구나. 그거라면 좋아! 배 터질 때까지 먹을 헤이즐넛을 챙겨올게!",
            ["DialogueId"] = 80060448,
            ["FacialId"] = {
                [1] = "95101:Smile02",
                },
            ["GUID"] = "C86C4540",
            ["NextDialogue"] = 80060449,
            ["SpeakNpcId"] = 95101,
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/004/C86C4540",
            },
        [80060449] = {
            ["Content"] = "那么我们就说好啦。你也一起来见证松露和榛子的伟大事业——小拇指伸出来，我们拉钩！",
            ["ContentKR"] = "그러면 약속하자. 트러플과 헤이즐넛이 얼마나 위대한 일을 할지 기대하는 거야. 자, 새끼손가락 걸고 약속!",
            ["DialogueId"] = 80060449,
            ["FacialId"] = {
                [1] = "95101:Smile02",
                },
            ["GUID"] = "C86C456A",
            ["SpeakNpcId"] = 95101,
            ["TalkActionId"] = {
                [1] = "95101:Sit_Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Songlu/004/C86C456A",
            },
        [80070101] = {
            ["Camera"] = "-108.692429,383.760162,74.947266,0.000002,8.799756,-69.59346,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "西比尔军团长，您用过的那间办公室我收拾出来了。",
            ["ContentKR"] = "시빌라 군단장님, 사용하시던 사무실 정리를 완료했습니다.",
            ["DialogueId"] = 80070101,
            ["GUID"] = "C87274F2",
            ["NextDialogue"] = 80070102,
            ["SpeakNpcId"] = 790014,
            ["TalkActionId"] = {
                [1] = "790014:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/001/C87274F2",
            },
        [80070102] = {
            ["Content"] = "嗯，那是你晋升少校的奖励之一，之后就搬进那里办公吧。",
            ["ContentKR"] = "그래. 그곳은 소령으로 진급한 자네에게 주는 보상 중 하나다. 앞으로는 그 사무실을 사용하도록.",
            ["DialogueId"] = 80070102,
            ["GUID"] = "C872751C",
            ["NextDialogue"] = 80070103,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790014:Explain01_End",
                [2] = "790013:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/001/C872751C",
            },
        [80070103] = {
            ["Content"] = "这也是陛下的意思。你抓捕传颂会间谍、剿灭神弃者武装、歼灭大型秽兽的功绩他都看在眼里。",
            ["ContentKR"] = "그리고 이건 폐하의 뜻이기도 하다. 폐하께서는 네가 교회의 첩자를 잡은 것과 포세이큰의 무장을 무너뜨리는 것, 또 대형 필토이드를 섬멸한 것까지... 모두 지켜보셨다.",
            ["DialogueId"] = 80070103,
            ["GUID"] = "C8727546",
            ["LookAt"] = {
                [1] = "790013:n(790014)",
                },
            ["NextDialogue"] = 80070104,
            ["SpeakNpcId"] = 790013,
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/001/C8727546",
            },
        [80070104] = {
            ["Camera"] = "-27.108675,189.212509,103.496094,0.000003,3.399535,-80.992088,45.0,357.136719,false,Manual,9.443032",
            ["Content"] = "……全靠军团长的栽培。",
            ["ContentKR"] = "...군단장님의 지도 덕분입니다.",
            ["DialogueId"] = 80070104,
            ["GUID"] = "C8727570",
            ["LookAt"] = {
                [1] = "790013:n(790013)",
                },
            ["NextDialogue"] = 80070105,
            ["SpeakNpcId"] = 790014,
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/001/C8727570",
            },
        [80070105] = {
            ["Content"] = "省省吧，十三军团不需要阿谀奉承那一套，兰迪教你的东西你得思考着学，取舍着用。",
            ["ContentKR"] = "빈말은 됐다. 13군단에 아부 같은 건 필요하지 않아. 랜디가 가르쳐 준다고 다 그대로 쓸 필요는 없다.",
            ["DialogueId"] = 80070105,
            ["GUID"] = "C872759A",
            ["NextDialogue"] = 80070106,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/001/C872759A",
            },
        }
  end },
