        [80080123] = {
            ["Camera"] = "-330.722656,-239.585709,105.560547,0.000012,0.0,51.204865,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "…………",
            ["ContentKR"] = "......",
            ["DialogueId"] = 80080123,
            ["GUID"] = "C878E12E",
            ["LookAt"] = {
                [1] = "790004:n(790002)",
                [2] = "790003:n(790004)",
                [3] = "790002:n(790004)",
                [4] = "790001:n(790001)",
