            },
        [80080332] = {
            ["Camera"] = "-252.96875,-122.314819,187.210938,0.000079,-18.400009,32.607815,32.000004,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "自从认识了一个人，经历了一场冒险之后，我就变了。",
            ["ContentKR"] = "누군가를 알게 되고, 모험을 하고 나니... 달라진 것 같아요.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80080332,
            ["GUID"] = "C8790378",
            ["NextDialogue"] = 80080333,
            ["SpeakNpcId"] = 790004,
            ["TalkActionId"] = {
                [1] = "790004:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Saiqi/003/C8790378",
            },
        [80080333] = {
            ["Camera"] = "-252.96875,-122.314819,187.210938,0.000079,-18.400009,32.607815,32.000004,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "现在的我变贪心了许多许多……我开始渴望能再多一些时间，再多一些……",
            ["ContentKR"] = "이제 욕심이 생겼어요... 제게 더 많은 시간이 주어졌으면 좋겠고, 또...",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80080333,
            ["GUID"] = "C87903A2",
            ["NextDialogue"] = 80080334,
            ["SpeakNpcId"] = 790004,
            ["TalkActionId"] = {
                [1] = "790004:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Saiqi/003/C87903A2",
            },
        [80080334] = {
            ["Camera"] = "-252.96875,-122.314819,187.210938,0.000079,-18.400009,32.607815,32.000004,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我开始渴望可以牵起一个人的手，一起逃离冰湖城，到很远、很远的地方……",
            ["ContentKR"] = "누군가의 손을 붙잡고 아이스레이크 시티를 떠나 머나먼 곳으로 떠나고 싶어요...",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80080334,
            ["GUID"] = "C87903CC",
            ["NextDialogue"] = 80080335,
            ["SpeakNpcId"] = 790004,
            ["TalkActionId"] = {
                [1] = "790004:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Saiqi/003/C87903CC",
            },
        [80080335] = {
            ["Camera"] = "-178.794922,-57.247498,139.419922,0.000046,-6.999994,44.603405,32.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我开始渴望可以长到爸爸妈妈的年纪……可以变成满脸皱纹的老婆婆……可以坐在广场上，一边给鸟儿喂食，一边和城里的孩子们讲述年轻时的故事……",
            ["ContentKR"] = "부모님의 나이만큼 살고 싶다는 욕심이 생겼어요... 주름이 가득한 할머니가 되어서... 광장에 앉아 새에게 먹이를 주고, 성 안의 아이들에게 옛날이야기를 들려주고 싶어요...",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80080335,
            ["GUID"] = "C87903F6",
            ["NextDialogue"] = 80080336,
            ["SpeakNpcId"] = 790004,
            ["TalkActionId"] = {
                [1] = "790004:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Saiqi/003/C87903F6",
            },
        [80080336] = {
            ["Camera"] = "-178.794922,-57.247498,139.419922,0.000046,-6.999994,44.603405,32.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我曾以为，我只要过好最后的日子就已经足够了。但是现在的我想要……",
            ["ContentKR"] = "예전에는 저에게 남은 시간만 잘 보내면 충분할 거라고 생각했어요. 하지만 지금은...",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80080336,
            ["GUID"] = "C8790420",
            ["NextDialogue"] = 80080337,
            ["SpeakNpcId"] = 790004,
            ["VoiceName"] = "voice/$Locale$/inv/Saiqi/003/C8790420",
            },
        [80080337] = {
            ["Camera"] = "-115.541016,2.555298,138.173828,0.000146,-6.001127,46.597878,32.000004,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "“活下去”。",
            ["ContentKR"] = "'살고' 싶어요.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80080337,
            ["GUID"] = "C879044A",
            ["NextDialogue"] = 80080338,
            ["SpeakNpcId"] = 790004,
            ["VoiceName"] = "voice/$Locale$/inv/Saiqi/003/C879044A",
            },
        [80080338] = {
            ["Camera"] = "-252.96875,-122.314819,187.210938,0.000079,-18.400009,32.607815,32.000004,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "所以，恩里克叔叔，请答应我的请求吧。",
            ["ContentKR"] = "그러니, 헨릭 아저씨... 부탁이에요.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80080338,
            ["GUID"] = "C8790474",
            ["NextDialogue"] = 80080339,
            ["SpeakNpcId"] = 790004,
            ["TalkActionId"] = {
                [1] = "790004:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Saiqi/003/C8790474",
            },
        [80080339] = {
            ["Camera"] = "-87.298828,86.861511,111.849609,0.00008,9.999362,-101.195549,32.000004,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "“既然我注定不能像人一样地活着，那么我希望像人一样地死去……”",
            ["ContentKR"] = "'어차피 사람답게 살 수 없다면, 적어도 사람답게 죽고 싶어요...'",
            ["DialogueId"] = 80080339,
            ["GUID"] = "C879049E",
            ["LookAt"] = {
                [1] = "790005:n(790005)",
                },
            ["NextDialogue"] = 80080340,
            ["SpeakNpcId"] = 790005,
            ["TalkActionId"] = {
                [1] = "790005:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Saiqi/003/C879049E",
            },
        [80080340] = {
            ["Camera"] = "-87.298828,86.861511,111.849609,0.00008,9.999362,-101.195549,32.000004,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这是海莉——我的女儿，在最后一夜对我倾诉的愿望。你们如此相似，但又如此不同……",
            ["ContentKR"] = "이건 헤일리... 내 딸 헤일리가 마지막 밤에 나에게 부탁했던 소원이란다. 너희 둘은 다르지만 또 한편으로는 닮았구나...",
            ["DialogueId"] = 80080340,
            ["GUID"] = "C87904C8",
            ["LookAt"] = {
                [1] = "790005:n(790004)",
                },
            ["NextDialogue"] = 80080341,
            ["SpeakNpcId"] = 790005,
            ["TalkActionId"] = {
                [1] = "790005:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Saiqi/003/C87904C8",
            },
        [80080341] = {
            ["Camera"] = "-137.392578,-0.853027,138.126953,0.000042,13.199668,-95.195374,32.000004,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "“像人一样地活下去”——我明白你的愿望了。",
            ["ContentKR"] = "'사람답게 살고 싶다'... 네 소원이 뭔지 이해했다.",
            ["DialogueId"] = 80080341,
            ["GUID"] = "C87904F2",
            ["LookAt"] = {
                [1] = "790005:n(790005)",
                },
            ["NextDialogue"] = 80080342,
            ["SpeakNpcId"] = 790005,
            ["TalkActionId"] = {
                [1] = "790005:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Saiqi/003/C87904F2",
            },
        [80080342] = {
            ["Camera"] = "-123.386719,-265.981384,183.080078,0.000053,-11.799984,89.199028,32.000004,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "命运啊……求你怜悯我唯一一次……让我帮她实现这个愿望吧。",
            ["ContentKR"] = "운명의 신이시여... 부디 한 번만 절 불쌍히 여기시어... 이 아이의 소원을 이룰 수 있게 해주십시오.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80080342,
            ["FinalCamera"] = "-123.013672,-238.728149,177.398438,0.000053,-11.799984,89.199028,32.000004,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "C879051C",
            ["SpeakNpcId"] = 790005,
            ["ToFinalCameraBlendTime"] = 3,
            ["TurnTo"] = {
                [1] = "790005:p(180)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Saiqi/003/C879051C",
            },
        [80090100] = {
            ["Content"] = "嘻嘻，今天要玩什么？",
            ["ContentKR"] = "히히, 오늘은 뭘 하고 놀아볼까?",
            ["DialogueId"] = 80090100,
            ["GUID"] = "C87F4608",
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/001/C87F4608",
            },
        [80090101] = {
            ["Camera"] = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
            ["Content"] = "……",
            ["ContentKR"] = "......",
            ["DialogueId"] = 80090101,
            ["FacialId"] = {
                [1] = "92301:Unhappy01",
                },
            ["GUID"] = "C87F4632",
            ["LookAt"] = {
                [1] = "92301:p(18000P1)",
                },
            ["NextDialogue"] = 80090102,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/001/C87F4632",
            },
        [80090102] = {
            ["Content"] = "……",
            ["ContentKR"] = "......",
            ["DialogueId"] = 80090102,
            ["GUID"] = "C87F465C",
            ["NextDialogue"] = 80090103,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/001/C87F465C",
            },
        [80090103] = {
            ["Content"] = "……喂！我刚才喝完饮料突然消失了，你怎么跟没事人似的！",
            ["ContentKR"] = "...야! 내가 방금 음료수 마시자마자 갑자기 사라졌잖아, 너는 왜 걱정도 안 하는 거야!",
            ["DialogueId"] = 80090103,
            ["GUID"] = "C87F4686",
            ["NextDialogue"] = 80090104,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/001/C87F4686",
            },
        [80090104] = {
            ["Content"] = "光天化日之下，“恶魔大盗”神秘失踪！你就不觉得很奇怪、很担心吗！",
            ["ContentKR"] = "이 대낮에! '악마대도'가 아무도 모르게 사라졌는데! 이상하거나 걱정되지 않는 거냐고!",
            ["DialogueId"] = 80090104,
            ["GUID"] = "C87F46B0",
            ["NextOptions"] = {
                [1] = 80090105,
                [2] = 80090107,
                },
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/001/C87F46B0",
            },
        [80090105] = {
            ["Content"] = "刚才这里多了一把椅子，那是你变的吧。",
            ["ContentKR"] = "방금 여기에 의자가 하나 더 생겼던데, 네가 변한 거 아니었어?",
            ["DialogueId"] = 80090105,
            ["GUID"] = "C87F46DA",
            ["NextDialogue"] = 80090106,
            },
        [80090106] = {
            ["Content"] = "什么！你居然看破了我的伪装绝技！",
            ["ContentKR"] = "아닛! 나의 이 대단한 위장 기술을 눈치채다니!",
            ["DialogueId"] = 80090106,
            ["FacialId"] = {
                [1] = "92301:Shock01",
                },
            ["GUID"] = "C87F4704",
            ["NextDialogue"] = 80090109,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/001/C87F4704",
            },
        [80090107] = {
            ["Content"] = "担心？塔比瑟变成椅子逗我开心，我欣慰才是。",
            ["ContentKR"] = "걱정? 타비사가 나를 즐겁게 해주려고 의자로 변했잖아. 난 오히려 기분이 좋은걸.",
            ["DialogueId"] = 80090107,
            ["GUID"] = "C87F472E",
            ["NextDialogue"] = 80090108,
            },
        [80090108] = {
            ["Content"] = "噫，你也太自作多情了，我只是想吓唬你！吓——唬！",
            ["ContentKR"] = "윽, 김칫국 그만 마셔. 난 그저 널 놀라게 하려고 그런 거야! 놀, 라, 게!",
            ["DialogueId"] = 80090108,
            ["GUID"] = "C87F4758",
            ["NextDialogue"] = 80090109,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/001/C87F4758",
            },
        [80090109] = {
            ["Content"] = "……嘁，这次算我失手了，下次我一定变成你想不到的东西！",
            ["ContentKR"] = "...칫, 이번은 실수야. 다음에는 네가 눈치챌 수 없게 다른 걸로 변하겠어!",
            ["DialogueId"] = 80090109,
            ["FacialId"] = {
                [1] = "92301:Unhappy01",
                },
            ["GUID"] = "C87F4782",
            ["NextDialogue"] = 80090110,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/001/C87F4782",
            },
        [80090110] = {
            ["Content"] = "变什么好呢……酒桶？吊灯？大锤？",
            ["ContentKR"] = "뭐로 변할까... 술통? 샹들리에? 아니면 망치?",
            ["DialogueId"] = 80090110,
            ["GUID"] = "C87F47AC",
            ["NextDialogue"] = 80090111,
            ["SpeakNpcId"] = 92301,
            ["TalkActionId"] = {
                [1] = "92301:Sit_Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/001/C87F47AC",
            },
        [80090111] = {
            ["Content"] = "哇哦，你好有本领。",
            ["ContentKR"] = "와, 정말 대단한데?",
            ["DialogueId"] = 80090111,
            ["GUID"] = "C87F47D6",
            ["NextDialogue"] = 80090112,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/001/C87F47D6",
            },
        [80090112] = {
            ["Content"] = "那当然！听说我这本事叫做……泥，泥什么来着……泥台？……拟态！对对，“拟态”！",
            ["ContentKR"] = "당연하지! 내 위... 위 뭐였더라... 위당?... 아, 위장! 그래, '위장' 실력이 얼마나 대단한데!",
            ["DialogueId"] = 80090112,
            ["FacialId"] = {
                [1] = "92301:Satisfy01",
                },
            ["GUID"] = "C87F4800",
            ["NextDialogue"] = 80090113,
            ["SpeakNpcId"] = 92301,
            ["TalkActionId"] = {
                [1] = "92301:Sit_Talk03ToThink_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/001/C87F4800",
            },
        [80090113] = {
            ["Content"] = "所以你什么都能变？",
            ["ContentKR"] = "뭐든지 다 변할 수 있는 거야?",
            ["DialogueId"] = 80090113,
            ["GUID"] = "C87F482A",
            ["NextDialogue"] = 80090114,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/001/C87F482A",
            },
        [80090114] = {
            ["Content"] = "嘻嘻，可不是！看好了——",
            ["ContentKR"] = "히히, 물론이지! 잘 봐!",
            ["DialogueId"] = 80090114,
            ["GUID"] = "C87F4854",
            ["NextDialogue"] = 80090144,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/001/C87F4854",
            },
        [80090115] = {
            ["Camera"] = "159.880188,-5.018555,149.99321,0.000005,1.39885,175.800934,30.000002,159.585938,false,Manual,3.0",
            ["Content"] = "我会提出一个你无法拒绝的条件，你最好深思熟虑之后再回答我。",
            ["ContentKR"] = "지금 그쪽이 거절할 수 없는 제안을 할게. 곰곰이 잘 생각해서 대답해.",
            ["DialogueId"] = 80090115,
            ["GUID"] = "C87F487E",
            ["LookAt"] = {
                [1] = "92301:p(18000P1)",
                },
            ["NextDialogue"] = 80090116,
            ["SpeakNpcId"] = 790052,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/001/C87F487E",
            },
        [80090116] = {
            ["Content"] = "叫醒我的是生意，叫醒你的是什么？",
            ["ContentKR"] = "날 깨운 것은 장사인데, 널 깨운 것은 뭐야?",
            ["DialogueId"] = 80090116,
            ["GUID"] = "C87F48A8",
            ["NextOptions"] = {
                [1] = 80090117,
                [2] = 80090119,
                },
            ["SpeakNpcId"] = 790052,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/001/C87F48A8",
            },
        [80090117] = {
            ["Content"] = "噗嗤——叫醒我的是恶魔大盗的万丈光芒！",
            ["ContentKR"] = "푸핫, 날 깨운 건 태양보다 빛나는 악마대도의 반짝임이지!",
            ["DialogueId"] = 80090117,
            ["GUID"] = "C87F48D2",
            ["NextDialogue"] = 80090118,
            },
        [80090118] = {
            ["Content"] = "嘻嘻，嘴真甜，比你调的饮料还甜！",
            ["ContentKR"] = "히히, 듣기 좋은데? 네가 만든 음료수보다 훨씬 달콤한걸!",
            ["DialogueId"] = 80090118,
            ["FacialId"] = {
                [1] = "790052:Happy01",
                },
            ["GUID"] = "C87F48FC",
            ["NextDialogue"] = 80090144,
            ["SpeakNpcId"] = 790052,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["TalkActionId"] = {
                [1] = "790052:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/001/C87F48FC",
            },
        [80090119] = {
            ["Content"] = "噗嗤——我告卡米拉了！",
            ["ContentKR"] = "푸핫, 카밀라 님한테 이를 거야!",
            ["DialogueId"] = 80090119,
            ["GUID"] = "C87F4926",
            ["NextDialogue"] = 80090120,
            },
        [80090120] = {
            ["Content"] = "我才不怕她嘞！没人能抓到恶魔大盗！",
            ["ContentKR"] = "나는 하나도 안 무섭거든! 그 누구도 악마대도를 막을 수는 없다고!",
            ["DialogueId"] = 80090120,
            ["FacialId"] = {
                [1] = "790052:Confident01",
                },
            ["GUID"] = "C87F4950",
            ["NextDialogue"] = 80090144,
            ["SpeakNpcId"] = 790052,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["TalkActionId"] = {
                [1] = "790052:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/001/C87F4950",
            },
        [80090121] = {
            ["Camera"] = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
            ["Content"] = "不过我也不是什么都会变，太大和太小的东西都不行。猫咪可以，老鼠就不可以。木桶可以，路灯架子就不可以。",
            ["ContentKR"] = "근데 아무거나 다 될 수 있는 건 아니야. 너무 작거나 크면 변할 수 없거든. 고양이나 통나무는 가능하지만, 쥐랑 가로등은 불가능해.",
            ["DialogueId"] = 80090121,
            ["GUID"] = "C87F497A",
            ["LookAt"] = {
                [1] = "92301:p(18000P1)",
                },
            ["NextDialogue"] = 80090122,
            ["SpeakNpcId"] = 92301,
            ["TalkActionId"] = {
                [1] = "92301:Sit_Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/001/C87F497A",
            },
        [80090122] = {
            ["Content"] = "但这就足够了，大部分人根本发现不了我的完美伪装！我随便变个罐子箱子垃圾桶什么的，那些坏小偷啊，就只能乖乖地被我收拾了！",
            ["ContentKR"] = "하지만 이 정도면 충분해. 웬만한 사람은 나의 완벽한 위장을 눈치채지 못하거든! 내가 캔이나, 상자, 쓰레기통으로 변해버리면 나쁜 도둑들은 다 내 손안에 있는 거나 다름없지!",
            ["DialogueId"] = 80090122,
            ["GUID"] = "C87F49A4",
            ["NextOptions"] = {
                [1] = 80090123,
                [2] = 80090131,
                },
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/001/C87F49A4",
            },
        [80090123] = {
            ["Content"] = "……完了，以后可有得头疼了。",
            ["ContentKR"] = "...망했네, 앞으로 골치 아프겠어.",
            ["DialogueId"] = 80090123,
            ["GUID"] = "C87F49CE",
            ["NextDialogue"] = 80090124,
            },
        [80090124] = {
            ["Content"] = "你嘀嘀咕咕什么呢？",
            ["ContentKR"] = "혼자 뭐라고 중얼대는 거야?",
            ["DialogueId"] = 80090124,
            ["FacialId"] = {
                [1] = "92301:Doubt01",
                },
            ["GUID"] = "C87F49F8",
            ["NextDialogue"] = 80090125,
            ["SpeakNpcId"] = 92301,
            ["TalkActionId"] = {
                [1] = "92301:Sit_Talk03ToTalkL_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/001/C87F49F8",
            },
        [80090125] = {
            ["Content"] = "没什么，夸你很厉害的意思。",
            ["ContentKR"] = "아무것도 아니야. 네가 엄청 대단하다고.",
            ["DialogueId"] = 80090125,
            ["GUID"] = "C87F4A22",
            ["NextDialogue"] = 80090126,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/001/C87F4A22",
            },
        [80090126] = {
            ["Content"] = "但之后还是别变箱子罐子垃圾桶了，万一被人路过随手打烂了然后翻翻找找有用的东西可怎么办……",
            ["ContentKR"] = "그래도 캔이나 상자, 쓰레기통 같은 것들로 변하지는 마. 지나가던 누군가 부수거나 뒤지면 어떡해...",
            ["DialogueId"] = 80090126,
            ["GUID"] = "C87F4A4C",
            ["NextDialogue"] = 80090127,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/001/C87F4A4C",
            },
        [80090127] = {
            ["Content"] = "谁手这么欠啊？",
            ["ContentKR"] = "도대체 누가 그런 나쁜 손버릇을 가졌길래?",
            ["DialogueId"] = 80090127,
            ["GUID"] = "C87F4A76",
            ["NextDialogue"] = 80090128,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/001/C87F4A76",
            },
        [80090128] = {
            ["Content"] = "呃……一些特别富有好奇心的路过市民？",
            ["ContentKR"] = "음... 길을 지나가던 호기심이 엄청난 시민?",
            ["DialogueId"] = 80090128,
            ["GUID"] = "C87F4AA0",
            ["NextDialogue"] = 80090129,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/001/C87F4AA0",
            },
        [80090129] = {
            ["Content"] = "有用的就收起来，没用的就利用完丢掉，坏大人都一个样！",
            ["ContentKR"] = "쓸모 있을 때는 좋아하고, 쓸모 없어지면 버리다니. 나쁜 어른들은 다 똑같아!",
            ["DialogueId"] = 80090129,
            ["FacialId"] = {
                [1] = "92301:Angry01",
                },
            ["GUID"] = "C87F4ACA",
            ["NextDialogue"] = 80090130,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/001/C87F4ACA",
            },
        [80090130] = {
            ["Content"] = "路过市民可没想伤害任何人！不过，你一直挂在嘴上的“坏大人”是什么？",
            ["ContentKR"] = "지나가던 시민은 아무도 해치지 않아! 근데 왜 계속 '나쁜 어른' 얘기를 하는 거야?",
            ["DialogueId"] = 80090130,
            ["GUID"] = "C87F4AF4",
            ["NextDialogue"] = 80090136,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/001/C87F4AF4",
            },
        [80090131] = {
            ["Content"] = "听起来很厉害，还好你没什么坏心思。",
            ["ContentKR"] = "굉장하네. 그래도 네가 착한 아이라서 다행이야.",
            ["DialogueId"] = 80090131,
            ["GUID"] = "C87F4B1E",
            ["NextDialogue"] = 80090132,
            },
        [80090132] = {
            ["Content"] = "什么意思？",
            ["ContentKR"] = "무슨 뜻이야?",
            ["DialogueId"] = 80090132,
            ["FacialId"] = {
                [1] = "92301:Doubt01",
                },
            ["GUID"] = "C87F4B48",
            ["NextDialogue"] = 80090133,
            ["SpeakNpcId"] = 92301,
            ["TalkActionId"] = {
                [1] = "92301:Sit_Talk03ToTalkL_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/001/C87F4B48",
            },
        [80090133] = {
            ["Content"] = "我是说，要是那些有点小聪明但心思很坏的家伙有这种本事，那整座城都要鸡飞狗跳了。",
            ["ContentKR"] = "그러니까, 똑똑한데 나쁜 속셈을 품은 사람이 그런 기술까지 있다면 온통 난리가 나지 않겠어?",
            ["DialogueId"] = 80090133,
            ["GUID"] = "C87F4B72",
            ["NextDialogue"] = 80090134,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/001/C87F4B72",
            },
        [80090134] = {
            ["Content"] = "哼哼，我也这么觉得！我和那些坏大人可不是一路人。等等，你难道是想说本“恶魔大盗”不够聪明？",
            ["ContentKR"] = "흐음, 맞는 말이야! 나는 나쁜 어른과 전혀 다르다고! 잠깐, 설마 지금 '악마대도'가 똑똑하지 않다는 거야?",
            ["DialogueId"] = 80090134,
            ["FacialId"] = {
                [1] = "92301:Confident01",
                },
            ["GUID"] = "C87F4B9C",
            ["NextDialogue"] = 80090135,
            ["SpeakNpcId"] = 92301,
            ["TalkActionId"] = {
                [1] = "92301:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/001/C87F4B9C",
            },
        [80090135] = {
            ["Content"] = "没有没有，塔比瑟是很聪明的好恶魔。不过这些不重要，我更好奇，“那些坏大人”是什么？",
            ["ContentKR"] = "그럴 리가, 타비사는 똑똑한 악마잖아. 그나저나 '나쁜 어른'은 무슨 말인지 더 궁금한데.",
            ["DialogueId"] = 80090135,
            ["GUID"] = "C87F4BC6",
            ["NextDialogue"] = 80090136,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/001/C87F4BC6",
            },
        [80090136] = {
            ["Content"] = "就是欺负弱小的坏蛋大人！我最先碰到的坏大人就是孤儿院那些照顾小孩的……啧，说是照顾，其实和看犯人没啥两样。",
            ["ContentKR"] = "약자를 괴롭히는 나쁜 어른을 말하는 거야! 내가 만났던 첫 나쁜 어른은 보육원의 아이들을 돌보는 사람이었어... 칫, 말만 보살핀다고 포장하지만 사실 감옥처럼 감시한다는 말이 더 어울렸달까?",
            ["DialogueId"] = 80090136,
            ["FacialId"] = {
                [1] = "92301:Angry01",
                },
            ["GUID"] = "C87F4BF0",
            ["NextDialogue"] = 80090137,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/001/C87F4BF0",
            },
        [80090137] = {
            ["Content"] = "小时候我饿着肚子去厨房找东西吃，被那些坏大人们发现了的话，就会挨打。坏死了！明明是他们不给我东西吃在先！",
            ["ContentKR"] = "어릴 때 배가 고팠던 나는 주방에 몰래 가서 음식을 뒤졌거든. 그런데 그걸 발견한 나쁜 어른이 날 때렸어. 너무 나빠! 밥도 안 줬으면서!",
            ["DialogueId"] = 80090137,
            ["GUID"] = "C87F4C1A",
            ["NextDialogue"] = 80090138,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/001/C87F4C1A",
            },
        [80090138] = {
            ["Content"] = "要是现在再让我遇到他们，我就把他们一个个倒立着捆起来挂在房顶，让他们瞪大眼看着我把厨房的东西吃光光！",
            ["ContentKR"] = "내 눈앞에 또 보이기만 해봐! 지붕에 거꾸로 매달아서 내가 주방에 있는 음식을 먹어 치우는 걸 지켜보게 할 거야!",
            ["DialogueId"] = 80090138,
            ["GUID"] = "C87F4C44",
            ["NextOptions"] = {
                [1] = 80090139,
                [2] = 80090140,
                },
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/001/C87F4C44",
            },
        [80090139] = {
            ["Content"] = "都过去了。现在的塔比瑟已经不会被坏大人打了。",
            ["ContentKR"] = "다 지나간 일이야. 지금은 그 어떤 나쁜 어른도 타비사를 때릴 수 없어.",
            ["DialogueId"] = 80090139,
            ["GUID"] = "C87F4C6E",
            ["NextDialogue"] = 80090141,
            },
        [80090140] = {
            ["Content"] = "对，这些坏家伙就该给点颜色瞧瞧。",
            ["ContentKR"] = "맞아. 그 나쁜 녀석들에게 본때를 보여줘야 해.",
            ["DialogueId"] = 80090140,
            ["GUID"] = "C87F4C98",
            ["NextDialogue"] = 80090141,
            },
        [80090141] = {
            ["Content"] = "哼！就是就是！",
            ["ContentKR"] = "흥! 맞아, 맞아!",
            ["DialogueId"] = 80090141,
            ["FacialId"] = {
                [1] = "92301:Satisfy01",
                },
            ["GUID"] = "C87F4CC2",
            ["NextDialogue"] = 80090142,
            ["SpeakNpcId"] = 92301,
            ["TalkActionId"] = {
                [1] = "92301:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/001/C87F4CC2",
            },
        [80090142] = {
            ["Content"] = "饮料喝完了，“坏大人”的事下次再讲，现在快陪我出去玩！",
            ["ContentKR"] = "음료수 다 마셨어. '나쁜 어른'에 대한 이야기는 다음에 또 들려줄게. 이제 나가서 놀자!",
            ["DialogueId"] = 80090142,
            ["GUID"] = "C87F4CEC",
            ["NextDialogue"] = 80090143,
            ["SpeakNpcId"] = 92301,
            ["TalkActionId"] = {
                [1] = "92301:Sit_Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/001/C87F4CEC",
            },
        [80090143] = {
            ["Content"] = "嘻嘻嘻，我们来玩捉迷藏吧，这次我可不会再被你轻松找到了！",
            ["ContentKR"] = "히히히, 우리 숨바꼭질하고 놀자. 이번에는 찾기 힘들걸!",
            ["DialogueId"] = 80090143,
            ["FacialId"] = {
                [1] = "92301:Smile02",
                },
            ["GUID"] = "C87F4D16",
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/001/C87F4D16",
            },
        [80090144] = {
            ["DialogueId"] = 80090144,
            ["DialoguePanelType"] = "None",
            ["Duration"] = 1,
            ["GUID"] = "C87F4D17",
            ["IsBlack"] = 1,
            },
        [80090201] = {
            ["Camera"] = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
            ["Content"] = "嗯~喝起来有点咸咸的，不过好好喝喔，就像海风味的棉花糖一样！",
            ["ContentKR"] = "음~ 조금 짜지만 맛있어. 꼭 바닷바람 맛의 솜사탕 같아!",
            ["DialogueId"] = 80090201,
            ["FacialId"] = {
                [1] = "92301:Smile01",
                },
            ["GUID"] = "C87F569A",
            ["LookAt"] = {
                [1] = "92301:p(18000P1)",
                },
            ["NextDialogue"] = 80090202,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/002/C87F569A",
            },
        [80090202] = {
            ["Content"] = "总感觉在很久很久以前我好像喝过类似的饮料，那时候我和爸爸妈妈一起乘上的船还没有沉，我也还没有漂到镇上被孤儿院收养……",
            ["ContentKR"] = "아주 예전에 비슷한 걸 마셔본 적 있는 것 같아. 그때는 나랑 부모님이 타고 있던 배가 침몰하지 않았고, 나도 떠내려와서 마을의 보육원으로 보내지기 전이었지...",
            ["DialogueId"] = 80090202,
            ["GUID"] = "C87F56C4",
            ["NextDialogue"] = 80090203,
            ["SpeakNpcId"] = 92301,
            ["TalkActionId"] = {
                [1] = "92301:Sit_Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/002/C87F56C4",
            },
        [80090203] = {
            ["Content"] = "但如果再让我选，还不如自己一个人流浪呢！坏大人们连吃的都不愿多给，更别说饮料了。",
            ["ContentKR"] = "다시 돌아간다면, 차라리 혼자 떠돌이 생활을 하겠어! 그 나쁜 어른들은 먹을 것도 제대로 안 줬는데, 음료는 더더욱 없었으니까.",
            ["DialogueId"] = 80090203,
            ["FacialId"] = {
                [1] = "92301:Angry01",
                },
            ["GUID"] = "C87F56EE",
            ["NextDialogue"] = 80090204,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/002/C87F56EE",
            },
        [80090204] = {
            ["Content"] = "就算是流浪好歹也能在垃圾桶里捡点吃的，总比在坏大人魔爪下饿肚子强多了！",
            ["ContentKR"] = "떠돌아다니다가 쓰레기통의 음식을 구해서 먹는 게, 나쁜 어른들이 있는 보육원에서 굶는 것보다 훨씬 나아!",
            ["DialogueId"] = 80090204,
            ["GUID"] = "C87F5718",
            ["NextDialogue"] = 80090205,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/002/C87F5718",
            },
        [80090205] = {
            ["Content"] = "等到长大点了，就会有群贵客时不时带走一些和我一样没人要的长角小孩，说是被有钱人领养了。",
            ["ContentKR"] = "좀 더 크고 나서는 나처럼 뿔이 달리고 입양되지 못한 아이들을 데려가는 분이 있었는데, 듣기로는 부잣집에 입양된 거라고 하더라고.",
            ["DialogueId"] = 80090205,
            ["FacialId"] = {
                [1] = "92301:None",
                },
            ["GUID"] = "C87F5742",
            ["NextDialogue"] = 80090206,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/002/C87F5742",
            },
        [80090206] = {
            ["Content"] = "我不想要别的爸爸妈妈，但有钱人家一定不缺吃的，我想去，但坏大人说我调皮捣蛋又不老实，贵客才不会看上我咧！",
            ["ContentKR"] = "나는 다른 엄마나 아빠가 생기기는 건 싫지만 배부르게 먹고 싶어서 부잣집에 가고 싶었거든. 그런데 나쁜 어른들은 내가 너무 말썽꾸러기라 그분들이 날 입양하지 않는 거라고 했어.",
            ["DialogueId"] = 80090206,
            ["GUID"] = "C87F576C",
            ["NextDialogue"] = 80090207,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/002/C87F576C",
            },
        [80090207] = {
            ["Content"] = "哼！那又怎么样，要是乖乖听话我就不是塔比瑟了！反正这鬼地方我是一天也待不下去了，于是我就趁着贵客不注意，变成了他的手提箱。",
            ["ContentKR"] = "흥! 그게 어쨌다는 거야. 이 타비사 님이 그런다고 고분고분해질 리 있나! 어쨌든 난 이 구질구질한 곳에 하루도 더 있기 싫어서 그 손님이 한눈판 틈을 타서 캐리어로 변신했어.",
            ["DialogueId"] = 80090207,
            ["FacialId"] = {
                [1] = "92301:Confident01",
                },
            ["GUID"] = "C87F5796",
            ["NextDialogue"] = 80090208,
            ["SpeakNpcId"] = 92301,
            ["TalkActionId"] = {
                [1] = "92301:Sit_Talk03ToThink_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/002/C87F5796",
            },
        [80090208] = {
            ["Content"] = "看来所谓的有钱人也不怎么聪明嘛！贵客把我拎起来就走，什么也没发现，就是苦了我的耳朵，被当成提手拎了一路，差点就掉在地上啦！",
            ["ContentKR"] = "부자들도 똑똑한 건 아닌가 봐! 아무도 눈치채지 못하고 나를 들고 나가더라고. 근데 가는 동안 내 귀를 손잡이처럼 계속 잡아당겨서, 어찌나 아프던지!",
            ["DialogueId"] = 80090208,
            ["GUID"] = "C87F57C0",
            ["NextOptions"] = {
                [1] = 80090209,
                [2] = 80090211,
                },
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/002/C87F57C0",
            },
        [80090209] = {
            ["Content"] = "噫，听着就痛！以后我一定好好保护你的耳朵！",
            ["ContentKR"] = "윽, 듣기만 해도 아프네! 앞으로 네 귀는 내가 잘 지켜줄게!",
            ["DialogueId"] = 80090209,
            ["GUID"] = "C87F57EA",
            ["NextDialogue"] = 80090210,
            },
        [80090210] = {
            ["Content"] = "……这话怎么好像听着怪怪的……算了，这个不是重点！",
            ["ContentKR"] = "...뭔가 좀 이상한데... 됐어, 그게 중요한 게 아니야!",
            ["DialogueId"] = 80090210,
            ["FacialId"] = {
                [1] = "92301:Doubt01",
                },
            ["GUID"] = "C87F5814",
            ["NextDialogue"] = 80090213,
            ["SpeakNpcId"] = 92301,
            ["TalkActionId"] = {
                [1] = "92301:Sit_DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/002/C87F5814",
            },
        [80090211] = {
            ["Content"] = "塔比瑟居然能从那种地方逃出来，未来的“恶魔大盗”的人非同一般！",
            ["ContentKR"] = "타비사, 그런 곳에서 도망쳐 나왔다니. 역시 미래의 '악마대도'는 남달랐네!",
            ["DialogueId"] = 80090211,
            ["GUID"] = "C87F583E",
            ["NextDialogue"] = 80090212,
            },
        [80090212] = {
            ["Content"] = "嘻嘻，那当然！可惜那时候我还不太熟练，否则我才不会把耳朵变成脸对着提手呢。",
            ["ContentKR"] = "히히, 당연하지! 근데 그때는 내가 아직 위장에 익숙하지 않았어. 아니었다면 귀가 손잡이로 변할 일은 없었을 텐데.",
            ["DialogueId"] = 80090212,
            ["GUID"] = "C87F5868",
            ["NextDialogue"] = 80090213,
            ["SpeakNpcId"] = 92301,
            ["TalkActionId"] = {
                [1] = "92301:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/002/C87F5868",
            },
        [80090213] = {
            ["Content"] = "其实我本来是想悄悄混在那几个被领养的孩子里的，想着如果能被有钱人领养，我就再也不用饿肚子了吧。",
            ["ContentKR"] = "원래는 입양된 아이들 사이에 슬쩍 끼어들어가려고 했어. 부잣집에 입양된다면 더 이상 배고플 일은 없겠다고 생각했거든.",
            ["DialogueId"] = 80090213,
            ["FacialId"] = {
                [1] = "92301:Sad01",
                },
            ["GUID"] = "C87F5892",
            ["NextDialogue"] = 80090214,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/002/C87F5892",
            },
        [80090214] = {
            ["Content"] = "但是贵客浑身上下都是奇怪的消毒水味儿，呛得我鼻子痛！而且，不知道为什么，我总觉得……他看孩子们的眼神，有点瘆人……",
            ["ContentKR"] = "근데 그 손님들 몸에서 이상한 소독약 냄새가 났어. 코가 따가울 정도로! 그리고 이유는 모르겠지만... 아이들을 쳐다보는 눈빛이 너무 소름 돋았어...",
            ["DialogueId"] = 80090214,
            ["GUID"] = "C87F58BC",
            ["NextDialogue"] = 80090215,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/002/C87F58BC",
            },
        [80090215] = {
            ["Content"] = "就像是……厨师大叔看鱼，看鸭子的那种眼神！",
            ["ContentKR"] = "마치... 쉐프가 생선이랑 오리를 보는 듯한 눈빛이 그런 눈빛일 것 같달까!",
            ["DialogueId"] = 80090215,
            ["GUID"] = "C87F58E6",
            ["NextDialogue"] = 80090216,
            ["SpeakNpcId"] = 92301,
            ["TalkActionId"] = {
                [1] = "92301:Sit_Talk03ToThink_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/002/C87F58E6",
            },
        [80090216] = {
            ["Content"] = "好大人少见，坏大人我可见太多啦！与其去相信他们，还不如靠我自己呢。所以我最后没有混进孩子的队伍里，一个人悄悄逃掉了。",
            ["ContentKR"] = "착한 어른은 거의 못 봤지만, 나쁜 어른은 많이 봤거든! 그들을 믿을 바엔 나를 믿는 게 더 나아. 그래서 결국 아이들 사이에 숨지 않고, 혼자 도망쳤어.",
            ["DialogueId"] = 80090216,
            ["FacialId"] = {
                [1] = "92301:Confident01",
                },
            ["GUID"] = "C87F5910",
            ["NextDialogue"] = 80090217,
            ["SpeakNpcId"] = 92301,
            ["TalkActionId"] = {
                [1] = "92301:Sit_Talk03ToThink_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/002/C87F5910",
            },
        [80090217] = {
            ["Content"] = "这就是塔比瑟成为恶魔大盗的第一步！",
            ["ContentKR"] = "그렇게 타비사는 악마대도가 되는 첫걸음을 내디딘 거지!",
            ["DialogueId"] = 80090217,
            ["GUID"] = "C87F593A",
            ["NextOptions"] = {
                [1] = 80090218,
                [2] = 80090220,
                },
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/002/C87F593A",
            },
        [80090218] = {
            ["Content"] = "我想塔比瑟并不是坏孩子，你只是……很特别。",
            ["ContentKR"] = "타비사는 나쁜 아이가 아니야. 넌 그저... 특별할 뿐이야.",
            ["DialogueId"] = 80090218,
            ["GUID"] = "C87F5964",
            ["NextDialogue"] = 80090219,
            },
        [80090219] = {
            ["Content"] = "我不是坏，而是很特别吗？还没人这么说过我……特别的孩子，特别的孩子……嘻嘻！",
            ["ContentKR"] = "나쁜 게 아니라 특별한 거라고? 이런 말은 처음이야... 특별한, 특별한 아이... 헤헤!",
            ["DialogueId"] = 80090219,
            ["FacialId"] = {
                [1] = "92301:Happy01",
                },
            ["GUID"] = "C87F598E",
            ["NextDialogue"] = 80090223,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/002/C87F598E",
            },
        [80090220] = {
            ["Content"] = "“贵客”听起来就很可疑，塔比瑟做出了冷静的判断。",
            ["ContentKR"] = "'손님'이라니 역시 수상하네. 타비사가 냉정하게 잘 판단했어.",
            ["DialogueId"] = 80090220,
            ["GUID"] = "C87F59B8",
            ["NextDialogue"] = 80090221,
            },
        [80090221] = {
            ["Content"] = "就是就是！你也这么觉得吧！",
            ["ContentKR"] = "그렇지? 너도 그렇게 생각하지?!",
            ["DialogueId"] = 80090221,
            ["GUID"] = "C87F59E2",
            ["NextDialogue"] = 80090222,
            ["SpeakNpcId"] = 92301,
            ["TalkActionId"] = {
                [1] = "92301:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/002/C87F59E2",
            },
        [80090222] = {
            ["Content"] = "不过那时候我光顾着自己逃了。要是我有现在的本事，一定悄悄跟在他们屁股后面，看看他们是不是在做坏事！",
            ["ContentKR"] = "근데 그때는 도망치는 것 말고 다른 건 신경 쓸 여력이 없었어. 지금의 나라면 몰래 따라다녀서 나쁜 일을 벌이는 게 아닌지 알아냈을 거야!",
            ["DialogueId"] = 80090222,
            ["FacialId"] = {
                [1] = "92301:Sad01",
                },
            ["GUID"] = "C87F5A0C",
            ["NextDialogue"] = 80090223,
            ["SpeakNpcId"] = 92301,
            ["TalkActionId"] = {
                [1] = "92301:Sit_Talk03ToThink_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/002/C87F5A0C",
            },
        [80090223] = {
            ["Content"] = "能安全逃出来，塔比瑟已经做得很好了，恭喜你获得了自由。",
            ["ContentKR"] = "무사히 도망쳐 나온 것만으로 타비사는 잘한 거야. 자유를 얻은 걸 축하해.",
            ["DialogueId"] = 80090223,
            ["GUID"] = "C87F5A36",
            ["NextDialogue"] = 80090224,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/002/C87F5A36",
            },
        [80090224] = {
            ["Content"] = "是呀，恭喜我自己！好不容易又呼吸到新鲜空气，第一次发现夜空并不一直都是黑黢黢的，那些透过脏玻璃看起来没精打采的星星，原来也可以这么明亮。",
            ["ContentKR"] = "맞아, 나도 축하해! 모처럼 신선한 공기를 마시며 고개를 들어보니 밤하늘은 어둠만 있는 게 아니더라고. 보육원의 더러운 유리창을 통해 본 밤하늘에는 흐릿한 별밖에 없었거든. 하지만 그때 본 밤하늘의 별들은 놀라울 정도로 반짝거렸어.",
            ["DialogueId"] = 80090224,
            ["FacialId"] = {
                [1] = "92301:Happy01",
                },
            ["GUID"] = "C87F5A60",
            ["NextDialogue"] = 80090225,
            ["SpeakNpcId"] = 92301,
            ["TalkActionId"] = {
                [1] = "92301:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/002/C87F5A60",
            },
        [80090225] = {
            ["Content"] = "我躺在草地上，伴着星星睡了一大觉，转天醒来，是个大晴天！之后我就一直住在那个海边小镇，再也没有“坏大人”打我了！",
            ["ContentKR"] = "나는 잔디에 누운 채 별들과 함께 잠에 들었고, 깨어나니 맑은 날이 눈앞에 펼쳐졌어! 그 후로 나는 그 바닷가 마을에 살았고, 그 뒤로는 나를 때리는 '나쁜 어른'은 없었어!",
            ["DialogueId"] = 80090225,
            ["GUID"] = "C87F5A8A",
            ["NextDialogue"] = 80090226,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/002/C87F5A8A",
            },
        [80090226] = {
            ["Content"] = "我还在那里遇到了一个人……",
            ["ContentKR"] = "그리고 거기서 누구를 만났냐면...",
            ["DialogueId"] = 80090226,
            ["GUID"] = "C87F5AB4",
            ["NextDialogue"] = 80090227,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/002/C87F5AB4",
            },
        [80090227] = {
            ["Content"] = "塔比瑟终于碰到好人了吗？",
            ["ContentKR"] = "드디어 좋은 어른을 만난 건가?",
            ["DialogueId"] = 80090227,
            ["GUID"] = "C87F5ADE",
            ["NextDialogue"] = 80090228,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/002/C87F5ADE",
            },
        [80090228] = {
            ["Content"] = "大好人！但我今天有点累了……“恶魔大盗”也会累的！",
            ["ContentKR"] = "엄청 좋은 어른이야! 휴, 그런데 오늘은 좀 힘드네... '악마대도'에게도 휴식이 필요하거든!",
            ["DialogueId"] = 80090228,
            ["FacialId"] = {
                [1] = "92301:Smile02",
                },
            ["GUID"] = "C87F5B08",
            ["NextDialogue"] = 80090229,
            ["SpeakNpcId"] = 92301,
            ["TalkActionId"] = {
                [1] = "92301:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/002/C87F5B08",
            },
        [80090229] = {
            ["Content"] = "等你下次准备好新饮料了，我再讲给你听！",
            ["ContentKR"] = "다음에 새로운 음료수를 준비해 주면, 또 이야기해 줄게!",
            ["DialogueId"] = 80090229,
            ["GUID"] = "C87F5B32",
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/002/C87F5B32",
            },
        [80090301] = {
            ["Camera"] = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
            ["Content"] = "这次的饮料也很美味！嘻嘻嘻，你可真了解我的口味！",
            ["ContentKR"] = "이번 음료수도 맛있네! 헤헤헤, 넌 역시 내 입맛을 잘 아는구나!",
            ["DialogueId"] = 80090301,
            ["FacialId"] = {
                [1] = "92301:Happy01",
                },
            ["GUID"] = "C87F6702",
            ["LookAt"] = {
                [1] = "92301:p(18000P1)",
                },
            ["NextDialogue"] = 80090302,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/003/C87F6702",
            },
        [80090302] = {
            ["Content"] = "本大盗昨天晚上是躺着草地看着夜空睡着的，天空从湛蓝色逐渐变深，星星一颗颗挂在上面，和撒着糖霜的蓝莓奶盖一模一样！",
            ["ContentKR"] = "어제 내가 잔디에 누워 밤하늘을 보며 잠이 들었거든. 파랗던 하늘이 어두워지고 별이 하나씩 반짝이기 시작하는 모습이 꼭 블루베리 치즈 폼 위에 뿌려진 설탕 같았어!",
            ["DialogueId"] = 80090302,
            ["GUID"] = "C87F672C",
            ["NextDialogue"] = 80090303,
            ["SpeakNpcId"] = 92301,
            ["TalkActionId"] = {
                [1] = "92301:Sit_Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/003/C87F672C",
            },
        [80090303] = {
            ["Content"] = "除了逃出孤儿院的那晚，我其实很少在草地上睡得这么安稳。",
            ["ContentKR"] = "보육원에서 탈출한 그날 밤을 제외하면, 사실 난 잔디 위에서 이렇게 편하게 잠든 적이 거의 없었어.",
            ["DialogueId"] = 80090303,
            ["FacialId"] = {
                [1] = "92301:Sad01",
                },
            ["GUID"] = "C87F6756",
            ["NextDialogue"] = 80090304,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/003/C87F6756",
            },
        [80090304] = {
            ["Content"] = "……因为，刚到小镇的时候，我做了很多不好的事……",
            ["ContentKR"] = "...왜냐하면, 내가 마을에 막 왔을 때 나쁜 짓을 많이 했거든...",
            ["DialogueId"] = 80090304,
            ["GUID"] = "C87F6780",
            ["NextDialogue"] = 80090305,
            ["SpeakNpcId"] = 92301,
            ["TalkActionId"] = {
                [1] = "92301:Sit_Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/003/C87F6780",
            },
        [80090305] = {
            ["Content"] = "所以大人们不喜欢我，叫我“恶魔”……",
            ["ContentKR"] = "그래서 어른들은 나를 싫어했고, '악마'라고 부르더라고...",
            ["DialogueId"] = 80090305,
            ["GUID"] = "C87F67AA",
            ["NextOptions"] = {
                [1] = 80090306,
                [2] = 80090308,
                },
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/003/C87F67AA",
            },
        [80090306] = {
            ["Content"] = "是不是恶作剧没掌握好分寸？",
            ["ContentKR"] = "장난이 지나쳤던 거야?",
            ["DialogueId"] = 80090306,
            ["GUID"] = "C87F67D4",
            ["NextDialogue"] = 80090307,
            },
        [80090307] = {
            ["Content"] = "是他们太笨了！唔……好吧，你说的对。",
            ["ContentKR"] = "그들이 너무 멍청한 거였어! 윽... 그래, 네 말이 맞아.",
            ["DialogueId"] = 80090307,
            ["FacialId"] = {
                [1] = "92301:Angry01",
                },
            ["GUID"] = "C87F67FE",
            ["NextDialogue"] = 80090310,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/003/C87F67FE",
            },
        [80090308] = {
            ["Content"] = "是不是偷吃了小镇上所有的海鱼？",
            ["ContentKR"] = "혹시 마을의 모든 생선을 먹어 치운 거야?",
            ["DialogueId"] = 80090308,
            ["GUID"] = "C87F6828",
            ["NextDialogue"] = 80090309,
            },
        [80090309] = {
            ["Content"] = "我哪有那么能吃！唔，不过你也说对了一部分……",
            ["ContentKR"] = "내가 뭘 얼마나 먹는다고! 뭐, 틀린 말은 아니지만...",
            ["DialogueId"] = 80090309,
            ["FacialId"] = {
                [1] = "92301:Angry01",
                },
            ["GUID"] = "C87F6852",
            ["NextDialogue"] = 80090310,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/003/C87F6852",
            },
        [80090310] = {
            ["Content"] = "我一直靠偷吃小摊上的食物过活。小贩们气得想打我，我就学他们气急败坏的样子，还对他们做鬼脸，也没觉得有什么不对。",
            ["ContentKR"] = "나는 늘 길거리 음식을 훔쳐서 배를 채웠어. 화난 상인들이 나를 때리려고 했지만, 나는 오히려 상인들을 약 올려줬지. 딱히 잘못했다고 생각하지는 않아.",
            ["DialogueId"] = 80090310,
            ["FacialId"] = {
                [1] = "92301:Sad01",
                },
            ["GUID"] = "C87F687C",
            ["NextDialogue"] = 80090311,
            ["SpeakNpcId"] = 92301,
            ["TalkActionId"] = {
                [1] = "92301:Sit_Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/003/C87F687C",
            },
        [80090311] = {
            ["Content"] = "“分我一点你们又饿不死，小气鬼！”",
            ["ContentKR"] = "\"좀 나눠준다고 굶어 죽는 거 아니잖아, 치사하긴!\"",
            ["DialogueId"] = 80090311,
            ["GUID"] = "C87F68A6",
            ["NextDialogue"] = 80090312,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/003/C87F68A6",
            },
        [80090312] = {
            ["Content"] = "直到遇见了她……",
            ["ContentKR"] = "하지만 그 아이를 만나고...",
            ["DialogueId"] = 80090312,
            ["FacialId"] = {
                [1] = "92301:Smile01",
                },
            ["GUID"] = "C87F68D0",
            ["NextDialogue"] = 80090313,
            ["SpeakNpcId"] = 92301,
            ["TalkActionId"] = {
                [1] = "92301:Sit_Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/003/C87F68D0",
            },
        [80090313] = {
            ["Content"] = "她是鱼摊摊主的女儿，看见我偷她家东西，不仅不打我，分海鱼给我吃，还问我家人在哪，如果走丢了可以在她家先住一晚，我第一次遇到这么好的人。",
            ["ContentKR"] = "그 아이는 생선 가게 주인의 딸이었어. 내가 훔치는 걸 보고도 때리지 않고, 생선을 나눠주기까지 했어. 또 가족에 관해 물어봐 주고, 길을 잃은 거면 자신의 집에서 하룻밤 머물러도 된다고 하더라고. 그렇게 좋은 사람은 처음이었어.",
            ["DialogueId"] = 80090313,
            ["GUID"] = "C87F68FA",
            ["NextDialogue"] = 80090314,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/003/C87F68FA",
            },
        [80090314] = {
            ["Content"] = "后来发生了许多事……她没有家了，只能去孤儿院，那可不行！我受过的罪，才不会让她也受一遍！我要带着她一起生活！",
            ["ContentKR"] = "그 뒤로 많은 일이 있었어... 그 아이가 가족을 잃어서 보육원에 가게 됐거든. 난 그걸 눈 뜨고 볼 수 없었어! 내가 겪은 걸 똑같이 겪게 둘 수 없었거든! 그래서 난 함께 살기로 했지!",
            ["DialogueId"] = 80090314,
            ["GUID"] = "C87F6924",
            ["NextDialogue"] = 80090315,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/003/C87F6924",
            },
        [80090315] = {
            ["Content"] = "我们一起在大太阳下傻笑，在海边撩起水花溅到对方身上，在泥泞的小路上跑来跑去，我会变成各种小动物逗她开心。",
            ["ContentKR"] = "우리는 햇빛 아래에서 즐겁게 웃고, 바다에서 물장난을 치고, 진흙 길에서 술래잡기했어. 내가 다양한 동물로 변해서 그 아이를 웃게 하기도 했고.",
            ["DialogueId"] = 80090315,
            ["GUID"] = "C87F694E",
            ["NextDialogue"] = 80090316,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/003/C87F694E",
            },
        [80090316] = {
            ["Content"] = "她还叫我“塔比瑟姐姐”！虽然和我一起饥一顿饱一顿地过日子，她却一直说自己很幸福。",
            ["ContentKR"] = "그리고 나를 '타비사 언니'라고 불렀어! 종종 굶기도 했지만, 그 아이는 행복하다고 했지.",
            ["DialogueId"] = 80090316,
            ["GUID"] = "C87F6978",
            ["NextDialogue"] = 80090317,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/003/C87F6978",
            },
        [80090317] = {
            ["Content"] = "也是因为她，我才决定不再拿好大人的东西了，我要做个“恶魔大盗”，专门去惩罚那些坏大人！",
            ["ContentKR"] = "덕분에 난 어른들의 물건에 손대지 않겠다고 다짐했어. 대신 나쁜 어른을 혼내는 '악마대도'가 되겠다고 생각했지!",
            ["DialogueId"] = 80090317,
            ["GUID"] = "C87F69A2",
            ["NextOptions"] = {
                [1] = 80090318,
                [2] = 80090320,
                },
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/003/C87F69A2",
            },
        [80090318] = {
            ["Content"] = "是因为很在意她的想法吗？",
            ["ContentKR"] = "그 아이가 뭐라고 생각할지 걱정한 거야?",
            ["DialogueId"] = 80090318,
            ["GUID"] = "C87F69CC",
            ["NextDialogue"] = 80090319,
            },
        [80090319] = {
            ["Content"] = "嗯，我不想她伤心。",
            ["ContentKR"] = "응, 속상하게 하긴 싫었거든.",
            ["DialogueId"] = 80090319,
            ["GUID"] = "C87F69F6",
            ["NextDialogue"] = 80090326,
            ["SpeakNpcId"] = 92301,
            ["TalkActionId"] = {
                [1] = "92301:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/003/C87F69F6",
            },
        [80090320] = {
            ["Content"] = "塔比瑟姐姐！",
            ["ContentKR"] = "{性别:타비사 누나!|타비사 언니!}",
            ["DialogueId"] = 80090320,
            ["GUID"] = "C87F6A20",
            ["NextDialogue"] = 80090321,
            },
        [80090321] = {
            ["Content"] = "怎么突然……救命，住口啊，尴尬死了！",
            ["ContentKR"] = "갑자기... 으악, 그만해. 너무 이상하잖아!",
            ["DialogueId"] = 80090321,
            ["FacialId"] = {
                [1] = "92301:Unacceptable01",
                },
            ["GUID"] = "C87F6A4A",
            ["NextDialogue"] = 80090322,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/003/C87F6A4A",
            },
        [80090322] = {
            ["Content"] = "我就想试试如果我也喊一下，你会不会也带我过日子……",
            ["ContentKR"] = "난 그저 이렇게 부르면, 나도 데리고 살아줄까 궁금해서...",
            ["DialogueId"] = 80090322,
            ["GUID"] = "C87F6A74",
            ["NextDialogue"] = 80090323,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/003/C87F6A74",
            },
        [80090323] = {
            ["Content"] = "噫！你怎么拿自己跟八岁小孩比呢！我还以为你已经是个成熟的大人了。",
            ["ContentKR"] = "윽! 그 아이는 여덟 살 꼬마였다고! 난 네가 다 큰 어른인 줄 알았는데!",
            ["DialogueId"] = 80090323,
            ["GUID"] = "C87F6A9E",
            ["NextDialogue"] = 80090324,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/003/C87F6A9E",
            },
        [80090324] = {
            ["Content"] = "开玩笑的。所以，塔比瑟是很在意她的想法吗？",
            ["ContentKR"] = "장난이야. 그러니까, 타비사는 그 아이가 어떻게 생각할지 신경 썼던 거야?",
            ["DialogueId"] = 80090324,
            ["GUID"] = "C87F6AC8",
            ["NextDialogue"] = 80090325,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/003/C87F6AC8",
            },
        [80090325] = {
            ["Content"] = "因为她问我：“偷善良人的东西，是对的吗？”",
            ["ContentKR"] = "한 번은 내게 '착한 사람의 물건을 훔치는 건 옳은 일이야?'라고 묻더라고.",
            ["DialogueId"] = 80090325,
            ["GUID"] = "C87F6AF2",
            ["NextDialogue"] = 80090326,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/003/C87F6AF2",
            },
        [80090326] = {
            ["Content"] = "我一开始想，那些小贩哪里善良了，看我饿的肚皮都贴一起了，也不给我点吃的，就知道对我发脾气。",
            ["ContentKR"] = "처음에는 그 상인들을 착하다고 말하는 걸 이해할 수 없었어. 내가 굶주리는데도 먹을 것도 안 주고, 화만 내던 사람들이니까.",
            ["DialogueId"] = 80090326,
            ["FacialId"] = {
                [1] = "92301:None",
                },
            ["GUID"] = "C87F6B1C",
            ["NextDialogue"] = 80090327,
            ["SpeakNpcId"] = 92301,
            ["TalkActionId"] = {
                [1] = "92301:Sit_Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/003/C87F6B1C",
            },
        [80090327] = {
            ["Content"] = "后来我才发现，有的小贩明明看见我拿东西吃，却没管我。",
            ["ContentKR"] = "근데 나중에 알고 보니, 어떤 상인은 내가 물건을 가져가는 걸 보고도 그냥 둔 거더라고.",
            ["DialogueId"] = 80090327,
            ["GUID"] = "C87F6B46",
            ["NextDialogue"] = 80090328,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/003/C87F6B46",
            },
        [80090328] = {
            ["Content"] = "追着我打的小贩们，好像也只是追几步就算了……当然了，也是因为本大盗逃得够快！",
            ["ContentKR"] = "나를 혼내겠다며 쫓아오던 상인도 얼마 안 쫓아오고는 그냥 가더라고... 물론, 그 사람들이 내 속도를 쫓아올 수 없겠지만 말이야!",
            ["DialogueId"] = 80090328,
            ["GUID"] = "C87F6B70",
            ["NextDialogue"] = 80090329,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/003/C87F6B70",
            },
        [80090329] = {
            ["Content"] = "有些摊主还会主动把没卖完的食物留给我，但我只当他们怕了我，那些食物统统是上贡给本大盗的保护费！",
            ["ContentKR"] = "어떤 상인은 팔고 남은 음식을 내게 주곤 했어. 나는 두려워서 내게 바치는 거로 생각했지만...",
            ["DialogueId"] = 80090329,
            ["GUID"] = "C87F6B9A",
            ["NextDialogue"] = 80090330,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/003/C87F6B9A",
            },
        [80090330] = {
            ["Content"] = "我只记得别人对我有多坏，却假装没看见这些好人。",
            ["ContentKR"] = "내가 사람들의 나쁜 모습만 기억하고, 좋은 모습은 못 본 척한 거야.",
            ["DialogueId"] = 80090330,
            ["GUID"] = "C87F6BC4",
            ["NextDialogue"] = 80090331,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/003/C87F6BC4",
            },
        [80090331] = {
            ["Content"] = "……想来想去，就觉得心里堵堵的，吃到嘴里的食物也不是滋味了。",
            ["ContentKR"] = "...다시 생각해도 가슴만 먹먹해지네. 입맛도 별로 없고...",
            ["DialogueId"] = 80090331,
            ["FacialId"] = {
                [1] = "92301:Sad01",
                },
            ["GUID"] = "C87F6BEE",
            ["NextDialogue"] = 80090332,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/003/C87F6BEE",
            },
        [80090332] = {
            ["Content"] = "我好像把对“坏大人”的恨，都报复到了这些小贩身上。",
            ["ContentKR"] = "난 이전의 '나쁜 어른'에게 당한 것 때문에 상인들에게 화풀이한 것 같아.",
            ["DialogueId"] = 80090332,
            ["GUID"] = "C87F6C18",
            ["NextDialogue"] = 80090333,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/003/C87F6C18",
            },
        [80090333] = {
            ["Content"] = "我真是个“恶魔”……",
            ["ContentKR"] = "난 정말 '악마'였어...",
            ["DialogueId"] = 80090333,
            ["GUID"] = "C87F6C42",
            ["NextOptions"] = {
                [1] = 80090334,
                [2] = 80090336,
                },
            ["SpeakNpcId"] = 92301,
            ["TalkActionId"] = {
                [1] = "92301:Sit_Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/003/C87F6C42",
            },
        [80090334] = {
            ["Content"] = "塔比瑟已经做得很好了，很多人用一生都未必能正视自己的错误。",
            ["ContentKR"] = "타비사는 이미 잘하고 있어. 대부분의 사람은 자신의 잘못을 평생 깨닫지 못하잖아.",
            ["DialogueId"] = 80090334,
            ["GUID"] = "C87F6C6C",
            ["NextDialogue"] = 80090335,
            },
        [80090335] = {
            ["Content"] = "谢谢你……唉，其实你不用安慰我的，错了就是错了。",
            ["ContentKR"] = "고마워... 휴, 위로하지 않아도 돼. 잘못한 건 잘못한 거니까.",
            ["DialogueId"] = 80090335,
            ["FacialId"] = {
                [1] = "92301:None",
                },
            ["GUID"] = "C87F6C96",
            ["NextDialogue"] = 80090338,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/003/C87F6C96",
            },
        [80090336] = {
            ["Content"] = "塔比瑟总有一天也会长大，如果一直欺负好人，不也成了坏大人的一员了吗？",
            ["ContentKR"] = "타비사도 언젠가는 어른이 될 텐데, 자꾸 착한 사람을 괴롭히면 나중에 타비사도 나쁜 어른이 되는 거 아냐?",
            ["DialogueId"] = 80090336,
            ["GUID"] = "C87F6CC0",
            ["NextDialogue"] = 80090337,
            },
        [80090337] = {
            ["Content"] = "你说的没错……唉，你骂吧，多骂几句，我会乖乖听着，不还嘴的。",
            ["ContentKR"] = "맞아... 더 많이 화내 줘. 말대꾸도 안 하고 얌전히 들을게.",
            ["DialogueId"] = 80090337,
            ["GUID"] = "C87F6CEA",
            ["NextDialogue"] = 80090338,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/003/C87F6CEA",
            },
        [80090338] = {
            ["Content"] = "之后我就一直拿坏小偷和坏大人的东西了，又威风，还不会伤害那些好人。",
            ["ContentKR"] = "그 뒤로 나는 도둑놈과 나쁜 어른의 물건만 훔쳤어. 그게 멋있기도 하고, 착한 사람에게 상처를 줄 일도 없으니까.",
            ["DialogueId"] = 80090338,
            ["FacialId"] = {
                [1] = "92301:Confident01",
                },
            ["GUID"] = "C87F6D14",
            ["NextDialogue"] = 80090339,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/003/C87F6D14",
            },
        [80090339] = {
            ["Content"] = "你还真别说，那些坏人可有钱了！我已经很少饿肚子了，偶尔再逗逗他们，看他们恼羞成怒的样子，嘻嘻嘻，日子过得可有趣了！",
            ["ContentKR"] = "그거 알아? 나쁜 사람은 전부 돈이 엄청 많아! 이제 나는 웬만해서는 굶지도 않고, 그냥 가끔 나쁜 사람을 약 올리고, 화내는 모습을 보기만 하지. 히히히, 하루하루가 너무 재밌어졌어!",
            ["DialogueId"] = 80090339,
            ["GUID"] = "C87F6D3E",
            ["NextOptions"] = {
                [1] = 80090340,
                },
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/003/C87F6D3E",
            },
        [80090340] = {
            ["Content"] = "想捉弄他们才是重点吧。",
            ["ContentKR"] = "그 사람들을 약 올리는 게 핵심인 것 같은데.",
            ["DialogueId"] = 80090340,
            ["GUID"] = "C87F6D68",
            ["NextDialogue"] = 80090341,
            },
        [80090341] = {
            ["Content"] = "没错！咳咳咳，才不是！这叫“为民除害”，他们长记性了，就知道欺负好人是不对的了。",
            ["ContentKR"] = "맞아! 크흠, 아니거든! 이건 나쁜 싹을 뽑는 거라고 말해야 해! 착한 사람을 괴롭히면 벌받는다는 걸 알려줘야지.",
            ["DialogueId"] = 80090341,
            ["GUID"] = "C87F6D92",
            ["NextDialogue"] = 80090342,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/003/C87F6D92",
            },
        [80090342] = {
            ["Content"] = "今天说了好多话，嗓子都冒烟了！",
            ["ContentKR"] = "오늘 말을 너무 많이 했나 봐, 목이 아프네!",
            ["DialogueId"] = 80090342,
            ["GUID"] = "C87F6DBC",
            ["NextDialogue"] = 80090343,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/003/C87F6DBC",
            },
        [80090343] = {
            ["Content"] = "嘻嘻嘻，刚才的蓝莓饮料，再来一杯嘛！",
            ["ContentKR"] = "헤헤, 방금 블루베리 음료, 한 잔 더 주면 안 될까!",
            ["DialogueId"] = 80090343,
            ["FacialId"] = {
                [1] = "92301:Smile02",
                },
            ["GUID"] = "C87F6DE6",
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/003/C87F6DE6",
            },
        [80090401] = {
            ["Camera"] = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
            ["Content"] = "真好喝！不管喝多少次都不会腻呢！本大盗可不经常夸人的，不过，还是谢谢你总是为我准备食物啦。",
            ["ContentKR"] = "음, 맛있어! 내가 칭찬은 잘 안 하는데, 계속 마셔도 질리지 않는 것 같아! 어쨌든, 맨날 이렇게 음식을 준비해 줘서 고마워.",
            ["DialogueId"] = 80090401,
            ["FacialId"] = {
                [1] = "92301:Smile01",
                },
            ["GUID"] = "C87F776A",
            ["LookAt"] = {
                [1] = "92301:p(18000P1)",
                },
            ["NextDialogue"] = 80090402,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/004/C87F776A",
            },
        [80090402] = {
            ["Content"] = "嘻嘻嘻，白喝了你这么多次饮料，难得让你也尝尝本大盗的手艺吧！",
            ["ContentKR"] = "헤헤, 그동안 얻어먹기만 했으니, 이번에는 내 솜씨를 발휘해 볼까!",
            ["DialogueId"] = 80090402,
            ["FacialId"] = {
                [1] = "92301:Smile02",
                },
            ["GUID"] = "C87F7794",
            ["NextDialogue"] = 80090403,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/004/C87F7794",
            },
        [80090403] = {
            ["Content"] = "你的面前放了一杯可疑的黑色液体，不断有小气泡涌上来，散发着一股诡异的味道，仔细看里面的沉淀物五花八门，能辨认出来的就有各种果干与糖果。",
            ["ContentKR"] = "앞에 수상한 검은 액체가 담긴 잔이 하나 놓였다. 작은 기포가 끊임없이 올라오고 이상한 냄새가 난다. 그 안에는 말린 과일과 사탕 조금을 제외하면 정체를 알 수 없는 것들로 가득하다.",
            ["DialogueId"] = 80090403,
            ["GUID"] = "C87F77BE",
            ["NextDialogue"] = 80090404,
            },
        [80090404] = {
            ["Content"] = "当当当！这就是塔比瑟的独家特调——和我共享同一个称号的“恶魔大盗”！嘻嘻嘻，我可是把我所有的感激之情都放在里面咯！",
            ["ContentKR"] = "짠! 이게 바로 이 타비사 님의 시그니처 메뉴인 '악마대도'야! 나와 같은 별명을 붙여줬지. 히히히, 너한테 고마운 마음을 모두 쏟아넣었다고!",
            ["DialogueId"] = 80090404,
            ["GUID"] = "C87F77E8",
            ["NextOptions"] = {
                [1] = 80090405,
                [2] = 80090410,
                },
            ["SpeakNpcId"] = 92301,
            ["TalkActionId"] = {
                [1] = "92301:Sit_Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/004/C87F77E8",
            },
        [80090405] = {
            ["Content"] = "不喝",
            ["ContentKR"] = "안 마신다",
            ["DialogueId"] = 80090405,
            ["GUID"] = "C87F7812",
            ["NextDialogue"] = 80090406,
            },
        [80090406] = {
            ["Content"] = "真没品味！这可是世界上仅此一杯的“恶魔大盗”！",
            ["ContentKR"] = "진짜 뭘 모르네! 이건 세상에 한 잔뿐인 '악마대도'라고!",
            ["DialogueId"] = 80090406,
            ["FacialId"] = {
                [1] = "92301:Unhappy01",
                },
            ["GUID"] = "C87F783C",
            ["NextDialogue"] = 80090407,
            ["SpeakNpcId"] = 92301,
            ["TalkActionId"] = {
                [1] = "92301:Sit_DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/004/C87F783C",
            },
        [80090407] = {
            ["Content"] = "里面的材料全都是好大人分享我的好东西，本大盗自己都舍不得吃，才一点点存到现在得，我都不敢想把他们放在一起有多美味！",
            ["ContentKR"] = "여기 들어간 재료는 모두 착한 어른이 나눠준 거야. 나 혼자 먹기 아까워서 챙겨둔 거라고. 그게 전부 들어갔으니 얼마나 맛있을까?!",
            ["DialogueId"] = 80090407,
            ["GUID"] = "C87F7866",
            ["NextDialogue"] = 80090408,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/004/C87F7866",
            },
        [80090408] = {
            ["Content"] = "这样吧！本大盗和你一人一半怎么样？咳咳，才不是我也想尝尝，只是为了给胆小鬼做个榜样！",
            ["ContentKR"] = "자, 그러면 같이 나눠 마시는 건 어때? 크흠, 내가 맛보고 싶은 건 아니고 네가 못 마시니까 내가 먼저 시범을 보여주려는 거야!",
            ["DialogueId"] = 80090408,
            ["FacialId"] = {
                [1] = "92301:Confident01",
                },
            ["GUID"] = "C87F7890",
            ["NextDialogue"] = 80090409,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/004/C87F7890",
            },
        [80090409] = {
            ["Content"] = "来，干杯！",
            ["ContentKR"] = "자, 짠!",
            ["DialogueId"] = 80090409,
            ["GUID"] = "C87F78BA",
            ["SpeakNpcId"] = 92301,
            ["TalkActionId"] = {
                [1] = "92301:Sit_Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/004/C87F78BA",
            },
        [80090410] = {
            ["Content"] = "喝",
            ["ContentKR"] = "마신다",
            ["DialogueId"] = 80090410,
            ["GUID"] = "C87F78E4",
            ["NextDialogue"] = 80090411,
            },
        [80090411] = {
            ["Content"] = "真有眼光！",
            ["ContentKR"] = "역시 보는 눈이 있네!",
            ["DialogueId"] = 80090411,
            ["FacialId"] = {
                [1] = "92301:Happy01",
                },
            ["GUID"] = "C87F790E",
            ["NextDialogue"] = 80090412,
            ["SpeakNpcId"] = 92301,
            ["TalkActionId"] = {
                [1] = "92301:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/004/C87F790E",
            },
        [80090412] = {
            ["Content"] = "里面的材料全都是好大人分享我的好东西，本大盗自己都舍不得吃，才一点点存到现在得，我都不敢想把他们放在一起有多美味！",
            ["ContentKR"] = "여기 들어간 재료는 모두 착한 어른이 나눠준 거야. 나 혼자 먹기 아까워서 챙겨둔 거라고. 그게 전부 들어갔으니 얼마나 맛있을까?!",
            ["DialogueId"] = 80090412,
            ["GUID"] = "C87F7938",
            ["NextDialogue"] = 80090413,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/004/C87F7938",
            },
        [80090413] = {
            ["Content"] = "这么珍贵的东西我要留给谁喝呢？想来想去果然只有你了。不过可不可以分我一点？嘻嘻，本大盗也很好奇“世界上最好喝的饮料”是什么味道嘛！",
            ["ContentKR"] = "이렇게 귀한 식재료를 누구와 나눌지 고민했는데, 역시 너뿐이더라고. 그런데 나도 조금만 마셔봐도 될까? 헤헤, 나도 '이 세상에서 가장 맛있는 음료수'가 어떤 맛일지 궁금하거든!",
            ["DialogueId"] = 80090413,
            ["GUID"] = "C87F7962",
            ["NextDialogue"] = 80090414,
            ["SpeakNpcId"] = 92301,
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/004/C87F7962",
            },
        [80090414] = {
            ["Content"] = "好啦好啦！害臊的话说到这里就可以啦，干杯！",
            ["ContentKR"] = "알겠어, 알겠다고! 부끄러우니까 여기까지만 하고 건배하는 거야!",
            ["DialogueId"] = 80090414,
            ["GUID"] = "C87F798C",
            ["SpeakNpcId"] = 92301,
            ["TalkActionId"] = {
                [1] = "92301:Sit_Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/004/C87F798C",
            },
        [80090415] = {
            ["Content"] = "你们一起喝下了塔比瑟的专属特调，诡异的甜味充斥着你的口腔，随后你就失去了意识。",
            ["ContentKR"] = "나와 타비사는 함께 음료수를 마셨다. 곧 기괴한 단맛이 입안을 가득 채웠고, 그렇게 의식을 잃는다.",
            ["DialogueId"] = 80090415,
            ["GUID"] = "C87F79B6",
            ["IsBlack"] = 1,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
            },
        [80090416] = {
            ["Camera"] = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
            ["Content"] = "还有气。只是睡过去了，两个都没事。",
            ["ContentKR"] = "아직 숨은 붙어있어, 둘 다 괜찮아. 그냥 잠에 든 것뿐이야.",
            ["DialogueId"] = 80090416,
            ["DisableMouth"] = 1,
            ["FacialId"] = {
                [1] = "92301:Close",
                },
            ["GUID"] = "C87F79E0",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 80090417,
            ["SpeakNpcId"] = 92301,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["TalkActionId"] = {
                [1] = "92301:Zhangyu_Story_Tentacle",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/004/C87F79E0",
            },
        [80090417] = {
            ["Content"] = "呜呜……吓死我了……早就和塔比瑟说了不要什么都往里放，出事了可怎么办……呜呜……",
            ["ContentKR"] = "흑흑... 깜짝 놀랐어... 이래서 타비사한테 음식에 아무거나 넣지 말라고, 사고 나면 어쩌냐고 했던 건데... 흑흑...",
            ["DialogueId"] = 80090417,
            ["DisableMouth"] = 1,
            ["GUID"] = "C87F7A0A",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 80090418,
            ["SpeakNpcId"] = 92301,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/004/C87F7A0A",
            },
        [80090418] = {
            ["Content"] = "嘻嘻嘻嘻，说不定会把脑袋喝坏，再出现奇奇怪怪的后遗症！",
            ["ContentKR"] = "히힛, 머리에 문제 생기거나, 이상한 후유증이 생길지도 몰라!",
            ["DialogueId"] = 80090418,
            ["DisableMouth"] = 1,
            ["GUID"] = "C87F7A34",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 80090419,
            ["SpeakNpcId"] = 92301,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/004/C87F7A34",
            },
        [80090419] = {
            ["Content"] = "乌鸦嘴，少说两句吧！",
            ["ContentKR"] = "조용히 해! 말이 씨가 될 수 있어.",
            ["DialogueId"] = 80090419,
            ["DisableMouth"] = 1,
            ["GUID"] = "C87F7A5E",
            ["IsBlack"] = 1,
            ["NextOptions"] = {
                [1] = 80090420,
                },
            ["SpeakNpcId"] = 92301,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/004/C87F7A5E",
            },
        [80090420] = {
            ["Content"] = "……谁？",
            ["ContentKR"] = "...누구야?",
            ["DialogueId"] = 80090420,
            ["GUID"] = "C87F7A88",
            ["NextDialogue"] = 80090421,
            },
        [80090421] = {
            ["Content"] = "你看到几条从塔比瑟身上延伸出来的触须正对着你轻柔地摇晃。",
            ["ContentKR"] = "타비사의 몸에서 나온 촉수가 날 향해 부드럽게 흔들렸다.",
            ["DialogueId"] = 80090421,
            ["DisableMouth"] = 1,
            ["GUID"] = "C87F7AB2",
            ["NextDialogue"] = 80090422,
            },
        [80090422] = {
            ["Content"] = "你们听到了吗？……{nickname}在和我们说话。",
            ["ContentKR"] = "너희도 들었어...? 우리에게 말한 거 같은데?",
            ["DialogueId"] = 80090422,
            ["DisableMouth"] = 1,
            ["GUID"] = "C87F7ADC",
            ["NextDialogue"] = 80090423,
            ["SpeakNpcId"] = 92301,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/004/C87F7ADC",
            },
        [80090423] = {
            ["Content"] = "据鄙人所知，只有塔比瑟才能听见我们说话吧？",
            ["ContentKR"] = "우리의 말소리는 타비사만 들을 수 있지 않나?",
            ["DialogueId"] = 80090423,
            ["DisableMouth"] = 1,
            ["GUID"] = "C87F7B06",
            ["NextDialogue"] = 80090424,
            ["SpeakNpcId"] = 92301,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/004/C87F7B06",
            },
        [80090424] = {
            ["Content"] = "……糟了糟了糟了，好像真的喝出毛病了！我就知道……每次5号说什么不好就应什么！算我求求你了，下次可千万别再张嘴了！",
            ["ContentKR"] = "...이런, 어쩌지! 역시 음료 때문에 문제가 생긴 건가? 5호가 불길한 말만 하면 꼭 현실이 된다니까! 제발, 그 입 좀 다물어!",
            ["DialogueId"] = 80090424,
            ["DisableMouth"] = 1,
            ["GUID"] = "C87F7B30",
            ["NextOptions"] = {
                [1] = 80090425,
                },
            ["SpeakNpcId"] = 92301,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/004/C87F7B30",
            },
        [80090425] = {
            ["Content"] = "触手……在说话……？",
            ["ContentKR"] = "촉수가... 말을 해...?",
            ["DialogueId"] = 80090425,
            ["GUID"] = "C87F7B5A",
            ["NextDialogue"] = 80090426,
            },
        [80090426] = {
            ["Content"] = "呃……你好？我们确实是塔比瑟的腕足，没想到会在这种情况下说上话！人生还真是猝不及防呀~哈、哈……",
            ["ContentKR"] = "어... 안녕? 우리는 타비사의 다리야. 이런 상황에서 이야기를 나누게 될 줄은 몰랐네! 인생은 참 한치 앞도 알 수 없다니까~ 하, 하하...",
            ["DialogueId"] = 80090426,
            ["DisableMouth"] = 1,
            ["GUID"] = "C87F7B84",
            ["NextDialogue"] = 80090427,
            ["SpeakNpcId"] = 92301,
            ["SpeakNpcName"] = "UI_Npc_Name_Wanzu6",
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/004/C87F7B84",
            },
        [80090427] = {
            ["Content"] = "那个……好像是那杯饮料的原因，你才会听到我们说话呜呜……给你喝到奇怪的东西真的很抱歉，但是塔比瑟和我们都不是故意的呜呜……",
            ["ContentKR"] = "그러니까... 아까 그 음료수 때문에 우리의 말을 듣을 수 있게 된 거 같은데... 이상한 걸 마시게 해서 미안해. 하지만 타비사랑 우리는 일부러 그런 게 아니야. 흑흑...",
            ["DialogueId"] = 80090427,
            ["DisableMouth"] = 1,
            ["GUID"] = "C87F7BAE",
            ["NextOptions"] = {
                [1] = 80090428,
                [2] = 80090429,
                },
            ["SpeakNpcId"] = 92301,
            ["SpeakNpcName"] = "UI_Npc_Name_Wanzu2",
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/004/C87F7BAE",
            },
        [80090428] = {
            ["Content"] = "塔比瑟没事吧？",
            ["ContentKR"] = "타비사는 괜찮아?",
            ["DialogueId"] = 80090428,
            ["GUID"] = "C87F7BD8",
            ["NextDialogue"] = 80090430,
            },
        [80090429] = {
            ["Content"] = "我没事吧？",
            ["ContentKR"] = "나, 괜찮은 거지?",
            ["DialogueId"] = 80090429,
            ["GUID"] = "C87F7C02",
            ["NextDialogue"] = 80090430,
            },
        [80090430] = {
            ["Content"] = "据鄙人观察，你们现在的反应只是因为一些——特别的食材。睡一觉就没事了！",
            ["ContentKR"] = "제가 보기엔 그저... 식재료가 특별해서 그런 것 같군요. 자고 일어나면 괜찮을 거예요!",
            ["DialogueId"] = 80090430,
            ["DisableMouth"] = 1,
            ["GUID"] = "C87F7C2C",
            ["NextDialogue"] = 80090431,
            ["SpeakNpcId"] = 92301,
            ["SpeakNpcName"] = "UI_Npc_Name_Wanzu3",
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/004/C87F7C2C",
            },
        [80090431] = {
            ["Content"] = "不过呢，咳咳——在本人的带领下，全体腕足同仁共同调制了大盗的这杯饮料，目的就是为了促成今日与阁下这场别开生面的会晤！",
            ["ContentKR"] = "다만, 크흠... 저의 인도 아래 모든 다리가 함께 완성한 이 음료수는 바로 오늘의 이 특별한 만남을 위해 만들어진 것이랍니다.",
            ["DialogueId"] = 80090431,
            ["DisableMouth"] = 1,
            ["GUID"] = "C87F7C56",
            ["NextDialogue"] = 80090432,
            ["SpeakNpcId"] = 92301,
            ["SpeakNpcName"] = "UI_Npc_Name_Wanzu3",
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/004/C87F7C56",
            },
        [80090432] = {
            ["Content"] = "啊？难道不是塔比瑟根本不懂调饮料，把漂亮蘑菇切成片泡进去导致的吗？",
            ["ContentKR"] = "그래? 타비사가 음료 만드는 법도 모르면서 예쁜 버섯을 넣어서 이렇게 된 거 아니었어?",
            ["DialogueId"] = 80090432,
            ["DisableMouth"] = 1,
            ["GUID"] = "C87F7C80",
            ["NextDialogue"] = 80090433,
            ["SpeakNpcId"] = 92301,
            ["SpeakNpcName"] = "UI_Npc_Name_Wanzu6",
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/004/C87F7C80",
            },
        [80090433] = {
            ["Content"] = "嘻嘻嘻，3号再摆架子你也会出现在这杯饮料里，嘻嘻嘻嘻……",
            ["ContentKR"] = "히힛... 3호, 자꾸 이상한 소리하면 너도 이 음료수 안에 넣어줄 줄 알아, 히히히힛...",
            ["DialogueId"] = 80090433,
            ["DisableMouth"] = 1,
            ["GUID"] = "C87F7CAA",
            ["NextDialogue"] = 80090434,
            ["SpeakNpcId"] = 92301,
            ["SpeakNpcName"] = "UI_Npc_Name_Wanzu5",
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/004/C87F7CAA",
            },
        [80090434] = {
            ["Content"] = "呜呜好可怕呀！",
            ["ContentKR"] = "흐엉, 너무 무서워!",
            ["DialogueId"] = 80090434,
            ["DisableMouth"] = 1,
            ["GUID"] = "C87F7CD4",
            ["NextDialogue"] = 80090435,
            ["SpeakNpcId"] = 92301,
            ["SpeakNpcName"] = "UI_Npc_Name_Wanzu2",
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/004/C87F7CD4",
            },
        [80090435] = {
            ["Content"] = "别嚷了……你们不累吗……还有，别吓着人家{nickname}……",
            ["ContentKR"] = "조용히 해... 너흰 지치지도 않냐... 그리고, {nickname} 놀라게 하지 마...",
            ["DialogueId"] = 80090435,
            ["DisableMouth"] = 1,
            ["GUID"] = "C87F7CFE",
            ["NextOptions"] = {
                [1] = 80090436,
                },
            ["SpeakNpcId"] = 92301,
            ["SpeakNpcName"] = "UI_Npc_Name_Wanzu4",
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/004/C87F7CFE",
            },
        [80090436] = {
            ["Content"] = "懂了，人在梦里，正在发昏。",
            ["ContentKR"] = "아, 그래. 여긴 꿈속이구나.",
            ["DialogueId"] = 80090436,
            ["GUID"] = "C87F7D28",
            ["NextDialogue"] = 80090437,
            },
        [80090437] = {
            ["Content"] = "当成梦倒是也可以，只是不知道饮料的效果会持续到什么时候……不过我们其实有很多话想和你说！不如趁此机会……1号，你先来！",
            ["ContentKR"] = "꿈이라고 생각해도 돼. 그나저나 이게 언제까지 지속될지 모르겠네... 사실 우리는 너와 하고 싶은 말이 엄청 많거든! 이번 기회에 다 해볼까... 1호, 너 먼저 해!",
            ["DialogueId"] = 80090437,
            ["DisableMouth"] = 1,
            ["GUID"] = "C87F7D52",
            ["NextDialogue"] = 80090438,
            ["SpeakNpcId"] = 92301,
            ["SpeakNpcName"] = "UI_Npc_Name_Wanzu6",
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/004/C87F7D52",
            },
        [80090438] = {
            ["Content"] = "……我的意识诞生在大海上，海难刚刚发生，我和塔比瑟在海里漂流，随时可能死去。她靠和我说话，渡过了那段时间。",
            ["ContentKR"] = "...나의 의식은 바다에서 생겨났어. 사고가 일어난 후, 나와 타비사는 바다 위를 표류 중이라 언제 죽어도 이상하지 않았어. 하지만 내가 말동무가 되어주며, 타비사가 그 힘든 시간을 버틸 수 있었지.",
            ["DialogueId"] = 80090438,
            ["DisableMouth"] = 1,
            ["GUID"] = "C87F7D7C",
            ["NextDialogue"] = 80090439,
            ["SpeakNpcId"] = 92301,
            ["SpeakNpcName"] = "UI_Npc_Name_Wanzu1",
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/004/C87F7D7C",
            },
        [80090439] = {
            ["Content"] = "我我我苏醒在孤儿院里，那段时间塔比瑟刚到了新地方，大人都对她很不好，她又害怕又要强，不愿在任何人面前示弱，到了晚上才会抱着我一直发抖……",
            ["ContentKR"] = "나, 나는 보육원에서 깨어났어. 그때 타비사는 그곳에 막 도착한 참이었는데, 어른들은 모두 그 애한테 심술궂게 굴었어. 타비사는 무서워했지만 고집이 세서 누구 앞에서도 약한 모습을 보이기 싫어했어. 하지만 밤만 되면 나를 꼭 껴안고 무서움에 계속 떨곤 했지...",
            ["DialogueId"] = 80090439,
            ["DisableMouth"] = 1,
            ["GUID"] = "C87F7DA6",
            ["NextDialogue"] = 80090440,
            ["SpeakNpcId"] = 92301,
            ["SpeakNpcName"] = "UI_Npc_Name_Wanzu2",
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/004/C87F7DA6",
            },
        [80090440] = {
            ["Content"] = "鄙人是在孤儿院的厨房加入这个团队的，危急关头，正是在鄙人的及时指挥下，我们得以躲开巡逻的守卫，获得了半块面包的战果！",
            ["ContentKR"] = "저는 보육원 주방에서 이 팀에 합류했습니다. 위기의 순간, 저의 지휘 덕분에 순찰하는 경비를 피해 무사히 빵 반쪽을 전리품으로 얻을 수 있었지요!",
            ["DialogueId"] = 80090440,
            ["DisableMouth"] = 1,
            ["GUID"] = "C87F7DD0",
            ["NextDialogue"] = 80090441,
            ["SpeakNpcId"] = 92301,
            ["SpeakNpcName"] = "UI_Npc_Name_Wanzu3",
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/004/C87F7DD0",
            },
        [80090441] = {
            ["Content"] = "至于鄙人的说话方式，正是孤儿院长的完美复现。",
            ["ContentKR"] = "제 말투는... 보육원 원장을 완벽하게 재현한 것입니다.",
            ["DialogueId"] = 80090441,
            ["DisableMouth"] = 1,
            ["GUID"] = "C87F7DFA",
            ["NextDialogue"] = 80090442,
            ["SpeakNpcId"] = 92301,
            ["SpeakNpcName"] = "UI_Npc_Name_Wanzu3",
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/004/C87F7DFA",
            },
        [80090442] = {
            ["Content"] = "哈欠……好困……我是在逃出孤儿院的晚上醒来的，劫后余生的感觉好重……好重……重到一到安全的地方，我就和她一起在草地上睡着了……",
            ["ContentKR"] = "흐아암... 졸려... 난 보육원에서 탈출하던 날 밤에 깨어났어. 죽다 살아난 느낌이 얼마나 버겁고... 버겁던지... 너무 버거워서 안전한 곳에 도착하자마자 우리는 잔디 위에서 바로 잠들어 버렸어...",
            ["DialogueId"] = 80090442,
            ["DisableMouth"] = 1,
            ["GUID"] = "C87F7E24",
            ["NextDialogue"] = 80090443,
            ["SpeakNpcId"] = 92301,
            ["SpeakNpcName"] = "UI_Npc_Name_Wanzu4",
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/004/C87F7E24",
            },
        [80090443] = {
            ["Content"] = "嘻嘻嘻，然后就是我了！我是塔比瑟最好的战友！一起打家劫舍的感觉真是爽飞啦！呜呼！",
            ["ContentKR"] = "히힛, 이제 내 차례인가! 나는 타비사 최고의 전우! 함께하는 도둑질은 언제나 짜릿해! 와우!",
            ["DialogueId"] = 80090443,
            ["DisableMouth"] = 1,
            ["GUID"] = "C87F7E4E",
            ["NextDialogue"] = 80090444,
            ["SpeakNpcId"] = 92301,
            ["SpeakNpcName"] = "UI_Npc_Name_Wanzu5",
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/004/C87F7E4E",
            },
        }
  end },
  { MinKey = 80090444, MaxKey = 80110303, Loader = function()
      return {
        [80090444] = {
            ["Content"] = "你给我适可而止！不好意思啊这孩子还是不太懂事！咳咳，接下来就是我啦！我是大家中最小的那个，有意识还是最近的事。",
            ["ContentKR"] = "적당히 해! 미안, 얘가 아직 철이 덜 들었어! 크흠, 드디어 내 차례네! 난 막내야. 최근에 의식이 생겼거든.",
            ["DialogueId"] = 80090444,
            ["DisableMouth"] = 1,
            ["GUID"] = "C87F7E78",
            ["NextDialogue"] = 80090445,
            ["SpeakNpcId"] = 92301,
            ["SpeakNpcName"] = "UI_Npc_Name_Wanzu6",
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/004/C87F7E78",
            },
        [80090445] = {
            ["Content"] = "其实很早之前我醒过一次，但因为那个卖鱼的小姑娘最终和塔比瑟分开了，她嘴上不说，其实非常伤心，连带我也沉湎着那段时光，睡过去了，不愿苏醒。",
            ["ContentKR"] = "사실 훨씬 전에 한 번 깨어난 적이 있어. 다만 생선을 팔던 아이와 헤어졌을 때 타비사가 말은 안 했지만 정말 힘들어했거든. 심지어 나도 현실을 마주하기 싫을 정도라서 다시 잠에 들었어.",
            ["DialogueId"] = 80090445,
            ["DisableMouth"] = 1,
            ["GUID"] = "C87F7EA2",
            ["NextDialogue"] = 80090446,
            ["SpeakNpcId"] = 92301,
            ["SpeakNpcName"] = "UI_Npc_Name_Wanzu6",
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/004/C87F7EA2",
            },
        [80090446] = {
            ["Content"] = "直到她又一次遇见了真心以待的人——是的，我是因为你而醒来的。",
            ["ContentKR"] = "그러다가 타비사가 진심으로 대하는 새로운 사람이 나타났지... 맞아, 난 너 덕분에 깨어난 거야.",
            ["DialogueId"] = 80090446,
            ["DisableMouth"] = 1,
            ["GUID"] = "C87F7ECC",
            ["NextDialogue"] = 80090447,
            ["SpeakNpcId"] = 92301,
            ["SpeakNpcName"] = "UI_Npc_Name_Wanzu6",
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/004/C87F7ECC",
            },
        [80090447] = {
            ["Content"] = "感谢你对塔比瑟的照顾，那股暖洋洋的善意让我不再做梦，也是在我的建议下，她才决定做一杯饮料感谢你的。",
            ["ContentKR"] = "그동안 타비사를 보살펴줘서 고마워. 너의 따뜻한 마음 덕분에 내가 깨어날 수 있었어. 고마운 마음을 담아 너에게 음료수를 만들어 주자는 것도 나의 제안이었어.",
            ["DialogueId"] = 80090447,
            ["DisableMouth"] = 1,
            ["GUID"] = "C87F7EF6",
            ["NextDialogue"] = 80090448,
            ["SpeakNpcId"] = 92301,
            ["SpeakNpcName"] = "UI_Npc_Name_Wanzu6",
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/004/C87F7EF6",
            },
        [80090448] = {
            ["Content"] = "但没想到那孩子下手一点儿轻重都没有啊啊啊！她根本不懂调饮料，就在那儿逮着什么放什么——还有你们，3号和5号，你们也在那撺掇她！",
            ["ContentKR"] = "하지만 그래도 음료를 그렇게까지 마구잡이로 만들 줄은 몰랐지, 으아아! 음료 만드는 법도 모르면서, 닥치는 대로 아무거나 넣더라니까... 그리고 3호랑 5호, 너희도 계속 옆에서 부추긴 거 다 알고 있어!",
            ["DialogueId"] = 80090448,
            ["DisableMouth"] = 1,
            ["GUID"] = "C87F7F20",
            ["NextDialogue"] = 80090449,
            ["SpeakNpcId"] = 92301,
            ["SpeakNpcName"] = "UI_Npc_Name_Wanzu6",
            ["VoiceName"] = "voice/$Locale$/inv/Zhangyu/004/C87F7F20",
            },
        [80090449] = {
            ["Content"] = "不好意思哈，不好意思……",
            ["ContentKR"] = "미안해, 정말 미안해...",
            ["DialogueId"] = 80090449,
