            },
        [80110229] = {
            ["Camera"] = "14.200928,-236.600464,163.609055,-0.0,-7.599944,97.395355,35.0,180.0,false,Manual,2.8",
            ["Content"] = "而且，我也不想失去一个……至少可以说点真心话的家伙。",
            ["ContentKR"] = "게다가, 나도... 적어도 진심을 좀 털어놓을 수 있는 사람을 잃고 싶지 않아.",
            ["DialogueId"] = 80110229,
            ["FinalCamera"] = "12.948349,-226.679688,163.609055,0.000001,-7.599944,97.195381,35.0,130.0,false,Manual,2.8",
            ["GUID"] = "C88C2C72",
            ["NextDialogue"] = 80110230,
