  { MinKey = 80110304, MaxKey = 80120439, Loader = function()
      return {
        [80110304] = {
            ["Content"] = "行吧，也有道理。那就告诉你吧，里面是一把枪，还有一张面具。",
            ["ContentKR"] = "그래, 일리는 있네. 그럼 말해줄게. 안에는 총 한 자루랑 가면 하나가 들어있어.",
            ["DialogueId"] = 80110304,
            ["FacialId"] = {
                [1] = "93101:Smile01",
                },
            ["GUID"] = "C88C38C0",
            ["NextDialogue"] = 80110305,
            ["SpeakNpcId"] = 93101,
            ["TalkActionId"] = {
                [1] = "93101:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Linen/003/C88C38C0",
            },
        [80110305] = {
            ["Content"] = "别那么紧张，是玩具枪。不放心的话，你可以拿它打我。",
            ["ContentKR"] = "그렇게 긴장하지 마, 장난감 총이야. 믿기지 않으면 날 쏴봐.",
            ["DialogueId"] = 80110305,
            ["FacialId"] = {
                [1] = "93101:Iyada01",
                },
            ["GUID"] = "C88C38EA",
            ["NextOptions"] = {
                [1] = 801103051,
                },
            ["SpeakNpcId"] = 93101,
            ["VoiceName"] = "voice/$Locale$/inv/Linen/003/C88C38EA",
            },
        [80110306] = {
            ["Content"] = "（砰——）",
            ["ContentKR"] = "(탕—)",
            ["DialogueId"] = 80110306,
            ["GUID"] = "C88C3914",
            ["NextDialogue"] = 80110307,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_toysshot\"},PlayAs2D{true}}",
            ["VoiceName"] = "voice/$Locale$/inv/Linen/003/C88C3914",
            },
        [80110307] = {
            ["Content"] = "哎呦哎呦，疼疼疼！假子弹也会疼的，你别对着额头打啊！你给我过来，让我弹一下脑壳！*的，下手真重。",
            ["ContentKR"] = "아야야, 아파! 가짜 총알이라도 아프다고, 이마에 쏘지 마! 이리 와봐, 내가 네 대가리 한 번 때려줄 테니까! 씨*, 왜 이렇게 세게 쏘냐.",
            ["DialogueId"] = 80110307,
            ["FacialId"] = {
                [1] = "93101:Sad01",
                },
            ["GUID"] = "C88C393E",
            ["NextDialogue"] = 80110308,
            ["Scripts"] = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_toysshot\"},PlayAs2D{true}}",
            ["SpeakNpcId"] = 93101,
            ["VoiceName"] = "voice/$Locale$/inv/Linen/003/C88C393E",
            },
        [80110308] = {
            ["Content"] = "唉，你这么一来倒是让我想起来了，小时候我和里奥拉打架的时候，也是拿着弹弓瞄着对方脑袋打，现在想来，没死也是运气好。这枪……就是送给她的。",
            ["ContentKR"] = "하, 네가 이러니까 생각나네. 어렸을 때 나랑 리오라가 싸울 때도 새총으로 서로 머리 겨냥해서 쏘고 그랬어. 지금 생각해보면 안 죽은 게 다행이지. 이 총이... 바로 리오라한테 주는 거야.",
            ["DialogueId"] = 80110308,
            ["GUID"] = "C88C3968",
            ["NextOptions"] = {
                [1] = 801103081,
                },
            ["SpeakNpcId"] = 93101,
            ["VoiceName"] = "voice/$Locale$/inv/Linen/003/C88C3968",
            },
        [80110309] = {
            ["Content"] = "嗯，算是吧……这次出任务要来冰湖城，就想着还是得带点什么。",
            ["ContentKR"] = "음, 그렇다고 볼 수 있지... 이번에 임무로 아이스레이크 시티에 오게 됐으니까, 뭔가 가져가야겠다고 생각했어.",
            ["DialogueId"] = 80110309,
            ["FacialId"] = {
                [1] = "93101:None",
                },
            ["GUID"] = "C88C3992",
            ["NextDialogue"] = 80110310,
            ["SpeakNpcId"] = 93101,
            ["TalkActionId"] = {
                [1] = "93101:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Linen/003/C88C3992",
            },
        [80110310] = {
            ["Content"] = "啰啰嗦嗦问这么多，到底干还是不干啊？不干我找其他狩月人了。",
            ["ContentKR"] = "이것저것 물어보느라 시간만 보내네, 결국 할 거야 말 거야? 안 할거면 다른 월석 사냥꾼을 찾아볼게.",
            ["DialogueId"] = 80110310,
            ["GUID"] = "C88C39BC",
            ["NextOptions"] = {
                [1] = 801103101,
                },
            ["SpeakNpcId"] = 93101,
            ["VoiceName"] = "voice/$Locale$/inv/Linen/003/C88C39BC",
            },
        [80110311] = {
            ["Content"] = "我去？算了吧，要不是长官派我来，我才不会回冰湖城这地方。",
            ["ContentKR"] = "내가 가? 됐어. 상관이 보내지 않았다면 난 아이스레이크 시티 같은 곳엔 절대 안 왔을 거야.",
            ["DialogueId"] = 80110311,
            ["FacialId"] = {
                [1] = "93101:Sad01",
                },
            ["GUID"] = "C88C39E6",
            ["NextOptions"] = {
                [1] = 801103111,
                [2] = 801103112,
                },
            ["SpeakNpcId"] = 93101,
            ["TalkActionId"] = {
                [1] = "93101:Sit_DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Linen/003/C88C39E6",
            },
        [80110312] = {
            ["Content"] = "嘁，少挖苦我。",
            ["ContentKR"] = "흥, 비꼬지 마.",
            ["DialogueId"] = 80110312,
            ["FacialId"] = {
                [1] = "93101:None",
                },
            ["GUID"] = "C88C3A10",
            ["NextDialogue"] = 80110313,
            ["SpeakNpcId"] = 93101,
            ["TalkActionId"] = {
                [1] = "93101:Sit_Talk02R_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Linen/003/C88C3A10",
            },
        [80110313] = {
            ["Content"] = "之前也不是没回来过，想着能找那些小时候一起掏过鸟窝偷过土豆的朋友喝上几杯。只聊聊过去那些傻事，把自己从军团里拽出来一些。",
            ["ContentKR"] = "전에도 한 번 와봤어. 어렸을 때 같이 새 둥지 뒤지고 감자 훔치던 친구들이랑 술 한잔 하면서 옛날 얘기나 할까 했지. 그냥 그때 바보 같았던 일들 얘기하면서 잠깐이라도 군단에서 벗어나고 싶었어.",
            ["DialogueId"] = 80110313,
            ["GUID"] = "C88C3A3A",
            ["NextDialogue"] = 80110314,
            ["SpeakNpcId"] = 93101,
            ["TalkActionId"] = {
                [1] = "93101:Sit_Talk02R_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Linen/003/C88C3A3A",
            },
        [80110314] = {
            ["Content"] = "结果呢，那些家伙也不知道从哪儿听说了我要回来，早就列好了队，等我回来的时候远远敬起了礼，一起叫着“琳恩长官”，连屋顶的鸟都被吓飞了。",
            ["ContentKR"] = "근데 어떻게 됐게? 그 녀석들이 어디서 내가 온다는 걸 들었는지 미리 줄까지 서 있더라고. 내가 오니까 멀리서 경례하면서 다 같이 \"린 님\"하고 부르는데 지붕 위의 새들까지 놀라서 날아가더라.",
            ["DialogueId"] = 80110314,
            ["GUID"] = "C88C3A64",
            ["NextDialogue"] = 80110315,
            ["SpeakNpcId"] = 93101,
            ["VoiceName"] = "voice/$Locale$/inv/Linen/003/C88C3A64",
            },
        [80110315] = {
            ["Content"] = "本来我还想着，即便和他们生疏了一点，但聊聊过去一起在大街上撒欢跑的日子，总会拉近距离的。",
            ["ContentKR"] = "사실 지금은 서로 좀 어색해졌더라도 예전에 거리에서 뛰어놀던 얘기라도 하면 다시 가까워질 줄 알았는데.",
            ["DialogueId"] = 80110315,
            ["GUID"] = "C88C3A8E",
            ["NextDialogue"] = 80110316,
            ["SpeakNpcId"] = 93101,
            ["TalkActionId"] = {
                [1] = "93101:Sit_Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Linen/003/C88C3A8E",
            },
        [80110316] = {
            ["Content"] = "结果我那几个朋友啊，根本没给我说这些话的机会，一个个点头哈腰，头都快低到脚尖去了，连个正眼都不给我。",
            ["ContentKR"] = "근데 그 친구들이 내가 그런 말 할 기회조차 주지 않더라고. 허리 굽혀 인사하느라 머리가 발끝에 닿을 것 같았어. 나랑 눈도 제대로 마주치지 않더라.",
            ["DialogueId"] = 80110316,
            ["GUID"] = "C88C3AB8",
            ["NextOptions"] = {
                [1] = 801103161,
                },
            ["SpeakNpcId"] = 93101,
            ["TalkActionId"] = {
                [1] = "93101:Sit_Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Linen/003/C88C3AB8",
            },
        [80110317] = {
            ["Content"] = "正常啊。我从小到大见多了这些事，太明白他们为什么怕我了。要不是我干了这一行，看到士兵打哆嗦的就得是我了。",
            ["ContentKR"] = "당연히 정상이지. 어렸을 때부터 이런 거 많이 봐왔거든. 그들이 왜 나를 무서워하는지 너무 잘 알지. 내가 이 일을 하지 않았다면 나부터도 군인만 봐도 덜덜 떨고 있었을 거야.",
            ["DialogueId"] = 80110317,
            ["FacialId"] = {
                [1] = "93101:Smile01",
                },
            ["GUID"] = "C88C3AE2",
            ["NextDialogue"] = 80110318,
            ["SpeakNpcId"] = 93101,
            ["TalkActionId"] = {
                [1] = "93101:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Linen/003/C88C3AE2",
            },
        [80110318] = {
            ["Content"] = "冰湖城……不，海伯利亚一直如此。拳头大的欺负拳头小的，富有的作践贫穷的……从我小时候就是这样，到现在也没变过。",
            ["ContentKR"] = "아이스레이크 시티... 아니, 휘페르보레아는 늘 그래왔어. 힘 있는 자가 약한 자를 괴롭히고, 부자가 가난한 자를 짓밟고... 내가 어렸을 때부터 그랬고, 지금도 변한 게 없어.",
            ["DialogueId"] = 80110318,
            ["GUID"] = "C88C3B0C",
            ["NextDialogue"] = 80110319,
            ["SpeakNpcId"] = 93101,
            ["VoiceName"] = "voice/$Locale$/inv/Linen/003/C88C3B0C",
            },
        [80110319] = {
            ["Content"] = "哎，你知道这把枪和面具是干什么用的吗？",
            ["ContentKR"] = "있잖아, 이 총이랑 가면이 뭐에 쓰이는지 알아?",
            ["DialogueId"] = 80110319,
            ["GUID"] = "C88C3B36",
            ["NextDialogue"] = 80110320,
            ["SpeakNpcId"] = 93101,
            ["TalkActionId"] = {
                [1] = "93101:Sit_Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Linen/003/C88C3B36",
            },
        [80110320] = {
            ["Content"] = "我和里奥拉小时候一起看了一本连环画，讲的是一个叫“卢布朗”的侠盗的故事。卢布朗从坏心肠的富人宅子里偷来宝贝，分给穷人。人们都叫他“面具英雄”。",
            ["ContentKR"] = "내가 어렸을 때 리오라랑 같이 만화책을 봤는데, '루팡'이란 의적 얘기였어. 루팡은 나쁜 부자들 집에서 보물을 훔쳐다 가난한 사람들한테 나눠줬지. 사람들은 그를 '가면의 영웅'이라고 불렀어.",
            ["DialogueId"] = 80110320,
            ["GUID"] = "C88C3B60",
            ["NextDialogue"] = 80110321,
            ["SpeakNpcId"] = 93101,
            ["TalkActionId"] = {
                [1] = "93101:Sit_Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Linen/003/C88C3B60",
            },
        [80110321] = {
            ["Content"] = "那时我和里奥拉用废纸板做成面具戴在脸上，用弹弓当手枪，跑到冰湖城的城墙上，大声喊卢布朗在连环画里的台词，一点也不觉得脸红。",
            ["ContentKR"] = "그때 우리는 폐지로 가면을 만들어 쓰고 새총을 총처럼 들고 아이스레이크 시티 성벽 위로 올라가서 루팡이 만화에서 하던 말을 큰 소리로 외쳤어. 전혀 부끄럽지 않았지.",
            ["DialogueId"] = 80110321,
            ["FacialId"] = {
                [1] = "93101:Syouganai01",
                },
            ["GUID"] = "C88C3B8A",
            ["NextDialogue"] = 80110322,
            ["SpeakNpcId"] = 93101,
            ["VoiceName"] = "voice/$Locale$/inv/Linen/003/C88C3B8A",
            },
        [80110322] = {
            ["Content"] = "因为那时候我们两个觉得我们……迟早有一天……也能成为“英雄”。",
            ["ContentKR"] = "그때는 우리 둘 다... 언젠가는... 우리도 '영웅'이 될 수 있을 거라고 생각했거든.",
            ["DialogueId"] = 80110322,
            ["FacialId"] = {
                [1] = "93101:None",
                },
            ["GUID"] = "C88C3BB4",
            ["NextDialogue"] = 80110323,
            ["SpeakNpcId"] = 93101,
            ["VoiceName"] = "voice/$Locale$/inv/Linen/003/C88C3BB4",
            },
        [80110323] = {
            ["Content"] = "很多年后，迪斯玛尼亚的一家商店里，我见到了更精美的卢布朗面具和玩具手枪，和真的一样。我就掏钱买了下来。",
            ["ContentKR"] = "여러 해가 지나고 디즈마니아의 어떤 가게에서 더 정교한 루팡 가면이랑 장난감 권총을 봤어. 진짜 같더라고. 그래서 돈 주고 샀지.",
            ["DialogueId"] = 80110323,
            ["GUID"] = "C88C3BDE",
            ["NextDialogue"] = 80110324,
            ["SpeakNpcId"] = 93101,
            ["TalkActionId"] = {
                [1] = "93101:Sit_Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Linen/003/C88C3BDE",
            },
        [80110324] = {
            ["Content"] = "“虽然我已经变成了一个只会对卡戎开枪的坏人，但至少里奥拉还有成为‘英雄’的机会”……那时，我是这样想的。",
            ["ContentKR"] = "\"내가 이제 카론에게만 총 쏘는 나쁜 놈이 됐어도 적어도 리오라는 아직 '영웅'이 될 기회가 있겠지\"... 그때는 그렇게 생각했어.",
            ["DialogueId"] = 80110324,
            ["FacialId"] = {
                [1] = "93101:Smile01",
                },
            ["GUID"] = "C88C3C08",
            ["NextDialogue"] = 80110325,
            ["SpeakNpcId"] = 93101,
            ["TalkActionId"] = {
                [1] = "93101:Sit_Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Linen/003/C88C3C08",
            },
        [80110325] = {
            ["Content"] = "……直到她在冰湖城看到我时抖得像条畏畏缩缩的鹅，她喊我也从“琳恩”变成了“琳恩长官”，我就知道，她和我一样，都回不去了。",
            ["ContentKR"] = "...그런데 리오라가 아이스레이크 시티에서 날 봤을 때 겁에 질린 거위처럼 떨더라고. 날 부를 때도 '린'이 아니라 '린 님'이라고 하더라. 그때 알았지, 리오라도 나처럼 돌아갈 수 없게 됐다는 걸.",
            ["DialogueId"] = 80110325,
            ["GUID"] = "C88C3C32",
            ["NextDialogue"] = 80110326,
            ["SpeakNpcId"] = 93101,
            ["VoiceName"] = "voice/$Locale$/inv/Linen/003/C88C3C32",
            },
        [80110326] = {
            ["Content"] = "……唉，头疼，再来一杯！",
            ["ContentKR"] = "...아, 머리 아파. 한 잔 더!",
            ["DialogueId"] = 80110326,
            ["FacialId"] = {
                [1] = "93101:Syouganai01",
                },
            ["GUID"] = "C88C3C5C",
            ["NextDialogue"] = 80110327,
            ["SpeakNpcId"] = 93101,
            ["VoiceName"] = "voice/$Locale$/inv/Linen/003/C88C3C5C",
            },
        [80110327] = {
            ["Content"] = "就是因为这些破事，我一点也不想回冰湖城。甚至连自己的亲弟弟亲妹妹，我都不想见。远远看一眼，知道他们还活着，又长高了，过得还不错，就够了。",
            ["ContentKR"] = "이런 쓰레기 같은 일들 때문에 아이스레이크 시티에 돌아가고 싶지 않아. 심지어 친동생들조차 보고 싶지 않더라. 멀리서 한 번 봐서 살아있다는 것, 키가 좀 컸다는 것, 그럭저럭 잘 살고 있다는 걸 아는 것만으로도 충분해.",
            ["DialogueId"] = 80110327,
            ["FacialId"] = {
                [1] = "93101:None",
                },
            ["GUID"] = "C88C3C86",
            ["NextOptions"] = {
                [1] = 801103271,
                },
            ["SpeakNpcId"] = 93101,
            ["TalkActionId"] = {
                [1] = "93101:Sit_DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Linen/003/C88C3C86",
            },
        [80110328] = {
            ["Content"] = "不，相反。他们总是在信里写，他们很想我，希望我多来看看他们。",
            ["ContentKR"] = "아니, 오히려 반대야. 그들은 항상 편지에 날 보고 싶어 하고 자주 와달라고 쓰지.",
            ["DialogueId"] = 80110328,
            ["FacialId"] = {
                [1] = "93101:Iyada01",
                },
            ["GUID"] = "C88C3CB0",
            ["NextDialogue"] = 80110329,
            ["SpeakNpcId"] = 93101,
            ["VoiceName"] = "voice/$Locale$/inv/Linen/003/C88C3CB0",
            },
        [80110329] = {
            ["Content"] = "但是就算看到他们，我又能对他们说什么？说我又看见了炼金院的什么实验？还是说我又俘虏了几个卡戎人？",
            ["ContentKR"] = "하지만 가족을 보러 가도 내가 뭘 말할 수 있겠어? 연금원에서 어떤 실험을 봤다고? 아니면 또 카론을 몇 명 잡아왔다고?",
            ["DialogueId"] = 80110329,
            ["GUID"] = "C88C3CDA",
            ["NextDialogue"] = 80110330,
            ["SpeakNpcId"] = 93101,
            ["TalkActionId"] = {
                [1] = "93101:Sit_Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Linen/003/C88C3CDA",
            },
        [80110330] = {
            ["Content"] = "……算了算了，每个人都有自己苦恼的破事，这太他*正常了。",
            ["ContentKR"] = "...에잇, 됐어. 누구나 다 고민거리는 있는 법이지. 이건 너무나 당연한 거야.",
            ["DialogueId"] = 80110330,
            ["FacialId"] = {
                [1] = "93101:None",
                },
            ["GUID"] = "C88C3D04",
            ["NextOptions"] = {
                [1] = 801103301,
                },
            ["SpeakNpcId"] = 93101,
            ["TalkActionId"] = {
                [1] = "93101:Sit_Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Linen/003/C88C3D04",
            },
        [80110331] = {
            ["Content"] = "这本应该是一个你想回家就回家的世界……或者说，我们这代人应该让它变成一个你想回家就回家的世界。",
            ["ContentKR"] = "이건 네가 집에 가고 싶을 때 갈 수 있는 세상이어야 해... 아니, 우리 세대가 그런 세상을 만들어야 한다고 봐.",
            ["DialogueId"] = 80110331,
            ["GUID"] = "C88C3D2E",
            ["NextDialogue"] = 80110332,
            ["SpeakNpcName"] = "UI_Npc_Name_Nvzhu",
            ["VoiceName"] = "voice/$Locale$/inv/Linen/003/C88C3D2E",
            },
        [80110332] = {
            ["Content"] = "也只有像你这样的外来人会觉得这些不正常，觉得这些是可以改变的。",
            ["ContentKR"] = "너 같은 외부인만 이런 게 비정상이라고 생각하고, 바뀔 수 있다고 여기는 거야.",
            ["DialogueId"] = 80110332,
            ["GUID"] = "C88C3D58",
            ["NextDialogue"] = 80110333,
            ["SpeakNpcId"] = 93101,
            ["VoiceName"] = "voice/$Locale$/inv/Linen/003/C88C3D58",
            },
        [80110333] = {
            ["Content"] = "你是不是还想着有一天，卡戎之民能够和索拉之民友好相处，不会再因为奇怪的角，奇怪的脊椎，奇怪的法术而受到不同的对待？",
            ["ContentKR"] = "혹시 너는 언젠가 카론과 솔라가 우호적으로 지내고, 이상한 뿔이나 척추, 이상한 마법 때문에 차별받지 않을 거라고 생각하나 봐?",
            ["DialogueId"] = 80110333,
            ["GUID"] = "C88C3D82",
            ["NextDialogue"] = 80110334,
            ["SpeakNpcId"] = 93101,
            ["TalkActionId"] = {
                [1] = "93101:Sit_Talk02R_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Linen/003/C88C3D82",
            },
        [80110334] = {
            ["Content"] = "说不定呢？",
            ["ContentKR"] = "그럴지도 모르지.",
            ["DialogueId"] = 80110334,
            ["GUID"] = "C88C3DAC",
            ["NextDialogue"] = 80110335,
            ["SpeakNpcName"] = "UI_Npc_Name_Nvzhu",
            ["TalkActionId"] = {
                [1] = "93101:Sit_Talk02R_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Linen/003/C88C3DAC",
            },
        [80110335] = {
            ["Content"] = "而且，就算你没法让冰湖城不下雪，但把雪铲走，堆个雪人，总做得到的。",
            ["ContentKR"] = "게다가, 네가 아이스레이크 시티에 눈이 안 오게 할 순 없어도, 눈을 치우고 눈사람을 만드는 건 할 수 있잖아.",
            ["DialogueId"] = 80110335,
            ["GUID"] = "C88C3DD6",
            ["NextDialogue"] = 80110336,
            ["SpeakNpcName"] = "UI_Npc_Name_Nvzhu",
            ["VoiceName"] = "voice/$Locale$/inv/Linen/003/C88C3DD6",
            },
        [80110336] = {
            ["Content"] = "至少，你可以走到你的朋友面前，告诉她，你还记得当年的梦想，即使那梦破碎了；你可以敲开家人的门，告诉他们，无论你是什么身份，你都牵挂着他们，这点永远不会改变。",
            ["ContentKR"] = "적어도, 네 친구에게 가서 옛날의 꿈을 아직도 기억하고 있다고 말할 수 있어. 그 꿈이 깨져버렸더라도 말이야. 가족들에게 가서 네가 어떤 위치에 있든 그들을 항상 생각하고 있다고, 그건 절대 변하지 않을 거라고 말해줄 수 있잖아.",
            ["DialogueId"] = 80110336,
            ["GUID"] = "C88C3E00",
            ["NextDialogue"] = 80110337,
            ["SpeakNpcName"] = "UI_Npc_Name_Nvzhu",
            ["TalkActionId"] = {
                [1] = "93101:Sit_Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Linen/003/C88C3E00",
            },
        [80110337] = {
            ["Content"] = "……哈哈，老实说，我真的挺喜欢你的想法的。虽然还是觉得有点不切实际，但比那些“世界本就如此，谁也改变不了”的垃圾话好听多了。",
            ["ContentKR"] = "...하하, 솔직히 말하면 난 네 생각이 정말 마음에 들어. 아직도 좀 비현실적이라고 생각하긴 하지만, \"세상은 원래 그런 거야, 아무도 바꿀 수 없어\"라는 쓰레기 같은 말보다는 훨씬 낫네.",
            ["DialogueId"] = 80110337,
            ["FacialId"] = {
                [1] = "93101:Smile01",
                },
            ["GUID"] = "C88C3E2A",
            ["NextDialogue"] = 80110338,
            ["SpeakNpcId"] = 93101,
            ["TalkActionId"] = {
                [1] = "93101:Sit_Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Linen/003/C88C3E2A",
            },
        [80110338] = {
            ["Content"] = "至少，听了让我觉得这冰湖城的风都变暖了点。嗯……再给我来一杯。",
            ["ContentKR"] = "적어도 네 말을 들으니까 이 아이스레이크 시티의 바람이 좀 따뜻해진 것 같아. 음... 한 잔 더 줘.",
            ["DialogueId"] = 80110338,
            ["FacialId"] = {
                [1] = "93101:Happy02",
                },
            ["GUID"] = "C88C3E54",
            ["NextDialogue"] = 80110339,
            ["SpeakNpcId"] = 93101,
            ["TalkActionId"] = {
                [1] = "93101:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Linen/003/C88C3E54",
            },
        [80110339] = {
            ["Content"] = "也让我看看你能走到哪一步吧。既然你说，你有改变世界这种白日梦，那我就等着瞧瞧，这个世界会不会因为一个天真的家伙，变得有那么一点不一样。",
            ["ContentKR"] = "네가 어디까지 갈 수 있는지 보여줘. 네가 세상을 바꾸겠다는 그런 헛된 꿈을 꾸고 있다면, 난 지켜보고 있을게. 이 세상이 순진한 놈 하나 때문에 조금이라도 달라질 수 있는지 말이야.",
            ["DialogueId"] = 80110339,
            ["FacialId"] = {
                [1] = "93101:Smile01",
                },
            ["GUID"] = "C88C3E7E",
            ["NextDialogue"] = 80110340,
            ["SpeakNpcId"] = 93101,
            ["VoiceName"] = "voice/$Locale$/inv/Linen/003/C88C3E7E",
            },
        [80110340] = {
            ["Content"] = "如果有什么需要帮忙的，我无事的时候，也可以找我——当然，和军团对着干的事除外。不过今天不行，我刚刚改变了主意，待会儿有其他事要忙了。",
            ["ContentKR"] = "도움이 필요하면 한가할 때 날 찾아. 물론, 군단과 맞서는 일은 빼고. 하지만 오늘은 안 돼. 방금 마음이 바뀌었거든. 이따 다른 일이 있어.",
            ["DialogueId"] = 80110340,
            ["GUID"] = "C88C3EA8",
            ["NextDialogue"] = 80110341,
            ["SpeakNpcId"] = 93101,
            ["TalkActionId"] = {
                [1] = "93101:Sit_Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Linen/003/C88C3EA8",
            },
        [80110341] = {
            ["Content"] = "委托你的单子取消，把面具和玩具枪还给我吧。",
            ["ContentKR"] = "네게 부탁한 일은 취소야. 가면이랑 장난감 총 돌려줘.",
            ["DialogueId"] = 80110341,
            ["FacialId"] = {
                [1] = "93101:None",
                },
            ["GUID"] = "C88C3ED2",
            ["SpeakNpcId"] = 93101,
            ["TalkActionId"] = {
                [1] = "93101:Sit_Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Linen/003/C88C3ED2",
            },
        [80120000] = {
            ["Content"] = "好舒服啊——椅子、饮料、零食、壁炉，还有你，已经变成懒洋洋的样子了……",
            ["ContentKR"] = "아, 너무 좋다. 편한 의자에 맛있는 음료랑 간식, 따뜻한 벽난로에 {nickname}까지... 이러다 완전 게을러질 것 같아.",
            ["DialogueId"] = 80120000,
            ["GUID"] = "C8926F80",
            },
        [80120100] = {
            ["Camera"] = "254.617188,-63.0,110.607666,0.0,0.0,155.600769,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "屋里的家具都是我三十年前从皇都迪斯玛尼亚带过来的，它们的材质之珍稀、工艺之精美，不是你们能想象得到的。",
            ["ContentKR"] = "이 집 가구들은 다 내가 30년 전에 황성 디즈마니아에서 가져온 거야. 얼마나 귀한 재료로 정교하게 만들어졌는지, 너희들은 상상도 못할 거다.",
            ["DialogueId"] = 80120100,
            ["FinalCamera"] = "254.617188,-54.528625,110.607666,0.0,0.0,155.600739,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "C8927FE8",
            ["NextDialogue"] = 80120101,
            ["SpeakNpcId"] = 790018,
            ["TalkActionId"] = {
                [1] = "790018:Explain01_Start",
                },
            ["ToFinalCameraBlendTime"] = 7,
            ["VoiceName"] = "voice/$Locale$/inv/Maer/001/C8927FE8",
            },
        [80120101] = {
            ["Camera"] = "-270.549316,-21.425171,153.719727,0.000001,-9.200162,19.797686,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "既然是这么珍贵的物品，真的可以交给我们来处理吗？我们是小本生意，万一您中途折回来了……",
            ["ContentKR"] = "그렇게 귀중한 물건들을 저희한테 맡기셔도 될까요? 저희가 워낙 작은 업체라서요. 혹시 중간에 마음이 바뀌시기라도 하면...",
            ["DialogueId"] = 80120101,
            ["FacialId"] = {
                [1] = "790019:Iyada01",
                },
            ["GUID"] = "C8928012",
            ["NextDialogue"] = 80120102,
            ["SpeakNpcId"] = 790019,
            ["TalkActionId"] = {
                [1] = "790019:Explain02_Start",
                [2] = "790018:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Maer/001/C8928012",
            },
        [80120102] = {
            ["Camera"] = "254.617188,-54.528625,110.607666,0.0,0.0,155.600739,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你已经问了好几遍了，我也回答了更多遍：这些家具，就是交给你们处理的。我这么多年积攒下来的乐谱才是真正的宝贝，早就被我放在了它该放的位置。",
            ["ContentKR"] = "벌써 몇 번이나 같은 질문을 하는 거냐. 내 대답도 여러 번 했지 않나. 이 가구들, 너희한테 맡긴다고. 내가 진짜 아끼는 보물은 수년간 모아온 악보들이고, 그건 이미 안전한 곳에 뒀으니까.",
            ["DialogueId"] = 80120102,
            ["GUID"] = "C892803C",
            ["NextDialogue"] = 80120103,
            ["SpeakNpcId"] = 790018,
            ["TalkActionId"] = {
                [1] = "790019:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Maer/001/C892803C",
            },
        [80120103] = {
            ["Camera"] = "-91.792969,-17.010254,119.101807,0.000001,-2.600096,26.798737,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那……为了以防万一，还是得跟您确认一下，我看书房里散落着不少纸张，整理出来有这么厚的一沓！我看了看，也是些乐谱……",
            ["ContentKR"] = "그래도요... 혹시 모르니까 한 번만 더 여쭤볼게요. 서재에 종이들이 잔뜩 흩어져 있던데, 모아보니 이만큼이나 되더라고요! 보니까 악보 같던데...",
            ["DialogueId"] = 80120103,
            ["GUID"] = "C8928066",
            ["NextDialogue"] = 80120104,
            ["SpeakNpcId"] = 790019,
            ["TalkActionId"] = {
                [1] = "790019:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Maer/001/C8928066",
            },
        [80120104] = {
            ["Camera"] = "188.380859,5.304199,118.568604,0.000005,0.0,165.387512,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "烧掉。",
            ["ContentKR"] = "다 태워버려.",
            ["DialogueId"] = 80120104,
            ["GUID"] = "C8928090",
            ["NextDialogue"] = 80120105,
            ["SpeakNpcId"] = 790018,
            ["TalkActionId"] = {
                [1] = "790019:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Maer/001/C8928090",
            },
        [80120105] = {
            ["Camera"] = "-194.875488,-9.761597,155.702393,0.000033,-32.798512,130.396423,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那些都是废稿，是垃圾，是没有用的东西。你随便找一户穿不暖的，让他们烧了取暖。",
            ["ContentKR"] = "전부 쓸모없는 쓰레기야. 그냥 버릴 거라고. 필요 없어. 춥다는 집 있으면 아무나 가져가서 땔감으로 쓰라고 해.",
            ["DialogueId"] = 80120105,
            ["FinalCamera"] = "-183.950195,-22.665466,181.275146,0.000027,-35.598583,129.996002,35.000008,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "C89280BA",
            ["NextDialogue"] = 80120106,
            ["SpeakNpcId"] = 790018,
            ["ToFinalCameraBlendTime"] = 9,
            ["VoiceName"] = "voice/$Locale$/inv/Maer/001/C89280BA",
            },
        [80120106] = {
            ["Camera"] = "7.850098,-71.797974,9.991455,0.000032,31.599302,132.795364,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "真是好笑，如果我真觉得那些东西重要，早就收好了，还用你特意提醒？",
            ["ContentKR"] = "웃기는군. 내가 정말 그게 중요하다고 생각했으면 벌써 잘 챙겼겠지. 네가 굳이 물어볼 필요도 없어.",
            ["DialogueId"] = 80120106,
            ["GUID"] = "C89280E4",
            ["NextDialogue"] = 80120107,
            ["SpeakNpcId"] = 790018,
            ["TalkActionId"] = {
                [1] = "790018:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Maer/001/C89280E4",
            },
        [80120107] = {
            ["Camera"] = "-65.708008,-20.782593,149.700928,0.000017,-11.799984,31.404984,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "…………",
            ["ContentKR"] = "......",
            ["DialogueId"] = 80120107,
