            },
        [80150127] = {
            ["Camera"] = "42.326603,34.966309,162.393936,0.000196,-12.195159,-114.703926,35.000008,1.5,false,DoNotOverride,15.0",
            ["Content"] = "那时我只是沉浸在震惊之中，什么也没做……",
            ["ContentKR"] = "그때는 충격에 빠져 아무것도 하지 못했어요...",
            ["DialogueId"] = 80150127,
            ["FacialId"] = {
