            ["VoiceName"] = "voice/$Locale$/inv/Lise/001/C8A5BF5C",
            },
        [80150201] = {
            ["Camera"] = "618.764404,403.857422,222.649796,0.000534,-8.595123,-145.30249,30.0,782.587708,false,Manual,3.0",
            ["Content"] = "（这一次，黎瑟按时赴约，只是早了一点。）",
            ["ContentKR"] = "(이번엔 리듬이 약속 시간에 맞춰 도착했다, 조금 일찍 왔지만...)",
            ["DialogueId"] = 80150201,
            ["FinalCamera"] = "618.764404,403.857422,258.947632,0.000537,-13.19516,-147.301575,30.0,782.587708,false,Manual,3.0",
            ["GUID"] = "C8A5CA5A",
            ["NextDialogue"] = 80150202,
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/002/C8A5CA5A",
            },
        [80150202] = {
            ["Camera"] = "128.130157,-64.091309,138.956345,0.00055,-1.994538,156.287964,35.0,209.939255,false,Manual,5.0",
            ["Content"] = "（她专心地盯着墙角，不知在想些什么。）",
            ["ContentKR"] = "(그녀는 벽 모퉁이를 집중해서 바라보며 무슨 생각을 하는지 모르겠다.)",
            ["DialogueId"] = 80150202,
            ["FinalCamera"] = "129.21524,-61.620605,138.956345,0.00055,-1.994538,156.287964,35.0,209.939255,false,Manual,5.0",
            ["GUID"] = "C8A5CA84",
            ["NextOptions"] = {
                [1] = 801502021,
                [2] = 801502022,
                },
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/002/C8A5CA84",
            },
        [80150203] = {
            ["Camera"] = "129.21524,-61.620605,138.956345,0.00055,-1.994538,156.287964,35.0,209.939255,false,Manual,5.0",
            ["Content"] = "……请不要再吓我了。万一我又没控制好能力，你可能会受伤的。",
            ["ContentKR"] = "...제발 그렇게 놀라게 하지 말아주세요. 제 능력이 잘못 발동되면 다칠 수도 있어요.",
            ["DialogueId"] = 80150203,
            ["FacialId"] = {
                [1] = "790044:Iyada01",
                },
            ["GUID"] = "C8A5CAAE",
            ["NextDialogue"] = 80150204,
            ["SpeakNpcId"] = 790044,
            ["TurnTo"] = {
                [1] = "790044:n(790008)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Lise/002/C8A5CAAE",
            },
        [80150204] = {
            ["Camera"] = "-49.563354,59.401855,141.255112,0.001375,-2.999081,-45.834862,35.000008,291.99585,false,DoNotOverride,15.0",
            ["Content"] = "真可惜，我还想再体验一次被电的感觉。",
            ["ContentKR"] = "아쉽네요. 한 번 더 감전되는 기분을 느껴보고 싶었는데.",
            ["DialogueId"] = 80150204,
            ["FacialId"] = {
                [1] = "790008:Blink",
                },
            ["FinalCamera"] = "-49.563354,59.401855,141.255112,0.001375,-2.999081,-45.834862,36.0,291.99585,false,DoNotOverride,15.0",
            ["GUID"] = "C8A5CAD8",
            ["NextDialogue"] = 80150205,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Talk01_Start",
                },
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/002/C8A5CAD8",
            },
        [80150205] = {
            ["Camera"] = "35.557709,-28.460938,135.738373,0.00136,0.802158,141.569565,35.000008,291.99585,false,DoNotOverride,15.0",
            ["Content"] = "请恕我无法理解这种奇怪的癖好……",
            ["ContentKR"] = "그런 이상한 취향은 도저히 이해가 안 됩니다...",
            ["DialogueId"] = 80150205,
            ["FacialId"] = {
                [1] = "790044:Doubt01",
                },
            ["FinalCamera"] = "35.557709,-28.460938,135.738373,0.00136,0.802158,141.569565,36.0,291.99585,false,DoNotOverride,15.0",
            ["GUID"] = "C8A5CB02",
            ["NextDialogue"] = 80150206,
            ["SpeakNpcId"] = 790044,
            ["TalkActionId"] = {
                [1] = "790044:DisagreeHead",
                },
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/002/C8A5CB02",
            },
        [80150206] = {
            ["Camera"] = "-111.224487,148.813965,141.615067,0.001381,-3.399535,-55.230232,35.000008,291.99585,false,DoNotOverride,15.0",
            ["Content"] = "你刚才在干什么呢？",
            ["ContentKR"] = "방금 뭐 하고 있었어요?",
            ["DialogueId"] = 80150206,
            ["FacialId"] = {
                [1] = "790008:None",
                },
            ["FinalCamera"] = "-108.748169,150.532227,141.615021,0.001381,-3.599537,-55.829838,35.000008,291.99585,false,DoNotOverride,15.0",
            ["GUID"] = "C8A5CB2C",
            ["NextDialogue"] = 80150208,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Talk01_End",
                },
            ["ToFinalCameraBlendTime"] = 3,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/002/C8A5CB2C",
            },
        [80150207] = {
            ["Camera"] = "129.21524,-61.620605,138.956345,0.00055,-1.994538,156.287964,35.0,209.939255,false,Manual,5.0",
            ["Content"] = "啊，你好。",
            ["ContentKR"] = "아, 안녕하세요.",
            ["DialogueId"] = 80150207,
            ["GUID"] = "C8A5CB56",
            ["NextDialogue"] = 80150208,
            ["SpeakNpcId"] = 790044,
            ["TurnTo"] = {
                [1] = "790044:n(790008)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Lise/002/C8A5CB56",
            },
        [80150208] = {
            ["Camera"] = "221.280334,-79.913574,140.015259,0.001379,-3.598205,162.369766,35.000008,291.99585,false,DoNotOverride,15.0",
            ["Content"] = "刚才我把你的屋子又检查了一遍，发现了好几处藏在角落的蜘蛛网和毛发团，都帮你清理掉了。",
            ["ContentKR"] = "방금 당신 집을 한 번 더 점검했어요. 구석구석에 거미줄이랑 먼지 뭉치가 좀 있어서 전부 정리했어요.",
            ["DialogueId"] = 80150208,
            ["FacialId"] = {
                [1] = "790044:Confident01",
                },
            ["FinalCamera"] = "222.133209,-77.229492,140.015289,0.001379,-3.598205,162.369766,35.000008,291.99585,false,DoNotOverride,15.0",
            ["GUID"] = "C8A5CB80",
            ["NextOptions"] = {
                [1] = 801502081,
                [2] = 801502082,
                },
            ["SpeakNpcId"] = 790044,
            ["TalkActionId"] = {
                [1] = "790044:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 11,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/002/C8A5CB80",
            },
        [80150209] = {
            ["Content"] = "既然做了，我就想做到最好。",
            ["ContentKR"] = "이미 시작한 거라서, 끝까지 최선을 다하고 싶었어요.",
            ["DialogueId"] = 80150209,
            ["FacialId"] = {
                [1] = "790044:Confident01",
                },
            ["GUID"] = "C8A5CBAA",
            ["NextDialogue"] = 80150211,
            ["SpeakNpcId"] = 790044,
            ["TalkActionId"] = {
                [1] = "790044:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Lise/002/C8A5CBAA",
            },
        [80150210] = {
            ["Content"] = "千万不要……我只是想帮上点什么忙，仅此而已。",
            ["ContentKR"] = "절대 그러지 마세요... 그냥 조금이라도 도움이 되고 싶었을 뿐이에요.",
            ["DialogueId"] = 80150210,
            ["GUID"] = "C8A5CBD4",
            ["NextDialogue"] = 80150211,
            ["SpeakNpcId"] = 790044,
            ["TalkActionId"] = {
                [1] = "790044:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Lise/002/C8A5CBD4",
            },
        [80150211] = {
            ["Camera"] = "-101.272095,139.332031,145.298187,0.001379,-5.399469,-56.236126,35.000008,291.99585,false,DoNotOverride,15.0",
            ["Content"] = "你还是和以前一样，做什么都很努力。",
            ["ContentKR"] = "여전히 뭐든 열심히 하시는군요.",
            ["DialogueId"] = 80150211,
            ["FacialId"] = {
                [1] = "790008:Happy02",
                },
            ["FinalCamera"] = "-99.371521,136.48877,144.974991,0.001379,-5.399469,-56.235954,35.000008,291.99585,false,DoNotOverride,15.0",
            ["GUID"] = "C8A5CBFE",
            ["NextDialogue"] = 80150212,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Talk02_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/002/C8A5CBFE",
            },
        [80150212] = {
            ["Camera"] = "75.613556,-25.058594,134.501633,0.001379,-0.598174,152.772156,35.000008,291.99585,false,DoNotOverride,15.0",
            ["Content"] = "努力吗……或许吧，这对我来说已经算是一种习惯了。你知道的，我一直没什么好的天赋，只能用笨办法补足一些。",
            ["ContentKR"] = "열심히라... 그럴지도요. 저한테는 이미 버릇처럼 돼버렸어요. 아시잖아요, 저는 특별한 재능이 없어서 노력으로 채워야 하거든요.",
            ["DialogueId"] = 80150212,
            ["FacialId"] = {
                [1] = "790044:Unhappy01",
                },
            ["FinalCamera"] = "75.613556,-25.058594,134.501633,0.001382,-0.598174,152.772156,37.0,291.99585,false,DoNotOverride,15.0",
            ["GUID"] = "C8A5CC28",
            ["NextOptions"] = {
                [1] = 801502121,
                [2] = 801502122,
                },
            ["SpeakNpcId"] = 790044,
            ["TalkActionId"] = {
                [1] = "790044:Think_Start",
                [2] = "\
790008:Talk02_End",
                },
            ["ToFinalCameraBlendTime"] = 12,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/002/C8A5CC28",
            },
        [80150213] = {
            ["Camera"] = "213.222778,-79.430664,146.874283,0.001398,-4.998319,160.351501,35.0,291.99585,false,DoNotOverride,15.0",
            ["Content"] = "长官们总说军团是全帝国最公平的地方，因为功劳不会骗人，努力就会得到回报。只要肯吃苦，即便是我这样的卡戎，也可以堂堂正正地获得荣誉。",
            ["ContentKR"] = "상관님들은 군단이 제국에서 가장 공정한 곳이라고 하셨어요. 공로는 거짓말을 안 하고, 노력하면 반드시 보상이 따라온다고요. 고생할 각오만 하면, 저 같은 카론도 당당히 명예를 얻을 수 있다고 하셨죠.",
            ["DialogueId"] = 80150213,
            ["FacialId"] = {
                [1] = "790044:Think01",
                },
            ["FinalCamera"] = "204.465332,-76.303711,146.061005,0.001398,-4.998319,160.351501,35.0,291.99585,false,DoNotOverride,15.0",
            ["GUID"] = "C8A5CC52",
            ["NextDialogue"] = 80150214,
            ["SpeakNpcId"] = 790044,
            ["ToFinalCameraBlendTime"] = 13,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/002/C8A5CC52",
            },
        [80150214] = {
            ["Camera"] = "312.985168,222.499512,18.860168,0.001343,9.600622,-145.63736,20.0,471.113068,false,Manual,1.2",
            ["Content"] = "于是我就一直这样埋头努力着，追逐着那个名为“桂冠卡戎”的华丽泡影，一步一步地前进……到最后却发现，我想要的东西却在相反的方向。",
            ["ContentKR"] = "그래서 저는 '계관카론'이라는 화려한 꿈을 향해 계속 열심히 걸어갔어요... 하지만 결국 제가 원한 건 그 반대편에 있다는 걸 알게 됐죠.",
            ["DialogueId"] = 80150214,
            ["FacialId"] = {
                [1] = "790044:Sad01",
                },
            ["FinalCamera"] = "312.985168,222.499512,33.452301,0.001343,8.40062,-145.637222,20.0,471.113068,false,Manual,1.2",
            ["GUID"] = "C8A5CC7C",
            ["NextDialogue"] = 80150215,
            ["SpeakNpcId"] = 790044,
            ["TalkActionId"] = {
                [1] = "790044:Talk01_Start",
                },
            ["ToFinalCameraBlendTime"] = 12,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/002/C8A5CC7C",
            },
        [80150215] = {
            ["Camera"] = "518.667297,378.844238,282.734802,0.00135,-19.199818,-144.032669,20.0,688.641724,false,Manual,1.2",
            ["Content"] = "我只能安慰自己，幸好我的天赋比不上别人，只能一步一步地走，所以也没有走得太远。",
            ["ContentKR"] = "저는 스스로를 위로했어요. 제 재능이 남들보다 부족해서 한 걸음씩 천천히 나아갈 수 있었던 게 오히려 다행이었죠. 그래서 멀리까지 가지 않았어요.",
            ["DialogueId"] = 80150215,
            ["FinalCamera"] = "534.613464,390.330078,296.944946,0.001353,-19.999872,-144.232666,20.0,688.641724,false,Manual,1.2",
            ["GUID"] = "C8A5CCA6",
            ["NextDialogue"] = 80150216,
            ["SpeakNpcId"] = 790044,
            ["TalkActionId"] = {
                [1] = "790044:Talk01_End",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/002/C8A5CCA6",
            },
        [80150216] = {
            ["Camera"] = "17.473877,-22.0,137.696609,0.001373,0.600271,139.371307,35.0,688.641724,false,DoNotOverride,1.2",
            ["Content"] = "如果我是更加懂得人情世故，更加圆滑的人，那么恐怕会去到更高的位置，即便是回过头来，也找不到起点，只能慢慢腐烂了。",
            ["ContentKR"] = "만약 제가 더 사교적이고 더 능숙한 사람이었다면, 아마 더 높은 자리까지 올라갔을지도 몰라요. 하지만 돌아보면 시작점도 잊어버린 채 서서히 타락해 갔겠죠.",
            ["DialogueId"] = 80150216,
            ["FacialId"] = {
                [1] = "790044:Disappoint01",
                },
            ["FinalCamera"] = "17.473877,-22.0,137.696609,0.001373,0.600271,139.371307,37.0,688.641724,false,DoNotOverride,1.2",
            ["GUID"] = "C8A5CCD0",
            ["NextOptions"] = {
                [1] = 801502161,
                [2] = 801502162,
                },
            ["SpeakNpcId"] = 790044,
            ["TalkActionId"] = {
                [1] = "790044:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 11,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/002/C8A5CCD0",
            },
        [80150217] = {
            ["Camera"] = "-69.954895,82.007324,132.937286,0.001387,-0.599581,-53.436954,35.000008,173.536774,false,Manual,15.0",
            ["Content"] = "如果让你在帮助别人和升迁之间去选择，你一定会去选择帮助他人。",
            ["ContentKR"] = "만약 다른 사람을 돕는 것과 승진 중에 하나 선택해야 한다면, 당신은 분명히 다른 사람을 돕는 걸 선택할 거예요.",
            ["DialogueId"] = 80150217,
            ["FinalCamera"] = "-69.954895,82.007324,135.66391,0.001388,-1.399601,-53.43697,35.000008,173.536774,false,Manual,15.0",
            ["GUID"] = "C8A5CCFA",
            ["NextDialogue"] = 80150219,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Talk02_Start",
                },
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/002/C8A5CCFA",
            },
        [80150218] = {
            ["Camera"] = "-69.954895,82.007324,132.937286,0.001387,-0.599581,-53.436954,35.000008,173.536774,false,Manual,15.0",
            ["Content"] = "或者说，你也有自己的天赋：你会比其他人更加坚持自己的原则。",
            ["ContentKR"] = "다른 말로 하면, 당신만의 재능이 있는 거예요. 누구보다 자신의 원칙을 잘 지키는 게 바로 당신의 재능이죠.",
            ["DialogueId"] = 80150218,
            ["FinalCamera"] = "-69.954895,82.007324,135.66391,0.001388,-1.399601,-53.43697,35.000008,173.536774,false,Manual,15.0",
            ["GUID"] = "C8A5CD24",
