            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Explain02_End",
                [2] = "\
790044:Explain02_End",
                },
            ["ToFinalCameraBlendTime"] = 12,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/002/C8A5CF70",
            },
        [80150233] = {
            ["Camera"] = "297.921814,214.879883,19.846474,-3.000002,10.399884,-142.621796,15.0,379.470764,false,Manual,1.2",
            ["Content"] = "想象一下：黎瑟·书店老板·费西尔、黎瑟·钓鱼迷·费西尔、也可以是驯马师、作家、糕点师。除了电力维修员，什么都可以。",
            ["ContentKR"] = "상상해 보세요. 리듬 서점 주인 페실, 리듬 낚시꾼 페실, 혹은 조련사, 작가, 제빵사... 전기 수리공만 빼고 다 될 수 있죠.",
            ["DialogueId"] = 80150233,
            ["FinalCamera"] = "324.730652,173.219727,15.300781,-1.0,11.19987,-154.821091,15.0,379.470764,false,Manual,1.2",
