            },
        [80150235] = {
            ["Camera"] = "150.443146,-68.690918,141.779251,0.001374,-3.398005,157.561905,35.000008,291.99585,false,DoNotOverride,15.0",
            ["Content"] = "你的意思是说……暂时不前进，也没关系吗？",
            ["ContentKR"] = "당신 말은... 잠시 멈춰도 괜찮다는 건가요?",
            ["DialogueId"] = 80150235,
            ["FacialId"] = {
                [1] = "790008:Smile01",
                },
            ["FinalCamera"] = "151.495178,-66.144043,141.779282,0.001374,-3.398005,158.361923,35.000008,291.99585,false,DoNotOverride,15.0",
            ["GUID"] = "C8A5CFEE",
            ["NextDialogue"] = 80150236,
            ["SpeakNpcId"] = 790044,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/002/C8A5CFEE",
            },
        [80150236] = {
            ["Camera"] = "-71.889221,108.26416,104.530975,0.001504,5.40033,-58.024708,30.0,206.628311,false,Manual,5.0",
            ["Content"] = "当然没关系。就算是机器，一直运作也会坏掉的。",
            ["ContentKR"] = "물론 괜찮죠. 기계도 쉬지 않고 돌리면 결국 고장 나는 법이잖아요.",
            ["DialogueId"] = 80150236,
            ["FacialId"] = {
                [1] = "790044:None",
                },
            ["GUID"] = "C8A5D018",
            ["NextDialogue"] = 80150237,
            ["Scripts"] = "PlayAnimation{_delay{1},ActorId{790008},AnimationId{\"Talk02_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Lise/002/C8A5D018",
            },
        [80150237] = {
            ["Content"] = "我想你应该好好享受“停下来”的时间。也许，你就会在不经意间发现真正想做的事，自然而然地明白前进的意义——不是别人给的，而是自己找到的。",
            ["ContentKR"] = "잠시 '멈추는' 시간을 잘 즐기세요. 그러다가 어느 순간 진짜 하고 싶은 일이 떠오르고, 앞으로 나아가는 의미를 알게 될 거예요. 이것은 다른 사람이 알려준 게 아니라 스스로 찾아야 할 것이죠.",
            ["DialogueId"] = 80150237,
            ["GUID"] = "C8A5D042",
            ["NextDialogue"] = 80150238,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Lise/002/C8A5D042",
            },
        [80150238] = {
            ["Camera"] = "37.151489,10.179688,162.34816,0.00138,-13.798518,160.361816,35.000008,291.99585,false,DoNotOverride,15.0",
            ["Content"] = "……好，我相信你。",
            ["ContentKR"] = "...알겠어요. 당신 말을 믿어볼게요.",
            ["DialogueId"] = 80150238,
            ["FacialId"] = {
                [1] = "790044:Confident01",
                },
            ["GUID"] = "C8A5D06C",
            ["NextDialogue"] = 80150239,
            ["SpeakNpcId"] = 790044,
            ["TalkActionId"] = {
                [1] = "790044:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Lise/002/C8A5D06C",
            },
        [80150239] = {
            ["Camera"] = "701.533142,-19.678223,342.430603,0.001379,-20.598722,179.159149,35.000008,291.99585,false,DoNotOverride,15.0",
            ["Content"] = "嗯……就这么定了！从今天开始，我会按照你的建议，认真地“停下来”，按照字典的顺序，去挨个尝试各种职业。",
            ["ContentKR"] = "음... 그렇게 할게요! 오늘부터 당신 조언대로 진지하게 '멈춰서' 사전 순서대로 다양한 직업을 시도해 볼게요.",
            ["DialogueId"] = 80150239,
            ["FinalCamera"] = "750.443481,-20.394043,360.815552,0.001379,-20.598722,179.159149,35.000008,291.99585,false,DoNotOverride,15.0",
            ["GUID"] = "C8A5D096",
            ["NextDialogue"] = 80150240,
            ["SpeakNpcId"] = 790044,
            ["TalkActionId"] = {
                [1] = "790044:Angry01_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/002/C8A5D096",
            },
        [80150240] = {
            ["Camera"] = "-70.064331,125.332031,101.724655,0.000002,6.400775,-59.833042,30.0,211.591843,false,Manual,5.0",
            ["Content"] = "……都说了不要这么较真啊！",
            ["ContentKR"] = "...너무 진지하게 받아들이지 말라니까요!",
            ["DialogueId"] = 80150240,
            ["FacialId"] = {
                [1] = "790008:Ahaha02",
                },
            ["FinalCamera"] = "-70.064331,125.332031,101.724655,0.000003,6.400775,-59.833019,32.0,211.591843,false,Manual,5.0",
            ["GUID"] = "C8A5D0C0",
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Sigh_Start",
                },
            ["ToFinalCameraBlendTime"] = 3.5,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/002/C8A5D0C0",
            },
        [80150301] = {
            ["Camera"] = "378.598389,-357.041016,313.750732,0.000139,-24.203033,136.98111,20.0,100000.0,false,DoNotOverride,3.0",
            ["Content"] = "（到了与黎瑟约定的时间，但是却没有看见人影。）",
            ["ContentKR"] = "(리듬과 약속한 시간이 되었지만 그녀는 보이지 않는다.)",
            ["DialogueId"] = 80150301,
            ["GUID"] = "C8A5DAC2",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 80150302,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/003/C8A5DAC2",
            },
        [80150302] = {
            ["Content"] = "（你再次确认了一下时间，又环顾了四周，确信黎瑟确实是迟来了，这不正常。正当你开始担心黎瑟是不是出了什么事时，窗外传来了口琴声。）",
            ["ContentKR"] = "(다시 시간을 확인하고 주위를 둘러보니, 리듬이 늦은 게 확실하다. 이건 평소와 달랐다. 리듬에게 무슨 일이 생긴 건 아닌지 걱정하기 시작할 때, 창밖에서 하모니카 소리가 들려왔다.)",
            ["DialogueId"] = 80150302,
            ["GUID"] = "C8A5DAEC",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 80150303,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/003/C8A5DAEC",
            },
        [80150303] = {
            ["Content"] = "♪—♪——（吹口琴的声音）",
            ["ContentKR"] = "♪—♪—",
            ["DialogueId"] = 80150303,
            ["GUID"] = "C8A5DB16",
            ["IsBlack"] = 1,
            ["NextOptions"] = {
                [1] = 801503031,
                },
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_kouqin\"},EventKey{\"yaoyue_kouqin\"},PlayAs2D{true}}",
            ["SpeakNpcId"] = 790044,
            ["TalkActionId"] = {
                [1] = "790044:Lise_Sing_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Lise/003/C8A5DB16",
            },
        [80150304] = {
            ["Camera"] = "-162.97998,-47.925293,139.780518,0.000136,-4.003618,17.769627,35.000008,100000.0,false,DoNotOverride,3.0",
            ["Content"] = "啊……是我。抱歉，我迟到了。",
            ["ContentKR"] = "아... 저예요. 미안해요, 늦었어요.",
            ["DialogueId"] = 80150304,
            ["FacialId"] = {
                [1] = "790044:Ahaha01",
                },
            ["GUID"] = "C8A5DB40",
            ["NextDialogue"] = 80150305,
            ["Scripts"] = "SEQ{\
StopNormalSound{EventKey{\"yaoyue_kouqin\"}},\
PlayAnimation{_delay{1.5},ActorId{790044},AnimationId{\"ScratchHead_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 790044,
            ["TalkActionId"] = {
                [1] = "790044:Lise_Sing_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Lise/003/C8A5DB40",
            },
        [80150305] = {
            ["Camera"] = "15.73584,-25.139648,130.758057,0.000128,5.396846,161.76976,35.000008,100000.0,false,DoNotOverride,3.0",
            ["Content"] = "你刚才是在吹口琴吗？真是稀奇啊。",
            ["ContentKR"] = "방금 하모니카 불고 있었어요? 정말 신기하네요.",
            ["DialogueId"] = 80150305,
            ["FacialId"] = {
                [1] = "790008:Shock01",
                },
            ["GUID"] = "C8A5DB6A",
            ["NextDialogue"] = 80150306,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790044:ScratchHead_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Lise/003/C8A5DB6A",
            },
        [80150306] = {
            ["Camera"] = "-162.97998,-47.925293,139.780518,0.000136,-4.003618,17.769627,35.000008,100000.0,false,DoNotOverride,3.0",
            ["Content"] = "嗯……你之前不是说，要我去发现“真正想做的事”吗？",
            ["ContentKR"] = "음... 전에 \"진짜 하고 싶은 일을 찾아보라\"고 했잖아요?",
            ["DialogueId"] = 80150306,
            ["FacialId"] = {
                [1] = "790044:Confident01",
                [2] = "\
790008:None",
                },
            ["GUID"] = "C8A5DB94",
            ["NextDialogue"] = 80150307,
            ["SpeakNpcId"] = 790044,
            ["TalkActionId"] = {
                [1] = "790044:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Lise/003/C8A5DB94",
            },
        [80150307] = {
            ["Camera"] = "-64.259766,-53.155762,98.869629,0.000149,12.995964,23.367174,35.000008,100000.0,false,DoNotOverride,3.0",
            ["Content"] = "我想，凭空去找到这样一件事实在困难，所以就打算先从自己接触过的东西开始尝试……比如说，吹奏口琴。",
            ["ContentKR"] = "그냥 아무것도 없이 찾는 건 어려울 것 같아서 전에 접했던 것부터 시도해 보려 했어요... 예를 들면 하모니카 불기 같은 거요.",
            ["DialogueId"] = 80150307,
            ["FacialId"] = {
                [1] = "790044:Think01",
                },
            ["FinalCamera"] = "-64.259766,-53.155762,98.869629,0.000149,12.995951,23.367155,36.0,100000.0,false,DoNotOverride,3.0",
            ["GUID"] = "C8A5DBBE",
            ["NextDialogue"] = 80150308,
            ["SpeakNpcId"] = 790044,
            ["TalkActionId"] = {
                [1] = "790044:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 11,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/003/C8A5DBBE",
            },
        [80150308] = {
            ["Camera"] = "-333.883301,-207.240234,206.4021,0.000138,-13.203909,33.370224,35.000008,100000.0,false,DoNotOverride,3.0",
            ["Content"] = "我并不是那么懂音乐，但我想试着理解。我选了一首新的曲子。旧书店的老板说，这是一首歌颂春天和希望的歌。",
            ["ContentKR"] = "음악에 대해 잘 알진 못하지만, 이해해 보려고 노력 중이에요. 헌책방 주인님이 추천해 주신 곡이에요. 봄과 희망을 찬미하는 곡이라고 하셨어요.",
            ["DialogueId"] = 80150308,
            ["FinalCamera"] = "-330.20752,-212.821289,206.4021,0.000139,-13.403891,33.770519,35.000008,100000.0,false,DoNotOverride,3.0",
            ["GUID"] = "C8A5DBE8",
            ["NextDialogue"] = 80150309,
            ["SpeakNpcId"] = 790044,
            ["ToFinalCameraBlendTime"] = 11,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/003/C8A5DBE8",
            },
        [80150309] = {
            ["Camera"] = "19.719727,-47.332031,127.602783,0.000157,6.795505,151.16304,35.000008,100000.0,false,DoNotOverride,3.0",
            ["Content"] = "我想要吹给你听一听，但还是担心不够熟练，所以刚刚在外面想要练习一会儿……",
            ["ContentKR"] = "당신에게 들려주고 싶었는데, 아직 익숙하지 않아서 방금 밖에서 연습 좀 하려고 했어요...",
            ["DialogueId"] = 80150309,
            ["FacialId"] = {
                [1] = "790044:Doubt01",
                },
            ["FinalCamera"] = "19.719727,-47.332031,127.602783,0.000157,6.795505,151.16304,37.0,100000.0,false,DoNotOverride,3.0",
            ["GUID"] = "C8A5DC12",
            ["NextOptions"] = {
                [1] = 801503091,
                [2] = 801503092,
                },
            ["SpeakNpcId"] = 790044,
            ["ToFinalCameraBlendTime"] = 9,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/003/C8A5DC12",
            },
        [80150310] = {
            ["Camera"] = "-112.624023,-27.073242,130.754395,0.000127,0.396267,16.373621,35.000008,186.892487,false,Manual,5.0",
            ["Content"] = "谢谢……",
            ["ContentKR"] = "감사합니다...",
            ["DialogueId"] = 80150310,
            ["FacialId"] = {
                [1] = "790044:Smile01",
                },
            ["GUID"] = "C8A5DC3C",
            ["NextDialogue"] = 80150311,
            ["SpeakNpcId"] = 790044,
            ["TalkActionId"] = {
                [1] = "790044:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Lise/003/C8A5DC3C",
            },
        [80150311] = {
            ["Content"] = "你知道吗，其实，我的名字的含义是“节奏”。",
            ["ContentKR"] = "알다시피, 제 이름은 '리듬'이에요.",
            ["DialogueId"] = 80150311,
            ["GUID"] = "C8A5DC66",
            ["NextDialogue"] = 80150312,
            ["SpeakNpcId"] = 790044,
            ["TalkActionId"] = {
                [1] = "790044:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Lise/003/C8A5DC66",
            },
        [80150312] = {
            ["Camera"] = "-275.132812,-182.827148,169.665527,0.000138,-8.603729,34.369663,35.000008,100000.0,false,DoNotOverride,3.0",
            ["Content"] = "这是父母认真为我取的名字，我很喜欢。不过很可惜，我天生就不擅长音律，实在是浪费了这个好名字……",
            ["ContentKR"] = "이건 부모님이 신중하게 지어주신 이름이라 정말 마음에 들어요. 하지만 안타깝게도, 제가 타고난 음감이 좋지 않아서 이 멋진 이름을 제대로 살리지 못하는 것 같아요...",
            ["DialogueId"] = 80150312,
            ["FinalCamera"] = "-285.81543,-190.133301,177.608398,0.00014,-9.803801,34.369843,35.000008,100000.0,false,DoNotOverride,3.0",
            ["GUID"] = "C8A5DC90",
            ["NextDialogue"] = 80150313,
            ["SpeakNpcId"] = 790044,
            ["TalkActionId"] = {
                [1] = "790044:ConfidentLToTalk01_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/003/C8A5DC90",
            },
        [80150313] = {
            ["Camera"] = "619.86084,-362.304688,120.789062,0.000158,-3.203878,149.565842,35.000008,100000.0,false,DoNotOverride,3.0",
            ["Content"] = "我会完整吹奏的曲子，就只有那首《致无名者的安魂曲》。之所以能记住，也是因为布鲁斯总是反反复复地在我耳边吹起。",
            ["ContentKR"] = "제가 완곡으로 연주할 수 있는 곡은 〈이름 없는 아이에게〉 하나뿐이에요. 이 곡을 기억할 수 있었던 거도 블루스가 제 옆에 반복해서 들려줬기 때문이에요.",
            ["DialogueId"] = 80150313,
            ["FinalCamera"] = "619.86084,-362.304688,144.250488,0.000159,-5.003967,149.765717,35.000008,100000.0,false,DoNotOverride,3.0",
            ["GUID"] = "C8A5DCBA",
            ["NextDialogue"] = 80150314,
            ["SpeakNpcId"] = 790044,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/003/C8A5DCBA",
            },
        [80150314] = {
            ["Camera"] = "141.552734,-26.657715,132.482422,0.000145,0.396588,168.366455,50.0,213.991577,false,Manual,6.0",
            ["Content"] = "老实说，乐谱上的这些音符我根本看不懂，纯粹是对照着音符和吹孔的对应表，靠死记硬背来记住吹奏的位置和顺序……",
            ["ContentKR"] = "솔직히 말하면, 악보에 있는 음표들은 전혀 이해하지 못해요. 그냥 음표와 하모니카 구멍을 매칭한 표를 보면서, 완전히 암기해서 부는 위치와 순서를 외운 거였어요...",
            ["DialogueId"] = 80150314,
            ["FacialId"] = {
                [1] = "790044:Sad01",
                },
            ["FinalCamera"] = "141.041504,-29.135254,132.482422,0.000145,0.396588,168.366455,50.0,213.991577,false,Manual,6.0",
            ["GUID"] = "C8A5DCE4",
            ["NextOptions"] = {
                [1] = 801503141,
                [2] = 801503142,
                },
            ["SpeakNpcId"] = 790044,
            ["TalkActionId"] = {
                [1] = "790044:Talk01_End",
                [2] = "\
790008:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 9,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/003/C8A5DCE4",
            },
        [80150315] = {
            ["Camera"] = "-50.819824,-10.924316,129.908691,0.000116,2.996124,7.37299,35.000008,100000.0,false,DoNotOverride,3.0",
            ["Content"] = "听你这么说，我又有信心了。",
            ["ContentKR"] = "그렇게 말해주니 자신감이 생기네요.",
            ["DialogueId"] = 80150315,
            ["FacialId"] = {
                [1] = "790044:Smile01",
                },
            ["GUID"] = "C8A5DD0E",
            ["NextDialogue"] = 80150316,
            ["SpeakNpcId"] = 790044,
            ["TalkActionId"] = {
                [1] = "790044:Explain02_Start",
                [2] = "\
790008:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Lise/003/C8A5DD0E",
            },
        [80150316] = {
            ["Camera"] = "460.504395,-291.947754,239.943115,0.000159,-14.603743,146.764069,35.0,213.991577,false,DoNotOverride,6.0",
            ["Content"] = "既然你在，我想拜托你一件事……你可以在我吹奏的同时，帮我把旋律唱出来吗？这样，我就知道自己吹得对不对了。",
            ["ContentKR"] = "마침 당신이 있으니 부탁 하나만 해도 되나요... 제가 하모니카를 연주할 때 멜로디를 불러줄 수 있나요? 그러면 제가 제대로 연주하고 있는지 알 수 있을 것 같아요.",
            ["DialogueId"] = 80150316,
            ["FinalCamera"] = "460.504395,-291.947754,215.802734,0.00016,-13.203704,146.76355,35.0,213.991577,false,DoNotOverride,6.0",
            ["GUID"] = "C8A5DD38",
            ["NextOptions"] = {
                [1] = 801503161,
                [2] = 801503162,
                },
            ["SpeakNpcId"] = 790044,
            ["TalkActionId"] = {
                [1] = "790044:Explain02_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/003/C8A5DD38",
            },
        [80150317] = {
            ["Camera"] = "-178.790039,-52.550781,147.112793,0.000133,-5.203948,18.972607,35.000008,100000.0,false,DoNotOverride,3.0",
            ["Content"] = "那就拜托你了。",
            ["ContentKR"] = "그럼 부탁할게요.",
            ["DialogueId"] = 80150317,
            ["GUID"] = "C8A5DD62",
            ["NextDialogue"] = 80150319,
            ["SpeakNpcId"] = 790044,
            ["TalkActionId"] = {
                [1] = "790044:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Lise/003/C8A5DD62",
            },
        [80150318] = {
            ["Camera"] = "-178.790039,-52.550781,147.112793,0.000133,-5.203948,18.972607,35.000008,100000.0,false,DoNotOverride,3.0",
            ["Content"] = "没关系，那我们就一起慢慢摸索吧。",
            ["ContentKR"] = "괜찮아요, 그럼 우리 같이 천천히 알아가봐요.",
            ["DialogueId"] = 80150318,
            ["GUID"] = "C8A5DD8C",
            ["NextDialogue"] = 80150319,
            ["SpeakNpcId"] = 790044,
            ["TalkActionId"] = {
                [1] = "790044:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Lise/003/C8A5DD8C",
            },
        [80150319] = {
            ["Camera"] = "-548.878906,-136.409668,668.428467,5.000547,-47.202866,15.77405,25.0,100000.0,false,DoNotOverride,5.0",
            ["Content"] = "（在黎瑟鼓励的目光中，你开始按照乐谱，慢慢地哼唱起那首歌的旋律。）",
            ["ContentKR"] = "(리듬이 격려하는 눈빛으로 당신을 바라본다. 당신은 악보를 보며 조심스럽게 그 노래의 멜로디를 흥얼거리기 시작한다.)",
            ["DialogueId"] = 80150319,
            ["FinalCamera"] = "-559.611816,50.6875,643.750977,-0.0,-45.602726,-5.025548,25.0,100000.0,false,DoNotOverride,5.0",
            ["GUID"] = "C8A5DDB6",
            ["NextDialogue"] = 80150320,
            ["TalkActionId"] = {
                [1] = "790008:Explain02_Start",
                [2] = "\
790044:Talk02_End",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/003/C8A5DDB6",
            },
        [80150320] = {
            ["Camera"] = "162.047363,487.058594,377.543457,0.000115,-29.804956,-110.623787,25.0,638.752747,false,Manual,1.2",
            ["Content"] = "（而她也举起口琴，跟着你的哼唱，略显笨拙地吹奏起一个又一个音符。一遍结束之后，她又试着自己独立吹奏了一遍。）",
            ["ContentKR"] = "(그녀도 하모니카를 들고 당신의 흥얼거림에 맞춰 서툴게 음표 하나하나를 연주하기 시작한다. 한 번 끝난 후, 그녀는 혼자서 다시 한번 연주를 시도한다.)",
            ["DialogueId"] = 80150320,
            ["FinalCamera"] = "171.548828,483.431641,377.543457,0.000112,-30.004972,-111.623634,25.0,638.752747,false,Manual,1.2",
            ["GUID"] = "C8A5DDE0",
            ["NextDialogue"] = 80150321,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_kouqin\"},EventKey{\"yaoyue_kouqin\"},PlayAs2D{true}}",
            ["TalkActionId"] = {
                [1] = "790044:Lise_Sing_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/003/C8A5DDE0",
            },
        [80150321] = {
            ["Camera"] = "-62.52002,52.065918,137.690918,0.000125,-1.003751,-20.827768,35.000008,100000.0,false,DoNotOverride,3.0",
            ["Content"] = "唔……这样，音高姑且是对了，但节奏完全乱掉了。一旦把注意力放在音高上，就很难对上节奏。看来我还得多加练习……",
            ["ContentKR"] = "음... 음정은 대충 맞췄는데, 리듬이 완전 엉망이네요. 음정에 집중하다 보니 리듬을 따라가는 게 어렵네요. 더 연습해야 할 것 같아요...",
            ["DialogueId"] = 80150321,
            ["FacialId"] = {
                [1] = "790044:Think01",
                },
            ["FinalCamera"] = "-54.942383,49.181641,137.548828,0.000125,-0.803742,-20.827745,35.000008,100000.0,false,DoNotOverride,3.0",
            ["GUID"] = "C8A5DE0A",
            ["NextDialogue"] = 80150322,
            ["Scripts"] = "StopNormalSound{EventKey{\"yaoyue_kouqin\"}}",
            ["SpeakNpcId"] = 790044,
            ["TalkActionId"] = {
                [1] = "790044:Lise_Sing_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/003/C8A5DE0A",
            },
        [80150322] = {
            ["Camera"] = "139.77832,42.777832,138.025635,0.000151,-2.403414,-164.424194,35.000011,216.461411,false,Manual,3.0",
            ["Content"] = "我觉得你刚才吹的这个版本也很好听。",
            ["ContentKR"] = "방금 연주한 것도 정말 좋았어요.",
            ["DialogueId"] = 80150322,
            ["FacialId"] = {
                [1] = "790008:Smile01",
                [2] = "\
790044:None",
                },
            ["FinalCamera"] = "139.365234,44.257812,138.025635,0.000151,-2.403414,-164.424194,35.000011,216.461411,false,Manual,3.0",
            ["GUID"] = "C8A5DE34",
            ["NextDialogue"] = 80150323,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Explain02_End",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/003/C8A5DE34",
            },
        [80150323] = {
            ["Content"] = "节奏对不上也没关系，这不是考试。音乐本来就是自由的。",
            ["ContentKR"] = "리듬이 맞지 않아도 괜찮아요. 이건 테스트가 아니니까요. 음악은 원래 자유로운 거예요.",
            ["DialogueId"] = 80150323,
            ["GUID"] = "C8A5DE5E",
            ["NextDialogue"] = 80150324,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Lise/003/C8A5DE5E",
            },
        [80150324] = {
            ["Camera"] = "38.568848,23.305664,122.765625,0.000132,6.796339,-167.826828,35.000008,100000.0,false,DoNotOverride,3.0",
            ["Content"] = "我想，“黎瑟”这个名字也是一样……它的意义，或许并不是让你按照某种既定的“节奏”去生活，而是希望你能找到属于自己的“节奏”。",
            ["ContentKR"] = "'리듬'이란 이름도 마찬가지일 거예요... 그 의미는 정해진 '리듬'에 맞춰 살아가라는 게 아니라, 당신만의 '리듬'을 찾으라는 뜻일지도 몰라요.",
            ["DialogueId"] = 80150324,
            ["FacialId"] = {
                [1] = "790008:Smile02",
                },
            ["FinalCamera"] = "38.568848,23.305664,122.765625,0.000139,6.796339,-167.826813,37.0,100000.0,false,DoNotOverride,3.0",
            ["GUID"] = "C8A5DE88",
            ["NextDialogue"] = 80150325,
            ["SpeakNpcId"] = 790008,
            ["ToFinalCameraBlendTime"] = 11,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/003/C8A5DE88",
            },
        [80150325] = {
            ["Camera"] = "-167.373047,41.786133,148.665527,0.000146,-6.203799,-14.629342,35.0,245.243332,false,Manual,5.0",
            ["Content"] = "那么，什么是你自己的“节奏”呢？我想等你彻底学会这首曲子，你就会明白了。",
            ["ContentKR"] = "그러니까 항상 그렇게 긴장할 필요는 없어요. 매일 스스로에게 일을 만들어 바쁘게 지내지 않아도 돼요. 조금 더 자유롭게 살고, 언제 나아갈지, 언제 멈출지를 스스로 정해보세요!\
그럼, 당신만의 '리듬'이란 뭘까요? 제 생각엔, 이 곡을 완전히 익히고 나면 그 답을 알게 될 거예요.",
            ["DialogueId"] = 80150325,
            ["GUID"] = "C8A5DEB2",
            ["NextDialogue"] = 80150326,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Lise/003/C8A5DEB2",
            },
        [80150326] = {
            ["Camera"] = "244.240723,98.888672,201.875,0.000206,-16.603704,-157.425842,35.000008,334.226532,false,Manual,5.0",
            ["Content"] = "想要吹好这首曲子，就得花时间去练习；想要学到更多曲子，就得再次去书店逛一逛；想和别人分享春天与希望，就要吹奏给别人听。",
            ["ContentKR"] = "이 곡을 잘 연주하려면 시간을 들여 연습해야 하고, 더 많은 곡을 배우려면 다시 책방을 방문해야 해요. 봄과 희망을 다른 사람과 나누고 싶다면, 그들에게 연주를 들려줘야겠죠.",
            ["DialogueId"] = 80150326,
            ["FacialId"] = {
                [1] = "790008:None",
                },
            ["FinalCamera"] = "247.649902,90.350098,201.875,0.000204,-16.203674,-160.425781,35.000008,334.226532,false,Manual,5.0",
            ["GUID"] = "C8A5DEDC",
            ["NextDialogue"] = 80150327,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Explain01_Start",
                },
            ["ToFinalCameraBlendTime"] = 14,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/003/C8A5DEDC",
            },
        [80150327] = {
            ["Camera"] = "66.17334,44.016113,92.894775,5.000216,15.596025,-162.825012,35.0,141.857666,false,Manual,3.0",
            ["Content"] = "没有一个时间表规定了应该什么时候做这些。决定要在什么时候做这些的，是你自己的心情，而心情的起伏，也就是你自己的“节奏”。",
            ["ContentKR"] = "이걸 언제 해야 한다고 정해진 시간표는 없어요. 언제 할지는 당신의 마음에 달려 있고, 마음의 변화가 바로 당신의 '리듬'이에요.",
            ["DialogueId"] = 80150327,
            ["FinalCamera"] = "66.17334,44.016113,92.894775,5.000216,15.596025,-162.825012,35.0,141.857666,false,Manual,3.0",
            ["GUID"] = "C8A5DF06",
            ["NextDialogue"] = 80150328,
            ["SpeakNpcId"] = 790008,
            ["ToFinalCameraBlendTime"] = 13,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/003/C8A5DF06",
            },
        [80150328] = {
            ["Camera"] = "140.223633,32.546387,132.494873,0.000125,0.796605,-167.824188,55.0,206.818161,false,Manual,6.0",
            ["Content"] = "当然，如果你偶尔需要有个人帮你读谱的话……我随时在这里。",
            ["ContentKR"] = "물론, 가끔 악보를 읽는 데 도움이 필요하다면... 언제든지 제가 여기 있을게요.",
            ["DialogueId"] = 80150328,
            ["FinalCamera"] = "139.521973,35.797363,132.494873,0.000125,0.796605,-167.024063,55.0,206.818161,false,Manual,6.0",
            ["GUID"] = "C8A5DF30",
            ["NextDialogue"] = 80150329,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Explain01_End",
                },
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/003/C8A5DF30",
            },
        [80150329] = {
            ["Camera"] = "-7.366699,20.205078,123.453613,0.000125,11.996175,-13.829354,35.000008,100000.0,false,DoNotOverride,3.0",
            ["Content"] = "你……",
            ["ContentKR"] = "당신...",
            ["DialogueId"] = 80150329,
            ["FacialId"] = {
                [1] = "790044:Shock01",
                },
            ["GUID"] = "C8A5DF5A",
            ["NextDialogue"] = 80150330,
            ["SpeakNpcId"] = 790044,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/003/C8A5DF5A",
            },
        [80150330] = {
            ["Camera"] = "-169.143555,52.443359,147.212646,0.000124,-5.404018,-18.232069,35.000008,100000.0,false,DoNotOverride,3.0",
            ["Content"] = "谢谢。这是我听到的，关于这个名字最好的解读。",
            ["ContentKR"] = "고마워요. 이 이름에 대해 들어본 해석 중에 가장 마음에 들어요.",
            ["DialogueId"] = 80150330,
            ["FacialId"] = {
                [1] = "790044:Happy01",
                },
            ["FinalCamera"] = "-168.707031,53.768555,147.212646,0.000124,-5.404018,-18.832098,35.000008,100000.0,false,DoNotOverride,3.0",
            ["GUID"] = "C8A5DF84",
            ["NextDialogue"] = 80150331,
            ["SpeakNpcId"] = 790044,
            ["TalkActionId"] = {
                [1] = "790044:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/003/C8A5DF84",
            },
        [80150331] = {
            ["Camera"] = "7.588379,267.65625,167.518799,0.00021,-12.203245,-91.424835,25.0,260.775696,false,Manual,1.2",
            ["Content"] = "你的这番话，我会记在心里。",
            ["ContentKR"] = "당신의 말을 마음에 새길게요.",
            ["DialogueId"] = 80150331,
            ["FinalCamera"] = "7.588379,267.65625,174.300049,0.000211,-14.003322,-91.624878,25.0,260.775696,false,Manual,1.2",
            ["GUID"] = "C8A5DFAE",
            ["NextDialogue"] = 80150332,
            ["SpeakNpcId"] = 790044,
            ["TalkActionId"] = {
                [1] = "790044:AgreeHead",
                },
            ["ToFinalCameraBlendTime"] = 3,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/003/C8A5DFAE",
            },
        [80150332] = {
            ["Camera"] = "-8.575684,5.778809,133.86499,0.000219,2.596681,-3.625247,25.0,73.127831,false,Manual,5.0",
            ["Content"] = "如果你愿意包容我的笨拙，见证我的改变……我向你约定，等我真正找到属于自己的“节奏”，一定会最先分享给你。",
            ["ContentKR"] = "제 서툰 모습을 받아주고, 변화하는 저를 지켜봐준다면... 제가 진정한 '리듬'을 찾았을 때, 가장 먼저 당신에게 알려줄게요.",
            ["DialogueId"] = 80150332,
            ["FinalCamera"] = "-8.575684,5.778809,133.86499,0.000219,2.596688,-3.625247,28.0,73.127831,false,Manual,5.0",
            ["GUID"] = "C8A5DFD8",
            ["SpeakNpcId"] = 790044,
            ["ToFinalCameraBlendTime"] = 13,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/003/C8A5DFD8",
            },
        [80160001] = {
            ["Content"] = "希望你能让我满意。",
            ["ContentKR"] = "날 만족시켜 주길 바란다.",
            ["DialogueId"] = 80160001,
            ["GUID"] = "C8AC122A",
            ["SpeakNpcId"] = 790055,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/001/C8AC122A",
            },
        [80160101] = {
            ["Camera"] = "151.585999,-190.824707,95.898872,0.000003,1.80011,-153.390167,39.474983,223.616684,false,Manual,2.8",
            ["Content"] = "确实是个安静的地方。",
            ["ContentKR"] = "확실히 조용한 곳이군.",
            ["DialogueId"] = 80160101,
            ["Duration"] = 1,
            ["GUID"] = "C8AC2292",
            ["NextDialogue"] = 80160102,
            ["Scripts"] = "MoveTo{ActorId{790055},TargetPoint{\"Move_320101\"},MoveSpeed{80},Visibility{\"Show\"}}",
            ["SpeakNpcId"] = 790055,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/001/C8AC2292",
            },
        [80160102] = {
            ["Camera"] = "-31.074158,-13.146484,130.436157,0.000003,0.199305,-130.376617,28.875509,223.616684,false,Manual,2.8",
            ["Content"] = "老板，请给我上一杯酒。",
            ["ContentKR"] = "여기, 술 한잔 부탁해.",
            ["DialogueId"] = 80160102,
            ["Duration"] = 3,
            ["GUID"] = "C8AC22BC",
            ["LookAt"] = {
                [1] = "790055:n(790008)",
                },
            ["NextOptions"] = {
                [1] = 801601021,
                [2] = 801601022,
                },
            ["SpeakNpcId"] = 790055,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/001/C8AC22BC",
            },
        [80160103] = {
            ["Content"] = "冰湖城北边的宅子，摆放着钢琴、铁砧、沙漏，那里有着一位会用自制饮料招待朋友的住客。{性别：他|她}也乐于结识没有恶意的陌生人。",
            ["ContentKR"] = "\"아이스레이크 북쪽. 피아노와 모루, 모래시계가 놓여 있는 저택이에요. 거기 손수 만든 음료로 친구를 대접하는 투숙객이 있어요. 악의 없는 낯선 이와의 만남도 즐기는 {性别:사람|사람}이죠.\"",
            ["DialogueId"] = 80160103,
            ["Duration"] = 3,
            ["GUID"] = "C8AC22E6",
            ["NextDialogue"] = 80160104,
            ["SpeakNpcId"] = 790055,
            ["TalkActionId"] = {
                [1] = "790055:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Haier/001/C8AC22E6",
            },
        [80160104] = {
            ["Content"] = "“在那里，我可以安安静静、无人打扰地喝上一杯。”",
            ["ContentKR"] = "\"거기서 전 조용히, 아무에게도 방해받지 않고 술 한 잔의 여유를 즐길 수 있죠.\"",
            ["DialogueId"] = 80160104,
            ["Duration"] = 3,
            ["GUID"] = "C8AC2310",
            ["NextDialogue"] = 80160105,
            ["SpeakNpcId"] = 790055,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/001/C8AC2310",
            },
        [80160105] = {
            ["Content"] = "水仙平原的老板，卡米拉·斯卡雷特是如此告知我的，难道她说谎了？",
            ["ContentKR"] = "아스포델의 주인, 카밀라 스칼렛이 그렇게 말하던데, 설마 카밀라가 거짓말을 한 건가?",
            ["DialogueId"] = 80160105,
            ["Duration"] = 3,
            ["GUID"] = "C8AC233A",
            ["NextOptions"] = {
                [1] = 801601071,
                },
            ["SpeakNpcId"] = 790055,
            ["TalkActionId"] = {
                [1] = "790055:Talk01_Loop",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Haier/001/C8AC233A",
            },
        [80160106] = {
            ["Content"] = "你是指卡米拉·斯卡雷特的水仙平原。其实，就是她介绍我来这里的。",
            ["ContentKR"] = "카밀라 스칼렛의 아스포델 얘기겠지. 여길 내게 소개해 준 게 바로 카밀라다.",
            ["DialogueId"] = 80160106,
            ["Duration"] = 3,
            ["GUID"] = "C8AC2364",
            ["NextDialogue"] = 80160107,
            ["SpeakNpcId"] = 790055,
            ["TalkActionId"] = {
                [1] = "790055:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Haier/001/C8AC2364",
            },
        [80160107] = {
            ["Content"] = "她那里的酒水几乎能与皇都媲美，酒客们趋之若鹜。但今天，我只想要一个清静的地方，再毫无顾忌地喝上两杯。",
            ["ContentKR"] = "아스포델의 술은 황성과 견줄 만큼 훌륭해서, 술꾼들로 발 디딜 틈이 없지. 하지만 오늘은 그저 조용한 곳에서 걱정 없이 두어 잔 마시고 싶군.",
            ["DialogueId"] = 80160107,
            ["Duration"] = 3,
            ["GUID"] = "C8AC238E",
            ["NextOptions"] = {
                [1] = 801601071,
                },
            ["SpeakNpcId"] = 790055,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/001/C8AC238E",
            },
        [80160108] = {
            ["Content"] = "怎么，是我的肤色，还是这把武器让你这么警惕？轻松点，卡米拉给我写了个便条，让我交给你。",
            ["ContentKR"] = "왜, 내 피부색 때문인가? 아니면 이 무기 때문에 긴장한 건가? 걱정 마, 카밀라가 이 쪽지를 바텐더한테 주라더군.",
            ["DialogueId"] = 80160108,
            ["Duration"] = 3,
            ["GUID"] = "C8AC23B8",
            ["NextDialogue"] = 80160109,
            ["Scripts"] = "PlayAnimation{_delay{2},ActorId{790055},AnimationId{\"Talk02_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 790055,
            ["TalkActionId"] = {
                [1] = "790055:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Haier/001/C8AC23B8",
            },
        [80160109] = {
            ["Content"] = "“好好招待这位客人，酬劳明天来水仙平原取。”",
            ["ContentKR"] = "\"이 손님을 잘 대접해 드려. 보수는 내일 아스포델에 와서 가져가.\"",
            ["DialogueId"] = 80160109,
            ["Duration"] = 3,
            ["GUID"] = "C8AC23E2",
            ["IsBlack"] = 1,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/001/C8AC23E2",
            },
        [80160110] = {
            ["Camera"] = "-147.684692,-116.645508,164.708984,0.000248,-3.398497,41.200367,42.28323,451.476898,false,DoNotOverride,10.496961",
            ["Content"] = "唉……老实说，我一点都不想拒绝您，毕竟，触怒您这样的大人物，对我可一点好处都没有。\
",
            ["ContentKR"] = "휴... 솔직히 말씀드리자면, 거절하고 싶지는 않아요. 당신 같은 거물을 화나게 해 봐야 제게 이득 될 게 없으니까요.",
            ["DialogueId"] = 80160110,
            ["Duration"] = 5,
            ["GUID"] = "C8AC240C",
            ["NextDialogue"] = 80160111,
            ["SpeakNpcId"] = 790052,
            ["TalkActionId"] = {
                [1] = "790052:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Haier/001/C8AC240C",
            },
        [80160111] = {
            ["Camera"] = "359.205933,-102.777344,311.273438,0.000032,-20.600035,174.999359,25.177044,203.023346,false,Manual,5.70148",
            ["Content"] = "我没有带多余的随从，也没有声张自己的行踪。女士，哪怕单纯因为你认出了我，我都应该在这里喝上一杯。",
            ["ContentKR"] = "난 쓸데없는 수행원을 데려오지도, 행적을 떠벌리지도 않았다. 그쪽이 날 알아봤다는 걸로만도 여기서 한잔할 이유는 충분해 보이는데.",
            ["DialogueId"] = 80160111,
            ["Duration"] = 5,
            ["FinalCamera"] = "359.205933,-102.777344,276.765625,0.000032,-20.600035,174.999359,25.177044,203.023346,false,Manual,5.70148",
            ["GUID"] = "C8AC2436",
            ["NextDialogue"] = 80160112,
            ["SpeakNpcId"] = 790055,
            ["TalkActionId"] = {
                [1] = "790055:Talk03_Start",
                [2] = "790052:Talk01_End",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/001/C8AC2436",
            },
        [80160112] = {
            ["Camera"] = "-310.237366,-391.768555,153.707031,0.000077,-1.999442,56.994724,43.855331,203.023346,false,Manual,5.70148",
            ["Content"] = "从帝国最南端与艾利西安接壤的边境线，到帝国最北端的维德弗尼尔山脉，您的大名无人不知无人不晓——",
            ["ContentKR"] = "그야 제국 최남단 엘리시안과 맞닿은 국경선부터 최북단 베드르폴니르 산맥까지, 이름을 모르는 이가 없을 정도로 명성이 자자하시니까요.",
            ["DialogueId"] = 80160112,
            ["Duration"] = 5,
            ["GUID"] = "C8AC2460",
            ["NextDialogue"] = 80160113,
            ["SpeakNpcId"] = 790052,
            ["TalkActionId"] = {
                [1] = "790052:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Haier/001/C8AC2460",
            },
        [80160113] = {
            ["Camera"] = "14.798828,-154.951172,149.396484,0.000091,-9.39922,-174.809311,43.855331,203.023346,false,Manual,5.70148",
            ["Content"] = "况且有关您的传闻，每一件都会提及您火一般的肤色。",
            ["ContentKR"] = "게다가 당신에 대한 소문에는 하나같이 불꽃 같은 피부색이 언급되곤 하더군요.",
            ["DialogueId"] = 80160113,
            ["Duration"] = 3,
            ["FinalCamera"] = "14.798828,-154.951172,177.433594,0.000091,-9.39922,-174.809311,43.855331,203.023346,false,Manual,5.70148",
            ["GUID"] = "C8AC248A",
            ["NextDialogue"] = 80160114,
            ["SpeakNpcId"] = 790052,
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/001/C8AC248A",
            },
        [80160114] = {
            ["Content"] = "冰湖城虽然衰落，但好歹是北方最大的城市……再怎么说我也是在这里开了很久的店，相信我，认出您并不是一件难事。",
            ["ContentKR"] = "아이스레이크 시티는 비록 쇠락했지만, 그래도 북쪽에서 가장 큰 도시예요... 이래 봬도 전 여기서 꽤 오랫동안 가게를 운영해 왔고요. 그러니 당신을 알아보는 건 전혀 어려운 일이 아니랍니다.",
            ["DialogueId"] = 80160114,
            ["Duration"] = 5,
            ["GUID"] = "C8AC24B4",
            ["NextDialogue"] = 80160115,
            ["SpeakNpcId"] = 790052,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/001/C8AC24B4",
            },
        [80160115] = {
            ["Camera"] = "263.591919,95.413086,166.505859,0.000114,-4.198818,-154.60791,49.593163,451.476898,false,DoNotOverride,10.496961",
            ["Content"] = "真令人头疼，我本来以为最多会引起一些人的侧目，没想到在这么一个冷清的酒馆里还是被人立刻认了出来。",
            ["ContentKR"] = "골치 아프게 됐군. 기껏해야 겨우 몇 명쯤 쳐다보려나 했는데, 이렇게 한적한 술집에서까지 날 알아볼 줄이야.",
            ["DialogueId"] = 80160115,
            ["Duration"] = 3,
            ["GUID"] = "C8AC24DE",
            ["NextDialogue"] = 80160116,
            ["SpeakNpcId"] = 790055,
            ["TalkActionId"] = {
                [1] = "790055:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Haier/001/C8AC24DE",
            },
        [80160116] = {
            ["Camera"] = "-318.082764,-391.271484,146.335938,0.000113,-0.998813,54.392494,49.593163,451.476898,false,DoNotOverride,10.496961",
            ["Content"] = "典狱长大人，也许您与犯人打交道的时间太多，以致于您没有意识到，如果一家开酒馆在这个时间点只有一位客人，那么应该早就倒闭了。",
            ["ContentKR"] = "교도소장님, 죄수들과 너무 많은 시간을 보내시느라, 미처 알아채지 못하셨나 본데요, 이 시간대에 손님이 단 한 명뿐인 술집이라면, 진작 파산했어야 정상이에요.",
            ["DialogueId"] = 80160116,
            ["Duration"] = 3,
            ["GUID"] = "C8AC2508",
            ["NextDialogue"] = 80160117,
            ["Scripts"] = "SEQ{\
CameraMoveTo{_delay{3},TargetPosition{\"-46.92395,-890.245117,476.808594,0.000107,-12.998778,134.186493,25.505644,451.476898,false,DoNotOverride,10.496961\"},duration{0}},\
CameraMoveTo{TargetPosition{\"-46.92395,-890.245117,476.808594,0.000113,-11.398554,-178.21524,25.505644,451.476898,false,DoNotOverride,10.496961\"},duration{40}}\
}",
            ["SpeakNpcId"] = 790052,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/001/C8AC2508",
            },
        [80160117] = {
            ["Content"] = "喏，好几个人在门口探头探脑不敢进来——显然，认出您的可不止我一个。我倒是很愿意在这里为您单独服务，但皇都官僚强行包场这样的闲话，我可没法管。",
            ["ContentKR"] = "보세요, 사람들이 문밖에서 머뭇거리기만 하고 들어오질 않잖아요. 아무래도 교도소장님을 알아본 건 저뿐만이 아닌 것 같죠? 전담 서비스를 해드리고는 싶지만, 황성의 관료가 막무가내로 술집을 전세 냈다는 소문이라도 퍼지면, 저도 어쩔 도리가 없어요.",
            ["DialogueId"] = 80160117,
            ["Duration"] = 5,
            ["GUID"] = "C8AC2532",
            ["NextDialogue"] = 80160118,
            ["SpeakNpcId"] = 790052,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/001/C8AC2532",
            },
        [80160118] = {
            ["Camera"] = "393.698364,122.831055,270.308594,0.000183,-14.198112,-159.790924,28.136471,451.476898,false,DoNotOverride,10.496961",
            ["Content"] = "你说得没错，在这里暴露行踪并非我的本意，谢谢你的提醒——虽然你的目的也不仅仅是帮我掩饰行踪。",
            ["ContentKR"] = "일리 있는 말이군. 행적을 드러내는 건 내 의도가 아니다. 경고는 고맙게 받아들이지. 목적이 단순히 내 행적을 숨겨주려는 게 아닌 건 알지만 말이야.",
            ["DialogueId"] = 80160118,
            ["Duration"] = 3,
            ["FinalCamera"] = "378.453979,117.220703,266.197266,0.000183,-14.198112,-159.790924,28.136471,451.476898,false,DoNotOverride,10.496961",
            ["GUID"] = "C8AC255C",
            ["NextDialogue"] = 80160119,
            ["SpeakNpcId"] = 790055,
            ["TalkActionId"] = {
                [1] = "790055:Talk02_Start",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/001/C8AC255C",
            },
        [80160119] = {
            ["Camera"] = "-65.366943,-360.875,145.677734,0.000188,-1.99826,138.407349,28.136471,451.476898,false,DoNotOverride,10.496961",
            ["Content"] = "（海尔法意味深长地看了一眼酒吧大厅里的机械齿轮，很显然，她能够察觉到机械结构的另一端联结着被精心隐藏的秘密。）",
            ["ContentKR"] = "(헬파이어가 술집 홀에 있는 기계 톱니를 유심히 바라본다. 기계 구조물 반대편에 정교하게 숨겨진 비밀이 연결되어 있다는 것을 감지한 게 분명하다.)",
            ["DialogueId"] = 80160119,
            ["Duration"] = 3,
            ["GUID"] = "C8AC2586",
            ["LookAt"] = {
                [1] = "790055:p(Look_H)",
                },
            ["NextDialogue"] = 80160120,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/001/C8AC2586",
            },
        [80160120] = {
            ["Camera"] = "-75.942627,-56.601562,151.488281,0.000211,-2.598238,-139.994705,35.0,451.476898,false,DoNotOverride,10.496961",
            ["Content"] = "那里藏着一个秘密。将谜面放在一个如此明显的地方，我佩服你的胆量。",
            ["ContentKR"] = "저기 뭔가 숨겨져 있군. 이렇게 눈에 띄는 곳에 비밀을 숨겨 두다니, 배짱 한번 대단한데.",
            ["DialogueId"] = 80160120,
            ["Duration"] = 3,
            ["GUID"] = "C8AC25B0",
            ["LookAt"] = {
                [1] = "790055:n(790052)",
                },
            ["NextDialogue"] = 80160121,
            ["SpeakNpcId"] = 790055,
            ["TalkActionId"] = {
                [1] = "790055:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Haier/001/C8AC25B0",
            },
        [80160121] = {
            ["Content"] = "又或者你比我想的更有手腕，为了还能在这里讨一杯酒喝，又或者为了能在这个城市里平安度日，人们总会为你守口如瓶。",
            ["ContentKR"] = "아니면 내 생각보다 수완이 좋은 건가? 술 한 잔 더 얻어 마시거나, 아니면 이 도시에서 평안히 살아가기 위해, 사람들이 당신의 비밀을 기꺼이 지켜준다든가 말이야.",
            ["DialogueId"] = 80160121,
            ["Duration"] = 3,
            ["GUID"] = "C8AC25DA",
            ["NextDialogue"] = 80160122,
            ["SpeakNpcId"] = 790055,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/001/C8AC25DA",
            },
        [80160122] = {
            ["Camera"] = "-59.147827,-133.68457,134.808594,0.000211,8.401542,69.408882,35.0,451.476898,false,DoNotOverride,10.496961",
            ["Content"] = "呵呵……感谢您的谬赞，可惜我只是个连拖欠税款都万万不敢的酒馆老板。至于秘密，谁没有几个秘密呢？",
            ["ContentKR"] = "후후... 과찬이세요. 아쉽게도, 전 감히 세금 밀릴 엄두도 못 내는 술집 주인일 뿐이랍니다. 비밀이라... 세상에 비밀 없는 사람이 있을까요?",
            ["DialogueId"] = 80160122,
            ["Duration"] = 5,
            ["FacialId"] = {
                [1] = "790052:Smile01",
                },
            ["FinalCamera"] = "-46.137329,-99.043945,142.054688,0.000211,8.401542,69.408882,35.0,451.476898,false,DoNotOverride,10.496961",
            ["GUID"] = "C8AC2604",
            ["NextDialogue"] = 80160123,
            ["SpeakNpcId"] = 790052,
            ["ToFinalCameraBlendTime"] = 25,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/001/C8AC2604",
            },
        [80160123] = {
            ["Content"] = "况且“秘密”也不总是一把锋利的刀子，它也可能是一张传承了三代人的火腿秘方，我到现在没有把它端上来，只是因为不确定是否合您的口味。",
            ["ContentKR"] = "게다가 '비밀'이란 게 꼭 날카로운 칼만은 아니죠. 3대를 이어온 햄 레시피일 수도 있잖아요? 여태 내놓지 않은 건, 혹시 교도소장님 입맛에 맞지 않으면 어쩌나 해서였을 뿐이에요.",
            ["DialogueId"] = 80160123,
            ["Duration"] = 5,
            ["GUID"] = "C8AC262E",
            ["NextDialogue"] = 80160124,
            ["SpeakNpcId"] = 790052,
            ["TalkActionId"] = {
                [1] = "790052:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Haier/001/C8AC262E",
            },
        [80160124] = {
            ["Camera"] = "-86.051514,-78.273438,146.841797,0.000205,-1.598749,-143.392212,35.0,451.476898,false,DoNotOverride,10.496961",
            ["Content"] = "呵，有趣……我在擅于搜查的下属那里听过类似的笑话。",
            ["ContentKR"] = "오, 재밌군... 수사에 능한 부하에게서 비슷한 농담을 들어본 적이 있어.",
            ["DialogueId"] = 80160124,
            ["Duration"] = 3,
            ["GUID"] = "C8AC2658",
            ["NextDialogue"] = 80160125,
            ["SpeakNpcId"] = 790055,
            ["TalkActionId"] = {
                [1] = "790055:Confident_Start",
                [2] = "790052:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Haier/001/C8AC2658",
            },
        [80160125] = {
            ["Content"] = "别紧张，女士。",
            ["ContentKR"] = "긴장 풀어, 카밀라 씨.",
            ["DialogueId"] = 80160125,
            ["Duration"] = 3,
            ["GUID"] = "C8AC2682",
            ["NextDialogue"] = 80160126,
            ["SpeakNpcId"] = 790055,
            ["TalkActionId"] = {
                [1] = "790055:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Haier/001/C8AC2682",
            },
        [80160126] = {
            ["Camera"] = "279.85791,105.764648,170.447266,0.000227,-3.998898,-152.592499,68.94529,451.476898,false,DoNotOverride,10.496961",
            ["Content"] = "这里是你的“水仙平原”，不是法庭，也不是皇家监狱，没有人会把吐真剂扎进你的脖子，逼你坦白从宽。",
            ["ContentKR"] = "여긴 법정도 아니고 황실 감옥도 아닌, 당신의 술집 '아스포델'이다. 목구멍에 약물을 들이부어 진실을 토해내게 할 사람은 없어.",
            ["DialogueId"] = 80160126,
            ["Duration"] = 3,
            ["GUID"] = "C8AC26AC",
            ["NextDialogue"] = 80160127,
            ["SpeakNpcId"] = 790055,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/001/C8AC26AC",
            },
        [80160127] = {
            ["Content"] = "我到冰湖城有自己的目的，而你也有自己的生存方式，我们没有在这张“火腿秘方”上消耗太多时间的必要。",
            ["ContentKR"] = "내가 아이스레이크 시티로 온 데는 나만의 목적이 있고, 당신은 당신만의 생존 방식이 있으니, '비법 햄 레시피'에 너무 많은 시간을 낭비할 필요는 없을 것 같군.",
            ["DialogueId"] = 80160127,
            ["Duration"] = 3,
            ["GUID"] = "C8AC26D6",
            ["NextDialogue"] = 80160128,
            ["SpeakNpcId"] = 790055,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/001/C8AC26D6",
            },
        [80160128] = {
            ["Content"] = "既然话已经说开，那么我也不在这里阻碍你的生意了。",
            ["ContentKR"] = "할 얘긴 끝난 것 같으니 더 이상 장사를 방해하진 않겠다.",
            ["DialogueId"] = 80160128,
            ["GUID"] = "C8AC2700",
            ["NextDialogue"] = 80160129,
            ["Scripts"] = "SEQ{\
LookAt{_delay{1},LookAtDescription{\"790055:n(790055)\"}},\
TurnTo{TurnToDescription{\"790055:p(-180)\"}},\
MoveTo{ActorId{790055},TargetPoint{\"Move_H\"},MoveSpeed{80},Visibility{\"Show\"}}\
}",
            ["SpeakNpcId"] = 790055,
            ["TalkActionId"] = {
                [1] = "790055:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Haier/001/C8AC2700",
            },
        [80160129] = {
            ["Camera"] = "-105.736328,-382.012695,149.125,0.000248,-3.398559,147.008057,39.565411,252.247864,false,Manual,2.892425",
            ["Content"] = "也许你会想知道，我为什么要特意指出你的秘密。",
            ["ContentKR"] = "내가 왜 굳이 당신의 비밀을 언급했는지 궁금할지도 모르겠군.",
            ["DialogueId"] = 80160129,
            ["Duration"] = 3,
            ["GUID"] = "C8AC272A",
            ["NextDialogue"] = 80160130,
            ["SpeakNpcId"] = 790055,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/001/C8AC272A",
            },
        [80160130] = {
            ["Content"] = "我并没有恶意，请当做是我的职业病在发作——我总是无法放过在我面前游走的谎言与隐瞒。",
            ["ContentKR"] = "악의는 없었다. 내 직업병이 발동했다고 생각해 둬. 눈앞에 보이는 거짓과 은폐를 그냥 지나칠 수가 없어서 말이지.",
            ["DialogueId"] = 80160130,
            ["Duration"] = 5,
            ["GUID"] = "C8AC2754",
            ["LookAt"] = {
                [1] = "790055:n(790052)",
                },
            ["NextDialogue"] = 80160131,
            ["SpeakNpcId"] = 790055,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/001/C8AC2754",
            },
        [80160131] = {
            ["Content"] = "无法在冰湖城中最好的酒馆喝上一杯，我深表遗憾。告辞。",
            ["ContentKR"] = "아이스레이크 시티 최고의 술집에서 한잔하지 못하다니, 매우 유감이군. 그럼 이만.",
            ["DialogueId"] = 80160131,
            ["Duration"] = 3,
            ["GUID"] = "C8AC277E",
            ["LookAt"] = {
                [1] = "790055:n(790055)",
                },
            ["NextDialogue"] = 80160132,
            ["SpeakNpcId"] = 790055,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/001/C8AC277E",
            },
        [80160132] = {
            ["Camera"] = "-141.847046,-192.130859,169.498047,0.000235,-3.798828,56.604771,47.597221,451.476898,false,DoNotOverride,10.496961",
            ["Content"] = "请您留步。",
            ["ContentKR"] = "잠시만요.",
            ["DialogueId"] = 80160132,
            ["Duration"] = 3,
            ["FacialId"] = {
                [1] = "790052:None",
                },
            ["GUID"] = "C8AC27A8",
            ["LookAt"] = {
                [1] = "790055:n(790052)",
                },
            ["NextDialogue"] = 80160133,
            ["SpeakNpcId"] = 790052,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/001/C8AC27A8",
            },
        [80160133] = {
            ["Camera"] = "204.932251,65.897461,166.253906,0.000237,-5.198696,-153.398605,35.000008,451.476898,false,DoNotOverride,10.496961",
            ["Content"] = "还有事？",
            ["ContentKR"] = "할 말이 남았나?",
            ["DialogueId"] = 80160133,
            ["Duration"] = 3,
            ["GUID"] = "C8AC27D2",
            ["LookAt"] = {
                [1] = "790055:n(790052)",
                },
            ["NextDialogue"] = 80160134,
            ["SpeakNpcId"] = 790055,
            ["TurnTo"] = {
                [1] = "790055:p(75)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Haier/001/C8AC27D2",
            },
        [80160134] = {
            ["Camera"] = "-146.874878,-117.574219,164.708984,0.000248,-3.398497,41.200367,42.28323,451.476898,false,DoNotOverride,10.496961",
            ["Content"] = "冰湖城北边的宅子，摆放着钢琴、铁砧、沙漏，那里有一位会用自制饮料招待朋友的住客。{性别：他|她}也乐于结识没有恶意的陌生人。",
            ["ContentKR"] = "아이스레이크 북쪽. 피아노와 모루, 모래시계가 놓여 있는 저택이에요. 거기 손수 만든 음료로 친구를 대접하는 투숙객이 있어요. 악의 없는 낯선 이와의 만남도 즐기는 {性别:사람|사람}이죠.",
            ["DialogueId"] = 80160134,
            ["Duration"] = 5,
            ["FinalCamera"] = "-117.245117,-91.633789,163.6875,0.000248,-3.398497,41.200367,42.28323,451.476898,false,DoNotOverride,10.496961",
            ["GUID"] = "C8AC27FC",
            ["NextDialogue"] = 80160135,
            ["SpeakNpcId"] = 790052,
            ["ToFinalCameraBlendTime"] = 25,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/001/C8AC27FC",
            },
        [80160135] = {
            ["Content"] = "如果您需要倾诉，{性别：他|她}会是个不错的人选，带着我的委托，{性别：他|她}不会拒绝您。",
            ["ContentKR"] = "하소연이 필요하시다면, {性别:그 친구|그 친구}도 나쁘지 않아요. 제 의뢰서를 가지고 가신다면, 거절하지 않을 거예요.",
            ["DialogueId"] = 80160135,
            ["Duration"] = 3,
            ["GUID"] = "C8AC2826",
            ["NextDialogue"] = 80160136,
            ["SpeakNpcId"] = 790052,
            ["TalkActionId"] = {
                [1] = "790052:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Haier/001/C8AC2826",
            },
        [80160136] = {
            ["Camera"] = "209.813721,89.859375,159.263672,0.000217,-2.798328,-149.798874,61.554684,451.476898,false,DoNotOverride,10.496961",
            ["Content"] = "谢谢。以你的洞察力，不应该只满足于做一个边陲城市的店主才是。",
            ["ContentKR"] = "고맙다. 변방 도시의 가게 주인으로만 머물기에는 아까운 통찰력이군.",
            ["DialogueId"] = 80160136,
            ["Duration"] = 3,
            ["GUID"] = "C8AC2850",
            ["LookAt"] = {
                [1] = "790055:n(790052)",
                },
            ["NextDialogue"] = 80160137,
            ["SpeakNpcId"] = 790055,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/001/C8AC2850",
            },
        [80160137] = {
            ["Camera"] = "-246.633789,-309.449219,143.691406,0.00022,0.201757,52.802853,61.554684,451.476898,false,DoNotOverride,10.496961",
            ["Content"] = "然而，现实总是与人们的想法背道而驰。就像……我也没想过典狱长大人会是如此讲道理的客人。",
            ["ContentKR"] = "하지만 현실은 항상 사람들의 생각과는 반대로 흘러가곤 하죠. 마치... 교도소장님이 이렇게 말이 통하는 손님일 줄 몰라본 저처럼요.",
            ["DialogueId"] = 80160137,
            ["Duration"] = 3,
            ["GUID"] = "C8AC287A",
            ["NextDialogue"] = 80160138,
            ["SpeakNpcId"] = 790052,
            ["TalkActionId"] = {
                [1] = "790052:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Haier/001/C8AC287A",
            },
        [80160138] = {
            ["Content"] = "因为一些原因，我不会奉上自我介绍。你可以把我当做一个风尘仆仆的过路人，此刻琐事缠身，需要一杯能暂忘忧愁的饮料。",
            ["ContentKR"] = "이런저런 이유로 인해, 내 소개는 생략하겠다. 날 긴 여정에 지친 행인으로 생각해도 좋아. 지금은 번잡한 일들이 많아서, 근심을 잊게 해줄 음료를 한잔해야겠군.",
            ["DialogueId"] = 80160138,
            ["Duration"] = 5,
            ["GUID"] = "C8AC28A4",
            ["IsBlack"] = 1,
            ["SpeakNpcId"] = 790055,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/001/C8AC28A4",
            },
        [80160201] = {
            ["Camera"] = "135.91098,22.045166,124.542297,0.000012,1.800007,-136.994522,35.0,158.845352,false,Manual,3.0",
            ["Content"] = "……",
            ["ContentKR"] = "......",
            ["DialogueId"] = 80160201,
            ["GUID"] = "C8AC32FA",
            ["NextOptions"] = {
                [1] = 801602011,
                },
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/002/C8AC32FA",
            },
        [80160202] = {
            ["Content"] = "无妨。今天我有一个晚上的空闲。",
            ["ContentKR"] = "괜찮아. 오늘 밤은 시간이 많으니까.",
            ["DialogueId"] = 80160202,
            ["GUID"] = "C8AC3324",
            ["NextDialogue"] = 80160203,
            ["SpeakNpcId"] = 93201,
            ["TalkActionId"] = {
                [1] = "93201:Sit_DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Haier/002/C8AC3324",
            },
        [80160203] = {
            ["Content"] = "看这里的居住痕迹，我猜你已经在这里停驻了很长的时间，但你对物品的摆放却如此陌生。",
            ["ContentKR"] = "집안 모습을 보니, 여기 꽤 오랫동안 머물렀던 걸로 보이는데, 물건들이 어디 있는지는 잘 모르나 보군.",
            ["DialogueId"] = 80160203,
            ["GUID"] = "C8AC334E",
            ["NextDialogue"] = 80160204,
            ["SpeakNpcId"] = 93201,
            ["TalkActionId"] = {
                [1] = "93201:Sit_Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Haier/002/C8AC334E",
            },
        [80160204] = {
            ["Content"] = "虽然只是客居此地，但我仍然建议你在空闲的时候将屋子彻底清理一遍，最好能弄清楚这里的一点一滴。",
            ["ContentKR"] = "손님으로 머무르는 곳이라도, 시간 날 때 집을 깨끗하게 한번 청소하는 게 좋아. 가능하다면 최대한 빈틈없이 파악해 두고.",
            ["DialogueId"] = 80160204,
            ["GUID"] = "C8AC3378",
            ["NextOptions"] = {
                [1] = 801602041,
                [2] = 801602042,
                },
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/002/C8AC3378",
            },
        [80160205] = {
            ["Content"] = "经验之谈罢了。曾经，我和我最可靠的同僚一起走访过很多地方，搜查过许多“温馨的家”，谁能想到呢？",
            ["ContentKR"] = "그냥 경험담이야. 예전에 가장 믿을 만한 동료와 함께 여기저기 찾아다니며 수많은 '아늑한 집'을 수색했었다. 무슨 일이 있었는지 아나?",
            ["DialogueId"] = 80160205,
            ["GUID"] = "C8AC33A2",
            ["NextDialogue"] = 80160206,
            ["SpeakNpcId"] = 93201,
            ["TalkActionId"] = {
                [1] = "93201:Sit_Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Haier/002/C8AC33A2",
            },
        [80160206] = {
            ["Content"] = "栽着名贵品种的花盆里，埋着精心制作的爆炸物；放着孩子儿时日记的抽屉下面，贴着走私集团的名册；作为伴手礼随手收下的酒，却藏着致命的毒药……",
            ["ContentKR"] = "귀한 식물이 심어진 화분에는 정성껏 만든 폭발물이 묻혀 있고, 어린 아이의 일기가 놓인 서랍 밑에는 밀수 단체의 명부가 붙어 있었다. 여행 선물로 받은 술에는 치명적인 독이 숨겨져 있더군...",
            ["DialogueId"] = 80160206,
            ["GUID"] = "C8AC33CC",
            ["NextOptions"] = {
                [1] = 801602061,
                [2] = 801602062,
                },
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/002/C8AC33CC",
            },
        [80160207] = {
            ["Content"] = "不用一脸震惊地看着我，我只是和你分享一下人生经验。一些被便宜出租的房子，特别是租给你这样外乡人的房子，需要格外留心。",
            ["ContentKR"] = "그렇게 놀란 얼굴로 볼 거 없어. 인생 경험을 나누는 것뿐이니까. 싸구려 임대 집, 특히 바텐더 씨 같은 외지인에게 빌려준 집은 각별한 주의가 필요해.",
            ["DialogueId"] = 80160207,
            ["GUID"] = "C8AC33F6",
            ["NextDialogue"] = 80160208,
            ["SpeakNpcId"] = 93201,
            ["TalkActionId"] = {
                [1] = "93201:Sit_Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Haier/002/C8AC33F6",
            },
        [80160208] = {
            ["Content"] = "房东的花言巧语会尽可能从你的口袋里掏走钱币，但这房子里曾发生过什么，又为什么便宜了对此一无所知的外乡人，谁能说得清呢。",
            ["ContentKR"] = "집주인은 온갖 감언이설로 주머니의 돈을 털어가려 하겠지. 하지만 누가 알겠나. 이 집에서 대체 무슨 일이 일어났는지, 왜 무지몽매한 외지인에게 이렇게 싼 가격에 빌려주는지 말이야.",
            ["DialogueId"] = 80160208,
            ["GUID"] = "C8AC3420",
            ["NextOptions"] = {
                [1] = 801602081,
                [2] = 801602082,
                },
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/002/C8AC3420",
            },
        [80160209] = {
            ["Content"] = "给你一句忠告吧——“尽可能留神身边的一切，以免变化发生得猝不及防。”",
            ["ContentKR"] = "충고 한마디 하지. \"주변 모든 것에 주의를 기울여 둬. 변화는 언제나 예상보다 빨리 찾아오니까.\"",
            ["DialogueId"] = 80160209,
            ["GUID"] = "C8AC344A",
            ["NextDialogue"] = 80160210,
            ["SpeakNpcId"] = 93201,
            ["TalkActionId"] = {
                [1] = "93201:Sit_Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Haier/002/C8AC344A",
            },
        [80160210] = {
            ["Content"] = "呵……说着容易，我却不算一个合格的践行者。",
            ["ContentKR"] = "후... 말은 이렇게 하지만, 나도 실천에는 약한 편이야.",
            ["DialogueId"] = 80160210,
            ["GUID"] = "C8AC3474",
            ["NextDialogue"] = 80160211,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/002/C8AC3474",
            },
        [80160211] = {
            ["Content"] = "我的同僚比我更擅长发现蛛丝马迹，她有一双明察秋毫的眼睛，一双灵巧过人的手——爆炸物，人员名单，毒酒，以及种种千奇百怪的罪案痕迹……",
            ["ContentKR"] = "실낱같은 단서를 찾아내는 건 나보다 내 동료가 전문이지. 예리한 눈썰미와 뛰어난 손재주를 가지고 있거든. 폭발물, 명부, 독주, 기상천외한 범죄 흔적들까지 기가 막히게 냄새를 맡지.",
            ["DialogueId"] = 80160211,
            ["GUID"] = "C8AC349E",
            ["NextDialogue"] = 80160212,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/002/C8AC349E",
            },
        [80160212] = {
            ["Content"] = "没有什么能逃过她的搜查。",
            ["ContentKR"] = "그 친구 수사망은 아무도 벗어나지 못해.",
            ["DialogueId"] = 80160212,
            ["GUID"] = "C8AC34C8",
            ["NextDialogue"] = 80160213,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/002/C8AC34C8",
            },
        [80160213] = {
            ["Content"] = "她是我的左膀右臂，这并不只是个形容词，我的双手能融化玻璃，点燃书本。与此相对，我无法亲手检查每一处疑点，也无法触碰那些脆弱的证物。",
            ["ContentKR"] = "내 왼팔이자 오른팔이었다. 단순한 비유가 아니야. 유리를 녹이고, 책을 불태우는 건 내 손으로 할 수 있다. 하지만 의심 가는 곳을 검사하거나 충격에 약한 증거물을 만지는 일은 내 손으로 할 수 없어.",
            ["DialogueId"] = 80160213,
            ["GUID"] = "C8AC34F2",
            ["NextDialogue"] = 80160214,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/002/C8AC34F2",
            },
        [80160214] = {
            ["Content"] = "此时，她就是我的第二双手。",
            ["ContentKR"] = "그럴 때마다 그 친구는 내 두 번째 손이 되어줬지.",
            ["DialogueId"] = 80160214,
            ["GUID"] = "C8AC351C",
            ["NextOptions"] = {
                [1] = 801602141,
                },
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/002/C8AC351C",
            },
        [80160215] = {
            ["Content"] = "离开？哦……怎么不算呢？",
            ["ContentKR"] = "떠났다...라? 음... 그렇게 볼 수도 있겠군.",
            ["DialogueId"] = 80160215,
            ["GUID"] = "C8AC3546",
            ["NextDialogue"] = 80160216,
            ["SpeakNpcId"] = 93201,
            ["TalkActionId"] = {
                [1] = "93201:Sit_Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Haier/002/C8AC3546",
            },
        [80160216] = {
            ["Content"] = "我们也曾亲密无间，在枪林弹雨中彼此依靠，在繁杂的电码中寻找线索，在探查真相的死胡同里彻夜挣扎。",
            ["ContentKR"] = "우린 한때 더할 나위 없이 가까웠지. 빗발치는 총탄 가운데 서로 의지하고, 복잡한 코드 속에서 단서를 찾고, 진실을 찾는 막다른 골목에서 밤새도록 함께 싸웠다.",
            ["DialogueId"] = 80160216,
            ["GUID"] = "C8AC3570",
            ["NextDialogue"] = 80160217,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/002/C8AC3570",
            },
        [80160217] = {
            ["Content"] = "为了至关重要的情报，她不惜以自己的生命犯险，堪堪保住了一条命，却永远失去了左耳的听力。只是为了能让我能将一个罪犯明正典刑。",
            ["ContentKR"] = "그 친구는 중요한 정보 하나를 위해 생명의 위험을 무릅썼어. 간신히 목숨은 건졌지만, 청력을 완전히 잃어버렸지. 바로 범죄자 하나를 극형에 처할 수 있게 하는 정보였다.",
            ["DialogueId"] = 80160217,
            ["GUID"] = "C8AC359A",
            ["NextDialogue"] = 80160218,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/002/C8AC359A",
            },
        [80160218] = {
            ["Content"] = "我以为我们将一直是最好的同僚与伙伴，但变化总是发生得猝不及防。",
            ["ContentKR"] = "난 늘 우리가 최고의 동료이자 파트너일 거라고 믿었지만, 변화는 언제나 예상보다 빨리 찾아오지.",
            ["DialogueId"] = 80160218,
            ["GUID"] = "C8AC35C4",
            ["NextDialogue"] = 80160219,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/002/C8AC35C4",
            },
        [80160219] = {
            ["Content"] = "不妨告诉你一个小秘密，我来这里，是为了接收一名勾连神弃者同盟的内鬼。她害死了很多本不该失去生命的士兵，其中包括几个跟随我多年的下属。",
            ["ContentKR"] = "비밀 하나 알려줄까? 내가 여기 온 이유는 포세이큰 동맹과 내통한 스파이를 넘겨받기 위해서야. 그자는 죽어서는 안 될 병사들을 죽였다. 오랫동안 날 따르던 부하들까지...",
            ["DialogueId"] = 80160219,
            ["GUID"] = "C8AC35EE",
            ["NextDialogue"] = 80160220,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/002/C8AC35EE",
            },
        [80160220] = {
            ["Content"] = "我本来打算亲手将她挂上绞刑架，看着她对所有死去的人忏悔……",
            ["ContentKR"] = "원래는 놈을 직접 교수대에 매달아, 죽어간 이들을 향해 뉘우치는 모습을 지켜볼 생각이었지...",
            ["DialogueId"] = 80160220,
            ["GUID"] = "C8AC3618",
            ["NextOptions"] = {
                [1] = 801602201,
                [2] = 801602202,
                },
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/002/C8AC3618",
            },
        [80160221] = {
            ["Content"] = "我宁愿她是为了海伯利亚而死，可惜，她成为了叛徒。",
            ["ContentKR"] = "그 친구가 휘페르보레아를 위해 죽었다면 차라리 좋았겠지. 안타깝지만, 반역자가 되고 말았어.",
            ["DialogueId"] = 80160221,
            ["GUID"] = "C8AC3642",
            ["NextDialogue"] = 80160223,
            ["SpeakNpcId"] = 93201,
            ["TalkActionId"] = {
                [1] = "93201:Sit_DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Haier/002/C8AC3642",
            },
        [80160222] = {
            ["Content"] = "是的，她背叛了我。",
            ["ContentKR"] = "맞아. 동료가 날 배반했어.",
            ["DialogueId"] = 80160222,
            ["GUID"] = "C8AC366C",
            ["NextDialogue"] = 80160223,
            ["SpeakNpcId"] = 93201,
            ["TalkActionId"] = {
                [1] = "93201:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Haier/002/C8AC366C",
            },
        [80160223] = {
            ["Content"] = "不等你动手，这位不速之客就自己满斟一杯，一饮而尽。",
            ["ContentKR"] = "당신이 말리기도 전에, 불청객은 스스로 한 잔을 가득 따라 단숨에 마신다.",
            ["DialogueId"] = 80160223,
            ["GUID"] = "C8AC3696",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 80160224,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
            ["VoiceName"] = "voice/$Locale$/inv/Haier/002/C8AC3696",
            },
        [80160224] = {
            ["Content"] = "呼……这酒比我想得更烈、更苦。苦到连即将到来的审判，都不那么苦涩了。",
            ["ContentKR"] = "후... 술이 생각했던 것보다 독하고 쓰군. 너무 써서 곧 다가올 심판조차 쓰지 않게 느껴질 정도야.",
            ["DialogueId"] = 80160224,
            ["GUID"] = "C8AC36C0",
            ["NextOptions"] = {
                [1] = 801602241,
                [2] = 801602242,
                },
            ["Scripts"] = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/002/C8AC36C0",
            },
        [80160225] = {
            ["Content"] = "……不。我要做的事情没有一丝一毫地改变，我只是……没想好再次与她相见时，应该如何反驳她的“谬论”——",
            ["ContentKR"] = "...아니. 내가 해야 할 일에 대해선 한 치의 흔들림도 없어. 다만... 다시 만났을 때, 그 친구 '헛소리'에 어떻게 받아칠지 고민이 되는군.",
            ["DialogueId"] = 80160225,
            ["GUID"] = "C8AC36EA",
            ["NextDialogue"] = 80160226,
            ["SpeakNpcId"] = 93201,
            ["TalkActionId"] = {
                [1] = "93201:Sit_DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Haier/002/C8AC36EA",
            },
        [80160226] = {
            ["Content"] = "“长官，我早就对你，对这份工作深恶痛绝，喜欢在阴沟里过着不见天日的生活是你的自由，而我，已经受够这摊污泥。向阳是人的本能，你这种怪物除外。”",
            ["ContentKR"] = "\"장교님, 전 당신, 그리고 이 일에 끔찍하게 신물이 나요. 음지의 더러운 삶을 즐기는 건 장교님 자유죠. 하지만 전, 이 흙탕물에 질렸어요. 양지를 원하는 건 인간의 본능이에요. 장교님 같은 괴물에겐 예외겠지만요.\"",
            ["DialogueId"] = 80160226,
            ["GUID"] = "C8AC3714",
            ["NextDialogue"] = 80160227,
            ["SpeakNpcId"] = 93201,
            ["TalkActionId"] = {
                [1] = "93201:Sit_Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Haier/002/C8AC3714",
            },
        [80160227] = {
            ["Content"] = "当我回过神，这样的争吵已经发生过不止一次。今天的结局也许早就有所端倪，是我，被信任蒙住了眼睛。",
            ["ContentKR"] = "돌이켜 보면, 이런 말다툼은 한두 번이 아니었지. 오늘의 결말은 어쩌면 이미 정해져 있었는지도 몰라. 내가 믿음에 눈이 멀었던 거지.",
            ["DialogueId"] = 80160227,
            ["GUID"] = "C8AC373E",
            ["NextDialogue"] = 80160228,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/002/C8AC373E",
            },
        [80160228] = {
            ["Content"] = "届时，我应该对她报以指责，还是痛惜？我是站在什么样的立场上去审判她的，朋友，同僚，上司还是法官？",
            ["ContentKR"] = "그 친구를 만나면, 난 비난을 해야 할까, 아니면 안타까워해야 할까? 그리고, 어떤 입장에서 심판해야 할까? 친구? 동료? 상관? 아니면 재판관?",
            ["DialogueId"] = 80160228,
            ["GUID"] = "C8AC3768",
            ["NextDialogue"] = 80160229,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/002/C8AC3768",
            },
        [80160229] = {
            ["Content"] = "我只有一个晚上得出答案……",
            ["ContentKR"] = "답을 생각할 시간은... 오늘 밤뿐이군...",
            ["DialogueId"] = 80160229,
            ["GUID"] = "C8AC3792",
            ["NextDialogue"] = 80160230,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/002/C8AC3792",
            },
        [80160230] = {
            ["Content"] = "在此之前……先把你手里的酒再倒一杯给我。",
            ["ContentKR"] = "그전에... 그 술 한 잔 더 따라줘.",
            ["DialogueId"] = 80160230,
            ["GUID"] = "C8AC37BC",
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/002/C8AC37BC",
            },
        [80160301] = {
            ["Camera"] = "135.91098,22.045166,124.542297,0.000012,1.800007,-136.994522,35.0,158.845352,false,Manual,3.0",
            ["Content"] = "再来一杯。",
            ["ContentKR"] = "한 잔 더.",
            ["DialogueId"] = 80160301,
            ["GUID"] = "C8AC4362",
            ["NextOptions"] = {
                [1] = 801603051,
                [2] = 801603052,
                },
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC4362",
            },
        [80160306] = {
            ["Content"] = "不要小看我，大部分酒精都会被我蒸发，能让我喝醉的酒恐怕还没有酿造出来。",
            ["ContentKR"] = "얕보지 마. 대부분의 알코올은 내 몸에서 증발해 버리니까. 날 취하게 할 수 있는 술은 아직 없어.",
            ["DialogueId"] = 80160306,
            ["FacialId"] = {
                [1] = "93201:Angry01",
                },
            ["GUID"] = "C8AC4434",
            ["NextOptions"] = {
                [1] = 801603071,
                },
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC4434",
            },
        [80160307] = {
            ["Content"] = "我付给你的报酬足够你再买十瓶这样的药酒。",
            ["ContentKR"] = "내가 준 보수라면 이런 술 열 병은 더 살 수 있을 텐데.",
            ["DialogueId"] = 80160307,
            ["FacialId"] = {
                [1] = "93201:Angry01",
                },
            ["GUID"] = "C8AC445E",
            ["NextOptions"] = {
                [1] = 801603071,
                },
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC445E",
            },
        [80160308] = {
            ["Content"] = "也许吧。",
            ["ContentKR"] = "아마도.",
            ["DialogueId"] = 80160308,
            ["FacialId"] = {
                [1] = "93201:Doubt01",
                },
            ["GUID"] = "C8AC4488",
            ["NextDialogue"] = 80160309,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC4488",
            },
        [80160309] = {
            ["Content"] = "你拿出了休憩之所所有的糖摆放在海尔法面前。",
            ["ContentKR"] = "휴식처에 있는 캔디를 전부 꺼내 헬파이어 앞에 놓는다.",
            ["DialogueId"] = 80160309,
            ["GUID"] = "C8AC44B2",
            ["IsBlack"] = 1,
            ["NextOptions"] = {
                [1] = 801603091,
                },
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC44B2",
            },
        [80160310] = {
            ["Content"] = "我选这种。",
            ["ContentKR"] = "이걸로 하지.",
            ["DialogueId"] = 80160310,
            ["FacialId"] = {
                [1] = "93201:None",
                },
            ["GUID"] = "C8AC44DC",
            ["NextOptions"] = {
                [1] = 801603101,
                },
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC44DC",
            },
        [80160311] = {
            ["Content"] = "好事？呵……",
            ["ContentKR"] = "좋은 추억? 후... ",
            ["DialogueId"] = 80160311,
            ["GUID"] = "C8AC4506",
            ["NextDialogue"] = 80160312,
            ["SpeakNpcId"] = 93201,
            ["TalkActionId"] = {
                [1] = "93201:Sit_Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC4506",
            },
        [80160312] = {
            ["Content"] = "紫露花蜜只会让我想到一个调香的行家——也是不折不扣的罪犯。她会以紫露花为原料制作出让人沉醉到永眠的香水，“命定之人”。",
            ["ContentKR"] = "이걸 보니 귀신같은 솜씨를 가진 조향사 하나가 떠오른 것뿐이야. 여지없는 범죄자지. 보라이슬꽃 꿀을 원료로, 상대를 영원히 잠들게 하는 '운명의 상대'라는 향수를 만들거든.",
            ["DialogueId"] = 80160312,
            ["GUID"] = "C8AC4530",
            ["NextOptions"] = {
                [1] = 801603121,
                },
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC4530",
            },
        [80160313] = {
            ["Content"] = "……不。",
            ["ContentKR"] = "...아니.",
            ["DialogueId"] = 80160313,
            ["GUID"] = "C8AC455A",
            ["NextDialogue"] = 80160314,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC455A",
            },
        [80160314] = {
            ["Content"] = "她是个油嘴滑舌、诡计多端的小人，漂亮的脑袋里只有她所谓的“爱情”，但如果把她当成傻瓜，就会变成一具身染剧毒的尸体。",
            ["ContentKR"] = "번지르르 말재주가 좋고 교활한 여자야. 예쁘장한 얼굴을 하고서는 '사랑'인지 뭔지만 떠들어 대지. 하지만 그 여자를 바보로 여기는 순간, 독살당한 시체가 되고 말아.",
            ["DialogueId"] = 80160314,
            ["GUID"] = "C8AC4584",
            ["NextDialogue"] = 80160315,
            ["SpeakNpcId"] = 93201,
            ["TalkActionId"] = {
                [1] = "93201:Sit_Talk03ToThink_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC4584",
            },
        [80160315] = {
            ["Content"] = "“调香师丽蓓卡”——在卢卡声名远扬，在帝国查无此人。",
            ["ContentKR"] = "'조향사 레베카'. 루카에서 명성이 자자하지만, 제국엔 흔적조차 없는 인물이다.",
            ["DialogueId"] = 80160315,
            ["GUID"] = "C8AC45AE",
            ["NextDialogue"] = 80160316,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC45AE",
            },
        [80160316] = {
            ["Content"] = "没有人知道她为何离开故土，也没有人知道她在何时混进了迪斯玛尼亚，好像只是一夜之间，她就凭空出现了。",
            ["ContentKR"] = "왜 고향을 떠났는지, 언제 디즈마니아에 몰래 들어왔는지 아무도 몰라. 마치 어느 날 갑자기 생겨난 것처럼 말이야.",
            ["DialogueId"] = 80160316,
            ["GUID"] = "C8AC45D8",
            ["NextDialogue"] = 80160317,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC45D8",
            },
        [80160317] = {
            ["Content"] = "任何有可能威胁到皇都安全的因素都该被予以铲除，特别对方可能是一位强大的“骸”，于是，我思考她的来历，猜测她到访此地的目的——",
            ["ContentKR"] = "제국 수도의 안전을 위협할 가능성이 있다면, 그게 뭐든 싹을 잘라야 해. 강력한 '다이몬'일 가능성이 있다면 더더욱. 그래서 나는 그자의 이력을 토대로, 수도에 방문한 목적을 추측해 봤지. 그런데——",
            ["DialogueId"] = 80160317,
            ["GUID"] = "C8AC4602",
            ["NextDialogue"] = 80160318,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC4602",
            },
        [80160318] = {
            ["Content"] = "超乎想象的是，我高估了她的野心，却低估了她有多么麻烦。",
            ["ContentKR"] = "생각보다 야심이 없는 자였더군. 대신, 엄청난 골칫덩이였다.",
            ["DialogueId"] = 80160318,
            ["GUID"] = "C8AC462C",
            ["NextDialogue"] = 80160319,
            ["SpeakNpcId"] = 93201,
            ["TalkActionId"] = {
                [1] = "93201:Sit_Talk03ToThink_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC462C",
            },
        [80160319] = {
            ["Content"] = "她不想偷走皇都银行里所有的钱，也不想在游行时刺杀皇帝。至于要塞的城防图，密探九死一生传递出的绝密信件，在她眼里都只是计算香料比例时要用到的草稿纸。",
            ["ContentKR"] = "황성 은행의 돈을 전부 훔쳐 간다든가, 행차에 나선 황제를 암살한다든가 하는 건 그자의 목적이 아니었어. 요새의 전략 지도, 요원이 천신만고 끝에 건넨 기밀 서찰조차, 그에겐 향수 비율을 계산하는 메모장에 불과했지.",
            ["DialogueId"] = 80160319,
            ["GUID"] = "C8AC4656",
            ["NextDialogue"] = 80160320,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC4656",
            },
        [80160320] = {
            ["Content"] = "“调香师丽蓓卡”只有一个简单得可笑的目的，找到最适合她的恋人——但她会为实现愿望不择手段，竭尽全力。",
            ["ContentKR"] = "'조향사 레베카'의 목표는 오직 하나, 단순하고 우스꽝스러운 목표, 바로 완벽한 연인을 찾는 거였어. 문제는, 그 소원을 이루기 위해 수단을 가리지 않는다는 점이랄까.",
            ["DialogueId"] = 80160320,
            ["GUID"] = "C8AC4680",
            ["NextDialogue"] = 80160321,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC4680",
            },
        }
  end },
  { MinKey = 80160321, MaxKey = 80170322, Loader = function()
      return {
        [80160321] = {
            ["Content"] = "对于潜藏于迪斯玛尼亚暗处的虫豸来说，这是一枚多么好用的棋子啊——一个来自异乡，用毒手段高明，最重要的是，还很好“哄骗”的骸。",
            ["ContentKR"] = "디즈마니아의 어둠 속에 도사린 벌레들에겐, 엄청나게 유용한 장기 말로 보였을 거야. 외지 출신에, 독을 다루는 덴 도사고, '사탕발림의 대가'인 다이몬이라니 말이야.",
            ["DialogueId"] = 80160321,
            ["GUID"] = "C8AC46AA",
            ["NextDialogue"] = 80160322,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC46AA",
            },
        [80160322] = {
            ["Content"] = "理所当然的，她被卷进了阴谋的漩涡，在被利用着杀死了几个满嘴轻佻言语的权贵后，又替幕后主使做了替罪羊，被投入了监狱。",
            ["ContentKR"] = "당연히도 레베카는 음모의 소용돌이에 휘말렸지. 경망스러운 말만 늘어놓는 귀족 몇을 죽이는 데 이용당한 뒤, 죄를 뒤집어쓰고 감옥에 갇히고 말았어.",
            ["DialogueId"] = 80160322,
            ["GUID"] = "C8AC46D4",
            ["NextDialogue"] = 80160323,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC46D4",
            },
        [80160323] = {
            ["Content"] = "而我，则领命调查出这一切的真相。",
            ["ContentKR"] = "명령을 받고, 나는 이 사건의 진상을 밝혀내기로 했다.",
            ["DialogueId"] = 80160323,
            ["GUID"] = "C8AC46FE",
            ["NextDialogue"] = 80160324,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC46FE",
            },
        [80160324] = {
            ["Content"] = "我在审问时告诉她，依照海伯利亚法典，她将被处以长达五十年的监禁。如果她愿意配合我，我将为她申请十年减刑。",
            ["ContentKR"] = "그리고 심문 중 레베카에게 말했지. 휘페르보레아 법에 따라, 최대 50년간 교도소에서 복역하게 되겠지만, 나한테 협력한다면 10년 감형을 신청해 주겠다고 말이야.",
            ["DialogueId"] = 80160324,
            ["GUID"] = "C8AC4728",
            ["NextOptions"] = {
                [1] = 801603241,
                },
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC4728",
            },
        [80160325] = {
            ["Content"] = "我甚至没来得及把这句话说完，她就迫不及待地答应了我。",
            ["ContentKR"] = "내 말이 채 끝나기도 전에, 황급히 제안을 받아들이더군.",
            ["DialogueId"] = 80160325,
            ["GUID"] = "C8AC4752",
            ["NextOptions"] = {
                [1] = 801603251,
                [2] = 801603252,
                },
            ["SpeakNpcId"] = 93201,
            ["TalkActionId"] = {
                [1] = "93201:Sit_Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC4752",
            },
        [80160326] = {
            ["Content"] = "几乎没有罪徒和她一样，为了案件的调查如此配合，就像她为了实现自己的愿望那样……不择手段，竭尽全力。",
            ["ContentKR"] = "레베카는 어떤 범죄자보다도 사건 수사에 협조적으로 임했다. 마치 소원을 이루기 위해서라면 뭐든 했던 것처럼... 수단과 방법을 가리지 않고 최선을 다했지.",
            ["DialogueId"] = 80160326,
            ["GUID"] = "C8AC477C",
            ["NextDialogue"] = 80160327,
            ["SpeakNpcId"] = 93201,
            ["TalkActionId"] = {
                [1] = "93201:Sit_Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC477C",
            },
        [80160327] = {
            ["Content"] = "我只能认为这是被人利用后的报复行为，但她却否定了这一点。",
            ["ContentKR"] = "난 그게 누군가에게 이용당한 자의 복수심이라고 생각했지만, 레베카는 아니라고 하더군.",
            ["DialogueId"] = 80160327,
            ["GUID"] = "C8AC47A6",
            ["NextDialogue"] = 80160328,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC47A6",
            },
        [80160328] = {
            ["Content"] = "她说，“调香师的嗅觉可是很灵敏的，而我在你身上……闻到了同类的味道。”",
            ["ContentKR"] = "대신 이런 말을 했지. \"조향사의 후각은 아주 예민하죠. 그런데 교도소장님껜... 같은 부류의 냄새가 나요.\"",
            ["DialogueId"] = 80160328,
            ["GUID"] = "C8AC47D0",
            ["NextOptions"] = {
                [1] = 801603281,
                [2] = 801603282,
                },
            ["SpeakNpcId"] = 93201,
            ["TalkActionId"] = {
                [1] = "93201:Sit_Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC47D0",
            },
        [80160329] = {
            ["Content"] = "如你所说，查清真相后，我们遭遇了幕后主使的袭击，重伤后，我失去了行动能力。",
            ["ContentKR"] = "맞아. 진실을 밝혀낸 후 우린 배후의 주모자에게 습격당했고, 나는 중상을 입고 움직일 수 없게 됐지.",
            ["DialogueId"] = 80160329,
            ["GUID"] = "C8AC47FA",
            ["NextDialogue"] = 80160330,
            ["SpeakNpcId"] = 93201,
            ["TalkActionId"] = {
                [1] = "93201:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC47FA",
            },
        [80160330] = {
            ["Content"] = "她没有逃跑，也没有趁机杀死我，反而为我做了急救。但在我不肯失去意识时，对我喷了一泵香水，那正是她的成名之作——“命定之人”。",
            ["ContentKR"] = "레베카는 도망치거나 기회를 틈타 날 죽이는 대신, 응급처치를 해 주었다. 하지만 내가 의식을 잃지 않으려고 애쓰는 사이, 나한테 향수를 한 방울 뿌렸지. 바로 자신의 출세작 '운명의 상대'였어.",
            ["DialogueId"] = 80160330,
            ["GUID"] = "C8AC4824",
            ["NextDialogue"] = 80160331,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC4824",
            },
        [80160331] = {
            ["Content"] = "那个由紫露花香气构筑的梦，自此找上了我。",
            ["ContentKR"] = "바로 그때부터, 보라이슬꽃 향기가 나는 꿈이 날 찾아왔지.",
            ["DialogueId"] = 80160331,
            ["GUID"] = "C8AC484E",
            ["NextDialogue"] = 80160332,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC484E",
            },
        [80160332] = {
            ["Content"] = "……",
            ["ContentKR"] = "......",
            ["DialogueId"] = 80160332,
            ["GUID"] = "C8AC4878",
            ["NextDialogue"] = 80160333,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC4878",
            },
        [80160333] = {
            ["Content"] = "你是否想过，如果某个特定的“意外”没有发生，你的生活会是什么样子？",
            ["ContentKR"] = "어떤 '우연'이 일어나지 않았다면, 삶이 어떤 모습이었을지 상상해 본 적 있나?",
            ["DialogueId"] = 80160333,
            ["GUID"] = "C8AC48A2",
            ["NextDialogue"] = 80160334,
            ["SpeakNpcId"] = 93201,
            ["TalkActionId"] = {
                [1] = "93201:Sit_Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC48A2",
            },
        [80160334] = {
            ["Content"] = "在那场梦里……我没有变成红皮肤的骸，血亲也没有把我当作圣人膜拜，母亲的手指依然能抚过我的脸颊。",
            ["ContentKR"] = "보라이슬꽃 향의 꿈속에서... 나는 붉은 피부의 다이몬으로 변하지도, 혈족들이 날 성인으로 숭배하지도 않았다. 어머니는 여전히 손으로 내 얼굴을 어루만져줄 수 있었지.",
            ["DialogueId"] = 80160334,
            ["GUID"] = "C8AC48CC",
            ["NextDialogue"] = 80160335,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC48CC",
            },
        [80160335] = {
            ["Content"] = "我久违地回忆起——啊，原来我拥有过如此白皙的双手。",
            ["ContentKR"] = "정말 오랜만에 기억이 나더군. '아, 내가 이렇게 새하얀 손을 가진 적도 있었네...'하고 말이야.",
            ["DialogueId"] = 80160335,
            ["GUID"] = "C8AC48F6",
            ["NextDialogue"] = 80160336,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC48F6",
            },
        [80160336] = {
            ["Content"] = "我是个普通的卡戎，没有断角，没有人被我灼伤，不必因为炽热的体温而终年睡在地板上，无数罪证与文件自然地从我手中流过，绝无焚毁之虞……",
            ["ContentKR"] = "난 평범한 카론이 되어 있었어. 뿔이 부러지지도, 누군가 나 때문에 화상을 입을 일도 없었지. 타는 듯한 체온 때문에 일 년 내내 바닥에서 잘 필요도 없었고, 수많은 증거와 서류들이 내 손이 닿는 순간 재로 변하는 일도 없었어...",
            ["DialogueId"] = 80160336,
            ["GUID"] = "C8AC4920",
            ["NextDialogue"] = 80160337,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC4920",
            },
        [80160337] = {
            ["Content"] = "我和我的父辈一样，继续履行着家族赋予的使命，这依然是一份行走在黑暗中的营生，但失去与先祖同样天赋的我，反而被许多人围绕着。",
            ["ContentKR"] = "나는 아버지 세대와 마찬가지로, 가문에서 부여한 사명을 계속 수행했다. 어둠 속을 걷는 삶인 건 똑같았지만, 조상의 재능을 잃으면서 오히려 더 많은 사람들과 함께할 수 있게 되었지.",
            ["DialogueId"] = 80160337,
            ["GUID"] = "C8AC494A",
            ["NextDialogue"] = 80160338,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC494A",
            },
        [80160338] = {
            ["Content"] = "起初，我仍能清醒面对这个过于“善良”的世界，这样的生活只是一枚甜蜜的诱饵，心怀叵测的罪人正不知在打着什么算盘。",
            ["ContentKR"] = "처음엔 이 지나치게 '착한' 세상을 냉정하게 바라보는 데 아무 문제가 없었어. 이런 삶은 달콤한 미끼일 뿐이라는 것도 알았지. 그 죄인이 도대체 무슨 꿍꿍이를 숨기고 있는지 모르겠다고 생각했다.",
            ["DialogueId"] = 80160338,
            ["GUID"] = "C8AC4974",
            ["NextDialogue"] = 80160339,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC4974",
            },
        [80160339] = {
            ["Content"] = "然而平静充实的日子循环往复……一年、两年、三年……十年过去了，我所担心的事情从未发生，这场梦境却长得看不到终点。",
            ["ContentKR"] = "하지만 평온한 날들은 계속 반복되었고... 1년, 2년, 3년... 10년이 흘렀지만 내가 걱정하던 일은 일어나지 않았어. 꿈은 끝을 모르고 이어졌지.",
            ["DialogueId"] = 80160339,
            ["GUID"] = "C8AC499E",
            ["NextDialogue"] = 80160340,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC499E",
            },
        [80160340] = {
            ["Content"] = "是的，这样“幸福”的日子长得看不见终点。",
            ["ContentKR"] = "맞아, 그렇게 '행복'한 날들이 끝도 없이 이어진 거야.",
            ["DialogueId"] = 80160340,
            ["GUID"] = "C8AC49C8",
            ["NextDialogue"] = 80160341,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC49C8",
            },
        [80160341] = {
            ["Content"] = "这称得上是一场漫长的拷问……忍受酷刑固然是一种苦痛，但拒绝已经到手的幸福更是一种剜心一般的折磨。",
            ["ContentKR"] = "정말 긴 고문이었다... 고문을 견디는 것도 고통이었지만, 손에 넣은 행복을 거부하는 것은 더한 고통이었지. 가슴을 도려내는 기분이 그런 걸까.",
            ["DialogueId"] = 80160341,
            ["GUID"] = "C8AC49F2",
            ["NextDialogue"] = 80160342,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC49F2",
            },
        [80160342] = {
            ["Content"] = "很不幸，我终究还是逐渐忘却了这只是一个狡猾调香师为我调配的幻觉，我习惯并且接受了——这就是我本来的生活。",
            ["ContentKR"] = "불행하게도, 난 그 행복이 어느 교활한 조향사가 날 위해 만들어낸 환각일 뿐이란 걸 점점 잊어버렸어. 익숙해진 나머지, 그게 바로 내 원래 삶이라고 믿어버렸지.",
            ["DialogueId"] = 80160342,
            ["GUID"] = "C8AC4A1C",
            ["NextDialogue"] = 80160343,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC4A1C",
            },
        [80160343] = {
            ["Content"] = "是从什么时候彻底屈服的呢？也许是在庆祝我生日的聚会上，我挨个打开了所有人的生日贺卡——",
            ["ContentKR"] = "완전히 굴복한 순간? 아마도 내 생일 파티 때였던 것 같군. 난 사람들이 보내준 생일 카드를 하나씩 전부 펼쳐보았지.",
            ["DialogueId"] = 80160343,
            ["GUID"] = "C8AC4A46",
            ["NextDialogue"] = 80160344,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC4A46",
            },
        [80160344] = {
            ["Content"] = "没错，直至今日，我仍清晰地记着每一张的内容……",
            ["ContentKR"] = "그래, 카드의 내용이 지금도 또렷하게 기억나는군...",
            ["DialogueId"] = 80160344,
            ["GUID"] = "C8AC4A70",
            ["SpeakNpcId"] = 93201,
            ["TalkActionId"] = {
                [1] = "93201:Sit_Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC4A70",
            },
        [80160345] = {
            ["Content"] = "“亲爱的小雪球，真高兴你长这么大了！\
陛下的荣耀在上，\
长久以来，我一直担心你过得并不快乐！\
小雪球，你总是日以继夜地工作，\
生怕有一分钟渡过得没有意义，\
好像休息被写入了犯罪条例似的！\
可是作为你的母亲，我只希望你能尽可能地去享受自己的人生。\
人生苦短，我们都只能活一次。\
对自己好一些，好吗？”",
            ["ContentKR"] = "\"사랑하는 우리 눈송이에게,\
이렇게 잘 자라줘서 정말 기쁘구나!\
폐하의 영광이 함께하길 바란다.\
오랫동안 엄마는 네가 행복하지 않을까 봐 걱정했단다!\
우리 눈송이, 매일 밤낮으로 일만 하면서\
1분이라도 의미 없이 보낼까 봐 두려워했지.\
마치 휴식이 범죄 조례에 쓰여 있는 것처럼 말이야!\
하지만, 이 엄마는 네가 최대한 네 인생을 즐기길 바라.\
인생은 짧단다, 모두에게 주어진 삶은 한 번 뿐이야.\
자신에게 좀 더 잘해주렴, 알겠지?\"",
            ["DialogueId"] = 80160345,
            ["Duration"] = 30,
            ["GUID"] = "C8AC4A9A",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 80160346,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC4A9A",
            },
        [80160346] = {
            ["Content"] = "“长官，今年也辛苦您了，祝您生日快乐——\
好了，场面话就说到这里。\
之后别再像陀螺一样转个不停了，\
以及，工作不是你逃避的理由与手段。\
说实话，我们认识快十年了，\
然而擅长搜证如我至今也没弄清楚，\
你整天到底在担忧什么。\
记住，生活还没有不幸到那个份上！\
别再患得患失，去享受下业余生活，好吗？\
——因为你也许不需要休息，但我，很需要！”",
            ["ContentKR"] = "\"장교님, 올해도 수고 많으셨습니다. 생일 축하드려요~\
자, 형식적인 말은 여기까지만 할게요.\
이제 팽이처럼 쉴 새 없이 빙빙 도는 삶은 그만!\
일을 장교님이 도피할 수단이나 이유로 삼지도 마세요.\
솔직히 우리가 안 지도 10년이 다 됐잖아요.\
그런데 장교님이 하루 종일 뭘 그렇게 걱정하시는 건지\
증거 수집의 귀재인 저도 아직 모르겠어요.\
삶이 아무리 불행해도 아직 그 정도까진 아니란 거, 잊지 마세요!\
그만 전전긍긍하고, 여가를 좀 즐기세요. 아셨죠?\
왜냐하면 장교님은 몰라도, 저는 휴식이 필요하거든요!\"",
            ["DialogueId"] = 80160346,
            ["Duration"] = 30,
            ["GUID"] = "C8AC4AC4",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 80160347,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC4AC4",
            },
        [80160347] = {
            ["Content"] = "“尊敬的典狱长女士，感谢您多年以来为海伯利亚的辛勤付出，\
对您报以真诚的敬意。\
祝您生日快乐，请尽情享受这值得纪念的每一分钟吧，\
愿您未来的每一天都充斥着如今日一般的喜悦。\
\
随信附上您本年度的用餐补贴，加班补贴与体检邀请函，请确认后签收。”",
            ["ContentKR"] = "\"존경하는 교도소장님,\
휘페르보레아 제국을 위해 수년간 애써주신 노력에 진심 어린 감사와 경의를 표합니다.\
생일을 축하드리며, 뜻깊은 하루의 모든 순간을 만끽하시길 바랍니다. \
앞으로의 하루도 오늘처럼 기쁨만 가득하길 바랍니다. \
\
이번 연도의 식대, 잔업수당, 건강검진권을 동봉하였으니 확인 후 서명 부탁드립니다.\"",
            ["DialogueId"] = 80160347,
            ["Duration"] = 30,
            ["GUID"] = "C8AC4AEE",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 80160348,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC4AEE",
            },
        [80160348] = {
            ["Content"] = "“亲爱的典狱长女士：\
原谅我不能署上自己的名字，\
您只要知道我是个悄悄注视着您的仰慕者罢了~\
也许您已经不记得我了，但我一直记得您与坏人恶斗的模样……\
为了自己的理想、他人的期待，也许还有渺小的我（嘻嘻），\
燃烧一切的您简直与您的名字一样滚烫。\
祝您生日快乐！\
愿您知晓，您非常值得你现在所拥有的一切。\
所以，请更心心安理得地享受这份嘉奖与祝福吧。”",
            ["ContentKR"] = "\"교도소장님께,\
이름은 밝힐 수 없지만\
전 교도소장님을 몰래 지켜보는 팬이랍니다.\
아마 절 기억하지 못하시겠지만, 전 교도소장님이 악당과 싸우던 모습을 항상 기억하고 있어요...\
자신의 이상과 타인의 바람을 위해, 그리고 어쩌면 작고 보잘것없는 저를 위해(헤헷)\
모든 것을 불사르는 교도소장님은, 그 이름처럼 뜨거운 분이세요.\
생일을 진심으로 축하드려요!\
교도소장님은 지금 갖고 계신 모든 걸 누릴 자격이 있는 분이란 거\
꼭 아셨으면 해요.\
그러니까, 이 상과 축복을 편안한 마음으로 받아주세요.\" ",
            ["DialogueId"] = 80160348,
            ["Duration"] = 30,
            ["GUID"] = "C8AC4B18",
            ["IsBlack"] = 1,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC4B18",
            },
        [80160349] = {
            ["Camera"] = "135.91098,22.045166,124.542297,0.000012,1.800007,-136.994522,35.0,158.845352,false,Manual,3.0",
            ["Content"] = "从那个晚上开始，我放弃去记得我原本的人生。",
            ["ContentKR"] = "그날 밤, 난 원래의 삶을 기억하는 걸 포기했지.",
            ["DialogueId"] = 80160349,
            ["GUID"] = "C8AC4B42",
            ["NextOptions"] = {
                [1] = 801603491,
                [2] = 801603492,
                },
            ["SpeakNpcId"] = 93201,
            ["TalkActionId"] = {
                [1] = "93201:Sit_Idle_Loop",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC4B42",
            },
        [80160350] = {
            ["Content"] = "我在这场梦中渡过了一生，最终在亲人、朋友、同僚的簇拥中死去——没有比这更好的结局了。",
            ["ContentKR"] = "난 그 꿈속에서 평생을 살았고, 가족, 친구, 동료들에게 둘러싸인 채 생을 마감했지. 그보다 더 좋은 결말은 없었을 거야.",
            ["DialogueId"] = 80160350,
            ["GUID"] = "C8AC4B6C",
            ["NextDialogue"] = 80160351,
            ["SpeakNpcId"] = 93201,
            ["TalkActionId"] = {
                [1] = "93201:Sit_Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC4B6C",
            },
        [80160351] = {
            ["Content"] = "终其一生，没有背叛，没有意外，没有死别，没有遗憾。",
            ["ContentKR"] = "배신도, 사고도, 사별도, 후회도 없는 일생이었지.",
            ["DialogueId"] = 80160351,
            ["GUID"] = "C8AC4B96",
            ["NextDialogue"] = 80160352,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC4B96",
            },
        [80160352] = {
            ["Content"] = "当我睁开眼睛，从梦里的死亡中复生，等待我的只有火焚后的余烬，身体的疼痛，以及充斥着脑海的茫然与混乱。",
            ["ContentKR"] = "하지만 눈을 뜨고 꿈속의 죽음에서 되살아나 보니, 날 기다리는 건 오직 타고 남은 재, 고통스러운 통증, 그리고 뇌리에 가득한 혼란과 막막함이었어.",
            ["DialogueId"] = 80160352,
            ["GUID"] = "C8AC4BC0",
            ["NextDialogue"] = 80160353,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC4BC0",
            },
        [80160353] = {
            ["Content"] = "我仅剩的力气只够举起我的一只手——",
            ["ContentKR"] = "그리고 한 손을 간신히 들어 올릴 힘만 남아있더군.",
            ["DialogueId"] = 80160353,
            ["GUID"] = "C8AC4BEA",
            ["NextDialogue"] = 80160354,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC4BEA",
            },
        [80160354] = {
            ["Content"] = "我看到了沾满灰烬与血渍的，不停发抖的，鲜红的手，在那一瞬，我或许流了泪——她就是在那时毫不犹豫地握住了我的手。",
            ["ContentKR"] = "재와 핏자국으로 범벅이 된, 덜덜 떨리는 선홍빛 손을 보는 순간, 난 아마 눈물을 흘렸던 것 같아. 그때 한 여자가 일 초도 망설임 없이 내 손을 잡았어.",
            ["DialogueId"] = 80160354,
            ["GUID"] = "C8AC4C14",
            ["NextDialogue"] = 80160355,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC4C14",
            },
        [80160355] = {
            ["Content"] = "即使她的皮肤根本无法承受这样的高温，而我以为她早就逃之夭夭。",
            ["ContentKR"] = "자기 피부는 이런 고온을 견딜 수 없는데도 말이야. ...난 그 여자가 진작에 도망쳤을 거라고 생각했었지.",
            ["DialogueId"] = 80160355,
            ["GUID"] = "C8AC4C3E",
            ["NextDialogue"] = 80160356,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC4C3E",
            },
        [80160356] = {
            ["Content"] = "是丽蓓卡。",
            ["ContentKR"] = "레베카였다.",
            ["DialogueId"] = 80160356,
            ["GUID"] = "C8AC4C68",
            ["NextOptions"] = {
                [1] = 801603561,
                [2] = 801603562,
                },
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC4C68",
            },
        [80160357] = {
            ["Content"] = "她对苏醒的我说：“我们都是他人眼中的怪物，可即使是怪物，也有做美梦和实现美梦的权力。”",
            ["ContentKR"] = "\"남들 눈에는 우리가 괴물일지도 몰라요. 하지만 괴물이라도 아름다운 꿈을 꾸고, 그 꿈을 이룰 권리가 있어요.\" 레베카는 그렇게 말했지.",
            ["DialogueId"] = 80160357,
            ["GUID"] = "C8AC4C92",
            ["NextDialogue"] = 80160358,
            ["SpeakNpcId"] = 93201,
            ["TalkActionId"] = {
                [1] = "93201:Sit_Talk03ToTalkL_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC4C92",
            },
        [80160358] = {
            ["Content"] = "我不想否定这句话。或许正因如此，我放走了她。",
            ["ContentKR"] = "그 말을 부정하고 싶지 않았어. 그래서였을까, 난 그녀를 풀어주었지.",
            ["DialogueId"] = 80160358,
            ["GUID"] = "C8AC4CBC",
            ["NextDialogue"] = 80160359,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC4CBC",
            },
        [80160359] = {
            ["Content"] = "我肩负着更重要的责任，如果放弃它，残酷的命运将降临在更多人的头上。所以，我愿意将我做梦的权力转让给她，仅此一次。",
            ["ContentKR"] = "내겐 더 중요한 책임이 있었어. 책임을 포기한다면, 더 많은 사람들이 잔혹한 운명을 맞게 되겠지. 그래서 난, 내가 꿈꿀 권리를 레베카에게 넘기기로 한 거야. 딱 한 번만.",
            ["DialogueId"] = 80160359,
            ["GUID"] = "C8AC4CE6",
            ["NextDialogue"] = 80160363,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC4CE6",
            },
        [80160360] = {
            ["Content"] = "她对苏醒的我说：“我们都是他人眼中的怪物，可即使是怪物，也有做美梦和实现美梦的权力。”",
            ["ContentKR"] = "\"남들 눈에는 우리가 괴물일지도 몰라요. 하지만 괴물이라도 아름다운 꿈을 꾸고, 그 꿈을 이룰 권리가 있어요.\" 레베카는 그렇게 말했어.",
            ["DialogueId"] = 80160360,
            ["GUID"] = "C8AC4D10",
            ["NextDialogue"] = 80160361,
            ["SpeakNpcId"] = 93201,
            ["TalkActionId"] = {
                [1] = "93201:Sit_Talk03ToTalkL_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC4D10",
            },
        [80160361] = {
            ["Content"] = "现在的我，已经能够辨出猛终究是一种空洞的满足，可那时的我，却沉浸在了“互为同类”的惺惺相惜中——最终，犯下了无法挽回的错误。",
            ["ContentKR"] = "지금의 난, 꿈이란 결국 공허한 만족일 뿐임을 알고 있지만, 그땐 '같은 부류'라는 착각에 레베카를 동정했지. 그렇게, 돌이킬 수 없는 실수를 저지르고 말았어.",
            ["DialogueId"] = 80160361,
            ["GUID"] = "C8AC4D3A",
            ["NextDialogue"] = 80160362,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC4D3A",
            },
        [80160362] = {
            ["Content"] = "但我不想用这样的说辞欺骗自己，我承认自己心中的渴望，正视它正是为了永远不再触及它。",
            ["ContentKR"] = "하지만 이런 말로 자신을 기만하고 싶진 않다. 분명히, 내 마음속엔 갈망이 존재해. 난 그걸 회피하지 않고 똑똑히 바라볼 생각이야. 그 갈망에 영원히 손대지 않도록 말이지.",
            ["DialogueId"] = 80160362,
            ["GUID"] = "C8AC4D64",
            ["NextDialogue"] = 80160363,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC4D64",
            },
        [80160363] = {
            ["Content"] = "我不会为我的罪行申辩，错误不会重复，下一次，我发誓要让她为自己的罪行付出代价。",
            ["ContentKR"] = "내 죄를 변명하지도, 두 번 실수하지도 않아. 맹세컨대, 다음번엔 반드시 레베카가 자기 죄의 대가를 치르게 할 거다.",
            ["DialogueId"] = 80160363,
            ["GUID"] = "C8AC4D8E",
            ["NextDialogue"] = 80160364,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC4D8E",
            },
        [80160364] = {
            ["Content"] = "但直至今日，紫露花的香气依然能让我在心浮气躁时重归平静。",
            ["ContentKR"] = "하지만 지금도, 보라이슬꽃의 향기를 맡으면, 들뜨거나 불안한 마음이 안정되는 건 어쩔 수 없군.",
            ["DialogueId"] = 80160364,
            ["GUID"] = "C8AC4DB8",
            ["NextDialogue"] = 80160365,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC4DB8",
            },
        [80160365] = {
            ["Content"] = "也许我会在某一天彻底遗忘那个梦境，摆脱这座由“命定之人”铸成的假象的监牢，但至少今天，我确实需要这份安宁。",
            ["ContentKR"] = "언젠간 그 꿈을 완전히 잊고, '운명의 상대'가 꾸며낸 거짓 감옥에서 벗어날 날이 올지도 모르지. 하지만 적어도 오늘만큼은, 이 평온함이 아주 절실하군.",
            ["DialogueId"] = 80160365,
            ["GUID"] = "C8AC4DE2",
            ["NextDialogue"] = 80160366,
            ["SpeakNpcId"] = 93201,
            ["TalkActionId"] = {
                [1] = "93201:Sit_Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC4DE2",
            },
        [80160366] = {
            ["Content"] = "最后……",
            ["ContentKR"] = "마지막으로...",
            ["DialogueId"] = 80160366,
            ["GUID"] = "C8AC4E0C",
            ["NextDialogue"] = 80160367,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC4E0C",
            },
        [80160367] = {
            ["Content"] = "这是她的通缉令，如果发现她的踪迹，请立刻上报当地的治安局。",
            ["ContentKR"] = "이건 레베카의 수배령이다. 이자의 흔적을 발견하면, 즉시 근처의 치안국에 신고하도록.",
            ["DialogueId"] = 80160367,
            ["GUID"] = "C8AC4E36",
            ["NextOptions"] = {
                [1] = 801603671,
                [2] = 801603672,
                },
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC4E36",
            },
        [80160368] = {
            ["Content"] = "请为我再调一杯酒吧，这次可以试着将紫露花蜜加进去吗？",
            ["ContentKR"] = "한 잔 더 하고 싶군. 이번엔 보라이슬꽃 꿀을 넣어줄 수 있나?",
            ["DialogueId"] = 80160368,
            ["GUID"] = "C8AC4E60",
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC4E60",
            },
        [80160401] = {
            ["Camera"] = "135.91098,22.045166,124.542297,0.000012,1.800007,-136.994522,35.0,158.845352,false,Manual,3.0",
            ["Content"] = "谢谢你的招待。",
            ["ContentKR"] = "환대해 줘서 고맙군.",
            ["DialogueId"] = 80160401,
            ["GUID"] = "C8AC53CA",
            ["NextDialogue"] = 80160402,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC53CA",
            },
        [80160402] = {
            ["Content"] = "我明白卡米拉对你的评价了，你是个很容易让人对你放下戒备的人。耐心，洞察，理解……作为酒保，这都是最值得被赞誉的品德。",
            ["ContentKR"] = "카밀라가 너에 대해 왜 그렇게 말했는지 알겠어. 함께 있으면 나도 모르게 무방비 상태가 돼 버리거든. 인내심, 통찰력, 이해심까지... 훌륭한 바텐더의 덕목을 가졌군.",
            ["DialogueId"] = 80160402,
            ["GUID"] = "C8AC53F4",
            ["NextDialogue"] = 80160403,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC53F4",
            },
        [80160403] = {
            ["Content"] = "如果哪天你愿意开个酒馆，也许我会常来光顾。",
            ["ContentKR"] = "언젠가 바텐더 씨가 술집을 연다면, 자주 찾아가게 될지도 모르겠어.",
            ["DialogueId"] = 80160403,
            ["GUID"] = "C8AC541E",
            ["NextOptions"] = {
                [1] = 801604031,
                },
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC541E",
            },
        [80160404] = {
            ["Content"] = "呵……朋友吗。",
            ["ContentKR"] = "후... 친구라.",
            ["DialogueId"] = 80160404,
            ["FacialId"] = {
                [1] = "93201:Smile01",
                },
            ["GUID"] = "C8AC5448",
            ["NextDialogue"] = 80160405,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC5448",
            },
        [80160405] = {
            ["Content"] = "也是，我不能这么无止境地休息下去。喝完最后一杯酒，我也应该去见见老朋友了。",
            ["ContentKR"] = "그래, 이렇게 하릴없이 쉬고만 있을 순 없지. 마지막 잔을 다 마시면, 나도 옛 친구를 만나러 가야겠어.",
            ["DialogueId"] = 80160405,
            ["GUID"] = "C8AC5472",
            ["NextOptions"] = {
                [1] = 801604051,
                },
            ["SpeakNpcId"] = 93201,
            ["TalkActionId"] = {
                [1] = "93201:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC5472",
            },
        [80160406] = {
            ["Content"] = "不需要，简单一点就好。",
            ["ContentKR"] = "아니, 간단한 걸로 하지.",
            ["DialogueId"] = 80160406,
            ["GUID"] = "C8AC549C",
            ["NextDialogue"] = 80160407,
            ["SpeakNpcId"] = 93201,
            ["TalkActionId"] = {
                [1] = "93201:Sit_DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC549C",
            },
        [80160407] = {
            ["Content"] = "“不屈者”，口感尖锐，咽下去的时候像是吞了一把刀子，冲进胃里的时候像是要在那里点火——现在看来，这真是一瓶适合雪原与冻土的酒。",
            ["ContentKR"] = "'불굴자'. 첫 모금은 날카롭고, 목 넘김은 칼을 삼키는 느낌, 위로 내려가면 가슴에 불을 지르는 듯한 기분이 드는 술이지. 지금 보니, 설원과 동토에 정말 딱 맞는 술이야.",
            ["DialogueId"] = 80160407,
            ["GUID"] = "C8AC54C6",
            ["NextDialogue"] = 80160408,
            ["SpeakNpcId"] = 93201,
            ["TalkActionId"] = {
                [1] = "93201:Sit_Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC54C6",
            },
        [80160408] = {
            ["Content"] = "就是它了，不过得麻烦你再等一下。",
            ["ContentKR"] = "그걸로 하지. 근데 잠깐 기다려줘.",
            ["DialogueId"] = 80160408,
            ["GUID"] = "C8AC54F0",
            ["NextDialogue"] = 80160409,
            ["SpeakNpcId"] = 93201,
            ["TalkActionId"] = {
                [1] = "93201:Sit_Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC54F0",
            },
        [80160409] = {
            ["Content"] = "海尔法小心翼翼地在尽可能不直接和酒杯接触的情况下，装满了从檐上敲下的冰，然后让你将“不屈者”倒满。",
            ["ContentKR"] = "헬파이어가 최대한 몸에 술잔이 닿지 않도록 조심하면서, 처마에서 뗀 고드름을 잔에 채웠다. 그러고 나서 당신에게 '불굴자'를 가득 채우게 했다.",
            ["DialogueId"] = 80160409,
            ["GUID"] = "C8AC551A",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 80160410,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC551A",
            },
        [80160410] = {
            ["Content"] = "冰块很快开始融化，她迅速地一饮而尽，接着就是下一杯，下一杯，再下一杯……",
            ["ContentKR"] = "얼음은 곧 녹아내리기 시작했고, 그녀는 재빠르게 한 잔을 비웠다. 그러고는 또 한 잔, 또 한 잔...",
            ["DialogueId"] = 80160410,
            ["GUID"] = "C8AC5544",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 80160411,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC5544",
            },
        [80160411] = {
            ["Content"] = "……",
            ["ContentKR"] = "......",
            ["DialogueId"] = 80160411,
            ["FacialId"] = {
                [1] = "93201:Pain01",
                },
            ["GUID"] = "C8AC556E",
            ["NextDialogue"] = 80160412,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC556E",
            },
        [80160412] = {
            ["Content"] = "…………",
            ["ContentKR"] = "......",
            ["DialogueId"] = 80160412,
            ["GUID"] = "C8AC5598",
            ["NextOptions"] = {
                [1] = 801604121,
                [2] = 801604122,
                },
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC5598",
            },
        [80160413] = {
            ["Content"] = "不要大惊小怪，装满冰块的杯子里能有多少酒。",
            ["ContentKR"] = "호들갑 떨 것 없어. 얼음을 가득 채운 잔에 술이 얼마나 들어간다고.",
            ["DialogueId"] = 80160413,
            ["FacialId"] = {
                [1] = "93201:Confident01",
                },
            ["GUID"] = "C8AC55C2",
            ["NextDialogue"] = 80160414,
            ["SpeakNpcId"] = 93201,
            ["TalkActionId"] = {
                [1] = "93201:Sit_Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC55C2",
            },
        [80160414] = {
            ["Content"] = "我只是遗憾冰块在我手中化得太快，即使尽量挽留，也会变成蒸汽和酒精一起挥发。",
            ["ContentKR"] = "얼음이 내 손에서 너무 빨리 녹아버리는 게 안타까워서 그런 거야. 아무리 붙잡으려 해도, 결국 증기가 되어 알코올과 함께 날아가 버리니까.",
            ["DialogueId"] = 80160414,
            ["GUID"] = "C8AC55EC",
            ["NextDialogue"] = 80160415,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC55EC",
            },
        [80160415] = {
            ["Content"] = "我不喜欢冗长精致的修辞，但坚冰融水与理想的消亡实在是太过相似。",
            ["ContentKR"] = "길고 화려한 수식어를 좋아하진 않지만, 단단한 얼음이 녹는 건 꿈이 사라지는 모습하고 참 닮았군.",
            ["DialogueId"] = 80160415,
            ["GUID"] = "C8AC5616",
            ["NextDialogue"] = 80160416,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC5616",
            },
        [80160416] = {
            ["Content"] = "让我想起很多年以前……当我还没有觉醒，角也没有被折断，我的朋友也没有背叛我的时候——我们一群年轻人刚刚走出学校，憧憬着未来与理想。",
            ["ContentKR"] = "오래전 일이 생각 나네... 내가 아직 각성하기 전, 뿔도 부러지지 않고 친구들도 날 배신하지 않았던 시절이었지. 학교를 막 졸업한 젊은이들이 미래와 꿈을 향해 달려가던 시절 말이야.",
            ["DialogueId"] = 80160416,
            ["GUID"] = "C8AC5640",
            ["NextDialogue"] = 80160417,
            ["SpeakNpcId"] = 93201,
            ["TalkActionId"] = {
                [1] = "93201:Sit_Talk03ToThink_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC5640",
            },
        [80160417] = {
            ["Content"] = "我们喝着最便宜的烈酒，同僚们呐喊的祝酒词，比杯子与杯子的碰撞声更加震耳欲聋。",
            ["ContentKR"] = "우린 제일 싼 독주를 마셨지. 동료들의 건배사는 잔이 부딪치는 소리보다 시끄러워서, 귀청이 떨어질 것 같았어.",
            ["DialogueId"] = 80160417,
            ["GUID"] = "C8AC566A",
            ["NextDialogue"] = 80160418,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC566A",
            },
        [80160418] = {
            ["Content"] = "所有人的脸庞涨成了同样的红色，入职时炽热的宣誓被重复了一遍又一遍。",
            ["ContentKR"] = "동료들은 모두 벌겋게 달아오른 얼굴로, 입직할 때의 뜨거운 맹세를 몇 번이고 외쳐댔지.",
            ["DialogueId"] = 80160418,
            ["GUID"] = "C8AC5694",
            ["NextDialogue"] = 80160419,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC5694",
            },
        [80160419] = {
            ["Content"] = "“为海伯利亚的正义而战斗，为海伯利亚的光明而燃烧，为海伯利亚的屹立而坚守。”",
            ["ContentKR"] = "\"우리는 휘페르보레아의 정의를 위해 싸운다. 휘페르보레아의 빛을 위해 타오른다. 휘페르보레아를 길이 지킨다.\"",
            ["DialogueId"] = 80160419,
            ["GUID"] = "C8AC56BE",
            ["NextDialogue"] = 80160420,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC56BE",
            },
        [80160420] = {
            ["Content"] = "“以'不屈者'向不屈者致敬”。",
            ["ContentKR"] = "\"'불굴자'로서 불굴자에게 경의를 표하며!\"",
            ["DialogueId"] = 80160420,
            ["GUID"] = "C8AC56E8",
            ["NextDialogue"] = 80160421,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC56E8",
            },
        [80160421] = {
            ["Content"] = "当时的同僚们已经不剩几个，我和那位名为艾尔汀的友人，是唯二活到今天的人。",
            ["ContentKR"] = "그때의 동료들은 대부분 사라지고, 이젠 나와 엘딘이라는 친구만 남아 있지.",
            ["DialogueId"] = 80160421,
            ["FacialId"] = {
                [1] = "93201:Sad01",
                },
            ["GUID"] = "C8AC5712",
            ["NextDialogue"] = 80160422,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC5712",
            },
        [80160422] = {
            ["Content"] = "但过不了多久，她也许就会离开这个世界。",
            ["ContentKR"] = "하지만 머지않아 엘딘마저 이 세상을 떠날 수도 있겠군.",
            ["DialogueId"] = 80160422,
            ["GUID"] = "C8AC573C",
            ["NextOptions"] = {
                [1] = 801604221,
                },
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC573C",
            },
        [80160423] = {
            ["Content"] = "……",
            ["ContentKR"] = ".....",
            ["DialogueId"] = 80160423,
            ["FacialId"] = {
                [1] = "93201:None",
                },
            ["GUID"] = "C8AC5766",
            ["NextDialogue"] = 80160424,
            ["SpeakNpcId"] = 93201,
            ["TalkActionId"] = {
                [1] = "93201:Sit_Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC5766",
            },
        [80160424] = {
            ["Content"] = "同样的错误我不会犯第二次。",
            ["ContentKR"] = "같은 실수를 두 번 되풀이하진 않아.",
            ["DialogueId"] = 80160424,
            ["GUID"] = "C8AC5790",
            ["NextDialogue"] = 80160425,
            ["SpeakNpcId"] = 93201,
            ["TalkActionId"] = {
                [1] = "93201:Sit_DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC5790",
            },
        [80160425] = {
            ["Content"] = "我们从同僚变成上下级，又变成了判官和罪人，或许我们都被岁月改变，但我将竭尽所能地遵守我当初许下的誓言。",
            ["ContentKR"] = "우리는 동료에서 상급자와 하급자, 다시 재판관과 범죄자가 되었지. 세월이 흐르면서 변한 걸지도 몰라. 하지만 난 최초의 그 맹세를, 온 힘을 다해 지킬 거다. ",
            ["DialogueId"] = 80160425,
            ["GUID"] = "C8AC57BA",
            ["NextDialogue"] = 80160426,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC57BA",
            },
        [80160426] = {
            ["Content"] = "就算这条路上只剩下我一个人。",
            ["ContentKR"] = "이 길에 나 혼자 남게 된다 해도 말이야.",
            ["DialogueId"] = 80160426,
            ["GUID"] = "C8AC57E4",
            ["NextOptions"] = {
                [1] = 801604261,
                },
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC57E4",
            },
        [80160427] = {
            ["Content"] = "什么都不用说。",
            ["ContentKR"] = "아무 말도 필요 없어.",
            ["DialogueId"] = 80160427,
            ["GUID"] = "C8AC580E",
            ["NextDialogue"] = 80160428,
            ["SpeakNpcId"] = 93201,
            ["TalkActionId"] = {
                [1] = "93201:Sit_DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC580E",
            },
        [80160428] = {
            ["Content"] = "值得我尊敬的同僚是当年的“不屈者”，而我对罪人的态度永远只有一个。",
            ["ContentKR"] = "내가 존경해야 할 동료는 그 시절의 '불굴자'일 뿐, 범죄자에 대한 태도는 변하지 않아.",
            ["DialogueId"] = 80160428,
            ["GUID"] = "C8AC5838",
            ["NextDialogue"] = 80160429,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC5838",
            },
        [80160429] = {
            ["Content"] = "海尔法将杯子里的冰块融水一饮而尽。",
            ["ContentKR"] = "헬파이어는 잔 속의 얼음을 녹여 단숨에 들이켰다.",
            ["DialogueId"] = 80160429,
            ["GUID"] = "C8AC5862",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 80160430,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC5862",
            },
        [80160430] = {
            ["Content"] = "不管面对的罪犯来自炼金院还是什么皇家军事学院，是敌人还是朋友，我都会一视同仁。",
            ["ContentKR"] = "연금원이든 황립 사관학교 출신이든, 적이든 친구든, 나는 언제나 똑같이 대한다.",
            ["DialogueId"] = 80160430,
            ["GUID"] = "C8AC588C",
            ["NextDialogue"] = 80160431,
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC588C",
            },
        [80160431] = {
            ["Content"] = "这才是一名皇家监狱典狱长所应有的，也是唯一的做法。",
            ["ContentKR"] = "황립 감옥의 교도소장으로서 당연히 가져야 할, 그리고 유일한 태도니까.",
            ["DialogueId"] = 80160431,
            ["GUID"] = "C8AC58B6",
            ["SpeakNpcId"] = 93201,
            ["VoiceName"] = "voice/$Locale$/inv/Haier/003/C8AC58B6",
            },
        [80170001] = {
            ["Content"] = "孩子，如果累了，就坐下休息一会儿吧。",
            ["ContentKR"] = "아이야, 피곤하다면 잠시 앉아서 쉬어가렴.",
            ["DialogueId"] = 80170001,
            ["GUID"] = "C8B27ACA",
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B27ACA",
            },
        [80170101] = {
            ["Camera"] = "135.91098,22.045166,124.542297,0.000012,1.800007,-136.994522,35.0,158.845352,false,Manual,3.0",
            ["Content"] = "多谢你邀请我，孩子。我已经很久没有像这样和朋友坐在一起聊天了，甚是怀念。",
            ["ContentKR"] = "초대해 줘서 고맙다, 아이야. 이렇게 친구들과 둘러앉아 이야기 나눈 게 정말 오랜만이야. 무척 그리웠단다.",
            ["DialogueId"] = 80170101,
            ["FacialId"] = {
                [1] = "91502:Smile01",
                },
            ["GUID"] = "C8B28B32",
            ["LookAt"] = {
                [1] = "91502:p(18000P1)",
                },
            ["NextDialogue"] = 80170102,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B28B32",
            },
        [80170102] = {
            ["Content"] = "“很久”？有多久？",
            ["ContentKR"] = "'오래'라니요? 얼마나 오래요?",
            ["DialogueId"] = 80170102,
            ["GUID"] = "C8B28B5C",
            ["NextDialogue"] = 80170103,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B28B5C",
            },
        [80170103] = {
            ["Content"] = "嗯。大概有十多年了吧。再往前……可能有几百年了？",
            ["ContentKR"] = "음, 대략 십여 년 정도. 그전에는... 글쎄, 몇백 년은 됐을지도 모르겠구나.",
            ["DialogueId"] = 80170103,
            ["GUID"] = "C8B28B86",
            ["NextDialogue"] = 80170104,
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B28B86",
            },
        [80170104] = {
            ["Content"] = "啊……？",
            ["ContentKR"] = "네...?",
            ["DialogueId"] = 80170104,
            ["GUID"] = "C8B28BB0",
            ["NextDialogue"] = 80170105,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B28BB0",
            },
        [80170105] = {
            ["Content"] = "呵呵，吓到你了吗？其实，我的岁数比你我脚下的这片土地——海伯利亚帝国还要长一些。",
            ["ContentKR"] = "후후, 놀랐니? 사실 내 나이는 우리가 딛고 있는 이 땅, 휘페르보레아 제국보다 더 오래됐단다.",
            ["DialogueId"] = 80170105,
            ["GUID"] = "C8B28BDA",
            ["NextOptions"] = {
                [1] = 801701051,
                [2] = 801701052,
                },
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B28BDA",
            },
        [80170106] = {
            ["Content"] = "“骸”的魔法千差万别，多是先天异能或经由血脉传承，只怕无法传授于人。",
            ["ContentKR"] = "'다이몬'의 마법은 종류가 정말 다양하지. 대부분 선천적으로 타고나거나 혈통을 통해 계승되는 능력이라 다른 사람에게 가르쳐줄 수는 없어.",
            ["DialogueId"] = 80170106,
            ["GUID"] = "C8B28C04",
            ["NextDialogue"] = 80170107,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B28C04",
            },
        [80170107] = {
            ["Content"] = "没关系，随口一说。认真来讲……",
            ["ContentKR"] = "괜찮아요, 그냥 한번 해본 말이에요. 솔직히 말하자면...",
            ["DialogueId"] = 80170107,
            ["GUID"] = "C8B28C2E",
            ["NextDialogue"] = 80170108,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B28C2E",
            },
        [80170108] = {
            ["Content"] = "没想到妮弗尔夫人是这么年长的长辈……非常荣幸能和您交谈。",
            ["ContentKR"] = "나이플 부인이 이렇게 연세가 많으신 분이셨다니... 대화를 나눌 수 있어 정말 영광이에요.",
            ["DialogueId"] = 80170108,
            ["GUID"] = "C8B28C58",
            ["NextDialogue"] = 80170109,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B28C58",
            },
        [80170109] = {
            ["Content"] = "不必如此郑重，你就当是在和普通朋友聊天便好。",
            ["ContentKR"] = "그렇게 격식 차릴 필요 없어. 그냥 평범한 친구랑 이야기한다고 생각하면 돼.",
            ["DialogueId"] = 80170109,
            ["GUID"] = "C8B28C82",
            ["NextDialogue"] = 80170110,
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B28C82",
            },
        [80170110] = {
            ["Content"] = "不过，你想和我聊些什么呢？我早已远离俗世，怕是没法接上当下时髦的话题，但你若是对远方、对过去有几分兴趣，我倒是有不少故事可讲。",
            ["ContentKR"] = "그런데, 나와 무슨 이야기를 하고 싶니? 난 이미 속세를 떠난 지 오래라 요즘 유행하는 이야기는 잘 모르겠구나. 하지만, 먼 곳이나 과거에 관심이 있다면 들려줄 이야기가 많지.",
            ["DialogueId"] = 80170110,
            ["GUID"] = "C8B28CAC",
            ["NextOptions"] = {
                [1] = 801701101,
                },
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B28CAC",
            },
        [80170111] = {
            ["Content"] = "我记得您说过，您是一位“雾海引渡人”。不过，我还没搞太清楚那究竟是什么。",
            ["ContentKR"] = "당신이 '안개의 바다의 인도자'라고 하셨던 걸 기억해요. 그런데 그게 정확히 뭘 의미하는지 아직 잘 모르겠어요.",
            ["DialogueId"] = 80170111,
            ["GUID"] = "C8B28CD6",
            ["NextDialogue"] = 80170112,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B28CD6",
            },
        [80170112] = {
            ["Content"] = "嗯……兴许你听说过卡戎之民的神话。",
            ["ContentKR"] = "음... 넌 아마도 카론의 신화를 들어본 적이 있겠지.",
            ["DialogueId"] = 80170112,
            ["GUID"] = "C8B28D00",
            ["NextDialogue"] = 80170113,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B28D00",
            },
        [80170113] = {
            ["Content"] = "最初，天地是混沌的雾海，自那雾海中诞生圣树，圣树绽放纯白的花。白花孕育了我们的祖先——最初的生命女神茵布拉，女神又创造万物。",
            ["ContentKR"] = "처음에, 천지는 혼돈스러운 안개의 바다였고, 그 안개의 바다에서 성스러운 나무가 태어났고, 그 나무는 순백한 꽃을 피웠지. 그 꽃은 우리의 조상이자 최초의 생명 여신 엠블라를 잉태했고, 그 여신은 세상 만물을 창조했단다.",
            ["DialogueId"] = 80170113,
            ["GUID"] = "C8B28D2A",
            ["NextDialogue"] = 80170114,
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_Talk02R_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B28D2A",
            },
        [80170114] = {
            ["Content"] = "一切有生之物都来自雾海，在唤作“尘世”的河流中漂泊一遭后，又将归于雾海。",
            ["ContentKR"] = "살아있는 모든 것은 안개의 바다에서 태어나, '속세'라는 강에서 잠시 떠돌다가, 결국엔 다시 안개의 바다로 돌아가게 되는 거야.",
            ["DialogueId"] = 80170114,
            ["GUID"] = "C8B28D54",
            ["NextDialogue"] = 80170115,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B28D54",
            },
        [80170115] = {
            ["Content"] = "而引渡人的职责则是指引迷失方向的亡魂回归雾海。所以，大多数时候，我都在倾听亡者的声音，与它们耳语。",
            ["ContentKR"] = "인도자의 역할은 길을 잃은 망령들을 안개의 바다로 안내하는 것이지. 그래서 나는 대부분의 시간을 죽은 자들의 목소리를 듣고 그들과 속삭이는 데 보내.",
            ["DialogueId"] = 80170115,
            ["GUID"] = "C8B28D7E",
            ["NextDialogue"] = 80170116,
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_Talk02R_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B28D7E",
            },
        [80170116] = {
            ["Content"] = "听来有些可怕。",
            ["ContentKR"] = "들으니 조금 섬뜩하네요.",
            ["DialogueId"] = 80170116,
            ["GUID"] = "C8B28DA8",
            ["NextDialogue"] = 80170117,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B28DA8",
            },
        [80170117] = {
            ["Content"] = "呵呵，的确。在大多数人看来，死亡是一件极其可怕的事。",
            ["ContentKR"] = "후후, 맞아. 대부분 사람들에게 죽음은 정말 두려운 일이지.",
            ["DialogueId"] = 80170117,
            ["GUID"] = "C8B28DD2",
            ["NextOptions"] = {
                [1] = 801701171,
                },
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B28DD2",
            },
        [80170118] = {
            ["Content"] = "嗯……正好，既然说到了这个话题，我就给你讲一个关于“死亡”的故事吧。这是一个少女和她重病的妹妹的故事。",
            ["ContentKR"] = "음... 마침 이 주제가 나왔으니, '죽음'에 관한 이야기를 하나 해줄게. 이건 한 소녀와 그녀의 병든 여동생에 대한 이야기란다.",
            ["DialogueId"] = 80170118,
            ["FacialId"] = {
                [1] = "91502:Sad01",
                },
            ["GUID"] = "C8B28DFC",
            ["NextDialogue"] = 80170119,
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_Talk02R_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B28DFC",
            },
        [80170119] = {
            ["Content"] = "少女和妹妹是生在艾利西安的穷人，从小失去双亲，两人相依为命，顽强地熬过了饥饿和寒冷。不幸的是，妹妹在某年的寒冬染上了不治之症。",
            ["ContentKR"] = "소녀와 여동생은 엘리시안에서 태어난 가난한 아이였지. 일찍 부모를 잃고 서로를 의지하여 굶주림과 추위를 견뎌냈어. 하지만 불행히도 여동생은 어느 겨울, 불치병에 걸리고 말았어.",
            ["DialogueId"] = 80170119,
            ["GUID"] = "C8B28E26",
            ["NextDialogue"] = 80170120,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B28E26",
            },
        [80170120] = {
            ["Content"] = "那位少女为了救自己的妹妹四处求医问药，遍寻无果的绝望之际，却从一个老人那里打听到了有关“黄金之血”的传说。",
            ["ContentKR"] = "소녀는 여동생을 구하기 위해 이곳저곳을 다니며 약을 찾았지만, 아무 소득도 얻지 못했어. 절망에 빠져 있던 소녀는 한 어르신에게서 '황금의 피'라는 전설을 듣게 되었지.",
            ["DialogueId"] = 80170120,
            ["GUID"] = "C8B28E50",
            ["NextDialogue"] = 80170121,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B28E50",
            },
        [80170121] = {
            ["Content"] = "相传艾利西安贵族曾经供奉过一位受神赐福的女人，她的血液能够治愈顽疾，永葆青春，因而珍贵异常，如同流动的黄金。",
            ["ContentKR"] = "전해지는 바에 따르면, 엘리시안의 귀족들은 신의 축복을 받은 여인을 섬겼다고 해. 그녀의 피는 난치병을 치유하고 영원한 젊음을 가져다준다고 알려져서, 마치 흐르는 황금처럼 귀중히 여겨졌단다.",
            ["DialogueId"] = 80170121,
            ["GUID"] = "C8B28E7A",
            ["NextDialogue"] = 80170122,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B28E7A",
            },
        [80170122] = {
            ["Content"] = "无数贵人献上数不清的真正黄金，来换一小瓶救命的血液。但是，战乱很快降临了艾利西安。在“大迁徙”中，女人被反抗军掳走，从此下落不明。",
            ["ContentKR"] = "수많은 귀족들이 셀 수 없을 만큼 많은 황금을 바치며 작은 병에 담긴 그 피를 얻으려 했지. 그러나 전쟁이 엘리시안을 휩쓸었고, '대이동' 중에 여인은 저항군에게 납치되어 행방불명되었고 말이야.",
            ["DialogueId"] = 80170122,
            ["GUID"] = "C8B28EA4",
            ["NextDialogue"] = 80170123,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B28EA4",
            },
        [80170123] = {
            ["Content"] = "为了拯救妹妹，少女凭着超乎常人的耐心四处寻访，她惊喜地发现，当年的那个女人竟然还活着，已年逾百岁的她如今就住在深林之国——伊瑟尔。",
            ["ContentKR"] = "여동생을 구하기 위해 소녀는 끝없는 인내로 여기저기 수소문을 했어. 그러다 놀랍게도, 그 여인이 아직 살아 있다는 사실을 알게 되었지. 백 살이 넘은 그녀는 깊은 숲의 나라, 이스엘에 살고 있었어.",
            ["DialogueId"] = 80170123,
            ["GUID"] = "C8B28ECE",
            ["NextDialogue"] = 80170124,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B28ECE",
            },
        [80170124] = {
            ["Content"] = "于是，她带着重病的妹妹跋山涉水，找到了那个被赐福的女人。抱着已然奄奄一息的妹妹，少女流着泪求女人分给他一点奇迹。",
            ["ContentKR"] = "그래서 소녀는 병든 여동생을 데리고 산을 넘고 물을 건너 그 축복받은 여인을 찾아갔어. 거의 숨이 끊어질 듯한 여동생을 안고 소녀는 눈물을 흘리며 여인에게 기적을 나누어 달라고 간청했단다.",
            ["DialogueId"] = 80170124,
            ["GUID"] = "C8B28EF8",
            ["NextDialogue"] = 80170125,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B28EF8",
            },
        [80170125] = {
            ["Content"] = "然而，“受神赐福的黄金之血”不过是贪婪的贵族粉饰恶行的谎言。实际上，女人当年是因为疗愈的魔法而遭到囚禁，历尽千辛万苦才终于逃离艾利西安。",
            ["ContentKR"] = "하지만 '신의 축복을 받은 황금의 피'는 탐욕스러운 귀족들이 자신의 악행을 감추기 위해 만들어낸 거짓말일 뿐이었어. 사실, 그 여인은 치유의 마법 때문에 감금당했고, 온갖 고난 끝에 엘리시안을 겨우 탈출할 수 있었지.",
            ["DialogueId"] = 80170125,
            ["GUID"] = "C8B28F22",
            ["NextDialogue"] = 80170126,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B28F22",
            },
        [80170126] = {
            ["Content"] = "她早就决定此生不再动用自己的治愈能力，以免再生事端。",
            ["ContentKR"] = "그녀는 다시는 자신의 치유 능력을 사용하지 않기로 결심했어. 또다시 비극이 일어나지 않도록 하기 위해서 말이야.",
            ["DialogueId"] = 80170126,
            ["GUID"] = "C8B28F4C",
            ["NextDialogue"] = 80170127,
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_Talk02R_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B28F4C",
            },
        [80170127] = {
            ["Content"] = "女孩的努力落得了一场空吗……",
            ["ContentKR"] = "소녀의 모든 노력이 헛된 일이었나요...?",
            ["DialogueId"] = 80170127,
            ["GUID"] = "C8B28F76",
            ["NextDialogue"] = 80170128,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B28F76",
            },
        [80170128] = {
            ["Content"] = "不，不对。既然你特地讲出来，这个故事肯定还没结束吧？",
            ["ContentKR"] = "아니요, 그렇지 않을거에요. 당신이 이 이야기를 특별히 들려주신 걸 보면, 이야기가 아직 끝난 건 아니겠죠?",
            ["DialogueId"] = 80170128,
            ["GUID"] = "C8B28FA0",
            ["NextDialogue"] = 80170129,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B28FA0",
            },
        [80170129] = {
            ["Content"] = "呵呵，你猜得没错——女人最后答应了少女的请求。",
            ["ContentKR"] = "후후, 맞아. 여인은 결국 소녀의 요청을 들어주기로 했지.",
            ["DialogueId"] = 80170129,
            ["FacialId"] = {
                [1] = "91502:Smile01",
                },
            ["GUID"] = "C8B28FCA",
            ["NextDialogue"] = 80170130,
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B28FCA",
            },
        [80170130] = {
            ["Content"] = "为什么？",
            ["ContentKR"] = "왜요?",
            ["DialogueId"] = 80170130,
            ["GUID"] = "C8B28FF4",
            ["NextDialogue"] = 80170131,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B28FF4",
            },
        [80170131] = {
            ["Content"] = "因为，女人其实并不是完全没动过治愈别人的心思——她曾经两度试图用自己的血延续别人的生命，一次是她最好的朋友，一次是她的女儿。",
            ["ContentKR"] = "사실, 여인은 다른 사람을 치유하려는 마음이 전혀 없었던 건 아니었거든. 그녀는 두 번이나 자신의 피로 다른 이의 생명을 연장하려 했지. 한 번은 그녀의 가장 친한 친구였고, 또 한 번은 그 여인의 딸이었어.",
            ["DialogueId"] = 80170131,
            ["GUID"] = "C8B2901E",
            ["NextDialogue"] = 80170132,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B2901E",
            },
        [80170132] = {
            ["Content"] = "她的朋友是一位英勇的战士，在战场上受了致命伤。她的女儿是一位德高望重的学者，安然地迎来了寿命的重点。",
            ["ContentKR"] = "그녀의 친구는 용감한 전사로, 전장에서 치명상을 입었어. 그 여인의 딸은 존경받는 학자로, 평온히 생의 끝을 맞이했지.",
            ["DialogueId"] = 80170132,
            ["GUID"] = "C8B29048",
            ["NextDialogue"] = 80170133,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B29048",
            },
        [80170133] = {
            ["Content"] = "虽然临终的情形大不相同，但相同的是，两人都坚定地拒绝了用女人的血延续生命，不愿意用这种方式活下去。",
            ["ContentKR"] = "비록 임종의 상황은 달랐지만, 두 사람 모두 그녀의 피로 생명을 연장하는 것을 단호히 거부했어. 그런 방식으로 목숨을 연명하고 싶지 않다고 말했지.",
            ["DialogueId"] = 80170133,
            ["GUID"] = "C8B29072",
            ["NextDialogue"] = 80170134,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B29072",
            },
        [80170134] = {
            ["Content"] = "那位姐姐悲痛而不甘的神情让女人想起了过去的自己，于是她的内心动摇了。她想起了横亘在自己心头多年的疑惑与遗憾——",
            ["ContentKR"] = "그 소녀의 슬픔도 간절한 표정도 여인에게 과거의 자신을 떠올리게 했어. 그래서 그녀의 마음은 흔들렸고, 오래도록 가슴에 묻어두었던 의문과 후회가 떠올랐지...",
            ["DialogueId"] = 80170134,
            ["GUID"] = "C8B2909C",
            ["NextDialogue"] = 80170135,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B2909C",
            },
        [80170135] = {
            ["Content"] = "如果自己救下了朋友和女儿，会怎么样？自己没能选择的那条道路，究竟通往怎样的终点？",
            ["ContentKR"] = "만약 그녀가 친구와 딸을 구했더라면 어떻게 되었을까? 선택하지 못했던 그 길은 어떤 끝으로 이어졌을까?",
            ["DialogueId"] = 80170135,
            ["GUID"] = "C8B290C6",
            ["NextDialogue"] = 80170136,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B290C6",
            },
        [80170136] = {
            ["Content"] = "她想知道答案。于是，她割开手臂，将自己的血液赠予了那对姐妹。",
            ["ContentKR"] = "그녀는 그 답을 알고 싶어했단다. 그래서 그녀는 팔을 베어 자신의 피를 그 자매에게 기증했어.",
            ["DialogueId"] = 80170136,
            ["GUID"] = "C8B290F0",
            ["NextDialogue"] = 80170137,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B290F0",
            },
        [80170137] = {
            ["Content"] = "重病的妹妹喝下“黄金之血”后，很快便恢复了意识。",
            ["ContentKR"] = "중병에 걸린 여동생은 '황금의 피'를 마신 후, 곧 의식을 되찾았지.",
            ["DialogueId"] = 80170137,
            ["GUID"] = "C8B2911A",
            ["NextOptions"] = {
                [1] = 801701371,
                [2] = 801701372,
                },
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B2911A",
            },
        [80170138] = {
            ["Content"] = "你是个善良的孩子……可是，所谓“黄金之血”的奇迹只是人们一厢情愿的幻想而已。",
            ["ContentKR"] = "너 참 착한 아이구나... 하지만 '황금의 피'라는 기적은 단지 사람들이 만들어낸 환상일 뿐이지.",
            ["DialogueId"] = 80170138,
            ["GUID"] = "C8B29144",
            ["NextDialogue"] = 80170140,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B29144",
            },
        [80170139] = {
            ["Content"] = "是啊。所谓“黄金之血”的奇迹只是人们一厢情愿的幻想而已。",
            ["ContentKR"] = "맞아. '황금의 피'라는 기적은 단지 사람들이 만들어낸 환상일 뿐이야.",
            ["DialogueId"] = 80170139,
            ["GUID"] = "C8B2916E",
            ["NextDialogue"] = 80170140,
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B2916E",
            },
        [80170140] = {
            ["Content"] = "女人的血液确实拥有特殊的力量，但喝下它并不能真正治愈疾病或延缓衰老，只能将生命维持在“存活”的状态。",
            ["ContentKR"] = "여인의 피는 특별한 힘을 가지고 있는 건 맞지만, 그걸 마신다고 해서 병이 완전히 낫거나, 노화를 늦출 수 있는 건 아니었어. 단지 생명을 '유지'하는 상태로 만드는 것뿐이야.",
            ["DialogueId"] = 80170140,
            ["FacialId"] = {
                [1] = "91502:Sad01",
                },
            ["GUID"] = "C8B29198",
            ["NextDialogue"] = 80170141,
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B29198",
            },
        [80170141] = {
            ["Content"] = "像是被琥珀封存的昆虫——不会腐朽，却也很难说是“活着”。",
            ["ContentKR"] = "마치 호박 속에 갇힌 곤충처럼... 썩지는 않지만, '살아있다'고 할 수는 없는 상태였지.",
            ["DialogueId"] = 80170141,
            ["GUID"] = "C8B291C2",
            ["NextDialogue"] = 80170142,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B291C2",
            },
        [80170142] = {
            ["Content"] = "所以，喝下血液之后，妹妹虽然没有死去，身体却依旧病入膏肓。",
            ["ContentKR"] = "그래서 피를 마신 여동생은 죽음에 이르진 않았지만, 몸 상태는 여전히 병들어 있었어.",
            ["DialogueId"] = 80170142,
            ["GUID"] = "C8B291EC",
            ["NextDialogue"] = 80170143,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B291EC",
            },
        [80170143] = {
            ["Content"] = "她只能终日卧于病榻之上，连喝水都要费尽力气。她尝不出食物的味道、看不清书上的文字、听不清姐姐呼唤她的声音。",
            ["ContentKR"] = "여동생은 하루 종일 병상에 누워 있어야 했고, 물 한 모금 마시는 것도 힘들었어. 음식의 맛도 느끼지 못하고, 책의 글씨도 보이지 않았으며, 언니가 부르는 소리조차 희미하게 들렸지.",
            ["DialogueId"] = 80170143,
            ["GUID"] = "C8B29216",
            ["NextDialogue"] = 80170144,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B29216",
            },
        [80170144] = {
            ["Content"] = "姐姐为了能随时照顾妹妹，只能找些工时灵活的零工。但为了赚到足够维持二人生活的钱，她又必须选择那些最苦、最累，别人不愿意干的活。",
            ["ContentKR"] = "그래서 소녀는 언제든지 여동생을 돌보기 위해 시간에 제약을 받지않는 일거리만 찾았어. 하지만, 둘의 생활을 유지할 만큼 돈을 벌기 위해서는 그 중의 가장 힘들고, 고된 일을 선택할 수밖에 없었지.",
            ["DialogueId"] = 80170144,
            ["GUID"] = "C8B29240",
            ["NextDialogue"] = 80170145,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B29240",
            },
        [80170145] = {
            ["Content"] = "她确实有着坚强的意志，苦心竭力地守护着这份来之不易的“奇迹”，但她孱弱的身体还是承受不住这样持续的辛劳，几乎每天都在倒下的边缘挣扎。",
            ["ContentKR"] = "소녀는 강한 의지로 어렵게 얻은 이 '기적'을 지키려 노력했지만, 연약한 몸으로는 계속되는 고된 노동을 감당할 수 없었고, 매일 쓰러지기 직전까지 일을 했어.",
            ["DialogueId"] = 80170145,
            ["GUID"] = "C8B2926A",
            ["NextOptions"] = {
                [1] = 801701451,
                },
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B2926A",
            },
        [80170146] = {
            ["Content"] = "后来，那位妹妹自己结束了生命。她用仅剩的力气，把姐姐又一次求来的那一小瓶“奇迹”推到地上，打碎了。",
            ["ContentKR"] = "결국, 여동생은 스스로 목숨을 끊었어. 온 힘을 다해 언니가 다시 가져온 작은 병의 '기적'을 바닥에 떨어뜨려 깨뜨렸지.",
            ["DialogueId"] = 80170146,
            ["GUID"] = "C8B29294",
            ["NextDialogue"] = 80170147,
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_Talk02R_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B29294",
            },
        [80170147] = {
            ["Content"] = "大概她终于意识到，这所谓的“奇迹”，无论对姐姐，还是对她自己而言，都只是一具沉重的枷锁。",
            ["ContentKR"] = "아마도 그 아이는 마침내 이 '기적'이라는 건 언니에게도, 자신에게도 무거운 족쇄일 뿐이라는 걸 깨달았을 거야.",
            ["DialogueId"] = 80170147,
            ["GUID"] = "C8B292BE",
            ["NextDialogue"] = 80170148,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B292BE",
            },
        [80170148] = {
            ["Content"] = "那时，是我将那个女孩送往了雾海。你猜猜她的灵魂对我说了什么？",
            ["ContentKR"] = "그때, 내가 그 여동생을 안개의 바다로 보냈어. 그 아이의 영혼이 나에게 뭐라고 했는지 맞춰볼래?",
            ["DialogueId"] = 80170148,
            ["FacialId"] = {
                [1] = "91502:Smile01",
                },
            ["GUID"] = "C8B292E8",
            ["NextDialogue"] = 80170149,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B292E8",
            },
        [80170149] = {
            ["Content"] = "看你的表情，她应该说了很温柔的话吧，比如“谢谢”？",
            ["ContentKR"] = "표정을 보니, 아마도 \"고마워요\" 같은 다정한 말을 했겠죠?",
            ["DialogueId"] = 80170149,
            ["GUID"] = "C8B29312",
            ["NextDialogue"] = 80170150,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B29312",
            },
        [80170150] = {
            ["Content"] = "……你这么聪明，倒显得我故弄玄虚了。你猜得没错。",
            ["ContentKR"] = "...이렇게 똑똑하니, 내가 괜히 뭔가 대단한 척했던 것 같네. 맞아, 네 말이 맞다.",
            ["DialogueId"] = 80170150,
            ["GUID"] = "C8B2933C",
            ["NextDialogue"] = 80170151,
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B2933C",
            },
        [80170151] = {
            ["Content"] = "她说，她很感谢姐姐，也很感谢那个女人。虽然经历了痛苦的末路，但也正因如此，她能够坦然接受自己的离去。",
            ["ContentKR"] = "그 아이는 언니에게도, 그 여인에게도 감사하다고 했어. 비록 고통스러운 끝을 맞았지만, 덕분에 자신의 죽음을 담담히 받아들일 수 있었다고.",
            ["DialogueId"] = 80170151,
            ["GUID"] = "C8B29366",
            ["NextDialogue"] = 80170152,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B29366",
            },
        [80170152] = {
            ["Content"] = "听到这些，少女先是哭着说了许多的“对不起”，但最后，她也对着妹妹漂流而去的骨灰匣，说了一句“谢谢”。",
            ["ContentKR"] = "그 말을 들은 소녀는 처음에는 울면서 \"미안해\"를 수없이 말했지만, 마지막에는 여동생의 유골함을 향해 \"고마워\"라고 말했어.",
            ["DialogueId"] = 80170152,
            ["GUID"] = "C8B29390",
            ["NextDialogue"] = 80170153,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B29390",
            },
        [80170153] = {
            ["Content"] = "少女后来在伊瑟尔定居，成了一位优秀的医生。在组建了自己的家庭之后，她还去拜访了那个女人，告诉她自己现在已经过上了幸福的生活。",
            ["ContentKR"] = "소녀는 나중에 이스엘에 정착해서 훌륭한 의사가 되었거든. 가정을 꾸린 후에는 그 여인을 찾아가 이제는 행복하게 살고 있다고 말하기도 했어.",
            ["DialogueId"] = 80170153,
            ["GUID"] = "C8B293BA",
            ["NextDialogue"] = 80170154,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B293BA",
            },
        [80170154] = {
            ["Content"] = "这时，女人终于明白，为何当年她的友人和女儿不愿意让她“救”自己——",
            ["ContentKR"] = "그때, 여인은 왜 그녀의 친구와 딸이 자신의 '구원'을 바라지 않았는지 비로소 깨달았어.",
            ["DialogueId"] = 80170154,
            ["GUID"] = "C8B293E4",
            ["NextDialogue"] = 80170155,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B293E4",
            },
        [80170155] = {
            ["Content"] = "死亡对于生命而言，并不总是一位恶客。有时，它也是温柔的。就像植物开始结果时凋零的花瓣一般，终结是为了新的开始。",
            ["ContentKR"] = "죽음은 삶에 있어서 항상 나쁜 손님인 건 아니야. 때로는 죽음도 다정하지. 식물이 열매를 맺을 때 꽃잎은 지는 것처럼, 끝은 새로운 시작을 위한 것이야.",
            ["DialogueId"] = 80170155,
            ["GUID"] = "C8B2940E",
            ["NextDialogue"] = 80170156,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B2940E",
            },
        [80170156] = {
            ["Content"] = "如果执意与死亡对抗，反而会让人止步不前，错过生的美好。",
            ["ContentKR"] = "죽음과 억지로 싸우면 오히려 앞으로 나아가지 못하고 삶의 아름다움을 놓치게 될지도 몰라.",
            ["DialogueId"] = 80170156,
            ["GUID"] = "C8B29438",
            ["NextOptions"] = {
                [1] = 801701561,
                [2] = 801701562,
                },
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_Talk02R_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B29438",
            },
        [80170157] = {
            ["Content"] = "这是个坚韧的回答。",
            ["ContentKR"] = "정말 꿋꿋한 대답이네.",
            ["DialogueId"] = 80170157,
            ["GUID"] = "C8B29462",
            ["NextDialogue"] = 80170159,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B29462",
            },
        [80170158] = {
            ["Content"] = "这是个勇敢的回答。",
            ["ContentKR"] = "정말 용감한 대답이네.",
            ["DialogueId"] = 80170158,
            ["GUID"] = "C8B2948C",
            ["NextDialogue"] = 80170159,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B2948C",
            },
        [80170159] = {
            ["Content"] = "不过，这个故事所传达的，终究只是那个女人的一己之见而已，不必太过在意。你大可以去寻找自己的答案。",
            ["ContentKR"] = "하지만, 이 이야기가 전하는 건 결국 그 여인의 개인적인 의견일 뿐이지. 너무 신경 쓰지는 마. 너만의 답을 찾아도 좋아.",
            ["DialogueId"] = 80170159,
            ["GUID"] = "C8B294B6",
            ["NextDialogue"] = 80170160,
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B294B6",
            },
        [80170160] = {
            ["Content"] = "我相信，无论你的选择为何，只要能够保持清醒、不被虚假之物羁绊，便终会找到正确的道路。",
            ["ContentKR"] = "난 네가 어떤 선택을 하든, 깨어 있고 거짓된 것에 얽매이지 않는다면, 결국 올바른 길을 찾을 거라고 믿어.",
            ["DialogueId"] = 80170160,
            ["GUID"] = "C8B294E0",
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/001/C8B294E0",
            },
        [80170201] = {
            ["Camera"] = "135.91098,22.045166,124.542297,0.000012,1.800007,-136.994522,35.0,158.845352,false,Manual,3.0",
            ["Content"] = "你好，孩子。你看上去似乎有些疲惫？",
            ["ContentKR"] = "안녕, 아이야. 조금 피곤해 보이네?",
            ["DialogueId"] = 80170201,
            ["GUID"] = "C8B29B9A",
            ["LookAt"] = {
                [1] = "91502:p(18000P1)",
                },
            ["NextOptions"] = {
                [1] = 801702011,
                [2] = 801702012,
                },
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/002/C8B29B9A",
            },
        [80170202] = {
            ["Content"] = "自从离开家乡以后，我经历过很多事，其中很多充满遗憾。有时我会觉得很无力，似乎很多努力都是徒劳。",
            ["ContentKR"] = "고향을 떠난 후 많은 일을 겪었어요. 그중 많은 것이 아쉬움으로 가득 차 있어요. 가끔은 무력감을 느끼고, 많은 노력이 헛된 것처럼 느껴져요.",
            ["DialogueId"] = 80170202,
            ["GUID"] = "C8B29BC4",
            ["NextDialogue"] = 80170203,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/002/C8B29BC4",
            },
        [80170203] = {
            ["Content"] = "妮弗尔夫人作为长辈，有什么建议吗？",
            ["ContentKR"] = "나이플 부인, 어른으로서 제가 어떻게 해야 할지 조언해 줄 수 있나요?",
            ["DialogueId"] = 80170203,
            ["GUID"] = "C8B29BEE",
            ["NextDialogue"] = 80170204,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/002/C8B29BEE",
            },
        [80170204] = {
            ["Content"] = "是吗……那么，就让我再给你讲个故事吧。",
            ["ContentKR"] = "그래... 그러면, 이야기를 하나 더 들려주도록 하지.",
            ["DialogueId"] = 80170204,
            ["GUID"] = "C8B29C18",
            ["NextDialogue"] = 80170205,
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/002/C8B29C18",
            },
        [80170205] = {
            ["Content"] = "这是一位青年和一位少女的故事，一个关于希望、勇气和未来的故事。",
            ["ContentKR"] = "이것은 한 청년과 소녀의 이야기로, 희망과 용기, 그리고 미래에 관한 이야기야.",
            ["DialogueId"] = 80170205,
            ["GUID"] = "C8B29C42",
            ["NextDialogue"] = 80170206,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/002/C8B29C42",
            },
        [80170206] = {
            ["Content"] = "故事发生在千年之前，那时这片大陆上只有艾利西安一个国家。他们二人一个是平民，一个是贵族。",
            ["ContentKR"] = "이야기는 천 년 전으로 거슬러 올라간단다. 그때 이 대륙에는 엘리시안이라는 나라만 있었고, 그 청년과 소녀는 각각 평민과 귀족 출신이었지.",
            ["DialogueId"] = 80170206,
            ["GUID"] = "C8B29C6C",
            ["NextDialogue"] = 80170207,
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_Talk02R_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/002/C8B29C6C",
            },
        [80170207] = {
            ["Content"] = "出身平民的青年从小就喜欢读书，尤其喜爱研究历史和神话，年纪轻轻便拥有了渊博的学识，人人都期待他能成长为一位优秀的学者。",
            ["ContentKR"] = "평민 출신의 청년은 어릴 때부터 책 읽기를 무척 좋아했어. 특히 역사와 신화 연구에 열중했지. 젊은 나이에 이미 해박한 지식을 갖춘 그는 모두의 기대를 받으며 훌륭한 학자로 성장할 거라 여겨졌어.",
            ["DialogueId"] = 80170207,
            ["GUID"] = "C8B29C96",
            ["NextDialogue"] = 80170208,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/002/C8B29C96",
            },
        [80170208] = {
            ["Content"] = "但青年读得越多、懂得越多、思考得越多，就越是意识到，他目之所及的土地上，播种着太多错误。那些人们习以为常的东西，却不都是对的。",
            ["ContentKR"] = "하지만 청년은 책을 읽고, 이해하고, 사고를 많이 할수록 자신이 사는 땅에 너무 많은 잘못된 것이 존재한다는 것을 깨달았어. 사람들이 당연하다고 여기는 것들이 모두 옳은 것은 아니었다는 걸 말이야.",
            ["DialogueId"] = 80170208,
            ["FacialId"] = {
                [1] = "91502:Sad01",
                },
            ["GUID"] = "C8B29CC0",
            ["NextDialogue"] = 80170209,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/002/C8B29CC0",
            },
        [80170209] = {
            ["Content"] = "平民们辛勤劳作也难得温饱，修士的桌上却永远摆着吃不完的美酒佳肴。祝福的赞美诗中，充斥着被当成异端处决的无辜者在绞刑架下的哭号。",
            ["ContentKR"] = "평민들은 아무리 열심히 일해도 겨우 먹고살기 바쁜데, 수도사들의 식탁은 항상 먹다 남은 술과 진수성찬으로 넘쳐났어. 축복의 찬송가 아래에는 억울하게 이단으로 몰려 교수대에서 울부짖는 무고한 사람들의 소리가 가득했지.",
            ["DialogueId"] = 80170209,
            ["GUID"] = "C8B29CEA",
            ["NextDialogue"] = 80170210,
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_Talk02R_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/002/C8B29CEA",
            },
        [80170210] = {
            ["Content"] = "——当然，哭泣的，还有一位据说拥有“黄金之血”的少女。",
            ["ContentKR"] = "...그리고, 그 울부짖는 이들 중 한 명이 바로 '황금의 피'를 가졌다고 알려진 어떤 소녀였어.",
            ["DialogueId"] = 80170210,
            ["GUID"] = "C8B29D14",
            ["NextDialogue"] = 80170211,
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/002/C8B29D14",
            },
        [80170211] = {
            ["Content"] = "白天，她颤抖着割开手臂，向前来顶礼膜拜的人赐予自己的血；晚上，她蜷缩在囚牢里，一边因疼痛而哭泣，一边向神明祈祷着垂怜。",
            ["ContentKR"] = "낮에는 떨리는 손으로 자신의 팔을 베어 신도들에게 피를 나눠주었고, 밤에는 감옥에 웅크린 채 고통 속에서 신의 자비를 구하며 울었단다.",
            ["DialogueId"] = 80170211,
            ["GUID"] = "C8B29D3E",
            ["NextDialogue"] = 80170212,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/002/C8B29D3E",
            },
        [80170212] = {
            ["Content"] = "有一天，年轻的学者冒险闯入圣堂，对着前来求取“黄金之血”的人们发表了一番激昂的演说。然而，回应他的却只有卫兵的长枪。",
            ["ContentKR"] = "그러던 어느 날, 젊은 학자가 성당에 몰래 들어가 '황금의 피'를 구하러 온 사람들 앞에서 열정적인 연설을 했어. 하지만 그를 맞이한 것은 경비병의 창이었지.",
            ["DialogueId"] = 80170212,
            ["GUID"] = "C8B29D68",
            ["NextDialogue"] = 80170213,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/002/C8B29D68",
            },
        [80170213] = {
            ["Content"] = "他被关进了阴冷的监牢，并在偶然的机缘巧合下，遇见了故事的另一位主角——陪同父亲前来视察的贵族少女。",
            ["ContentKR"] = "그는 차가운 감옥에 갇혔고, 우연히도 이야기의 또 다른 주인공을 만나게 되었어. 바로 아버지를 따라 시찰을 온 그 귀족 소녀였어.",
            ["DialogueId"] = 80170213,
            ["GUID"] = "C8B29D92",
            ["NextDialogue"] = 80170214,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/002/C8B29D92",
            },
        [80170214] = {
            ["Content"] = "少女喜欢骑马、练武，英姿飒爽。她有一颗善良的心，对与自己同龄却误入歧途的青年感到怜惜，便私下前去劝说对方认罪以减轻刑罚。",
            ["ContentKR"] = "귀족 출신의 소녀는 말을 타고 무술을 연습하는 것을 좋아했으며, 용감하고 당당한 성격이었어. 선한 마음을 가진 그녀는 자신과 같은 또래의 청년이 잘못된 길을 걷는 것이 안타까웠고, 몰래 그 청년을 찾아가 죄를 인정하면 형벌이 줄어들거라며 그를 설득했지. ",
            ["DialogueId"] = 80170214,
            ["GUID"] = "C8B29DBC",
            ["NextDialogue"] = 80170215,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/002/C8B29DBC",
            },
        [80170215] = {
            ["Content"] = "可是青年不仅宣称自己无罪，还反过来劝贵族少女尽早醒悟。",
            ["ContentKR"] = "하지만, 청년은 자신이 무죄라고 주장하며, 오히려 귀족 소녀에게 현실을 깨닫고 깨어나야 한다고 충고했어.",
            ["DialogueId"] = 80170215,
            ["GUID"] = "C8B29DE6",
            ["NextDialogue"] = 80170216,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/002/C8B29DE6",
            },
        [80170216] = {
            ["Content"] = "他告诉少女，人们膜拜的，拥有“黄金之血”的女孩，实际上只是被一位大贵族——也就是贵族少女的父亲，囚禁起来敛财的可怜人。",
            ["ContentKR"] = "그는 귀족 소녀에게 사람들이 숭배하는 '황금의 피'를 가진 소녀가 사실은 대귀족, 즉 귀족 소녀의 아버지에게 감금당한 채 돈벌이 수단으로 이용되는 불쌍한 사람일 뿐이라고 말했어.",
            ["DialogueId"] = 80170216,
            ["GUID"] = "C8B29E10",
            ["NextDialogue"] = 80170217,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/002/C8B29E10",
            },
        [80170217] = {
            ["Content"] = "听了青年的话，贵族少女最初的反应当然是不信，甚至觉得荒谬。但青年慷慨陈词时那双熠熠生辉的眼眸，却始终在她的脑海中盘旋不去。",
            ["ContentKR"] = "청년의 말을 들은 귀족 소녀는 당연히 믿지 않았고, 심지어 터무니없는 말이라고 생각했지. 하지만 열정적으로 말하는 청년의 반짝이는 눈빛이 그녀의 머릿속에서 떠나지 않았어.",
            ["DialogueId"] = 80170217,
            ["GUID"] = "C8B29E3A",
            ["NextDialogue"] = 80170218,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/002/C8B29E3A",
            },
        [80170218] = {
            ["Content"] = "那目光不像是在说谎。于是，贵族少女踏出了探求的第一步。她从父亲那里偷来钥匙，打开圣堂深处的房间，找到了那个苍白瘦弱、锁链缠身的女孩。",
            ["ContentKR"] = "그 눈빛은 거짓말을 하는 것 같지 않았단다. 그래서 귀족 소녀는 진실을 확인하기 위한 첫걸음을 내디뎠고, 아버지 몰래 열쇠를 훔쳐 성당 깊숙한 방을 열었어. 그곳에서 그녀는 사슬에 묶인 그 창백하고 허약한 소녀를 발견했어.",
            ["DialogueId"] = 80170218,
            ["GUID"] = "C8B29E64",
            ["NextDialogue"] = 80170219,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/002/C8B29E64",
            },
        [80170219] = {
            ["Content"] = "发现真相之后，少女回到监牢，再次站在青年面前。看到她与先前判若两人的沉重神情，青年明白她已经做好了准备，便向她讲述了贵族的更多罪行。",
            ["ContentKR"] = "진실을 깨달은 귀족 소녀는 감옥으로 돌아가 청년을 다시 찾아갔어. 이전과는 전혀 다른 무거운 표정으로 다가오는 그녀를 보며, 청년은 그녀가 준비되었음을 깨닫고 귀족들의 더 많은 죄행의 진실을 이야기했어.",
            ["DialogueId"] = 80170219,
            ["GUID"] = "C8B29E8E",
            ["NextDialogue"] = 80170220,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/002/C8B29E8E",
            },
        [80170220] = {
            ["Content"] = "青年的话像一把利刃割开了少女生活其中的精美画布，暴露出背后血淋淋的真实。在那之后，少女终于开始看见那些她不曾看过的暗角。",
            ["ContentKR"] = "청년이 한 말들은 귀족 소녀가 꿈꾸던 화려한 세상을 날카롭게 찢고는, 그 뒤에 숨겨진 피투성이 현실을 적나라하게 드러내게 만들었지. 그 후로 귀족 소녀는 세상의 어두운 구석을 더 깊이 들여다보기 시작했단다.",
            ["DialogueId"] = 80170220,
            ["GUID"] = "C8B29EB8",
            ["NextDialogue"] = 80170221,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/002/C8B29EB8",
            },
        [80170221] = {
            ["Content"] = "她将自己的发现告诉了父亲，希望父亲能够释放青年，可等待她的却是软禁和监视——她这才明白，自己的父亲从始至终都是苦难的帮凶。",
            ["ContentKR"] = "그리고 귀족 소녀는 자신이 발견한 내용을 아버지에게 전하며 청년을 풀어달라고 사정도 했어. 하지만, 그녀에게 돌아온 건 감금과 감시뿐이었단다... 그제야 그녀는 자신의 아버지가 처음부터 끝까지 고난의 공범이었다는 사실을 깨달았지.",
            ["DialogueId"] = 80170221,
            ["GUID"] = "C8B29EE2",
            ["NextOptions"] = {
                [1] = 801702211,
                [2] = 801702212,
                },
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/002/C8B29EE2",
            },
        [80170222] = {
            ["Content"] = "是啊——他们也曾哀叹过自身的无力，也曾如你一般疲惫不堪，怀疑抗争究竟有何意义。但是，他们还是选择了坚持下去。",
            ["ContentKR"] = "그래... 그들도 자신의 무력함을 한탄했었고, 너처럼 지치고 힘들어하며 저항이 과연 어떤 의미가 있는건지 의심도 했었지. 하지만 그들은 끝까지 포기하지 않기로 했거든.",
            ["DialogueId"] = 80170222,
            ["FacialId"] = {
                [1] = "91502:Smile01",
                },
            ["GUID"] = "C8B29F0C",
            ["NextDialogue"] = 80170223,
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/002/C8B29F0C",
            },
        [80170223] = {
            ["Content"] = "即便在牢狱中，青年依旧日夜推演着自己的学说，试图描绘一幅正义与自由的新世界图景。",
            ["ContentKR"] = "감옥에 갇힌 청년은 밤낮으로 자신의 학설을 연구하며 정의와 자유가 실현된 새로운 세상을 꿈꿨어.",
            ["DialogueId"] = 80170223,
            ["GUID"] = "C8B29F36",
            ["NextDialogue"] = 80170224,
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_Talk02R_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/002/C8B29F36",
            },
        [80170224] = {
            ["Content"] = "即便孤立无援，少女依然拒绝纸醉金迷的诱惑，想方设法地接济下层民众，并从中寻找志同道合的伙伴。",
            ["ContentKR"] = "귀족 소녀는 고립된 상황 속에서도 사치스러운 삶의 유혹에 넘어가지 않고, 빈민을 돕기 위해 애쓰며 뜻을 함께할 동료를 찾아다녔어.",
            ["DialogueId"] = 80170224,
            ["GUID"] = "C8B29F60",
            ["NextDialogue"] = 80170225,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/002/C8B29F60",
            },
        [80170225] = {
            ["Content"] = "他们的努力最初看上去只是蝴蝶振翅，最终却掀起了一道飓风，在艾利西安坚不可摧的外壳上撕开一道裂痕。",
            ["ContentKR"] = "그들의 노력은 처음에는 나비의 날갯짓처럼 미미해 보였지만, 결국에는 폭풍을 일으켜 엘리시안의 견고한 껍데기에 균열을 만들어냈지.",
            ["DialogueId"] = 80170225,
            ["GUID"] = "C8B29F8A",
            ["NextDialogue"] = 80170226,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/002/C8B29F8A",
            },
        [80170226] = {
            ["Content"] = "他们二人便是那场永垂青史的“大迁徙”事件的领导者。他们建立起一支反抗军，带领被压迫的底层人民离开了艾利西安。",
            ["ContentKR"] = "그들은 바로 역사에 길이 남을 '대이동'의 지도자였단다. 억눌리고 가난에 시달리던 빈민을 이끌고 저항군을 조직해 엘리시안을 떠났지.",
            ["DialogueId"] = 80170226,
            ["GUID"] = "C8B29FB4",
            ["NextDialogue"] = 80170227,
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_Talk02R_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/002/C8B29FB4",
            },
        [80170227] = {
            ["Content"] = "艾利西安的反抗军……“大迁徙”的人们……",
            ["ContentKR"] = "엘리시안의 저항군... '대이동'의 사람들...",
            ["DialogueId"] = 80170227,
            ["GUID"] = "C8B29FDE",
            ["NextDialogue"] = 80170228,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/002/C8B29FDE",
            },
        [80170228] = {
            ["Content"] = "我在书里读到过。这些人最终并没有真正实现平等的理想，对吧？",
            ["ContentKR"] = "책에서 읽은 적 있어요. 그들이 결국 평등의 이상을 실현하지는 못했죠?",
            ["DialogueId"] = 80170228,
            ["GUID"] = "C8B2A008",
            ["NextDialogue"] = 80170229,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/002/C8B2A008",
            },
        [80170229] = {
            ["Content"] = "……没错，命运就是如此残酷的东西，它能在平静中掀起飓风，亦能驱使狂澜浇灭火焰。正如你所说，很多时候，努力的结局是“徒劳”。",
            ["ContentKR"] = "...그래, 운명이란 게 원래 그렇게 잔혹한 것이지. 평온 속에 폭풍을 일으키기도 하고, 거대한 파도로 불꽃을 꺼뜨리기도 하지. 네가 말한 것처럼, 때로는 노력의 결말은 '헛된' 것일지도 몰라.",
            ["DialogueId"] = 80170229,
            ["GUID"] = "C8B2A032",
            ["NextDialogue"] = 80170230,
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/002/C8B2A032",
            },
        [80170230] = {
            ["Content"] = "但是，那些曾经闪耀过的瞬间是真实存在的，也会因“记忆”而永远被铭刻。",
            ["ContentKR"] = "하지만 말이야, 그들이 빛났던 순간들은 분명히 존재했고, '기억'을 통해 영원히 새겨질 거야.",
            ["DialogueId"] = 80170230,
            ["FacialId"] = {
                [1] = "91502:Confident01",
                },
            ["GUID"] = "C8B2A05C",
            ["NextDialogue"] = 80170231,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/002/C8B2A05C",
            },
        [80170231] = {
            ["Content"] = "那场大迁徙将勇敢和自由的光辉播撒到阿特拉西亚大陆上，也戳穿了神的谎言，让人们第一次开始正视自身的情感与渴望。",
            ["ContentKR"] = "그 대이동은 아트라시아 대륙에 용기와 자유의 빛을 전파했으며, 신의 거짓된 가면을 벗겨내어, 사람들이 처음으로 자신의 진짜 감정과 욕망을 마주보게 했지.",
            ["DialogueId"] = 80170231,
            ["GUID"] = "C8B2A086",
            ["NextDialogue"] = 80170232,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/002/C8B2A086",
            },
        [80170232] = {
            ["Content"] = "即便历经数百年，仍然有许多人从厚重的史书中寻到这缕光辉，为了实现青年和少女理想中的世界而努力奋斗着。",
            ["ContentKR"] = "수백 년이 지나도 여전히 많은 사람들이 두꺼운 역사책 속에서 그 빛을 찾아내고, 청년과 소녀가 꿈꾸던 세계를 이루기 위해 노력하고 있어.",
            ["DialogueId"] = 80170232,
            ["GUID"] = "C8B2A0B0",
            ["NextDialogue"] = 80170233,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/002/C8B2A0B0",
            },
        [80170233] = {
            ["Content"] = "嗯……",
            ["ContentKR"] = "네...",
            ["DialogueId"] = 80170233,
            ["GUID"] = "C8B2A0DA",
            ["NextDialogue"] = 80170234,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/002/C8B2A0DA",
            },
        [80170234] = {
            ["Content"] = "你方才说，想要听取我的建议。但我多年避世离俗，很难给出什么具体的指导。",
            ["ContentKR"] = "아까 나한테 조언을 구한다고 했지만, 난 오래도록 속세와 멀리 떨어져 지내왔기에 구체적인 지침을 주기는 좀 어렵단다.",
            ["DialogueId"] = 80170234,
            ["GUID"] = "C8B2A104",
            ["NextDialogue"] = 80170235,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/002/C8B2A104",
            },
        [80170235] = {
            ["Content"] = "我想我只能告诉你：越是经历长生，越是接近永恒，我就越是发觉，真正珍贵的东西，其实是瞬间。一切你抗争过的瞬间，都不会因抗争的结果而改变。",
            ["ContentKR"] = "다만 한 가지는 말해줄 수 있지. 오래 살수록, 영원에 가까워질수록, 그 무엇보다 소중한 것은 바로 '순간'이라는 거야. 네가 싸워온 모든 순간은 결과와 상관없이 그 자체로 빛나고 있단다.",
            ["DialogueId"] = 80170235,
            ["GUID"] = "C8B2A12E",
            ["NextDialogue"] = 80170236,
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/002/C8B2A12E",
            },
        [80170236] = {
            ["Content"] = "{nickname}，不必畏惧，不必犹疑——你拥有非同寻常的力量，你一定会在时间中，留下自己的光辉。",
            ["ContentKR"] = "{nickname}, 두려워하지 말거라, 망설이지도 말렴. 넌 특별한 힘을 가지고 있고, 분명히 시간 속에 자신의 빛을 남기게 될 거야.",
            ["DialogueId"] = 80170236,
            ["GUID"] = "C8B2A158",
            ["NextOptions"] = {
                [1] = 801702361,
                [2] = 801702362,
                },
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/002/C8B2A158",
            },
        [80170237] = {
            ["Content"] = "我相信你将来一定能做到。",
            ["ContentKR"] = "난, 네가 분명히 해낼 거라고 믿어.",
            ["DialogueId"] = 80170237,
            ["FacialId"] = {
                [1] = "91502:Satisfy01",
                },
            ["GUID"] = "C8B2A182",
            ["NextDialogue"] = 80170238,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/002/C8B2A182",
            },
        [80170238] = {
            ["Content"] = "至于现在……就让我们放下那些沉重的东西，一起将这壶茶饮尽，好好享受这来之不易的片刻安宁吧。",
            ["ContentKR"] = "이제는... 무거운 것들은 내려놓고, 이 차나 한잔 하며 이 소중한 평화의 순간을 만끽하렴.",
            ["DialogueId"] = 80170238,
            ["GUID"] = "C8B2A1AC",
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/002/C8B2A1AC",
            },
        [80170301] = {
            ["Camera"] = "135.91098,22.045166,124.542297,0.000012,1.800007,-136.994522,35.0,158.845352,false,Manual,3.0",
            ["Content"] = "你好，孩子。你的神色看起来比上次好多了。",
            ["ContentKR"] = "안녕, 아이야. 지난번보다 얼굴빛이 한결 나아졌구나.",
            ["DialogueId"] = 80170301,
            ["FacialId"] = {
                [1] = "91502:Smile01",
                },
            ["GUID"] = "C8B2AC02",
            ["LookAt"] = {
                [1] = "91502:p(18000P1)",
                },
            ["NextOptions"] = {
                [1] = 801703011,
                [2] = 801703012,
                },
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2AC02",
            },
        [80170302] = {
            ["Content"] = "很高兴我的故事能对你有所帮助。那么，这次你有什么想要探讨的话题吗？",
            ["ContentKR"] = "내 이야기가 도움이 되었다니 기쁘네. 그럼, 이번에는 어떤 화제를 얘기하고 싶니?",
            ["DialogueId"] = 80170302,
            ["FacialId"] = {
                [1] = "91502:Happy01",
                },
            ["GUID"] = "C8B2AC2C",
            ["NextDialogue"] = 80170303,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2AC2C",
            },
        [80170303] = {
            ["Content"] = "我想知道，妮弗尔怎么看待“错误”？",
            ["ContentKR"] = "당신은 '잘못'에 대해 어떻게 생각하는지 알고 싶어요.",
            ["DialogueId"] = 80170303,
            ["GUID"] = "C8B2AC56",
            ["NextDialogue"] = 80170304,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2AC56",
            },
        [80170304] = {
            ["Content"] = "我……这一路上经历了很多，也失去了很多。我总是会想，自己是不是做错了什么？如果当初做了不同的选择，一切是不是会变得更好？",
            ["ContentKR"] = "전... 이 길을 걸어오며 많은 것을 겪었고 또 잃었어요. 항상 제가 뭔가 잘못한 게 아닐지 생각하게 돼요. 만약 그때 다른 선택을 했다면, 모든 것이 더 나아졌을까요?",
            ["DialogueId"] = 80170304,
            ["GUID"] = "C8B2AC80",
            ["NextDialogue"] = 80170305,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2AC80",
            },
        [80170305] = {
            ["Content"] = "可是，我无法回到过去，永远也不可能知道答案了。",
            ["ContentKR"] = "하지만, 과거로 돌아갈 수 없고, 전 영원히 답을 알 수 없겠죠.",
            ["DialogueId"] = 80170305,
            ["GUID"] = "C8B2ACAA",
            ["NextDialogue"] = 80170306,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2ACAA",
            },
        [80170306] = {
            ["Content"] = "嗯……我明白你的困惑了。那么，今天我就讲一个关于“错误”的故事吧。这是一对夫妇的故事。",
            ["ContentKR"] = "음... 네가 혼란스러워하는 마음 잘 알겠다. 그럼, 오늘은 '잘못'에 관한 이야기를 하나 해주지. 이건 한 부부의 이야기야.",
            ["DialogueId"] = 80170306,
            ["FacialId"] = {
                [1] = "91502:Smile01",
                },
            ["GUID"] = "C8B2ACD4",
            ["NextDialogue"] = 80170307,
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2ACD4",
            },
        [80170307] = {
            ["Content"] = "他们住在艾利西安的郊外，丈夫是个猎人，妻子在城里做女佣。夫妻二人很想要一个孩子，但多年来未能如愿。",
            ["ContentKR"] = "그들은 엘리시안의 교외에 살고있었어. 남편은 사냥꾼이었고 아내는 도시에서 하녀로 일했단다. 부부는 아이를 갖고 싶어 했지만, 오랫동안 이루지 못했지.",
            ["DialogueId"] = 80170307,
            ["GUID"] = "C8B2ACFE",
            ["NextDialogue"] = 80170308,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2ACFE",
            },
        [80170308] = {
            ["Content"] = "某一天，丈夫在森林中打猎时遇到了一个流浪的孩子，见她浑身血污、瑟瑟发抖，实在可怜，便将她带回了自己家。",
            ["ContentKR"] = "어느 날, 남편은 숲에서 사냥하다 길을 잃은 여자아이를 발견했단다. 아이는 온몸이 피투성이었고, 덜덜 떨고 있었지. 남편은 불쌍하게 여겼고, 결국 그 아이를 집으로 데려왔지.",
            ["DialogueId"] = 80170308,
            ["GUID"] = "C8B2AD28",
            ["NextDialogue"] = 80170309,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2AD28",
            },
        [80170309] = {
            ["Content"] = "他的妻子给那女孩洗了澡，发现她并未受伤，只是似乎受到了严重的惊吓，不管对她说什么，她都只是呆呆地睁着眼睛，什么也不回答。",
            ["ContentKR"] = "아내가 그 아이를 씻겨주었지, 비록 다친 곳은 없었지만 심하게 겁에 질린 모습이었어. 무슨 말을 해도 그저 멍하니 눈을 뜬 채 아무 대답도 하지 않았어.",
            ["DialogueId"] = 80170309,
            ["GUID"] = "C8B2AD52",
            ["NextDialogue"] = 80170310,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2AD52",
            },
        [80170310] = {
            ["Content"] = "于是，夫妻俩便暂时收留了这个孩子。在他们日复一日的悉心照料下，女孩慢慢有了知觉，开始对外界的刺激做出反应，最后终于开口说话了。",
            ["ContentKR"] = "그래서 부부는 그 아이를 잠시 돌보기로 했지. 그들의 정성 어린 보살핌 덕분에 아이는 서서히 감각을 되찾고, 외부 자극에 반응하기 시작하며, 마침내 말문을 트게 되었어.",
            ["DialogueId"] = 80170310,
            ["GUID"] = "C8B2AD7C",
            ["NextDialogue"] = 80170311,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2AD7C",
            },
        [80170311] = {
            ["Content"] = "女孩告诉夫妻俩，自己失去了亲生父母。夫妻俩商量之后，决定将女孩收养。二人对养女视如己出，养女也非常乖巧懂事，一家人其乐融融。",
            ["ContentKR"] = "아이는 부모를 잃었다고 고백했고, 부부는 상의 끝에 그 아이를 입양하기로 했단다. 두 사람은 양딸을 친자식처럼 아꼈고, 그 딸 또한 매우 착하고 이해심이 깊어 그들은 무척 행복한 나날을 보냈지.",
            ["DialogueId"] = 80170311,
            ["GUID"] = "C8B2ADA6",
            ["NextOptions"] = {
                [1] = 801703111,
                },
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2ADA6",
            },
        [80170312] = {
            ["Content"] = "表面看来是这样，但，这个女孩身上藏着一个可怕的秘密。",
            ["ContentKR"] = "겉으로는 그래 보이지. 하지만, 이 아이에게는 무서운 비밀이 숨겨져 있었단다.",
            ["DialogueId"] = 80170312,
            ["FacialId"] = {
                [1] = "91502:Unhappy01",
                },
            ["GUID"] = "C8B2ADD0",
            ["NextDialogue"] = 80170313,
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2ADD0",
            },
        [80170313] = {
            ["Content"] = "她出身于异端者的家庭，一家人都信奉卡戎之民的古老神话。正因如此，她的父母遭到处决，但她却因为奇特的自愈能力捡回一条命。",
            ["ContentKR"] = "그 아이는 이단자 가문 출신으로, 가족 모두가 카론의 고대 신화를 믿었어. 그리하여 부모는 처형당했지만, 그 아이만은 특별한 치유 능력 덕분에 살아남을 수 있었지.",
            ["DialogueId"] = 80170313,
            ["GUID"] = "C8B2ADFA",
            ["NextDialogue"] = 80170314,
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_Talk02R_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2ADFA",
            },
        [80170314] = {
            ["Content"] = "她用血肉模糊的手指一寸寸挖开坟墓，从旷野奔逃进林地。",
            ["ContentKR"] = "그 아이는 피투성이가 된 손가락으로 무덤을 기어 나와 광야를 지나서 숲으로 도망쳤단다.",
            ["DialogueId"] = 80170314,
            ["GUID"] = "C8B2AE24",
            ["NextDialogue"] = 80170315,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2AE24",
            },
        [80170315] = {
            ["Content"] = "在艾利西安，没有比信仰异教更加严重的罪行。一旦这个秘密暴露，养父母就算不将她交给处刑人，也一定会立刻抛弃她。",
            ["ContentKR"] = "엘리시안에서는 이교를 믿는 것이 가장 큰 죄였어. 이 비밀이 드러나면 양부모는 그 아이를 처형인에게 넘기지 않을 지언정, 버릴 게 뻔했지.",
            ["DialogueId"] = 80170315,
            ["GUID"] = "C8B2AE4E",
            ["NextDialogue"] = 80170316,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2AE4E",
            },
        [80170316] = {
            ["Content"] = "好不容易重新拥有了“家”的女孩不愿意失去这份温暖，于是便抱着小小的侥幸，对自己真正的身份缄口不言。",
            ["ContentKR"] = "겨우 다시 얻은 '가정'의 따뜻함을 잃고 싶지 않았던 아이는 자그마한 희망을 품고 진짜 신분을 숨겼단다.",
            ["DialogueId"] = 80170316,
            ["GUID"] = "C8B2AE78",
            ["NextDialogue"] = 80170317,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2AE78",
            },
        [80170317] = {
            ["Content"] = "时间一天天过去，女孩在养父母的呵护下健康长大，没有任何人发现她的秘密。慢慢地，她自己也忘记了这件事，一心相信可以就这样幸福地活下去。",
            ["ContentKR"] = "시간이 흐르면서, 아이는 양부모의 보살핌 속에서 건강하게 자랐고, 아무도 소녀의 비밀을 알아채지 못했어. 점차 그 소녀 자신도 그 일을 잊고, 이렇게 행복하게 살 수 있을 거라고 믿었지.",
            ["DialogueId"] = 80170317,
            ["GUID"] = "C8B2AEA2",
            ["NextDialogue"] = 80170318,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2AEA2",
            },
        [80170318] = {
            ["Content"] = "当养母提出带她进城做工见见世面的时候，她也没有多想。毕竟她们只是去贵族的宅邸做扫地搓衣的低级女佣，不会引人注目。",
            ["ContentKR"] = "양모가 그녀에게 도시로 가서 일을 배우자고 했을 때도, 깊이 생각하지 않았어. 어차피 귀족 저택에서 청소하고 빨래하는 하녀일 뿐이라 눈에 띄지 않을 거라고 생각했단다.",
            ["DialogueId"] = 80170318,
            ["GUID"] = "C8B2AECC",
            ["NextDialogue"] = 80170319,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2AECC",
            },
        [80170319] = {
            ["Content"] = "可是有一天，她的养母在打扫时失手打碎了一件收藏品。按照宅邸中的规定，这样的过失需要用鞭刑来惩罚。她不忍心养母受苦，替养母认下了错。",
            ["ContentKR"] = "그런데 어느 날, 양모가 청소를 하다 실수로 수집품을 깨뜨렸어. 저택 규정에 따라 이런 실수는 채찍질로 벌을 받아야 했지. 소녀는 양모가 고통받는 것을 참을 수 없어 대신 잘못을 인정했어.",
            ["DialogueId"] = 80170319,
            ["GUID"] = "C8B2AEF6",
            ["NextDialogue"] = 80170320,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2AEF6",
            },
        [80170320] = {
            ["Content"] = "她的皮肤在一瞬间被抽出了触目惊心的伤口，却又在短短几分钟后迅速愈合。",
            ["ContentKR"] = "채찍질을 당한 소녀는 피부에 심각한 상처를 입었지만, 몇 분 만에 상처가 아물었단다.",
            ["DialogueId"] = 80170320,
            ["GUID"] = "C8B2AF20",
            ["NextDialogue"] = 80170321,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2AF20",
            },
        [80170321] = {
            ["Content"] = "这样的“神迹”很快传到了宅邸的主人——“慷慨”大人——的耳中。他闻讯赶到现场，对准女孩的心脏刺下一刀，女孩痛苦挣扎了数十分钟后，活了过来。",
            ["ContentKR"] = "이런 '기적'은 곧 저택의 주인인 '관대' 님의 귀에 들어갔지. 그는 이런 소식을 듣고는 바로 달려와서 소녀의 심장을 찔렀어. 그 후 수십 분 동안 고통스럽게 몸부림치던 소녀는 다시 살아났지.",
            ["DialogueId"] = 80170321,
            ["GUID"] = "C8B2AF4A",
            ["NextDialogue"] = 80170322,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2AF4A",
            },
        [80170322] = {
            ["Content"] = "于是“慷慨”大人将这个女孩带走，并调查了她的身份，发现她正是当年那两个异端者的女儿。",
            ["ContentKR"] = "이후 '관대' 님은 소녀를 데려가 신분을 조사했고, 소녀가 바로 그 이단자 부부의 딸임을 알게 되었지.",
            ["DialogueId"] = 80170322,
            ["FacialId"] = {
                [1] = "91502:Sad01",
                },
            ["GUID"] = "C8B2AF74",
            ["NextDialogue"] = 80170323,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2AF74",
            },
        }
  end },
  { MinKey = 80170323, MaxKey = 80180335, Loader = function()
      return {
        [80170323] = {
            ["Content"] = "看着这个杀不死的女孩，他最初是愤怒，但又突然想到一个绝佳的主意——艾利西安从未出现过这样的异能，如果能当做“神迹”好好利用，他便可名利双收。",
            ["ContentKR"] = "죽지 않는 소녀를 보며 처음엔 분노했지만, 엘리시안에 이런 능력이 나타난 적이 없으니 곧 이 능력을 '기적'이라 포장하면 명예와 이익을 얻을 수 있겠다는 생각이 들었어.",
            ["DialogueId"] = 80170323,
            ["GUID"] = "C8B2AF9E",
            ["NextDialogue"] = 80170324,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2AF9E",
            },
        [80170324] = {
            ["Content"] = "但要这么做，就必须隐瞒女孩的真实身份。为此，他将女孩关押起来，给她编造了新的身份，又将女孩的养母秘密处决。",
            ["ContentKR"] = "하지만 그렇게 하려면 소녀의 진짜 신분을 숨겨야 했지. 그래서 그는 소녀를 감금하고 새로운 신분을 만들어주었으며, 소녀의 양모를 비밀리에 처형했단다.",
            ["DialogueId"] = 80170324,
            ["GUID"] = "C8B2AFC8",
            ["NextOptions"] = {
                [1] = 801703241,
                },
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2AFC8",
            },
        [80170325] = {
            ["Content"] = "女孩感到非常后悔。若不是因为她贪恋亲情的温暖，隐瞒了自己的身份，便不会让善良的养父母经受如此惨剧。",
            ["ContentKR"] = "소녀는 깊이 후회했단다. 만약 가족의 따뜻함을 탐하지 않고 신분을 숨기지 않았다면, 선량한 양부모가 이런 비극을 겪지 않았을 거라 생각했지.",
            ["DialogueId"] = 80170325,
            ["GUID"] = "C8B2AFF2",
            ["NextDialogue"] = 80170326,
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_Talk02R_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2AFF2",
            },
        [80170326] = {
            ["Content"] = "所以，尽管女孩在“大迁徙”发生之时被反抗军救走，却没有再去见自己的养父。这场相遇从一开始就是错误的，她不想再给养父带去麻烦。",
            ["ContentKR"] = "그래서 '대이동' 때 저항군에게 구출되었지만, 더 이상 양부를 찾아가지 않았어. 이 만남은 처음부터 잘못된 것이었고, 양부에게 더 이상 폐를 끼치고 싶지 않았던 거야.",
            ["DialogueId"] = 80170326,
            ["GUID"] = "C8B2B01C",
            ["NextDialogue"] = 80170327,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2B01C",
            },
        [80170327] = {
            ["Content"] = "此后数十年，她一直对往事耿耿于怀，放心不下养父。后来，我在途径艾利西安的时候，替她前去拜访了她的养父。",
            ["ContentKR"] = "그 후 수십 년 동안, 그녀는 과거를 잊지 못하고 양부를 걱정했어. 나중에 내가 엘리시안을 지날 때, 그녀를 대신해 양부를 찾아갔단다.",
            ["DialogueId"] = 80170327,
            ["FacialId"] = {
                [1] = "91502:None",
                },
            ["GUID"] = "C8B2B046",
            ["NextDialogue"] = 80170328,
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2B046",
            },
        [80170328] = {
            ["Content"] = "那时她的养父已经是个鬓发斑斑的老人。他已经隐姓埋名多年，见到我时，他很惊讶居然还有人知道他曾经的名字。",
            ["ContentKR"] = "그때 양부는 이미 머리가 희끗해 진 노인이 되어있었지. 오랫동안 자신의 이름을 숨기고 살았던 그는, 내가 그의 옛 이름을 알고 있다는 사실에 꽤 놀라는 눈치였지.",
            ["DialogueId"] = 80170328,
            ["GUID"] = "C8B2B070",
            ["NextDialogue"] = 80170329,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2B070",
            },
        [80170329] = {
            ["Content"] = "按照女孩的意愿，我没有告知自己的真正来意，只是以引渡人的身份和他聊了聊天，说起了当年的事。",
            ["ContentKR"] = "그녀의 뜻에 따라, 난 진짜 의도를 밝히지 않고 인도자의 신분으로 그와 옛날 이야기를 나누며 대화를 했어.",
            ["DialogueId"] = 80170329,
            ["GUID"] = "C8B2B09A",
            ["NextDialogue"] = 80170330,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2B09A",
            },
        [80170330] = {
            ["Content"] = "老人还清楚地记得当年发生的一切，记得自己在一夜之间失去了妻女，又变成了通缉犯，辗转流亡数年。",
            ["ContentKR"] = "노인은 여전히 그때의 일을 뚜렷이 기억하고 있었지. 하룻밤 사이에 아내와 딸을 잃고, 수배자가 되어 몇 년을 떠돌며 겪었던 고통을.",
            ["DialogueId"] = 80170330,
            ["GUID"] = "C8B2B0C4",
            ["NextDialogue"] = 80170331,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2B0C4",
            },
        [80170331] = {
            ["Content"] = "但出乎意料的是，他告诉我，自己并不后悔收养了那个孩子。",
            ["ContentKR"] = "그럼에도 그는 놀랍게도, 그 아이를 입양했던 걸 후회하지 않는다고 했어.",
            ["DialogueId"] = 80170331,
            ["FacialId"] = {
                [1] = "91502:Shock01",
                },
            ["GUID"] = "C8B2B0EE",
            ["NextDialogue"] = 80170332,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2B0EE",
            },
        [80170332] = {
            ["Content"] = "他还拿出了一个匣子交给我——那是他妻子的骨灰。他说自己一直在等一位引渡人，好让妻子的灵魂能安然离去。",
            ["ContentKR"] = "노인은 아내의 유골이 담긴 상자를 나에게 건네며 이렇게 말했단다. 자신은 아내의 영혼이 편히 떠날 수 있도록 인도자를 기다리고 있었다고.",
            ["DialogueId"] = 80170332,
            ["GUID"] = "C8B2B118",
            ["NextDialogue"] = 80170333,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2B118",
            },
        [80170333] = {
            ["Content"] = "我在惊讶中完成了这场迟来几十年的送别仪式。不可思议的是，我竟然还能听见那个灵魂的低语——",
            ["ContentKR"] = "나는 놀란 마음으로 수십 년 만에 늦은 이별식을 진행했어. 그리고 그 과정에서 그녀의 영혼이 속삭이는 말을 들을 수 있었지...",
            ["DialogueId"] = 80170333,
            ["GUID"] = "C8B2B142",
            ["NextDialogue"] = 80170334,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2B142",
            },
        [80170334] = {
            ["Content"] = "她和丈夫说了同样的话：“谢谢你成为我们的女儿。”",
            ["ContentKR"] = "그녀와 그녀의 남편은 모두 똑같은 말을 했어. \"우리의 딸이 되어줘서 고마워.\"",
            ["DialogueId"] = 80170334,
            ["FacialId"] = {
                [1] = "91502:Smile01",
                },
            ["GUID"] = "C8B2B16C",
            ["NextDialogue"] = 80170335,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2B16C",
            },
        [80170335] = {
            ["Content"] = "老人告诉我，其实他们从一开始就知道那女孩的身份。女孩父母被杀害的那一天，他们亲眼见到了手执火把的处刑人闯入密林。",
            ["ContentKR"] = "노인은 사실 처음부터 그 아이의 신분을 알고 있었다고 했어. 아이의 부모가 살해당한 날, 그들은 횃불을 든 처형인이 숲으로 들어가는 것을 직접 봤었거든.",
            ["DialogueId"] = 80170335,
            ["GUID"] = "C8B2B196",
            ["NextDialogue"] = 80170336,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2B196",
            },
        [80170336] = {
            ["Content"] = "因此，第二天，在看到那个流浪的女孩的瞬间，他就猜到了她的身份。他们夫妻俩是在知道真相的前提下，决定收养女孩的。",
            ["ContentKR"] = "다음 날 길을 잃은 소녀를 발견했을 때, 그 아이의 정체를 짐작했지만, 진실을 알고도 그 아이를 입양하기로 결심했단다.",
            ["DialogueId"] = 80170336,
            ["GUID"] = "C8B2B1C0",
            ["NextDialogue"] = 80170337,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2B1C0",
            },
        [80170337] = {
            ["Content"] = "对他们来说，能够遇见女孩，保护她、养育她，是莫大的幸福。即便这份幸福建立在危险之上，他们也甘愿接受。",
            ["ContentKR"] = "그들에게는, 그 아이를 만나게 되고, 지켜주고 키워 줄 수 있다는 것은 큰 행복이었던거야. 그 행복에 위험이 따르더라도, 기꺼이 받아들였을 거라고.",
            ["DialogueId"] = 80170337,
            ["GUID"] = "C8B2B1EA",
            ["NextDialogue"] = 80170338,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2B1EA",
            },
        [80170338] = {
            ["Content"] = "老人还说，他当年唯一后悔的事情，是自己不够勇敢。如果他早点带着妻女逃离艾利西安，也许一家人现在依然能幸福地生活。",
            ["ContentKR"] = "노인은 말했지, 자신이 후회하는 단 한가지는 용감하지 못했던 것이었다고. 만약 아내와 딸을 데리고 일찌감치 엘리시안을 떠났더라면, 지금도 행복하게 살고 있었을지도 모른다고 말이야.",
            ["DialogueId"] = 80170338,
            ["GUID"] = "C8B2B214",
            ["NextDialogue"] = 80170339,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2B214",
            },
        [80170339] = {
            ["Content"] = "所以，在那之后，他也从一个被捏造罪名的普通猎户，变成了真正的“异端者”——几十年来，他一直在暗中帮助艾利西安平民逃离边境。",
            ["ContentKR"] = "그래서 그 후로 그는 조작된 죄명을 가진 평범한 사냥꾼에서 진정한 '이단자'가 되었어. 수십 년 동안 엘리시안의 평민들이 국경을 넘을 수 있도록 도왔단다.",
            ["DialogueId"] = 80170339,
            ["GUID"] = "C8B2B23E",
            ["NextOptions"] = {
                [1] = 801703391,
                },
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2B23E",
            },
        [80170340] = {
            ["Content"] = "……虽然我没有明说，但看他释然的神情，我想他应该猜到了吧。",
            ["ContentKR"] = "...직접 말하지는 않았지만, 그의 평온한 표정을 보니, 어쩌면 이미 짐작했을지도 몰라.",
            ["DialogueId"] = 80170340,
            ["GUID"] = "C8B2B268",
            ["NextDialogue"] = 80170341,
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2B268",
            },
        [80170341] = {
            ["Content"] = "虽然不能再相见，但知道彼此都还安好，也足以成为安慰吧。",
            ["ContentKR"] = "다시 만날 수는 없지만, 서로가 잘 지내고 있다는 걸 아는 것만으로도 위안이 되겠죠.",
            ["DialogueId"] = 80170341,
            ["GUID"] = "C8B2B292",
            ["NextDialogue"] = 80170342,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2B292",
            },
        [80170342] = {
            ["Content"] = "这个故事的结局不算太糟。",
            ["ContentKR"] = "이 이야기의 결말이 그리 나쁘진 않네요.",
            ["DialogueId"] = 80170342,
            ["GUID"] = "C8B2B2BC",
            ["NextDialogue"] = 80170343,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2B2BC",
            },
        [80170343] = {
            ["Content"] = "嗯。听了他的这些话，我不禁这么想——",
            ["ContentKR"] = "그래. 그의 이야기를 들으면서 이런 생각이 들었단다...",
            ["DialogueId"] = 80170343,
            ["GUID"] = "C8B2B2E6",
            ["NextDialogue"] = 80170344,
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2B2E6",
            },
        [80170344] = {
            ["Content"] = "我们人类啊，只要活着，就总是会做出一些错误的选择。有时是因为目光短浅，有时是因为心存侥幸，有时则是明知故犯。",
            ["ContentKR"] = "우리는 살아가면서 늘 잘못된 선택을 하게 되기 마련이지. 때로는 몰라서, 때로는 운에 맡겨서, 또 때로는 알면서도 실수를 하곤 했지.",
            ["DialogueId"] = 80170344,
            ["FacialId"] = {
                [1] = "91502:Confident01",
                },
            ["GUID"] = "C8B2B310",
            ["NextDialogue"] = 80170345,
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2B310",
            },
        [80170345] = {
            ["Content"] = "但是，错误的选择带来的未必总是错误的结果。其中酸甜苦涩，只有当事人自己才完全知晓。",
            ["ContentKR"] = "하지만 잘못된 선택이 항상 잘못된 결과로 이어지는 건 아니야. 그 선택을 둘러싼 감정은 오직 당사자만이 온전히 이해할 수 있단다.",
            ["DialogueId"] = 80170345,
            ["GUID"] = "C8B2B33A",
            ["NextDialogue"] = 80170346,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2B33A",
            },
        [80170346] = {
            ["Content"] = "比起错误本身，更重要的是，我们还有未来。",
            ["ContentKR"] = "잘못 그 자체보다 중요한 건, 우리에게 아직 미래가 있다는 거야.",
            ["DialogueId"] = 80170346,
            ["GUID"] = "C8B2B364",
            ["NextDialogue"] = 80170347,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2B364",
            },
        [80170347] = {
            ["Content"] = "我们可以弥补它，改变它，赋予它更多的意义。",
            ["ContentKR"] = "우리는 그 잘못을 보완하고, 변화시키며, 더 깊은 의미를 부여할 수 있지.",
            ["DialogueId"] = 80170347,
            ["GUID"] = "C8B2B38E",
            ["NextDialogue"] = 80170348,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2B38E",
            },
        [80170348] = {
            ["Content"] = "至少，当那个老人和我讲起往事的时候，我从他的脸上看到的不是懊悔或痛苦，而是平静与幸福。",
            ["ContentKR"] = "적어도, 그 노인이 나에게 과거를 이야기하던 순간만큼은, 후회나 고통 보단 평온과 행복이 배어 있었단다.",
            ["DialogueId"] = 80170348,
            ["GUID"] = "C8B2B3B8",
            ["NextOptions"] = {
                [1] = 801703481,
                },
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2B3B8",
            },
        [80170349] = {
            ["Content"] = "谢谢你的故事，今天我也受益匪浅。",
            ["ContentKR"] = "이야기 감사합니다. 오늘 저도 많은 걸 배웠어요.",
            ["DialogueId"] = 80170349,
            ["GUID"] = "C8B2B3E2",
            ["NextDialogue"] = 80170350,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2B3E2",
            },
        [80170350] = {
            ["Content"] = "呵呵， 是我要谢谢你才对。",
            ["ContentKR"] = "하하, 내가 고마워해야지.",
            ["DialogueId"] = 80170350,
            ["FacialId"] = {
                [1] = "91502:Smile01",
                },
            ["GUID"] = "C8B2B40C",
            ["NextDialogue"] = 80170351,
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2B40C",
            },
        [80170351] = {
            ["Content"] = "许是因为上了年纪，我说话总是有些啰嗦，多谢你愿意陪着我这个老人家，听我絮絮叨叨地讲这些往事。",
            ["ContentKR"] = "나이를 먹어서 그런지 내가 말이 좀 많아졌네. 이야기를 들어줘서 고마워.",
            ["DialogueId"] = 80170351,
            ["GUID"] = "C8B2B436",
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/003/C8B2B436",
            },
        [80170401] = {
            ["Camera"] = "135.91098,22.045166,124.542297,0.000012,1.800007,-136.994522,35.0,158.845352,false,Manual,3.0",
            ["Content"] = "你来了，孩子。今天想聊些什么？",
            ["ContentKR"] = "왔구나, 아이야. 오늘은 또 어떤 이야기를 나눠볼까?",
            ["DialogueId"] = 80170401,
            ["FacialId"] = {
                [1] = "91502:Smile01",
                },
            ["GUID"] = "C8B2BC6A",
            ["LookAt"] = {
                [1] = "91502:p(18000P1)",
                },
            ["NextOptions"] = {
                [1] = 801704011,
                },
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/004/C8B2BC6A",
            },
        [80170402] = {
            ["Content"] = "今天我想听妮弗尔自己的故事。",
            ["ContentKR"] = "오늘은 나이플 부인의 이야기를 듣고 싶어요.",
            ["DialogueId"] = 80170402,
            ["GUID"] = "C8B2BC94",
            ["NextDialogue"] = 80170403,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/004/C8B2BC94",
            },
        [80170403] = {
            ["Content"] = "我的故事啊……你这么聪明，应该已经猜到了吧？",
            ["ContentKR"] = "내 이야기라... 너라면 이미 짐작했을지도 모르겠구나.",
            ["DialogueId"] = 80170403,
            ["GUID"] = "C8B2BCBE",
            ["NextOptions"] = {
                [1] = 801704031,
                [2] = 801704032,
                },
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/004/C8B2BCBE",
            },
        [80170404] = {
            ["Content"] = "其实，你之前讲的那些故事，都是你亲身经历的事情，对吧？",
            ["ContentKR"] = "사실, 전에 들려줬던 이야기들이 모두 부인의 경험담이죠?",
            ["DialogueId"] = 80170404,
            ["GUID"] = "C8B2BCE8",
            ["NextDialogue"] = 80170405,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/004/C8B2BCE8",
            },
        [80170405] = {
            ["Content"] = "没错。",
            ["ContentKR"] = "맞아.",
            ["DialogueId"] = 80170405,
            ["GUID"] = "C8B2BD12",
            ["NextDialogue"] = 80170407,
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/004/C8B2BD12",
            },
        [80170406] = {
            ["Content"] = "其实我自己的故事，就藏在之前那些故事中间。",
            ["ContentKR"] = "사실, 나의 이야기는 전에 말해주었던 이야기들 속에 담겨 있단다.",
            ["DialogueId"] = 80170406,
            ["GUID"] = "C8B2BD3C",
            ["NextDialogue"] = 80170407,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/004/C8B2BD3C",
            },
        [80170407] = {
            ["Content"] = "它们既是别人的故事，也都是我的故事。",
            ["ContentKR"] = "그 이야기들은 다른 이들의 이야기이기도 하지만, 모두 내 이야기이기도 하지.",
            ["DialogueId"] = 80170407,
            ["GUID"] = "C8B2BD66",
            ["NextDialogue"] = 80170408,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/004/C8B2BD66",
            },
        [80170408] = {
            ["Content"] = "我是那个拥有异能却不能消解他人苦难的女人，是那个被囚禁在圣堂中无力反抗的少女，也是那个害得养父母家破人亡的孩子。",
            ["ContentKR"] = "나는 능력을 가졌지만 타인의 고통을 덜어줄 수 없었던 여인이고, 성당에 갇혀 아무것도 할 수 없었던 소녀이며, 양부모를 불행하게 만든 아이이기도 하단다.",
            ["DialogueId"] = 80170408,
            ["GUID"] = "C8B2BD90",
            ["NextDialogue"] = 80170409,
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/004/C8B2BD90",
            },
        [80170409] = {
            ["Content"] = "嗯……可是，我还是想听你完完整整地说一遍——不再以旁观的视角，而是以你自己，妮弗尔，作为主角。",
            ["ContentKR"] = "음... 그래도 저는 나이플 부인이 제삼자가 아닌 주인공으로서 자신의 이야기를 온전히 들려줬으면 좋겠어요.",
            ["DialogueId"] = 80170409,
            ["GUID"] = "C8B2BDBA",
            ["NextDialogue"] = 80170410,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/004/C8B2BDBA",
            },
        [80170410] = {
            ["Content"] = "是吗……好，既然你有兴趣，我便难得地回忆一下往事吧。",
            ["ContentKR"] = "그래... 알겠어. 그렇게 원한다면 내 이야기를 들려줄게.",
            ["DialogueId"] = 80170410,
            ["GUID"] = "C8B2BDE4",
            ["NextDialogue"] = 80170411,
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/004/C8B2BDE4",
            },
        [80170411] = {
            ["Content"] = "我本是艾利西安人，出生在一个信奉卡戎神话的家庭。",
            ["ContentKR"] = "난 원래 엘리시안 사람이었고, 카론 신화를 믿는 가정에서 태어났단다.",
            ["DialogueId"] = 80170411,
            ["GUID"] = "C8B2BE0E",
            ["NextDialogue"] = 80170412,
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_Talk02R_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/004/C8B2BE0E",
            },
        [80170412] = {
            ["Content"] = "在我十岁的时候，我的父母因异端者罪被处刑，我本该和他们一同死去，却在那时意外觉醒为“骸”，获得了不老不死的异能，活了下来。",
            ["ContentKR"] = "열 살이 되던 해에 부모님이 이단자라는 죄목으로 처형당하셨고, 나도 함께 죽을 뻔했지만, 그때 우연히 '다이몬'으로 각성해서 불로불사의 능력을 얻고 살아남았지.",
            ["DialogueId"] = 80170412,
            ["FacialId"] = {
                [1] = "91502:Sad01",
                },
            ["GUID"] = "C8B2BE38",
            ["NextDialogue"] = 80170413,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/004/C8B2BE38",
            },
        [80170413] = {
            ["Content"] = "失去了亲生父母的我独自在森林中游荡，被路过的猎户救下，从此拥有了第二个家。",
            ["ContentKR"] = "부모님을 잃고 혼자 숲을 떠돌다가 지나가던 사냥꾼에게 구출되어 두 번째 가정을 얻게 되었어.",
            ["DialogueId"] = 80170413,
            ["GUID"] = "C8B2BE62",
            ["NextDialogue"] = 80170414,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/004/C8B2BE62",
            },
        [80170414] = {
            ["Content"] = "十八岁时，我无意中暴露了自己的真实身份，被“慷慨”大人发现，从此戴上了“被赐福者”这顶荆棘之冠。",
            ["ContentKR"] = "열여덟 살 때, 우연히 내 정체가 드러나 '관대'님에게 발견되었고, 그때부터 '축복받은 자'라는 무거운 짐을 지게 되었단다.",
            ["DialogueId"] = 80170414,
            ["GUID"] = "C8B2BE8C",
            ["NextDialogue"] = 80170415,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/004/C8B2BE8C",
            },
        [80170415] = {
            ["Content"] = "此后数年间，我的世界就只剩下了那间小小的圣堂，而“慷慨”大人则靠贩卖我的血液敛财无数。",
            ["ContentKR"] = "그 후 몇 년 동안, 나의 세상은 작은 성당이 전부가 되어버렸고, '관대'님은 내 피를 이용해 막대한 부를 쌓았어.",
            ["DialogueId"] = 80170415,
            ["GUID"] = "C8B2BEB6",
            ["NextDialogue"] = 80170416,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/004/C8B2BEB6",
            },
        [80170416] = {
            ["Content"] = "直到，两位勇敢的反叛者将我从这个噩梦中救了出来——第二个故事中的青年和少女是我的恩人，是我最好的朋友，也是为我指引前进方向的人。",
            ["ContentKR"] = "그러다 두 명의 용감한 반역자가 이 악몽에서 나를 구해주었지. 두 번째 이야기 속 청년과 귀족 소녀는 내 은인이자 가장 친한 친구였으며, 나에게 새로운 길을 제시해 준 사람들이기도 하단다.",
            ["DialogueId"] = 80170416,
            ["FacialId"] = {
                [1] = "91502:Confident01",
                },
            ["GUID"] = "C8B2BEE0",
            ["NextDialogue"] = 80170417,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/004/C8B2BEE0",
            },
        [80170417] = {
            ["Content"] = "后来，艾瑞卡死于北上途中的一场战役；莱克西斯虽然平安逃离，却始终没有找到理想国度的答案，最后在成堆的书稿之中郁郁而终。",
            ["ContentKR"] = "나중에 에리카는 북쪽으로 향하던 도중 전투에서 생을 마감했고, 렉시스는 무사히 도망쳤지만, 꿈꾸던 세상을 이루지 못한 채 쌓여있던 원고 속에서 쓸쓸히 생을 마감했어.",
            ["DialogueId"] = 80170417,
            ["GUID"] = "C8B2BF0A",
            ["NextDialogue"] = 80170418,
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_Talk02R_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/004/C8B2BF0A",
            },
        [80170418] = {
            ["Content"] = "在伊瑟尔生活的时候，我收养了一个孩子。那是我第一次站在养育者的立场上，去见证一个人完整的生命。",
            ["ContentKR"] = "또 이스엘에서 살 땐, 난 한 아이를 입양했지. 처음으로 양육자의 입장에서 한 사람의 온전한 삶을 지켜보게 되었단다.",
            ["DialogueId"] = 80170418,
            ["GUID"] = "C8B2BF34",
            ["NextDialogue"] = 80170419,
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/004/C8B2BF34",
            },
        [80170419] = {
            ["Content"] = "我看着她从襁褓中的小小婴儿，出落成明媚动人的少女，再蜕变为沉静睿智的女人；我记得她的啼哭，记得她牙牙学语，记得她第一次背起古老的诗文……",
            ["ContentKR"] = "그 아이가 아기에서 밝고 사랑스러운 소녀로, 그리고 차분하고 지혜로운 여인으로 성장해 가는 모습을 지켜봤어. 그 아이가 울음을 터뜨리던 순간, 옹알이를 시작하던 때, 처음으로 오래된 시를 외우던 그 장면들이 아직도 생생히 기억나...",
            ["DialogueId"] = 80170419,
            ["GUID"] = "C8B2BF5E",
            ["NextDialogue"] = 80170420,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/004/C8B2BF5E",
            },
        [80170420] = {
            ["Content"] = "记得她与莱克西斯滔滔不绝的辩论，也记得她悲痛而郑重地在莱克西斯的病榻前收下他图书馆的钥匙。",
            ["ContentKR"] = "렉시스와 열띤 토론을 나누던 모습, 그리고 그의 병상 옆에서 도서관 열쇠를 건네받던 슬퍼하며 진지한 모습까지 모두 기억하고 있단다.",
            ["DialogueId"] = 80170420,
            ["GUID"] = "C8B2BF88",
            ["NextDialogue"] = 80170421,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/004/C8B2BF88",
            },
        [80170421] = {
            ["Content"] = "我为她的点滴变化而惊喜和欣慰，但也清晰地意识到，她终究也是有限的生命。像艾瑞卡和莱克西斯一样，她也无法永远与我同行。",
            ["ContentKR"] = "그 아이가 조금씩 성장하는 모습을 보며 기뻐했고, 또 안도했지만, 결국 그 아이 또한 언젠가는 끝이 있는 생명을 가진 존재라는 사실을 난 알고 있었지. 에리카와 렉시스처럼 그 아이 역시 영원히 내 곁에 머물 수는 없다는 걸 말이야.",
            ["DialogueId"] = 80170421,
            ["GUID"] = "C8B2BFB2",
            ["NextDialogue"] = 80170422,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/004/C8B2BFB2",
            },
        [80170422] = {
            ["Content"] = "最终，他们都离开了我。我曾经为他们的离去感到悲伤，但在遇到那对求血的姐妹、见证更多的生离死别之后，我终于彻底接受了这无常的世间。",
            ["ContentKR"] = "결국, 그들은 모두 날 떠났단다. 그들과의 이별은 슬펐지만, 이후 피를 원하는 자매들을 만나며 더 많은 생이별과 사별을 경험하게 되면서 이 덧없는 세상을 자연스럽게 받아들이게 되었지.",
            ["DialogueId"] = 80170422,
            ["FacialId"] = {
                [1] = "91502:None",
                },
            ["GUID"] = "C8B2BFDC",
            ["NextDialogue"] = 80170423,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/004/C8B2BFDC",
            },
        [80170423] = {
            ["Content"] = "我放下了悲喜，也抛却了欲念，不会为人世间的诸多苦难而哀痛或愤懑。在那之后的九百年，我一直辗转阿特拉西亚各地引渡亡魂。",
            ["ContentKR"] = "난 슬픔과 기쁨을 내려놓고 욕망도 버렸어. 인간 세상의 많은 고통에 슬퍼하거나 분노하지 않게 되었고, 이후 900년 동안 아트라시아 곳곳을 떠돌며 망자를 인도해 왔단다.",
            ["DialogueId"] = 80170423,
            ["GUID"] = "C8B2C006",
            ["NextDialogue"] = 80170424,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/004/C8B2C006",
            },
        [80170424] = {
            ["Content"] = "如今我在海伯利亚暂时停留，是为了一个面容熟悉的孩子。但我也无意参与纷争或改变什么，只是想见证她的故事而已。",
            ["ContentKR"] = "지금 휘페르보레아 제국에 잠시 머무는 건, 낯익은 얼굴의 아이 때문인데, 그저 그 아이의 이야기를 지켜보려는 것뿐이야. 분쟁에 개입하거나 무언가를 바꿀 생각은 없어.",
            ["DialogueId"] = 80170424,
            ["GUID"] = "C8B2C030",
            ["NextDialogue"] = 80170425,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/004/C8B2C030",
            },
        [80170425] = {
            ["Content"] = "不久之后，我大概又会踏上旅途吧……这世上再也不会有什么东西能真正让我结束飘零，除非，“死亡”终于愿意为我敞开怀抱。",
            ["ContentKR"] = "얼마 지나지 않아 나는 다시 여행을 떠나겠지... 이제 이 세상 어디에도 날 정착하게 만들 수 있는 것은 없어. '죽음'이 마침내 나를 받아들이는 날이 오기 전까지.",
            ["DialogueId"] = 80170425,
            ["GUID"] = "C8B2C05A",
            ["NextDialogue"] = 80170426,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/004/C8B2C05A",
            },
        [80170426] = {
            ["Content"] = "——这就是我的故事，不知你是否满意？",
            ["ContentKR"] = "이게 나의 이야기야. 이제 만족하니?",
            ["DialogueId"] = 80170426,
            ["GUID"] = "C8B2C084",
            ["NextOptions"] = {
                [1] = 801704261,
                },
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/004/C8B2C084",
            },
        [80170427] = {
            ["Content"] = "我还想知道，在拥有这些身份之前，在还没有获得长生的能力之前——那时的“妮弗尔”，是怎样的人？",
            ["ContentKR"] = "이 능력을 얻기 전, 장생의 능력을 갖기 전의 '나이플'은 어떤 사람이었나요?",
            ["DialogueId"] = 80170427,
            ["GUID"] = "C8B2C0AE",
            ["NextDialogue"] = 80170428,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/004/C8B2C0AE",
            },
        [80170428] = {
            ["Content"] = "……",
            ["ContentKR"] = "......",
            ["DialogueId"] = 80170428,
            ["FacialId"] = {
                [1] = "91502:Shock01",
                },
            ["GUID"] = "C8B2C0D8",
            ["NextDialogue"] = 80170429,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/004/C8B2C0D8",
            },
        [80170429] = {
            ["Content"] = "很多人都对我的过去抱有好奇，但问起我童年时期的，你还是第一个。相比于我后来的人生，那段回忆实在太过平淡和普通。",
            ["ContentKR"] = "많은 사람들이 내 과거에 대해 궁금해했지만, 어린 시절에 관해 묻는 건 네가 처음이야. 이후의 삶과 비교하면 그 기억들은 너무 평범했는데.",
            ["DialogueId"] = 80170429,
            ["GUID"] = "C8B2C102",
            ["NextDialogue"] = 80170430,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/004/C8B2C102",
            },
        [80170430] = {
            ["Content"] = "让我想想……",
            ["ContentKR"] = "기억을 좀 돌이켜볼께...",
            ["DialogueId"] = 80170430,
            ["FacialId"] = {
                [1] = "91502:Think01",
                },
            ["GUID"] = "C8B2C12C",
            ["NextDialogue"] = 80170431,
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/004/C8B2C12C",
            },
        [80170431] = {
            ["Content"] = "我的家——我最初的那个家，在艾利西安北方一片郁郁葱葱的森林中。那里没有传颂会，没有贵族，只有可爱的野兔和美味的浆果。",
            ["ContentKR"] = "내 첫 번째 집은 엘리시안 북쪽의 울창한 숲속에 있었어. 거기에는 교회도 귀족도 없었고, 귀여운 토끼들과 맛있는 열매들만 있었단다.",
            ["DialogueId"] = 80170431,
            ["GUID"] = "C8B2C156",
            ["NextDialogue"] = 80170432,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/004/C8B2C156",
            },
        [80170432] = {
            ["Content"] = "我对童年的记忆，是树叶间洒下的斑驳阳光，是溪水潺潺悦耳的声响。",
            ["ContentKR"] = "어린 시절의 기억은 나뭇잎 사이로 비치는 햇살과 시냇물의 졸졸 흐르는 소리와 함께 하지.",
            ["DialogueId"] = 80170432,
            ["GUID"] = "C8B2C180",
            ["NextDialogue"] = 80170433,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/004/C8B2C180",
            },
        [80170433] = {
            ["Content"] = "那时的我，就和一个普通的女孩一样，会吵着要父亲带我去森林里玩耍，会不顾母亲的叮嘱在小溪边肆意玩水。",
            ["ContentKR"] = "그때 나는 그저 평범한 아이였어. 아버지에게 숲에서 놀자고 떼를 쓰기도 하고, 어머니의 당부를 무시한 채 개울가에서 신나게 물놀이를 하기도 했지.",
            ["DialogueId"] = 80170433,
            ["GUID"] = "C8B2C1AA",
            ["NextDialogue"] = 80170434,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/004/C8B2C1AA",
            },
        [80170434] = {
            ["Content"] = "我的母亲也是一位引渡人。我常常见到陌生人穿越森林，将一个小匣子交给母亲。母亲会在月下起舞，让那个匣子顺着水流漂走。",
            ["ContentKR"] = "내 어머니도 인도자였어. 낯선 사람들이 숲을 지나 작은 상자를 어머니에게 건네는 걸 자주 봤단다. 어머니는 달빛 아래에서 춤을 추며 그 상자를 물에 띄워 보냈어.",
            ["DialogueId"] = 80170434,
            ["GUID"] = "C8B2C1D4",
            ["NextDialogue"] = 80170435,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/004/C8B2C1D4",
            },
        [80170435] = {
            ["Content"] = "我问母亲，匣子里装的是什么？母亲回答说，是人们的思念。",
            ["ContentKR"] = "한번은 어머니에게 상자 안에 뭐가 들어있냐고 물어봤는데, 어머니는 사람들의 그리움이라고 대답하셨지.",
            ["DialogueId"] = 80170435,
            ["GUID"] = "C8B2C1FE",
            ["NextDialogue"] = 80170436,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/004/C8B2C1FE",
            },
        [80170436] = {
            ["Content"] = "我又问母亲，为什么要把思念扔进水里？母亲回答说，因为人们还要向前走。",
            ["ContentKR"] = "내가 다시 왜 그리움을 물에 버리는지 물었을 때, 어머니는 사람들이 앞으로 나아가기 위해서라고 하셨어.",
            ["DialogueId"] = 80170436,
            ["GUID"] = "C8B2C228",
            ["NextDialogue"] = 80170437,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/004/C8B2C228",
            },
        [80170437] = {
            ["Content"] = "我完全听不明白。看到我一脸困惑的样子，父亲笑着摸了摸我的头顶，说等我长大就会懂了。",
            ["ContentKR"] = "난 그때 전혀 이해할 수 없었지. 내가 혼란스러워하는 모습을 보고 아버지는 웃으며 내 머리를 쓰다듬고는, 크면 이해할 거라고 하셨어.",
            ["DialogueId"] = 80170437,
            ["GUID"] = "C8B2C252",
            ["NextDialogue"] = 80170438,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/004/C8B2C252",
            },
        [80170438] = {
            ["Content"] = "只可惜，他们没能看到我长大的模样。在他们被处刑人杀死的那一刻，属于那个无忧无虑的妮弗尔的人生也就结束了。",
            ["ContentKR"] = "안타깝게도, 그들은 내가 자라는 모습을 보지 못했단다. 그들이 처형인에게 살해당한 순간, 걱정 없던 나이플의 삶도 끝났어.",
            ["DialogueId"] = 80170438,
            ["FacialId"] = {
                [1] = "91502:Sad01",
                },
            ["GUID"] = "C8B2C27C",
            ["NextOptions"] = {
                [1] = 801704381,
                },
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/004/C8B2C27C",
            },
        [80170439] = {
            ["Content"] = "我偶尔会忆起往事，但并不像人们通常所做的那样，带着怀念和追思去摩挲这些回忆，只是任由它们从思绪中浮起、飘过。",
            ["ContentKR"] = "가끔 과거를 떠올리긴 하지만, 보통 사람들이 그러는 것처럼 그리움이나 추억에 잠기지는 않아. 그저 기억이 스쳐 지나가도록 내버려둘 뿐이지.",
            ["DialogueId"] = 80170439,
            ["FacialId"] = {
                [1] = "91502:None",
                },
            ["GUID"] = "C8B2C2A6",
            ["NextDialogue"] = 80170440,
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/004/C8B2C2A6",
            },
        [80170440] = {
            ["Content"] = "于我而言，那段往事，连同其他所有的回忆一样，都是我生命的一部分，本没有什么特别。",
            ["ContentKR"] = "나에게 그 시절은 다른 모든 기억과 마찬가지로 내 삶의 일부일 뿐, 특별한 건 없단다.",
            ["DialogueId"] = 80170440,
            ["GUID"] = "C8B2C2D0",
            ["NextDialogue"] = 80170441,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/004/C8B2C2D0",
            },
        [80170441] = {
            ["Content"] = "不过，也许是因为今天有你这个听众在，说起这些往事的时候，我的心中似乎也起了些许波澜……",
            ["ContentKR"] = "하지만, 오늘은 네가 이야기를 들어주고 있어서인지, 과거를 이야기하다 보니 내 마음에도 잔잔한 파문이 일렁이는 것 같아...",
            ["DialogueId"] = 80170441,
            ["GUID"] = "C8B2C2FA",
            ["NextDialogue"] = 80170442,
            ["SpeakNpcId"] = 91502,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/004/C8B2C2FA",
            },
        [80170442] = {
            ["Content"] = "……我有些累了。请允许我休息片刻吧。",
            ["ContentKR"] = "...조금 피곤하네. 잠시 쉬어도 될까?",
            ["DialogueId"] = 80170442,
            ["FacialId"] = {
                [1] = "91502:Close",
                },
            ["GUID"] = "C8B2C324",
            ["NextDialogue"] = 80170443,
            ["SpeakNpcId"] = 91502,
            ["TalkActionId"] = {
                [1] = "91502:Sit_Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/004/C8B2C324",
            },
        [80170443] = {
            ["Content"] = "（妮弗尔夫人说着闭上了眼睛，轻轻地将脑袋靠在你的肩膀上。）",
            ["ContentKR"] = "(나이플 부인은 눈을 감고 살며시 머리를 당신의 어깨에 기댄다.)",
            ["DialogueId"] = 80170443,
            ["GUID"] = "C8B2C34E",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 80170444,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/004/C8B2C34E",
            },
        [80170444] = {
            ["Content"] = "（从她安稳的呼吸和略带笑意的表情来看，她一定是做了一个好梦吧。）",
            ["ContentKR"] = "(그녀의 고른 숨소리와 약간의 미소를 보니, 분명 좋은 꿈을 꾸고 있는 것 같다.)",
            ["DialogueId"] = 80170444,
            ["GUID"] = "C8B2C378",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 80170445,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/004/C8B2C378",
            },
        [80170445] = {
            ["Content"] = "（一个充满着浆果的香气和阳光的暖意——或许还有一只调皮的野兔飞奔而过——的好梦。）",
            ["ContentKR"] = "(아마도 열매 향기와 햇살의 따스함이 가득한 꿈... 그리고 장난스러운 토끼 한 마리가 뛰어다니는 꿈일 것이다.)",
            ["DialogueId"] = 80170445,
            ["GUID"] = "C8B2C3A2",
            ["IsBlack"] = 1,
            ["VoiceName"] = "voice/$Locale$/inv/Nifu/004/C8B2C3A2",
            },
        [80180001] = {
            ["DialogueId"] = 80180001,
            ["GUID"] = "C8B8E36A",
            ["SpeakNpcId"] = 790045,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/001/C8B8E36A",
            },
        [80180101] = {
            ["Camera"] = "452.71582,-120.713928,293.808594,0.000068,-25.999489,160.803513,30.000002,125.0,false,DoNotOverride,2.8",
            ["Content"] = "（那是半年前，我去医院探望一位在南方战线对传颂会战争中负伤的老兵罗杰·加斯顿的事。）",
            ["ContentKR"] = "(반년 전, 남부 전선에서 교회와 전쟁을 치르다 부상을 입은 노병, 로저 개스톤 씨의 병문안을 갔던 날의 일이다.)",
            ["DialogueId"] = 80180101,
            ["FacialId"] = {
                [1] = "790045:Unhappy01",
                },
            ["FinalCamera"] = "452.71582,-120.713928,293.808594,0.000071,-23.999413,157.603546,30.000002,125.0,false,DoNotOverride,2.8",
            ["GUID"] = "C8B8F3D2",
            ["NextDialogue"] = 80180102,
            ["SpeakNpcId"] = 790045,
            ["TalkActionId"] = {
                [1] = "790045:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/001/C8B8F3D2",
            },
        [80180102] = {
            ["Camera"] = "-17.312012,189.65033,156.878906,0.000039,-12.39904,-60.39682,30.000002,247.327988,false,Manual,3.162369",
            ["Content"] = "艾米莉亚……你来了……",
            ["ContentKR"] = "에밀리아... 왔구나...",
            ["DialogueId"] = 80180102,
            ["FinalCamera"] = "-15.135742,190.885254,156.878906,0.00004,-12.399033,-61.39677,30.000002,247.327988,false,Manual,3.162369",
            ["GUID"] = "C8B8F3FC",
            ["NextDialogue"] = 80180103,
            ["SpeakNpcId"] = 790059,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/001/C8B8F3FC",
            },
        [80180103] = {
            ["Camera"] = "93.808105,84.920227,124.542969,0.000044,9.600609,157.202698,30.000008,107.300728,false,Manual,3.162369",
            ["Content"] = "…………",
            ["ContentKR"] = "......",
            ["DialogueId"] = 80180103,
            ["GUID"] = "C8B8F426",
            ["NextDialogue"] = 80180104,
            ["SpeakNpcId"] = 790045,
            ["TalkActionId"] = {
                [1] = "790045:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/001/C8B8F426",
            },
        [80180104] = {
            ["Content"] = "……是的，爸爸。我来看您了。",
            ["ContentKR"] = "...네, 아빠. 저 왔어요.",
            ["DialogueId"] = 80180104,
            ["GUID"] = "C8B8F450",
            ["NextDialogue"] = 80180105,
            ["SpeakNpcId"] = 790045,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/001/C8B8F450",
            },
        [80180105] = {
            ["Camera"] = "233.50293,-42.842896,169.013672,0.000073,-14.598969,150.198013,30.000002,247.327988,false,DoNotOverride,3.162369",
            ["Content"] = "我带了一些糕点和蜂蜜，是迪斯玛尼亚最受欢迎的烘焙店买的！您……尝尝还合不合胃口？",
            ["ContentKR"] = "과자랑 꿀을 좀 사 왔어요. 디즈마니아에서 가장 인기 있는 빵집 거예요! 입에 맞는지... 조금 드셔 보실래요?",
            ["DialogueId"] = 80180105,
            ["FinalCamera"] = "233.50293,-42.842896,169.013672,0.000074,-10.998831,146.797302,30.000002,247.327988,false,DoNotOverride,3.162369",
            ["GUID"] = "C8B8F47A",
            ["NextDialogue"] = 80180106,
            ["SpeakNpcId"] = 790045,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/001/C8B8F47A",
            },
        [80180106] = {
            ["Camera"] = "-0.36084,492.293091,78.546875,0.000105,4.201092,-82.801735,30.000002,247.327988,false,DoNotOverride,3.162369",
            ["Content"] = "艾米莉亚，你走近些，让我看看……",
            ["ContentKR"] = "에밀리아, 이리 가까이 오렴. 얼굴 좀 보자꾸나...",
            ["DialogueId"] = 80180106,
            ["FinalCamera"] = "-15.919922,490.611572,78.546875,0.000109,4.201092,-79.201218,30.000002,247.327988,false,DoNotOverride,3.162369",
            ["GUID"] = "C8B8F4A4",
            ["NextDialogue"] = 80180107,
            ["SpeakNpcId"] = 790059,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/001/C8B8F4A4",
            },
        [80180107] = {
            ["Content"] = "你长高了好多，也瘦了……炼金院的工作，还是很辛苦吧……",
            ["ContentKR"] = "키는 훌쩍 자랐는데, 살은 더 빠진 걸 보니... 연금원 일이 아직도 많이 힘든 모양이구나...",
            ["DialogueId"] = 80180107,
            ["GUID"] = "C8B8F4CE",
            ["NextDialogue"] = 80180108,
            ["SpeakNpcId"] = 790059,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/001/C8B8F4CE",
            },
        [80180108] = {
            ["Camera"] = "124.885254,73.358887,114.648438,0.000111,8.801046,154.798798,30.000002,247.327988,false,DoNotOverride,3.162369",
            ["Content"] = "没关系的，我很好！研究员们都很友善，他们也总是很照顾我。",
            ["ContentKR"] = "괜찮아요, 전 잘 지내요! 연구원들도 다들 친절하고, 항상 절 잘 챙겨 주는걸요.",
            ["DialogueId"] = 80180108,
            ["FinalCamera"] = "129.206543,80.562866,114.648438,0.000111,8.801046,157.199387,30.000002,247.327988,false,DoNotOverride,3.162369",
            ["GUID"] = "C8B8F4F8",
            ["NextDialogue"] = 80180109,
            ["SpeakNpcId"] = 790045,
            ["TalkActionId"] = {
                [1] = "790045:Talk02_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/001/C8B8F4F8",
            },
        [80180109] = {
            ["Camera"] = "-22.415527,411.51062,217.269531,0.000075,-19.597588,-75.394966,30.000002,247.327988,false,DoNotOverride,3.162369",
            ["Content"] = "……不……",
            ["ContentKR"] = "...아니야...",
            ["DialogueId"] = 80180109,
            ["FinalCamera"] = "-37.787109,408.08606,217.269531,0.000077,-19.597588,-72.99453,30.000002,247.327988,false,DoNotOverride,3.162369",
            ["GUID"] = "C8B8F522",
            ["NextDialogue"] = 80180110,
            ["SpeakNpcId"] = 790059,
            ["TalkActionId"] = {
                [1] = "790045:Talk02_End",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/001/C8B8F522",
            },
        [80180110] = {
            ["Content"] = "艾米莉亚每次提起炼金院的时候都会掉眼泪，说她常常后悔去了那里。",
            ["ContentKR"] = "에밀리아는 연금원 얘기를 꺼낼 때마다 눈물을 글썽였어. 거기 간 게 후회된다는 얘기도 자주 했었지.",
            ["DialogueId"] = 80180110,
            ["GUID"] = "C8B8F54C",
            ["NextDialogue"] = 80180111,
            ["SpeakNpcId"] = 790059,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/001/C8B8F54C",
            },
        [80180111] = {
            ["Camera"] = "114.473145,81.809021,158.171875,0.000098,-23.197474,-77.990166,30.000002,247.327988,false,DoNotOverride,3.162369",
            ["Content"] = "你不是艾米莉亚！……你究竟是谁？",
            ["ContentKR"] = "넌 에밀리아가 아니야! ...대체 정체가 뭐지?",
            ["DialogueId"] = 80180111,
            ["FinalCamera"] = "110.792969,99.114258,165.755859,0.000092,-22.997458,-77.989754,30.000002,247.327988,false,DoNotOverride,3.162369",
            ["GUID"] = "C8B8F576",
            ["NextDialogue"] = 80180112,
            ["SpeakNpcId"] = 790059,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/001/C8B8F576",
            },
        [80180112] = {
            ["Camera"] = "211.481445,-34.879761,148.429688,0.000081,-6.797363,148.809708,30.000002,268.824341,false,Manual,3.162369",
            ["Content"] = "抱歉……加斯顿先生。我是达芙涅·塞奥多尔，是……艾米莉亚的朋友。我代她来探望您。",
            ["ContentKR"] = "죄송해요... 개스톤 씨. 전 에밀리아의 친구... 다프네 세오도어예요. 에밀리아 대신 찾아뵈러 왔어요.",
            ["DialogueId"] = 80180112,
            ["FinalCamera"] = "214.442383,-29.989197,148.429688,0.000082,-6.797363,151.209473,30.000002,268.824341,false,Manual,3.162369",
            ["GUID"] = "C8B8F5A0",
            ["NextDialogue"] = 80180113,
            ["SpeakNpcId"] = 790045,
            ["TalkActionId"] = {
                [1] = "790045:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/001/C8B8F5A0",
            },
        [80180113] = {
            ["Camera"] = "389.942871,-15.916992,216.761719,0.000082,-16.596901,170.208176,30.000002,379.770111,false,Manual,3.162369",
            ["Content"] = "……啊啊……对不起，塞奥多尔小姐。请原谅我没法站起来向你问候。",
            ["ContentKR"] = "...아아, 미안해요, 세오도어 양... 이렇게 누워서 인사를 받는 무례를 용서해 줘요.",
            ["DialogueId"] = 80180113,
            ["FacialId"] = {
                [1] = "790059:CM_Sad01",
                },
            ["FinalCamera"] = "391.346191,-7.785767,216.761719,0.000082,-16.596901,170.208176,30.000002,379.770111,false,Manual,3.162369",
            ["GUID"] = "C8B8F5CA",
            ["NextDialogue"] = 80180114,
            ["SpeakNpcId"] = 790059,
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/001/C8B8F5CA",
            },
        [80180114] = {
            ["Content"] = "我又忘了很多事，也常常分不清到底是做梦还是醒着。这些天我总觉得艾米莉亚还活着。",
            ["ContentKR"] = "기억이 안 나는 일들이 많아요. 꿈을 꾸는 건지 깨어 있는 건지도 잘 구분이 안 되고... 요즘은 자꾸 에밀리아가 살아있는 것만 같아요.",
            ["DialogueId"] = 80180114,
            ["GUID"] = "C8B8F5F4",
            ["NextDialogue"] = 80180115,
            ["SpeakNpcId"] = 790059,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/001/C8B8F5F4",
            },
        [80180115] = {
            ["Camera"] = "-14.48877,190.756897,161.263672,0.000049,-12.396656,-61.593624,30.000008,244.623566,false,Manual,3.301471",
            ["Content"] = "她变得那么小，像小时候一样，从八层的台阶上跳下来扑到我怀里，喊着“爸爸”。",
            ["ContentKR"] = "꼬마 때처럼 자그마해져선, 계단 8개를 깡충 뛰어 내려와 품에 쏙 안기며 \"아빠\"하고 부르더라고요.",
            ["DialogueId"] = 80180115,
            ["FinalCamera"] = "-7.308105,195.172363,161.263672,0.000047,-12.396656,-65.793968,30.000008,244.623566,false,Manual,3.301471",
            ["GUID"] = "C8B8F61E",
            ["NextDialogue"] = 80180116,
            ["SpeakNpcId"] = 790059,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/001/C8B8F61E",
            },
        [80180116] = {
            ["Camera"] = "116.074707,70.821228,122.748047,0.000048,6.402981,152.803696,30.000008,131.13031,false,Manual,3.301471",
            ["Content"] = "加斯顿先生……对不……",
            ["ContentKR"] = "개스톤 씨... 정말 죄송...",
            ["DialogueId"] = 80180116,
            ["FinalCamera"] = "120.910645,79.414978,122.748047,0.000047,6.402981,155.80397,30.000008,131.026245,false,Manual,3.301471",
            ["GUID"] = "C8B8F648",
            ["NextDialogue"] = 80180117,
            ["SpeakNpcId"] = 790045,
            ["TalkActionId"] = {
                [1] = "790045:Explain02_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/001/C8B8F648",
            },
        [80180117] = {
            ["Content"] = "不，孩子，你不用安慰我……我能想起来，艾米莉亚一个月前就下葬了，一位好心肠的护士推着我去了她的葬礼。我把她小时候总在玩的那只橡皮鸭子放在了她的墓前。",
            ["ContentKR"] = "아니에요, 아가씨. 굳이 위로하려 애쓸 필요 없어요... 다 기억나요. 에밀리아는 한 달 전에 땅에 묻혔죠. 친절한 간호사 한 분이 휠체어에 태워 장례식에 데려다줬거든요. 그 애가 어릴 때 늘 가지고 놀던 고무 오리도 직접 무덤 앞에 놓아 주고 왔어요.",
            ["DialogueId"] = 80180117,
            ["GUID"] = "C8B8F672",
            ["NextDialogue"] = 80180118,
            ["SpeakNpcId"] = 790059,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/001/C8B8F672",
            },
        [80180118] = {
            ["Camera"] = "437.276855,-80.072693,281.332031,0.000106,-25.192556,163.998383,30.000008,507.135406,false,Manual,2.479588",
            ["Content"] = "塞奥多尔小姐，你是她最好的朋友，她活着的时候总是向我说起你。你也要多小心，炼金院那种地方……",
            ["ContentKR"] = "세오도어 양, 에밀리아는 늘 자기하고 가장 친한 친구는 아가씨라고 했었어요. 그러니까 아가씨도 조심해요. 연금원 같은 곳은...",
            ["DialogueId"] = 80180118,
            ["FinalCamera"] = "437.276855,-80.072693,281.332031,0.000103,-22.392521,159.3983,30.000008,507.135406,false,Manual,2.479588",
            ["GUID"] = "C8B8F69C",
            ["NextDialogue"] = 80180119,
            ["SpeakNpcId"] = 790059,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/001/C8B8F69C",
            },
        [80180119] = {
            ["Camera"] = "437.276855,-80.072693,281.332031,0.000103,-22.392521,159.3983,30.000008,507.135406,false,Manual,2.479588",
            ["Content"] = "（我明白加斯顿先生指的是什么。我要好的同窗——艾米莉亚·加斯顿正是死于佩剑炼金院的一场意外。）",
            ["ContentKR"] = "(나는 개스톤 씨가 뭘 말하려는지 알고 있다. 나의 절친한 친구 에밀리아 개스톤은... 바로 소드 연금원에서 일어난 사고로 목숨을 잃었으니까.)",
            ["DialogueId"] = 80180119,
            ["GUID"] = "C8B8F6C6",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 80180120,
            ["SpeakNpcId"] = 790045,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/001/C8B8F6C6",
            },
        [80180120] = {
            ["Camera"] = "567.892578,244.198547,75.826172,0.000136,1.407784,-158.007095,35.0,646.375061,false,Manual,1.2",
            ["Content"] = "——唔呃！",
            ["ContentKR"] = "으윽!",
            ["DialogueId"] = 80180120,
            ["GUID"] = "C8B8F6F0",
            ["NextDialogue"] = 80180121,
            ["SpeakNpcId"] = 790059,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/001/C8B8F6F0",
            },
        [80180121] = {
            ["Camera"] = "567.892578,244.198547,75.826172,0.000136,1.407784,-158.007095,35.0,646.375061,false,Manual,1.2",
            ["Content"] = "……加斯顿先生！",
            ["ContentKR"] = "...개스톤 씨!",
            ["DialogueId"] = 80180121,
            ["GUID"] = "C8B8F71A",
            ["NextDialogue"] = 80180122,
            ["SpeakNpcId"] = 790045,
            ["TalkActionId"] = {
                [1] = "790045:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/001/C8B8F71A",
            },
        [80180122] = {
            ["Camera"] = "245.396484,-74.086365,158.837891,0.00012,-8.591114,143.39476,40.0,301.252777,false,Manual,1.955812",
            ["Content"] = "您哪儿难受吗？我这就去叫医生来！",
            ["ContentKR"] = "어디 불편하세요? 지금 바로 의사 선생님을 불러올게요!",
            ["DialogueId"] = 80180122,
            ["FinalCamera"] = "245.396484,-74.086365,158.837891,0.000121,-6.791072,142.994873,40.0,301.252777,false,Manual,1.955812",
            ["GUID"] = "C8B8F744",
            ["NextDialogue"] = 80180123,
            ["SpeakNpcId"] = 790045,
            ["TalkActionId"] = {
                [1] = "790045:Talk02_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/001/C8B8F744",
            },
        [80180123] = {
            ["Camera"] = "70.369141,68.184753,163.933594,0.000103,-23.59066,-52.404755,40.0,301.252777,false,DoNotOverride,1.955812",
            ["Content"] = "不用了……孩子……",
            ["ContentKR"] = "괜찮아요... 아가씨...",
            ["DialogueId"] = 80180123,
            ["FinalCamera"] = "64.535645,75.762634,168.109375,0.000104,-23.590666,-52.404778,40.0,301.252777,false,DoNotOverride,1.955812",
            ["GUID"] = "C8B8F76E",
            ["NextDialogue"] = 80180124,
            ["SpeakNpcId"] = 790059,
            ["ToFinalCameraBlendTime"] = 3,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/001/C8B8F76E",
            },
        [80180124] = {
            ["Content"] = "我的腿治不了了。它们在战壕里泡了太久，一条已经截断了，没截的那条也烂透了。",
            ["ContentKR"] = "이 다리는 이제 가망이 없어요. 참호에서 너무 오래 뒹굴었거든요. 한쪽은 이미 잘려 나갔고, 남은 하나도 썩어 문드러졌죠.",
            ["DialogueId"] = 80180124,
            ["GUID"] = "C8B8F798",
            ["NextDialogue"] = 80180125,
            ["SpeakNpcId"] = 790059,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/001/C8B8F798",
            },
        [80180125] = {
            ["Camera"] = "-42.722656,257.672241,151.652344,0.000059,-6.989933,-60.00206,40.0,311.952545,false,Manual,2.256478",
            ["Content"] = "除了疼之外，倒也没什么大不了的，好歹比那些送命的兄弟强……对吧……",
            ["ContentKR"] = "아픈 것만 빼면 별일 아니에요. 거기서 목숨을 잃은 친구들보단 낫잖아요... 안 그런가요...",
            ["DialogueId"] = 80180125,
            ["FinalCamera"] = "-33.669922,263.006287,151.652344,0.000065,-6.989933,-63.602329,40.0,311.952545,false,Manual,2.256478",
            ["GUID"] = "C8B8F7C2",
            ["NextDialogue"] = 80180126,
            ["SpeakNpcId"] = 790059,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/001/C8B8F7C2",
            },
        [80180126] = {
            ["Content"] = "唔……啊啊啊……",
            ["ContentKR"] = "크윽... 으으윽...",
            ["DialogueId"] = 80180126,
            ["GUID"] = "C8B8F7EC",
            ["NextDialogue"] = 80180127,
            ["SpeakNpcId"] = 790059,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/001/C8B8F7EC",
            },
        [80180127] = {
            ["Content"] = "（加斯顿先生疼痛的病症又犯了。他的双手紧紧地抓住床单，青筋暴起。我知道，那是一位退伍老兵竭力抓住自己最后的东西——体面。）",
            ["ContentKR"] = "(또다시 고통이 개스톤 씨를 덮쳤다. 힘줄이 도드라질 정도로 힘껏 침대 시트를 움켜쥐는 개스톤 씨는, 퇴역 군인으로서 마지막 자존심을 지키기 위해 몸부림치고 있었다.)",
            ["DialogueId"] = 80180127,
            ["GUID"] = "C8B8F816",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 80180128,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/001/C8B8F816",
            },
        [80180128] = {
            ["Camera"] = "-196.821289,36.408081,111.78125,0.000072,-0.789276,-6.604747,40.000011,311.952545,false,Manual,2.256478",
            ["Content"] = "呃啊啊啊啊啊——",
            ["ContentKR"] = "으아아아악!",
            ["DialogueId"] = 80180128,
            ["FinalCamera"] = "-228.835938,40.114746,112.220703,0.000072,-0.789276,-6.604747,40.000011,311.952545,false,Manual,2.256478",
            ["GUID"] = "C8B8F840",
            ["NextDialogue"] = 80180129,
            ["SpeakNpcId"] = 790059,
            ["ToFinalCameraBlendTime"] = 0.5,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/001/C8B8F840",
            },
        [80180129] = {
            ["Camera"] = "146.449707,-106.377991,109.685547,0.000106,5.210492,114.589401,40.000011,311.952545,false,Manual,2.256478",
            ["Content"] = "塞奥多尔小姐，拜托你。给我一枪吧！我早就是个废物了，除了在床上打滚，什么都做不到！现在连唯一的女儿都……",
            ["ContentKR"] = "세오도어 양, 부탁이에요. 날 쏴 줘요! 난 이미 산송장이에요. 침대에서 나뒹구는 것 말곤 할 수 있는 게 없어요! 그런데 이젠 하나뿐인 딸까지...",
            ["DialogueId"] = 80180129,
            ["FinalCamera"] = "141.276367,-109.157471,109.685547,0.000106,5.210492,112.589111,40.000011,311.952545,false,Manual,2.256478",
            ["GUID"] = "C8B8F86A",
            ["NextDialogue"] = 80180130,
            ["SpeakNpcId"] = 790059,
            ["TalkActionId"] = {
                [1] = "790045:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/001/C8B8F86A",
            },
        [80180130] = {
            ["Content"] = "我会写下遗嘱，证明这是我自己自愿的。还有遗产……我没有其他家人了，我可以把老家的屋子也留给你！",
            ["ContentKR"] = "스스로 원한 일이었다고 유언장도 써 놓을게요. 그리고 유산도... 그 낡은 집도 다 아가씨한테 줄게요! 어차피 다른 가족도 없으니까요.",
            ["DialogueId"] = 80180130,
            ["GUID"] = "C8B8F894",
            ["NextDialogue"] = 80180131,
            ["SpeakNpcId"] = 790059,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/001/C8B8F894",
            },
        [80180131] = {
            ["Camera"] = "9.807129,54.86792,159.228516,-28.800745,-17.989195,-27.007662,40.000011,311.952545,false,DoNotOverride,2.256478",
            ["Content"] = "给我一枪，求求你，给我一枪——！或者至少，把我另一条腿也砍断吧！",
            ["ContentKR"] = "부탁이니까 날 쏴 줘요, 제발요! 아니면, 차라리 남은 다리라도 잘라내 줘요!",
            ["DialogueId"] = 80180131,
            ["FinalCamera"] = "-10.913086,65.429382,166.779297,-18.000868,-17.989195,-27.007536,40.000011,311.952545,false,DoNotOverride,2.256478",
            ["GUID"] = "C8B8F8BE",
            ["NextDialogue"] = 80180132,
            ["SpeakNpcId"] = 790059,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/001/C8B8F8BE",
            },
        [80180132] = {
            ["Camera"] = "92.85498,2.856323,117.208984,-0.001006,7.810587,122.38958,40.000011,311.952545,false,DoNotOverride,2.256478",
            ["Content"] = "不……加斯顿先生，我不能那样做！",
            ["ContentKR"] = "안 돼요... 개스톤 씨, 그럴 순 없어요!",
            ["DialogueId"] = 80180132,
            ["FinalCamera"] = "102.462891,-12.291992,114.761719,-0.001006,7.810587,122.38958,40.000011,311.952545,false,DoNotOverride,2.256478",
            ["GUID"] = "C8B8F8E8",
            ["NextDialogue"] = 80180133,
            ["SpeakNpcId"] = 790045,
            ["TalkActionId"] = {
                [1] = "790045:Explain02_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/001/C8B8F8E8",
            },
        [80180133] = {
            ["Camera"] = "-328.205566,88.299622,110.056641,-0.001007,2.210365,-3.410769,40.000011,466.053558,false,Manual,1.2",
            ["Content"] = "请您再忍耐一段时间！只要一年……不，半年。我发誓，以翠玉勋章发誓，我会治好您的！",
            ["ContentKR"] = "조금만 더 견뎌 주세요! 1년... 아니, 딱 6개월만요. 무슨 일이 있어도 낫게 해 드릴게요. 제 비취 훈장을 걸고 맹세해요!",
            ["DialogueId"] = 80180133,
            ["FinalCamera"] = "-329.355469,68.979004,110.056641,-0.001007,2.210365,-0.410614,40.000011,466.053558,false,Manual,1.2",
            ["GUID"] = "C8B8F912",
            ["NextDialogue"] = 80180134,
            ["SpeakNpcId"] = 790045,
            ["TalkActionId"] = {
                [1] = "790045:Talk02_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/001/C8B8F912",
            },
        [80180134] = {
            ["Content"] = "请您活下去……这一定也是艾米莉亚的心愿！",
            ["ContentKR"] = "삶을 포기하시면 안 돼요... 에밀리아도 그러길 바랄 거예요!",
            ["DialogueId"] = 80180134,
            ["GUID"] = "C8B8F93C",
            ["NextDialogue"] = 80180135,
            ["SpeakNpcId"] = 790045,
            ["TalkActionId"] = {
                [1] = "790045:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/001/C8B8F93C",
            },
        [80180135] = {
            ["Camera"] = "-195.09668,210.955811,166.289062,-0.001007,-8.589727,-28.414295,45.0,388.30954,false,Manual,1.750545",
            ["Content"] = "呜……呜呜……",
            ["ContentKR"] = "으흑... 으흐윽...",
            ["DialogueId"] = 80180135,
            ["FinalCamera"] = "-214.103516,221.238892,169.546875,-0.001007,-8.589727,-28.414295,45.0,411.829193,false,Manual,1.750545",
            ["GUID"] = "C8B8F966",
            ["NextDialogue"] = 80180136,
            ["SpeakNpcId"] = 790059,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/001/C8B8F966",
            },
        [80180136] = {
            ["Content"] = "（剧烈的翻滚和挣扎后，病床的躁动逐渐平静了下来。加斯顿先生在抽泣中睡去了，不知是疼昏了头，还是艾米莉亚的名字让他多少恢复了镇定。）",
            ["ContentKR"] = "(한바탕 폭풍이 휩쓸고 간 후, 병상은 조금씩 고요해졌다. 고통에 지쳐 정신을 잃은 건지, 아니면 딸의 이름에 조금이나마 진정된 건지는 알 수 없지만, 흐느끼던 개스톤 씨도 잠이 들었다.)",
            ["DialogueId"] = 80180136,
            ["GUID"] = "C8B8F990",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 80180137,
            ["SpeakNpcId"] = 790045,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/001/C8B8F990",
            },
        [80180137] = {
            ["Content"] = "（对人们来说，疼痛也许是比死亡更残忍的折辱。在漫长的岁月里，它如同打磨一块卵石一样，将人的意气与尊严尽数磨平。）",
            ["ContentKR"] = "(고통이란 어쩌면 인간에게 죽음보다 끔찍한 모욕일지도 모른다. 세월이 조약돌을 마모시키듯, 고통은 사람의 의지와 존엄을 흔적도 없이 닳아 없어지게 만든다.)",
            ["DialogueId"] = 80180137,
            ["GUID"] = "C8B8F9BA",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 80180138,
            ["SpeakNpcId"] = 790045,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/001/C8B8F9BA",
            },
        [80180138] = {
            ["Content"] = "（他的战友和女儿被葬在公墓，而这张白色的狭小病床，则是他的坟茔。）",
            ["ContentKR"] = "(전우들과 딸은 공동묘지에 묻혔지만, 개스톤 씨의 무덤은, 바로 이 하얗고 비좁은 침대였다.)",
            ["DialogueId"] = 80180138,
            ["GUID"] = "C8B8F9E4",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 80180139,
            ["SpeakNpcId"] = 790045,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/001/C8B8F9E4",
            },
        [80180139] = {
            ["Content"] = "（而那一天，在加斯顿先生的病床前，我终于做出了那个重要的抉择。）",
            ["ContentKR"] = "(그리고 그날, 나는 개스톤 씨의 병상 앞에서, 중요한 결단을 내렸다.)",
            ["DialogueId"] = 80180139,
            ["GUID"] = "C8B8FA0E",
            ["IsBlack"] = 1,
            ["SpeakNpcId"] = 790045,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/001/C8B8FA0E",
            },
        [80180201] = {
            ["Camera"] = "-21.269043,-387.99707,181.142334,0.000059,-9.599646,87.198402,30.000008,489.123169,false,Manual,1.2",
            ["Content"] = "你看，达芙涅！我们的AG-1899号强效镇痛药已经成功合成了。",
            ["ContentKR"] = "이거 봐, 다프네! 우리가 드디어 강력 진통제 AG-1899를 합성해 냈어.",
            ["DialogueId"] = 80180201,
            ["FinalCamera"] = "-21.269043,-387.99707,181.142334,0.000052,-11.999659,87.198425,30.000008,489.123169,false,Manual,1.2",
            ["GUID"] = "C8B9043A",
            ["NextDialogue"] = 80180202,
            ["SpeakNpcId"] = 790056,
            ["TalkActionId"] = {
                [1] = "790056:Talk02_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B9043A",
            },
        [80180202] = {
            ["Camera"] = "40.555176,-36.499023,178.654053,0.000067,-22.199459,72.391502,30.000008,489.123169,false,DoNotOverride,1.2",
            ["Content"] = "啊，确切来说是你的……毕竟大部分构想和实验都是你的，我只算得上你的实验助手而已。",
            ["ContentKR"] = "아, 정확히 말하면 우리가 아닌 네가 성공한 거지만... 구상이랑 실험은 거의 다 네가 했고, 난 실험 조수나 마찬가지였으니까.",
            ["DialogueId"] = 80180202,
            ["FinalCamera"] = "45.767578,-38.120117,178.654053,0.000066,-22.199451,74.391289,30.000008,489.123169,false,DoNotOverride,1.2",
            ["GUID"] = "C8B90464",
            ["NextDialogue"] = 80180203,
            ["SpeakNpcId"] = 790056,
            ["TalkActionId"] = {
                [1] = "790056:Talk02_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B90464",
            },
        [80180203] = {
            ["Camera"] = "141.903809,100.63916,144.927734,0.000075,-3.59927,-147.809128,35.0,267.386597,false,Manual,2.319523",
            ["Content"] = "别这么说！如果不是你坚持，我也不会参与到这个课题来呀。",
            ["ContentKR"] = "아니야! 네가 계속 하자고 안 했으면, 난 이 프로젝트에 참여하지도 않았을 거야.",
            ["DialogueId"] = 80180203,
            ["FinalCamera"] = "144.20166,96.986328,144.927734,0.000075,-3.59927,-149.008759,35.0,267.386597,false,Manual,2.319523",
            ["GUID"] = "C8B9048E",
            ["NextDialogue"] = 80180204,
            ["SpeakNpcId"] = 790045,
            ["TalkActionId"] = {
                [1] = "790045:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B9048E",
            },
        [80180204] = {
            ["Camera"] = "134.325195,-279.771973,156.985107,0.00007,-7.199005,97.99205,35.0,361.466309,false,Manual,2.319523",
            ["Content"] = "达芙涅，你说，只要我们的药剂通过毒性实验……只要炼金院能把它投入生产……",
            ["ContentKR"] = "있잖아, 다프네. 우리가 만든 약이 독성 실험을 무사히 통과해서... 연금원에서 이걸 생산하고...",
            ["DialogueId"] = 80180204,
            ["FinalCamera"] = "123.702637,-281.262207,156.985107,0.00007,-7.199005,97.99205,35.0,361.466309,false,Manual,2.319523",
            ["GUID"] = "C8B904B8",
            ["NextDialogue"] = 80180205,
            ["SpeakNpcId"] = 790056,
            ["TalkActionId"] = {
                [1] = "790056:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B904B8",
            },
        [80180205] = {
            ["Camera"] = "-93.812012,-132.799805,142.472168,0.000076,-3.198878,58.991425,35.0,264.274048,false,Manual,3.676726",
            ["Content"] = "只要它能顺利诞生，走进每一所医院，每一处战场——",
            ["ContentKR"] = "이 약을 무사히 세상에 선보이고, 모든 병원이랑 전장에 보급된다면...",
            ["DialogueId"] = 80180205,
            ["FinalCamera"] = "-89.988281,-135.097168,142.472168,0.000077,-3.198878,60.79129,35.0,264.274048,false,Manual,3.676726",
            ["GUID"] = "C8B904E2",
            ["NextDialogue"] = 80180206,
            ["SpeakNpcId"] = 790056,
            ["TalkActionId"] = {
                [1] = "790056:Think_End",
                [2] = "790045:Explain02_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B904E2",
            },
        [80180206] = {
            ["Content"] = "那些被疼痛折磨的人，就能变得好过一些吧？",
            ["ContentKR"] = "고통에 시달리던 사람들도, 조금은 괜찮아지겠지?",
            ["DialogueId"] = 80180206,
            ["GUID"] = "C8B9050C",
            ["SpeakNpcId"] = 790056,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B9050C",
            },
        [80180207] = {
            ["Camera"] = "154.316406,-437.40625,81.189453,0.000059,11.198689,114.994148,30.000002,125.0,false,DoNotOverride,2.8",
            ["Content"] = "…………",
            ["ContentKR"] = "......",
            ["DialogueId"] = 80180207,
            ["FinalCamera"] = "154.316406,-437.40625,81.189453,0.000059,11.198689,114.994148,30.000002,125.0,false,DoNotOverride,2.8",
            ["GUID"] = "C8B90536",
            ["NextDialogue"] = 80180208,
            ["SpeakNpcId"] = 790045,
            ["TalkActionId"] = {
                [1] = "790045:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B90536",
            },
        [80180208] = {
            ["Camera"] = "59.469727,2.3125,118.984375,0.000144,2.398797,-108.205406,30.000002,125.0,false,DoNotOverride,2.8",
            ["Content"] = "达芙涅·塞奥多尔。",
            ["ContentKR"] = "다프네 세오도어.",
            ["DialogueId"] = 80180208,
            ["FinalCamera"] = "78.555176,-4.228027,118.984375,0.000145,2.398797,-112.405106,30.000002,125.0,false,DoNotOverride,2.8",
            ["GUID"] = "C8B90560",
            ["NextDialogue"] = 80180209,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B90560",
            },
        [80180209] = {
            ["Camera"] = "30.060059,-266.956055,146.386719,0.000153,-4.000885,105.797691,30.000002,284.222046,false,Manual,2.8",
            ["Content"] = "……是，梅森女士。不……现在应该叫您“军团长”大人。",
            ["ContentKR"] = "...네, 메이슨 씨. 아니... 이젠 '군단장'님이라고 불러야겠네요.",
            ["DialogueId"] = 80180209,
            ["FinalCamera"] = "34.405273,-265.727051,146.386719,0.000154,-4.000885,106.997757,30.000002,284.222046,false,Manual,2.8",
            ["GUID"] = "C8B9058A",
            ["NextDialogue"] = 80180210,
            ["SpeakNpcId"] = 790045,
            ["TalkActionId"] = {
                [1] = "790045:Explain02_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B9058A",
            },
        [80180210] = {
            ["Camera"] = "27.647949,-145.186035,176.830078,0.000124,-27.800474,-122.401695,30.000002,284.222046,false,DoNotOverride,2.8",
            ["Content"] = "过去的你会叫我“师姐”……不过，这不重要。",
            ["ContentKR"] = "예전의 너였다면 날 '선배'라고 불렀겠지... 어쨌든, 그건 중요하지 않아.",
            ["DialogueId"] = 80180210,
            ["FinalCamera"] = "30.851074,-147.144043,176.830078,0.000117,-27.800474,-125.801666,30.000002,284.222046,false,DoNotOverride,2.8",
            ["GUID"] = "C8B905B4",
            ["NextDialogue"] = 80180211,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Talk03_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B905B4",
            },
        [80180211] = {
            ["Camera"] = "1375.89209,139.100586,164.9375,0.000093,-2.600458,-169.596542,30.000002,1368.736572,false,Manual,2.8",
            ["Content"] = "解释一下你的所作所为吧，达芙涅。你是怎么得罪塞拉斯院长的？",
            ["ContentKR"] = "네 행동에 대해 설명해 봐, 다프네. 세라스에게 무슨 잘못을 한 거지?",
            ["DialogueId"] = 80180211,
            ["FinalCamera"] = "1377.645996,129.715332,164.9375,0.000093,-2.600458,-170.996094,30.000002,1368.736572,false,Manual,2.8",
            ["GUID"] = "C8B905DE",
            ["NextDialogue"] = 80180212,
            ["SpeakNpcId"] = 790013,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B905DE",
            },
        [80180212] = {
            ["Camera"] = "42.463379,-180.554199,119.259766,0.000107,2.599891,102.002693,30.000002,284.222046,false,DoNotOverride,2.8",
            ["Content"] = "我没有多余的解释。我欺骗了院长，欺骗了整座佩剑炼金院。",
            ["ContentKR"] = "더 드릴 말씀이 없어요. 제가 원장님을 속였고, 소드 연금원 전체를 기만했어요.",
            ["DialogueId"] = 80180212,
            ["FinalCamera"] = "51.740234,-178.580566,119.259766,0.000108,2.599891,105.003036,30.000002,284.222046,false,DoNotOverride,2.8",
            ["GUID"] = "C8B90608",
            ["NextDialogue"] = 80180213,
            ["SpeakNpcId"] = 790045,
            ["TalkActionId"] = {
                [1] = "790045:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B90608",
            },
        [80180213] = {
            ["Camera"] = "51.740234,-178.580566,119.259766,0.000108,2.599891,105.003036,30.000002,284.222046,false,DoNotOverride,2.8",
            ["Content"] = "我提交了虚假的计划书，并申请了研究经费。事实上我并没有按照院长要求研究应用于激化实验的药物，而是继续了此前未完成的镇痛剂课题。",
            ["ContentKR"] = "전 계획서를 허위로 작성해서 연구비를 신청했어요. 그렇게 타낸 연구비론, 원장님이 지시하신 광폭화 촉진제가 아니라, 예전에 중단됐던 진통제 프로젝트를 계속 진행했죠.",
            ["DialogueId"] = 80180213,
            ["GUID"] = "C8B90632",
            ["NextDialogue"] = 80180214,
            ["SpeakNpcId"] = 790045,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B90632",
            },
        [80180214] = {
            ["Camera"] = "229.41748,-451.871582,304.970703,0.000153,-26.199333,122.002304,30.000002,1368.736572,false,DoNotOverride,2.8",
            ["Content"] = "……因为我认为它远比激化药物更有价值。",
            ["ContentKR"] = "...진통제를 만드는 게 훨씬 가치 있는 일이라고 생각했거든요.",
            ["DialogueId"] = 80180214,
            ["FinalCamera"] = "248.888184,-441.256836,304.970703,0.000167,-26.19932,127.202431,30.000002,1368.736572,false,DoNotOverride,2.8",
            ["GUID"] = "C8B9065C",
            ["NextDialogue"] = 80180215,
            ["SpeakNpcId"] = 790045,
            ["TalkActionId"] = {
                [1] = "790045:Explain02_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B9065C",
            },
        [80180215] = {
            ["Camera"] = "33.566895,-94.611328,178.189453,0.000141,-24.198963,109.400581,30.000002,1368.736572,false,DoNotOverride,2.8",
            ["Content"] = "我愿为我的欺瞒行为接受任何惩罚，但我这次来是请求您动用军团长的权力……特别批准炼金院将AG-1899号强效镇痛剂投入生产。",
            ["ContentKR"] = "어떤 처벌이든 달게 받을게요. 그렇지만 제발 군단장님 권한으로... 연금원이 AG-1899를 생산할 수 있도록 특별히 허가해 주세요.",
            ["DialogueId"] = 80180215,
            ["FinalCamera"] = "33.566895,-94.611328,178.189453,0.000154,-21.798882,108.600464,30.000002,1368.736572,false,DoNotOverride,2.8",
            ["GUID"] = "C8B90686",
            ["NextDialogue"] = 80180216,
            ["SpeakNpcId"] = 790045,
            ["TalkActionId"] = {
                [1] = "790045:Talk02_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B90686",
            },
        [80180216] = {
            ["Camera"] = "34.025391,-264.680176,161.505859,0.000184,-10.198838,108.00029,30.000002,293.752045,false,Manual,2.8",
            ["Content"] = "它只是一种药物，它没有犯任何错。而且，它可以拯救很多被疼痛折磨的人。",
            ["ContentKR"] = "약은 아무 잘못이 없잖아요. 그리고 그 약으로 고통받는 많은 사람을 구할 수 있어요.",
            ["DialogueId"] = 80180216,
            ["FinalCamera"] = "42.447266,-262.075195,161.505859,0.000186,-10.198838,110.800125,30.000002,293.752045,false,Manual,2.8",
            ["GUID"] = "C8B906B0",
            ["NextDialogue"] = 80180217,
            ["SpeakNpcId"] = 790045,
            ["TalkActionId"] = {
                [1] = "790045:Talk02_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B906B0",
            },
        [80180217] = {
            ["Camera"] = "69.490723,-197.728516,145.714844,0.000191,0.801079,171.39772,30.000002,293.752045,false,DoNotOverride,2.8",
            ["Content"] = "我并不打算否认AG-1899的价值。但，这种药物，其他炼金术师也能做到，只是他们需要花比你更久的时间。",
            ["ContentKR"] = "AG-1899의 가치를 부정할 생각은 없다. 하지만 그런 약은 너 말고 다른 연금술사도 충분히 만들 수 있어. 너보단 시간이 걸리겠지만.",
            ["DialogueId"] = 80180217,
            ["FinalCamera"] = "68.950684,-201.303711,145.714844,0.000191,0.801079,171.39772,30.000002,293.752045,false,DoNotOverride,2.8",
            ["GUID"] = "C8B906DA",
            ["NextDialogue"] = 80180218,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B906DA",
            },
        [80180218] = {
            ["Camera"] = "32.769043,41.966309,152.269531,0.000203,-6.59857,-107.203644,30.000002,249.2892,false,Manual,2.8",
            ["Content"] = "作为一个比旁人更优秀的研究者，你本应投入到帝国更需要的领域中去，这才符合炼金院的人对你的期待。",
            ["ContentKR"] = "남들보다 뛰어난 연구자라면, 제국에 더 필요한 분야를 연구해야지. 연금원 사람들이 네게 거는 기대에 맞게 행동해.",
            ["DialogueId"] = 80180218,
            ["FinalCamera"] = "40.151367,39.748047,152.269531,0.000204,-6.59857,-109.603592,30.000002,249.2892,false,Manual,2.8",
            ["GUID"] = "C8B90704",
            ["NextDialogue"] = 80180219,
            ["SpeakNpcId"] = 790013,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B90704",
            },
        [80180219] = {
            ["Camera"] = "971.158691,717.543945,7.337891,0.000212,3.801465,-145.200256,30.000002,1297.015747,false,Manual,2.8",
            ["Content"] = "既然你闹了这一出，以塞拉斯的脾气，就算他不惩罚你，你日后的所有研究都得在专人监视下进行了。",
            ["ContentKR"] = "이번 소동을 일으켜 세라스의 심기를 건드렸으니, 원장이 널 벌하지 않는다 해도, 앞으로 연구는 감시를 받게 될 거다.",
            ["DialogueId"] = 80180219,
            ["FinalCamera"] = "971.158691,717.543945,7.337891,0.000213,4.001452,-142.200302,30.000002,1297.015747,false,Manual,2.8",
            ["GUID"] = "C8B9072E",
            ["NextDialogue"] = 80180220,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Talk03_End",
                },
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B9072E",
            },
        [80180220] = {
            ["Camera"] = "971.158691,717.543945,7.337891,0.000213,4.001452,-142.200302,30.000002,1297.015747,false,Manual,2.8",
            ["Content"] = "…………",
            ["ContentKR"] = "......",
            ["DialogueId"] = 80180220,
            ["GUID"] = "C8B90758",
            ["NextDialogue"] = 80180221,
            ["SpeakNpcId"] = 790045,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B90758",
            },
        [80180221] = {
            ["Camera"] = "44.922852,-289.09082,141.619141,0.000184,-3.598758,107.796936,30.000002,298.325684,false,Manual,2.8",
            ["Content"] = "我拒绝，军团长。我拒绝按照院长的吩咐参加激化实验——因为，我不想成为第二个艾米莉亚·加斯顿。",
            ["ContentKR"] = "거절할게요, 군단장님. 원장님이 지시하신 광폭화 실험엔 참여하지 않을 거예요. 전... 두 번째 에밀리아 개스톤이 되고 싶진 않거든요.",
            ["DialogueId"] = 80180221,
            ["FinalCamera"] = "52.822266,-286.523438,141.619141,0.000183,-3.398798,109.996681,30.000002,298.325684,false,Manual,2.8",
            ["GUID"] = "C8B90782",
            ["NextDialogue"] = 80180222,
            ["SpeakNpcId"] = 790045,
            ["TalkActionId"] = {
                [1] = "790045:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B90782",
            },
        [80180222] = {
            ["Camera"] = "66.137207,-83.689941,127.6875,0.000023,5.200861,-122.401611,30.000002,298.325684,false,DoNotOverride,2.8",
            ["Content"] = "艾米莉亚·加斯顿？",
            ["ContentKR"] = "에밀리아 개스톤?",
            ["DialogueId"] = 80180222,
            ["FinalCamera"] = "63.108887,-81.731445,127.6875,0.000025,5.200861,-120.00177,30.000002,298.325684,false,DoNotOverride,2.8",
            ["GUID"] = "C8B907AC",
            ["NextDialogue"] = 80180223,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B907AC",
            },
        [80180223] = {
            ["Camera"] = "479.37207,-381.822266,18.287109,0.000066,7.800827,150.999481,30.000002,298.325684,false,DoNotOverride,2.8",
            ["Content"] = "在我们的课题还没完成的时候，她就被调去了激化实验的课题组。尽管她一千个、一万个不愿意，她还是无力反抗，因为这是佩剑炼金院的命令。",
            ["ContentKR"] = "진통제 연구가 한창 진행 중일 때, 에밀리는 광폭화 실험팀으로 차출됐어요. 아무리 싫다고 해도 소용없었죠. 소드 연금원의 명령은 절대적이니까요.",
            ["DialogueId"] = 80180223,
            ["FinalCamera"] = "479.37207,-381.822266,18.287109,0.000066,9.800829,150.799469,30.000002,298.325684,false,DoNotOverride,2.8",
            ["GUID"] = "C8B907D6",
            ["NextDialogue"] = 80180224,
            ["SpeakNpcId"] = 790045,
            ["TalkActionId"] = {
                [1] = "790045:Explain02_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B907D6",
            },
        [80180224] = {
            ["Camera"] = "40.990723,54.654297,136.542969,0.000085,-1.399444,-109.997879,30.000002,249.443985,false,Manual,2.8",
            ["Content"] = "哦……你是说，半年前意外死掉的那个炼金术师。",
            ["ContentKR"] = "아... 반년 전에 사고로 죽었다는 그 연금술사 말이군.",
            ["DialogueId"] = 80180224,
            ["FinalCamera"] = "47.699219,52.181641,136.542969,0.000085,-1.399444,-113.197594,30.000002,249.443985,false,Manual,2.8",
            ["GUID"] = "C8B90800",
            ["NextDialogue"] = 80180225,
            ["SpeakNpcId"] = 790013,
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B90800",
            },
        [80180225] = {
            ["Camera"] = "47.699219,52.181641,136.542969,0.000085,-1.399444,-113.197594,30.000002,249.443985,false,Manual,2.8",
            ["Content"] = "你多虑了，你一贯谨慎。你不会像她一样，粗心大意到连拘束带都忘了系，结果被疯狂的实验体捅穿胸口。",
            ["ContentKR"] = "쓸데없는 걱정이야. 넌 조심성이 많으니까, 그 연금술사처럼 구속 벨트 채우는 거 하나 제대로 기억 못 해서, 미쳐 날뛰는 실험체한테 가슴팍을 꿰뚫릴 일은 없어.",
            ["DialogueId"] = 80180225,
            ["GUID"] = "C8B9082A",
            ["NextDialogue"] = 80180226,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B9082A",
            },
        [80180226] = {
            ["Camera"] = "40.967773,-116.154785,129.154297,0.000088,3.600206,109.805168,30.000002,249.443985,false,DoNotOverride,2.8",
            ["Content"] = "……不，军团长。您并不了解艾米莉亚·加斯顿。",
            ["ContentKR"] = "...그렇지 않아요, 군단장님. 군단장님은 에밀리아 개스톤이 어떤 사람인지 전혀 모르시는군요.",
            ["DialogueId"] = 80180226,
            ["FinalCamera"] = "40.967773,-116.154785,129.154297,0.00009,5.800196,110.005104,30.000002,249.443985,false,DoNotOverride,2.8",
            ["GUID"] = "C8B90854",
            ["NextDialogue"] = 80180227,
            ["SpeakNpcId"] = 790045,
            ["TalkActionId"] = {
                [1] = "790045:DisagreeHead",
                },
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B90854",
            },
        [80180227] = {
            ["Camera"] = "40.967773,-116.154785,129.154297,0.00009,5.800196,110.005104,30.000002,249.443985,false,DoNotOverride,2.8",
            ["Content"] = "我和她合作过很久，艾米莉亚是一个远比我更细心谨慎的研究员。",
            ["ContentKR"] = "전 오랫동안 에밀리아와 함께 연구해 왔어요. 그 애는 저보다 훨씬 꼼꼼하고 신중한 연구원이었고요.",
            ["DialogueId"] = 80180227,
            ["GUID"] = "C8B9087E",
            ["NextDialogue"] = 80180228,
            ["SpeakNpcId"] = 790045,
            ["TalkActionId"] = {
                [1] = "790045:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B9087E",
            },
        [80180228] = {
            ["Camera"] = "543.975098,-643.192871,207.191406,0.000092,-8.199464,137.000534,30.000002,861.833862,false,Manual,1.2",
            ["Content"] = "您看到的只是艾米莉亚之死的报告书，但您不知道的是……她临死之前，满地都是血……血还在从她的身体往外流……但她没有对她的同僚说“救救我”……",
            ["ContentKR"] = "에밀리아의 사망 보고서만 읽으셨을 테니까, 모르시겠죠... 그 애는 피로 범벅이 된 바닥에서... 몸에서 피가 철철 흐르는대도... 동료들한테 살려달라고 하지 않았어요...",
            ["DialogueId"] = 80180228,
            ["FinalCamera"] = "563.548828,-622.201172,207.191406,0.000092,-8.199464,138.8004,30.000002,861.833862,false,Manual,1.2",
            ["GUID"] = "C8B908A8",
            ["NextDialogue"] = 80180229,
            ["SpeakNpcId"] = 790045,
            ["TalkActionId"] = {
                [1] = "790045:Talk02_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B908A8",
            },
        [80180229] = {
            ["Camera"] = "54.456055,-318.109375,151.507812,0.000091,-5.799561,105.601219,30.000002,319.662201,false,Manual,1.2",
            ["Content"] = "而是……不停地……对那个还在咒骂她的实验体说……“对不起”。",
            ["ContentKR"] = "오히려... 자기한테 저주를 퍼붓는 실험체에게... 계속해서 말했죠... \"미안해\"라고.",
            ["DialogueId"] = 80180229,
            ["FinalCamera"] = "49.29834,-299.633301,149.564453,0.000087,-6.199557,105.001999,30.000002,319.662201,false,Manual,1.2",
            ["GUID"] = "C8B908D2",
            ["NextDialogue"] = 80180230,
            ["SpeakNpcId"] = 790045,
            ["TalkActionId"] = {
                [1] = "790045:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B908D2",
            },
        [80180230] = {
            ["Camera"] = "49.29834,-299.633301,149.564453,0.000087,-6.199557,105.001999,30.000002,319.662201,false,Manual,1.2",
            ["Content"] = "那时我便明白，她解开实验体的拘束带，绝非因为粗心……而是无论如何，她都无法看到一个人类受苦。",
            ["ContentKR"] = "그때 깨달았어요. 에밀리아는 실수로 구속 벨트를 채우지 않았던 게 아니에요... 이유가 뭐든... 고통받는 사람을 외면할 수 없었던 거예요.",
            ["DialogueId"] = 80180230,
            ["GUID"] = "C8B908FC",
            ["NextDialogue"] = 80180231,
            ["SpeakNpcId"] = 790045,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B908FC",
            },
        [80180231] = {
            ["Camera"] = "962.483398,712.037109,2.564453,0.00009,7.400503,-144.79744,30.000002,1383.023071,false,Manual,1.2",
            ["Content"] = "换了是我，大概也会做出同样的选择。我和惨死的艾米莉亚之间，不过隔着一纸调令的距离。",
            ["ContentKR"] = "그 자리에 제가 있었다 해도 아마 같은 선택을 했을 거예요. 끔찍하게 죽은 에밀리아와 저 사이엔, 인사 발령서를 받았고 안 받았고의 차이밖에 없으니까요.",
            ["DialogueId"] = 80180231,
            ["FinalCamera"] = "964.055176,709.811035,2.564453,0.000089,7.400503,-143.597458,30.000002,1383.023071,false,Manual,1.2",
            ["GUID"] = "C8B90926",
            ["NextDialogue"] = 80180232,
            ["SpeakNpcId"] = 790045,
            ["TalkActionId"] = {
                [1] = "790045:Explain02_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B90926",
            },
        [80180232] = {
            ["Camera"] = "98.930664,135.452148,204.640625,-10.808317,-18.599213,-115.984474,30.000002,368.927856,false,Manual,1.2",
            ["Content"] = "那批实验体不过是一些社会的渣滓，我还以为艾米莉亚·加斯顿的死至少能让你长点记性。",
            ["ContentKR"] = "그 실험체들은 사회의 쓰레기나 다름없어. 에밀리아 개스톤의 죽음으로 배운 게 좀 있을 줄 알았는데, 아니었나 보네.",
            ["DialogueId"] = 80180232,
            ["FinalCamera"] = "89.845215,140.586426,202.753906,-10.808901,-18.599213,-114.383667,30.000002,368.927856,false,Manual,1.2",
            ["GUID"] = "C8B90950",
            ["NextDialogue"] = 80180233,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B90950",
            },
        [80180233] = {
            ["Camera"] = "24.695312,-121.806152,171.394531,-10.819184,-18.998465,-112.377495,30.000002,368.927856,false,DoNotOverride,1.2",
            ["Content"] = "大多数卡戎之民都是一群冷血、自私、狡猾的蛇，只要你把后背对准他们，他们就会毫不犹豫地对你的脚踝伸出毒牙。",
            ["ContentKR"] = "카론은 대부분 피도 눈물도 없고 이기적이지. 하나같이 뱀처럼 교활한 녀석들이야. 등을 보이는 순간, 주저 없이 네 발목에 독니를 박아 넣을 거다.",
            ["DialogueId"] = 80180233,
            ["FinalCamera"] = "18.752441,-119.948242,170.269531,-10.820675,-18.398371,-107.777733,30.000002,368.927856,false,DoNotOverride,1.2",
            ["GUID"] = "C8B9097A",
            ["NextDialogue"] = 80180234,
            ["SpeakNpcId"] = 790013,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B9097A",
            },
        [80180234] = {
            ["Camera"] = "18.752441,-119.948242,170.269531,-10.820675,-18.398371,-107.777733,30.000002,368.927856,false,DoNotOverride,1.2",
            ["Content"] = "当然，我也一样。我也冷血、自私而狡猾——只要你爬到更高的位置俯视我，自然也可以随意碾碎我，就像我可以轻易碾碎你一样。",
            ["ContentKR"] = "물론, 그건 나도 마찬가지야. 피도 눈물도 없고, 이기적이고, 교활하지. 네가 나보다 높은 자리에 올라간다면, 얼마든지 날 짓뭉개도록 해. 아무렇지 않게 널 밟아버릴 수 있는 나처럼 말이야.",
            ["DialogueId"] = 80180234,
            ["GUID"] = "C8B909A4",
            ["NextDialogue"] = 80180235,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B909A4",
            },
        [80180235] = {
            ["Camera"] = "274.801758,201.754395,22.921875,-0.001008,14.001088,-135.975983,30.000002,368.927856,false,DoNotOverride,1.2",
            ["Content"] = "但是现在的你没有这个资格，达芙涅。“仁慈”是强者的特权。",
            ["ContentKR"] = "하지만 다프네, 지금의 네겐 그럴 자격이 없어. '자비'는 강자의 특권이거든.",
            ["DialogueId"] = 80180235,
            ["FinalCamera"] = "274.801758,201.754395,22.921875,-0.001008,11.201038,-136.775848,30.000002,368.927856,false,DoNotOverride,1.2",
            ["GUID"] = "C8B909CE",
            ["NextDialogue"] = 80180236,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Talk01_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B909CE",
            },
        [80180236] = {
            ["Camera"] = "38.126953,-294.654297,141.544922,-0.001007,-3.199267,106.030937,35.0,300.532867,false,Manual,3.442178",
            ["Content"] = "……没错。艾米莉亚善良地给那个实验体松绑，却换来了他刺向心脏的尖刀。他们真是冷血透了，狡猾透了——",
            ["ContentKR"] = "...맞아요. 에밀리의 친절은 심장을 꿰뚫는 칼날이 되어 그 애에게 되돌아왔죠. 카론은 정말 지독하게 차갑고 교활해요...",
            ["DialogueId"] = 80180236,
            ["FinalCamera"] = "44.895996,-292.64502,141.544922,-0.001008,-3.199267,107.03141,35.0,300.532867,false,Manual,3.442178",
            ["GUID"] = "C8B909F8",
            ["NextDialogue"] = 80180237,
            ["SpeakNpcId"] = 790045,
            ["TalkActionId"] = {
                [1] = "790013:Talk01_End",
                [2] = "790045:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B909F8",
            },
        [80180237] = {
            ["Camera"] = "44.895996,-292.64502,141.544922,-0.001008,-3.199267,107.03141,35.0,300.532867,false,Manual,3.442178",
            ["Content"] = "但是，把他们变成这样的，又是谁？",
            ["ContentKR"] = "그렇지만, 카론을 그렇게 만든 건, 대체 누굴까요?",
            ["DialogueId"] = 80180237,
            ["GUID"] = "C8B90A22",
            ["NextDialogue"] = 80180238,
            ["SpeakNpcId"] = 790045,
            ["TalkActionId"] = {
                [1] = "790045:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B90A22",
            },
        [80180238] = {
            ["Camera"] = "38.929199,-70.45166,156.289062,-0.001007,-6.799528,-109.573471,30.000002,368.927856,false,DoNotOverride,1.2",
            ["Content"] = "…………",
            ["ContentKR"] = "......",
            ["DialogueId"] = 80180238,
            ["FinalCamera"] = "45.669922,-72.849121,156.289062,-0.001008,-6.799528,-112.173264,30.000002,368.927856,false,DoNotOverride,1.2",
            ["GUID"] = "C8B90A4C",
            ["NextDialogue"] = 80180239,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B90A4C",
            },
        [80180239] = {
            ["Camera"] = "384.644531,-492.653809,29.773438,-0.001008,8.000091,136.426346,35.0,300.532867,false,DoNotOverride,3.442178",
            ["Content"] = "军团长，不，师姐……我已经决定了，不会改变。",
            ["ContentKR"] = "군단장님, 아니, 선배... 전 마음을 정했고, 제 결심은 바뀌지 않을 거예요.",
            ["DialogueId"] = 80180239,
            ["FinalCamera"] = "396.825684,-480.255859,29.773438,-0.001007,8.000091,138.426254,35.0,300.532867,false,DoNotOverride,3.442178",
            ["GUID"] = "C8B90A76",
            ["NextDialogue"] = 80180240,
            ["SpeakNpcId"] = 790045,
            ["TalkActionId"] = {
                [1] = "790045:DisagreeHead",
                },
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B90A76",
            },
        [80180240] = {
            ["Camera"] = "396.825684,-480.255859,29.773438,-0.001007,8.000091,138.426254,35.0,300.532867,false,DoNotOverride,3.442178",
            ["Content"] = "“炼金术的存在是为了让人们更加幸福”——我是抱着这样的<H>理想</>才进入炼金院的。",
            ["ContentKR"] = "\"연금술은 사람들을 더 행복하게 만들어 주기 위해 존재한다\"... 전 이런 <H>이상</>을 품고 연금원에 들어간 거니까요.",
            ["DialogueId"] = 80180240,
            ["GUID"] = "C8B90AA0",
            ["NextDialogue"] = 80180241,
            ["SpeakNpcId"] = 790045,
            ["TalkActionId"] = {
                [1] = "790013:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B90AA0",
            },
        [80180241] = {
            ["Camera"] = "51.583496,-229.13623,99.591797,-0.001008,6.199721,102.229668,35.0,300.532867,false,DoNotOverride,3.442178",
            ["Content"] = "我回去了，师姐。回炼金院，接受我应得的惩罚……当然，我最后一次恳求您，如果您愿意命令炼金院生产AG-1899，所有被疼痛折磨的人都将对您感激不尽。",
            ["ContentKR"] = "이만 돌아갈게요, 선배. 연금원에 돌아가 마땅한 벌을 받아야죠... 다만, 마지막으로 간청할게요. 선배가 연금원에 AG-1899를 생산하도록 명령해 준다면, 고통에 시달리는 모든 사람들이 선배에게 깊이 감사해 할 거예요.",
            ["DialogueId"] = 80180241,
            ["FinalCamera"] = "62.180664,-226.969727,99.591797,-0.001007,6.199721,105.430244,35.0,300.532867,false,DoNotOverride,3.442178",
            ["GUID"] = "C8B90ACA",
            ["NextDialogue"] = 80180242,
            ["SpeakNpcId"] = 790045,
            ["TalkActionId"] = {
                [1] = "790045:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B90ACA",
            },
        [80180242] = {
            ["Camera"] = "38.126953,-294.654297,141.544922,-0.001007,-3.199267,106.030937,35.0,300.532867,false,Manual,3.442178",
            ["Content"] = "既然你这样坚持，我就给你几句忠告吧。",
            ["ContentKR"] = "네 뜻이 정 그렇다면, 충고 몇 마디 하지.",
            ["DialogueId"] = 80180242,
            ["FinalCamera"] = "44.895996,-292.64502,141.544922,-0.001008,-3.199267,107.03141,35.0,300.532867,false,Manual,3.442178",
            ["GUID"] = "C8B90AF4",
            ["NextDialogue"] = 80180243,
            ["SpeakNpcId"] = 790013,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B90AF4",
            },
        [80180243] = {
            ["Camera"] = "47.391602,-123.157227,200.138672,-0.001004,-26.399937,111.230003,35.0,300.532867,false,DoNotOverride,3.442178",
            ["Content"] = "你在炼金院这么久，知道太多核心机密，塞拉斯必然不会允许你想去哪儿就去哪儿。所以，现在的你有三个选择。",
            ["ContentKR"] = "넌 오랫동안 연금원에 있으면서 핵심 기밀을 너무 많이 알아 버렸어. 세라스가 널 순순히 보내주지 않을 거다. 너한텐 세 가지 선택지가 있어.",
            ["DialogueId"] = 80180243,
            ["FinalCamera"] = "55.6875,-120.101562,200.138672,-0.001007,-26.399929,114.229691,35.0,300.532867,false,DoNotOverride,3.442178",
            ["GUID"] = "C8B90B1E",
            ["NextDialogue"] = 80180244,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790045:Explain02_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B90B1E",
            },
        [80180244] = {
            ["Content"] = "（子弹上膛声）",
            ["ContentKR"] = "{空格}",
            ["DialogueId"] = 80180244,
            ["GUID"] = "C8B90B48",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 80180245,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_load\"},PlayAs2D{true}}",
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B90B48",
            },
        [80180245] = {
            ["Camera"] = "41.63623,-81.270996,178.802734,-10.80179,-16.399618,-113.192589,30.000002,125.0,false,DoNotOverride,2.8",
            ["Content"] = "第一个选择，让他们把你关进监狱或疯人院，在那儿度过你的后半生。",
            ["ContentKR"] = "첫 번째 선택지는, 감옥이나 정신병동에 처박혀, 거기서 남은 여생을 보내는 거다.",
            ["DialogueId"] = 80180245,
            ["FinalCamera"] = "48.197266,-83.916504,180.082031,-10.802736,-16.999601,-116.99115,30.000002,125.0,false,DoNotOverride,2.8",
            ["GUID"] = "C8B90B72",
            ["NextDialogue"] = 80180246,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B90B72",
            },
        [80180246] = {
            ["Camera"] = "109.578125,-199.028809,139.896484,-0.001007,2.399862,174.2034,30.000002,125.0,false,DoNotOverride,2.8",
            ["Content"] = "第二个选择，将这把枪对准脑袋，去地狱。",
            ["ContentKR"] = "두 번째 선택지는, 이 총구에 머리통을 대고 지옥에 떨어지는 거지.",
            ["DialogueId"] = 80180246,
            ["FinalCamera"] = "109.203613,-202.743164,139.896484,-0.001007,2.399862,174.2034,30.000002,125.0,false,DoNotOverride,2.8",
            ["GUID"] = "C8B90B9C",
            ["NextDialogue"] = 80180247,
            ["SpeakNpcId"] = 790013,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B90B9C",
            },
        [80180247] = {
            ["Camera"] = "38.126953,-294.654297,141.544922,-0.001007,-3.199267,106.030937,35.0,300.532867,false,Manual,3.442178",
            ["Content"] = "这两个选择我都考虑过。第三个选择是……什么？",
            ["ContentKR"] = "둘 다 생각해 봤던 거네요. 세 번째 선택지는... 뭐죠?",
            ["DialogueId"] = 80180247,
            ["FinalCamera"] = "44.895996,-292.64502,141.544922,-0.001008,-3.199267,107.03141,35.0,300.532867,false,Manual,3.442178",
            ["GUID"] = "C8B90B9D",
            ["NextDialogue"] = 80180248,
            ["SpeakNpcId"] = 790045,
            ["TalkActionId"] = {
                [1] = "790045:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B90B9D",
            },
        [80180248] = {
            ["Camera"] = "250.523438,210.553223,66.386719,-0.001007,9.000072,-133.994293,30.000002,125.0,false,DoNotOverride,2.8",
            ["Content"] = "第三个选择，向富尔维斯递交申请，去军团前线，像蝼蚁一样死去。",
            ["ContentKR"] = "세 번째 선택지는, 풀비스한테 신청서를 제출한 다음, 최전선으로 가서 벌레처럼 죽는 거다.",
            ["DialogueId"] = 80180248,
            ["FinalCamera"] = "250.523438,210.553223,66.386719,-0.001007,5.80006,-132.794342,30.000002,125.0,false,DoNotOverride,2.8",
            ["GUID"] = "C8B90B9E",
            ["NextDialogue"] = 80180249,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Talk03_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B90B9E",
            },
        [80180249] = {
            ["Camera"] = "46.905762,-84.696289,145.484375,-0.001007,-2.400326,-115.394318,30.000002,125.0,false,DoNotOverride,2.8",
            ["Content"] = "满天的流弹会击穿你的骄傲，漫长的疼痛会腐蚀你的尊严，队友一个接一个的倒下会摧毁你的意志，毫无意义的死亡会溶解你的信念。",
            ["ContentKR"] = "빗발치는 유탄이 네 교만함을 꿰뚫고, 기나긴 고통이 네 존엄을 갉아먹고, 쓰러져 가는 전우들이 네 의지를 꺾고, 무의미한 개죽음이 네 신념을 무너뜨리겠지.",
            ["DialogueId"] = 80180249,
            ["FinalCamera"] = "52.906738,-87.544922,145.484375,-0.001007,-2.400326,-118.794006,30.000002,125.0,false,DoNotOverride,2.8",
            ["GUID"] = "C8B90BC6",
            ["NextDialogue"] = 80180250,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790045:Explain02_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B90BC6",
            },
        [80180250] = {
            ["Camera"] = "37.298828,51.883789,147.867188,-0.001007,-3.200312,-109.992836,30.000002,250.348099,false,Manual,2.8",
            ["Content"] = "而如果你能侥幸存活，到那时，再过来我身边。",
            ["ContentKR"] = "그러고도 운 좋게 살아남는다면, 그때 다시 날 찾아와.",
            ["DialogueId"] = 80180250,
            ["FinalCamera"] = "44.025879,49.503418,147.867188,-0.001007,-3.200319,-113.192429,30.000002,250.348099,false,Manual,2.8",
            ["GUID"] = "C8B90BF0",
            ["NextDialogue"] = 80180251,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790045:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B90BF0",
            },
        [80180251] = {
            ["Camera"] = "972.825684,719.781738,4.660156,-0.001007,3.199554,-144.190918,30.000002,250.348099,false,Manual,2.8",
            ["Content"] = "——告诉我，<H>你的理想依旧在吗？</>",
            ["ContentKR"] = "그리고 말해. <H>네 이상이 여전히 건재한지</> 말이야.",
            ["DialogueId"] = 80180251,
            ["FinalCamera"] = "973.912109,718.088379,4.660156,-0.001007,3.399556,-143.391037,30.000002,250.348099,false,Manual,2.8",
            ["GUID"] = "C8B90C1A",
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790045:Confident_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/002/C8B90C1A",
            },
        [80180301] = {
            ["Camera"] = "269.386719,-113.140137,157.827637,0.000044,-6.800259,160.204285,30.000002,309.33728,false,Manual,1.2",
            ["Content"] = "——这就是我离开佩剑炼金院的原因。我选择成为一名医务员，这大概是我最后能为自己选择的事。",
            ["ContentKR"] = "...이게 바로 제가 소드 연금원을 떠나는 이유예요. 전 의무관이 되기로 했어요. 아마 제 자신을 위해 할 수 있는 마지막 선택이겠죠.",
            ["DialogueId"] = 80180301,
            ["FinalCamera"] = "271.535156,-107.079102,157.827637,0.000044,-6.800259,160.80426,30.000002,309.33728,false,Manual,1.2",
            ["GUID"] = "C8B914A2",
            ["NextDialogue"] = 80180302,
            ["SpeakNpcId"] = 790045,
            ["TalkActionId"] = {
                [1] = "790057:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/003/C8B914A2",
            },
        [80180302] = {
            ["Camera"] = "-121.863525,337.176758,36.699707,0.000079,9.19965,-61.996338,30.000002,309.33728,false,DoNotOverride,1.2",
            ["Content"] = "亲爱的妈妈，当您听到这份录音时，我已经在赶赴战场的路上。也许我不会回来了，很抱歉以这种方式和您道别。",
            ["ContentKR"] = "사랑하는 엄마, 이걸 들으실 때쯤이면 전 이미 전장으로 향하고 있을 거예요. 돌아오지 못할지도 몰라요. 이런 식으로 작별 인사를 드려서 죄송해요.",
            ["DialogueId"] = 80180302,
            ["FinalCamera"] = "-121.863525,337.176758,36.699707,0.000074,10.999657,-62.196552,30.000002,309.33728,false,DoNotOverride,1.2",
            ["GUID"] = "C8B914CC",
            ["NextDialogue"] = 80180303,
            ["SpeakNpcId"] = 790045,
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/003/C8B914CC",
            },
        [80180303] = {
            ["Camera"] = "-121.863525,337.176758,36.699707,0.000074,10.999657,-62.196552,30.000002,309.33728,false,DoNotOverride,1.2",
            ["Content"] = "我书桌上有一盒用于镇痛的药剂，请您代我转交给河间医院的罗杰·加斯顿先生。我在自己身上做过实验，它会有效的。",
            ["ContentKR"] = "제 책상 위에 진통제 상자가 하나 있어요. 저 대신 리버랜드 병원에 있는 로저 개스톤 씨한테 전해 주세요. 저한테 직접 실험해 봤는데, 효과가 있을 거예요.",
            ["DialogueId"] = 80180303,
            ["GUID"] = "C8B914F6",
            ["NextDialogue"] = 80180304,
            ["SpeakNpcId"] = 790045,
            ["TalkActionId"] = {
                [1] = "790057:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/003/C8B914F6",
            },
        [80180304] = {
            ["Camera"] = "79.812988,-4.779297,137.84375,0.00008,-2.80035,168.601562,30.000002,309.33728,false,DoNotOverride,1.2",
            ["Content"] = "请原谅我注定无法达成您的期许，我是全世界最糟糕的女儿，最可耻的逃兵。",
            ["ContentKR"] = "엄마가 바라던 딸이 되지 못해서 죄송해요. 전 세상에서 가장 못난 딸이고, 가장 비겁한 탈영병이에요.",
            ["DialogueId"] = 80180304,
            ["FinalCamera"] = "79.812988,-4.779297,137.84375,0.00008,2.399684,168.800461,30.000002,309.33728,false,DoNotOverride,1.2",
            ["GUID"] = "C8B91520",
            ["NextDialogue"] = 80180305,
            ["SpeakNpcId"] = 790045,
            ["TalkActionId"] = {
                [1] = "790057:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/003/C8B91520",
            },
        [80180305] = {
            ["Camera"] = "429.874512,-79.35791,282.631104,0.000086,-25.399929,174.798096,30.000002,309.33728,false,DoNotOverride,1.2",
            ["Content"] = "但我并不为我的选择感到后悔，因为我相信很多很多年后，我们会迎来一个光辉璀璨的时代。",
            ["ContentKR"] = "그래도 전 제 선택을 후회하지 않아요. 먼 훗날 언젠가, 눈부시게 빛나는 시대가 찾아와 줄 거라고 믿어요.",
            ["DialogueId"] = 80180305,
            ["FinalCamera"] = "431.295898,-62.712891,282.631104,0.000086,-25.399921,179.798019,30.000002,309.33728,false,DoNotOverride,1.2",
            ["GUID"] = "C8B9154A",
            ["NextDialogue"] = 80180306,
            ["SpeakNpcId"] = 790045,
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/003/C8B9154A",
            },
        [80180306] = {
            ["Camera"] = "431.295898,-62.712891,282.631104,0.000086,-25.399921,179.798019,30.000002,309.33728,false,DoNotOverride,1.2",
            ["Content"] = "那时，或许会有人在我的墓前向我致候，告诉我——",
            ["ContentKR"] = "그날이 오면, 누군가 제 무덤에 와서 인사를 건네며, 이렇게 말할지도 몰라요...",
            ["DialogueId"] = 80180306,
            ["GUID"] = "C8B91574",
            ["NextDialogue"] = 80180307,
            ["SpeakNpcId"] = 790045,
            ["TalkActionId"] = {
                [1] = "790057:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/003/C8B91574",
            },
        [80180307] = {
            ["Camera"] = "126.79541,-93.274414,133.225342,0.000073,-1.399772,139.192261,30.000002,309.33728,false,DoNotOverride,1.2",
            ["Content"] = "达芙涅·塞奥多尔，你做了正确的事。",
            ["ContentKR"] = "다프네 세오도어, 당신은 옳은 일을 했다고요.",
            ["DialogueId"] = 80180307,
            ["FinalCamera"] = "105.866211,-75.204102,132.549316,0.000073,-0.599752,139.192261,30.000002,309.33728,false,DoNotOverride,1.2",
            ["GUID"] = "C8B9159E",
            ["NextDialogue"] = 80180308,
            ["SpeakNpcId"] = 790045,
            ["TalkActionId"] = {
                [1] = "790057:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/003/C8B9159E",
            },
        [80180308] = {
            ["Camera"] = "105.866211,-75.204102,132.549316,0.000073,-0.599752,139.192261,30.000002,309.33728,false,DoNotOverride,1.2",
            ["Content"] = "…………",
            ["ContentKR"] = "......",
            ["DialogueId"] = 80180308,
            ["GUID"] = "C8B915C8",
            ["NextDialogue"] = 80180309,
            ["SpeakNpcId"] = 790057,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/003/C8B915C8",
            },
        [80180309] = {
            ["Camera"] = "503.694824,337.953125,141.101562,21.599174,-5.399681,-139.205948,30.000002,606.763855,false,Manual,1.2",
            ["Content"] = "阿瓦尔，看看你教出来的好女儿，简直和你一个模子刻出来的！她怎么可以——怎么可以这么愚蠢、自私又认死理！",
            ["ContentKR"] = "아바르, 딸을 아주 잘 가르치셨네! 어쩜 이렇게 쏙 빼닮았을까! 왜 그렇게 미련하고, 이기적이고, 고집불통이냐고!",
            ["DialogueId"] = 80180309,
            ["FinalCamera"] = "527.729492,358.695312,144.101807,21.599174,-5.399681,-139.205948,30.000002,606.763855,false,Manual,1.2",
            ["GUID"] = "C8B915F2",
            ["NextDialogue"] = 80180310,
            ["SpeakNpcId"] = 790057,
            ["TalkActionId"] = {
                [1] = "790057:Explain02_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/003/C8B915F2",
            },
        [80180310] = {
            ["Camera"] = "173.015625,-19.455566,210.615723,0.000005,-26.399349,169.588226,30.000002,606.763855,false,DoNotOverride,1.2",
            ["Content"] = "愚不可及！她难道不知道只要稍微认个错，服个软，或者向我求救，很多事情就会有转机吗？！",
            ["ContentKR"] = "정말 구제 불능이야! 잘못했다고 조금만 굽히고 들어가든가, 아니면 나한테 도와달라고만 했어도 상황이 달라졌을 거란 걸 왜 몰라?",
            ["DialogueId"] = 80180310,
            ["FinalCamera"] = "175.425293,-8.150879,210.615723,0.000005,-26.399342,172.787903,30.000002,606.763855,false,DoNotOverride,1.2",
            ["GUID"] = "C8B9161C",
            ["NextDialogue"] = 80180311,
            ["SpeakNpcId"] = 790057,
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/003/C8B9161C",
            },
        [80180311] = {
            ["Camera"] = "175.425293,-8.150879,210.615723,0.000005,-26.399342,172.787903,30.000002,606.763855,false,DoNotOverride,1.2",
            ["Content"] = "…………",
            ["ContentKR"] = "......",
            ["DialogueId"] = 80180311,
            ["GUID"] = "C8B91646",
            ["NextDialogue"] = 80180312,
            ["SpeakNpcId"] = 790057,
            ["TalkActionId"] = {
                [1] = "790057:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/003/C8B91646",
            },
        [80180312] = {
            ["Camera"] = "-121.863525,337.176758,36.699707,0.000079,9.19965,-61.996338,30.000002,309.33728,false,DoNotOverride,1.2",
            ["Content"] = "……但……我记得……",
            ["ContentKR"] = "그런데... 기억나...",
            ["DialogueId"] = 80180312,
            ["FinalCamera"] = "-121.863525,337.176758,36.699707,0.000074,10.999657,-62.196552,30.000002,309.33728,false,DoNotOverride,1.2",
            ["GUID"] = "C8B91670",
            ["NextDialogue"] = 80180313,
            ["SpeakNpcId"] = 790057,
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/003/C8B91670",
            },
        [80180313] = {
            ["Camera"] = "-121.863525,337.176758,36.699707,0.000074,10.999657,-62.196552,30.000002,309.33728,false,DoNotOverride,1.2",
            ["Content"] = "……也正是这份天真和愚蠢，让当年的我选择了你。说到底，真正的蠢人是我才对。",
            ["ContentKR"] = "...나도 당신의 그 미련할 정도의 순진함에 반한 거였지. 따지고 보면, 진짜 바보는 나였네.",
            ["DialogueId"] = 80180313,
            ["GUID"] = "C8B9169A",
            ["NextDialogue"] = 80180314,
            ["SpeakNpcId"] = 790057,
            ["TalkActionId"] = {
                [1] = "790057:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/003/C8B9169A",
            },
        [80180314] = {
            ["Content"] = "你们两个……一定要……活着回来。",
            ["ContentKR"] = "여보, 우리 딸... 둘 다... 꼭 살아 돌아와 줘.",
            ["DialogueId"] = 80180314,
            ["GUID"] = "C8B916C4",
            ["IsBlack"] = 1,
            ["SpeakNpcId"] = 790057,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/003/C8B916C4",
            },
        [80180315] = {
            ["Camera"] = "6.101562,-49.640625,124.166504,0.000013,8.197476,156.384064,30.000002,125.0,false,DoNotOverride,2.8",
            ["Content"] = "太好了，你在这儿！走，跟我——",
            ["ContentKR"] = "다행이에요! 여기 있었군요! 자, 어서 같이...",
            ["DialogueId"] = 80180315,
            ["FinalCamera"] = "8.539062,-43.953125,124.166504,0.000013,8.19747,159.784409,30.000002,125.0,false,DoNotOverride,2.8",
