        [80200217] = {
            ["Content"] = "那是……扶疏？",
            ["ContentKR"] = "저 사람은... 부소?",
            ["DialogueId"] = 80200217,
            ["FacialId"] = {
                [1] = "790008:Shock01",
                },
            ["GUID"] = "C8C5D1DE",
            ["LookAt"] = {
                [1] = "790008:n(790054)",
                },
            ["NextDialogue"] = 80200218,
            ["Scripts"] = "PlayAnimation{_delay{1.01},ActorId{790008},AnimationId{\"Talk03_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D1DE",
            },
        [80200218] = {
            ["Camera"] = "-84.304626,35.644173,65.415039,0.000002,2.396269,78.78582,35.0,107.243362,false,DoNotOverride,2.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "麻烦。麻烦。麻烦。麻烦！",
            ["ContentKR"] = "귀찮아, 진짜 귀찮아, 귀찮아 죽겠어!",
            ["DialogueId"] = 80200218,
            ["FacialId"] = {
                [1] = "790054:Angry01",
                },
            ["FinalCamera"] = "-66.061569,127.614021,68.84082,0.000002,1.396248,78.785858,35.0,107.243362,false,DoNotOverride,2.8",
            ["GUID"] = "C8C5D208",
            ["NextDialogue"] = 80200219,
            ["SpeakNpcId"] = 790054,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["TalkActionId"] = {
                [1] = "790054:Angry01_Start",
                },
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D208",
            },
        [80200219] = {
            ["Content"] = "唉，早上起来的时候，还再三告诫自己别去惹她别去惹她，怎么早饭还没吃完，就破戒了！",
            ["ContentKR"] = "으, 아침에 일어날 때만 해도, 오늘은 절대 걔 속 긁지 말자고 그렇게 다짐했잖아. 어떻게 아침도 다 먹기 전에 그걸 못 참니!",
            ["DialogueId"] = 80200219,
            ["GUID"] = "C8C5D232",
            ["NextDialogue"] = 80200220,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{3.01},ActorId{790054},AnimationId{\"Sigh_Start\"},Duration{1}},\
PlayAnimation{_delay{7.01},ActorId{790054},AnimationId{\"Sigh_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 790054,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["TalkActionId"] = {
                [1] = "790054:Angry01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D232",
            },
        [80200220] = {
            ["Camera"] = "-2343.795166,1023.041992,114.227539,0.000092,-0.803982,-4.996912,35.0,2401.962891,false,Manual,2.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "扶风啊扶风！你怎能如此沉不住气呢！那小妮子脾气再臭，也是你亲妹子！你又不可能扔下她不管，干嘛总是气她呢！",
            ["ContentKR"] = "부풍아, 내가 진짜 못 살아! 넌 대체 왜 이렇게 참을성이 없는 거야! 성격이 아무리 나빠도, 걔는 네 친동생이잖아! 어차피 챙겨 줄 거면서, 왜 자꾸 걜 화나게 만드는 건데!",
            ["DialogueId"] = 80200220,
            ["FinalCamera"] = "-2335.671875,1115.896973,114.227539,0.000092,-0.803982,-4.997154,35.0,2401.962891,false,Manual,2.8",
            ["GUID"] = "C8C5D25C",
            ["NextDialogue"] = 80200221,
            ["Scripts"] = "PARA{\
TurnTo{_delay{1.01},TurnToDescription{\"790054:p(90))\"}},\
PlayAnimation{_delay{3.01},ActorId{790054},AnimationId{\"Talk03_Start\"},Duration{1}},\
PlayAnimation{_delay{9.01},ActorId{790054},AnimationId{\"Talk03_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 790054,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["TalkActionId"] = {
                [1] = "790008:Talk03_End",
                },
            ["ToFinalCameraBlendTime"] = 30,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D25C",
            },
        [80200221] = {
            ["Camera"] = "76.413086,1077.357422,133.182617,0.000061,0.986498,-55.45702,40.000011,61.390137,false,Manual,9.159348",
            ["Content"] = "没办法啊没办法，扶疏那一本正经的样子，实在是很好气……笑容没有消失，只是从扶疏妹妹的脸上，移到了我的脸上……",
            ["ContentKR"] = "나도 어쩔 수가 없어. 부소가 그렇게 정색하고 있으면, 엄청 약 올리고 싶은걸... 걔한테서 웃음이 사라진 게 아니라, 나한테 옮겨 온 거라니까...",
            ["DialogueId"] = 80200221,
            ["FacialId"] = {
                [1] = "790054:Sad01",
                },
            ["GUID"] = "C8C5D286",
            ["NextDialogue"] = 80200222,
            ["Scripts"] = "PARA{\
SetLocation{ActorId{790008},TargetPoint{\"BP_200301b_fushu01\"},Visibility{\"Show\"}},\
PlayAnimation{_delay{3.01},ActorId{790054},AnimationId{\"Angry01_End\"},Duration{1}},\
PlayAnimation{_delay{7.01},ActorId{790054},AnimationId{\"Think_Start\"},Duration{1}},\
PlayFacial{_delay{8.01},ActorId{790054},FacialId{\"Smile02\"}}\
}",
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D286",
            },
        [80200222] = {
            ["Camera"] = "76.413086,1077.357422,133.182617,0.000061,0.986498,-55.45702,40.000011,61.390137,false,Manual,9.159348",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "人之常情，人之常情嘛！",
            ["ContentKR"] = "당연한 거 아냐? 다들 나랑 똑같이 생각할걸!",
            ["DialogueId"] = 80200222,
            ["FinalCamera"] = "108.321411,1110.508301,147.339844,0.000063,-8.613893,-93.255981,40.0,218.69223,false,Manual,11.861392",
            ["GUID"] = "C8C5D2B0",
            ["NextDialogue"] = 80200223,
            ["Scripts"] = "MoveTo{ActorId{790008},TargetPoint{\"BP_200301b_nvzhu01\"},MoveSpeed{100},Visibility{\"Show\"}}",
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:Think_End",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D2B0",
            },
        [80200223] = {
            ["Content"] = "扶、扶疏？是你吗？",
            ["ContentKR"] = "부, 부소? 너 맞아?",
            ["DialogueId"] = 80200223,
            ["Duration"] = 1,
            ["GUID"] = "C8C5D2DA",
            ["LookAt"] = {
                [1] = "790008:n(790054)",
                [2] = "790054:n(790008)",
                },
            ["NextDialogue"] = 80200224,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D2DA",
            },
        [80200224] = {
            ["Camera"] = "-5.917664,812.056946,114.511719,0.000043,2.986077,54.542389,35.000015,234.030762,false,Manual,3.823875",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "不是哦。我是扶疏的双胞胎姐姐，扶风。将我俩弄混的人，你不是第一个。",
            ["ContentKR"] = "아니, 난 걔 쌍둥이 언니 부풍이야. 다들 우리 둘을 헷갈리더라. 너만 그런 게 아니야.",
            ["DialogueId"] = 80200224,
            ["FacialId"] = {
                [1] = "790008:None",
                [2] = "790054:None",
                },
            ["FinalCamera"] = "-19.185059,822.114929,114.511719,0.000044,2.786068,50.5424,35.000015,234.030762,false,Manual,3.823875",
            ["GUID"] = "C8C5D304",
            ["NextDialogue"] = 80200225,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{3.01},ActorId{790054},AnimationId{\"Confident_Start\"},Duration{1}},\
PlayAnimation{_delay{6.01},ActorId{790054},AnimationId{\"Confident_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:DisagreeHead",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D304",
            },
        [80200225] = {
            ["Content"] = "你找扶疏？怪了，她素来不和人来往，是个小闷葫芦，原来也有熟人？",
            ["ContentKR"] = "부소한테 볼일 있어? 이상하네, 걘 원래 남이랑 잘 안 어울리는 앤데. 그 답답이가 아는 사람도 있었네?",
            ["DialogueId"] = 80200225,
            ["GUID"] = "C8C5D32E",
            ["NextOptions"] = {
                [1] = 802002251,
                [2] = 802002252,
                [3] = 802002253,
                },
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{3.01},ActorId{790054},AnimationId{\"Talk01_End\"},Duration{1}},\
PlayAnimation{_delay{3.01},ActorId{790054},AnimationId{\"DisagreeHead\"},Duration{1}},\
PlayAnimation{_delay{6.01},ActorId{790054},AnimationId{\"Talk03_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D32E",
            },
        [80200226] = {
            ["Content"] = "哇……你这个年纪的人，竟不觉得她闷，还这样夸奖她，不错不错，扶疏的朋友，就是我扶风的朋友！",
            ["ContentKR"] = "와... 어린 친구 같은데 걔를 답답이가 아니라 좋은 애라고 칭찬하다니. 좋아, 나쁘지 않네. 부소랑 친구면, 나하고도 친구지!",
            ["DialogueId"] = 80200226,
            ["FacialId"] = {
                [1] = "790054:Smile01",
                },
            ["GUID"] = "C8C5D382",
            ["NextDialogue"] = 80200229,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{3.01},ActorId{790054},AnimationId{\"Confident_Start\"},Duration{1}},\
PlayAnimation{_delay{5.01},ActorId{790054},AnimationId{\"Confident_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D382",
            },
        [80200227] = {
            ["Content"] = "讹钱讹到我枯荣阁来了？！你去这十里八乡问问，这小闷葫芦的肚子里连点铜钱响都听不到，你要诬赖人，好歹也诬赖给我吧！",
            ["ContentKR"] = "우리 고영각에 돈을 뜯으러 왔다고?! 동네 사람들한테 물어봐, 우리 답답이 주머니에 땡전 한 푼 있나. 덤터기 씌우려면 상대를 잘못 골랐어. 부소가 아니라 나한테 씌웠어야지!",
            ["DialogueId"] = 80200227,
            ["FacialId"] = {
                [1] = "790054:Angry01",
                },
            ["GUID"] = "C8C5D3D6",
            ["NextDialogue"] = 80200229,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{3.01},ActorId{790054},AnimationId{\"Angry01_Start\"},Duration{1}},\
PlayAnimation{_delay{8.01},ActorId{790054},AnimationId{\"Angry01_End\"},Duration{1}},\
PlayAnimation{_delay{8.5},ActorId{790054},AnimationId{\"Talk02_Start\"},Duration{1}},\
PlayAnimation{_delay{10},ActorId{790054},AnimationId{\"Talk02_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D3D6",
            },
        [80200228] = {
            ["Content"] = "噫，油嘴滑舌，要是没病没痛就回家自己玩儿吧，乖。",
            ["ContentKR"] = "와, 입에 침이나 바르고 그런 소리 해. 어디 아픈 거 아니면 얼른 집에 가서 놀아. 착하지?",
            ["DialogueId"] = 80200228,
            ["GUID"] = "C8C5D42A",
            ["NextDialogue"] = 80200229,
            ["Scripts"] = "PlayAnimation{_delay{4.01},ActorId{790054},AnimationId{\"DisagreeHead\"},Duration{1}}",
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D42A",
            },
        [80200229] = {
            ["Camera"] = "-30.235046,1285.589722,155.125977,0.000064,-7.212188,-68.241211,35.000019,393.319,false,Manual,3.482719",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "所以，你造访枯荣阁所为何事？",
            ["ContentKR"] = "그래서, 고영각엔 무슨 일로 온 거야?",
            ["DialogueId"] = 80200229,
            ["FacialId"] = {
                [1] = "790054:None",
                },
            ["FinalCamera"] = "31.76886,1303.230225,155.125977,0.00006,-7.012207,-79.441032,35.000019,393.319,false,Manual,3.482719",
            ["GUID"] = "C8C5D454",
            ["NextDialogue"] = 80200230,
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D454",
            },
        [80200230] = {
            ["Content"] = "我误食了音容草，头脑发昏，还看见奇奇怪怪的东西，我想扶疏一定能治，就寻医问药来了。",
            ["ContentKR"] = "잘못해서 음용초를 먹는 바람에, 머리도 어지럽고 이상한 게 보여요. 부소라면 낫게 해 줄 것 같아서 찾아온 거예요.",
            ["DialogueId"] = 80200230,
            ["FacialId"] = {
                [1] = "790008:Sad03",
                },
            ["GUID"] = "C8C5D47E",
            ["NextDialogue"] = 80200231,
            ["Scripts"] = "PlayAnimation{_delay{7.01},ActorId{790008},AnimationId{\"Explain02_End\"},Duration{1}}\
",
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D47E",
            },
        [80200231] = {
            ["Camera"] = "-1451.951172,1624.570801,804.917969,0.000134,-23.215143,-28.063692,35.000019,2117.26001,false,Manual,1.2",
            ["Content"] = "你来得不巧，扶疏正生着闷气呢，还是别在这时候打扰她了。不过我是一名医师，让我看病也是一样的。",
            ["ContentKR"] = "운이 없구나. 부소는 지금 단단히 토라져 있으니까, 이럴 땐 안 건드리는 게 좋아. 아쉬운 대로 내가 봐 줄게. 나도 의사거든.",
            ["DialogueId"] = 80200231,
            ["FinalCamera"] = "-1614.322998,1711.163574,883.839844,0.000134,-23.215143,-28.063692,35.000015,2117.26001,false,Manual,1.2",
            ["GUID"] = "C8C5D4A8",
            ["NextDialogue"] = 80200232,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{5.01},ActorId{790054},AnimationId{\"Think_End\"},Duration{1}},\
TurnTo{_delay{5.8},TurnToDescription{\"790054:n(790008)\"}},\
PlayAnimation{_delay{7.01},ActorId{790054},AnimationId{\"Confident_Start\"},Duration{1}},\
PlayAnimation{_delay{9.01},ActorId{790054},AnimationId{\"Confident_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D4A8",
            },
        [80200232] = {
            ["Camera"] = "-253.072449,961.222961,89.996094,0.000045,3.386319,-1.453428,35.000015,323.748901,false,Manual,3.482719",
            ["Content"] = "让我仔细看看……",
            ["ContentKR"] = "어디 좀 보자...",
            ["DialogueId"] = 80200232,
            ["FinalCamera"] = "-253.819214,931.512756,89.996094,0.000045,3.186317,-1.253389,35.000015,323.748901,false,Manual,3.482719",
            ["GUID"] = "C8C5D4D2",
            ["NextDialogue"] = 80200233,
            ["Scripts"] = "MoveTo{ActorId{790054},TargetPoint{\"BP_200301b_fushu03\"},MoveSpeed{80},Visibility{\"Show\"}}",
            ["SpeakNpcId"] = 790054,
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D4D2",
            },
        [80200233] = {
            ["Content"] = "嗯……步履还算稳健，双目也有焦点，口齿利索，舌头不打架，误食的量应该不大。大约是半片左右？",
            ["ContentKR"] = "음... 걷는 건 멀쩡하고, 눈이랑 혀도 안 풀렸고, 말도 똑바로 잘하는 걸 보니까 많이 먹진 않았나 보네. 대충 잎사귀 반 개 정도?",
            ["DialogueId"] = 80200233,
            ["GUID"] = "C8C5D4FC",
            ["NextDialogue"] = 80200234,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{3.01},ActorId{790054},AnimationId{\"Think_Start\"},Duration{1}},\
PlayAnimation{_delay{7.01},ActorId{790054},AnimationId{\"Think_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D4FC",
            },
        [80200234] = {
            ["Content"] = "你症状不重，没等解药熬完，就全好了。再耐心等等吧，很快就会清醒的，别怕。",
            ["ContentKR"] = "별로 심각하진 않아. 해독제 달이기도 전에 다 나을걸. 겁먹지 말고, 조금만 더 참고 기다려 봐. 금방 괜찮아질 거야.",
            ["DialogueId"] = 80200234,
            ["FacialId"] = {
                [1] = "790054:Smile01",
                },
            ["GUID"] = "C8C5D526",
            ["NextDialogue"] = 80200235,
            ["Scripts"] = "PlayAnimation{_delay{7.01},ActorId{790054},AnimationId{\"Talk01_End\"},Duration{1}}",
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D526",
            },
        [80200235] = {
            ["Camera"] = "24.030762,840.372314,98.698242,0.000059,12.985261,58.542137,35.000023,135.488754,false,Manual,8.071544",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "要是实在难受，我随身带了些橘枳丸，你嚼两个，会好些。",
            ["ContentKR"] = "정 못 견디겠으면, 내가 가지고 다니는 탱자환이 있는데, 두어 개 씹어 먹으면 좀 나아질 거야.",
            ["DialogueId"] = 80200235,
            ["FinalCamera"] = "14.792786,846.531738,98.698242,0.000066,12.985261,54.742638,35.000023,135.488754,false,Manual,8.071544",
            ["GUID"] = "C8C5D550",
            ["NextDialogue"] = 80200236,
            ["SpeakNpcId"] = 790054,
            ["ToFinalCameraBlendTime"] = 20,
            ["TurnTo"] = {
                [1] = "790054:p(-30)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D550",
            },
        [80200236] = {
            ["Content"] = "我猜，你还有少眠多梦的毛病，于是你想去找怀梦草医治，但却不小心误食了极其类似的音容草。",
            ["ContentKR"] = "평소에 잠도 잘 못 자고, 꿈도 많이 꾸는 편이지? 그래서 회몽초로 낫게 해 보려다가, 거의 똑같이 생긴 음용초를 먹어 버린 모양이네.",
            ["DialogueId"] = 80200236,
            ["FacialId"] = {
                [1] = "790054:Angry01",
                },
            ["GUID"] = "C8C5D57A",
            ["LookAt"] = {
                [1] = "790054:n(790054)",
                },
            ["NextDialogue"] = 80200237,
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D57A",
            },
        [80200237] = {
            ["Content"] = "不过想治这个毛病，还是匍地枝与隙中花一同煎来服下更合适，怀梦草虽能助眠，但会在梦中看到难以忘怀之事，徒惹伤怀。",
            ["ContentKR"] = "사실 네 증상엔 땅의 가지랑 틈새의 꽃을 같이 달여 먹는 게 훨씬 효과가 좋아. 회몽초는 잠은 잘 오게 해 주지만, 대신 가슴에 묻지 못한 일들을 꿈에서 보게 되니까, 괜히 마음만 상하거든.",
            ["DialogueId"] = 80200237,
            ["GUID"] = "C8C5D5A4",
            ["LookAt"] = {
                [1] = "790054:n(790008)",
                },
            ["NextDialogue"] = 80200238,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{3.01},ActorId{790054},AnimationId{\"Talk02_Start\"},Duration{1}},\
PlayAnimation{_delay{7.01},ActorId{790054},AnimationId{\"Talk02_End\"},Duration{1}},\
PlayAnimation{_delay{10.01},ActorId{790054},AnimationId{\"DisagreeHead\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D5A4",
            },
        [80200238] = {
            ["Camera"] = "60.828491,978.365967,136.150391,0.000078,-7.614254,-76.449127,35.0,78.697502,false,Manual,8.071544",
            ["Content"] = "……不提外貌，你和扶疏确实相像。",
            ["ContentKR"] = "...생김새 말고도, 부소랑 정말 많이 닮았네요.",
            ["DialogueId"] = 80200238,
            ["FacialId"] = {
                [1] = "790008:Smile01",
                },
            ["GUID"] = "C8C5D5CE",
            ["NextDialogue"] = 80200239,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Laugh01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D5CE",
            },
        [80200239] = {
            ["Camera"] = "41.295807,880.312378,133.982422,0.00011,0.385721,62.549858,35.000011,88.438805,false,Manual,8.071544",
            ["Content"] = "这话倒是鲜少听到，我和扶疏虽是双生胎，但都说我性格跳脱，颇有“离经叛道”的嫌疑，与大风九章第九条很不相宜。",
            ["ContentKR"] = "그런 말은 처음 듣네. 나랑 부소는 쌍둥이지만, 다들 난 '정도를 벗어난' 인간 같다고 하던데. 대풍구장 아홉 번째 규율에 전혀 안 맞다면서 말이야.",
            ["DialogueId"] = 80200239,
            ["FacialId"] = {
                [1] = "790054:Smile01",
                },
            ["GUID"] = "C8C5D5F8",
            ["NextDialogue"] = 80200240,
            ["SpeakNpcId"] = 790054,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D5F8",
            },
        [80200240] = {
            ["Camera"] = "60.828491,978.365967,136.150391,0.000078,-7.614254,-76.449127,35.0,78.697502,false,Manual,8.071544",
            ["Content"] = "扶疏瞧着冷淡疏离，你瞧着风风火火，但只要涉及问诊的时候，那份一本正经，温和耐心简直如出一辙。",
            ["ContentKR"] = "부소는 차가워 보이고, 그쪽은 활발해 보이지만, 환자를 대하는 태도는 똑같아요. 진지하면서도 상냥하고, 참을성 있죠.",
            ["DialogueId"] = 80200240,
            ["FacialId"] = {
                [1] = "790008:Shy",
                },
            ["GUID"] = "C8C5D622",
            ["NextDialogue"] = 80200241,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Laugh01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D622",
            },
        [80200241] = {
            ["Camera"] = "41.295807,880.312378,133.982422,0.00011,0.385721,62.549858,35.000011,88.438805,false,Manual,8.071544",
            ["Content"] = "你这人……现在我相信你和扶疏很熟了。",
            ["ContentKR"] = "너... 부소랑 친하다고 했던 거 믿어 줄게.",
            ["DialogueId"] = 80200241,
            ["FacialId"] = {
                [1] = "790054:None",
                },
            ["GUID"] = "C8C5D64C",
            ["NextDialogue"] = 80200242,
            ["SpeakNpcId"] = 790054,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D64C",
            },
        [80200242] = {
            ["Camera"] = "-225.803223,724.690369,-5.095703,0.00006,18.385708,34.549988,35.000015,390.386017,false,Manual,3.482719",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "那孩子性格执拗，许多话憋在心里不肯说，一张嘴也不怎么灵巧，有时明明是这个意思，说出来却离题万里。",
            ["ContentKR"] = "걔가 좀 꽉 막혔잖아. 하고 싶은 말은 속에 담아 두기만 하고, 말주변도 별로라 속마음을 제대로 표현하질 못해.",
            ["DialogueId"] = 80200242,
            ["FinalCamera"] = "-314.394165,663.687378,-40.84668,0.000058,18.385708,34.550003,35.000015,390.386017,false,Manual,3.482719",
            ["GUID"] = "C8C5D676",
            ["NextDialogue"] = 80200243,
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D676",
            },
        [80200243] = {
            ["Camera"] = "60.795898,983.703857,142.798828,0.000097,-11.615378,-75.852562,35.000019,86.947418,false,Manual,4.75455",
            ["Content"] = "大概……只有你这样细心的人才能和她玩到一起吧！",
            ["ContentKR"] = "아무래도... 너처럼 속 깊은 사람이라야 걔 친구 노릇을 해 줄 수 있나 보네!",
            ["DialogueId"] = 80200243,
            ["GUID"] = "C8C5D6A0",
            ["NextDialogue"] = 80200244,
            ["SpeakNpcId"] = 790054,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D6A0",
            },
        [80200244] = {
            ["Camera"] = "41.295807,880.312378,133.982422,0.00011,0.385721,62.549858,35.000011,88.438805,false,Manual,8.071544",
            ["Content"] = "我这个做姐姐的惯爱嘴欠，先甘拜下风啦。",
            ["ContentKR"] = "말로 사람 속 긁는 건 내 전문인데, 내가 졌다.",
            ["DialogueId"] = 80200244,
            ["FacialId"] = {
                [1] = "790054:Smile01",
                },
            ["GUID"] = "C8C5D6CA",
            ["NextDialogue"] = 80200245,
            ["SpeakNpcId"] = 790054,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D6CA",
            },
        [80200245] = {
            ["Camera"] = "-1451.951172,1624.570801,804.917969,0.000134,-23.215143,-28.063692,35.000019,2117.26001,false,Manual,1.2",
            ["Content"] = "那么，扶疏的熟人！姐姐有件事情拜托，看在扶疏的面子上，你一定会答应我的吧！",
            ["ContentKR"] = "자, 부소의 친구 씨! 이 {性别:누나|언니}가 부탁 하나만 할게. 내 동생을 봐서라도, 당연히 들어 줄 거지?",
            ["DialogueId"] = 80200245,
            ["FinalCamera"] = "-1614.322998,1711.163574,883.839844,0.000134,-23.215143,-28.063692,35.000015,2117.26001,false,Manual,1.2",
            ["GUID"] = "C8C5D6F4",
            ["NextDialogue"] = 80200246,
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:Talk03_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D6F4",
            },
        [80200246] = {
            ["Content"] = "愿闻其详。",
            ["ContentKR"] = "뭔지 들어 보고요.",
            ["DialogueId"] = 80200246,
            ["GUID"] = "C8C5D71E",
            ["NextDialogue"] = 80200247,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D71E",
            },
        [80200247] = {
            ["Camera"] = "-272.939331,626.305969,174.68457,0.000111,-7.414948,45.139679,35.000015,466.027344,false,Manual,1.2",
            ["Content"] = "可不可以帮我找一下送给扶疏的道歉礼物？",
            ["ContentKR"] = "부소한테 줄 화해의 선물을 하나 찾아다 줄래?",
            ["DialogueId"] = 80200247,
            ["GUID"] = "C8C5D748",
            ["NextDialogue"] = 80200248,
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790008:Confident_Start",
                [2] = "790054:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D748",
            },
        [80200248] = {
            ["Camera"] = "-272.939331,626.305969,174.68457,0.000111,-7.414948,45.139679,35.000015,466.027344,false,Manual,1.2",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "离这里不远的水域中，常有寿星乌贼出没，帮我钓些来，不难的吧！",
            ["ContentKR"] = "이 근처에 있는 물가에 수성 오징어가 자주 나타나거든. 나 대신 몇 마리만 낚아 와 줘. 별로 안 어렵지!",
            ["DialogueId"] = 80200248,
            ["FinalCamera"] = "-248.974243,678.924866,174.214844,0.000118,0.185153,65.936897,35.000019,4716.592773,false,Manual,1.2",
            ["GUID"] = "C8C5D772",
            ["Scripts"] = "PlayAnimation{_delay{1.01},ActorId{790054},AnimationId{\"Talk03_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:Talk02_End",
                },
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D772",
            },
        [80200301] = {
            ["Camera"] = "-979.67981,-2224.893066,758.677734,0.000011,-14.599727,63.197662,30.000002,2650.537109,false,Manual,1.2",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "哇……真的钓到了，好厉害。全能如我，坐在那里一天也未必能钓上来一条……",
            ["ContentKR"] = "와... 진짜 낚았구나, 대단해. 나 같은 만능 천재도 하루 종일 앉아 있어야 한 마리 낚을까 말까인데...",
            ["DialogueId"] = 80200301,
            ["Duration"] = 1,
            ["FinalCamera"] = "-1096.155396,-2166.05835,758.677734,0.000011,-14.599727,63.197662,30.000002,2650.537109,false,Manual,1.2",
            ["GUID"] = "C8C5E5E2",
            ["NextDialogue"] = 80200302,
            ["Scripts"] = "PARA{\
MoveTo{ActorId{790008},TargetPoint{\"BP_200401a_nvzhu01\"},MoveSpeed{90},Visibility{\"Show\"}},\
PlayAnimation{_delay{2.1},ActorId{790054},AnimationId{\"Explain01_Start\"},Duration{1}},\
PlayAnimation{_delay{6.1},ActorId{790054},AnimationId{\"Explain01_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 790054,
            ["ToFinalCameraBlendTime"] = 25,
            ["TurnTo"] = {
                [1] = "790054:n(790008)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5E5E2",
            },
        [80200302] = {
            ["Camera"] = "0.420166,-219.716721,163.364258,0.000018,-7.399601,85.99836,45.0,289.463654,false,Manual,6.00204",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "并非全能。",
            ["ContentKR"] = "만능 천재는 아닌 걸로 아는데요.",
            ["DialogueId"] = 80200302,
            ["FacialId"] = {
                [1] = "790008:Smile01",
                },
            ["FinalCamera"] = "-18.45842,-218.633926,160.760742,0.000016,-6.999639,81.997551,45.0,289.463654,false,Manual,6.00204",
            ["GUID"] = "C8C5E60C",
            ["NextDialogue"] = 80200303,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Laugh01_Start",
                },
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5E60C",
            },
        [80200303] = {
            ["Content"] = "扶疏给我看过你的画，很抽象。",
            ["ContentKR"] = "부소가 부풍 씨 그림을 보여 준 적 있어요. 꽤 난해하던데요.",
            ["DialogueId"] = 80200303,
            ["Duration"] = 3,
            ["FacialId"] = {
                [1] = "790008:Smile02",
                },
            ["GUID"] = "C8C5E636",
            ["LookAt"] = {
                [1] = "790008:n(790054)",
                },
            ["NextDialogue"] = 80200304,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Laugh01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5E636",
            },
        [80200304] = {
            ["Camera"] = "-212.935883,315.686401,125.688477,0.000042,-0.800628,-54.792068,40.0,423.583282,false,Manual,6.00204",
            ["Content"] = "……你们是不是有点太熟了，她怎么把此等家丑也告诉你？",
            ["ContentKR"] = "...둘이 그렇게 친했어? 우리 집안 망신거리까지 알려 주면 어떡해?",
            ["DialogueId"] = 80200304,
            ["FinalCamera"] = "-271.671875,398.944336,125.233398,0.000042,-0.800628,-54.792068,40.0,423.583282,false,Manual,6.00204",
            ["GUID"] = "C8C5E660",
            ["NextDialogue"] = 80200305,
            ["Scripts"] = "PlayAnimation{_delay{3.1},ActorId{790054},AnimationId{\"DisagreeHead\"},Duration{1}}",
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 25,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5E660",
            },
        [80200305] = {
            ["Content"] = "咳……但我从来不知道扶疏喜欢寿星乌贼。",
            ["ContentKR"] = "크흠... 그런데 부소가 수성 오징어를 좋아한다는 건 진짜 몰랐어요.",
            ["DialogueId"] = 80200305,
            ["GUID"] = "C8C5E68A",
            ["LookAt"] = {
                [1] = "790054:n(790054)",
                },
            ["NextDialogue"] = 80200306,
            ["Scripts"] = "PlayAnimation{_delay{1.1},ActorId{790054},AnimationId{\"Confident_End\"},Duration{1}}",
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Explain01L_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5E68A",
            },
        [80200306] = {
            ["Content"] = "并非喜欢。",
            ["ContentKR"] = "걔 그거 안 좋아해.",
            ["DialogueId"] = 80200306,
            ["GUID"] = "C8C5E6B4",
            ["NextDialogue"] = 80200307,
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790008:Explain01L_End",
                },
            ["TurnTo"] = {
                [1] = "790054:p(70)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5E6B4",
            },
        [80200307] = {
            ["Content"] = "扶疏最讨厌寿星乌贼，小时候被吓哭过呢！",
            ["ContentKR"] = "부소가 제일 싫어하는 게 수성 오징어야. 어렸을 땐 그거 보고 놀라서 운 적도 있어!",
            ["DialogueId"] = 80200307,
            ["FacialId"] = {
                [1] = "790054:Smile02",
                },
            ["GUID"] = "C8C5E6DE",
            ["LookAt"] = {
                [1] = "790054:n(790008)",
                },
            ["NextOptions"] = {
                [1] = 802003071,
                [2] = 802003072,
                [3] = 802003073,
                },
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5E6DE",
            },
        [80200311] = {
            ["Camera"] = "-1.582031,-202.988312,154.458984,0.000054,-4.600522,86.210663,50.000008,127.993942,false,Manual,11.517033",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "其实我最近已经和她吵架好几次了，你应该知道我们吵架的缘由吧？",
            ["ContentKR"] = "사실 요즘 걔랑 좀 싸웠거든. 왜 싸웠는지는 대충 알지?",
            ["DialogueId"] = 80200311,
            ["FacialId"] = {
                [1] = "790008:Beg",
                [2] = "790054:Sad01",
                },
            ["FinalCamera"] = "-4.151443,-241.749527,157.583984,0.000054,-4.600494,86.210938,50.000008,320.172394,false,Manual,6.00204",
            ["GUID"] = "C8C5E786",
            ["LookAt"] = {
                [1] = "790054:n(790054)",
                },
            ["NextDialogue"] = 80200312,
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:Angry01_End",
                [2] = "790008:Shy03_Start",
                },
            ["ToFinalCameraBlendTime"] = 25,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5E786",
            },
        [80200312] = {
            ["Content"] = "无非就是我想要钻研新的治病救人的办法，而她认为要坚守枯荣之术。",
            ["ContentKR"] = "매번 똑같아. 난 환자를 치료할 수 있는 새로운 방법을 연구하고 싶은데, 걔는 고영법을 고수해야 한다고 생각하거든.",
            ["DialogueId"] = 80200312,
            ["Duration"] = 1,
            ["GUID"] = "C8C5E7B0",
            ["NextDialogue"] = 80200313,
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5E7B0",
            },
        [80200313] = {
            ["Camera"] = "-96.161865,159.932739,99.22168,0.000047,7.599357,-58.392002,40.0,273.733917,false,Manual,6.00204",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "老实说，她有她的道理，我的方法一是前途未卜，不知成效，二是背离了大风九章……",
            ["ContentKR"] = "솔직히 말해서, 걔 말도 일리는 있어. 내 방법은 성공할지 못 할지도 불확실한 데다가, 대풍구장을 거스르는 거니까...",
            ["DialogueId"] = 80200313,
            ["FinalCamera"] = "-122.544006,202.442444,84.046875,0.000046,8.199416,-58.192867,40.0,320.911621,false,Manual,6.00204",
            ["GUID"] = "C8C5E7DA",
            ["NextDialogue"] = 80200314,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{2.1},ActorId{790054},AnimationId{\"Think_Start\"}},\
LookAt{_delay{1.1},LookAtDescription{\"790054:n(790008)\"}}\
}",
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:Talk03_End",
                },
            ["ToFinalCameraBlendTime"] = 30,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5E7DA",
            },
        [80200314] = {
            ["Content"] = "我与我的研究最后究竟是怎样的结局，谁也不知道。",
            ["ContentKR"] = "나랑 내 연구가 어떤 결말을 맞이하게 될진, 아무도 몰라.",
            ["DialogueId"] = 80200314,
            ["Duration"] = 2,
            ["GUID"] = "C8C5E804",
            ["LookAt"] = {
                [1] = "790054:n(790054)",
                },
            ["NextDialogue"] = 80200315,
            ["Scripts"] = "PlayAnimation{_delay{3.1},ActorId{790054},AnimationId{\"DisagreeHead\"},Duration{1}}",
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5E804",
            },
        [80200315] = {
            ["Camera"] = "-63.858021,-9.877949,179.9375,0.000124,-18.402338,-38.786407,50.000011,105.212311,false,Manual,8.395343",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "但有一件事我可以确定，那就是滥用枯荣之术，扶疏妹妹一定会英年早逝吧。",
            ["ContentKR"] = "그래도 이거 하나는 확실해. 계속 고영법을 사용했다간, 부소는 제명에 못 죽을 거야.",
            ["DialogueId"] = 80200315,
            ["FinalCamera"] = "-57.449242,-15.032286,177.196289,0.000124,-18.402338,-38.786407,50.000011,105.212311,false,Manual,8.395343",
            ["GUID"] = "C8C5E82E",
            ["NextDialogue"] = 80200316,
            ["Scripts"] = "PlayAnimation{_delay{5.1},ActorId{790054},AnimationId{\"Explain02_End\"},Duration{1}}",
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5E82E",
            },
        [80200316] = {
            ["Camera"] = "-43.131927,125.243118,128.523438,0.000069,4.597353,-67.988014,55.0,219.25647,false,Manual,17.764473",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "而我……不想看到这个局面，所以我绝不会让步，我们的架也只能一直吵下去了。",
            ["ContentKR"] = "그리고 난... 그 꼴은 못 봐. 그래서 양보하지 않을 거고, 우린 계속 싸울 수밖에 없어.",
            ["DialogueId"] = 80200316,
            ["FinalCamera"] = "-50.373177,143.161255,126.967773,0.000069,4.597353,-67.987976,55.0,219.25647,false,Manual,17.764473",
            ["GUID"] = "C8C5E858",
            ["LookAt"] = {
                [1] = "790054:n(790008)",
                },
            ["NextDialogue"] = 80200317,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{4.1},ActorId{790054},AnimationId{\"Confident_Start\"},Duration{1}},\
PlayAnimation{_delay{11.1},ActorId{790054},AnimationId{\"Confident_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 790054,
            ["ToFinalCameraBlendTime"] = 20,
            ["TurnTo"] = {
                [1] = "790054:n(790008)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5E858",
            },
        [80200317] = {
            ["Camera"] = "-826.984375,564.034241,566.810547,0.00006,-22.002954,-35.181374,30.0,1155.509888,false,Manual,17.764473",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "唉，摊上这么一个不知姐姐苦心的妹妹，就算是得由我来道歉，我也不会让她好过的！",
            ["ContentKR"] = "하여간, 언니 속도 모르는 동생을 뒀으니 어쩌겠어. 그렇지만 내가 먼저 사과해야 하더라도, 곱게는 못 넘어가지!",
            ["DialogueId"] = 80200317,
            ["FinalCamera"] = "-826.984375,564.034241,531.505859,0.000068,-22.202971,-35.380627,30.0,1155.509888,false,Manual,17.764473",
            ["GUID"] = "C8C5E882",
            ["NextDialogue"] = 80200318,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{2.1},ActorId{790054},AnimationId{\"DisagreeHead\"},Duration{1}},\
PlayAnimation{_delay{5.1},ActorId{790054},AnimationId{\"Talk01_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:Talk01_Start",
                },
            ["ToFinalCameraBlendTime"] = 40,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5E882",
            },
        [80200318] = {
            ["Content"] = "但我已经不被允许靠近她了，这些小可爱就交由你来转赠吧！她那么信任你，肯定毫无防备，说不定还会像小时候一样被吓哭哦。",
            ["ContentKR"] = "그런데 난 지금 걔 근처에도 못 가니까, 이 귀염둥이들은 네가 대신 전해 줘! 걔는 널 철석같이 믿으니까, 전혀 의심 안 할걸. 어쩌면 어릴 때처럼 깜짝 놀라서 울어 버릴지도 몰라.",
            ["DialogueId"] = 80200318,
            ["FacialId"] = {
                [1] = "790054:Smile01",
                },
            ["GUID"] = "C8C5E8AC",
            ["NextOptions"] = {
                [1] = 80200319,
                },
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{6.1},ActorId{790054},AnimationId{\"Explain01_End\"},Duration{1}},\
PlayAnimation{_delay{9.1},ActorId{790054},AnimationId{\"Angry01_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:Explain01_Start",
                [2] = "790008:Shy03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5E8AC",
            },
        [80200319] = {
            ["Content"] = "寿星乌贼……",
            ["ContentKR"] = "수성 오징어라...",
            ["DialogueId"] = 80200319,
            ["GUID"] = "C8C5E8D6",
            ["NextDialogue"] = 80200320,
            },
        [80200320] = {
            ["Camera"] = "-40.08873,-25.583652,132.830078,0.000071,0.997262,64.819328,40.0,103.979561,false,Manual,17.764473",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "你只是想拐弯抹角地告诉她，“希望你能长命百岁”吧？",
            ["ContentKR"] = "그냥 빙빙 돌려서 '오래오래 살았으면 좋겠다'고 말하려는 거잖아요?",
            ["DialogueId"] = 80200320,
            ["Duration"] = 1,
            ["FinalCamera"] = "-44.77795,-23.377747,132.830078,0.000071,0.997262,64.819717,40.0,103.979561,false,Manual,17.764473",
            ["GUID"] = "C8C5E900",
            ["NextDialogue"] = 80200321,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{2.1},ActorId{790008},AnimationId{\"Think_End\"},Duration{1}},\
PlayFacial{_delay{4.1},ActorId{790008},FacialId{\"Smile02\"}}\
}",
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 30,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5E900",
            },
        [80200321] = {
            ["Camera"] = "-335.726562,-30.426773,87.43457,-0.299988,4.600269,5.00543,28.0,371.52066,false,Manual,1.2",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "呃……看破不说破嘛，这种小心思说出来就没劲儿了。我还想看扶疏生气的样子呢！",
            ["ContentKR"] = "음... 알아도 모르는 척해 줘. 이런 속마음은 얘기해 버리면 재미가 없잖아. 난 부소가 화내는 걸 보고 싶단 말이야!",
            ["DialogueId"] = 80200321,
            ["FinalCamera"] = "-376.866547,-34.026245,84.112305,-0.299988,4.600269,5.00543,28.0,383.921387,false,Manual,1.2",
            ["GUID"] = "C8C5E92A",
            ["LookAt"] = {
                [1] = "790054:n(790054)",
                },
            ["NextDialogue"] = 80200322,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{2.1},ActorId{790054},AnimationId{\"Talk03_Start\"},Duration{1}},\
LookAt{_delay{6.1},LookAtDescription{\"790054:n(790008)\"}}\
}",
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:Angry01_End",
                },
            ["ToFinalCameraBlendTime"] = 20,
            ["TurnTo"] = {
                [1] = "790054:p(70)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5E92A",
            },
        [80200322] = {
            ["Content"] = "快去！快去！",
            ["ContentKR"] = "그럼 빨리 가 봐! 얼른!",
            ["DialogueId"] = 80200322,
            ["GUID"] = "C8C5E954",
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790008:AgreeHead",
                [2] = "790054:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5E954",
            },
        [80200323] = {
            ["Content"] = "出幻境，回到采药任务点1，和扶疏站桩。",
            ["ContentKR"] = "환상에서 깨어나, 약초 채집 퀘스트 지점1로 돌아온다. 부소와 함께 서 있다.",
            ["DialogueId"] = 80200323,
            ["GUID"] = "C8C5E97E",
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5E97E",
            },
        [80200324] = {
            ["Camera"] = "119.887146,130.070343,137.368652,0.000012,2.799851,-138.98819,45.0,175.296234,false,Manual,22.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "你醒了！",
            ["ContentKR"] = "깨어났군요!",
            ["DialogueId"] = 80200324,
            ["FacialId"] = {
                [1] = "790053:Shock01",
                },
            ["FinalCamera"] = "141.731094,149.066513,136.484863,0.000012,1.599883,-138.98819,45.0,202.350357,false,Manual,12.098981",
            ["GUID"] = "C8C5E9A8",
            ["NextDialogue"] = 80200325,
            ["SpeakNpcId"] = 790053,
            ["TalkActionId"] = {
                [1] = "790053:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 20,
            ["TurnTo"] = {
                [1] = "790008:n(790053)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5E9A8",
            },
        [80200325] = {
            ["Content"] = "才过去三四分钟，但实在牵肠挂肚……我都怀疑是否记错了书上的内容，莫非毒性比我想象中大？",
            ["ContentKR"] = "고작 몇 분이었지만 얼마나 걱정했는지 몰라요... 제가 책 내용을 잘못 기억한 건 아닌지, 독성이 생각보다 강했던 건 아닌지 온갖 걱정을 다 했어요.",
            ["DialogueId"] = 80200325,
            ["FacialId"] = {
                [1] = "790053:Sad01",
                },
            ["GUID"] = "C8C5E9D2",
            ["NextDialogue"] = 80200326,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{2.1},ActorId{790053},AnimationId{\"DisagreeHead\"},Duration{1}},\
PlayAnimation{_delay{3.1},ActorId{790053},AnimationId{\"Think_Start\"},Duration{1}},\
PlayAnimation{_delay{7.1},ActorId{790053},AnimationId{\"Think_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 790053,
            ["TalkActionId"] = {
                [1] = "790053:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5E9D2",
            },
        [80200326] = {
            ["Content"] = "我想给你用枯荣之术，但又怕没等我施术完毕，你就又好了……",
            ["ContentKR"] = "고영법을 사용하려고 했었는데, 제가 뭘 끝내기도 전에 정신을 차릴까 봐...",
            ["DialogueId"] = 80200326,
            ["GUID"] = "C8C5E9FC",
            ["NextDialogue"] = 80200327,
            ["Scripts"] = "PlayAnimation{_delay{7.1},ActorId{790053},AnimationId{\"Explain01_End\"},Duration{1}}",
            ["SpeakNpcId"] = 790053,
            ["TalkActionId"] = {
                [1] = "790053:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5E9FC",
            },
        [80200327] = {
            ["Camera"] = "30.172951,-5.828094,146.924805,0.000022,-4.600405,68.410217,45.0,131.244232,false,Manual,6.805237",
            ["Content"] = "噗嗤……你们姐妹俩还真是像……",
            ["ContentKR"] = "풉... 언니랑 똑같구나...",
            ["DialogueId"] = 80200327,
            ["FacialId"] = {
                [1] = "790008:Smile02",
                },
            ["GUID"] = "C8C5EA26",
            ["NextDialogue"] = 80200328,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Laugh01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5EA26",
            },
        [80200328] = {
            ["Camera"] = "141.731094,149.066513,136.484863,0.000012,1.599883,-138.98822,45.0,202.350357,false,Manual,6.805237",
            ["Content"] = "你也……见到家姐了？",
            ["ContentKR"] = "당신도... 언니를 만났어요?",
            ["DialogueId"] = 80200328,
            ["FacialId"] = {
                [1] = "790053:Unacceptable01",
                },
            ["GUID"] = "C8C5EA50",
            ["NextDialogue"] = 80200329,
            ["SpeakNpcId"] = 790053,
            ["TalkActionId"] = {
                [1] = "790053:Shy02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5EA50",
            },
        [80200329] = {
            ["Camera"] = "-15.628626,-121.557404,164.124023,0.000028,-8.000521,72.409447,45.0,254.346725,false,Manual,6.805237",
            ["Content"] = "没错，你记得吗，她同你吵架，送了你最讨厌的寿星乌贼做道歉礼物。",
            ["ContentKR"] = "응, 혹시 기억나? 싸우고 나서, 언니가 화해의 선물이라면서 부소가 제일 싫어하는 수성 오징어를 줬었잖아.",
            ["DialogueId"] = 80200329,
            ["GUID"] = "C8C5EA7A",
            ["NextDialogue"] = 80200330,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Talk01_Start",
                [2] = "790053:Shy02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5EA7A",
            },
        [80200330] = {
            ["Camera"] = "95.230194,90.889275,139.040527,0.000013,1.999715,-138.388199,45.0,129.860046,false,Manual,6.805237",
            ["Content"] = "……我都已经忘记了。那真是，很久很久以前的往事了。",
            ["ContentKR"] = "...까맣게 잊고 있었어요. 정말, 아주 오래전 일이네요.",
            ["DialogueId"] = 80200330,
            ["FacialId"] = {
                [1] = "790053:Sad03",
                },
            ["GUID"] = "C8C5EAA4",
            ["LookAt"] = {
                [1] = "790053:n(790053)",
                },
            ["NextDialogue"] = 80200331,
            ["Scripts"] = "PlayAnimation{_delay{2.1},ActorId{790053},AnimationId{\"Explain02_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 790053,
            ["TalkActionId"] = {
                [1] = "790053:DisagreeHead",
                [2] = "790008:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5EAA4",
            },
        [80200331] = {
            ["Camera"] = "415.101501,-1311.599854,42.874023,0.000077,2.399227,107.206627,45.0,1317.139771,false,Manual,6.805237",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "你接受她的道歉了吗？",
            ["ContentKR"] = "사과는 받아 줬어?",
            ["DialogueId"] = 80200331,
            ["FinalCamera"] = "448.243896,-1301.340576,42.874023,0.000077,2.399227,107.206627,45.0,1317.139771,false,Manual,6.805237",
            ["GUID"] = "C8C5EACE",
            ["NextDialogue"] = 80200332,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Talk02_Start",
                [2] = "790053:Explain02_End",
                },
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5EACE",
            },
        [80200332] = {
            ["Content"] = "呵呵……没有，我和她又吵了一架。我虽然不后悔……",
            ["ContentKR"] = "후후... 아니요, 또 한바탕 싸웠어요. 후회하는 건 아니지만...",
            ["DialogueId"] = 80200332,
            ["GUID"] = "C8C5EAF8",
            ["NextDialogue"] = 80200333,
            ["SpeakNpcId"] = 790053,
            ["TalkActionId"] = {
                [1] = "790008:Talk02_End",
                [2] = "790053:Sad02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5EAF8",
            },
        [80200333] = {
            ["Camera"] = "106.505447,46.279133,180.103516,0.000015,-17.200472,-157.386368,45.0,118.629143,false,Manual,12.098981",
            ["Content"] = "但或许，现在的我会愿意接受那条寿星乌贼。",
            ["ContentKR"] = "지금의 저였다면, 그 수성 오징어를 기꺼이 받아 줬을지도 모르겠네요.",
            ["DialogueId"] = 80200333,
            ["FacialId"] = {
                [1] = "790053:SpecialSmile",
                },
            ["FinalCamera"] = "93.592377,40.89082,175.773438,0.000015,-17.200472,-157.386368,45.0,109.419518,false,Manual,12.098981",
            ["GUID"] = "C8C5EB22",
            ["NextDialogue"] = 80200334,
            ["SpeakNpcId"] = 790053,
            ["TalkActionId"] = {
                [1] = "790053:Sad02_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5EB22",
            },
        [80200334] = {
            ["Content"] = "……但也只是或许，我不喜欢多足生物，这点千真万确。",
            ["ContentKR"] = "...어디까지나 가정일 뿐이지만요. 전 다리가 많이 달린 생물은 질색이거든요. 진짜, 진짜로요.",
            ["DialogueId"] = 80200334,
            ["FacialId"] = {
                [1] = "790053:Pain01",
                },
            ["GUID"] = "C8C5EB4C",
            ["NextDialogue"] = 80200335,
            ["SpeakNpcId"] = 790053,
            ["TalkActionId"] = {
                [1] = "790053:Sigh_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5EB4C",
            },
        [80200335] = {
            ["Camera"] = "48.175987,-418.433289,149.098633,0.000042,-4.200382,92.013222,45.0,450.246735,false,Manual,12.098981",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "其实……不应该让你看到这些往事，过去的人都已作古，看到这些徒惹伤怀，也是无益。",
            ["ContentKR"] = "사실... 이런 옛날 일들을 당신한테 보여주지 말아야 했어요. 이미 다 지나간 일이고, 떠나간 사람들이잖아요. 봐도 괜히 마음만 아프고 좋을 게 없는걸요.",
            ["DialogueId"] = 80200335,
            ["FacialId"] = {
                [1] = "790008:Beg",
                },
            ["FinalCamera"] = "-69.18502,-422.553558,149.098633,0.000043,-3.200346,79.0131,45.0,450.246735,false,Manual,12.098981",
            ["GUID"] = "C8C5EB76",
            ["NextDialogue"] = 80200336,
            ["SpeakNpcId"] = 790053,
            ["TalkActionId"] = {
                [1] = "790053:Sigh_End",
                [2] = "790008:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 30,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5EB76",
            },
        [80200336] = {
            ["Content"] = "只是这枯荣阁是我们从小生长的地方，恐怕所有的音容草里，都存放着我们的过往。",
            ["ContentKR"] = "하지만 이 고영각은 우리 자매가 나고 자란 곳이니까, 이곳 음용초엔 전부 저랑 언니의 옛이야기가 담겨 있을지도 몰라요.",
            ["DialogueId"] = 80200336,
            ["GUID"] = "C8C5EBA0",
            ["NextDialogue"] = 80200337,
            ["SpeakNpcId"] = 790053,
            ["TurnTo"] = {
                [1] = "790053:p(70)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5EBA0",
            },
        [80200337] = {
            ["Camera"] = "-23.33609,-427.601105,149.098633,0.00004,16.598991,57.414169,45.0,450.246735,false,Manual,12.098981",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "所以下一次，还是由我来尝试吧，好吗？",
            ["ContentKR"] = "그러니까 다음엔 제가 먹어 볼게요. 괜찮죠?",
            ["DialogueId"] = 80200337,
            ["FinalCamera"] = "-23.33609,-427.601105,149.098633,0.000045,22.798664,61.012764,45.0,450.246735,false,Manual,12.098981",
            ["GUID"] = "C8C5EBCA",
            ["NextOptions"] = {
                [1] = 802003371,
                [2] = 802003372,
                },
            ["SpeakNpcId"] = 790053,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5EBCA",
            },
        [80200339] = {
            ["Content"] = "谢谢。",
            ["ContentKR"] = "고마워요.",
            ["DialogueId"] = 80200339,
            ["GUID"] = "C8C5EC1E",
            ["NextDialogue"] = 80200342,
            ["SpeakNpcId"] = 790053,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5EC1E",
            },
        [80200341] = {
            ["Content"] = "呵呵，下次相约之时，我再讲给你听吧。",
            ["ContentKR"] = "후후, 다음에 만날 때 저하고 언니 얘기를 들려줄게요.",
            ["DialogueId"] = 80200341,
            ["GUID"] = "C8C5EC72",
            ["NextDialogue"] = 80200342,
            ["SpeakNpcId"] = 790053,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5EC72",
            },
        [80200342] = {
            ["Content"] = "好，那去寻找下一个地方吧。",
            ["ContentKR"] = "자, 이제 다음 장소로 가서 찾아보죠.",
            ["DialogueId"] = 80200342,
            ["GUID"] = "C8C5EC9C",
            ["SpeakNpcId"] = 790053,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5EC9C",
            },
        [80200343] = {
            ["Content"] = "转场，枯荣阁野外",
            ["ContentKR"] = "장면 전환, 고영각 야외",
            ["DialogueId"] = 80200343,
            ["GUID"] = "C8C5ECC6",
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5ECC6",
            },
        [80200344] = {
            ["Camera"] = "172.202026,4449.555664,2332.257812,0.00004,-26.399895,-95.595238,30.000002,4788.840332,false,Manual,1.2",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "找到了。",
            ["ContentKR"] = "찾았어요.",
            ["DialogueId"] = 80200344,
            ["FinalCamera"] = "402.414307,4427.007812,2332.257812,0.00004,-26.399895,-95.595238,30.000002,4788.840332,false,Manual,1.2",
            ["GUID"] = "C8C5ECF0",
            ["NextDialogue"] = 80200345,
            ["SpeakNpcId"] = 790053,
            ["ToFinalCameraBlendTime"] = 10,
            ["TurnTo"] = {
                [1] = "790008:n(790053)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5ECF0",
            },
        [80200345] = {
            ["Content"] = "要不要猜一猜，这是音容草，还是怀梦草呢？",
            ["ContentKR"] = "문제 하나 낼게요. 이건 음용초일까요? 회몽초일까요?",
            ["DialogueId"] = 80200345,
            ["GUID"] = "C8C5ED1A",
            ["NextOptions"] = {
                [1] = 802003451,
                [2] = 802003452,
                },
            ["SpeakNpcId"] = 790053,
            ["TalkActionId"] = {
                [1] = "790008:Think_Start",
                },
            ["TurnTo"] = {
                [1] = "790053:n(790008)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5ED1A",
            },
        [80200348] = {
            ["Camera"] = "-514.179199,-65.437241,130.561523,0.000188,1.6034,11.198832,50.000008,636.943848,false,Manual,3.221528",
            ["Content"] = "看着没什么殊异之处，但摸在手里，确实有些极其微妙的差别……我猜这就是我们要找的怀梦草。",
            ["ContentKR"] = "눈으론 구별이 안 되지만, 손으로 만져 보면 미묘하게 달라요... 아무리도 이게 우리가 찾던 회몽초인 것 같네요.",
            ["DialogueId"] = 80200348,
            ["FinalCamera"] = "-516.200806,-55.210449,130.561523,0.000188,1.6034,11.198832,50.000008,636.943848,false,Manual,3.221528",
            ["GUID"] = "C8C5ED98",
            ["NextDialogue"] = 80200349,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{5.1},ActorId{790053},AnimationId{\"Confident_End\"},Duration{1}},\
PlayAnimation{_delay{6.1},ActorId{790053},AnimationId{\"Explain01_Start\"},Duration{1}},\
PlayAnimation{_delay{8.1},ActorId{790053},AnimationId{\"Explain01_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 790053,
            ["TalkActionId"] = {
                [1] = "790053:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5ED98",
            },
        [80200349] = {
            ["Camera"] = "83.302071,146.197098,182.37207,0.000091,-11.599047,-118.401756,40.000011,172.35437,false,Manual,3.813417",
            ["Content"] = "如果不是连续失败两次，我恐怕永远不会有这样的发现。",
            ["ContentKR"] = "두 번이나 연달아 실패하지 않았다면, 전 이 차이를 영원히 알아채지 못했을 거예요.",
            ["DialogueId"] = 80200349,
            ["GUID"] = "C8C5EDC2",
            ["NextDialogue"] = 80200350,
            ["SpeakNpcId"] = 790053,
            ["TalkActionId"] = {
                [1] = "790053:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5EDC2",
            },
        [80200350] = {
            ["Camera"] = "5.743984,121.353485,148.166016,0.000061,-2.198931,1.794543,40.000023,104.974152,false,Manual,8.259511",
            ["Content"] = "第一个发现这两种植物的人是怎么做到的？难道她也像我们一样，一点一点试出来的？",
            ["ContentKR"] = "맨 처음 이 두 식물을 발견한 사람은 이걸 어떻게 구분했을까? 그 사람도 우리처럼 하나씩 먹어 봤으려나?",
            ["DialogueId"] = 80200350,
            ["GUID"] = "C8C5EDEC",
            ["NextDialogue"] = 80200351,
            ["Scripts"] = "PlayAnimation{_delay{5.1},ActorId{790008},AnimationId{\"Talk03_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5EDEC",
            },
        [80200351] = {
            ["Camera"] = "30.070026,119.496765,121.788086,0.000079,14.400496,-100.208359,50.000011,123.697914,false,Manual,9.225292",
            ["Content"] = "呵……是呀，她是怎么做到的呢？",
            ["ContentKR"] = "후후... 그러게요. 어떻게 구분했던 걸까요?",
            ["DialogueId"] = 80200351,
            ["FacialId"] = {
                [1] = "790053:Think01",
                },
            ["GUID"] = "C8C5EE16",
            ["LookAt"] = {
                [1] = "790053:n(790053)",
                },
            ["NextDialogue"] = 80200352,
            ["Scripts"] = "PlayFacial{_delay{2.1},ActorId{790053},FacialId{\"Sad03\"}}",
            ["SpeakNpcId"] = 790053,
            ["TalkActionId"] = {
                [1] = "790053:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5EE16",
            },
        [80200352] = {
            ["Camera"] = "30.070026,119.496765,121.788086,0.000079,14.400496,-100.208359,50.000011,123.697914,false,Manual,9.225292",
            ["Content"] = "想必，一定经过无数次危险，与无数次不眠不休的钻研吧，即使不被理解，即使历经伤痛，她也从来没有放弃过。",
            ["ContentKR"] = "분명히 수없이 위험에 처하고, 수많은 밤을 새우며 연구했을 거예요. 남들이 이해해 주지 않아도, 고통에 시달리더라도, 절대로 포기하지 않았을 거고요.",
            ["DialogueId"] = 80200352,
            ["FinalCamera"] = "30.070026,119.496765,135.290039,0.000068,30.998163,-82.200356,50.000008,3999.122314,false,Manual,9.225292",
            ["GUID"] = "C8C5EE40",
            ["LookAt"] = {
                [1] = "790053:p(BP_200401fushu)",
                },
            ["NextDialogue"] = 80200353,
            ["SpeakNpcId"] = 790053,
            ["ToFinalCameraBlendTime"] = 32,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5EE40",
            },
        [80200353] = {
            ["Content"] = "一切都是为了从无数个一百年前，一直流传到今天的那个悬壶济世的理想。",
            ["ContentKR"] = "그 모든 건, 아득한 옛날부터 이어져 내려온, 의술로 인간을 구제한다는 신념을 위해서였겠죠.",
            ["DialogueId"] = 80200353,
            ["Duration"] = 2,
            ["GUID"] = "C8C5EE6A",
            ["NextDialogue"] = 80200354,
            ["SpeakNpcId"] = 790053,
            ["TalkActionId"] = {
                [1] = "790008:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5EE6A",
            },
        [80200354] = {
            ["Camera"] = "-159.132416,-51.042709,147.863281,0.00019,-2.796628,27.59856,50.000011,312.992676,false,Manual,3.221528",
            ["Content"] = "其实，还有一件事忘了告诉你。我刚才遇见的扶风说，匍地枝与隙中花更合适治疗多梦少眠。",
            ["ContentKR"] = "사실, 깜빡하고 말 안 한 게 있어. 아까 만난 부풍 씨가 그랬는데, 내 증상엔 땅의 가지랑 틈새의 꽃을 쓰는 게 더 좋대.",
            ["DialogueId"] = 80200354,
            ["FacialId"] = {
                [1] = "790008:Beg",
                },
            ["GUID"] = "C8C5EE94",
            ["LookAt"] = {
                [1] = "790053:n(790053)",
                },
            ["NextDialogue"] = 80200355,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5EE94",
            },
        [80200355] = {
            ["Content"] = "怀梦草虽能助眠，但会在梦中看到无法忘怀之事。",
            ["ContentKR"] = "회몽초를 쓰면 잠은 잘 오겠지만, 가슴에 묻지 못한 일들을 꿈에서 보게 된다더라고.",
            ["DialogueId"] = 80200355,
            ["GUID"] = "C8C5EEBE",
            ["NextDialogue"] = 80200356,
            ["Scripts"] = "PlayAnimation{_delay{2.1},ActorId{790008},AnimationId{\"DisagreeHead\"},Duration{1}}",
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5EEBE",
            },
        [80200356] = {
            ["Camera"] = "71.251167,76.700455,164.569336,0.000129,-5.199686,-133.204468,50.000011,99.112167,false,Manual,15.973291",
            ["Content"] = "也就是说，我不需要怀梦草了，但即使如此，你也要尝试吗？",
            ["ContentKR"] = "그러니까, 나한텐 회몽초가 필요 없을 것 같아. 그래도 부소는 먹어 볼 생각이야?",
            ["DialogueId"] = 80200356,
            ["Duration"] = 1,
            ["FinalCamera"] = "66.068237,71.181648,163.882812,0.000129,-5.199686,-133.204468,50.000011,99.112167,false,Manual,15.973291",
            ["GUID"] = "C8C5EEE8",
            ["NextDialogue"] = 80200357,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Shy03_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5EEE8",
            },
        [80200357] = {
            ["Content"] = "扶疏没有说话，只是照旧将那叶尖放入口中。这一次，没有不安与责难，你听到了均匀的呼吸声，以及一句浅浅的梦呓——",
            ["ContentKR"] = "부소는 아무 말 없이, 아까처럼 잎사귀를 입에 넣었다. 이번에는 불안해하지도, 누구를 비난하지도 않았다. 귀에 들려오는 건 고른 숨소리와 희미한 잠꼬대뿐이었다...",
            ["DialogueId"] = 80200357,
            ["Duration"] = 2,
            ["GUID"] = "C8C5EF12",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 80200358,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5EF12",
            },
        [80200358] = {
            ["Camera"] = "10.260178,29.508621,158.517578,0.00016,-13.799194,-104.60054,55.0,26.127415,false,Manual,15.973291",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "唉……下一次，换个道歉礼物吧。",
            ["ContentKR"] = "에휴... 다음엔 화해의 선물로 다른 걸 줘야겠네.",
            ["DialogueId"] = 80200358,
            ["FacialId"] = {
                [1] = "790053:Close",
                },
            ["FinalCamera"] = "13.641603,40.02512,158.702148,0.000164,-2.999177,-107.99968,55.000008,38.118717,false,Manual,15.973291",
            ["GUID"] = "C8C5EF3C",
            ["Scripts"] = "PlayFacial{_delay{1.5},ActorId{790053},FacialId{\"SpecialSmile\"}}",
            ["SpeakNpcId"] = 790053,
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5EF3C",
            },
        [80210101] = {
            ["Camera"] = "805.707031,-8.211914,540.876953,0.0,0.0,-177.666962,25.0,125.0,false,DoNotOverride,2.8",
            ["Content"] = "侠自然是快意恩仇的，他们手提三尺剑，专爱打抱不平。",
            ["ContentKR"] = "은혜는 은혜로, 원수는 원수로 되갚는 자, 협객. 그들은 삼척검을 손에 쥐고, 세상의 불의를 바로잡고자 한다.",
            ["DialogueId"] = 80210101,
            ["FinalCamera"] = "506.652344,-9.29248,134.94043,0.0,-5.548217,-178.123627,25.0,125.0,false,DoNotOverride,2.8",
            ["GUID"] = "C8CC2DB2",
            ["NextDialogue"] = 80210102,
            ["Scripts"] = "PlayOrStopBGM{PlayType{\"Play\"},SoundPriority{\"Invite\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"}}",
            ["ToFinalCameraBlendTime"] = 12,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC2DB2",
            },
        [80210102] = {
            ["Content"] = "浪迹天涯，四海飘零，不受任何羁绊。要按时回家的人，武艺再高，也更像是镖师，这听起来就比侠客不潇洒得多了。",
            ["ContentKR"] = "아무런 속박 없이, 천하를 떠돌며 사해를 누빈다. 때가 되면 집에 돌아가는 이들은, 무예가 아무리 출중한들 결국 표사일 뿐이니, 협객의 호방한 기개에 견줄 바 아니다.",
            ["DialogueId"] = 80210102,
            ["GUID"] = "C8CC2DDC",
            ["NextDialogue"] = 80210103,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC2DDC",
            },
        [80210103] = {
            ["Camera"] = "506.652344,-9.29248,134.94043,0.0,-5.548217,-178.123627,25.0,125.0,false,DoNotOverride,2.8",
            ["Content"] = "你要走了。",
            ["ContentKR"] = "떠나는 건가.",
            ["DialogueId"] = 80210103,
            ["FacialId"] = {
                [1] = "790065:CM_Sad01",
                [2] = "790066:CM_Sad01",
                },
            ["GUID"] = "C8CC2E06",
            ["LookAt"] = {
                [1] = "790065:n(790066)",
                },
            ["NextDialogue"] = 80210104,
            ["Scripts"] = "PlayOrStopBGM{PlayType{\"Stop\"},SoundPriority{\"Invite\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"}}",
            ["SpeakNpcId"] = 790065,
            ["TalkActionId"] = {
                [1] = "790067:ScratchHead_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["TurnTo"] = {
                [1] = "790065:n(790066)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC2E06",
            },
        [80210104] = {
            ["Camera"] = "390.390625,-180.267578,96.469727,0.000003,-1.798122,157.194687,30.0,337.309082,false,Manual,2.8",
            ["Content"] = "我要走了。",
            ["ContentKR"] = "떠나야겠지.",
            ["DialogueId"] = 80210104,
            ["FinalCamera"] = "310.414062,-146.627441,93.75,0.000003,0.0,157.194702,30.0,323.332245,false,Manual,2.8",
            ["GUID"] = "C8CC2E30",
            ["NextDialogue"] = 80210105,
            ["SpeakNpcId"] = 790066,
            ["TalkActionId"] = {
                [1] = "790066:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 30,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC2E30",
            },
        [80210105] = {
            ["Content"] = "你毕竟还是要走。",
            ["ContentKR"] = "결국 떠나기로 했군.",
            ["DialogueId"] = 80210105,
            ["GUID"] = "C8CC2E5A",
            ["NextDialogue"] = 80210106,
            ["SpeakNpcId"] = 790065,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC2E5A",
            },
        [80210106] = {
            ["Content"] = "我毕竟还是要走。",
            ["ContentKR"] = "결국 떠나야만 하니까.",
            ["DialogueId"] = 80210106,
            ["GUID"] = "C8CC2E84",
            ["NextDialogue"] = 80210107,
            ["SpeakNpcId"] = 790066,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC2E84",
            },
        [80210107] = {
            ["Content"] = "你本不该走的。",
            ["ContentKR"] = "떠나면 안 돼.",
            ["DialogueId"] = 80210107,
            ["GUID"] = "C8CC2EAE",
            ["NextDialogue"] = 80210108,
            ["SpeakNpcId"] = 790065,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC2EAE",
            },
        [80210108] = {
            ["Content"] = "可我已经要走了。",
            ["ContentKR"] = "하지만 떠나기로 했다네.",
            ["DialogueId"] = 80210108,
            ["GUID"] = "C8CC2ED8",
            ["NextDialogue"] = 80210109,
            ["SpeakNpcId"] = 790066,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC2ED8",
            },
        [80210109] = {
            ["Content"] = "你为什么要走？",
            ["ContentKR"] = "왜 떠나려는 거지?",
            ["DialogueId"] = 80210109,
            ["GUID"] = "C8CC2F02",
            ["NextDialogue"] = 80210110,
            ["SpeakNpcId"] = 790065,
            ["TalkActionId"] = {
                [1] = "790065:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC2F02",
            },
        [80210110] = {
            ["Content"] = "因为要留人的性命。",
            ["ContentKR"] = "한 사람을 살려야 하거든.",
            ["DialogueId"] = 80210110,
            ["GUID"] = "C8CC2F2C",
            ["NextDialogue"] = 80210111,
            ["SpeakNpcId"] = 790066,
            ["TalkActionId"] = {
                [1] = "790066:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC2F2C",
            },
        [80210111] = {
            ["Content"] = "留谁的性命？",
            ["ContentKR"] = "그게 누구지...?",
            ["DialogueId"] = 80210111,
            ["GUID"] = "C8CC2F56",
            ["NextDialogue"] = 80210112,
            ["SpeakNpcId"] = 790065,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC2F56",
            },
        [80210112] = {
            ["Camera"] = "-97.171875,135.871094,124.923828,0.000072,-11.800135,-56.803616,25.0,226.88681,false,Manual,2.8",
            ["Content"] = "留你的性命！",
            ["ContentKR"] = "바로 너!",
            ["DialogueId"] = 80210112,
            ["Duration"] = 4,
            ["GUID"] = "C8CC2F80",
            ["LookAt"] = {
                [1] = "790066:n(790065)",
                },
            ["NextDialogue"] = 80210113,
            ["SpeakNpcId"] = 790066,
            ["TalkActionId"] = {
                [1] = "790065:Explain01_End",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["TurnTo"] = {
                [1] = "790066:n(790065)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC2F80",
            },
        [80210113] = {
            ["Camera"] = "150.417969,40.62793,98.314453,0.000076,-0.199004,171.387024,30.0,201.271973,false,Manual,2.8",
            ["Content"] = "哎呀，果然帅气，这次我们交换，让我来说：“留你的性命！”",
            ["ContentKR"] = "오, 역시 멋있네. 그럼 바꿔서 해보자. 이번엔 내가 \"바로 너!\" 부분을 하는 거야.",
            ["DialogueId"] = 80210113,
            ["FacialId"] = {
                [1] = "790065:CM_Happy01",
                },
            ["GUID"] = "C8CC2FAA",
            ["NextDialogue"] = 80210114,
            ["SpeakNpcId"] = 790065,
            ["TalkActionId"] = {
                [1] = "790065:Huanhu_Nan_Start",
                },
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC2FAA",
            },
        [80210114] = {
            ["Camera"] = "33.960938,151.338867,112.264648,0.000069,-7.200624,-74.774574,35.000011,224.596802,false,Manual,2.8",
            ["Content"] = "蠢死啦，我只答应你演一遍的。",
            ["ContentKR"] = "바보야, 연기 상대는 딱 한 번만 해준다고 했잖아.",
            ["DialogueId"] = 80210114,
            ["FacialId"] = {
                [1] = "790066:CM_Idle",
                },
            ["GUID"] = "C8CC2FD4",
            ["NextDialogue"] = 80210115,
            ["SpeakNpcId"] = 790066,
            ["TalkActionId"] = {
                [1] = "790066:Sigh_Start",
                },
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC2FD4",
            },
        [80210115] = {
            ["Camera"] = "-154.820312,-313.032227,46.03125,0.000064,4.999999,61.640118,22.063116,681.604492,false,Manual,2.8",
            ["Content"] = "你们……这是在干什么。",
            ["ContentKR"] = "너네... 지금 뭐 하는 거냐.",
            ["DialogueId"] = 80210115,
            ["FinalCamera"] = "-182.828125,-367.04541,41.943359,0.000061,3.999984,62.639935,22.063116,681.604492,false,Manual,2.8",
            ["GUID"] = "C8CC2FFE",
            ["NextDialogue"] = 80210116,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790066:Sigh_End",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC2FFE",
            },
        [80210116] = {
            ["Camera"] = "274.847656,276.966309,232.944336,0.00018,-20.000671,-141.973434,30.0,445.724579,false,Manual,4.0",
            ["Content"] = "这都不知道，我们这是在模仿飘零人对话呀。",
            ["ContentKR"] = "보면 모르세요? 나그네 대화를 따라 하는 거잖아요.",
            ["DialogueId"] = 80210116,
            ["FinalCamera"] = "262.335938,267.178223,227.157227,0.00018,-20.000671,-141.973434,30.0,248.094116,false,Manual,4.0",
            ["GUID"] = "C8CC3028",
            ["LookAt"] = {
                [1] = "790067:n(790065)",
                },
            ["NextDialogue"] = 80210117,
            ["SpeakNpcId"] = 790065,
            ["TalkActionId"] = {
                [1] = "790067:ScratchHead_Start",
                },
            ["ToFinalCameraBlendTime"] = 15,
            ["TurnTo"] = {
                [1] = "790065:n(790067)",
                [2] = "790066:n(790067)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC3028",
            },
        [80210117] = {
            ["Content"] = "这场对话是之前最流行的飘零人小说里，最有名的一段台词了，每当读到这里的时候，我都恨不得钻进书里去。",
            ["ContentKR"] = "이건 예전에 엄청 유행한 나그네 소설에 나오는 명장면이에요. 읽다가 이 부분만 나오면, 책 안으로 빨려 들어갈 것 같다니까요.",
            ["DialogueId"] = 80210117,
            ["GUID"] = "C8CC3052",
            ["NextDialogue"] = 80210118,
            ["SpeakNpcId"] = 790065,
            ["TalkActionId"] = {
                [1] = "790065:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC3052",
            },
        [80210118] = {
            ["Content"] = "要不是每天被阿妈揪着耳朵读书，我肯定去奔赴那山外山学得一身好本领，快意恩仇！",
            ["ContentKR"] = "엄마가 맨날 공부하라고 닦달하지만 않았어도, 바로 산외산에 달려가서 무공을 배웠을 거예요. 그런 다음 원수에게 통쾌하게 복수했겠죠!",
            ["DialogueId"] = 80210118,
            ["GUID"] = "C8CC307C",
            ["LookAt"] = {
                [1] = "790065:n(790066)",
                },
            ["NextDialogue"] = 80210119,
            ["SpeakNpcId"] = 790065,
            ["TalkActionId"] = {
                [1] = "790065:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC307C",
            },
        [80210119] = {
            ["Camera"] = "33.960938,151.338867,112.264648,0.000069,-7.200624,-74.774574,35.000011,224.596802,false,Manual,2.8",
            ["Content"] = "你要是和我一样早早做完功课，阿妈才懒得管你呢。",
            ["ContentKR"] = "그러니까 나처럼 숙제를 미리미리 했어야지. 그럼 엄마가 뭐 하러 잔소리하겠어.",
            ["DialogueId"] = 80210119,
            ["GUID"] = "C8CC30A6",
            ["LookAt"] = {
                [1] = "790066:n(790065)",
                },
            ["NextDialogue"] = 80210120,
            ["SpeakNpcId"] = 790066,
            ["TalkActionId"] = {
                [1] = "790066:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC30A6",
            },
        [80210120] = {
            ["Camera"] = "150.417969,40.62793,98.314453,0.000076,-0.199004,171.387024,30.0,201.271973,false,Manual,2.8",
            ["Content"] = "阿妈是偏心，她的那把佩剑，你拿来砍柴杀鱼她都不会说什么。而我想要拿起来舞一个剑花，她都要说我是玩物丧志呢。",
            ["ContentKR"] = "엄만 누나만 예뻐해. 누나가 엄마 검으로 장작 패고 생선 손질할 땐 아무 말도 안 하면서, 내가 칼춤이라도 한 번 추려고 하면, 노는 데만 정신 팔렸다고 야단치시잖아.",
            ["DialogueId"] = 80210120,
            ["GUID"] = "C8CC30D0",
            ["NextDialogue"] = 80210121,
            ["SpeakNpcId"] = 790065,
            ["TalkActionId"] = {
                [1] = "790065:Talk02_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC30D0",
            },
        [80210121] = {
            ["Camera"] = "-97.171875,135.871094,124.923828,0.000072,-11.800135,-56.803616,25.0,226.88681,false,Manual,2.8",
            ["Content"] = "那当然了，我这可都干得是正事，给阿妈帮忙的。你拿起剑来舞来舞去，不伤到自己都算是好的。",
            ["ContentKR"] = "그거야 당연하지, 난 엄마 일을 돕는 거잖아. 넌 검 들고 설치다가 다치지나 않으면 다행이고.",
            ["DialogueId"] = 80210121,
            ["GUID"] = "C8CC30FA",
            ["NextDialogue"] = 80210122,
            ["SpeakNpcId"] = 790066,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC30FA",
            },
        [80210122] = {
            ["Camera"] = "112.191406,49.433105,156.642578,0.000145,-12.799466,173.017639,35.0,178.705887,false,Manual,2.8",
            ["Content"] = "要我说啊，阿妈就是没读过飘零人小说，否则才不会由着你拿着这把剑干杂活。",
            ["ContentKR"] = "엄마가 나그네 소설을 안 읽어봐서 그래. 아니면 그 검으로 그런 허드렛일을 하도록 놔두시겠어?",
            ["DialogueId"] = 80210122,
            ["FinalCamera"] = "80.292969,53.341797,149.338867,0.000145,-12.799466,173.017639,35.000011,149.474472,false,Manual,2.8",
            ["GUID"] = "C8CC3124",
            ["NextDialogue"] = 80210123,
            ["SpeakNpcId"] = 790065,
            ["TalkActionId"] = {
                [1] = "790065:Talk02_End",
                },
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC3124",
            },
        [80210123] = {
            ["Content"] = "应该给我才是，让我练习剑谱，等我长大了就可以保护阿姐你和阿妈。",
            ["ContentKR"] = "나한테 검법을 연습하라고 주셨겠지. 나중에 커서 누나랑 엄마를 지켜 주라고.",
            ["DialogueId"] = 80210123,
            ["GUID"] = "C8CC314E",
            ["NextDialogue"] = 80210124,
            ["SpeakNpcId"] = 790065,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC314E",
            },
        [80210124] = {
            ["Camera"] = "33.960938,151.338867,112.264648,0.000069,-7.200624,-74.774574,35.000011,224.596802,false,Manual,2.8",
            ["Content"] = "你就是小说看多啦，现在有大风九章，根本不需要飘零人保护大家的。",
            ["ContentKR"] = "제발 소설 좀 그만 봐. 지금은 대풍구장이 있어서, 나그네들이 사람들을 보호해 줄 필요가 없단 말이야.",
            ["DialogueId"] = 80210124,
            ["GUID"] = "C8CC3178",
            ["NextDialogue"] = 80210125,
            ["SpeakNpcId"] = 790066,
            ["TalkActionId"] = {
                [1] = "790066:Confident_End",
                },
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC3178",
            },
        [80210125] = {
            ["Camera"] = "160.730469,298.234375,220.72168,0.000052,-13.400564,-69.973022,35.000011,125.0,false,Manual,2.8",
            ["Content"] = "说得是啊，现在这个时日，确实已经没多少个飘零人了。",
            ["ContentKR"] = "그건 맞다. 확실히 요즘 시대엔 나그네가 얼마 남지도 않았지.",
            ["DialogueId"] = 80210125,
            ["FinalCamera"] = "165.699219,284.596191,217.265625,0.000052,-13.400564,-69.973022,35.000011,110.763969,false,Manual,2.8",
            ["GUID"] = "C8CC31A2",
            ["NextDialogue"] = 80210126,
            ["SpeakNpcId"] = 790067,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC31A2",
            },
        [80210126] = {
            ["Camera"] = "393.839844,444.308105,335.135742,0.000015,-26.198637,-130.560333,35.000011,240.726898,false,Manual,2.8",
            ["Content"] = "啊，不好意思，大哥哥，刚刚我只顾着和弟弟说话了，忘了你还在边上。",
            ["ContentKR"] = "아, 죄송해요. 방금 동생이랑 이야기하는 데 정신이 팔려서, 옆에 누가 계신 줄 몰랐어요.",
            ["DialogueId"] = 80210126,
            ["GUID"] = "C8CC31CC",
            ["LookAt"] = {
                [1] = "790065:n(790067)",
                [2] = "790066:n(790067)",
                },
            ["NextDialogue"] = 80210127,
            ["SpeakNpcId"] = 790066,
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC31CC",
            },
        [80210127] = {
            ["Camera"] = "153.617188,127.562012,157.194336,0.000101,-18.800348,-103.577133,35.000011,187.821686,false,Manual,2.8",
            ["Content"] = "请问你来这里是……找阿妈吗？她吩咐过，不见来客的。",
            ["ContentKR"] = "혹시... 엄마를 만나러 오셨나요? 엄마는 손님을 만나지 않겠다고 하셨는데요.",
            ["DialogueId"] = 80210127,
            ["GUID"] = "C8CC31F6",
            ["LookAt"] = {
                [1] = "790067:n(790066)",
                },
            ["NextDialogue"] = 80210128,
            ["SpeakNpcId"] = 790066,
            ["TalkActionId"] = {
                [1] = "790066:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC31F6",
            },
        [80210128] = {
            ["Camera"] = "-2.984375,-178.594238,79.739258,0.000157,10.398853,55.621544,40.0,463.63916,false,Manual,2.8",
            ["Content"] = "嗯，看得出来，她之前佩剑不离身，现在这把佩剑却在你们手上，那我自然明白她是什么意思。",
            ["ContentKR"] = "응, 한시도 떼어놓지 않는다던 그 검이 지금 네 손에 있는 걸 보니, 너희 엄마가 무슨 생각인지 말 안 해도 알겠다.",
            ["DialogueId"] = 80210128,
            ["FinalCamera"] = "13.074219,-155.074219,84.959961,0.000157,10.398853,55.621544,40.0,463.63916,false,Manual,2.8",
            ["GUID"] = "C8CC3220",
            ["NextDialogue"] = 80210129,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:AgreeHead",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC3220",
            },
        [80210129] = {
            ["Camera"] = "274.847656,276.966309,232.944336,0.00018,-20.000671,-141.973434,30.0,445.724579,false,Manual,4.0",
            ["Content"] = "你认识阿妈？能和我讲讲她年轻时候的事情吗？我总怀疑她是一位大侠，否则怎么会有这么一把好剑。",
            ["ContentKR"] = "우리 엄마를 아세요? 그럼 우리 엄마가 젊었을 때 얘기해 주실 수 있어요? 제 생각엔 분명히 대단한 협객이었을 것 같거든요. 그런 멋진 검을 갖고 계신 것만 봐도 뻔하잖아요.",
            ["DialogueId"] = 80210129,
            ["FinalCamera"] = "262.335938,267.178223,227.157227,0.00018,-20.000671,-141.973434,30.0,248.094116,false,Manual,4.0",
            ["GUID"] = "C8CC324A",
            ["LookAt"] = {
                [1] = "790067:n(790065)",
                },
            ["NextDialogue"] = 80210130,
            ["SpeakNpcId"] = 790065,
            ["ToFinalCameraBlendTime"] = 9,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC324A",
            },
        [80210130] = {
            ["Content"] = "每次我缠着她，她却又什么都不肯说。",
            ["ContentKR"] = "근데 아무리 졸라도 말해주질 않으세요.",
            ["DialogueId"] = 80210130,
            ["GUID"] = "C8CC3274",
            ["NextDialogue"] = 80210131,
            ["SpeakNpcId"] = 790065,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC3274",
            },
        [80210131] = {
            ["Camera"] = "105.101562,49.699219,200.319336,0.000131,-3.00042,53.422153,35.000011,175.117645,false,Manual,2.8",
            ["Content"] = "那，我也是受人所托来找她，但既然她无意相见，那么我也不便多说。",
            ["ContentKR"] = "나도 부탁을 받고 찾아온 거야. 하지만 너희 엄마가 손님을 만나지 않는다니, 그럼 나도 함부로 말해줄 수 없지.",
            ["DialogueId"] = 80210131,
            ["FinalCamera"] = "112.863281,60.17041,199.636719,0.000131,-3.00042,53.422176,35.000011,175.117645,false,Manual,2.8",
            ["GUID"] = "C8CC329E",
            ["LookAt"] = {
                [1] = "790067:n(790065)",
                },
            ["NextDialogue"] = 80210132,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:DisagreeHead",
                },
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC329E",
            },
        [80210132] = {
            ["Camera"] = "150.417969,40.62793,98.314453,0.000076,-0.199004,171.387024,30.0,201.271973,false,Manual,2.8",
            ["Content"] = "什么嘛，没劲。我看你这副行头，又背着剑，还以为能看到阿妈出手呢。",
            ["ContentKR"] = "뭐예요, 재미없게. 차림새도 그렇고 검도 차고 있길래, 우리 엄마 실력이라도 볼 수 있나 했더니.",
            ["DialogueId"] = 80210132,
            ["GUID"] = "C8CC32C8",
            ["NextDialogue"] = 80210133,
            ["SpeakNpcId"] = 790065,
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC32C8",
            },
        [80210133] = {
            ["Camera"] = "393.839844,444.308105,335.135742,0.000015,-26.198637,-130.560333,35.000011,240.726898,false,Manual,2.8",
            ["Content"] = "哈哈，假以时日，会见到的。那么，在下告辞。",
            ["ContentKR"] = "하하, 곧 그렇게 될 거다. 그럼 난 이만.",
            ["DialogueId"] = 80210133,
            ["FacialId"] = {
                [1] = "790067:Smile02",
                },
            ["FinalCamera"] = "359.804688,403.016113,308.810547,0.000015,-26.198637,-130.560333,35.000011,290.796356,false,Manual,2.8",
            ["GUID"] = "C8CC32F2",
            ["LookAt"] = {
                [1] = "790067:n(790067)",
                },
            ["NextDialogue"] = 80210134,
            ["SpeakNpcId"] = 790067,
            ["ToFinalCameraBlendTime"] = 4,
            ["TurnTo"] = {
                [1] = "790067:p(180)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC32F2",
            },
        [80210134] = {
            ["Camera"] = "150.417969,40.62793,98.314453,0.000076,-0.199004,171.387024,30.0,201.271973,false,Manual,2.8",
            ["Content"] = "真的假的。喂，阿姐，听见了没，快别用阿妈的剑杀鸡了，以后还会用的，锈了怎么办。",
            ["ContentKR"] = "헐, 진짠가? 누나, 방금 들었지? 엄마 검으로 닭 잡지 말라니까. 나중에 써야 되는데 녹이라도 슬면 어떡해.",
            ["DialogueId"] = 80210134,
            ["FacialId"] = {
                [1] = "790065:CM_Happy01",
                },
            ["GUID"] = "C8CC331C",
            ["LookAt"] = {
                [1] = "790065:n(790066)",
                },
            ["NextDialogue"] = 80210135,
            ["SpeakNpcId"] = 790065,
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC331C",
            },
        [80210135] = {
            ["Camera"] = "33.960938,151.338867,112.264648,0.000069,-7.200624,-74.774574,35.000011,224.596802,false,Manual,2.8",
            ["Content"] = "一惊一乍的，以后的事，以后再说。",
            ["ContentKR"] = "뭘 그런 걸 걱정해, 그때 일은 그때 생각하면 되잖아.",
            ["DialogueId"] = 80210135,
            ["GUID"] = "C8CC3346",
            ["LookAt"] = {
                [1] = "790066:n(790065)",
                },
            ["NextDialogue"] = 80210136,
            ["SpeakNpcId"] = 790066,
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC3346",
            },
        [80210136] = {
            ["Camera"] = "71.171875,-18.830078,134.579102,0.000001,10.798099,59.223282,35.000011,265.938843,false,Manual,2.8",
            ["Content"] = "倒是这位大哥哥，不妨坐下来歇息一会儿再走？",
            ["ContentKR"] = "근데 아저씨야말로 이왕 오신 거, 좀 더 있다 가셔도 되지 않아요?",
            ["DialogueId"] = 80210136,
            ["FinalCamera"] = "71.171875,-18.830078,134.579102,0.0,10.798091,56.999958,35.000011,265.938843,false,Manual,2.8",
            ["GUID"] = "C8CC3370",
            ["LookAt"] = {
                [1] = "790065:n(790067)",
                [2] = "790066:n(790067)",
                },
            ["NextDialogue"] = 80210137,
            ["SpeakNpcId"] = 790066,
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC3370",
            },
        [80210137] = {
            ["Camera"] = "-152.511719,-805.267578,105.516602,0.000007,4.396415,73.174652,20.0,125.0,false,DoNotOverride,2.8",
            ["Content"] = "这可不行，我身后可是一直有一群小狗在追着，停留不得，就不打扰你们了。",
            ["ContentKR"] = "안 돼, 늑대 무리들이 내 뒤를 항상 쫓고 있거든. 괜히 여기 있다가 너희한테 귀찮은 일이 생길 수 있어.",
            ["DialogueId"] = 80210137,
            ["FacialId"] = {
                [1] = "790067:None",
                },
            ["FinalCamera"] = "-218.78125,-1024.449219,87.90332,0.000007,4.396415,73.174652,20.0,125.0,false,DoNotOverride,2.8",
            ["GUID"] = "C8CC339A",
            ["Scripts"] = "MoveTo{ActorId{790067},TargetPoint{\"BP_NewTargetPoint_150301\"},MoveSpeed{150}}",
            ["SpeakNpcId"] = 790067,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC339A",
            },
        [80210201] = {
            ["Camera"] = "-3911.427734,-2583.495605,1694.981445,0.000021,-15.999539,41.210613,30.000002,5058.067383,false,Manual,2.8",
            ["Content"] = "侠客爱憎分明，情天恨海，是非多多。更有好事者把这些纠缠写成书册，人人爱看。",
            ["ContentKR"] = "협객은 좋고 싫음이 분명하고 감정이 확실하며, 사연도 갈등도 많다. 호사가들은 이런 내용을 모두가 즐겨 읽는 책으로 엮는다.",
            ["DialogueId"] = 80210201,
            ["FinalCamera"] = "-3781.285156,-2732.086426,1694.981445,0.000021,-15.999539,41.210613,30.000002,5058.067383,false,Manual,2.8",
            ["GUID"] = "C8CC3E1A",
            ["NextDialogue"] = 80210202,
            ["Scripts"] = "PlayOrStopBGM{PlayType{\"Play\"},SoundPriority{\"Invite\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"}}",
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC3E1A",
            },
        [80210202] = {
            ["Content"] = "人人皆向往能策马红尘，但身在其中者，往往是另外一番愁滋味。",
            ["ContentKR"] = "사람들은 누구나 자유로운 삶을 동경하지만, 그 안에는 또 다른 아픔이 있다.",
            ["DialogueId"] = 80210202,
            ["GUID"] = "C8CC3E44",
            ["NextDialogue"] = 80210203,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC3E44",
            },
        [80210203] = {
            ["Camera"] = "-212.583984,65.048096,167.224609,0.000083,-6.598106,-14.604714,33.0,343.677704,false,Manual,3.0",
            ["Content"] = "你回来了，鸣鸾。",
            ["ContentKR"] = "돌아왔구나, 난명 형.",
            ["DialogueId"] = 80210203,
            ["FacialId"] = {
                [1] = "790067:Smile01",
                },
            ["FinalCamera"] = "-214.660156,57.06543,167.224609,0.000083,-6.598106,-14.604714,33.0,343.677704,false,Manual,3.0",
            ["GUID"] = "C8CC3E6E",
            ["LookAt"] = {
                [1] = "790067:n(790068)",
                [2] = "790068:n(790067)",
                },
            ["NextDialogue"] = 80210204,
            ["Scripts"] = "PlayOrStopBGM{PlayType{\"Stop\"},SoundPriority{\"Invite\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"}}",
            ["SpeakNpcId"] = 790067,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC3E6E",
            },
        [80210204] = {
            ["Camera"] = "150.619141,-184.330078,170.381836,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
            ["Content"] = "我回来了，刻舟。",
            ["ContentKR"] = "돌아왔다, 각주.",
            ["DialogueId"] = 80210204,
            ["FacialId"] = {
                [1] = "790068:CM_Smile01",
                },
            ["FinalCamera"] = "134.451172,-164.355713,167.136719,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
            ["GUID"] = "C8CC3E98",
            ["NextDialogue"] = 80210205,
            ["SpeakNpcId"] = 790068,
            ["TalkActionId"] = {
                [1] = "790068:Agree",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC3E98",
            },
        [80210205] = {
            ["Camera"] = "-461.167969,-98.087646,206.131836,0.000101,-12.798893,15.005779,20.0,592.475586,false,Manual,4.0",
            ["Content"] = "那么结果呢？",
            ["ContentKR"] = "성과는?",
            ["DialogueId"] = 80210205,
            ["FinalCamera"] = "-361.898438,-71.477051,182.797852,0.0001,-12.798893,15.006591,20.0,592.475586,false,Manual,4.0",
            ["GUID"] = "C8CC3EC2",
            ["NextDialogue"] = 80210206,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Talk02_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC3EC2",
            },
        [80210206] = {
            ["Content"] = "自然是有一些的。",
            ["ContentKR"] = "물론 있지.",
            ["DialogueId"] = 80210206,
            ["GUID"] = "C8CC3EEC",
            ["NextDialogue"] = 80210207,
            ["SpeakNpcId"] = 790068,
            ["TalkActionId"] = {
                [1] = "790068:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC3EEC",
            },
        [80210207] = {
            ["Camera"] = "109.556641,-109.840332,171.128906,0.000122,-10.598042,137.795868,20.0,275.546844,false,Manual,4.0",
            ["Content"] = "我踏足了五个国家，悟出了五门新功夫。",
            ["ContentKR"] = "다섯 나라를 돌며, 다섯 가지 무공을 터득했어.",
            ["DialogueId"] = 80210207,
            ["FinalCamera"] = "32.886719,-42.50415,154.229492,0.000131,-5.197801,142.396057,20.0,155.23967,false,Manual,4.0",
            ["GUID"] = "C8CC3F16",
            ["NextDialogue"] = 80210208,
            ["SpeakNpcId"] = 790068,
            ["ToFinalCameraBlendTime"] = 30,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC3F16",
            },
        [80210208] = {
            ["Camera"] = "1812.060547,3093.102783,-750.477539,0.000029,8.600014,158.03595,15.133835,13322.412109,false,Manual,4.0",
            ["Content"] = "我先是西出了华胥，踏入了赫墨的瀚海。",
            ["ContentKR"] = "먼저 화서를 나와 서쪽 케메트의 한해에 갔었지.",
            ["DialogueId"] = 80210208,
            ["FinalCamera"] = "1251.640625,3319.118652,-659.09082,0.000029,8.600014,158.03595,15.133835,13322.412109,false,Manual,4.0",
            ["GUID"] = "C8CC3F40",
            ["NextDialogue"] = 80210209,
            ["SpeakNpcId"] = 790068,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC3F40",
            },
        [80210209] = {
            ["Camera"] = "-1200.404297,23490.853516,354.0,0.000031,0.0,-70.761887,15.133835,13322.412109,false,Manual,4.0",
            ["Content"] = "之前我听人说赫墨的瀚海是万里黄沙，酷热无比。于是便拿定主意，夜半披星赶路。",
            ["ContentKR"] = "케메트의 한해는 끝없이 이어진 모래사막인데, 아주 무덥다더군. 그래서 밤길을 달려서 가기로 했지.",
            ["DialogueId"] = 80210209,
            ["FinalCamera"] = "-1074.800781,23130.9375,354.0,0.000031,0.0,-70.761887,15.133835,13322.412109,false,Manual,4.0",
            ["GUID"] = "C8CC3F6A",
            ["NextDialogue"] = 80210210,
            ["SpeakNpcId"] = 790068,
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC3F6A",
            },
        [80210210] = {
            ["Content"] = "但我没料到夜半的沙漠却又奇寒无比，如果不做些什么必将冻毙其中，成为一具无名的白骨。",
            ["ContentKR"] = "그런데 한밤중의 사막은 엄청나게 춥다는 걸 몰랐다. 거기 가만히 있다간, 이름 모를 시체로 꽁꽁 얼어 죽을 것 같았어.",
            ["DialogueId"] = 80210210,
            ["GUID"] = "C8CC3F94",
            ["NextDialogue"] = 80210211,
            ["SpeakNpcId"] = 790068,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC3F94",
            },
        [80210211] = {
            ["Camera"] = "-23017.669922,21547.728516,8057.0,0.000038,14.399909,168.238129,22.934771,13322.412109,false,Manual,4.0",
            ["Content"] = "正当我烦恼该如何自救之时，我看到远处的地平上有几颗绿星忽闪忽闪，却又渐渐变大。",
            ["ContentKR"] = "그래서 어떡해야 하나 하고 고민하는데, 멀리 지평선 가까이에서 녹색 별 몇 개가 깜빡이더군. 그리고 그 별이 점점 더 커지는 게 보였지.",
            ["DialogueId"] = 80210211,
            ["FinalCamera"] = "-23384.009766,19835.208984,8057.0,0.000038,14.399909,166.236816,22.934771,13322.412109,false,Manual,4.0",
            ["GUID"] = "C8CC3FBE",
            ["NextDialogue"] = 80210212,
            ["SpeakNpcId"] = 790068,
            ["TalkActionId"] = {
                [1] = "790067:Talk02_End",
                },
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC3FBE",
            },
        [80210212] = {
            ["Content"] = "那些绿星都是成对的，并且远远地也能透着股肃杀之气，像是典籍上提到的贪狼星。我突然醒悟过来，这并非是什么星星，而是狼的眼睛。",
            ["ContentKR"] = "녹색 별들은 두 개씩 짝을 지어 있었는데, 멀리서도 스산한 기운이 느껴지는 게, 꼭 경서에 나오는 탐랑성 같더군. 그러다 정신이 번쩍 들었지. 그건 별이 아니라 늑대의 눈이었던 거야.",
            ["DialogueId"] = 80210212,
            ["GUID"] = "C8CC3FE8",
            ["NextDialogue"] = 80210213,
            ["SpeakNpcId"] = 790068,
            ["TalkActionId"] = {
                [1] = "790068:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC3FE8",
            },
        [80210213] = {
            ["Camera"] = "-31.490234,-67.365234,193.577148,0.000082,-19.79907,13.007189,30.000008,125.0,false,Manual,2.8",
            ["Content"] = "可怜。",
            ["ContentKR"] = "안됐네.",
            ["DialogueId"] = 80210213,
            ["GUID"] = "C8CC4012",
            ["NextDialogue"] = 80210214,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC4012",
            },
        [80210214] = {
            ["Camera"] = "-461.167969,-98.087646,206.131836,0.000101,-12.798893,15.005779,20.0,592.475586,false,Manual,4.0",
            ["Content"] = "谁可怜。",
            ["ContentKR"] = "누가.",
            ["DialogueId"] = 80210214,
            ["FinalCamera"] = "-425.052734,-189.832764,206.131836,0.000102,-12.998901,25.60441,20.0,592.475586,false,Manual,4.0",
            ["GUID"] = "C8CC403C",
            ["NextDialogue"] = 80210215,
            ["SpeakNpcId"] = 790068,
            ["TalkActionId"] = {
                [1] = "790068:Talk03_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC403C",
            },
        [80210215] = {
            ["Content"] = "自然不是你可怜。",
            ["ContentKR"] = "당연히 형은 아니지.",
            ["DialogueId"] = 80210215,
            ["GUID"] = "C8CC4066",
            ["NextDialogue"] = 80210216,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC4066",
            },
        [80210216] = {
            ["Camera"] = "150.619141,-184.330078,170.381836,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
            ["Content"] = "那你错怪我了，那些小狗崽子安然无恙，我只是拍晕了几只，把它们拖到沙丘的背风处，当做垫背，靠着它们的体温囫囵了一个晚上。",
            ["ContentKR"] = "잘못 짚었어, 녀석들은 멀쩡하거든. 난 그냥 몇 놈을 기절시켜서, 깔개로 삼았을 뿐이야. 그다음에 바람이 닿지 않는 모래 언덕 뒤쪽으로 녀석들을 끌고 와서, 밤새 꼭 끌어안고 체온을 좀 빌렸지.",
            ["DialogueId"] = 80210216,
            ["FinalCamera"] = "134.451172,-164.355713,167.136719,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
            ["GUID"] = "C8CC4090",
            ["NextDialogue"] = 80210217,
            ["SpeakNpcId"] = 790068,
            ["TalkActionId"] = {
                [1] = "790068:Disagree",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC4090",
            },
        [80210217] = {
            ["Content"] = "了结它们倒也不难，但真要如此的话，我活不过第一个晚上。",
            ["ContentKR"] = "그 녀석들 처리하는 것쯤이야 별일 아니지만, 그랬다면 첫날 밤을 버티지 못했을 테니까.",
            ["DialogueId"] = 80210217,
            ["GUID"] = "C8CC40BA",
            ["NextDialogue"] = 80210218,
            ["SpeakNpcId"] = 790068,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC40BA",
            },
        [80210218] = {
            ["Camera"] = "-31.490234,-67.365234,193.577148,0.000083,-19.79907,13.007248,30.000008,125.0,false,Manual,2.8",
            ["Content"] = "于你来说，几只野狼自然不是对手，但是我记得你的掌风素来刚猛凌厉，号称降龙，没想到居然能控制到恰好击晕活物而留其性命的地步。",
            ["ContentKR"] = "늑대 따위가 형의 상대일 리 있겠어. 다만 형의 장풍은 '용의 강림'이라 불릴 정도로 매서웠던 걸로 기억하는데, 살아있는 짐승을 목숨만 붙여놓는 정도로도 구사할 수 있는 줄은 몰랐네.",
            ["DialogueId"] = 80210218,
            ["FinalCamera"] = "-29.367188,-76.549561,193.577148,0.000083,-19.79907,13.007559,30.000008,125.0,false,Manual,2.8",
            ["GUID"] = "C8CC40E4",
            ["NextDialogue"] = 80210219,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Talk01_Start",
                },
            ["ToFinalCameraBlendTime"] = 12,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC40E4",
            },
        [80210219] = {
            ["Content"] = "这应该便是你悟出的第一门功夫吧。",
            ["ContentKR"] = "그게 형이 터득한 첫 번째 무공인가 보지?",
            ["DialogueId"] = 80210219,
            ["GUID"] = "C8CC410E",
            ["NextDialogue"] = 80210220,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC410E",
            },
        [80210220] = {
            ["Camera"] = "150.619141,-184.330078,170.381836,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
            ["Content"] = "不愧是刻舟刻大侠，立刻意识到关节所在。在那过后每晚我都是如此过夜，击晕野狼取暖。从而悟出了一套新的掌法，我称之为狼眠掌。",
            ["ContentKR"] = "역시 우리 각주 대협답게 핵심을 바로 알아채는군. 그 후 난 매일 밤 늑대를 죽지 않을 정도로만 기절시켜, 녀석들의 온기로 밤을 보냈다. 그러면서 '낭면장'이라는 새로운 장법도 터득했지.",
            ["DialogueId"] = 80210220,
            ["FinalCamera"] = "134.451172,-164.355713,167.136719,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
            ["GUID"] = "C8CC4138",
            ["NextDialogue"] = 80210221,
            ["SpeakNpcId"] = 790068,
            ["TalkActionId"] = {
                [1] = "790068:Agree",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC4138",
            },
        [80210221] = {
            ["Camera"] = "-212.583984,65.048096,167.224609,0.000083,-6.598106,-14.604714,33.0,343.677704,false,Manual,3.0",
            ["Content"] = "好，好个狼眠掌，当浮一大白。",
            ["ContentKR"] = "이야, 낭면장이라니! 한 잔 해야겠는걸.",
            ["DialogueId"] = 80210221,
            ["FacialId"] = {
                [1] = "790067:Smile02",
                },
            ["FinalCamera"] = "-156.203125,50.284424,160.674805,0.000084,-5.398062,-15.405737,33.0,343.677704,false,Manual,3.0",
            ["GUID"] = "C8CC4162",
            ["NextDialogue"] = 80210222,
            ["SpeakNpcId"] = 790067,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC4162",
            },
        [80210222] = {
            ["Content"] = "那么第二门功夫，应当就是在海伯利亚帝国了。让我猜猜你悟出了什么……有类迅捷剑术的快剑？还是如同冰湖城坚冰一样厚重的长拳？",
            ["ContentKR"] = "그렇다면 두 번째 무공은 휘페르보레아 제국이겠군. 내가 한 번 맞춰볼까... 빠르고 날렵한 쾌검인가? 아니면 아이스레이크 시티의 얼음처럼 묵직한 장권?",
            ["DialogueId"] = 80210222,
            ["GUID"] = "C8CC418C",
            ["NextDialogue"] = 80210223,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC418C",
            },
        [80210223] = {
            ["Camera"] = "371.589844,-637.212402,325.822266,0.000051,-17.998013,119.596794,33.0,1098.901978,false,Manual,3.0",
            ["Content"] = "想不到你人一直在华胥，却还知道海伯利亚还有个冰湖城。",
            ["ContentKR"] = "쭉 화서에 있었던 네가 휘페르보레아 제국의 아이스레이크 시티를 알 줄은 몰랐는데.",
            ["DialogueId"] = 80210223,
            ["FinalCamera"] = "305.197266,-520.310547,282.146484,0.000051,-17.998013,119.596794,33.0,1098.901978,false,Manual,3.0",
            ["GUID"] = "C8CC41B6",
            ["NextDialogue"] = 80210224,
            ["SpeakNpcId"] = 790068,
            ["ToFinalCameraBlendTime"] = 30,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC41B6",
            },
        [80210224] = {
            ["Content"] = "最近交了个朋友，在冰湖城居住，所以多少知道一些。",
            ["ContentKR"] = "최근에 아이스레이크 시티에 사는 친구를 하나 사귄 덕에, 얘기를 좀 들었지.",
            ["DialogueId"] = 80210224,
            ["FacialId"] = {
                [1] = "790067:Smile01",
                },
            ["GUID"] = "C8CC41E0",
            ["NextDialogue"] = 80210225,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC41E0",
            },
        [80210225] = {
            ["Content"] = "原来如此，不过你猜错了，我着急赶路，直接去了卢卡。",
            ["ContentKR"] = "그랬군. 하지만 잘못 짚었어. 난 그 길로 루카 공화국까지 바로 갔거든.",
            ["DialogueId"] = 80210225,
            ["GUID"] = "C8CC420A",
            ["NextDialogue"] = 80210226,
            ["SpeakNpcId"] = 790068,
            ["TalkActionId"] = {
                [1] = "790067:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC420A",
            },
        [80210226] = {
            ["Content"] = "在前往卢卡的路上，我遭遇了传说中的海中精怪，被称作塞壬的异兽。它们貌似婵娟，但是却能以歌声摄人心魄。",
            ["ContentKR"] = "루카로 가는 길에 전설 속의 바닷속 요괴와 마주쳤다. 세이렌이라는 이름이더군. 아름다운 얼굴을 하고 있지만, 노랫소리로 인간의 영혼을 삼키는 괴물이었지.",
            ["DialogueId"] = 80210226,
            ["GUID"] = "C8CC4234",
            ["NextDialogue"] = 80210227,
            ["SpeakNpcId"] = 790068,
            ["TalkActionId"] = {
                [1] = "790068:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC4234",
            },
        [80210227] = {
            ["Camera"] = "-31.490234,-67.365234,193.577148,0.000082,-19.79907,13.007189,30.000008,125.0,false,Manual,2.8",
            ["Content"] = "那岂不是和百年前的前辈莫抱琴一般，能以传音入密的功夫乱人心神？",
            ["ContentKR"] = "백 년 전의 선조 막포금과 비슷한 것 같은데. 전음술로 상대의 정신을 어지럽히는 건가?",
            ["DialogueId"] = 80210227,
            ["GUID"] = "C8CC425E",
            ["NextDialogue"] = 80210228,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790068:Talk03_End",
                },
            ["ToFinalCameraBlendTime"] = 7,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC425E",
            },
        [80210228] = {
            ["Camera"] = "150.619141,-184.330078,170.381836,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
            ["Content"] = "确实如出一辙。只是我当时没有想到这些，只顾着跳入水中，闭息凝神，又抓住了路过的巨鲸，才堪堪逃得性命。",
            ["ContentKR"] = "확실히 거의 똑같지. 다만 그때 난 거기까진 생각 못 하고, 물속으로 곧장 뛰어들어, 숨을 참고 정신을 똑바로 차리려고 애썼다. 그러다 지나가던 바하무트를 붙잡고 간신히 도망쳤지.",
            ["DialogueId"] = 80210228,
            ["FinalCamera"] = "134.451172,-164.355713,167.136719,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
            ["GUID"] = "C8CC4288",
            ["NextDialogue"] = 80210229,
            ["SpeakNpcId"] = 790068,
            ["TalkActionId"] = {
                [1] = "790068:Agree",
                },
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC4288",
            },
        [80210229] = {
            ["Content"] = "但也因此，我的闭气功夫见长不少，几乎不再惧怕毒雾之类的雕虫小技。而我将这套法门唤作长鲸心法。",
            ["ContentKR"] = "하지만 덕분에 폐기 무공이 크게 늘어서, 독 안개 같은 잔재주는 거의 겁내지 않게 됐다. 난 이 법술을 장경심법이라고 부르기로 했지.",
            ["DialogueId"] = 80210229,
            ["GUID"] = "C8CC42B2",
            ["NextDialogue"] = 80210230,
            ["SpeakNpcId"] = 790068,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC42B2",
            },
        [80210230] = {
            ["Content"] = "然后呢？",
            ["ContentKR"] = "그다음엔?",
            ["DialogueId"] = 80210230,
            ["GUID"] = "C8CC42DC",
            ["NextDialogue"] = 80210231,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC42DC",
            },
        [80210231] = {
            ["Content"] = "我在卢卡也没有停留太久，于是去了传颂会的雅什尼亚，在那里我……",
            ["ContentKR"] = "루카 공화국에는 오래 머무르지 않고, 교회의 야슈니아로 갔다. 거기서...",
            ["DialogueId"] = 80210231,
            ["GUID"] = "C8CC4306",
            ["NextDialogue"] = 80210232,
            ["SpeakNpcId"] = 790068,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC4306",
            },
        [80210232] = {
            ["Camera"] = "-214.660156,57.06543,167.224609,0.000083,-6.598106,-14.604714,33.0,343.677704,false,Manual,3.0",
            ["Content"] = "稍等，我打断一下。",
            ["ContentKR"] = "잠깐, 말 좀 끊어도 될까.",
            ["DialogueId"] = 80210232,
            ["FacialId"] = {
                [1] = "790067:None",
                },
            ["GUID"] = "C8CC4330",
            ["NextDialogue"] = 80210233,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790068:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC4330",
            },
        [80210233] = {
            ["Content"] = "你可以打断，但需要自罚一杯。",
            ["ContentKR"] = "안 될 거 있나, 대신 벌주 한 잔만 마신다면야.",
            ["DialogueId"] = 80210233,
            ["GUID"] = "C8CC435A",
            ["NextDialogue"] = 80210234,
            ["SpeakNpcId"] = 790068,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC435A",
            },
        [80210234] = {
            ["Content"] = "罚就罚，没问题，我只是想问你，她呢？你最终找到她了吗？",
            ["ContentKR"] = "벌주야 마시면 그만이지. 내가 묻고 싶은 건... 결국 그녀는 찾았어?",
            ["DialogueId"] = 80210234,
            ["GUID"] = "C8CC4384",
            ["NextDialogue"] = 80210235,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC4384",
            },
        [80210235] = {
            ["Camera"] = "-54.832031,-48.86377,169.512695,0.000115,-10.397644,109.791862,20.0,116.948799,false,Manual,4.0",
            ["Content"] = "……",
            ["ContentKR"] = "......",
            ["DialogueId"] = 80210235,
            ["FacialId"] = {
                [1] = "790068:CM_Idle",
                },
            ["GUID"] = "C8CC43AE",
            ["NextDialogue"] = 80210236,
            ["SpeakNpcId"] = 790068,
            ["TalkActionId"] = {
                [1] = "790068:Confident_End",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC43AE",
            },
        [80210236] = {
            ["Camera"] = "-31.490234,-67.365234,193.577148,0.000082,-19.79907,13.007189,30.000008,125.0,false,Manual,2.8",
            ["Content"] = "你说过，不找到她是不会回华胥的。",
            ["ContentKR"] = "그녀를 찾지 못하면 화서에 돌아오지 않겠다고 했잖아.",
            ["DialogueId"] = 80210236,
            ["FinalCamera"] = "-22.458984,-65.278564,190.244141,0.000084,-19.79907,13.007616,30.000008,115.331322,false,Manual,2.8",
            ["GUID"] = "C8CC43D8",
            ["NextDialogue"] = 80210237,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Talk01_End",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC43D8",
            },
        [80210237] = {
            ["Camera"] = "150.619141,-184.330078,170.381836,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
            ["Content"] = "我累了。",
            ["ContentKR"] = "지쳤다.",
            ["DialogueId"] = 80210237,
            ["FacialId"] = {
                [1] = "790068:CM_Sad01",
                },
            ["FinalCamera"] = "134.451172,-164.355713,167.136719,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
            ["GUID"] = "C8CC4402",
            ["NextDialogue"] = 80210238,
            ["SpeakNpcId"] = 790068,
            ["TalkActionId"] = {
                [1] = "790068:Disagree",
                },
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC4402",
            },
        }
  end },
  { MinKey = 80210238, MaxKey = 80220205, Loader = function()
      return {
        [80210238] = {
            ["Content"] = "我无时无刻不在想着她。沙砾里，海浪里，森林里，圣塔旁，絮语河上，我都寻觅过她，但是却又寻她不见。",
            ["ContentKR"] = "매일 같이 그녀만 생각했어. 모래바람 속에서도, 파도 속에서도, 숲에서도, 성탑에서도, 속삭임 강에서도... 하지만 찾을 수 없었지.",
            ["DialogueId"] = 80210238,
            ["GUID"] = "C8CC442C",
            ["NextDialogue"] = 80210239,
            ["SpeakNpcId"] = 790068,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC442C",
            },
        [80210239] = {
            ["Content"] = "于是我在想，她会不会是回到了华胥这个伤心地。但，依旧没有人见过她。",
            ["ContentKR"] = "그래서 난 그녀가 그 상처 입은 땅, 화서로 돌아온 게 아닐까 생각했다. 하지만 봤다는 사람은 역시 없더군.",
            ["DialogueId"] = 80210239,
            ["GUID"] = "C8CC4456",
            ["NextDialogue"] = 80210240,
            ["SpeakNpcId"] = 790068,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC4456",
            },
        [80210240] = {
            ["Camera"] = "55.90625,-152.534912,193.577148,0.000092,-22.199057,72.007072,30.000013,109.656555,false,Manual,2.8",
            ["Content"] = "可怜。",
            ["ContentKR"] = "안됐네.",
            ["DialogueId"] = 80210240,
            ["FinalCamera"] = "57.841797,-147.262451,191.289062,0.000092,-22.199057,72.007072,30.000013,109.656555,false,Manual,2.8",
            ["GUID"] = "C8CC4480",
            ["NextDialogue"] = 80210241,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:DisagreeHead",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC4480",
            },
        [80210241] = {
            ["Camera"] = "118.96875,-145.442871,164.535156,0.000056,-5.398397,129.398148,33.0,376.434326,false,Manual,3.0",
            ["Content"] = "谁可怜。",
            ["ContentKR"] = "누가.",
            ["DialogueId"] = 80210241,
            ["FinalCamera"] = "107.117188,-131.01001,162.773438,0.000061,-5.398397,129.398041,33.0,376.434326,false,Manual,3.0",
            ["GUID"] = "C8CC44AA",
            ["NextDialogue"] = 80210242,
            ["SpeakNpcId"] = 790068,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC44AA",
            },
        [80210242] = {
            ["Camera"] = "-2.816406,-67.810547,183.550781,0.000092,-19.198992,12.008528,30.000008,92.276848,false,Manual,2.8",
            ["Content"] = "天下有情人。",
            ["ContentKR"] = "세상의 모든 연인들.",
            ["DialogueId"] = 80210242,
            ["GUID"] = "C8CC44D4",
            ["NextDialogue"] = 80210243,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC44D4",
            },
        [80210243] = {
            ["Camera"] = "371.589844,-637.212402,325.822266,0.000051,-17.998013,119.596794,33.0,1098.901978,false,Manual,3.0",
            ["Content"] = "哈哈。",
            ["ContentKR"] = "하하.",
            ["DialogueId"] = 80210243,
            ["FacialId"] = {
                [1] = "790068:CM_Smile01",
                },
            ["FinalCamera"] = "305.197266,-520.310547,282.146484,0.000051,-17.998013,119.596794,33.0,1098.901978,false,Manual,3.0",
            ["GUID"] = "C8CC44FE",
            ["NextDialogue"] = 80210244,
            ["SpeakNpcId"] = 790068,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC44FE",
            },
        [80210244] = {
            ["Content"] = "要说可怜，你也同样，我远离华胥不受大风九章羁绊，而你的话，恐怕在来见我之前，刚刚和应天尉交过手吧。",
            ["ContentKR"] = "불쌍한 건 너도 마찬가지지. 난 화서를 떠나서, 대풍구장의 속박을 받지 않지만, 넌 날 만나기 전까지만 해도 응천위하고 한바탕하고 있었잖아.",
            ["DialogueId"] = 80210244,
            ["GUID"] = "C8CC4528",
            ["NextDialogue"] = 80210245,
            ["SpeakNpcId"] = 790068,
            ["TalkActionId"] = {
                [1] = "790068:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC4528",
            },
        [80210245] = {
            ["Camera"] = "-212.583984,65.048096,167.224609,0.000083,-6.598106,-14.604714,33.0,343.677704,false,Manual,3.0",
            ["Content"] = "那是自然，但也早就习惯如此了，正如你习惯了漂泊异乡一样。",
            ["ContentKR"] = "아무렴. 하지만 다 익숙해졌어. 형이 타향을 떠도는 데 익숙해진 것처럼 말이지.",
            ["DialogueId"] = 80210245,
            ["FinalCamera"] = "-214.660156,57.06543,167.224609,0.000083,-6.598106,-14.604714,33.0,343.677704,false,Manual,3.0",
            ["GUID"] = "C8CC4552",
            ["NextDialogue"] = 80210246,
            ["SpeakNpcId"] = 790067,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC4552",
            },
        [80210246] = {
            ["Camera"] = "150.619141,-184.330078,170.381836,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
            ["Content"] = "刚刚你打断我的话，罚酒一杯，该喝了。等你喝完我就上路继续找她，这次我反其道行之，先从海路到伊瑟尔。",
            ["ContentKR"] = "방금 내 말을 끊은 벌주나 얼른 마셔라. 네가 그 잔을 비우면 난 다시 그녀를 찾으러 떠나야 하니 말이야. 이번엔 반대로, 바닷길로 이스엘에 갈 생각이다.",
            ["DialogueId"] = 80210246,
            ["FinalCamera"] = "134.451172,-164.355713,167.136719,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
            ["GUID"] = "C8CC457C",
            ["NextDialogue"] = 80210247,
            ["SpeakNpcId"] = 790068,
            ["TalkActionId"] = {
                [1] = "790068:Talk01_End",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC457C",
            },
        [80210247] = {
            ["Camera"] = "-461.167969,-98.087646,206.131836,0.000101,-12.798893,15.005779,20.0,592.475586,false,Manual,4.0",
            ["Content"] = "我刚刚已经罚完了。",
            ["ContentKR"] = "벌주는 아까 마셨는데.",
            ["DialogueId"] = 80210247,
            ["FinalCamera"] = "-425.052734,-189.832764,206.131836,0.000102,-12.998901,25.60441,20.0,592.475586,false,Manual,4.0",
            ["GUID"] = "C8CC45A6",
            ["NextDialogue"] = 80210248,
            ["SpeakNpcId"] = 790067,
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC45A6",
            },
        [80210248] = {
            ["Content"] = "什么时候？我怎么没瞧见。",
            ["ContentKR"] = "언제? 난 못 본 것 같은데.",
            ["DialogueId"] = 80210248,
            ["GUID"] = "C8CC45D0",
            ["NextDialogue"] = 80210249,
            ["SpeakNpcId"] = 790068,
            ["TalkActionId"] = {
                [1] = "790068:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC45D0",
            },
        [80210249] = {
            ["Content"] = "在你说到圣塔旁，絮语河上的时候。",
            ["ContentKR"] = "형이 성탑과 속삭임 강을 이야기할 때 마셨지.",
            ["DialogueId"] = 80210249,
            ["GUID"] = "C8CC45FA",
            ["NextDialogue"] = 80210250,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC45FA",
            },
        [80210250] = {
            ["Content"] = "真的假的？唉，可能是我太想见她了。",
            ["ContentKR"] = "그랬나? 후, 그녀 생각을 하느라 못 봤나 보군.",
            ["DialogueId"] = 80210250,
            ["GUID"] = "C8CC4624",
            ["NextDialogue"] = 80210251,
            ["SpeakNpcId"] = 790068,
            ["TalkActionId"] = {
                [1] = "790068:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC4624",
            },
        [80210251] = {
            ["Camera"] = "-31.490234,-67.365234,193.577148,0.000082,-19.79907,13.007189,30.000008,125.0,false,Manual,2.8",
            ["Content"] = "骗你的，我还没喝。",
            ["ContentKR"] = "형은 그걸 믿냐? 안 마셨어.",
            ["DialogueId"] = 80210251,
            ["FacialId"] = {
                [1] = "790067:Smile01",
                },
            ["GUID"] = "C8CC464E",
            ["NextDialogue"] = 80210252,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC464E",
            },
        [80210252] = {
            ["Camera"] = "32.886719,-42.50415,154.229492,0.000131,-5.197801,142.396057,20.0,155.23967,false,Manual,4.0",
            ["Content"] = "你小子，从小就喜欢骗人，一直没变。",
            ["ContentKR"] = "넌 어릴 때부터 그렇게 거짓말을 좋아하더니, 변하지도 않는구나.",
            ["DialogueId"] = 80210252,
            ["GUID"] = "C8CC4678",
            ["NextDialogue"] = 80210253,
            ["SpeakNpcId"] = 790068,
            ["TalkActionId"] = {
                [1] = "790067:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC4678",
            },
        [80210253] = {
            ["Camera"] = "-212.583984,65.048096,167.224609,0.000083,-6.598106,-14.604714,33.0,343.677704,false,Manual,3.0",
            ["Content"] = "而你就没有识破的时候。",
            ["ContentKR"] = "그리고 형은 항상 속아 넘어갔지.",
            ["DialogueId"] = 80210253,
            ["FinalCamera"] = "-246.677734,73.932129,171.296875,0.000083,-6.598113,-14.604773,33.0,343.677704,false,Manual,3.0",
            ["GUID"] = "C8CC46A2",
            ["NextDialogue"] = 80210254,
            ["SpeakNpcId"] = 790067,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC46A2",
            },
        [80210254] = {
            ["Content"] = "哈哈哈哈。",
            ["ContentKR"] = "하하하하하.",
            ["DialogueId"] = 80210254,
            ["FacialId"] = {
                [1] = "790067:Smile02",
                },
            ["GUID"] = "C8CC46CC",
            ["NextDialogue"] = 80210255,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790068:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC46CC",
            },
        [80210255] = {
            ["Camera"] = "-17.587891,-73.812012,162.646484,0.000131,-7.797698,121.197479,20.0,155.23967,false,Manual,4.0",
            ["Content"] = "那么，我出发了，后会有期。",
            ["ContentKR"] = "그럼 난 이만 가야겠다. 다음에 또 보자.",
            ["DialogueId"] = 80210255,
            ["FacialId"] = {
                [1] = "790068:CM_Idle",
                },
            ["GUID"] = "C8CC46F6",
            ["NextDialogue"] = 80210256,
            ["SpeakNpcId"] = 790068,
            ["TalkActionId"] = {
                [1] = "790068:Salute_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC46F6",
            },
        [80210256] = {
            ["Camera"] = "-786.357422,-477.311035,427.586914,0.000243,-19.797138,31.996326,20.0,1022.357056,false,Manual,4.0",
            ["Content"] = "后会有期。",
            ["ContentKR"] = "나중에 또 봐.",
            ["DialogueId"] = 80210256,
            ["FacialId"] = {
                [1] = "790067:None",
                },
            ["FinalCamera"] = "-968.662109,-591.214844,504.962891,0.000238,-17.997028,31.397633,20.0,1022.357056,false,Manual,4.0",
            ["GUID"] = "C8CC4720",
            ["LookAt"] = {
                [1] = "790068:n(790068)",
                },
            ["NextDialogue"] = 80210257,
            ["Scripts"] = "MoveTo{_delay{3},ActorId{790068},TargetPoint{\"BP_NewTargetPoint_15032\"},MoveSpeed{150},Visibility{\"Hide\"}}",
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790068:Salute_End",
                [2] = "790067:Story_HoldFist_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC4720",
            },
        [80210257] = {
            ["Content"] = "这第二位也就此离去……那么接下来是第三位。",
            ["ContentKR"] = "두 번째 사람도 이렇게 가버리는군... 그럼, 이제 세 번째 인물 차롄가.",
            ["DialogueId"] = 80210257,
            ["GUID"] = "C8CC474A",
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Story_HoldFist_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC474A",
            },
        [80210301] = {
            ["Camera"] = "-1168.496094,1264.441406,313.365234,0.000131,-4.398683,-49.787758,30.000002,1615.87854,false,Manual,2.8",
            ["Content"] = "侠客大多是吃主，玩主。想来也是正常的，好马，好剑，好衣裳，总是大侠的标配。",
            ["ContentKR"] = "놀 줄 알고, 먹을 줄 아는 자들이 협객이다. 생각해 보면 당연한 일이다. 좋은 말, 좋은 검, 좋은 옷은 대협의 기본이 아니던가?",
            ["DialogueId"] = 80210301,
            ["FacialId"] = {
                [1] = "790071:Smile01",
                },
            ["FinalCamera"] = "-1040.925781,1113.558594,298.16748,0.000131,-4.398683,-49.787758,30.000002,1361.954834,false,Manual,2.8",
            ["GUID"] = "C8CC4E82",
            ["LookAt"] = {
                [1] = "790071:n(790069)",
                [2] = "790069:n(790071)",
                },
            ["NextDialogue"] = 80210302,
            ["Scripts"] = "PlayAnimation{ActorId{790071},AnimationId{\"Sit_Idle_Loop\"},Sync{true}}",
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC4E82",
            },
        [80210302] = {
            ["Content"] = "至于酒食，更是极为精细。以至于提起侠客，总是感觉他们好酒，大块吃肉。而如果一个侠客明言不喝酒，就多少觉得他的剑意少了三分老辣。",
            ["ContentKR"] = "술과 음식 쪽엔 더욱 깐깐할 것이다. 협객이라면 당연히 두툼한 고기를 앞에 두고, 호쾌하게 술을 들이켜야 할 것 같다. 반대로, 술을 마다하는 협객이라면, 아무래도 검 끝의 날렵함이 부족하지 않을까.",
            ["DialogueId"] = 80210302,
            ["GUID"] = "C8CC4EAC",
            ["NextDialogue"] = 80210303,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC4EAC",
            },
        [80210303] = {
            ["Camera"] = "-235.25,3.191406,148.305176,0.000013,-19.999994,47.002541,20.0,187.784851,false,Manual,2.8",
            ["Content"] = "小二，一斤黄酒，七个油豆腐，辣酱要多！",
            ["ContentKR"] = "여기, 황주 한 근에 튀긴 두부 일곱 개! 고추기름은 넉넉하게 주게!",
            ["DialogueId"] = 80210303,
            ["FinalCamera"] = "-220.636719,18.855469,140.509766,0.000013,-19.999994,47.002541,20.0,169.81192,false,Manual,2.8",
            ["GUID"] = "C8CC4ED6",
            ["NextDialogue"] = 80210304,
            ["SpeakNpcId"] = 790071,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC4ED6",
            },
        [80210304] = {
            ["Camera"] = "-159.164062,204.953125,88.058105,0.000052,9.999997,-80.395218,20.0,169.81192,false,Manual,2.8",
            ["Content"] = "好嘞，我这就吩咐给您做。",
            ["ContentKR"] = "예, 알겠습니다.",
            ["DialogueId"] = 80210304,
            ["FinalCamera"] = "-156.535156,189.371094,90.843262,0.000052,9.999997,-80.395218,20.0,169.81192,false,Manual,2.8",
            ["GUID"] = "C8CC4F00",
            ["NextDialogue"] = 80210305,
            ["SpeakNpcId"] = 790069,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC4F00",
            },
        [80210305] = {
            ["Content"] = "一斤黄酒，七个油豆腐，辣酱要多！",
            ["ContentKR"] = "황주 한 근, 튀긴 두부 일곱 개, 고추기름 푸짐하게요!",
            ["DialogueId"] = 80210305,
            ["GUID"] = "C8CC4F2A",
            ["NextDialogue"] = 80210306,
            ["SpeakNpcId"] = 790069,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC4F2A",
            },
        [80210306] = {
            ["Camera"] = "-545.542969,-132.332031,36.390137,0.000018,6.600196,30.606834,20.0,466.554138,false,Manual,2.8",
            ["Content"] = "谢了。顺便问下，你可听说过一位飘零人，名唤铁掌移山刘纬甫，年纪应该有六七十了。",
            ["ContentKR"] = "고맙네. 근데 뭐 한 가지 물어봐도 될까? 철장이산 류위보라는 사람 들어본 적 있나? 나이는 예순은 족히 넘었을 거야.",
            ["DialogueId"] = 80210306,
            ["FinalCamera"] = "-444.984375,-72.832031,49.90918,0.00003,6.600196,30.607128,20.0,400.820953,false,Manual,2.8",
            ["GUID"] = "C8CC4F54",
            ["NextDialogue"] = 80210307,
            ["SpeakNpcId"] = 790071,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC4F54",
            },
        [80210307] = {
            ["Content"] = "没听说过。我这辈子都没见过飘零人呢。",
            ["ContentKR"] = "글쎄요, 전 평생 나그네라곤 만나본 적이 없는데요.",
            ["DialogueId"] = 80210307,
            ["GUID"] = "C8CC4F7E",
            ["NextDialogue"] = 80210308,
            ["SpeakNpcId"] = 790069,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC4F7E",
            },
        [80210308] = {
            ["Camera"] = "-194.460938,93.691406,125.272461,0.000011,-19.99996,37.409882,20.0,81.55352,false,Manual,2.8",
            ["Content"] = "那你现在见过了。",
            ["ContentKR"] = "그렇다면 지금 만난 것 같은데.",
            ["DialogueId"] = 80210308,
            ["FinalCamera"] = "-185.449219,100.574219,121.142578,0.000011,-19.99996,37.409882,20.0,81.55352,false,Manual,2.8",
            ["GUID"] = "C8CC4FA8",
            ["NextDialogue"] = 80210309,
            ["SpeakNpcId"] = 790071,
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC4FA8",
            },
        [80210309] = {
            ["Content"] = "您是飘零人？",
            ["ContentKR"] = "손님, 나그네세요?",
            ["DialogueId"] = 80210309,
            ["GUID"] = "C8CC4FD2",
            ["NextDialogue"] = 80210310,
            ["SpeakNpcId"] = 790069,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC4FD2",
            },
        [80210310] = {
            ["Content"] = "我是啊，怎么，看着不像？",
            ["ContentKR"] = "맞아. 왜, 그렇게 안 보이나?",
            ["DialogueId"] = 80210310,
            ["GUID"] = "C8CC4FFC",
            ["NextDialogue"] = 80210311,
            ["SpeakNpcId"] = 790071,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC4FFC",
            },
        [80210311] = {
            ["Camera"] = "-159.164062,204.953125,88.058105,0.000052,9.999997,-80.395218,20.0,169.81192,false,Manual,2.8",
            ["Content"] = "是不像，我听说飘零人啊都是喜欢大口喝酒大口吃肉的，没见过点油豆腐的。",
            ["ContentKR"] = "그럼요. 나그네들은 다들 고기반찬에 말술만 드신다고 들었거든요. 튀긴 두부를 시킨다는 얘긴 처음이네요.",
            ["DialogueId"] = 80210311,
            ["FinalCamera"] = "-156.535156,189.371094,90.843262,0.000052,9.999997,-80.395218,20.0,169.81192,false,Manual,2.8",
            ["GUID"] = "C8CC5026",
            ["NextDialogue"] = 80210312,
            ["SpeakNpcId"] = 790069,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC5026",
            },
        [80210312] = {
            ["Camera"] = "-235.25,3.191406,148.305176,0.000013,-19.999994,47.002541,20.0,187.784851,false,Manual,2.8",
            ["Content"] = "这叫什么话，飘零人又不是野狼野狗就爱吃肉，那吃得精细起来也是自有一套讲究的。",
            ["ContentKR"] = "그게 무슨 소리야. 굶주린 들개도 아니고 고기만 먹는다니. 음식도 제대로 먹으려면 신경 써야 할 게 많은 법이야.",
            ["DialogueId"] = 80210312,
            ["FinalCamera"] = "-220.636719,18.855469,140.509766,0.000013,-19.999994,47.002541,20.0,169.81192,false,Manual,2.8",
            ["GUID"] = "C8CC5050",
            ["NextDialogue"] = 80210313,
            ["SpeakNpcId"] = 790071,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC5050",
            },
        [80210313] = {
            ["Camera"] = "-545.542969,-132.332031,36.390137,0.000018,6.600196,30.606834,20.0,466.554138,false,Manual,2.8",
            ["Content"] = "那野狼野狗也不止吃肉，还吃其他东西呢……",
            ["ContentKR"] = "그렇게 따지자면, 들개도 고기만 먹는 건 아닌데요...",
            ["DialogueId"] = 80210313,
            ["FinalCamera"] = "-462.796875,-83.355469,47.517578,0.0,6.600196,30.608337,20.0,466.554138,false,Manual,2.8",
            ["GUID"] = "C8CC507A",
            ["NextDialogue"] = 80210314,
            ["SpeakNpcId"] = 790069,
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC507A",
            },
        [80210314] = {
            ["Content"] = "打住，打住，我油豆腐好没？帮我催一催。",
            ["ContentKR"] = "그만, 그만. 튀긴 두부는 아직 멀었나? 왜 이리 늦어.",
            ["DialogueId"] = 80210314,
            ["GUID"] = "C8CC50A4",
            ["NextDialogue"] = 80210315,
            ["SpeakNpcId"] = 790071,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC50A4",
            },
        [80210315] = {
            ["Content"] = "得嘞，卯金叔，油豆腐快点。",
            ["ContentKR"] = "앗, 네. 묘금 아저씨, 여기 튀긴 두부 빨리요.",
            ["DialogueId"] = 80210315,
            ["GUID"] = "C8CC50CE",
            ["NextDialogue"] = 80210316,
            ["SpeakNpcId"] = 790069,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC50CE",
            },
        [80210316] = {
            ["Content"] = "莫催莫催，就好了。",
            ["ContentKR"] = "아따, 거 보채기는. 금방 나간다.",
            ["DialogueId"] = 80210316,
            ["GUID"] = "C8CC50F8",
            ["NextDialogue"] = 80210317,
            ["SpeakNpcId"] = 790070,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC50F8",
            },
        [80210317] = {
            ["Camera"] = "-159.164062,204.953125,88.058105,0.000052,9.999997,-80.395218,20.0,169.81192,false,Manual,2.8",
            ["Content"] = "行。客官您再等等。不过，刚刚您说飘零人吃起来自有一套，要不多讲讲呗，反正现在店里也没人，想听。",
            ["ContentKR"] = "손님, 좀 더 기다리셔야 할 것 같은데요. 근데 아까 나그네는 음식을 먹을 때도 따져야 할 게 많다고 하셨죠? 어차피 손님도 없는데 더 자세히 좀 얘기해 주시죠.",
            ["DialogueId"] = 80210317,
            ["FinalCamera"] = "-156.535156,189.371094,90.843262,0.000052,9.999997,-80.395218,20.0,169.81192,false,Manual,2.8",
            ["GUID"] = "C8CC5122",
            ["NextDialogue"] = 80210318,
            ["SpeakNpcId"] = 790069,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC5122",
            },
        [80210318] = {
            ["Camera"] = "-235.25,3.191406,148.305176,0.000013,-19.999994,47.002541,20.0,187.784851,false,Manual,2.8",
            ["Content"] = "也罢，我今天来找的这位飘零人前辈，当年也以做得一手好菜闻名，被称作庖侠。",
            ["ContentKR"] = "안 될 거 없지. 안 그래도 내가 찾는 그 나그네 선배도, 주방 대협이라고 불리실 만큼 요리에 조예가 깊은 분이거든.",
            ["DialogueId"] = 80210318,
            ["FinalCamera"] = "-208.675781,31.691406,134.121582,0.000012,-19.999954,47.00246,20.0,150.472961,false,Manual,2.8",
            ["GUID"] = "C8CC514C",
            ["NextDialogue"] = 80210319,
            ["SpeakNpcId"] = 790071,
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC514C",
            },
        [80210319] = {
            ["Content"] = "他老人家最知名的一手是“若木无觅衔烛龙”，号称是能把维系大风九章的那白龙斩了做宴席。",
            ["ContentKR"] = "그분의 걸작은 '약목(若木)엔 촉룡이 없노라'라는 연회상이야. 대풍구장을 감고 있는 그 백룡을 잘라내 만든 거라고들 하지.",
            ["DialogueId"] = 80210319,
            ["GUID"] = "C8CC5176",
            ["NextDialogue"] = 80210320,
            ["SpeakNpcId"] = 790071,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC5176",
            },
        [80210320] = {
            ["Content"] = "实际上呢，是用各种飞禽走兽的肉分别以掌力击碎，再绞制成型。这样一来，一口下去可以尝出百般滋味，所以敢自称是龙肉。",
            ["ContentKR"] = "실제로는 각종 짐승의 고기를 손바닥으로 으깨서 빚어내는 거야. 그렇게 하면 각양각색의 다양한 풍미를 한입에 느낄 수 있거든. 그러니 용 고기라고 불러도 손색이 없지.",
            ["DialogueId"] = 80210320,
            ["GUID"] = "C8CC51A0",
            ["NextDialogue"] = 80210321,
            ["SpeakNpcId"] = 790071,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC51A0",
            },
        [80210321] = {
            ["Content"] = "然后再又以极其滑嫩的豆腐作为基底，与诸多畜类的脊髓骨髓一同炒制，让它们的香味渗入豆腐中，号称龙髓。",
            ["ContentKR"] = "그다음엔 아주 부드러운 두부에, 다양한 짐승의 골수를 함께 볶으면, 그 향이 두부에 가득 배게 되는데, 이건 용의 골수라고 부른다네.",
            ["DialogueId"] = 80210321,
            ["GUID"] = "C8CC51CA",
            ["NextDialogue"] = 80210322,
            ["SpeakNpcId"] = 790071,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC51CA",
            },
        [80210322] = {
            ["Camera"] = "-159.164062,204.953125,88.058105,0.000052,9.999997,-80.395218,20.0,169.81192,false,Manual,2.8",
            ["Content"] = "客官您说笑了，豆腐就是豆腐，怎么能号称是龙髓呢。要这么说，我们店卖的油豆腐，也能叫炸龙髓了。",
            ["ContentKR"] = "아유, 농담도 잘하십니다, 손님. 두부면 그냥 두부지, 어찌 용의 골수가 된단 말입니까? 그렇담 저희 가게의 튀긴 두부는 용의 골수 튀김이게요?",
            ["DialogueId"] = 80210322,
            ["FinalCamera"] = "-156.535156,189.371094,90.843262,0.000052,9.999997,-80.395218,20.0,169.81192,false,Manual,2.8",
            ["GUID"] = "C8CC51F4",
            ["NextDialogue"] = 80210323,
            ["SpeakNpcId"] = 790069,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC51F4",
            },
        [80210323] = {
            ["Camera"] = "-194.460938,93.691406,125.272461,0.000011,-19.99996,37.409882,20.0,81.55352,false,Manual,2.8",
            ["Content"] = "哎，我也是听师父说过而已。那位铁掌移山刘纬甫早早金盆洗手，如今没人知道他身在何方。",
            ["ContentKR"] = "아, 난 그냥 사부님 말씀을 들은 것뿐이야. 그 철장이산 류위보라는 선배는 은퇴하신 지 오래고, 행방을 아는 사람도 없거든.",
            ["DialogueId"] = 80210323,
            ["FinalCamera"] = "-185.449219,100.574219,121.142578,0.000011,-19.99996,37.409882,20.0,81.55352,false,Manual,2.8",
            ["GUID"] = "C8CC521E",
            ["NextDialogue"] = 80210324,
            ["SpeakNpcId"] = 790071,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC521E",
            },
        [80210324] = {
            ["Camera"] = "-1040.925781,1113.558594,298.16748,0.000131,-4.398683,-49.787758,30.000002,1361.954834,false,Manual,2.8",
            ["Content"] = "说半天说得我都流口水了，原来您没吃过啊。行了那别说这些虚无缥缈的了，来尝尝这个吧，我们店招牌的油豆腐。",
            ["ContentKR"] = "얘길 듣다 보니 저도 군침이 돌던데, 손님께서도 아직 드셔보신 게 아니군요. 그럼 허무맹랑한 얘기는 그만두고, 이거나 드셔 보시지요. 저희 식당의 자랑, 튀긴 두부랍니다.",
            ["DialogueId"] = 80210324,
            ["FinalCamera"] = "-847.84375,934.597656,274.614746,0.000131,-6.0,-49.78775,30.000002,1361.954834,false,Manual,2.8",
            ["GUID"] = "C8CC5248",
            ["NextDialogue"] = 80210325,
            ["SpeakNpcId"] = 790069,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC5248",
            },
        [80210325] = {
            ["Content"] = "……我来尝尝。",
            ["ContentKR"] = "흠, 그럼 어디...",
            ["DialogueId"] = 80210325,
            ["GUID"] = "C8CC5272",
            ["SpeakNpcId"] = 790071,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC5272",
            },
        [80210326] = {
            ["Content"] = "啊……烫，但……好好吃。",
            ["ContentKR"] = "앗, 뜨거... 호오... 근데 정말 맛있군.",
            ["DialogueId"] = 80210326,
            ["GUID"] = "C8CC529C",
            ["IsBlack"] = 1,
            ["LookAt"] = {
                [1] = "790071:n(790069)",
                [2] = "790069:n(790071)",
                },
            ["NextDialogue"] = 80210327,
            ["Scripts"] = "PlayAnimation{ActorId{790071},AnimationId{\"Sit_Idle_Loop\"},Sync{true}}",
            ["SpeakNpcId"] = 790071,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC529C",
            },
        [80210327] = {
            ["Content"] = "嘶哈——",
            ["ContentKR"] = "흐읍——",
            ["DialogueId"] = 80210327,
            ["GUID"] = "C8CC52C6",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 80210328,
            ["SpeakNpcId"] = 790071,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC52C6",
            },
        [80210328] = {
            ["Camera"] = "-194.460938,93.691406,125.272461,0.000011,-19.99996,37.409882,20.0,81.55352,false,Manual,2.8",
            ["Content"] = "表皮被炸得酥脆，咬下去嘎吱作响，而里面的豆腐却软嫩绵滑，却又不至于立刻散掉，得要相当的力道和巧劲才能做到这个地步。",
            ["ContentKR"] = "표면은 '파스스' 소리가 날 만큼 잘 튀겨져 바삭거리고, 안쪽의 두부는 실크처럼 보드랍지만, 부스러지지 않고 탄력이 있군. 이 정도 솜씨라면 상당한 내공이 필요하겠는걸.",
            ["DialogueId"] = 80210328,
            ["FinalCamera"] = "-189.175781,97.710938,122.863281,0.00001,-19.999954,37.409824,20.0,81.55352,false,Manual,2.8",
            ["GUID"] = "C8CC52F0",
            ["NextDialogue"] = 80210329,
            ["SpeakNpcId"] = 790071,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC52F0",
            },
        [80210329] = {
            ["Camera"] = "-159.164062,204.953125,88.058105,0.000052,9.999997,-80.395218,20.0,169.81192,false,Manual,2.8",
            ["Content"] = "算你识货，我们卯金叔做得油豆腐可是远近闻名，想来啊，不比那什么“若木无觅衔烛龙”差。",
            ["ContentKR"] = "역시 뭘 좀 아시네요. 저희 묘금 아저씨의 튀긴 두부는 멀리서도 이름이 자자하답니다. 아마 '약목엔 촉룡이 없노라'인가 뭔가랑 견줘도 뒤지지 않을 걸요?",
            ["DialogueId"] = 80210329,
            ["FinalCamera"] = "-156.535156,189.371094,90.843262,0.000052,9.999997,-80.395218,20.0,169.81192,false,Manual,2.8",
            ["GUID"] = "C8CC531A",
            ["NextDialogue"] = 80210330,
            ["SpeakNpcId"] = 790069,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC531A",
            },
        [80210330] = {
            ["Content"] = "等等……莫非……",
            ["ContentKR"] = "잠깐... 이건 설마...",
            ["DialogueId"] = 80210330,
            ["FacialId"] = {
                [1] = "790071:Shock01",
                },
            ["GUID"] = "C8CC5344",
            ["NextDialogue"] = 80210331,
            ["SpeakNpcId"] = 790071,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC5344",
            },
        [80210331] = {
            ["Camera"] = "-291.878906,37.308594,153.111328,0.000122,-8.597596,-25.187979,30.000013,264.169495,false,Manual,2.8",
            ["Content"] = "就你个瓜娃儿话多，莫要和客人摆龙门阵了，又有油豆腐弄好了，上菜。",
            ["ContentKR"] = "이 떠버리 자슥이. 손님 앞에서 씨부리지 마라. 저기 튀긴 두부 하나 더 나왔다. 퍼뜩 내가라.",
            ["DialogueId"] = 80210331,
            ["FinalCamera"] = "-241.59375,9.6875,154.276855,0.000128,-8.597521,-24.999588,30.000013,185.753601,false,Manual,2.8",
            ["GUID"] = "C8CC536E",
            ["NextDialogue"] = 80210332,
            ["Scripts"] = "MoveTo{ActorId{790070},TargetPoint{\"BP_NewTargetPoint_150303_1\"},MoveSpeed{150}}",
            ["SpeakNpcId"] = 790070,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC536E",
            },
        [80210332] = {
            ["Content"] = "得嘞。",
            ["ContentKR"] = "예예.",
            ["DialogueId"] = 80210332,
            ["Duration"] = 5,
            ["GUID"] = "C8CC5398",
            ["LookAt"] = {
                [1] = "790069:n(790069)",
                },
            ["NextDialogue"] = 80210333,
            ["Scripts"] = "MoveTo{ActorId{790069},TargetPoint{\"BP_NewTargetPoint_150303_2\"},MoveSpeed{150},Visibility{\"Hide\"}}",
            ["SpeakNpcId"] = 790069,
            ["TurnTo"] = {
                [1] = "790070:n(790071)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC5398",
            },
        [80210333] = {
            ["Camera"] = "-201.753906,194.632812,93.111328,0.000129,1.999995,-50.996628,20.0,305.107788,false,Manual,2.8",
            ["Content"] = "尝出来了？",
            ["ContentKR"] = "눈치챘나.",
            ["DialogueId"] = 80210333,
            ["FinalCamera"] = "-191.488281,181.953125,93.680664,0.000129,1.999995,-50.996746,20.0,305.107788,false,Manual,2.8",
            ["GUID"] = "C8CC53C2",
            ["LookAt"] = {
                [1] = "790071:n(790070)",
                },
            ["NextDialogue"] = 80210334,
            ["SpeakNpcId"] = 790070,
            ["ToFinalCameraBlendTime"] = 5,
            ["TurnTo"] = {
                [1] = "790070:n(790071)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC53C2",
            },
        [80210334] = {
            ["Camera"] = "-194.460938,93.691406,125.272461,0.000011,-19.99996,37.409882,20.0,81.55352,false,Manual,2.8",
            ["Content"] = "尝出来了，前辈的手艺果然名不虚传，难怪我师父这么多年一直念念不忘。",
            ["ContentKR"] = "네. 역시 선배님 솜씨는 역시 듣던 대로네요. 저희 사부님께서 그토록 오랫동안 잊지 못하신 이유를 알겠습니다.",
            ["DialogueId"] = 80210334,
            ["FacialId"] = {
                [1] = "790071:Smile01",
                },
            ["FinalCamera"] = "-189.175781,97.710938,122.863281,0.00001,-19.999954,37.409824,20.0,81.55352,false,Manual,2.8",
            ["GUID"] = "C8CC53EC",
            ["NextDialogue"] = 80210335,
            ["SpeakNpcId"] = 790071,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC53EC",
            },
        [80210335] = {
            ["Camera"] = "-187.410156,43.980469,119.370605,0.00013,1.999995,-44.796921,20.0,171.840973,false,Manual,2.8",
            ["Content"] = "净讲这些虚的干啥子嘞，你吃东西是为自己吃的还是为你师父吃的？讲你自己的想法。",
            ["ContentKR"] = "씰데없는 소리. 음식이 니 주디로 들어갔지, 니 스승 주디로 들어갔나. 니 생각을 말하라켔다아이가.",
            ["DialogueId"] = 80210335,
            ["FinalCamera"] = "-198.394531,31.234375,119.370605,0.00013,1.999995,-39.196651,20.0,171.840973,false,Manual,2.8",
            ["GUID"] = "C8CC5416",
            ["NextDialogue"] = 80210336,
            ["SpeakNpcId"] = 790070,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC5416",
            },
        [80210336] = {
            ["Camera"] = "-400.648438,-387.972656,82.464844,0.000133,1.999995,51.002842,20.0,592.152588,false,Manual,2.8",
            ["Content"] = "好吃！",
            ["ContentKR"] = "맛있습니다!",
            ["DialogueId"] = 80210336,
            ["FinalCamera"] = "-314.59375,-444.601562,82.464844,0.000134,1.999995,62.002323,20.0,592.152588,false,Manual,2.8",
            ["GUID"] = "C8CC5440",
            ["NextDialogue"] = 80210337,
            ["SpeakNpcId"] = 790071,
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC5440",
            },
        [80210337] = {
            ["Content"] = "对头，那好吃的话应该怎么做啊？",
            ["ContentKR"] = "맞제. 맛있다캤으면, 그다음엔 머꼬?",
            ["DialogueId"] = 80210337,
            ["GUID"] = "C8CC546A",
            ["NextDialogue"] = 80210338,
            ["SpeakNpcId"] = 790070,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC546A",
            },
        [80210338] = {
            ["Content"] = "再来七块！",
            ["ContentKR"] = "일곱 개 더 먹어야지요!",
            ["DialogueId"] = 80210338,
            ["GUID"] = "C8CC5494",
            ["NextDialogue"] = 80210339,
            ["SpeakNpcId"] = 790071,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC5494",
            },
        [80210339] = {
            ["Content"] = "嘞就对嘛。",
            ["ContentKR"] = "당연히 그래야지.",
            ["DialogueId"] = 80210339,
            ["GUID"] = "C8CC54BE",
            ["NextDialogue"] = 80210340,
            ["SpeakNpcId"] = 790070,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC54BE",
            },
        [80210340] = {
            ["Camera"] = "-187.410156,43.980469,119.370605,0.00013,1.999995,-44.796921,20.0,171.840973,false,Manual,2.8",
            ["Content"] = "好，吃的问题解决了，现在你告诉我，你师父是哪一个？",
            ["ContentKR"] = "좋다. 먹는 건 인제 해결됐다 아이가. 말해 봐라. 니 사부가 누구고.",
            ["DialogueId"] = 80210340,
            ["FinalCamera"] = "-198.394531,31.234375,119.370605,0.00013,1.999995,-39.196651,20.0,171.840973,false,Manual,2.8",
            ["GUID"] = "C8CC54E8",
            ["NextDialogue"] = 80210341,
            ["SpeakNpcId"] = 790070,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC54E8",
            },
        [80210341] = {
            ["Camera"] = "-194.460938,93.691406,125.272461,0.000011,-19.99996,37.409882,20.0,81.55352,false,Manual,2.8",
            ["Content"] = "宴山亭。",
            ["ContentKR"] = "연산정입니다.",
            ["DialogueId"] = 80210341,
            ["FinalCamera"] = "-189.175781,97.710938,122.863281,0.00001,-19.999954,37.409824,20.0,81.55352,false,Manual,2.8",
            ["GUID"] = "C8CC5512",
            ["NextDialogue"] = 80210342,
            ["SpeakNpcId"] = 790067,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC5512",
            },
        [80210342] = {
            ["Camera"] = "-187.410156,43.980469,119.370605,0.00013,1.999995,-44.796921,20.0,171.840973,false,Manual,2.8",
            ["Content"] = "喔，原来是他，是为了论剑而来的吧？没想到他还记得这个事。",
            ["ContentKR"] = "아, 그자였구마. 논검 때문에 온 기가. 여직 그 일을 기억하는지는 몰랐네.",
            ["DialogueId"] = 80210342,
            ["FinalCamera"] = "-198.394531,31.234375,119.370605,0.00013,1.999995,-39.196651,20.0,171.840973,false,Manual,2.8",
            ["GUID"] = "C8CC553C",
            ["NextDialogue"] = 80210343,
            ["SpeakNpcId"] = 790070,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC553C",
            },
        [80210343] = {
            ["Camera"] = "-104.40625,-155.425781,163.111328,0.000038,-19.999928,85.208679,20.0,314.309692,false,Manual,2.8",
            ["Content"] = "师父念念不忘，敢问刘前辈会参加吗？",
            ["ContentKR"] = "사부님께선 쭉 그리워하셨습니다. 유선배님께선 이번에 참가하십니까?",
            ["DialogueId"] = 80210343,
            ["FacialId"] = {
                [1] = "790071:Smile01",
                },
            ["FinalCamera"] = "-102.179688,-128.832031,153.394531,0.000038,-19.999928,85.208679,20.0,314.309692,false,Manual,2.8",
            ["GUID"] = "C8CC5566",
            ["NextDialogue"] = 80210344,
            ["SpeakNpcId"] = 790071,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC5566",
            },
        [80210344] = {
            ["Camera"] = "-201.753906,194.632812,93.111328,0.000129,1.999995,-50.996628,20.0,305.107788,false,Manual,2.8",
            ["Content"] = "这里没有刘前辈，我早已放下刀，这里只有卯金叔。",
            ["ContentKR"] = "유 선배라카는 인간은 인자 없다. 내는 칼 내려놓은지 오래다. 여기 있는 사람은 묘금이다.",
            ["DialogueId"] = 80210344,
            ["FinalCamera"] = "-191.488281,181.953125,93.680664,0.000129,1.999995,-50.996746,20.0,305.107788,false,Manual,2.8",
            ["GUID"] = "C8CC5590",
            ["NextDialogue"] = 80210345,
            ["SpeakNpcId"] = 790070,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC5590",
            },
        [80210345] = {
            ["Content"] = "好了，莫要再问了，再要七个油豆腐是吧，我这就继续。",
            ["ContentKR"] = "자, 인자 고마 캐물어라잉. 두부 튀긴 거 일곱 개 더 달라캤제. 내는 고만 튀구러 가봐야겠다.",
            ["DialogueId"] = 80210345,
            ["GUID"] = "C8CC55BA",
            ["NextDialogue"] = 80210346,
            ["SpeakNpcId"] = 790070,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC55BA",
            },
        [80210346] = {
            ["Camera"] = "-194.460938,93.691406,125.272461,0.000011,-19.99996,37.409882,20.0,81.55352,false,Manual,2.8",
            ["Content"] = "……再来七个，打包带走，我也让我朋友尝一尝。",
            ["ContentKR"] = "...일곱 개 더 주시지요. 맛을 보여주고 싶은 친구가 있어서요.",
            ["DialogueId"] = 80210346,
            ["FacialId"] = {
                [1] = "790071:Smile01",
                },
            ["FinalCamera"] = "-189.175781,97.710938,122.863281,0.00001,-19.999954,37.409824,20.0,81.55352,false,Manual,2.8",
            ["GUID"] = "C8CC55E4",
            ["NextDialogue"] = 80210347,
            ["SpeakNpcId"] = 790071,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC55E4",
            },
        [80210347] = {
            ["Camera"] = "-400.648438,-387.972656,82.464844,0.000133,1.999995,51.002842,20.0,592.152588,false,Manual,2.8",
            ["Content"] = "要得，但切记，只许和朋友说这是卯金叔做的，要是多说一句，我把你舌头割下来做成卤菜。",
            ["ContentKR"] = "그래야제. 근데, 단디 명심해래이. 이거는 묘금 아저씨가 만든기다잉. 한 마디만 더 지껴봐라. 니 혀를 잘라가 확 삶아뿔기라.",
            ["DialogueId"] = 80210347,
            ["FinalCamera"] = "-544.378906,-565.476562,74.48877,0.000132,1.999995,51.004082,20.0,592.152588,false,Manual,2.8",
            ["GUID"] = "C8CC560E",
            ["NextDialogue"] = 80210348,
            ["SpeakNpcId"] = 790070,
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC560E",
            },
        [80210348] = {
            ["Content"] = "那是自然，那么后生拜别前辈。",
            ["ContentKR"] = "물론이죠, 그럼 후배는 먼저 가보겠습니다.",
            ["DialogueId"] = 80210348,
            ["GUID"] = "C8CC5638",
            ["SpeakNpcId"] = 790071,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC5638",
            },
        [80210401] = {
            ["Camera"] = "-15.96875,236.780762,198.734375,0.00004,-1.999995,63.206463,40.310993,407.767792,false,Manual,2.8",
            ["Content"] = "一大早的，还没睡醒呢就把人吵起来，是要去哪儿？",
            ["ContentKR"] = "이참부터 시끄럽게 사람을 깨워서, 어딜 가자는 거야?",
            ["DialogueId"] = 80210401,
            ["FacialId"] = {
                [1] = "790008:Doubt01",
                },
            ["FinalCamera"] = "0.390625,269.174805,197.469727,0.00004,-1.999995,63.206463,40.310993,407.767792,false,Manual,2.8",
            ["GUID"] = "C8CC5EEA",
            ["LookAt"] = {
                [1] = "790008:n(790067)",
                [2] = "790067:n(790008)",
                },
            ["NextDialogue"] = 80210402,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC5EEA",
            },
        [80210402] = {
            ["Camera"] = "15.414062,815.271973,212.397461,0.000014,-4.60016,-71.792816,40.310993,430.446808,false,Manual,2.8",
            ["Content"] = "比武论剑，二十年一次。",
            ["ContentKR"] = "20년에 한 번 열리는 논검 대회다.",
            ["DialogueId"] = 80210402,
            ["FacialId"] = {
                [1] = "790067:Confident01",
                },
            ["FinalCamera"] = "28.40625,774.96582,208.994141,0.000013,-4.60016,-72.792603,40.310993,430.446808,false,Manual,2.8",
            ["GUID"] = "C8CC5F14",
            ["NextDialogue"] = 80210403,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC5F14",
            },
        [80210403] = {
            ["Camera"] = "-748.292969,-30.820801,161.345703,0.000053,0.0,31.808994,40.310993,975.20166,false,Manual,2.8",
            ["Content"] = "说这个我就不困了，谁和谁啊？",
            ["ContentKR"] = "갑자기 잠이 확 달아나네. 누구랑 누구 대결인데?",
            ["DialogueId"] = 80210403,
            ["FinalCamera"] = "-626.019531,45.025391,161.345703,0.000053,0.0,31.809633,40.310993,872.170044,false,Manual,2.8",
            ["GUID"] = "C8CC5F3E",
            ["NextDialogue"] = 80210404,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Confident_End",
                },
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC5F3E",
            },
        [80210404] = {
            ["Content"] = "华胥有头有脸的飘零人理应都会来，之前已经举行过七八次了，大家会在山巅互相比试，直到分出胜负。",
            ["ContentKR"] = "화서의 명망 있는 나그네는 모두 참가할 거야. 이번이 9회째인가 되는데, 산 정상에서 승부가 날 때까지 겨룰 거다.",
            ["DialogueId"] = 80210404,
            ["GUID"] = "C8CC5F68",
            ["NextDialogue"] = 80210405,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC5F68",
            },
        [80210405] = {
            ["Camera"] = "-15.96875,236.780762,198.734375,0.00004,-1.999995,63.206463,40.310993,407.767792,false,Manual,2.8",
            ["Content"] = "那么这次，会有多少人参加？",
            ["ContentKR"] = "그럼, 이번엔 몇 명이나 참가하는데?",
            ["DialogueId"] = 80210405,
            ["FinalCamera"] = "0.390625,269.174805,197.469727,0.00004,-1.999995,63.206463,40.310993,407.767792,false,Manual,2.8",
            ["GUID"] = "C8CC5F92",
            ["NextDialogue"] = 80210406,
            ["SpeakNpcId"] = 790008,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC5F92",
            },
        [80210406] = {
            ["Camera"] = "-26.566406,613.213379,186.345703,0.000053,0.0,-59.788727,40.310993,251.490341,false,Manual,2.8",
            ["Content"] = "等到了你就知道了。",
            ["ContentKR"] = "가보면 알아.",
            ["DialogueId"] = 80210406,
            ["FinalCamera"] = "-14.558594,592.585449,193.345703,0.000053,0.0,-59.788727,40.310993,213.980072,false,Manual,2.8",
            ["GUID"] = "C8CC5FBC",
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Talk03_End",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC5FBC",
            },
        [80210407] = {
            ["Camera"] = "976.125,1795.242676,518.382812,0.000097,-9.999997,-118.000748,26.65424,2016.868164,false,Manual,2.8",
            ["Content"] = "跟着刻舟到了一处相当荒僻的山间，想来这就是他们此前比武论剑之地了。",
            ["ContentKR"] = "각주를 따라가 보니, 황량하고 외진 산속이다. 여기가 바로 논검 대회 장소인 모양이다.",
            ["DialogueId"] = 80210407,
            ["FinalCamera"] = "882.355469,1518.284668,467.509766,0.000097,-9.999964,-118.000748,26.65424,1751.967041,false,Manual,2.8",
            ["GUID"] = "C8CC5FE6",
            ["NextDialogue"] = 80210408,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC5FE6",
            },
        [80210408] = {
            ["Content"] = "但见满目新绿，飞泉直下。是适合比试的场地，只是，似乎有些过于冷清……",
            ["ContentKR"] = "푸른 나무 사이 폭포가 흐르고 있어, 대결에는 꼭 맞는 장소다. 하지만 왠지 너무 조용한 느낌인데...",
            ["DialogueId"] = 80210408,
            ["GUID"] = "C8CC6010",
            ["NextDialogue"] = 80210409,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6010",
            },
        [80210409] = {
            ["Camera"] = "511.71875,-314.994141,144.21875,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
            ["Content"] = "怎么只有我们俩，不是说有头有脸的飘零人都会来吗？",
            ["ContentKR"] = "왜 우리 둘뿐이야? 명망 있는 나그네라면 모두 온다고 했잖아?",
            ["DialogueId"] = 80210409,
            ["FacialId"] = {
                [1] = "790008:Doubt01",
                },
            ["FinalCamera"] = "491.65625,-286.541504,141.78418,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
            ["GUID"] = "C8CC603A",
            ["LookAt"] = {
                [1] = "790067:n(790008)",
                },
            ["NextDialogue"] = 80210410,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Sigh_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC603A",
            },
        [80210410] = {
            ["Camera"] = "434.003906,248.654785,121.818359,0.000152,1.999995,-107.80146,42.362053,398.766113,false,Manual,2.8",
            ["Content"] = "说来惭愧，现在有头有脸的飘零人也不剩几位了，正所谓江湖儿女日渐少。",
            ["ContentKR"] = "이런 말 하기 부끄럽지만, 명망 있는 나그네가 이미 얼마 남지 않았다... 강호에 인물이 사라져 간단 말도 있지 않느냐.",
            ["DialogueId"] = 80210410,
            ["FacialId"] = {
                [1] = "790067:Sad01",
                },
            ["FinalCamera"] = "408.511719,168.209961,124.753906,0.000153,2.99999,-105.801682,42.362053,306.325958,false,Manual,2.8",
            ["GUID"] = "C8CC6064",
            ["NextDialogue"] = 80210411,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790008:Sigh_End",
                [2] = "790067:Talk01_Start",
                },
            ["ToFinalCameraBlendTime"] = 40,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6064",
            },
        [80210411] = {
            ["Content"] = "且不说这次，就是上一次参加比武论剑的飘零人，仅有四位而已。",
            ["ContentKR"] = "사실 꼭 이번만이 아니라, 지난번 논검 대회에 참가한 나그네도 네 명뿐이었다.",
            ["DialogueId"] = 80210411,
            ["FacialId"] = {
                [1] = "790008:None",
                },
            ["GUID"] = "C8CC608E",
            ["LookAt"] = {
                [1] = "790008:n(790067)",
                },
            ["NextDialogue"] = 80210412,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC608E",
            },
        [80210412] = {
            ["Content"] = "第一位呢，便是我的师父宴山亭。虽然他已经离世，但是在离世前对这比武论剑念念不忘，让我代他出战。",
            ["ContentKR"] = "첫 번째가 연산정, 바로 내 사부님이다. 이미 돌아가셨지만, 마지막 순간까지도 이 논검 대회를 잊지 못하시고 나보고 대신 참가하라고 하셨거든.",
            ["DialogueId"] = 80210412,
            ["FacialId"] = {
                [1] = "790067:None",
                },
            ["GUID"] = "C8CC60B8",
            ["NextDialogue"] = 80210413,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC60B8",
            },
        [80210413] = {
            ["Content"] = "于是我就走访了各处，找到了另外三位当年参加了比武论剑的高手。",
            ["ContentKR"] = "그래서 각지를 돌아다니며, 지난 논검 대회에 참가했던 나머지 고수 세 명을 찾아낸 거야.",
            ["DialogueId"] = 80210413,
            ["GUID"] = "C8CC60E2",
            ["NextDialogue"] = 80210414,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC60E2",
            },
        [80210414] = {
            ["Content"] = "我先找了其中一位善于用剑的女侠，也是上次论剑时夺得魁首的天下第一。但却连面也没见到。",
            ["ContentKR"] = "먼저 검의 귀재인 여협을 찾아갔다. 지난 논검에서 승리한 '천하제일'이지만, 얼굴조차 보지 못했어.",
            ["DialogueId"] = 80210414,
            ["GUID"] = "C8CC610C",
            ["NextDialogue"] = 80210415,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC610C",
            },
        [80210415] = {
            ["Content"] = "我师父一直说她爱剑成痴，大部分时候甚至不愿意拔剑，只以剑鞘伤人，又早早归隐，远离江湖，所以并没有被大风九章盯上。",
            ["ContentKR"] = "사부님 말씀으론, 검을 아끼다 못해 발검조차 꺼리는 여협이라고 하더군. 칼집으로만 공격하는 데다, 일찌감치 강호를 떠나 은거한 덕분에 대풍구장의 눈에 띄지 않았지.",
            ["DialogueId"] = 80210415,
            ["GUID"] = "C8CC6136",
            ["NextDialogue"] = 80210416,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6136",
            },
        [80210416] = {
            ["Content"] = "现如今，却把自己的佩剑拿去当孩子的玩物，想必是不愿踏足江湖，只想躲进小楼，远离纷扰，那么我也没有多打扰她。",
            ["ContentKR"] = "그런데 지금은 그 검을 아이에게 장난감으로 쥐여줄 정도니, 아무래도 강호에 다시 돌아오지 않고, 조용하게 살고 싶은 것 같더라고. 그래서 굳이 귀찮게 하지 않았다.",
            ["DialogueId"] = 80210416,
            ["GUID"] = "C8CC6160",
            ["NextDialogue"] = 80210417,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6160",
            },
        [80210417] = {
            ["Content"] = "师父一直说她有大智慧，我此前都不明白，这次见了……不，这次没见到她，但是也已经明白师父为什么会这么说了。",
            ["ContentKR"] = "사부님께선 아주 똑똑한 사람이라고 하셨지만, 전엔 잘 몰랐어. 이번에 만나고서야... 아, 사실 만나지도 못했지. 어쨌든 사부님이 왜 그렇게 말씀하셨는지 알았다.",
            ["DialogueId"] = 80210417,
            ["GUID"] = "C8CC618A",
            ["NextDialogue"] = 80210418,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC618A",
            },
        [80210418] = {
            ["Camera"] = "478.570312,-143.509766,121.444336,0.000169,2.99999,132.400314,42.362053,217.393646,false,Manual,2.8",
            ["Content"] = "嗯，换做是我的话，我应该也会这么做。",
            ["ContentKR"] = "하긴, 나라도 그렇게 했을 거야.",
            ["DialogueId"] = 80210418,
            ["FinalCamera"] = "472.527344,-136.883301,121.911133,0.00017,2.99999,132.400513,42.362053,217.393646,false,Manual,2.8",
            ["GUID"] = "C8CC61B4",
            ["NextDialogue"] = 80210419,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC61B4",
            },
        [80210419] = {
            ["Camera"] = "925.164062,204.170898,224.050781,0.000123,-9.999943,-150.992493,26.65424,679.187683,false,Manual,2.8",
            ["Content"] = "再一位呢，唤作鸣鸾，比我年长一点，自幼就被认定是习武的天才，年少成名，以弱冠之龄便能参加比武论剑。",
            ["ContentKR"] = "두 번째는 난명이라는 자인데, 나이는 나보다 조금 위야. 어렸을 때부터 무공에 천재적인 재능을 보여 이름을 날리다, 약관의 나이에 논검 대회에 참가했지.",
            ["DialogueId"] = 80210419,
            ["FinalCamera"] = "742.019531,445.837402,225.842773,0.000124,-9.999943,-129.189941,26.65424,679.187683,false,Manual,2.8",
            ["GUID"] = "C8CC61DE",
            ["NextDialogue"] = 80210420,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Talk02R_Start",
                },
            ["ToFinalCameraBlendTime"] = 40,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC61DE",
            },
        [80210420] = {
            ["Content"] = "他本有一位红颜知己，剑法同样精微，一直与他快意恩仇，人人都觉得他们是一对璧人，天作之合。",
            ["ContentKR"] = "난명에겐 원래 절친한 벗이 있었다. 난명과 쭉 같이 강호를 누빈 여협인데, 검술이 대단했지. 모두가 두 사람을 천생배필이라고 불렀어.",
            ["DialogueId"] = 80210420,
            ["GUID"] = "C8CC6208",
            ["NextDialogue"] = 80210421,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6208",
            },
        [80210421] = {
            ["Content"] = "但是再多的快意恩仇也会让人厌倦，那位红颜知己厌倦了终日飘零，不得不躲避应天尉追杀的生活。",
            ["ContentKR"] = "하지만 통쾌한 복수도 언젠간 싫증이 나는 법, 여협은 종일 떠돌며 응천위의 추격을 피해 다니는 삶이 지겨워진 거지.",
            ["DialogueId"] = 80210421,
            ["GUID"] = "C8CC6232",
            ["NextDialogue"] = 80210422,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6232",
            },
        [80210422] = {
            ["Content"] = "于是他们相约，在某日一起离开华胥，去大陆的其他地方，过安稳日子。",
            ["ContentKR"] = "그래서 두 사람은 함께 화서를 떠나기로 약속했어. 대륙 다른 곳에 가서 조용하게 살기로 한 거지.",
            ["DialogueId"] = 80210422,
            ["GUID"] = "C8CC625C",
            ["NextDialogue"] = 80210423,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC625C",
            },
        [80210423] = {
            ["Content"] = "只是他们许约的那一日，偏偏又是论剑的日子。而鸣鸾被年少盛名所累，想要等到比武结束后，夺了第一的名号后与那位知己再一同离开华胥。",
            ["ContentKR"] = "그런데 하필 두 사람이 떠나기로 한 날이 바로 논검 당일이었던 거다. 난명은 그동안 쌓아온 명성이 있으니, 논검 대회에서 천하제일이란 이름을 얻은 다음, 벗과 함께 화서를 떠나고 싶었지.",
            ["DialogueId"] = 80210423,
            ["GUID"] = "C8CC6286",
            ["NextDialogue"] = 80210424,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6286",
            },
        [80210424] = {
            ["Content"] = "但高手对决，又怎么会几招内分出胜负，他们斗了三个日夜。等鸣鸾比试结束，前去赴约时，眼前所见只有江上数峰青山，不见人影。",
            ["ContentKR"] = "하지만 고수의 대결이 어찌 몇 초식만에 승부가 나겠느냐. 그들은 꼬박 사흘 밤낮을 싸웠지. 대회가 끝나고 난명이 약속 장소에 갔을 땐, 텅 빈 강엔 멀리 푸른 산만 비칠 뿐이었다.",
            ["DialogueId"] = 80210424,
            ["GUID"] = "C8CC62B0",
            ["NextDialogue"] = 80210425,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC62B0",
            },
        [80210425] = {
            ["Content"] = "应当是那位红颜知己见他仍然是放不下名声，感到失望而独自离开。",
            ["ContentKR"] = "아마도 자신의 벗이 아직도 명성에 연연하는 걸 보고, 실망해서 홀로 떠난 거겠지.",
            ["DialogueId"] = 80210425,
            ["GUID"] = "C8CC62DA",
            ["NextDialogue"] = 80210426,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC62DA",
            },
        [80210426] = {
            ["Content"] = "鸣鸾最初不以为意，但是很快便思念成疾，察觉到这世界上有比所谓的“天下第一”更重要的事物。",
            ["ContentKR"] = "난명은 처음엔 대수롭지 않게 여겼지만, 곧 그녀에 대한 그리움으로 미쳐갔다. 세상엔 '천하제일'보다 더 중요한 게 있다는 걸 알게 된 거지.",
            ["DialogueId"] = 80210426,
            ["GUID"] = "C8CC6304",
            ["NextDialogue"] = 80210427,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6304",
            },
        [80210427] = {
            ["Content"] = "于是他也离开了华胥，寻觅至今，却还是没有寻到。",
            ["ContentKR"] = "그래서 화서를 떠나 그녀를 찾아 헤맸지만, 아직 찾지 못했어.",
            ["DialogueId"] = 80210427,
            ["GUID"] = "C8CC632E",
            ["NextDialogue"] = 80210428,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC632E",
            },
        [80210428] = {
            ["Content"] = "所以这一次比武论剑，他不参加。",
            ["ContentKR"] = "그러니 난명도 이번 논검에 오지 않을 거다.",
            ["DialogueId"] = 80210428,
            ["GUID"] = "C8CC6358",
            ["NextDialogue"] = 80210429,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Talk02R_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6358",
            },
        [80210429] = {
            ["Camera"] = "523.363281,229.195312,121.128906,0.000162,1.999995,-122.399033,42.362053,406.334045,false,Manual,2.8",
            ["Content"] = "至于最后一位，被称作庖侠，妙手调羹的本领是一绝，所制作的“若木无觅衔烛龙”更是举世无双。",
            ["ContentKR"] = "마지막 인물은 주방 대협이라고 불리는데, 국자 다루는 기술이 일품이지. 그가 만든 '약목엔 촉룡이 없노라'는 세상에 둘도 없는 명요리고.",
            ["DialogueId"] = 80210429,
            ["FinalCamera"] = "434.003906,248.654785,121.818359,0.000152,1.999995,-107.80146,42.362053,398.766113,false,Manual,2.8",
            ["GUID"] = "C8CC6382",
            ["NextDialogue"] = 80210430,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 40,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6382",
            },
        [80210430] = {
            ["Content"] = "但在他某次设宴招待客人时，却被歹人在饭菜中下了毒，青花的瓷盘本来盛的是珍果佳肴，却沾染了血。",
            ["ContentKR"] = "근데 어느 연회 날, 누군가 일부러 그의 요리에 독을 넣었다. 산해진미로 가득 차야 할 잔칫상은 결국 피로 얼룩지고 말았지.",
            ["DialogueId"] = 80210430,
            ["GUID"] = "C8CC63AC",
            ["NextDialogue"] = 80210431,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC63AC",
            },
        [80210431] = {
            ["Content"] = "这毒虽然不是他下的，但毕竟饭菜都经过他手，于是也被大风九章认定为有罪。",
            ["ContentKR"] = "비록 그가 독을 넣은 건 아니었지만, 그의 손을 거친 요리였으니, 대풍구장은 그를 죄인이라 규정했어.",
            ["DialogueId"] = 80210431,
            ["GUID"] = "C8CC63D6",
            ["NextDialogue"] = 80210432,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC63D6",
            },
        [80210432] = {
            ["Content"] = "他的武艺，要应对应天尉倒也不难。但一旦反抗，那简直如同是自认有罪，所以他就束手就擒，受到惩罚，跛了一足。",
            ["ContentKR"] = "그의 무공이라면, 사실 응천위 정도야 별거 아니지. 하지만 반항한다면 죄를 인정하는 꼴이 돼 버리니까, 결국 순순히 포박되어 벌을 받고 절름발이가 됐어.",
            ["DialogueId"] = 80210432,
            ["GUID"] = "C8CC6400",
            ["NextDialogue"] = 80210433,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6400",
            },
        [80210433] = {
            ["Content"] = "等他重回自由身时，也是心灰意冷，不再以飘零人自居，专心磨练厨艺去了，炸油豆腐是一绝。",
            ["ContentKR"] = "다시 자유의 몸이 되었을 때, 그는 낙담했지. 그래서 나그네 행세는 그만두고, 대신 요리에 전념하기로 했어. 그의 튀긴 두부는 당대 제일이니까.",
            ["DialogueId"] = 80210433,
            ["GUID"] = "C8CC642A",
            ["NextDialogue"] = 80210434,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC642A",
            },
        [80210434] = {
            ["Camera"] = "511.71875,-314.994141,144.21875,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
            ["Content"] = "难道说前几天你带给我的油豆腐就是……",
            ["ContentKR"] = "설마 며칠 전에 갖다준 튀긴 두부가...",
            ["DialogueId"] = 80210434,
            ["FinalCamera"] = "491.65625,-286.541504,141.78418,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
            ["GUID"] = "C8CC6454",
            ["NextDialogue"] = 80210435,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6454",
            },
        [80210435] = {
            ["Camera"] = "408.371094,68.496582,165.21582,0.000151,-3.99997,-106.198517,42.362053,214.163193,false,Manual,2.8",
            ["Content"] = "不，不是，我什么都没说，你什么都没听见。",
            ["ContentKR"] = "아, 아니, 난 아무 말도 안 했어! 너도 아무 말 못 들은 거다.",
            ["DialogueId"] = 80210435,
            ["FacialId"] = {
                [1] = "790067:Nervous",
                },
            ["FinalCamera"] = "399.097656,36.579102,162.895508,0.000151,-2.99999,-106.198524,42.362053,175.129822,false,Manual,2.8",
            ["GUID"] = "C8CC647E",
            ["NextDialogue"] = 80210436,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:DisagreeHead",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC647E",
            },
        [80210436] = {
            ["Camera"] = "511.71875,-314.994141,144.21875,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
            ["Content"] = "噢……我懂了。",
            ["ContentKR"] = "어... 알았어.",
            ["DialogueId"] = 80210436,
            ["FinalCamera"] = "491.65625,-286.541504,141.78418,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
            ["GUID"] = "C8CC64A8",
            ["NextDialogue"] = 80210437,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:AgreeHead",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC64A8",
            },
        [80210437] = {
            ["Content"] = "不过这么一来……岂不是来参加比武的，只有代表宴山亭师父的你？",
            ["ContentKR"] = "근데 그럼... 너만 연산정 사부님 대신 대회에 참가하는 거야?",
            ["DialogueId"] = 80210437,
            ["GUID"] = "C8CC64D2",
            ["NextDialogue"] = 80210438,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC64D2",
            },
        [80210438] = {
            ["Camera"] = "434.003906,248.654785,121.818359,0.000152,1.999995,-107.80146,42.362053,398.766113,false,Manual,2.8",
            ["Content"] = "没错，这次比武论剑，只有我代表师父参加。",
            ["ContentKR"] = "맞아. 이번 논검 대회는 사부님을 대신해서 나만 참가할 거야.",
            ["DialogueId"] = 80210438,
            ["FacialId"] = {
                [1] = "790067:None",
                },
            ["FinalCamera"] = "408.511719,168.209961,124.753906,0.000153,2.99999,-105.801682,42.362053,306.325958,false,Manual,2.8",
            ["GUID"] = "C8CC64FC",
            ["NextDialogue"] = 80210439,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Talk03_End",
                [2] = "790067:AgreeHead",
                },
            ["ToFinalCameraBlendTime"] = 40,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC64FC",
            },
        [80210439] = {
            ["Content"] = "这就是现在飘零人的现状啊，曾几何时他们聚啸山林，没有什么特意需要遵从的法条，只需要遵从内心与手中剑。",
            ["ContentKR"] = "지금 나그네의 상황이 그래. 과거엔 산속에서 다들 법 같은 건 신경 쓰지 않고, 그저 마음과 손에 든 검만을 따랐지. ",
            ["DialogueId"] = 80210439,
            ["GUID"] = "C8CC6526",
            ["NextDialogue"] = 80210440,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6526",
            },
        [80210440] = {
            ["Content"] = "刀光剑影里有着一个又一个快意恩仇的故事。",
            ["ContentKR"] = "검이 번쩍일 때마다 통쾌한 복수 이야기가 따라왔고.",
            ["DialogueId"] = 80210440,
            ["GUID"] = "C8CC6550",
            ["NextDialogue"] = 80210441,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6550",
            },
        [80210441] = {
            ["Content"] = "在大风九章之下，没有所谓的路见不平拔刀相助，大家都畏惧触发法条，被应天尉盯上。",
            ["ContentKR"] = "하지만 대풍구장 때문에, 불의 앞에서 칼을 뽑아, 남을 돕는 일은 사라졌다. 다들 법을 어겼다가 응천위의 표적이 될까 봐 두려워하거든.",
            ["DialogueId"] = 80210441,
            ["GUID"] = "C8CC657A",
            ["NextDialogue"] = 80210442,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC657A",
            },
        [80210442] = {
            ["Content"] = "即便是号称自由自在的飘零人，也无法免于受到大风九章的羁绊。",
            ["ContentKR"] = "자유로이 살아가는 나그네들이라고 해도, 대풍구장의 속박엔 예외가 없으니까.",
            ["DialogueId"] = 80210442,
            ["GUID"] = "C8CC65A4",
            ["NextDialogue"] = 80210443,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC65A4",
            },
        [80210443] = {
            ["Camera"] = "511.71875,-314.994141,144.21875,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
            ["Content"] = "所以，你才会想要推翻大风九章？",
            ["ContentKR"] = "그게 대풍구장을 무너뜨리기로 결심한 이유야?",
            ["DialogueId"] = 80210443,
            ["FinalCamera"] = "491.65625,-286.541504,141.78418,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
            ["GUID"] = "C8CC65CE",
            ["NextDialogue"] = 80210444,
            ["SpeakNpcId"] = 790008,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC65CE",
            },
        [80210444] = {
            ["Camera"] = "502.972656,27.527832,181.694336,0.000158,-7.999989,-134.198502,42.362053,234.67363,false,Manual,2.8",
            ["Content"] = "只能说是原因之一吧，还有其他的新仇旧恨。",
            ["ContentKR"] = "그중 하나라고 봐야겠지. 다른 원한도 있으니까.",
            ["DialogueId"] = 80210444,
            ["FinalCamera"] = "481.535156,5.483887,177.371094,0.000159,-7.999968,-134.198471,42.362053,201.77124,false,Manual,2.8",
            ["GUID"] = "C8CC65F8",
            ["NextDialogue"] = 80210445,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Talk01_End",
                },
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC65F8",
            },
        [80210445] = {
            ["Content"] = "有时候我也在想，有大风九章在，至少大部分人能够安居，去反对它是不是真的有意义。",
            ["ContentKR"] = "난 가끔 이런 생각을 한다. 대풍구장 아래서 대부분의 사람이 안심하고 지낼 수 있다면, 반대에 무슨 의미가 있을까 하고 말이야.",
            ["DialogueId"] = 80210445,
            ["GUID"] = "C8CC6622",
            ["NextDialogue"] = 80210446,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6622",
            },
        [80210446] = {
            ["Content"] = "但这次为了准备论剑拜访了诸位前辈，看他们也都过得不尽如人意，那么在一片祥和之下，到底有多少不平之事，又有谁知道。",
            ["ContentKR"] = "하지만 이번 논검을 준비하느라 여러 선배를 찾아가 보니, 다들 초라하게 살고 계시지 않느냐. 그렇다면 이 평온함 속에 남모를 억울한 일들이 또 얼마나 많겠냐.",
            ["DialogueId"] = 80210446,
            ["GUID"] = "C8CC664C",
            ["NextDialogue"] = 80210447,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC664C",
            },
        [80210447] = {
            ["Content"] = "我作为飘零人，就不应该袖手旁观。虽说江湖儿女日渐少，但也有句话说得好嘛，天下风云出我辈。",
            ["ContentKR"] = "나그네로서 가만히 있을 순 없다. 강호의 인물들이 사라져간다곤 해도, 또 이런 말이 있지 않느냐. \"천하의 호걸은 결국 이 시대에 나리라.\"",
            ["DialogueId"] = 80210447,
            ["GUID"] = "C8CC6676",
            ["NextDialogue"] = 80210448,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6676",
            },
        [80210448] = {
            ["Content"] = "长剑在手，人在江湖，即便如孤鹜飘零，也能为天下之先，一览他人未见之景，是好事。",
            ["ContentKR"] = "장검 손에 쥐고 강호를 떠도네. 홀로일지언정 절경을 먼저 눈에 담으니, 이 또한 좋은 일이렷다!",
            ["DialogueId"] = 80210448,
            ["GUID"] = "C8CC66A0",
            ["NextDialogue"] = 80210449,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC66A0",
            },
        [80210449] = {
            ["Camera"] = "511.71875,-314.994141,144.21875,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
            ["Content"] = "行应行之路，竟未竟之志。我想，我大概明白所谓的飘零人为什么能延续至今了。",
            ["ContentKR"] = "가야 할 길을 가며, 못다 한 꿈 이루리라! 나그네들이 왜 지금까지 이어져 내려올 수 있었는지 이제야 알 것 같아.",
            ["DialogueId"] = 80210449,
            ["FinalCamera"] = "491.65625,-286.541504,141.78418,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
            ["GUID"] = "C8CC66CA",
            ["NextDialogue"] = 80210450,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC66CA",
            },
        [80210450] = {
            ["Content"] = "并且我也相信，此后比武论剑之人，肯定不会像今天这样，只有你孤身一人的。",
            ["ContentKR"] = "그리고 앞으로의 논검 대회는 절대 오늘처럼 너 혼자만은 아닐 거야.",
            ["DialogueId"] = 80210450,
            ["GUID"] = "C8CC66F4",
            ["NextDialogue"] = 80210451,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC66F4",
            },
        [80210451] = {
            ["Camera"] = "795.160156,-371.187988,113.348633,0.000152,1.999995,146.999313,42.362053,398.766113,false,Manual,2.8",
            ["Content"] = "哈哈哈哈，好，好，好，说得好。",
            ["ContentKR"] = "하하하하, 맞다, 그래, 옳은 말이다.",
            ["DialogueId"] = 80210451,
            ["FacialId"] = {
                [1] = "790067:Smile01",
                },
            ["FinalCamera"] = "862.960938,-289.070312,112.585938,0.000152,1.999995,156.599838,42.362053,398.766113,false,Manual,2.8",
            ["GUID"] = "C8CC671E",
            ["NextDialogue"] = 80210452,
            ["SpeakNpcId"] = 790067,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC671E",
            },
        [80210452] = {
            ["Content"] = "不过嘛，我可没有为没有人论剑感到难过，不如说，这可是大好事——",
            ["ContentKR"] = "하지만 논검 대회에 아무도 안 온 게 아쉽진 않아. 오히려 기쁜 일 아니냐!",
            ["DialogueId"] = 80210452,
            ["GUID"] = "C8CC6748",
            ["NextDialogue"] = 80210453,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6748",
            },
        [80210453] = {
            ["Camera"] = "408.371094,68.496582,165.21582,0.000151,-3.99997,-106.198517,42.362053,214.163193,false,Manual,2.8",
            ["Content"] = "我宣布，因为其他三位比武者的缺席，宴山亭的弟子刻舟，正式成为华胥第一飘零人。",
            ["ContentKR"] = "다른 세 명의 참가자가 불참하였으므로, 연산정의 제자 각주가 화서 제일의 나그네가 되었음을 정식으로 선포한다.",
            ["DialogueId"] = 80210453,
            ["FinalCamera"] = "399.097656,36.579102,162.895508,0.000151,-2.99999,-106.198524,42.362053,175.129822,false,Manual,2.8",
            ["GUID"] = "C8CC6772",
            ["NextDialogue"] = 80210454,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6772",
            },
        [80210454] = {
            ["Camera"] = "511.71875,-314.994141,144.21875,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
            ["Content"] = "就这么宣布了？",
            ["ContentKR"] = "이렇게 해버린다고?",
            ["DialogueId"] = 80210454,
            ["FinalCamera"] = "491.65625,-286.541504,141.78418,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
            ["GUID"] = "C8CC679C",
            ["NextDialogue"] = 80210455,
            ["SpeakNpcId"] = 790008,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC679C",
            },
        [80210455] = {
            ["Camera"] = "434.003906,248.654785,121.818359,0.000152,1.999995,-107.80146,42.362053,398.766113,false,Manual,2.8",
            ["Content"] = "那不然呢？我师父就让我这么做的。我记得清清楚楚，当时他和我说，如果上一届的参加者们不想参加比武，那么也不用强行劝说。",
            ["ContentKR"] = "뭐 어떠냐? 사부님께서 이렇게 하라고 하셨다. 정확히 말하면, 지난 회 참가자들이 오지 않겠다고 한다면, 굳이 강권할 필요도 없다고 말이지.",
            ["DialogueId"] = 80210455,
            ["FinalCamera"] = "408.511719,168.209961,124.753906,0.000153,2.99999,-105.801682,42.362053,306.325958,false,Manual,2.8",
            ["GUID"] = "C8CC67C6",
            ["NextDialogue"] = 80210456,
            ["SpeakNpcId"] = 790067,
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC67C6",
            },
        [80210456] = {
            ["Content"] = "毕竟，如果参加人数少了，那么赢到最后的可能性也会跟着变大，说不定只要比试一场就能夺冠了。",
            ["ContentKR"] = "참가 인원이 적어질수록 끝까지 남을 확률도 높아지지 않느냐. 한 판 승부로 천하제일이 될 수 있을지도 모르고.",
            ["DialogueId"] = 80210456,
            ["GUID"] = "C8CC67F0",
            ["NextDialogue"] = 80210457,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC67F0",
            },
        [80210457] = {
            ["Content"] = "师父还是太保守了，实际上一场都没比试，这才叫真正的天下无敌！",
            ["ContentKR"] = "근데 사부님께서 괜한 걱정을 하셨구나. 진정한 천하제일이라면 대결조차 필요 없는 법이지!",
            ["DialogueId"] = 80210457,
            ["GUID"] = "C8CC681A",
            ["NextDialogue"] = 80210458,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC681A",
            },
        [80210458] = {
            ["Camera"] = "511.71875,-314.994141,144.21875,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
            ["Content"] = "我还以为你会再低落一会儿。",
            ["ContentKR"] = "난 네가 더 우울해할 줄 알았는데.",
            ["DialogueId"] = 80210458,
            ["FinalCamera"] = "491.65625,-286.541504,141.78418,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
            ["GUID"] = "C8CC6844",
            ["NextDialogue"] = 80210459,
            ["SpeakNpcId"] = 790008,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6844",
            },
        [80210459] = {
            ["Camera"] = "502.972656,27.527832,181.694336,0.000158,-7.999989,-134.198502,42.362053,234.67363,false,Manual,2.8",
            ["Content"] = "黯然神伤刻舟求剑这种事情，不适合我，有其他人做就行了。",
            ["ContentKR"] = "낙담하거나 괜한 고집 부리는 건 이 각주에겐 어울리지 않는다. 그런 건 다른 사람이나 하면 돼.",
            ["DialogueId"] = 80210459,
            ["FinalCamera"] = "481.535156,5.483887,177.371094,0.000159,-7.999968,-134.198471,42.362053,201.77124,false,Manual,2.8",
            ["GUID"] = "C8CC686E",
            ["NextDialogue"] = 80210460,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:DisagreeHead",
                },
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC686E",
            },
        [80210460] = {
            ["Content"] = "我要做的，是斩落师父，师兄，以及诸位前辈们为之郁结的大风九章。",
            ["ContentKR"] = "내가 할 일은 사부와 사형, 그리고 수많은 선배들에게 한을 준 대풍구장을 없애는 거다.",
            ["DialogueId"] = 80210460,
            ["GUID"] = "C8CC6898",
            ["NextDialogue"] = 80210461,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6898",
            },
        [80210461] = {
            ["Content"] = "等到这件事告一段落后，我大概才能和那些飘零人小说中描写的一样，退隐山林了。",
            ["ContentKR"] = "이 일만 마무리되면, 나도 나그네 소설에 나오는 것처럼, 조용히 은퇴할 수 있을 거야.",
            ["DialogueId"] = 80210461,
            ["GUID"] = "C8CC68C2",
            ["NextDialogue"] = 80210462,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC68C2",
            },
        [80210462] = {
            ["Camera"] = "511.71875,-314.994141,144.21875,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
            ["Content"] = "依你的性格，我感觉你闲不下来。",
            ["ContentKR"] = "네 성격으론 '조용히'가 안 될 것 같은데.",
            ["DialogueId"] = 80210462,
            ["FinalCamera"] = "491.65625,-286.541504,141.78418,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
            ["GUID"] = "C8CC68EC",
            ["NextDialogue"] = 80210463,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:DisagreeHead",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC68EC",
            },
        [80210463] = {
            ["Camera"] = "377.449219,42.706543,179.00293,0.000195,-7.99994,-98.99649,42.362053,171.145584,false,Manual,2.8",
            ["Content"] = "确实，那就等那时再说吧。",
            ["ContentKR"] = "하긴 그런가, 그럼 그때 가서 생각하자.",
            ["DialogueId"] = 80210463,
            ["FinalCamera"] = "377.128906,35.079102,177.938477,0.000195,-7.99994,-98.99649,42.362053,171.145584,false,Manual,2.8",
            ["GUID"] = "C8CC6916",
            ["NextDialogue"] = 80210464,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:AgreeHead",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6916",
            },
        [80210464] = {
            ["Camera"] = "855.464844,-598.185059,132.694336,0.0,0.0,136.606979,26.65424,695.636841,false,Manual,2.8",
            ["Content"] = "今日拔得头筹成为第一飘零人，应该开心过活，不去管那以后的事。来吧，朋友，且歌且醉，且醉且歌！",
            ["ContentKR"] = "오늘은 천하제일 나그네 자리에 오른 날이니, 기쁘게 보내야 하지 않겠느냐. 나중 일들은 잊고, 거나하게 취해 봐야지!",
            ["DialogueId"] = 80210464,
            ["FinalCamera"] = "1130.59375,-914.811523,132.694336,0.0,0.0,133.406891,26.65424,275.423279,false,Manual,2.8",
            ["GUID"] = "C8CC6940",
            ["NextDialogue"] = 80210465,
            ["SpeakNpcId"] = 790067,
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6940",
            },
        [80210465] = {
            ["Content"] = "那些曾经锋芒毕露的，生死相许的，快意恩仇的，都早已成为风中一缕轻尘。",
            ["ContentKR"] = "한때의 놀라운 재능도, 간절한 맹세도, 통쾌한 복수도, 이제는 모두 한낱 먼지가 되었다.",
            ["DialogueId"] = 80210465,
            ["GUID"] = "C8CC696A",
            ["NextDialogue"] = 80210466,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC696A",
            },
        [80210466] = {
            ["Content"] = "最终都只剩下满头霜雪与轻叹一声，少年子弟江湖老。",
            ["ContentKR"] = "결국엔 성성한 백발과 덧없는 탄식만 남을 뿐이니, 혈기 왕성했던 청춘은 끝내 강호에 저물어 간다.",
            ["DialogueId"] = 80210466,
            ["GUID"] = "C8CC6994",
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6994",
            },
        [80210467] = {
            ["DialogueId"] = 80210467,
            ["Duration"] = 1,
            ["GUID"] = "C8CC6995",
            ["IsBlack"] = 1,
            },
        [80220101] = {
            ["Content"] = "……",
            ["DialogueId"] = 80220101,
            ["GUID"] = "C8D29652",
            ["NextDialogue"] = 80220102,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29652",
            },
        [80220102] = {
            ["Content"] = "师兄？",
            ["ContentKR"] = "사형?",
            ["DialogueId"] = 80220102,
            ["GUID"] = "C8D2967C",
            ["NextDialogue"] = 80220103,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D2967C",
            },
        [80220103] = {
            ["Content"] = "是不夏啊。",
            ["ContentKR"] = "불하였구나.",
            ["DialogueId"] = 80220103,
            ["GUID"] = "C8D296A6",
            ["NextDialogue"] = 80220104,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D296A6",
            },
        [80220104] = {
            ["Content"] = "老远就听到笛声了，果然是你。",
            ["ContentKR"] = "멀리서 피리 소리가 들렸거든. 역시 사형이었네.",
            ["DialogueId"] = 80220104,
            ["GUID"] = "C8D296D0",
            ["NextDialogue"] = 80220105,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D296D0",
            },
        [80220105] = {
            ["Content"] = "你找我有事？",
            ["ContentKR"] = "무슨 일이야?",
            ["DialogueId"] = 80220105,
            ["GUID"] = "C8D296FA",
            ["NextDialogue"] = 80220106,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D296FA",
            },
        [80220106] = {
            ["Content"] = "其实是……师兄，帮忙看看它吧。",
            ["ContentKR"] = "그게... 사형, 얘 상태 좀 봐 줘.",
            ["DialogueId"] = 80220106,
            ["GUID"] = "C8D29724",
            ["NextDialogue"] = 80220107,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29724",
            },
        [80220107] = {
            ["Content"] = "我和刻舟师兄在山外山外面发现了这只小狐狸，它被野兽咬伤了。",
            ["ContentKR"] = "각주 사형이랑 산외산 밖에 나갔다가 발견한 꼬마 여우인데, 들짐승한테 물렸나 봐.",
            ["DialogueId"] = 80220107,
            ["GUID"] = "C8D2974E",
            ["NextDialogue"] = 80220108,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D2974E",
            },
        [80220108] = {
            ["Content"] = "刻舟师兄粗枝大叶，完全不知道怎么处理它身上的伤，就只能来找师兄你了。放着不管的话，它很快便会死掉的。",
            ["ContentKR"] = "그냥 내버려두면 금방 죽을 거 같아서 얼른 사형한테 데려온 거야. 각주 사형은 덤벙이라 처치법을 모르더라고.",
            ["DialogueId"] = 80220108,
            ["GUID"] = "C8D29778",
            ["NextDialogue"] = 80220109,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29778",
            },
        [80220109] = {
            ["Content"] = "……",
            ["ContentKR"] = "......",
            ["DialogueId"] = 80220109,
            ["GUID"] = "C8D297A2",
            ["NextDialogue"] = 80220110,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D297A2",
            },
        [80220110] = {
            ["Content"] = "师兄？",
            ["ContentKR"] = "사형?",
            ["DialogueId"] = 80220110,
            ["GUID"] = "C8D297CC",
            ["NextDialogue"] = 80220111,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D297CC",
            },
        [80220111] = {
            ["Content"] = "没什么。让我来看看吧。",
            ["ContentKR"] = "아무것도 아니야. 상처 좀 보자.",
            ["DialogueId"] = 80220111,
            ["GUID"] = "C8D297F6",
            ["NextDialogue"] = 80220112,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D297F6",
            },
        [80220112] = {
            ["Content"] = "我们发现它的时候，它就那么蜷在岩石的缝隙之间，死死地盯着外面。我们在附近找到了几只断了气的大狐狸，顺着它们的血迹才找到了这个小家伙。",
            ["ContentKR"] = "여우 몇 마리가 죽어 있길래, 각주 사형이랑 핏자국을 따라가 봤거든. 그런데 얘가 바위틈에 웅크리고 앉아서 밖을 엄청 노려보고 있는 거야.",
            ["DialogueId"] = 80220112,
            ["GUID"] = "C8D29820",
            ["NextDialogue"] = 80220113,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29820",
            },
        [80220113] = {
            ["Content"] = "刻舟师兄把它抱起来的时候，它没有叫，也没有害怕。或者说……它太小了，小到甚至不明白发生了什么，只能这么颤抖着被带来这里。",
            ["ContentKR"] = "사형이 안아 들었는데도 안 울고 가만히 있더라. 너무 어려서... 아무것도 모르니까, 그냥 바들바들 떨면서 여기까지 안겨 온 것 같아.",
            ["DialogueId"] = 80220113,
            ["GUID"] = "C8D2984A",
            ["NextDialogue"] = 80220114,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D2984A",
            },
        [80220114] = {
            ["Content"] = "……伤口处理好了。",
            ["ContentKR"] = "...일단 치료는 했어.",
            ["DialogueId"] = 80220114,
            ["GUID"] = "C8D29874",
            ["NextDialogue"] = 80220115,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29874",
            },
        [80220115] = {
            ["Content"] = "让刻舟去砍些木材回来，我给它搭个窝避雨。",
            ["ContentKR"] = "비 피할 집을 만들어 주게, 각주한테 나무 좀 해 오라고 해.",
            ["DialogueId"] = 80220115,
            ["GUID"] = "C8D2989E",
            ["NextDialogue"] = 80220116,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D2989E",
            },
        [80220116] = {
            ["Content"] = "师兄你的意思是……我们可以养它吗？",
            ["ContentKR"] = "사형 얘기는 그러니까... 키워도 된다는 거네?",
            ["DialogueId"] = 80220116,
            ["GUID"] = "C8D298C8",
            ["NextDialogue"] = 80220117,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D298C8",
            },
        [80220117] = {
            ["Content"] = "太好了，我这就去！嗯嗯，还得给它取个名字……就叫你“小橙子”吧！小狐狸！",
            ["ContentKR"] = "야호! 얼른 갔다 올게! 으음, 이름도 지어 줘야지... 좋아, 넌 이제부터 '귤이'야!",
            ["DialogueId"] = 80220117,
            ["GUID"] = "C8D298F2",
            ["NextDialogue"] = 80220118,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D298F2",
            },
        [80220118] = {
            ["Content"] = "一年后",
            ["ContentKR"] = "1년 후",
            ["DialogueId"] = 80220118,
            ["GUID"] = "C8D2991C",
            ["NextDialogue"] = 80220119,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D2991C",
            },
        [80220119] = {
            ["Content"] = "不夏？",
            ["ContentKR"] = "불하야?",
            ["DialogueId"] = 80220119,
            ["GUID"] = "C8D29946",
            ["NextDialogue"] = 80220120,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29946",
            },
        [80220120] = {
            ["Content"] = "……",
            ["ContentKR"] = "......",
            ["DialogueId"] = 80220120,
            ["GUID"] = "C8D29970",
            ["NextDialogue"] = 80220121,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29970",
            },
        [80220121] = {
            ["Content"] = "不夏。",
            ["ContentKR"] = "불하야.",
            ["DialogueId"] = 80220121,
            ["GUID"] = "C8D2999A",
            ["NextDialogue"] = 80220122,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D2999A",
            },
        [80220122] = {
            ["Content"] = "师兄！你回来啦？",
            ["ContentKR"] = "사형! 언제 왔어?",
            ["DialogueId"] = 80220122,
            ["GUID"] = "C8D299C4",
            ["NextDialogue"] = 80220123,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D299C4",
            },
        [80220123] = {
            ["Content"] = "你的耳朵？",
            ["ContentKR"] = "귀는 좀 어떠니?",
            ["DialogueId"] = 80220123,
            ["GUID"] = "C8D299EE",
            ["NextDialogue"] = 80220124,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D299EE",
            },
        [80220124] = {
            ["Content"] = "没事没事，只是有一只耳朵偶尔听不清而已，另一只好着呢！……嗯，一定是耳朵告诉我，我又该睡大觉了！",
            ["ContentKR"] = "괜찮아! 가끔 한쪽이 잘 안 들리긴 해도, 나머지 하나는 멀쩡해! ...음, 귀가 나보고 잠 좀 자라고 투정 부리나 봐!",
            ["DialogueId"] = 80220124,
            ["GUID"] = "C8D29A18",
            ["NextDialogue"] = 80220125,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29A18",
            },
        [80220125] = {
            ["Content"] = "……不要怠惰。若不是你与刻舟偷懒被发现，师父也不会罚你们在这里抄书三天，磨砺心性。你与刻舟天赋有别，若继续和他一般，迟早会被拖累。",
            ["ContentKR"] = "...게으름 피우지 마. 사흘 내내 책만 베껴 쓰게 된 건, 수련을 팽개치고 각주랑 놀러 다녀서잖아. 너하고 각주는 타고난 자질이 달라. 자꾸 휩쓸리다간 너만 뒤처져.",
            ["DialogueId"] = 80220125,
            ["GUID"] = "C8D29A42",
            ["NextDialogue"] = 80220126,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29A42",
            },
        [80220126] = {
            ["Content"] = "至于你的耳朵，我想还是得早日去皓京寻得药师来瞧瞧。",
            ["ContentKR"] = "그리고 귀는, 조만간 호경에 가서 약사를 만나 보자.",
            ["DialogueId"] = 80220126,
            ["GUID"] = "C8D29A6C",
            ["NextDialogue"] = 80220127,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29A6C",
            },
        [80220127] = {
            ["Content"] = "知道啦知道啦——师兄还那么年轻，就像师父那个老头子一样唠唠叨叨的。",
            ["ContentKR"] = "예~ 예~ 사형은 할아버지도 아닌데, 스승님처럼 잔소리가 많다니까.",
            ["DialogueId"] = 80220127,
            ["GUID"] = "C8D29A96",
            ["NextDialogue"] = 80220128,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29A96",
            },
        [80220128] = {
            ["Content"] = "对了对了，小橙子怎么样了？昨天下了那么大的雨，我有点担心……",
            ["ContentKR"] = "아, 참, 귤이는? 어제 비가 엄청 쏟아져서 좀 걱정되는데...",
            ["DialogueId"] = 80220128,
            ["GUID"] = "C8D29AC0",
            ["NextDialogue"] = 80220129,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29AC0",
            },
        [80220129] = {
            ["Content"] = "今天我去后山看它，此前给它造的小窝被山石砸坏了。它蜷缩在那些折断的木板下面，任凭雨水渗过缝隙流淌在它身上。",
            ["ContentKR"] = "뒷산에 가 봤더니, 전에 지어준 집이 굴러떨어진 바위에 맞아 무너져 있었어. 귤이는 부서진 판자 밑에서 웅크린 채 비를 맞고 있었고.",
            ["DialogueId"] = 80220129,
            ["GUID"] = "C8D29AEA",
            ["NextDialogue"] = 80220130,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29AEA",
            },
        [80220130] = {
            ["Content"] = "我把窝修补好了，又放了些干草。但它还是老样子，蜷在那儿发抖。",
            ["ContentKR"] = "집도 고치고 건초도 깔아 줬지만, 여전히 똑같이 몸을 말고 벌벌 떨고 있더라고.",
            ["DialogueId"] = 80220130,
            ["GUID"] = "C8D29B14",
            ["NextDialogue"] = 80220131,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29B14",
            },
        [80220131] = {
            ["Content"] = "唉……这叫我怎么放心得下呀。",
            ["ContentKR"] = "어휴... 정말 걱정되네.",
            ["DialogueId"] = 80220131,
            ["GUID"] = "C8D29B3E",
            ["NextDialogue"] = 80220132,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29B3E",
            },
        [80220132] = {
            ["Content"] = "你们在干什么？不夏，你的书抄完了？",
            ["ContentKR"] = "거기서 뭐 하느냐? 불하야, 책은 다 베껴 쓴 게지?",
            ["DialogueId"] = 80220132,
            ["GUID"] = "C8D29B68",
            ["NextDialogue"] = 80220133,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29B68",
            },
        [80220133] = {
            ["Content"] = "啊，师父，我……我们只是在商量武学！今天早上煜明师兄使出了一招枪，特别好看前所未见，我看了就也想学一学，所以正在和他讨教……没干什么，嘿嘿。",
            ["ContentKR"] = "앗, 스승님! 저희는... 무예 이야기 중이었어요! 아침에 욱명 사형이 보여 준 창술이 너무 멋져서, 좀 가르쳐 달라고 조르고 있었거든요... 별일 아니에요, 헤헤.",
            ["DialogueId"] = 80220133,
            ["GUID"] = "C8D29B92",
            ["NextDialogue"] = 80220134,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29B92",
            },
        [80220134] = {
            ["Content"] = "是的。",
            ["ContentKR"] = "그렇습니다.",
            ["DialogueId"] = 80220134,
            ["GUID"] = "C8D29BBC",
            ["NextDialogue"] = 80220135,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29BBC",
            },
        [80220135] = {
            ["Content"] = "唉，你们俩，一个说谎的时候话会变多，一个说谎的时候话会变少。当为师是你们俩养的那小狐狸一样不通人言吗？",
            ["ContentKR"] = "어허, 한 놈은 거짓말을 하면 말이 많아지고, 한 놈은 말수가 주는구나. 내가 저 여우마냥 사람 말을 못 알아 들을 줄 알았더냐?",
            ["DialogueId"] = 80220135,
            ["GUID"] = "C8D29BE6",
            ["NextDialogue"] = 80220136,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29BE6",
            },
        [80220136] = {
            ["Content"] = "原来……师父都知道了呀。",
            ["ContentKR"] = "다... 알고 계셨네요.",
            ["DialogueId"] = 80220136,
            ["GUID"] = "C8D29C10",
            ["NextDialogue"] = 80220137,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29C10",
            },
        [80220137] = {
            ["Content"] = "为师只是老了不是傻了！一年前你们把这小东西捡来的时候我就知道了，毕竟它也时不时到处撒欢。",
            ["ContentKR"] = "내가 늙었다고 바보인 줄 아느냐! 1년 전에 주워 왔을 때부터 알고 있었다. 녀석이 오죽 신나게 뛰어다녔어야지.",
            ["DialogueId"] = 80220137,
            ["GUID"] = "C8D29C3A",
            ["NextDialogue"] = 80220138,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29C3A",
            },
        [80220138] = {
            ["Content"] = "这几天没有见它，特意寻过来看一看，发现你们俩在这边愁眉苦脸，想问问怎么回事，没想到还和我不老实。",
            ["ContentKR"] = "요 며칠 녀석이 안 보이길래 찾아왔더니, 둘이 죽상을 하고 있어 무슨 일인지 물어본 것이다. 끝까지 시치미를 뗄 줄이야.",
            ["DialogueId"] = 80220138,
            ["GUID"] = "C8D29C64",
            ["NextDialogue"] = 80220139,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29C64",
            },
        [80220139] = {
            ["Content"] = "哎呀，这不是因为师父一直仙风道骨，是武林耆宿，想着你可能更喜欢什么鹤呀鹿呀之类的动物，不喜欢狐狸，所以不敢告诉你嘛。",
            ["ContentKR"] = "에이~ 스승님은 워낙 도인 같고, 무림의 큰 어르신이시니까, 학이나 사슴이나 좋아하시지, 여우는 싫어하시는 줄 알고 말씀 안 드렸죠.",
            ["DialogueId"] = 80220139,
            ["GUID"] = "C8D29C8E",
            ["NextDialogue"] = 80220140,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29C8E",
            },
        [80220140] = {
            ["Content"] = "还在饶舌，又是跟刻舟学的吧。为师什么时候讲究那些了。说吧，遇到什么问题了？",
            ["ContentKR"] = "입만 살았구나, 또 각주에게 배운 게냐? 내가 언제부터 그런 걸 따졌다는 건지 원. 말해 보거라, 무슨 일이 있었던 거냐?",
            ["DialogueId"] = 80220140,
            ["GUID"] = "C8D29CB8",
            ["NextDialogue"] = 80220141,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29CB8",
            },
        [80220141] = {
            ["Content"] = "（不夏和煜明把“小橙子”的事告诉了宴山亭。）",
            ["ContentKR"] = "(불하와 욱명이 연산정에게 '귤이'에 대해 털어놓는다.)",
            ["DialogueId"] = 80220141,
            ["GUID"] = "C8D29CE2",
            ["NextDialogue"] = 80220142,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29CE2",
            },
        [80220142] = {
            ["Content"] = "哈哈，我当是什么事。要是我，我就把它拎起来，拎到它来的地方去。山外山不是它的家，外面的山林才是。",
            ["ContentKR"] = "허허, 난 또 뭐라고. 목덜미를 잡아다, 원래 있던 곳에 데려다 놓으면 되지 않느냐. 녀석의 집은, 산외산이 아닌 숲 아니더냐.",
            ["DialogueId"] = 80220142,
            ["GUID"] = "C8D29D0C",
            ["NextDialogue"] = 80220143,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29D0C",
            },
        [80220143] = {
            ["Content"] = "那……那怎么行！它饿的时候谁来喂食，冷的时候谁来给它往窝里多塞点棉絮？",
            ["ContentKR"] = "그건... 안 돼요! 밥도 챙겨 줘야 하고, 춥지 않게 집에 솜도 넣어 줘야 하는걸요?",
            ["DialogueId"] = 80220143,
            ["GUID"] = "C8D29D36",
            ["NextDialogue"] = 80220144,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29D36",
            },
        [80220144] = {
            ["Content"] = "你看，就是因为你总做这些，它才一直长不大的。",
            ["ContentKR"] = "감싸고돌기만 하니, 녀석이 홀로 서지 못하는 게야.",
            ["DialogueId"] = 80220144,
            ["GUID"] = "C8D29D60",
            ["NextDialogue"] = 80220145,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29D60",
            },
        [80220145] = {
            ["Content"] = "你们给它搭了避雨的窝，却没有教会它如何度过寒冬。给了它果腹之物，却没有教会它如何捕猎。",
            ["ContentKR"] = "너희는 거처는 마련해 줬지만, 겨울을 나는 법은 알려 주지 않았다. 먹이는 주었어도, 사냥은 가르치지 않았지.",
            ["DialogueId"] = 80220145,
            ["GUID"] = "C8D29D8A",
            ["NextDialogue"] = 80220146,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29D8A",
            },
        [80220146] = {
            ["Content"] = "它饿了冷了都等着你们照顾，要如何自己谋生？要是哪天没我的傻徒儿盯着，一场大雨就能要了它的小命啦。",
            ["ContentKR"] = "춥든 배고프든 너희만 기다리고 있으니, 어찌 홀로 살아가겠느냐? 너희가 한눈판 새에 큰비라도 내리면, 녀석은 그 길로 끝이다.",
            ["DialogueId"] = 80220146,
            ["GUID"] = "C8D29DB4",
            ["NextDialogue"] = 80220147,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29DB4",
            },
        [80220147] = {
            ["Content"] = "那、那师父的意思是……",
            ["ContentKR"] = "그, 그러니까 스승님 말씀은...",
            ["DialogueId"] = 80220147,
            ["GUID"] = "C8D29DDE",
            ["NextDialogue"] = 80220148,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29DDE",
            },
        [80220148] = {
            ["Content"] = "纵是你再不舍，它终究还是要回归山林的。它是头小野兽，一味地庇护只会让它失去生存的能力。",
            ["ContentKR"] = "어려도 짐승이니, 정이 들었더라도 결국은 숲으로 돌려보내야 한다. 마냥 끼고 도는 건, 녀석을 제 앞가림도 못하게 만들 뿐이야.",
            ["DialogueId"] = 80220148,
            ["GUID"] = "C8D29E08",
            ["NextDialogue"] = 80220149,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29E08",
            },
        [80220149] = {
            ["Content"] = "……我明白了。让我和两位师兄商量商量……",
            ["ContentKR"] = "...알겠어요. 사형들이랑 상의해 볼게요...",
            ["DialogueId"] = 80220149,
            ["GUID"] = "C8D29E32",
