            ["GUID"] = "C8D2A888",
            ["NextDialogue"] = 80220213,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2A888",
            },
        [80220213] = {
            ["Content"] = "汝眼前种种，乃旧魇缚身，不得解脱。",
            ["ContentKR"] = "눈앞의 환영들이, 과거의 굴레가 되어 그대를 옭아매고 있구나.",
            ["DialogueId"] = 80220213,
            ["GUID"] = "C8D2A8B2",
