            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2A8B2",
            },
        [80220214] = {
            ["Content"] = "……我知道。",
            ["ContentKR"] = "...알고 있어.",
            ["DialogueId"] = 80220214,
            ["GUID"] = "C8D2A8DC",
            ["NextDialogue"] = 80220215,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2A8DC",
            },
        [80220215] = {
            ["Content"] = "此其墓乎？",
            ["ContentKR"] = "이게 그 아이의 무덤인가?",
            ["DialogueId"] = 80220215,
            ["GUID"] = "C8D2A906",
            ["NextDialogue"] = 80220216,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2A906",
            },
        [80220216] = {
            ["Content"] = "她……变成了那样，我甚至无法捡回她的遗骨。我只能寻得她的一些旧衣物，葬在这里。",
            ["ContentKR"] = "그런 모습으로... 변해서 유골조차 수습하지 못했어. 여기에 묻혀 있는 건 몇 안 되는 옷가지뿐이야.",
            ["DialogueId"] = 80220216,
            ["GUID"] = "C8D2A930",
            ["NextDialogue"] = 80220217,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2A930",
            },
        [80220217] = {
            ["Content"] = "之所以选择这里，而非山外山……",
            ["ContentKR"] = "산외산이 아니라, 여길 선택한 이유는...",
            ["DialogueId"] = 80220217,
            ["GUID"] = "C8D2A95A",
            ["NextDialogue"] = 80220218,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2A95A",
            },
        [80220218] = {
            ["Content"] = "是因为她的最后一句话是，“如果当时我选择了大风九章，那么结果会不会不一样。”",
            ["ContentKR"] = "그 아이가 마지막으로 그러더군. \"내가 그때 대풍구장을 따르기로 했다면, 이런 일은 없었을까?\"라고.",
            ["DialogueId"] = 80220218,
