            ["GUID"] = "C8D2AA2C",
            ["NextDialogue"] = 80220223,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2AA2C",
            },
        [80220223] = {
            ["Content"] = "……选择。",
            ["ContentKR"] = "...선택이라.",
            ["DialogueId"] = 80220223,
            ["GUID"] = "C8D2AA56",
