            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2AA56",
            },
        [80220224] = {
            ["Content"] = "太皓，如果我们选择了大风九章，那么结果会不会不一样？",
            ["ContentKR"] = "태호, 우리가 대풍구장에 순응하는 길을 택했더라면, 그런 일은 일어나지 않았을까?",
            ["DialogueId"] = 80220224,
            ["GUID"] = "C8D2AA80",
            ["NextDialogue"] = 80220225,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2AA80",
            },
        [80220225] = {
            ["Content"] = "汝等飘零人渴求无拘，却不知鸢无线而坠，川无堤不海。",
            ["ContentKR"] = "나그네는 속박 없는 삶을 갈망하지만, 줄 없는 연은 날지 못하고, 둑 없는 강은 바다에 닿지 못하는 법이다.",
            ["DialogueId"] = 80220225,
            ["GUID"] = "C8D2AAAA",
            ["NextDialogue"] = 80220226,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2AAAA",
            },
        [80220226] = {
            ["Content"] = "往事已矣，来日可期。迷途知返，犹未晚也。",
            ["ContentKR"] = "과거는 돌이킬 수 없어도, 훗날은 기약할 수 있지. 바른길로 되돌아오기 늦은 때란 없느니라.",
            ["DialogueId"] = 80220226,
            ["GUID"] = "C8D2AAD4",
            ["NextDialogue"] = 80220227,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2AAD4",
            },
        [80220227] = {
            ["Content"] = "言尽于此，汝其慎思。",
            ["ContentKR"] = "더 할 말은 없다. 잘 생각해 보거라.",
            ["DialogueId"] = 80220227,
            ["GUID"] = "C8D2AAFE",
            ["NextDialogue"] = 80220228,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2AAFE",
            },
        [80220228] = {
