            ["VoiceName"] = "voice/$Locale$/char/Aote/vo_topic_04_2",
            ["bForbidSkipOptions"] = true,
            },
        }
  end },
  { MinKey = 90160501, MaxKey = 90220301, Loader = function()
      return {
        [90160501] = {
            ["Content"] = "嗯……等等，你手上怎么才这么几个钱，是不是又把你那份报酬随便分给其他人了？",
            ["ContentKR"] = "음... 잠깐만. 왜 가진 돈이 그것밖에 없어? 또 보상을 다른 사람에게 나눠준 거야?",
            ["DialogueId"] = 90160501,
            ["GUID"] = "E1B51532",
            ["LookAt"] = {
                [1] = "85102:n(0)",
                [2] = "0:n(85102)",
                },
            ["NextDialogue"] = 90160503,
            ["SpeakNpcId"] = 85102,
            ["TalkActionId"] = {
                [1] = "85102:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Aote/vo_topic_05_1",
            },
        [90160503] = {
            ["Content"] = "他们比我更需要那些钱。",
            ["ContentKR"] = "나보단 그들에게 더 필요하거든.",
            ["DialogueId"] = 90160503,
            ["GUID"] = "E1B51586",
            ["NextDialogue"] = 90160504,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "85102:Confident_End",
                },
            },
        [90160504] = {
            ["Content"] = "你……哎，算了，这大概就是你的优点吧。手头紧的时候记得跟我说。",
            ["ContentKR"] = "너... 에휴, 그래. 이런 게 네 장점이겠지. 돈이 부족하면 나한테 말해.",
            ["DialogueId"] = 90160504,
            ["GUID"] = "E1B515B0",
            ["NextDialogue"] = 90160505,
            ["SpeakNpcId"] = 85102,
            ["TalkActionId"] = {
                [1] = "85102:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Aote/vo_topic_05_2",
            },
        [90160505] = {
            ["Content"] = "好，那我现在手头紧了！",
            ["ContentKR"] = "좋아. 그럼 난 지금 돈이 부족해!",
            ["DialogueId"] = 90160505,
            ["GUID"] = "E1B515DA",
            ["NextDialogue"] = 90160506,
            ["SpeakNpcId"] = 100001,
            },
        [90160506] = {
            ["Content"] = "……我这是身为朋友在关心你，你别得寸进尺耍无赖啊！",
            ["ContentKR"] = "...친구로서 걱정해서 한 말인데, 이런 걸로 장난치지 말라고!",
            ["DialogueId"] = 90160506,
            ["GUID"] = "E1B51604",
            ["NextOptions"] = {
