            ["bForbidSkipOptions"] = true,
            },
        [90170002] = {
            ["Content"] = "聊点别的",
            ["ContentKR"] = "다른 얘기를 하자",
            ["DialogueId"] = 90170002,
            ["GUID"] = "90170002.0",
            ["NextDialogue"] = 90170001,
            },
        [90170003] = {
            ["Content"] = "再见",
            ["ContentKR"] = "안녕",
            ["DialogueId"] = 90170003,
            ["GUID"] = "90170003.0",
            },
        [90170101] = {
            ["Content"] = "嗯……大概是为那些被舍弃的物品找到合适的主人的营生，唔，也能让那些遭受物资匮乏之苦的人，得到更好的生活。",
            ["ContentKR"] = "음... 대충 말하자면, 버려진 물건들에 주인을 찾아주고, 음, 경제적으로 부족한 사람들은 더 나은 삶을 살 수 있게 해주는 거죠.",
            ["DialogueId"] = 90170101,
