            ["TalkActionId"] = {
                [1] = "83301:Sigh_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Maer/vo_topic_02_3",
            },
        [90170205] = {
            ["Content"] = "捡垃圾也真不容易……",
            ["ContentKR"] = "쓰레기 줍는 것도 쉽지 않구나...",
            ["DialogueId"] = 90170205,
            ["GUID"] = "E1BB4D42",
            ["NextDialogue"] = 90170206,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "83301:Sigh_End",
                },
            },
        [90170206] = {
            ["Content"] = "可不是嘛，嘿，我就说你是个明眼人！",
            ["ContentKR"] = "그러니까요. 역시, 보는 눈이 있군요!",
            ["DialogueId"] = 90170206,
            ["GUID"] = "E1BB4D6C",
            ["NextOptions"] = {
                [1] = 90170002,
                [2] = 90170003,
                },
            ["SpeakNpcId"] = 83301,
            ["VoiceName"] = "voice/$Locale$/char/Maer/vo_topic_02_4",
            ["bForbidSkipOptions"] = true,
            },
        [90170301] = {
            ["Content"] = "不，你说反啦！我非常喜欢冰湖城。只是我常常回想起和爸爸一起在雪原上流浪的日子，我的整个童年都是在那里度过的。",
            ["ContentKR"] = "아니요. 반대예요! 전 아이스레이크 시티를 정말 좋아해요. 다만 아빠와 설원을 떠돌던 시절이 종종 떠올라서 그래요. 제 어린 시절은 모두 그곳에서 보냈거든요.",
            ["DialogueId"] = 90170301,
            ["GUID"] = "E1BB5D02",
            ["LookAt"] = {
                [1] = "83301:n(0)",
                [2] = "0:n(83301)",
                },
            ["NextDialogue"] = 90170303,
            ["SpeakNpcId"] = 83301,
            ["VoiceName"] = "voice/$Locale$/char/Maer/vo_topic_03_1",
            },
        [90170303] = {
            ["Content"] = "你怎么看待那些时光呢？",
            ["ContentKR"] = "그 시절에 대해 어떻게 생각해?",
            ["DialogueId"] = 90170303,
            ["GUID"] = "E1BB5D56",
            ["NextDialogue"] = 90170304,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "83301:Agree",
                },
            },
        [90170304] = {
            ["Content"] = "从这里看向雪原，美得像童话里的冰国雪国。可一步一步走进去，又会觉得自己好小好小。在齐膝的雪地里迈着腿，不管走了多久，看到的景色都不会改变。",
            ["ContentKR"] = "여기서 설원을 바라보면, 마치 동화 속 아름다운 얼음 왕국 같죠. 하지만 가까이 갈수록 자신이 아주 작게 느껴질 거예요. 무릎까지 쌓인 눈길을 계속 걷고 걸어도 그 주변 풍경이 변하지 않거든요.",
            ["DialogueId"] = 90170304,
            ["GUID"] = "E1BB5D80",
            ["NextDialogue"] = 90170305,
            ["SpeakNpcId"] = 83301,
            ["TalkActionId"] = {
                [1] = "83301:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Maer/vo_topic_03_2",
            },
        [90170305] = {
            ["Content"] = "我不讨厌那段时光，但我最喜欢的，果然还是热热闹闹，充满烟火味的冰湖城！",
            ["ContentKR"] = "그 시절이 싫다는 건 아니지만, 전 역시 시끌벅적하고, 화약 냄새 가득한 아이스레이크 시티가 좋은 것 같아요!",
            ["DialogueId"] = 90170305,
            ["GUID"] = "E1BB5DAA",
            ["NextOptions"] = {
                [1] = 90170002,
                [2] = 90170003,
                },
            ["SpeakNpcId"] = 83301,
            ["TalkActionId"] = {
                [1] = "83301:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Maer/vo_topic_03_3",
            ["bForbidSkipOptions"] = true,
            },
        [90170401] = {
            ["Content"] = "是小时候和我在雪原上一起流浪的大猫！它叫“胖尾巴”，平时得用肉干贿赂才愿意给我摸摸，但那个手感——嘿嘿嘿嘿，一个字，绝啦！",
            ["ContentKR"] = "어릴 적 저와 설원을 떠돌던 큰 고양이예요! '팻테일'이라고 해요. 육포를 줘야만 만지게 해주는데, 그 느낌이 정말... 헤헤헤헤, 한 마디로 끝내줘요!",
            ["DialogueId"] = 90170401,
            ["GUID"] = "E1BB6D6A",
            ["LookAt"] = {
                [1] = "83301:n(0)",
                [2] = "0:n(83301)",
                },
            ["NextDialogue"] = 90170403,
            ["SpeakNpcId"] = 83301,
            ["TalkActionId"] = {
                [1] = "83301:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Maer/vo_topic_04_1",
            },
        [90170403] = {
            ["Content"] = "雪原大猫怎么叫？像猫还是像老虎？",
            ["ContentKR"] = "설원의 고양이는 어떻게 울어? 고양이처럼? 아니면 호랑이처럼?",
            ["DialogueId"] = 90170403,
            ["GUID"] = "E1BB6DBE",
            ["NextDialogue"] = 90170404,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "83301:Explain02_End",
                },
            },
        [90170404] = {
            ["Content"] = "嗯……反正不是喵喵喵，大概是，嗷呜——嗷呜——嗷呜——的声音！",
            ["ContentKR"] = "음... 아무튼 '야옹'은 아니에요. 어흥~ 어흥~ 어흥~ 이런 소리예요!",
            ["DialogueId"] = 90170404,
            ["GUID"] = "E1BB6DE8",
            ["NextDialogue"] = 90170405,
            ["SpeakNpcId"] = 83301,
            ["TalkActionId"] = {
                [1] = "83301:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Maer/vo_topic_04_2",
            },
        [90170405] = {
            ["Content"] = "现在还能见到它吗？",
            ["ContentKR"] = "지금도 만날 수 있어?",
            ["DialogueId"] = 90170405,
            ["GUID"] = "E1BB6E12",
            ["NextDialogue"] = 90170406,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "83301:Think_End",
                },
            },
        [90170406] = {
            ["Content"] = "胖尾巴毕竟是生活在雪原的野兽，它不愿意靠近城市，等待我们的只有分道扬镳。但它会一直留在我的记忆里，和那片雪原一起。",
            ["ContentKR"] = "팻테일은 설원에 사는 야수이다 보니 도시 가까이 오는 걸 싫어해요. 그래서 헤어질 수밖에 없었죠. 하지만 팻테일은 영원히 제 기억 속에 남아 있을 거예요. 저 설원과 함께요.",
            ["DialogueId"] = 90170406,
            ["GUID"] = "E1BB6E3C",
            ["NextOptions"] = {
                [1] = 90170002,
                [2] = 90170003,
                },
            ["SpeakNpcId"] = 83301,
            ["VoiceName"] = "voice/$Locale$/char/Maer/vo_topic_04_3",
            ["bForbidSkipOptions"] = true,
            },
        [90170501] = {
            ["Content"] = "我没有，我不是，别瞎说！我都这么大了，怎么还用这种哄小孩的称呼！算我求你了，别再提这个了！",
            ["ContentKR"] = "아니에요. 무슨 소리예요! 이상한 소리 마세요! 이렇게나 컸는데, 대체 왜 아직도 그런 아이 같은 호칭을 들어야 하는 거죠! 부탁이에요. 그렇게 부르지 말아 주세요!",
            ["DialogueId"] = 90170501,
            ["GUID"] = "E1BB7DD2",
            ["LookAt"] = {
                [1] = "83301:n(0)",
                [2] = "0:n(83301)",
                },
            ["NextDialogue"] = 90170503,
            ["SpeakNpcId"] = 83301,
            ["VoiceName"] = "voice/$Locale$/char/Maer/vo_topic_05_1",
            },
        [90170503] = {
            ["Content"] = "那玛尔洁希望被人们怎样称呼呢？",
            ["ContentKR"] = "그럼 마르제는 뭐라고 불리고 싶어?",
            ["DialogueId"] = 90170503,
            ["GUID"] = "E1BB7E26",
            ["NextDialogue"] = 90170504,
            ["SpeakNpcId"] = 100001,
            },
        [90170504] = {
            ["Content"] = "那当然是——咳咳，于城市背面孤独行走，缄默的侦探——玛尔洁小姐！今天，也为你揭示冰湖城不为人知的隐秘！",
            ["ContentKR"] = "그야 당연히, 크흠! 도시의 뒤편을 홀로 걷는 과묵한 탐정, 마르제! 오늘도 당신에게 아이스레이크 시티의 알려지지 않은 비밀을 보여드리죠!",
            ["DialogueId"] = 90170504,
            ["GUID"] = "E1BB7E50",
            ["NextDialogue"] = 90170505,
            ["SpeakNpcId"] = 83301,
            ["TalkActionId"] = {
                [1] = "83301:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Maer/vo_topic_05_2",
            },
        [90170505] = {
            ["Content"] = "嘿嘿，这才是与我相称的外号嘛~",
            ["ContentKR"] = "헤헤, 이거야말로 저랑 잘 어울리죠~",
            ["DialogueId"] = 90170505,
            ["GUID"] = "E1BB7E7A",
            ["NextOptions"] = {
                [1] = 90170002,
                [2] = 90170003,
                },
            ["SpeakNpcId"] = 83301,
            ["TalkActionId"] = {
                [1] = "83301:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Maer/vo_topic_05_3",
            ["bForbidSkipOptions"] = true,
            },
        [90170701] = {
            ["Content"] = "小菲娜！好久不见啦~想听《雪猫游侠与橘猫侦探》的后续？好！等我搬个小板凳，坐下来慢慢给你讲！",
            ["ContentKR"] = "피나! 오랜만이야~ 〈설원 고양이 협객과 치즈 고양이 탐정〉의 다음 이야기를 듣고 싶니? 좋아! 잠깐 의자만 가져온 다음에 앉아서 천천히 들려줄게!",
            ["DialogueId"] = 90170701,
            ["GUID"] = "E1BB9EA2",
            ["SpeakNpcId"] = 83301,
            ["VoiceName"] = "voice/$Locale$/char/Maer/vo_companio_02",
            },
        [90170801] = {
            ["Content"] = "典狱长大人，我可是彻头彻尾的良民！一没偷二没抢，只是从垃圾桶里拿一点点残羹剩饭果腹罢了，您再敬业，也管不到垃圾头上吧？",
            ["ContentKR"] = "교도소장님, 전 그냥 선량한 시민이에요! 훔치지도 빼앗지도 않았어요. 그저 쓰레기통에 남은 음식으로 배를 채웠을 뿐이죠. 직업 정신이 아무리 투철하셔도 쓰레기통까지 신경 쓰시는 건 아니겠죠?",
            ["DialogueId"] = 90170801,
            ["GUID"] = "E1BBAF0A",
            ["SpeakNpcId"] = 83301,
            ["VoiceName"] = "voice/$Locale$/char/Maer/vo_companio_03",
            },
        [90170901] = {
            ["Content"] = "你这日子过得也太紧巴巴了吧！好、好惨……你要不要来和我一起捡垃圾，说不定日子还能过得宽裕一点？",
            ["ContentKR"] = "너무 빠듯하게 사는 거 아니에요!? 이, 이런... 저랑 쓰레기라도 좀 줍는 건 어때요? 생활에 보탬이 될 수도 있는걸요?",
            ["DialogueId"] = 90170901,
            ["GUID"] = "E1BBBF72",
            ["SpeakNpcId"] = 83301,
            ["VoiceName"] = "voice/$Locale$/char/Maer/vo_companio_04",
            },
        [90171001] = {
            ["Content"] = "最最最善良美丽的卡米拉姐，我这里有一点小小小小的麻烦，得拜托你帮个忙——这回绝对是最后一次！呃，本月的最后一次！你一定会答应我的，对吧？",
            ["ContentKR"] = "세상에서 가장 착하고 아름다운 카밀라 언니. 저한테 아주 작은 문제가 생겼는데, 좀 도와주시겠어요? 이번이 진짜 마지막이에요! 그러니까, 이번 달의 마지막이요! 도와주실 거죠? 그렇죠?",
            ["DialogueId"] = 90171001,
            ["GUID"] = "E1BBCFDA",
            ["SpeakNpcId"] = 83301,
            ["VoiceName"] = "voice/$Locale$/char/Maer/vo_companio_05",
            },
        [90180000] = {
            ["Content"] = "耶尔：红鲤鱼，有头小绿、绿，绿鲤，绿驴，绿缕鱼…….",
            ["ContentKR"] = "예일: 간장 공장 공장장은 강 공잔, 공자, 공잔자...",
            ["DialogueId"] = 90180000,
            ["GUID"] = "E1C19467",
            ["NextDialogue"] = 90180002,
            ["SpeakNpcId"] = 83103,
            ["VoiceName"] = "voice/$Locale$/char/Yeer/vo_idle_1",
            },
        [90180001] = {
            ["Content"] = "耶尔：你来啦……天气真好……很适合做爆炸实验……唔，天气真好。",
            ["ContentKR"] = "예일: 오셨네요... 날씨가 참 좋죠... 폭발 실험하기 딱 좋은 날이에요... 으음, 날씨가 참 좋아요.",
            ["DialogueId"] = 90180001,
            ["GUID"] = "E1C1946A",
            ["LookAt"] = {
                [1] = "83103:n(0)",
                [2] = "0:n(83103)",
                },
            ["NextOptions"] = {
                [1] = 901800011,
                [2] = 901800012,
                [3] = 901800013,
                [4] = 901800014,
                },
            ["RandomOptionNum"] = 3,
            ["SpeakNpcId"] = 83103,
            ["TalkActionId"] = {
                [1] = "83103:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Yeer/vo_welcome",
            ["bForbidSkipOptions"] = true,
            },
        [90180002] = {
            ["Content"] = "奥利弗：是“红鲤鱼有头小绿驴，绿鲤鱼有头小红驴！”笨蛋耶尔，快跟我念！",
            ["ContentKR"] = "올리버: '간장 공장 공장장은 강 공장장이고 된장 공장 공장장은 장 공장장이다'겠지! 이 바보 예일아. 제대로 말하라고!",
            ["DialogueId"] = 90180002,
            ["GUID"] = "E1C19468",
            ["NextDialogue"] = 90180003,
            ["SpeakNpcId"] = 83103,
            ["VoiceName"] = "voice/$Locale$/char/Yeer/vo_idle_2",
            },
        [90180003] = {
            ["Content"] = "耶尔：好、好的！红、红鲤鱼……",
            ["ContentKR"] = "예일: 아, 알겠어! 간장, 공장...",
            ["DialogueId"] = 90180003,
            ["GUID"] = "E1C19469",
            ["SpeakNpcId"] = 83103,
            ["VoiceName"] = "voice/$Locale$/char/Yeer/vo_idle_3",
            },
        [90180004] = {
            ["Content"] = "聊点别的",
            ["ContentKR"] = "다른 얘기를 하자",
            ["DialogueId"] = 90180004,
            ["GUID"] = "90180004.0",
            ["NextDialogue"] = 90180001,
            },
        [90180005] = {
            ["Content"] = "再见",
            ["ContentKR"] = "안녕",
            ["DialogueId"] = 90180005,
            ["GUID"] = "90180005.0",
            },
        [90180101] = {
            ["Content"] = "耶尔：奥利弗不是会说话的炸弹……可能听起来有些不可思议，但……他其实是……",
            ["ContentKR"] = "예일: 올리버는 말하는 폭탄이 아니에요... 이상하게 들릴 수도 있지만... 사실 올리버는...",
            ["DialogueId"] = 90180101,
            ["GUID"] = "E1C1A4D2",
            ["LookAt"] = {
                [1] = "83103:n(0)",
                [2] = "0:n(83103)",
                },
            ["NextDialogue"] = 90180103,
            ["SpeakNpcId"] = 83103,
            ["TalkActionId"] = {
                [1] = "83103:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Yeer/vo_topic_01_1",
            },
        [90180103] = {
            ["Content"] = "奥利弗：闭嘴，被你急死了！我就是耶尔，耶尔就是我。听明白了吗？不明白也无所谓，也没指望你木屑一样的脑子能搞懂。",
            ["ContentKR"] = "올리버: 닥쳐, 답답해 죽겠네! 내가 바로 예일이고, 예일이 바로 나야. 알겠어? 이해 못 해도 상관없어. 머리가 장식인 너 같은 멍청이가 이해하길 바라지도 않았다고.",
            ["DialogueId"] = 90180103,
            ["GUID"] = "E1C1A526",
            ["NextDialogue"] = 90180104,
            ["SpeakNpcId"] = 83103,
            ["TalkActionId"] = {
                [1] = "83103:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Yeer/vo_topic_01_2",
            },
        [90180104] = {
            ["Content"] = "好没礼貌的炸弹，扔了算了。",
            ["ContentKR"] = "정말 예의 없는 폭탄이네. 던져 버려야지.",
            ["DialogueId"] = 90180104,
            ["GUID"] = "E1C1A550",
            ["NextDialogue"] = 90180105,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "83103:Angry01_End",
                },
            },
        [90180105] = {
            ["Content"] = "耶尔：奥利弗他、他他是个好孩子！虽然看看上去脾气不好，说话有点凶，还总总总是突然冒出来，但……",
            ["ContentKR"] = "예일: 오, 오, 올리버는 착한 아이예요! 조, 조금 사납고 말이 거친 데다, 하, 하, 항상 갑자기 튀어나오긴 하지만...",
            ["DialogueId"] = 90180105,
            ["GUID"] = "E1C1A57A",
            ["NextDialogue"] = 90180106,
            ["SpeakNpcId"] = 83103,
            ["TalkActionId"] = {
                [1] = "83103:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Yeer/vo_topic_01_3",
            },
        [90180106] = {
            ["Content"] = "奥利弗：喂，有你这么夸奖人的吗？",
            ["ContentKR"] = "올리버: 야, 누가 칭찬을 그딴 식으로 하냐.",
            ["DialogueId"] = 90180106,
            ["GUID"] = "E1C1A5A4",
            ["NextOptions"] = {
                [1] = 90180004,
                [2] = 90180005,
                },
            ["SpeakNpcId"] = 83103,
            ["TalkActionId"] = {
                [1] = "83103:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Yeer/vo_topic_01_4",
            ["bForbidSkipOptions"] = true,
            },
        [90180201] = {
            ["Content"] = "耶尔：我……可能派不上什么用场。唯一擅长的……可能就只有制作“小可爱”了吧？",
            ["ContentKR"] = "예일: 전... 도움이 되지 않을 거예요. 잘하는 거라고는... '귀요미'를 만드는 것밖에 없으니까요.",
            ["DialogueId"] = 90180201,
            ["GUID"] = "E1C1B53A",
            ["LookAt"] = {
                [1] = "83103:n(0)",
                [2] = "0:n(83103)",
                },
            ["NextDialogue"] = 90180203,
            ["SpeakNpcId"] = 83103,
            ["TalkActionId"] = {
                [1] = "83103:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Yeer/vo_topic_02_1",
            },
        [90180203] = {
            ["Content"] = "嗯？“小可爱”是什么？",
            ["ContentKR"] = "응? '귀요미'가 뭐야?",
            ["DialogueId"] = 90180203,
            ["GUID"] = "E1C1B58E",
            ["NextDialogue"] = 90180204,
            ["SpeakNpcId"] = 100001,
            },
        [90180204] = {
            ["Content"] = "耶尔：“小可爱”……是“劈里啪啦”玩具店中……最受欢迎的商品，制作它们，要花费不少时间。",
            ["ContentKR"] = "예일: '귀요미'...는 '우르르쾅쾅' 장난감 가게에서... 가장 인기 많은 상품이에요. 만드는 데 꽤 시간이 걸리죠.",
            ["DialogueId"] = 90180204,
            ["GUID"] = "E1C1B5B8",
            ["NextDialogue"] = 90180205,
            ["SpeakNpcId"] = 83103,
            ["TalkActionId"] = {
                [1] = "83103:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Yeer/vo_topic_02_2",
            },
        [90180205] = {
            ["Content"] = "耶尔：但，不是因为我的技艺……有多好，只是因为，奥利弗他很熟悉。",
            ["ContentKR"] = "예일: 하지만 제 기술이... 좋아서 그런 게 아니에요. 그냥 올리버가 능숙해서 그래요.",
            ["DialogueId"] = 90180205,
            ["GUID"] = "E1C1B5E2",
            ["NextOptions"] = {
                [1] = 90180004,
                [2] = 90180005,
                },
            ["SpeakNpcId"] = 83103,
            ["TalkActionId"] = {
                [1] = "83103:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Yeer/vo_topic_02_3",
            ["bForbidSkipOptions"] = true,
            },
        [90180301] = {
            ["Content"] = "耶尔：啊，抱歉！但、但是要是说得快了，我的舌头就就就容易打结。",
            ["ContentKR"] = "예일: 앗, 미안해요! 하, 하지만 빨리 말하면, 마, 마, 말을 더 더듬거든요.",
            ["DialogueId"] = 90180301,
            ["GUID"] = "E1C1C5A2",
            ["LookAt"] = {
                [1] = "83103:n(0)",
                [2] = "0:n(83103)",
                },
            ["NextDialogue"] = 90180303,
            ["SpeakNpcId"] = 83103,
            ["TalkActionId"] = {
                [1] = "83103:Sigh_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Yeer/vo_topic_03_1",
            },
        [90180303] = {
            ["Content"] = "那和别人交流起来应该还挺不容易的。",
            ["ContentKR"] = "그럼 다른 사람과 이야기 나누는 게 쉽지 않겠다.",
            ["DialogueId"] = 90180303,
            ["GUID"] = "E1C1C5F6",
            ["NextDialogue"] = 90180304,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "83103:Sigh_End",
                },
            },
        [90180304] = {
            ["Content"] = "耶尔：还、还好，有时候奥利弗会帮我说......而且，旁边没有人的时候，奥利弗总会把我想说的话听完的。",
            ["ContentKR"] = "예일: 괘, 괜찮아요. 올리버가 대신 말해주기도 하거든요... 게다가, 옆에 아무도 없을 땐 올리버가 제 말을 끝까지 들어줘요.",
            ["DialogueId"] = 90180304,
            ["GUID"] = "E1C1C620",
            ["NextOptions"] = {
                [1] = 90180004,
                [2] = 90180005,
                },
            ["SpeakNpcId"] = 83103,
            ["VoiceName"] = "voice/$Locale$/char/Yeer/vo_topic_03_2",
            ["bForbidSkipOptions"] = true,
            },
        [90180401] = {
            ["Content"] = "耶尔：我没有“小时候”……我从记事的时候，就在这个大孩子的身体里了。奥利弗也许有吧。",
            ["ContentKR"] = "예일: 저한테는 '어린 시절'이 없어요... 제 몸이 꽤 성장한 상태 이후의 기억만 있거든요. 올리버에겐 '어린 시절'이 있을지도 모르지만요.",
            ["DialogueId"] = 90180401,
            ["GUID"] = "E1C1D60A",
            ["LookAt"] = {
                [1] = "83103:n(0)",
                [2] = "0:n(83103)",
                },
            ["NextDialogue"] = 90180403,
            ["SpeakNpcId"] = 83103,
            ["TalkActionId"] = {
                [1] = "83103:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Yeer/vo_topic_04_1",
            },
        [90180403] = {
            ["Content"] = "少了很多回忆，有点遗憾。",
            ["ContentKR"] = "많은 추억이 사라져서 조금 아쉽겠어.",
            ["DialogueId"] = 90180403,
            ["GUID"] = "E1C1D65E",
            ["NextDialogue"] = 90180404,
            ["SpeakNpcId"] = 100001,
            },
        [90180404] = {
            ["Content"] = "耶尔：我也想过如果能有“童年”，应该会是……怎样的呢？每晚睡觉前……琼斯先生会不会像普通的爸爸一样，坐在我的床头……给我讲故事……",
            ["ContentKR"] = "예일: 저도 만약 '어린 시절'이 있었다면... 어떨지 생각해 봤어요. 매일 밤 잠들기 전... 존스 씨가 평범한 아빠처럼 제 곁에 앉아서... 이야기를 들려주지 않았을까요...",
            ["DialogueId"] = 90180404,
            ["GUID"] = "E1C1D688",
            ["NextDialogue"] = 90180405,
            ["SpeakNpcId"] = 83103,
            ["TalkActionId"] = {
                [1] = "83103:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Yeer/vo_topic_04_2",
            },
        [90180405] = {
            ["Content"] = "奥利弗：琼斯那混蛋讲故事？你脑子进胶水了吗？",
            ["ContentKR"] = "올리버: 존스 그 자식이 이야기를 들려준다고? 너 머리가 어떻게 된 거냐?",
            ["DialogueId"] = 90180405,
            ["GUID"] = "E1C1D6B2",
            ["NextDialogue"] = 90180406,
            ["SpeakNpcId"] = 83103,
            ["TalkActionId"] = {
                [1] = "83103:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Yeer/vo_topic_04_3",
            },
        [90180406] = {
            ["Content"] = "耶尔：对对对不起！我我知道的，他只关心实验，不会做这些……",
            ["ContentKR"] = "예일: 미, 미, 미안해! 나, 나도 알아. 존스 씨는 실험에만 관심 있을 뿐이고, 이야기 같은 건 들려줄 리 없다는 걸...",
            ["DialogueId"] = 90180406,
            ["GUID"] = "E1C1D6DC",
            ["NextOptions"] = {
                [1] = 90180004,
                [2] = 90180005,
                },
            ["SpeakNpcId"] = 83103,
            ["TalkActionId"] = {
                [1] = "83103:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Yeer/vo_topic_04_4",
            ["bForbidSkipOptions"] = true,
            },
        [90180501] = {
            ["Content"] = "耶尔：您，您好……您的歌声，真的很、很动听。",
            ["ContentKR"] = "예일: 아, 안녕하세요... 목소리가 저, 정말 아름다워요.",
            ["DialogueId"] = 90180501,
            ["GUID"] = "E1C1E672",
            ["NextDialogue"] = 90180502,
            ["SpeakNpcId"] = 83103,
            ["VoiceName"] = "voice/$Locale$/char/Yeer/vo_companio_01_1",
            },
        [90180502] = {
            ["Content"] = "奥利弗：哼，又一只可怜虫。",
            ["ContentKR"] = "올리버: 흥, 불쌍한 벌레가 또 있었군.",
            ["DialogueId"] = 90180502,
            ["GUID"] = "E1C1E69C",
            ["SpeakNpcId"] = 83103,
            ["VoiceName"] = "voice/$Locale$/char/Yeer/vo_companio_01_2",
            },
        [90180601] = {
            ["Content"] = "耶尔：榛子……是你的朋友吗？我也有很好的朋友，他像榛、榛子一样可靠。",
            ["ContentKR"] = "예일: 헤이즐넛... 이 친구예요? 저도 좋은 친구가 있어요. 헤, 헤이즐넛처럼 듬직해요.",
            ["DialogueId"] = 90180601,
            ["GUID"] = "E1C1F6DA",
            ["NextDialogue"] = 90180602,
            ["SpeakNpcId"] = 83103,
            ["VoiceName"] = "voice/$Locale$/char/Yeer/vo_companio_02_1",
            },
        [90180602] = {
            ["Content"] = "奥利弗：你骂谁呢？",
            ["ContentKR"] = "올리버: 누굴 욕하는 거야?",
            ["DialogueId"] = 90180602,
            ["GUID"] = "E1C1F704",
            ["SpeakNpcId"] = 83103,
            ["VoiceName"] = "voice/$Locale$/char/Yeer/vo_companio_02_2",
            },
        [90180701] = {
            ["Content"] = "耶尔：唔啊……你、你不要生气，我的炸弹实验都是符！符符符符合安全规定的……",
            ["ContentKR"] = "예일: 으아... 화, 화내지 마세요. 제 폭탄 실험은 다 아! 아, 아, 아, 안전 규칙에 부합한다고요...",
            ["DialogueId"] = 90180701,
            ["GUID"] = "E1C20742",
            ["SpeakNpcId"] = 83103,
            ["VoiceName"] = "voice/$Locale$/char/Yeer/vo_companio_03",
            },
        [90190000] = {
            ["Content"] = "难得有这么悠闲的时光，没有伤患的呼救，也没有紧急的战报。嗯……泡杯咖啡，把那本小说看完吧。公主最后到底和谁在一起了呢……",
            ["ContentKR"] = "모처럼 부상자들의 비명도, 긴급 전투 보고도 없는 한가한 시간이네. 음... 커피나 한잔 마시면서 그 소설을 마저 봐야겠어. 공주는 결국 누구랑 사랑에 빠졌을까...",
            ["DialogueId"] = 90190000,
            ["GUID"] = "E1C7FD09",
            ["SpeakNpcId"] = 85401,
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_idle",
            },
        [90190001] = {
            ["Content"] = "很高兴看到您今天健康平安。请多加珍重……为了终有一天会到来的和平。",
            ["ContentKR"] = "오늘도 건강한 모습을 보니 기쁩니다. 언젠가 찾아올 평화를 위해서... 몸조심하셔야 합니다.",
            ["DialogueId"] = 90190001,
            ["GUID"] = "E1C7FD0A",
            ["LookAt"] = {
                [1] = "85401:n(0)",
                [2] = "0:n(85401)",
                },
            ["NextOptions"] = {
                [1] = 901900011,
                [2] = 901900012,
                [3] = 901900013,
                [4] = 901900014,
                [5] = 901900015,
                },
            ["RandomOptionNum"] = 3,
            ["SpeakNpcId"] = 85401,
            ["TalkActionId"] = {
                [1] = "85401:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_welcome",
            ["bForbidSkipOptions"] = true,
            },
        [90190002] = {
            ["Content"] = "聊点别的",
            ["ContentKR"] = "다른 얘기를 하자",
            ["DialogueId"] = 90190002,
            ["GUID"] = "90190002.0",
            ["NextDialogue"] = 90190001,
            },
        [90190003] = {
            ["Content"] = "再见",
            ["ContentKR"] = "안녕",
            ["DialogueId"] = 90190003,
            ["GUID"] = "90190003.0",
            },
        [90190101] = {
            ["Content"] = "我……没有什么特别的爱好。也许读书算一个吧？",
            ["ContentKR"] = "전... 별다른 취미는 없습니다. 독서 정도랄까요?",
            ["DialogueId"] = 90190101,
            ["GUID"] = "E1C80D72",
            ["LookAt"] = {
                [1] = "85401:n(0)",
                [2] = "0:n(85401)",
                },
            ["NextDialogue"] = 90190102,
            ["SpeakNpcId"] = 85401,
            ["TalkActionId"] = {
                [1] = "85401:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_01_1",
            },
        [90190102] = {
            ["Content"] = "虽然妈妈总是唠叨，说我一直把自己关在家里，错过了那些舞会和沙龙，会失去很多跻身更上一层的机会……",
            ["ContentKR"] = "어머니께선 항상 잔소리를 하세요. 집에만 틀어박혀 무도회나 미용실에 나가지 않으면, 상류층이 될 기회들을 놓칠 거라고 말이죠.",
            ["DialogueId"] = 90190102,
            ["GUID"] = "E1C80D9C",
            ["NextDialogue"] = 90190103,
            ["SpeakNpcId"] = 85401,
            ["TalkActionId"] = {
                [1] = "85401:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_01_2",
            },
        [90190103] = {
            ["Content"] = "但我还是觉得，这样就很好。",
            ["ContentKR"] = "하지만 전 역시, 지금이 좋아요.",
            ["DialogueId"] = 90190103,
            ["GUID"] = "E1C80DC6",
            ["NextDialogue"] = 90190104,
            ["SpeakNpcId"] = 85401,
            ["TalkActionId"] = {
                [1] = "85401:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_01_3",
            },
        [90190104] = {
            ["Content"] = "那你最近在看什么书？",
            ["ContentKR"] = "그럼 요즘엔 어떤 책을 읽는 중이에요?",
            ["DialogueId"] = 90190104,
            ["GUID"] = "E1C80DF0",
            ["NextDialogue"] = 90190105,
            ["SpeakNpcId"] = 100001,
            },
        [90190105] = {
            ["Content"] = "主要是战伤救治相关的书籍，《战地应急救援策略》、《常规外伤处理》、《野战医院的临时搭建》……",
            ["ContentKR"] = "주로 전투 부상 치료에 관한 책을 읽어요. 〈전장 긴급 구조 전략〉, 〈일반적 외상 처리〉, 〈야전병원의 임시 건설〉 같은 것들이요.",
            ["DialogueId"] = 90190105,
            ["GUID"] = "E1C80E1A",
            ["NextDialogue"] = 90190106,
            ["SpeakNpcId"] = 85401,
            ["TalkActionId"] = {
                [1] = "85401:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_01_4",
            },
        [90190106] = {
            ["Content"] = "您也许知道，我过去学习的方向并非救护相关，尽管我已经获得了军团随行医务员的资格，但仍然时常感到沉重与惶恐。",
            ["ContentKR"] = "아실지 모르겠지만, 제 전공은 구호 관련은 아니었어요. 이미 군단 의무병 자격을 취득하긴 했지만, 항상 압박감과 긴장감을 느끼곤 해요.",
            ["DialogueId"] = 90190106,
            ["GUID"] = "E1C80E44",
            ["NextDialogue"] = 90190107,
            ["SpeakNpcId"] = 85401,
            ["TalkActionId"] = {
                [1] = "85401:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_01_5",
            },
        [90190107] = {
            ["Content"] = "你也要适当放松一下，不要让自己太紧绷了。",
            ["ContentKR"] = "적당히 쉬면서 해요, 너무 바짝 긴장해 있는 것 같아요.",
            ["DialogueId"] = 90190107,
            ["GUID"] = "E1C80E6E",
            ["NextDialogue"] = 90190108,
            ["SpeakNpcId"] = 100001,
            },
        [90190108] = {
            ["Content"] = "嗯，最近我也在看一本叫做《玻璃鞋》的书。是关于……呃，公主和骑士……我、我并不是非常喜欢看浪漫小说！只是，随便……翻一下……",
            ["ContentKR"] = "네, 최근엔 〈유리구두〉라는 책도 읽고 있어요. 그... 공주와 기사에 관한 내용인데... 제, 제가 로맨스 소설을 좋아하는 건 아닌데요! 그냥, 대충... 몇 페이지만...",
            ["DialogueId"] = 90190108,
            ["GUID"] = "E1C80E98",
            ["NextOptions"] = {
                [1] = 90190002,
                [2] = 90190003,
                },
            ["SpeakNpcId"] = 85401,
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_01_6",
            ["bForbidSkipOptions"] = true,
            },
        [90190201] = {
            ["Content"] = "嗯，当然可以！它是海伯利亚的基石，是学者们口中“原初的奇迹”！",
            ["ContentKR"] = "네, 물론이죠! 연금술은 휘페르보레아의 초석이 되는 기술이자, 학자들이 말하는 '원초의 기적'이에요!",
            ["DialogueId"] = 90190201,
            ["GUID"] = "E1C81DDA",
            ["LookAt"] = {
                [1] = "85401:n(0)",
                [2] = "0:n(85401)",
                },
            ["NextDialogue"] = 90190202,
            ["SpeakNpcId"] = 85401,
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_02_1",
            },
        [90190202] = {
            ["Content"] = "最一开始，人们试图从月石中分离出黄金，但后来，人们发现这枚小小的石头还有更多用途——转动机械的齿轮，释放电的火花……它就是索拉之民的“魔法”。",
            ["ContentKR"] = "모든 건 사람들이 월석에서 황금을 분리하려는 시도에서 시작됐어요. 월석이 기계의 톱니바퀴를 돌린다든지, 전기를 방출하는 불꽃을 내뿜는다든지... 그건 솔라가 부릴 수 있는 '마법'이었죠.",
            ["DialogueId"] = 90190202,
            ["GUID"] = "E1C81E04",
            ["NextDialogue"] = 90190203,
            ["SpeakNpcId"] = 85401,
            ["TalkActionId"] = {
                [1] = "85401:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_02_2",
            },
        [90190203] = {
            ["Content"] = "……只是后来，炼金院……",
            ["ContentKR"] = "...하지만 연금원은 나중에...",
            ["DialogueId"] = 90190203,
            ["GUID"] = "E1C81E2E",
            ["NextDialogue"] = 90190204,
            ["SpeakNpcId"] = 85401,
            ["TalkActionId"] = {
                [1] = "85401:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_02_3",
            },
        [90190204] = {
            ["Content"] = "你好像在炼金院待过？",
            ["ContentKR"] = "연금원에 있었던 적이 있나 보네요?",
            ["DialogueId"] = 90190204,
            ["GUID"] = "E1C81E58",
            ["NextDialogue"] = 90190205,
            ["SpeakNpcId"] = 100001,
            },
        [90190205] = {
            ["Content"] = "……是的。不过，那已经是过去的事了。",
            ["ContentKR"] = "...네. 하지만, 이젠 지난 일이죠.",
            ["DialogueId"] = 90190205,
            ["GUID"] = "E1C81E82",
            ["NextDialogue"] = 90190206,
            ["SpeakNpcId"] = 85401,
            ["TalkActionId"] = {
                [1] = "85401:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_02_4",
            },
        [90190206] = {
            ["Content"] = "你为什么要离开炼金院？",
            ["ContentKR"] = "왜 연금원을 떠나게 된 거예요?",
            ["DialogueId"] = 90190206,
            ["GUID"] = "E1C81EAC",
            ["NextDialogue"] = 90190207,
            ["SpeakNpcId"] = 100001,
            },
        [90190207] = {
            ["Content"] = "因为后来的佩剑炼金院偏离了轨道，走在了一条错误的路上。它是海伯利亚这座战车最炽热的炉芯，但燃料却是太多人的痛苦和不幸。",
            ["ContentKR"] = "소드 연금원은 시간이 지날수록 궤도를 벗어나 잘못된 길로 들어섰기 때문입니다. 휘페르보레아가 전차라면 소드 연금원은 가장 뜨거운 엔진이었지만, 그 엔진의 연료는 너무나 많은 사람들의 고통과 불행이었어요.",
            ["DialogueId"] = 90190207,
            ["GUID"] = "E1C81ED6",
            ["NextDialogue"] = 90190208,
            ["SpeakNpcId"] = 85401,
            ["TalkActionId"] = {
                [1] = "85401:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_02_5",
            },
        [90190208] = {
            ["Content"] = "我想，我远比自己想象中更软弱。我无法说服自己接受它，也没有勇气和力量阻止它。所以，我只能选择逃避它。",
            ["ContentKR"] = "저는, 제가 생각했던 것보다 훨씬 나약했던 것 같아요. 그런 것들을 용납하도록 제 자신을 설득하지도 못했고, 그렇다고 그것을 막을 용기와 힘도 없었기에, 그저 도망치는 것을 선택할 수밖에 없었죠.",
            ["DialogueId"] = 90190208,
            ["GUID"] = "E1C81F00",
            ["NextOptions"] = {
                [1] = 90190002,
                [2] = 90190003,
                },
            ["SpeakNpcId"] = 85401,
            ["TalkActionId"] = {
                [1] = "85401:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_02_6",
            ["bForbidSkipOptions"] = true,
            },
        [90190301] = {
            ["Content"] = "一些应急的器械和药品。绷带，消毒剂，麻醉剂，还有处理外伤的刀片和缝线。",
            ["ContentKR"] = "응급 장비와 약품들입니다. 붕대, 소독제, 마취제, 외상 처리용 메스 그리고 바늘과 실 같은 것들이죠.",
            ["DialogueId"] = 90190301,
            ["GUID"] = "E1C82E42",
            ["LookAt"] = {
                [1] = "85401:n(0)",
                [2] = "0:n(85401)",
                },
            ["NextDialogue"] = 90190302,
            ["SpeakNpcId"] = 85401,
            ["TalkActionId"] = {
                [1] = "85401:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_03_1",
            },
        [90190302] = {
            ["Content"] = "此外，还有一张手帕和一把梳子。",
            ["ContentKR"] = "그 외에 손수건과 머리빗도 있어요.",
            ["DialogueId"] = 90190302,
            ["GUID"] = "E1C82E6C",
            ["NextDialogue"] = 90190303,
            ["SpeakNpcId"] = 85401,
            ["TalkActionId"] = {
                [1] = "85401:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_03_2",
            },
        [90190303] = {
            ["Content"] = "战场上也要梳妆么？达芙涅很爱美呢。",
            ["ContentKR"] = "전장에서도 화장을 하는 거예요? 다프네는 꾸미는 걸 좋아하나 보네요.",
            ["DialogueId"] = 90190303,
            ["GUID"] = "E1C82E96",
            ["NextDialogue"] = 90190304,
            ["SpeakNpcId"] = 100001,
            },
        [90190304] = {
            ["Content"] = "啊，这个……不是我自己用的。如果救护的伤员不幸离世，我会帮他们简单整理一下仪容。",
            ["ContentKR"] = "아, 그게... 제가 쓰려는 건 아니에요. 혹시 누군가... 운명을 달리하시게 된다면, 간단하게라도 용모 정리 정도는 해드려야 할 것 같아서요.",
            ["DialogueId"] = 90190304,
            ["GUID"] = "E1C82EC0",
            ["NextDialogue"] = 90190305,
            ["SpeakNpcId"] = 85401,
            ["TalkActionId"] = {
                [1] = "85401:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_03_3",
            },
        [90190305] = {
            ["Content"] = "伤痛是很残忍的东西，它从人们那里夺走的，除了生命，还有生而为人的全部尊严。",
            ["ContentKR"] = "부상은 정말 잔인한 것이에요. 전장에서 부상을 당한다는 건, 목숨을 잃는다는 뜻일 뿐만 아니라 인간의 존엄성도 빼앗긴다는 뜻이기도 하죠.",
            ["DialogueId"] = 90190305,
            ["GUID"] = "E1C82EEA",
            ["NextDialogue"] = 90190306,
            ["SpeakNpcId"] = 85401,
            ["TalkActionId"] = {
                [1] = "85401:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_03_4",
            },
        [90190306] = {
            ["Content"] = "我希望……他们的家人看到的他们，可以干净一些、安详一些……久别重逢，父母应该看到孩子们安然睡去的脸，而不是被疼痛扭曲五官的凄惨面容。",
            ["ContentKR"] = "저는... 그들이 가족들과 다시 만날 때, 조금은 더 깔끔하고, 평화로운 모습이길 바라요. 오랜만에 만나는 자식의 모습은 고통에 일그러진 처참한 모습이 아니라, 편히 잠든 모습이어야 한다고 생각합니다.",
            ["DialogueId"] = 90190306,
            ["GUID"] = "E1C82F14",
            ["NextOptions"] = {
                [1] = 90190002,
                [2] = 90190003,
                },
            ["SpeakNpcId"] = 85401,
            ["TalkActionId"] = {
                [1] = "85401:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_03_5",
            ["bForbidSkipOptions"] = true,
            },
        [90190401] = {
            ["Content"] = "我没关系，不辛苦的！……呃，其实还是有点……急救和护理知识的学习还好，但体能测试确实令人苦恼。",
            ["ContentKR"] = "괜찮아요. 힘들지 않아요! ...어, 사실 조금 힘들긴 합니다... 긴급 구조와 간호학에 관한 공부는 괜찮지만, 체력 검사는 머리 아픈 일이긴 하거든요.",
            ["DialogueId"] = 90190401,
            ["GUID"] = "E1C83EAA",
            ["LookAt"] = {
                [1] = "85401:n(0)",
                [2] = "0:n(85401)",
                },
            ["NextDialogue"] = 90190402,
            ["SpeakNpcId"] = 85401,
            ["TalkActionId"] = {
                [1] = "85401:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_04_1",
            },
        [90190402] = {
            ["Content"] = "就算每天比大家起得更早独自加练，还是只能拿勉强及格的分数……唉，不要笑话我，锻炼体力真是比读书难太多了。",
            ["ContentKR"] = "남들보다 일찍 일어나 혼자 아무리 연습을 해도 겨우 간신히 합격할 점수밖에 안 나오네요... 비웃지 말아 주세요. 체력 훈련은 정말 공부보다 훨씬 어려워요.",
            ["DialogueId"] = 90190402,
            ["GUID"] = "E1C83ED4",
            ["NextDialogue"] = 90190403,
            ["SpeakNpcId"] = 85401,
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_04_2",
            },
        [90190403] = {
            ["Content"] = "早起加练，听起来好累啊。",
            ["ContentKR"] = "일찍 일어나 훈련이라니, 정말 힘들 것 같아요.",
            ["DialogueId"] = 90190403,
            ["GUID"] = "E1C83EFE",
            ["NextDialogue"] = 90190404,
            ["SpeakNpcId"] = 100001,
            },
        [90190404] = {
            ["Content"] = "嗯，的确很累。不过当我把注意力从脚下移开，去看城郊的麦田，地平线尽头的小屋，去听风车的每一声转动和牧牛人的每一声哨笛，就觉得平静许多。",
            ["ContentKR"] = "네, 정말 힘들긴 하죠. 그래도 주의를 딴 데로 돌려, 교외의 밀밭과 지평선 끝에 있는 오두막을 바라보며, 풍차 소리와 소몰이꾼의 휘파람 소리를 들으면 마음이 한결 편해지죠.",
            ["DialogueId"] = 90190404,
            ["GUID"] = "E1C83F28",
            ["NextDialogue"] = 90190405,
            ["SpeakNpcId"] = 85401,
            ["TalkActionId"] = {
                [1] = "85401:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_04_3",
            },
        [90190405] = {
            ["Content"] = "因为……也许我奔跑在这条路上，就是为了保护这些最普通、最寻常的东西不被毁掉吧。",
            ["ContentKR"] = "아마 제가 그 길을 달리는 이유는... 그런 평범하면서도 소중한 것들을 지키기 위해서일 거예요.",
            ["DialogueId"] = 90190405,
            ["GUID"] = "E1C83F52",
            ["NextOptions"] = {
                [1] = 90190002,
                [2] = 90190003,
                },
            ["SpeakNpcId"] = 85401,
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_04_4",
            ["bForbidSkipOptions"] = true,
            },
        [90190501] = {
            ["Content"] = "……我最后一次和爸爸说话，就是在对讲机里。那时还在龙莎要塞危机四伏的战场，他却对我说，“你放心。”",
            ["ContentKR"] = "...마지막으로 아버지와 대화한 건, 이 무전기를 통해서였어요. 론샤 요새의 절망적인 전쟁터에서 그가 저에게 남긴 마지막 한마디는 \"걱정하지 마라\" 였습니다.",
            ["DialogueId"] = 90190501,
            ["GUID"] = "E1C84F12",
            ["LookAt"] = {
                [1] = "85401:n(0)",
                [2] = "0:n(85401)",
                },
            ["NextDialogue"] = 90190502,
            ["SpeakNpcId"] = 85401,
            ["TalkActionId"] = {
                [1] = "85401:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_05_1",
            },
        [90190502] = {
            ["Content"] = "后来我还是会常常在深夜打开自己的对讲机，调到爸爸的频段，按下呼叫按钮，期待着他的声音从对讲机那头传来……",
            ["ContentKR"] = "그 뒤에도 저는 종종 밤늦게 무전기를 아버지의 채널로 맞춰서 켜놓고는 그의 목소리가 무전기 너머로 들려오길 기대하곤 했죠...",
            ["DialogueId"] = 90190502,
            ["GUID"] = "E1C84F3C",
            ["NextDialogue"] = 90190503,
            ["SpeakNpcId"] = 85401,
            ["TalkActionId"] = {
                [1] = "85401:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_05_2",
            },
        [90190503] = {
            ["Content"] = "直到我对着听筒等了十几分钟，我才突然发现，他是真的回不来了。",
            ["ContentKR"] = "그렇게 십여 분을 기다리고 나서야 전 깨달았어요... 아버지는 이제 정말 돌아오지 못한다는 걸요.",
            ["DialogueId"] = 90190503,
            ["GUID"] = "E1C84F66",
            ["NextDialogue"] = 90190504,
            ["SpeakNpcId"] = 85401,
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_05_3",
            },
        [90190504] = {
            ["Content"] = "请你节哀……",
            ["ContentKR"] = "너무 슬퍼하지 말아요...",
            ["DialogueId"] = 90190504,
            ["GUID"] = "E1C84F90",
            ["NextDialogue"] = 90190505,
            ["SpeakNpcId"] = 100001,
            },
        [90190505] = {
            ["Content"] = "谢谢，我明白的。我会好好活下去，在为父亲、为龙莎战役的死难者洗刷冤屈之前，我不会停下脚步。",
            ["ContentKR"] = "감사해요. 저도 알아요. 전 열심히 살아갈 겁니다. 아버지, 그리고 론샤 전투에서 전사한 사람들의 억울함을 풀어드리기 전까지 전 멈추지 않을 거예요.",
            ["DialogueId"] = 90190505,
            ["GUID"] = "E1C84FBA",
            ["NextOptions"] = {
                [1] = 90190002,
                [2] = 90190003,
                },
            ["SpeakNpcId"] = 85401,
            ["TalkActionId"] = {
                [1] = "85401:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_05_4",
            ["bForbidSkipOptions"] = true,
            },
        [90190601] = {
            ["Content"] = "我曾在皇都的图书馆中阅读过华胥的医书，虽然与海伯利亚的医理不太相同，但应用于救治却十分有效。这本书中我仍有一些问题，方便向您请教吗？",
            ["ContentKR"] = "수도의 도서관에서 화서의 의서를 본 적이 있어요. 휘페르보레아의 의학 이론과는 좀 다르긴 했지만 실제로 매우 효과가 좋았어요. 의서에 대해 아직 의문이 남아있는데 혹시 여쭤봐도 될까요?",
            ["DialogueId"] = 90190601,
            ["GUID"] = "E1C85F7A",
            ["SpeakNpcId"] = 85401,
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_companio_01",
            },
        [90190701] = {
            ["Content"] = "典狱长女士，迟来的正义真的还是正义吗？",
            ["ContentKR"] = "교도소장님, 뒤늦은 정의도 과연 정의일까요?",
            ["DialogueId"] = 90190701,
            ["GUID"] = "E1C86FE2",
            ["SpeakNpcId"] = 85401,
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_companio_02",
            },
        [90190801] = {
            ["Content"] = "好久不见，自离开炼金院后我们就很少联系了，你还……好吗？",
            ["ContentKR"] = "오랜만이야. 연금원을 떠난 후부터 연락이 뜸해졌었지... 잘... 지내지?",
            ["DialogueId"] = 90190801,
            ["GUID"] = "E1C8804A",
            ["SpeakNpcId"] = 85401,
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_companio_03",
            },
        [90190901] = {
            ["Content"] = "虽然我已经离开了佩剑炼金院，但那依旧是我学习过的地方。也许您永远不会选择宽恕，但还是请允许我说一句，对不起。",
            ["ContentKR"] = "전 비록 이미 소드 연금원을 떠났지만, 그곳은 여전히 제가 공부했던 곳이죠. 아마 영원히 절 용서하지 않으시겠지만, 그래도 말씀드리고 싶어요. 정말 죄송합니다.",
            ["DialogueId"] = 90190901,
            ["GUID"] = "E1C890B2",
            ["SpeakNpcId"] = 85401,
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_companio_04",
            },
        [90200000] = {
            ["Content"] = "嘘……我就快要进入角色了。",
            ["ContentKR"] = "쉿... 곧 캐릭터에 몰입할 것 같아.",
            ["DialogueId"] = 90200000,
            ["GUID"] = "E1CE65A9",
            ["SpeakNpcId"] = 81103,
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_idle",
            },
        [90200001] = {
            ["Content"] = "如今我扮演破碎的囚徒，而你是为我执掌枷锁的典狱长。",
            ["ContentKR"] = "이제 난 부서진 죄수의 역할이고, 넌 나한테 족쇄를 채우는 교도소장이네.",
            ["DialogueId"] = 90200001,
            ["GUID"] = "E1CE65AA",
            ["LookAt"] = {
                [1] = "81103:n(0)",
                [2] = "0:n(81103)",
                },
            ["NextOptions"] = {
                [1] = 902000011,
                [2] = 902000012,
                [3] = 902000013,
                [4] = 902000014,
                [5] = 902000015,
                },
            ["RandomOptionNum"] = 3,
            ["SpeakNpcId"] = 81103,
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_welcome",
            ["bForbidSkipOptions"] = true,
            },
        [90200002] = {
            ["Content"] = "聊点别的",
            ["ContentKR"] = "다른 얘기를 하자",
            ["DialogueId"] = 90200002,
            ["GUID"] = "90200002.0",
            ["NextDialogue"] = 90200001,
            },
        [90200003] = {
            ["Content"] = "再见",
            ["ContentKR"] = "안녕",
            ["DialogueId"] = 90200003,
            ["GUID"] = "90200003.0",
            },
        [90200101] = {
            ["Content"] = "他是被摔碎的玻璃灯，是洒在污水沟里的星星。",
            ["ContentKR"] = "그는 깨져버린 유리등이자, 시궁창에 떨어진 별.",
            ["DialogueId"] = 90200101,
            ["GUID"] = "E1CE7612",
            ["LookAt"] = {
                [1] = "81103:n(0)",
                [2] = "0:n(81103)",
                },
            ["NextDialogue"] = 90200102,
            ["SpeakNpcId"] = 81103,
            ["TalkActionId"] = {
                [1] = "81103:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_01_1",
            },
        [90200102] = {
            ["Content"] = "…………？",
            ["ContentKR"] = "......?",
            ["DialogueId"] = 90200102,
            ["GUID"] = "E1CE763C",
            ["NextDialogue"] = 90200103,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "81103:Talk01_End",
                },
            },
        [90200103] = {
            ["Content"] = "和那些东西一样，荒诞得惹人发笑，却又闪闪发亮。",
            ["ContentKR"] = "그것들과 마찬가지로 우스꽝스러우면서도 반짝반짝 빛나지.",
            ["DialogueId"] = 90200103,
            ["GUID"] = "E1CE7666",
            ["NextDialogue"] = 90200104,
            ["SpeakNpcId"] = 81103,
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_01_2",
            },
        [90200104] = {
            ["Content"] = "我们的牢房只隔着一道墙，隔音差得让人绝望。他就在我看不见的一米之外，一会儿回忆家人，一会儿憧憬未来，一会儿又五音不全地哼起歌。",
            ["ContentKR"] = "우리의 감옥은 얇은 벽 하나만을 사이에 두고 있어서 방음이 절망적일 정도로 좋지 않았어. 그는 내가 볼 수 없는 그곳에서 가족들을 추억하고, 미래를 꿈꾸다가, 또 갑자기 정확하지 않은 음정으로 노래를 흥얼거리곤 했지.",
            ["DialogueId"] = 90200104,
            ["GUID"] = "E1CE7690",
            ["NextDialogue"] = 90200105,
            ["SpeakNpcId"] = 81103,
            ["TalkActionId"] = {
                [1] = "81103:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_01_3",
            },
        [90200105] = {
            ["Content"] = "有时我甚至恍惚觉得，我不是被关在笼子里的困兽，而是一个无忧无虑的普通学生，在午后打盹时做了个噩梦，被邻座聒噪的同学吵醒了。",
            ["ContentKR"] = "가끔 난 울타리에 갇힌 짐승이 아니라, 걱정이 없는 평범한 학생이 된 기분이 들더라. 오후에 꾸벅 졸며 악몽을 꾸는데 옆자리의 시끄러운 급우 때문에 깬 것처럼.",
            ["DialogueId"] = 90200105,
            ["GUID"] = "E1CE76BA",
            ["NextDialogue"] = 90200106,
            ["SpeakNpcId"] = 81103,
            ["TalkActionId"] = {
                [1] = "81103:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_01_4",
            },
        [90200106] = {
            ["Content"] = "所以，你被他吸引，和他成为了朋友。",
            ["ContentKR"] = "그래서 그에게 이끌려 친구가 됐구나.",
            ["DialogueId"] = 90200106,
            ["GUID"] = "E1CE76E4",
            ["NextDialogue"] = 90200107,
            ["SpeakNpcId"] = 100001,
            },
        [90200107] = {
            ["Content"] = "……呵，也许吧。",
            ["ContentKR"] = "...어쩌면.",
            ["DialogueId"] = 90200107,
            ["GUID"] = "E1CE770E",
            ["NextDialogue"] = 90200108,
            ["SpeakNpcId"] = 81103,
            ["TalkActionId"] = {
                [1] = "81103:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_01_5",
            },
        [90200108] = {
            ["Content"] = "但“朋友”是一个过于耀眼的词语，我不配拥有它。或许更应该算是，干枯河床里搁浅的两条鱼吧。",
            ["ContentKR"] = "하지만 '친구'란 말은 너무 눈부셔. 난 그걸 가질 자격이 없어. 어쩌면 그저 마른 강바닥에 남은 두 마리의 물고기가 더 어울릴 수도 있어.",
            ["DialogueId"] = 90200108,
            ["GUID"] = "E1CE7738",
            ["NextOptions"] = {
                [1] = 90200002,
                [2] = 90200003,
                },
            ["SpeakNpcId"] = 81103,
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_01_6",
            ["bForbidSkipOptions"] = true,
            },
        [90200201] = {
            ["Content"] = "为什么？“帕西法尔”的人生早已落幕。那个名字太遥远了，远到我怀疑自己是否曾真的拥有它。",
            ["ContentKR"] = "왜? '파르지팔'의 인생은 진작에 끝났어. 그 이름은 이미 너무 멀어져서, 가졌던 적이 있는지도 이젠 잘 모르겠더라.",
            ["DialogueId"] = 90200201,
            ["GUID"] = "E1CE867A",
            ["LookAt"] = {
                [1] = "81103:n(0)",
                [2] = "0:n(81103)",
                },
            ["NextDialogue"] = 90200202,
            ["SpeakNpcId"] = 81103,
            ["TalkActionId"] = {
                [1] = "81103:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_02_1",
            },
        [90200202] = {
            ["Content"] = "但对我来说，你的存在是真实的。",
            ["ContentKR"] = "하지만 나에게 너는 진짜로 존재하고 있어.",
            ["DialogueId"] = 90200202,
            ["GUID"] = "E1CE86A4",
            ["NextDialogue"] = 90200203,
            ["SpeakNpcId"] = 100001,
            },
        [90200203] = {
            ["Content"] = "……是吗？",
            ["ContentKR"] = "...그런가?",
            ["DialogueId"] = 90200203,
            ["GUID"] = "E1CE86CE",
            ["NextDialogue"] = 90200204,
            ["SpeakNpcId"] = 81103,
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_02_2",
            },
        [90200204] = {
            ["Content"] = "好吧。既然如此，我会把这最后一场戏一直演下去——为了我最后的、唯一的观众。",
            ["ContentKR"] = "좋아. 그럼 난 이 연극을 끝까지 해볼게. 내 마지막, 그리고 유일한 관객을 위해서.",
            ["DialogueId"] = 90200204,
            ["GUID"] = "E1CE86F8",
            ["NextDialogue"] = 90200205,
            ["SpeakNpcId"] = 81103,
            ["TalkActionId"] = {
                [1] = "81103:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_02_3",
            },
        [90200205] = {
            ["Content"] = "谢谢你，让我停驻在你的舞台上。",
            ["ContentKR"] = "고마워, 네 무대 위에 머무르게 해줘서.",
            ["DialogueId"] = 90200205,
            ["GUID"] = "E1CE8722",
            ["NextOptions"] = {
                [1] = 90200002,
                [2] = 90200003,
                },
            ["SpeakNpcId"] = 81103,
            ["TalkActionId"] = {
                [1] = "81103:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_02_4",
            ["bForbidSkipOptions"] = true,
            },
        [90200301] = {
            ["Content"] = "多谢你的慷慨。但我的承诺都已兑现，我已经不再有什么值得眷念的事。",
            ["ContentKR"] = "호의는 고맙지만, 내 약속은 다 지켰으니, 이제 더 이상 미련 같은 건 없어.",
            ["DialogueId"] = 90200301,
            ["GUID"] = "E1CE96E2",
            ["LookAt"] = {
                [1] = "81103:n(0)",
                [2] = "0:n(81103)",
                },
            ["NextDialogue"] = 90200302,
            ["SpeakNpcId"] = 81103,
            ["TalkActionId"] = {
                [1] = "81103:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_03_1",
            },
        [90200302] = {
            ["Content"] = "…………",
            ["ContentKR"] = "......",
            ["DialogueId"] = 90200302,
            ["GUID"] = "E1CE970C",
            ["NextDialogue"] = 90200303,
            ["SpeakNpcId"] = 81103,
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_03_2",
            },
        [90200303] = {
            ["Content"] = "若有一天你在盖雷亚剧院遇到我的恩师薇奥莱塔女士，请转告她，我已在伊瑟尔定居。现在过得很好，请不要担忧。",
            ["ContentKR"] = "만약 언젠가 갈레아 극장에서 나의 스승님 비올레타 여사님을 만나게 된다면 전해줘. 난 이미 이스엘에서 자리를 잡고 잘 지내니 걱정하지 말라고.",
            ["DialogueId"] = 90200303,
            ["GUID"] = "E1CE9736",
            ["NextDialogue"] = 90200304,
            ["SpeakNpcId"] = 81103,
            ["TalkActionId"] = {
                [1] = "81103:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_03_3",
            },
        [90200304] = {
            ["Content"] = "“那是音乐与诗的国度，那里的每一颗卵石都敲击着节拍，每一泓泉水都歌唱着旋律。”",
            ["ContentKR"] = "\"조약돌 하나하나가 장단을 치고, 샘물 하나하나가 선율을 노래하는 음악과 시의 나라.\"",
            ["DialogueId"] = 90200304,
            ["GUID"] = "E1CE9760",
            ["NextDialogue"] = 90200305,
            ["SpeakNpcId"] = 81103,
            ["TalkActionId"] = {
                [1] = "81103:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_03_4",
            },
        [90200305] = {
            ["Content"] = "这样一来，或许她就不会再打听我的下落了。我曾是她欣赏的学生……我不希望她因我蒙羞。",
            ["ContentKR"] = "그러면 스승님께선 아마 더 이상 내 행방을 묻지 않겠지. 난 그녀의 가장 자랑스러운 제자였으니까... 그녀가 나 때문에 창피당하는 건 원치 않아.",
            ["DialogueId"] = 90200305,
            ["GUID"] = "E1CE978A",
            ["NextDialogue"] = 90200306,
            ["SpeakNpcId"] = 81103,
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_03_5",
            },
        [90200306] = {
            ["Content"] = "善意的欺骗吗……",
            ["ContentKR"] = "선의의 거짓말인 건가...",
            ["DialogueId"] = 90200306,
            ["GUID"] = "E1CE97B4",
            ["NextDialogue"] = 90200307,
            ["SpeakNpcId"] = 100001,
            },
        [90200307] = {
            ["Content"] = "嗯，一无所知总会是更加幸福的。",
            ["ContentKR"] = "그래. 아무것도 모르면 더 행복하겠지.",
            ["DialogueId"] = 90200307,
            ["GUID"] = "E1CE97DE",
            ["NextOptions"] = {
                [1] = 90200002,
                [2] = 90200003,
                },
            ["SpeakNpcId"] = 81103,
            ["TalkActionId"] = {
                [1] = "81103:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_03_6",
            ["bForbidSkipOptions"] = true,
            },
        [90200401] = {
            ["Content"] = "为什么想学表演？你不需要变成任何人。",
            ["ContentKR"] = "왜 연기를 배우려 하는 거지? 넌 그 누구도 될 필요 없어.",
            ["DialogueId"] = 90200401,
            ["GUID"] = "E1CEA74A",
            ["LookAt"] = {
                [1] = "81103:n(0)",
                [2] = "0:n(81103)",
                },
            ["NextDialogue"] = 90200402,
            ["SpeakNpcId"] = 81103,
            ["TalkActionId"] = {
                [1] = "81103:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_04_1",
            },
        [90200402] = {
            ["Content"] = "“变成任何人”？",
            ["ContentKR"] = "\"누군가 된다\"고?",
            ["DialogueId"] = 90200402,
            ["GUID"] = "E1CEA774",
            ["NextDialogue"] = 90200403,
            ["SpeakNpcId"] = 100001,
            },
        [90200403] = {
            ["Content"] = "只要站在舞台上，把你的每一寸骨骼，每一缕气息奉献给演出，你就可以彻底变成另一个人、忘记带给你痛苦的一切，走向你前所未见的世界。",
            ["ContentKR"] = "무대에선 모든 뼈마디와 숨결까지 공연에 바친다면, 완전히 다른 사람이 될 수 있지. 고통을 가져다주는 모든 걸 잊고 새로운 세계로 갈 수 있어.",
            ["DialogueId"] = 90200403,
            ["GUID"] = "E1CEA79E",
            ["NextDialogue"] = 90200404,
            ["SpeakNpcId"] = 81103,
            ["TalkActionId"] = {
                [1] = "81103:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_04_2",
            },
        [90200404] = {
            ["Content"] = "但你生而就是一位冒险故事里被祝福的主人公，拥有所有角色的瞩目和信赖。你无需舞台，便足以熠熠生辉。",
            ["ContentKR"] = "하지만 넌 모험담의 축복받는 주인공으로 태어나 모든 이의 주목과 신뢰를 받고 있잖아. 무대 없이도 충분히 밝게 빛날 수 있어.",
            ["DialogueId"] = 90200404,
            ["GUID"] = "E1CEA7C8",
            ["NextOptions"] = {
                [1] = 90200002,
                [2] = 90200003,
                },
            ["SpeakNpcId"] = 81103,
            ["TalkActionId"] = {
                [1] = "81103:Angry01_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_04_3",
            ["bForbidSkipOptions"] = true,
            },
        [90200501] = {
            ["Content"] = "它站在那儿，经历远比我的生命悠长的岁月。在它外墙的这一边，是巍峨的内城。和乌云一样高，比乌云更冷。",
            ["ContentKR"] = "극장은 나보다 훨씬 더 오랜 세월 동안 그 자리를 지켰어. 외벽 쪽엔 먹구름보다 높고 더 차갑게 우뚝 솟은 내성이 있지. ",
            ["DialogueId"] = 90200501,
            ["GUID"] = "E1CEB7B2",
            ["LookAt"] = {
                [1] = "81103:n(0)",
                [2] = "0:n(81103)",
                },
            ["NextDialogue"] = 90200502,
            ["SpeakNpcId"] = 81103,
            ["TalkActionId"] = {
                [1] = "81103:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_05_1",
            },
        [90200502] = {
            ["Content"] = "人们从裹着丝绸的马车走来，谈论总不放晴的天气，谈论诗歌与绘画，谈论舞会与婚事，抱怨外城污浊的雪水弄脏了漂亮的皮靴。",
            ["ContentKR"] = "사람들은 비단으로 감싸진 마차에서 내리며 좀처럼 맑아지지 않는 날씨와 시, 그림, 무도회, 혼사에 관해 얘기를 해. 또 아름다운 가죽 부츠를 얼룩지게 하는 외성의 더러운 눈을 불평하면서 말이야.",
            ["DialogueId"] = 90200502,
            ["GUID"] = "E1CEB7DC",
            ["NextDialogue"] = 90200503,
            ["SpeakNpcId"] = 81103,
            ["TalkActionId"] = {
                [1] = "81103:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_05_2",
            },
        [90200503] = {
            ["Content"] = "外墙的另一侧，是嘈杂的雾区。在那儿，小贩扯尖嗓子叫卖，母亲抱着自己的孩子，乞求一片黑面包果腹。好事者一边躲着卫兵，一边在墙上涂鸦。",
            ["ContentKR"] = "외벽의 반대쪽은 시끄러운 안개 지역이야. 그곳에선 노점상들은 큰 소리로 물건을 팔고, 어머니는 굶주린 아이를 안고 빵 한 조각을 구걸해. 일 벌이길 좋아하는 사람들은 위병들의 눈을 피해 벽에 낙서하고 있어.",
            ["DialogueId"] = 90200503,
            ["GUID"] = "E1CEB806",
            ["NextDialogue"] = 90200504,
            ["SpeakNpcId"] = 81103,
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_05_3",
            },
        [90200504] = {
            ["Content"] = "这就是我们的盖雷亚剧院。它站在那儿，听着这些声音，但又听不懂这些声音。",
            ["ContentKR"] = "그게 우리 갈레아 극장이야. 그저 우뚝 서서 그 소리를 듣지만, 또 그 소리를 알아듣지 못하지.",
            ["DialogueId"] = 90200504,
            ["GUID"] = "E1CEB830",
            ["NextDialogue"] = 90200505,
            ["SpeakNpcId"] = 81103,
            ["TalkActionId"] = {
                [1] = "81103:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_05_4",
            },
        [90200505] = {
            ["Content"] = "那，那里有什么关于你自己的回忆吗？",
            ["ContentKR"] = "그럼, 거기에 너 자신에 대한 기억은 없을까?",
            ["DialogueId"] = 90200505,
            ["GUID"] = "E1CEB85A",
            ["NextDialogue"] = 90200506,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "81103:Confident_End",
                },
            },
        [90200506] = {
            ["Content"] = "……不知为什么，我第一个想起的不是各种剧本，不是花哨的戏服和首饰，甚至不是每天打扫的小道具间。",
            ["ContentKR"] = "...왜인지 모르겠지만, 처음 떠오르는 건 대본도, 화려한 의상과 장신구도, 심지어 매일 청소하는 소품실도 아니야.",
            ["DialogueId"] = 90200506,
            ["GUID"] = "E1CEB884",
            ["NextDialogue"] = 90200507,
            ["SpeakNpcId"] = 81103,
            ["TalkActionId"] = {
                [1] = "81103:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_05_5",
            },
        [90200507] = {
            ["Content"] = "我想起的是演出落幕后，舞台上那袭薄绒毯。小时候，记忆里的第一场演出结束后，我和母亲在那儿重复着剧里的唱词，跳了整夜的舞。",
            ["ContentKR"] = "그저 공연이 끝나고 무대 위에 펼쳐진 얇은 담요가 생각나. 어린 시절, 기억 속의 첫 공연이 끝나고 나랑 어머니는 그곳에서 극 중 가사를 반복하며 밤새 춤췄어.",
            ["DialogueId"] = 90200507,
            ["GUID"] = "E1CEB8AE",
            ["NextDialogue"] = 90200508,
            ["SpeakNpcId"] = 81103,
            ["TalkActionId"] = {
                [1] = "81103:Sigh_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_05_6",
            },
        [90200508] = {
            ["Content"] = "日出时分我累了，就躺在那袭绒毯上，枕着她的两膝，做了一个长长的梦。",
            ["ContentKR"] = "해가 뜰 무렵, 난 피곤해져 어머니 무릎을 베고 그 담요 위에 누웠지. 그리고 긴 꿈을 꿨어.",
            ["DialogueId"] = 90200508,
            ["GUID"] = "E1CEB8D8",
            ["NextOptions"] = {
                [1] = 90200002,
                [2] = 90200003,
                },
            ["SpeakNpcId"] = 81103,
            ["TalkActionId"] = {
                [1] = "81103:Sigh_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_05_7",
            ["bForbidSkipOptions"] = true,
            },
        [90200601] = {
            ["Content"] = "你最近过得好吗？\
……抱歉，是我唐突了。我们并不相识，我只是……替一个朋友问问罢了。",
            ["ContentKR"] = "잘 지내고 있나?\
...아, 미안. 내가 경솔했던 것 같아. 우린 모르는 사이니까. 그냥... 친구 대신 물어본 거야.",
            ["DialogueId"] = 90200601,
            ["GUID"] = "E1CEC81A",
            ["SpeakNpcId"] = 81103,
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_companio_01",
            },
        [90200701] = {
            ["Content"] = "是吗，你现在有了一个新家，也有了会关心照顾你的家人……真是太好了。你逃出了自己的囚笼，是个勇敢的孩子。",
            ["ContentKR"] = "그렇구나... 이제 새집도 생겼고 돌봐줄 가족도 생겼구나. 정말 잘됐어. 넌 네 감옥에서 벗어난 용감한 아이야.",
            ["DialogueId"] = 90200701,
            ["GUID"] = "E1CED882",
            ["SpeakNpcId"] = 81103,
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_companio_02",
            },
        [90200901] = {
            ["Content"] = "你的拟态能力非常特别，哪怕是最优秀的舞台道具师也未必能做出这样精妙绝伦的效果。",
            ["ContentKR"] = "너의 변신 능력은 꽤 특별하군. 최고의 무대 소품사도 이렇게 정교하고 절묘한 효과를 내진 못할 거야.",
            ["DialogueId"] = 90200901,
            ["GUID"] = "E1CEF952",
            ["SpeakNpcId"] = 81103,
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_companio_04",
            },
        [90210000] = {
            ["Content"] = "有没有什么任务可以安排给我？不，我并非有多喜欢工作，而是……一种惯性吧。如果无法让自己忙碌起来，我总觉得坐立难安。",
            ["ContentKR"] = "저에게 맡겨주실 만한 임무라도 있나요? 일을 좋아하는 게 아니라, 그냥 일종의 습관이죠. 제 자신을 바쁘게 만들지 않으면 너무 불안합니다.",
            ["DialogueId"] = 90210000,
            ["GUID"] = "E1D4CE49",
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_idle",
            },
        [90210001] = {
            ["Content"] = "今日据点巡逻结束。未发现危险生物，未发现墙壁开裂，未发现可疑记号，潜在威胁排除，可照例进行日常生活，报告完毕。",
            ["ContentKR"] = "금일 거점 순찰 완료. 위험 생물 없음. 성벽 파손 없음. 수상한 표기 없음. 잠재적 위협 배제. 평소대로 일상생활 가능. 보고 완료.",
            ["DialogueId"] = 90210001,
            ["GUID"] = "E1D4CE4A",
            ["NextOptions"] = {
                [1] = 902100011,
                [2] = 902100012,
                [3] = 902100013,
                [4] = 902100014,
                [5] = 902100015,
                [6] = 902100016,
                [7] = 902100017,
                },
            ["RandomOptionNum"] = 3,
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_welcome",
            ["bForbidSkipOptions"] = true,
            },
        [90210002] = {
            ["Content"] = "聊点别的",
            ["ContentKR"] = "다른 얘기를 하자",
            ["DialogueId"] = 90210002,
            ["GUID"] = "90210002.0",
            ["NextDialogue"] = 90210001,
            },
        [90210003] = {
            ["Content"] = "再见",
            ["ContentKR"] = "안녕",
            ["DialogueId"] = 90210003,
            ["GUID"] = "90210003.0",
            },
        [90210101] = {
            ["Content"] = "呃……你注意到了啊，我是有一把亲人留下的口琴。好好地锁了起来，但又总担心它会突然消失不见，所以会时不时，忍不住地去确认一下。",
            ["ContentKR"] = "어... 눈치채셨군요. 가족이 남겨준 하모니카가 하나 있습니다. 잘 간직하고 있지만 왠지 사라져 버릴까 불안해서 가끔 확인해 봅니다.",
            ["DialogueId"] = 90210101,
            ["GUID"] = "E1D4DEB2",
            ["NextDialogue"] = 90210102,
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_topic_01_1",
            },
        [90210102] = {
            ["Content"] = "那么你一定会很多首曲子啦？",
            ["ContentKR"] = "그럼 연주할 수 있는 노래도 많겠네요?",
            ["DialogueId"] = 90210102,
            ["GUID"] = "E1D4DEDC",
            ["NextDialogue"] = 90210103,
            ["SpeakNpcId"] = 100001,
            },
        [90210103] = {
            ["Content"] = "其实只会一首，还是亲人教给我的。我学得也不是很快，因为实在不擅长音乐这样需要情绪起伏的东西……",
            ["ContentKR"] = "사실 한 곡밖에 못 합니다. 그것도 가족이 가르쳐 준 거죠. 빨리 배우는 편이 아니라서요. 음악처럼 감정의 변화가 필요한 건 잘 못합니다...",
            ["DialogueId"] = 90210103,
            ["GUID"] = "E1D4DF06",
            ["NextDialogue"] = 90210104,
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_topic_01_2",
            },
        [90210104] = {
            ["Content"] = "不过，每当我太过紧张或者太过开心的时候，总会暗暗握住它，这能让我想到很多我确信的事，反而能够让我冷静一些。",
            ["ContentKR"] = "그래도 너무 긴장되거나 너무 기쁠 땐 항상 몰래 손에 쥐어보곤 합니다. 제가 확신하는 것들이 많이 생각나게 해서 마음이 차분해지거든요.",
            ["DialogueId"] = 90210104,
            ["GUID"] = "E1D4DF30",
            ["NextDialogue"] = 90210105,
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_topic_01_3",
            },
        [90210105] = {
            ["Content"] = "我的许多同僚会因为压力而去找医生，需要镇定或者兴奋。我不需要那些，心跳快一拍也好慢一拍也罢，口琴会帮找回正常的节拍。",
            ["ContentKR"] = "저의 많은 동료들이 스트레스 때문에 의사를 찾아가곤 합니다. 진정이나 자극이 필요한 거죠. 하지만 전 필요 없습니다. 심장이 빨리 뛰든 천천히 뛰든 하모니카가 정상적인 박자를 찾아줄 겁니다.",
            ["DialogueId"] = 90210105,
            ["GUID"] = "E1D4DF5A",
            ["NextOptions"] = {
                [1] = 90210002,
                [2] = 90210003,
                },
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_topic_01_4",
            ["bForbidSkipOptions"] = true,
            },
        [90210201] = {
            ["Content"] = "还不错，军团是一个只要努力就能获得回报的地方。我现在受到了认可，拥有几名部下，我还可以命令他们一定要平等对待卡戎之民和索拉之民。",
            ["ContentKR"] = "그럭저럭요. 군단은 노력과 보상이 정비례하는 곳입니다. 전 인정을 받았고, 부하도 몇 명 있습니다. 그들에게 카론과 솔라를 평등하게 대하라고 명령도 할 수 있죠.",
            ["DialogueId"] = 90210201,
            ["GUID"] = "E1D4EF1A",
            ["NextDialogue"] = 90210202,
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_topic_02_1",
            },
        [90210202] = {
            ["Content"] = "我听过许多人抱怨甚至谩骂军团对于卡戎之民过度严苛，而我能尽可能去缓和这些声音……我希望日子久了，可以让大家眼里的军团变得有那么一点点不一样。",
            ["ContentKR"] = "많은 이들이 군단이 카론에게 너무 가혹하다고 불평하거나 욕을 하기도 하지만, 전 그런 말들이 최대한 나오지 않도록 만들기 위해 노력했습니다... 시간이 지나 사람들이 군단에 대한 인식이 조금씩 달라졌으면 좋겠습니다.",
            ["DialogueId"] = 90210202,
            ["GUID"] = "E1D4EF44",
            ["NextDialogue"] = 90210203,
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_topic_02_2",
            },
        [90210203] = {
            ["Content"] = "可是像你这样的人还是太少了。",
            ["ContentKR"] = "하지만 리듬님 같은 사람은 너무 적어요.",
            ["DialogueId"] = 90210203,
            ["GUID"] = "E1D4EF6E",
            ["NextDialogue"] = 90210204,
            ["SpeakNpcId"] = 100001,
            },
        [90210204] = {
            ["Content"] = "会慢慢多起来的，在更早之前军团里连一个卡戎都没有呢。我虽然能做的不多，但是只要我坚持这样教导部下，那么卡戎之民和索拉之民的矛盾就会变少。",
            ["ContentKR"] = "천천히 많아질 겁니다. 이전에는 군단에 카론이 한 명도 없었던 시절도 있는걸요. 제가 할 수 있는 건 많지 않지만, 계속 그렇게 부하들을 가르치다 보면 카론과 솔라의 갈등은 줄어들 거라고 믿습니다.",
            ["DialogueId"] = 90210204,
            ["GUID"] = "E1D4EF98",
            ["NextDialogue"] = 90210205,
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_topic_02_3",
            },
        [90210205] = {
            ["Content"] = "是的，平等对待所有人，努力保护大家远离秽兽和秽蚀的威胁，就一定能让卡戎们的境遇好上一些，冰湖城里的叹气声也能少一些。",
            ["ContentKR"] = "그래요. 모든 이들을 평등하게 대하고 필토이드와 침식의 위협으로부터 지켜낸다면 카론의 상황은 분명히 나아질 겁니다. 아이스레이크 시티의 한숨 소리도 줄어들고요.",
            ["DialogueId"] = 90210205,
            ["GUID"] = "E1D4EFC2",
            ["NextOptions"] = {
                [1] = 90210002,
                [2] = 90210003,
                },
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_topic_02_4",
            ["bForbidSkipOptions"] = true,
            },
        [90210301] = {
            ["Content"] = "谈不上负责，我只是严格遵守了卫戍部队规章的所有内容而已。",
            ["ContentKR"] = "책임감이라기보단, 그저 방위대 규칙의 모든 내용을 엄격히 준수했을 뿐입니다.",
            ["DialogueId"] = 90210301,
            ["GUID"] = "E1D4FF82",
            ["NextDialogue"] = 90210302,
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_topic_03_1",
            },
        [90210302] = {
            ["Content"] = "可是其他人好像都不遵守什么规定，横行霸道的。",
            ["ContentKR"] = "하지만 다른 사람들은 규칙은 지키지 않고 횡포만 부리는 것 같던데요.",
            ["DialogueId"] = 90210302,
            ["GUID"] = "E1D4FFAC",
            ["NextDialogue"] = 90210303,
            ["SpeakNpcId"] = 100001,
            },
        [90210303] = {
            ["Content"] = "规章规定不允许随意讨论同僚的言行，否则会被视为违背军纪。",
            ["ContentKR"] = "규칙에 동료의 언행을 함부로 논하는 건 군기 위반이라고 정해져 있습니다.",
            ["DialogueId"] = 90210303,
            ["GUID"] = "E1D4FFD6",
            ["NextDialogue"] = 90210304,
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_topic_03_2",
            },
        [90210304] = {
            ["Content"] = "不过实话说，我不理解他们是怎么想的，可能觉得卫戍部队就只是一份普通的工作，只要不被上司发现，怎么胡闹都无所谓。",
            ["ContentKR"] = "그렇지만, 솔직히 그들이 무슨 생각인지 이해가 잘 안 되긴 합니다. 방위대는 그냥 평범한 직업이고, 상사에게 들키지만 않으면 소란을 피워도 상관없다고 생각하는 걸지도 모르겠습니다.",
            ["DialogueId"] = 90210304,
            ["GUID"] = "E1D50000",
            ["NextDialogue"] = 90210305,
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_topic_03_3",
            },
        [90210305] = {
            ["Content"] = "我觉得，不应该这样，人应该遵循着固定的规则而活着，否则的话，就会不断放低对自己的要求，过一天算一天，最后只能和下水道里的老鼠混在一起。",
            ["ContentKR"] = "저는 그렇게 해서는 안 된다고 생각합니다. 사람은 정해진 규칙에 따라서 살아야 하죠. 그렇지 않으면 끊임없이 자신에 대한 요구를 낮추게 되고, 하루하루 그렇게 살다 보면, 결국 하수도 안의 쥐와 다를 게 없게 되죠.",
            ["DialogueId"] = 90210305,
            ["GUID"] = "E1D5002A",
            ["NextOptions"] = {
                [1] = 90210002,
                [2] = 90210003,
                },
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_topic_03_4",
            ["bForbidSkipOptions"] = true,
            },
        [90210401] = {
            ["Content"] = "不用了……抱歉，我不太喜欢照镜子。毕竟一眼就能看到头上的角，总觉得有些难受……",
            ["ContentKR"] = "괜찮습니다... 죄송합니다. 전 거울을 보는 걸 별로 좋아하지 않습니다. 머리에 달린 뿔을 보면, 기분이 좋지 않아서요...",
            ["DialogueId"] = 90210401,
            ["GUID"] = "E1D50FEA",
            ["NextDialogue"] = 90210402,
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_topic_04_1",
            },
        [90210402] = {
            ["Content"] = "原来你不喜欢卡戎之民的外表啊……",
            ["ContentKR"] = "카론의 외모를 싫어하는군요...",
            ["DialogueId"] = 90210402,
            ["GUID"] = "E1D51014",
            ["NextDialogue"] = 90210403,
            ["SpeakNpcId"] = 100001,
            },
        [90210403] = {
            ["Content"] = "不，我并非对我们一族的外表自轻自贱。我只是觉得，如果它能长得更规则、更对称一些，也许会看起来舒服很多。啊，不是，我也没有在说你的角……",
            ["ContentKR"] = "아닙니다. 카론의 외모가 싫어서 그런 게 아니라, 그냥, 뿔의 대칭이 잘 맞았다면 더 좋았을 것 같다는 생각이 들어서요. 아, 아니에요, 당신의 뿔을 얘기한 건 아닙니다...",
            ["DialogueId"] = 90210403,
            ["GUID"] = "E1D5103E",
            ["NextOptions"] = {
                [1] = 90210002,
                [2] = 90210003,
                },
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_topic_04_2",
            ["bForbidSkipOptions"] = true,
            },
        [90210501] = {
            ["Content"] = "还在，只是它现在变得好沉重，太沉重了……我不知道自己是否还有力气再次握起它，吹奏下去。",
            ["ContentKR"] = "네, 하지만 이제 너무 무거워져 버려서... 다시 손에 쥐어 연주할 힘이 있을지 모르겠습니다.",
            ["DialogueId"] = 90210501,
            ["GUID"] = "E1D52052",
            ["NextDialogue"] = 90210502,
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_topic_05_1",
            },
        [90210502] = {
            ["Content"] = "毕竟，这把口琴曾装载了我全部的期待和梦想。",
            ["ContentKR"] = "한때, 이 하모니카에 저의 모든 기대와 꿈이 담겨 있었으니까요.",
            ["DialogueId"] = 90210502,
            ["GUID"] = "E1D5207C",
            ["NextDialogue"] = 90210503,
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_topic_05_2",
            },
        [90210503] = {
            ["Content"] = "如果有一天你能重新吹起它，让我做你的第一个听众吧。",
            ["ContentKR"] = "언젠간 다시 연주할 수 있게 된다면, 제가 첫 번째로 들을 수 있게 해주세요.",
            ["DialogueId"] = 90210503,
            ["GUID"] = "E1D520A6",
            ["NextDialogue"] = 90210504,
            ["SpeakNpcId"] = 100001,
            },
        [90210504] = {
            ["Content"] = "……我明白了。我答应你，等将来有一天，我能够再次拿起这把口琴，去学习新曲子的时候……一定第一个吹奏给你听。",
            ["ContentKR"] = "...알겠습니다. 그렇게 할게요. 언젠가, 제가 이 하모니카를 다시 잡고, 새로운 곡을 배우게 된다면... 꼭 제일 처음으로 들려드리도록 하겠습니다.",
            ["DialogueId"] = 90210504,
            ["GUID"] = "E1D520D0",
            ["NextOptions"] = {
                [1] = 90210002,
                [2] = 90210003,
                },
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_topic_05_3",
            ["bForbidSkipOptions"] = true,
            },
        [90210601] = {
            ["Content"] = "我每天都会接到一些零工，够我一个人日常开销和吃穿用度。不过，对现在的我来说，工作与其说是为了糊口，不如说是为了工作本身。",
            ["ContentKR"] = "매일 아르바이트를 합니다. 혼자 먹고 살기엔 충분해요. 지금의 저에게는, 먹고 살기 위해 일을 한다기보단, 그냥 일 그 자체를 위해서인 것 같아요.",
            ["DialogueId"] = 90210601,
            ["GUID"] = "E1D530BA",
            ["NextDialogue"] = 90210602,
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_topic_06_1",
            },
        [90210602] = {
            ["Content"] = "为了工作本身？",
            ["ContentKR"] = "일 그 자체를 위해서요?",
            ["DialogueId"] = 90210602,
            ["GUID"] = "E1D530E4",
            ["NextDialogue"] = 90210603,
            ["SpeakNpcId"] = 100001,
            },
        [90210603] = {
            ["Content"] = "工作让我的生活充实无比，工作让我的心情更加快乐，有工作的日子，太阳都会更暖和一点。",
            ["ContentKR"] = "일은 제 삶을 풍요롭게 하고, 마음을 즐겁게 합니다. 할 일이 있는 날은 햇살도 더 따뜻하게 느껴지죠.",
            ["DialogueId"] = 90210603,
            ["GUID"] = "E1D5310E",
            ["NextOptions"] = {
                [1] = 90210002,
                [2] = 90210003,
                },
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_topic_06_2",
            ["bForbidSkipOptions"] = true,
            },
        [90210701] = {
            ["Content"] = "至少比待在里面要好。军团曾是我安身的庇护所，是我的梦想所在。但是现在梦想成了谎言，我以为的庇护所是让家人万劫不复的地狱……",
            ["ContentKR"] = "적어도 떠나기 전보단 낫습니다. 군단은 한 때 저의 안식처였고 꿈이 있는 곳이었습니다만, 그 꿈은 거짓말이 돼버렸고 제가 안식처라 여겼던 곳은 가족들을 죽음으로 내모는 지옥이었습니다...",
            ["DialogueId"] = 90210701,
            ["GUID"] = "E1D54122",
            ["NextDialogue"] = 90210702,
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_topic_07_1",
            },
        [90210702] = {
            ["Content"] = "我无法释怀家人的仇，可是我也无法对昔日同僚拔枪相向。我真的不知道……告诉我，我应该怎么办才好？",
            ["ContentKR"] = "가족들의 복수는 포기할 수 없지만, 옛 동료들에게 총을 겨눌 수도 없습니다. 전 정말 모르겠어요... 말해 주세요, 전 어떻게 해야 할까요?",
            ["DialogueId"] = 90210702,
            ["GUID"] = "E1D5414C",
            ["NextDialogue"] = 90210703,
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_topic_07_2",
            },
        [90210703] = {
            ["Content"] = "我想这个问题只能由你自己回答。",
            ["ContentKR"] = "이 문제는 스스로 답을 찾아야 할 것 같아요.",
            ["DialogueId"] = 90210703,
            ["GUID"] = "E1D54176",
            ["NextDialogue"] = 90210704,
            ["SpeakNpcId"] = 100001,
            },
        [90210704] = {
            ["Content"] = "……抱歉，刚才是我失态了。你说得没错，我应该自己找出答案，而不是把问题推给你。虽然，这可能还要花上很长的时间吧……",
            ["ContentKR"] = "...죄송합니다, 실례를 범했네요. 당신 말이 맞습니다. 당신한테 문제를 떠넘길 게 아니라 스스로 답을 찾아야겠죠. 시간이 오래 걸리겠지만요...",
            ["DialogueId"] = 90210704,
            ["GUID"] = "E1D541A0",
            ["NextOptions"] = {
                [1] = 90210002,
                [2] = 90210003,
                },
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_topic_07_3",
            ["bForbidSkipOptions"] = true,
            },
        [90210901] = {
            ["Content"] = "这份计划书上的安排详略得当，精确到秒，逐步完成这些安排想必能获得巨大的满足感。只是……真的很难把这样严密的计划与兰迪长官联系起来。",
            ["ContentKR"] = "이 계획서는 정말 초 단위까지 정확하게 잘 짜였군요. 이 계획들을 단계별로 완료할 수 있다면 정말 큰 만족감이 느껴질 것 같습니다. 그런데 이런 빈틈없는 계획과 랜디 님이라니... 연결짓기 어렵네요.",
            ["DialogueId"] = 90210901,
            ["GUID"] = "E1D561F2",
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_companio_02",
            },
        [90220000] = {
            ["Content"] = "在这纷争的土地上，能拥有这么一方安宁天地，享受片刻放松的时光，也不错。",
            ["ContentKR"] = "이 분쟁의 땅에 이렇게 아늑한 곳이 있다니, 잠시나마 휴식을 취하는 것도 나쁘지 않을 것 같구나.",
            ["DialogueId"] = 90220000,
            ["GUID"] = "E1DB36E9",
            ["SpeakNpcId"] = 81502,
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_idle",
            },
        [90220001] = {
            ["Content"] = "是你呀，亲爱的孩子。日安，有什么事想要讲给我听吗？",
            ["ContentKR"] = "너구나, 내가 아끼는 아이. 내게 들려주고 싶은 이야기라도 있니?",
            ["DialogueId"] = 90220001,
            ["GUID"] = "E1DB36EA",
            ["LookAt"] = {
                [1] = "81502:n(0)",
                [2] = "0:n(81502)",
                },
            ["NextOptions"] = {
                [1] = 902200011,
                [2] = 902200012,
                [3] = 902200013,
                [4] = 902200014,
                },
            ["RandomOptionNum"] = 3,
            ["SpeakNpcId"] = 81502,
            ["TalkActionId"] = {
                [1] = "81502:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_welcome",
            ["bForbidSkipOptions"] = true,
            },
        [90220002] = {
            ["Content"] = "聊点别的",
            ["ContentKR"] = "다른 얘기를 하자",
            ["DialogueId"] = 90220002,
            ["GUID"] = "90220002.0",
            ["NextDialogue"] = 90220001,
            },
        [90220003] = {
            ["Content"] = "再见",
            ["ContentKR"] = "안녕",
            ["DialogueId"] = 90220003,
            ["GUID"] = "90220003.0",
            },
        [90220101] = {
            ["Content"] = "是的，在漫长的时间中，我在阿特拉西亚的各处旅行——或者流浪。我用双足丈量过这片土地的每一寸刻度，也用手指摩挲过它的每一缕纹理。",
            ["ContentKR"] = "맞아. 긴 시간 동안, 나는 아트라시아 곳곳을 여행... 혹은 방황했지. 난 이 땅의 눈금을 두 발로 재보았고, 이 땅의 모든 결을 손끝으로 매만졌어.",
            ["DialogueId"] = 90220101,
            ["GUID"] = "E1DB4752",
            ["LookAt"] = {
                [1] = "81502:n(0)",
                [2] = "0:n(81502)",
                },
            ["NextDialogue"] = 90220102,
            ["SpeakNpcId"] = 81502,
            ["TalkActionId"] = {
                [1] = "81502:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_01_1",
            },
        [90220102] = {
            ["Content"] = "那你最喜欢的地方是哪儿？",
            ["ContentKR"] = "제일 좋았던 곳은 어디예요?",
            ["DialogueId"] = 90220102,
            ["GUID"] = "E1DB477C",
            ["NextDialogue"] = 90220103,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "81502:Explain01_End",
                },
            },
        [90220103] = {
            ["Content"] = "如果你走过足够多的地方，会觉得各处的风景并无太多差别。北境的飞雪，赫墨的砂砾，或者华胥的炊烟，无非也是另一种林间的薄雾而已。",
            ["ContentKR"] = "충분히 많은 곳을 다녀보면, 모든 풍경이 크게 다르지 않다는 걸 알게 될 거란다. 북쪽 지대의 흩날리는 눈도, 케메트의 자갈도, 화서의 연기도, 결국은 또 다른 숲속의 안개일 뿐이지.",
            ["DialogueId"] = 90220103,
            ["GUID"] = "E1DB47A6",
            ["NextDialogue"] = 90220104,
            ["SpeakNpcId"] = 81502,
            ["TalkActionId"] = {
                [1] = "81502:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_01_2",
            },
        [90220104] = {
            ["Content"] = "如果一定要说个地方的话……那便是伊瑟尔的群山和林地。那里的气息最让我感到安心。",
            ["ContentKR"] = "굳이 한 곳을 말하자면... 이스엘의 산과 숲이 아닐까 해. 그곳의 기운이 가장 편하게 느껴지거든.",
            ["DialogueId"] = 90220104,
            ["GUID"] = "E1DB47D0",
            ["NextDialogue"] = 90220105,
            ["SpeakNpcId"] = 81502,
            ["TalkActionId"] = {
                [1] = "81502:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_01_3",
            },
        [90220105] = {
            ["Content"] = "那我有机会也要去看看。",
            ["ContentKR"] = "기회가 된다면 저도 한번 가봐야겠어요.",
            ["DialogueId"] = 90220105,
            ["GUID"] = "E1DB47FA",
            ["NextDialogue"] = 90220106,
            ["SpeakNpcId"] = 100001,
            },
        [90220106] = {
            ["Content"] = "好啊。",
            ["ContentKR"] = "그래.",
            ["DialogueId"] = 90220106,
            ["GUID"] = "E1DB4824",
            ["NextDialogue"] = 90220107,
            ["SpeakNpcId"] = 81502,
            ["TalkActionId"] = {
                [1] = "81502:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_01_4",
            },
        [90220107] = {
            ["Content"] = "若有一天你去翡翠森林，请帮我带一束白堇致候吧。在那里长眠的啊，是我的友人、我的孩子、以及少时的我。",
            ["ContentKR"] = "언젠가 에메랄드 숲에 가게 된다면, 하얀 팬지꽃 한 다발을 가져다줘. 그곳엔 내 친구, 내 아이, 그리고 어린 시절의 내가 잠들어있거든.",
            ["DialogueId"] = 90220107,
            ["GUID"] = "E1DB484E",
            ["NextOptions"] = {
                [1] = 90220002,
                [2] = 90220003,
                },
            ["SpeakNpcId"] = 81502,
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_01_5",
            ["bForbidSkipOptions"] = true,
            },
        [90220201] = {
            ["Content"] = "雾海是一切生者的来处与归途。万物归于雾海，雾海又孕育新的万物……就像死去的云滴落泥土，鲜花又自泥土中盛开。",
            ["ContentKR"] = "안개의 바다는 살아있는 모든 것이 시작된 곳이자 돌아갈 곳이란다. 모든 것은 안개의 바다로 돌아가서 새롭게 태어날 거야... 마치 죽은 구름이 빗물이 되어 땅속에 묻혀 새로운 꽃을 피워내는 것처럼.",
            ["DialogueId"] = 90220201,
            ["GUID"] = "E1DB57BA",
            ["LookAt"] = {
                [1] = "81502:n(0)",
                [2] = "0:n(81502)",
                },
            ["NextDialogue"] = 90220202,
            ["SpeakNpcId"] = 81502,
            ["TalkActionId"] = {
                [1] = "81502:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_02_1",
            },
        [90220202] = {
            ["Content"] = "有一天我也会去往那里吗？",
            ["ContentKR"] = "저도 언젠간 거기로 가게 될까요?",
            ["DialogueId"] = 90220202,
            ["GUID"] = "E1DB57E4",
            ["NextDialogue"] = 90220203,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "81502:Confident_End",
                },
            },
        [90220203] = {
            ["Content"] = "我想是的。终有一天，你会前往雾海，前往茵布拉女神的怀抱。",
            ["ContentKR"] = "그렇겠지. 언젠간 너도 안개의 바다로, 엠블라 여신의 품속으로 가게 되겠지.",
            ["DialogueId"] = 90220203,
            ["GUID"] = "E1DB580E",
            ["NextDialogue"] = 90220204,
            ["SpeakNpcId"] = 81502,
            ["TalkActionId"] = {
                [1] = "81502:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_02_2",
            },
        [90220204] = {
            ["Content"] = "听上去有些可怕……",
            ["ContentKR"] = "좀 무섭게 들리네요...",
            ["DialogueId"] = 90220204,
            ["GUID"] = "E1DB5838",
            ["NextDialogue"] = 90220205,
            ["SpeakNpcId"] = 100001,
            },
        [90220205] = {
            ["Content"] = "孩子，请你爱着生的一切，亦不要畏惧消亡。消亡并非苦痛，只是生命必经的终点。",
            ["ContentKR"] = "아이야, 삶의 모든 것을 사랑하며, 죽음을 두려워하지 마. 죽음은 고통이 아니라 피하지 못할 삶의 끝일 뿐이지.",
            ["DialogueId"] = 90220205,
            ["GUID"] = "E1DB5862",
            ["NextDialogue"] = 90220206,
            ["SpeakNpcId"] = 81502,
            ["TalkActionId"] = {
                [1] = "81502:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_02_3",
            },
        [90220206] = {
            ["Content"] = "若你累了，就在我的臂弯中安歇片刻吧……别害怕，这不会是永眠。现在的你，还有太多未竟之事。",
            ["ContentKR"] = "피곤하다면 내 품속에서 잠시 쉬어가도록 해... 영면은 아니니 두려워하지 마. 지금의 너에겐 아직 해야 할 일이 너무 많아.",
            ["DialogueId"] = 90220206,
            ["GUID"] = "E1DB588C",
            ["NextOptions"] = {
                [1] = 90220002,
                [2] = 90220003,
                },
            ["SpeakNpcId"] = 81502,
            ["TalkActionId"] = {
                [1] = "81502:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_02_4",
            ["bForbidSkipOptions"] = true,
            },
        [90220301] = {
            ["Content"] = "怎么，这很让你惊讶吗？实不相瞒，在昔日“大迁徙”时，我还曾是一位在前线冲锋陷阵的战士，一位格斗的好手。",
            ["ContentKR"] = "왜, 그렇게 놀랍니? 사실 난 예전에 '대이동' 때 선봉에 선 전사였어. 격투기의 달인이야.",
            ["DialogueId"] = 90220301,
            ["GUID"] = "E1DB6822",
            ["LookAt"] = {
                [1] = "81502:n(0)",
                [2] = "0:n(81502)",
                },
            ["NextDialogue"] = 90220302,
            ["SpeakNpcId"] = 81502,
            ["TalkActionId"] = {
                [1] = "81502:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_03_1",
            },
        }
  end },
  { MinKey = 90220302, MaxKey = 101012133, Loader = function()
      return {
        [90220302] = {
            ["Content"] = "虽说那是十分遥远的过去，但基本的战斗技巧，我大体都还记得。",
            ["ContentKR"] = "아주 먼 옛날 일이지만 기본적인 전투 기술은 거의 다 기억하고 있지.",
            ["DialogueId"] = 90220302,
            ["GUID"] = "E1DB684C",
            ["NextDialogue"] = 90220303,
            ["SpeakNpcId"] = 81502,
            ["TalkActionId"] = {
                [1] = "81502:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_03_2",
            },
        [90220303] = {
            ["Content"] = "在旅途中，我也会时不时要与盘桓的兽群搏斗，它们也曾带给我爪痕，淤伤，甚至理当的死亡。",
            ["ContentKR"] = "여행 중 가끔 짐승 무리와 싸워야 할 때도 있어. 그것들은 내게 상처도 남기고, 심지어 죽음의 위험까지도 가져다주었어.",
            ["DialogueId"] = 90220303,
            ["GUID"] = "E1DB6876",
            ["NextDialogue"] = 90220304,
            ["SpeakNpcId"] = 81502,
            ["TalkActionId"] = {
                [1] = "81502:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_03_3",
            },
        [90220304] = {
            ["Content"] = "好难想象你近身搏斗的样子。",
            ["ContentKR"] = "근접 전투를 치르는 모습은 상상이 안 가네요.",
            ["DialogueId"] = 90220304,
            ["GUID"] = "E1DB68A0",
            ["NextDialogue"] = 90220305,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "81502:Talk02_End",
                },
            },
        [90220305] = {
            ["Content"] = "亘古的月亮尚且每天都在变幻，人类当然更加复杂。更何况如我一般，经历过数倍于常人岁月的人呢？",
            ["ContentKR"] = "밤이 되면 영원히 찾아오는 달도 매일 모습이 바뀌는데, 인간은 더욱 복잡하게 변화하는 법이지. 하물며 나처럼 보통 인간의 몇 배나 되는 세월을 지내온 사람은 어떻겠어?",
            ["DialogueId"] = 90220305,
            ["GUID"] = "E1DB68CA",
            ["NextDialogue"] = 90220306,
            ["SpeakNpcId"] = 81502,
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_03_4",
            },
        [90220306] = {
            ["Content"] = "若是你对这段过往有兴趣，改日我细细说与你听吧。",
            ["ContentKR"] = "그 이야기에 관심이 있다면 나중에 자세하게 얘기해줄게.",
            ["DialogueId"] = 90220306,
            ["GUID"] = "E1DB68F4",
            ["NextOptions"] = {
                [1] = 90220002,
                [2] = 90220003,
                },
            ["SpeakNpcId"] = 81502,
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_03_5",
            ["bForbidSkipOptions"] = true,
            },
        [90220401] = {
            ["Content"] = "“朋友”……以人们对这二字的通常定义来看，我有过很多朋友。",
            ["ContentKR"] = "'친구'라... 사람들이 흔히 말하는 친구라면 많이 있었지.",
            ["DialogueId"] = 90220401,
            ["GUID"] = "E1DB788A",
            ["LookAt"] = {
                [1] = "81502:n(0)",
                [2] = "0:n(81502)",
                },
            ["NextDialogue"] = 90220402,
            ["SpeakNpcId"] = 81502,
            ["TalkActionId"] = {
                [1] = "81502:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_04_1",
            },
        [90220402] = {
            ["Content"] = "不过，提起这个词，我最先想到的还是莱克西斯和艾瑞卡——就是带我离开艾利西安的那两位朋友。",
            ["ContentKR"] = "그래도 친구라는 단어를 떠올렸을 때, 가장 먼저 생각나는 건 아무래도 나를 엘리시안에서 떠나게 해준 렉시스와 에리카인 것 같아.",
            ["DialogueId"] = 90220402,
            ["GUID"] = "E1DB78B4",
            ["NextDialogue"] = 90220403,
            ["SpeakNpcId"] = 81502,
            ["TalkActionId"] = {
                [1] = "81502:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_04_2",
            },
        [90220403] = {
            ["Content"] = "他们是怎样的人？",
            ["ContentKR"] = "그들은 어떤 사람인가요?",
            ["DialogueId"] = 90220403,
            ["GUID"] = "E1DB78DE",
            ["NextDialogue"] = 90220404,
            ["SpeakNpcId"] = 100001,
            },
        [90220404] = {
            ["Content"] = "在后世的史书和英雄故事里，他们通常被描述成揭下神明蒙昧的纱幕、将真理带给人们的“智者”，以及为了智者崇奉的真理而牺牲的“英雄”……",
            ["ContentKR"] = "후세의 역사책과 영웅담에선 그들을 신들에 대한 무지함을 걷어내고 진리를 전한 '현자', 혹은 현자의 진리를 위해 목숨을 바친 '영웅'으로 기록하더구나...",
            ["DialogueId"] = 90220404,
            ["GUID"] = "E1DB7908",
            ["NextDialogue"] = 90220405,
            ["SpeakNpcId"] = 81502,
            ["TalkActionId"] = {
                [1] = "81502:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_04_3",
            },
        [90220405] = {
            ["Content"] = "但我常常回忆起他们还仅仅是“莱克西斯”和“艾瑞卡”的时候。",
            ["ContentKR"] = "하지만 난 그들이 그저 '렉시스'와 '에리카'였을 때를 자주 떠올리지.",
            ["DialogueId"] = 90220405,
            ["GUID"] = "E1DB7932",
            ["NextDialogue"] = 90220406,
            ["SpeakNpcId"] = 81502,
            ["TalkActionId"] = {
                [1] = "81502:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_04_4",
            },
        [90220406] = {
            ["Content"] = "那时艾瑞卡是个勇敢活泼的姑娘，大家都很喜欢她。莱克西斯虽然头脑很聪明，但有时候太较真，经常突然陷入沉思，所以反而会显得有些迟钝。",
            ["ContentKR"] = "에리카는 용감하고 활발한 아가씨였단다. 모두가 그녀를 좋아했어. 렉시스는 머리가 너무 좋았지만 과하게 진지한 면도 있었지. 갑자기 생각에 잠기는 경우가 많아 오히려 둔해 보일 때가 있곤 했어.",
            ["DialogueId"] = 90220406,
            ["GUID"] = "E1DB795C",
            ["NextDialogue"] = 90220407,
            ["SpeakNpcId"] = 81502,
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_04_5",
            },
        [90220407] = {
            ["Content"] = "你还记得什么趣事吗？",
            ["ContentKR"] = "또 재미있는 일 기억 나는 거 없어요?",
            ["DialogueId"] = 90220407,
            ["GUID"] = "E1DB7986",
            ["NextDialogue"] = 90220408,
            ["SpeakNpcId"] = 100001,
            },
        [90220408] = {
            ["Content"] = "嗯……有一次，莱克西斯为了某件事去给艾瑞卡道歉，艾瑞卡便随口指着士兵们用来练箭的靶子说，他要是能射中红心就原谅他……",
            ["ContentKR"] = "흠... 한번은 렉시스가 어떤 일 때문에 에리카에게 사과하러 간 적이 있었어. 에리카는 병사들이 활 연습을 하던 과녁을 가리키며 정 가운데를 맞추면 용서해 주겠다고 했지...",
            ["DialogueId"] = 90220408,
            ["GUID"] = "E1DB79B0",
            ["NextDialogue"] = 90220409,
            ["SpeakNpcId"] = 81502,
            ["TalkActionId"] = {
                [1] = "81502:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_04_6",
            },
        [90220409] = {
            ["Content"] = "当然，这是一句气话。连士兵都不是每个人都做得到，更何况莱克西斯的双手并不是用来握剑，而是用来书写灵智与真理的。",
            ["ContentKR"] = "물론 그건 홧김에 한 소리였어. 병사들조차도 쉽게 해낼 수 있는 일이 아니었고, 게다가 렉시스의 두 손은 검이 아니라 지혜와 진리를 기록할 펜을 잡는 데 쓰여왔거든.",
            ["DialogueId"] = 90220409,
            ["GUID"] = "E1DB79DA",
            ["NextDialogue"] = 90220410,
            ["SpeakNpcId"] = 81502,
            ["TalkActionId"] = {
                [1] = "81502:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_04_7",
            },
        [90220410] = {
            ["Content"] = "但他却把这话当真了，趁士兵们歇息之后，一个人练习了一晚上。",
            ["ContentKR"] = "하지만 그는 그 말을 진담으로 받아들이고, 병사들이 잠에 들길 기다렸다 밤새 혼자 연습을 했어.",
            ["DialogueId"] = 90220410,
            ["GUID"] = "E1DB7A04",
            ["NextDialogue"] = 90220411,
            ["SpeakNpcId"] = 81502,
            ["TalkActionId"] = {
                [1] = "81502:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_04_8",
            },
        [90220411] = {
            ["Content"] = "当然，历史不是英雄传说。即使是聪慧如莱克西斯，也有学不会的事。他一直练习到手心被磨出血，艾瑞卡为他包上麻布，也没能射中靶心。",
            ["ContentKR"] = "물론 역사는 영웅담이 아니야. 아무리 슬기로운 렉시스라도 배우지 못하는 건 있기 마련이지. 렉시스는 손바닥에 피가 날 때까지 연습했고, 에리카가 그걸 보곤 손에 천을 감아 주었지만, 결국 과녁을 맞추진 못했어.",
            ["DialogueId"] = 90220411,
            ["GUID"] = "E1DB7A2E",
            ["NextDialogue"] = 90220412,
            ["SpeakNpcId"] = 81502,
            ["TalkActionId"] = {
                [1] = "81502:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_04_9",
            },
        [90220412] = {
            ["Content"] = "呵呵……最开始他们到底是为了什么吵架，我反而记不起来了。真是奇怪……现在回忆起有关他们的事，最先浮现的总是这些微不足道的细节。",
            ["ContentKR"] = "하하. 무슨 일 때문에 싸웠는지는 오히려 기억이 안 나네. 참 이상하지... 그들에 대한 일들을 생각해 보면 항상 이런 사소한 일들만 먼저 떠오르네.",
            ["DialogueId"] = 90220412,
            ["GUID"] = "E1DB7A58",
            ["NextDialogue"] = 90220413,
            ["SpeakNpcId"] = 81502,
            ["TalkActionId"] = {
                [1] = "81502:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_04_10",
            },
        [90220413] = {
            ["Content"] = "听起来是一段非常快乐的时光。",
            ["ContentKR"] = "정말 즐거운 시간들이었을 것 같아요.",
            ["DialogueId"] = 90220413,
            ["GUID"] = "E1DB7A82",
            ["NextDialogue"] = 90220414,
            ["SpeakNpcId"] = 100001,
            },
        [90220414] = {
            ["Content"] = "嗯，是啊。那确实是……非常、非常快乐的日子。只是，已经是很久很久以前的事了。",
            ["ContentKR"] = "맞아. 그때는 정말... 더없이 행복한 날들이었지. 하지만 이젠 너무 먼 과거의 일이 되어버렸어.",
            ["DialogueId"] = 90220414,
            ["GUID"] = "E1DB7AAC",
            ["NextOptions"] = {
                [1] = 90220002,
                [2] = 90220003,
                },
            ["SpeakNpcId"] = 81502,
            ["TalkActionId"] = {
                [1] = "81502:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_04_11",
            ["bForbidSkipOptions"] = true,
            },
        [90220501] = {
            ["Content"] = "人无法真正逃离自己的过去。总有一天，你会需要面对它们……希望到那时，你已经获得了足够与之对抗的力量。",
            ["ContentKR"] = "누구도 자신의 과거에서 벗어날 수 없어. 언젠가 너도 그것들과 마주해야겠지... 그때가 되면 그들과 맞설 힘을 얻었길 바랄게.",
            ["DialogueId"] = 90220501,
            ["GUID"] = "E1DB88F2",
            ["SpeakNpcId"] = 81502,
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_companio_01",
            },
        [90220601] = {
            ["Content"] = "姑娘，你身上有股熟悉的气息，莫不是与我同为旧日之人？",
            ["ContentKR"] = "아가씨는 어쩐지 낯익은 기운이 느껴지네. 혹 나와 같은 옛사람이 아닌가?",
            ["DialogueId"] = 90220601,
            ["GUID"] = "E1DB995A",
            ["SpeakNpcId"] = 81502,
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_companio_02",
            },
        [90230000] = {
            ["Content"] = "近来的日程我都让秘书推掉了。这几日，我只想与你待在一起，排却外界纷扰，体会此处的清净——这次是真心诚意，还是另有所图？不妨猜猜看吧。",
            ["ContentKR"] = "최근 일정은 모두 비서에게 미루라고 했어. 이번 며칠은 너와 함께하면서 외부의 소란을 잊고, 이곳의 고요를 만끽하고 싶어... 이번엔 진심일까, 아니면 다른 의도가 있을까? 한번 맞춰볼래.",
            ["DialogueId"] = 90230000,
            ["GUID"] = "E1E19F60",
            ["SpeakNpcId"] = 84102,
            ["VoiceName"] = "voice/$Locale$/char/Zhiliu/vo_idle",
            },
        [90230001] = {
            ["Content"] = "你愿意来见我了……你还在生气吗？困惑吗？还是说，你已经对我漠然无动于衷？无妨，现在我们有大把的时间可以一一探讨。",
            ["ContentKR"] = "네가 나를 만나러 와줬군... 아직 화났어? 혼란스러운 건가? 아니면, 이제 나에게 무관심해진 걸까? 괜찮아. 이제 우리에겐 천천히 이야기를 나눌 시간이 많으니까.",
            ["DialogueId"] = 90230001,
            ["GUID"] = "E1E19F8A",
            ["LookAt"] = {
                [1] = "84102:n(0)",
                [2] = "0:n(84102)",
                },
            ["NextOptions"] = {
                [1] = 902300011,
                [2] = 902300012,
                [3] = 902300013,
                [4] = 902300014,
                },
            ["RandomOptionNum"] = 3,
            ["SpeakNpcId"] = 84102,
            ["VoiceName"] = "voice/$Locale$/char/Zhiliu/vo_welcome",
            ["bForbidSkipOptions"] = true,
            },
        [90230002] = {
            ["Content"] = "聊点别的",
            ["ContentKR"] = "다른 얘기를 하자",
            ["DialogueId"] = 90230002,
            ["GUID"] = "E1E19FB4",
            ["NextDialogue"] = 90230001,
            },
        [90230003] = {
            ["Content"] = "再见",
            ["ContentKR"] = "안녕",
            ["DialogueId"] = 90230003,
            ["GUID"] = "E1E19FDE",
            },
        [90230101] = {
            ["Content"] = "没有什么是不能作为筹码的。区别仅仅在于，你所付出的，能够撬动怎样的回报。",
            ["ContentKR"] = "모든 것이 거래의 수단이 될 수 있지. 다만, 중요한 건 네가 지불한 대가가 어떤 보상을 가져다주는가에 달려 있을 뿐이거든.",
            ["DialogueId"] = 90230101,
            ["GUID"] = "E1E1AFF2",
            ["LookAt"] = {
                [1] = "84102:n(0)",
                [2] = "0:n(84102)",
                },
            ["NextDialogue"] = 90230102,
            ["SpeakNpcId"] = 84102,
            ["VoiceName"] = "voice/$Locale$/char/Zhiliu/vo_topic_01_1",
            },
        [90230102] = {
            ["Content"] = "就算是性命也没关系吗？",
            ["ContentKR"] = "목숨도 거래의 대상이 될 수 있나요?",
            ["DialogueId"] = 90230102,
            ["GUID"] = "E1E1B01C",
            ["NextDialogue"] = 90230103,
            ["SpeakNpcId"] = 100001,
            },
        [90230103] = {
            ["Content"] = "没错。你的性命、我的性命，乃至于芸芸众生，在更高的利益层面上，都只是一枚筹码罢了。",
            ["ContentKR"] = "맞아. 네 목숨, 나의 목숨, 심지어 수많은 사람들의 목숨도 더 큰 이익 앞에서는 그저 하나의 수단일 뿐이지.",
            ["DialogueId"] = 90230103,
            ["GUID"] = "E1E1B046",
            ["NextDialogue"] = 90230104,
            ["SpeakNpcId"] = 84102,
            ["VoiceName"] = "voice/$Locale$/char/Zhiliu/vo_topic_01_2",
            },
        [90230104] = {
            ["Content"] = "对于渺小的人类而言，能够用自己仅有的筹码，去偿换欲求之物，未尝不是一件幸事。",
            ["ContentKR"] = "하찮은 인간에게는 자신이 가진 것으로 원하는 걸 얻는 것만으로도 아주 나쁘지 않은 선택일 수 있어.",
            ["DialogueId"] = 90230104,
            ["GUID"] = "E1E1B070",
            ["NextDialogue"] = 90230105,
            ["SpeakNpcId"] = 84102,
            ["VoiceName"] = "voice/$Locale$/char/Zhiliu/vo_topic_01_3",
            },
        [90230105] = {
            ["Content"] = "讨厌这个答案吗？那就向我证明，我所言非实吧。",
            ["ContentKR"] = "이 답이 마음에 들지 않나? 그렇다면 내가 틀렸다는 걸 직접 증명해 봐.",
            ["DialogueId"] = 90230105,
            ["GUID"] = "E1E1B09A",
            ["NextOptions"] = {
                [1] = 90230002,
                [2] = 90230003,
                },
            ["SpeakNpcId"] = 84102,
            ["VoiceName"] = "voice/$Locale$/char/Zhiliu/vo_topic_01_4",
            ["bForbidSkipOptions"] = true,
            },
        [90230201] = {
            ["Content"] = "让我想想……不必计较一时得失，多多让利。学会观人、用人，施以恩惠。让他们敬你、重你，但也畏惧于你。",
            ["ContentKR"] = "음... 일시적인 손익에 집착하지 말고, 아낌없이 베푸는 거지. 그리고 사람을 알아보고, 적재적소에 사람을 쓰고, 은혜를 베푸는 것도 배워야지. 사람들이 널 존경하고 중시하면서도, 동시에 두려워하도록 만드는 것도 중요하단다.",
            ["DialogueId"] = 90230201,
            ["GUID"] = "E1E1C05A",
            ["LookAt"] = {
                [1] = "84102:n(0)",
                [2] = "0:n(84102)",
                },
            ["NextDialogue"] = 90230202,
            ["SpeakNpcId"] = 84102,
            ["VoiceName"] = "voice/$Locale$/char/Zhiliu/vo_topic_02_1",
            },
        [90230202] = {
            ["Content"] = "这和我想的不太一样。",
            ["ContentKR"] = "그건 제가 생각했던 것과는 조금 다르네요.",
            ["DialogueId"] = 90230202,
            ["GUID"] = "E1E1C084",
            ["NextDialogue"] = 90230203,
            ["SpeakNpcId"] = 100001,
            },
        [90230203] = {
            ["Content"] = "呵呵。货物有价，人情无价。锱铢必较者，只能经营足下一隅。学会借助人情的东风，才能飞向更加广阔的天地。",
            ["ContentKR"] = "하하. 물건에는 가격표가 있지만, 인간관계에는 가격표가 없어. 작은 이익에 집착하는 사람은 결국 작은 세계 안에서만 머물게 되지. 인간관계를 잘 활용해야 더 넓은 세상으로 나아갈 수 있단다.",
            ["DialogueId"] = 90230203,
            ["GUID"] = "E1E1C0AE",
            ["NextOptions"] = {
                [1] = 90230002,
                [2] = 90230003,
                },
            ["SpeakNpcId"] = 84102,
            ["VoiceName"] = "voice/$Locale$/char/Zhiliu/vo_topic_02_2",
            ["bForbidSkipOptions"] = true,
            },
        [90230301] = {
            ["Content"] = "我平素多有琐事缠身，很少能真正得空。闲暇二字，于我倒是有些许奢侈。",
            ["ContentKR"] = "평소에 자질구레한 일들이 많아서 여유를 가질 시간이 거의 없어. 여가라는 말이 내겐 조금 사치스럽게 느껴질 정도지.",
            ["DialogueId"] = 90230301,
            ["GUID"] = "E1E1D0C2",
            ["LookAt"] = {
                [1] = "84102:n(0)",
                [2] = "0:n(84102)",
                },
            ["NextDialogue"] = 90230302,
            ["SpeakNpcId"] = 84102,
            ["VoiceName"] = "voice/$Locale$/char/Zhiliu/vo_topic_03_1",
            },
        [90230302] = {
            ["Content"] = "若是侥幸得了浮生半日闲……我大约会去观戏吧。无论是华胥的说书、评弹，帝国的歌剧、话剧，抑或是远洋新近流行的照影，我都有几分兴致。",
            ["ContentKR"] = "만약 뜻밖에 반나절의 여유가 생긴다면... 아마 극을 보러 갈 것 같아. 화서의 이야기 공연, 제국의 오페라나 연극, 혹은 해외에서 새롭게 유행하는 영상극까지 모두 흥미가 있어.",
            ["DialogueId"] = 90230302,
            ["GUID"] = "E1E1D0EC",
            ["NextDialogue"] = 90230303,
            ["SpeakNpcId"] = 84102,
            ["VoiceName"] = "voice/$Locale$/char/Zhiliu/vo_topic_03_2",
            },
        [90230303] = {
            ["Content"] = "原来我们相遇在剧院并非偶然。",
            ["ContentKR"] = "우리가 극장에서 만난 건 우연이 아니었군요.",
            ["DialogueId"] = 90230303,
            ["GUID"] = "E1E1D116",
            ["NextDialogue"] = 90230304,
            ["SpeakNpcId"] = 100001,
            },
        [90230304] = {
            ["Content"] = "呵呵……是啊。戏剧撷取吉光片羽，却能讲尽人性幽微。人心这东西，说不清，道不明，总是带来意外，又永远教人看不厌。",
            ["ContentKR"] = "하하... 맞아. 연극은 짧은 순간을 포착하면서도 인간 본성의 깊은 부분을 모두 이야기할 수 있지. 사람 마음이라는 게 참 설명하기도 어렵고, 늘 예상치 못한 놀라움을 주면서도 언제나 흥미롭잖아.",
            ["DialogueId"] = 90230304,
            ["GUID"] = "E1E1D140",
            ["NextDialogue"] = 90230305,
            ["SpeakNpcId"] = 84102,
            ["VoiceName"] = "voice/$Locale$/char/Zhiliu/vo_topic_03_3",
            },
        [90230305] = {
            ["Content"] = "今后的日子里，你又会给我带来怎样的意外？我可是拭目以待呢。",
            ["ContentKR"] = "앞으로 네가 또 어떤 놀라움을 보여줄지 기대하고 있어.",
            ["DialogueId"] = 90230305,
            ["GUID"] = "E1E1D16A",
            ["NextOptions"] = {
                [1] = 90230002,
                [2] = 90230003,
                },
            ["SpeakNpcId"] = 84102,
            ["VoiceName"] = "voice/$Locale$/char/Zhiliu/vo_topic_03_4",
            ["bForbidSkipOptions"] = true,
            },
        [90230401] = {
            ["Content"] = "嗯？这也被你注意到了。只是有些老毛病罢了。",
            ["ContentKR"] = "어? 눈치챘네. 그냥 오래된 버릇일 뿐이야.",
            ["DialogueId"] = 90230401,
            ["GUID"] = "E1E1E12A",
            ["LookAt"] = {
                [1] = "84102:n(0)",
                [2] = "0:n(84102)",
                },
            ["NextDialogue"] = 90230402,
            ["SpeakNpcId"] = 84102,
            ["VoiceName"] = "voice/$Locale$/char/Zhiliu/vo_topic_04_1",
            },
        [90230402] = {
            ["Content"] = "我年幼时，曾因一起意外，受困于山洞涧谷中，三天三夜不见天日。大约是从那时起落下的陋习。",
            ["ContentKR"] = "어릴 때, 한 번 사고로 산속 동굴에 갇힌 적이 있었는데, 사흘 밤낮을 햇빛도 못 봤어. 아마 그때부터 생긴 버릇인 것 같아.",
            ["DialogueId"] = 90230402,
            ["GUID"] = "E1E1E154",
            ["NextDialogue"] = 90230403,
            ["SpeakNpcId"] = 84102,
            ["VoiceName"] = "voice/$Locale$/char/Zhiliu/vo_topic_04_2",
            },
        [90230403] = {
            ["Content"] = "在这世间，为人皆有恐惧之物，我也不能幸免……看你的表情，这让你很惊讶吗？",
            ["ContentKR"] = "세상에 사람이라면 누구나 두려운 게 있잖아. 나도 예외는 아니지... 이게 조금 놀라운가?",
            ["DialogueId"] = 90230403,
            ["GUID"] = "E1E1E17E",
            ["NextDialogue"] = 90230404,
            ["SpeakNpcId"] = 84102,
            ["VoiceName"] = "voice/$Locale$/char/Zhiliu/vo_topic_04_3",
            },
        [90230404] = {
            ["Content"] = "只是觉得，你平时的形象好像没有弱点。",
            ["ContentKR"] = "그냥 평소에 약점이 없는 사람처럼 보여서요.",
            ["DialogueId"] = 90230404,
            ["GUID"] = "E1E1E1A8",
            ["NextDialogue"] = 90230405,
            ["SpeakNpcId"] = 100001,
            },
        [90230405] = {
            ["Content"] = "呵呵……没错。弱点只会成为商人的绊脚石。",
            ["ContentKR"] = "하하... 맞아. 약점은 상인에게 걸림돌이 되니까.",
            ["DialogueId"] = 90230405,
            ["GUID"] = "E1E1E1D2",
            ["NextDialogue"] = 90230406,
            ["SpeakNpcId"] = 84102,
            ["VoiceName"] = "voice/$Locale$/char/Zhiliu/vo_topic_04_4",
            },
        [90230406] = {
            ["Content"] = "我后来针对这点进行了严格的特训。若对面是谈判的对手，我可以随时将这份恐惧抛之脑后。只是在你面前，没有强装的必要罢了。",
            ["ContentKR"] = "그래서 나중에 이 점을 극복하려고 엄청난 훈련을 했어. 협상 상대라면 언제든 이 두려움을 떨쳐낼 수 있지. 다만, 네 앞에서는 굳이 강한 척하지 않아도 되니까.",
            ["DialogueId"] = 90230406,
            ["GUID"] = "E1E1E1FC",
            ["NextOptions"] = {
                [1] = 90230002,
                [2] = 90230003,
                },
            ["SpeakNpcId"] = 84102,
            ["VoiceName"] = "voice/$Locale$/char/Zhiliu/vo_topic_04_5",
            ["bForbidSkipOptions"] = true,
            },
        [90230501] = {
            ["Content"] = "你身上香水的味道，浓郁、热烈，散发出毫不克制的甜美。与华胥惯用香的疏淡却是有所不同。我很感兴趣。",
            ["ContentKR"] = "너한테서 나는 향수는 진하고 강렬하며, 절제되지 않은 달콤함이 느껴져. 화서에서 흔히 쓰는 은은한 향과는 확실히 다르네. 흥미로워.",
            ["DialogueId"] = 90230501,
            ["GUID"] = "E1E1F192",
            ["SpeakNpcId"] = 84102,
            ["VoiceName"] = "voice/$Locale$/char/Zhiliu/vo_companio_01",
            },
        [90230601] = {
            ["Content"] = "我在你身上看见了故人的影子……不，是我多言了。",
            ["ContentKR"] = "너한테서는 옛 지인의 모습이 겹쳐 보여... 아니다, 내가 괜한 말을 했네.",
            ["DialogueId"] = 90230601,
            ["GUID"] = "E1E201FA",
            ["SpeakNpcId"] = 84102,
            ["VoiceName"] = "voice/$Locale$/char/Zhiliu/vo_companio_03",
            },
        [90230701] = {
            ["Content"] = "许久未品过你亲手调的酒了。今日得空，可否再为我浅酌一杯午后小饮？",
            ["ContentKR"] = "네가 직접 만든 칵테일을 못 마신 지 오래됐네. 오늘 시간 되는데 한 잔 만들어 줄 수 있나?",
            ["DialogueId"] = 90230701,
            ["GUID"] = "E1E21262",
            ["SpeakNpcId"] = 84102,
            ["VoiceName"] = "voice/$Locale$/char/Zhiliu/vo_companio_04",
            },
        [90240000] = {
            ["Content"] = "这里很是亮堂又宽敞，就是桌椅板凳多了些，否则倒是演武对练的好地方。",
            ["ContentKR"] = "여긴 밝고 넓어서 수련하기 좋을 것 같군, 책상과 걸상들만 없었다면 말이야.",
            ["DialogueId"] = 90240000,
            ["GUID"] = "E1E80800",
            ["SpeakNpcId"] = 81503,
            ["VoiceName"] = "voice/$Locale$/char/Kezhou/vo_idle",
            },
        [90240001] = {
            ["Content"] = "今日宜饮酒纵歌，来来，待我饮完这杯，一起去诛尽那些应杀之人。什么？你说昨天我也是这样说的？那当然，一年三百六十日，日日都宜如此过活。",
            ["ContentKR"] = "술 마시며 노래하기 좋은 날이로구나. 자 자, 이 잔만 비우고, 죽어 마땅한 놈들을 처리하러 가자고. 뭐라? 내가 어제도 똑같은 말을 했다고? 당연하지. 일 년 삼백육십오 일, 매일을 오늘처럼 사니까.",
            ["DialogueId"] = 90240001,
            ["GUID"] = "E1E8082A",
            ["LookAt"] = {
                [1] = "81503:n(0)",
                [2] = "0:n(81503)",
                },
            ["NextOptions"] = {
                [1] = 902400011,
                [2] = 902400012,
                [3] = 902400013,
                [4] = 902400014,
                },
            ["RandomOptionNum"] = 3,
            ["SpeakNpcId"] = 81503,
            ["VoiceName"] = "voice/$Locale$/char/Kezhou/vo_welcome",
            ["bForbidSkipOptions"] = true,
            },
        [90240002] = {
            ["Content"] = "聊点别的",
            ["ContentKR"] = "다른 얘기를 하자",
            ["DialogueId"] = 90240002,
            ["GUID"] = "E1E80854",
            ["NextDialogue"] = 90240001,
            },
        [90240003] = {
            ["Content"] = "再见",
            ["ContentKR"] = "안녕",
            ["DialogueId"] = 90240003,
            ["GUID"] = "E1E8087E",
            },
        [90240101] = {
            ["Content"] = "怎么，你也对剑法感兴趣吗？是了，我看你也带着一把好剑，想必是有家传的功夫。比一比就知道啦。",
            ["ContentKR"] = "왜? 너도 검술에 뜻이 있는 것이냐? 그렇군, 너도 좋은 검을 가지고 있는 걸 보니, 가문의 검술을 익힌 모양이구나. 한번 겨뤄보면 알겠지.",
            ["DialogueId"] = 90240101,
            ["GUID"] = "E1E81892",
            ["LookAt"] = {
                [1] = "81503:n(0)",
                [2] = "0:n(81503)",
                },
            ["NextDialogue"] = 90240102,
            ["SpeakNpcId"] = 81503,
            ["TalkActionId"] = {
                [1] = "81503:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Kezhou/vo_topic_01_1",
            },
        [90240102] = {
            ["Content"] = "老实说，我已经很久没有遇到过势均力敌的对手了。但是按照我师父的说法，我个性太直，不会演戏，还需要继续磨练。",
            ["ContentKR"] = "솔직히 난 오랫동안 제대로 된 적수를 만나지 못했다. 그래도 사부님은 난 아직 멀었다고 하더군. 성격이 너무 우직해서 연기할 줄을 모른다면서 말이야.",
            ["DialogueId"] = 90240102,
            ["GUID"] = "E1E818BC",
            ["NextDialogue"] = 90240103,
            ["SpeakNpcId"] = 81503,
            ["TalkActionId"] = {
                [1] = "81503:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Kezhou/vo_topic_01_2",
            },
        [90240103] = {
            ["Content"] = "演技也是剑法的一种吗？",
            ["ContentKR"] = "연기도 검술의 일종이야?",
            ["DialogueId"] = 90240103,
            ["GUID"] = "E1E818E6",
            ["NextDialogue"] = 90240104,
            ["SpeakNpcId"] = 100001,
            },
        [90240104] = {
            ["Content"] = "其实我觉得不是，但是师父有说用剑需要会演：“能而示之不能”，和“不战而屈人之兵”、“以众击寡”一样，都是上等的剑法。",
            ["ContentKR"] = "사실 나는 그렇게 생각하지 않아. 하지만 사부님은 검술엔 연기도 필요하다고 하셨지. '능력이 있어도 없는듯 하는 것', 그리고 '싸우지 않고 굴복시키는 것', '많은 수로 적은 수를 치는 것'과 같은 건 전부 고급 검술이야.",
            ["DialogueId"] = 90240104,
            ["GUID"] = "E1E81910",
            ["NextDialogue"] = 90240105,
            ["SpeakNpcId"] = 81503,
            ["TalkActionId"] = {
                [1] = "81503:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Kezhou/vo_topic_01_3",
            },
        [90240105] = {
            ["Content"] = "我小的时候他就是这样对待我的，说自己本领稀松平常，只要把他打倒在地就可以不用练习之类的话。我试了一年，从没碰到过他的衣袖。",
            ["ContentKR"] = "내 어릴 적 사부님께서 날 꼭 그리 대하셨지. 자신의 재주가 뛰어나지 않으니, 자기를 바닥에 쓰러뜨리기만 하면 연습을 쉬게 해주겠다면서 말이야. 난 꼬박 일 년 동안이나 도전했지만, 옷깃도 한 번 스칠 수 없었어.",
            ["DialogueId"] = 90240105,
            ["GUID"] = "E1E8193A",
            ["NextDialogue"] = 90240106,
            ["SpeakNpcId"] = 81503,
            ["TalkActionId"] = {
                [1] = "81503:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Kezhou/vo_topic_01_4",
            },
        [90240106] = {
            ["Content"] = "直到有一天累到趴在地上，看他脚底下连一滴汗都没有。才确信他那副颠颠又倒倒的样子都是演的。",
            ["ContentKR"] = "그러던 어느 날, 지쳐서 바닥에 엎드렸는데 사부님의 발밑에 땀 한 방울도 떨어지지 않은 걸 보고서야 알았지. 그 비틀거리는 모습은 전부 연기였다는 걸 말이야.",
            ["DialogueId"] = 90240106,
            ["GUID"] = "E1E81964",
            ["NextOptions"] = {
                [1] = 90240002,
                [2] = 90240003,
                },
            ["SpeakNpcId"] = 81503,
            ["TalkActionId"] = {
                [1] = "81503:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Kezhou/vo_topic_01_5",
            ["bForbidSkipOptions"] = true,
            },
        [90240201] = {
            ["Content"] = "理由可以举出无数个，但是归根结底无非三个字：我不愿。",
            ["ContentKR"] = "이유야 수도 없이 많지. 하지만 근본적인 이유는 그저 세 글자다. 싫 어 서. ",
            ["DialogueId"] = 90240201,
            ["GUID"] = "E1E828FA",
            ["LookAt"] = {
                [1] = "81503:n(0)",
                [2] = "0:n(81503)",
                },
            ["NextDialogue"] = 90240202,
            ["SpeakNpcId"] = 81503,
            ["TalkActionId"] = {
                [1] = "81503:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Kezhou/vo_topic_02_1",
            },
        [90240202] = {
            ["Content"] = "从小逍遥自在惯了，只知道路见不平拔刀相助。师父和师兄的话我都只听爱听的，大半当作秋风过耳。又怎么会受什么律法的羁绊。",
            ["ContentKR"] = "어려서부터 자유로움에 익숙해져서 불의를 보면 검부터 뽑아 드는, 사부님과 선배의 말도 듣고 싶은 말만 듣고 반쯤은 한쪽 귀로 흘려보내는데, 어떻게 율법 같은 것에 얽매일 수가 있더냐.",
            ["DialogueId"] = 90240202,
            ["GUID"] = "E1E82924",
            ["NextDialogue"] = 90240203,
            ["SpeakNpcId"] = 81503,
            ["TalkActionId"] = {
                [1] = "81503:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Kezhou/vo_topic_02_2",
            },
        [90240203] = {
            ["Content"] = "那说一说最重要的理由吧。",
            ["ContentKR"] = "그럼 가장 중요한 이유 하나만 말해줘.",
            ["DialogueId"] = 90240203,
            ["GUID"] = "E1E8294E",
            ["NextDialogue"] = 90240204,
            ["SpeakNpcId"] = 100001,
            },
        [90240204] = {
            ["Content"] = "身为剑客的担忧吧：打个比方，习剑的基础是熟记图谱上的一招一式，面对一般的敌人时可以不用多加思索，顷刻间拔剑迎敌。",
            ["ContentKR"] = "검객으로서의 걱정이랄까... 예를 들어주마, 검을 익힐 때 기초가 되는 것은 비급에 적힌 초식을 하나하나 익히는 것이지. 외우고 나면 일반적인 적수는 깊이 생각할 필요도 없이 순식간에 검을 뽑아 상대할 수 있게 되지. ",
            ["DialogueId"] = 90240204,
            ["GUID"] = "E1E82978",
            ["NextDialogue"] = 90240205,
            ["SpeakNpcId"] = 81503,
            ["TalkActionId"] = {
                [1] = "81503:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Kezhou/vo_topic_02_3",
            },
        [90240205] = {
            ["Content"] = "但太过依赖图谱，不会随机应变，那手中的剑就会变成死剑、呆剑、傻瓜剑。面对未曾谋面的敌人就会方寸大乱，如同呆头鹅。",
            ["ContentKR"] = "하지만 비급에 과하게 의존하게 되면 융통성을 잃게 된다. 그러면 손에 쥔 검은 죽은 검, 미련한 검, 머저리 검이 되어버리지. 잘 모르는 적수를 만나게 되면 그저 허둥대는 멍청이가 될 뿐이야.",
            ["DialogueId"] = 90240205,
            ["GUID"] = "E1E829A2",
            ["NextDialogue"] = 90240206,
            ["SpeakNpcId"] = 81503,
            ["TalkActionId"] = {
                [1] = "81503:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Kezhou/vo_topic_02_4",
            },
        [90240206] = {
            ["Content"] = "在我看来，现在的华胥就是把《大风九章》翻烂的拙剑客，连像我这样的飘零人都斩不尽，要是遇到真正的强敌，是会败的。",
            ["ContentKR"] = "내가 보기에 지금의 화서는 〈대풍구장〉을 달달 외운 서투른 검객과 같아. 나 같은 나그네조차 제대로 처리하지 못하는데, 진정으로 강한 적을 마주치면 반드시 패할 거다.",
            ["DialogueId"] = 90240206,
            ["GUID"] = "E1E829CC",
            ["NextOptions"] = {
                [1] = 90240002,
                [2] = 90240003,
                },
            ["SpeakNpcId"] = 81503,
            ["VoiceName"] = "voice/$Locale$/char/Kezhou/vo_topic_02_5",
            ["bForbidSkipOptions"] = true,
            },
        [90240301] = {
            ["Content"] = "当然了，剑客的意思是擅长用剑，不是只会用剑。否则的话，华胥还有人能拿笔和筷子当做武器，那剑客岂不是不能写字吃饭？",
            ["ContentKR"] = "당연하지. 검객은 검을 잘 쓰는 사람인 거지 검만 쓰는 사람이 아니야. 화서에는 붓과 젓가락을 무기로 쓰는 사람도 있는데, 그럼 검객은 글도 못 쓰고 밥도 못 먹나?",
            ["DialogueId"] = 90240301,
            ["GUID"] = "E1E83962",
            ["LookAt"] = {
                [1] = "81503:n(0)",
                [2] = "0:n(81503)",
                },
            ["NextDialogue"] = 90240302,
            ["SpeakNpcId"] = 81503,
            ["TalkActionId"] = {
                [1] = "81503:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Kezhou/vo_topic_03_1",
            },
        [90240302] = {
            ["Content"] = "好遗憾，我还以为你真能做到用剑切开子弹。",
            ["ContentKR"] = "아쉽네. 난 각주가 정말 검으로 총알을 벨 수 있는 줄 알았어.",
            ["DialogueId"] = 90240302,
            ["GUID"] = "E1E8398C",
            ["NextDialogue"] = 90240303,
            ["SpeakNpcId"] = 100001,
            },
        [90240303] = {
            ["Content"] = "我能啊，但能这样做不代表必须这么做，躲开可要比硬接容易多了。山里的野猪都知道能吃萝卜的时候决不去啃树皮呢。",
            ["ContentKR"] = "벨 수 있어. 하지만 할 수 있다고 꼭 그래야만 하는 건 아니지. 피하는 게 받는 것보다 훨씬 쉬워. 산속에 사는 멧돼지도 당근이 있으면 절대 나무껍질을 안 먹잖아.",
            ["DialogueId"] = 90240303,
            ["GUID"] = "E1E839B6",
            ["NextDialogue"] = 90240304,
            ["SpeakNpcId"] = 81503,
            ["TalkActionId"] = {
                [1] = "81503:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Kezhou/vo_topic_03_2",
            },
        [90240304] = {
            ["Content"] = "当然，如果碰见能痛快打上一场的对手，我肯定会拔出剑来，全力以赴。",
            ["ContentKR"] = "물론, 시원하게 싸울 수 있는 적수를 만난다면, 반드시 검을 뽑고 전력으로 상대할 거야.",
            ["DialogueId"] = 90240304,
            ["GUID"] = "E1E839E0",
            ["NextOptions"] = {
                [1] = 90240002,
                [2] = 90240003,
                },
            ["SpeakNpcId"] = 81503,
            ["TalkActionId"] = {
                [1] = "81503:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Kezhou/vo_topic_03_3",
            ["bForbidSkipOptions"] = true,
            },
        [90240401] = {
            ["Content"] = "确实，你这么一问我能想到不少。啥啥一哥，什么王，某仙之类，用动物来做外号的尤其多，龙虎狮鹤，飞禽走兽都有，非常热闹。",
            ["ContentKR"] = "그렇지. 그러고 보니 떠오르는 게 꽤 있어. 무슨 형님이요. 왕이요. 또 무슨 신선도 있었지. 동물로 별호를 짓는 경우도 유독 많아. 용이며 호랑이, 사자, 학, 날고 긴다 하는 짐승들은 전부 갖다 써서 여간 요란한 게 아니더군.",
            ["DialogueId"] = 90240401,
            ["GUID"] = "E1E849CA",
            ["LookAt"] = {
                [1] = "81503:n(0)",
                [2] = "0:n(81503)",
                },
            ["NextDialogue"] = 90240402,
            ["SpeakNpcId"] = 81503,
            ["TalkActionId"] = {
                [1] = "81503:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Kezhou/vo_topic_04_1",
            },
        [90240402] = {
            ["Content"] = "然后这些外号啊，往往字数越长，功夫越差。四个字的一看就是刚入门，三个字的有头有脸，两个字，高手。至于没有外号的，那都是大宗师了。",
            ["ContentKR"] = "그리고 그 별호들 말이지, 보통은 글자 수가 많을수록 실력이 떨어지더군. 네 글자짜리는 안 봐도 갓 입문한 햇병아리고, 세 글자짜리는 좀 하는 양반, 두 글자짜리는 분명히 고수야. 별호가 없는 사람은 대가의 경지에 이른 사람들이지.",
            ["DialogueId"] = 90240402,
            ["GUID"] = "E1E849F4",
            ["NextDialogue"] = 90240403,
            ["SpeakNpcId"] = 81503,
            ["TalkActionId"] = {
                [1] = "81503:Angry01_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Kezhou/vo_topic_04_2",
            },
        [90240403] = {
            ["Content"] = "刻舟是真名还是外号？",
            ["ContentKR"] = "각주는 별호인가?",
            ["DialogueId"] = 90240403,
            ["GUID"] = "E1E84A1E",
            ["NextDialogue"] = 90240404,
            ["SpeakNpcId"] = 100001,
            },
        [90240404] = {
            ["Content"] = "行不更名坐不改姓，是真名。我知道你想说这个听起来像是外号。师父也这么说过，说是容易小小年纪就被当做高手，会吃亏。",
            ["ContentKR"] = "본명 그대로야. '각주'라는 이름이 별호처럼 들린다는 거 알아. 사부님도 그러셨지. 어린 나이에 고수 취급 받는 건 독이 된다면서.",
            ["DialogueId"] = 90240404,
            ["GUID"] = "E1E84A48",
            ["NextDialogue"] = 90240405,
            ["SpeakNpcId"] = 81503,
            ["TalkActionId"] = {
                [1] = "81503:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Kezhou/vo_topic_04_3",
            },
        [90240405] = {
            ["Content"] = "可毕竟这个名字是老爹给我起的，可能也是希望我成为一个侠客吧。他留下的东西不多，但只要这个名字还在，就总归证明他在世上还留有剑痕一道。",
            ["ContentKR"] = "그래도 아버지가 지어주신 이름인 걸 어쩌겠어. 아버지도 내가 협객이 되길 바라셨던 거겠지. 아버지가 남긴 물건은 딱히 없어도, 내 이름만으로도 그가 이 세상에 칼자국 하나 정도는 남기고 갔다는 걸 증명할 수 있잖아.",
            ["DialogueId"] = 90240405,
            ["GUID"] = "E1E84A72",
            ["NextOptions"] = {
                [1] = 90240002,
                [2] = 90240003,
                },
            ["SpeakNpcId"] = 81503,
            ["TalkActionId"] = {
                [1] = "81503:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Kezhou/vo_topic_04_4",
            ["bForbidSkipOptions"] = true,
            },
        [90240601] = {
            ["Content"] = "你的旧剑我先代为保管，等你什么时候不再紧锁着眉头哭丧着脸，我就还你。当然，得先比试一场，要是输了，这剑就当你送我了。",
            ["ContentKR"] = "당신이 쓰던 검은 내가 맡아둘게. 그 찌푸린 얼굴이랑 우울한 표정 좀 풀릴 때까지만이야. 물론 그 전에 먼저 한판 붙어봐야겠지. 만약 내가 이기면 이 검은 내가 가져가는 걸로 하고.",
            ["DialogueId"] = 90240601,
            ["GUID"] = "E1E86A9A",
            ["SpeakNpcId"] = 81503,
            ["VoiceName"] = "voice/$Locale$/char/Kezhou/vo_companio_02",
            },
        [90240701] = {
            ["Content"] = "剑可以是朋友，可以是玩物，甚至也可以是餐具、撬棍和剃须刀，但是唯独不可以是主人。希望你前行的旅途不要被这柄剑困住。",
            ["ContentKR"] = "검은 친구일 수도 있고, 장난감일 수도 있지. 심지어 식기나 지렛대, 면도칼이 될 수도 있어. 하지만 절대로, 검이 네 주인이 되게 두어선 안 돼. 네가 가는 길이 그 검에 가로막히지 않길 바라마.",
            ["DialogueId"] = 90240701,
            ["GUID"] = "E1E87B02",
            ["SpeakNpcId"] = 81503,
            ["VoiceName"] = "voice/$Locale$/char/Kezhou/vo_companio_03",
            },
        [90250000] = {
            ["Content"] = "萨麦尔，今天外面正艳阳高照呢，那我们吃点凉的怎么样？唔，听说圣都最近有一种叫“冰淇淋”的甜品，莉兹偷偷买给你吧！虽然是平民的食物，但肯定比那些老顽固给的餐点美味很多！",
            ["ContentKR"] = "사마엘, 오늘은 밖에 해가 쨍쨍한데, 우리 차가운 거 먹을까?\
아, 수도에 요즘 '아이스크림'이라는 디저트가 있는데, 몰래 사다 줄게! 평민들이 먹는 음식이긴 하지만, 그 꼰대들이 주는 것보다 훨씬 맛있을 거야!",
            ["DialogueId"] = 90250000,
            ["GUID"] = "E1EE70A0",
            ["SpeakNpcId"] = 81501,
            ["VoiceName"] = "voice/$Locale$/char/Baonu/vo_idle",
            },
        [90250001] = {
            ["Content"] = "你好啊，我在带着萨麦尔呼吸新鲜空气，熟悉这里的氛围和阳光，你要和它打招呼吗？它会很高兴的，嗯嗯，应该会的！",
            ["ContentKR"] = "안녕! 난 사마엘이랑 같이 신선한 공기를 마시면서, 여기 분위기랑 햇살에 익숙해지는 중이었어. 사마엘한테 인사해 볼래? 엄청 기뻐할 거야. 으음, 아마도!",
            ["DialogueId"] = 90250001,
            ["GUID"] = "E1EE70CA",
            ["LookAt"] = {
                [1] = "81501:n(0)",
                [2] = "0:n(81501)",
                },
            ["NextOptions"] = {
                [1] = 90250100,
                [2] = 90250200,
                [3] = 90250300,
                [4] = 90250400,
                },
            ["RandomOptionNum"] = 3,
            ["SpeakNpcId"] = 81501,
            ["VoiceName"] = "voice/$Locale$/char/Baonu/vo_welcome",
            ["bForbidSkipOptions"] = true,
            },
        [90250002] = {
            ["Content"] = "聊点别的",
            ["ContentKR"] = "다른 얘기를 하자",
            ["DialogueId"] = 90250002,
            ["GUID"] = "E1EE70F4",
            ["NextDialogue"] = 90250001,
            },
        [90250003] = {
            ["Content"] = "再见",
            ["ContentKR"] = "안녕",
            ["DialogueId"] = 90250003,
            ["GUID"] = "E1EE711E",
            },
        [90250100] = {
            ["Content"] = "你的兵器好像很厉害的样子……",
            ["ContentKR"] = "엄청 강해 보이는 무기네...",
            ["DialogueId"] = 90250100,
            ["GUID"] = "E1EE8108",
            ["NextDialogue"] = 90250101,
            },
        [90250101] = {
            ["Content"] = "萨麦尔可不是什么普通兵器，它是我最好的朋友！",
            ["ContentKR"] = "사마엘은 그냥 무기가 아니야. 내 가장 친한 친구라구!",
            ["DialogueId"] = 90250101,
            ["GUID"] = "E1EE8132",
            ["LookAt"] = {
                [1] = "81501:n(0)",
                [2] = "0:n(81501)",
                },
            ["NextDialogue"] = 90250102,
            ["SpeakNpcId"] = 81501,
            ["TalkActionId"] = {
                [1] = "81501:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Baonu/vo_topic_01_1",
            },
        [90250102] = {
            ["Content"] = "为什么莉兹贝尔会把一把剑当做朋友呢？",
            ["ContentKR"] = "왜 검을 친구라고 생각하는 거야?",
            ["DialogueId"] = 90250102,
            ["GUID"] = "E1EE815C",
            ["NextDialogue"] = 90250103,
            ["SpeakNpcId"] = 100001,
            },
        [90250103] = {
            ["Content"] = "在传颂会，只有被七件圣器选中的人才能成为“七美德”。当时有那么多那么多大力士，但只有我能拔出萨麦尔——既然它选择了我，我也一定会好好对待它的！",
            ["ContentKR"] = "교회에선 일곱 성물에게 선택받은 사람만이 '세븐 버튜스'가 될 수 있어. 힘센 사람이 그렇게 많았는데도, 그때 사마엘을 뽑을 수 있던 건 나뿐이었지. 사마엘이 날 선택해 준 거니까, 나도 사마엘을 소중히 대해 줄 거야!",
            ["DialogueId"] = 90250103,
            ["GUID"] = "E1EE8186",
            ["NextDialogue"] = 90250104,
            ["SpeakNpcId"] = 81501,
            ["VoiceName"] = "voice/$Locale$/char/Baonu/vo_topic_01_2",
            },
        [90250104] = {
            ["Content"] = "只是，虽然我拔出了它，但从那天开始，它就再也没有回应过我的呼唤了……等等，这是秘密，绝对不要说出去！",
            ["ContentKR"] = "그치만, 내가 자길 뽑은 그날부터 사마엘은 내 부름에 한 번도 답해 주지 않았어... 잠깐, 이건 비밀이니까 절대 소문내지 마!",
            ["DialogueId"] = 90250104,
            ["GUID"] = "E1EE81B0",
            ["NextDialogue"] = 90250105,
            ["SpeakNpcId"] = 81501,
            ["TalkActionId"] = {
                [1] = "81501:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Baonu/vo_topic_01_3",
            },
        [90250105] = {
            ["Content"] = "你天天往剑刃上抹奶油，它当然不会回应你。",
            ["ContentKR"] = "맨날 칼날에 크림을 바르니까, 당연히 대답을 안 해 주지.",
            ["DialogueId"] = 90250105,
            ["GUID"] = "E1EE81DA",
            ["NextDialogue"] = 90250106,
            ["SpeakNpcId"] = 100001,
            },
        [90250106] = {
            ["Content"] = "啊？难道它不喜欢冰淇淋？！那……土豆泥怎么样？沙拉酱呢？",
            ["ContentKR"] = "어? 사마엘은 아이스크림을 안 좋아하나?! 그럼... 으깬 감자는 어때? 마요네즈는?",
            ["DialogueId"] = 90250106,
            ["GUID"] = "E1EE8204",
            ["NextOptions"] = {
                [1] = 90250002,
                [2] = 90250003,
                },
            ["SpeakNpcId"] = 81501,
            ["TalkActionId"] = {
                [1] = "81501:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Baonu/vo_topic_01_4",
            ["bForbidSkipOptions"] = true,
            },
        [90250200] = {
            ["Content"] = "艾利西安传颂会的人对你怎么样？",
            ["ContentKR"] = "엘리시안 교회 사람들은 너한테 잘해줘?",
            ["DialogueId"] = 90250200,
            ["GUID"] = "E1EE9170",
            ["NextDialogue"] = 90250201,
            },
        [90250201] = {
            ["Content"] = "闭嘴闭嘴！别和我提那群老顽固！啊啊，真是的，好好的心情都被你……啊，我不能生气，不能生气……\
",
            ["ContentKR"] = "조용, 조용! 그 꼰대들 얘긴 꺼내지도 마! 아우, 진짜, 기분 좋았었는데, 너 때문에... 아, 난 화내면 안 되지. 화내면 안 돼...",
            ["DialogueId"] = 90250201,
            ["GUID"] = "E1EE919A",
            ["LookAt"] = {
                [1] = "81501:n(0)",
                [2] = "0:n(81501)",
                },
            ["NextDialogue"] = 90250202,
            ["SpeakNpcId"] = 81501,
            ["TalkActionId"] = {
                [1] = "81501:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Baonu/vo_topic_02_1",
            },
        [90250202] = {
            ["Content"] = "听起来你对他们意见很大啊……",
            ["ContentKR"] = "교회 사람들한테 불만이 많은가 보네...",
            ["DialogueId"] = 90250202,
            ["GUID"] = "E1EE91C4",
            ["NextDialogue"] = 90250203,
            ["SpeakNpcId"] = 100001,
            },
        [90250203] = {
            ["Content"] = "咳咳，才没有呢！司祭们人都好棒的，一个个都特别和蔼可亲的。背错的经文只需要抄三十遍，喂萨麦尔吃奶油被发现也只要面壁思过两天就行了，超喜欢大家的。",
            ["ContentKR"] = "크흠, 아니거든! 사제님들은 다 좋은 분들이야. 다들 굉장히 친절하고 자상하셔. 경전 내용을 잘못 외워도 딱 30번만 베껴 쓰면 되고, 사마엘한테 크림 먹이다 들켜도 딱 이틀만 벽 보고 반성하면 되거든. 난 모두를 아주아주 좋아해.",
            ["DialogueId"] = 90250203,
            ["GUID"] = "E1EE91EE",
            ["NextOptions"] = {
                [1] = 90250002,
                [2] = 90250003,
                },
            ["SpeakNpcId"] = 81501,
            ["TalkActionId"] = {
                [1] = "81501:Angry01_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Baonu/vo_topic_02_2",
            ["bForbidSkipOptions"] = true,
            },
        [90250300] = {
            ["Content"] = "“坚忍”意味着什么？",
            ["ContentKR"] = "'인내'는 뭘 의미하는 거야?",
            ["DialogueId"] = 90250300,
            ["GUID"] = "E1EEA1D8",
            ["NextDialogue"] = 90250301,
            },
        [90250301] = {
            ["Content"] = "就是字面意思啊，“坚忍”就是要坚定、要忍耐，无论遇到什么事都不能生气！",
            ["ContentKR"] = "당연히 '인내'지. 무슨 일이 있어도, 꿋꿋하게 참고 화내지 않는 거!",
            ["DialogueId"] = 90250301,
            ["GUID"] = "E1EEA202",
            ["LookAt"] = {
                [1] = "81501:n(0)",
                [2] = "0:n(81501)",
                },
            ["NextDialogue"] = 90250302,
            ["SpeakNpcId"] = 81501,
            ["TalkActionId"] = {
                [1] = "81501:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Baonu/vo_topic_03_1",
            },
        [90250302] = {
            ["Content"] = "那也太难了吧……",
            ["ContentKR"] = "그러기 쉽지 않을 것 같은데...",
            ["DialogueId"] = 90250302,
            ["GUID"] = "E1EEA22C",
            ["NextDialogue"] = 90250303,
            ["SpeakNpcId"] = 100001,
            },
        [90250303] = {
            ["Content"] = "可不是嘛……因为这个称号，我总是被教导要用忍耐去对抗愤怒。可这就像是打哈欠打到一半被人搭话，又或是举剑后被告知眼前的敌人并非敌人而是同伴一样。总之就是，反而会让人更加生……",
            ["ContentKR"] = "내 말이... 난 이 칭호 때문에 항상 인내심으로 분노를 이겨내라고 배웠어. 근데 그건 하품하는 중에 누가 딱 말 거는 느낌이야. 검을 딱 들었는데 눈앞의 상대가 적이 아니라 아군이었단 소릴 들은 느낌이기도 하고. 아무튼, 오히려 더 화만 나는...",
            ["DialogueId"] = 90250303,
            ["GUID"] = "E1EEA256",
            ["NextDialogue"] = 90250304,
            ["SpeakNpcId"] = 81501,
            ["VoiceName"] = "voice/$Locale$/char/Baonu/vo_topic_03_2",
            },
        [90250304] = {
            ["Content"] = "唔，他们说愤怒是很大的罪恶，我不能生气，不能生气……",
            ["ContentKR"] = "으, 교회에선 분노가 큰 죄악이라고 했어. 난 화내면 안 돼, 화내면 안 돼...",
            ["DialogueId"] = 90250304,
            ["GUID"] = "E1EEA280",
            ["NextDialogue"] = 90250305,
            ["SpeakNpcId"] = 81501,
            ["TalkActionId"] = {
                [1] = "81501:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Baonu/vo_topic_03_3",
            },
        [90250305] = {
            ["Content"] = "真是辛苦你了。",
            ["ContentKR"] = "많이 힘들겠구나.",
            ["DialogueId"] = 90250305,
            ["GUID"] = "E1EEA2AA",
            ["NextDialogue"] = 90250306,
            ["SpeakNpcId"] = 100001,
            },
        [90250306] = {
            ["Content"] = "哼哼，谁叫我是“坚忍”大人呢！",
            ["ContentKR"] = "후훗, 내가 괜히 '인내'의 리사벨 님일까봐!",
            ["DialogueId"] = 90250306,
            ["GUID"] = "E1EEA2D4",
            ["NextOptions"] = {
                [1] = 90250002,
                [2] = 90250003,
                },
            ["SpeakNpcId"] = 81501,
            ["TalkActionId"] = {
                [1] = "81501:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Baonu/vo_topic_03_4",
            ["bForbidSkipOptions"] = true,
            },
        [90250400] = {
            ["Content"] = "“七美德”是什么?",
            ["ContentKR"] = "'세븐 버튜스'가 뭐야?",
            ["DialogueId"] = 90250400,
            ["GUID"] = "E1EEB240",
            ["NextDialogue"] = 90250401,
            },
        [90250401] = {
            ["Content"] = "“七美德”是艾利西安最威风，最高贵，最强大帅气的七个人。当然，顾名思义，也是美德最丰沛的七个人啦。",
            ["ContentKR"] = "'세븐 버튜스'는 엘리시안에서 가장 늠름하고, 고귀하고, 강하면서 멋진 일곱 명을 말해. 물론, 일곱 덕목이란 이름답게 최고의 덕목을 갖춘 7명이란 의미이기도 하지, 헤헷!",
            ["DialogueId"] = 90250401,
            ["GUID"] = "E1EEB26A",
            ["LookAt"] = {
                [1] = "81501:n(0)",
                [2] = "0:n(81501)",
                },
            ["NextDialogue"] = 90250402,
            ["SpeakNpcId"] = 81501,
            ["TalkActionId"] = {
                [1] = "81501:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Baonu/vo_topic_04_1",
            },
        [90250402] = {
            ["Content"] = "呃……",
            ["ContentKR"] = "음...",
            ["DialogueId"] = 90250402,
            ["GUID"] = "E1EEB294",
            ["NextDialogue"] = 90250403,
            ["SpeakNpcId"] = 100001,
            },
        [90250403] = {
            ["Content"] = "你那是什么表情……真是放肆！竟然敢质疑本大人，我要罚你抄写戒律三十……不，一百遍！",
            ["ContentKR"] = "뭐야, 그 표정은... 진짜 무례하네! 감히 이 리사벨 님을 의심해? 계율 깜지 쓰기 30번... 아니, 100번에 처한다!",
            ["DialogueId"] = 90250403,
            ["GUID"] = "E1EEB2BE",
            ["NextOptions"] = {
                [1] = 90250002,
                [2] = 90250003,
                },
            ["SpeakNpcId"] = 81501,
            ["TalkActionId"] = {
                [1] = "81501:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Baonu/vo_topic_04_2",
            ["bForbidSkipOptions"] = true,
            },
        [90250601] = {
            ["Content"] = "“坚忍，是七大美德之一……心中常存忍耐，就能够见到常人不能见的，行世人难以……难以……”\
啊啊啊不行受不了啦！小矮子你再在那里模仿本大人的样子本大人就要忍不住拿萨麦尔切水产了我以九神之名发誓真的会做到的！！",
            ["ContentKR"] = "인내, 세븐 버튜스 중 하나... 항상 마음속에 인내를 가지고 있으면 일반인이 볼 수 없는 것을 볼 수 있고, 세상 사람들이 못... 못...\
아아아 도저히 못 참겠어! 꼬맹이 너 또 이 몸을 흉내 내면 이 몸이 사마엘로 오징어인지 문어인지 같은 모습을 베어버릴 거야. 아홉 신의 이름으로 맹세하는데, 정말 베어버릴 거라고!!",
            ["DialogueId"] = 90250601,
            ["GUID"] = "E1EED33A",
            ["SpeakNpcId"] = 81501,
            ["VoiceName"] = "voice/$Locale$/char/Baonu/vo_companio_02",
            },
        [90250701] = {
            ["Content"] = "抹奶油？怎么啦。我们艾利西安人就是这样保养武器的，有什么意见吗？",
            ["ContentKR"] = "크림 바르는 게 왜? 우리 엘리시안 사람은 이렇게 무기를 관리해. 무슨 불만이라도?",
            ["DialogueId"] = 90250701,
            ["GUID"] = "E1EEE3A2",
            ["SpeakNpcId"] = 81501,
            ["VoiceName"] = "voice/$Locale$/char/Baonu/vo_companio_03",
            },
        [90260000] = {
            ["Content"] = "你一个人在外面……没有我真的可以吗？",
            ["ContentKR"] = "밖에서 혼자 돌아다니는 거... 진짜 나 없이도 괜찮겠어?(걱정스러운 듯이)",
            ["DialogueId"] = 90260000,
            ["GUID"] = "E1F4D940",
            ["SpeakNpcId"] = 81504,
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_idle",
            },
        [90260001] = {
            ["Content"] = "你来啦！是不是听说我又重新改装了青鸾贰型，给你看——咦，你只是来找我闲聊的？",
            ["ContentKR"] = "잘 왔어! 내가 난새 2호 새로 개조했다는 거 들었구나! 자, 봐봐... 어? 그냥 나랑 얘기하러 온 거야?(친근한 말투로 빠르게 말하다가 깜짝 놀라며)",
            ["DialogueId"] = 90260001,
            ["GUID"] = "E1F4D96A",
            ["LookAt"] = {
                [1] = "81504:n(0)",
                [2] = "0:n(81504)",
                },
            ["NextOptions"] = {
                [1] = 90260100,
                [2] = 90260200,
                [3] = 90260300,
                [4] = 90260400,
                },
            ["RandomOptionNum"] = 3,
            ["SpeakNpcId"] = 81504,
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_welcome",
            ["bForbidSkipOptions"] = true,
            },
        [90260002] = {
            ["Content"] = "聊点别的",
            ["ContentKR"] = "다른 이야기를 하자",
            ["DialogueId"] = 90260002,
            ["GUID"] = "E1F4D994",
            ["NextDialogue"] = 90260001,
            },
        [90260003] = {
            ["Content"] = "再见",
            ["ContentKR"] = "안녕",
            ["DialogueId"] = 90260003,
            ["GUID"] = "E1F4D9BE",
            },
        [90260100] = {
            ["Content"] = "闲暇时喜欢做什么？",
            ["ContentKR"] = "한가할 때는 주로 뭐 해?",
            ["DialogueId"] = 90260100,
            ["GUID"] = "E1F4E9A8",
            ["NextDialogue"] = 90260101,
            },
        [90260101] = {
            ["Content"] = "拼机枢，打磨齿轮，寻找新材料，研发更好用的东西。",
            ["ContentKR"] = "기추 장치 조립하고, 톱니바퀴 손질하고, 새로운 재료를 찾아다녀. 더 좋은 걸 만들려고 연구하는 거지.(진지하게 생각한 후, 읊조리듯 대답하며)",
            ["DialogueId"] = 90260101,
            ["GUID"] = "E1F4E9D2",
            ["LookAt"] = {
                [1] = "81504:n(0)",
                [2] = "0:n(81504)",
                },
            ["NextDialogue"] = 90260102,
            ["SpeakNpcId"] = 81504,
            ["TalkActionId"] = {
                [1] = "81504:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_topic_01_1",
            },
        [90260102] = {
            ["Content"] = "上次唐叔不是腿摔了吗？刚好最近有空，我就一直在研究能够更平稳升空的载具。机枢派弟子总是要成果不要命，可不能放任这样的风气延续下去！",
            ["ContentKR"] = "저번에 당씨 아저씨가 다리 다치셨잖아? 마침 요즘 좀 시간이 나길래, 더 부드럽게 이륙하는 비행 장치를 연구 중이야. 기추파 사람들은 결과만 좋다면 자기 몸이야 어떻게 되든 신경 안 쓰는데, 그렇게 놔 두면 절대 안 돼! (생각에 잠긴 채 말하다가, 걱정스럽다는 듯)",
            ["DialogueId"] = 90260102,
            ["GUID"] = "E1F4E9FC",
            ["NextDialogue"] = 90260103,
            ["SpeakNpcId"] = 81504,
            ["TalkActionId"] = {
                [1] = "81504:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_topic_01_2",
            },
        [90260103] = {
            ["Content"] = "一直工作不累吗？",
            ["ContentKR"] = "계속 일하면 피곤하지 않아?",
            ["DialogueId"] = 90260103,
            ["GUID"] = "E1F4EA26",
            ["NextDialogue"] = 90260104,
            ["SpeakNpcId"] = 100001,
            },
        [90260104] = {
            ["Content"] = "怎么会累？世上还有比工作最有趣的事吗？你只需要在脑海中把机枢拆解成一个个组件，再在现实中拼起来就好。这简直是最享受的时刻啦。",
            ["ContentKR"] = "으응? 그럴 리가? 일하는 게 세상에서 제일 재미있는걸! 그냥 머릿속으로 장치를 하나하나 분해한 다음에, 손으로 딱딱 조립만 하면 돼. 나한텐 제일 즐거운 순간이야. (진지하면서도 경쾌하게)",
            ["DialogueId"] = 90260104,
            ["GUID"] = "E1F4EA50",
            ["NextDialogue"] = 90260105,
            ["SpeakNpcId"] = 81504,
            ["TalkActionId"] = {
                [1] = "81504:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_topic_01_3",
            },
        [90260105] = {
            ["Content"] = "你要不要也试试？全山外山最厉害的机枢大师现在有空，可以手把手教你哦。",
            ["ContentKR"] = "한번 해 볼래? 산외산 최고의 기추 장인이 때마침 좀 한가하거든. 일대일로 가르쳐 줄게! (우쭐대며)",
            ["DialogueId"] = 90260105,
            ["GUID"] = "E1F4EA7A",
            ["NextOptions"] = {
                [1] = 90260002,
                [2] = 90260003,
                },
            ["SpeakNpcId"] = 81504,
            ["TalkActionId"] = {
                [1] = "81504:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_topic_01_4",
            ["bForbidSkipOptions"] = true,
            },
        [90260200] = {
            ["Content"] = "你之前说过自己辈分高，是什么意思？",
            ["ContentKR"] = "전에 넌 항렬이 높은 거라고 했잖아. 그게 무슨 말이야?",
            ["DialogueId"] = 90260200,
            ["GUID"] = "E1F4FA10",
            ["NextDialogue"] = 90260201,
            },
        [90260201] = {
            ["Content"] = "机枢派和飘零人都讲究世代传承。比方说，一个九十岁的老师父，收了一个十岁的孩子当关门弟子，那么门派里很多四十多岁的中年人都要管这个孩子叫师叔。",
            ["ContentKR"] = "기추파나 나그네나 족보를 엄청 따지거든. 만약에 스승님이 아흔 살인데, 열 살짜리를 직계 제자로 받아 버리면, 그 문파 사람들은 마흔이 넘었다고 해도, 걔를 사숙이라고 불러야 해.(진지하게 설명하며)",
            ["DialogueId"] = 90260201,
            ["GUID"] = "E1F4FA3A",
            ["LookAt"] = {
                [1] = "81504:n(0)",
                [2] = "0:n(81504)",
                },
            ["NextDialogue"] = 90260202,
            ["SpeakNpcId"] = 81504,
            ["TalkActionId"] = {
                [1] = "81504:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_topic_02_1",
            },
        [90260202] = {
            ["Content"] = "我比较幸运，我的老师——也就是我的姑姑，她辈分很高，所以我的辈分自然也很高啦。",
            ["ContentKR"] = "난 운이 좋아서, 내 스승님... 그러니까 우리 고모가 왕고참이었거든. 덕분에 나까지 고참이 된 거지.(해맑게 설명하며)",
            ["DialogueId"] = 90260202,
            ["GUID"] = "E1F4FA64",
            ["NextDialogue"] = 90260203,
            ["SpeakNpcId"] = 81504,
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_topic_02_2",
            },
        [90260203] = {
            ["Content"] = "刻舟就比较不幸，他师父宴山亭辈分低，所以论起排辈啊，他得管我叫姑奶奶~",
            ["ContentKR"] = "각주는 운이 좀 없는 편이야. 걔 스승인 연산정이 항렬이 낮거든. 그래서 족보로 따지면, 나한테 고모할머니라고 불러야 해~(경쾌하고 의기양양하게)",
            ["DialogueId"] = 90260203,
            ["GUID"] = "E1F4FA8E",
            ["NextDialogue"] = 90260204,
            ["SpeakNpcId"] = 81504,
            ["TalkActionId"] = {
                [1] = "81504:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_topic_02_3",
            },
        [90260204] = {
            ["Content"] = "那我呢那我呢？",
            ["ContentKR"] = "그럼 난? 난 어떻게 되는 거야?",
            ["DialogueId"] = 90260204,
            ["GUID"] = "E1F4FAB8",
            ["NextDialogue"] = 90260205,
            ["SpeakNpcId"] = 100001,
            },
        [90260205] = {
            ["Content"] = "公尚先生的辈分也是很高的哦。让我换算一下……巧了，你和我算是同辈呢！",
            ["ContentKR"] = "공상 사부도 항렬이 되게 높으셔. 잠깐 계산해 볼게... 와! 너 나랑 항렬이 똑같다!(곰곰이 생각하다가 경쾌하게)",
            ["DialogueId"] = 90260205,
            ["GUID"] = "E1F4FAE2",
            ["NextDialogue"] = 90260206,
            ["SpeakNpcId"] = 81504,
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_topic_02_4",
            },
        [90260206] = {
            ["Content"] = "嘻嘻，如果以后刻舟那家伙对你耍贫嘴，你就可以尽情让他管你喊{性别：爷爷|奶奶}了。",
            ["ContentKR"] = "후후, 그러니까 나중에 각주가 너한테 깐족대면, 당당하게 {性别:할아버지|할머니}라고 부르라고 해.(우쭐해하며 장난치듯 경쾌하게)",
            ["DialogueId"] = 90260206,
            ["GUID"] = "E1F4FB0C",
            ["NextDialogue"] = 90260207,
            ["SpeakNpcId"] = 81504,
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_topic_02_5",
            },
        [90260207] = {
            ["Content"] = "等等，我记得你是白的小仆从来着……意思是她是你师父？……天啊，难道我们中辈分最高的其实是一个小不点吗？！",
            ["ContentKR"] = "어라, 근데 넌 스노우의 시종이라며... 그럼 걔가 네 스승인 거야? ...말도 안 돼. 그 꼬맹이가 우리 중에서 항렬이 제일 높다고?!(경악하며)",
            ["DialogueId"] = 90260207,
            ["GUID"] = "E1F4FB36",
            ["NextOptions"] = {
                [1] = 90260002,
                [2] = 90260003,
                },
            ["SpeakNpcId"] = 81504,
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_topic_02_6",
            ["bForbidSkipOptions"] = true,
            },
        [90260300] = {
            ["Content"] = "说起来，最近经常在你身边见到一只小鸟。",
            ["ContentKR"] = "참, 요즘 작은 새 하나가 너랑 같이 다니는 것 같던데.",
            ["DialogueId"] = 90260300,
            ["GUID"] = "E1F50A78",
            ["NextDialogue"] = 90260301,
            },
        [90260301] = {
            ["Content"] = "哦，那是青鸾叁型，我最新的宠物！",
            ["ContentKR"] = "아, 난새 3호 말이구나! 내 최신형 애완동물이야!(뿌듯하게 소개하며)",
            ["DialogueId"] = 90260301,
            ["GUID"] = "E1F50AA2",
            ["LookAt"] = {
                [1] = "81504:n(0)",
                [2] = "0:n(81504)",
                },
            ["NextDialogue"] = 90260302,
            ["SpeakNpcId"] = 81504,
            ["TalkActionId"] = {
                [1] = "81504:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_topic_03_1",
            },
        [90260302] = {
            ["Content"] = "你看，是不是很像是真的云翎鸥？我简化了发动流程，长按头顶，它就能开启拟态飞行模式了。说到飞行——",
            ["ContentKR"] = "짜잔, 운령구랑 똑같이 생겼지? 조작을 단순화해서, 머리만 꾹 누르면, 비행 시뮬레이션 모드를 시작하게 만들었어. 비행 얘기가 나와서 말인데...(입에 침이 마르도록 자랑을 늘어놓으며)",
            ["DialogueId"] = 90260302,
            ["GUID"] = "E1F50ACC",
            ["NextDialogue"] = 90260303,
            ["SpeakNpcId"] = 81504,
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_topic_03_2",
            },
        [90260303] = {
            ["Content"] = "这羽毛也是有学问的！我回收了云翎鸥自然掉落的羽毛，用了改良版的离水技艺给羽毛封层，几乎不会增加重量。",
            ["ContentKR"] = "이 깃털도 그냥 깃털이 아냐! 운령구가 떨어뜨린 깃털을 주워서, 더 강화된 발수 코팅을 입혔거든! 근데 무게는 거의 그대로야.(입에 침이 마르도록 자랑을 늘어놓으며)",
            ["DialogueId"] = 90260303,
            ["GUID"] = "E1F50AF6",
            ["NextDialogue"] = 90260304,
            ["SpeakNpcId"] = 81504,
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_topic_03_3",
            },
        [90260304] = {
            ["Content"] = "不会掉色，永远毛茸茸，也不是飞天老虎钳，情绪价值拉满，完美的宠物。",
            ["ContentKR"] = "색 바랠 걱정도 없고, 늘 폭신폭신해. 물거나 할퀴지도 않고, 정서적인 안정감까지 주는 완벽한 애완동물이라는 거지!(입에 침이 마르도록 자랑을 늘어놓으며)",
            ["DialogueId"] = 90260304,
            ["GUID"] = "E1F50B20",
            ["NextDialogue"] = 90260305,
            ["SpeakNpcId"] = 81504,
            ["TalkActionId"] = {
                [1] = "81504:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_topic_03_4",
            },
        [90260305] = {
            ["Content"] = "为什么不养只真的？",
            ["ContentKR"] = "진짜 새는 안 키워?",
            ["DialogueId"] = 90260305,
            ["GUID"] = "E1F50B4A",
            ["NextDialogue"] = 90260306,
            ["SpeakNpcId"] = 100001,
            },
        [90260306] = {
            ["Content"] = "云翎鸥是喜欢天空的鸟儿，如果要养，就只能关在笼子里。可是如果我只是为了一饱眼福就把它捉来，那我和昔日的悬衡派有什么区别？",
            ["ContentKR"] = "운령구는 하늘을 좋아하는 새인걸. 데려다 키우려면 새장에 가둬야 하는데, 나 하나 즐겁자고 자유를 뺏는다면, 그 옛날 현형파랑 다를 게 없잖아?(진지하게)",
            ["DialogueId"] = 90260306,
            ["GUID"] = "E1F50B74",
            ["NextDialogue"] = 90260307,
            ["SpeakNpcId"] = 81504,
            ["TalkActionId"] = {
                [1] = "81504:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_topic_03_5",
            },
        [90260307] = {
            ["Content"] = "有些动物适合伴人左右，但云翎鸥显然不在此列。它尖尖的喙，长长的尾，适应风阻的双翼，足以证明——它属于天空，而并非某人的掌心。",
            ["ContentKR"] = "사람 곁을 좋아하는 동물들도 있지만, 운령구는 아니야. 저 날렵한 부리와 기다란 꼬리, 그리고 바람을 가르는 두 날개는... 누군가의 손아귀가 아니라, 하늘을 누비라고 있는 거니까.(진지하게)",
            ["DialogueId"] = 90260307,
            ["GUID"] = "E1F50B9E",
            ["NextOptions"] = {
                [1] = 90260002,
                [2] = 90260003,
                },
            ["SpeakNpcId"] = 81504,
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_topic_03_6",
            ["bForbidSkipOptions"] = true,
            },
        [90260400] = {
            ["Content"] = "山外山是个怎样的地方？",
            ["ContentKR"] = "산외산은 어떤 곳이야?",
            ["DialogueId"] = 90260400,
            ["GUID"] = "E1F51AE0",
            ["NextDialogue"] = 90260401,
            },
        [90260401] = {
            ["Content"] = "山外山啊……嗯，好问题。",
            ["ContentKR"] = "산외산은 말이지... 음, 좋은 질문이야.(생각에 잠겨 진지하게)",
            ["DialogueId"] = 90260401,
            ["GUID"] = "E1F51B0A",
            ["LookAt"] = {
                [1] = "81504:n(0)",
                [2] = "0:n(81504)",
                },
            ["NextDialogue"] = 90260402,
            ["SpeakNpcId"] = 81504,
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_topic_04_1",
            },
        [90260402] = {
            ["Content"] = "我们因为相似的处境而集结起来，为了相同的目标而努力着，能够互相理解、彼此信任，战斗时交托后背，疲惫时携手同行……是个很好很好的地方。",
            ["ContentKR"] = "비슷한 처지끼리 모여서, 같은 목표를 향해 노력하는 곳이야. 서로 이해해 주고, 믿어 주고, 싸울 땐 등을 맡기기도 하고, 힘들 땐 기대기도 하는... 정말 멋진 곳이지.(진지하게)",
            ["DialogueId"] = 90260402,
            ["GUID"] = "E1F51B34",
            ["NextDialogue"] = 90260403,
            ["SpeakNpcId"] = 81504,
            ["TalkActionId"] = {
                [1] = "81504:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_topic_04_2",
            },
        [90260403] = {
            ["Content"] = "对于山外山的很多人来说，这里就像是家一样。",
            ["ContentKR"] = "많은 사람에게 산외산은, 집이나 마찬가지야.(진지하게)",
            ["DialogueId"] = 90260403,
            ["GUID"] = "E1F51B5E",
            ["NextDialogue"] = 90260404,
            ["SpeakNpcId"] = 81504,
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_topic_04_3",
            },
        [90260404] = {
            ["Content"] = "这也是你的家吗？",
            ["ContentKR"] = "너한테도 그래?",
            ["DialogueId"] = 90260404,
            ["GUID"] = "E1F51B88",
            ["NextDialogue"] = 90260405,
            ["SpeakNpcId"] = 100001,
            },
        [90260405] = {
            ["Content"] = "这……当然也是我家了！",
            ["ContentKR"] = "그야... 물론이지!(잠시 머뭇거리다가, 급히 긍정하며)",
            ["DialogueId"] = 90260405,
            ["GUID"] = "E1F51BB2",
            ["NextDialogue"] = 90260406,
            ["SpeakNpcId"] = 81504,
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_topic_04_4",
            },
        [90260406] = {
            ["Content"] = "你好像不太对劲，怎么了？",
            ["ContentKR"] = "반응이 좀 애매한데, 왜 그래?",
            ["DialogueId"] = 90260406,
            ["GUID"] = "E1F51BDC",
            ["NextDialogue"] = 90260407,
            ["SpeakNpcId"] = 100001,
            },
        [90260407] = {
            ["Content"] = "好敏锐啊，这就是雇佣兵……不对不对，狩月人的直觉？不只是战斗，接人待物也有用？要是我的机傀探测导航装置，也能和你一样灵活就好了。",
            ["ContentKR"] = "감이 좋네. 역시 용병... 아니, 월석 사냥꾼의 직감인가? 전투 말고, 사람 상대할 때도 유용하겠는데? 내 기계 꼭두각시의 탐지 장치도 네 감만큼 예리하면 좋겠다.(감탄하며)",
            ["DialogueId"] = 90260407,
            ["GUID"] = "E1F51C06",
            ["NextDialogue"] = 90260408,
            ["SpeakNpcId"] = 81504,
            ["TalkActionId"] = {
                [1] = "81504:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_topic_04_5",
            },
        [90260408] = {
            ["Content"] = "我只是有点迷茫……家应该是一个什么样的地方？",
            ["ContentKR"] = "그냥, 좀 헷갈려서... 집이란 건, 대체 어떤 곳인 걸까?(아무것도 떠오르지 않는 듯)",
            ["DialogueId"] = 90260408,
            ["GUID"] = "E1F51C30",
            ["NextDialogue"] = 90260409,
            ["SpeakNpcId"] = 81504,
            ["TalkActionId"] = {
                [1] = "81504:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_topic_04_6",
            },
        [90260409] = {
            ["Content"] = "那是，不管多远都要回去的地方。",
            ["ContentKR"] = "집은, 아무리 멀리 있어도 꼭 돌아가야만 하는 곳이야.",
            ["DialogueId"] = 90260409,
            ["GUID"] = "E1F51C5A",
            ["NextDialogue"] = 90260410,
            ["SpeakNpcId"] = 100001,
            },
        [90260410] = {
            ["Content"] = "那……回不去的地方，还算是家吗？……抱歉，让你听了奇怪的话，还是当我没说过吧！",
            ["ContentKR"] = "그럼... 돌아갈 수 없는 곳도 집이라고 할 수 있을까? ...미안, 이상한 소릴 해 버렸네. 그냥 못 들은 걸로 해 줘!(멍하고 힘없이 중얼거리듯 이야기하다가, 후반부에서는 다급하게)",
            ["DialogueId"] = 90260410,
            ["GUID"] = "E1F51C84",
            ["NextOptions"] = {
                [1] = 90260002,
                [2] = 90260003,
                },
            ["SpeakNpcId"] = 81504,
            ["TalkActionId"] = {
                [1] = "81504:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_topic_04_7",
            ["bForbidSkipOptions"] = true,
            },
        [90260501] = {
            ["Content"] = "卢卡人都这么开放吗，说话没有三两句，就要拥抱了。不、不行！现在还不可以！",
            ["ContentKR"] = "루카 공화국 사람들은 다 그렇게 개방적이야? 말 몇 마디 했다고 덥석 껴안으려고 하다니. 아, 안 돼! 아직은 안 된다니까!(작은 목소리로 투덜거리다가 거절하며)",
            ["DialogueId"] = 90260501,
            ["GUID"] = "E1F52B72",
            ["SpeakNpcId"] = 81504,
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_companio_01",
            },
        [90260601] = {
            ["Content"] = "又要买新剑？！……我们山外山的预算有那么充足吗？不买！跪下求也没用！喊姑奶奶也不行！这次我绝对不会被你说动了！",
            ["ContentKR"] = "검을 또 사겠다고?! ...우리 산외산에 예산이 남아나는 줄 알아? 안 돼! 무릎 꿇어도 소용없어! 고모할머니라고 불러도 안 사 줄 거야! 이번엔 절대 안 넘어가!(딱 잘라 반대하면서도, 다정하게 투덜거리며)",
            ["DialogueId"] = 90260601,
            ["GUID"] = "E1F53BDA",
            ["SpeakNpcId"] = 81504,
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_companio_02",
            },
        [90260701] = {
            ["Content"] = "你的翅膀……真漂亮，不过我的也不差。要不要来比比谁飞得快？",
            ["ContentKR"] = "날개... 예쁘다. 근데 내 날개도 꽤 멋져. 우리 누가 더 빨리 나는지 시합해 볼래?(칭찬하면서도 한 번 겨뤄 보고 싶다는 듯)",
            ["DialogueId"] = 90260701,
            ["GUID"] = "E1F54C42",
            ["SpeakNpcId"] = 81504,
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_companio_03",
            },
        [90270000] = {
            ["Content"] = "烈酒要越纯粹越好，如果掺杂了太多味道，就会掩盖原本的芳香，人也是一样的。",
            ["ContentKR"] = "(살짝 냄새를 맡으며) 독주는 순수할수록 좋아. 너무 많은 맛을 섞으면, 원래 가진 향이 묻혀 버리거든. 사람도 마찬가지지.",
            ["DialogueId"] = 90270000,
            ["GUID"] = "E1FB41E0",
            ["SpeakNpcId"] = 83202,
            ["VoiceName"] = "voice/$Locale$/char/Kami/vo_idle",
            },
        [90270001] = {
            ["Content"] = "叫醒我的是生意，叫醒你的是什么？",
            ["ContentKR"] = "날 깨운 건 장사인데, 널 깨운 건 뭐야?",
            ["DialogueId"] = 90270001,
            ["GUID"] = "E1FB420A",
            ["NextOptions"] = {
                [1] = 90270100,
                [2] = 90270200,
                [3] = 90270300,
                [4] = 90270400,
                },
            ["RandomOptionNum"] = 3,
            ["SpeakNpcId"] = 83202,
            ["VoiceName"] = "voice/$Locale$/char/Kami/vo_welcome",
            ["bForbidSkipOptions"] = true,
            },
        [90270002] = {
            ["Content"] = "聊点别的",
            ["ContentKR"] = "다른 이야기를 하자",
            ["DialogueId"] = 90270002,
            ["GUID"] = "E1FB4234",
            ["NextDialogue"] = 90270001,
            },
        [90270003] = {
            ["Content"] = "再见",
            ["ContentKR"] = "안녕히 계세요",
            ["DialogueId"] = 90270003,
            ["GUID"] = "E1FB425E",
            },
        [90270100] = {
            ["Content"] = "水仙平原那几个大酒桶是干什么用的？",
            ["ContentKR"] = "아스포델에 있는 커다란 술통들은 어디에 쓰는 건가요?",
            ["DialogueId"] = 90270100,
            ["GUID"] = "E1FB5248",
            ["NextDialogue"] = 90270101,
            },
        [90270101] = {
            ["Content"] = "酒桶？那自然是用来装美酒的。“冰湖往事”爽口，“军团狼血”浓烈，华胥运来的“苍龙醉”清冽悠长，卢卡的“假面舞会”由十种口味混合而成，每个人品出来的味道都不一样。",
            ["ContentKR"] = "술통? 당연히 술 담는 데 쓰는 거지. 목넘김이 시원한 '아이스레이크의 이야기', 독하고 강렬한 '군단용 울프 블러드'. 화서에서 가져온 '청룡의 취기'는 청량하지만 여운이 길고, 루카의 '가면무도회'는 10가지 맛으로 이루어져서, 마시는 사람마다 다른 맛을 느낄 수 있어.",
            ["DialogueId"] = 90270101,
            ["GUID"] = "E1FB5272",
            ["NextDialogue"] = 90270102,
            ["SpeakNpcId"] = 83202,
            ["VoiceName"] = "voice/$Locale$/char/Kami/vo_topic_01_1",
            },
        [90270102] = {
            ["Content"] = "怎么，你也打算来一杯？",
            ["ContentKR"] = "어때, 너도 한 잔 마셔 볼래?",
            ["DialogueId"] = 90270102,
            ["GUID"] = "E1FB529C",
            ["NextDialogue"] = 90270103,
            ["SpeakNpcId"] = 83202,
            ["VoiceName"] = "voice/$Locale$/char/Kami/vo_topic_01_2",
            },
        [90270103] = {
            ["Content"] = "别装傻了，我敲过，那些酒桶一直是空的。",
            ["ContentKR"] = "시치미 떼지 마세요. 제가 두드려봤는데, 술통은 쭉 비어 있었어요.",
            ["DialogueId"] = 90270103,
            ["GUID"] = "E1FB52C6",
            ["NextDialogue"] = 90270104,
            ["SpeakNpcId"] = 100001,
            },
        [90270104] = {
            ["Content"] = "……呵呵，你聪明了许多，早就不像初来冰湖城那样懵懂无知。",
            ["ContentKR"] = "...후후, 그새 많이 똑똑해졌구나. 아이스레이크 시티에 막 도착했을 때 그 어리바리하던 모습이 엊그제 같은데.",
            ["DialogueId"] = 90270104,
            ["GUID"] = "E1FB52F0",
            ["NextDialogue"] = 90270105,
            ["SpeakNpcId"] = 83202,
            ["VoiceName"] = "voice/$Locale$/char/Kami/vo_topic_01_3",
            },
        [90270105] = {
            ["Content"] = "冰湖城往北走一百多公里，翻越维德弗尼尔山脉，便是峡湾地埃斯加特——传说中卡戎之民真正的故乡。",
            ["ContentKR"] = "아이스레이크 시티에서 북쪽으로 백 킬로쯤 가서 베드르폴니르 산맥을 넘으면, 바로 아스카드 협만이 나와. 카론의 진짜 고향이라고 전해지는 곳이지.",
            ["DialogueId"] = 90270105,
            ["GUID"] = "E1FB531A",
            ["NextDialogue"] = 90270106,
            ["SpeakNpcId"] = 83202,
            ["VoiceName"] = "voice/$Locale$/char/Kami/vo_topic_01_4",
            },
        [90270106] = {
            ["Content"] = "对于很多冰湖城的卡戎之民来说，隔着一百多公里，一座高山……应许之地也并非远不可及，不是吗？",
            ["ContentKR"] = "백 킬로미터 거리, 산맥 하나... 이 도시에 사는 카론이라면, 약속의 땅이 꿈도 못 꿀 거리는 아닐 거야. 안 그래?",
            ["DialogueId"] = 90270106,
            ["GUID"] = "E1FB5344",
            ["NextDialogue"] = 90270107,
            ["SpeakNpcId"] = 83202,
            ["VoiceName"] = "voice/$Locale$/char/Kami/vo_topic_01_5",
            },
        [90270107] = {
            ["Content"] = "难道你在帮他们偷渡……",
            ["ContentKR"] = "설마 그 사람들의 밀항을 돕고 있는 건...",
            ["DialogueId"] = 90270107,
            ["GUID"] = "E1FB536E",
            ["NextDialogue"] = 90270108,
            ["SpeakNpcId"] = 100001,
            },
        [90270108] = {
            ["Content"] = "嘘——我可什么都没有说哦。",
            ["ContentKR"] = "쉬잇—— 난 아무 말 도 안 한 거다?",
            ["DialogueId"] = 90270108,
            ["GUID"] = "E1FB5398",
            ["NextOptions"] = {
                [1] = 90270002,
                [2] = 90270003,
                },
            ["SpeakNpcId"] = 83202,
            ["VoiceName"] = "voice/$Locale$/char/Kami/vo_topic_01_6",
            ["bForbidSkipOptions"] = true,
            },
        [90270200] = {
            ["Content"] = "“水仙平原”撑起了冰湖城狩月人这样一个职业，真了不起。",
            ["ContentKR"] = "'아스포델'이 아이스레이크 시티의 월석 사냥꾼이란 직업을 떠받치고 있다니, 정말 대단하네요.",
            ["DialogueId"] = 90270200,
            ["GUID"] = "E1FB62B0",
            ["NextDialogue"] = 90270201,
            },
        [90270201] = {
            ["Content"] = "承蒙缪赞。狩月人的历史比我这间酒馆古老得多，他们需要一个地方谈谈天，吹吹牛，交换一下彼此手里的“生意”，就算没有“水仙平原”，也会有“铃兰平原”，“郁金香平原”。",
            ["ContentKR"] = "과찬이야. 월석 사냥꾼의 역사는 이 술집보다 더 오래됐는걸. 그 사람들에겐 이야기를 나누고, 허풍을 떨면서, 각자의 '사업'을 교류할 공간이 필요했을 뿐이야. 아스포델이 없었다면 다른 술집에 갔겠지. '은방울꽃'이라든가 '튜울립'이라든가, 이름은 달랐겠지만.",
            ["DialogueId"] = 90270201,
            ["GUID"] = "E1FB62DA",
            ["NextDialogue"] = 90270202,
            ["SpeakNpcId"] = 83202,
            ["VoiceName"] = "voice/$Locale$/char/Kami/vo_topic_02_1",
            },
        [90270202] = {
            ["Content"] = "至于最终他们为什么汇集到我这儿来……无非是好喝的酒，作为中间人的公道无欺，以及人们困窘时给出的一点小恩小惠罢了。",
            ["ContentKR"] = "다만 마지막에 왜 다들 여기를 선택했을까 하는 건... 아마도 맛있는 술과 상도의를 지키는 중개인이 있고, 난처한 순간에 약간의 선심을 베풀어 주었기 때문이겠지?",
            ["DialogueId"] = 90270202,
            ["GUID"] = "E1FB6304",
            ["NextOptions"] = {
                [1] = 90270002,
                [2] = 90270003,
                },
            ["SpeakNpcId"] = 83202,
            ["VoiceName"] = "voice/$Locale$/char/Kami/vo_topic_02_2",
            ["bForbidSkipOptions"] = true,
            },
        [90270300] = {
            ["Content"] = "金钱对人们究竟意味着什么呢？",
            ["ContentKR"] = "돈이란 사람에게 과연 무슨 의미일까요?",
            ["DialogueId"] = 90270300,
            ["GUID"] = "E1FB7318",
            ["NextDialogue"] = 90270301,
            },
        [90270301] = {
            ["Content"] = "比起问我，问你自己不是更加合适吗？我还记得你初来冰湖城时无处可去的窘境，你应该很明白，钱是在世间立足的根本。",
            ["ContentKR"] = "그건 나보단 스스로한테 직접 묻는 게 낫지 않을까? 아이스레이크 시티에 막 도착해서 오갈 데 없는 신세였던 네가 난 아직도 기억에 생생한데. 세상을 살아가는데 돈은 기본이란 거, 너도 잘 알잖아?",
            ["DialogueId"] = 90270301,
            ["GUID"] = "E1FB7342",
            ["NextDialogue"] = 90270302,
            ["SpeakNpcId"] = 83202,
            ["VoiceName"] = "voice/$Locale$/char/Kami/vo_topic_03_1",
            },
        [90270302] = {
            ["Content"] = "我没有忘记，缺钱的时候确实很困难。",
            ["ContentKR"] = "맞아요, 돈이 없을 땐 확실히 곤란했죠.",
            ["DialogueId"] = 90270302,
            ["GUID"] = "E1FB736C",
            ["NextDialogue"] = 90270303,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/char/Kami/vo_topic_03_2",
            },
        [90270303] = {
            ["Content"] = "只要积累财富，即使无法改变出身，也会获得勇气对抗命运，即使周遭都是风雨，也能给自己买上一瓶酒暖暖身子，甚至能给别人分上一口，赚个人情。",
            ["ContentKR"] = "돈이 있으면, 설령 출신을 바꾸진 못하더라도, 운명에 맞설 용기가 생기지. 세찬 비바람이 몰아칠 때, 술 한 병 사서 몸이라도 녹일 수 있고, 아니면 다른 사람과 나눠 마시면서 인심을 쌓을 수도 있잖아.",
            ["DialogueId"] = 90270303,
            ["GUID"] = "E1FB7396",
            ["NextDialogue"] = 90270304,
            ["SpeakNpcId"] = 83202,
            ["VoiceName"] = "voice/$Locale$/char/Kami/vo_topic_03_3",
            },
        [90270304] = {
            ["Content"] = "你说，钱是不是很重要？",
            ["ContentKR"] = "봐, 돈이 얼마나 중요한지 알겠지?",
            ["DialogueId"] = 90270304,
            ["GUID"] = "E1FB73C0",
            ["NextOptions"] = {
                [1] = 90270002,
                [2] = 90270003,
                },
            ["SpeakNpcId"] = 83202,
            ["bForbidSkipOptions"] = true,
            },
        [90270400] = {
            ["Content"] = "关于带我来冰湖城的神秘人，你还知道些什么？",
            ["ContentKR"] = "절 아이스레이크 시티로 데려온 수수께끼의 인물에 대해 잘 아세요?",
            ["DialogueId"] = 90270400,
            ["GUID"] = "E1FB8380",
            ["NextDialogue"] = 90270401,
            },
        [90270401] = {
            ["Content"] = "很遗憾，我在冰湖城待了这么多年，但那人我也是第一次瞧见。他把自己裹在一身斗篷里，说话也是用的变声器。从哪儿来的，是男是女，多大年纪……一概不知。",
            ["ContentKR"] = "안타깝지만, 아이스레이크 시티에서 이렇게 오래 지낸 나조차도 처음 보는 얼굴이었어. 망토를 뒤집어쓴 데다가 말할 땐 음성 변조기를 사용했거든. 어디서 왔는지, 남자인지 여자인지, 나이는 어느 정도인지... 아무것도 몰라.",
            ["DialogueId"] = 90270401,
            ["GUID"] = "E1FB83AA",
            ["NextDialogue"] = 90270402,
            ["SpeakNpcId"] = 83202,
            ["VoiceName"] = "voice/$Locale$/char/Kami/vo_topic_04_1",
            },
        [90270402] = {
            ["Content"] = "我唯一可以确认的便是他的力量深不可测。只是短暂的交手，我便知绝无胜算。",
            ["ContentKR"] = "한 가지 확실한 건, 엄청난 힘의 소유자였다는 거야. 맞서자마자 곧 승산이 없다는 걸 깨달았거든.",
            ["DialogueId"] = 90270402,
            ["GUID"] = "E1FB83D4",
            ["NextDialogue"] = 90270403,
            ["SpeakNpcId"] = 83202,
            ["VoiceName"] = "voice/$Locale$/char/Kami/vo_topic_04_2",
            },
        [90270403] = {
            ["Content"] = "想不到你会这么谦虚。",
            ["ContentKR"] = "생각보다 겸손하시네요.",
            ["DialogueId"] = 90270403,
            ["GUID"] = "E1FB83FE",
            ["NextDialogue"] = 90270404,
            ["SpeakNpcId"] = 100001,
            },
        [90270404] = {
            ["Content"] = "呵呵，对生意人来说，最重要的就是盘清自己和对方手里分别捏着多少价码，只有你们手里的价码差不多时，虚张声势才有意义。这种利弊，我还是看得清。",
            ["ContentKR"] = "후후, 장사꾼한테 제일 중요한 게 뭔지 알아? 내가 쥔 것과 상대가 쥔 것의 가치를 정확하게 파악하는 거야. 상대가 나랑 비슷한 걸 들고 있을 때만 블러핑도 의미가 있거든. 이런 계산 정도는 할 줄 알아야지.",
            ["DialogueId"] = 90270404,
            ["GUID"] = "E1FB8428",
            ["NextDialogue"] = 90270405,
            ["SpeakNpcId"] = 83202,
            ["VoiceName"] = "voice/$Locale$/char/Kami/vo_topic_04_3",
            },
        [90270405] = {
            ["Content"] = "对了，我想起来了，那人离开前说了一句话——",
            ["ContentKR"] = "아참, 그러고 보니 그 사람이 가기 전에 남긴 말이 있었네——",
            ["DialogueId"] = 90270405,
            ["GUID"] = "E1FB8452",
            ["NextDialogue"] = 90270406,
            ["SpeakNpcId"] = 83202,
            ["VoiceName"] = "voice/$Locale$/char/Kami/vo_topic_04_4",
            },
        [90270406] = {
            ["Content"] = "他说，他希望从你那里得到的，是一个“答案”。",
            ["ContentKR"] = "그래, 그 사람은 너한테서 '답'을 얻고 싶다고 했어.",
            ["DialogueId"] = 90270406,
            ["GUID"] = "E1FB847C",
            ["NextOptions"] = {
                [1] = 90270002,
                [2] = 90270003,
                },
            ["SpeakNpcId"] = 83202,
            ["VoiceName"] = "voice/$Locale$/char/Kami/vo_topic_04_5",
            ["bForbidSkipOptions"] = true,
            },
        [90270601] = {
            ["Content"] = "每个人的天赋不同，有些人生来就拥有治愈人心的能力，就像你，好孩子。",
            ["ContentKR"] = "사람마다 타고난 재능이 달라서, 어떤 사람은 마음을 치유하는 능력이 있어. 바로 너처럼 말이야.",
            ["DialogueId"] = 90270601,
            ["GUID"] = "E1FBA47A",
            ["SpeakNpcId"] = 83202,
            ["VoiceName"] = "voice/$Locale$/char/Kami/vo_companio_01",
            },
        [90270701] = {
            ["Content"] = "难得你会大老远跑来冰湖城。这次是想要什么帝国特产物资？还是只是打算听场戏？",
            ["ContentKR"] = "이 먼 아이스레이크 시티까지 찾아오다니, 이번엔 제국 특산품이 목적이야? 아니면 공연을 보러 온 건가?",
            ["DialogueId"] = 90270701,
            ["GUID"] = "E1FBB4E2",
            ["SpeakNpcId"] = 83202,
            ["VoiceName"] = "voice/$Locale$/char/Kami/vo_companio_02",
            },
        [90270801] = {
            ["Content"] = "这伤疤……你难道又接了危险的任务？……唉，我店里有药，你自己去涂点，毕竟在这里出事会影响我做生意。怎么，傻站在这是想让我亲自给你去拿？",
            ["ContentKR"] = "이 상처... 설마 또 위험한 임무를 다녀온 거야? ...휴, 가게에 약 있으니까 가서 발라둬. 여기서 무슨 일이라도 생기면 내 장사에 지장이 생긴다고. 응? 왜 그러고 서 있어? 설마, 나보고 직접 가져다 달라는 거야?",
            ["DialogueId"] = 90270801,
            ["GUID"] = "E1FBC54A",
            ["SpeakNpcId"] = 83202,
            ["VoiceName"] = "voice/$Locale$/char/Kami/vo_companio_03",
            },
        [100365691] = {
            ["DialogueId"] = 100365691,
            ["DialoguePanelType"] = "None",
            ["Duration"] = 3,
            ["GUID"] = "100365691",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10036571.T_Story_Recall_10036571'",
            ["NextDialogue"] = 10036570,
            },
        [100365862] = {
            ["Camera"] = "-369.931641,-193.570129,443.070312,-0.001404,-42.627155,6.081401,35.000008,371.172089,false,Manual,3.0",
            ["Content"] = "（士兵的手腕有一道细细的伤痕，稍加辨认便能看出是被利剑所伤。但<H>这个舞台最终留下的，应该只有军团与“怪物”战斗的痕迹才对。</>）",
            ["ContentKR"] = "(병사의 손목에 가느다란 상처가 눈에 띈다. 날카로운 검에 베인 흔적이다. 하지만, <H>이 무대에 남을 수 있는 건, 군단과 '괴물'이 맞서 싸운 흔적뿐이다.</>)",
            ["DialogueId"] = 100365862,
            ["FinalCamera"] = "-388.837891,-106.715332,443.070312,-0.001404,-46.226898,-0.518005,35.000008,371.172089,false,Manual,3.0",
            ["GUID"] = "100365862",
            ["NextOptions"] = {
                [1] = 100365863,
                },
            ["ToFinalCameraBlendTime"] = 8,
            },
        [100365863] = {
            ["Content"] = "（毁掉剑痕。）",
            ["ContentKR"] = "(검에 베인 흔적을 없앤다.)",
            ["DialogueId"] = 100365863,
            ["GUID"] = "100365863",
            ["NextDialogue"] = 100365864,
            },
        [100365864] = {
            ["Camera"] = "237.636719,751.144104,145.707031,-0.001404,-4.425778,-101.517555,35.0,844.950317,false,Manual,3.0",
            ["Content"] = "（那道剑伤足够细，所以伤口的形状可以轻易被破坏掉。朱红的露滴滚落，<H>就像从来没有一位使剑的狩月人来过这里一样。</>）",
            ["ContentKR"] = "(가늘고 긴 흔적은 손쉽게 형태를 망가뜨릴 수 있었다. 선홍빛 핏방울이 상처를 따라 흘러내린다. <H>마치 검을 사용하는 월석 사냥꾼 따위는 처음부터 이곳에 없었다는 듯이.</>)",
            ["DialogueId"] = 100365864,
            ["FinalCamera"] = "359.826172,861.536682,156.921875,-0.001403,-4.82574,-105.317894,35.0,844.950317,false,Manual,3.0",
            ["GUID"] = "100365864",
            ["NextDialogue"] = 100365865,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/02/stab\"},PlayAs2D{true}}",
            ["ToFinalCameraBlendTime"] = 8,
            },
        [100365865] = {
            ["Camera"] = "-197.347656,-337.183167,364.167969,-0.001403,-31.025061,92.480331,35.000008,844.950317,false,Manual,3.0",
            ["Content"] = "（士兵的身上有大面积焦痂，稍加辨认便能看出遭受过电击。但<H>这个舞台最终留下的，应该只有军团与“怪物”战斗的痕迹才对。</>）",
            ["ContentKR"] = "(병사의 몸에 딱지가 넓게 앉아 있고, 감전의 흔적이 눈에 띈다. 하지만 <H>이 무대에 남을 수 있는 건, 군단과 '괴물'이 맞서 싸운 흔적뿐이다.</>)",
            ["DialogueId"] = 100365865,
            ["FinalCamera"] = "-290.177734,-277.0578,492.726562,-0.001407,-42.224854,94.280289,35.000008,844.950317,false,Manual,3.0",
            ["GUID"] = "100365865",
            ["LookAt"] = {
                [1] = "100327:n(100352)",
                },
            ["NextOptions"] = {
                [1] = 100365866,
                },
            ["Scripts"] = "SetLocation{ActorId{100327},TargetPoint{\"BP_NewTargetPoint_ch2fix62_2\"},Visibility{\"Show\"}}",
            ["TalkActionId"] = {
                [1] = "100327:Angry01_Start",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["TurnTo"] = {
                [1] = "100327:p(110)",
                },
            },
        [100365866] = {
            ["Content"] = "（扯过电缆。）",
            ["ContentKR"] = "(전선을 손으로 치운다.)",
            ["DialogueId"] = 100365866,
            ["GUID"] = "100365866",
            ["NextDialogue"] = 100365867,
            },
        [100365867] = {
            ["Camera"] = "-1248.921875,692.722961,215.214844,-0.001404,-8.02483,-50.121822,35.0,549.465881,false,Manual,3.0",
            ["Content"] = "（落地灯碎裂，垂落的电缆被拦腰扯断。电火花跳起快活的小步舞曲，<H>就像从来没有一位能操纵电流的军官来过这里一样。</>啊，可惜了，那真的是一盏很漂亮的落地灯。）",
            ["ContentKR"] = "(플로어 스탠드가 깨지며, 늘어진 전선이 허리춤에서 끊어진다. 전기 불꽃이 즐거운 미뉴에트를 추듯 피어오른다. <H>마치 전기를 다루는 장교는 처음부터 이곳에 없었다는 듯이</>. 아, 제법 멋진 등이었는데, 참 아까운 일이다.)",
            ["DialogueId"] = 100365867,
            ["FinalCamera"] = "-1248.921875,692.722961,215.214844,-0.001403,-4.82477,-49.922085,35.0,549.465881,false,Manual,3.0",
            ["GUID"] = "100365867",
            ["NextDialogue"] = 100365868,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/02/stab\"},PlayAs2D{true}}",
            ["ToFinalCameraBlendTime"] = 8,
            },
        [100365868] = {
            ["Camera"] = "-314.880859,882.889343,174.027344,-0.001404,0.975194,-93.919266,15.0,328.721466,false,Manual,3.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "（现在，布景已经完成了：十三军团一路追查到盖雷亚剧院，<H>先头小队虽然疏散了群众，却不幸命丧“怪物”之手。</>随后赶来的大部队则成功击毙“怪物”，为卡戎狩猎一案画上了休止符——这才是卡戎狩猎最恰如其分的谢幕。）",
            ["ContentKR"] = "(이제 모든 무대 장치가 완성됐다. 제13군단은 갈레아 극장까지 괴물을 추적했고, <H>선발대는 관객을 대피시켰으나, 불행히도 '괴물'의 손에 목숨을 잃는다.</> 뒤이어 도착한 본대가 '괴물'을 성공적으로 사살함으로써, '카론 사냥'은 막을 내린다. 이것이야말로 '카론 사냥'에 가장 걸맞은 피날레다.)",
            ["DialogueId"] = 100365868,
            ["FinalCamera"] = "-324.787109,1630.875977,511.484375,-0.001404,0.175338,-91.318481,15.000005,768.242798,false,Manual,3.0",
            ["GUID"] = "100365868",
            ["LookAt"] = {
                [1] = "100327:n(100310)",
                },
            ["Scripts"] = "SetLocation{ActorId{100327},TargetPoint{\"tuosi02_62\"},Visibility{\"Show\"}}",
            ["TalkActionId"] = {
                [1] = "100327:Angry01_End",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["TurnTo"] = {
                [1] = "100327:p(-70)",
                },
            },
        [101002151] = {
            ["Content"] = "（跟随卡米拉前往冰湖城。）",
            ["ContentKR"] = "(카밀라를 따라 아이스레이크 시티로 간다.)",
            ["DialogueId"] = 101002151,
            ["GUID"] = "101002151",
            ["ImprPlusId"] = 1006,
            ["NextDialogue"] = 10100223,
            },
        [101002152] = {
            ["Content"] = "（无法信任陌生人。）",
            ["ContentKR"] = "(낯선 사람은 믿을 수 없다.)",
            ["DialogueId"] = 101002152,
            ["GUID"] = "101002152",
            ["ImprPlusId"] = 1008,
            ["NextDialogue"] = 10100216,
            },
        [101004021] = {
            ["Content"] = "已经没事了，别怕。",
            ["ContentKR"] = "이제 괜찮아, 겁먹지 마.",
            ["DialogueId"] = 101004021,
            ["GUID"] = "101004021",
            ["ImprPlusId"] = 1009,
            ["NextDialogue"] = 10100403,
            },
        [101004022] = {
            ["Content"] = "刚才好像有谁说要罩着我来着。",
            ["ContentKR"] = "방금 누가 지켜준다고 한 것 같은데~",
            ["DialogueId"] = 101004022,
            ["GUID"] = "101004022",
            ["ImprPlusId"] = 1010,
            ["NextDialogue"] = 10100404,
            },
        [101006061] = {
            ["Content"] = "南方的一个小岛。",
            ["ContentKR"] = "남쪽의 한 작은 섬에서...",
            ["DialogueId"] = 101006061,
            ["GUID"] = "101006061",
            ["ImprPlusId"] = 1007,
            ["NextDialogue"] = 10100607,
            },
        [101006062] = {
            ["Content"] = "我是卡米拉女士的亲戚。",
            ["ContentKR"] = "전 카밀라 씨 친척이에요.",
            ["DialogueId"] = 101006062,
            ["GUID"] = "101006062.0",
            ["ImprPlusId"] = 1010,
            ["NextDialogue"] = 10100609,
            },
        [101006063] = {
            ["Content"] = "（保持沉默，把目光投向卡米拉。）",
            ["ContentKR"] = "(말없이 카밀라를 쳐다본다.)",
            ["DialogueId"] = 101006063,
            ["GUID"] = "101006063.0",
            ["ImprPlusId"] = 1008,
            ["NextDialogue"] = 101006110,
            },
        [101006110] = {
            ["Camera"] = "31.592773,-132.096191,174.667969,0.00129,-11.999296,124.201492,40.60326,233.368286,false,Manual,1.2",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["DialogueId"] = 101006110,
            ["DialoguePanelType"] = "None",
            ["Duration"] = 3,
            ["FinalCamera"] = "20.211914,-139.831543,174.667969,0.001292,-11.999235,124.201599,40.60326,188.175873,false,Manual,1.2",
            ["GUID"] = "19492B55",
            ["LookAt"] = {
                [1] = "100001:n(200003)",
                },
            ["NextDialogue"] = 10100611,
            ["ToFinalCameraBlendTime"] = 3,
            },
        [101006121] = {
            ["Content"] = "（做出一个悲伤的表情。）",
            ["ContentKR"] = "(슬픈 표정을 지어 보인다.)",
            ["DialogueId"] = 101006121,
            ["GUID"] = "101006121.0",
            ["NextDialogue"] = 10100613,
            },
        [101006122] = {
            ["Content"] = "（挤出几滴眼泪。）",
            ["ContentKR"] = "(눈물을 몇 방울 짜낸다.)",
            ["DialogueId"] = 101006122,
            ["GUID"] = "101006122.0",
            ["NextDialogue"] = 10100613,
            },
        [101008011] = {
            ["Content"] = "……刚刚感觉到了危险。",
            ["ContentKR"] = "...그러지 않으면 안 될 것 같아서요.",
            ["DialogueId"] = 101008011,
            ["GUID"] = "101008011.0",
            ["NextDialogue"] = 10100802,
            },
        [101008012] = {
            ["Content"] = "彼此彼此。",
            ["ContentKR"] = "그쪽도 마찬가지인 걸요.",
            ["DialogueId"] = 101008012,
            ["GUID"] = "101008012.0",
            ["NextDialogue"] = 10100802,
            },
        [101008061] = {
            ["Content"] = "你们救下我，似乎并不是巧合。难道这就是你口中的“交易”？",
            ["ContentKR"] = "절 구한 게 단지 우연은 아닌 것 같은데, 설마 이게 당신이 말한 '거래' 인가요?",
            ["DialogueId"] = 101008061,
            ["GUID"] = "101008061",
            ["NextDialogue"] = 10100807,
            },
        [101008062] = {
            ["DialogueId"] = 101008062,
            ["DialoguePanelType"] = "None",
            ["Duration"] = 0.1,
            ["FinalDialogueId"] = 10100824,
            ["GUID"] = "101008062",
            ["NextOptions"] = {
                [1] = 101008061,
                [2] = 101008151,
                [3] = 101008191,
                },
            },
        [101008151] = {
            ["Content"] = "我想知道怎么回净界岛。",
            ["ContentKR"] = "연옥도로 돌아가는 방법을 알고 싶어요.",
            ["DialogueId"] = 101008151,
            ["GUID"] = "101008151",
            ["NextDialogue"] = 10100816,
            },
        [101008191] = {
            ["Content"] = "我还是想找西比尔。我没有开玩笑。",
            ["ContentKR"] = "그래도 시빌라를 만나고 싶어요. 농담하는 거 아니에요.",
            ["DialogueId"] = 101008191,
            ["GUID"] = "101008191",
            ["NextDialogue"] = 10100820,
            },
        [101012131] = {
            ["Content"] = "走吧，会有其他办法的。",
            ["ContentKR"] = "가자, 다른 방법이 있을 거야. ",
            ["DialogueId"] = 101012131,
            ["GUID"] = "101012131",
            ["ImprPlusId"] = 1007,
            },
        [101012132] = {
            ["Content"] = "这样做生意不怕倒闭吗？ ",
            ["ContentKR"] = "이렇게 장사하다 망하면 어쩌려고 그래요? ",
            ["DialogueId"] = 101012132,
            ["GUID"] = "101012132",
            ["ImprPlusId"] = 1006,
            },
        [101012133] = {
            ["Content"] = "其实我是治安署派来的，你等着吧。",
            ["ContentKR"] = "사실 전 치안서에서 왔어요. 두고 보죠.",
            ["DialogueId"] = 101012133,
            ["GUID"] = "101012133.0",
            ["ImprPlusId"] = 1010,
            },
        }
  end },
