            ["DialogueId"] = 101016101,
            ["GUID"] = "101016101",
            ["ImprPlusId"] = 1007,
            ["NextDialogue"] = 10101612,
            },
        [101016102] = {
            ["Content"] = "白，你的肚子在叫？ ",
            ["ContentKR"] = "스노우, 방금 네 배에서 난 소리야? ",
            ["DialogueId"] = 101016102,
            ["GUID"] = "101016102.0",
            ["ImprPlusId"] = 1010,
            ["NextDialogue"] = 10101611,
            },
        [101024191] = {
            ["Content"] = "这也是无可奈何的事吧。 ",
            ["ContentKR"] = "어쩔 수 없는 일이겠지. ",
            ["DialogueId"] = 101024191,
            ["GUID"] = "101024191",
            ["ImprPlusId"] = 1009,
            ["NextDialogue"] = 10102420,
            },
        [101024192] = {
            ["Content"] = "白说得对。应当以牙还牙，以眼还眼。 ",
            ["ContentKR"] = "스노우 말이 맞아. 받은 만큼 돌려줘야지. ",
            ["DialogueId"] = 101024192,
            ["GUID"] = "101024192",
            ["ImprPlusId"] = 1007,
            ["NextDialogue"] = 10102420,
            },
        [101026091] = {
            ["Content"] = "更危险的事情，我也已经经历过了。 ",
            ["ContentKR"] = "더 위험한 일도 겪어 본걸요. ",
            ["DialogueId"] = 101026091,
            ["GUID"] = "101026091",
            ["ImprPlusId"] = 1008,
            ["NextDialogue"] = 10102610,
            },
        [101026092] = {
            ["Content"] = "和饿死相比，我选择冒险。",
            ["ContentKR"] = "굶어 죽을 바에는 뭐라도 해보겠어요.",
            ["DialogueId"] = 101026092,
            ["GUID"] = "101026092",
            ["ImprPlusId"] = 1006,
            ["NextDialogue"] = 10102610,
            },
        [101038121] = {
            ["Content"] = "？",
            ["ContentKR"] = "......?",
            ["DialogueId"] = 101038121,
            ["GUID"] = "101038121.0",
            ["NextDialogue"] = 10103813,
            },
        [101040051] = {
            ["Content"] = "“烫手山芋”？",
            ["ContentKR"] = "'그 일'이라뇨?",
            ["DialogueId"] = 101040051,
            ["GUID"] = "101040051.0",
            ["NextDialogue"] = 10104006,
            },
        [101040061] = {
            ["Content"] = "讲给我听听吧，我很好奇。",
            ["ContentKR"] = "그래도 얘기해 주세요. 궁금해요.",
            ["DialogueId"] = 101040061,
            ["GUID"] = "101040061.0",
            ["NextDialogue"] = 10104007,
            },
        [101040141] = {
            ["Content"] = "我打算试一试。",
            ["ContentKR"] = "한번 시도해 보고 싶어요.",
            ["DialogueId"] = 101040141,
            ["GUID"] = "101040141.0",
            ["NextDialogue"] = 10104015,
            },
        [101043011] = {
            ["Content"] = "和我聊聊冰湖城吧。",
            ["ContentKR"] = "아이스레이크 시티 얘기 좀 해주세요.",
            ["DialogueId"] = 101043011,
            ["GUID"] = "101043011",
            ["NextDialogue"] = 10104302,
            },
        [101043051] = {
            ["Content"] = "和我聊聊狩月人吧。",
            ["ContentKR"] = "월석 사냥꾼 얘기 좀 해주세요.",
            ["DialogueId"] = 101043051,
            ["GUID"] = "101043051",
            ["NextDialogue"] = 10104306,
            },
        [101043091] = {
            ["Content"] = "和我聊聊你自己吧。",
            ["ContentKR"] = "당신 얘기 좀 해주세요.",
            ["DialogueId"] = 101043091,
            ["GUID"] = "101043091",
            ["NextDialogue"] = 10104310,
            },
        [101043111] = {
            ["Content"] = "聊聊别的。",
            ["ContentKR"] = "다른 이야기를 해볼까요.",
            ["DialogueId"] = 101043111,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "101043111",
            ["SpeakNpcId"] = 100001,
            },
        [101043112] = {
            ["Content"] = "谢谢，我没有其他事了。",
            ["ContentKR"] = "감사합니다. 필요한 말은 다 한 것 같아요.",
            ["DialogueId"] = 101043112,
            ["GUID"] = "101043112",
            },
        [101044051] = {
            ["Content"] = "多谢，又欠了你的人情。",
            ["ContentKR"] = "고마워, 또 빚을 지네. ",
            ["DialogueId"] = 101044051,
            ["GUID"] = "101044051",
            ["ImprPlusId"] = 1009,
            ["NextDialogue"] = 10104406,
            },
        [101044052] = {
            ["Content"] = "既然是帮你们办事，理当如此。 ",
            ["ContentKR"] = "너희 일이니까 당연히 그러는 게 좋지. ",
            ["DialogueId"] = 101044052,
            ["GUID"] = "101044052",
            ["ImprPlusId"] = 1006,
            ["NextDialogue"] = 10104406,
            },
        [101046091] = {
            ["Content"] = "那就一起走吧。",
            ["ContentKR"] = "그럼 같이 가자.",
            ["DialogueId"] = 101046091,
            ["GUID"] = "101046091",
            ["ImprPlusId"] = 1009,
            ["NextDialogue"] = 10104612,
            },
        [101046092] = {
            ["Content"] = "别听白怂恿，她只是想多一个人壮胆。",
            ["ContentKR"] = "스노우 녀석 말은 듣지 마. 괜히 너한테 바람만 넣는 거야.",
            ["DialogueId"] = 101046092,
            ["GUID"] = "101046092",
            ["ImprPlusId"] = 1008,
            ["NextDialogue"] = 10104610,
            },
        [101054041] = {
            ["Content"] = "秽兽是我们击败的，把战利品还给我。 ",
            ["ContentKR"] = "필토이드는 우리가 쓰러뜨린 거야. 전리품을 돌려줘.",
            ["DialogueId"] = 101054041,
            ["GUID"] = "101054041",
            ["ImprPlusId"] = 1007,
            ["NextDialogue"] = 10105406,
            },
        [101054042] = {
            ["Content"] = "既然不论先来后到，那就是说，打一顿抢回来就行了。 ",
            ["ContentKR"] = "순서가 중요한 게 아니라면, 힘으로 가져가도 된다는 말이겠지?",
            ["DialogueId"] = 101054042,
            ["GUID"] = "101054042",
            ["ImprPlusId"] = 1010,
            ["NextDialogue"] = 10105406,
            },
        [101054091] = {
            ["Content"] = "拒绝！",
            ["ContentKR"] = "아니!",
            ["DialogueId"] = 101054091,
            ["GUID"] = "101054091.0",
            ["NextDialogue"] = 10105410,
            },
        [101054092] = {
            ["Content"] = "坚定地拒绝！",
            ["ContentKR"] = "절대 안 돼!",
            ["DialogueId"] = 101054092,
            ["GUID"] = "101054092.0",
            ["NextDialogue"] = 10105410,
            },
        [101054141] = {
            ["Content"] = "不打了，成交。",
            ["ContentKR"] = "알겠어, 대화로 해결하자.",
            ["DialogueId"] = 101054141,
            ["GUID"] = "101054141.0",
            ["NextDialogue"] = 10105417,
            },
        [101054142] = {
            ["Content"] = "打！",
            ["ContentKR"] = "공격!",
            ["DialogueId"] = 101054142,
            ["GUID"] = "101054142.0",
            ["NextDialogue"] = 10105415,
            },
        [101054151] = {
            ["Content"] = "不打了，成交。",
            ["ContentKR"] = "알겠어, 대화로 해결하자.",
            ["DialogueId"] = 101054151,
            ["GUID"] = "101054151.0",
            ["NextDialogue"] = 10105417,
            },
        [101054152] = {
            ["Content"] = "好巧！我也是！",
            ["ContentKR"] = "공교롭지만, 나도 마찬가지야!",
            ["DialogueId"] = 101054152,
            ["GUID"] = "101054152.0",
            ["NextDialogue"] = 10105416,
            },
        [101054191] = {
            ["Content"] = "一份价值五千银币的悬赏。",
            ["ContentKR"] = "현상금이 5천 실버나 되니까.",
            ["DialogueId"] = 101054191,
            ["GUID"] = "101054191",
            ["NextDialogue"] = 10105420,
            },
        [101054211] = {
            ["Content"] = "行吧。",
            ["ContentKR"] = "그러든지.",
            ["DialogueId"] = 101054211,
            ["GUID"] = "101054211",
            ["NextDialogue"] = 10105425,
            },
        [101054212] = {
            ["Content"] = "口说无凭，我要怎么相信你？",
            ["ContentKR"] = "말뿐인 약속을 내가 어떻게 믿지?",
            ["DialogueId"] = 101054212,
            ["GUID"] = "101054212",
            ["NextDialogue"] = 10105422,
            },
        [101058131] = {
            ["Content"] = "她又不是你的女儿。",
            ["ContentKR"] = "당신 딸도 아니잖아요.",
            ["DialogueId"] = 101058131,
            ["GUID"] = "101058131",
            ["NextDialogue"] = 10105814,
            },
        [101058132] = {
            ["Content"] = "你对所有人都这样礼貌吗？",
            ["ContentKR"] = "당신은 모두를 이렇게 대하나요?",
            ["DialogueId"] = 101058132,
            ["GUID"] = "101058132",
            ["NextDialogue"] = 10105815,
            },
        [101063031] = {
            ["Content"] = "你不想让白听到？",
            ["ContentKR"] = "스노우가 못 듣게 하려고 그런 거야?",
            ["DialogueId"] = 101063031,
            ["GUID"] = "101063031",
            ["NextDialogue"] = 10106304,
            },
        [101063032] = {
            ["Content"] = "你不想让赛琪听到？",
            ["ContentKR"] = "프시케가 못 듣게 하려고 그런 거야?",
            ["DialogueId"] = 101063032,
            ["GUID"] = "101063032",
            ["NextDialogue"] = 10106305,
            },
        [101063245] = {
            ["Content"] = "如果恩里克真的有什么阴谋，相比怀疑，我更担心恩里克会对她不利。她不会做坏事……我相信我的直觉。",
            ["ContentKR"] = "정말 헨릭이 무슨 음모를 꾸민다면 뭘 할지보다는 프시케가 위험해질까 봐 더 걱정돼. 프시케라면 나쁜 짓은 결코 하지 않을 거야... 내 직감이 그래.",
            ["DialogueId"] = 101063245,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194CD3A2",
            ["NextDialogue"] = 10106325,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101063/194CD3A2",
            },
        [101068021] = {
            ["Content"] = "请过目。",
            ["ContentKR"] = "직접 보세요.",
            ["DialogueId"] = 101068021,
            ["GUID"] = "101068021",
            ["NextDialogue"] = 10106803,
            },
        [101070021] = {
            ["Content"] = "谢谢你，赛琪。不过，我从奥特赛德那里把绮晶讨了回来。",
            ["ContentKR"] = "고마워, 프시케. 하지만 아웃사이더한테서 수정을 되찾아 왔어.",
            ["DialogueId"] = 101070021,
            ["GUID"] = "101070021.0",
            ["NextDialogue"] = 10107003,
            },
        [101070031] = {
            ["Content"] = "我讲了个故事把他感动哭了。 ",
            ["ContentKR"] = "내가 이야기를 해줬더니 감동받아서 울더라.",
            ["DialogueId"] = 101070031,
            ["GUID"] = "101070031",
            ["ImprPlusId"] = 1009,
            ["NextDialogue"] = 10107004,
            },
        [101070032] = {
            ["Content"] = "他回城路上摔断了腿，现在在家嗷嗷乱叫。",
            ["ContentKR"] = "시티로 돌아가는 길에 다리가 부러져서 지금 집에서 비명 지르고 있을걸.",
            ["DialogueId"] = 101070032,
            ["GUID"] = "101070032",
            ["ImprPlusId"] = 1010,
            ["NextDialogue"] = 10107006,
            },
        [101070071] = {
            ["Content"] = "这里的住客看起来有些……无精打采。",
            ["ContentKR"] = "여기 투숙객들은 좀... 기운이 없어 보이네.",
            ["DialogueId"] = 101070071,
            ["GUID"] = "101070071.0",
            ["NextDialogue"] = 10107008,
            },
        [101070131] = {
            ["Content"] = "恩里克先生平常主要什么时候在家？",
            ["ContentKR"] = "헨릭 씨는 주로 언제 집에 있어?",
            ["DialogueId"] = 101070131,
            ["GUID"] = "101070131",
            ["NextDialogue"] = 10107014,
            },
        [101070171] = {
            ["Content"] = "你还好吗？",
            ["ContentKR"] = "넌 괜찮아?",
            ["DialogueId"] = 101070171,
            ["GUID"] = "101070171",
            ["NextDialogue"] = 10107018,
            },
        [101070291] = {
            ["Content"] = "谢谢你，是很漂亮的花。",
            ["ContentKR"] = "고마워, 예쁜 꽃이네.",
            ["DialogueId"] = 101070291,
            ["GUID"] = "101070291.0",
            ["NextDialogue"] = 10107030,
            },
        [101071031] = {
            ["Content"] = "这么说不就让人更好奇了吗。",
            ["ContentKR"] = "그렇게 말하면 더 궁금하잖아.",
            ["DialogueId"] = 101071031,
            ["GUID"] = "101071031",
            ["NextDialogue"] = 10107104,
            },
        [101071032] = {
            ["Content"] = "你在这里做什么？",
            ["ContentKR"] = "넌 여기서 뭐 하는데?",
            ["DialogueId"] = 101071032,
            ["GUID"] = "101071032.0",
            ["NextDialogue"] = 10107106,
            },
        [101071051] = {
            ["Content"] = "你在这里做什么？",
            ["ContentKR"] = "넌 여기서 뭐 하는데?",
            ["DialogueId"] = 101071051,
            ["GUID"] = "101071051.0",
            ["NextDialogue"] = 10107106,
            },
        [101071061] = {
            ["Content"] = "每天一遍？也太麻烦了。",
            ["ContentKR"] = "매일? 귀찮지 않아?",
            ["DialogueId"] = 101071061,
            ["GUID"] = "101071061.0",
            ["NextDialogue"] = 10107107,
            },
        [101071062] = {
            ["Content"] = "这扇门已经很干净了，现在没有擦的必要。",
            ["ContentKR"] = "이 문은 충분히 깨끗해, 더 닦지 않아도 돼.",
            ["DialogueId"] = 101071062,
            ["GUID"] = "101071062.0",
            ["NextDialogue"] = 10107107,
            },
        [101071081] = {
            ["Content"] = "很有道理，我也想养成习惯。那么恩里克先生有什么习惯吗？",
            ["ContentKR"] = "그렇겠네, 나도 습관을 기르고 싶어. 그럼 헨릭 씨는 어떤 습관이 있어? ",
            ["DialogueId"] = 101071081,
            ["GUID"] = "101071081",
            ["ImprPlusId"] = 1008,
            ["NextDialogue"] = 10107109,
            },
        [101071121] = {
            ["Content"] = "已经足够了。是非常有意义的习惯。",
            ["ContentKR"] = "그걸로 충분해. 아주 의미 있는 습관이네.",
            ["DialogueId"] = 101071121,
            ["GUID"] = "101071121.0",
            ["NextDialogue"] = 10107113,
            },
        [101073021] = {
            ["Content"] = "你提到了“亨特”？",
            ["ContentKR"] = "'헌트'라고?",
            ["DialogueId"] = 101073021,
            ["GUID"] = "101073021.0",
            ["NextDialogue"] = 10107303,
            },
        [101073041] = {
            ["Content"] = "是你自己说话太大声了……",
            ["ContentKR"] = "네 목소리가 컸던 거야...",
            ["DialogueId"] = 101073041,
            ["GUID"] = "101073041.0",
            ["NextDialogue"] = 10107305,
            },
        [101073051] = {
            ["Content"] = "我们聊聊“亨特”吧。他去了哪里？",
            ["ContentKR"] = "'헌트' 얘기를 하자. 그는 어디로 갔지?",
            ["DialogueId"] = 101073051,
            ["GUID"] = "101073051",
            ["NextDialogue"] = 10107306,
            },
        [101073071] = {
            ["Content"] = "抱歉，我这就走。",
            ["ContentKR"] = "알겠어, 미안해. 방해하지 않을게.",
            ["DialogueId"] = 101073071,
            ["GUID"] = "101073071.0",
            ["NextDialogue"] = 10107308,
            },
        [101078021] = {
            ["Content"] = "修普诺斯之家的住客都是病人。",
            ["ContentKR"] = "히프노스의 집 투숙객들은 모두 환자야.",
            ["DialogueId"] = 101078021,
            ["GUID"] = "101078021.0",
            ["NextDialogue"] = 10107803,
            },
        [101078071] = {
            ["Content"] = "宅邸内有一个上锁的房间。秘密也许在那里。",
            ["ContentKR"] = "저택 안에 잠겨 있는 방이 하나 있었어. 아마 비밀은 거기에 숨겨져 있을 거야.",
            ["DialogueId"] = 101078071,
            ["GUID"] = "101078071",
            ["NextDialogue"] = 10107808,
            },
        [101078111] = {
            ["Content"] = "恩里克绝大部分时间都在宅邸内，但有一个例外。",
            ["ContentKR"] = "헨릭은 대부분의 시간을 저택에서 보낸대. 하지만 그래도 예외는 있지.",
            ["DialogueId"] = 101078111,
            ["GUID"] = "101078111",
            ["NextDialogue"] = 10107812,
            },
        [101078171] = {
            ["Content"] = "那就谢了。",
            ["ContentKR"] = "그럼 고맙지.",
            ["DialogueId"] = 101078171,
            ["GUID"] = "101078171.0",
            ["NextDialogue"] = 10107818,
            },
        [101089031] = {
            ["Content"] = "调查炉子",
            ["ContentKR"] = "난로를 조사한다.",
            ["DialogueId"] = 101089031,
            ["GUID"] = "194E7BE7",
            ["NextDialogue"] = 10130401,
            },
        [101089032] = {
            ["Content"] = "调查柜子上的日志",
            ["ContentKR"] = "캐비닛의 일지를 조사한다.",
            ["DialogueId"] = 101089032,
            ["GUID"] = "194E7BE8",
            ["NextDialogue"] = 10108918,
            },
        [101089041] = {
            ["Content"] = "调查柜子上的日志",
            ["ContentKR"] = "캐비닛의 일지를 조사한다.",
            ["DialogueId"] = 101089041,
            ["GUID"] = "194E7CB9",
            ["NextDialogue"] = 10108917,
            },
        [101089081] = {
            ["Content"] = "调查炉子",
            ["ContentKR"] = "난로를 조사한다.",
            ["DialogueId"] = 101089081,
            ["GUID"] = "194E7CBA",
            ["NextDialogue"] = 10130404,
            },
        [101131171] = {
            ["Content"] = "……好。 ",
            ["ContentKR"] = "...그래.",
            ["DialogueId"] = 101131171,
            ["GUID"] = "101131171",
            ["ImprPlusId"] = 1009,
            ["NextDialogue"] = 10113118,
            },
        [101131172] = {
            ["Content"] = "没事。我会好起来的……很快就会好起来的。 ",
            ["ContentKR"] = "괜찮아, 난 괜찮아질 거야... 곧 괜찮아질 거야. ",
            ["DialogueId"] = 101131172,
            ["GUID"] = "101131172",
            ["ImprPlusId"] = 1006,
            ["NextDialogue"] = 10113118,
            },
        [101131173] = {
            ["Content"] = "无能的人才会哭泣，我总有一天会让他们付出代价。",
            ["ContentKR"] = "눈물은 약한 사람이나 흘리는 거야. 언젠가 그들에게 대가를 치르게 할 거야.",
            ["DialogueId"] = 101131173,
            ["GUID"] = "101131173",
            ["ImprPlusId"] = 1010,
            ["NextDialogue"] = 10113118,
            },
        [101259011] = {
            ["Content"] = "你在做什么？",
            ["ContentKR"] = "뭐 하는 거죠?",
            ["DialogueId"] = 101259011,
            ["GUID"] = "101259011.0",
            ["NextDialogue"] = 10125902,
            },
        [101259012] = {
            ["Content"] = "你是谁？",
            ["ContentKR"] = "누구세요?",
            ["DialogueId"] = 101259012,
            ["GUID"] = "101259012.0",
            ["NextDialogue"] = 10125902,
            },
        [101259161] = {
            ["Content"] = "我很想念她。",
