            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_End",
                },
            },
        [120155051] = {
            ["Content"] = "不知道你在说什么……",
            ["ContentKR"] = "네가 무슨 얘길 하는 건지 모르겠는데...",
            ["DialogueId"] = 120155051,
            ["GUID"] = "120155051.0",
            ["NextDialogue"] = 12015507,
            },
        [120155052] = {
            ["Content"] = "扶疏也是百年之前的人？！",
            ["ContentKR"] = "부소도 백 년 전 사람이라고?!",
            ["DialogueId"] = 120155052,
            ["GUID"] = "120155052.0",
            ["NextDialogue"] = 12015509,
            },
        [120186141] = {
            ["Content"] = "他们也不是故意的。",
            ["ContentKR"] = "저 사람들도 일부러 그런 건 아니잖아요.",
            ["DialogueId"] = 120186141,
            ["GUID"] = "120186141.0",
            ["ImprPlusId"] = 1202,
            ["NextDialogue"] = 12018616,
            },
        [120186142] = {
            ["Content"] = "罚他们三天工资！",
            ["ContentKR"] = "3일 치 급여를 깎아 버리세요!",
            ["DialogueId"] = 120186142,
            ["GUID"] = "120186142.0",
            ["ImprPlusId"] = 1205,
            ["NextDialogue"] = 12018619,
            },
        [120193051] = {
            ["Content"] = "幸会幸会……原来华胥之外的地方，还有如此拉风的职业！相逢即是有缘，何不结伴一程？",
            ["ContentKR"] = "반갑다! 화서 밖에는 그렇게 멋진 직업도 있나 보군! 이렇게 만난 것도 인연인데, 나와 잠시 동행하겠느냐?",
            ["DialogueId"] = 120193051,
            ["GUID"] = "120193050",
            ["NextDialogue"] = 12019307,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120193/120193050",
            },
        [120193141] = {
            ["Content"] = "哦哦……！原来如此！难怪我以随身的枪戟剑林将此地翻来覆去轰了几遍，都没能撼动分毫……竟是要敲击这里。话说回来，这机枢派的造物可真结实。",
            ["ContentKR"] = "안녕.",
            ["DialogueId"] = 120193141,
            ["GUID"] = "1E16CD3A",
            ["NextDialogue"] = 12019316,
            ["VoiceName"] = "voice/$Locale$/story/1201/120193/1E16CD3A",
            },
        [120223281] = {
            ["Content"] = "我不想看着华胥陷入祸乱，我想看看有什么我能做的。",
            ["ContentKR"] = "난 화서가 재앙에 빠지는 걸 보고 싶지 않아. 내가 할 수 있는 일이 있는지 찾아보고 싶어.",
            ["DialogueId"] = 120223281,
            ["GUID"] = "120223281.0",
            ["ImprPlusId"] = 1204,
            ["NextDialogue"] = 12022329,
            },
        [120223282] = {
            ["Content"] = "今天实在是发生了太多事情，我只想回冰湖城……",
            ["ContentKR"] = "솔직히 오늘은 너무 많은 일이 일어나서, 그냥 아이스레이크 시티로 돌아가고 싶어...",
            ["DialogueId"] = 120223282,
            ["GUID"] = "120223282.0",
            ["ImprPlusId"] = 1201,
            ["NextDialogue"] = 12022329,
            },
        [120230021] = {
            ["Content"] = "感觉那个人有点可怜……",
            ["ContentKR"] = "그 사람, 좀 불쌍해 보이던데요...",
            ["DialogueId"] = 120230021,
            ["GUID"] = "120230021.0",
            ["ImprPlusId"] = 1204,
            ["NextDialogue"] = 12023003,
            },
        [120230022] = {
            ["Content"] = "虽然他的想法可能有错，但也不应该这样对待他。",
            ["ContentKR"] = "생각이 틀렸을지는 몰라도, 꼭 그렇게까지 대할 필요는 없었다고 봐요.",
            ["DialogueId"] = 120230022,
            ["GUID"] = "120230022.0",
            ["ImprPlusId"] = 1202,
            ["NextDialogue"] = 12023003,
            },
        [120230023] = {
            ["Content"] = "为了防止人心动摇，适当的手段也是应该的。",
            ["ContentKR"] = "사람들이 동요하지 않게 하려면, 적절한 조치도 필요하다고 생각해요.",
            ["DialogueId"] = 120230023,
            ["GUID"] = "120230023.0",
            ["ImprPlusId"] = 1201,
            ["NextDialogue"] = 12023003,
            },
        [120230024] = {
            ["Content"] = "做得好，就该这样！",
            ["ContentKR"] = "잘하셨어요, 그래야죠!",
            ["DialogueId"] = 120230024,
            ["GUID"] = "120230024.0",
            ["ImprPlusId"] = 1205,
            ["NextDialogue"] = 12023003,
            },
        [120233101] = {
            ["Content"] = "讲述经过",
            ["ContentKR"] = "경위를 설명한다.",
            ["DialogueId"] = 120233101,
            ["GUID"] = "120233101.0",
            ["NextDialogue"] = 12023311,
            },
        [120233131] = {
            ["Content"] = "试图辩解",
            ["ContentKR"] = "설명해 보려 한다.",
            ["DialogueId"] = 120233131,
            ["GUID"] = "120233131.0",
            ["NextDialogue"] = 12023314,
            },
        [120320101] = {
            ["DialogueId"] = 120320101,
            ["DisableMouth"] = 1,
            ["GUID"] = "120320101.0",
