            ["DialogueId"] = 200006152,
            ["GUID"] = "200006152",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 20000618,
            },
        [200008091] = {
            ["Content"] = "（留意到她有些无精打采——她好像有什么心事。）",
            ["ContentKR"] = "(프시케가 기운 없어 보인다. 무슨 고민이 있는 것 같은데.)",
            ["DialogueId"] = 200008091,
            ["GUID"] = "200008091",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 20000810,
            },
        [200008092] = {
            ["Content"] = "（留意到她刚才在照看的花——她刚才似乎就是对着这些花叹气。）",
            ["ContentKR"] = "(프시케가 아까 돌보던 꽃에 주목한다 - 아까 그 꽃을 보며 한숨 쉬는 것 같았는데.)",
            ["DialogueId"] = 200008092,
            ["GUID"] = "200008092.0",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 20000811,
            },
        [200008093] = {
            ["Content"] = "一般来说休息没什么用，出去找点乐子就精神了。",
            ["ContentKR"] = "보통 쉰다고 해결되는 게 아니야. 밖에 나가서 즐겁게 놀면 기운 나.",
            ["DialogueId"] = 200008093,
            ["GUID"] = "200008093.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 20000812,
            },
        [200008161] = {
