        [200071012] = {
            ["Content"] = "做魔灵学者的感觉如何？",
            ["ContentKR"] = "마령 학자가 된 소감이 어때?",
            ["DialogueId"] = 200071012,
            ["GUID"] = "200071012",
            ["NextDialogue"] = 20007105,
            },
        [200071013] = {
            ["Content"] = "没什么事。",
            ["ContentKR"] = "아무것도 아니야.",
            ["DialogueId"] = 200071013,
            ["GUID"] = "200071013",
            },
        [510001041] = {
            ["Content"] = "啊啊啊！我喝！让我自己来！",
            ["ContentKR"] = "으아아! 먹을게요! 혼자 먹을 수 있어요!",
            ["DialogueId"] = 510001041,
            ["GUID"] = "510001041.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51000105,
            },
        [510001042] = {
            ["Content"] = "（灵巧地闪开——你并不信任陌生人过分的热情。）",
            ["ContentKR"] = "(재빨리 피한다. 낯선 사람의 지나친 호의를 믿지 않는다.)",
            ["DialogueId"] = 510001042,
            ["GUID"] = "510001042.0",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51000107,
            },
        [510001101] = {
            ["Content"] = "您口中的“夫人”生了病？",
            ["ContentKR"] = "말씀하시는 '마님'께서 병에 걸리셨나요?",
            ["DialogueId"] = 510001101,
            ["GUID"] = "510001101",
            ["NextDialogue"] = 51000111,
            },
        [510003021] = {
            ["Content"] = "（留意到她的衣服布料颇为华贵。）",
            ["ContentKR"] = "(옷감이 꽤 고급스러워 보인다.)",
            ["DialogueId"] = 510003021,
            ["GUID"] = "510003021.0",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51000303,
            },
        [510003022] = {
            ["Content"] = "（留意到她似乎在找什么人。）",
            ["ContentKR"] = "(누군가를 찾고 있는 것 같다.)",
            ["DialogueId"] = 510003022,
            ["GUID"] = "510003022.0",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51000304,
            },
        [510003023] = {
            ["Content"] = "（留意到她很悲伤。）",
            ["ContentKR"] = "(매우 슬퍼 보인다.)",
            ["DialogueId"] = 510003023,
            ["GUID"] = "510003023.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51000305,
            },
        [510003051] = {
            ["Content"] = "（也许可以帮上什么忙。）",
            ["ContentKR"] = "(도움을 줄 수 있을지도 몰라.)",
            ["DialogueId"] = 510003051,
            ["GUID"] = "510003051.0",
            ["NextDialogue"] = 510003052,
            },
        [510003052] = {
            ["Content"] = "（也许可以帮上什么忙。）",
            ["ContentKR"] = "(도움을 줄 수 있을지도 몰라.)",
            ["DialogueId"] = 510003052,
            ["GUID"] = "510003052.0",
            ["NextOptions"] = {
                [1] = 510003054,
                [2] = 510003055,
                [3] = 510003056,
                },
            ["SpeakNpcId"] = 100001,
            ["bForbidSkipOptions"] = true,
            },
        [510003053] = {
            ["Content"] = "（离开。）",
            ["ContentKR"] = "(떠난다.)",
            ["DialogueId"] = 510003053,
            ["GUID"] = "510003053.0",
            ["Scripts"] = "SetOutport{FinishType{\"Fail\"}}",
            },
        [510003054] = {
            ["Content"] = "（询问她是不是遇到了什么烦心事。付一些报酬的话，可以考虑帮忙解决。）",
            ["ContentKR"] = "(무슨 고민거리가 있는지 물어본다. 또 보수를 지불한다면, 해결해 줄 수도 있다고 말한다.)",
            ["DialogueId"] = 510003054,
            ["FailDialogue"] = 51000306,
            ["GUID"] = "510003054.0",
            ["ImprCheckId"] = 1001,
            ["NextDialogue"] = 51000307,
            },
        [510003055] = {
            ["Content"] = "（询问她是否在找什么人，也许日后出城的时候可以帮她留意一下。）",
            ["ContentKR"] = "(찾는 사람이 있는지 물어보고, 나중에 성 밖으로 나갈 때 염두에 두겠다고 말한다.)",
            ["DialogueId"] = 510003055,
            ["FailDialogue"] = 51000306,
            ["GUID"] = "510003055.0",
            ["ImprCheckId"] = 1002,
            ["NextDialogue"] = 51000307,
            },
        [510003056] = {
            ["Content"] = "（询问她是不是有什么困难，或许能提供一些帮助。）",
            ["ContentKR"] = "(곤란한 일이 생겼는지 묻는다. 도움을 줄 수 있을 것 같다고 말한다.)",
            ["DialogueId"] = 510003056,
            ["FailDialogue"] = 51000306,
            ["GUID"] = "510003056.0",
            ["ImprCheckId"] = 1003,
            ["NextDialogue"] = 51000307,
            },
        [510003111] = {
            ["Content"] = "对此没有印象。",
            ["ContentKR"] = "본 기억이 없어요.",
            ["DialogueId"] = 510003111,
            ["GUID"] = "510003111.0",
            ["NextDialogue"] = 51000312,
            },
        [510004031] = {
            ["Content"] = "那个……{性别：我是男的。|我不是你的女儿。}",
            ["ContentKR"] = "에... {性别:저는 남자인데요. |저는 아줌마 딸이 아닌데요.}",
            ["DialogueId"] = 510004031,
            ["GUID"] = "510004031.0",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51000490,
            },
        [510004032] = {
            ["Content"] = "冷静一下。你在找人？我会帮你留意。",
            ["ContentKR"] = "진정하세요. 혹시 사람을 찾으시나요? 제가 알아봐 드릴게요.",
            ["DialogueId"] = 510004032,
            ["GUID"] = "510004032.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51000490,
            },
        [510004033] = {
            ["Content"] = "妈！！！",
            ["ContentKR"] = "엄마!!!",
            ["DialogueId"] = 510004033,
            ["GUID"] = "510004033.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51000404,
            },
        [510004071] = {
            ["Content"] = "（接受）",
            ["ContentKR"] = "(수락)",
            ["DialogueId"] = 510004071,
            ["GUID"] = "510004071.0",
            ["NextDialogue"] = 51000408,
            },
        [510004921] = {
            ["Content"] = "请好好回想一下你女儿的特征与失踪的经过，这样我才能确定能否帮到你。",
            ["ContentKR"] = "따님의 특징과 실종 경위를 자세히 얘기해 주세요. 그래야 도와드릴 수 있는지 알 수 있으니까요.",
            ["DialogueId"] = 510004921,
            ["FailDialogue"] = 51000405,
            ["GUID"] = "510004921.0",
            ["ImprCheckId"] = 1007,
            ["NextDialogue"] = 51000406,
            },
        [510005011] = {
            ["Content"] = "爱尔莎，我有了安妮的消息……",
            ["ContentKR"] = "엘사, 애니의 소식을 가져왔어요...",
            ["DialogueId"] = 510005011,
            ["GUID"] = "510005011.0",
            ["NextDialogue"] = 51000502,
            },
        [510005021] = {
            ["Content"] = "请您节哀，安妮已经去世了……在她生命的最后，她帮助另一个女孩活了下来，她的善良值得被铭记。",
            ["ContentKR"] = "삼가 조의를 표합니다. 비록 애니는 세상을 떠났지만... 생명이 다 하는 순간에도 함께 있던 다른 여자아이를 구해냈어요. 애니의 선량함은 모두에게 기억될 거예요.",
            ["DialogueId"] = 510005021,
            ["GUID"] = "510005021.0",
            ["NextDialogue"] = 51000503,
            },
        [510006011] = {
            ["Content"] = "爱尔莎，我有了安妮的消息……",
            ["ContentKR"] = "엘사, 당신 딸을 찾았어요.",
            ["DialogueId"] = 510006011,
            ["GUID"] = "510006011.0",
            ["NextDialogue"] = 51000602,
            },
        [510007011] = {
            ["Content"] = "你一直在这里徘徊，有什么能帮你的吗？",
            ["ContentKR"] = "계속 여기서 서성이고 있던데, 도움이 필요하니?",
            ["DialogueId"] = 510007011,
            ["GUID"] = "510007011.0",
            ["NextDialogue"] = 51000702,
            },
        [510007031] = {
            ["Content"] = "我理解你的迷茫，失去归属感的确很糟。",
            ["ContentKR"] = "네가 혼란스러운 건 이해해. 돌아갈 곳을 잃는 기분은 정말 좋지 않거든.",
            ["DialogueId"] = 510007031,
            ["GUID"] = "510007031.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51000705,
            },
        [510007032] = {
            ["Content"] = "滞留在外并不安全，还是尽早弄清你的真实身份为妙。",
            ["ContentKR"] = "혼자서 밖에 돌아다니는 건 안전하지 않아. 최대한 빨리 자신이 누군지 알아내는 게 좋을 것 같아.",
            ["DialogueId"] = 510007032,
            ["GUID"] = "510007032.0",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 51000705,
            },
        [510007033] = {
            ["Content"] = "眼见不一定为实。一切都需要调查后才能得出结论。",
            ["ContentKR"] = "눈에 보이는 것이 꼭 진실이라는 법은 없어. 무엇이든 잘 확인해 봐야 결론을 낼 수 있지.",
            ["DialogueId"] = 510007033,
            ["GUID"] = "510007033.0",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51000705,
            },
        [510007051] = {
            ["Content"] = "（接受）",
            ["ContentKR"] = "(수락)",
            ["DialogueId"] = 510007051,
            ["GUID"] = "510007051.0",
            ["NextDialogue"] = 51000706,
            },
        [510008121] = {
            ["Content"] = "（不展示爱丽丝的日记）",
            ["ContentKR"] = "(앨리스의 일기를 보여주지 않는다)",
            ["DialogueId"] = 510008121,
            ["GUID"] = "510008121.0",
            ["NextDialogue"] = 51000813,
            ["Scripts"] = "SetOutport{FinishType{2},OptionIdx{2}}",
            },
        [510008141] = {
            ["Content"] = "正是你母亲托我来寻找你，我会带你去见她。",
            ["ContentKR"] = "맞아, 바로 네 어머니가 널 찾아달라고 의뢰했어. 어머니한테 데려다줄게.",
            ["DialogueId"] = 510008141,
            ["GUID"] = "510008141.0",
            ["NextDialogue"] = 51000814,
            },
        [510008921] = {
            ["Content"] = "（展示爱丽丝的日记）",
            ["ContentKR"] = "(앨리스의 일기를 보여준다)",
            ["DialogueId"] = 510008921,
            ["GUID"] = "510008921.0",
            ["NextDialogue"] = 51000803,
            ["Scripts"] = "SetOutport{FinishType{2},OptionIdx{1}}",
            },
        [510009031] = {
            ["Content"] = "我只看到了一些破烂，据我估价，他们不会比几块石头更有价值。",
            ["ContentKR"] = "싸구려만 보이는데. 아무리 잘 쳐줘도 돌멩이 몇 개만도 못하겠는걸.",
            ["DialogueId"] = 510009031,
            ["GUID"] = "510009031.0",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51000904,
            },
        [510009032] = {
            ["Content"] = "不问自取的行为还是少做为妙。",
            ["ContentKR"] = "물건을 훔치는 짓은 안 하는 게 좋을 텐데.",
            ["DialogueId"] = 510009032,
            ["GUID"] = "510009032.0",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 51000905,
            },
        [510009033] = {
            ["Content"] = "从哪儿摸的！带我一个！",
            ["ContentKR"] = "어디서 난 건데? 나도 끼워줘!",
            ["DialogueId"] = 510009033,
            ["GUID"] = "510009033.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51000906,
            },
        [510009071] = {
            ["Content"] = "很可惜，这里没有我需要的商品。",
            ["ContentKR"] = "아쉽지만 여기엔 나한테 필요한 물건이 없네.",
            ["DialogueId"] = 510009071,
            ["GUID"] = "510009071.0",
            ["NextDialogue"] = 51000907,
            },
        [510009072] = {
            ["Content"] = "（他仔仔细细地打量着你，露出了一个深思的表情）",
            ["ContentKR"] = "(그는 당신을 훑어보며 깊은 생각에 잠긴 듯 한 표정을 지었다.)",
            ["DialogueId"] = 510009072,
            ["GUID"] = "510009072.0",
            ["ImprCheckId"] = 1004,
            ["NextDialogue"] = 51000909,
            },
        [510009101] = {
            ["Content"] = "我听说有人可以提供一部分价格低廉的燃料与布匹，这让不少穷人能安然渡过隆冬。",
            ["ContentKR"] = "저렴한 연료와 옷감을 제공하는 사람이 있어서 많은 가난한 사람들이 겨울을 편안하게 보낼 수 있었다고 들었어.",
            ["DialogueId"] = 510009101,
            ["GUID"] = "510009101.0",
            ["ImprPlusId"] = 1002,
            },
        [510009102] = {
            ["Content"] = "你售卖情报，但你看起来不像个私家侦探，难道你有特别的情报来源？",
            ["ContentKR"] = "정보를 팔긴 하지만 사립탐정처럼 보이진 않는데, 특별한 정보원이라도 있는 건가?",
            ["DialogueId"] = 510009102,
            ["GUID"] = "510009102.0",
            ["ImprPlusId"] = 1003,
            },
        [510009103] = {
            ["Content"] = "我已经听你说过三遍马丁了，你到底谁啊？",
            ["ContentKR"] = "벌써 마틴이라는 이름을 세 번이나 들었는데, 진짜 뭐 하는 사람이야?",
            ["DialogueId"] = 510009103,
            ["GUID"] = "510009103.0",
            ["ImprPlusId"] = 1005,
            },
        [510009121] = {
            ["Content"] = "真有那么神奇吗？",
            ["ContentKR"] = "그 정도로 신기해?",
            ["DialogueId"] = 510009121,
            ["GUID"] = "510009121",
            },
        [510009161] = {
            ["Content"] = "（接受）",
            ["ContentKR"] = "(수락)",
            ["DialogueId"] = 510009161,
            ["GUID"] = "510009161.0",
            },
        [510010071] = {
            ["Content"] = "你丢了一样东西。这件东西证明了你不过也是个和他一样的窝棚板富豪。",
            ["ContentKR"] = "네가 잃어버린 물건이야. 이걸 보니 너도 방금 그 사람과 다를 바 없어 보이는데.",
            ["DialogueId"] = 510010071,
            ["GUID"] = "510010071.0",
            ["ImprCheckId"] = 1005,
            ["NextDialogue"] = 51001008,
            },
        [510010072] = {
            ["Content"] = "你丢了一样东西。通常来说，过期车票应该销毁以防模仿造假，而私藏显然是个违规行为。",
            ["ContentKR"] = "네가 잃어버린 물건이야. 만료된 티켓은 통상적으로 위조 방지를 위해 폐기해야 하지. 개인적으로 보관하는 건 엄연한 위법 행위고.",
            ["DialogueId"] = 510010072,
            ["GUID"] = "510010072.0",
            ["ImprCheckId"] = 1006,
            ["NextDialogue"] = 51001008,
            },
        [510010101] = {
            ["Content"] = "传说星星有实现愿望的能力，你用车票叠了上百颗星星，又想实现什么样的愿望呢？",
            ["ContentKR"] = "별은 소원을 들어주는 능력이 있다고 하던데, 어떤 소원을 빌려고 승차권으로 별을 수백 개나 접은 거야?",
            ["DialogueId"] = 510010101,
            ["GUID"] = "510010101.0",
            },
        [510010181] = {
            ["Content"] = "我理解你的不甘与悲痛，人生总有不如意的时候，但现在无法跨越的天堑也许终有一天会成为坦途。",
            ["ContentKR"] = "네가 억울하고 슬픈 건 나도 이해해, 인생은 뜻대로 되지 않을 때가 생기기 마련이니까. 하지만 지금 힘들어 보이는 것도 나중에는 쉬워질지도 몰라.",
            ["DialogueId"] = 510010181,
            ["GUID"] = "510010181.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51001019,
            },
        [510010182] = {
            ["Content"] = "不论如何，刚才的先生都不应该被你这么羞辱，恕我难以苟同你把怒火发泄到别人身上的行为。",
            ["ContentKR"] = "이유야 어찌 되었건, 방금처럼 그분을 모욕하는 건 정당하지 못해. 분노를 애먼 사람에게 푸는 건 이해하기 힘든 걸.",
            ["DialogueId"] = 510010182,
            ["GUID"] = "510010182.0",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 51001020,
            },
        [510010183] = {
            ["Content"] = "不管你怎么想，要是不想摊上事，你就该把这东西收回去，妥善保存也罢，销毁也好，那是你的问题。",
            ["ContentKR"] = "네가 어떻게 생각하든, 일이 복잡해지는 걸 원하지 않는다면 가져가서 잘 보관하든가 없애 버리든가 알아서 하라고.",
            ["DialogueId"] = 510010183,
            ["GUID"] = "510010183.0",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51001021,
            },
        [510010184] = {
            ["Content"] = "你干嘛不扒在车顶坐个来回过过瘾？",
            ["ContentKR"] = "지붕 위에 앉아서 왔다 갔다 하며 기분전환 하는 건 어때?",
            ["DialogueId"] = 510010184,
            ["GUID"] = "510010184.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51001022,
            },
        [510012011] = {
            ["Content"] = "那些鸟都是你养的吗？",
            ["ContentKR"] = "여기 있는 새들은 전부 당신이 기른 건가요?",
            ["DialogueId"] = 510012011,
            ["GUID"] = "510012011.0",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51001202,
            },
        [510012012] = {
            ["Content"] = "那些鸟飞得太高了，不然今天还能加顿餐。",
            ["ContentKR"] = "새들이 너무 높이 나네요. 안 그러면 오늘 야식 메뉴가 될 수 있을 텐데요.",
            ["DialogueId"] = 510012012,
            ["GUID"] = "510012012.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51001203,
            },
        [510012041] = {
            ["Content"] = "（回忆你从书本上看到的金翎鸟的知识——它们的习性，以及为什么它们可以成为探测工具。）",
            ["ContentKR"] = "(책에서 봤던 금령조의 습성과 금령조가 탐지 수단이 된 원인을 떠올린다.)",
            ["DialogueId"] = 510012041,
            ["GUID"] = "510012041.0",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51001205,
            },
        [510012042] = {
            ["Content"] = "（附和面前这位矿工，批判人们对传统的遗弃。）",
            ["ContentKR"] = "(앞에 있는 광부를 따라 전통을 버린 사람들을 비판한다.)",
            ["DialogueId"] = 510012042,
            ["GUID"] = "510012042.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51001206,
            },
        [510012043] = {
            ["Content"] = "（向面前这位矿工赞扬技术发展能让人类社会更高效地运转。）",
            ["ContentKR"] = "(눈앞의 광부에게 인류 사회가 더 효율적으로 작동하게 한 기술 발전을 칭찬한다.)",
            ["DialogueId"] = 510012043,
            ["GUID"] = "510012043.0",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51001207,
            },
        [510013011] = {
            ["Content"] = "你不能这样侮辱一位受尊敬的女士。",
            ["ContentKR"] = "사람들이 존경하는 사람을 그렇게 욕하면 안 되지.",
            ["DialogueId"] = 510013011,
            ["GUID"] = "510013011.0",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 51001302,
            },
        [510013012] = {
            ["Content"] = "（上去就是一拳）",
            ["ContentKR"] = "(바로 주먹을 날린다.)",
            ["DialogueId"] = 510013012,
            ["GUID"] = "510013012.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51001303,
            },
        [510013013] = {
            ["Content"] = "给她点面子就敢蹬鼻子上脸，还说什么看不上老子的酒，老子早晚让她吃不了兜着走！",
            ["ContentKR"] = "체면 좀 살려 줬더니 끝도 없이 콧대를 세우네. 뭐? 내 술이 맘에 안 들어? 내가 꼭 후회하게 만든다!",
            ["DialogueId"] = 510013013,
            ["GUID"] = "510013013",
            ["NextOptions"] = {
                [1] = 510013011,
                [2] = 510013012,
                },
            ["SpeakNpcId"] = 700014,
            ["bForbidSkipOptions"] = true,
            },
        [510013041] = {
            ["Content"] = "不，卡米拉是一位值得信赖的朋友，她帮过我忙。",
            ["ContentKR"] = "아니, 카밀라는 믿을 만한 친구야. 날 도와준 적도 있거든.",
            ["DialogueId"] = 510013041,
            ["FailDialogue"] = 51001305,
            ["GUID"] = "510013041.0",
            ["ImprCheckId"] = 1008,
            ["NextDialogue"] = 51001306,
            },
        [510013042] = {
            ["Content"] = "你不用多费唇舌，卡米拉为人怎么样，我相信自己的判断。",
            ["ContentKR"] = "카밀라가 어떤 사람인지는 내가 판단하니까 쓸데없는 말 하지 마.",
            ["DialogueId"] = 510013042,
            ["FailDialogue"] = 51001305,
            ["GUID"] = "510013042.0",
            ["ImprCheckId"] = 1009,
            ["NextDialogue"] = 51001306,
            },
        [510013043] = {
            ["Content"] = "所以你是向卡米拉推销酒水不成，着急了。",
            ["ContentKR"] = "그러니까, 카밀라한테 술을 못 팔아서 안달이 난 거구나.",
            ["DialogueId"] = 510013043,
            ["FailDialogue"] = 51001305,
            ["GUID"] = "510013043.0",
            ["ImprCheckId"] = 1010,
            ["NextDialogue"] = 51001306,
            },
        [510013061] = {
            ["Content"] = "嗯，咳，听口音你不是本地人吧。我猜，自从来到冰湖城，你就没去水仙平原之外的地方喝过吧？",
            ["ContentKR"] = "크흠, 말투를 보아하니 이 지역 출신은 아닌 것 같은데, 그럼 아이스레이크 시티에서 온 이후로 아스포델 외의 곳에서 마셔본 적은 없는 거지?",
            ["DialogueId"] = 510013061,
            ["GUID"] = "510013061.0",
            ["SpeakNpcId"] = 700014,
            },
        [510013062] = {
            ["Content"] = "那又如何？",
            ["ContentKR"] = "그렇다면?",
            ["DialogueId"] = 510013062,
            ["GUID"] = "510013062",
            },
        [510013091] = {
            ["Content"] = "好吧，来一桶。",
            ["ContentKR"] = "좋아, 한 통만 줘.",
            ["DialogueId"] = 510013091,
            ["GUID"] = "510013091.0",
            ["NextDialogue"] = 51001310,
            },
        [510013092] = {
            ["Content"] = "便宜没好货。",
            ["ContentKR"] = "싼 게 비지떡이지. 됐어.",
            ["DialogueId"] = 510013092,
            ["GUID"] = "510013092.0",
            ["NextDialogue"] = 51001313,
            },
        [510013231] = {
            ["Content"] = "抢生意也就算了，万一假酒把人喝出毛病怎么办？",
            ["ContentKR"] = "부당한 호객 행위는 그렇다 치더라도 가짜 술을 먹고 누가 탈이라도 나면 어쩌려고?",
            ["DialogueId"] = 510013231,
            ["GUID"] = "510013231.0",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 51001324,
            },
        [510013232] = {
            ["Content"] = "就是！还怕她一张嘴！兄弟你喝一桶看看实力！",
            ["ContentKR"] = "그래! 저 말에 겁먹지 마! 한 통 쭉 마셔서 네 실력을 보여 줘!",
            ["DialogueId"] = 510013232,
            ["GUID"] = "510013232.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51001326,
            },
        [510013281] = {
            ["Content"] = "假货害人啊……",
            ["ContentKR"] = "가짜 술이 사람을 잡네요...",
            ["DialogueId"] = 510013281,
            ["GUID"] = "510013281.0",
            ["NextDialogue"] = 51001329,
            },
        [510014021] = {
            ["Content"] = "孩子本就是天生通透的诗人。",
            ["ContentKR"] = "아이들이야말로 타고난 시인이죠.",
            ["DialogueId"] = 510014021,
            ["GUID"] = "510014021.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51001403,
            },
        [510014022] = {
            ["Content"] = "你看起来非常为他们自豪。",
            ["ContentKR"] = "그들을 엄청 자랑스럽게 생각하는 것 같네요.",
            ["DialogueId"] = 510014022,
            ["GUID"] = "510014022.0",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51001403,
            },
        [510014023] = {
            ["Content"] = "可恶，原来我输在了起跑线上。",
            ["ContentKR"] = "젠장, 처음부터 제가 진 거였군요.",
            ["DialogueId"] = 510014023,
            ["GUID"] = "510014023.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51001403,
            },
        [510014061] = {
            ["Content"] = "才不是呢，你教会了孩子可贵的纯真与浪漫。",
            ["ContentKR"] = "그렇지 않아요. 당신은 아이들에게 순수함과 낭만을 가르치잖아요.",
            ["DialogueId"] = 510014061,
            ["FailDialogue"] = 51001407,
            ["GUID"] = "510014061.0",
            ["ImprCheckId"] = 1011,
            ["NextDialogue"] = 51001409,
            },
        [510014901] = {
            ["Content"] = "你看起来在和孩子们的相处中收获了很多。",
            ["ContentKR"] = "아이들과 함께 지내면서 많은 것을 얻은 모양이네요.",
            ["DialogueId"] = 510014901,
            ["GUID"] = "510014901.0",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51001412,
            },
        [510014902] = {
            ["Content"] = "为这些孩子们做出牺牲，真的是值得的吗？",
            ["ContentKR"] = "이 아이들을 위해 희생하는 게 정말 의미가 있을까요?",
            ["DialogueId"] = 510014902,
            ["GUID"] = "510014902.0",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51001412,
            },
        [510015021] = {
            ["Content"] = "用清洁剂泡一泡再擦？",
            ["ContentKR"] = "세제를 사용해서 닦는 게 어때?",
            ["DialogueId"] = 510015021,
            ["GUID"] = "510015021.0",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51001503,
            },
        [510015022] = {
            ["Content"] = "你付钱给我，我给你擦。",
            ["ContentKR"] = "돈 주면 내가 대신 해줄게.",
            ["DialogueId"] = 510015022,
            ["GUID"] = "510015022.0",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51001503,
            },
        [510015023] = {
            ["Content"] = "挨打挨骂是好事，有助于锻炼精神。",
            ["ContentKR"] = "매를 맞고 혼나는 건 좋은 일이야. 정신력을 단련하는 데 도움이 되거든.",
            ["DialogueId"] = 510015023,
            ["GUID"] = "510015023.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51001503,
            },
        [510015071] = {
            ["Content"] = "你不觉得说这种话太冷漠了吗？",
            ["ContentKR"] = "방금 그 말은 너무 심한 거 아니야?",
            ["DialogueId"] = 510015071,
            ["GUID"] = "510015071.0",
            ["ImprCheckId"] = 1012,
            ["NextDialogue"] = 51001509,
            },
        [510016021] = {
            ["Content"] = "（此人脾气有点暴躁，摸一摸他的恶魔角安抚下吧。）",
            ["ContentKR"] = "(성질이 포악한 것 같다. 악마 뿔을 만져 달래야 할 것 같다.)",
            ["DialogueId"] = 510016021,
            ["GUID"] = "510016021.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51001603,
            },
        [510016022] = {
            ["Content"] = "卡戎和索拉是平等的。你不该心存偏见。",
            ["ContentKR"] = "카론과 솔라는 평등해요. 편견을 가져서는 안 돼요.",
            ["DialogueId"] = 510016022,
            ["GUID"] = "510016022.0",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 51001605,
            },
        [510016023] = {
            ["Content"] = "可是你也是个卡戎啊……？",
            ["ContentKR"] = "하지만 당신도 카론이잖아요...?",
            ["DialogueId"] = 510016023,
            ["GUID"] = "510016023.0",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51001607,
            },
        [510016121] = {
            ["Content"] = "我可以看看您的“桂冠卡戎”奖章吗？",
            ["ContentKR"] = "'계관카론' 훈장을 좀 볼 수 있을까요?",
            ["DialogueId"] = 510016121,
            ["FailDialogue"] = 51001690,
            ["GUID"] = "510016121.0",
            ["ImprCheckId"] = 1013,
            ["NextDialogue"] = 51001613,
            },
        [510017031] = {
            ["Content"] = "（真诚建议他注意个人卫生问题）",
            ["ContentKR"] = "(개인위생에 주의할 것을 신신당부한다)",
            ["DialogueId"] = 510017031,
            ["GUID"] = "510017031.0",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51001704,
            },
        [510017032] = {
            ["Content"] = "（为自己刚才失礼的动作道歉）",
            ["ContentKR"] = "(실례를 범한 것에 대해 사과한다)",
            ["DialogueId"] = 510017032,
            ["GUID"] = "510017032.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51001704,
            },
        [510017033] = {
            ["Content"] = "（指责他的味道过于腥臭有恶劣影响）",
            ["ContentKR"] = "(악취와 그로 인한 악영향에 대해 비난한다)",
            ["DialogueId"] = 510017033,
            ["GUID"] = "510017033.0",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 51001704,
            },
        [510017081] = {
            ["Content"] = "一个本该救死扶伤的人不应该来修理下水道。",
            ["ContentKR"] = "생명을 구해야 할 사람이 하수도를 고치고 있으면 안 되죠.",
            ["DialogueId"] = 510017081,
            ["FailDialogue"] = 51001709,
            ["GUID"] = "510017081.0",
            ["ImprCheckId"] = 1014,
            ["NextDialogue"] = 51001711,
            },
        [510017161] = {
            ["Content"] = "如果再给你的人生重来一次的机会，你还会救他吗？",
            ["ContentKR"] = "인생을 다시 시작할 기회가 주어진다면, 다시 그 사람을 구할 건가요?",
            ["DialogueId"] = 510017161,
            ["GUID"] = "510017161.0",
            ["NextDialogue"] = 51001717,
            },
        [510018011] = {
            ["Content"] = "（接受）",
            ["ContentKR"] = "(수락)",
            ["DialogueId"] = 510018011,
            ["GUID"] = "510018011.0",
            ["NextDialogue"] = 51001802,
            },
        [510018012] = {
            ["Content"] = "（拒绝）",
            ["ContentKR"] = "(거절)",
            ["DialogueId"] = 510018012,
            ["GUID"] = "510018012.0",
            ["Scripts"] = "SetOutport{FinishType{\"Fail\"}}",
            },
        [510019231] = {
            ["Content"] = "这裂纹的形状……原来如此，它替威尔斯先生挡下了胸口的致命伤啊。",
            ["ContentKR"] = "이 균열 모양은...그런 거였군요, 웨일즈 씨의 가슴팍의 치명상을 막아준 거네요.",
            ["DialogueId"] = 510019231,
            ["GUID"] = "510019231.0",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51001924,
            },
        [510019232] = {
            ["Content"] = "……威尔斯先生就算过得再怎么惨，也不该去偷别人的怀表吧。",
            ["ContentKR"] = "...웨일즈 씨, 아무리 가난해도 남의 시계를 훔치는 건 좀 그렇지 않아요?",
            ["DialogueId"] = 510019232,
            ["GUID"] = "510019232.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51001924,
            },
        [510019911] = {
            ["Content"] = "威尔斯先生没你说的不堪，别太过分了。",
            ["ContentKR"] = "말씀이 지나치시군요, 웨일즈 씨는 당신이 말한 것처럼 형편없지 않아요.",
            ["DialogueId"] = 510019911,
            ["FailDialogue"] = 51001916,
            ["GUID"] = "510019911.0",
            ["ImprCheckId"] = 1015,
            ["NextDialogue"] = 51001918,
            },
        [510019912] = {
            ["Content"] = "桂冠卡戎对我们没有任何吸引力，别拿你浅薄的认知定义所有人。",
            ["ContentKR"] = "계관카론은 우리에게 있어 전혀 구미가 당기지 않는걸요. 자신의 기준으로 남을 판단하지 말라고요.",
            ["DialogueId"] = 510019912,
            ["FailDialogue"] = 51001916,
            ["GUID"] = "510019912.0",
            ["ImprCheckId"] = 1016,
            ["NextDialogue"] = 51001918,
            },
        [510019913] = {
            ["Content"] = "嘴巴放干净点。不然今天像狗一样被打一顿的，就是另一个“威尔斯先生”了。",
            ["ContentKR"] = "말 조심해 영감. 안 그럼 오늘 개처럼 두들겨 맞는 건 또 다른 '웨일즈 씨'가 될 테니까.",
            ["DialogueId"] = 510019913,
            ["FailDialogue"] = 51001916,
            ["GUID"] = "510019913.0",
            ["ImprCheckId"] = 1017,
            ["NextDialogue"] = 51001918,
            },
        [510020031] = {
            ["Content"] = "为什么你不自己去寻宝呢？",
            ["ContentKR"] = "직접 보물을 찾으러 가지 그래요?",
            ["DialogueId"] = 510020031,
            ["GUID"] = "510020031.0",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51002004,
            },
        [510020032] = {
            ["Content"] = "稍微介绍一下这个宝藏？",
            ["ContentKR"] = "어떤 보물인지 말해줄래요?",
            ["DialogueId"] = 510020032,
            ["GUID"] = "510020032.0",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51002006,
            },
        [510020033] = {
            ["Content"] = "你是不是在骗人啊……",
            ["ContentKR"] = "사기 치는 건 아니죠...?",
            ["DialogueId"] = 510020033,
            ["GUID"] = "510020033.0",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 51002008,
            },
        [510020131] = {
            ["Content"] = "我总觉得你说的这个南方海岛很耳熟。",
            ["ContentKR"] = "말씀하신 남쪽 섬이 왠지 익숙하네요.",
            ["DialogueId"] = 510020131,
            ["FailDialogue"] = 51002014,
            ["GUID"] = "510020131.0",
            ["ImprCheckId"] = 1018,
            ["NextDialogue"] = 51002016,
            },
        [510023011] = {
            ["Content"] = "哈默尔·狄金森……我好像看到过这个名字……",
            ["ContentKR"] = "하멜 디킨슨... 들어본 이름인 것 같은데...",
            ["DialogueId"] = 510023011,
            ["GUID"] = "510023011.0",
            ["NextDialogue"] = 51002302,
            },
        [510023041] = {
            ["Content"] = "（交出在矿坑中得到的日记）",
            ["ContentKR"] = "(광갱에서 얻은 일기장을 건네준다.)",
            ["DialogueId"] = 510023041,
            ["GUID"] = "510023041.0",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 51002305,
            ["Scripts"] = "SetOutport{FinishType{2},OptionIdx{1}}",
            },
        [510023042] = {
            ["Content"] = "（隐瞒在矿坑中得到的日记）",
            ["ContentKR"] = "(광산에서 발견한 일기 내용을 숨긴다)",
            ["DialogueId"] = 510023042,
            ["GUID"] = "510023042.0",
            ["ImprPlusId"] = 1016,
            ["NextDialogue"] = 51002312,
            ["Scripts"] = "SetOutport{FinishType{2},OptionIdx{2}}",
            },
        [510024031] = {
            ["Content"] = "可以告诉我哈默尔的事情吗？",
            ["ContentKR"] = "하멜에 대해 이야기해 주실 수 있나요?",
            ["DialogueId"] = 510024031,
            ["GUID"] = "510024031.0",
            ["NextDialogue"] = 51002432,
            },
        [510024141] = {
            ["Content"] = "但是哈默尔爽约了？",
            ["ContentKR"] = "그런데 하멜이 약속을 어겼나요?",
            ["DialogueId"] = 510024141,
            ["GUID"] = "510024141.0",
            ["NextDialogue"] = 51002415,
            },
        [510025021] = {
            ["Content"] = "我虽然不买，但分我一半报酬的话，可以帮你找找买家。",
            ["ContentKR"] = "살 생각은 없지만, 제게도 값만 치른다면 구매자를 알아봐 줄게요.",
            ["DialogueId"] = 510025021,
            ["GUID"] = "510025021.0",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51002505,
            },
        [510025022] = {
            ["Content"] = "你需要什么帮助吗？",
            ["ContentKR"] = "도움이 필요한가요?",
            ["DialogueId"] = 510025022,
            ["GUID"] = "510025022.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51002505,
            },
        [510025023] = {
            ["Content"] = "帝国肯定不会允许你干这种事，不想惹麻烦的话就快走吧。",
