            ["GUID"] = "510033052.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 510033054,
            },
        [510033053] = {
            ["Content"] = "托您的福，食物和燃料，我总能得到其中一个，人生就是一场取舍。",
