            ["ContentKR"] = "뭐 하러 어울리려고 해? 차라리 제대로 혼내주는 게 낫지.",
            ["DialogueId"] = 510039132,
            ["GUID"] = "510039132.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51003917,
            },
        [510039133] = {
            ["Content"] = "他们是骗你的，不要相信。",
            ["ContentKR"] = "다 거짓말이니까 믿지 마.",
            ["DialogueId"] = 510039133,
            ["GUID"] = "510039133.0",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51003919,
            },
        [510040011] = {
            ["Content"] = "想象你是凶狠的恶魔。",
            ["ContentKR"] = "네가 잔혹한 악마라고 상상해 봐.",
            ["DialogueId"] = 510040011,
            ["GUID"] = "510040011.0",
            ["NextDialogue"] = 51004002,
            },
        [510040012] = {
            ["Content"] = "他们平时怎么说你的，你就怎么骂回去。",
            ["ContentKR"] = "평소에 그들이 널 대했던 그대로 똑같이 해줘.",
            ["DialogueId"] = 510040012,
            ["GUID"] = "510040012.0",
            ["NextDialogue"] = 51004002,
            },
        [510040061] = {
            ["Content"] = "既然知道，还不快滚远点。",
            ["ContentKR"] = "알았으면 꺼져.",
            ["DialogueId"] = 510040061,
            ["GUID"] = "510040061.0",
            ["NextDialogue"] = 51004008,
            },
        [510040062] = {
            ["Content"] = "不要那么急躁，这位小姐有些文明友善的话想讲给各位听。",
            ["ContentKR"] = "소녀가 나름 착한 말을 고민 중이니, 조금만 기다린다.",
            ["DialogueId"] = 510040062,
            ["GUID"] = "510040062.0",
            ["NextDialogue"] = 51004007,
            },
        [510041091] = {
            ["Content"] = "我看你也挺会骂人的，记得以后多骂骂。",
            ["ContentKR"] = "너도 욕을 꽤 잘하던데, 앞으로 많이 해봐.",
            ["DialogueId"] = 510041091,
            ["GUID"] = "510041091.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51004110,
            },
        [510041092] = {
            ["Content"] = "谢谢夸奖。不过更重要的是，你终于敢反抗他们了。",
            ["ContentKR"] = "고마워. 그런데 중요한 건 네가 드디어 맞설 수 있게 되었다는 거지.",
            ["DialogueId"] = 510041092,
            ["GUID"] = "510041092.0",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51004110,
            },
        [510041141] = {
