            ["ContentKR"] = "(동의)",
            ["DialogueId"] = 510041211,
            ["GUID"] = "510041211.0",
            ["NextDialogue"] = 51004122,
            },
        [510041212] = {
            ["Content"] = "（拒绝。）",
            ["ContentKR"] = "(거절)",
            ["DialogueId"] = 510041212,
            ["GUID"] = "510041212.0",
            ["NextDialogue"] = 51004124,
            },
        [510041271] = {
