            ["DialogueId"] = 510042031,
            ["GUID"] = "510042031.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51004204,
            },
        [510042032] = {
            ["Content"] = "你在等的人介绍我来的。",
            ["ContentKR"] = "당신이 기다리고 있는 그 사람이 보냈어요.",
            ["DialogueId"] = 510042032,
            ["GUID"] = "510042032.0",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51004205,
            },
        [510042033] = {
