            ["DialogueId"] = 510049032,
            ["GUID"] = "510049032.0",
            ["Scripts"] = "SetOutport{FinishType{\"Fail\"}}",
            },
        [510049091] = {
            ["Content"] = "放松，我不是来威胁你的。",
            ["ContentKR"] = "진정해요. 당신을 위협하러 온 게 아니에요.",
            ["DialogueId"] = 510049091,
            ["GUID"] = "510049091.0",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 51004910,
            },
        [510049092] = {
            ["Content"] = "学着她的动作一起比划双手。",
            ["ContentKR"] = "루나처럼 허공에 손짓한다.",
            ["DialogueId"] = 510049092,
            ["GUID"] = "510049092.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51004911,
            },
        [510049141] = {
            ["Content"] = "“直到他们喂我喝下莲草制成的毒药。我虽然没死，但嗓子再也没法说话了。”",
            ["ContentKR"] = "'나중엔 로터스로 만든 독약까지 먹였어요. 목숨은 건졌지만, 두 번 다시 말을 할 수 없게 되어 버렸죠.'",
            ["DialogueId"] = 510049141,
            ["GUID"] = "510049141.0",
            ["NextDialogue"] = 51004915,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Ziji",
            ["TalkActionId"] = {
                [1] = "700010:Explain02_End",
                },
            },
        [510049171] = {
            ["Content"] = "你写这些又有什么用呢？除了给自己惹来麻烦，什么都改变不了。",
            ["ContentKR"] = "이런 걸 쓰는 게 무슨 소용이에요? 본인만 곤란해질 뿐, 변하는 건 없잖아요.",
            ["DialogueId"] = 510049171,
            ["GUID"] = "510049171.0",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51004918,
            ["Scripts"] = "SetOutport{FinishType{2},OptionIdx{1}}",
            },
        [510049172] = {
            ["Content"] = "即使遭遇这样的不幸，你还是在创作，我敬佩你的勇气。",
            ["ContentKR"] = "이렇게 힘든 와중에도 창작 활동을 하시다니, 용기가 존경스럽습니다.",
            ["DialogueId"] = 510049172,
            ["GUID"] = "510049172.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51004923,
            ["Scripts"] = "SetOutport{FinishType{2},OptionIdx{1}}",
            },
        [510049173] = {
            ["Content"] = "这张纸现在在我手上了。想要的话就拿点什么来赎吧。",
            ["ContentKR"] = "종이는 제가 갖고 있으니, 돌려받고 싶거든 대가를 지불하세요.",
            ["DialogueId"] = 510049173,
            ["GUID"] = "510049173.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51004927,
            ["Scripts"] = "SetOutport{FinishType{2},OptionIdx{2}}",
            },
        [510050121] = {
            ["Content"] = "现在所有人都当这里是鬼宅，但您似乎并不意外，也并不抵触。",
            ["ContentKR"] = "이제 모두 이 집을 귀신의 집이라고 생각하는데, 당신은 아무렇지 않은 것 같네요.",
            ["DialogueId"] = 510050121,
            ["FailDialogue"] = 51005013,
            ["GUID"] = "510050121.0",
            ["ImprCheckId"] = 1024,
            ["NextDialogue"] = 51005015,
            },
        [510050171] = {
            ["Content"] = "您和恩里克先生相识很久了吗？",
            ["ContentKR"] = "헨릭 씨와 오래 알고 지내셨나요?",
            ["DialogueId"] = 510050171,
            ["GUID"] = "510050171.0",
            ["NextDialogue"] = 51005018,
            },
        [510050201] = {
            ["Content"] = "可惜，他的善举没有带给他应得的名誉。",
            ["ContentKR"] = "아쉽게도 헨릭 씨의 선의가 명성으로 이어지지는 않았네요.",
            ["DialogueId"] = 510050201,
            ["GUID"] = "510050201.0",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51005021,
            },
        [510050202] = {
            ["Content"] = "他坚守着为人的底线。",
            ["ContentKR"] = "도리가 무엇인지 잘 아는 분이셨네요.",
            ["DialogueId"] = 510050202,
            ["GUID"] = "510050202.0",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 51005022,
            },
        [510050203] = {
            ["Content"] = "也许……他想到了自己的女儿。",
            ["ContentKR"] = "아마... 딸 생각이 났을 거예요.",
            ["DialogueId"] = 510050203,
            ["GUID"] = "510050203.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51005023,
            },
        [510050231] = {
            ["Content"] = "如果恩里克先生知道，在他过世后你依然照顾着这里，一定会感到欣慰。",
            ["ContentKR"] = "당신이 여전히 관리하고 있다는 사실을 돌아가신 헨릭 씨가 알면 분명 기뻐하실 거예요.",
            ["DialogueId"] = 510050231,
            ["GUID"] = "510050231.0",
            ["NextDialogue"] = 51005024,
            },
        [510050261] = {
            ["Content"] = "（你看见莱娜女士捧在手里的钥匙，一种熟悉感涌上心头。）",
            ["ContentKR"] = "(레나가 들고 있는 열쇠가 어딘가 익숙하다.)",
            ["DialogueId"] = 510050261,
            ["FailDialogue"] = 51005027,
            ["GUID"] = "510050261.0",
            ["ImprCheckId"] = 1025,
            ["NextDialogue"] = 51005028,
            },
        [510050291] = {
            ["Content"] = "莱娜女士，你认得这把钥匙吗？",
            ["ContentKR"] = "레나 아주머니, 이 열쇠를 아세요?",
            ["DialogueId"] = 510050291,
            ["GUID"] = "510050291.0",
            ["NextDialogue"] = 51005030,
            },
        [510050391] = {
            ["Camera"] = "-236.947266,-87.956055,124.296875,0.0,0.0,23.006927,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "收下吧，由我见证，这把钥匙将一直属于你。",
            ["ContentKR"] = "자, 받으세요. 제가 증인이잖아요. 이 열쇠는 레나 아주머니 거예요.",
            ["DialogueId"] = 510050391,
            ["GUID"] = "510050391.0",
            ["SpeakNpcId"] = 100001,
            },
        [510050411] = {
            ["Content"] = "不是所有活在阳光下的人都问心无愧。",
            ["ContentKR"] = "이 태양 아래의 모든 사람이 완전무결한 건 아니야.",
            ["DialogueId"] = 510050411,
            ["GUID"] = "510050411.0",
            ["SpeakNpcId"] = 700013,
            },
        [510051051] = {
            ["Content"] = "无意评判，并不关心。只是为了达成目的才暂且逗留在这里。",
            ["ContentKR"] = "별생각 없어. 목적이 있어서 잠깐 머무는 것뿐이거든.",
            ["DialogueId"] = 510051051,
            ["GUID"] = "510051051.0",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51005106,
            },
        [510051052] = {
            ["Content"] = "第一次来这种大城市，总感觉这里的氛围很奇特，也碰见了前所未有的人和事，说实话，还不太习惯……",
            ["ContentKR"] = "이런 대도시는 처음인데, 조금 특이한 것 같아. 새로운 사람을 만나고, 새로운 일을 겪었거든. 솔직히 아직 좀 어색해...",
            ["DialogueId"] = 510051052,
            ["GUID"] = "510051052.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51005107,
            },
        [510051053] = {
            ["Content"] = "像回家一样！",
            ["ContentKR"] = "집에 온 느낌이야!",
            ["DialogueId"] = 510051053,
            ["GUID"] = "510051053.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51005108,
            },
        [510051111] = {
            ["Content"] = "这都是些旧货，恐怕没什么价值。",
            ["ContentKR"] = "낡아서 별 가치가 없을 것 같아.",
            ["DialogueId"] = 510051111,
            ["GUID"] = "510051111.0",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51005112,
            },
        [510051112] = {
            ["Content"] = "我先确认下，这些应该不是……偷来的吧？",
            ["ContentKR"] = "근데 이 물건들... 훔쳐 온 건 아니지?",
            ["DialogueId"] = 510051112,
            ["GUID"] = "510051112.0",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 51005113,
            },
        [510051113] = {
            ["Content"] = "哪儿搞的！带我一个！",
            ["ContentKR"] = "어디서 난 건데? 하나 가져갈래!",
            ["DialogueId"] = 510051113,
            ["GUID"] = "510051113.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51005114,
            },
        [510051151] = {
            ["Content"] = "（你拾起一张药方，它的背面似乎写着一首不太“友善”的打油诗。）",
            ["ContentKR"] = "(처방전 하나를 집는다. 위에 그다지 '친절'하지 않아 보이는 싯구가 적혀 있는 듯하다.)",
            ["DialogueId"] = 510051151,
            ["FailDialogue"] = 51005116,
            ["GUID"] = "510051151.0",
            ["ImprCheckId"] = 1040,
            ["NextDialogue"] = 51005117,
            },
        [510051152] = {
            ["Content"] = "（你拾起一大盒纸星星，它的主人一定有非常想要实现的愿望。）",
            ["ContentKR"] = "(종이별이 담긴 상자를 집는다. 물건의 주인은 분명히 꼭 이루고 싶은 소망이 있을 것이다.)",
            ["DialogueId"] = 510051152,
            ["FailDialogue"] = 51005116,
            ["GUID"] = "510051152.0",
            ["ImprCheckId"] = 1041,
            ["NextDialogue"] = 51005117,
            },
        [510051153] = {
            ["Content"] = "（你拾起一把钥匙，这把钥匙的样式似曾相识——你好像在恩里克那里见过一把类似的。）",
            ["ContentKR"] = "(열쇠 하나를 집는다. 열쇠 모양이 왠지 눈에 익은 게, 헨릭의 집에서 본 것과 비슷한 듯하다.)",
            ["DialogueId"] = 510051153,
            ["FailDialogue"] = 51005116,
            ["GUID"] = "510051153.0",
            ["ImprCheckId"] = 1042,
            ["NextDialogue"] = 51005117,
            },
        [510051251] = {
            ["Content"] = "这些够吗？",
            ["ContentKR"] = "이 정도면 될까?",
            ["DialogueId"] = 510051251,
            ["GUID"] = "510051251.0",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 51005126,
            },
        [510051252] = {
            ["Content"] = "说好的八折呢？",
            ["ContentKR"] = "20% 할인해 준다고 했지?",
            ["DialogueId"] = 510051252,
            ["GUID"] = "510051252.0",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51005127,
            },
        [510051253] = {
            ["Content"] = "溜了。",
            ["ContentKR"] = "안 살래.",
            ["DialogueId"] = 510051253,
            ["GUID"] = "510051253.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51005128,
            },
        [510051321] = {
            ["Content"] = "祝您查案顺利，侦探阁下！",
            ["ContentKR"] = "행운을 빌어요, 탐정님!",
            ["DialogueId"] = 510051321,
            ["GUID"] = "510051321.0",
            ["NextDialogue"] = 510051322,
            ["SpeakNpcId"] = 700115,
            },
        [510051322] = {
            ["Content"] = "等你调查完这三件东西背后的故事，再来和我谈谈你对冰湖城的看法吧！",
            ["ContentKR"] = "이것들의 사연을 알아낸 후에, 아이스레이크 시티에 대한 느낌을 다시 말해줘요!",
            ["DialogueId"] = 510051322,
            ["GUID"] = "510051322.0",
            ["SpeakNpcId"] = 700115,
            },
        [510052021] = {
            ["Content"] = "药方属于医生露娜。她曾是一位吟游诗人，但憎恨卡戎的人夺走了她的声音，这些言语是她仅剩的倾诉方式。",
            ["ContentKR"] = "처방전의 주인은 의사인 루나였어. 음유시인이었던 루나는 자신의 목소리를 앗아간 카론을 증오했지. 이 말들은 자신이 털어놓을 수 있는 유일한 방법이었어.",
            ["DialogueId"] = 510052021,
            ["GUID"] = "510052021.0",
            ["NextDialogue"] = 51005203,
            },
        [510052022] = {
            ["Content"] = "售票员杰西卡最大的愿望就是登上离开这里的火车，可她能做的只有把过期车票折成星星，祈祷着奇迹降临。",
            ["ContentKR"] = "매표원 제시카는 이곳을 떠나는 기차를 타는 게 소원이었어. 하지만 이미 기한이 지나버린 기차표로 별을 접으면서 기적을 기다릴 수밖에 없었지.",
            ["DialogueId"] = 510052022,
            ["GUID"] = "510052022.0",
            ["NextDialogue"] = 51005204,
            },
        [510052023] = {
            ["Content"] = "那把钥匙可以打开一个保险柜，我们找到了一份遗嘱。莱娜女士成了我的新房东，但她免掉了我的房租。",
            ["ContentKR"] = "열쇠는 금고의 열쇠였어. 그리고 거기서 유언장을 하나 발견했지. 레나 씨가 새로운 집 주인이 되었고, 내 임대료를 면제해 줬어.",
            ["DialogueId"] = 510052023,
            ["GUID"] = "510052023.0",
            ["NextDialogue"] = 51005205,
            },
        [510052081] = {
            ["Content"] = "在冰湖城，最好只做“安全”的事，越界的结果是害人害己，得不偿失。",
            ["ContentKR"] = "아이스레이크 시티에서는 '안전'한 일만 해야겠어. 선을 넘으면 잃는 게 더 많아.",
            ["DialogueId"] = 510052081,
            ["GUID"] = "510052081.0",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51005209,
            },
        [510052082] = {
            ["Content"] = "生活很难一帆风顺。在冰湖城，我们唯一能坚守的只有自己的准则。",
            ["ContentKR"] = "순탄한 삶을 사는 건 쉽지 않아. 아이스레이크 시티에서 우리가 유일하게 지킬 수 있는 건 본인의 원칙뿐이지.",
            ["DialogueId"] = 510052082,
            ["GUID"] = "510052082.0",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 51005209,
            },
        [510052083] = {
            ["Content"] = "不是所有人都是“城市法则”的信徒，有多少人在暗地里悄悄违背它呢？",
            ["ContentKR"] = "다들 '도시의 규칙'을 따르는 건 아니잖아. 그렇다면 따르지 않는 사람은 얼마나 있을까?",
            ["DialogueId"] = 510052083,
            ["GUID"] = "510052083.0",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51005209,
            },
        [510052084] = {
            ["Content"] = "人们抱紧希冀、信念、苦衷……这些他们仅存的东西，然后事情就发生了。",
            ["ContentKR"] = "사람들에게는 희망과 믿음, 그리고 고충이 있어... 이런 것들 때문에 사건도 생기는 거지.",
            ["DialogueId"] = 510052084,
            ["GUID"] = "510052084.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51005209,
            },
        [510052085] = {
            ["Content"] = "城市易燃易爆炸，泪湖蒸发又升华！",
            ["ContentKR"] = "도시는 위험해. 눈물의 호수는 언제든 마를 수 있지!",
            ["DialogueId"] = 510052085,
            ["GUID"] = "510052085.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51005209,
            },
        [510052131] = {
            ["Content"] = "一切都还顺利吗，新晋侦探阁下？",
            ["ContentKR"] = "신입 탐정님, 잘 되어가고 있나요?",
            ["DialogueId"] = 510052131,
            ["GUID"] = "510052131.0",
            ["SpeakNpcId"] = 700128,
            },
        [510053031] = {
            ["Content"] = "（凑近看看他手里的册子。）",
            ["ContentKR"] = "(다가가서 남자가 들고 있는 수첩을 본다.)",
            ["DialogueId"] = 510053031,
            ["GUID"] = "510053031.0",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51005304,
            },
        [510053032] = {
            ["Content"] = "（默默离开。）",
            ["ContentKR"] = "(조용히 떠나기)",
            ["DialogueId"] = 510053032,
            ["GUID"] = "510053032.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51005306,
            },
        [510053111] = {
            ["Content"] = "腌制……生吃？",
            ["ContentKR"] = "절여서... 바로 먹나요?",
            ["DialogueId"] = 510053111,
            ["GUID"] = "510053111.0",
            ["NextDialogue"] = 51005312,
            },
        [510053112] = {
            ["Content"] = "果然很有……特色。",
            ["ContentKR"] = "정말... 특이하네요.",
            ["DialogueId"] = 510053112,
            ["GUID"] = "510053112.0",
            ["NextDialogue"] = 51005312,
            },
        [510053121] = {
            ["Content"] = "食材的事就拜托你了，我再想想食谱还有没有优化空间。",
            ["ContentKR"] = "재료 찾는 걸 부탁드려요. 전 레시피를 발전시킬 방법을 생각해 볼게요.",
            ["DialogueId"] = 510053121,
            ["GUID"] = "510053121.0",
            ["SpeakNpcId"] = 700116,
            },
        [510054021] = {
            ["DialogueId"] = 510054021,
            ["GUID"] = "510054021.0",
            ["IsBlack"] = 1,
            },
        [510054061] = {
            ["Content"] = "这些都还是生的吧，我就不吃了！",
            ["ContentKR"] = "안 익었잖아요. 안 먹을래요!",
            ["DialogueId"] = 510054061,
            ["GUID"] = "510054061.0",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51005407,
            },
        [510054062] = {
            ["Content"] = "（勉为其难地吃一口，并称赞好吃。）",
            ["ContentKR"] = "(억지로 한입 먹고 맛있다고 칭찬한다.)",
            ["DialogueId"] = 510054062,
            ["GUID"] = "510054062.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51005408,
            },
        [510054063] = {
            ["Content"] = "如果我一分钟后就要饿死了，那么我宁愿去吃冰渣。",
            ["ContentKR"] = "곧 굶어 죽는 상황이라고 해도, 차라리 눈을 먹을래요.",
            ["DialogueId"] = 510054063,
            ["GUID"] = "510054063.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51005409,
            },
        [510055071] = {
            ["Content"] = "月牙鱼的事就交给你了，我再想想食谱还有没有改善空间。",
            ["ContentKR"] = "마블 피쉬는 당신이 맡아주세요. 저는 레시피를 발전시킬 방법을 생각해 볼게요.",
            ["DialogueId"] = 510055071,
            ["GUID"] = "510055071.0",
            ["SpeakNpcId"] = 700117,
            },
        [510056011] = {
            ["Content"] = "（留意到北风莓的果皮上沾有血渍。）",
            ["ContentKR"] = "(아이스베리 껍질에 묻은 핏자국을 본다.)",
            ["DialogueId"] = 510056011,
            ["GUID"] = "510056011.0",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51005602,
            },
        [510056012] = {
            ["Content"] = "（留意到马库斯的身上沾有血渍。）",
            ["ContentKR"] = "(마커스 몸에 묻은 핏자국을 본다.)",
            ["DialogueId"] = 510056012,
            ["GUID"] = "510056012.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51005603,
            },
        [510057121] = {
            ["Content"] = "（诚实地表达对食物的喜爱，一定能收获所有人的赞美。）",
            ["ContentKR"] = "(맛있는 음식에 대한 느낌으로 '분명 모두가 감탄할 거'라며 솔직하게 말한다.)",
            ["DialogueId"] = 510057121,
            ["GUID"] = "510057121.0",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 51005713,
            },
        [510057122] = {
            ["Content"] = "（撒谎说好吃但不够有特色，劝马库斯养好身体后再找下一份工作。）",
            ["ContentKR"] = "(맛있지만 특색이 없다며 거짓말하고, 몸부터 챙긴 뒤 다른 일을 찾아보라고 조언한다.)",
            ["DialogueId"] = 510057122,
            ["GUID"] = "510057122.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51005716,
            },
        [510058021] = {
            ["Content"] = "城里所有箱子不都是给我的吗？",
            ["ContentKR"] = "도시에 있는 모든 상자는 다 내건 줄 알았는데?",
            ["DialogueId"] = 510058021,
            ["GUID"] = "510058021.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51005803,
            },
        [510058022] = {
            ["Content"] = "抱歉，我不知道这些箱子是你们的。",
            ["ContentKR"] = "미안, 너희 상자인지 몰랐어.",
            ["DialogueId"] = 510058022,
            ["GUID"] = "510058022.0",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 51005804,
            },
        [510058023] = {
            ["Content"] = "这箱子上也没写你们名字啊？",
            ["ContentKR"] = "상자에 너희 이름이 적힌 것도 아닌데?",
            ["DialogueId"] = 510058023,
            ["GUID"] = "510058023.0",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51005807,
            },
        [510059041] = {
            ["Content"] = "唉……这箱子让给你们，行了吧？",
            ["ContentKR"] = "휴... 상자는 양보할게. 됐지?",
            ["DialogueId"] = 510059041,
            ["GUID"] = "510059041.0",
            ["ImprPlusId"] = 1004,
            },
        [510059042] = {
            ["Content"] = "（用另一条腿狠狠踢一脚三哥。）",
            ["ContentKR"] = "(반대쪽 발로 셋째를 강하게 찬다.)",
            ["DialogueId"] = 510059042,
            ["GUID"] = "510059042.0",
            ["ImprPlusId"] = 1005,
            },
        [510059251] = {
            ["Content"] = "是合作伙伴。",
            ["ContentKR"] = "동료라는 뜻이야.",
            ["DialogueId"] = 510059251,
            ["GUID"] = "510059251.0",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51005926,
            },
        [510059252] = {
            ["Content"] = "是奴隶。",
            ["ContentKR"] = "노예라는 뜻이야.",
            ["DialogueId"] = 510059252,
            ["GUID"] = "510059252.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51005926,
            },
        [510059253] = {
            ["Content"] = "是朋友。",
            ["ContentKR"] = "친구라는 뜻이야.",
            ["DialogueId"] = 510059253,
            ["GUID"] = "510059253.0",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 51005926,
            },
        [510059371] = {
            ["Content"] = "……总感觉我们在欺负傻子，有点罪恶。",
            ["ContentKR"] = "...바보를 괴롭히는 것 같아서 죄책감이 들어.",
            ["DialogueId"] = 510059371,
            ["GUID"] = "510059371.0",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 51005938,
            },
        [510059372] = {
            ["Content"] = "还不够。你们得把身上的钱财都交出来，孝敬大大哥。",
            ["ContentKR"] = "이걸론 부족해. 왕형님을 존경하는 뜻으로 갖고 있는 돈도 모두 내놔.",
            ["DialogueId"] = 510059372,
            ["GUID"] = "510059372.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51005939,
            },
        [510060171] = {
            ["Content"] = "有的人光看这个名字就会感到不适的。",
            ["ContentKR"] = "솔직히 이름만 들어도 불편해할 사람도 있을 것 같아.",
            ["DialogueId"] = 510060171,
            ["GUID"] = "510060171.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51006018,
            },
        [510060172] = {
            ["Content"] = "这会把委托人吓跑的。",
            ["ContentKR"] = "그러다 의뢰인들이 다 도망갈걸?",
            ["DialogueId"] = 510060172,
            ["GUID"] = "510060172.0",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51006019,
            },
        [510060173] = {
            ["Content"] = "挺好的，我们就要研究食用昆虫！",
            ["ContentKR"] = "좋아! 우리도 식용 곤충 연구나 해볼까?",
            ["DialogueId"] = 510060173,
            ["GUID"] = "510060173.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51006020,
            },
        [510067091] = {
            ["Content"] = "要是我，可能也不想挑战看起来就赢不了的成绩。",
            ["ContentKR"] = "솔직히 나도 이길 수 없어 보이는 기록이면 도전할 맛이 안 날 것 같아.",
            ["DialogueId"] = 510067091,
            ["GUID"] = "510067091.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51006710,
            },
        [510067092] = {
            ["Content"] = "所以你是利用我向奥特赛德复仇。",
            ["ContentKR"] = "그래서 날 이용해서 아웃사이더한테 복수한 거구나.",
            ["DialogueId"] = 510067092,
            ["GUID"] = "510067092.0",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51006712,
            },
        [510067093] = {
            ["Content"] = "奥特赛德太慢了，丢人，你转行吧。",
            ["ContentKR"] = "아웃사이더, 그렇게 느려서 얼굴이나 들고 다니겠어? 차라리 직업을 바꾸는 게 어때?",
            ["DialogueId"] = 510067093,
            ["GUID"] = "510067093.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51006715,
            },
        [510070011] = {
            ["Content"] = "这座城市似乎民风如此，听多了就会习惯了。",
            ["ContentKR"] = "이 도시는 분위기가 원래 그런가 봐요. 듣다 보면 익숙해질 거예요.",
            ["DialogueId"] = 510070011,
            ["GUID"] = "510070011.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51007002,
            },
        [510070012] = {
            ["Content"] = "你怎么连骂人都不会？",
            ["ContentKR"] = "욕도 제대로 못 해요?",
            ["DialogueId"] = 510070012,
            ["GUID"] = "510070012.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51007003,
            },
        [510070051] = {
            ["Content"] = "让一下，我有办法让她好好说话。",
            ["ContentKR"] = "잠시만요. 저한테 방법이 있어요.",
            ["DialogueId"] = 510070051,
            ["FailDialogue"] = 51007006,
            ["GUID"] = "510070051.0",
            ["ImprCheckId"] = 1060,
            ["NextDialogue"] = 51007007,
            },
        [510071161] = {
            ["Content"] = "这是很重要的东西吧，就这样交给别人真的没关系吗？",
            ["ContentKR"] = "중요한 물건 같은데 다른 사람한테 맡겨도 정말 괜찮을까요?",
            ["DialogueId"] = 510071161,
            ["GUID"] = "510071161.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51007117,
            },
        [510071162] = {
            ["Content"] = "（再拆开一颗纸星星，并把上面的内容大声念出来。）",
            ["ContentKR"] = "(별을 하나 더 펼쳐 종이에 적힌 내용을 크게 읽는다.)",
            ["DialogueId"] = 510071162,
            ["GUID"] = "510071162.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51007119,
            },
        [510073021] = {
            ["Content"] = "欲望就是搞清楚你想要什么。",
            ["ContentKR"] = "욕망이란 자신이 원하는 게 뭔지 아는 거죠.",
            ["DialogueId"] = 510073021,
            ["GUID"] = "510073021.0",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 510073024,
            },
        [510073022] = {
            ["Content"] = "欲望是生命存在的原动力。",
            ["ContentKR"] = "욕망은 생명을 살아 숨 쉬게 하는 원동력이에요.",
            ["DialogueId"] = 510073022,
            ["GUID"] = "510073022.0",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 510073025,
            },
        [510073023] = {
            ["Content"] = "欲望是不宜在公开场合谈的东西。",
            ["ContentKR"] = "욕망을 공개적인 장소에서 말하긴 좀 그렇죠.",
            ["DialogueId"] = 510073023,
            ["GUID"] = "510073023.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 510073026,
            },
        [510073024] = {
            ["Content"] = "我也不知道我想要什么……",
            ["ContentKR"] = "전 제가 뭘 원하는지 모르는걸요...",
            ["DialogueId"] = 510073024,
            ["GUID"] = "7FB1017D",
            ["NextDialogue"] = 51007303,
            ["SpeakNpcId"] = 700077,
            },
        [510073025] = {
            ["Content"] = "好深奥啊……",
            ["ContentKR"] = "심오한 얘기네요...",
            ["DialogueId"] = 510073025,
            ["GUID"] = "7FB1017E",
            ["NextDialogue"] = 51007303,
            ["SpeakNpcId"] = 700077,
            },
        [510073026] = {
            ["Content"] = "原来如此，怪不得我搞不懂。",
            ["ContentKR"] = "어쩐지... 그래서 제가 이해하지 못한 거군요.",
            ["DialogueId"] = 510073026,
            ["GUID"] = "7FB1017F",
            ["NextDialogue"] = 51007303,
            ["SpeakNpcId"] = 700077,
            },
        [510073031] = {
            ["Content"] = "（同意。）",
            ["ContentKR"] = "(수락한다.)",
            ["DialogueId"] = 510073031,
            ["GUID"] = "510073031.0",
            ["NextDialogue"] = 51007304,
            },
        [510073032] = {
            ["Content"] = "（拒绝。）",
            ["ContentKR"] = "(거절한다.)",
            ["DialogueId"] = 510073032,
            ["GUID"] = "510073032.0",
            ["Scripts"] = "SetOutport{FinishType{\"Fail\"}}",
            },
        [510073131] = {
            ["Content"] = "你的这个学术报告……听起来也不是很学术。",
            ["ContentKR"] = "학술 보고서라더니... 별로 학술적으로 들리진 않네요.",
            ["DialogueId"] = 510073131,
            ["GUID"] = "510073131.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51007314,
            },
        [510073132] = {
            ["Content"] = "这些东西跟考古有什么关系？",
            ["ContentKR"] = "그 보고서가 고고학이랑 무슨 관계죠?",
            ["DialogueId"] = 510073132,
            ["GUID"] = "510073132.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51007314,
            },
        [510073141] = {
            ["Content"] = "就是因为你这敷衍了事的态度，才会让投资人“感受不到欲望”。",
            ["ContentKR"] = "그렇게 대충 어영부영 넘어가려고 하니까, 투자자가 \"욕망이 느껴지지 않는다\"고 하는 게 아닐까요.",
            ["DialogueId"] = 510073141,
            ["GUID"] = "510073141.0",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 510073142,
            },
        [510073142] = {
            ["Content"] = "我也不想的嘛，可是欲望这东西到底是什么，至少我在现在的冰湖城没发现……",
            ["ContentKR"] = "저도 이러고 싶은 게 아니에요. 하지만 그 욕망이란 걸, 적어도 지금 이 아이스레이크 시티에선 찾아내지 못했어요...",
            ["DialogueId"] = 510073142,
            ["GUID"] = "510073142.0",
            ["NextOptions"] = {
                [1] = 51007315,
                },
            ["RestartTag"] = 510073142,
            ["SpeakNpcId"] = 700077,
            },
        [510073151] = {
            ["Content"] = "唉……要有合适的向导我还会在这里发愁吗？",
            ["ContentKR"] = "휴... 올바른 안내인이 있다면 제가 왜 고민하겠어요?",
            ["DialogueId"] = 510073151,
            ["GUID"] = "510073151.0",
            ["SpeakNpcId"] = 700077,
            },
        [510073152] = {
            ["Content"] = "找不到啊，这里的狩月人都只懂打架和喝酒，问他们附近有什么历史遗迹，结果反问说自己家祖传的炖锅有没有历史，算不算遗迹。",
            ["ContentKR"] = "그런 안내인을 찾을 수가 없어요. 이곳 월석 사냥꾼들은 술 마시고 싸움박질이나 할 줄 알지, 근처의 역사나 유적에 대해 물으면, 자기 조상님이 물려주신 가마솥엔 역사가 있는지, 유적으로 쳐주는지 되묻는다니까요.",
            ["DialogueId"] = 510073152,
            ["GUID"] = "510073152",
            ["NextDialogue"] = 510073156,
            ["SpeakNpcId"] = 700077,
            },
        [510073153] = {
            ["Content"] = "好吧，看看能不能帮你找到灵感。",
            ["ContentKR"] = "좋아요, 영감을 찾을 수 있는지 한번 가보죠.",
            ["DialogueId"] = 510073153,
            ["GUID"] = "510073153",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51007316,
            },
        [510073154] = {
            ["Content"] = "给我报酬，我帮你一起想。",
            ["ContentKR"] = "보수를 주면 생각해 볼게요.",
            ["DialogueId"] = 510073154,
            ["GUID"] = "510073154",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51007316,
            },
        [510073155] = {
            ["Content"] = "找对人了，我是高级知识分子，考察经费分我一些。",
            ["ContentKR"] = "사람 보실 줄 아시네요. 제가 이래 봬도 배운 사람이거든요. 대신 발굴 경비는 챙겨주셔야 해요.",
            ["DialogueId"] = 510073155,
            ["GUID"] = "510073155",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51007316,
            },
        [510073156] = {
            ["Content"] = "要不……你带我去附近转悠转悠吧，找找灵感。水仙平原的常客里就你看起来死劲儿最少读书最多。",
            ["ContentKR"] = "아니면... 영감을 찾을 수 있게, 저랑 같이 근처를 좀 돌아다녀봐 줄래요? 아스포델 단골 중에서 책 좀 읽은 사람은 그나마 당신뿐인 것 같거든요.",
            ["DialogueId"] = 510073156,
            ["GUID"] = "7FB1039F",
            ["NextOptions"] = {
                [1] = 510073153,
                [2] = 510073154,
                [3] = 510073155,
                },
            ["SpeakNpcId"] = 700077,
            },
        [510073231] = {
            ["Content"] = "工艺与设施好像都不太一样，越是早的部分，会有更多的砖石结构，而新修的部分会有更多的机械……",
            ["ContentKR"] = "공법과 시설도 좀 다른 것 같아요. 오래된 부분일수록 벽돌과 석조 구조가 많고, 새로 보수한 부분은 기계가 많네요...",
            ["DialogueId"] = 510073231,
            ["GUID"] = "7FB104C5",
            ["NextDialogue"] = 510073232,
            ["SpeakNpcId"] = 700172,
            },
        [510073232] = {
            ["Content"] = "应该能写一篇报告，不过有点偏向城市史……不知道这方面之前有没有人做过啊……",
            ["ContentKR"] = "보고서 한 편을 쓸 수 있겠어요. 조금 도시사에 가깝긴 한데... 이쪽 분야를 먼저 연구한 사람이 있는지 모르겠네요...",
            ["DialogueId"] = 510073232,
            ["GUID"] = "7FB104C6",
            ["NextDialogue"] = 510073233,
            ["SpeakNpcId"] = 700172,
            },
        [510073233] = {
            ["Content"] = "啊，抱歉，我想问题入神了。但确实我获得灵感了，你能再带我去看看其他地方吗？你觉得意思的地方，都行。",
            ["ContentKR"] = "아, 죄송해요. 그만 정신이 팔려서... 근데 확실히 영감을 얻었어요. 저랑 다른 곳도 가줄 수 있어요? 당신이 보기에 흥미로운 곳이면 돼요.",
            ["DialogueId"] = 510073233,
            ["GUID"] = "7FB104EE",
            ["SpeakNpcId"] = 700172,
            },
        [510073411] = {
            ["Content"] = "本来还想低调一点的……",
            ["ContentKR"] = "후, 조용히 살려고 했는데...",
            ["DialogueId"] = 510073411,
            ["GUID"] = "510073411.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51007344,
            },
        [510073412] = {
            ["Content"] = "我只是路过的平凡狩月人罢了。",
            ["ContentKR"] = "전 그냥 지나가던 평범한 월석 사냥꾼일 뿐이에요.",
            ["DialogueId"] = 510073412,
            ["GUID"] = "510073412.0",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 510073441,
            },
        [510073413] = {
            ["Content"] = "别整那些虚的名号，我的报酬呢。",
            ["ContentKR"] = "쓸데없는 타이틀 말고 보수는요?",
            ["DialogueId"] = 510073413,
            ["GUID"] = "510073413.0",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51007342,
            },
        [510073441] = {
            ["Content"] = "我懂的，大师，您是想隐藏身份，不被其他人发现。",
            ["ContentKR"] = "이해해요, 신분을 숨기고 싶은 거죠? 아무래도 대가니까요.",
            ["DialogueId"] = 510073441,
            ["GUID"] = "510073441.0",
            ["NextDialogue"] = 51007342,
            ["SpeakNpcId"] = 700173,
            },
        [510073841] = {
            ["Content"] = "（真诚建议他注意个人卫生问题）",
            ["ContentKR"] = "(개인위생에 주의할 것을 신신당부한다)",
            ["DialogueId"] = 510073841,
            ["GUID"] = "510073841.0",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51007388,
            },
        [510073842] = {
            ["Content"] = "（为自己刚才失礼的动作道歉）",
            ["ContentKR"] = "(실례를 범한 것에 대해 사과한다)",
            ["DialogueId"] = 510073842,
            ["GUID"] = "510073842.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51007388,
            },
        [510073843] = {
            ["Content"] = "（指责他的味道过于腥臭有恶劣影响）",
            ["ContentKR"] = "(악취와 그로 인한 악영향에 대해 비난한다)",
            ["DialogueId"] = 510073843,
            ["GUID"] = "510073843.0",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 51007388,
            },
        [510073931] = {
            ["Content"] = "你并不理解他的行为，感觉没办法继续和他聊下去了。",
            ["ContentKR"] = "그의 행동이 이해되지 않는다. 더 이상 이야기를 나눌 필요가 없을 것 같다.",
            ["DialogueId"] = 510073931,
            ["GUID"] = "510073931.0",
            },
        [510073991] = {
            ["Content"] = "我去跟你一起。",
