            ["GUID"] = "510090051.0",
            },
        [510090052] = {
            ["Content"] = "现在暂时没空。",
            ["ContentKR"] = "지금은 좀 바쁘네요.",
            ["DialogueId"] = 510090052,
            ["GUID"] = "510090052.0",
            },
        [510090081] = {
