            ["ContentKR"] = "네, 시작하죠.",
            ["DialogueId"] = 510090081,
            ["GUID"] = "510090081.0",
            },
        [510090082] = {
            ["Content"] = "现在暂时没空。",
            ["ContentKR"] = "지금은 좀 바쁘네요.",
            ["DialogueId"] = 510090082,
            ["GUID"] = "510090082.0",
            },
        [510091111] = {
            ["Content"] = "这个……要收钱吗？",
