            ["DialogueId"] = 510091111,
            ["GUID"] = "510091111.0",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51009112,
            },
        [510091112] = {
            ["Content"] = "好精致的武器，我可以试试吗？",
            ["ContentKR"] = "정말 멋진 무기네요. 한번 써 봐도 될까요?",
