            ["GUID"] = "510091112.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51009113,
            },
        [510092251] = {
            ["Content"] = "说了这么久原来是推销！",
            ["ContentKR"] = "뭔가 했더니 결국 물건 판매였네요!",
            ["DialogueId"] = 510092251,
            ["GUID"] = "510092251.0",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51009226,
            },
        [510092252] = {
            ["Content"] = "我没有审美水平还真是对不起了。",
            ["ContentKR"] = "제가 영 미적 감각이 없어서요. 죄송하게 됐네요.",
            ["DialogueId"] = 510092252,
            ["GUID"] = "510092252.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51009228,
            },
        [510092253] = {
