            ["ContentKR"] = "염료를 빼앗아 단숨에 마셔 버린다.",
            ["DialogueId"] = 510092253,
            ["GUID"] = "510092253.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51009230,
            },
        [510092381] = {
            ["Content"] = "有吗，我觉得正好？",
            ["ContentKR"] = "그런가요? 전 딱 좋은데요?",
            ["DialogueId"] = 510092381,
            ["GUID"] = "510092381.0",
            ["NextDialogue"] = 51009239,
            },
        [510092382] = {
            ["Content"] = "的确，用回第一版吧。",
