            ["DialogueId"] = 510092382,
            ["GUID"] = "510092382.0",
            ["NextDialogue"] = 51009241,
            },
        [510093271] = {
            ["Content"] = "有印象",
            ["ContentKR"] = "본 기억이 난다.",
            ["DialogueId"] = 510093271,
            ["GUID"] = "510093271.0",
            ["NextDialogue"] = 51009418,
