            ["DialogueId"] = 510093272,
            ["GUID"] = "510093272.0",
            ["NextDialogue"] = 51009419,
            },
        [510093491] = {
            ["Content"] = "交给我吧。",
            ["ContentKR"] = "맡겨만 주세요.",
            ["DialogueId"] = 510093491,
            ["GUID"] = "510093491.0",
            ["NextDialogue"] = 51009440,
            },
        [510093492] = {
            ["Content"] = "为什么你不自己去？",
            ["ContentKR"] = "직접 가시면 되지 않아요?",
