            ["ContentKR"] = "제가 한번 해 볼게요.",
            ["DialogueId"] = 510093641,
            ["GUID"] = "510093641.0",
            ["NextDialogue"] = 51009455,
            },
        [510093951] = {
            ["Content"] = "事情不是你想的那样。",
            ["ContentKR"] = "그런 사이 아니라니까요.",
            ["DialogueId"] = 510093951,
            ["GUID"] = "510093951.0",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 51009486,
            },
        [510093952] = {
            ["Content"] = "知道就好，不要再插手别人的感情。",
