            ["GUID"] = "510093952.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51009486,
            },
        [510095121] = {
            ["Content"] = "……",
            ["DialogueId"] = 510095121,
            ["GUID"] = "510095121.0",
            ["NextOptions"] = {
                [1] = 510095122,
                },
            ["SpeakNpcId"] = 700303,
            },
        [510095122] = {
            ["Content"] = "出什么事了？",
            ["ContentKR"] = "무슨 일이야?",
            ["DialogueId"] = 510095122,
            ["GUID"] = "510095122.0",
            ["NextDialogue"] = 51009603,
            },
        [510095401] = {
            ["Content"] = "怎么还会有年轻人到这种地方……你在雪原迷路了吗？冰湖城的方向是——",
            ["ContentKR"] = "젊은 친구가 뭐 때문에 이런 곳에... 설원에서 길을 잃었나? 아이스레이크 시티로 가려면 저쪽인데...",
            ["DialogueId"] = 510095401,
