            ["GUID"] = "710014052.0",
            ["Scripts"] = "SetOutport{FinishType{2},OptionIdx{2}}",
            },
        [710015031] = {
            ["Content"] = "我来试试好了。",
            ["ContentKR"] = "한번 해볼게요.",
            ["DialogueId"] = 710015031,
            ["GUID"] = "710015031.0",
            },
        [710015032] = {
            ["Content"] = "不用那么麻烦，拍两下就好了。",
            ["ContentKR"] = "너무 복잡하게 생각할 것 없어요. 그냥 두드려 보시죠.",
            ["DialogueId"] = 710015032,
            ["GUID"] = "710015032.0",
            },
        [710015033] = {
            ["Content"] = "（不想跟军团的人扯上关系，离开此处。）",
            ["ContentKR"] = "(군단 사람들과 엮이고 싶지 않으니 자리를 떠난다.)",
            ["DialogueId"] = 710015033,
            ["GUID"] = "710015033.0",
            },
        [710016081] = {
