        [710020031] = {
            ["Content"] = "（一把抓住它，抱给那个女孩。）",
            ["ContentKR"] = "(고양이를 단숨에 붙잡아 소녀에게 안겨준다.)",
            ["DialogueId"] = 710020031,
            ["GUID"] = "710020031.0",
            },
        [710020032] = {
            ["Content"] = "（把它留在原地，找个借口应付一下那个女孩。）",
            ["ContentKR"] = "(고양이를 그대로 둔 채, 소녀에게 적당한 핑계를 대며 둘러댄다.)",
            ["DialogueId"] = 710020032,
            ["GUID"] = "710020032.0",
            },
        [710021021] = {
            ["Content"] = "（接受。）",
            ["ContentKR"] = "(수락)",
            ["DialogueId"] = 710021021,
