            },
        [710051332] = {
            ["Content"] = "（前言不搭后语，男人明显在耍你。）",
            ["ContentKR"] = "(말 앞뒤가 맞지 않는다. 이 남자, 분명히 당신을 놀리고 있다.)",
            ["DialogueId"] = 710051332,
            ["GUID"] = "710051272.0",
            },
        [710052141] = {
            ["Content"] = "太神奇了，所有幸福硬币我都要了！",
            ["ContentKR"] = "와, 정말 신기하네! 행복 동전 전부 다 살게!",
            ["DialogueId"] = 710052141,
            ["GUID"] = "710052071.0",
            },
        [710052142] = {
            ["Content"] = "比起借助外物，我选择靠自己的双手来获得幸福。",
            ["ContentKR"] = "난... 무언가에 의지하기보단, 내 스스로 행복을 찾고 싶어.",
            ["DialogueId"] = 710052142,
            ["GUID"] = "710052072.0",
            },
        [710053081] = {
            ["Content"] = "（拿走钱财，给内城那些高高在上的家伙一点教训。）",
            ["ContentKR"] = "(돈을 챙긴다. 내성의 잘난 사람들에게 한 번쯤은 이런 맛도 보여줘야지.)",
            ["DialogueId"] = 710053081,
            ["GUID"] = "710053121.0",
            },
        [710053082] = {
            ["Content"] = "（归还钱财，即使出身不同，丢失物品的悲伤都是共通的。）",
            ["ContentKR"] = "(물건을 돌려준다. 어디서 왔든, 잃어버린 슬픔만큼은 모두 똑같다.)",
            ["DialogueId"] = 710053082,
            ["GUID"] = "710053122.0",
            },
        [710054021] = {
            ["Content"] = "试试看吧。",
            ["ContentKR"] = "좋아, 한번 해보자.",
            ["DialogueId"] = 710054021,
            ["GUID"] = "710054031.0",
            },
        [710054022] = {
            ["Content"] = "稍等一下。",
            ["ContentKR"] = "음, 잠깐만... 뭔가 수상한데?",
            ["DialogueId"] = 710054022,
            ["GUID"] = "710054032.0",
            },
        [710054041] = {
            ["Content"] = "箱子一碰就坏，你没做手脚的话我把锁芯拆出来给所有人看看如何。",
            ["ContentKR"] = "상자를 건드리기만 해도 고장나던데... 미리 손을 써둔 게 아니라면, 이 자물쇠 심을 분해해서 모두에게 보여줘도 될까?",
            ["DialogueId"] = 710054041,
            ["GUID"] = "710054071.0",
            ["NextDialogue"] = 71005405,
            ["Scripts"] = "SetOutport{FinishType{2},OptionIdx{1}}",
            },
        [710054042] = {
            ["Content"] = "上一个讹我钱的人已经成为病房贵宾了。",
            ["ContentKR"] = "지난번에 나한테 같은 수작 부리다가 병원 신세를 진 친구가 생각나는군.",
            ["DialogueId"] = 710054042,
            ["GUID"] = "710054072.0",
            ["NextDialogue"] = 71005407,
            ["Scripts"] = "SetOutport{FinishType{2},OptionIdx{2}}",
            },
        [710055021] = {
            ["Content"] = "（接受。）",
            ["ContentKR"] = "(수락한다.)",
            ["DialogueId"] = 710055021,
            ["GUID"] = "710055041.0",
            },
        [710055022] = {
            ["Content"] = "（拒绝。）",
            ["ContentKR"] = "(거절한다.)",
            ["DialogueId"] = 710055022,
            ["GUID"] = "710055042.0",
            },
        [710055031] = {
            ["Content"] = "（声音可以传播很远。再往前看看吧。）",
            ["ContentKR"] = "(소리는 꽤 멀리 퍼지는 법이니까, 좀 더 앞으로 가보자.)",
            ["DialogueId"] = 710055031,
            ["GUID"] = "710055061.0",
            },
        [710055032] = {
            ["Content"] = "（水道旁有什么东西在闪闪发光，先过去看看吧。）",
            ["ContentKR"] = "(수로 옆에 무언가 반짝이고 있다. 가까이 가서 확인해 보자.)",
