            ["Content"] = "听起来有些浪漫。",
            ["ContentKR"] = "꽤 멋진 것 같은데.",
            ["DialogueId"] = 800202161,
            ["GUID"] = "800202161.0",
            ["NextDialogue"] = 80020217,
            },
        [800202162] = {
            ["Content"] = "听起来很辛苦。",
            ["ContentKR"] = "정말 힘들었겠다.",
            ["DialogueId"] = 800202162,
            ["GUID"] = "800202162.0",
            ["NextDialogue"] = 80020218,
            },
        [800203021] = {
            ["Content"] = "我可以一起吗？",
            ["ContentKR"] = "나도 함께 갈 수 있을까?",
            ["DialogueId"] = 800203021,
            ["GUID"] = "800203021.0",
            ["NextDialogue"] = 80020303,
            },
        [800203022] = {
            ["Content"] = "你也会逛街吗？",
            ["ContentKR"] = "너도 쇼핑을 좋아해?",
            ["DialogueId"] = 800203022,
            ["GUID"] = "800203022.0",
            ["NextDialogue"] = 80020304,
            },
        [800203121] = {
            ["Content"] = "真的这么神奇？",
            ["ContentKR"] = "정말 그렇게 보일 거라고?",
            ["DialogueId"] = 800203121,
            ["GUID"] = "800203121.0",
            ["NextDialogue"] = 80020313,
            },
        [800203122] = {
            ["Content"] = "听上去确实会很好看。",
            ["ContentKR"] = "그러게, 괜찮을 것 같네.",
            ["DialogueId"] = 800203122,
            ["GUID"] = "800203122.0",
            ["NextDialogue"] = 80020314,
            },
        [800203161] = {
            ["Content"] = "王子？",
            ["ContentKR"] = "왕자도?",
            ["DialogueId"] = 800203161,
            ["GUID"] = "800203161.0",
            ["NextDialogue"] = 80020317,
            },
        [800204021] = {
            ["Content"] = "听起来心情不错？",
            ["ContentKR"] = "기분이 좋아 보이네?",
            ["DialogueId"] = 800204021,
            ["GUID"] = "800204021.0",
            ["NextDialogue"] = 80020403,
            },
        [800204022] = {
            ["Content"] = "这才更像是女仆的工作啊。",
            ["ContentKR"] = "이제야 정말로 메이드 같아 보이는걸.",
            ["DialogueId"] = 800204022,
            ["GUID"] = "800204022.0",
            ["NextDialogue"] = 80020404,
            },
        [800204091] = {
            ["Content"] = "那么你是遇到了什么烦心事？",
            ["ContentKR"] = "그러면, 무슨 고민이라도 있어?",
            ["DialogueId"] = 800204091,
            ["GUID"] = "800204091.0",
            ["NextDialogue"] = 80020410,
            },
        [800204092] = {
            ["Content"] = "展开讲讲你的前同僚们？",
            ["ContentKR"] = "네 과거 동료들에 대해 듣고 싶어.",
            ["DialogueId"] = 800204092,
            ["GUID"] = "800204092.0",
            ["NextDialogue"] = 80020411,
            },
        [800204171] = {
            ["Content"] = "好奇的话，不如直接去见她？",
            ["ContentKR"] = "궁금하면, 직접 만나러 가면 되지 않아?",
            ["DialogueId"] = 800204171,
            ["GUID"] = "800204171.0",
            ["NextDialogue"] = 80020418,
            },
        [800205011] = {
            ["Content"] = "啊？只是巧合而已。",
            ["ContentKR"] = "응? 우연일 뿐이야.",
            ["DialogueId"] = 800205011,
            ["GUID"] = "800205011.0",
            ["NextDialogue"] = 80020503,
            },
        [800205012] = {
            ["Content"] = "你的头发那么显眼，很难不注意到。",
            ["ContentKR"] = "네 머리 색깔을 봐. 그렇게 눈에 띄는데 못 알아챌 리가 없지.",
            ["DialogueId"] = 800205012,
            ["GUID"] = "800205012.0",
            ["NextDialogue"] = 80020503,
            },
        [800205071] = {
            ["Content"] = "听起来像是解开了心结？",
            ["ContentKR"] = "마음 깊은 곳에 엉켜 있던 매듭이 드디어 풀린 건가?",
            ["DialogueId"] = 800205071,
            ["GUID"] = "800205071.0",
            ["NextDialogue"] = 80020508,
            },
        [800205072] = {
            ["Content"] = "不会觉得可惜吗？",
            ["ContentKR"] = "아쉽지 않아?",
            ["DialogueId"] = 800205072,
            ["GUID"] = "800205072.0",
            ["NextDialogue"] = 80020509,
            },
        [800205121] = {
            ["Content"] = "当我尚在犹豫之时，她毫不迟疑地想要去完成任务——甚至把我也视为必要时可以除去的阻碍。",
            ["ContentKR"] = "제가 잠깐 고민하는 사이, 그녀는 조금의 망설임도 없이 임무를 완수하려 했어요. 심지어 저조차도 임무 완수의 방해물이 될 수 있다고 여겨, 필요하다면 제거하려고 했죠.",
            ["DialogueId"] = 800205121,
            ["GUID"] = "C852AD41",
            ["NextDialogue"] = 80020513,
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/005/C852AD41",
            },
        [800205141] = {
            ["Content"] = "你还恨着她吗？",
            ["ContentKR"] = "아직도 그녀가 미워?",
            ["DialogueId"] = 800205141,
            ["GUID"] = "C852AD6C",
            ["NextDialogue"] = 800205143,
            },
        [800205142] = {
            ["Content"] = "你还爱着她吗？",
            ["ContentKR"] = "아직도 그녀가 생각나?",
            ["DialogueId"] = 800205142,
            ["GUID"] = "C852AD6D",
            ["NextDialogue"] = 800205143,
            },
        [800205143] = {
            ["Content"] = "坦白说，我不知道。我对她只是有些气恼，有些委屈，还有些想念。对于两个密探来说，你提到的爱和恨，都太奢侈了。",
            ["ContentKR"] = "솔직히 말하자면... 모르겠어요. 화가 나거나, 억울하기도 한데, 그립기도 하거든요. 하지만 요원에게 사랑과 미움은 다 너무 사치예요.",
            ["DialogueId"] = 800205143,
            ["FacialId"] = {
                [1] = "93102:Unhappy01",
                },
            ["GUID"] = "C852AD94",
            ["NextDialogue"] = 80020515,
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/005/C852AD94",
            },
        [800205181] = {
            ["Content"] = "嗯？你刚才说了“谢谢”吧？",
            ["ContentKR"] = "응? 방금 '고맙다'고 한 거야?",
            ["DialogueId"] = 800205181,
            ["GUID"] = "800205181.0",
            ["NextDialogue"] = 80020522,
            },
        [800205182] = {
            ["Content"] = "没听清，再说一遍。",
            ["ContentKR"] = "뭐라고? 한 번 더 말해줘.",
            ["DialogueId"] = 800205182,
            ["GUID"] = "800205182.0",
            ["NextDialogue"] = 80020522,
            },
        [800301051] = {
            ["Content"] = "兰迪在这些方面可真有原则啊。",
            ["ContentKR"] = "랜디는 이쪽 방면에서는 정말 철저하네.",
            ["DialogueId"] = 800301051,
            ["GUID"] = "800301051.0",
            ["NextDialogue"] = 80030106,
            },
        [800301052] = {
            ["Content"] = "兰迪总是偷懒呢。",
            ["ContentKR"] = "랜디는 항상 게으르다니까.",
            ["DialogueId"] = 800301052,
            ["GUID"] = "800301052.0",
            ["NextDialogue"] = 80030107,
            },
        [800302051] = {
            ["Content"] = "为了休假编谎，这也能叫绅士？",
            ["ContentKR"] = "휴가를 위해 거짓말하는 게 신사라고?",
            ["DialogueId"] = 800302051,
            ["GUID"] = "800302051.0",
            ["NextDialogue"] = 80030206,
            },
        [800302052] = {
            ["Content"] = "嗯，对对，风度翩翩，绅士极了。",
            ["ContentKR"] = "응, 그래 그래. 품격 있는 신사님.",
            ["DialogueId"] = 800302052,
            ["GUID"] = "800302052.0",
            ["NextDialogue"] = 80030207,
            },
        [800302091] = {
            ["Content"] = "姐姐们？听起来应该也都是淑女。",
            ["ContentKR"] = "누나들? 숙녀분들 같아 보인다.",
            ["DialogueId"] = 800302091,
            ["GUID"] = "800302091.0",
            ["NextDialogue"] = 80030210,
            },
        [800302092] = {
            ["Content"] = "无法想象你还是小男孩的时候。",
            ["ContentKR"] = "어린 시절의 너라니, 상상이 안 되는데?",
            ["DialogueId"] = 800302092,
            ["GUID"] = "800302092.0",
            ["NextDialogue"] = 80030211,
            },
        [800302131] = {
            ["Content"] = "“关爱”？听上去并不坏啊。",
            ["ContentKR"] = "'관심'? 나쁘지 않아 보이는데?",
            ["DialogueId"] = 800302131,
            ["GUID"] = "800302131.0",
            ["NextDialogue"] = 80030214,
            },
        [800302132] = {
            ["Content"] = "“关爱”？听起来和“绅士”是差不多的用法，辛苦你了。",
            ["ContentKR"] = "'관심'? '신사'와 비슷하게 들리는데? 고생이 많았구나.",
            ["DialogueId"] = 800302132,
            ["GUID"] = "800302132.0",
            ["NextDialogue"] = 80030215,
            },
        [800304031] = {
            ["Content"] = "是不是遇到什么烦心事了？你平时不这样。",
            ["ContentKR"] = "무슨 걱정이라도 있어? 평소의 랜디가 아닌데?",
            ["DialogueId"] = 800304031,
            ["GUID"] = "800304031.0",
            ["NextDialogue"] = 80030404,
            },
        [800304032] = {
            ["Content"] = "这么急着走，是被人约了跳舞吗？",
            ["ContentKR"] = "왜 그렇게 급하게 떠나? 춤 약속이라도 있어?",
            ["DialogueId"] = 800304032,
            ["GUID"] = "800304032.0",
            ["NextDialogue"] = 80030406,
            },
        [800304071] = {
            ["Content"] = "噩梦？",
            ["ContentKR"] = "악몽?",
            ["DialogueId"] = 800304071,
            ["GUID"] = "800304071.0",
            ["NextDialogue"] = 80030408,
            },
        [800304081] = {
            ["Content"] = "兰迪的父亲？头一次听你提到他。",
            ["ContentKR"] = "랜디의 아버지? 네가 네 아버지에 관한 이야기를 하는 것은 처음인 것 같아.",
            ["DialogueId"] = 800304081,
            ["GUID"] = "800304081.0",
            ["NextDialogue"] = 80030409,
            },
        [800304321] = {
            ["Content"] = "真的是这样吗？",
            ["ContentKR"] = "정말이야?",
            ["DialogueId"] = 800304321,
            ["GUID"] = "800304321.0",
            ["NextDialogue"] = 80030433,
            },
        [800304351] = {
            ["Content"] = "他要是现在醒来的话，一定会为你骄傲的。",
            ["ContentKR"] = "만약 아버지가 깨어나신다면, 분명 널 자랑스러워하실 거야.",
            ["DialogueId"] = 800304351,
            ["GUID"] = "800304351.0",
            ["NextDialogue"] = 80030436,
            },
        [800304352] = {
            ["Content"] = "我再给你调一杯。",
            ["ContentKR"] = "한잔 더 만들어 줄게.",
            ["DialogueId"] = 800304352,
            ["GUID"] = "800304352.0",
            ["NextDialogue"] = 80030437,
            },
        [800305011] = {
            ["Content"] = "谢谢，看上去心情不错？",
            ["ContentKR"] = "고마워. 오늘은 기분이 좋아 보이네?",
            ["DialogueId"] = 800305011,
            ["GUID"] = "C8790EF4",
            ["NextDialogue"] = 80030502,
            },
        [800305012] = {
            ["Content"] = "你是不是有什么企图？",
            ["ContentKR"] = "뭔가 속셈이 있는 건 아니고?",
            ["DialogueId"] = 800305012,
            ["GUID"] = "C8790F48",
            ["NextDialogue"] = 80030503,
            },
        [800305081] = {
            ["Content"] = "一位女士？那找我干什么？",
            ["ContentKR"] = "여성? 그러면 왜 날 찾는 거야?",
            ["DialogueId"] = 800305081,
            ["GUID"] = "C879106E",
            ["NextDialogue"] = 80030509,
            ["TriggerCondition"] = {
                ["IsBoy"] = {
                    },
                },
            },
        [800305082] = {
            ["Content"] = "所以你是为了这个才邀请我……",
            ["ContentKR"] = "그래서 날 초대하려는 거였구나...",
            ["DialogueId"] = 800305082,
            ["GUID"] = "800305082.0",
            ["NextDialogue"] = 80030526,
            ["TriggerCondition"] = {
                ["IsGirl"] = {
                    },
                },
            },
        [800305091] = {
            ["Content"] = "你自己怎么不扮？",
            ["ContentKR"] = "왜 네가 여장하지 않고?",
            ["DialogueId"] = 800305091,
            ["GUID"] = "800305091.0",
            ["NextDialogue"] = 80030510,
            },
        [800305092] = {
            ["Content"] = "？",
            ["ContentKR"] = "?",
            ["DialogueId"] = 800305092,
            ["GUID"] = "800305092.0",
            ["NextDialogue"] = 80030511,
            },
        [800305141] = {
            ["Content"] = "？？？什么情况，兄弟。",
            ["ContentKR"] = "??? 이걸 어떻게 받아들여야 하는 거지?",
            ["DialogueId"] = 800305141,
            ["GUID"] = "800305141.0",
            ["NextDialogue"] = 80030515,
            },
        [800305142] = {
            ["Content"] = "其实根本就是你想自己穿吧。",
            ["ContentKR"] = "사실 네가 입고 싶어서 그런 거지?",
            ["DialogueId"] = 800305142,
            ["GUID"] = "800305142.0",
            ["NextDialogue"] = 80030515,
            },
        [800305161] = {
            ["Content"] = "后面两个是什么奇怪的东西……",
            ["ContentKR"] = "뒤에 이상한 게 두 개 추가된 것 같은데...",
            ["DialogueId"] = 800305161,
            ["GUID"] = "800305161.0",
            ["NextDialogue"] = 80030517,
            },
        [800305171] = {
            ["Content"] = "那我就勉为其难地答应了。",
            ["ContentKR"] = "그러면 조금 생각해 볼까.",
            ["DialogueId"] = 800305171,
            ["GUID"] = "80030571",
            ["NextDialogue"] = 80030518,
            },
        [800305172] = {
            ["Content"] = "让我再想想。",
            ["ContentKR"] = "생각 좀 해보고.",
            ["DialogueId"] = 800305172,
            ["GUID"] = "800305172",
            ["NextDialogue"] = 80030523,
            },
        [800305261] = {
            ["Content"] = "你是不是想要在舞会上活捉我？",
            ["ContentKR"] = "무도회에서 날 잡아가려고?",
            ["DialogueId"] = 800305261,
            ["GUID"] = "C87910C2",
            ["NextDialogue"] = 80030527,
            },
        [800305311] = {
            ["Content"] = "当然是开玩笑。",
            ["ContentKR"] = "당연히 장난이지.",
            ["DialogueId"] = 800305311,
            ["GUID"] = "C87911BE",
            ["NextDialogue"] = 80030532,
            },
        [800305312] = {
            ["Content"] = "这两者并不矛盾啊！",
            ["ContentKR"] = "둘 다 틀린 말은 아닌데?",
            ["DialogueId"] = 800305312,
            ["GUID"] = "C8791212",
            ["NextDialogue"] = 80030533,
            },
        [800305351] = {
            ["Content"] = "抱歉，因为觉得你惊慌的样子一定会很有趣，没忍住……",
            ["ContentKR"] = "미안, 네가 당황하는 모습이 재밌을 것 같아서...",
            ["DialogueId"] = 800305351,
            ["GUID"] = "C87912BA",
            ["NextDialogue"] = 80030536,
            },
        [800305352] = {
            ["Content"] = "不，我是真的很担心会被你抓走！",
            ["ContentKR"] = "아니, 난 정말 네가 날 잡아갈까 봐 무섭다고!",
            ["DialogueId"] = 800305352,
            ["GUID"] = "C8791362",
            ["NextDialogue"] = 80030539,
            },
        [800305431] = {
            ["Content"] = "那，好吧，我答应你。",
            ["ContentKR"] = "알겠어, 그럼 갈게.",
            ["DialogueId"] = 800305431,
            ["GUID"] = "C879145E",
            ["NextDialogue"] = 80030544,
            },
        [800701271] = {
            ["DialogueId"] = 800701271,
            ["GUID"] = "800701271.0",
            ["IsBlack"] = 1,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/invite/gun_kill\"},PlayAs2D{true}}",
            },
        [801001021] = {
            ["Content"] = "薄情？我做了什么了？",
            ["ContentKR"] = "차갑다고? 내가 뭘 어쨌는데?",
            ["DialogueId"] = 801001021,
            ["GUID"] = "801001021.0",
            ["NextDialogue"] = 80100103,
            },
        [801001022] = {
            ["Content"] = "没错，我就是无情的人，你要干什么？",
            ["ContentKR"] = "맞아, 난 차가운 사람이야. 그런데 뭘 어쩌자고?",
            ["DialogueId"] = 801001022,
            ["GUID"] = "801001022.0",
            ["NextDialogue"] = 80100104,
            },
        [801001041] = {
            ["Content"] = "恋情？谁和谁的？",
            ["ContentKR"] = "사랑? 누구와 누구의 사랑?",
            ["DialogueId"] = 801001041,
            ["GUID"] = "801001041.0",
            ["NextDialogue"] = 80100105,
            },
        [801001091] = {
            ["Content"] = "你冷静一点，我们才认识没多久。",
            ["ContentKR"] = "좀 진정해. 우린 처음 본 지도 얼마 안 됐잖아.",
            ["DialogueId"] = 801001091,
            ["GUID"] = "801001091.0",
            ["NextDialogue"] = 80100110,
            },
        [801001092] = {
            ["Content"] = "我知道了，你在练习舞台剧，所以才会一直念诗。",
            ["ContentKR"] = "이제 알겠다. 연극 연습 중이구나? 시를 외우거나, 그런 거지?",
            ["DialogueId"] = 801001092,
            ["GUID"] = "801001092.0",
            ["NextDialogue"] = 80100111,
            },
        [801002011] = {
            ["Content"] = "“那一面”？",
            ["ContentKR"] = "'그런 면'?",
            ["DialogueId"] = 801002011,
            ["GUID"] = "801002011.0",
            ["NextDialogue"] = 80100202,
            },
        [801002071] = {
            ["Content"] = "原来你也有过这样的梦想啊。",
            ["ContentKR"] = "너한테 그런 꿈도 있었구나.",
            ["DialogueId"] = 801002071,
            ["GUID"] = "801002071.0",
            ["NextDialogue"] = 80100208,
            },
        [801002072] = {
            ["Content"] = "曾经……也就是说现在已经习惯了？",
            ["ContentKR"] = "한때라는 건... 지금은 익숙해졌다는 뜻인가?",
            ["DialogueId"] = 801002072,
            ["GUID"] = "801002072.0",
            ["NextDialogue"] = 80100209,
            },
        [801002151] = {
            ["Content"] = "太危险了，我拒绝。",
            ["ContentKR"] = "너무 위험해. 거절할게.",
            ["DialogueId"] = 801002151,
            ["GUID"] = "801002151.0",
            ["NextDialogue"] = 80100216,
            },
        [801002152] = {
            ["Content"] = "你可以试一试。",
            ["ContentKR"] = "한번 해봐도 좋고.",
            ["DialogueId"] = 801002152,
            ["GUID"] = "801002152.0",
            ["NextDialogue"] = 80100217,
            },
        [801002191] = {
            ["Content"] = "我不会给你这样的机会。",
            ["ContentKR"] = "그런 기대는 하지 않는 게 좋을 거야.",
            ["DialogueId"] = 801002191,
            ["GUID"] = "801002191.0",
            ["NextDialogue"] = 80100220,
            },
