            ["DialogueId"] = 801601021,
            ["GUID"] = "801601021.0",
            ["NextDialogue"] = 80160103,
            },
        [801601022] = {
            ["Content"] = "不好意思，这里不是酒馆。想来一杯的话，我知道城里有那么一家。",
            ["ContentKR"] = "죄송하지만 여긴 술집이 아닙니다. 한잔하고 싶으시다면 성안에 추천해 드릴만한 술집이 있습니다.",
            ["DialogueId"] = 801601022,
            ["GUID"] = "801601022.0",
            ["NextDialogue"] = 80160106,
            },
        [801601071] = {
            ["Content"] = "……怎么证明是卡米拉女士让你来的？",
            ["ContentKR"] = "카밀라 씨가 보냈다는 걸 어떻게 증명하죠...?",
            ["DialogueId"] = 801601071,
            ["GUID"] = "801601071.0",
            ["NextDialogue"] = 80160108,
            },
        [801602011] = {
