            ["NextDialogue"] = 80160404,
            },
        [801604051] = {
            ["Content"] = "想来点什么？卡米拉女士告诉过我，皇都最近流行的是这种——",
            ["ContentKR"] = "어떤 걸로 드릴까요? 카밀라 씨가 황성에선 요즘 이게 유행이라고...",
            ["DialogueId"] = 801604051,
            ["GUID"] = "801604051",
